INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(0, '360-degree feedback', '/θriː hʌndrəd ˈsɪksti dɪˈɡriː ˈfiːdbæk/', 'noun', '{"zh-TW":["360度反饋"],"en":["performance feedback gathered from multiple sources including peers and subordinates"]}', NULL, 'implement 360-degree feedback / 360-degree feedback process', '[{"en":"The 360-degree feedback revealed blind spots in leadership style.","zh-TW":"360度反饋揭示了領導風格中的盲點。"},{"en":"Employees appreciate 360-degree feedback for its balanced perspective.","zh-TW":"員工欣賞360度反饋的平衡視角。"}]', NULL, NULL, 5, 0, NULL),
(1, 'a la carte', '/ɑː lɑː kɑːrt/', 'phrase', '{"zh-TW":["單點；照菜單點菜"],"en":["ordering individual dishes rather than a set menu"]}', NULL, 'a la carte menu / order a la carte', '[{"en":"We ordered a la carte rather than the set menu.","zh-TW":"我們選擇單點而非套餐。"},{"en":"The a la carte menu offers more variety.","zh-TW":"單點菜單提供更多選擇。"}]', NULL, NULL, 4, 1, NULL),
(2, 'A/B testing', '/ˌeɪ biː ˈtestɪŋ/', 'noun', '{"zh-TW":["A/B測試；對照測試"],"en":["comparing two versions of content to see which performs better"]}', NULL, 'run an A/B test / A/B testing results / implement A/B testing', '[{"en":"A/B testing showed that the red button outperformed the green one.","zh-TW":"A/B測試顯示紅色按鈕的表現優於綠色按鈕。"},{"en":"We use A/B testing to optimize our landing pages.","zh-TW":"我們使用A/B測試優化登陸頁面。"}]', '{"verb":"A/B test"}', NULL, 4, 2, NULL),
(3, 'abandon', '/əˈbændən/', 'verb', '{"zh-TW":["放棄；拋棄","遺棄"],"en":["to give up completely","to leave someone permanently"]}', '{"prefix":{"text":"a-","meaning":"away (離開)"},"root":{"text":"bandon","meaning":"control (控制)"},"logic":"離開控制，意即「放棄」。"}', 'abandon a plan/project/ship', '[{"en":"They had to abandon the project due to lack of funding.","zh-TW":"因資金不足，他們不得不放棄該計畫。"},{"en":"The crew abandoned the sinking ship.","zh-TW":"船員們棄船逃生。"}]', '{"noun":"abandonment","adjective":"abandoned"}', NULL, 3, 3, NULL),
(4, 'abandonment', '/əˈbændənmənt/', 'noun', '{"zh-TW":["放棄；廢棄"],"en":["the act of giving up ownership, a claim, or a contract"]}', NULL, 'project abandonment / abandonment of claim', '[{"en":"The insurance policy covered costs from project abandonment.","zh-TW":"保險單涵蓋了項目放棄的成本。"},{"en":"The lease provided for early abandonment without penalty after five years.","zh-TW":"租約規定五年後可以無罰款提前放棄。"}]', '{"verb":"abandon"}', NULL, 4, 4, NULL),
(5, 'abatement', '/əˈbeɪtmənt/', 'noun', '{"zh-TW":["減少；削減；緩和"],"en":["the action of lessening or removing something, typically pollution or costs"]}', NULL, 'noise abatement / pollution abatement / cost abatement', '[{"en":"The factory installed filters as part of its pollution abatement program.","zh-TW":"工廠安裝了過濾器作為其污染削減計畫的一部分。"},{"en":"Tax abatement can be used to attract businesses to underdeveloped areas.","zh-TW":"稅收減免可用於吸引企業進入欠發達地區。"}]', '{"verb":"abate"}', NULL, 3, 5, NULL),
(6, 'abide', '/əˈbaɪd/', 'verb', '{"zh-TW":["遵守；忍受"],"en":["to accept or obey a rule or decision"]}', '{"prefix":{"text":"a-","meaning":"on (在…上)"},"root":{"text":"bide","meaning":"wait/stay (等待/停留)"},"logic":"停留在規則上，即「遵守」。"}', 'abide by rules/laws/decisions', '[{"en":"All members must abide by the association''s rules.","zh-TW":"所有會員必須遵守協會規則。"},{"en":"We expect partners to abide by the agreement.","zh-TW":"我們期望合作夥伴遵守協議。"}]', NULL, NULL, 2, 6, 628),
(7, 'abide by', '/əˈbaɪd baɪ/', 'verb', '{"zh-TW":["遵守；遵從"],"en":["to accept and act in accordance with a decision or rule"]}', NULL, 'abide by the rules / abide by the contract / abide by the decision', '[{"en":"All parties must abide by the terms of the agreement.","zh-TW":"所有各方必須遵守協議條款。"},{"en":"The company agreed to abide by the regulator''s decision.","zh-TW":"公司同意遵守監管機構的裁決。"}]', NULL, NULL, 3, 7, NULL),
(8, 'ability', '/əˈbɪləti/', 'noun', '{"zh-TW":["能力；才能"],"en":["the power or skill to do something"]}', '{"root":{"text":"abil","meaning":"able (能夠)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"能夠的狀態，即「能力」。"}', 'ability to do sth', '[{"en":"She has the ability to solve complex problems.","zh-TW":"她有解決複雜問題的能力。"},{"en":"Leadership ability is essential for managers.","zh-TW":"領導能力對管理者至關重要。"}]', '{"adjective":"able","adverb":"ably"}', NULL, 3, 8, NULL),
(9, 'able', 'ˈeɪbəl', 'adjective', '{"zh-TW":["能夠；有能力","有才能的"],"en":["having the power to do something","having the skill"]}', NULL, 'able to/be able to', '[{"en":"She is able to handle multiple projects.","zh-TW":"她能夠處理多個專案。"}]', '{"noun":"ability","adverb":"ably"}', NULL, 1, 9, NULL),
(10, 'abolish', '/əˈbɒlɪʃ/', 'verb', '{"zh-TW":["廢除；廢止"],"en":["to officially end a law or system"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"ol","meaning":"grow (成長)"},"suffix":{"text":"-ish","meaning":"to make (使)"},"logic":"使離開成長，即「廢除」。"}', 'abolish a law/system/practice', '[{"en":"The government voted to abolish the outdated regulation.","zh-TW":"政府投票廢除了過時的法規。"},{"en":"Many countries have abolished the death penalty.","zh-TW":"許多國家已廢除死刑。"}]', '{"noun":"abolition"}', NULL, 3, 10, 629),
(11, 'abolition', '/ˌæbəˈlɪʃn/', 'noun', '{"zh-TW":["廢除；廢止"],"en":["the act of officially ending something"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"ol","meaning":"grow (成長)"},"suffix":{"text":"-ition","meaning":"action (動作)"},"logic":"離開成長的動作，即「廢除」。"}', 'abolition of / call for abolition', '[{"en":"The abolition of trade barriers boosted exports.","zh-TW":"廢除貿易壁壘促進了出口。"},{"en":"Some advocate for the abolition of overtime caps.","zh-TW":"有些人提倡廢除加班上限。"}]', '{"verb":"abolish"}', NULL, 3, 11, NULL),
(12, 'about', '/əˈbaʊt/', 'preposition', '{"zh-TW":["關於；大約"],"en":["concerning","approximately","concerning; approximately"]}', NULL, 'think about / about to; about + 名詞/V-ing', '[{"en":"What is this meeting about?","zh-TW":"這個會議是關於什麼的？"},{"en":"There are about 200 employees.","zh-TW":"大約有200名員工。"},{"en":"The book is about history.","zh-TW":"這本書是關於歷史的。"},{"en":"There are about 50 people here.","zh-TW":"這裡大約有50個人。"}]', '{"preposition":"about","adverb":"about"}', NULL, 2, 12, NULL),
(13, 'above', '/əˈbʌv/', 'preposition', '{"zh-TW":["在…上方；超過","在…上面；超過","在...上方；超過"],"en":["higher than","more than","in or to a higher position","at a higher level than; more than"]}', NULL, 'above all / above average; above all (最重要的是)', '[{"en":"Sales rose above expectations.","zh-TW":"銷售額超出了預期。"},{"en":"Above all, safety comes first.","zh-TW":"最重要的是，安全第一。"},{"en":"The temperature rose above 30 degrees.","zh-TW":"溫度升到了30度以上。"},{"en":"Above all, be honest.","zh-TW":"最重要的是，要誠實。"},{"en":"The plane flew above the clouds.","zh-TW":"飛機在雲層上方飛行。"},{"en":"Temperatures rose above 30 degrees.","zh-TW":"氣溫升超過30度。"}]', '{"preposition":"above","adjective":"above-mentioned"}', NULL, 2, 13, NULL),
(14, 'above the line', '/əˈbʌv ðə laɪn/', 'phrase', '{"zh-TW":["線上項目；主要項目"],"en":["relating to revenue or costs directly involved in a company''s core operations"]}', NULL, 'above-the-line costs / above-the-line promotions', '[{"en":"Above-the-line advertising includes TV, radio, and national press campaigns.","zh-TW":"線上廣告包括電視、廣播和全國性報紙活動。"},{"en":"Above-the-line items in the income statement reflect core operational performance.","zh-TW":"損益表中的線上項目反映了核心運營績效。"}]', '{"opposite":"below the line"}', NULL, 5, 14, NULL),
(15, 'above-mentioned', '/əˌbʌv ˈmenʃənd/', 'adjective', '{"zh-TW":["上述的；上文所提到的"],"en":["previously mentioned in the same document"]}', NULL, 'the above-mentioned conditions / above-mentioned parties', '[{"en":"The above-mentioned requirements apply to all applicants.","zh-TW":"上述要求適用於所有申請者。"},{"en":"The above-mentioned vendors have been approved.","zh-TW":"上述供應商已獲批准。"}]', NULL, NULL, 5, 15, NULL),
(16, 'above-the-line', '/əˌbʌv ðə laɪn/', 'adjective', '{"zh-TW":["線上的；媒體廣告的"],"en":["relating to advertising that uses mass media channels to reach a wide audience"]}', NULL, 'above-the-line advertising / above-the-line promotion', '[{"en":"TV and radio are classic above-the-line advertising channels.","zh-TW":"電視和廣播是傳統的線上廣告渠道。"},{"en":"The campaign combined above-the-line and digital media.","zh-TW":"該活動結合了線上廣告和數位媒體。"}]', '{"opposite":"below-the-line"}', NULL, 5, 16, NULL),
(17, 'abrupt', '/əˈbrʌpt/', 'adjective', '{"zh-TW":["突然的；意外的"],"en":["happening suddenly or without warning"]}', NULL, 'abrupt change / abrupt departure / abrupt decision', '[{"en":"The abrupt resignation of the CEO shocked investors.","zh-TW":"執行長的突然辭職震驚了投資者。"},{"en":"An abrupt halt in production disrupted the supply chain.","zh-TW":"生產的突然停止打亂了供應鏈。"}]', '{"adverb":"abruptly","noun":"abruptness"}', NULL, 2, 17, 967),
(18, 'abscond', '/əbˈskɒnd/', 'verb', '{"zh-TW":["潛逃；逃匿"],"en":["to leave hurriedly and secretly, typically to escape from custody"]}', NULL, 'abscond with funds / abscond from justice / abscond overseas', '[{"en":"The suspect absconded before the arrest warrant could be served.","zh-TW":"嫌疑人在逮捕令送達前潛逃了。"},{"en":"The accountant absconded with client funds and fled to another country.","zh-TW":"這位會計師攜客戶資金潛逃至另一個國家。"}]', '{"noun":"absconsion"}', NULL, 3, 18, NULL),
(19, 'absence', '/ˈæbsəns/', 'noun', '{"zh-TW":["缺席；不在","缺乏"],"en":["the state of being away","the lack of something"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"sens","meaning":"be (存在)"},"logic":"離開存在的狀態，即「缺席」。"}', 'in the absence of / leave of absence', '[{"en":"In the absence of the manager, the assistant took charge.","zh-TW":"經理不在時，助理負責管理。"},{"en":"She took a leave of absence for personal reasons.","zh-TW":"她因私人原因請假。"}]', '{"adjective":"absent"}', NULL, 3, 19, 968),
(20, 'absenteeism', 'ˌæbsənˈtiːɪzəm', 'noun', '{"zh-TW":["缺勤；曠職","曠工"],"en":["frequent absence from work","being away without permission"]}', NULL, 'reduce absenteeism/absenteeism rate', '[{"en":"We aim to reduce absenteeism.","zh-TW":"我們致力於減少缺勤。"}]', '{"adjective":"absent"}', NULL, 4, 20, 738),
(21, 'absorb', '/əbˈzɔːrb/', 'verb', '{"zh-TW":["吸收","全神貫注"],"en":["to take in or soak up","to occupy attention fully"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"sorb","meaning":"suck (吸)"},"logic":"把東西吸走，即「吸收」。"}', 'absorb information/costs; absorb information / absorb moisture', '[{"en":"The company will absorb the extra shipping costs.","zh-TW":"公司將承擔額外的運費。"},{"en":"She was completely absorbed in her research.","zh-TW":"她完全沉浸在研究中。"},{"en":"Plants absorb carbon dioxide from the air.","zh-TW":"植物從空氣中吸收二氧化碳。"},{"en":"She quickly absorbed all the new information.","zh-TW":"她很快吸收了所有新資訊。"}]', '{"noun":"absorption","adjective":"absorbing"}', NULL, 2, 21, NULL),
(22, 'absorption', '/əbˈzɔːrpʃən/', 'noun', '{"zh-TW":["吸收；融合"],"en":["the process of absorbing or being absorbed"]}', NULL, 'economic absorption / absorption of migrants / sound absorption', '[{"en":"The absorption of new technology often transforms entire industries.","zh-TW":"新技術的吸收往往改變整個行業。"},{"en":"The economy showed strong absorption of new workers after the recession.","zh-TW":"衰退後，經濟顯示出對新工人的強大吸收能力。"}]', '{"verb":"absorb","adjective":"absorbed"}', NULL, 4, 22, NULL),
(23, 'absorption costing', '/əbˈzɔːrpʃən ˈkɒstɪŋ/', 'noun', '{"zh-TW":["完全成本法；吸收成本法"],"en":["a method of costing that includes all manufacturing costs in product cost"]}', NULL, 'apply absorption costing / absorption costing method', '[{"en":"Under absorption costing, fixed overhead is included in product cost.","zh-TW":"在完全成本法下，固定費用計入產品成本。"},{"en":"Absorption costing can distort profit when inventory levels change.","zh-TW":"當庫存水準變化時，完全成本法可能扭曲利潤。"}]', NULL, NULL, 5, 23, NULL),
(24, 'abstract', '/ˈæbstrækt/', 'adjective', '{"zh-TW":["抽象的","摘要"],"en":["existing in thought but not physical","a summary of a document","existing in thought rather than having a physical existence"]}', '{"prefix":{"text":"abs-","meaning":"away (離開)"},"root":{"text":"tract","meaning":"draw (拉)"},"logic":"從具體中拉出來，即「抽象的」。"}', 'abstract concept/idea/art; abstract art / abstract concept', '[{"en":"The report includes an abstract summarizing key findings.","zh-TW":"報告包含一份摘要，概述了主要發現。"},{"en":"Abstract thinking is required for strategic planning.","zh-TW":"策略規劃需要抽象思維。"},{"en":"The painting is very abstract.","zh-TW":"這幅畫非常抽象。"},{"en":"Justice is an abstract concept.","zh-TW":"正義是一個抽象概念。"}]', '{"noun":"abstraction","adverb":"abstractly","verb":"abstract"}', NULL, 3, 24, 969),
(25, 'abstract reasoning', '/''æbstrækt ˌriːzənɪŋ/', 'noun', '{"zh-TW":["抽象推理"],"en":["the ability to understand and think about concepts and ideas that are not concrete or tangible"]}', NULL, 'develop abstract reasoning / strong abstract reasoning / test abstract reasoning', '[{"en":"Abstract reasoning is tested in many aptitude exams used in hiring processes.","zh-TW":"抽象推理在許多用於招聘流程的資質考試中被測試。"},{"en":"Solving mathematical puzzles can help develop abstract reasoning skills.","zh-TW":"解決數學謎題有助於培養抽象推理能力。"}]', '{"adjective":"abstract"}', NULL, 5, 25, NULL),
(26, 'abstraction', '/æbˈstrækʃən/', 'noun', '{"zh-TW":["抽象；抽象概念"],"en":["the quality of dealing with ideas rather than events"]}', NULL, 'high level of abstraction / conceptual abstraction / layer of abstraction', '[{"en":"The model works at a high level of abstraction.","zh-TW":"該模型在高度抽象的層次上運作。"},{"en":"Mathematics involves reasoning through abstraction.","zh-TW":"數學涉及通過抽象進行推理。"}]', '{"adjective":"abstract","verb":"abstract"}', NULL, 4, 26, NULL),
(27, 'abstraction layer', '/æbˈstrækʃən ˈleɪər/', 'noun', '{"zh-TW":["抽象層"],"en":["a level of programming that hides implementation details from the user"]}', NULL, 'add abstraction layer / software abstraction layer / network abstraction layer', '[{"en":"An abstraction layer allows developers to work without knowing underlying details.","zh-TW":"抽象層允許開發者在不了解底層細節的情況下工作。"},{"en":"Operating systems provide an abstraction layer between hardware and software.","zh-TW":"作業系統在硬體和軟體之間提供抽象層。"}]', NULL, NULL, 5, 27, NULL),
(28, 'abstraction level', '/æbˈstrækʃən ˈlevəl/', 'noun', '{"zh-TW":["抽象層級"],"en":["a degree of complexity at which a system is described or modeled"]}', NULL, 'higher abstraction level / lower abstraction level / appropriate abstraction level', '[{"en":"Working at the right abstraction level improves code readability.","zh-TW":"在正確的抽象層級工作提高了代碼可讀性。"},{"en":"The system architecture defines multiple abstraction levels for different concerns.","zh-TW":"系統架構為不同的關注點定義了多個抽象層級。"}]', NULL, NULL, 5, 28, NULL),
(29, 'abstruse', '/æbˈstruːs/', 'adjective', '{"zh-TW":["深奧的；難以理解的"],"en":["difficult to understand; obscure"]}', NULL, 'abstruse theory / abstruse concept / abstruse language', '[{"en":"The professor''s abstruse lecture confused most students.","zh-TW":"教授深奧的講課讓大多數學生感到困惑。"},{"en":"The legal text was written in abstruse terminology.","zh-TW":"該法律文本以晦澀的術語撰寫。"}]', '{"adverb":"abstrusely"}', NULL, 3, 29, NULL),
(30, 'abundant', '/əˈbʌndənt/', 'adjective', '{"zh-TW":["豐富的；大量的"],"en":["existing in large quantities; more than enough"]}', '{"prefix":{"text":"ab-","meaning":"over (超出)"},"root":{"text":"und","meaning":"wave (波浪)"},"suffix":{"text":"-ant","meaning":"having quality (具有特質)"},"logic":"如波浪般溢出，即「豐富的」。"}', 'abundant resources/supply/evidence', '[{"en":"The region has abundant natural resources.","zh-TW":"該地區擁有豐富的自然資源。"},{"en":"There is abundant evidence to support the claim.","zh-TW":"有大量證據支持這個說法。"}]', '{"noun":"abundance","adverb":"abundantly"}', NULL, 3, 30, NULL),
(31, 'academia', '/ˌækəˈdiːmiə/', 'noun', '{"zh-TW":["學術界"],"en":["the world of universities and scholarly research"]}', NULL, 'in academia / bridge between academia and industry', '[{"en":"She spent 10 years in academia before joining the firm.","zh-TW":"她在加入公司前在學術界待了10年。"},{"en":"We bridge the gap between academia and industry.","zh-TW":"我們搭建學術界與產業界之間的橋樑。"}]', '{"noun":"academia","adjective":"academic","adverb":"academically"}', NULL, 3, 31, NULL),
(32, 'academic', '/ˌækəˈdɛmɪk/', 'adjective', '{"zh-TW":["學術的"],"en":["relating to education and studying"]}', NULL, 'academic year / academic achievement', '[{"en":"Her academic performance is excellent.","zh-TW":"她的學業成績很優秀。"},{"en":"The academic year starts in September.","zh-TW":"學年從九月開始。"}]', '{"noun":"academia","noun2":"academy"}', NULL, 3, 32, NULL),
(33, 'academic advisor', '/''ækəˌdemɪk ədˌvaɪzər/', 'noun', '{"zh-TW":["學業輔導員；課業顧問"],"en":["a faculty member or staff who guides students in planning their academic program"]}', NULL, 'meet with an academic advisor / consult an academic advisor / academic advisor recommendation', '[{"en":"She met with her academic advisor to plan her course schedule for the semester.","zh-TW":"她與學業輔導員會面，規劃學期的課程安排。"},{"en":"Academic advisors help students navigate degree requirements and career planning.","zh-TW":"學業輔導員幫助學生了解學位要求和職業規劃。"}]', NULL, NULL, 5, 33, NULL),
(34, 'academic calendar', '/''ækəˌdemɪk ˌkæləndər/', 'noun', '{"zh-TW":["學年曆；學術日曆"],"en":["a schedule of the academic year including key dates for terms, exams, and vacations"]}', NULL, 'consult the academic calendar / academic calendar dates / follow the academic calendar', '[{"en":"Students should consult the academic calendar to plan their study schedules.","zh-TW":"學生應查閱學年曆，制定學習計劃。"},{"en":"The academic calendar shows that the final exams begin on December eighteenth.","zh-TW":"學年曆顯示期末考試從十二月十八日開始。"}]', NULL, NULL, 5, 34, NULL),
(35, 'academic excellence', '/''ækəˌdemɪk ˌeksələns/', 'noun', '{"zh-TW":["學術卓越；學業優秀"],"en":["consistently high standards of achievement in academic work"]}', NULL, 'pursue academic excellence / reward academic excellence / achieve academic excellence', '[{"en":"The award recognizes students who have demonstrated academic excellence throughout the year.","zh-TW":"該獎項表彰在整個學年中展示出學術卓越的學生。"},{"en":"Achieving academic excellence requires both discipline and a genuine love of learning.","zh-TW":"實現學術卓越需要紀律和對學習的真誠熱愛。"}]', NULL, NULL, 5, 35, NULL),
(36, 'academic integrity', '/''ækəˌdemɪk ɪnˈteɡrɪti/', 'noun', '{"zh-TW":["學術誠信"],"en":["the commitment to honesty, fairness, and ethical behavior in academic work"]}', NULL, 'uphold academic integrity / academic integrity policy / violate academic integrity', '[{"en":"All students must sign an academic integrity pledge at the start of each semester.","zh-TW":"所有學生必須在每學期開始時簽署學術誠信承諾書。"},{"en":"The university takes academic integrity violations very seriously.","zh-TW":"大學非常重視學術誠信違規行為。"}]', NULL, NULL, 5, 36, NULL),
(37, 'academic journal', '/''ækəˌdemɪk ˌdʒɜːrnəl/', 'noun', '{"zh-TW":["學術期刊"],"en":["a peer-reviewed periodical in which scholarship relating to a particular academic discipline is published"]}', NULL, 'publish in an academic journal / subscribe to an academic journal / academic journal article', '[{"en":"Her research was published in a leading academic journal in her field.","zh-TW":"她的研究發表在她領域的頂尖學術期刊上。"},{"en":"Students are encouraged to read academic journals to stay current with research.","zh-TW":"鼓勵學生閱讀學術期刊，以了解最新研究。"}]', NULL, NULL, 5, 37, NULL),
(38, 'academic misconduct', '/''ækəˌdemɪk ˌmɪsˈkɒndʌkt/', 'noun', '{"zh-TW":["學術不端行為；學術違規"],"en":["any action that violates the established academic standards of integrity and fairness"]}', NULL, 'commit academic misconduct / penalize academic misconduct / report academic misconduct', '[{"en":"Cheating on an exam is a serious form of academic misconduct.","zh-TW":"在考試中作弊是一種嚴重的學術不端行為。"},{"en":"The university committee reviewed the case of academic misconduct and issued a warning.","zh-TW":"大學委員會審查了學術不端行為案例並發出了警告。"}]', NULL, NULL, 5, 38, NULL),
(39, 'academic performance', '/''ækəˌdemɪk pəˈfɔːrməns/', 'noun', '{"zh-TW":["學業成績；學術表現"],"en":["the extent to which a student has achieved their educational goals"]}', NULL, 'improve academic performance / measure academic performance / decline in academic performance', '[{"en":"Her academic performance improved significantly after she joined a study group.","zh-TW":"她加入學習小組後，學業成績顯著提高。"},{"en":"Schools monitor academic performance to identify students who need additional support.","zh-TW":"學校監測學業成績，以識別需要額外支持的學生。"}]', NULL, NULL, 5, 39, NULL),
(40, 'academic writing', '/''ækəˌdemɪk ˌraɪtɪŋ/', 'noun', '{"zh-TW":["學術寫作"],"en":["a formal style of writing used in universities and scholarly publications"]}', NULL, 'improve academic writing / academic writing style / academic writing course', '[{"en":"She took a course in academic writing to improve her essay technique.","zh-TW":"她選修了一門學術寫作課程，以提高她的論文寫作技巧。"},{"en":"Academic writing requires a formal tone, precise language, and proper citations.","zh-TW":"學術寫作需要正式的語氣、精確的語言和適當的引用。"}]', NULL, NULL, 5, 40, NULL),
(41, 'academic year', '/ˌækəˈdɛmɪk jɪər/', 'noun', '{"zh-TW":["學年"],"en":["the annual period during which students attend school or college"]}', NULL, 'start of the academic year / academic year calendar', '[{"en":"The academic year begins in September and ends in June.","zh-TW":"學年從9月開始，6月結束。"},{"en":"Registration opens two months before the academic year begins.","zh-TW":"入學申請在學年開始前兩個月開放。"}]', NULL, NULL, 5, 41, NULL),
(42, 'accelerate', '/əkˈseləreɪt/', 'verb', '{"zh-TW":["加速；促進"],"en":["to increase in speed","to cause to happen sooner"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"celer","meaning":"speed (速度)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使朝向速度，即「加速」。"}', 'accelerate growth/development', '[{"en":"The company aims to accelerate its expansion into Asian markets.","zh-TW":"公司旨在加速擴展亞洲市場。"},{"en":"Technology has accelerated the pace of change.","zh-TW":"科技加速了變革的步伐。"}]', '{"noun":"acceleration"}', NULL, 4, 42, 632),
(43, 'accelerated depreciation', '/əkˌseləreɪtɪd dɪˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["加速折舊"],"en":["a depreciation method that records higher expenses in early years of an asset''s life"]}', NULL, 'apply accelerated depreciation / accelerated depreciation schedule', '[{"en":"Accelerated depreciation reduces taxable income in the early years of an asset.","zh-TW":"加速折舊在資產的前幾年降低了應稅收入。"},{"en":"The tax authorities allow accelerated depreciation for certain qualifying assets.","zh-TW":"稅務機關允許對某些符合條件的資產使用加速折舊。"}]', NULL, NULL, 5, 43, NULL),
(44, 'accept', '/əkˈsept/', 'verb', '{"zh-TW":["接受；認可"],"en":["to agree to receive something","to believe something to be true","to agree to receive; to believe something is true"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cept","meaning":"take (拿取)"},"logic":"朝向自己拿取，即「接受」。"}', 'accept an offer/invitation; accept an offer/invitation/responsibility', '[{"en":"She accepted the job offer without hesitation.","zh-TW":"她毫不猶豫地接受了工作邀約。"},{"en":"The board accepted the proposal unanimously.","zh-TW":"董事會一致通過了該提案。"},{"en":"She accepted the job offer.","zh-TW":"她接受了這份工作。"},{"en":"He refused to accept the blame.","zh-TW":"他拒絕接受指責。"}]', '{"noun":"acceptance","adjective":"acceptable"}', NULL, 2, 44, NULL),
(45, 'acceptable', 'əkˈsɛptəbəl', 'adjective', '{"zh-TW":["可接受的；滿意的","還不錯的"],"en":["satisfactory","good enough"]}', NULL, 'acceptable quality/acceptable behavior', '[{"en":"This is an acceptable solution.","zh-TW":"這是一個可接受的解決方案。"}]', '{"noun":"acceptability","adverb":"acceptably"}', NULL, 4, 45, NULL),
(46, 'acceptance', '/ækˈsɛptəns/', 'noun', '{"zh-TW":["接受；承諾"],"en":["agreement to receive or undertake something offered"]}', NULL, 'acceptance of terms / written acceptance', '[{"en":"Please confirm your acceptance of the offer in writing.","zh-TW":"請以書面形式確認您接受此報價。"},{"en":"Acceptance of the contract terms is required before work begins.","zh-TW":"在工作開始之前需要接受合約條款。"}]', '{"verb":"accept","adjective":"accepted"}', NULL, 4, 46, NULL),
(47, 'acceptance testing', '/əkˈseptəns ˈtestɪŋ/', 'noun', '{"zh-TW":["驗收測試"],"en":["testing conducted to verify that a system meets specified requirements before final acceptance"]}', NULL, 'conduct acceptance testing / acceptance testing criteria', '[{"en":"The client conducted acceptance testing before signing off on the software.","zh-TW":"客戶在驗收軟件之前進行了驗收測試。"},{"en":"Acceptance testing ensures the delivered system matches agreed specifications.","zh-TW":"驗收測試確保交付的系統符合商定規格。"}]', NULL, NULL, 5, 47, NULL),
(48, 'access', '/ˈækses/', 'noun', '{"zh-TW":["進入；使用權","存取"],"en":["the opportunity to approach or enter","the right to use something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cess","meaning":"go (走)"},"logic":"走向某處，即「進入、存取」。"}', 'access to information/system', '[{"en":"Employees have access to the company database.","zh-TW":"員工可以存取公司資料庫。"},{"en":"The building provides wheelchair access.","zh-TW":"該建築提供輪椅通道。"}]', '{"adjective":"accessible","noun":"accessibility"}', NULL, 2, 48, 245),
(49, 'access control', '/ˈækses kənˈtrəʊl/', 'noun', '{"zh-TW":["存取控制"],"en":["mechanisms that restrict access to resources based on identity and permissions"]}', NULL, 'implement access control / access control list / role-based access control', '[{"en":"Role-based access control assigns permissions based on user roles.","zh-TW":"基於角色的存取控制根據用戶角色分配權限。"},{"en":"Access control logs help audit who accessed sensitive information.","zh-TW":"存取控制日誌幫助審計誰訪問了敏感信息。"}]', NULL, NULL, 5, 49, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(50, 'accession', '/ækˈseʃən/', 'noun', '{"zh-TW":["加入；就任"],"en":["formal joining of a group or treaty; coming to a position of power"]}', NULL, 'accession to a treaty / accession to the EU / accession negotiations', '[{"en":"The country''s accession to the trade agreement took three years of negotiations.","zh-TW":"該國加入貿易協議歷時三年的談判。"},{"en":"Presidential accession must follow established constitutional procedures.","zh-TW":"總統就任必須遵循既定的憲法程序。"}]', '{"verb":"accede"}', NULL, 3, 50, NULL),
(51, 'accident', 'ˈæksɪdənt', 'noun', '{"zh-TW":["意外；事故","偶然"],"en":["an unpleasant event that was not planned","a chance event"]}', NULL, 'car accident/work accident', '[{"en":"There was an accident on the highway.","zh-TW":"高速公路上發生了事故。"}]', '{"adjective":"accidental","adverb":"accidentally"}', NULL, 3, 51, NULL),
(52, 'accident report', '/ˈæksɪdənt rɪˈpɔːrt/', 'noun', '{"zh-TW":["事故報告"],"en":["a written account of a workplace accident"]}', NULL, 'file an accident report / complete an accident report', '[{"en":"An accident report must be submitted within 24 hours.","zh-TW":"事故報告必須在24小時內提交。"},{"en":"The accident report described how the injury occurred.","zh-TW":"事故報告描述了受傷是如何發生的。"}]', NULL, NULL, 5, 52, NULL),
(53, 'accommodate', '/əˈkɒmədeɪt/', 'verb', '{"zh-TW":["容納；適應","提供住宿"],"en":["to provide lodging or room for","to adjust to fit needs"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"commod","meaning":"fit (適合)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使適合，即「容納、適應」。"}', 'accommodate guests/needs/requests', '[{"en":"The hotel can accommodate up to 500 guests.","zh-TW":"該飯店可容納最多500位客人。"},{"en":"We will try to accommodate your schedule.","zh-TW":"我們會盡量配合您的時間表。"}]', '{"noun":"accommodation"}', NULL, 4, 53, 1),
(54, 'accommodation', '/əˌkɒməˈdeɪʃən/', 'noun', '{"zh-TW":["住宿設施"],"en":["a place to stay, especially on a trip"]}', NULL, 'hotel accommodation / book accommodation', '[{"en":"The accommodation was clean and comfortable.","zh-TW":"住宿環境乾淨舒適。"},{"en":"We need to arrange accommodation for conference delegates.","zh-TW":"我們需要為與會代表安排住宿。"}]', '{"verb":"accommodate","adjective":"accommodating"}', NULL, 5, 54, NULL),
(55, 'accomplish', '/əˈkɒmplɪʃ/', 'verb', '{"zh-TW":["完成；達成"],"en":["to succeed in doing or completing something","to achieve or complete successfully"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"compli","meaning":"fill (填滿)"},"suffix":{"text":"-ish","meaning":"to make (使)"},"logic":"使填滿完成，即「完成」。"}', 'accomplish a goal/task/mission; accomplish a goal / accomplish a task', '[{"en":"She accomplished all her objectives ahead of schedule.","zh-TW":"她提前完成了所有目標。"},{"en":"What do you hope to accomplish this quarter?","zh-TW":"你希望這季度達成什麼？"},{"en":"She accomplished her goal of running a marathon.","zh-TW":"她達成了跑馬拉松的目標。"},{"en":"What do you hope to accomplish today?","zh-TW":"你今天希望完成什麼？"}]', '{"noun":"accomplishment"}', NULL, 4, 55, 634),
(56, 'accomplishment', 'əˈkɒmplɪʃmənt', 'noun', '{"zh-TW":["成就；完成","業績"],"en":["something achieved successfully","a skill or ability"]}', NULL, 'list accomplishments/key accomplishment', '[{"en":"Please list your key accomplishments.","zh-TW":"請列出您的主要成就。"}]', '{"verb":"accomplish","adjective":"accomplished"}', NULL, 5, 56, NULL),
(57, 'account', '/əˈkaʊnt/', 'noun', '{"zh-TW":["帳戶；帳目","描述；報告"],"en":["a record of money received and spent","a description of an event"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"count","meaning":"count (計算)"},"logic":"朝向計算，即「帳戶」。"}', 'bank account / on account of', '[{"en":"Please transfer the payment to our company account.","zh-TW":"請將款項匯入我們的公司帳戶。"},{"en":"She gave a detailed account of the incident.","zh-TW":"她詳細描述了該事件。"}]', '{"noun":"accountant","adjective":"accountable"}', NULL, 3, 57, 246),
(58, 'account holder', '/əˈkaʊnt ˈhəʊldər/', 'noun', '{"zh-TW":["帳戶持有人"],"en":["the person or entity who owns a bank account"]}', NULL, 'primary account holder / joint account holder', '[{"en":"The account holder must sign all withdrawal forms.","zh-TW":"帳戶持有人必須在所有提款單上簽名。"},{"en":"She is the primary account holder on the joint account.","zh-TW":"她是聯名帳戶的主要帳戶持有人。"}]', NULL, NULL, 5, 58, NULL),
(59, 'account management', '/əˈkaʊnt ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["客戶管理；帳戶管理"],"en":["managing ongoing relationships with existing clients to retain and grow business"]}', NULL, 'strategic account management / key account management / account management team', '[{"en":"Strong account management is key to customer retention.","zh-TW":"強大的客戶管理是客戶保留的關鍵。"},{"en":"The account management team meets clients quarterly to review performance.","zh-TW":"帳戶管理團隊每季與客戶會面以審查績效。"}]', '{"noun":"account manager"}', NULL, 5, 59, NULL),
(60, 'account payable', '/əˈkaʊnt ˈpeɪəbl/', 'noun', '{"zh-TW":["應付帳款"],"en":["money owed by a company to suppliers for goods and services received"]}', NULL, 'pay the account payable / outstanding account payable', '[{"en":"The account payable was due within 30 days of the invoice date.","zh-TW":"應付帳款在發票日期後30天到期。"},{"en":"Managing account payable terms improves working capital efficiency.","zh-TW":"管理應付帳款條款提高了營運資金效率。"}]', '{"plural":"accounts payable"}', NULL, 5, 60, NULL),
(61, 'account receivable financing', '/əˈkaʊnt rɪˈsiːvəbl ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["應收帳款融資"],"en":["using outstanding invoices as collateral to obtain funding"]}', NULL, 'use account receivable financing / AR financing facility', '[{"en":"Account receivable financing helped the firm bridge its cash gap.","zh-TW":"應收帳款融資幫助公司彌補了現金缺口。"},{"en":"Banks offer account receivable financing to businesses with slow-paying clients.","zh-TW":"銀行為有緩慢付款客戶的企業提供應收帳款融資。"}]', NULL, NULL, 5, 61, NULL),
(62, 'accountability', '/əˌkaʊntəˈbɪlɪti/', 'noun', '{"zh-TW":["責任；問責"],"en":["the obligation to accept responsibility for one''s actions"]}', NULL, 'corporate accountability / accountability framework', '[{"en":"Accountability is central to good corporate governance.","zh-TW":"問責制是良好公司治理的核心。"},{"en":"The CEO was held to strict accountability for the losses.","zh-TW":"首席執行官對虧損負有嚴格責任。"}]', '{"adjective":"accountable","verb":"account"}', NULL, 5, 62, 739),
(63, 'accountability framework', '/''əˌkaʊntəˌbɪlɪti ˌfreɪmwɜːrk/', 'noun', '{"zh-TW":["問責框架；責任架構"],"en":["a structured system of responsibilities and expectations to ensure people are answerable for their actions"]}', NULL, 'establish an accountability framework / accountability framework requirements / implement an accountability framework', '[{"en":"The new accountability framework assigns clear responsibilities to each department.","zh-TW":"新的問責框架為每個部門分配了明確的責任。"},{"en":"Organizations without an accountability framework often struggle to address failures effectively.","zh-TW":"沒有問責框架的組織通常難以有效地解決失敗問題。"}]', NULL, NULL, 5, 63, NULL),
(64, 'accountant', '/əˈkaʊntənt/', 'noun', '{"zh-TW":["會計師；會計人員"],"en":["a professional who maintains and audits financial records"]}', NULL, 'qualified accountant / hire an accountant / management accountant', '[{"en":"The accountant prepared the year-end financial statements.","zh-TW":"會計師準備了年末財務報表。"},{"en":"A certified accountant is required for statutory audits.","zh-TW":"法定審計需要認證會計師。"}]', '{"plural":"accountants","adjective":"accounting"}', NULL, 4, 64, NULL),
(65, 'accounts payable', '/əˈkaʊnts ˈpeɪəbl/', 'noun', '{"zh-TW":["應付帳款"],"en":["money a company owes to its suppliers or vendors"]}', NULL, 'accounts payable process / manage accounts payable', '[{"en":"Extending accounts payable terms preserved cash.","zh-TW":"延長應付帳款期限保留了現金。"},{"en":"The accounts payable department processes invoices weekly.","zh-TW":"應付帳款部門每週處理發票。"}]', '{"abbreviation":"AP"}', NULL, 5, 65, NULL),
(66, 'accounts receivable', '/əˈkaʊnts rɪˈsiːvəbl/', 'noun', '{"zh-TW":["應收帳款"],"en":["money owed to a company by its customers"]}', NULL, 'manage accounts receivable / accounts receivable turnover', '[{"en":"High accounts receivable can signal collection problems.","zh-TW":"高應收帳款可能表明收款問題。"},{"en":"They factored their accounts receivable to improve cash flow.","zh-TW":"他們將應收帳款進行保理以改善現金流。"}]', '{"abbreviation":"AR"}', NULL, 5, 66, NULL),
(67, 'accounts receivable turnover', '/əˈkaʊnts rɪˈsiːvəbl ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["應收帳款周轉率"],"en":["a measure of how efficiently a company collects its outstanding receivables"]}', NULL, 'improve accounts receivable turnover / calculate accounts receivable turnover', '[{"en":"A high accounts receivable turnover indicates efficient credit management.","zh-TW":"高應收帳款周轉率表明信用管理效率高。"},{"en":"The company improved its accounts receivable turnover by tightening credit terms.","zh-TW":"公司通過收緊信用條款改善了應收帳款周轉率。"}]', NULL, NULL, 5, 67, NULL),
(68, 'accounts reconciliation', '/əˈkaʊnts ˌrekənsɪliˈeɪʃən/', 'noun', '{"zh-TW":["帳戶對帳"],"en":["matching transactions between accounting records and bank statements"]}', NULL, 'perform accounts reconciliation / monthly accounts reconciliation', '[{"en":"Accounts reconciliation revealed an unrecorded transaction.","zh-TW":"帳戶對帳發現了一筆未記錄的交易。"},{"en":"IT tools have automated the accounts reconciliation process.","zh-TW":"IT工具已自動化了帳戶對帳流程。"}]', NULL, NULL, 5, 68, NULL),
(69, 'accreditation', '/əˌkrɛdɪˈteɪʃən/', 'noun', '{"zh-TW":["認可；認證"],"en":["official recognition that a program meets established standards"]}', NULL, 'accreditation process / seek accreditation', '[{"en":"The university received accreditation from the national board.","zh-TW":"這所大學獲得了國家委員會的認可。"},{"en":"Accreditation ensures that educational programs meet quality standards.","zh-TW":"認證確保教育計劃符合品質標準。"}]', '{"verb":"accredit","adjective":"accredited"}', NULL, 5, 69, 740),
(70, 'accreditation body', '/əˌkrɛdɪˈteɪʃən ˈbɒdi/', 'noun', '{"zh-TW":["認證機構"],"en":["an organization that grants official accreditation"]}', NULL, 'apply to an accreditation body / recognized accreditation body', '[{"en":"The school is recognized by a leading international accreditation body.","zh-TW":"這所學校獲得了頂尖的國際認證機構的認可。"},{"en":"Accreditation bodies set standards for educational quality.","zh-TW":"認證機構為教育品質設定標準。"}]', NULL, NULL, 5, 70, NULL),
(71, 'accredited institution', '/''əˌkredɪtɪd ˌɪnstɪˈtjuːʃən/', 'noun', '{"zh-TW":["認可機構；獲認證的院校"],"en":["an educational institution that has been officially recognized as meeting required standards"]}', NULL, 'graduate from an accredited institution / recognized accredited institution', '[{"en":"A degree from an accredited institution is recognized by employers worldwide.","zh-TW":"來自認可機構的學位受到全球雇主的認可。"},{"en":"Ensure that your university is an accredited institution before enrolling.","zh-TW":"在入學前確認你的大學是一所認可機構。"}]', NULL, NULL, 5, 71, NULL),
(72, 'accretion', '/əˈkriːʃən/', 'noun', '{"zh-TW":["增長；積累；漸增"],"en":["growth by the gradual accumulation of additional layers or components"]}', NULL, 'natural accretion / accretion of power / accretion of wealth', '[{"en":"The delta was formed by the accretion of sediment over thousands of years.","zh-TW":"三角洲是數千年來沉積物積累而成的。"},{"en":"The company''s growth came through accretion of smaller acquisitions.","zh-TW":"公司的增長來自於一系列小規模收購的積累。"}]', '{"verb":"accrete","adjective":"accretive"}', NULL, 3, 72, NULL),
(73, 'accretive', '/əˈkriːtɪv/', 'adjective', '{"zh-TW":["增值的；累積成長的"],"en":["relating to the growth of a business through incremental additions"]}', NULL, 'accretive acquisition / accretive deal / accretive to earnings', '[{"en":"The acquisition is expected to be accretive to earnings in year two.","zh-TW":"該收購預計在第二年對盈利具有增值效果。"},{"en":"The board approved only accretive investments.","zh-TW":"董事會只批准增值性投資。"}]', '{"noun":"accretion","verb":"accrete"}', NULL, 3, 73, NULL),
(74, 'accrual', '/əˈkruːəl/', 'noun', '{"zh-TW":["應計；累計"],"en":["an accounting method recognizing revenues and expenses when earned or incurred"]}', NULL, 'accrual accounting / accrual basis / accrual method', '[{"en":"The company reports under the accrual basis of accounting.","zh-TW":"公司採用權責發生制報告。"},{"en":"Accruals ensure expenses match the period they relate to.","zh-TW":"應計確保費用與其相關期間匹配。"}]', '{"verb":"accrue","adjective":"accrued"}', NULL, 3, 74, 741),
(75, 'accrual accounting', '/əˈkruːəl əˈkaʊntɪŋ/', 'noun', '{"zh-TW":["應計制會計；權責發生制"],"en":["an accounting method recording revenues and expenses when earned or incurred"]}', NULL, 'use accrual accounting / switch to accrual accounting', '[{"en":"Most listed companies report under the accrual accounting basis.","zh-TW":"大多數上市公司採用應計制會計報告。"},{"en":"Accrual accounting gives a more accurate picture of financial health.","zh-TW":"應計制會計提供了更準確的財務狀況圖像。"}]', '{"alternative":"cash-basis accounting"}', NULL, 5, 75, NULL),
(76, 'accrual basis', '/əˈkruːəl ˈbeɪsɪs/', 'noun', '{"zh-TW":["應計制；權責發生制"],"en":["an accounting method recognizing income and expenses when incurred, not when paid"]}', NULL, 'report on accrual basis / accrual basis accounting', '[{"en":"Most large companies prepare accounts on an accrual basis.","zh-TW":"大多數大型公司採用應計制編制帳目。"},{"en":"On an accrual basis, revenue is recognized when earned, not when received.","zh-TW":"在應計制下，收入在賺得時確認，而非在收到時。"}]', '{"opposite":"cash basis"}', NULL, 5, 76, NULL),
(77, 'accrue', '/əˈkruː/', 'verb', '{"zh-TW":["累積；應計"],"en":["to accumulate or be received as a regular gain"]}', NULL, 'accrue interest / accrue benefits / accrue overtime', '[{"en":"Interest accrues daily on the outstanding balance.","zh-TW":"利息每天在未償餘額上累積。"},{"en":"Vacation days accrue at the rate of one day per month.","zh-TW":"假期以每月一天的速度累積。"}]', '{"noun":"accrual","adjective":"accrued"}', NULL, 2, 77, 727),
(78, 'accrued expense', '/əˈkruːd ɪkˈspens/', 'noun', '{"zh-TW":["應計費用"],"en":["an expense that has been incurred but not yet paid"]}', NULL, 'record accrued expenses / accrue expenses / accrued expense account', '[{"en":"Wages earned but unpaid at month-end are accrued expenses.","zh-TW":"月末已賺取但未支付的工資是應計費用。"},{"en":"The accountant reviewed all accrued expenses before closing.","zh-TW":"會計師在結帳前審查了所有應計費用。"}]', '{"plural":"accrued expenses","verb":"accrue"}', NULL, 5, 78, NULL),
(79, 'accrued expenses', '/əˈkruːd ɪkˈspensɪz/', 'noun', '{"zh-TW":["應計費用"],"en":["expenses that have been incurred but not yet paid or recorded in financial statements"]}', NULL, 'record accrued expenses / accrued expenses on balance sheet / reduce accrued expenses', '[{"en":"Accrued expenses such as unpaid wages appear as a current liability on the balance sheet.","zh-TW":"未支付工資等應計費用在資產負債表上顯示為流動負債。"},{"en":"Overstating accrued expenses is a common method of smoothing reported earnings.","zh-TW":"高估應計費用是平滑已報告收益的常用方法。"}]', NULL, NULL, 5, 79, NULL),
(80, 'accrued interest', '/əˈkruːd ˈɪntrəst/', 'noun', '{"zh-TW":["應計利息"],"en":["interest that has accumulated since the last payment date"]}', NULL, 'calculate accrued interest / pay accrued interest / accrued interest receivable', '[{"en":"The bond was sold with accrued interest of three months.","zh-TW":"債券以三個月的應計利息出售。"},{"en":"Accrued interest must be recognized on the balance sheet date.","zh-TW":"應計利息必須在資產負債表日確認。"}]', NULL, NULL, 5, 80, NULL),
(81, 'accrued liability', '/əˈkruːd laɪˈæbɪlɪti/', 'noun', '{"zh-TW":["應計負債"],"en":["an expense incurred but not yet paid at the reporting date"]}', NULL, 'record an accrued liability / accrued liability balance', '[{"en":"Salaries payable are recorded as an accrued liability at month end.","zh-TW":"應付薪資在月末被記錄為應計負債。"},{"en":"Accrued liabilities appear in the current liabilities section of the balance sheet.","zh-TW":"應計負債出現在資產負債表的流動負債部分。"}]', NULL, NULL, 5, 81, NULL),
(82, 'acculturation', '/əˌkʌltʃəˈreɪʃən/', 'noun', '{"zh-TW":["文化適應；移植文化"],"en":["the process of cultural change through contact with another culture"]}', NULL, 'acculturation process / acculturation stress / acculturate immigrants', '[{"en":"Acculturation studies examine how migrants adapt to new cultural environments.","zh-TW":"文化適應研究審視移民如何適應新的文化環境。"},{"en":"Acculturation can be a source of identity conflict for first-generation immigrants.","zh-TW":"文化適應對於第一代移民而言可能是身份認同衝突的根源。"}]', '{"verb":"acculturate","adjective":"acculturated"}', NULL, 5, 82, NULL),
(83, 'accumulate', '/əˈkjuːmjəleɪt/', 'verb', '{"zh-TW":["累積；積聚"],"en":["to gather together or acquire an increasing amount"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cumul","meaning":"heap (堆積)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使堆積起來，即「累積」。"}', 'accumulate wealth/debt/experience', '[{"en":"He accumulated considerable wealth over the years.","zh-TW":"他多年來累積了可觀的財富。"},{"en":"Dust had accumulated on the unused equipment.","zh-TW":"未使用的設備上積了灰塵。"}]', '{"noun":"accumulation"}', NULL, 4, 83, 635),
(84, 'accumulated depreciation', '/əˌkjuːmjəleɪtɪd dɪˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["累計折舊"],"en":["the total amount of depreciation charged against an asset since its acquisition"]}', NULL, 'calculate accumulated depreciation / accumulated depreciation account', '[{"en":"Accumulated depreciation is subtracted from cost to show net book value.","zh-TW":"累計折舊從成本中扣除以顯示淨帳面價值。"},{"en":"Fully depreciated assets have accumulated depreciation equal to their cost.","zh-TW":"已完全折舊的資產的累計折舊等於其成本。"}]', NULL, NULL, 5, 84, NULL),
(85, 'accuracy', 'ˈækjərəsi', 'noun', '{"zh-TW":["準確性；精確度","正確性"],"en":["the quality of being correct","freedom from error"]}', NULL, 'data accuracy/improve accuracy', '[{"en":"Please check the accuracy of the figures.","zh-TW":"請核實數字的準確性。"}]', '{"adjective":"accurate","adverb":"accurately"}', NULL, 3, 85, 973),
(86, 'accurate', '/ˈækjərət/', 'adjective', '{"zh-TW":["準確的；精確的","準確的"],"en":["correct in all details; exact","correct in all details"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cur","meaning":"care (注意)"},"suffix":{"text":"-ate","meaning":"having quality (具有特質)"},"logic":"朝向注意的，即「準確的」。"}', 'accurate information/data/description; accurate information / accurate prediction', '[{"en":"Please ensure that all data entries are accurate.","zh-TW":"請確保所有資料輸入準確無誤。"},{"en":"The forecast proved to be highly accurate.","zh-TW":"該預測被證明非常準確。"},{"en":"The report contains accurate data.","zh-TW":"報告包含準確的數據。"},{"en":"Her prediction turned out to be accurate.","zh-TW":"她的預測結果證明是準確的。"}]', '{"noun":"accuracy","adverb":"accurately"}', NULL, 3, 86, 247),
(87, 'achieve', '/əˈtʃiːv/', 'verb', '{"zh-TW":["達成；實現"],"en":["to successfully reach a goal by effort"]}', '{"prefix":{"text":"a-","meaning":"to (朝向)"},"root":{"text":"chieve","meaning":"come to head (完成)"},"logic":"朝向完成，即「達成」。"}', 'achieve a goal/success/results', '[{"en":"The team achieved record sales this quarter.","zh-TW":"團隊本季度達成了創紀錄的銷售額。"},{"en":"She achieved her ambition of becoming CEO.","zh-TW":"她實現了成為執行長的抱負。"}]', '{"noun":"achievement","adjective":"achievable"}', NULL, 3, 87, 248),
(88, 'achievement', '/əˈtʃiːvmənt/', 'noun', '{"zh-TW":["成就；成績"],"en":["a thing accomplished, especially by effort or skill"]}', NULL, 'academic achievement / achievement award', '[{"en":"She graduated with outstanding academic achievements.","zh-TW":"她以卓越的學業成就畢業。"},{"en":"The award recognizes the student''s remarkable achievements.","zh-TW":"該獎項表彰了學生的卓越成就。"}]', '{"verb":"achieve","adjective":"achievable"}', NULL, 4, 88, 68),
(89, 'acidification', '/əˌsɪdɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["酸化"],"en":["the process of becoming acid; specifically, ocean acidification from CO₂"]}', NULL, 'ocean acidification / soil acidification / acidification of lakes', '[{"en":"Ocean acidification harms marine organisms that build calcium shells.","zh-TW":"海洋酸化損害了構建碳酸鈣外殼的海洋生物。"},{"en":"Industrial emissions have caused acidification of many freshwater lakes.","zh-TW":"工業排放導致許多淡水湖泊酸化。"}]', '{"verb":"acidify","adjective":"acidified"}', NULL, 5, 89, NULL),
(90, 'acknowledge', '/əkˈnɒlɪdʒ/', 'verb', '{"zh-TW":["承認；確認","致謝","承認；答謝"],"en":["to accept or admit the truth of","to show that one has noticed","to accept or admit the truth of something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"knowledge","meaning":"knowledge (知識)"},"logic":"朝向知道，即「承認」。"}', 'acknowledge receipt/contribution; acknowledge a mistake / acknowledge receipt', '[{"en":"The company acknowledged the error in the report.","zh-TW":"公司承認了報告中的錯誤。"},{"en":"Please acknowledge receipt of this email.","zh-TW":"請確認收到此電子郵件。"},{"en":"He acknowledged his mistake.","zh-TW":"他承認了自己的錯誤。"}]', '{"noun":"acknowledgment"}', NULL, 4, 90, 249),
(91, 'acknowledgment', '/əkˈnɒlɪdʒmənt/', 'noun', '{"zh-TW":["確認；感謝"],"en":["recognition or confirmation of receiving something"]}', NULL, 'acknowledgment of receipt / written acknowledgment', '[{"en":"Please send an acknowledgment once the package is received.","zh-TW":"收到包裹後請發送確認訊息。"},{"en":"The acknowledgment letter confirmed the application was received.","zh-TW":"確認信確認了申請書已被收到。"}]', '{"verb":"acknowledge","adjective":"acknowledged"}', NULL, 5, 91, NULL),
(92, 'acquire', '/əˈkwaɪər/', 'verb', '{"zh-TW":["獲得；取得","收購","獲得；收購"],"en":["to buy or obtain something","to learn or develop a skill","to gain possession of something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"quire","meaning":"seek (尋求)"},"logic":"朝向尋求，即「獲得」。"}', 'acquire skills/knowledge/company; acquire knowledge / acquire a company', '[{"en":"The firm acquired a smaller competitor last year.","zh-TW":"該公司去年收購了一家較小的競爭對手。"},{"en":"She acquired fluency in three languages.","zh-TW":"她掌握了三種語言的流利程度。"},{"en":"She acquired fluency in three languages.","zh-TW":"她習得了三種語言的流利度。"},{"en":"The company acquired a smaller competitor.","zh-TW":"公司收購了一家較小的競爭者。"}]', '{"noun":"acquisition"}', NULL, 3, 92, 2),
(93, 'acquisition', '/ˌækwɪˈzɪʃn/', 'noun', '{"zh-TW":["收購；獲得"],"en":["the purchase of one company by another","the act of obtaining something","the buying of a company","the process of gaining something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"quis","meaning":"seek (尋求)"},"suffix":{"text":"-ition","meaning":"action (動作)"},"logic":"朝向尋求的動作，即「收購」。"}', 'mergers and acquisitions / acquisition strategy; mergers and acquisitions / customer acquisition', '[{"en":"The acquisition was valued at $2 billion.","zh-TW":"此次收購估值為20億美元。"},{"en":"Customer acquisition costs have increased.","zh-TW":"客戶獲取成本增加了。"},{"en":"The acquisition was worth $2 billion.","zh-TW":"這次收購價值20億美元。"},{"en":"Customer acquisition costs are rising.","zh-TW":"客戶獲取成本正在上升。"}]', '{"verb":"acquire","noun":"acquisition"}', NULL, 4, 93, 491),
(94, 'acquisition cost', '/ˌækwɪˈzɪʃən kɒst/', 'noun', '{"zh-TW":["收購成本；取得成本"],"en":["the total cost to acquire an asset or customer"]}', NULL, 'reduce acquisition cost / customer acquisition cost', '[{"en":"Customer acquisition cost fell after the new referral program launched.","zh-TW":"新推薦計劃推出後，客戶取得成本下降了。"},{"en":"The acquisition cost of the target company included a 20% premium.","zh-TW":"目標公司的收購成本包括20%的溢價。"}]', NULL, NULL, 5, 94, NULL),
(95, 'acronym', '/''ækrənɪm/', 'noun', '{"zh-TW":["首字母縮略詞；縮寫詞"],"en":["a word formed from the initial letters of other words"]}', NULL, 'use an acronym / common acronym / business acronym', '[{"en":"NASA is an acronym for the National Aeronautics and Space Administration.","zh-TW":"NASA是美國國家航空暨太空總署的首字母縮略詞。"},{"en":"Business communication is full of acronyms like ROI and KPI.","zh-TW":"商業溝通中充滿了ROI和KPI等首字母縮略詞。"}]', NULL, NULL, 3, 95, NULL),
(96, 'across', '/əˈkrɒs/', 'preposition', '{"zh-TW":["橫越；在對面","穿過；橫跨","橫越；穿過；在對面"],"en":["from one side to the other","from one side to the other; on the opposite side"]}', NULL, 'come across / across from; across the street / come across; across from (在...對面)', '[{"en":"The office is across from the station.","zh-TW":"辦公室在車站對面。"},{"en":"We expanded across the region.","zh-TW":"我們擴展到整個地區。"},{"en":"She walked across the bridge.","zh-TW":"她走過了那座橋。"},{"en":"I came across an old friend.","zh-TW":"我偶然遇到了一位老朋友。"},{"en":"She walked across the street.","zh-TW":"她走過馬路。"},{"en":"The store is across from the bank.","zh-TW":"商店在銀行對面。"}]', '{"preposition":"across"}', NULL, 2, 96, NULL),
(97, 'act', 'ˈækt', 'verb', '{"zh-TW":["行動；表現","扮演"],"en":["to do something","to perform in a play"]}', NULL, 'act quickly/responsibly', '[{"en":"She acted quickly in the emergency.","zh-TW":"她在緊急情況下迅速行動。"}]', '{"noun":"action, actor","adjective":"active","adverb":"actively"}', NULL, 1, 97, NULL),
(98, 'action', 'ˈækʃən', 'noun', '{"zh-TW":["行動；措施","訴訟"],"en":["the process of doing something","a legal process"]}', NULL, 'take action/course of action', '[{"en":"We need to take immediate action.","zh-TW":"我們需要立即採取行動。"}]', '{"verb":"act","adjective":"active","adverb":"actively"}', NULL, 2, 98, NULL),
(99, 'action item', '/ˈækʃən ˈaɪtəm/', 'noun', '{"zh-TW":["行動事項；待辦事項"],"en":["a specific task assigned to a person following a meeting"]}', NULL, 'assign action items / track action items / close action items', '[{"en":"Each action item was assigned to a specific team member.","zh-TW":"每個行動事項都分配給了特定的團隊成員。"},{"en":"Outstanding action items were reviewed at the start of the meeting.","zh-TW":"未完成的行動事項在會議開始時進行了審查。"}]', '{"plural":"action items"}', NULL, 4, 99, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(100, 'actionable', '/ˈækʃənəbəl/', 'adjective', '{"zh-TW":["可行的；可採取行動的"],"en":["capable of being acted on; providing a basis for action"]}', NULL, 'actionable insights / actionable recommendation', '[{"en":"The report provides actionable recommendations for improvement.","zh-TW":"報告提供了可行的改進建議。"},{"en":"Good data analysis produces actionable insights for managers.","zh-TW":"良好的數據分析為管理者提供可採取行動的洞見。"}]', NULL, NULL, 4, 100, 951),
(101, 'activate', 'ˈæktɪveɪt', 'verb', '{"zh-TW":["啟動；激活","開啟"],"en":["to start something working","to put into operation"]}', NULL, 'activate an account/activate a feature', '[{"en":"Please activate your account to begin.","zh-TW":"請啟動您的帳戶以開始。"}]', '{"noun":"activation","adjective":"active","adverb":"actively"}', NULL, 3, 101, 813),
(102, 'active', 'ˈæktɪv', 'adjective', '{"zh-TW":["積極的；活躍的","主動的"],"en":["energetic and engaged","in operation"]}', NULL, 'active role/active member', '[{"en":"He plays an active role in the community.","zh-TW":"他在社區中扮演積極的角色。"}]', '{"noun":"activity","adverb":"actively"}', NULL, 2, 102, NULL),
(103, 'active learning', '/''æktɪv ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["主動學習；積極學習"],"en":["an approach to education that involves students actively participating rather than passively receiving information"]}', NULL, 'promote active learning / active learning strategy / active learning environment', '[{"en":"Active learning strategies include group discussions, problem-solving, and debates.","zh-TW":"主動學習策略包括小組討論、解決問題和辯論。"},{"en":"Teachers who use active learning techniques see higher student engagement.","zh-TW":"使用主動學習技術的教師看到更高的學生參與度。"}]', NULL, NULL, 5, 103, NULL),
(104, 'active listening', '/ˈæktɪv ˈlɪsənɪŋ/', 'noun', '{"zh-TW":["積極傾聽"],"en":["fully concentrating and responding thoughtfully to what a person is saying"]}', NULL, 'practice active listening / active listening skills', '[{"en":"Active listening is critical in customer service and negotiations.","zh-TW":"積極傾聽在客戶服務和談判中至關重要。"},{"en":"Managers who use active listening build stronger team relationships.","zh-TW":"使用積極傾聽的管理者建立了更強的團隊關係。"}]', NULL, NULL, 5, 104, NULL),
(105, 'active management', '/ˈæktɪv ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["主動管理"],"en":["an investment strategy where managers make specific investment decisions to outperform the market"]}', NULL, 'employ active management / active management fees', '[{"en":"Active management aims to beat benchmark returns through stock selection.","zh-TW":"主動管理旨在通過選股超越基準回報。"},{"en":"Higher fees for active management must be justified by superior returns.","zh-TW":"主動管理的較高費用必須通過卓越回報來證明合理性。"}]', '{"opposite":"passive management"}', NULL, 5, 105, NULL),
(106, 'active recovery', '/''æktɪv rɪˌkʌvəri/', 'noun', '{"zh-TW":["主動恢復；積極恢復訓練"],"en":["light physical activity done on rest days to aid muscle recovery without causing additional fatigue"]}', NULL, 'use active recovery / active recovery day / active recovery exercise', '[{"en":"She went for an easy swim as active recovery after the intense marathon race.","zh-TW":"她在激烈的馬拉松比賽後進行了一次輕鬆的游泳作為主動恢復。"},{"en":"Active recovery methods like yoga and walking are preferred by many elite athletes.","zh-TW":"許多精英運動員喜歡瑜伽和步行等主動恢復方法。"}]', '{"adjective":"active","verb":"recover"}', NULL, 5, 106, NULL),
(107, 'actual', 'ˈæktʃuəl', 'adjective', '{"zh-TW":["實際的；真正的","現實的"],"en":["existing in reality","real"]}', NULL, 'actual cost/actual results', '[{"en":"The actual cost exceeded the budget.","zh-TW":"實際成本超出了預算。"}]', '{"noun":"actuality","adverb":"actually"}', NULL, 2, 107, 814),
(108, 'actualize', '/ˈæktʃuəlaɪz/', 'verb', '{"zh-TW":["實現；使現實化"],"en":["to make something real or actual"]}', NULL, 'actualize potential / actualize a vision / actualize goals', '[{"en":"The training program helps employees actualize their professional potential.","zh-TW":"培訓計畫幫助員工實現其專業潛力。"},{"en":"The project team worked to actualize the architect''s creative vision.","zh-TW":"項目團隊努力實現建築師的創意願景。"}]', '{"noun":"actualization","adjective":"actualized"}', NULL, 3, 108, NULL),
(109, 'actuary', '/ˈæktʃuəri/', 'noun', '{"zh-TW":["精算師"],"en":["a person who uses mathematics and statistics to assess financial risks"]}', NULL, 'qualified actuary / insurance actuary / pension actuary', '[{"en":"An actuary calculates premiums based on statistical risk models.","zh-TW":"精算師根據統計風險模型計算保費。"},{"en":"Pension fund actuaries must forecast long-term obligations accurately.","zh-TW":"養老基金精算師必須準確預測長期義務。"}]', '{"noun2":"actuarial","adjective":"actuarial"}', NULL, 3, 109, NULL),
(110, 'actuator', '/ˈæktʃueɪtər/', 'noun', '{"zh-TW":["執行器；致動器"],"en":["a device that converts energy into physical movement to control a system"]}', NULL, 'control an actuator / linear actuator / smart actuator', '[{"en":"The robot''s arm is controlled by precision actuators.","zh-TW":"機器人的手臂由精密執行器控制。"},{"en":"Smart actuators in HVAC systems automatically adjust temperature.","zh-TW":"暖通空調系統中的智能執行器自動調節溫度。"}]', NULL, NULL, 3, 110, NULL),
(111, 'acuity', '/əˈkjuːɪti/', 'noun', '{"zh-TW":["敏銳；清晰度"],"en":["sharpness or keenness of thought, vision, or hearing"]}', NULL, 'visual acuity / mental acuity / business acuity', '[{"en":"Her mental acuity was remarkable even at an advanced age.","zh-TW":"她在高齡時仍展現出卓越的思維敏銳度。"},{"en":"Market acuity allows leaders to spot opportunities before competitors do.","zh-TW":"市場敏銳度使領導者能夠在競爭對手之前發現機會。"}]', NULL, NULL, 2, 111, NULL),
(112, 'acumen', '/ˈækjʊmən/', 'noun', '{"zh-TW":["敏銳；洞察力"],"en":["the ability to make good judgments and quick decisions"]}', NULL, 'business acumen / financial acumen / sharp acumen', '[{"en":"Her business acumen helped the company grow rapidly.","zh-TW":"她的商業敏銳度幫助公司快速成長。"},{"en":"He demonstrated remarkable acumen in identifying market trends.","zh-TW":"他在識別市場趨勢方面展現出卓越的洞察力。"}]', NULL, NULL, 2, 112, NULL),
(113, 'acupuncture', '/ˈækjʊˌpʌŋktʃər/', 'noun', '{"zh-TW":["針灸"],"en":["a therapy involving inserting needles into the body at specific points"]}', NULL, 'receive acupuncture / acupuncture treatment', '[{"en":"She tried acupuncture to relieve chronic back pain.","zh-TW":"她嘗試針灸來緩解慢性背痛。"},{"en":"Acupuncture is widely used in traditional Chinese medicine.","zh-TW":"針灸在中醫中被廣泛使用。"}]', '{"adjective":"acupuncture"}', NULL, 4, 113, NULL),
(114, 'acupuncturist', '/ˌækjʊˈpʌŋktʃərɪst/', 'noun', '{"zh-TW":["針灸師"],"en":["a practitioner who performs acupuncture treatment"]}', NULL, 'licensed acupuncturist / qualified acupuncturist / consult an acupuncturist', '[{"en":"The acupuncturist treated her chronic back pain with fine needles.","zh-TW":"針灸師用細針治療她的慢性背痛。"},{"en":"An acupuncturist must complete specialized training to practice.","zh-TW":"針灸師必須完成專業培訓才能執業。"}]', NULL, NULL, 5, 114, NULL),
(115, 'acute', '/''əˈkjuːt/', 'adjective', '{"zh-TW":["急性的；敏銳的；嚴重的"],"en":["of a bad, difficult, or unwelcome situation or phenomenon; present to a severe or intense degree"]}', NULL, 'acute shortage / acute awareness / acute sense', '[{"en":"There is an acute shortage of qualified engineers in the technology sector.","zh-TW":"科技行業合格工程師嚴重短缺。"},{"en":"She has an acute awareness of market trends that helps her make timely decisions.","zh-TW":"她對市場趨勢有敏銳的洞察力，幫助她及時做出決策。"}]', '{"adverb":"acutely","noun":"acuteness"}', NULL, 2, 115, NULL),
(116, 'ad hoc', '/ˌæd ˈhɒk/', 'adjective', '{"zh-TW":["臨時的；特別的"],"en":["created or done for a specific purpose without prior planning"]}', NULL, 'ad hoc meeting / ad hoc committee / ad hoc arrangement', '[{"en":"An ad hoc committee was formed to handle the merger negotiations.","zh-TW":"一個臨時委員會成立以處理合併談判。"},{"en":"Ad hoc decisions should not replace a formal strategic process.","zh-TW":"臨時決策不應取代正式的戰略流程。"}]', NULL, NULL, 2, 116, NULL),
(117, 'ad valorem tax', '/æd vəˈlɔːrəm tæks/', 'noun', '{"zh-TW":["從價稅"],"en":["a tax based on the assessed value of a transaction, typically a percentage"]}', NULL, 'apply an ad valorem tax / ad valorem tax rate', '[{"en":"Import duties are often structured as an ad valorem tax on the goods'' value.","zh-TW":"進口關稅通常以貨物價值的從價稅形式徵收。"},{"en":"An ad valorem tax rate of 15% applies to all luxury goods imported.","zh-TW":"15%的從價稅率適用於所有進口奢侈品。"}]', NULL, NULL, 5, 117, NULL),
(118, 'adamant', '/''ædəmənt/', 'adjective', '{"zh-TW":["堅定不移的；不為所動的"],"en":["refusing to be persuaded or to change one''s mind"]}', NULL, 'adamant refusal / remain adamant / be adamant about', '[{"en":"The manager was adamant that the deadline could not be extended.","zh-TW":"管理者堅定地認為截止日期不能延長。"},{"en":"She was adamant about maintaining quality standards despite the budget pressure.","zh-TW":"儘管有預算壓力，她仍堅定不移地堅持質量標準。"}]', '{"adverb":"adamantly"}', NULL, 3, 118, NULL),
(119, 'adapt', '/əˈdæpt/', 'verb', '{"zh-TW":["適應；改編"],"en":["to adjust to new conditions","to modify for a new purpose"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"apt","meaning":"fit (適合)"},"logic":"朝向適合，即「適應」。"}', 'adapt to changes/environment; adapt to / adapt a novel', '[{"en":"Employees must adapt to new technologies quickly.","zh-TW":"員工必須快速適應新技術。"},{"en":"The novel was adapted into a film.","zh-TW":"這部小說被改編成電影。"},{"en":"Animals must adapt to their environment.","zh-TW":"動物必須適應環境。"},{"en":"The novel was adapted into a film.","zh-TW":"這本小說被改編成電影。"}]', '{"noun":"adaptation","adjective":"adaptable"}', NULL, 2, 119, 815),
(120, 'adaptability', '/əˌdæptəˈbɪlɪti/', 'noun', '{"zh-TW":["適應能力"],"en":["the ability to adjust to new conditions or requirements quickly"]}', NULL, 'demonstrate adaptability / adaptability in the workplace / build adaptability', '[{"en":"Adaptability is increasingly valued as business environments change rapidly.","zh-TW":"隨著商業環境快速變化，適應能力日益受到重視。"},{"en":"Her adaptability made her an asset during the company restructuring.","zh-TW":"她的適應能力使她在公司重組期間成為寶貴資產。"}]', '{"adjective":"adaptable","verb":"adapt"}', NULL, 4, 120, 742),
(121, 'adaptive algorithm', '/əˈdæptɪv ˈælɡərɪðəm/', 'noun', '{"zh-TW":["自適應算法"],"en":["an algorithm that adjusts its behavior in response to input data"]}', NULL, 'develop an adaptive algorithm / apply an adaptive algorithm / use an adaptive algorithm', '[{"en":"Adaptive algorithms improve recommendation accuracy over time.","zh-TW":"自適應算法隨時間的推移提高推薦準確性。"},{"en":"The system uses an adaptive algorithm to optimize energy consumption.","zh-TW":"系統使用自適應算法來優化能源消耗。"}]', NULL, NULL, 5, 121, NULL),
(122, 'add', '/æd/', 'verb', '{"zh-TW":["增加；添加","增加；添加；補充說"],"en":["to put something with something else","to put something with another thing; to say something more"]}', NULL, 'add up / add to; add up (加總) / add to (增添)', '[{"en":"Add some sugar to my coffee.","zh-TW":"在我的咖啡裡加些糖。"},{"en":"The numbers don''t add up.","zh-TW":"這些數字加起來不對。"},{"en":"Please add your name to the list.","zh-TW":"請把你的名字加到名單上。"},{"en":"The rain added to our difficulties.","zh-TW":"雨水增加了我們的困難。"}]', '{"noun":"addition","adjective":"additional","adverb":"additionally"}', NULL, 1, 122, NULL),
(123, 'addendum', '/əˈdɛndəm/', 'noun', '{"zh-TW":["附錄；補充條款"],"en":["an item added to a contract or document"]}', NULL, 'add an addendum / contract addendum', '[{"en":"An addendum was attached to the agreement outlining new terms.","zh-TW":"協議附上了說明新條款的附錄。"},{"en":"Please sign the addendum to confirm the changes.","zh-TW":"請簽署附錄以確認更改。"}]', '{"plural":"addenda"}', NULL, 3, 123, NULL),
(124, 'additional', '/əˈdɪʃənl/', 'adjective', '{"zh-TW":["額外的；附加的"],"en":["extra; more than what is usual or expected"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"dit","meaning":"give (給予)"},"suffix":{"text":"-ional","meaning":"relating to (有關的)"},"logic":"額外給予的，即「額外的」。"}', 'additional cost/information/support', '[{"en":"There will be an additional charge for express delivery.","zh-TW":"快遞將收取額外費用。"},{"en":"Do you need any additional information?","zh-TW":"您需要任何額外資訊嗎？"}]', '{"noun":"addition","adverb":"additionally"}', NULL, 4, 124, 816),
(125, 'address', '/əˈdres/', 'verb', '{"zh-TW":["【主要意義-名詞】地址；住址","【次要意義-動詞】處理；著手解決（問題）","【次要意義-動詞】向……發表演說；稱呼"],"en":["[primary - noun] the details of where someone lives or works","[secondary - verb] to deal with or direct attention to a problem or issue","[secondary - verb] to speak formally to a group or person"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"dress","meaning":"direct (引導)"},"logic":"朝向引導，即「處理；致辭」。"}', 'address a problem / address concerns / address the audience / address the issue', '[{"en":"The new policy aims to address the growing concerns about workplace safety.","zh-TW":"新政策旨在解決對工作場所安全日益增長的擔憂。"},{"en":"The CEO addressed shareholders at the annual general meeting.","zh-TW":"執行長在年度股東大會上向股東發表演說。"},{"en":"We need to address the budget shortfall before the end of the quarter.","zh-TW":"我們需要在季度結束前解決預算短缺問題。"}]', '{"noun":"addressee","adjective":"addressable"}', '動詞 address = 「處理/解決」某問題，是 TOEIC 最高頻動詞之一，句型 address + issue/concern/problem 極為常見，考生常誤以為只有「地址」的意思。', 3, 125, 251),
(126, 'adept', '/əˈdept/', 'adjective', '{"zh-TW":["熟練的；精通的"],"en":["highly skilled or proficient at something"]}', NULL, 'adept at / adept negotiator / become adept', '[{"en":"She is adept at navigating complex organizational dynamics.","zh-TW":"她擅長處理複雜的組織動態。"},{"en":"He became adept at managing multiple projects simultaneously.","zh-TW":"他在同時管理多個項目方面變得非常熟練。"}]', '{"adverb":"adeptly","noun":"adeptness"}', NULL, 2, 126, NULL),
(127, 'adequate', '/ˈædɪkwət/', 'adjective', '{"zh-TW":["足夠的；適當的"],"en":["sufficient for a specific need or requirement","sufficient for a specific requirement"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"equ","meaning":"equal (相等)"},"suffix":{"text":"-ate","meaning":"having quality (具有)"},"logic":"朝向相等，即「足夠的」。"}', 'adequate supply/funding/preparation; adequate supply / adequate preparation', '[{"en":"The budget is barely adequate for the project.","zh-TW":"預算勉強夠用於該專案。"},{"en":"Ensure adequate ventilation in the workspace.","zh-TW":"確保工作空間有充足的通風。"},{"en":"The hotel room was adequate for our needs.","zh-TW":"飯店房間足以滿足我們的需求。"},{"en":"Make sure you have adequate insurance.","zh-TW":"確保你有足夠的保險。"}]', '{"noun":"adequacy","adverb":"adequately"}', NULL, 3, 127, 69),
(128, 'adhere', '/ədˈhɪər/', 'verb', '{"zh-TW":["遵守；堅持","黏附"],"en":["to follow rules or guidelines closely","to stick firmly to a surface"]}', '{"prefix":{"text":"ad-","meaning":"to (朝向)"},"root":{"text":"here","meaning":"stick (黏)"},"logic":"朝向黏住，即「遵守、黏附」。"}', 'adhere to rules/policies/standards', '[{"en":"All employees must adhere to the company''s code of conduct.","zh-TW":"所有員工都必須遵守公司行為準則。"},{"en":"Please adhere to the safety guidelines at all times.","zh-TW":"請隨時遵守安全指南。"}]', '{"noun":"adherence","adjective":"adherent"}', NULL, 2, 128, 636),
(129, 'adjacent', '/əˈdʒeɪsnt/', 'adjective', '{"zh-TW":["鄰近的；毗鄰的"],"en":["next to or near something"]}', '{"prefix":{"text":"ad-","meaning":"near (靠近)"},"root":{"text":"jac","meaning":"lie (躺)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"躺在旁邊的，即「鄰近的」。"}', 'adjacent to / adjacent building/room', '[{"en":"The parking lot is adjacent to the main building.","zh-TW":"停車場緊鄰主建築。"},{"en":"We booked adjacent conference rooms for the event.","zh-TW":"我們為活動預訂了相鄰的會議室。"}]', NULL, NULL, 3, 129, 3),
(130, 'adjourn', '/əˈdʒɜːrn/', 'verb', '{"zh-TW":["休會；延期"],"en":["to suspend a meeting or session to a later time"]}', NULL, 'adjourn the meeting / adjourn until next week', '[{"en":"The chairperson adjourned the meeting after three hours.","zh-TW":"主席在三小時後宣布休會。"},{"en":"The hearing was adjourned pending new evidence.","zh-TW":"聽證會因等待新證據而被延期。"}]', '{"noun":"adjournment","adjective":"adjourned"}', NULL, 3, 130, 817),
(131, 'adjournment', '/əˈdʒɜːrnmənt/', 'noun', '{"zh-TW":["休會；延期"],"en":["the act of suspending a meeting to a later time"]}', NULL, 'motion for adjournment / meeting adjournment', '[{"en":"The adjournment allowed more time for preparation.","zh-TW":"休會提供了更多的準備時間。"},{"en":"The chairperson called for an adjournment after two hours.","zh-TW":"主席在兩小時後宣布休會。"}]', '{"verb":"adjourn"}', NULL, 4, 131, 976),
(132, 'adjudicate', '/əˈdʒuːdɪkeɪt/', 'verb', '{"zh-TW":["裁決；判決"],"en":["to make a formal judgment or decision about a dispute"]}', NULL, 'adjudicate a dispute / adjudicate a claim / adjudicate a case', '[{"en":"The tribunal adjudicated the labor dispute in favor of the workers.","zh-TW":"裁判所就勞資糾紛作出有利工人的裁決。"},{"en":"Regulatory bodies adjudicate complaints about unfair market practices.","zh-TW":"監管機構裁決關於不公平市場行為的投訴。"}]', '{"noun":"adjudication","noun2":"adjudicator"}', NULL, 4, 132, NULL),
(133, 'adjust', '/əˈdʒʌst/', 'verb', '{"zh-TW":["調整；校準","調整"],"en":["to alter slightly to achieve the desired result","to alter slightly to achieve a desired result"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"just","meaning":"right (正確)"},"logic":"朝向正確，即「調整」。"}', 'adjust settings/schedule/strategy; adjust settings / adjust to', '[{"en":"We need to adjust our strategy to meet market demands.","zh-TW":"我們需要調整策略以滿足市場需求。"},{"en":"The price has been adjusted for inflation.","zh-TW":"價格已根據通膨進行調整。"},{"en":"You can adjust the temperature with this dial.","zh-TW":"你可以用這個旋鈕調整溫度。"},{"en":"It took time to adjust to the new schedule.","zh-TW":"適應新時間表需要一些時間。"}]', '{"noun":"adjustment","adjective":"adjustable"}', NULL, 2, 133, 818),
(134, 'adjusting entry', '/əˈdʒʌstɪŋ ˈentri/', 'noun', '{"zh-TW":["調整分錄"],"en":["an accounting entry made at the end of a period to update accounts"]}', NULL, 'make an adjusting entry / adjusting entry for accruals', '[{"en":"Adjusting entries ensure that revenues and expenses are properly matched.","zh-TW":"調整分錄確保收入和費用的適當配比。"},{"en":"The accountant made adjusting entries to correct the monthly accounts.","zh-TW":"會計師進行了調整分錄以修正月度帳目。"}]', NULL, NULL, 5, 134, NULL),
(135, 'administer', '/ədˈmɪnɪstər/', 'verb', '{"zh-TW":["管理；執行","施予"],"en":["to manage or direct","to give or apply formally","to manage or be responsible for"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"minister","meaning":"serve (服務)"},"logic":"朝向服務，即「管理」。"}', 'administer a program/test/policy; administer a program / administer medicine', '[{"en":"The HR department administers the benefits program.","zh-TW":"人力資源部門管理福利計畫。"},{"en":"The exam will be administered next Monday.","zh-TW":"考試將於下週一進行。"},{"en":"She administers the company''s finances.","zh-TW":"她管理公司的財務。"},{"en":"The nurse administered the medication.","zh-TW":"護理師給予了藥物。"}]', '{"noun":"administration","adjective":"administrative","noun2":"administrator"}', NULL, 4, 135, 638),
(136, 'administration', '/ədˌmɪnɪˈstreɪʃən/', 'noun', '{"zh-TW":["行政；管理"],"en":["the management and organization of a business or institution"]}', NULL, 'business administration / public administration / administration team', '[{"en":"The administration team handles all scheduling and correspondence.","zh-TW":"行政團隊處理所有排程和信件往來。"},{"en":"A degree in business administration is highly valued by employers.","zh-TW":"工商管理學位受到雇主的高度重視。"}]', '{"verb":"administer","adjective":"administrative","noun":"administrator"}', NULL, 5, 136, 494),
(137, 'administrative assistant', '/ədˈmɪnɪstrətɪv əˈsɪstənt/', 'noun', '{"zh-TW":["行政助理"],"en":["a person who provides organizational support to an office"]}', NULL, 'hire an administrative assistant / senior administrative assistant', '[{"en":"The administrative assistant scheduled all meetings.","zh-TW":"行政助理安排了所有會議。"},{"en":"A reliable administrative assistant is essential for a smooth operation.","zh-TW":"可靠的行政助理對於順暢運作至關重要。"}]', NULL, NULL, 5, 137, NULL),
(138, 'administrative expense', '/ədˈmɪnɪstrətɪv ɪkˈspens/', 'noun', '{"zh-TW":["行政費用"],"en":["costs associated with the general management and administration of a company"]}', NULL, 'reduce administrative expenses / administrative expense ratio', '[{"en":"Administrative expenses were cut by consolidating back-office functions.","zh-TW":"通過整合後台職能降低了行政費用。"},{"en":"Administrative expenses include salaries of management and office overhead.","zh-TW":"行政費用包括管理人員薪資和辦公室間接費用。"}]', NULL, NULL, 5, 138, NULL),
(139, 'administrative overhead', '/ədˈmɪnɪstrətɪv ˈoʊvərhed/', 'noun', '{"zh-TW":["行政間接費用"],"en":["indirect costs related to managing and running an organization"]}', NULL, 'reduce administrative overhead / administrative overhead costs', '[{"en":"Reducing administrative overhead was a key part of the cost-cutting plan.","zh-TW":"降低行政間接費用是削減成本計劃的重要組成部分。"},{"en":"Administrative overhead includes HR, finance, and legal department costs.","zh-TW":"行政間接費用包括人力資源、財務和法務部門的成本。"}]', NULL, NULL, 5, 139, NULL),
(140, 'admire', '/ədˈmaɪər/', 'verb', '{"zh-TW":["欽佩；讚賞"],"en":["to regard with respect or warm approval"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"mire","meaning":"wonder (驚嘆)"},"logic":"朝向某事物驚嘆，即「欽佩」。"}', 'admire someone for / greatly admire', '[{"en":"I admire her courage and determination.","zh-TW":"我欽佩她的勇氣和決心。"},{"en":"Everyone admires his dedication to work.","zh-TW":"每個人都讚賞他對工作的奉獻。"}]', '{"noun":"admiration","adjective":"admirable","noun2":"admirer"}', NULL, 2, 140, NULL),
(141, 'admissibility', '/ədˌmɪsəˈbɪlɪti/', 'noun', '{"zh-TW":["可採納性；可受理性"],"en":["the quality of being acceptable or valid in a court of law"]}', NULL, 'challenge admissibility / admissibility of evidence / rule on admissibility', '[{"en":"The judge ruled on the admissibility of the digital evidence.","zh-TW":"法官就數字證據的可採納性作出裁定。"},{"en":"Admissibility of evidence is governed by strict procedural rules.","zh-TW":"證據的可採納性受嚴格的程序規則約束。"}]', '{"adjective":"admissible","antonym":"inadmissible"}', NULL, 5, 141, NULL),
(142, 'admission', '/ədˈmɪʃn/', 'noun', '{"zh-TW":["入場；入學","承認"],"en":["the process of being allowed to enter","a confession that something is true"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"miss","meaning":"send (送)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"被送入的動作，即「入場」。"}', 'admission fee/requirements/process', '[{"en":"Admission to the conference is free for members.","zh-TW":"會員可免費參加會議。"},{"en":"The admission requirements include a bachelor''s degree.","zh-TW":"入學要求包括學士學位。"}]', '{"verb":"admit"}', NULL, 3, 142, 253),
(143, 'admit', '/ədˈmɪt/', 'verb', '{"zh-TW":["承認；准許進入"],"en":["to agree something is true unwillingly","to agree that something is true; to allow to enter"]}', NULL, 'admit to / be admitted to; admit to + V-ing / be admitted to', '[{"en":"He admitted making a mistake.","zh-TW":"他承認犯了錯。"},{"en":"She was admitted to the hospital.","zh-TW":"她被送進了醫院。"},{"en":"He admitted making a mistake.","zh-TW":"他承認犯了一個錯誤。"}]', '{"noun":"admission","adjective":"admissible"}', NULL, 2, 143, NULL),
(144, 'adopt', '/əˈdɒpt/', 'verb', '{"zh-TW":["採用；採納","收養","採用；收養"],"en":["to start using a new method or idea","to legally take another''s child","to take up or start to use"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"opt","meaning":"choose (選擇)"},"logic":"朝向選擇，即「採用」。"}', 'adopt a policy/strategy/approach; adopt a policy / adopt a child', '[{"en":"The company adopted a new remote work policy.","zh-TW":"公司採用了新的遠端工作政策。"},{"en":"Several countries have adopted similar regulations.","zh-TW":"幾個國家已採用了類似法規。"},{"en":"The company adopted a new marketing strategy.","zh-TW":"公司採用了新的行銷策略。"},{"en":"They decided to adopt a child.","zh-TW":"他們決定領養一個孩子。"}]', '{"noun":"adoption","adjective":"adopted"}', NULL, 2, 144, 254),
(145, 'advance', '/ədˈvɑːns/', 'verb', '{"zh-TW":["推進；前進","預付","前進；推進"],"en":["to move forward or make progress","to pay money before it is due","to move forward","to make progress"]}', '{"prefix":{"text":"ad-","meaning":"forward (向前)"},"root":{"text":"vance","meaning":"go (走)"},"logic":"向前走，即「推進」。"}', 'advance knowledge/career/payment; advance in career / advance payment / in advance', '[{"en":"Technology continues to advance at a rapid pace.","zh-TW":"技術持續快速進步。"},{"en":"Can you advance me next month''s salary?","zh-TW":"你可以預付我下個月的薪水嗎？"},{"en":"Technology continues to advance rapidly.","zh-TW":"科技持續快速進步。"},{"en":"Please pay in advance.","zh-TW":"請預先付款。"}]', '{"noun":"advancement","adjective":"advanced"}', NULL, 3, 145, 70),
(146, 'advance notice', '/ədˈvɑːns ˈnoʊtɪs/', 'noun', '{"zh-TW":["提前通知"],"en":["notification given ahead of a required action or event"]}', NULL, 'provide advance notice / advance notice requirement', '[{"en":"The contract requires 60 days advance notice for termination.","zh-TW":"合約要求提前60天通知終止。"},{"en":"Employees must give advance notice before taking extended leave.","zh-TW":"員工在請長假前必須提前通知。"}]', NULL, NULL, 5, 146, NULL),
(147, 'advance payment', '/ədˈvɑːns ˈpeɪmənt/', 'noun', '{"zh-TW":["預付款；訂金"],"en":["payment made before goods or services are delivered"]}', NULL, 'require advance payment / advance payment terms', '[{"en":"A 30% advance payment is required before production begins.","zh-TW":"生產開始前需要支付30%的預付款。"},{"en":"The client made an advance payment to secure the delivery slot.","zh-TW":"客戶提前付款以確保交貨時間槽。"}]', NULL, NULL, 5, 147, NULL),
(148, 'advance payment guarantee', '/ədˈvɑːns ˈpeɪmənt ˌɡærənˈtiː/', 'noun', '{"zh-TW":["預付款保函"],"en":["a guarantee ensuring advance payments are returned if a contract is not fulfilled"]}', NULL, 'issue an advance payment guarantee / advance payment guarantee terms', '[{"en":"The contractor provided an advance payment guarantee to the client.","zh-TW":"承包商向客戶提供了預付款保函。"},{"en":"An advance payment guarantee protects the buyer''s initial investment.","zh-TW":"預付款保函保護了買方的初始投資。"}]', NULL, NULL, 5, 148, NULL),
(149, 'advantage', '/ədˈvɑːntɪdʒ/', 'noun', '{"zh-TW":["優勢；利益"],"en":["a condition giving a greater chance of success"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vant","meaning":"before (在前)"},"suffix":{"text":"-age","meaning":"state (狀態)"},"logic":"在前面的狀態，即「優勢」。"}', 'competitive advantage / take advantage of', '[{"en":"Our competitive advantage lies in customer service.","zh-TW":"我們的競爭優勢在於客戶服務。"},{"en":"Take advantage of the early-bird discount.","zh-TW":"把握早鳥折扣的機會。"}]', '{"adjective":"advantageous"}', NULL, 3, 149, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(150, 'adventure tourism', '/''ədˈventʃər ˌtʊərɪzəm/', 'noun', '{"zh-TW":["冒險旅遊"],"en":["tourism involving activities that require physical exertion, such as hiking, skydiving, or rafting"]}', NULL, 'promote adventure tourism / adventure tourism operator / extreme adventure tourism', '[{"en":"Adventure tourism has grown rapidly as travelers seek more thrilling experiences.","zh-TW":"隨著旅行者尋求更刺激的體驗，冒險旅遊迅速增長。"},{"en":"The region is a popular destination for adventure tourism, offering rafting and climbing.","zh-TW":"該地區是冒險旅遊的熱門目的地，提供漂流和攀岩活動。"}]', NULL, NULL, 5, 150, NULL),
(151, 'adversarial', '/ˌædvɜːˈseəriəl/', 'adjective', '{"zh-TW":["對抗性的；敵對的"],"en":["involving opposition or conflict between two parties"]}', NULL, 'adversarial relationship / adversarial process / adversarial system', '[{"en":"Adversarial legal proceedings pit opposing lawyers against each other.","zh-TW":"對抗性法律程序使對立雙方律師相互較量。"},{"en":"The adversarial relationship between management and unions hurt productivity.","zh-TW":"管理層與工會之間的對抗性關係損害了生產力。"}]', '{"adverb":"adversarially","noun":"adversary"}', NULL, 4, 151, NULL),
(152, 'adverse', '/ˈædvɜːrs/', 'adjective', '{"zh-TW":["不利的；有害的"],"en":["preventing success or development; harmful"]}', NULL, 'adverse conditions / adverse effect / adverse reaction', '[{"en":"Adverse weather conditions delayed the shipment by three days.","zh-TW":"惡劣的天氣條件使貨物延誤了三天。"},{"en":"The price increase had an adverse effect on sales volume.","zh-TW":"價格上漲對銷售量產生了不利影響。"}]', '{"adverb":"adversely","noun":"adversity"}', NULL, 3, 152, NULL),
(153, 'adverse conditions', '/ədˈvɜːrs kənˈdɪʃənz/', 'noun', '{"zh-TW":["不利條件；惡劣條件"],"en":["circumstances that are negative or harmful to business operations"]}', NULL, 'face adverse conditions / operate under adverse conditions', '[{"en":"Sales declined due to adverse market conditions during the quarter.","zh-TW":"由於本季度不利的市場條件，銷售額下降了。"},{"en":"The company showed resilience in the face of adverse economic conditions.","zh-TW":"公司在面對不利的經濟條件時表現出了韌性。"}]', '{"adjective":"adverse"}', NULL, 5, 153, NULL),
(154, 'adverse event', '/ˈædvɜːrs ɪˈvent/', 'noun', '{"zh-TW":["不良事件"],"en":["an unwanted incident in a clinical trial or medical treatment"]}', NULL, 'report an adverse event / serious adverse event / adverse event monitoring', '[{"en":"The clinical trial was paused following several serious adverse events.","zh-TW":"在幾起嚴重不良事件之後，臨床試驗暫停了。"},{"en":"Healthcare workers must document all adverse events for regulatory review.","zh-TW":"醫療工作者必須記錄所有不良事件以供監管審查。"}]', NULL, NULL, 5, 154, NULL),
(155, 'adverse reaction', '/ˈædvɜːrs riˈækʃən/', 'noun', '{"zh-TW":["不良反應；副作用"],"en":["an unintended harmful response to a drug or treatment"]}', NULL, 'report an adverse reaction / adverse drug reaction / monitor for adverse reactions', '[{"en":"The patient reported an adverse reaction to the new medication.","zh-TW":"患者報告了對新藥物的不良反應。"},{"en":"Clinical trials closely monitor adverse reactions to ensure patient safety.","zh-TW":"臨床試驗密切監測不良反應以確保患者安全。"}]', NULL, NULL, 5, 155, NULL),
(156, 'adverse selection', '/ˈædvɜːrs sɪˈlekʃən/', 'noun', '{"zh-TW":["逆向選擇"],"en":["a market process in which undesired results occur when buyers and sellers have asymmetric information"]}', NULL, 'problem of adverse selection / adverse selection in insurance / reduce adverse selection', '[{"en":"Adverse selection in health insurance occurs when sicker people are more likely to buy coverage.","zh-TW":"健康保險中的逆向選擇發生在病情較重的人更有可能購買保障的情況下。"},{"en":"Mandatory insurance requirements reduce adverse selection by including healthy individuals.","zh-TW":"強制保險要求通過納入健康個體來減少逆向選擇。"}]', NULL, NULL, 5, 156, NULL),
(157, 'advertise', '/ˈædvətaɪz/', 'verb', '{"zh-TW":["做廣告；宣傳"],"en":["to describe a product in media to promote sales"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vert","meaning":"turn (轉向)"},"suffix":{"text":"-ise","meaning":"to make (使)"},"logic":"使人轉向注意，即「做廣告」。"}', 'advertise a product/position/service', '[{"en":"The company advertises heavily on social media.","zh-TW":"公司在社群媒體上大量做廣告。"},{"en":"The position was advertised in major newspapers.","zh-TW":"該職位在主要報紙上刊登廣告。"}]', '{"noun":"advertisement","noun2":"advertiser"}', NULL, 3, 157, 819),
(158, 'advertisement', '/ədˈvɜːrtɪsmənt/', 'noun', '{"zh-TW":["廣告"],"en":["a notice or announcement promoting a product or service"]}', NULL, 'run an advertisement / television advertisement', '[{"en":"The advertisement campaign reached millions of viewers.","zh-TW":"廣告活動觸達了數百萬觀眾。"},{"en":"She designed an eye-catching advertisement for the new product.","zh-TW":"她為新產品設計了引人注目的廣告。"}]', '{"verb":"advertise","noun":"advertiser","adjective":"advertised"}', NULL, 5, 158, NULL),
(159, 'advertising budget', '/ˈædvətaɪzɪŋ ˈbʌdʒɪt/', 'noun', '{"zh-TW":["廣告預算"],"en":["the amount of money allocated for advertising and promotional activities"]}', NULL, 'set an advertising budget / advertising budget allocation', '[{"en":"The advertising budget was increased by 25% to support the product launch.","zh-TW":"廣告預算增加了25%以支持產品發布。"},{"en":"A well-managed advertising budget maximizes return on marketing spend.","zh-TW":"管理良好的廣告預算最大化了行銷支出的回報。"}]', NULL, NULL, 5, 159, NULL),
(160, 'advice', 'ədˈvaɪs', 'noun', '{"zh-TW":["建議；忠告","意見"],"en":["recommendation about what to do","guidance"]}', NULL, 'seek advice/give advice', '[{"en":"She sought advice from a specialist.","zh-TW":"她向專家尋求建議。"}]', '{"verb":"advise","adjective":"advisable","adverb":"advisably"}', NULL, 2, 160, NULL),
(161, 'advise', '/ədˈvaɪz/', 'verb', '{"zh-TW":["建議；勸告"],"en":["to give counsel or recommendations"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vise","meaning":"see (看)"},"logic":"朝向看清楚，即「建議」。"}', 'advise sb to do / advise against', '[{"en":"I would advise you to review the contract carefully.","zh-TW":"我建議你仔細審閱合約。"},{"en":"The consultant advised against the merger.","zh-TW":"顧問建議不要進行合併。"}]', '{"noun":"advice","noun2":"adviser","adjective":"advisable"}', NULL, 2, 161, NULL),
(162, 'advisory', '/ədˈvaɪzəri/', 'adjective', '{"zh-TW":["顧問的；諮詢的"],"en":["having the function of giving advice but not making decisions"]}', NULL, 'advisory role / advisory board / advisory committee', '[{"en":"She serves in an advisory role to the board of directors.","zh-TW":"她擔任董事會的顧問角色。"},{"en":"The advisory committee recommended reducing operational costs.","zh-TW":"諮詢委員會建議降低運營成本。"}]', '{"noun":"adviser","verb":"advise"}', NULL, 3, 162, 953),
(163, 'advisory board', '/ədˈvaɪzəri bɔːrd/', 'noun', '{"zh-TW":["顧問委員會"],"en":["a group of external advisors providing non-binding strategic guidance"]}', NULL, 'form an advisory board / advisory board member / advisory board meeting', '[{"en":"The startup assembled an advisory board of industry veterans.","zh-TW":"新創公司組建了由行業老手組成的顧問委員會。"},{"en":"The advisory board provided valuable insights on market expansion.","zh-TW":"顧問委員會提供了有關市場擴張的寶貴見解。"}]', NULL, NULL, 5, 163, NULL),
(164, 'advocate', '/ˈædvəkeɪt/', 'verb', '{"zh-TW":["提倡；擁護"],"en":["to publicly support or recommend a cause"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"voc","meaning":"call (呼叫)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"朝向呼叫支持，即「提倡」。"}', 'advocate for change/reform/rights', '[{"en":"She advocates for better working conditions.","zh-TW":"她提倡更好的工作條件。"},{"en":"Many experts advocate a gradual approach.","zh-TW":"許多專家提倡循序漸進的方式。"}]', '{"noun":"advocacy"}', NULL, 3, 164, 640),
(165, 'aerobic', '/''eəˈrəʊbɪk/', 'adjective', '{"zh-TW":["有氧的；需氧的"],"en":["relating to or denoting exercise that improves the efficiency of the body''s cardiovascular system"]}', NULL, 'aerobic exercise / aerobic capacity / aerobic fitness', '[{"en":"Jogging, swimming, and cycling are popular forms of aerobic exercise.","zh-TW":"慢跑、游泳和騎自行車是常見的有氧運動形式。"},{"en":"Improving your aerobic capacity allows you to exercise for longer periods without fatigue.","zh-TW":"提高有氧能力可讓你在不感到疲勞的情況下鍛煉更長時間。"}]', '{"noun":"aerobics"}', NULL, 3, 165, NULL),
(166, 'aerobic exercise', '/''eəˌrəʊbɪk ˈeksərsaɪz/', 'noun', '{"zh-TW":["有氧運動"],"en":["physical activity that increases the heart rate and breathing, improving cardiovascular fitness"]}', NULL, 'do aerobic exercise / regular aerobic exercise / aerobic exercise routine', '[{"en":"Thirty minutes of aerobic exercise daily significantly reduces the risk of heart disease.","zh-TW":"每天三十分鐘的有氧運動可顯著降低患心臟病的風險。"},{"en":"Walking, swimming, and cycling are all popular forms of aerobic exercise.","zh-TW":"步行、游泳和騎自行車都是受歡迎的有氧運動形式。"}]', '{"adjective":"aerobic"}', NULL, 5, 166, NULL),
(167, 'aesthetic', '/iːsˈθetɪk/', 'noun', '{"zh-TW":["美感；美學"],"en":["a set of principles underlying a work of art; visual style"]}', NULL, 'visual aesthetic / distinctive aesthetic / minimalist aesthetic', '[{"en":"The photographer developed a distinctive aesthetic centered on light and shadow.","zh-TW":"攝影師發展出一種以光影為中心的獨特美學。"},{"en":"The brand''s aesthetic appeals to young urban consumers.","zh-TW":"該品牌的美感吸引年輕的都市消費者。"}]', '{"adjective":"aesthetic","adverb":"aesthetically"}', NULL, 3, 167, NULL),
(168, 'affect', '/əˈfekt/', 'verb', '{"zh-TW":["【主要意義-動詞】影響；對……有影響","【次要意義-名詞（心理學）】情感；感情；情緒狀態","【次要意義-動詞（正式）】假裝；裝出（某種態度）"],"en":["[primary - verb] to have an effect or influence on something","[secondary - noun (psychology)] an emotion or feeling as a component of behavior","[secondary - verb] to pretend or assume something falsely"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fect","meaning":"do/make (做)"},"logic":"朝向作用，即「影響」。"}', 'affect the outcome / affect sales / flat affect / affected speech', '[{"en":"The sudden change in policy will affect all existing contract holders.","zh-TW":"政策的突然改變將影響所有現有合約持有人。"},{"en":"The patient showed signs of flat affect following the treatment.","zh-TW":"患者在治療後表現出情感平淡的跡象。"},{"en":"His affected manner of speaking annoyed some of his colleagues.","zh-TW":"他做作的說話方式令一些同事感到惱火。"}]', '{"noun":"effect (different word!)","adjective":"affected, affective"}', 'affect（動詞）= 「影響」，與 effect（名詞/動詞）區別是 TOEIC 必考文法點；名詞 affect（心理學術語 = 情感）較少見但出現在醫療文章中，affected（adj.）= 「裝出來的/做作的」。', 2, 168, 255),
(169, 'affection', '/əˈfekʃn/', 'noun', '{"zh-TW":["情感；喜愛"],"en":["a gentle feeling of fondness or love"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fect","meaning":"do/make (做)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"對某人產生感情的狀態。"}', 'show affection / deep affection', '[{"en":"She showed great affection for her grandchildren.","zh-TW":"她對孫子們表現出極大的喜愛。"},{"en":"He has a deep affection for his hometown.","zh-TW":"他對故鄉有深厚的感情。"}]', '{"adjective":"affectionate"}', NULL, 3, 169, NULL),
(170, 'affidavit', '/ˌæfɪˈdeɪvɪt/', 'noun', '{"zh-TW":["宣誓書；書面陳述"],"en":["a written statement confirmed by oath"]}', NULL, 'sign an affidavit / sworn affidavit', '[{"en":"The witness signed an affidavit confirming the events.","zh-TW":"證人簽署了確認事件的宣誓書。"},{"en":"Submit an affidavit along with your application.","zh-TW":"請隨申請書一併提交宣誓書。"}]', NULL, NULL, 3, 170, NULL),
(171, 'affiliate', '/əˈfɪlieɪt/', 'verb', '{"zh-TW":["使隸屬；使加入","附屬機構"],"en":["to officially attach or connect to an organization"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fili","meaning":"son (子)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使成為兒子般的關係，即「隸屬」。"}', 'affiliate with / affiliated company', '[{"en":"The institute is affiliated with a major university.","zh-TW":"該研究所隸屬於一所主要大學。"},{"en":"Our affiliate offices handle regional operations.","zh-TW":"我們的附屬辦公室處理區域業務。"}]', '{"noun":"affiliation"}', NULL, 3, 171, 978),
(172, 'affiliate marketing', '/əˈfɪliət ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["聯盟行銷；分潤行銷"],"en":["earning commissions by promoting other companies'' products or services"]}', NULL, 'affiliate marketing program / join an affiliate program / affiliate marketing revenue', '[{"en":"The company generated 20% of sales through affiliate marketing.","zh-TW":"公司通過聯盟行銷產生了20%的銷售額。"},{"en":"Affiliate marketing is a cost-effective way to expand reach.","zh-TW":"聯盟行銷是擴大覆蓋範圍的具成本效益方式。"}]', '{"noun":"affiliate marketer"}', NULL, 5, 172, NULL),
(173, 'affiliation', '/əˌfɪliˈeɪʃən/', 'noun', '{"zh-TW":["聯繫；附屬關係"],"en":["the state of being affiliated with or connected to an organization"]}', NULL, 'professional affiliation / affiliation agreement', '[{"en":"She listed all her professional affiliations on the form.","zh-TW":"她在表格上列出了所有專業聯繫。"},{"en":"The two companies formalized their affiliation agreement.","zh-TW":"兩家公司正式簽署了附屬關係協議。"}]', '{"verb":"affiliate","adjective":"affiliated"}', NULL, 4, 173, 497),
(174, 'affinity', '/əˈfɪnɪti/', 'noun', '{"zh-TW":["親和力；共鳴"],"en":["a natural liking for and understanding of someone or something"]}', NULL, 'brand affinity / cultural affinity / affinity group', '[{"en":"Brands with strong consumer affinity outperform during market downturns.","zh-TW":"具有強烈消費者親和力的品牌在市場下行期間表現較好。"},{"en":"Cultural affinity between trading partners facilitates business relationships.","zh-TW":"貿易夥伴之間的文化親和力促進了商業關係。"}]', NULL, NULL, 3, 174, NULL),
(175, 'affirmative action', '/əˈfɜːrmətɪv ˈækʃən/', 'noun', '{"zh-TW":["積極差別待遇；平權行動"],"en":["policies promoting opportunities for underrepresented groups"]}', NULL, 'affirmative action policy / affirmative action program', '[{"en":"Affirmative action policies increased diversity in the workforce.","zh-TW":"積極差別待遇政策增加了勞動力的多元性。"},{"en":"The company adopted affirmative action measures in its hiring process.","zh-TW":"公司在招聘流程中採用了積極差別待遇措施。"}]', NULL, NULL, 5, 175, NULL),
(176, 'afford', '/əˈfɔːrd/', 'verb', '{"zh-TW":["負擔得起","提供"],"en":["to have enough money to pay for","to provide or supply"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"ford","meaning":"further (推進)"},"logic":"朝向推進足夠的，即「負擔得起」。"}', 'afford to buy/pay / can''t afford', '[{"en":"The company cannot afford to lose any more clients.","zh-TW":"公司承受不起再失去任何客戶。"},{"en":"The new location affords a beautiful view.","zh-TW":"新地點提供了美麗的景觀。"}]', '{"adjective":"affordable"}', NULL, 2, 176, 256),
(177, 'affordability', '/əˌfɔːrdəˈbɪlɪti/', 'noun', '{"zh-TW":["可負擔性"],"en":["the quality of being reasonably priced and within financial reach"]}', NULL, 'housing affordability / healthcare affordability / improve affordability', '[{"en":"Housing affordability has declined significantly in major cities.","zh-TW":"主要城市的住房可負擔性顯著下降。"},{"en":"Policy measures must address the affordability of essential medicines.","zh-TW":"政策措施必須解決基本藥物的可負擔性問題。"}]', '{"adjective":"affordable","adverb":"affordably"}', NULL, 5, 177, NULL),
(178, 'affordable', '/əˈfɔːrdəbl/', 'adjective', '{"zh-TW":["負擔得起的"],"en":["inexpensive enough for most people"]}', '{"root":{"text":"afford","meaning":"provide (提供)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠負擔的。"}', 'affordable housing / affordable price', '[{"en":"We need more affordable housing in the city.","zh-TW":"我們城市需要更多平價住宅。"},{"en":"The restaurant offers good food at affordable prices.","zh-TW":"這家餐廳以實惠的價格提供美食。"}]', '{"verb":"afford"}', NULL, 4, 178, 820),
(179, 'afforestation', '/əˌfɒrɪˈsteɪʃən/', 'noun', '{"zh-TW":["造林；植樹造林"],"en":["the process of planting trees in an area where there was no previous forest"]}', NULL, 'afforestation program / national afforestation drive / afforestation project', '[{"en":"Afforestation programs can absorb carbon and restore degraded land.","zh-TW":"造林計畫可以吸收碳並恢復退化土地。"},{"en":"The government committed to afforestation of one million hectares by 2030.","zh-TW":"政府承諾到2030年造林一百萬公頃。"}]', '{"verb":"afforest","antonym":"deforestation"}', NULL, 5, 179, NULL),
(180, 'afraid', '/əˈfreɪd/', 'adjective', '{"zh-TW":["害怕的；恐怕","害怕的；擔心的"],"en":["feeling fear or anxiety","feeling fear; worried about something"]}', NULL, 'afraid of / I''m afraid; be afraid of / I''m afraid (that)...', '[{"en":"She is afraid of spiders.","zh-TW":"她怕蜘蛛。"},{"en":"I''m afraid I can''t help.","zh-TW":"恐怕我幫不了你。"},{"en":"I''m afraid we''re sold out.","zh-TW":"恐怕我們賣完了。"}]', NULL, NULL, 2, 180, NULL),
(181, 'after-sales service', '/ˈɑːftər seɪlz ˈsɜːrvɪs/', 'noun', '{"zh-TW":["售後服務"],"en":["support provided to customers after purchasing a product"]}', NULL, 'offer after-sales service / excellent after-sales service', '[{"en":"The company is known for its excellent after-sales service.","zh-TW":"這家公司以其卓越的售後服務而聞名。"},{"en":"After-sales service includes warranty support and repairs.","zh-TW":"售後服務包括保固支援和維修。"}]', NULL, NULL, 5, 181, NULL),
(182, 'after-tax profit', '/ˌɑːftər tæks ˈprɒfɪt/', 'noun', '{"zh-TW":["稅後利潤"],"en":["the net profit remaining after all tax payments have been deducted"]}', NULL, 'report after-tax profit / increase after-tax profit', '[{"en":"After-tax profit rose by 22% due to improved cost control.","zh-TW":"由於成本控制改善，稅後利潤增長了22%。"},{"en":"Investors compare after-tax profit margins across competitors.","zh-TW":"投資者比較競爭對手之間的稅後利潤率。"}]', '{"synonym":"net profit after tax"}', NULL, 5, 182, NULL),
(183, 'afternoon', '/ˌɑːftəˈnuːn/', 'noun', '{"zh-TW":["下午"],"en":["the period between midday and evening"]}', NULL, 'in the afternoon / this afternoon', '[{"en":"The meeting is scheduled for this afternoon.","zh-TW":"會議安排在今天下午。"},{"en":"She usually takes a nap in the afternoon.","zh-TW":"她通常在下午小睡。"}]', NULL, NULL, 3, 183, NULL),
(184, 'again', '/əˈɡɛn/', 'adverb', '{"zh-TW":["再一次；又"],"en":["one more time"]}', NULL, 'once again / again and again', '[{"en":"Please try again later.","zh-TW":"請稍後再試。"},{"en":"Once again, thank you all.","zh-TW":"再次感謝大家。"}]', '{"adverb":"again"}', NULL, 2, 184, NULL),
(185, 'against', '/əˈɡɛnst/', 'preposition', '{"zh-TW":["反對；靠著"],"en":["in opposition to","leaning on"]}', NULL, 'against the rules / go against', '[{"en":"This is against company policy.","zh-TW":"這違反公司政策。"},{"en":"He leaned against the desk.","zh-TW":"他靠在書桌上。"}]', '{"preposition":"against"}', NULL, 3, 185, NULL),
(186, 'age', '/eɪdʒ/', 'noun', '{"zh-TW":["年齡；時代"],"en":["the number of years someone has lived"]}', NULL, 'at the age of / old age', '[{"en":"She started working at the age of 18.","zh-TW":"她18歲開始工作。"},{"en":"We live in the digital age.","zh-TW":"我們生活在數位時代。"}]', '{"verb":"age","adjective":"aged"}', NULL, 1, 186, NULL),
(187, 'agency relationship', '/ˈeɪdʒənsi rɪˈleɪʃənʃɪp/', 'noun', '{"zh-TW":["代理關係"],"en":["a legal relationship where one party acts on behalf of another"]}', NULL, 'establish an agency relationship / agency relationship disclosure', '[{"en":"In an agency relationship, the agent must act in the principal''s best interest.","zh-TW":"在代理關係中，代理人必須以委托人的最佳利益行事。"},{"en":"Undisclosed agency relationships may give rise to liability for the principal.","zh-TW":"未披露的代理關係可能使委托人承擔責任。"}]', NULL, NULL, 5, 187, NULL),
(188, 'agenda', '/əˈdʒendə/', 'noun', '{"zh-TW":["議程；待辦事項"],"en":["a list of items to be discussed at a meeting"]}', '{"root":{"text":"ag","meaning":"do (做)"},"suffix":{"text":"-enda","meaning":"things to be done (待做的事)"},"logic":"待做的事，即「議程」。"}', 'meeting agenda / on the agenda', '[{"en":"The first item on the agenda is the budget review.","zh-TW":"議程上的第一項是預算審查。"},{"en":"Please distribute the agenda before the meeting.","zh-TW":"請在會議前分發議程。"}]', NULL, NULL, 2, 188, 71),
(189, 'agenda item', '/əˈdʒendə ˈaɪtəm/', 'noun', '{"zh-TW":["議程項目"],"en":["a specific topic listed for discussion in a meeting"]}', NULL, 'add an agenda item / agenda item for discussion / priority agenda item', '[{"en":"The merger was added as the first agenda item for the board meeting.","zh-TW":"合併被列為董事會議的第一個議程項目。"},{"en":"All participants may suggest agenda items before the meeting.","zh-TW":"所有與會者可在會議前提議議程項目。"}]', NULL, NULL, 4, 189, NULL),
(190, 'agenda-setting', '/əˈdʒendə ˈsetɪŋ/', 'noun', '{"zh-TW":["議程設定"],"en":["the ability to determine the topics and priorities of discussion"]}', NULL, 'agenda-setting power / agenda-setting role', '[{"en":"The chairperson has agenda-setting authority in the meeting.","zh-TW":"主席在會議中擁有議程設定權力。"},{"en":"Effective agenda-setting ensures productive meetings.","zh-TW":"有效的議程設定確保高效的會議。"}]', NULL, NULL, 5, 190, NULL),
(191, 'agent of record', '/ˈeɪdʒənt əv ˈrekərd/', 'noun', '{"zh-TW":["授權代理人；備案代理人"],"en":["the officially designated representative authorized to act on a client''s behalf"]}', NULL, 'appoint an agent of record / agent of record agreement', '[{"en":"The law firm was named agent of record for the insurance policy.","zh-TW":"律師事務所被指定為保險單的授權代理人。"},{"en":"An agent of record manages all communications with the insurer.","zh-TW":"授權代理人負責管理與保險公司的所有溝通。"}]', NULL, NULL, 5, 191, NULL),
(192, 'agentic', '/eɪˈdʒentɪk/', 'adjective', '{"zh-TW":["能動的；有主體性的"],"en":["relating to a sense of personal agency or the capacity to act independently"]}', NULL, 'agentic behavior / agentic individual / agentic approach', '[{"en":"Agentic individuals are more likely to take initiative in problem-solving.","zh-TW":"有主體性的個人更可能在解決問題時採取主動。"},{"en":"The research examines agentic and communal leadership styles.","zh-TW":"研究考察了能動型和社群型領導風格。"}]', '{"noun":"agency"}', NULL, 3, 192, NULL),
(193, 'agglomeration', '/əˌɡlɒməˈreɪʃən/', 'noun', '{"zh-TW":["聚集；積聚"],"en":["a dense clustering of firms, people, or activities in a geographic area"]}', NULL, 'urban agglomeration / industrial agglomeration / agglomeration effects', '[{"en":"Silicon Valley demonstrates the benefits of industrial agglomeration.","zh-TW":"矽谷展示了工業聚集的好處。"},{"en":"Agglomeration economies arise when firms benefit from locating near each other.","zh-TW":"當企業從相互鄰近中受益時，就會出現集聚經濟。"}]', '{"adjective":"agglomerated","verb":"agglomerate"}', NULL, 5, 193, NULL),
(194, 'aggregate', '/ˈæɡrɪɡɪt/', 'adjective', '{"zh-TW":["總計的；總體的"],"en":["formed by the combination of many items"]}', NULL, 'aggregate demand / aggregate data', '[{"en":"Aggregate sales data showed a 15% increase over last year.","zh-TW":"總計銷售數據顯示比去年增長了15%。"},{"en":"The aggregate cost of the project exceeded five million dollars.","zh-TW":"項目的總成本超過了五百萬元。"}]', '{"verb":"aggregate","noun":"aggregate"}', NULL, 3, 194, 498),
(195, 'aggregate demand', '/ˈæɡrɪɡɪt dɪˈmɑːnd/', 'noun', '{"zh-TW":["總需求"],"en":["the total demand for goods and services in an economy"]}', NULL, 'boost aggregate demand / weak aggregate demand', '[{"en":"Lower interest rates can boost aggregate demand.","zh-TW":"降低利率可以提振總需求。"},{"en":"The recession caused aggregate demand to fall significantly.","zh-TW":"經濟衰退導致總需求大幅下降。"}]', NULL, NULL, 5, 195, NULL),
(196, 'aggregate supply', '/ˈæɡrɪɡɪt səˈplaɪ/', 'noun', '{"zh-TW":["總供給"],"en":["the total amount of goods and services produced in an economy at a given price level"]}', NULL, 'stimulate aggregate supply / aggregate supply constraint', '[{"en":"Supply-side reforms aim to increase aggregate supply by reducing production costs.","zh-TW":"供給側改革旨在通過降低生產成本來增加總供給。"},{"en":"Aggregate supply fell after a severe drought damaged agricultural output.","zh-TW":"嚴重乾旱損壞農業產出後，總供給下降了。"}]', NULL, NULL, 5, 196, NULL),
(197, 'aggressive', '/əˈɡresɪv/', 'adjective', '{"zh-TW":["積極進取的","侵略的","侵略性的；積極進取的"],"en":["pursuing goals forcefully","hostile or violent"]}', '{"prefix":{"text":"ag-","meaning":"toward (朝向)"},"root":{"text":"gress","meaning":"step (踏步)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"朝向踏步的，即「積極進取的」。"}', 'aggressive strategy/marketing/growth; aggressive behavior / aggressive marketing', '[{"en":"The firm adopted an aggressive expansion strategy.","zh-TW":"該公司採用了積極的擴張策略。"},{"en":"Aggressive marketing helped boost brand awareness.","zh-TW":"積極的行銷幫助提升了品牌知名度。"},{"en":"The dog became aggressive toward strangers.","zh-TW":"這隻狗對陌生人變得有攻擊性。"},{"en":"The company adopted an aggressive marketing strategy.","zh-TW":"公司採取了積極的行銷策略。"}]', '{"noun":"aggression","adverb":"aggressively"}', NULL, 4, 197, 821),
(198, 'agile', '/ˈædʒaɪl/', 'adjective', '{"zh-TW":["敏捷的；靈活的"],"en":["able to move quickly and easily; using agile development methods"]}', NULL, 'agile team / agile approach / agile development / agile mindset', '[{"en":"The agile team delivered new features every two weeks.","zh-TW":"敏捷團隊每兩週交付新功能。"},{"en":"Staying agile allows the company to respond quickly to market changes.","zh-TW":"保持敏捷使公司能夠快速響應市場變化。"}]', '{"noun":"agility","adverb":"agilely"}', NULL, 2, 198, 822),
(199, 'agile development', '/ˈædʒaɪl dɪˈveləpmənt/', 'noun', '{"zh-TW":["敏捷開發"],"en":["an iterative approach to software development emphasizing flexibility"]}', NULL, 'adopt agile development / agile development process / agile development methodology', '[{"en":"Agile development enables teams to respond quickly to changing requirements.","zh-TW":"敏捷開發使團隊能夠快速回應不斷變化的需求。"},{"en":"The company transitioned from waterfall to agile development practices.","zh-TW":"公司從瀑布式轉型為敏捷開發實踐。"}]', NULL, NULL, 5, 199, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(200, 'agile methodology', '/ˈædʒaɪl meθəˈdɒlədʒi/', 'noun', '{"zh-TW":["敏捷方法論"],"en":["an iterative approach to project management and development"]}', NULL, 'adopt agile methodology / agile methodology framework', '[{"en":"The team adopted agile methodology to speed up delivery.","zh-TW":"團隊採用敏捷方法論加快交付速度。"},{"en":"Agile methodology encourages continuous feedback and adaptation.","zh-TW":"敏捷方法論鼓勵持續反饋和適應。"}]', '{"adjective":"agile"}', NULL, 5, 200, NULL),
(201, 'agrarian', '/əˈɡreəriən/', 'adjective', '{"zh-TW":["農業的；農耕的"],"en":["relating to land, especially agricultural land or its tenure"]}', NULL, 'agrarian society / agrarian reform / agrarian economy', '[{"en":"Agrarian reforms redistributed land to poor farmers in the region.","zh-TW":"土地改革將土地重新分配給該地區的貧農。"},{"en":"The country''s transition from an agrarian to an industrial economy was rapid.","zh-TW":"這個國家從農業到工業經濟的轉型是迅速的。"}]', '{"noun":"agrarianism"}', NULL, 3, 201, NULL),
(202, 'agree', '/əˈɡriː/', 'verb', '{"zh-TW":["同意；贊成","同意；一致"],"en":["to have the same opinion; to consent","to have the same opinion","to have the same opinion; to say yes"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"gree","meaning":"pleasing (令人滿意)"},"logic":"朝向令人滿意，即「同意」。"}', 'agree on/to/with / agree to terms; agree with / agree on; agree with sb / agree to do sth / agree on sth', '[{"en":"Both parties agreed to the terms of the contract.","zh-TW":"雙方同意了合約條款。"},{"en":"I agree with your assessment of the situation.","zh-TW":"我同意你對情況的評估。"},{"en":"I agree with your suggestion.","zh-TW":"我同意你的建議。"},{"en":"They agreed on a price.","zh-TW":"他們就價格達成了一致。"},{"en":"They agreed to postpone the meeting.","zh-TW":"他們同意延後會議。"}]', '{"noun":"agreement","adjective":"agreeable"}', NULL, 2, 202, NULL),
(203, 'agreed terms', '/əˈɡriːd tɜːrmz/', 'noun', '{"zh-TW":["商定條款"],"en":["the conditions that all parties to an agreement have consented to"]}', NULL, 'finalize agreed terms / operate under agreed terms', '[{"en":"The deal was completed on agreed terms satisfactory to both parties.","zh-TW":"交易在雙方滿意的商定條款下完成了。"},{"en":"Any deviation from agreed terms must be documented in writing.","zh-TW":"對商定條款的任何偏差都必須以書面形式記錄。"}]', NULL, NULL, 4, 203, NULL),
(204, 'agreement', '/əˈɡriːmənt/', 'noun', '{"zh-TW":["協議；合約"],"en":["a formal arrangement between parties"]}', NULL, 'sign an agreement / reach an agreement', '[{"en":"Both parties signed the agreement last Monday.","zh-TW":"雙方上週一簽署了協議。"},{"en":"The terms of the agreement must be met by both sides.","zh-TW":"協議條款必須由雙方遵守。"}]', '{"verb":"agree","adjective":"agreed"}', NULL, 3, 204, 72),
(205, 'agriculture', '/ˈæɡrɪkʌltʃər/', 'noun', '{"zh-TW":["農業"],"en":["the science or practice of farming"]}', '{"root":{"text":"agri","meaning":"field (田地)"},"suffix":{"text":"culture","meaning":"cultivation (耕作)"},"logic":"耕作田地，即「農業」。"}', 'agriculture industry / sustainable agriculture', '[{"en":"Agriculture is the main industry in this region.","zh-TW":"農業是這個地區的主要產業。"},{"en":"Modern agriculture relies heavily on technology.","zh-TW":"現代農業高度依賴技術。"}]', '{"adjective":"agricultural"}', NULL, 4, 205, NULL),
(206, 'agrobiodiversity', '/ˌæɡrəʊˌbaɪəʊdaɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["農業生物多樣性"],"en":["the variety of plants, animals, and microorganisms used in agriculture"]}', NULL, 'protect agrobiodiversity / loss of agrobiodiversity / agrobiodiversity conservation', '[{"en":"Preserving agrobiodiversity strengthens food system resilience.","zh-TW":"保護農業生物多樣性增強了食物系統的韌性。"},{"en":"Monoculture farming reduces agrobiodiversity and increases crop vulnerability.","zh-TW":"單一作物農業降低了農業生物多樣性並增加了作物脆弱性。"}]', NULL, NULL, 5, 206, NULL),
(207, 'ahead', '/əˈhɛd/', 'adverb', '{"zh-TW":["在前面；提前"],"en":["in front; in advance"]}', NULL, 'go ahead / ahead of time', '[{"en":"Go ahead, I''ll catch up.","zh-TW":"你先走，我趕上。"},{"en":"We finished ahead of schedule.","zh-TW":"我們提前完成了。"}]', NULL, NULL, 2, 207, NULL),
(208, 'aid', '/eɪd/', 'noun', '{"zh-TW":["援助；幫助"],"en":["help or support","financial or material assistance"]}', '{"root":{"text":"aid","meaning":"help (幫助)"},"logic":"直接表示「援助」。"}', 'financial aid / first aid / in aid of', '[{"en":"The government provided aid to flood victims.","zh-TW":"政府向洪災受害者提供援助。"},{"en":"Visual aids can enhance presentations.","zh-TW":"視覺輔助工具可以增強簡報效果。"}]', NULL, NULL, 1, 208, NULL),
(209, 'aim', '/eɪm/', 'verb', '{"zh-TW":["目標；瞄準","旨在"],"en":["to intend or plan","to point or direct toward a target"]}', '{"root":{"text":"aim","meaning":"estimate/direct (估算/指向)"},"logic":"指向某處，即「瞄準、旨在」。"}', 'aim to do / aim at / aim for', '[{"en":"We aim to increase revenue by 20% this year.","zh-TW":"我們的目標是今年營收增長20%。"},{"en":"The campaign is aimed at young professionals.","zh-TW":"該活動針對年輕專業人士。"}]', NULL, NULL, 1, 209, NULL),
(210, 'air', '/ɛr/', 'noun', '{"zh-TW":["【主要意義-名詞】空氣；空中","【次要意義-動詞】播出；播映（節目）","【次要意義-動詞】通風；晾曬","【次要意義-動詞】表達（意見/不滿）","【次要意義-名詞】神態；樣子"],"en":["[primary - noun] the invisible mixture of gases around us","[secondary - verb] to broadcast on radio or television","[secondary - verb] to ventilate a room or dry clothes in the open air","[secondary - verb] to express an opinion or grievance openly"]}', NULL, 'air a grievance / air a program / air time / on air / put on airs', '[{"en":"The documentary will be aired on the national broadcaster next week.","zh-TW":"這部紀錄片將於下週在國家廣播機構播出。"},{"en":"Employees were given the opportunity to air their grievances at the town hall.","zh-TW":"員工在員工大會上獲得了表達不滿的機會。"},{"en":"The show will go on air live at 9 PM tonight.","zh-TW":"該節目將於今晚9點進行現場直播。"}]', '{"noun":"airway, airing","adjective":"on-air"}', 'air 作動詞：air a program（播出節目）、air a grievance（表達不滿）均是 TOEIC 媒體和職場文章的高頻用法，on air（播出中）、airtime（播出時間）也常見。', 1, 210, NULL),
(211, 'air freight', '/ɛər freɪt/', 'noun', '{"zh-TW":["空運貨物"],"en":["goods transported by air"]}', NULL, 'ship by air freight / air freight cost', '[{"en":"Air freight is used for urgent or perishable shipments.","zh-TW":"空運用於緊急或易腐貨物的運輸。"},{"en":"The air freight cost was higher than anticipated.","zh-TW":"空運成本高於預期。"}]', NULL, NULL, 4, 211, NULL),
(212, 'air quality', '/ɛər ˈkwɒlɪti/', 'noun', '{"zh-TW":["空氣品質"],"en":["the condition of the air in terms of pollutants"]}', NULL, 'monitor air quality / poor air quality', '[{"en":"Poor air quality can cause respiratory problems.","zh-TW":"空氣品質差可能導致呼吸系統問題。"},{"en":"The city has installed sensors to monitor air quality.","zh-TW":"市政府安裝了感測器來監測空氣品質。"}]', NULL, NULL, 4, 212, NULL),
(213, 'aircraft', '/ˈɛərkræft/', 'noun', '{"zh-TW":["飛機；航空器"],"en":["a vehicle able to fly"]}', NULL, 'commercial aircraft / military aircraft', '[{"en":"The aircraft landed safely despite the storm.","zh-TW":"飛機在暴風雨中安全降落。"},{"en":"Modern aircraft use advanced navigation systems.","zh-TW":"現代飛機使用先進的導航系統。"}]', '{"adjective":"airborne"}', NULL, 3, 213, NULL),
(214, 'airline', '/ˈɛərlaɪn/', 'noun', '{"zh-TW":["航空公司"],"en":["a company providing air transport services"]}', NULL, 'major airline / budget airline', '[{"en":"The airline offers daily flights to Tokyo.","zh-TW":"這家航空公司提供每日飛往東京的航班。"},{"en":"She booked her ticket through the airline website.","zh-TW":"她透過航空公司網站預訂機票。"}]', '{"verb":"fly","adjective":"aerial"}', NULL, 3, 214, NULL),
(215, 'airport', '/ˈɛərpɔːrt/', 'noun', '{"zh-TW":["機場"],"en":["a place where aircraft take off and land"]}', NULL, 'international airport / regional airport', '[{"en":"We arrived at the airport two hours before departure.","zh-TW":"我們在出發前兩小時抵達機場。"},{"en":"The new airport terminal opened last year.","zh-TW":"新的航站樓去年開幕。"}]', '{"verb":"depart"}', NULL, 3, 215, NULL),
(216, 'airport layover', '/''eərpɔːrt ˌleɪəʊvər/', 'noun', '{"zh-TW":["機場轉機等候；中途停留"],"en":["a period of time between flights spent at an intermediate airport"]}', NULL, 'long airport layover / use an airport layover / airport layover activities', '[{"en":"Her airport layover in Dubai was long enough to visit the city for a few hours.","zh-TW":"她在迪拜的機場轉機等候時間足夠長，可以在城市裡遊覽幾個小時。"},{"en":"She used her airport layover to relax in the lounge and catch up on work.","zh-TW":"她利用機場轉機等候時間在貴賓室休息並處理工作。"}]', '{"noun":"layover"}', NULL, 5, 216, NULL),
(217, 'airway bill', '/''eərweɪ bɪl/', 'noun', '{"zh-TW":["航空運單"],"en":["a document issued by an airline carrier which provides detailed information about a shipment sent via air freight"]}', NULL, 'issue an airway bill / airway bill number / original airway bill', '[{"en":"The airway bill serves as both a receipt and a contract for air cargo shipment.","zh-TW":"航空運單既作為空運貨物運輸的收據，也作為合同。"},{"en":"She tracked her shipment using the airway bill number provided by the carrier.","zh-TW":"她使用承運人提供的航空運單號碼追蹤她的貨物。"}]', NULL, NULL, 4, 217, NULL),
(218, 'aisle', '/aɪl/', 'noun', '{"zh-TW":["走道；通道"],"en":["a passage between rows of shelves or seats"]}', '{"root":{"text":"aisle","meaning":"passage (通道)"},"logic":"源自拉丁語 ala（翼），指建築內的側通道。"}', 'walk down the aisle / aisle seat', '[{"en":"You can find the cereal in aisle three.","zh-TW":"你可以在第三走道找到麥片。"},{"en":"She prefers an aisle seat on the plane.","zh-TW":"她偏好飛機上的走道座位。"}]', NULL, NULL, 2, 218, NULL),
(219, 'aisle seat', '/aɪl siːt/', 'noun', '{"zh-TW":["走道座位"],"en":["a seat next to the aisle in a plane"]}', NULL, 'prefer an aisle seat / request an aisle seat', '[{"en":"I always request an aisle seat for long flights.","zh-TW":"我長途飛行都要求走道座位。"},{"en":"The aisle seat gives you more legroom.","zh-TW":"走道座位給您更多腿部空間。"}]', NULL, NULL, 4, 219, NULL),
(220, 'alert', '/əˈlɜːrt/', 'adjective', '{"zh-TW":["警覺的；警報"],"en":["quick to notice and respond to danger"]}', '{"root":{"text":"alert","meaning":"on the watch (警戒)"},"logic":"源自義大利語 all''erta（在瞭望台上）。"}', 'stay alert / alert system / high alert', '[{"en":"Drivers should stay alert at all times.","zh-TW":"駕駛人應隨時保持警覺。"},{"en":"The system sends an alert when errors occur.","zh-TW":"系統在發生錯誤時發送警報。"}]', '{"noun":"alert","verb":"alert"}', NULL, 2, 220, 258),
(221, 'algorithm', '/ˈælɡərɪðəm/', 'noun', '{"zh-TW":["演算法"],"en":["a set of rules for solving a problem"]}', NULL, 'search algorithm / algorithm design', '[{"en":"The algorithm sorts data efficiently.","zh-TW":"這個演算法能有效地排序資料。"},{"en":"Social media algorithms control what you see.","zh-TW":"社群媒體演算法控制你看到的內容。"}]', '{"adjective":"algorithmic"}', NULL, 3, 221, NULL),
(222, 'algorithm complexity', '/ˈælɡərɪðəm kəmˈpleksɪti/', 'noun', '{"zh-TW":["算法複雜度"],"en":["a measure of the computing resources required by an algorithm"]}', NULL, 'analyze algorithm complexity / reduce algorithm complexity / Big-O algorithm complexity', '[{"en":"Understanding algorithm complexity helps developers choose efficient solutions.","zh-TW":"理解算法複雜度幫助開發者選擇高效的解決方案。"},{"en":"The sorting algorithm has O(n log n) complexity.","zh-TW":"這個排序算法具有O(n log n)的複雜度。"}]', NULL, NULL, 5, 222, NULL),
(223, 'alienation', '/ˌeɪliəˈneɪʃən/', 'noun', '{"zh-TW":["疏離感；異化"],"en":["the state of being isolated from a group or activity you should be involved in"]}', NULL, 'social alienation / worker alienation / sense of alienation', '[{"en":"Marx argued that industrial capitalism causes worker alienation from their labor.","zh-TW":"馬克思認為工業資本主義導致工人對勞動的異化。"},{"en":"Political alienation among youth leads to low voter turnout.","zh-TW":"青年的政治疏離感導致了低投票率。"}]', '{"verb":"alienate","adjective":"alienated"}', NULL, 4, 223, NULL),
(224, 'align', '/əˈlaɪn/', 'verb', '{"zh-TW":["對齊；使一致"],"en":["to arrange things in a line or to ensure consistency between things"]}', NULL, 'align goals / align teams / align with strategy', '[{"en":"The new policy aligns employee incentives with company objectives.","zh-TW":"新政策使員工激勵與公司目標保持一致。"},{"en":"The departments aligned their priorities before the budget review.","zh-TW":"各部門在預算審查前調整了其優先事項。"}]', '{"noun":"alignment","adjective":"aligned"}', NULL, 2, 224, 641),
(225, 'alive', '/əˈlaɪv/', 'adjective', '{"zh-TW":["活著的；有生氣的","活著的；有活力的","活著的；活躍的"],"en":["living; not dead","full of energy","living; full of energy"]}', NULL, 'stay alive / come alive', '[{"en":"The tradition is still alive today.","zh-TW":"這個傳統至今仍然存在。"},{"en":"The market comes alive on weekends.","zh-TW":"市場在週末變得熱鬧起來。"},{"en":"He was found alive after three days.","zh-TW":"三天後他被發現還活著。"},{"en":"The city comes alive at night.","zh-TW":"城市在夜晚活躍起來。"},{"en":"He is lucky to be alive after the accident.","zh-TW":"他在事故後還活著很幸運。"},{"en":"The city comes alive at night.","zh-TW":"這座城市在夜晚變得活躍起來。"}]', '{"adjective":"alive"}', NULL, 2, 225, NULL),
(226, 'all-in cost', '/ɔːl ɪn kɒst/', 'noun', '{"zh-TW":["綜合成本；全包成本"],"en":["the total cost including all fees, charges, and expenses"]}', NULL, 'calculate all-in cost / all-in cost comparison', '[{"en":"The all-in cost of the loan included processing and insurance fees.","zh-TW":"貸款的綜合成本包括處理費和保險費。"},{"en":"Compare the all-in cost of leasing versus buying before deciding.","zh-TW":"在決定之前比較租賃和購買的綜合成本。"}]', NULL, NULL, 4, 226, NULL),
(227, 'all-inclusive', '/''ɔːl ɪnˈkluːsɪv/', 'adjective', '{"zh-TW":["全包式的；一切費用包括在內的"],"en":["including everything, especially all meals and drinks within a single price"]}', NULL, 'all-inclusive resort / all-inclusive package / all-inclusive deal', '[{"en":"The all-inclusive resort covered accommodation, meals, drinks, and activities.","zh-TW":"這個全包式度假村涵蓋了住宿、餐食、飲料和活動。"},{"en":"All-inclusive packages are popular with families who want to budget in advance.","zh-TW":"全包式套餐對希望提前預算的家庭很受歡迎。"}]', NULL, NULL, 5, 227, NULL),
(228, 'allegation', '/ˌæləˈɡeɪʃən/', 'noun', '{"zh-TW":["指控；指稱"],"en":["a claim that someone has done something wrong, without proof"]}', NULL, 'make an allegation / deny the allegation / allegation of fraud', '[{"en":"The allegation of fraud triggered an internal investigation.","zh-TW":"詐欺指控引發了內部調查。"},{"en":"She denied all allegations made against her.","zh-TW":"她否認了針對她的所有指控。"}]', '{"verb":"allege","adjective":"alleged"}', NULL, 4, 228, NULL),
(229, 'allegory', '/ˈæləɡɒri/', 'noun', '{"zh-TW":["寓言；暗喻"],"en":["a story, poem, or picture that can be interpreted to reveal a hidden meaning"]}', NULL, 'political allegory / religious allegory / read as an allegory', '[{"en":"The novel is often read as an allegory for colonialism and resistance.","zh-TW":"這部小說常被解讀為殖民主義和抵抗的寓言。"},{"en":"The film works both as entertainment and as a powerful allegory.","zh-TW":"這部電影既可作為娛樂，也可作為強有力的寓言。"}]', '{"adjective":"allegorical","adverb":"allegorically"}', NULL, 3, 229, NULL),
(230, 'allergen', '/ˈælədʒən/', 'noun', '{"zh-TW":["過敏原"],"en":["a substance that causes an allergic reaction"]}', NULL, 'common allergen / allergen information', '[{"en":"Please inform the server of any allergens before ordering.","zh-TW":"點餐前請告知服務員任何過敏原。"},{"en":"The menu clearly lists all allergens in each dish.","zh-TW":"菜單清楚列出每道菜的所有過敏原。"}]', '{"adjective":"allergenic","noun":"allergy"}', NULL, 3, 230, NULL),
(231, 'allergy', '/ˈælərdʒi/', 'noun', '{"zh-TW":["過敏症"],"en":["an adverse reaction of the immune system to a substance"]}', NULL, 'food allergy / seasonal allergy', '[{"en":"She has a severe allergy to peanuts.","zh-TW":"她對花生有嚴重過敏症。"},{"en":"Please inform your doctor about all known allergies.","zh-TW":"請告知您的醫生所有已知的過敏症。"}]', '{"adjective":"allergic","noun":"allergen"}', NULL, 3, 231, NULL),
(232, 'alliance', 'əˈlaɪəns', 'noun', '{"zh-TW":["聯盟；結盟","同盟"],"en":["a formal agreement between parties","a partnership"]}', NULL, 'strategic alliance/form an alliance', '[{"en":"We formed a strategic alliance with our partner.","zh-TW":"我們與合作夥伴建立了戰略聯盟。"}]', '{"adjective":"allied"}', NULL, 3, 232, NULL),
(233, 'allocate', '/ˈæləkeɪt/', 'verb', '{"zh-TW":["分配；撥出","分配"],"en":["to distribute resources for a particular purpose","to distribute for a particular purpose"]}', '{"prefix":{"text":"al-","meaning":"toward (朝向)"},"root":{"text":"loc","meaning":"place (地方)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使朝向特定地方，即「分配」。"}', 'allocate funds/resources/budget; allocate resources / allocate funds', '[{"en":"The company allocated $2 million for R&D.","zh-TW":"公司撥出200萬美元用於研發。"},{"en":"Resources should be allocated based on priority.","zh-TW":"資源應根據優先順序分配。"},{"en":"The government allocated funds for education.","zh-TW":"政府撥款用於教育。"},{"en":"We need to allocate more time to this project.","zh-TW":"我們需要為這個專案分配更多時間。"}]', '{"noun":"allocation"}', NULL, 3, 233, 4),
(234, 'allocation', '/ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["分配；撥款"],"en":["the distribution of resources, funds, or tasks to specific purposes"]}', NULL, 'budget allocation / resource allocation / allocation of funds', '[{"en":"Fair allocation of tasks prevented burnout in the team.","zh-TW":"公平的任務分配防止了團隊倦怠。"},{"en":"Budget allocation decisions are made at the executive level.","zh-TW":"預算分配決策在高管層面做出。"}]', '{"verb":"allocate","adjective":"allocated"}', NULL, 4, 234, 500),
(235, 'allocation method', '/ˌæləˈkeɪʃən ˈmeθəd/', 'noun', '{"zh-TW":["分配方法"],"en":["the approach used to distribute costs, resources, or responsibilities"]}', NULL, 'select an allocation method / apply the allocation method', '[{"en":"The company uses activity-based allocation methods for overhead costs.","zh-TW":"公司對間接費用使用基於活動的分配方法。"},{"en":"Choosing the right allocation method is critical for accurate pricing.","zh-TW":"選擇正確的分配方法對於準確定價至關重要。"}]', NULL, NULL, 5, 235, NULL),
(236, 'allocation of resources', '/ˌæləˈkeɪʃən əv rɪˈsɔːrsɪz/', 'noun', '{"zh-TW":["資源分配"],"en":["the process of deciding how to distribute available resources across activities"]}', NULL, 'optimize allocation of resources / allocation of resources decision', '[{"en":"Efficient allocation of resources maximizes organizational output.","zh-TW":"有效的資源分配最大化了組織產出。"},{"en":"The annual plan includes an allocation of resources to each department.","zh-TW":"年度計劃包括向每個部門的資源分配。"}]', NULL, NULL, 5, 236, NULL),
(237, 'allotment', '/əˈlɒtmənt/', 'noun', '{"zh-TW":["分配；配額；配售"],"en":["the distribution of shares or resources among applicants or participants"]}', NULL, 'allotment of shares / allotment notice / allotment of resources', '[{"en":"Employees received an allotment of shares at the company''s IPO.","zh-TW":"員工在公司首次公開招股時獲得了股份配售。"},{"en":"The budget committee approved the allotment of funds to each department.","zh-TW":"預算委員會批准了向各部門的資金分配。"}]', '{"verb":"allot","adjective":"allotted"}', NULL, 3, 237, 745),
(238, 'allow', '/əˈlaʊ/', 'verb', '{"zh-TW":["允許；准許","允許；容許"],"en":["to give permission for","to make something possible","to let someone do something","to give permission; to make it possible"]}', '{"prefix":{"text":"al-","meaning":"toward (朝向)"},"root":{"text":"low","meaning":"approve (批准)"},"logic":"朝向批准，即「允許」。"}', 'allow sb to do / allow for; allow for / not allowed; allow sb to do sth / be allowed to', '[{"en":"The policy allows employees to work from home.","zh-TW":"該政策允許員工在家工作。"},{"en":"Please allow 3-5 business days for processing.","zh-TW":"請預留3-5個工作天處理。"},{"en":"Smoking is not allowed here.","zh-TW":"這裡不准吸煙。"},{"en":"Allow two weeks for delivery.","zh-TW":"請預留兩週送貨時間。"},{"en":"Smoking is not allowed here.","zh-TW":"這裡不允許吸菸。"},{"en":"Please allow two weeks for delivery.","zh-TW":"請預留兩週的配送時間。"}]', '{"noun":"allowance","adjective":"allowable"}', NULL, 2, 238, NULL),
(239, 'allowance', 'əˈlaʊəns', 'noun', '{"zh-TW":["津貼；補貼","額度"],"en":["a regular amount of money","an amount permitted"]}', NULL, 'travel allowance/housing allowance', '[{"en":"You are entitled to a travel allowance.","zh-TW":"您有權獲得差旅津貼。"}]', '{"verb":"allow","adjective":"allowable"}', NULL, 3, 239, 259),
(240, 'allowance for doubtful accounts', '/əˈlaʊəns fɔːr ˈdaʊtfəl əˈkaʊnts/', 'noun', '{"zh-TW":["呆帳準備金"],"en":["a reserve established to account for receivables that may not be collected"]}', NULL, 'set up an allowance for doubtful accounts / review allowance for doubtful accounts', '[{"en":"The accountant increased the allowance for doubtful accounts after reviewing aging.","zh-TW":"會計師在審查帳齡後增加了呆帳準備金。"},{"en":"An allowance for doubtful accounts reduces net receivables on the balance sheet.","zh-TW":"呆帳準備金降低了資產負債表上的淨應收帳款。"}]', NULL, NULL, 5, 240, NULL),
(241, 'alone', '/əˈloʊn/', 'adjective', '{"zh-TW":["獨自的；單獨的","單獨的；獨自的","獨自的；單獨地"],"en":["without other people","without other people; only"]}', NULL, 'leave alone / stand alone; leave alone / all alone; leave sb alone / let alone (更不用說)', '[{"en":"She prefers to work alone.","zh-TW":"她偏好獨自工作。"},{"en":"You are not alone in this.","zh-TW":"你不是一個人面對這件事。"},{"en":"She lives alone.","zh-TW":"她獨自生活。"},{"en":"Leave me alone, please.","zh-TW":"請讓我一個人待著。"},{"en":"She lives alone in a small apartment.","zh-TW":"她獨自住在一間小公寓裡。"},{"en":"Leave me alone, please.","zh-TW":"請別打擾我。"}]', '{"adjective":"alone","adverb":"alone"}', NULL, 2, 241, NULL),
(242, 'along', '/əˈlɒŋ/', 'preposition', '{"zh-TW":["沿著；一起"],"en":["moving forward on"]}', NULL, 'along with / get along', '[{"en":"We walked along the river.","zh-TW":"我們沿著河邊散步。"},{"en":"She gets along with everyone.","zh-TW":"她和每個人都相處得很好。"}]', NULL, NULL, 2, 242, NULL),
(243, 'already', '/ɔːlˈrɛdi/', 'adverb', '{"zh-TW":["已經"],"en":["before now or a specified time","before now or before a particular time"]}', NULL, 'already done / already know; already + 完成式', '[{"en":"The report is already finished.","zh-TW":"報告已經完成了。"},{"en":"We have already discussed this.","zh-TW":"我們已經討論過這件事了。"},{"en":"I''ve already eaten lunch.","zh-TW":"我已經吃過午餐了。"},{"en":"She already knows the answer.","zh-TW":"她已經知道答案了。"},{"en":"I''ve already finished my homework.","zh-TW":"我已經完成作業了。"},{"en":"The train had already left when we arrived.","zh-TW":"我們到達時火車已經開走了。"}]', '{"adverb":"already"}', NULL, 3, 243, NULL),
(244, 'also', '/ˈɔːlsoʊ/', 'adverb', '{"zh-TW":["也；而且"],"en":["in addition; too"]}', NULL, 'also known as / but also', '[{"en":"He also speaks French.","zh-TW":"他也說法語。"},{"en":"She is not only smart but also kind.","zh-TW":"她不僅聰明而且善良。"}]', NULL, NULL, 1, 244, NULL),
(245, 'alter', '/ˈɔːltər/', 'verb', '{"zh-TW":["改變；修改"],"en":["to change or make different"]}', '{"root":{"text":"alter","meaning":"other (其他)"},"logic":"使成為其他樣子，即「改變」。"}', 'alter plans/design/course', '[{"en":"The company altered its marketing strategy.","zh-TW":"公司修改了行銷策略。"},{"en":"Circumstances may alter the timeline.","zh-TW":"情況可能改變時間表。"}]', '{"noun":"alteration","adjective":"alternate"}', NULL, 2, 245, NULL),
(246, 'alternative', '/ɔːlˈtɜːrnətɪv/', 'noun', '{"zh-TW":["替代方案；選擇"],"en":["one of two or more available possibilities"]}', '{"root":{"text":"alter","meaning":"other (其他)"},"suffix":{"text":"-ative","meaning":"relating to (有關的)"},"logic":"與其他有關的，即「替代方案」。"}', 'alternative solution/approach/option', '[{"en":"We need to find an alternative to the current supplier.","zh-TW":"我們需要找到目前供應商的替代方案。"},{"en":"What are the alternatives if the deal falls through?","zh-TW":"如果交易失敗，有什麼替代方案？"}]', '{"adverb":"alternatively"}', NULL, 4, 246, 260),
(247, 'alternatively', '/ɔːlˈtɜːrnətɪvli/', 'adverb', '{"zh-TW":["或者；作為替代"],"en":["in a way that offers a choice between two or more things"]}', NULL, 'alternatively, you may / choose alternatively', '[{"en":"You can pay online, or alternatively, at our office.","zh-TW":"您可以在線支付，或者也可以在我們的辦公室支付。"},{"en":"We can meet on Tuesday, or alternatively on Friday.","zh-TW":"我們可以在週二會面，或者也可以在週五。"}]', '{"adjective":"alternative","noun":"alternative"}', NULL, 5, 247, NULL),
(248, 'although', '/ɔːlˈðoʊ/', 'conjunction', '{"zh-TW":["雖然；儘管"],"en":["despite the fact that"]}', NULL, 'although... still; although = though (較口語)', '[{"en":"Although it rained, we went out.","zh-TW":"雖然下雨了，我們還是出門了。"},{"en":"Although tired, she kept working.","zh-TW":"雖然累了，她仍繼續工作。"},{"en":"Although it was raining, we went out.","zh-TW":"雖然在下雨，我們還是出去了。"},{"en":"Although expensive, the product is worth it.","zh-TW":"雖然貴，但這個產品值得。"}]', NULL, NULL, 3, 248, NULL),
(249, 'altitude', '/''æltɪtjuːd/', 'noun', '{"zh-TW":["海拔；高度"],"en":["the height of an object or point in relation to sea level"]}', NULL, 'high altitude / altitude sickness / gain altitude', '[{"en":"Travelers visiting high-altitude destinations should allow time to acclimatize.","zh-TW":"前往高海拔目的地的旅客應給自己時間適應。"},{"en":"The plane cruised at an altitude of thirty-five thousand feet.","zh-TW":"飛機在三萬五千英尺的高度巡航。"}]', NULL, NULL, 3, 249, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(250, 'alumni', '/əˈlʌmnaɪ/', 'noun', '{"zh-TW":["校友"],"en":["former students of a school or university"]}', NULL, 'alumni association / alumni network', '[{"en":"The alumni donated to the school.","zh-TW":"校友們捐款給學校。"},{"en":"She joined the alumni association.","zh-TW":"她加入了校友會。"}]', NULL, NULL, 2, 250, NULL),
(251, 'alumni network', '/''æˌlʌmnaɪ ˌnetwɜːrk/', 'noun', '{"zh-TW":["校友網絡；校友會"],"en":["a group of former students of a school or university who maintain connections and support each other professionally"]}', NULL, 'join the alumni network / leverage the alumni network / active alumni network', '[{"en":"She found her job through connections in her university''s alumni network.","zh-TW":"她通過大學校友網絡的人脈找到了工作。"},{"en":"A strong alumni network can provide mentorship, references, and job opportunities.","zh-TW":"強大的校友網絡可以提供指導、推薦信和就業機會。"}]', NULL, NULL, 5, 251, NULL),
(252, 'always', '/ˈɔːlweɪz/', 'adverb', '{"zh-TW":["總是；一直"],"en":["at all times"]}', NULL, 'always available / as always', '[{"en":"He is always punctual.","zh-TW":"他總是很準時。"},{"en":"Customers always come first.","zh-TW":"客戶永遠是第一位的。"}]', '{"adverb":"always"}', NULL, 2, 252, NULL),
(253, 'amalgamate', '/əˈmælɡəmeɪt/', 'verb', '{"zh-TW":["合併；融合"],"en":["to combine or unite to form one organization or structure"]}', NULL, 'amalgamate companies / amalgamate departments', '[{"en":"The two regional offices were amalgamated into one.","zh-TW":"兩個區域辦公室被合併為一個。"},{"en":"The union decided to amalgamate with a larger federation.","zh-TW":"工會決定與一個更大的聯合會合併。"}]', '{"noun":"amalgamation","adjective":"amalgamated"}', NULL, 4, 253, NULL),
(254, 'amalgamation', '/əˌmælɡəˈmeɪʃən/', 'noun', '{"zh-TW":["合並；融合"],"en":["the combination of several elements into a single more effective whole"]}', NULL, 'corporate amalgamation / amalgamation of departments / complete amalgamation', '[{"en":"The amalgamation of three departments reduced administrative overhead.","zh-TW":"三個部門的合並降低了行政費用。"},{"en":"The amalgamation of two rival unions created a more powerful bargaining group.","zh-TW":"兩個競爭工會的合並創建了一個更強大的談判群體。"}]', '{"verb":"amalgamate","adjective":"amalgamated"}', NULL, 4, 254, NULL),
(255, 'amazing', '/əˈmeɪzɪŋ/', 'adjective', '{"zh-TW":["令人驚嘆的；了不起的"],"en":["extremely surprising or impressive"]}', NULL, 'amazing + 名詞 / It''s amazing that...', '[{"en":"The view from the top was amazing.","zh-TW":"從頂端看下去的景色令人驚嘆。"},{"en":"She did an amazing job on the project.","zh-TW":"她在專案中表現出色。"}]', '{"verb":"amaze","noun":"amazement","adverb":"amazingly"}', NULL, 3, 255, NULL),
(256, 'ambitious', '/æmˈbɪʃəs/', 'adjective', '{"zh-TW":["有野心的；雄心勃勃的"],"en":["having a strong desire to succeed","requiring great effort"]}', '{"root":{"text":"ambi","meaning":"go around (四處走)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿四處尋求機會的特質，即「有野心的」。"}', 'ambitious plan/goal/target; ambitious goal / ambitious plan', '[{"en":"The company set ambitious growth targets for next year.","zh-TW":"公司為明年設定了雄心勃勃的成長目標。"},{"en":"She is an ambitious young professional.","zh-TW":"她是一位有抱負的年輕專業人士。"},{"en":"She is an ambitious young woman.","zh-TW":"她是個有抱負的年輕女性。"},{"en":"The project is ambitious but achievable.","zh-TW":"這個計畫雄心勃勃但可實現。"}]', '{"noun":"ambition","adverb":"ambitiously"}', NULL, 3, 256, 823),
(257, 'ambivalence', '/æmˈbɪvələns/', 'noun', '{"zh-TW":["矛盾情感；態度不明確"],"en":["the state of having mixed feelings about something"]}', NULL, 'feel ambivalence / express ambivalence / ambivalence toward', '[{"en":"Her ambivalence about the project delayed the decision.","zh-TW":"她對該項目的矛盾情感拖延了決策。"},{"en":"There is a general ambivalence toward automation in the workforce.","zh-TW":"工作人員對自動化普遍持矛盾態度。"}]', '{"adjective":"ambivalent","adverb":"ambivalently"}', NULL, 4, 257, NULL),
(258, 'ambivalent', '/''æmˈbɪvələnt/', 'adjective', '{"zh-TW":["矛盾的；態度不明確的"],"en":["having mixed feelings or contradictory ideas about something or someone"]}', NULL, 'ambivalent attitude / feel ambivalent / remain ambivalent', '[{"en":"She felt ambivalent about accepting the job offer because it required relocating.","zh-TW":"她對接受這份工作要約感到矛盾，因為它需要搬遷。"},{"en":"The board was ambivalent about the acquisition, seeing both opportunities and risks.","zh-TW":"董事會對收購態度矛盾，看到了機遇和風險。"}]', '{"adverb":"ambivalently","noun":"ambivalence"}', NULL, 4, 258, NULL),
(259, 'ambulance', '/ˈæmbjʊləns/', 'noun', '{"zh-TW":["救護車"],"en":["a vehicle for taking sick people to hospital"]}', NULL, 'call an ambulance / emergency ambulance', '[{"en":"Call an ambulance immediately if someone collapses.","zh-TW":"如果有人倒下，立即叫救護車。"},{"en":"The ambulance arrived within five minutes.","zh-TW":"救護車在五分鐘內到達。"}]', NULL, NULL, 3, 259, NULL),
(260, 'ameliorate', '/əˈmiːliəreɪt/', 'verb', '{"zh-TW":["改善；改良"],"en":["to make something bad or unsatisfactory better"]}', NULL, 'ameliorate conditions / ameliorate suffering / ameliorate the situation', '[{"en":"Policy interventions can ameliorate the effects of poverty on children.","zh-TW":"政策干預可以改善貧困對兒童的影響。"},{"en":"The new protocol was designed to ameliorate systemic risks.","zh-TW":"新協議旨在改善系統性風險。"}]', '{"noun":"amelioration","adjective":"ameliorative"}', NULL, 4, 260, NULL),
(261, 'amelioration', '/əˌmiːliəˈreɪʃən/', 'noun', '{"zh-TW":["改善；改進"],"en":["the act of making something better"]}', NULL, 'policy amelioration / condition amelioration / seek amelioration', '[{"en":"The international aid focused on amelioration of the refugee crisis.","zh-TW":"國際援助重點是對難民危機的改善。"},{"en":"Amelioration of working conditions improved staff morale significantly.","zh-TW":"工作條件的改善顯著提高了員工士氣。"}]', '{"verb":"ameliorate","adjective":"ameliorated"}', NULL, 4, 261, NULL),
(262, 'ameliorative', '/əˈmiːliərətɪv/', 'adjective', '{"zh-TW":["改善的；有助改進的"],"en":["tending to improve or alleviate a bad situation"]}', NULL, 'ameliorative policy / ameliorative measure / ameliorative action', '[{"en":"Ameliorative policies reduced poverty rates among the elderly.","zh-TW":"改善性政策降低了老年人的貧困率。"},{"en":"Ameliorative actions were taken to address the environmental damage.","zh-TW":"採取了改善性行動來處理環境損害。"}]', '{"verb":"ameliorate","noun":"amelioration"}', NULL, 4, 262, NULL),
(263, 'amend', '/əˈmend/', 'verb', '{"zh-TW":["修正；修訂"],"en":["to make changes to improve or correct","to make changes to a document or law"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"mend","meaning":"fault (過錯)"},"logic":"朝向修正過錯，即「修訂」。"}', 'amend a contract/law/policy; amend a law / amend the constitution', '[{"en":"The contract was amended to include new terms.","zh-TW":"合約被修訂以納入新條款。"},{"en":"Congress voted to amend the legislation.","zh-TW":"國會投票修正了該立法。"},{"en":"The committee voted to amend the proposal.","zh-TW":"委員會投票修正了提案。"},{"en":"The law was amended to include new provisions.","zh-TW":"法律被修訂以納入新條款。"}]', '{"noun":"amendment"}', NULL, 2, 263, 643),
(264, 'amendment', '/əˈmɛndmənt/', 'noun', '{"zh-TW":["修正案"],"en":["a change made to a law or document"]}', NULL, 'constitutional amendment / first amendment', '[{"en":"The First Amendment protects free speech.","zh-TW":"第一修正案保護言論自由。"},{"en":"They proposed an amendment to the bill.","zh-TW":"他們提議修改法案。"}]', '{"verb":"amend"}', NULL, 3, 264, 261),
(265, 'amenities', '/əˈmiːnɪtiz/', 'noun', '{"zh-TW":["設施；便民設施"],"en":["useful features that make a place pleasant or convenient"]}', NULL, 'local amenities / property amenities', '[{"en":"The apartment is close to many local amenities.","zh-TW":"這棟公寓靠近許多當地便民設施。"},{"en":"The development includes amenities such as a gym and pool.","zh-TW":"該開發項目包括健身房和游泳池等設施。"}]', NULL, NULL, 3, 265, NULL),
(266, 'amenity', '/əˈmiːnɪti/', 'noun', '{"zh-TW":["設施；便利設備"],"en":["a useful or desirable feature of a place"]}', NULL, 'hotel amenity / modern amenity', '[{"en":"The resort offers excellent amenities including a spa.","zh-TW":"度假村提供包括水療在內的優質設施。"},{"en":"Please check the list of in-room amenities.","zh-TW":"請查看客房設施清單。"}]', NULL, NULL, 3, 266, NULL),
(267, 'amenity kit', '/əˈmenɪti kɪt/', 'noun', '{"zh-TW":["旅行盥洗包"],"en":["a bag of toiletries and essentials provided to passengers"]}', NULL, 'business class amenity kit / complimentary amenity kit', '[{"en":"Passengers in business class received an amenity kit.","zh-TW":"商務艙乘客收到了旅行盥洗包。"},{"en":"The amenity kit included a sleep mask, toothbrush, and earplugs.","zh-TW":"盥洗包內含睡眠眼罩、牙刷和耳塞。"}]', NULL, NULL, 4, 267, NULL),
(268, 'among', '/əˈmʌŋ/', 'preposition', '{"zh-TW":["在…之中","在...之中；之間"],"en":["in the middle of; surrounded by","in the middle of; between more than two"]}', NULL, 'among others / among the best; among others (其中)', '[{"en":"She is among the top candidates.","zh-TW":"她是頂尖的候選人之一。"},{"en":"Divide the tasks among the team.","zh-TW":"把任務分配給團隊成員。"},{"en":"She sat among her friends.","zh-TW":"她坐在朋友們中間。"},{"en":"He is among the best students.","zh-TW":"他是最好的學生之一。"},{"en":"She is popular among her colleagues.","zh-TW":"她在同事之間很受歡迎。"},{"en":"The cost was divided among the team members.","zh-TW":"費用在團隊成員之間分攤。"}]', '{"preposition":"among"}', NULL, 2, 268, NULL),
(269, 'amortization', '/əˌmɔːrtɪˈzeɪʃən/', 'noun', '{"zh-TW":["攤銷"],"en":["the gradual write-off of an intangible asset over time"]}', NULL, 'loan amortization / amortization schedule / amortization of goodwill', '[{"en":"The amortization of goodwill impacts reported earnings.","zh-TW":"商譽攤銷影響報告的盈利。"},{"en":"He prepared an amortization schedule for the loan.","zh-TW":"他為貸款準備了攤銷時間表。"}]', '{"verb":"amortize","adjective":"amortized"}', NULL, 4, 269, NULL),
(270, 'amortization schedule', '/əˌmɔːrtɪˈzeɪʃən ˈʃedjuːl/', 'noun', '{"zh-TW":["分期攤還計劃"],"en":["a table showing each loan payment broken down into principal and interest"]}', NULL, 'follow the amortization schedule / amortization schedule calculation', '[{"en":"The amortization schedule shows the loan is paid off in 10 years.","zh-TW":"分期攤還計劃顯示貸款將在10年內還清。"},{"en":"Each payment in the amortization schedule reduces the outstanding principal.","zh-TW":"分期攤還計劃中的每次付款都減少了未償還本金。"}]', NULL, NULL, 5, 270, NULL),
(271, 'amortize', '/ˈæmɔːrtaɪz/', 'verb', '{"zh-TW":["攤銷；分期償還"],"en":["to spread the cost of an asset over its useful life"]}', NULL, 'amortize a loan / amortize intangible assets', '[{"en":"The loan was amortized over 10 years with equal monthly payments.","zh-TW":"貸款以等額月付方式在10年內攤銷。"},{"en":"Software development costs were amortized over five years.","zh-TW":"軟體開發成本在五年內攤銷。"}]', '{"noun":"amortization","adjective":"amortized"}', NULL, 3, 271, NULL),
(272, 'amount', '/əˈmaʊnt/', 'noun', '{"zh-TW":["金額；數量"],"en":["a quantity of something","the total of two or more quantities"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"mount","meaning":"mountain (山)"},"logic":"朝向堆積如山，即「數量」。"}', 'a large/small amount of / total amount', '[{"en":"The total amount due is $5,000.","zh-TW":"應付總金額為5,000美元。"},{"en":"A significant amount of time was spent on research.","zh-TW":"大量時間被用於研究。"}]', NULL, NULL, 2, 272, NULL),
(273, 'anachronism', '/əˈnækrənɪzəm/', 'noun', '{"zh-TW":["時代錯誤；不合時宜的事物"],"en":["something that belongs to a different period of time and seems outdated"]}', NULL, 'an anachronism / political anachronism / cultural anachronism', '[{"en":"The use of fax machines in modern offices is an anachronism.","zh-TW":"在現代辦公室使用傳真機是一種時代錯誤。"},{"en":"The ancient ritual is viewed as an anachronism in contemporary society.","zh-TW":"這個古老的儀式在當代社會被視為不合時宜的事物。"}]', '{"adjective":"anachronistic","adverb":"anachronistically"}', NULL, 4, 273, NULL),
(274, 'anaerobic', '/''ænəˈrəʊbɪk/', 'adjective', '{"zh-TW":["無氧的；厭氧的"],"en":["relating to physical exercise that is intense but of short duration, not requiring oxygen as fuel"]}', NULL, 'anaerobic exercise / anaerobic training / anaerobic capacity', '[{"en":"Sprinting and weightlifting are examples of anaerobic exercise.","zh-TW":"短跑和舉重是無氧運動的例子。"},{"en":"Anaerobic training builds muscle strength and power more effectively than aerobic exercise.","zh-TW":"無氧訓練比有氧運動更有效地建立肌肉力量和爆發力。"}]', NULL, NULL, 3, 274, NULL),
(275, 'anaerobic training', '/''ænˌeəˌrəʊbɪk ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["無氧訓練"],"en":["high-intensity physical activity performed without oxygen, used to build strength and speed"]}', NULL, 'benefit of anaerobic training / incorporate anaerobic training / anaerobic training session', '[{"en":"Anaerobic training like sprinting and weight lifting builds explosive muscle power.","zh-TW":"無氧訓練如短跑和舉重可以建立爆發性的肌肉力量。"},{"en":"Athletes combine aerobic and anaerobic training to maximize overall fitness.","zh-TW":"運動員結合有氧和無氧訓練以最大化整體健康。"}]', '{"adjective":"anaerobic"}', NULL, 5, 275, NULL),
(276, 'analgesia', '/ˌænəlˈdʒiːziə/', 'noun', '{"zh-TW":["止痛；鎮痛"],"en":["the inability to feel pain; or the condition produced by analgesic drugs"]}', NULL, 'provide analgesia / epidural analgesia / adequate analgesia', '[{"en":"Epidural analgesia is commonly used during labor for pain relief.","zh-TW":"硬膜外鎮痛常用於分娩期間的止痛。"},{"en":"Patient-controlled analgesia gives patients autonomy over their pain relief.","zh-TW":"患者自控鎮痛讓患者自主控制止痛。"}]', '{"adjective":"analgesic","noun":"analgesic"}', NULL, 3, 276, NULL),
(277, 'analogy', '/əˈnælədʒi/', 'noun', '{"zh-TW":["類比；比喻"],"en":["a comparison between two things for the purpose of explanation"]}', NULL, 'draw an analogy / apt analogy / analogy between', '[{"en":"The teacher drew an analogy between electricity and water flow.","zh-TW":"老師以電流和水流之間的類比作說明。"},{"en":"An analogy can make complex ideas easier to understand.","zh-TW":"類比可以使複雜的概念更易於理解。"}]', '{"adjective":"analogous","adverb":"analogously"}', NULL, 3, 277, NULL),
(278, 'analysis', 'əˈnæləsɪs', 'noun', '{"zh-TW":["分析；研究","分解"],"en":["a detailed examination","a study of data"]}', NULL, 'cost analysis/market analysis', '[{"en":"Please present a market analysis.","zh-TW":"請提交市場分析。"}]', '{"verb":"analyze","adjective":"analytical","adverb":"analytically"}', NULL, 3, 278, NULL),
(279, 'analyst', '/ˈænəlɪst/', 'noun', '{"zh-TW":["分析師；分析人員"],"en":["a professional who examines data or situations to draw conclusions"]}', NULL, 'financial analyst / business analyst / data analyst / market analyst', '[{"en":"The financial analyst issued a buy recommendation on the stock.","zh-TW":"財務分析師對該股票發出了買入建議。"},{"en":"She works as a business analyst in the strategy department.","zh-TW":"她在策略部門擔任業務分析師。"}]', '{"plural":"analysts","verb":"analyze"}', NULL, 3, 279, NULL),
(280, 'analytical thinking', '/ˌænəˈlɪtɪkəl ˈθɪŋkɪŋ/', 'noun', '{"zh-TW":["分析性思維；分析思維"],"en":["the ability to systematically break down complex problems and evaluate information to reach conclusions"]}', NULL, 'develop analytical thinking / strong analytical thinking / apply analytical thinking', '[{"en":"Analytical thinking helps professionals identify patterns and solve complex problems.","zh-TW":"分析性思維幫助專業人士識別規律並解決複雜問題。"},{"en":"Employers value candidates who demonstrate strong analytical thinking in interviews.","zh-TW":"雇主重視在面試中展示強大分析性思維的候選人。"}]', NULL, NULL, 5, 280, NULL),
(281, 'analytics', '/ˌænəˈlɪtɪks/', 'noun', '{"zh-TW":["分析；數據分析"],"en":["systematic computational analysis of data"]}', NULL, 'marketing analytics / data analytics', '[{"en":"Analytics revealed that most customers visit the site on mobile.","zh-TW":"分析顯示大多數顧客使用手機訪問網站。"},{"en":"The analytics team provided insights to improve the campaign.","zh-TW":"分析團隊提供了改進活動的見解。"}]', '{"verb":"analyze","adjective":"analytical"}', NULL, 3, 281, NULL),
(282, 'analyze', '/ˈænəlaɪz/', 'verb', '{"zh-TW":["分析；解析","分析"],"en":["to examine something in detail to understand it","to examine in detail"]}', '{"root":{"text":"ana","meaning":"up/throughout (全面)"},"suffix":{"text":"-lyze","meaning":"loosen/break down (分解)"},"logic":"全面分解，即「分析」。"}', 'analyze data/results/trends; analyze data / analyze results', '[{"en":"The team will analyze the survey results next week.","zh-TW":"團隊將在下週分析調查結果。"},{"en":"We need to analyze market trends before launching.","zh-TW":"推出前我們需要分析市場趨勢。"},{"en":"Scientists analyzed the data carefully.","zh-TW":"科學家仔細分析了數據。"},{"en":"We need to analyze the market trends.","zh-TW":"我們需要分析市場趨勢。"}]', '{"noun":"analysis","adjective":"analytical","noun2":"analyst"}', NULL, 3, 282, 262),
(283, 'anchor investor', '/ˈæŋkər ɪnˈvestər/', 'noun', '{"zh-TW":["錨定投資者"],"en":["a cornerstone investor who commits to a significant portion of an IPO or placement"]}', NULL, 'secure an anchor investor / role of anchor investor / anchor investor commitment', '[{"en":"The fund secured an anchor investor to give confidence to other buyers.","zh-TW":"基金獲得了錨定投資者以給予其他買家信心。"},{"en":"Anchor investors stabilize IPO pricing and signal confidence in the offering.","zh-TW":"錨定投資者穩定IPO定價並向發行傳遞信心訊號。"}]', NULL, NULL, 5, 283, NULL),
(284, 'anchoring effect', '/''æŋkərɪŋ ɪˌfekt/', 'noun', '{"zh-TW":["定錨效應；錨點偏誤"],"en":["the tendency to rely too heavily on the first piece of information offered when making decisions"]}', NULL, 'use the anchoring effect / beware of the anchoring effect / anchoring effect in negotiation', '[{"en":"Negotiators often use the anchoring effect by making the first offer to set the reference point.","zh-TW":"談判者通常通過先報價來設定參考點，利用定錨效應。"},{"en":"The anchoring effect explains why initial prices greatly influence what consumers consider reasonable.","zh-TW":"定錨效應解釋了為什麼初始價格對消費者認為合理的價格有很大影響。"}]', '{"noun":"anchor","verb":"anchor"}', NULL, 5, 284, NULL),
(285, 'ancillary', '/ˈænsɪləri/', 'adjective', '{"zh-TW":["輔助的；附屬的"],"en":["providing support to a primary activity; additional"]}', NULL, 'ancillary services / ancillary costs / ancillary staff', '[{"en":"Ancillary services such as catering and cleaning support the core business.","zh-TW":"餐飲和清潔等輔助服務支持核心業務。"},{"en":"Ancillary costs can add twenty percent to the total project budget.","zh-TW":"輔助成本可能使項目總預算增加百分之二十。"}]', NULL, NULL, 3, 285, NULL),
(286, 'ancillary cost', '/ænˈsɪləri kɒst/', 'noun', '{"zh-TW":["附帶費用；輔助成本"],"en":["a secondary cost incurred in support of a primary activity or function"]}', NULL, 'include ancillary costs / ancillary cost budget', '[{"en":"Freight, customs, and insurance are ancillary costs of importing.","zh-TW":"貨運、海關和保險費是進口的附帶費用。"},{"en":"Ancillary costs can significantly increase the total project expenditure.","zh-TW":"附帶費用可能會顯著增加項目的總支出。"}]', NULL, NULL, 5, 286, NULL),
(287, 'ancillary service', '/ænˈsɪləri ˈsɜːrvɪs/', 'noun', '{"zh-TW":["輔助服務；附加服務"],"en":["a supplementary service that supports or complements the main service"]}', NULL, 'offer ancillary services / ancillary service charge', '[{"en":"The hotel generates revenue through ancillary services like parking.","zh-TW":"飯店通過停車等輔助服務產生收入。"},{"en":"Ancillary services are often bundled with the primary offering.","zh-TW":"輔助服務通常與主要產品捆綁在一起。"}]', NULL, NULL, 5, 287, NULL),
(288, 'anesthesia', '/ˌænɪsˈθiːziə/', 'noun', '{"zh-TW":["麻醉"],"en":["a state of induced insensitivity to pain for surgery"]}', NULL, 'general anesthesia / local anesthesia', '[{"en":"The patient was placed under general anesthesia for the operation.","zh-TW":"患者在手術中被施以全身麻醉。"},{"en":"Local anesthesia numbs only the specific area being treated.","zh-TW":"局部麻醉只會使正在治療的特定區域失去知覺。"}]', '{"noun":"anesthesiologist","adjective":"anesthetic"}', NULL, 4, 288, NULL),
(289, 'anesthesiologist', '/ˌænɪsˌθiːziˈɒlədʒɪst/', 'noun', '{"zh-TW":["麻醉科醫師"],"en":["a physician specializing in the administration of anesthesia"]}', NULL, 'consult an anesthesiologist / qualified anesthesiologist / experienced anesthesiologist', '[{"en":"The anesthesiologist monitored the patient throughout the surgery.","zh-TW":"麻醉科醫師在整個手術過程中監測患者。"},{"en":"An anesthesiologist assesses risks before administering general anesthesia.","zh-TW":"麻醉科醫師在施用全身麻醉前評估風險。"}]', NULL, NULL, 5, 289, NULL),
(290, 'angel investor', '/ˈeɪndʒəl ɪnˈvestər/', 'noun', '{"zh-TW":["天使投資人"],"en":["an individual who invests personal money in early-stage startups"]}', NULL, 'angel investor network / find an angel investor / pitch to angel investors', '[{"en":"An angel investor provided the initial capital to launch the company.","zh-TW":"天使投資人提供了啟動公司的初始資本。"},{"en":"Angel investors often provide mentorship in addition to funding.","zh-TW":"天使投資人除了資金外，通常還提供指導。"}]', '{"plural":"angel investors"}', NULL, 5, 290, NULL),
(291, 'angry', '/ˈæŋɡri/', 'adjective', '{"zh-TW":["生氣的","生氣的；憤怒的"],"en":["feeling strong displeasure","feeling or showing strong displeasure"]}', NULL, 'get angry / angry about; angry at / angry about; angry with/at sb / angry about sth', '[{"en":"The customer was angry about the delay.","zh-TW":"顧客對延誤感到生氣。"},{"en":"Don''t make hasty decisions when angry.","zh-TW":"生氣時不要做倉促的決定。"},{"en":"She was angry about the delay.","zh-TW":"她對延誤感到生氣。"},{"en":"Don''t be angry with me.","zh-TW":"別對我生氣。"},{"en":"He was angry about the delay.","zh-TW":"他對延誤感到憤怒。"}]', '{"adjective":"angry","noun":"anger","adverb":"angrily","verb":"anger"}', NULL, 2, 291, NULL),
(292, 'animal', '/ˈænɪməl/', 'noun', '{"zh-TW":["動物"],"en":["a living creature that is not a plant or human","a living creature that can move and feel"]}', NULL, 'wild animal / animal rights; domestic/wild animal', '[{"en":"Dogs are loyal animals.","zh-TW":"狗是忠誠的動物。"},{"en":"Many wild animals are endangered.","zh-TW":"許多野生動物瀕臨滅絕。"},{"en":"Dogs are popular domestic animals.","zh-TW":"狗是受歡迎的家畜。"},{"en":"Many wild animals are endangered.","zh-TW":"許多野生動物瀕臨絕種。"}]', NULL, NULL, 2, 292, NULL),
(293, 'annex', '/ˈæneks/', 'noun', '{"zh-TW":["附件；附屬建築"],"en":["an addition or supplement to a document; also an attached building"]}', NULL, 'attach an annex / annex to the report / building annex', '[{"en":"The technical specifications are detailed in the annex.","zh-TW":"技術規格在附件中有詳細說明。"},{"en":"A new annex was constructed to expand the office capacity.","zh-TW":"建造了新的附屬建築以擴大辦公室容量。"}]', '{"verb":"annex","adjective":"annexed"}', NULL, 2, 293, 983),
(294, 'anniversary', 'ˌænɪˈvɜːrsəri', 'noun', '{"zh-TW":["週年紀念；週年","週年慶"],"en":["the annual date of a past event","a celebration of longevity"]}', NULL, 'company anniversary/10th anniversary', '[{"en":"We are celebrating our 20th anniversary.","zh-TW":"我們正在慶祝20週年紀念日。"}]', '{"adjective":"annual","adverb":"annually"}', NULL, 4, 294, NULL),
(295, 'annotate', '/''ænəˌteɪt/', 'verb', '{"zh-TW":["注釋；加批注"],"en":["to add notes or comments to a text or diagram to explain or comment on it"]}', NULL, 'annotate a text / annotate a document / annotate with comments', '[{"en":"Students are encouraged to annotate their textbooks as they read.","zh-TW":"學生被鼓勵在閱讀時對教科書進行注釋。"},{"en":"The teacher asked students to annotate the poem with their interpretation of each stanza.","zh-TW":"老師要求學生對每節詩進行注釋，說明他們的理解。"}]', '{"noun":"annotation","adjective":"annotated"}', NULL, 3, 295, NULL),
(296, 'announce', '/əˈnaʊns/', 'verb', '{"zh-TW":["宣布；公告","宣布；宣告","宣布"],"en":["to make a public or official statement","to make something known publicly","to make a public statement about something"]}', '{"prefix":{"text":"an-","meaning":"toward (朝向)"},"root":{"text":"nounce","meaning":"report (報告)"},"logic":"朝向報告，即「宣布」。"}', 'announce a decision/plan/merger; announce a decision / announce that; announce the results / announce a decision / officially announce', '[{"en":"The CEO announced the merger at a press conference.","zh-TW":"執行長在記者會上宣布了合併消息。"},{"en":"The results will be announced next Monday.","zh-TW":"結果將於下週一公布。"},{"en":"They announced the winner.","zh-TW":"他們宣布了獲勝者。"},{"en":"The company announced a new product.","zh-TW":"公司宣布了一款新產品。"},{"en":"The company announced record profits.","zh-TW":"公司宣布了創紀錄的利潤。"},{"en":"They will announce the winner tomorrow.","zh-TW":"他們明天將宣布得獎者。"}]', '{"noun":"announcement","noun2":"announcer"}', NULL, 3, 296, 5),
(297, 'announcement', 'əˈnaʊnsmənt', 'noun', '{"zh-TW":["公告；通知","宣布"],"en":["an official public statement","a declaration"]}', NULL, 'make an announcement/company announcement', '[{"en":"The CEO made an important announcement.","zh-TW":"執行長發布了重要公告。"}]', '{"verb":"announce","adjective":"announcing"}', NULL, 4, 297, 501),
(298, 'annual', '/ˈænjuəl/', 'adjective', '{"zh-TW":["年度的；每年的"],"en":["occurring once every year"]}', '{"root":{"text":"annu","meaning":"year (年)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"與年有關的，即「年度的」。"}', 'annual report/meeting/revenue; annual report / annual meeting / annual income', '[{"en":"The annual report shows a 15% increase in profit.","zh-TW":"年度報告顯示利潤增長了15%。"},{"en":"The annual conference is held in December.","zh-TW":"年度會議在十二月舉行。"},{"en":"The company holds its annual meeting in March.","zh-TW":"公司每年三月舉行年度會議。"},{"en":"What is your annual income?","zh-TW":"你的年收入是多少？"}]', '{"adverb":"annually"}', NULL, 2, 298, 6),
(299, 'annual general meeting', '/ˈænjuəl ˈdʒenərəl ˈmiːtɪŋ/', 'noun', '{"zh-TW":["年度股東大會"],"en":["a yearly meeting where shareholders vote on company matters"]}', NULL, 'hold an AGM / attend the AGM / annual general meeting agenda', '[{"en":"Shareholders voted on the dividend proposal at the annual general meeting.","zh-TW":"股東在年度股東大會上對股利提案進行了投票。"},{"en":"The CEO presented the annual report at the AGM.","zh-TW":"執行長在年度股東大會上呈報了年報。"}]', '{"abbreviation":"AGM"}', NULL, 5, 299, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(300, 'annual leave', '/ˈænjuəl liːv/', 'noun', '{"zh-TW":["年假；有薪假"],"en":["paid vacation time granted each year"]}', NULL, 'take annual leave / annual leave entitlement', '[{"en":"Employees receive 15 days of annual leave per year.","zh-TW":"員工每年獲得15天年假。"},{"en":"Please submit your annual leave request two weeks in advance.","zh-TW":"請提前兩週提交年假申請。"}]', NULL, NULL, 4, 300, NULL),
(301, 'annual report', '/ˈænjuəl rɪˈpɔːrt/', 'noun', '{"zh-TW":["年報；年度報告"],"en":["a comprehensive report on a company''s activities and financial performance"]}', NULL, 'publish an annual report / review the annual report / annual report filing', '[{"en":"The annual report highlighted strong revenue growth year over year.","zh-TW":"年報強調了年度收入的強勁增長。"},{"en":"Shareholders receive the annual report before the AGM.","zh-TW":"股東在年度股東大會前收到年報。"}]', NULL, NULL, 5, 301, NULL),
(302, 'annualized', '/ˈænjuəlaɪzd/', 'adjective', '{"zh-TW":["年化的；按年換算的"],"en":["converted to an annual rate or basis"]}', NULL, 'annualized return / annualized growth rate / annualized figure', '[{"en":"The annualized return on the portfolio was twelve percent.","zh-TW":"投資組合的年化回報率為百分之十二。"},{"en":"Annualized GDP growth figures smooth out seasonal fluctuations.","zh-TW":"年化GDP增長數字消除了季節性波動。"}]', '{"verb":"annualize","noun":"annualization"}', NULL, 4, 302, NULL),
(303, 'annuity', '/əˈnjuːɪti/', 'noun', '{"zh-TW":["年金"],"en":["a fixed sum paid annually as retirement or investment income"]}', NULL, 'annuity plan / purchase an annuity / annuity payment', '[{"en":"He invested in an annuity to secure retirement income.","zh-TW":"他投資年金以確保退休收入。"},{"en":"The pension scheme pays a monthly annuity after age 60.","zh-TW":"退休金計劃在60歲後每月支付年金。"}]', '{"adjective":"annuitized"}', NULL, 3, 303, NULL),
(304, 'anomalous', '/əˈnɒmələs/', 'adjective', '{"zh-TW":["異常的；反常的"],"en":["deviating from what is standard or normal"]}', NULL, 'anomalous result / anomalous behavior / anomalous reading', '[{"en":"The anomalous data point was investigated to determine its cause.","zh-TW":"對異常數據點進行了調查以確定其原因。"},{"en":"Anomalous voting patterns triggered an audit of the election results.","zh-TW":"異常的投票模式觸發了對選舉結果的審計。"}]', '{"adverb":"anomalously","noun":"anomaly"}', NULL, 3, 304, NULL),
(305, 'anomaly', '/''əˌnɒməli/', 'noun', '{"zh-TW":["異常；例外；不規則現象"],"en":["something that deviates from what is standard, normal, or expected"]}', NULL, 'detect an anomaly / statistical anomaly / identify an anomaly', '[{"en":"The data analyst flagged an anomaly in the sales figures that required investigation.","zh-TW":"數據分析師標記了銷售數字中需要調查的異常情況。"},{"en":"Scientists discovered an anomaly in the experimental results that led to a new hypothesis.","zh-TW":"科學家發現了實驗結果中的異常，引出了一個新假說。"}]', '{"adjective":"anomalous","adverb":"anomalously"}', NULL, 3, 305, NULL),
(306, 'anomaly detection', '/əˈnɒməli dɪˈtekʃən/', 'noun', '{"zh-TW":["異常偵測"],"en":["the identification of patterns that deviate from expected behavior"]}', NULL, 'perform anomaly detection / anomaly detection algorithm / real-time anomaly detection', '[{"en":"Anomaly detection systems flag unusual activity in network traffic.","zh-TW":"異常偵測系統標記網路流量中的異常活動。"},{"en":"Machine learning enhances anomaly detection in fraud prevention.","zh-TW":"機器學習增強了欺詐預防中的異常偵測。"}]', NULL, NULL, 5, 306, NULL),
(307, 'anomie', '/ˈænəmiː/', 'noun', '{"zh-TW":["社會失範；社會解組"],"en":["a state of social instability resulting from breakdown of norms"]}', NULL, 'experience anomie / social anomie / Durkheim''s anomie', '[{"en":"Rapid social change can create anomie by disrupting established norms.","zh-TW":"快速的社會變遷可能通過破壞既定規範來產生社會失範。"},{"en":"Anomie theory explains higher suicide rates during periods of social upheaval.","zh-TW":"失範理論解釋了社會動盪時期較高的自殺率。"}]', '{"adjective":"anomic"}', NULL, 2, 307, NULL),
(308, 'another', '/əˈnʌðər/', 'determiner', '{"zh-TW":["另一個；再一個"],"en":["one more; a different one"]}', NULL, 'one another / another way', '[{"en":"Would you like another cup of tea?","zh-TW":"你想再來一杯茶嗎？"},{"en":"Let''s try another approach.","zh-TW":"讓我們試試另一種方法。"}]', NULL, NULL, 3, 308, NULL),
(309, 'answer', '/ˈænsər/', 'noun', '{"zh-TW":["答案；回覆","答案；回答","回答；答案；接電話"],"en":["a reply","a solution","a reply to a question","a reply; to respond to a question or call"]}', NULL, 'in answer to / answer the phone; answer the phone / in answer to; answer the phone / answer a question / in answer to', '[{"en":"Please answer my email by Friday.","zh-TW":"請在週五前回覆我的電子郵件。"},{"en":"There is no easy answer to this.","zh-TW":"這個問題沒有簡單的答案。"},{"en":"I don''t know the answer.","zh-TW":"我不知道答案。"},{"en":"Please answer the phone.","zh-TW":"請接電話。"},{"en":"Please answer my question.","zh-TW":"請回答我的問題。"},{"en":"Nobody answered the door.","zh-TW":"沒人來應門。"}]', '{"noun":"answer","verb":"answer","adjective":"answerable"}', NULL, 2, 309, NULL),
(310, 'answerable', '/ˈɑːnsərəbl/', 'adjective', '{"zh-TW":["應負責的；應解釋的"],"en":["required to account for actions or decisions to a higher authority"]}', NULL, 'answerable to the board / answerable for decisions', '[{"en":"The manager is answerable to the board for the division''s performance.","zh-TW":"管理者對部門績效向董事會負責。"},{"en":"All executives are answerable for their spending decisions.","zh-TW":"所有高管都應對其支出決策負責。"}]', NULL, NULL, 4, 310, NULL),
(311, 'antecedent', '/ˌæntɪˈsiːdənt/', 'noun', '{"zh-TW":["先行詞；前因"],"en":["something that precedes another; an ancestor or earlier condition"]}', NULL, 'historical antecedent / structural antecedent / causal antecedent', '[{"en":"Understanding the historical antecedents of a conflict is essential for resolution.","zh-TW":"了解衝突的歷史前因對於解決至關重要。"},{"en":"The study identifies antecedents of entrepreneurial intention in students.","zh-TW":"研究識別了學生創業意圖的前因。"}]', '{"adjective":"antecedent"}', NULL, 4, 311, NULL),
(312, 'anthropogenic', '/ˌænθrəpəˈdʒenɪk/', 'adjective', '{"zh-TW":["人為的；人類引起的"],"en":["originating in human activity"]}', NULL, 'anthropogenic emissions / anthropogenic climate change / anthropogenic factors', '[{"en":"Anthropogenic greenhouse gas emissions are the primary driver of global warming.","zh-TW":"人為溫室氣體排放是全球暖化的主要驅動力。"},{"en":"Anthropogenic noise pollution disrupts marine mammal communication.","zh-TW":"人為噪音污染破壞了海洋哺乳動物的溝通。"}]', NULL, NULL, 5, 312, NULL),
(313, 'anti-dumping duty', '/ˌænti ˈdʌmpɪŋ ˈdjuːti/', 'noun', '{"zh-TW":["反傾銷稅"],"en":["a tariff imposed to protect domestic industry from foreign goods sold below cost"]}', NULL, 'impose anti-dumping duties / anti-dumping duty investigation', '[{"en":"The government imposed anti-dumping duties on cheap imported steel.","zh-TW":"政府對進口廉價鋼鐵徵收了反傾銷稅。"},{"en":"An anti-dumping duty investigation requires proof of material injury.","zh-TW":"反傾銷稅調查需要提供實質損害的證明。"}]', NULL, NULL, 5, 313, NULL),
(314, 'antibiotic', '/ˌæntɪbaɪˈɒtɪk/', 'noun', '{"zh-TW":["抗生素"],"en":["a medicine that kills bacteria"]}', NULL, 'take an antibiotic / antibiotic resistance', '[{"en":"The doctor prescribed a course of antibiotics.","zh-TW":"醫生開了一個療程的抗生素。"},{"en":"Do not stop taking antibiotics before the course is finished.","zh-TW":"在療程結束前不要停止服用抗生素。"}]', '{"adjective":"antibiotic"}', NULL, 4, 314, NULL),
(315, 'antibiotic resistance', '/ˌæntɪbaɪˈɒtɪk rɪˈzɪstəns/', 'noun', '{"zh-TW":["抗生素耐藥性"],"en":["the ability of bacteria to withstand antibiotic treatment"]}', NULL, 'combat antibiotic resistance / antibiotic resistance crisis / spread of antibiotic resistance', '[{"en":"Overuse of antibiotics is the primary driver of antibiotic resistance.","zh-TW":"抗生素的過度使用是抗生素耐藥性的主要驅動力。"},{"en":"Antibiotic resistance threatens to make common infections untreatable.","zh-TW":"抗生素耐藥性威脅著使常見感染變得無法治療。"}]', '{"adjective":"antibiotic-resistant"}', NULL, 5, 315, NULL),
(316, 'anticipate', '/ænˈtɪsɪpeɪt/', 'verb', '{"zh-TW":["預期；預料"],"en":["to expect or predict something"]}', '{"prefix":{"text":"anti-","meaning":"before (之前)"},"root":{"text":"cip","meaning":"take (拿)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"在之前就拿取（準備），即「預期」。"}', 'anticipate demand/problems/growth', '[{"en":"We anticipate strong demand for the new product.","zh-TW":"我們預期新產品會有強勁需求。"},{"en":"The delay was not anticipated.","zh-TW":"這個延遲是始料未及的。"}]', '{"noun":"anticipation"}', NULL, 4, 316, 502),
(317, 'antioxidant', '/''æntiˈɒksɪdənt/', 'noun', '{"zh-TW":["抗氧化劑；抗氧化物"],"en":["a substance that prevents or slows damage to cells caused by free radicals"]}', NULL, 'rich in antioxidants / antioxidant supplement / natural antioxidant', '[{"en":"Blueberries and dark chocolate are rich in antioxidants.","zh-TW":"藍莓和黑巧克力富含抗氧化劑。"},{"en":"Many people take antioxidant supplements to support immune health.","zh-TW":"許多人服用抗氧化劑補充品來支持免疫健康。"}]', '{"adjective":"antioxidant-rich"}', NULL, 4, 317, NULL),
(318, 'antitrust', '/ˌæntiˈtrʌst/', 'adjective', '{"zh-TW":["反托拉斯的；反壟斷的"],"en":["relating to legislation preventing monopolistic business practices"]}', NULL, 'antitrust law / antitrust investigation / antitrust violation', '[{"en":"The merger was blocked following an antitrust investigation.","zh-TW":"合併在反托拉斯調查後被阻止了。"},{"en":"Antitrust regulators scrutinize mergers to protect market competition.","zh-TW":"反托拉斯監管機構審查合併以保護市場競爭。"}]', NULL, NULL, 3, 318, NULL),
(319, 'antitrust law', '/ˈæntitrʌst lɔː/', 'noun', '{"zh-TW":["反托拉斯法；競爭法"],"en":["legislation preventing anti-competitive business practices and monopolies"]}', NULL, 'comply with antitrust law / antitrust law investigation', '[{"en":"The merger was blocked by antitrust law authorities on competition grounds.","zh-TW":"合併被反托拉斯法機關以競爭理由阻止了。"},{"en":"Antitrust law promotes fair competition and protects consumer interests.","zh-TW":"反托拉斯法促進公平競爭並保護消費者利益。"}]', '{"synonym":"competition law"}', NULL, 5, 319, NULL),
(320, 'anxious', '/ˈæŋkʃəs/', 'adjective', '{"zh-TW":["焦慮的；擔心的"],"en":["feeling worried or nervous"]}', '{"root":{"text":"anx","meaning":"choke/distress (窒息/痛苦)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿痛苦不安的，即「焦慮的」。"}', 'feel anxious / anxious about', '[{"en":"She felt anxious about the job interview.","zh-TW":"她對工作面試感到焦慮。"},{"en":"He was anxious to hear the results.","zh-TW":"他急切地想知道結果。"}]', '{"noun":"anxiety","adverb":"anxiously"}', NULL, 3, 320, NULL),
(321, 'anybody', '/ˈɛnibɒdi/', 'pronoun', '{"zh-TW":["任何人"],"en":["any person at all"]}', NULL, 'anybody else / not anybody', '[{"en":"Is anybody home?","zh-TW":"有人在家嗎？"},{"en":"Anybody can learn to cook.","zh-TW":"任何人都能學會做飯。"}]', NULL, NULL, 3, 321, NULL),
(322, 'anyone', '/ˈeniwʌn/', 'pronoun', '{"zh-TW":["任何人"],"en":["any person; it doesn''t matter who"]}', NULL, 'anyone else', '[{"en":"Is anyone here?","zh-TW":"有人在嗎？"},{"en":"Anyone can apply for this position.","zh-TW":"任何人都可以申請這個職位。"}]', NULL, NULL, 2, 322, NULL),
(323, 'anything', '/ˈɛniθɪŋ/', 'pronoun', '{"zh-TW":["任何事物"],"en":["any thing at all","any thing; it doesn''t matter what"]}', NULL, 'anything else / not anything; anything else / if anything', '[{"en":"Is there anything I can do?","zh-TW":"有什麼我能做的嗎？"},{"en":"She didn''t say anything.","zh-TW":"她什麼都沒說。"},{"en":"Is there anything I can help with?","zh-TW":"有什麼我可以幫忙的嗎？"},{"en":"I''ll do anything to pass the exam.","zh-TW":"我會做任何事來通過考試。"}]', NULL, NULL, 3, 323, NULL),
(324, 'anywhere', '/ˈɛniwɛr/', 'adverb', '{"zh-TW":["任何地方"],"en":["in or to any place"]}', NULL, 'anywhere else / not anywhere', '[{"en":"You can sit anywhere you like.","zh-TW":"你可以坐任何你喜歡的位置。"},{"en":"I can''t find it anywhere.","zh-TW":"我哪裡都找不到它。"}]', NULL, NULL, 3, 324, NULL),
(325, 'apart', '/əˈpɑːrt/', 'adverb', '{"zh-TW":["分開地；相隔"],"en":["separated by distance or time"]}', NULL, 'apart from / fall apart', '[{"en":"They live far apart.","zh-TW":"他們住得很遠。"},{"en":"The old building is falling apart.","zh-TW":"那棟老建築正在坍塌。"}]', NULL, NULL, 2, 325, NULL),
(326, 'apartheid', '/əˈpɑːrtaɪd/', 'noun', '{"zh-TW":["種族隔離"],"en":["a former system of institutional racial segregation in South Africa; any analogous form of segregation"]}', NULL, 'apartheid regime / post-apartheid / apartheid era', '[{"en":"Nelson Mandela led the movement to end apartheid in South Africa.","zh-TW":"納爾遜·曼德拉領導了終結南非種族隔離的運動。"},{"en":"Social apartheid persists when economic inequality limits access to opportunity.","zh-TW":"當經濟不平等限制獲得機會時，社會隔離就會持續存在。"}]', NULL, NULL, 3, 326, NULL),
(327, 'apartment', '/əˈpɑːrtmənt/', 'noun', '{"zh-TW":["公寓"],"en":["a residential unit in a building","a set of rooms for living in, usually on one floor of a building"]}', NULL, 'apartment complex / rent an apartment; apartment building / studio apartment', '[{"en":"She rents an apartment near the office.","zh-TW":"她在辦公室附近租了一間公寓。"},{"en":"The apartment comes fully furnished.","zh-TW":"這間公寓有全套家具。"},{"en":"They rented a two-bedroom apartment.","zh-TW":"他們租了一間兩房公寓。"},{"en":"The apartment complex has a swimming pool.","zh-TW":"這個公寓大樓有游泳池。"}]', '{"noun":"apartment"}', NULL, 3, 327, NULL),
(328, 'aperitif', '/əˈpɛrɪtiːf/', 'noun', '{"zh-TW":["餐前酒；開胃飲料"],"en":["an alcoholic drink served before a meal"]}', NULL, 'order an aperitif / classic aperitif', '[{"en":"The waiter offered an aperitif while we looked at the menu.","zh-TW":"我們看菜單時，服務生提供了餐前酒。"},{"en":"A dry sherry is a popular aperitif in Spain.","zh-TW":"干雪利酒是西班牙受歡迎的餐前酒。"}]', NULL, NULL, 3, 328, NULL),
(329, 'aphorism', '/ˈæfərɪzəm/', 'noun', '{"zh-TW":["格言；警句"],"en":["a short pithy statement expressing a general truth"]}', NULL, 'memorable aphorism / classical aphorism / witty aphorism', '[{"en":"The essay opens with an aphorism that summarizes its central argument.","zh-TW":"文章以一句概括其核心論點的格言開頭。"},{"en":"Aphorisms distill complex wisdom into a single memorable phrase.","zh-TW":"格言將複雜的智慧濃縮成一句令人難忘的話。"}]', '{"adjective":"aphoristic"}', NULL, 3, 329, NULL),
(330, 'API', '/ˌeɪ piː ˈaɪ/', 'noun', '{"zh-TW":["應用程式介面"],"en":["application programming interface; allows software systems to communicate"]}', NULL, 'API integration / RESTful API / open API / API documentation', '[{"en":"The API allows third-party developers to build on the platform.","zh-TW":"API允許第三方開發者在平台上構建應用程式。"},{"en":"Seamless API integration was key to the digital transformation project.","zh-TW":"無縫的API整合是數位轉型項目的關鍵。"}]', '{"full form":"application programming interface"}', NULL, 1, 330, NULL),
(331, 'API endpoint', '/eɪ piː aɪ ˈendpɔɪnt/', 'noun', '{"zh-TW":["API端點"],"en":["a specific URL where an API receives requests"]}', NULL, 'call an API endpoint / expose an API endpoint / secure an API endpoint', '[{"en":"Each API endpoint handles a specific type of request.","zh-TW":"每個API端點處理特定類型的請求。"},{"en":"The developer documented all API endpoints for frontend integration.","zh-TW":"開發者記錄了所有API端點以供前端整合。"}]', NULL, NULL, 4, 331, NULL),
(332, 'API gateway', '/eɪ piː aɪ ˈɡeɪtweɪ/', 'noun', '{"zh-TW":["API閘道"],"en":["a server that acts as an entry point for client requests to backend services"]}', NULL, 'deploy an API gateway / configure an API gateway / API gateway security', '[{"en":"The API gateway handles authentication, rate limiting, and load balancing.","zh-TW":"API閘道處理身份驗證、速率限制和負載平衡。"},{"en":"An API gateway simplifies microservices architecture for clients.","zh-TW":"API閘道為客戶端簡化微服務架構。"}]', NULL, NULL, 4, 332, NULL),
(333, 'apology', 'əˈpɒlədʒi', 'noun', '{"zh-TW":["道歉；歉意","辯護"],"en":["an expression of regret","a statement of being sorry"]}', NULL, 'offer an apology/formal apology', '[{"en":"Please accept our sincere apology for the delay.","zh-TW":"請接受我們對延誤的誠摯道歉。"}]', '{"verb":"apologize","adjective":"apologetic","adverb":"apologetically"}', NULL, 3, 333, NULL),
(334, 'apparent', '/əˈpærənt/', 'adjective', '{"zh-TW":["明顯的；顯然的"],"en":["clearly visible or understood; obvious"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"par","meaning":"appear (出現)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"朝向出現的，即「明顯的」。"}', 'become apparent / for no apparent reason', '[{"en":"It became apparent that the project would exceed budget.","zh-TW":"很明顯該專案將超出預算。"},{"en":"The benefits are apparent to everyone involved.","zh-TW":"好處對所有相關人員都是顯而易見的。"}]', '{"adverb":"apparently"}', NULL, 3, 334, NULL),
(335, 'appeal', '/əˈpiːl/', 'verb', '{"zh-TW":["呼籲；上訴","吸引","吸引；呼籲；上訴"],"en":["to make a serious request","to be attractive or interesting","to attract or be interesting"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"peal","meaning":"drive/push (推動)"},"logic":"朝向推動人，即「呼籲、吸引」。"}', 'appeal to / appeal a decision; appeal to / appeal a decision / sex appeal', '[{"en":"The product appeals to health-conscious consumers.","zh-TW":"該產品吸引注重健康的消費者。"},{"en":"The company plans to appeal the court''s decision.","zh-TW":"公司計劃對法院判決提出上訴。"},{"en":"The idea doesn''t appeal to me.","zh-TW":"這個想法不吸引我。"},{"en":"They appealed the court''s decision.","zh-TW":"他們對法院的判決提出上訴。"}]', '{"adjective":"appealing","noun":"appeal"}', NULL, 2, 335, 503),
(336, 'appear', '/əˈpɪər/', 'verb', '{"zh-TW":["出現；似乎","出現；似乎；看起來"],"en":["to become visible","to seem or give the impression","to become visible; to seem"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"pear","meaning":"be visible (可見)"},"logic":"朝向可見，即「出現」。"}', 'appear to be / appear on/in; appear to be / appear in; appear to be / it appears that', '[{"en":"The error appears to have been corrected.","zh-TW":"這個錯誤似乎已被更正。"},{"en":"New opportunities appear as the market evolves.","zh-TW":"隨著市場發展，新機會不斷出現。"},{"en":"Stars appear at night.","zh-TW":"星星在夜晚出現。"},{"en":"He appears to be happy.","zh-TW":"他看起來很開心。"},{"en":"A new store appeared on our street.","zh-TW":"一家新店出現在我們的街上。"},{"en":"He appears to be very busy.","zh-TW":"他看起來非常忙碌。"}]', '{"noun":"appearance","adjective":"apparent","adverb":"apparently"}', NULL, 2, 336, NULL),
(337, 'appellate', '/əˈpelɪt/', 'adjective', '{"zh-TW":["上訴的；具有上訴管轄權的"],"en":["relating to legal appeals"]}', NULL, 'appellate court / appellate jurisdiction / appellate review', '[{"en":"The case was appealed to the appellate court for further review.","zh-TW":"案件被上訴至上訴法院進行進一步審查。"},{"en":"Appellate decisions set precedents that lower courts must follow.","zh-TW":"上訴法院的決定確立了下級法院必須遵循的先例。"}]', '{"noun":"appellant"}', NULL, 3, 337, NULL),
(338, 'appendix', '/əˈpɛndɪks/', 'noun', '{"zh-TW":["附錄；附件"],"en":["additional material at the end of a document"]}', NULL, 'see the appendix / attached appendix', '[{"en":"Detailed financial data can be found in the appendix.","zh-TW":"詳細的財務數據可以在附錄中找到。"},{"en":"Please refer to Appendix C for the supporting documentation.","zh-TW":"請參閱附錄C獲取支持文件。"}]', '{"plural":"appendices"}', NULL, 3, 338, NULL),
(339, 'appetizer', '/ˈæpɪtaɪzər/', 'noun', '{"zh-TW":["開胃菜；前菜"],"en":["a small dish served before the main course"]}', NULL, 'order an appetizer / light appetizer', '[{"en":"We shared a few appetizers before the main course.","zh-TW":"我們在主菜前共享了幾道開胃菜。"},{"en":"The appetizer menu includes soup and salad options.","zh-TW":"開胃菜菜單包含湯品和沙拉選項。"}]', '{"adjective":"appetizing"}', NULL, 3, 339, NULL),
(340, 'apple', '/ˈæpl/', 'noun', '{"zh-TW":["蘋果"],"en":["a round fruit with red, green, or yellow skin"]}', NULL, 'apple pie / apple juice', '[{"en":"An apple a day keeps the doctor away.","zh-TW":"一天一蘋果，醫生遠離我。"},{"en":"She bought some apples at the market.","zh-TW":"她在市場買了一些蘋果。"}]', NULL, NULL, 2, 340, NULL),
(341, 'applicability', '/ˌæplɪkəˈbɪlɪti/', 'noun', '{"zh-TW":["適用性；適用範圍"],"en":["the quality of being relevant or appropriate"]}', NULL, 'applicability of a rule / wide applicability', '[{"en":"Check the applicability of the policy to your department.","zh-TW":"查看該政策對您部門的適用性。"},{"en":"The new regulation has wide applicability across industries.","zh-TW":"新法規在各行業具有廣泛的適用性。"}]', '{"adjective":"applicable","verb":"apply"}', NULL, 5, 341, NULL),
(342, 'applicable', '/əˈplɪkəbl/', 'adjective', '{"zh-TW":["適用的；可應用的"],"en":["relevant or appropriate to a situation"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠朝向應用的，即「適用的」。"}', 'applicable to / where applicable', '[{"en":"This discount is applicable to orders over $100.","zh-TW":"此折扣適用於超過100美元的訂單。"},{"en":"Please fill in all applicable fields on the form.","zh-TW":"請填寫表格上所有適用的欄位。"}]', '{"noun":"applicability"}', NULL, 4, 342, 264),
(343, 'applicable law', '/ˈæplɪkəbl lɔː/', 'noun', '{"zh-TW":["適用法律"],"en":["the body of law that governs a contract or transaction"]}', NULL, 'specify applicable law / under applicable law', '[{"en":"The contract is governed by and construed in accordance with applicable law.","zh-TW":"合約受適用法律管轄並依其解釋。"},{"en":"Both parties agreed that applicable law would be English law.","zh-TW":"雙方同意適用法律為英國法律。"}]', NULL, NULL, 5, 343, NULL),
(344, 'applicant', '/ˈæplɪkənt/', 'noun', '{"zh-TW":["申請人；應徵者"],"en":["a person who applies for something"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-ant","meaning":"person who (…的人)"},"logic":"朝向應用的人，即「申請人」。"}', 'job applicant / successful applicant', '[{"en":"We received over 200 applicants for the position.","zh-TW":"我們收到了超過200位該職位的應徵者。"},{"en":"Successful applicants will be notified by email.","zh-TW":"錄取者將以電子郵件通知。"}]', '{"noun":"application","verb":"apply"}', NULL, 3, 344, NULL),
(345, 'application', '/ˌæplɪˈkeɪʃən/', 'noun', '{"zh-TW":["應用程式；申請"],"en":["a computer program; a formal request"]}', NULL, 'mobile application / job application', '[{"en":"Download the application from the store.","zh-TW":"從商店下載這個應用程式。"},{"en":"I submitted my job application.","zh-TW":"我提交了工作申請。"}]', '{"verb":"apply","noun2":"applicant"}', NULL, 4, 345, 7),
(346, 'application programming interface', '/ˌæplɪˈkeɪʃən ˌproʊɡræmɪŋ ˈɪntərfeɪs/', 'noun', '{"zh-TW":["應用程式介面"],"en":["a set of rules allowing different software applications to communicate"]}', NULL, 'API integration / REST API / API documentation', '[{"en":"The payment gateway connects via an API to our e-commerce platform.","zh-TW":"支付閘道通過API連接到我們的電子商務平台。"},{"en":"Developers used the API to build a mobile application.","zh-TW":"開發人員使用API構建了行動應用程式。"}]', '{"abbreviation":"API"}', NULL, 5, 346, NULL),
(347, 'apply', '/əˈplaɪ/', 'verb', '{"zh-TW":["申請；應用"],"en":["to make a formal request","to put into operation or use"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"ply","meaning":"fold (折疊/靠近)"},"logic":"朝向靠近，即「申請、應用」。"}', 'apply for a job / apply knowledge', '[{"en":"She applied for the marketing manager position.","zh-TW":"她應徵了行銷經理職位。"},{"en":"Students learn how to apply theory to practice.","zh-TW":"學生學習如何將理論應用於實踐。"}]', '{"noun":"application","adjective":"applicable"}', NULL, 2, 347, NULL),
(348, 'appoint', '/əˈpɔɪnt/', 'verb', '{"zh-TW":["任命；指定"],"en":["to officially choose someone for a position"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"point","meaning":"point (指)"},"logic":"朝向指定某人，即「任命」。"}', 'appoint a director/representative', '[{"en":"The board appointed a new chief financial officer.","zh-TW":"董事會任命了新的財務長。"},{"en":"She was appointed to lead the project team.","zh-TW":"她被指定領導專案團隊。"}]', '{"noun":"appointment"}', NULL, 3, 348, 8),
(349, 'appointment', '/əˈpɔɪntmənt/', 'noun', '{"zh-TW":["預約；約診"],"en":["an arrangement to meet a doctor at a set time"]}', NULL, 'make an appointment / doctor appointment', '[{"en":"I need to make an appointment with my doctor.","zh-TW":"我需要預約我的醫生。"},{"en":"Please arrive ten minutes before your appointment.","zh-TW":"請在預約時間前十分鐘到達。"}]', '{"verb":"appoint","adjective":"appointed"}', NULL, 4, 349, 504);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(350, 'apportion', '/əˈpɔːrʃən/', 'verb', '{"zh-TW":["分攤；分配"],"en":["to divide and allocate something among parties"]}', NULL, 'apportion costs / apportion responsibility / apportion blame', '[{"en":"Costs were apportioned equally between the three departments.","zh-TW":"費用在三個部門之間平均分攤。"},{"en":"Responsibility was apportioned based on each party''s contribution.","zh-TW":"責任根據各方的貢獻進行了分攤。"}]', '{"noun":"apportionment"}', NULL, 3, 350, 984),
(351, 'apportionment', '/əˈpɔːrʃənmənt/', 'noun', '{"zh-TW":["分攤；分配"],"en":["the division of something among several parties"]}', NULL, 'cost apportionment / apportionment of expenses', '[{"en":"The apportionment of shared costs was agreed between divisions.","zh-TW":"共同成本的分攤在各部門之間達成了一致。"},{"en":"An equitable apportionment method was used for overhead allocation.","zh-TW":"採用了公平的分攤方法分配間接費用。"}]', '{"verb":"apportion"}', NULL, 5, 351, NULL),
(352, 'appraisal', '/əˈpreɪzəl/', 'noun', '{"zh-TW":["績效考核；評估"],"en":["a formal assessment of an employee''s job performance"]}', NULL, 'performance appraisal / annual appraisal / appraisal interview', '[{"en":"She received positive feedback during her annual appraisal.","zh-TW":"她在年度考核中收到了正面的反饋。"},{"en":"The appraisal system was redesigned to align with company values.","zh-TW":"考核制度被重新設計以與公司價值觀保持一致。"}]', '{"verb":"appraise","noun":"appraiser"}', NULL, 3, 352, 505),
(353, 'appraisal cycle', '/əˈpreɪzəl ˈsaɪkəl/', 'noun', '{"zh-TW":["考核週期"],"en":["the recurring schedule of performance evaluations in an organization"]}', NULL, 'annual appraisal cycle / mid-year appraisal cycle', '[{"en":"The annual appraisal cycle runs from January to December.","zh-TW":"年度考核週期從一月到十二月。"},{"en":"Employees set goals at the start of each appraisal cycle.","zh-TW":"員工在每個考核週期開始時設定目標。"}]', NULL, NULL, 5, 353, NULL),
(354, 'appraise', '/əˈpreɪz/', 'verb', '{"zh-TW":["評估；鑑定"],"en":["to assess the value or quality of something"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"praise","meaning":"price/value (價值)"},"logic":"朝向評定價值，即「評估」。"}', 'appraise performance/property/value', '[{"en":"The property was appraised at $1.2 million.","zh-TW":"該房產被估價為120萬美元。"},{"en":"Managers appraise staff performance annually.","zh-TW":"經理每年評估員工績效。"}]', '{"noun":"appraisal"}', NULL, 3, 354, NULL),
(355, 'appreciate', '/əˈpriːʃieɪt/', 'verb', '{"zh-TW":["【主要意義-動詞】感激；欣賞","【次要意義-動詞】理解；意識到（某事的重要性/困難）","【次要意義-動詞】（資產）升值；增值"],"en":["[primary] to recognize and enjoy the value of something; to be grateful","[secondary] to fully understand a situation or problem","[secondary] to increase in value over time"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"preci","meaning":"price/value (價值)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"朝向認識價值，即「感謝、增值」。"}', 'appreciate the difficulty / appreciate your support / property appreciates', '[{"en":"I appreciate the difficulty of implementing these changes within one week.","zh-TW":"我理解在一周內實施這些變更的難度。"},{"en":"Real estate in the area has appreciated significantly over the past decade.","zh-TW":"該地區的房地產在過去十年中大幅升值。"},{"en":"We appreciate your patience while we resolve the technical issues.","zh-TW":"我們感謝您在我們解決技術問題期間的耐心等待。"}]', '{"noun":"appreciation","adjective":"appreciative"}', 'appreciate 的次要意義：「理解/意識到」（appreciate the complexity = 理解複雜性）和「升值」（assets appreciate），在 TOEIC 財務和商業文章中常見，考生常誤以為只有「感激/欣賞」的意思。', 4, 355, 265),
(356, 'appreciation', '/əˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["感謝；升值；欣賞"],"en":["gratitude; or an increase in value"]}', NULL, 'express appreciation / currency appreciation', '[{"en":"We wish to express our appreciation for your support.","zh-TW":"我們謹向您的支持表示感謝。"},{"en":"The appreciation of the property value doubled their investment.","zh-TW":"房產增值使他們的投資翻了一倍。"}]', '{"verb":"appreciate","adjective":"appreciated"}', NULL, 4, 356, NULL),
(357, 'apprehensive', '/''æprɪˌhensɪv/', 'adjective', '{"zh-TW":["憂慮的；擔心的"],"en":["anxious or fearful that something bad or unpleasant will happen"]}', NULL, 'apprehensive about / feel apprehensive / apprehensive of', '[{"en":"She was apprehensive about her first day at the new job.","zh-TW":"她對新工作的第一天感到擔心。"},{"en":"The entire team was apprehensive about the upcoming performance review.","zh-TW":"整個團隊都對即將到來的績效評估感到憂慮。"}]', '{"adverb":"apprehensively","noun":"apprehension"}', NULL, 4, 357, NULL),
(358, 'apprenticeship', '/''əˈprentɪsʃɪp/', 'noun', '{"zh-TW":["學徒期；學徒訓練"],"en":["a period of time working as an apprentice under a skilled worker to learn a trade or profession"]}', NULL, 'serve an apprenticeship / complete an apprenticeship / formal apprenticeship', '[{"en":"She completed a three-year apprenticeship before becoming a licensed electrician.","zh-TW":"她在成為持牌電工之前完成了為期三年的學徒訓練。"},{"en":"Apprenticeships offer a practical alternative to university education.","zh-TW":"學徒制提供了一種大學教育的實際替代選擇。"}]', '{"noun":"apprentice"}', NULL, 5, 358, NULL),
(359, 'approach', '/əˈprəʊtʃ/', 'noun', '{"zh-TW":["方法；途徑","接近"],"en":["a way of dealing with something","the act of coming near"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"proach","meaning":"near (靠近)"},"logic":"朝向靠近，即「接近、方法」。"}', 'approach to / new approach', '[{"en":"We need a fresh approach to this problem.","zh-TW":"我們需要一個解決此問題的新方法。"},{"en":"The deadline is approaching rapidly.","zh-TW":"截止日期正在迅速逼近。"}]', '{"adjective":"approachable"}', NULL, 3, 359, NULL),
(360, 'appropriate', '/əˈprəʊpriət/', 'adjective', '{"zh-TW":["適當的；恰當的","適當的"],"en":["suitable or proper in the circumstances","suitable or proper for the circumstances"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"propri","meaning":"own (自己的)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"朝向自己所有的，即「適當的」。"}', 'appropriate measures/behavior/response; appropriate behavior / appropriate response', '[{"en":"Please dress in appropriate business attire.","zh-TW":"請穿著適當的商務服裝。"},{"en":"The manager took appropriate action.","zh-TW":"經理採取了適當的行動。"},{"en":"Jeans are not appropriate for a formal dinner.","zh-TW":"牛仔褲不適合正式晚宴。"},{"en":"Please wear appropriate clothing.","zh-TW":"請穿著合適的服裝。"}]', '{"adverb":"appropriately","noun":"appropriateness"}', NULL, 4, 360, 266),
(361, 'appropriate funds', '/əˈproʊpriɪt fʌndz/', 'verb', '{"zh-TW":["撥款"],"en":["to set aside money for a specific official purpose"]}', NULL, 'appropriate funds for research / appropriated budget', '[{"en":"Congress appropriated additional funds for the disaster relief effort.","zh-TW":"國會為災難救援工作撥出了額外資金。"},{"en":"The board appropriated reserves to cover the unexpected expenses.","zh-TW":"董事會撥出了儲備金以支付意外費用。"}]', NULL, NULL, 5, 361, NULL),
(362, 'appropriation', '/əˌproʊpriˈeɪʃən/', 'noun', '{"zh-TW":["撥款；撥用"],"en":["the setting aside of funds for a specific purpose or authorized use"]}', NULL, 'budget appropriation / government appropriation', '[{"en":"The board approved the appropriation of $2 million for the R&D project.","zh-TW":"董事會批准了200萬元用於研發項目的撥款。"},{"en":"Government appropriations for infrastructure were increased in the budget.","zh-TW":"預算中增加了用於基礎設施的政府撥款。"}]', '{"verb":"appropriate"}', NULL, 5, 362, NULL),
(363, 'approval', '/əˈpruːvəl/', 'noun', '{"zh-TW":["批准；認可"],"en":["official agreement or permission"]}', NULL, 'require approval / pending approval', '[{"en":"Final approval is required from the board of directors.","zh-TW":"需要董事會的最終批准。"},{"en":"The budget proposal awaits management approval.","zh-TW":"預算提案正等待管理層批准。"}]', '{"verb":"approve","adjective":"approved"}', NULL, 3, 363, 9),
(364, 'approval process', '/əˈpruːvəl ˈprɒses/', 'noun', '{"zh-TW":["審批流程"],"en":["the formal steps required to review and authorize decisions or transactions"]}', NULL, 'follow the approval process / approval process delays', '[{"en":"All capital expenditures must go through the approval process.","zh-TW":"所有資本支出必須通過審批流程。"},{"en":"Streamlining the approval process reduced decision-making time by half.","zh-TW":"簡化審批流程將決策時間縮短了一半。"}]', NULL, NULL, 5, 364, NULL),
(365, 'approve', '/əˈpruːv/', 'verb', '{"zh-TW":["批准；核准","贊成"],"en":["to officially agree to or accept","to believe that something is good"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"prove","meaning":"test/good (驗證/好)"},"logic":"朝向好的，即「批准」。"}', 'approve a request/budget/plan', '[{"en":"The board approved the annual budget.","zh-TW":"董事會批准了年度預算。"},{"en":"The proposal was approved unanimously.","zh-TW":"該提案被一致通過。"}]', '{"noun":"approval"}', NULL, 3, 365, NULL),
(366, 'approved', 'əˈpruːvd', 'adjective', '{"zh-TW":["已批准的；獲批的","認可的"],"en":["officially accepted","meeting required standards"]}', NULL, 'approved supplier/approved budget', '[{"en":"Only approved vendors may be used.","zh-TW":"只能使用已批准的供應商。"}]', '{"verb":"approve","noun":"approval"}', NULL, 3, 366, NULL),
(367, 'approved vendor list', '/əˈpruːvd ˈvendər lɪst/', 'noun', '{"zh-TW":["核准供應商名單"],"en":["a list of suppliers that have been evaluated and approved for procurement use"]}', NULL, 'add to the approved vendor list / approved vendor list audit', '[{"en":"Only suppliers on the approved vendor list can receive purchase orders.","zh-TW":"只有在核准供應商名單上的供應商才能收到採購訂單。"},{"en":"The approved vendor list is reviewed annually for quality and compliance.","zh-TW":"核准供應商名單每年審查一次品質和合規情況。"}]', NULL, NULL, 5, 367, NULL),
(368, 'approximate', '/əˈprɒksɪmət/', 'adjective', '{"zh-TW":["大約的；近似的"],"en":["close to the actual but not completely exact"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"proxim","meaning":"nearest (最近)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"朝向最近的，即「近似的」。"}', 'approximate cost/time/value', '[{"en":"The approximate cost of the project is $500,000.","zh-TW":"該專案的大約成本為50萬美元。"},{"en":"Can you give me an approximate delivery date?","zh-TW":"你能給我一個大約的交貨日期嗎？"}]', '{"adverb":"approximately","noun":"approximation"}', NULL, 4, 368, NULL),
(369, 'approximately', '/əˈprɒksɪmətli/', 'adverb', '{"zh-TW":["大約"],"en":["close to an exact amount but not completely accurate"]}', '{"prefix":{"text":"ap-","meaning":"to (朝向)"},"root":{"text":"proxim","meaning":"near (接近)"},"suffix":{"text":"-ately","meaning":"in manner of (以…方式)"},"logic":"以接近的方式，即「大約」。"}', 'approximately 100 / takes approximately', '[{"en":"The project will take approximately six months.","zh-TW":"這個專案大約需要六個月。"},{"en":"Approximately 200 people attended the event.","zh-TW":"大約200人參加了活動。"}]', '{"adjective":"approximate","verb":"approximate","noun":"approximation"}', NULL, 5, 369, 10),
(370, 'apt', '/æpt/', 'adjective', '{"zh-TW":["恰當的；適合的"],"en":["appropriate or suitable in the circumstances"]}', NULL, 'apt description / apt choice', '[{"en":"She made an apt comparison between the two strategies.","zh-TW":"她在兩種策略之間做了恰當的比較。"},{"en":"His concise summary was an apt way to end the presentation.","zh-TW":"他的簡明摘要是結束簡報的恰當方式。"}]', '{"adverb":"aptly","noun":"aptness"}', NULL, 1, 370, NULL),
(371, 'aptitude test', '/ˈæptɪtjuːd tɛst/', 'noun', '{"zh-TW":["性向測驗；能力傾向測試"],"en":["a test measuring a person''s ability or potential"]}', NULL, 'take an aptitude test / aptitude test score', '[{"en":"The company uses aptitude tests to screen candidates.","zh-TW":"公司使用性向測驗篩選候選人。"},{"en":"Her aptitude test results showed strong analytical skills.","zh-TW":"她的性向測驗結果顯示出強大的分析能力。"}]', NULL, NULL, 5, 371, NULL),
(372, 'arbitrage', '/ˈɑːrbɪtrɑːʒ/', 'noun', '{"zh-TW":["套利"],"en":["profiting from price differences of the same asset in different markets"]}', NULL, 'risk arbitrage / currency arbitrage / exploit arbitrage opportunities', '[{"en":"Traders engage in arbitrage to profit from price discrepancies.","zh-TW":"交易者進行套利以從價格差異中獲利。"},{"en":"Arbitrage opportunities quickly disappear in efficient markets.","zh-TW":"套利機會在有效市場中迅速消失。"}]', '{"verb":"arbitrage","noun":"arbitrageur"}', NULL, 3, 372, NULL),
(373, 'arbitrageur', '/ˌɑːrbɪtrɑːˈʒɜːr/', 'noun', '{"zh-TW":["套利者"],"en":["a person who engages in arbitrage transactions"]}', NULL, 'market arbitrageur / merger arbitrageur / skilled arbitrageur', '[{"en":"The arbitrageur profited from price discrepancies across exchanges.","zh-TW":"套利者從交易所之間的價格差異中獲利。"},{"en":"Arbitrageurs help make markets more efficient.","zh-TW":"套利者有助於使市場更有效率。"}]', '{"noun2":"arbitrage","verb":"arbitrage"}', NULL, 4, 373, NULL),
(374, 'arbitral tribunal', '/ˈɑːrbɪtrəl traɪˈbjuːnəl/', 'noun', '{"zh-TW":["仲裁庭"],"en":["a panel of arbitrators that hears and decides a dispute"]}', NULL, 'convene an arbitral tribunal / establish an arbitral tribunal / arbitral tribunal award', '[{"en":"The parties agreed to submit the dispute to an arbitral tribunal.","zh-TW":"雙方同意將爭議提交仲裁庭。"},{"en":"The arbitral tribunal issued its award after six months of proceedings.","zh-TW":"仲裁庭在六個月的程序後發布了裁決。"}]', NULL, NULL, 5, 374, NULL),
(375, 'arbitrary', '/''ɑːrbɪtrɪri/', 'adjective', '{"zh-TW":["任意的；武斷的"],"en":["based on random choice or personal whim, rather than any reason or system"]}', NULL, 'arbitrary decision / arbitrary rule / arbitrary limit', '[{"en":"The policy seemed arbitrary and employees questioned its rationale.","zh-TW":"政策看起來很任意，員工們質疑其依據。"},{"en":"Setting an arbitrary deadline without considering workload leads to poor outcomes.","zh-TW":"在不考慮工作量的情況下設定任意截止日期會導致不良結果。"}]', '{"adverb":"arbitrarily","noun":"arbitrariness"}', NULL, 3, 375, NULL),
(376, 'arbitrate', '/ˈɑːrbɪtreɪt/', 'verb', '{"zh-TW":["仲裁；裁決"],"en":["to act as an impartial judge to resolve a dispute between parties"]}', NULL, 'arbitrate a dispute / arbitrate between parties', '[{"en":"An independent expert was appointed to arbitrate the contract dispute.","zh-TW":"任命了一名獨立專家仲裁合約糾紛。"},{"en":"The two sides agreed to arbitrate rather than go to court.","zh-TW":"雙方同意進行仲裁而不是上法院。"}]', '{"noun":"arbitration","noun2":"arbitrator"}', NULL, 3, 376, 646),
(377, 'arbitration', '/ˌɑːrbɪˈtreɪʃən/', 'noun', '{"zh-TW":["仲裁"],"en":["a method of resolving disputes outside of court using a neutral third party"]}', NULL, 'binding arbitration / arbitration clause / submit to arbitration / arbitration hearing', '[{"en":"The contract included an arbitration clause to resolve disputes.","zh-TW":"合約包含仲裁條款以解決糾紛。"},{"en":"Arbitration is faster and cheaper than litigation for commercial disputes.","zh-TW":"仲裁比訴訟更快且更便宜解決商業糾紛。"}]', '{"verb":"arbitrate","noun":"arbitrator"}', NULL, 4, 377, 749),
(378, 'arbitration agreement', '/ˌɑːrbɪˈtreɪʃən əˈɡriːmənt/', 'noun', '{"zh-TW":["仲裁協議"],"en":["a contract requiring parties to resolve disputes through arbitration"]}', NULL, 'sign an arbitration agreement / enforce an arbitration agreement', '[{"en":"The parties entered an arbitration agreement to avoid costly litigation.","zh-TW":"雙方簽訂了仲裁協議以避免代價高昂的訴訟。"},{"en":"An arbitration agreement specifies the governing rules and venue.","zh-TW":"仲裁協議規定了管轄規則和地點。"}]', NULL, NULL, 5, 378, NULL),
(379, 'arbitration clause', '/ˌɑːrbɪˈtreɪʃən klɔːz/', 'noun', '{"zh-TW":["仲裁條款"],"en":["a provision in a contract requiring disputes to be resolved by arbitration"]}', NULL, 'include an arbitration clause / binding arbitration clause', '[{"en":"The arbitration clause prevented costly court proceedings.","zh-TW":"仲裁條款防止了代價高昂的法庭訴訟。"},{"en":"Both parties agreed to include an arbitration clause in the contract.","zh-TW":"雙方同意在合約中加入仲裁條款。"}]', NULL, NULL, 5, 379, NULL),
(380, 'arbitrator', '/ˈɑːrbɪtreɪtər/', 'noun', '{"zh-TW":["仲裁人；仲裁員"],"en":["an independent person appointed to settle a dispute"]}', NULL, 'appoint an arbitrator / neutral arbitrator', '[{"en":"An independent arbitrator was appointed to resolve the pay dispute.","zh-TW":"任命了一名獨立仲裁員解決薪資糾紛。"},{"en":"The arbitrator''s decision is binding on both parties.","zh-TW":"仲裁員的裁決對雙方均具有約束力。"}]', '{"verb":"arbitrate","noun":"arbitration"}', NULL, 4, 380, NULL),
(381, 'archetype', '/ˈɑːrkɪtaɪp/', 'noun', '{"zh-TW":["原型；典型"],"en":["a very typical example of a certain person or thing"]}', NULL, 'cultural archetype / Jungian archetype / classic archetype', '[{"en":"The hero is a universal archetype found in all cultures.","zh-TW":"英雄是在所有文化中都能找到的普遍原型。"},{"en":"She became the archetype of the successful female entrepreneur.","zh-TW":"她成為成功女性企業家的典型代表。"}]', '{"adjective":"archetypal","adverb":"archetypally"}', NULL, 3, 381, NULL),
(382, 'architect', '/ˈɑːrkɪtekt/', 'noun', '{"zh-TW":["建築師"],"en":["a person who designs buildings"]}', '{"prefix":{"text":"archi-","meaning":"chief (首席)"},"root":{"text":"tect","meaning":"builder (建造者)"},"logic":"首席建造者，即「建築師」。"}', 'architect firm / landscape architect', '[{"en":"The architect designed a modern office building.","zh-TW":"建築師設計了一棟現代辦公大樓。"},{"en":"She hired an architect to redesign her home.","zh-TW":"她聘請建築師重新設計她的房子。"}]', '{"noun":"architecture","adjective":"architectural"}', NULL, 3, 382, NULL),
(383, 'archive', '/ˈɑːrkaɪv/', 'noun', '{"zh-TW":["檔案庫；存檔"],"en":["a collection of historical documents or records"]}', NULL, 'company archive / archive files', '[{"en":"All contracts are stored in the company archive.","zh-TW":"所有合約都存放在公司檔案庫中。"},{"en":"Please archive the completed project files.","zh-TW":"請將已完成的項目文件存檔。"}]', '{"verb":"archive","adjective":"archived"}', NULL, 3, 383, 825),
(384, 'arduous', '/ˈɑːrdʒuəs/', 'adjective', '{"zh-TW":["艱難的；費力的"],"en":["involving or requiring strenuous effort; difficult and tiring"]}', NULL, 'arduous task / arduous journey / arduous process', '[{"en":"The arduous process of building a startup from scratch taught her invaluable lessons.","zh-TW":"從零開始建立一家初創公司的艱難過程給她帶來了寶貴的教訓。"},{"en":"Climbing the mountain was arduous, but the view from the top was worth every step.","zh-TW":"攀登這座山既艱難又費力，但山頂的景色值得每一步的努力。"}]', '{"adverb":"arduously","noun":"arduousness"}', NULL, 3, 384, NULL),
(385, 'area', '/ˈɛriə/', 'noun', '{"zh-TW":["區域；面積"],"en":["a particular part of a place or subject"]}', NULL, 'in the area / area of expertise', '[{"en":"This area is known for its food.","zh-TW":"這個地區以美食聞名。"},{"en":"What''s the area of this room?","zh-TW":"這個房間的面積是多少？"}]', NULL, NULL, 1, 385, NULL),
(386, 'arguably', '/''ɑːrɡjʊəbli/', 'adverb', '{"zh-TW":["可以說；有理由認為"],"en":["it may be argued; used to say that something is probably true or can be supported with evidence"]}', NULL, 'arguably the best / arguably more important / arguably the most', '[{"en":"She is arguably the most influential figure in the company''s history.","zh-TW":"她可以說是公司歷史上最具影響力的人物。"},{"en":"The new strategy is arguably riskier but offers much higher rewards.","zh-TW":"新策略可以說風險更大，但提供了更高的回報。"}]', '{"adjective":"arguable"}', NULL, 3, 386, NULL),
(387, 'arise', '/əˈraɪz/', 'verb', '{"zh-TW":["出現；產生","出現；發生"],"en":["to come into being or to come to attention","to come into being; to occur"]}', '{"prefix":{"text":"a-","meaning":"up (向上)"},"root":{"text":"rise","meaning":"rise (升起)"},"logic":"升起來，即「出現」。"}', 'arise from / problems arise; problems arise / arise from / should the need arise', '[{"en":"Several issues arose during the negotiation.","zh-TW":"談判期間出現了幾個問題。"},{"en":"Opportunities may arise from this partnership.","zh-TW":"這個合作關係可能產生機會。"},{"en":"Unexpected problems arose during the project.","zh-TW":"專案期間出現了意料之外的問題。"},{"en":"Conflicts can arise from misunderstandings.","zh-TW":"衝突可能源於誤解。"}]', NULL, NULL, 2, 387, NULL),
(388, 'arm', '/ɑːrm/', 'noun', '{"zh-TW":["手臂；武器","手臂；武裝"],"en":["the body part from shoulder to hand","the body part between shoulder and hand; to supply with weapons"]}', NULL, 'arm in arm / open arms; arm in arm / armed with', '[{"en":"She broke her arm skiing.","zh-TW":"她滑雪時摔斷了手臂。"},{"en":"They welcomed us with open arms.","zh-TW":"他們張開雙臂歡迎我們。"},{"en":"She broke her arm in the accident.","zh-TW":"她在事故中摔斷了手臂。"},{"en":"The security guard was armed.","zh-TW":"保全人員有武裝。"}]', '{"noun":"armament","adjective":"armed, unarmed"}', NULL, 1, 388, NULL),
(389, 'arm''s length', '/ɑːrmz leŋθ/', 'adjective', '{"zh-TW":["公平交易的；公正的"],"en":["describing a transaction in which parties act independently and without influence"]}', NULL, 'arm''s length transaction / arm''s length pricing / arm''s length basis', '[{"en":"Tax authorities require related parties to transact on an arm''s length basis.","zh-TW":"稅務機關要求關聯方以公平交易為基礎進行交易。"},{"en":"The sale was conducted at arm''s length to avoid conflict of interest.","zh-TW":"銷售是在公平交易的基礎上進行的，以避免利益衝突。"}]', NULL, NULL, 4, 389, NULL),
(390, 'arm''s length price', '/ɑːrmz leŋθ praɪs/', 'noun', '{"zh-TW":["公平交易價格"],"en":["a price for a transaction set as if the parties were independent of each other"]}', NULL, 'determine arm''s length price / arm''s length pricing standard', '[{"en":"Tax authorities require related companies to transact at arm''s length prices.","zh-TW":"稅務機關要求關聯公司按公平交易價格進行交易。"},{"en":"An arm''s length price prevents profit shifting between group entities.","zh-TW":"公平交易價格防止了集團實體之間的利潤轉移。"}]', NULL, NULL, 5, 390, NULL),
(391, 'arms-length transaction', '/ɑːrmz leŋθ trænˈzækʃən/', 'noun', '{"zh-TW":["公平交易；獨立交易"],"en":["a transaction between unrelated parties dealing independently on equal terms"]}', NULL, 'conduct an arms-length transaction / arms-length transaction requirement', '[{"en":"Tax authorities require that related-party dealings be conducted at arms-length.","zh-TW":"稅務機關要求關聯方交易按公平交易原則進行。"},{"en":"An independent valuation confirms the deal is an arms-length transaction.","zh-TW":"獨立估值確認了該交易是公平交易。"}]', NULL, NULL, 5, 391, NULL),
(392, 'army', '/ˈɑːrmi/', 'noun', '{"zh-TW":["軍隊；陸軍"],"en":["the military land forces of a country"]}', NULL, 'join the army / army base', '[{"en":"He joined the army at 18.","zh-TW":"他18歲參軍。"},{"en":"The army was deployed overseas.","zh-TW":"軍隊被部署到海外。"}]', NULL, NULL, 1, 392, NULL),
(393, 'around', '/əˈraʊnd/', 'preposition', '{"zh-TW":["周圍；大約"],"en":["on all sides of; approximately"]}', NULL, 'around the world / look around', '[{"en":"There are trees around the house.","zh-TW":"房子周圍有樹。"},{"en":"It costs around fifty dollars.","zh-TW":"大約花費五十美元。"}]', NULL, NULL, 2, 393, NULL),
(394, 'arrange', '/əˈreɪndʒ/', 'verb', '{"zh-TW":["安排；籌備"],"en":["to plan or organize something in advance"]}', '{"prefix":{"text":"ar-","meaning":"toward (朝向)"},"root":{"text":"range","meaning":"rank/row (排列)"},"logic":"朝向排列，即「安排」。"}', 'arrange a meeting/event/delivery', '[{"en":"I''ll arrange a meeting with the client for next week.","zh-TW":"我會安排下週與客戶的會議。"},{"en":"Transportation has been arranged for all attendees.","zh-TW":"已為所有出席者安排了交通。"}]', '{"noun":"arrangement"}', NULL, 3, 394, 267),
(395, 'arrears', '/əˈrɪərz/', 'noun', '{"zh-TW":["欠款；拖欠款項"],"en":["unpaid debts or obligations that are overdue"]}', NULL, 'fall into arrears / pay off arrears', '[{"en":"The customer fell three months into arrears on the loan.","zh-TW":"客戶的貸款拖欠了三個月。"},{"en":"The company cleared all arrears on its supplier accounts.","zh-TW":"公司清除了供應商帳戶上的所有欠款。"}]', '{"singular":"arrearage"}', NULL, 3, 395, NULL),
(396, 'arrival', '/''əˈraɪvəl/', 'noun', '{"zh-TW":["到達；抵達"],"en":["the action or process of arriving at a place or destination"]}', NULL, 'upon arrival / arrival time / airport arrival', '[{"en":"Upon arrival at the hotel, guests receive a complimentary welcome drink.","zh-TW":"抵達飯店後，客人會收到免費的歡迎飲料。"},{"en":"Her arrival at the conference was greeted with enthusiastic applause.","zh-TW":"她抵達會議時，受到熱烈掌聲的歡迎。"}]', '{"verb":"arrive"}', NULL, 3, 396, NULL),
(397, 'arrive', '/əˈraɪv/', 'verb', '{"zh-TW":["到達；抵達"],"en":["to reach a destination","to reach a place after traveling"]}', NULL, 'arrive at / arrive on time; arrive at/in + 地點', '[{"en":"The shipment will arrive tomorrow.","zh-TW":"貨物明天會到達。"},{"en":"Please arrive 10 minutes early.","zh-TW":"請提前10分鐘到達。"},{"en":"The flight arrives at 3 PM.","zh-TW":"班機下午三點抵達。"},{"en":"We arrived in Tokyo yesterday.","zh-TW":"我們昨天到達東京。"}]', '{"verb":"arrive","noun":"arrival"}', NULL, 2, 397, NULL),
(398, 'arrogant', '/ˈærəɡənt/', 'adjective', '{"zh-TW":["傲慢的"],"en":["having an exaggerated sense of one''s importance"]}', '{"prefix":{"text":"ar-","meaning":"toward (朝向)"},"root":{"text":"rog","meaning":"ask/claim (要求)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"對自己提出過高要求的，即「傲慢的」。"}', 'arrogant attitude / arrogant behavior', '[{"en":"His arrogant attitude made him unpopular.","zh-TW":"他傲慢的態度使他不受歡迎。"},{"en":"Don''t be so arrogant about your achievements.","zh-TW":"不要對你的成就如此傲慢。"}]', '{"noun":"arrogance"}', NULL, 3, 398, NULL),
(399, 'art', '/ɑːrt/', 'noun', '{"zh-TW":["藝術；美術"],"en":["the creation of beautiful or meaningful things"]}', NULL, 'work of art / art gallery', '[{"en":"She studies art at university.","zh-TW":"她在大學學藝術。"},{"en":"This painting is a true work of art.","zh-TW":"這幅畫是真正的藝術品。"}]', '{"noun":"artist","adjective":"artistic"}', NULL, 1, 399, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(400, 'articles of association', '/ˈɑːrtɪkəlz əv əˌsoʊsiˈeɪʃən/', 'noun', '{"zh-TW":["公司章程"],"en":["a document governing how a company is internally managed"]}', NULL, 'amend articles of association / file articles of association', '[{"en":"The articles of association define voting rights and board powers.","zh-TW":"公司章程規定了投票權和董事會權力。"},{"en":"Changes to the articles of association require shareholder approval.","zh-TW":"對公司章程的修改需要股東批准。"}]', NULL, NULL, 5, 400, NULL),
(401, 'articulate', '/ɑːrˈtɪkjʊleɪt/', 'verb', '{"zh-TW":["清楚地表達；闡述"],"en":["to express clearly and effectively"]}', NULL, 'articulate a vision / articulate concerns', '[{"en":"She articulated the company''s strategy clearly to investors.","zh-TW":"她向投資者清楚地闡述了公司的策略。"},{"en":"The manager articulated concerns about the project timeline.","zh-TW":"經理清楚地表達了對項目時間表的顧慮。"}]', '{"adjective":"articulate","adverb":"articulately"}', NULL, 4, 401, 955),
(402, 'artifact', '/ˈɑːrtɪfækt/', 'noun', '{"zh-TW":["文物；人工製品"],"en":["an object made by a human, especially one of historical interest"]}', '{"root":{"text":"arti","meaning":"skill (技藝)"},"suffix":{"text":"fact","meaning":"made (製造)"},"logic":"用技藝製造的東西，即「工藝品」。"}', 'ancient artifact / cultural artifact', '[{"en":"The museum displays artifacts from ancient Egypt.","zh-TW":"博物館展示古埃及文物。"},{"en":"Archaeologists discovered several artifacts at the site.","zh-TW":"考古學家在遺址發現了數件文物。"}]', NULL, NULL, 3, 402, NULL),
(403, 'artificial', '/ˌɑːrtɪˈfɪʃəl/', 'adjective', '{"zh-TW":["人工的；人造的"],"en":["made by people; not natural","made by humans rather than occurring naturally"]}', '{"root":{"text":"arti","meaning":"skill/craft (技藝)"},"suffix":{"text":"-ficial","meaning":"making (製造)"},"logic":"用技藝製造的，即「人工的」。"}', 'artificial intelligence / artificial flavor', '[{"en":"Artificial intelligence is changing the world.","zh-TW":"人工智慧正在改變世界。"},{"en":"The flowers are artificial.","zh-TW":"這些花是人造的。"},{"en":"The lake is artificial, not natural.","zh-TW":"這個湖是人工的，不是天然的。"},{"en":"Artificial intelligence is transforming many industries.","zh-TW":"人工智慧正在改變許多產業。"}]', '{"adverb":"artificially"}', NULL, 4, 403, NULL),
(404, 'artificial intelligence', '/ˌɑːrtɪˈfɪʃəl ɪnˈtelɪdʒəns/', 'noun', '{"zh-TW":["人工智慧"],"en":["simulation of human intelligence processes by computer systems"]}', NULL, 'AI-powered / artificial intelligence tools / leverage AI / AI strategy', '[{"en":"Artificial intelligence is transforming how businesses make decisions.","zh-TW":"人工智慧正在改變企業的決策方式。"},{"en":"The company deployed AI to improve customer service response times.","zh-TW":"公司部署人工智慧以改善客戶服務響應時間。"}]', '{"abbreviation":"AI","adjective":"AI-driven"}', NULL, 5, 404, NULL),
(405, 'artisan', '/''ɑːrtɪzən/', 'noun', '{"zh-TW":["工匠；手工藝師"],"en":["a person who makes high-quality products by hand; also used as an adjective for handcrafted goods"]}', NULL, 'artisan bread / artisan cheese / artisan market', '[{"en":"The artisan bakery made all its breads by hand using traditional methods.","zh-TW":"這家工匠麵包店使用傳統方法全部手工製作麵包。"},{"en":"Artisan cheeses from local farms are featured on the restaurant''s menu.","zh-TW":"來自當地農場的工匠起司是餐廳菜單上的特色。"}]', '{"adjective":"artisanal"}', NULL, 3, 405, NULL),
(406, 'ask', '/ɑːsk/', 'verb', '{"zh-TW":["詢問；要求；邀請"],"en":["to say something to get an answer; to request"]}', NULL, 'ask for / ask sb to do sth / ask about', '[{"en":"Can I ask you a question?","zh-TW":"我可以問你一個問題嗎？"},{"en":"She asked for a raise.","zh-TW":"她要求加薪。"}]', NULL, NULL, 1, 406, NULL),
(407, 'ask price', '/ɑːsk praɪs/', 'noun', '{"zh-TW":["賣出價；要價"],"en":["the price a seller is willing to accept for a security or asset"]}', NULL, 'quote an ask price / bid-ask spread', '[{"en":"The ask price for the shares was $10.50 per unit.","zh-TW":"股份的賣出價為每單位10.50元。"},{"en":"The difference between bid and ask price is called the spread.","zh-TW":"買入價和賣出價之間的差額稱為差價。"}]', '{"opposite":"bid price","synonym":"offer price"}', NULL, 3, 407, NULL),
(408, 'asking price', '/''ɑːskɪŋ praɪs/', 'noun', '{"zh-TW":["開價；要求售價"],"en":["the price at which a seller offers a property for sale"]}', NULL, 'above the asking price / below the asking price / negotiate the asking price', '[{"en":"The apartment sold at the full asking price within the first week on the market.","zh-TW":"公寓在上市第一週內以全額開價售出。"},{"en":"Buyers often start their negotiations below the asking price.","zh-TW":"買家通常在低於開價的情況下開始談判。"}]', NULL, NULL, 4, 408, NULL),
(409, 'aspect', '/ˈæspekt/', 'noun', '{"zh-TW":["方面；層面"],"en":["a particular part or feature of something"]}', '{"prefix":{"text":"a-","meaning":"to (朝向)"},"root":{"text":"spect","meaning":"look (看)"},"logic":"從某個方向看過去的面向，即「方面」。"}', 'important aspect / every aspect / key aspect', '[{"en":"We need to consider every aspect of the problem.","zh-TW":"我們需要考慮問題的每個方面。"},{"en":"Safety is the most important aspect of the job.","zh-TW":"安全是這份工作最重要的面向。"}]', NULL, NULL, 2, 409, NULL),
(410, 'assemble', '/əˈsembl/', 'verb', '{"zh-TW":["組裝；集合"],"en":["to fit together the parts of","to come together in one place","to put together the parts of"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"semble","meaning":"together (一起)"},"logic":"朝向一起，即「組裝、集合」。"}', 'assemble a team/product/parts; assemble a team / assemble furniture', '[{"en":"Workers assemble the components on the factory floor.","zh-TW":"工人在工廠車間組裝零件。"},{"en":"The committee assembled to discuss the proposal.","zh-TW":"委員會集合討論該提案。"},{"en":"Workers assemble the products on the factory floor.","zh-TW":"工人在工廠樓層組裝產品。"},{"en":"The team assembled in the conference room.","zh-TW":"團隊在會議室集合。"}]', '{"noun":"assembly"}', NULL, 3, 410, 648),
(411, 'assert', '/əˈsɜːrt/', 'verb', '{"zh-TW":["斷言；主張"],"en":["to state something clearly and firmly"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sert","meaning":"join/bind (結合)"},"logic":"朝向牢固結合的聲明，即「斷言」。"}', 'assert rights/authority/claims', '[{"en":"The company asserted its right to the patent.","zh-TW":"公司主張其專利權。"},{"en":"She asserted that the data was accurate.","zh-TW":"她斷言資料是準確的。"}]', '{"noun":"assertion","adjective":"assertive"}', NULL, 2, 411, NULL),
(412, 'assertion', '/əˈsɜːrʃən/', 'noun', '{"zh-TW":["主張；斷言"],"en":["a confident and forceful statement"]}', NULL, 'make an assertion / bold assertion / unsupported assertion', '[{"en":"His assertion was not backed by any data.","zh-TW":"他的主張沒有任何數據支持。"},{"en":"The paper makes several assertions that require empirical verification.","zh-TW":"該論文提出了幾個需要實證驗證的主張。"}]', '{"verb":"assert","adjective":"assertive"}', NULL, 3, 412, NULL),
(413, 'assertive', '/''əˈsɜːrtɪv/', 'adjective', '{"zh-TW":["自信的；有主見的"],"en":["having or showing a confident and forceful personality; able to express opinions firmly"]}', NULL, 'assertive communication / be assertive / become more assertive', '[{"en":"Being assertive means expressing your needs clearly without being aggressive.","zh-TW":"自信是指清楚地表達你的需求而不具有攻擊性。"},{"en":"Assertive employees are more likely to share valuable ideas and stand up for their rights.","zh-TW":"自信的員工更有可能分享有價值的想法並維護自己的權益。"}]', '{"noun":"assertiveness","adverb":"assertively"}', NULL, 3, 413, NULL),
(414, 'assertiveness training', '/''əˈsɜːrtɪvnəs ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["自信表達培訓；自我主張訓練"],"en":["training that helps people communicate their needs and boundaries clearly and confidently"]}', NULL, 'attend assertiveness training / benefit from assertiveness training / need assertiveness training', '[{"en":"Assertiveness training helped her speak up in meetings and share her ideas more confidently.","zh-TW":"自信表達培訓幫助她在會議中發言，更自信地分享她的想法。"},{"en":"Many professionals benefit from assertiveness training to improve workplace communication.","zh-TW":"許多專業人士受益於自信表達培訓，以改善工作場所的溝通。"}]', NULL, NULL, 5, 414, NULL),
(415, 'assess', '/əˈses/', 'verb', '{"zh-TW":["評估；估算"],"en":["to evaluate or estimate the nature or quality of"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sess","meaning":"sit (坐)"},"logic":"坐下來朝向審視，即「評估」。"}', 'assess risk/damage/performance', '[{"en":"We need to assess the potential risks before investing.","zh-TW":"投資前我們需要評估潛在風險。"},{"en":"The damage was assessed at $2 million.","zh-TW":"損失估計為200萬美元。"}]', '{"noun":"assessment"}', NULL, 2, 415, NULL),
(416, 'assess risk', '/əˈses rɪsk/', 'verb', '{"zh-TW":["評估風險"],"en":["to identify, analyze, and evaluate potential risks before taking action"]}', NULL, 'assess risk before investing / regularly assess risk', '[{"en":"Managers must assess risk before approving capital expenditure.","zh-TW":"管理者在批准資本支出前必須評估風險。"},{"en":"The team assessed risk using a probability-impact matrix.","zh-TW":"團隊使用概率-影響矩陣評估了風險。"}]', '{"noun":"risk assessment","noun2":"assessor"}', NULL, 4, 416, NULL),
(417, 'assessed value', '/əˈsest ˈvæljuː/', 'noun', '{"zh-TW":["評定價值；課稅估值"],"en":["the value assigned to a property for tax purposes"]}', NULL, 'assessed value of the property / calculate assessed value', '[{"en":"Property taxes are based on the assessed value of the property.","zh-TW":"房產稅基於物業的評定價值計算。"},{"en":"The assessed value was lower than the market value.","zh-TW":"評定價值低於市場價值。"}]', NULL, NULL, 5, 417, NULL),
(418, 'assessment', '/əˈsesmənt/', 'noun', '{"zh-TW":["評估；鑑定"],"en":["the process of evaluating performance, risk, or capability"]}', NULL, 'risk assessment / needs assessment / performance assessment / conduct an assessment', '[{"en":"A comprehensive risk assessment was conducted before the project launch.","zh-TW":"在項目啟動前進行了全面的風險評估。"},{"en":"The assessment revealed gaps in the team''s technical skills.","zh-TW":"評估揭示了團隊技術技能方面的差距。"}]', '{"verb":"assess","noun":"assessor"}', NULL, 4, 418, 268),
(419, 'asset', '/ˈæset/', 'noun', '{"zh-TW":["資產"],"en":["any resource owned by a company with economic value"]}', NULL, 'current asset / fixed asset / intangible asset / asset management / asset valuation', '[{"en":"The company''s most valuable asset is its brand reputation.","zh-TW":"公司最有價值的資產是其品牌聲譽。"},{"en":"Total assets on the balance sheet exceeded $1 billion.","zh-TW":"資產負債表上的總資產超過10億美元。"}]', '{"plural":"assets","adjective":"asset-rich"}', NULL, 2, 419, 269),
(420, 'asset allocation', '/ˈæset ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["資產配置"],"en":["distributing investments among different asset classes"]}', NULL, 'strategic asset allocation / dynamic asset allocation', '[{"en":"Asset allocation determines the risk-return profile of a portfolio.","zh-TW":"資產配置決定了投資組合的風險回報特徵。"},{"en":"She adjusted her asset allocation as she neared retirement.","zh-TW":"她在接近退休時調整了資產配置。"}]', '{"verb":"allocate assets"}', NULL, 5, 420, NULL),
(421, 'asset class', '/ˈæset klɑːs/', 'noun', '{"zh-TW":["資產類別"],"en":["a category of investments with similar characteristics and market behaviors"]}', NULL, 'diversify across asset classes / asset class allocation', '[{"en":"Bonds and equities are distinct asset classes with different risk profiles.","zh-TW":"債券和股票是具有不同風險特徵的不同資產類別。"},{"en":"Portfolio managers allocate capital across multiple asset classes.","zh-TW":"投資組合管理人在多種資產類別中分配資本。"}]', NULL, NULL, 4, 421, NULL),
(422, 'asset disposal', '/ˈæset dɪˈspoʊzəl/', 'noun', '{"zh-TW":["資產處置"],"en":["the process of selling or writing off an asset that is no longer needed"]}', NULL, 'manage asset disposal / asset disposal proceeds', '[{"en":"The asset disposal generated $500000 for reinvestment.","zh-TW":"資產處置產生了50萬元用於再投資。"},{"en":"Proceeds from asset disposal were used to reduce company debt.","zh-TW":"資產處置所得用於減少公司債務。"}]', NULL, NULL, 5, 422, NULL),
(423, 'asset impairment', '/ˈæset ɪmˈpeərmənt/', 'noun', '{"zh-TW":["資產減值"],"en":["a reduction in the carrying value of an asset due to a decline in its recoverable amount"]}', NULL, 'record asset impairment / asset impairment test', '[{"en":"An asset impairment charge was recognized after the plant closure.","zh-TW":"工廠關閉後確認了資產減值費用。"},{"en":"Annual asset impairment tests are required by international accounting standards.","zh-TW":"國際會計準則要求進行年度資產減值測試。"}]', NULL, NULL, 5, 423, NULL),
(424, 'asset management', '/ˈæsɛt ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["資產管理"],"en":["the professional management of financial and physical assets"]}', NULL, 'investment asset management / asset management company', '[{"en":"She works at an asset management company specializing in equity.","zh-TW":"她在一家專門從事股票的資產管理公司工作。"},{"en":"Asset management ensures that resources are used efficiently.","zh-TW":"資產管理確保資源得到有效使用。"}]', NULL, NULL, 5, 424, NULL),
(425, 'asset management company', '/ˈæset ˈmænɪdʒmənt ˈkʌmpəni/', 'noun', '{"zh-TW":["資產管理公司"],"en":["a firm that manages investments and financial portfolios on behalf of clients"]}', NULL, 'hire an asset management company / asset management company services', '[{"en":"The pension fund engaged an asset management company to grow returns.","zh-TW":"養老基金聘請了一家資產管理公司來增加回報。"},{"en":"Asset management companies charge fees based on assets under management.","zh-TW":"資產管理公司根據管理的資產規模收取費用。"}]', NULL, NULL, 5, 425, NULL),
(426, 'asset register', '/ˈæset ˈredʒɪstər/', 'noun', '{"zh-TW":["資產登記冊"],"en":["a record listing all assets owned by an organization with their details"]}', NULL, 'maintain an asset register / asset register update', '[{"en":"The asset register must be updated whenever assets are purchased or disposed of.","zh-TW":"每次購買或處置資產時，必須更新資產登記冊。"},{"en":"An accurate asset register supports insurance coverage and depreciation.","zh-TW":"準確的資產登記冊支持保險保障和折舊計算。"}]', NULL, NULL, 5, 426, NULL),
(427, 'asset turnover', '/ˈæset ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["資產周轉率"],"en":["a financial ratio measuring how efficiently a company uses its assets to generate revenue"]}', NULL, 'calculate asset turnover / improve asset turnover', '[{"en":"A high asset turnover ratio indicates efficient use of company assets.","zh-TW":"高資產周轉率表明公司資產使用效率高。"},{"en":"The company improved asset turnover by disposing of underperforming assets.","zh-TW":"公司通過處置業績不佳的資產改善了資產周轉率。"}]', NULL, NULL, 5, 427, NULL),
(428, 'asset valuation', '/ˈæset ˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["資產評估"],"en":["the process of determining the current worth of a company''s assets"]}', NULL, 'conduct asset valuation / asset valuation report', '[{"en":"An independent asset valuation was required for the merger.","zh-TW":"合併需要獨立的資產評估。"},{"en":"Asset valuation methods include market value and replacement cost.","zh-TW":"資產評估方法包括市場價值和重置成本。"}]', NULL, NULL, 5, 428, NULL),
(429, 'asset-backed securities', '/ˈæset bækt sɪˈkjʊərɪtiz/', 'noun', '{"zh-TW":["資產抵押證券"],"en":["financial instruments backed by a pool of underlying assets"]}', NULL, 'issue asset-backed securities / invest in asset-backed securities', '[{"en":"Mortgage-backed securities are a type of asset-backed securities.","zh-TW":"抵押支持證券是資產抵押證券的一種。"},{"en":"Asset-backed securities played a major role in the financial crisis.","zh-TW":"資產抵押證券在金融危機中扮演了重要角色。"}]', '{"abbreviation":"ABS"}', NULL, 5, 429, NULL),
(430, 'asset-backed security', '/ˈæset bækt sɪˈkjʊərɪti/', 'noun', '{"zh-TW":["資產擔保證券"],"en":["a financial instrument backed by a pool of assets such as loans or receivables"]}', NULL, 'issue asset-backed securities / asset-backed security risk', '[{"en":"The bank securitized its auto loan portfolio into asset-backed securities.","zh-TW":"銀行將其汽車貸款組合證券化為資產擔保證券。"},{"en":"Asset-backed securities allow banks to free up capital for new lending.","zh-TW":"資產擔保證券使銀行能夠釋放資本用於新貸款。"}]', '{"abbreviation":"ABS"}', NULL, 5, 430, NULL),
(431, 'asset-light', '/ˈæset laɪt/', 'adjective', '{"zh-TW":["輕資產的"],"en":["describing a business model that relies on few physical assets"]}', NULL, 'asset-light model / asset-light strategy / asset-light company', '[{"en":"Franchise businesses are typically asset-light.","zh-TW":"特許經營企業通常是輕資產的。"},{"en":"The firm transitioned to an asset-light model by outsourcing logistics.","zh-TW":"公司通過將物流外包轉型為輕資產模式。"}]', NULL, NULL, 4, 431, NULL),
(432, 'assign', '/əˈsaɪn/', 'verb', '{"zh-TW":["分配；指派"],"en":["to give someone a particular job or task"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sign","meaning":"mark (標記)"},"logic":"朝向標記某人做某事，即「指派」。"}', 'assign a task/role/responsibility', '[{"en":"The manager assigned the task to the new employee.","zh-TW":"經理將任務分配給新員工。"},{"en":"Each team member was assigned a specific role.","zh-TW":"每位團隊成員被指派了特定角色。"}]', '{"noun":"assignment"}', NULL, 2, 432, 270),
(433, 'assign responsibility', '/əˈsaɪn rɪˌspɒnsɪˈbɪlɪti/', 'verb', '{"zh-TW":["指派責任"],"en":["to designate someone as being accountable for a task or outcome"]}', NULL, 'assign clear responsibility / assign responsibility for each task', '[{"en":"Responsibility for data security was assigned to the IT director.","zh-TW":"資料安全的責任被指派給了IT總監。"},{"en":"Each project milestone had an assigned responsibility owner.","zh-TW":"每個項目里程碑都有指派的責任人。"}]', NULL, NULL, 5, 433, NULL),
(434, 'assigned', 'əˈsaɪnd', 'adjective', '{"zh-TW":["指定的；分配的","負責的"],"en":["given a specific task","allocated"]}', NULL, 'assigned tasks/assigned responsibilities', '[{"en":"Complete your assigned tasks on time.","zh-TW":"按時完成您的指定任務。"}]', '{"verb":"assign","noun":"assignment"}', NULL, 3, 434, NULL),
(435, 'assignment', '/əˈsaɪnmənt/', 'noun', '{"zh-TW":["作業；任務"],"en":["a task given as part of a job or studies"]}', NULL, 'homework assignment / complete an assignment', '[{"en":"The assignment is due on Friday.","zh-TW":"作業週五到期。"},{"en":"She completed all her assignments on time.","zh-TW":"她按時完成了所有作業。"}]', '{"verb":"assign"}', NULL, 4, 435, 508),
(436, 'assignment of contract', '/əˈsaɪnmənt əv ˈkɒntrækt/', 'noun', '{"zh-TW":["合約轉讓"],"en":["the transfer of contractual rights or obligations from one party to another"]}', NULL, 'permit assignment of contract / assignment of contract clause', '[{"en":"An assignment of contract clause requires prior written consent.","zh-TW":"合約轉讓條款需要事先書面同意。"},{"en":"The assignment of contract was approved by all parties involved.","zh-TW":"所有相關各方批准了合約轉讓。"}]', NULL, NULL, 5, 436, NULL),
(437, 'assimilate', '/''əˌsɪmɪˌleɪt/', 'verb', '{"zh-TW":["同化；吸收；消化"],"en":["to take in and understand fully; to absorb into a group or culture"]}', NULL, 'assimilate information / assimilate into society / assimilate quickly', '[{"en":"It took her several months to assimilate all the new information from the training.","zh-TW":"她花了幾個月的時間吸收培訓中的所有新信息。"},{"en":"Immigrants often face challenges as they try to assimilate into a new culture.","zh-TW":"移民在嘗試融入新文化時往往面臨挑戰。"}]', '{"noun":"assimilation","adjective":"assimilated"}', NULL, 4, 437, NULL),
(438, 'assimilation', '/əˌsɪmɪˈleɪʃən/', 'noun', '{"zh-TW":["同化；融合"],"en":["the process by which a minority group adopts the culture of the dominant group"]}', NULL, 'cultural assimilation / forced assimilation / assimilation of immigrants', '[{"en":"Critics argue that forced assimilation erases important cultural heritage.","zh-TW":"批評者認為強迫同化抹去了重要的文化遺產。"},{"en":"Immigrants face pressure to assimilation into the dominant culture.","zh-TW":"移民面臨著融入主流文化的壓力。"}]', '{"verb":"assimilate","adjective":"assimilated"}', NULL, 4, 438, NULL),
(439, 'assist', '/əˈsɪst/', 'verb', '{"zh-TW":["協助；幫助"],"en":["to help or give support to someone"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sist","meaning":"stand (站)"},"logic":"站在旁邊支持，即「協助」。"}', 'assist with / assist in doing', '[{"en":"Our team will assist you with the transition.","zh-TW":"我們的團隊將協助您完成過渡。"},{"en":"Can I assist you in finding what you need?","zh-TW":"我能幫您找到您需要的東西嗎？"}]', '{"noun":"assistance","noun2":"assistant"}', NULL, 2, 439, 73),
(440, 'assistance', 'əˈsɪstəns', 'noun', '{"zh-TW":["協助；幫助","支援"],"en":["help or support given","aid provided"]}', NULL, 'technical assistance/request assistance', '[{"en":"Please call us if you need any assistance.","zh-TW":"如果您需要任何幫助，請致電。"}]', '{"verb":"assist","adjective":"assistive"}', NULL, 4, 440, NULL),
(441, 'associate', '/əˈsəʊsieɪt/', 'verb', '{"zh-TW":["聯想；關聯","交往"],"en":["to connect in one''s mind","to spend time with someone"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"soci","meaning":"companion (夥伴)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使成為夥伴，即「關聯」。"}', 'associate with / be associated with', '[{"en":"Customers associate the brand with quality.","zh-TW":"顧客將該品牌與品質聯繫在一起。"},{"en":"High stress is associated with health problems.","zh-TW":"高壓力與健康問題有關。"}]', '{"noun":"association"}', NULL, 3, 441, NULL),
(442, 'associated costs', '/əˈsoʊsiˌeɪtɪd kɒsts/', 'noun', '{"zh-TW":["相關成本；附帶費用"],"en":["additional costs that arise in connection with a primary activity or purchase"]}', NULL, 'identify associated costs / minimize associated costs', '[{"en":"The project''s associated costs exceeded the initial estimate by 20%.","zh-TW":"項目的相關成本超出了初始估計20%。"},{"en":"All associated costs were disclosed in the financial summary.","zh-TW":"所有相關成本均在財務摘要中披露了。"}]', NULL, NULL, 5, 442, NULL),
(443, 'assume', '/əˈsjuːm/', 'verb', '{"zh-TW":["假設；承擔"],"en":["to suppose to be true without proof","to take on responsibility"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sume","meaning":"take (拿取)"},"logic":"朝向拿取（未證實的），即「假設」。"}', 'assume responsibility/role/risk', '[{"en":"Let''s assume the project will take six months.","zh-TW":"我們假設這個專案需要六個月。"},{"en":"She assumed the role of department head.","zh-TW":"她承擔了部門主管的角色。"}]', '{"noun":"assumption"}', NULL, 2, 443, NULL),
(444, 'assumption', '/əˈsʌmpʃən/', 'noun', '{"zh-TW":["假設；前提"],"en":["a condition believed to be true without verification, used in planning"]}', NULL, 'project assumption / document assumptions / challenge an assumption', '[{"en":"All project assumptions were recorded in the project charter.","zh-TW":"所有項目假設都記錄在項目章程中。"},{"en":"Failing to validate assumptions early caused the project to fail.","zh-TW":"未能早期驗證假設導致項目失敗。"}]', '{"plural":"assumptions","verb":"assume"}', NULL, 4, 444, 509),
(445, 'assure', '/əˈʃʊər/', 'verb', '{"zh-TW":["保證；使確信","向…保證；確保"],"en":["to tell someone confidently to remove doubt","to tell someone confidently that something is true"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sure","meaning":"sure (確定)"},"logic":"朝向使人確定，即「保證」。"}', 'assure sb that / rest assured; assure someone that / rest assured / I assure you', '[{"en":"I assure you that the issue will be resolved promptly.","zh-TW":"我向您保證問題將盡快解決。"},{"en":"Rest assured, your data is secure.","zh-TW":"請放心，您的資料是安全的。"},{"en":"I assure you the problem will be fixed.","zh-TW":"我向你保證問題會被解決。"},{"en":"Rest assured, your data is safe.","zh-TW":"請放心，你的資料是安全的。"}]', '{"noun":"assurance","adjective":"assured"}', NULL, 2, 445, 728),
(446, 'astounding', '/''əˈstaʊndɪŋ/', 'adjective', '{"zh-TW":["令人驚嘆的；驚人的"],"en":["surprisingly impressive or notable"]}', NULL, 'astounding results / astounding growth / astounding achievement', '[{"en":"The startup''s astounding growth attracted investment from all over the world.","zh-TW":"這家新創公司令人驚嘆的增長吸引了來自世界各地的投資。"},{"en":"Her astounding ability to retain complex information set her apart from other candidates.","zh-TW":"她令人驚嘆的記憶複雜信息的能力使她在其他候選人中脫穎而出。"}]', '{"adverb":"astoundingly","verb":"astound"}', NULL, 4, 446, NULL),
(447, 'astute', '/''əˈstjuːt/', 'adjective', '{"zh-TW":["敏銳的；精明的"],"en":["having an ability to accurately assess situations or people and turn this to one''s advantage"]}', NULL, 'astute businessperson / astute observation / astute investor', '[{"en":"An astute investor recognizes opportunities that others overlook.","zh-TW":"一位精明的投資者能夠識別他人忽視的機會。"},{"en":"Her astute observations during the negotiation helped secure a favorable deal.","zh-TW":"她在談判中的敏銳觀察幫助達成了有利的交易。"}]', '{"adverb":"astutely","noun":"astuteness"}', NULL, 2, 447, NULL),
(448, 'astute observer', '/''əˌstjuːt əbˌzɜːrvər/', 'noun', '{"zh-TW":["敏銳的觀察者"],"en":["someone who notices things and forms accurate judgments quickly and cleverly"]}', NULL, 'act as an astute observer / be an astute observer of / known as an astute observer', '[{"en":"As an astute observer of market trends, she often predicted shifts before others noticed.","zh-TW":"作為市場趨勢的敏銳觀察者，她往往在其他人注意到之前就預測到了變化。"},{"en":"An astute observer can read the room and adjust communication style accordingly.","zh-TW":"敏銳的觀察者能夠解讀場景，並相應地調整溝通方式。"}]', '{"adjective":"astute"}', NULL, 5, 448, NULL),
(449, 'asynchronous', '/eɪˈsɪŋkrənəs/', 'adjective', '{"zh-TW":["非同步的"],"en":["not occurring at the same time; allowing operations to proceed independently"]}', NULL, 'asynchronous processing / asynchronous communication / asynchronous task', '[{"en":"Asynchronous processing improves the responsiveness of web applications.","zh-TW":"非同步處理提高了網路應用程式的回應能力。"},{"en":"The system uses asynchronous message queues to handle high traffic volumes.","zh-TW":"系統使用非同步訊息佇列來處理高流量。"}]', '{"adverb":"asynchronously","noun":"asynchrony"}', NULL, 4, 449, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(450, 'at par', '/æt pɑːr/', 'phrase', '{"zh-TW":["按面值；按平價"],"en":["at the nominal or face value of a security or financial instrument"]}', NULL, 'issued at par / redeemed at par / trade at par', '[{"en":"The bonds were issued at par and mature in five years.","zh-TW":"債券按面值發行，五年後到期。"},{"en":"Shares trading at par indicate market confidence in book value.","zh-TW":"按面值交易的股份表明市場對帳面價值有信心。"}]', NULL, NULL, 2, 450, NULL),
(451, 'at-will employment', '/æt wɪl ɪmˈplɔɪmənt/', 'noun', '{"zh-TW":["隨意雇用"],"en":["an employment arrangement where either party can terminate at any time without cause"]}', NULL, 'at-will employment contract / at-will employment policy', '[{"en":"At-will employment means the employer can terminate without advance notice.","zh-TW":"隨意雇用意味著雇主可以在不提前通知的情況下終止雇用。"},{"en":"Some states restrict at-will employment through protective legislation.","zh-TW":"一些州通過保護性立法限制了隨意雇用。"}]', NULL, NULL, 5, 451, NULL),
(452, 'athlete', '/ˈæθliːt/', 'noun', '{"zh-TW":["運動員"],"en":["a person who is good at sports"]}', NULL, 'professional athlete / athlete''s performance', '[{"en":"She is a talented athlete.","zh-TW":"她是一位有天賦的運動員。"},{"en":"The athlete broke the world record.","zh-TW":"那位運動員打破了世界紀錄。"}]', '{"adjective":"athletic","noun2":"athletics"}', NULL, 3, 452, NULL),
(453, 'athletic', '/''æθˈletɪk/', 'adjective', '{"zh-TW":["運動的；體格健壯的"],"en":["physically strong, fit, and active; relating to athletes or athletics"]}', NULL, 'athletic build / athletic performance / athletic ability', '[{"en":"Her athletic build was ideal for competitive swimming.","zh-TW":"她健壯的體格非常適合競技游泳。"},{"en":"The school offers a wide range of athletic programs for students of all ages.","zh-TW":"學校為各年齡層的學生提供廣泛的運動計畫。"}]', '{"noun":"athlete","noun2":"athletics"}', NULL, 3, 453, NULL),
(454, 'athletic performance', '/''æθˌletɪk pəˌfɔːrməns/', 'noun', '{"zh-TW":["運動表現；競技表現"],"en":["the level of ability or achievement in sport or physical activity"]}', NULL, 'improve athletic performance / assess athletic performance / optimize athletic performance', '[{"en":"Adequate sleep is essential for maintaining and improving athletic performance.","zh-TW":"充足的睡眠對維持和改善運動表現至關重要。"},{"en":"The coach monitored each player''s athletic performance throughout the season.","zh-TW":"教練在整個賽季監測每位球員的運動表現。"}]', '{"adjective":"athletic"}', NULL, 5, 454, NULL),
(455, 'athletic scholarship', '/''æθˈletɪk ˌskɒlərʃɪp/', 'noun', '{"zh-TW":["體育獎學金"],"en":["financial aid awarded to a student primarily on the basis of athletic ability"]}', NULL, 'receive an athletic scholarship / earn an athletic scholarship / full athletic scholarship', '[{"en":"She received a full athletic scholarship to study and play tennis at the university.","zh-TW":"她獲得了在大學學習和打網球的全額體育獎學金。"},{"en":"Athletic scholarships help talented young athletes afford higher education.","zh-TW":"體育獎學金幫助有才華的年輕運動員負擔高等教育費用。"}]', NULL, NULL, 5, 455, NULL),
(456, 'athletic training', '/''æθˌletɪk ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["運動訓練；競技訓練"],"en":["systematic practice aimed at improving performance in a sport or physical activity"]}', NULL, 'undergo athletic training / athletic training program / benefit of athletic training', '[{"en":"She underwent intensive athletic training for six months before the national competition.","zh-TW":"她在全國比賽前進行了六個月的密集運動訓練。"},{"en":"Athletic training combines physical conditioning, technique development, and mental preparation.","zh-TW":"運動訓練結合了體能調整、技術發展和心理準備。"}]', '{"adjective":"athletic"}', NULL, 5, 456, NULL),
(457, 'ATM', '/eɪ tiː ɛm/', 'noun', '{"zh-TW":["自動提款機"],"en":["a machine that allows bank customers to withdraw cash"]}', NULL, 'use an ATM / ATM withdrawal', '[{"en":"She withdrew cash from the ATM near the hotel.","zh-TW":"她在飯店附近的自動提款機提取了現金。"},{"en":"ATM fees apply when using machines outside your network.","zh-TW":"使用網絡外的機器時需支付自動提款機手續費。"}]', NULL, NULL, 1, 457, NULL),
(458, 'atmosphere', '/ˈætməsfɪr/', 'noun', '{"zh-TW":["大氣層；氣氛"],"en":["the layer of gases around the earth","the mood or feeling of a place"]}', '{"root":{"text":"atmos","meaning":"vapor (蒸氣)"},"suffix":{"text":"sphere","meaning":"ball (球)"},"logic":"蒸氣包圍的球體，即「大氣層」。"}', 'earth''s atmosphere / friendly atmosphere', '[{"en":"The atmosphere at the party was lively.","zh-TW":"派對的氣氛很活絡。"},{"en":"Pollution is damaging the atmosphere.","zh-TW":"汙染正在破壞大氣層。"}]', '{"adjective":"atmospheric"}', NULL, 4, 458, NULL),
(459, 'atrium', '/ˈeɪtriəm/', 'noun', '{"zh-TW":["中庭大廳"],"en":["a large open space inside a building"]}', NULL, 'hotel atrium / glass atrium', '[{"en":"The hotel has a stunning glass atrium with natural light.","zh-TW":"飯店有令人驚嘆的玻璃中庭，採光自然。"},{"en":"Guests can relax in the central atrium.","zh-TW":"賓客可以在中央中庭休息。"}]', NULL, NULL, 2, 459, NULL),
(460, 'attach', '/əˈtætʃ/', 'verb', '{"zh-TW":["附上；連接"],"en":["to fasten or join one thing to another"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tach","meaning":"stake/fasten (釘住)"},"logic":"朝向釘住，即「附上」。"}', 'attach a file/document/label', '[{"en":"Please find the report attached to this email.","zh-TW":"請查看附在此電子郵件中的報告。"},{"en":"Attach the receipt to your expense claim.","zh-TW":"請將收據附在您的報銷申請上。"}]', '{"noun":"attachment"}', NULL, 2, 460, NULL),
(461, 'attached', '/əˈtætʃt/', 'adjective', '{"zh-TW":["附件的；附上的"],"en":["joined or fastened to something; included with a message"]}', NULL, 'as attached / please find attached', '[{"en":"Please find the report attached to this email.","zh-TW":"請查看此電子郵件的附件報告。"},{"en":"The attached document outlines the terms of the agreement.","zh-TW":"附件文件概述了協議條款。"}]', '{"verb":"attach","noun":"attachment"}', NULL, 3, 461, NULL),
(462, 'attachment', '/əˈtætʃmənt/', 'noun', '{"zh-TW":["附件；附加物"],"en":["a file sent along with an email or document"]}', NULL, 'email attachment / download the attachment', '[{"en":"Please open the attachment for the full report.","zh-TW":"請打開附件查看完整報告。"},{"en":"The attachment contains all the required forms.","zh-TW":"附件包含所有所需的表格。"}]', '{"verb":"attach","adjective":"attached"}', NULL, 4, 462, 510),
(463, 'attack', '/əˈtæk/', 'noun', '{"zh-TW":["攻擊；發作"],"en":["an act of violence against someone"]}', NULL, 'heart attack / under attack', '[{"en":"The city was under attack.","zh-TW":"城市遭受了攻擊。"},{"en":"He suffered a heart attack.","zh-TW":"他心臟病發作了。"}]', '{"verb":"attack","noun2":"attacker"}', NULL, 2, 463, NULL),
(464, 'attain', '/əˈteɪn/', 'verb', '{"zh-TW":["達到；獲得"],"en":["to succeed in achieving something after effort"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"朝向持有，即「達到」。"}', 'attain a goal/level/standard', '[{"en":"Few companies attain such high customer satisfaction ratings.","zh-TW":"很少有公司達到如此高的客戶滿意度。"},{"en":"He attained the rank of senior vice president.","zh-TW":"他達到了資深副總裁的職位。"}]', '{"adjective":"attainable","noun":"attainment"}', NULL, 2, 464, NULL),
(465, 'attempt', '/əˈtempt/', 'verb', '{"zh-TW":["嘗試；企圖"],"en":["to try to do something, especially difficult","to try to do something"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tempt","meaning":"try (嘗試)"},"logic":"朝向嘗試，即「企圖」。"}', 'attempt to do / make an attempt; attempt to / first attempt / make an attempt', '[{"en":"The company attempted to enter the European market.","zh-TW":"公司嘗試進入歐洲市場。"},{"en":"Several attempts were made to resolve the dispute.","zh-TW":"多次嘗試解決爭端。"},{"en":"He attempted to climb the mountain alone.","zh-TW":"他嘗試獨自攀登那座山。"},{"en":"She passed the exam on her first attempt.","zh-TW":"她第一次嘗試就通過了考試。"}]', '{"noun":"attempt"}', NULL, 3, 465, NULL),
(466, 'attend', '/əˈtend/', 'verb', '{"zh-TW":["【主要意義-動詞】出席；參加","【次要意義-動詞】照料；服侍；護理（病人）","【次要意義-動詞】處理；注意（attend to）"],"en":["[primary] to be present at an event or place","[secondary] to care for someone who is sick or in need","[secondary] to deal with something; to give attention to"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tend","meaning":"stretch (延伸)"},"logic":"朝向延伸注意力，即「出席」。"}', 'attend to a matter / attend to a customer / attend on someone', '[{"en":"A doctor attended to the injured worker on site.","zh-TW":"現場有醫生照料受傷的工人。"},{"en":"Please attend to the urgent client inquiry before anything else.","zh-TW":"請在處理其他事情之前先處理緊急的客戶詢問。"},{"en":"The sales representative attended to each customer personally.","zh-TW":"銷售代表親自服務每位顧客。"}]', '{"noun":"attendant, attendance","adjective":"attentive"}', 'attend to = 「照料/服侍/處理」，不同於 attend（出席），是 TOEIC 客服或醫療文章中的陷阱用法，attendant（服務員/侍者）的詞根含義也源於此。', 2, 466, NULL),
(467, 'attendance record', '/''əˈtendəns ˌrekərd/', 'noun', '{"zh-TW":["出勤記錄；到課紀錄"],"en":["a record of a student''s presence or absence from classes"]}', NULL, 'maintain an attendance record / perfect attendance record / check attendance record', '[{"en":"A strong attendance record is often required for scholarship eligibility.","zh-TW":"強大的出勤記錄通常是獎學金資格的要求。"},{"en":"The system automatically updates attendance records each day.","zh-TW":"系統每天自動更新出勤記錄。"}]', NULL, NULL, 5, 467, NULL),
(468, 'attention', '/əˈtɛnʃən/', 'noun', '{"zh-TW":["注意力；關注","注意；關注"],"en":["the act of concentrating on something","the act of thinking about or watching something carefully"]}', NULL, 'pay attention / draw attention to; pay attention to / attract/draw attention', '[{"en":"Pay attention to the safety guidelines.","zh-TW":"請注意安全指南。"},{"en":"The report drew attention to the issue.","zh-TW":"報告引起了人們對該問題的關注。"},{"en":"Please pay attention to the instructions.","zh-TW":"請注意指示。"},{"en":"The advertisement attracted a lot of attention.","zh-TW":"這則廣告引起了很多關注。"}]', '{"noun":"attention","adjective":"attentive","adverb":"attentively"}', NULL, 3, 468, NULL),
(469, 'attitude', '/ˈætɪtjuːd/', 'noun', '{"zh-TW":["態度；看法"],"en":["a settled way of thinking or feeling about something"]}', '{"root":{"text":"apt","meaning":"fit (適合)"},"suffix":{"text":"-itude","meaning":"state (狀態)"},"logic":"適合的狀態展現，即「態度」。"}', 'positive/negative attitude / attitude toward', '[{"en":"A positive attitude is valued in the workplace.","zh-TW":"工作場所重視積極的態度。"},{"en":"Her attitude toward work impressed her supervisors.","zh-TW":"她對工作的態度令主管印象深刻。"}]', NULL, NULL, 3, 469, NULL),
(470, 'attorney', '/əˈtɜːrni/', 'noun', '{"zh-TW":["律師"],"en":["a person qualified to practice law"]}', NULL, 'attorney general / defense attorney', '[{"en":"She hired an attorney.","zh-TW":"她請了一位律師。"},{"en":"The attorney general issued a statement.","zh-TW":"總檢察長發表了聲明。"}]', NULL, NULL, 3, 470, NULL),
(471, 'attract', '/əˈtrækt/', 'verb', '{"zh-TW":["吸引；招引","吸引"],"en":["to cause to come to a place or participate","to draw someone''s attention or interest"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tract","meaning":"draw/pull (拉)"},"logic":"朝向拉來，即「吸引」。"}', 'attract customers/investors/talent; attract attention / attract customers / attract investment', '[{"en":"The campaign attracted thousands of new customers.","zh-TW":"該活動吸引了數千名新客戶。"},{"en":"We need to attract top talent to remain competitive.","zh-TW":"我們需要吸引頂尖人才以保持競爭力。"},{"en":"The new store attracted many customers.","zh-TW":"新店吸引了許多顧客。"},{"en":"Bright colors attract children''s attention.","zh-TW":"鮮艷的顏色吸引孩子的注意力。"}]', '{"noun":"attraction","adjective":"attractive"}', NULL, 3, 471, 272),
(472, 'attribute', '/əˈtrɪbjuːt/', 'verb', '{"zh-TW":["歸因於；認為是"],"en":["to regard something as being caused by"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tribute","meaning":"assign (分配)"},"logic":"朝向分配原因，即「歸因於」。"}', 'attribute success/failure to', '[{"en":"She attributes her success to hard work and determination.","zh-TW":"她將成功歸因於努力和決心。"},{"en":"The decline was attributed to market conditions.","zh-TW":"下降被歸因於市場狀況。"}]', '{"noun":"attribution"}', NULL, 3, 472, 650),
(473, 'attribution', '/ˌætrɪˈbjuːʃən/', 'noun', '{"zh-TW":["歸因；歸屬"],"en":["the action of regarding a quality or feature as belonging to someone or something"]}', NULL, 'correct attribution / source attribution / attribution analysis', '[{"en":"Proper attribution of sources is required in academic writing.","zh-TW":"學術寫作中需要適當的來源歸因。"},{"en":"Attribution analysis helps investors understand which factors drove portfolio returns.","zh-TW":"歸因分析幫助投資者了解哪些因素推動了投資組合的回報。"}]', '{"verb":"attribute","adjective":"attributable"}', NULL, 4, 473, NULL),
(474, 'attribution model', '/ˌætrɪˈbjuːʃən ˈmɒdəl/', 'noun', '{"zh-TW":["歸因模型"],"en":["a framework for determining which marketing activities drove a conversion"]}', NULL, 'multi-touch attribution model / last-click attribution model', '[{"en":"The attribution model showed that email drove most conversions.","zh-TW":"歸因模型顯示電子郵件推動了最多的轉換。"},{"en":"Choosing the right attribution model is critical for measuring ROI.","zh-TW":"選擇正確的歸因模型對衡量投資報酬率至關重要。"}]', NULL, NULL, 5, 474, NULL),
(475, 'attrition', '/əˈtrɪʃən/', 'noun', '{"zh-TW":["自然減員；磨損"],"en":["the reduction in staff through voluntary departures without replacement"]}', NULL, 'natural attrition / attrition rate / high attrition', '[{"en":"The company relied on attrition rather than layoffs to reduce headcount.","zh-TW":"公司依靠自然減員而非裁員來減少人數。"},{"en":"High attrition in the sales team raised concerns about culture.","zh-TW":"銷售團隊的高自然減員率引發了對企業文化的擔憂。"}]', '{"adjective":"attritive"}', NULL, 3, 475, 750),
(476, 'attrition rate', '/əˈtrɪʃən reɪt/', 'noun', '{"zh-TW":["自然減員率；人員流失率"],"en":["the rate at which employees leave a company over time and are not replaced"]}', NULL, 'reduce attrition rate / high attrition rate / measure attrition rate', '[{"en":"The high attrition rate signaled serious problems with employee morale and management.","zh-TW":"高人員流失率表明員工士氣和管理存在嚴重問題。"},{"en":"Improving working conditions is the most effective way to reduce the attrition rate.","zh-TW":"改善工作條件是降低人員流失率最有效的方法。"}]', '{"noun":"attrition","adjective":"attritional"}', NULL, 5, 476, NULL),
(477, 'auction', '/ˈɔːkʃən/', 'noun', '{"zh-TW":["拍賣"],"en":["a public sale in which goods or property are sold to the highest bidder"]}', NULL, 'public auction / online auction / put up for auction', '[{"en":"The seized assets were sold at a public auction.","zh-TW":"被沒收的資產在公開拍賣會上出售。"},{"en":"She won the bid at the online auction for the collectibles.","zh-TW":"她在線上拍賣會上以最高出價獲得了藏品。"}]', '{"verb":"auction","noun":"auctioneer"}', NULL, 3, 477, NULL),
(478, 'audience', '/ˈɔːdiəns/', 'noun', '{"zh-TW":["觀眾；聽眾"],"en":["people watching or listening to a performance"]}', NULL, 'target audience / live audience', '[{"en":"The audience applauded loudly.","zh-TW":"觀眾大聲鼓掌。"},{"en":"The show attracted a large audience.","zh-TW":"這個節目吸引了大量觀眾。"}]', NULL, NULL, 3, 478, NULL),
(479, 'audio guide', '/''ɔːdiəʊ ɡaɪd/', 'noun', '{"zh-TW":["語音導覽；語音指南"],"en":["a recording providing commentary or information about a place of interest"]}', NULL, 'rent an audio guide / audio guide headset / download an audio guide', '[{"en":"An audio guide is available in twelve languages at the visitor center.","zh-TW":"遊客中心提供十二種語言的語音導覽。"},{"en":"The audio guide explained the history behind each painting in the gallery.","zh-TW":"語音導覽解釋了畫廊中每幅畫作背後的歷史。"}]', NULL, NULL, 4, 479, NULL),
(480, 'audit', '/ˈɔːdɪt/', 'noun', '{"zh-TW":["審計；稽核"],"en":["an official examination of accounts or processes"]}', '{"root":{"text":"audit","meaning":"hear (聽)"},"logic":"最初為聽取帳目報告，即「審計」。"}', 'conduct an audit / annual audit', '[{"en":"The firm conducts an annual financial audit.","zh-TW":"該公司進行年度財務審計。"},{"en":"An internal audit revealed several discrepancies.","zh-TW":"內部稽核揭露了幾項差異。"}]', '{"noun":"auditor"}', NULL, 2, 480, 273),
(481, 'audit committee', '/ˈɔːdɪt kəˈmɪti/', 'noun', '{"zh-TW":["審計委員會"],"en":["a board committee overseeing financial reporting and audit processes"]}', NULL, 'appoint an audit committee / audit committee meeting', '[{"en":"The audit committee reviewed the external auditor''s findings.","zh-TW":"審計委員會審查了外部審計師的調查結果。"},{"en":"An independent audit committee is required for listed companies.","zh-TW":"上市公司需要設立獨立的審計委員會。"}]', NULL, NULL, 5, 481, NULL),
(482, 'audit trail', '/ˈɔːdɪt treɪl/', 'noun', '{"zh-TW":["審計追蹤；稽核軌跡"],"en":["a documented record of all transactions and changes for accountability"]}', NULL, 'maintain an audit trail / complete audit trail / audit trail review', '[{"en":"The audit trail showed every change made to the financial records.","zh-TW":"審計追蹤顯示了對財務記錄所做的每一項更改。"},{"en":"A complete audit trail is required for compliance purposes.","zh-TW":"合規目的需要完整的審計追蹤。"}]', NULL, NULL, 4, 482, NULL),
(483, 'auditor', '/ˈɔːdɪtər/', 'noun', '{"zh-TW":["審計師；稽核人員"],"en":["a person who conducts an official examination of financial records"]}', NULL, 'external auditor / internal auditor / appoint an auditor', '[{"en":"The auditor found discrepancies in the accounts.","zh-TW":"審計師在帳目中發現了差異。"},{"en":"The firm''s auditor issued a clean audit opinion.","zh-TW":"公司的審計師發表了無保留意見。"}]', '{"plural":"auditors"}', NULL, 3, 483, NULL),
(484, 'augment', '/ɔːɡˈment/', 'verb', '{"zh-TW":["增加；擴充"],"en":["to make something greater by adding to it"]}', NULL, 'augment resources / augment capabilities / augment the workforce', '[{"en":"Companies use freelancers to augment their full-time workforce.","zh-TW":"公司使用自由工作者來擴充其全職勞動力。"},{"en":"Wearable sensors augment the doctor''s ability to monitor patients remotely.","zh-TW":"可穿戴感測器增強了醫生遠程監測患者的能力。"}]', '{"noun":"augmentation","adjective":"augmented"}', NULL, 3, 484, NULL),
(485, 'auspicious', '/''ɔːˌspɪʃəs/', 'adjective', '{"zh-TW":["吉利的；有利的"],"en":["conducive to success; favorable; giving or being a sign of future success"]}', NULL, 'auspicious start / auspicious occasion / auspicious sign', '[{"en":"The new product launch had an auspicious start with record first-day sales.","zh-TW":"新產品發布有了一個吉利的開始，第一天創下了銷售記錄。"},{"en":"She chose an auspicious date for signing the contract, according to cultural tradition.","zh-TW":"她根據文化傳統，選擇了一個吉利的日期簽署合同。"}]', '{"adverb":"auspiciously","noun":"auspice"}', NULL, 4, 485, NULL),
(486, 'austerity', '/ɒˈsterɪti/', 'noun', '{"zh-TW":["緊縮；節約"],"en":["government policies cutting spending to reduce budget deficits"]}', NULL, 'austerity measures / period of austerity / implement austerity', '[{"en":"The government introduced austerity measures to reduce the deficit.","zh-TW":"政府引入緊縮措施以削減赤字。"},{"en":"Years of austerity reduced public services significantly.","zh-TW":"多年的緊縮政策顯著縮減了公共服務。"}]', '{"adjective":"austere"}', NULL, 3, 486, NULL),
(487, 'auteur', '/ɒˈtɜːr/', 'noun', '{"zh-TW":["作者型導演；藝術創作者"],"en":["a filmmaker who has a distinctive personal style and creative control"]}', NULL, 'celebrated auteur / auteur theory / independent auteur', '[{"en":"The auteur crafted a deeply personal film that divided critics.","zh-TW":"這位作者型導演創作了一部極為個人化的電影，引發評論兩極分化。"},{"en":"Auteur theory credits directors as the primary authors of films.","zh-TW":"作者論認為導演是電影的主要作者。"}]', NULL, NULL, 2, 487, NULL),
(488, 'authentic', '/ɔːˈθentɪk/', 'adjective', '{"zh-TW":["真實的；正宗的"],"en":["genuine; of undisputed origin"]}', '{"root":{"text":"authent","meaning":"original (原始的)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與原始真實相關的，即「正宗的」。"}', 'authentic cuisine / authentic experience', '[{"en":"This restaurant serves authentic Italian food.","zh-TW":"這家餐廳供應正宗義大利料理。"},{"en":"Is this an authentic Gucci bag?","zh-TW":"這是正品Gucci包嗎？"}]', '{"noun":"authenticity","adverb":"authentically"}', NULL, 3, 488, NULL),
(489, 'authenticate', 'ɔːˈθɛntɪkeɪt', 'verb', '{"zh-TW":["驗證；認證","確認真實性"],"en":["to prove something is genuine","to verify"]}', NULL, 'authenticate a user/authenticate documents', '[{"en":"Please authenticate your identity.","zh-TW":"請驗證您的身份。"}]', '{"noun":"authentication","adjective":"authenticated"}', NULL, 4, 489, NULL),
(490, 'authorised capital', '/ˈɔːθəraɪzd ˈkæpɪtəl/', 'noun', '{"zh-TW":["授權資本；法定股本"],"en":["the maximum amount of share capital a company is permitted to issue"]}', NULL, 'increase authorised capital / authorised capital structure', '[{"en":"The company increased its authorised capital to allow a larger share issuance.","zh-TW":"公司增加了其授權資本以允許更大規模的股票發行。"},{"en":"Authorised capital sets an upper limit on the shares a company may sell.","zh-TW":"授權資本設定了公司可出售股份的上限。"}]', '{"synonym":"authorized share capital"}', NULL, 5, 490, NULL),
(491, 'authority', '/ɔːˈθɒrəti/', 'noun', '{"zh-TW":["權威；當局"],"en":["the power to give orders","an organization with official power"]}', '{"root":{"text":"author","meaning":"originator (創始者)"},"suffix":{"text":"-ity","meaning":"state of (狀態)"},"logic":"身為創始者的地位，即「權威」。"}', 'local authority / authority figure / have authority', '[{"en":"The local authority approved the building plan.","zh-TW":"地方當局批准了建築計畫。"},{"en":"He spoke with authority on the subject.","zh-TW":"他在這個議題上很有權威。"}]', '{"adjective":"authoritative","verb":"authorize","noun2":"authorization"}', NULL, 3, 491, 274),
(492, 'authorization', '/ˌɔːθərɪˈzeɪʃən/', 'noun', '{"zh-TW":["授權；批准"],"en":["official permission or power to do something"]}', NULL, 'obtain authorization / require authorization', '[{"en":"Please obtain authorization before accessing restricted files.","zh-TW":"訪問受限文件前請先獲得授權。"},{"en":"Payment authorization was granted by the finance director.","zh-TW":"付款授權由財務主管批准。"}]', '{"verb":"authorize","adjective":"authorized"}', NULL, 5, 492, 511),
(493, 'authorization level', '/ˌɔːθərɪˈzeɪʃən ˈlevəl/', 'noun', '{"zh-TW":["授權級別"],"en":["the limit of spending or approval authority assigned to a role or individual"]}', NULL, 'set authorization levels / authorization level exceeded', '[{"en":"Purchases above $10000 require manager authorization level approval.","zh-TW":"超過10,000元的採購需要經理授權級別的批准。"},{"en":"The authorization level for capital expenditure was raised to $50000.","zh-TW":"資本支出的授權級別提高到了5萬元。"}]', NULL, NULL, 5, 493, NULL),
(494, 'authorize', '/ˈɔːθəraɪz/', 'verb', '{"zh-TW":["授權；批准"],"en":["to give official permission for something"]}', '{"root":{"text":"author","meaning":"creator (創造者)"},"suffix":{"text":"-ize","meaning":"to make (使)"},"logic":"使成為有權者，即「授權」。"}', 'authorize payment/access/use', '[{"en":"Only the director can authorize expenditures over $10,000.","zh-TW":"只有主管可以授權超過10,000美元的支出。"},{"en":"The transaction was not authorized.","zh-TW":"該交易未獲授權。"}]', '{"noun":"authorization","adjective":"authorized"}', NULL, 3, 494, 75),
(495, 'authorized dealer', '/ˈɔːθəraɪzd ˈdiːlər/', 'noun', '{"zh-TW":["授權經銷商"],"en":["a seller officially approved by a manufacturer to sell its products"]}', NULL, 'become an authorized dealer / authorized dealer network', '[{"en":"Only purchase from an authorized dealer to ensure product authenticity.","zh-TW":"只從授權經銷商購買以確保產品真實性。"},{"en":"The authorized dealer program expanded to 50 locations.","zh-TW":"授權經銷商計劃擴展到了50個地點。"}]', NULL, NULL, 5, 495, NULL),
(496, 'automated', 'ˈɔːtəmeɪtɪd', 'adjective', '{"zh-TW":["自動化的；自動的","機械化的"],"en":["using automatic equipment","operated without manual control"]}', NULL, 'automated system/automated report', '[{"en":"The automated system generates weekly reports.","zh-TW":"自動化系統每週生成報告。"}]', '{"verb":"automate","noun":"automation"}', NULL, 3, 496, NULL),
(497, 'automatic', '/ˌɔːtəˈmætɪk/', 'adjective', '{"zh-TW":["自動的"],"en":["operating by itself with little human control"]}', '{"root":{"text":"auto","meaning":"self (自己)"},"suffix":{"text":"-matic","meaning":"acting (行動的)"},"logic":"自己行動的，即「自動的」。"}', 'automatic update/renewal/response; automatic transmission / automatic reply / fully automatic', '[{"en":"The system sends automatic email confirmations.","zh-TW":"系統會發送自動電子郵件確認。"},{"en":"Payments are processed automatically each month.","zh-TW":"付款每月自動處理。"},{"en":"The doors open automatically.","zh-TW":"門會自動開啟。"},{"en":"The system sends automatic reminders.","zh-TW":"系統會發送自動提醒。"}]', '{"adverb":"automatically","noun":"automation","verb":"automate"}', NULL, 3, 497, NULL),
(498, 'automatic renewal', '/ˌɔːtəˈmætɪk rɪˈnjuːəl/', 'noun', '{"zh-TW":["自動續約"],"en":["the extension of a contract for another term without requiring affirmative action"]}', NULL, 'automatic renewal clause / opt out of automatic renewal', '[{"en":"The subscription had an automatic renewal clause unless cancelled in advance.","zh-TW":"訂閱有自動續約條款，除非提前取消。"},{"en":"Customers must be notified before an automatic renewal takes effect.","zh-TW":"在自動續約生效之前，必須通知客戶。"}]', NULL, NULL, 5, 498, NULL),
(499, 'automation', '/ˌɔːtəˈmeɪʃən/', 'noun', '{"zh-TW":["自動化"],"en":["using technology to perform tasks with minimal human intervention"]}', NULL, 'process automation / robotic automation / automation technology / workflow automation', '[{"en":"Automation reduced the time needed for data entry by 80%.","zh-TW":"自動化將數據輸入所需時間減少了80%。"},{"en":"The factory''s automation increased output while reducing labor costs.","zh-TW":"工廠自動化在降低勞動成本的同時提高了產量。"}]', '{"verb":"automate","adjective":"automated","noun":"automator"}', NULL, 4, 499, 275);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(500, 'autonomous vehicle', '/ɔːˈtɒnəməs ˈviːɪkəl/', 'noun', '{"zh-TW":["自駕車；自動駕駛車輛"],"en":["a vehicle capable of navigating without human input"]}', NULL, 'deploy autonomous vehicles / test autonomous vehicles / autonomous vehicle technology', '[{"en":"Autonomous vehicles use sensors and AI to navigate roads safely.","zh-TW":"自駕車使用感測器和人工智慧安全導航道路。"},{"en":"Regulatory frameworks for autonomous vehicles are still being developed.","zh-TW":"自駕車的監管框架仍在制定中。"}]', '{"adjective":"autonomous"}', NULL, 5, 500, NULL),
(501, 'autonomy', '/ɔːˈtɒnəmi/', 'noun', '{"zh-TW":["自主；自主權"],"en":["freedom to act independently without external control"]}', NULL, 'organizational autonomy / operational autonomy / give autonomy', '[{"en":"Subsidiaries operate with a high degree of autonomy.","zh-TW":"子公司以高度自主的方式運營。"},{"en":"Employees with more autonomy tend to show greater job satisfaction.","zh-TW":"擁有更多自主權的員工往往表現出更高的工作滿意度。"}]', '{"adjective":"autonomous","adverb":"autonomously"}', NULL, 3, 501, NULL),
(502, 'autumn', '/ˈɔːtəm/', 'noun', '{"zh-TW":["秋天"],"en":["the season between summer and winter"]}', NULL, 'autumn season / in autumn; in autumn / autumn leaves', '[{"en":"Sales typically increase in autumn.","zh-TW":"銷售額通常在秋季增加。"},{"en":"The autumn collection launches next week.","zh-TW":"秋季系列下週發布。"},{"en":"Leaves change color in autumn.","zh-TW":"秋天葉子會變色。"},{"en":"Autumn is my favorite season.","zh-TW":"秋天是我最喜歡的季節。"}]', '{"noun":"autumn","adjective":"autumnal"}', NULL, 2, 502, NULL),
(503, 'availability', '/əˌveɪləˈbɪlɪti/', 'noun', '{"zh-TW":["可用性；空房情況"],"en":["the state of being available or accessible"]}', NULL, 'room availability / check availability', '[{"en":"Please check room availability for the dates you need.","zh-TW":"請查看您所需日期的房間空房情況。"},{"en":"Availability is limited during the holiday season.","zh-TW":"假日期間可用性有限。"}]', '{"verb":"avail","adjective":"available"}', NULL, 4, 503, 957),
(504, 'available', '/əˈveɪləbl/', 'adjective', '{"zh-TW":["可用的；可獲得的"],"en":["able to be used or obtained"]}', '{"root":{"text":"avail","meaning":"be strong/be of use (有用)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠被使用的，即「可用的」。"}', 'available for / currently available', '[{"en":"The product is now available in all major stores.","zh-TW":"該產品現已在所有主要商店有售。"},{"en":"I''m available for a meeting on Thursday afternoon.","zh-TW":"我週四下午有空開會。"}]', '{"noun":"availability"}', NULL, 3, 504, 11),
(505, 'avalanche', '/ˈævəlæntʃ/', 'noun', '{"zh-TW":["雪崩"],"en":["a mass of snow falling rapidly down a mountainside"]}', '{"root":{"text":"avalanche","meaning":"descend (滑落)"},"logic":"源自法語 avaler（下降），指雪的快速滑落。"}', 'trigger an avalanche / avalanche warning', '[{"en":"The avalanche buried the entire village.","zh-TW":"雪崩掩埋了整個村莊。"},{"en":"Skiers should be aware of avalanche risks.","zh-TW":"滑雪者應注意雪崩風險。"}]', NULL, NULL, 3, 505, NULL),
(506, 'avant-garde', '/ˌævɒ̃ ˈɡɑːrd/', 'adjective', '{"zh-TW":["前衛的；先鋒的"],"en":["new and experimental in ideas or art"]}', NULL, 'avant-garde art / avant-garde movement / avant-garde style', '[{"en":"The gallery exhibited avant-garde sculptures that challenged conventional forms.","zh-TW":"畫廊展出了挑戰傳統形式的前衛雕塑。"},{"en":"Avant-garde music often alienates mainstream audiences at first.","zh-TW":"前衛音樂最初往往讓主流觀眾感到陌生。"}]', '{"noun":"avant-garde"}', NULL, 4, 506, NULL),
(507, 'average', 'ˈævərɪdʒ', 'noun', '{"zh-TW":["平均；一般水準","平均值"],"en":["the middle value of a group","a usual level"]}', NULL, 'on average/industry average', '[{"en":"The average salary in this sector is high.","zh-TW":"這個行業的平均薪資很高。"}]', '{"adjective":"average","adverb":"on average"}', NULL, 3, 507, NULL),
(508, 'average collection period', '/ˈævərɪdʒ kəˈlekʃən ˈpɪəriəd/', 'noun', '{"zh-TW":["平均收款期"],"en":["the average number of days it takes to collect payment after a sale"]}', NULL, 'calculate average collection period / shorten average collection period', '[{"en":"The average collection period decreased from 45 to 30 days.","zh-TW":"平均收款期從45天縮短到了30天。"},{"en":"A shorter average collection period improves cash flow management.","zh-TW":"較短的平均收款期改善了現金流管理。"}]', NULL, NULL, 5, 508, NULL),
(509, 'avoid', '/əˈvɔɪd/', 'verb', '{"zh-TW":["避免；迴避"],"en":["to keep away from or stop oneself from doing"]}', '{"prefix":{"text":"a-","meaning":"away (離開)"},"root":{"text":"void","meaning":"empty (空)"},"logic":"使離開空虛（危險），即「避免」。"}', 'avoid risk/mistakes/delays', '[{"en":"To avoid delays, please submit your documents early.","zh-TW":"為避免延遲，請提早提交文件。"},{"en":"The company took steps to avoid further losses.","zh-TW":"公司採取措施避免進一步損失。"}]', '{"adjective":"avoidable","noun":"avoidance"}', NULL, 2, 509, NULL),
(510, 'awake', '/əˈweɪk/', 'adjective', '{"zh-TW":["醒著的"],"en":["not sleeping"]}', NULL, 'wide awake / stay awake', '[{"en":"Are you still awake?","zh-TW":"你還醒著嗎？"},{"en":"I lay awake all night.","zh-TW":"我整晚都醒著。"}]', '{"verb":"awaken"}', NULL, 2, 510, NULL),
(511, 'award', '/əˈwɔːrd/', 'noun', '{"zh-TW":["獎項；獎金","授予","獎；獎項"],"en":["a prize given for achievement","to officially give something as a reward"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"ward","meaning":"guard/watch (看守)"},"logic":"朝向看守評定後給予，即「獎項」。"}', 'award a contract/prize/grant; award ceremony / win an award', '[{"en":"The contract was awarded to the lowest bidder.","zh-TW":"合約授予了最低出價者。"},{"en":"She received an award for outstanding performance.","zh-TW":"她因傑出表現獲得獎項。"},{"en":"She won an award for best actress.","zh-TW":"她獲得了最佳女主角獎。"},{"en":"The awards ceremony is tonight.","zh-TW":"頒獎典禮今晚舉行。"}]', '{"verb":"award"}', NULL, 2, 511, NULL),
(512, 'aware', 'əˈwɛr', 'adjective', '{"zh-TW":["意識到的；知道的","了解的"],"en":["having knowledge of something","conscious of"]}', NULL, 'be aware of/fully aware', '[{"en":"Please be aware of the new policy.","zh-TW":"請注意新政策。"}]', '{"noun":"awareness","adverb":"with awareness"}', NULL, 2, 512, 276),
(513, 'axiom', '/ˈæksiəm/', 'noun', '{"zh-TW":["公理；自明之理"],"en":["a statement accepted as true without proof"]}', NULL, 'fundamental axiom / basic axiom / accept an axiom', '[{"en":"It is an axiom that markets seek equilibrium.","zh-TW":"市場尋求均衡是一個公理。"},{"en":"The researcher challenged the prevailing axiom of the field.","zh-TW":"研究員挑戰了該領域的主流公理。"}]', '{"adjective":"axiomatic","adverb":"axiomatically"}', NULL, 2, 513, NULL),
(514, 'B2B', '/ˌbiː tə ˈbiː/', 'adjective', '{"zh-TW":["企業對企業的；B2B"],"en":["business to business; transactions between companies"]}', NULL, 'B2B sales / B2B marketing / B2B e-commerce / B2B platform', '[{"en":"The company shifted its focus from B2C to B2B customers.","zh-TW":"公司將重心從消費者市場轉向企業客戶。"},{"en":"B2B sales cycles are typically longer than consumer sales.","zh-TW":"B2B銷售週期通常比消費者銷售更長。"}]', '{"full form":"business to business"}', NULL, 1, 514, NULL),
(515, 'B2C', '/ˌbiː tə ˈsiː/', 'adjective', '{"zh-TW":["企業對消費者的；B2C"],"en":["business to consumer; transactions between a company and individual consumers"]}', NULL, 'B2C marketing / B2C platform / B2C e-commerce', '[{"en":"The new product line targets B2C customers through retail channels.","zh-TW":"新產品線通過零售渠道針對消費者客戶。"},{"en":"B2C brands invest heavily in social media advertising.","zh-TW":"B2C品牌在社群媒體廣告上投入大量資金。"}]', '{"full form":"business to consumer"}', NULL, 1, 515, NULL),
(516, 'baby', '/ˈbeɪbi/', 'noun', '{"zh-TW":["嬰兒；寶寶"],"en":["a very young child"]}', NULL, 'have a baby / baby products; baby shower / have a baby; baby shower / baby boom', '[{"en":"She is on maternity leave after having a baby.","zh-TW":"她生完孩子後在休產假。"},{"en":"Baby products are on the second floor.","zh-TW":"嬰兒用品在二樓。"},{"en":"The baby is sleeping.","zh-TW":"寶寶正在睡覺。"},{"en":"They''re having a baby next month.","zh-TW":"他們下個月要生寶寶了。"},{"en":"The baby is sleeping.","zh-TW":"寶寶在睡覺。"},{"en":"She''s expecting a baby in June.","zh-TW":"她預計六月生寶寶。"}]', '{"noun":"baby","adjective":"babyish"}', NULL, 1, 516, NULL),
(517, 'back', '/bæk/', 'noun', '{"zh-TW":["背部；後面","背部；後面；回去；支持"],"en":["the rear part of the body or thing","the rear part; to a previous position; to support"]}', NULL, 'go back / back and forth; go back / back up / at the back of', '[{"en":"My back hurts.","zh-TW":"我的背很痛。"},{"en":"I''ll be back in an hour.","zh-TW":"我一小時後回來。"},{"en":"He sat at the back of the room.","zh-TW":"他坐在房間後面。"},{"en":"I''ll be back in five minutes.","zh-TW":"我五分鐘後回來。"}]', '{"noun":"background, backup","adjective":"backward"}', NULL, 1, 517, NULL),
(518, 'back office', '/bæk ˈɒfɪs/', 'noun', '{"zh-TW":["後台；後勤辦公室"],"en":["the administrative and support functions of a business not visible to clients"]}', NULL, 'manage back office operations / back office system', '[{"en":"The bank upgraded its back office software to reduce processing errors.","zh-TW":"銀行升級了後台軟件以減少處理錯誤。"},{"en":"Back office functions include accounting, IT, and compliance.","zh-TW":"後台功能包括會計、IT和合規。"}]', '{"opposite":"front office"}', NULL, 4, 518, NULL),
(519, 'back order', '/bæk ˈɔːrdər/', 'noun', '{"zh-TW":["待補貨訂單；延遲交貨訂單"],"en":["an order placed for goods that are currently out of stock"]}', NULL, 'place a back order / back order fulfillment', '[{"en":"Customers were notified that their orders were placed on back order.","zh-TW":"客戶被告知其訂單處於待補貨狀態。"},{"en":"The warehouse worked overtime to fulfill outstanding back orders.","zh-TW":"倉庫加班以完成未結的待補貨訂單。"}]', '{"verb":"back order"}', NULL, 4, 519, NULL),
(520, 'back-office operations', '/bæk ˈɒfɪs ˌɒpəˈreɪʃənz/', 'noun', '{"zh-TW":["後台運營"],"en":["administrative and support activities that are not customer-facing"]}', NULL, 'improve back-office operations / automate back-office operations', '[{"en":"Automating back-office operations reduced processing time by 40%.","zh-TW":"自動化後台運營將處理時間縮短了40%。"},{"en":"Back-office operations include transaction processing and compliance reporting.","zh-TW":"後台運營包括交易處理和合規報告。"}]', NULL, NULL, 5, 520, NULL),
(521, 'background', '/ˈbækˌɡraʊnd/', 'noun', '{"zh-TW":["背景；背景資料"],"en":["a person''s history, education, or experience"]}', NULL, 'professional background / background check', '[{"en":"Her background in finance made her ideal for the role.","zh-TW":"她的金融背景使她非常適合這個職位。"},{"en":"A background check is required before the job offer is confirmed.","zh-TW":"在確認錄用前需要進行背景調查。"}]', NULL, NULL, 4, 521, 512),
(522, 'background check', '/ˈbækˌɡraʊnd tʃek/', 'noun', '{"zh-TW":["背景調查"],"en":["verification of an applicant''s personal history and credentials"]}', NULL, 'conduct a background check / pass a background check / pre-employment background check', '[{"en":"All applicants must pass a background check before being hired.","zh-TW":"所有申請者在被錄用前必須通過背景調查。"},{"en":"The background check revealed a discrepancy in the resume.","zh-TW":"背景調查發現了簡歷中的差異。"}]', '{"verb":"run a background check"}', NULL, 5, 522, NULL),
(523, 'backlog', '/ˈbæklɒɡ/', 'noun', '{"zh-TW":["待辦清單；積壓工作"],"en":["a list of tasks or features yet to be completed, prioritized for future work"]}', NULL, 'product backlog / backlog grooming / clear the backlog / backlog item', '[{"en":"The product backlog was reviewed and prioritized at the start of each sprint.","zh-TW":"產品待辦清單在每個衝刺開始時進行審查和優先排序。"},{"en":"The team worked through the backlog of support tickets.","zh-TW":"團隊處理了積壓的支援票務。"}]', '{"verb":"backlog"}', NULL, 3, 523, 751),
(524, 'backlog of orders', '/ˈbæklɒɡ əv ˈɔːrdərz/', 'noun', '{"zh-TW":["積壓訂單"],"en":["a build-up of unfilled customer orders awaiting fulfillment"]}', NULL, 'reduce the backlog of orders / backlog of orders indicator', '[{"en":"The backlog of orders grew to three weeks as production was delayed.","zh-TW":"隨著生產延誤，積壓訂單增長到了三週。"},{"en":"A rising backlog of orders indicates strong demand and potential revenue.","zh-TW":"不斷增長的積壓訂單表明了強勁的需求和潛在收入。"}]', NULL, NULL, 5, 524, NULL),
(525, 'backorder', '/ˈbækˌɔːrdər/', 'noun', '{"zh-TW":["延期交貨訂單；積壓訂單"],"en":["an order that cannot be fulfilled immediately due to lack of stock"]}', NULL, 'place on backorder / clear backorders / high backorder rate', '[{"en":"Demand surged and many items were placed on backorder.","zh-TW":"需求激增，許多商品被列為延期交貨。"},{"en":"The factory worked overtime to clear the backorder queue.","zh-TW":"工廠加班以清理積壓訂單。"}]', '{"verb":"backorder","adjective":"backordered"}', NULL, 3, 525, NULL),
(526, 'backpacker', '/''bækˌpækər/', 'noun', '{"zh-TW":["背包客"],"en":["a person who travels with minimal luggage carrying a backpack"]}', NULL, 'budget backpacker / solo backpacker / experienced backpacker', '[{"en":"Many backpackers stay in hostels to save money.","zh-TW":"許多背包客住在青年旅舍以節省費用。"},{"en":"She spent a year as a backpacker traveling through Southeast Asia.","zh-TW":"她花了一年時間作為背包客遊覽東南亞。"}]', '{"noun":"backpacking","verb":"backpack"}', NULL, 4, 526, NULL),
(527, 'backpacking trip', '/''bækˌpækɪŋ trɪp/', 'noun', '{"zh-TW":["背包旅行；自助旅行"],"en":["a low-budget trip where the traveler carries their belongings in a backpack"]}', NULL, 'plan a backpacking trip / go on a backpacking trip / solo backpacking trip', '[{"en":"A backpacking trip through Europe taught her independence and resourcefulness.","zh-TW":"穿越歐洲的背包旅行教會了她獨立和足智多謀。"},{"en":"He saved for two years to fund a six-month backpacking trip around the world.","zh-TW":"他存了兩年錢，資助了一次為期六個月的環球背包旅行。"}]', NULL, NULL, 5, 527, NULL),
(528, 'backpropagation', '/ˌbækˌprɒpəˈɡeɪʃən/', 'noun', '{"zh-TW":["反向傳播"],"en":["an algorithm used to train neural networks by adjusting weights"]}', NULL, 'backpropagation algorithm / apply backpropagation / gradient descent backpropagation', '[{"en":"Backpropagation is the core algorithm for training deep neural networks.","zh-TW":"反向傳播是訓練深度神經網路的核心算法。"},{"en":"The model improved accuracy through thousands of backpropagation iterations.","zh-TW":"模型通過數千次反向傳播迭代提高了準確性。"}]', NULL, NULL, 5, 528, NULL),
(529, 'backup', '/ˈbækʌp/', 'noun', '{"zh-TW":["備份"],"en":["a copy of data stored separately in case of loss"]}', NULL, 'create a backup / data backup', '[{"en":"Always create a backup of important files.","zh-TW":"務必對重要文件進行備份。"},{"en":"The system backup is scheduled to run at midnight.","zh-TW":"系統備份安排在午夜執行。"}]', '{"verb":"back up","adjective":"backed up"}', NULL, 2, 529, NULL),
(530, 'backward integration', '/ˈbækwərd ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["向後整合；向上游整合"],"en":["a strategy where a company acquires its suppliers to control upstream activities"]}', NULL, 'pursue backward integration / backward integration strategy', '[{"en":"Backward integration gave the company direct control over raw material supply.","zh-TW":"向後整合使公司直接控制了原材料供應。"},{"en":"Buying out a key supplier is a common backward integration approach.","zh-TW":"收購主要供應商是常見的向後整合方式。"}]', '{"opposite":"forward integration"}', NULL, 5, 530, NULL),
(531, 'bad', '/bæd/', 'adjective', '{"zh-TW":["壞的；糟糕的","壞的；糟糕的；嚴重的"],"en":["of poor quality; unpleasant","of poor quality; unpleasant; serious"]}', NULL, 'not bad / go bad; go bad (變壞) / not bad (還不錯)', '[{"en":"The weather is really bad today.","zh-TW":"今天天氣真的很糟。"},{"en":"The milk has gone bad.","zh-TW":"牛奶壞了。"},{"en":"The weather was really bad yesterday.","zh-TW":"昨天天氣真的很糟。"},{"en":"I feel bad about what happened.","zh-TW":"我對發生的事感到抱歉。"}]', '{"adverb":"badly","noun":"badness"}', NULL, 1, 531, NULL),
(532, 'bag', '/bæɡ/', 'noun', '{"zh-TW":["袋子；包","袋子；手提包"],"en":["a container made of flexible material","a container made of paper, plastic, cloth, or leather"]}', NULL, 'shopping bag / bag of tricks; shopping bag / handbag / luggage bag', '[{"en":"She put the books in her bag.","zh-TW":"她把書放進了包裡。"},{"en":"Can I have a plastic bag?","zh-TW":"可以給我一個塑膠袋嗎？"},{"en":"She put the groceries in a bag.","zh-TW":"她把雜貨放進袋子裡。"},{"en":"Don''t forget your bag.","zh-TW":"別忘了你的包。"}]', NULL, NULL, 1, 532, NULL),
(533, 'baggage', '/ˈbægɪdʒ/', 'noun', '{"zh-TW":["行李"],"en":["bags and suitcases used when traveling"]}', NULL, 'carry-on baggage / excess baggage', '[{"en":"Passengers are allowed one piece of carry-on baggage.","zh-TW":"乘客可攜帶一件手提行李。"},{"en":"The airline charges a fee for excess baggage.","zh-TW":"航空公司對超重行李收費。"}]', '{"verb":"pack","adjective":"excess"}', NULL, 3, 533, NULL),
(534, 'baggage allowance', '/ˈbægɪdʒ əˈlaʊəns/', 'noun', '{"zh-TW":["行李限額"],"en":["the weight or number of bags permitted on a flight"]}', NULL, 'exceed the baggage allowance / baggage allowance policy', '[{"en":"Passengers in economy class have a 23 kg baggage allowance.","zh-TW":"經濟艙乘客有23公斤的行李限額。"},{"en":"Check the baggage allowance before packing.","zh-TW":"打包前請查看行李限額。"}]', NULL, NULL, 5, 534, NULL),
(535, 'baggage carousel', '/''bæɡɪdʒ ˌkærəˈsel/', 'noun', '{"zh-TW":["行李轉盤"],"en":["a revolving conveyor belt at an airport on which checked baggage is delivered to arriving passengers"]}', NULL, 'wait at the baggage carousel / baggage carousel area / find the baggage carousel', '[{"en":"Passengers wait at the baggage carousel to collect their checked luggage.","zh-TW":"旅客在行李轉盤旁等待取回託運行李。"},{"en":"Her suitcase was one of the last bags to appear on the baggage carousel.","zh-TW":"她的手提箱是行李轉盤上最後出現的行李之一。"}]', NULL, NULL, 5, 535, NULL),
(536, 'baggage claim', '/ˈbægɪdʒ kleɪm/', 'noun', '{"zh-TW":["行李提領處"],"en":["the area where passengers collect their luggage"]}', NULL, 'proceed to baggage claim / baggage claim belt', '[{"en":"Proceed to baggage claim after clearing customs.","zh-TW":"通關後請前往行李提領處。"},{"en":"Her suitcase was the last one on the baggage claim belt.","zh-TW":"她的行李箱是行李輸送帶上最後一件。"}]', NULL, NULL, 5, 536, NULL),
(537, 'bail', '/beɪl/', 'noun', '{"zh-TW":["保釋金"],"en":["money paid to release someone from jail before trial"]}', NULL, 'post bail / bail out', '[{"en":"The judge set bail at $50,000.","zh-TW":"法官將保釋金定為五萬美元。"},{"en":"His family posted bail.","zh-TW":"他的家人交了保釋金。"}]', NULL, NULL, 1, 537, NULL),
(538, 'bailout', '/ˈbeɪlaʊt/', 'noun', '{"zh-TW":["紓困；緊急援助"],"en":["emergency financial assistance given to a failing business or economy"]}', NULL, 'government bailout / bank bailout / financial bailout', '[{"en":"The government approved a bailout package to prevent the bank from collapsing.","zh-TW":"政府批准了一項紓困計畫，以防止銀行崩潰。"},{"en":"Critics argued that bailouts encourage reckless risk-taking by corporations.","zh-TW":"批評者認為，紓困鼓勵了企業不計後果地冒險。"}]', NULL, NULL, 3, 538, NULL),
(539, 'balance', '/ˈbæləns/', 'noun', '{"zh-TW":["平衡；餘額"],"en":["an even distribution of weight","the amount of money remaining in an account"]}', '{"root":{"text":"bi","meaning":"two (二)"},"suffix":{"text":"-lance","meaning":"plate (盤)"},"logic":"兩個盤子的均衡，即「平衡」。"}', 'balance sheet / maintain balance / account balance', '[{"en":"Please check your account balance before making a transfer.","zh-TW":"轉帳前請確認帳戶餘額。"},{"en":"We must maintain a balance between cost and quality.","zh-TW":"我們必須在成本和品質之間保持平衡。"}]', '{"adjective":"balanced"}', NULL, 3, 539, 277),
(540, 'balance brought forward', '/ˈbæləns brɔːt ˈfɔːrwərd/', 'noun', '{"zh-TW":["期初餘額；結轉餘額"],"en":["the balance from a previous period carried into the current accounting period"]}', NULL, 'record balance brought forward / balance brought forward from last month', '[{"en":"The balance brought forward was $15000 from the previous month.","zh-TW":"上月結轉的期初餘額為15,000元。"},{"en":"Balance brought forward ensures continuity between accounting periods.","zh-TW":"結轉餘額確保了會計期間之間的連續性。"}]', NULL, NULL, 5, 540, NULL),
(541, 'balance forward', '/ˈbæləns ˈfɔːrwərd/', 'noun', '{"zh-TW":["結轉餘額"],"en":["an amount carried over to the next accounting period"]}', NULL, 'balance forward from last month / carry a balance forward', '[{"en":"The balance forward from last month was two thousand dollars.","zh-TW":"上個月的結轉餘額為兩千元。"},{"en":"Any unpaid balance will be carried forward to the next statement.","zh-TW":"任何未付餘額將結轉到下一期帳單。"}]', NULL, NULL, 5, 541, NULL),
(542, 'balance of payments', '/ˈbæləns əv ˈpeɪmənts/', 'noun', '{"zh-TW":["國際收支；收支平衡"],"en":["a record of all financial transactions between a country and the rest of the world"]}', NULL, 'monitor the balance of payments / balance of payments deficit', '[{"en":"A persistent balance of payments deficit may weaken the national currency.","zh-TW":"持續的國際收支赤字可能削弱本國貨幣。"},{"en":"The government implemented trade policies to improve the balance of payments.","zh-TW":"政府實施了貿易政策以改善國際收支。"}]', NULL, NULL, 5, 542, NULL),
(543, 'balance of trade', '/ˈbæləns əv treɪd/', 'noun', '{"zh-TW":["貿易差額"],"en":["the difference between a country''s exports and imports"]}', NULL, 'positive balance of trade / balance of trade deficit', '[{"en":"A positive balance of trade means exports exceed imports.","zh-TW":"貿易差額為正表示出口超過進口。"},{"en":"The country worked to improve its negative balance of trade.","zh-TW":"該國努力改善其負貿易差額。"}]', NULL, NULL, 5, 543, NULL),
(544, 'balance sheet', '/ˈbæləns ʃiːt/', 'noun', '{"zh-TW":["資產負債表"],"en":["a financial statement showing assets, liabilities, and equity"]}', NULL, 'review the balance sheet / balance sheet strength / off-balance sheet', '[{"en":"The balance sheet showed total assets of $500 million.","zh-TW":"資產負債表顯示總資產為5億美元。"},{"en":"Investors scrutinize the balance sheet for hidden liabilities.","zh-TW":"投資者仔細審查資產負債表以發現隱藏負債。"}]', NULL, NULL, 5, 544, NULL),
(545, 'balance sheet analysis', '/ˈbæləns ʃiːt əˈnæləsɪs/', 'noun', '{"zh-TW":["資產負債表分析"],"en":["the examination of a company''s balance sheet to assess financial health"]}', NULL, 'conduct balance sheet analysis / balance sheet analysis results', '[{"en":"Balance sheet analysis revealed significant long-term debt accumulation.","zh-TW":"資產負債表分析揭示了顯著的長期債務積累。"},{"en":"Investors use balance sheet analysis to assess solvency and leverage.","zh-TW":"投資者使用資產負債表分析來評估償付能力和槓桿。"}]', NULL, NULL, 5, 545, NULL),
(546, 'balance training', '/''bæləns ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["平衡訓練"],"en":["exercises designed to improve stability, coordination, and body control"]}', NULL, 'include balance training / balance training exercise / benefit of balance training', '[{"en":"Balance training is especially important for older adults to prevent falls.","zh-TW":"平衡訓練對老年人特別重要，可以防止跌倒。"},{"en":"She added balance training to her routine after noticing instability during yoga.","zh-TW":"她在瑜伽期間注意到不穩定後，將平衡訓練加入了她的日常例程。"}]', '{"noun":"balance","adjective":"balanced"}', NULL, 5, 546, NULL),
(547, 'balanced meal', '/''bælənst miːl/', 'noun', '{"zh-TW":["均衡餐食；營養均衡的膳食"],"en":["a meal that contains appropriate proportions of all essential nutrients"]}', NULL, 'prepare a balanced meal / eat a balanced meal / what makes a balanced meal', '[{"en":"A balanced meal should include proteins, carbohydrates, fats, and vegetables.","zh-TW":"均衡餐食應包括蛋白質、碳水化合物、脂肪和蔬菜。"},{"en":"She prepared a balanced meal for the whole family in under thirty minutes.","zh-TW":"她在三十分鐘內為全家準備了一頓均衡的餐食。"}]', NULL, NULL, 5, 547, NULL),
(548, 'balcony', '/ˈbælkəni/', 'noun', '{"zh-TW":["陽台"],"en":["a platform projecting from the wall of a building"]}', NULL, 'balcony room / sea-view balcony', '[{"en":"The suite features a private balcony overlooking the sea.","zh-TW":"套房設有可俯瞰大海的私人陽台。"},{"en":"We enjoyed morning coffee on the balcony.","zh-TW":"我們在陽台享用早晨咖啡。"}]', NULL, NULL, 3, 548, NULL),
(549, 'ball', '/bɔːl/', 'noun', '{"zh-TW":["球；舞會"],"en":["a round object used in games"]}', NULL, 'ball game / have a ball', '[{"en":"Throw the ball to me.","zh-TW":"把球丟給我。"},{"en":"They had a ball at the party.","zh-TW":"他們在派對上玩得很開心。"}]', NULL, NULL, 1, 549, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(550, 'ballet', '/bæˈleɪ/', 'noun', '{"zh-TW":["芭蕾舞"],"en":["a form of artistic dancing"]}', NULL, 'ballet dancer / ballet class', '[{"en":"She has studied ballet since age five.","zh-TW":"她從五歲開始學芭蕾。"},{"en":"We saw a beautiful ballet performance.","zh-TW":"我們看了一場美麗的芭蕾表演。"}]', NULL, NULL, 2, 550, NULL),
(551, 'ballot', '/ˈbælət/', 'noun', '{"zh-TW":["選票；投票"],"en":["a piece of paper used to vote"]}', NULL, 'secret ballot / ballot box', '[{"en":"Voters cast their ballots.","zh-TW":"選民投下了他們的選票。"},{"en":"The election was decided by ballot.","zh-TW":"選舉以投票方式決定。"}]', NULL, NULL, 2, 551, NULL),
(552, 'ban', '/bæn/', 'verb', '{"zh-TW":["禁止；禁令"],"en":["to officially prohibit something"]}', '{"root":{"text":"ban","meaning":"proclaim/forbid (宣告/禁止)"},"logic":"宣告禁止，即「禁止」。"}', 'ban on / impose a ban', '[{"en":"The city imposed a ban on single-use plastics.","zh-TW":"該市對一次性塑膠實施禁令。"},{"en":"Smoking is banned in all public buildings.","zh-TW":"所有公共建築內禁止吸菸。"}]', NULL, NULL, 1, 552, NULL),
(553, 'band', '/bænd/', 'noun', '{"zh-TW":["樂隊；帶子"],"en":["a group of musicians"]}', NULL, 'rock band / rubber band', '[{"en":"He plays guitar in a band.","zh-TW":"他在樂隊裡彈吉他。"},{"en":"The band performed live on stage.","zh-TW":"樂隊在舞台上現場演出。"}]', NULL, NULL, 1, 553, NULL),
(554, 'bandwidth', '/ˈbændwɪdθ/', 'noun', '{"zh-TW":["頻寬"],"en":["the amount of data that can be transmitted"]}', NULL, 'high bandwidth / bandwidth limit', '[{"en":"We need more bandwidth for video calls.","zh-TW":"我們需要更多頻寬進行視訊通話。"},{"en":"The server has limited bandwidth.","zh-TW":"伺服器頻寬有限。"}]', NULL, NULL, 3, 554, 752),
(555, 'bandwidth throttling', '/ˈbændwɪdθ ˈθrɒtəlɪŋ/', 'noun', '{"zh-TW":["頻寬限制"],"en":["intentional slowing of internet speed by a service provider"]}', NULL, 'apply bandwidth throttling / bandwidth throttling policy / avoid bandwidth throttling', '[{"en":"ISPs use bandwidth throttling to manage network congestion.","zh-TW":"網路服務提供商使用頻寬限制來管理網路擁塞。"},{"en":"The streaming service experienced bandwidth throttling during peak hours.","zh-TW":"串流服務在高峰時段遭遇頻寬限制。"}]', '{"verb":"throttle","noun":"throttle"}', NULL, 5, 555, NULL),
(556, 'bank', '/bæŋk/', 'noun', '{"zh-TW":["【主要意義-名詞】銀行；河岸","【次要意義-動詞】依靠；指望（bank on）","【次要意義-動詞】（飛機/車）傾斜轉彎","【次要意義-名詞】一排；一組（電腦/設備）"],"en":["[primary - noun] a financial institution; the land beside a river","[secondary - verb] to rely or depend on someone or something","[secondary - verb] to tilt to one side when turning","[secondary - noun] a row or series of similar objects"]}', NULL, 'bank on / bank holiday / bank of screens / river bank', '[{"en":"We cannot bank on government subsidies to cover the shortfall.","zh-TW":"我們不能指望政府補貼來彌補缺口。"},{"en":"The control room features a bank of monitoring screens.","zh-TW":"控制室配備了一排監控螢幕。"},{"en":"The branch manager banked on strong customer loyalty to boost sales.","zh-TW":"分行經理指望強烈的客戶忠誠度來提升銷售額。"}]', '{"noun":"banking, banker"}', 'bank on = 「依靠/指望」是 TOEIC 商業文章常見片語，a bank of（一排……）描述設備群組，這些次要意義完全不同於「銀行」，是常見陷阱。', 1, 556, NULL),
(557, 'bank guarantee', '/bæŋk ˌɡærənˈtiː/', 'noun', '{"zh-TW":["銀行擔保"],"en":["a commitment by a bank to cover a borrower''s obligations if they default"]}', NULL, 'issue a bank guarantee / bank guarantee amount', '[{"en":"A bank guarantee was required before the construction contract was awarded.","zh-TW":"在授予建設合約前需要銀行擔保。"},{"en":"The bank guarantee protected the developer against contractor default.","zh-TW":"銀行擔保保護了開發商免受承包商違約的影響。"}]', NULL, NULL, 5, 557, NULL),
(558, 'bank reconciliation', '/bæŋk ˌrekənsɪliˈeɪʃən/', 'noun', '{"zh-TW":["銀行對帳；銀行核帳"],"en":["comparing internal accounting records with bank statements to find discrepancies"]}', NULL, 'perform bank reconciliation / monthly bank reconciliation', '[{"en":"Bank reconciliation is performed every month to verify accuracy.","zh-TW":"每月進行銀行對帳以核實準確性。"},{"en":"The bank reconciliation identified a double payment of 5000.","zh-TW":"銀行對帳識別了一筆5000元的雙重付款。"}]', NULL, NULL, 5, 558, NULL),
(559, 'bank statement', '/bæŋk ˈsteɪtmənt/', 'noun', '{"zh-TW":["銀行對帳單"],"en":["a document from a bank showing all transactions in an account"]}', NULL, 'review the bank statement / reconcile the bank statement', '[{"en":"The accountant reviewed the bank statement to find the discrepancy.","zh-TW":"會計師審查了銀行對帳單以找出差異。"},{"en":"Monthly bank statements are essential for accurate bookkeeping.","zh-TW":"每月銀行對帳單對準確記帳至關重要。"}]', NULL, NULL, 5, 559, NULL),
(560, 'bank transfer', '/bæŋk ˈtrænsfɜːr/', 'noun', '{"zh-TW":["銀行轉帳"],"en":["the movement of money between bank accounts"]}', NULL, 'initiate a bank transfer / bank transfer fee', '[{"en":"She initiated a bank transfer to pay the vendor.","zh-TW":"她發起了一筆銀行轉帳來支付供應商款項。"},{"en":"International bank transfers may take two to five business days.","zh-TW":"國際銀行轉帳可能需要兩到五個工作日。"}]', NULL, NULL, 5, 560, NULL),
(561, 'bankrupt', '/ˈbæŋkrʌpt/', 'adjective', '{"zh-TW":["破產的"],"en":["unable to pay debts"]}', NULL, 'go bankrupt / declare bankrupt', '[{"en":"The company went bankrupt.","zh-TW":"公司破產了。"},{"en":"He was declared bankrupt by the court.","zh-TW":"他被法院宣告破產。"}]', '{"noun":"bankruptcy"}', NULL, 3, 561, NULL),
(562, 'bankruptcy', '/ˈbæŋkrʌptsi/', 'noun', '{"zh-TW":["破產"],"en":["a legal process for individuals or companies unable to repay debts"]}', NULL, 'declare bankruptcy / file for bankruptcy / bankruptcy protection', '[{"en":"The retail chain declared bankruptcy after the pandemic.","zh-TW":"這家零售連鎖店在疫情後宣布破產。"},{"en":"Bankruptcy protection gave the company time to restructure.","zh-TW":"破產保護給了公司重組的時間。"}]', '{"adjective":"bankrupt","verb":"bankrupt"}', NULL, 4, 562, NULL),
(563, 'bankruptcy protection', '/ˈbæŋkrʌptsi prəˈtekʃən/', 'noun', '{"zh-TW":["破產保護"],"en":["legal protection granted to an insolvent debtor preventing creditors from collecting"]}', NULL, 'file for bankruptcy protection / granted bankruptcy protection', '[{"en":"The retailer filed for bankruptcy protection to restructure its debts.","zh-TW":"零售商申請破產保護以重組其債務。"},{"en":"Under bankruptcy protection, operations can continue while debts are reorganized.","zh-TW":"在破產保護下，可以在重組債務的同時繼續運營。"}]', '{"synonym":"Chapter 11 protection"}', NULL, 5, 563, NULL),
(564, 'banquet', '/ˈbæŋkwɪt/', 'noun', '{"zh-TW":["宴會；盛宴"],"en":["an elaborate meal for many people"]}', NULL, 'banquet hall / corporate banquet', '[{"en":"The hotel''s banquet hall can accommodate 500 guests.","zh-TW":"飯店的宴會廳可容納500位賓客。"},{"en":"They hosted a banquet to celebrate the company''s anniversary.","zh-TW":"他們舉辦了宴會慶祝公司周年紀念。"}]', '{"verb":"banquet"}', NULL, 3, 564, NULL),
(565, 'banquet hall', '/ˈbæŋkwɪt hɔːl/', 'noun', '{"zh-TW":["宴會廳"],"en":["a large hall used for formal dinners or events"]}', NULL, 'book a banquet hall / banquet hall capacity', '[{"en":"The banquet hall can accommodate up to 300 guests.","zh-TW":"宴會廳最多可容納300位賓客。"},{"en":"The annual gala will be held in the hotel''s banquet hall.","zh-TW":"年度晚會將在飯店的宴會廳舉行。"}]', NULL, NULL, 4, 565, NULL),
(566, 'bar', '/bɑːr/', 'noun', '{"zh-TW":["酒吧；條；障礙"],"en":["a place serving drinks; a long narrow piece"]}', NULL, 'behind bars / bar chart', '[{"en":"Let''s meet at the bar.","zh-TW":"我們在酒吧見面吧。"},{"en":"He was put behind bars.","zh-TW":"他被關進了監獄。"}]', '{"verb":"bar","noun2":"bartender"}', NULL, 1, 566, NULL),
(567, 'bar chart', '/bɑːr tʃɑːrt/', 'noun', '{"zh-TW":["長條圖；柱狀圖"],"en":["a chart using bars to show comparisons"]}', NULL, 'create a bar chart / bar chart analysis', '[{"en":"The bar chart clearly shows the revenue growth over five years.","zh-TW":"長條圖清楚地顯示了五年來的收入增長。"},{"en":"Use a bar chart to compare sales across regions.","zh-TW":"使用長條圖比較各地區的銷售情況。"}]', NULL, NULL, 3, 567, NULL),
(568, 'barely', '/ˈbeərli/', 'adverb', '{"zh-TW":["勉強；幾乎不"],"en":["only just; almost not"]}', '{"root":{"text":"bare","meaning":"bare/merely (僅僅)"},"suffix":{"text":"-ly","meaning":"in manner of (以…方式)"},"logic":"僅僅的方式，即「勉強」。"}', 'barely visible / barely enough / can barely', '[{"en":"She barely passed the exam.","zh-TW":"她勉強通過了考試。"},{"en":"I can barely hear you.","zh-TW":"我幾乎聽不到你說話。"}]', NULL, NULL, 2, 568, NULL),
(569, 'bargain', '/ˈbɑːrɡɪn/', 'noun', '{"zh-TW":["便宜貨；協議","討價還價","便宜貨；交易"],"en":["something bought cheaply","an agreement between parties","to negotiate terms of a deal"]}', '{"root":{"text":"bargain","meaning":"trade/negotiate (交易)"},"logic":"通過交易談判達成的，即「便宜貨、協議」。"}', 'bargain price / collective bargaining; a real bargain / bargain hunter', '[{"en":"The property was a real bargain at that price.","zh-TW":"以那個價格買下這處房產真是便宜。"},{"en":"The union engaged in collective bargaining.","zh-TW":"工會進行了集體談判。"},{"en":"This coat was a real bargain at half price.","zh-TW":"這件外套半價，真是便宜貨。"},{"en":"They bargained with the vendor for a lower price.","zh-TW":"他們跟攤販討價還價。"}]', '{"verb":"bargain"}', NULL, 3, 569, NULL),
(570, 'bargaining power', '/ˈbɑːrɡənɪŋ ˈpaʊər/', 'noun', '{"zh-TW":["議價能力"],"en":["the relative power of parties in a negotiation to influence the outcome"]}', NULL, 'increase bargaining power / strong bargaining power', '[{"en":"Large retailers have significant bargaining power over their suppliers.","zh-TW":"大型零售商對其供應商有顯著的議價能力。"},{"en":"Consolidating purchases improves a buyer''s bargaining power.","zh-TW":"整合採購提高了買家的議價能力。"}]', '{"verb":"bargain"}', NULL, 5, 570, NULL),
(571, 'barrier', '/ˈbæriər/', 'noun', '{"zh-TW":["障礙；壁壘","障礙；屏障"],"en":["a fence or obstacle that prevents movement or access","something that prevents movement or access"]}', '{"root":{"text":"bar","meaning":"bar/block (阻擋)"},"suffix":{"text":"-ier","meaning":"thing that (…的東西)"},"logic":"阻擋的東西，即「障礙」。"}', 'trade barrier / language barrier / barrier to entry; language barrier / trade barrier / break down barriers', '[{"en":"Language barriers can hinder international business.","zh-TW":"語言障礙可能妨礙國際商務。"},{"en":"The company faced significant barriers to entry.","zh-TW":"公司面臨重大的進入門檻。"},{"en":"Language can be a barrier to communication.","zh-TW":"語言可能是溝通的障礙。"},{"en":"They are trying to break down trade barriers.","zh-TW":"他們正試圖消除貿易障礙。"}]', NULL, NULL, 3, 571, 513),
(572, 'barrier to entry', '/ˈbæriər tə ˈentri/', 'noun', '{"zh-TW":["進入壁壘"],"en":["an obstacle that makes it difficult for new competitors to enter a market"]}', NULL, 'high barrier to entry / reduce barriers to entry / overcome barriers to entry', '[{"en":"Patents create a high barrier to entry in pharmaceutical markets.","zh-TW":"專利在藥品市場創造了高進入壁壘。"},{"en":"Strong brand loyalty is a significant barrier to entry for new competitors.","zh-TW":"強大的品牌忠誠度對新競爭對手是重大的進入壁壘。"}]', '{"plural":"barriers to entry"}', NULL, 5, 572, NULL),
(573, 'base', '/beɪs/', 'noun', '{"zh-TW":["基礎；基地","以…為基礎"],"en":["the lowest part or foundation","to use as a starting point"]}', '{"root":{"text":"bas","meaning":"bottom (底部)"},"logic":"底部基礎，即「基礎」。"}', 'customer base / base on / base salary', '[{"en":"The company has a large customer base in Asia.","zh-TW":"公司在亞洲擁有龐大的客戶群。"},{"en":"The decision was based on thorough research.","zh-TW":"該決定基於深入研究。"}]', '{"adjective":"basic","adverb":"basically"}', NULL, 1, 573, NULL),
(574, 'base and superstructure', '/beɪs ænd ˈsuːpəˌstrʌktʃər/', 'phrase', '{"zh-TW":["基礎與上層建築"],"en":["the Marxist framework where economic base shapes cultural and political superstructure"]}', NULL, 'Marxist base and superstructure / analyze base and superstructure / base and superstructure theory', '[{"en":"Marxists argue that the economic base determines the cultural and political superstructure.","zh-TW":"馬克思主義者認為經濟基礎決定文化和政治上層建築。"},{"en":"Critics of base and superstructure theory note the relative autonomy of cultural institutions.","zh-TW":"批評基礎與上層建築理論的人指出文化機構的相對自主性。"}]', NULL, NULL, 5, 574, NULL),
(575, 'base salary', '/beɪs ˈsæləri/', 'noun', '{"zh-TW":["基本薪資"],"en":["the fixed amount paid to an employee before bonuses or benefits"]}', NULL, 'negotiate base salary / base salary range', '[{"en":"She negotiated a higher base salary before accepting the offer.","zh-TW":"她在接受邀約前談判了更高的基本薪資。"},{"en":"Base salary is supplemented by performance-linked bonuses.","zh-TW":"基本薪資由績效掛鉤的獎金補充。"}]', NULL, NULL, 4, 575, NULL),
(576, 'baseline', '/ˈbeɪslaɪn/', 'noun', '{"zh-TW":["基準線；基線"],"en":["a starting point used for comparison or measurement of progress"]}', NULL, 'set a baseline / baseline measurement / performance baseline', '[{"en":"The baseline for the project was established at the kickoff meeting.","zh-TW":"項目的基準線在啟動會議上確立。"},{"en":"Performance is measured against the established baseline.","zh-TW":"績效根據既定基準線進行衡量。"}]', '{"adjective":"baseline"}', NULL, 3, 576, 827),
(577, 'basic', '/ˈbeɪsɪk/', 'adjective', '{"zh-TW":["基本的；基礎的"],"en":["forming the most important part"]}', NULL, 'basic knowledge / basic needs', '[{"en":"You need basic computer skills.","zh-TW":"你需要基本的電腦技能。"},{"en":"Food and water are basic needs.","zh-TW":"食物和水是基本需求。"}]', '{"noun":"basics","adverb":"basically"}', NULL, 2, 577, NULL),
(578, 'basis', '/ˈbeɪsɪs/', 'noun', '{"zh-TW":["基礎；依據","基礎；根據"],"en":["the underlying support or foundation for something","the underlying support or foundation"]}', '{"root":{"text":"bas","meaning":"bottom (底部)"},"suffix":{"text":"-is","meaning":"noun ending (名詞字尾)"},"logic":"底部的根基，即「基礎」。"}', 'on a regular basis / on the basis of; on the basis of / daily basis / regular basis', '[{"en":"Reports are submitted on a weekly basis.","zh-TW":"報告每週提交一次。"},{"en":"Candidates are selected on the basis of experience.","zh-TW":"候選人根據經驗進行篩選。"},{"en":"Employees are evaluated on a regular basis.","zh-TW":"員工定期接受評估。"},{"en":"On what basis did you make that decision?","zh-TW":"你根據什麼做出那個決定？"}]', '{"adjective":"basic","adverb":"basically"}', NULL, 2, 578, 514),
(579, 'basis point', '/ˈbeɪsɪs pɔɪnt/', 'noun', '{"zh-TW":["基點"],"en":["one hundredth of a percentage point, used in finance"]}', NULL, 'move by basis points / basis point spread / one basis point', '[{"en":"A ten basis point increase in interest rates would raise mortgage costs.","zh-TW":"利率提高十個基點將增加抵押貸款成本。"},{"en":"The yield spread widened by fifty basis points after the announcement.","zh-TW":"公告後殖利率利差擴大了五十個基點。"}]', NULL, NULL, 4, 579, NULL),
(580, 'basis points', '/ˈbeɪsɪs pɔɪnts/', 'noun', '{"zh-TW":["基點"],"en":["a unit of measure for interest rates equal to one hundredth of one percent"]}', NULL, 'cut by fifty basis points / raise by twenty-five basis points / measure in basis points', '[{"en":"The central bank raised interest rates by fifty basis points to combat inflation.","zh-TW":"中央銀行將利率提高了五十個基點以對抗通膨。"},{"en":"A spread of two hundred basis points indicates significant credit risk.","zh-TW":"兩百個基點的利差表明存在重大信用風險。"}]', NULL, NULL, 4, 580, NULL),
(581, 'batch', '/bætʃ/', 'noun', '{"zh-TW":["批次；一批"],"en":["a quantity of goods produced in one operation"]}', NULL, 'batch processing / production batch', '[{"en":"The factory produced a batch of 500 units today.","zh-TW":"工廠今天生產了500個單位的一批產品。"},{"en":"Batch processing reduces production costs for large orders.","zh-TW":"批次處理降低了大訂單的生產成本。"}]', '{"verb":"batch","adjective":"batched"}', NULL, 2, 581, NULL),
(582, 'batch processing', '/''bætʃ ˌprɒsesɪŋ/', 'noun', '{"zh-TW":["批次處理；批量加工"],"en":["the processing of a group of items or data at once rather than one at a time"]}', NULL, 'use batch processing / batch processing system / batch processing efficiency', '[{"en":"Batch processing allows the factory to handle large volumes of orders simultaneously.","zh-TW":"批次處理允許工廠同時處理大量訂單。"},{"en":"The IT team runs batch processing jobs at night to minimize disruption during work hours.","zh-TW":"IT團隊在夜間運行批次處理作業，以盡量減少工作時間的中斷。"}]', '{"adjective":"batch","verb":"process"}', NULL, 5, 582, NULL),
(583, 'batch production', '/bætʃ prəˈdʌkʃən/', 'noun', '{"zh-TW":["批量生產"],"en":["manufacturing goods in groups or batches rather than continuously"]}', NULL, 'use batch production / batch production method', '[{"en":"The bakery uses batch production to make different bread types daily.","zh-TW":"麵包店使用批量生產每天製作不同種類的麵包。"},{"en":"Batch production offers flexibility but may result in higher per-unit costs.","zh-TW":"批量生產提供靈活性但可能導致較高的單位成本。"}]', NULL, NULL, 5, 583, NULL),
(584, 'bath', '/bæθ/', 'noun', '{"zh-TW":["洗澡；浴缸","沐浴；浴缸"],"en":["an act of washing the body","washing the body; a container for water"]}', NULL, 'take a bath / bath towel; take a bath / bathroom', '[{"en":"I take a bath every evening.","zh-TW":"我每天晚上洗澡。"},{"en":"The bath is full of hot water.","zh-TW":"浴缸裡滿是熱水。"},{"en":"The bathroom is on the second floor.","zh-TW":"浴室在二樓。"}]', '{"verb":"bathe","noun2":"bathroom"}', NULL, 1, 584, NULL),
(585, 'batting average', '/''bætɪŋ ˌævərɪdʒ/', 'noun', '{"zh-TW":["擊球率；打擊率"],"en":["in baseball, a statistic measuring a batter''s performance based on hits divided by at-bats"]}', NULL, 'maintain a batting average / batting average statistic / high batting average', '[{"en":"He maintained a batting average of over 0.300 throughout the season.","zh-TW":"他在整個賽季保持了超過0.300的擊球率。"},{"en":"A batting average of 0.350 is considered excellent at the professional level.","zh-TW":"在職業水平上，0.350的擊球率被認為是非常優秀的。"}]', NULL, NULL, 5, 585, NULL),
(586, 'batting cage', '/''bætɪŋ keɪdʒ/', 'noun', '{"zh-TW":["打擊練習場；打籠"],"en":["an enclosed area where baseball or softball players practice their batting"]}', NULL, 'practice in the batting cage / use a batting cage / batting cage session', '[{"en":"He spent an hour in the batting cage every morning to improve his swing.","zh-TW":"他每天早上在打擊練習場練習一個小時，以改善他的揮棒。"},{"en":"The training facility included a batting cage, weights room, and indoor track.","zh-TW":"訓練設施包括打擊練習場、重量訓練室和室內跑道。"}]', NULL, NULL, 4, 586, NULL),
(587, 'battle', '/ˈbætəl/', 'noun', '{"zh-TW":["戰鬥；鬥爭"],"en":["a fight between armed forces"]}', NULL, 'battle against / battle field', '[{"en":"The battle lasted three days.","zh-TW":"戰鬥持續了三天。"},{"en":"She won her battle against cancer.","zh-TW":"她贏得了與癌症的鬥爭。"}]', '{"verb":"battle"}', NULL, 2, 587, NULL),
(588, 'beach', '/biːtʃ/', 'noun', '{"zh-TW":["海灘"],"en":["an area of sand beside the sea"]}', NULL, 'on the beach / beach volleyball', '[{"en":"We spent the day at the beach.","zh-TW":"我們在海灘度過了一天。"},{"en":"The beach was crowded in summer.","zh-TW":"夏天海灘很擁擠。"}]', NULL, NULL, 2, 588, NULL),
(589, 'bear', '/beər/', 'verb', '{"zh-TW":["【主要意義-名詞】熊","【次要意義-動詞】承受；忍耐","【次要意義-動詞】產出；帶來（結果）","【次要意義-動詞】朝向某方向移動"],"en":["[primary - noun] a large wild animal","[secondary - verb] to carry a weight or responsibility; to endure","[secondary - verb] to produce something such as fruit or results","[secondary - verb] to move or turn in a particular direction"]}', '{"root":{"text":"bear","meaning":"carry (攜帶)"},"logic":"攜帶重量，即「承擔」。"}', 'bear in mind / bear fruit / bear responsibility / bear left / bear witness', '[{"en":"Please bear in mind that the deadline cannot be extended.","zh-TW":"請記住截止日期無法延後。"},{"en":"The new strategy is beginning to bear fruit after six months.","zh-TW":"新策略在六個月後開始顯現成效。"},{"en":"The company must bear full responsibility for the product defect.","zh-TW":"公司必須對產品缺陷承擔全部責任。"}]', '{"noun":"bearing","adjective":"bearable"}', 'bear 作動詞有多個高頻用法：bear in mind（記住），bear fruit（結出成果），bear responsibility（承擔責任），這些均為 TOEIC 商業文章必考表達，與名詞「熊」完全無關。', 1, 589, NULL),
(590, 'bear market', '/beər ˈmɑːrkɪt/', 'noun', '{"zh-TW":["空頭市場；熊市"],"en":["a prolonged period of falling stock prices"]}', NULL, 'enter a bear market / bear market conditions / survive a bear market', '[{"en":"The bear market wiped out years of gains.","zh-TW":"熊市抹去了多年的收益。"},{"en":"Defensive stocks performed better during the bear market.","zh-TW":"防禦型股票在熊市中表現較好。"}]', '{"antonym":"bull market"}', NULL, 4, 590, NULL),
(591, 'bear out', '/beər aʊt/', 'phrasal verb', '{"zh-TW":["【主要意義】證實；支持；佐證"],"en":["[primary] to confirm or support the truth of something","[secondary] to justify or vindicate a claim or statement"]}', NULL, 'bear out a claim / bear out a theory / bear someone out', '[{"en":"The financial data bears out the auditor''s concerns about overspending.","zh-TW":"財務數據證實了審計人員對超支的擔憂。"},{"en":"His performance in the interview bore out our initial impression of him.","zh-TW":"他在面試中的表現證實了我們對他的最初印象。"},{"en":"The results bear out the hypothesis proposed last year.","zh-TW":"這些結果支持了去年提出的假設。"}]', '{"verb":"bear, bears, bore, borne"}', 'bear out 意為「證實/佐證」，常出現在 TOEIC 閱讀的報告分析或研究結論語境中，與 bear（熊）毫無關聯。', 3, 591, NULL),
(592, 'beat', '/biːt/', 'verb', '{"zh-TW":["打敗；跳動"],"en":["to defeat someone; to make a rhythm"]}', NULL, 'beat the record / heartbeat', '[{"en":"Our team beat theirs 3-1.","zh-TW":"我們隊以3比1打敗了他們。"},{"en":"My heart was beating fast.","zh-TW":"我的心跳得很快。"}]', '{"noun":"beat"}', NULL, 1, 592, NULL),
(593, 'beautiful', '/ˈbjuːtɪfəl/', 'adjective', '{"zh-TW":["美麗的","美麗的；漂亮的","美麗的；美好的"],"en":["very pleasing to look at or experience","very attractive or pleasing","very attractive; giving great pleasure"]}', NULL, 'beautiful weather / beautiful design; beautiful scenery / beautiful day; beautiful scenery/weather/music', '[{"en":"The office has a beautiful view.","zh-TW":"辦公室有很美的景觀。"},{"en":"Thank you for this beautiful gift.","zh-TW":"謝謝你這份美麗的禮物。"},{"en":"What a beautiful sunset!","zh-TW":"多美的日落啊！"},{"en":"She has a beautiful voice.","zh-TW":"她有一副美麗的嗓音。"},{"en":"What a beautiful day!","zh-TW":"多麼美好的一天！"},{"en":"She wore a beautiful dress.","zh-TW":"她穿了一件漂亮的洋裝。"}]', '{"adjective":"beautiful","noun":"beauty","adverb":"beautifully","verb":"beautify"}', NULL, 3, 593, NULL),
(594, 'because', '/bɪˈkɒz/', 'conjunction', '{"zh-TW":["因為"],"en":["for the reason that"]}', NULL, 'because of / just because', '[{"en":"I stayed home because I was sick.","zh-TW":"我因為生病待在家裡。"},{"en":"The game was canceled because of rain.","zh-TW":"比賽因為下雨被取消了。"}]', NULL, NULL, 3, 594, NULL),
(595, 'become', '/bɪˈkʌm/', 'verb', '{"zh-TW":["變成；成為","成為；變得"],"en":["to begin to be; to grow to be","to begin to be something","to begin to be; to start being"]}', NULL, 'become aware / become available; become aware / become friends; become + adj/noun', '[{"en":"He became the new manager.","zh-TW":"他成為了新經理。"},{"en":"The product has become very popular.","zh-TW":"這個產品變得非常受歡迎。"},{"en":"She became a doctor.","zh-TW":"她成為了一名醫生。"},{"en":"It''s becoming colder.","zh-TW":"天氣越來越冷了。"},{"en":"The situation became worse.","zh-TW":"情況變得更糟了。"}]', '{"verb":"become"}', NULL, 2, 595, NULL),
(596, 'bed', '/bɛd/', 'noun', '{"zh-TW":["床","床；花壇"],"en":["a piece of furniture for sleeping","a piece of furniture for sleeping on"]}', NULL, 'go to bed / in bed; go to bed / make the bed / bed and breakfast', '[{"en":"Time to go to bed.","zh-TW":"該上床睡覺了。"},{"en":"He stayed in bed all day.","zh-TW":"他整天待在床上。"},{"en":"I usually go to bed at 11 PM.","zh-TW":"我通常晚上11點上床睡覺。"},{"en":"Please make your bed.","zh-TW":"請整理你的床。"}]', '{"noun2":"bedroom","noun3":"bedding","noun":"bedding, bedroom"}', NULL, 1, 596, NULL),
(597, 'bed and breakfast', '/bɛd ænd ˈbrɛkfəst/', 'noun', '{"zh-TW":["民宿；住宿含早餐"],"en":["accommodation with an overnight stay and breakfast included"]}', NULL, 'stay at a bed and breakfast / charming bed and breakfast', '[{"en":"They chose a charming bed and breakfast in the countryside.","zh-TW":"他們選擇了鄉村的一家迷人的民宿。"},{"en":"A bed and breakfast is usually smaller and more personal than a hotel.","zh-TW":"民宿通常比飯店規模更小且更具個人特色。"}]', '{"abbreviation":"B&B"}', NULL, 5, 597, NULL),
(598, 'before', '/bɪˈfɔːr/', 'preposition, conjunction, adverb', '{"zh-TW":["在...之前"],"en":["earlier than; at an earlier time"]}', NULL, 'before + V-ing / the day before', '[{"en":"Finish your work before the deadline.","zh-TW":"在截止日期前完成你的工作。"},{"en":"I''ve never been here before.","zh-TW":"我以前從未來過這裡。"}]', NULL, NULL, 2, 598, NULL),
(599, 'begin', '/bɪˈɡɪn/', 'verb', '{"zh-TW":["開始","開始；著手"],"en":["to start","to start doing something","to start; to do the first part of something"]}', NULL, 'begin with / to begin with; begin to do / begin doing / begin with', '[{"en":"The workshop begins at 10 a.m.","zh-TW":"研習會在上午10點開始。"},{"en":"Let us begin with the agenda.","zh-TW":"讓我們從議程開始。"},{"en":"The meeting begins at 9.","zh-TW":"會議9點開始。"},{"en":"Let''s begin with introductions.","zh-TW":"讓我們從自我介紹開始。"},{"en":"The meeting begins at 9 AM.","zh-TW":"會議上午九點開始。"},{"en":"Let''s begin with the first item on the agenda.","zh-TW":"讓我們從議程的第一項開始。"}]', '{"verb":"begin","noun":"beginning","noun2":"beginner"}', NULL, 2, 599, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(600, 'behalf', '/bɪˈhɑːf/', 'noun', '{"zh-TW":["代表；為了…的利益","代表"],"en":["in the interest of; as a representative of"]}', '{"prefix":{"text":"be-","meaning":"by (在旁)"},"root":{"text":"half","meaning":"side (邊)"},"logic":"在某人的邊（一方），即「代表」。"}', 'on behalf of / on sb''s behalf; on behalf of / act on someone''s behalf', '[{"en":"I''m writing on behalf of the marketing department.","zh-TW":"我代表行銷部門寫信。"},{"en":"The lawyer acted on behalf of the client.","zh-TW":"律師代表客戶行事。"},{"en":"I am writing on behalf of my client.","zh-TW":"我代表我的客戶寫信。"},{"en":"She accepted the award on behalf of the team.","zh-TW":"她代表團隊接受了獎項。"}]', NULL, NULL, 2, 600, NULL),
(601, 'behave', '/bɪˈheɪv/', 'verb', '{"zh-TW":["行為；表現"],"en":["to act in a particular way","to conduct oneself properly"]}', '{"prefix":{"text":"be-","meaning":"thoroughly (徹底)"},"root":{"text":"have","meaning":"hold oneself (持有自己)"},"logic":"徹底持有自己的方式，即「行為」。"}', 'behave professionally / consumer behavior', '[{"en":"Employees are expected to behave professionally.","zh-TW":"員工應表現專業。"},{"en":"Market conditions cause consumers to behave differently.","zh-TW":"市場條件使消費者行為有所不同。"}]', '{"noun":"behavior"}', NULL, 2, 601, NULL),
(602, 'behavioral economics', '/bɪˌheɪvjərəl ˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["行為經濟學"],"en":["a field that combines economic and psychological insights to explain decision-making"]}', NULL, 'principles of behavioral economics / apply behavioral economics / behavioral economics research', '[{"en":"Behavioral economics shows that people often act irrationally in financial decisions.","zh-TW":"行為經濟學表明，人們在金融決策中常常表現出非理性行為。"},{"en":"Nudge theory, a branch of behavioral economics, improves health outcomes.","zh-TW":"輕推理論是行為經濟學的一個分支，可改善健康結果。"}]', NULL, NULL, 5, 602, NULL),
(603, 'behavioral finance', '/bɪˈheɪvjərəl ˈfaɪnæns/', 'noun', '{"zh-TW":["行為金融學"],"en":["the study of psychological influences on investors and financial markets"]}', NULL, 'apply behavioral finance / principles of behavioral finance / behavioral finance research', '[{"en":"Behavioral finance explains why investors make irrational decisions driven by emotion.","zh-TW":"行為金融學解釋了為什麼投資者會因情緒驅動而做出非理性決策。"},{"en":"Loss aversion, a concept from behavioral finance, causes investors to hold losing positions too long.","zh-TW":"損失厭惡是行為金融學中的一個概念，導致投資者持有虧損頭寸太長時間。"}]', NULL, NULL, 5, 603, NULL),
(604, 'behind', '/bɪˈhaɪnd/', 'preposition', '{"zh-TW":["在…後面；落後","在…後面","在...後面；落後"],"en":["at the back of","less advanced than","at the back of; not making enough progress"]}', NULL, 'fall behind / behind schedule; behind schedule / fall behind; behind schedule / fall behind / leave behind', '[{"en":"The project is behind schedule.","zh-TW":"專案進度落後了。"},{"en":"Who is behind this decision?","zh-TW":"誰在這個決定背後？"},{"en":"The cat hid behind the sofa.","zh-TW":"貓躲在沙發後面。"},{"en":"We''re behind schedule.","zh-TW":"我們落後於進度了。"},{"en":"The garden is behind the house.","zh-TW":"花園在房子後面。"},{"en":"We''re behind schedule on this project.","zh-TW":"我們這個專案進度落後。"}]', '{"preposition":"behind","adverb":"behind"}', NULL, 2, 604, NULL),
(605, 'believe', '/bɪˈliːv/', 'verb', '{"zh-TW":["相信；認為"],"en":["to think something is true","to have confidence in","to accept as true","to think something is true; to have faith"]}', NULL, 'believe in / hard to believe; believe in / believe it or not', '[{"en":"I believe this strategy will work.","zh-TW":"我相信這個策略會成功。"},{"en":"We believe in teamwork.","zh-TW":"我們相信團隊合作。"},{"en":"I believe you''re right.","zh-TW":"我相信你是對的。"},{"en":"Do you believe in ghosts?","zh-TW":"你相信有鬼嗎？"},{"en":"I believe this plan will work.","zh-TW":"我相信這個計畫會成功。"},{"en":"She doesn''t believe in ghosts.","zh-TW":"她不相信鬼。"}]', '{"verb":"believe","noun":"belief","adjective":"believable","adjective2":"unbelievable"}', NULL, 3, 605, NULL),
(606, 'bellhop', '/''belhɒp/', 'noun', '{"zh-TW":["行李服務員；飯店服務生"],"en":["a hotel worker who carries bags and runs errands for guests"]}', NULL, 'tip the bellhop / bellhop service / call the bellhop', '[{"en":"The bellhop helped carry our luggage to the room and explained the hotel facilities.","zh-TW":"行李服務員幫我們把行李搬到房間，並介紹了飯店設施。"},{"en":"We gave the bellhop a generous tip for his quick and courteous service.","zh-TW":"我們給了行李服務員豐厚的小費，感謝他快速而有禮貌的服務。"}]', NULL, NULL, 3, 606, NULL),
(607, 'bellwether', '/ˈbelwɛðər/', 'noun', '{"zh-TW":["風向標；領頭羊"],"en":["a leader or indicator that is a leading indicator of a broader trend"]}', NULL, 'bellwether stock / economic bellwether / bellwether industry', '[{"en":"Technology stocks often serve as a bellwether for the broader market.","zh-TW":"科技股通常作為更廣泛市場的風向標。"},{"en":"This region is considered a bellwether for national election outcomes.","zh-TW":"該地區被視為全國選舉結果的風向標。"}]', NULL, NULL, 4, 607, NULL),
(608, 'belong', '/bɪˈlɒŋ/', 'verb', '{"zh-TW":["屬於","屬於；適合在"],"en":["to be the property of","to be the property of; to be in the right place"]}', NULL, 'belong to / a sense of belonging', '[{"en":"This book belongs to me.","zh-TW":"這本書是我的。"},{"en":"She felt she didn''t belong.","zh-TW":"她覺得自己不屬於這裡。"},{"en":"These files belong in the cabinet.","zh-TW":"這些文件應該放在櫃子裡。"}]', '{"noun":"belonging"}', NULL, 2, 608, NULL),
(609, 'below', '/bɪˈloʊ/', 'preposition', '{"zh-TW":["在…下面","在...下面；低於"],"en":["at a lower level than","at a lower level than; less than"]}', NULL, 'below average / see below; below average / below zero', '[{"en":"The temperature dropped below zero.","zh-TW":"溫度降到了零度以下。"},{"en":"See the chart below.","zh-TW":"請看下面的圖表。"},{"en":"The temperature dropped below zero.","zh-TW":"氣溫降到零度以下。"},{"en":"See the chart below.","zh-TW":"請見下方圖表。"}]', NULL, NULL, 2, 609, NULL),
(610, 'below the line', '/bɪˈloʊ ðə laɪn/', 'adjective', '{"zh-TW":["線下的；促銷活動的"],"en":["relating to direct, targeted marketing such as promotions and events"]}', NULL, 'below-the-line advertising / below-the-line promotion', '[{"en":"Below-the-line campaigns use direct mail, promotions, and events.","zh-TW":"線下活動使用直郵、促銷和活動。"},{"en":"A below-the-line campaign targeted specific customer segments with coupons.","zh-TW":"線下活動通過優惠券針對特定客戶群體。"}]', '{"opposite":"above-the-line"}', NULL, 5, 610, NULL),
(611, 'benchmark', '/ˈbentʃmɑːrk/', 'noun', '{"zh-TW":["基準；標竿"],"en":["a standard or point of reference for comparison","a standard for comparison"]}', '{"root":{"text":"bench","meaning":"bench (長凳)"},"suffix":{"text":"mark","meaning":"mark (標記)"},"logic":"長凳上的標記（測量基準），即「基準」。"}', 'industry benchmark / set a benchmark / benchmark against', '[{"en":"Our service quality sets the benchmark in the industry.","zh-TW":"我們的服務品質樹立了行業基準。"},{"en":"We benchmark our performance against competitors.","zh-TW":"我們以競爭對手為基準評估績效。"},{"en":"This sets a new benchmark for quality.","zh-TW":"這為品質設立了新的標竿。"},{"en":"We measure performance against industry benchmarks.","zh-TW":"我們以產業基準來衡量績效。"}]', '{"verb":"benchmark","noun":"benchmark","noun2":"benchmarking"}', NULL, 3, 611, 278),
(612, 'benchmark against', '/ˈbentʃmɑːrk əˈɡenst/', 'verb', '{"zh-TW":["對標；與...比較基準"],"en":["to compare performance against a standard or competitor"]}', NULL, 'benchmark against industry peers / benchmark against competitors', '[{"en":"The company benchmarks against global best practices annually.","zh-TW":"公司每年與全球最佳實踐對標。"},{"en":"Management benchmarked costs against three leading competitors.","zh-TW":"管理層將成本與三家主要競爭對手進行對標。"}]', NULL, NULL, 5, 612, NULL),
(613, 'benchmark analysis', '/ˈbentʃmɑːrk əˈnæləsɪs/', 'noun', '{"zh-TW":["基準分析"],"en":["the process of comparing performance metrics against a standard or competitor"]}', NULL, 'conduct benchmark analysis / benchmark analysis results', '[{"en":"A benchmark analysis revealed the company lags peers in digital adoption.","zh-TW":"基準分析顯示公司在數位採用方面落後於同業。"},{"en":"Benchmark analysis is part of the annual strategic review process.","zh-TW":"基準分析是年度戰略審查流程的一部分。"}]', NULL, NULL, 5, 613, NULL),
(614, 'benchmark comparison', '/''bentʃˌmɑːrk kəmˌpærɪsən/', 'noun', '{"zh-TW":["基準比較；標準對照"],"en":["an evaluation that measures performance against an established standard or reference point"]}', NULL, 'conduct benchmark comparison / use benchmark comparison / benchmark comparison report', '[{"en":"The quarterly benchmark comparison showed that performance exceeded industry average.","zh-TW":"季度基準比較顯示業績超過了行業平均水平。"},{"en":"Benchmark comparisons help organizations identify areas for improvement.","zh-TW":"基準比較幫助組織識別需要改進的領域。"}]', NULL, NULL, 5, 614, NULL),
(615, 'benchmark data', '/''bentʃmɑːrk ˌdeɪtə/', 'noun', '{"zh-TW":["基準數據"],"en":["data used as a reference point against which performance or progress can be measured"]}', NULL, 'collect benchmark data / analyze benchmark data / use benchmark data', '[{"en":"The study collected benchmark data on student performance before implementing the new curriculum.","zh-TW":"研究在實施新課程之前收集了學生表現的基準數據。"},{"en":"Benchmark data allows companies to compare their efficiency with industry standards.","zh-TW":"基準數據使公司能夠將其效率與行業標準進行比較。"}]', '{"noun":"benchmark"}', NULL, 5, 615, NULL),
(616, 'benchmark index', '/ˈbentʃmɑːrk ˈɪndeks/', 'noun', '{"zh-TW":["基準指數"],"en":["a standard index used to measure and compare the performance of investments"]}', NULL, 'track the benchmark index / outperform the benchmark index', '[{"en":"The fund consistently outperformed the benchmark index over five years.","zh-TW":"該基金在五年內持續超越了基準指數。"},{"en":"Portfolio managers are measured against an appropriate benchmark index.","zh-TW":"投資組合管理人按適當的基準指數衡量績效。"}]', NULL, NULL, 5, 616, NULL),
(617, 'benchmark interest rate', '/ˈbentʃmɑːrk ˈɪntrɪst reɪt/', 'noun', '{"zh-TW":["基準利率"],"en":["the standard interest rate set by a central bank that influences other rates"]}', NULL, 'set the benchmark interest rate / below the benchmark interest rate', '[{"en":"The central bank raised the benchmark interest rate to curb inflation.","zh-TW":"中央銀行提高了基準利率以抑制通貨膨脹。"},{"en":"Lending rates are typically set above the benchmark interest rate.","zh-TW":"貸款利率通常設定在基準利率之上。"}]', NULL, NULL, 5, 617, NULL),
(618, 'benchmark performance', '/''bentʃmɑːrk pəˌfɔːrməns/', 'noun', '{"zh-TW":["基準表現；標竿績效"],"en":["a level of performance used as a standard against which others can be measured"]}', NULL, 'exceed benchmark performance / measure benchmark performance / set a benchmark performance', '[{"en":"The team''s benchmark performance exceeded expectations in every category.","zh-TW":"團隊的基準表現在每個類別中都超出了預期。"},{"en":"Regular benchmark performance reviews help teams stay on track with their goals.","zh-TW":"定期基準績效審查幫助團隊在實現目標方面保持正軌。"}]', NULL, NULL, 5, 618, NULL),
(619, 'benchmark rate', '/ˈbentʃmɑːrk reɪt/', 'noun', '{"zh-TW":["基準利率"],"en":["an interest rate used as a reference for pricing other financial products"]}', NULL, 'set a benchmark rate / floating rate tied to benchmark / benchmark rate change', '[{"en":"LIBOR was replaced by SOFR as the primary benchmark rate.","zh-TW":"LIBOR被SOFR取代成為主要基準利率。"},{"en":"The loan is priced at two hundred basis points above the benchmark rate.","zh-TW":"貸款定價為基準利率上加兩百個基點。"}]', NULL, NULL, 5, 619, NULL),
(620, 'benchmark standard', '/''bentʃmɑːrk ˌstændərd/', 'noun', '{"zh-TW":["基準標準"],"en":["an established level of quality or attainment used as a reference point for comparison"]}', NULL, 'set a benchmark standard / meet a benchmark standard / exceed the benchmark standard', '[{"en":"The factory established benchmark standards for quality control at every stage of production.","zh-TW":"工廠在生產的每個階段建立了品質控制的基準標準。"},{"en":"Meeting the industry benchmark standard is essential for gaining customer trust.","zh-TW":"達到行業基準標準對於獲得客戶信任至關重要。"}]', NULL, NULL, 5, 620, NULL),
(621, 'benchmark test', '/ˈbɛntʃmɑːrk tɛst/', 'noun', '{"zh-TW":["基準測試"],"en":["a standard test used to measure performance"]}', NULL, 'run a benchmark test / benchmark test results', '[{"en":"The IT team ran a benchmark test on the new servers.","zh-TW":"IT團隊在新伺服器上進行了基準測試。"},{"en":"Benchmark tests help compare performance across systems.","zh-TW":"基準測試有助於比較各系統的性能。"}]', NULL, NULL, 5, 621, NULL),
(622, 'benchmarking', '/ˈbentʃˌmɑːrkɪŋ/', 'noun', '{"zh-TW":["基準分析；標竿學習"],"en":["comparing performance metrics to industry best practices"]}', NULL, 'competitive benchmarking / internal benchmarking', '[{"en":"Benchmarking revealed we lagged behind competitors in speed.","zh-TW":"基準分析顯示我們在速度上落後於競爭對手。"},{"en":"We use benchmarking to identify areas for improvement.","zh-TW":"我們使用基準分析來識別改進領域。"}]', '{"verb":"benchmark","noun":"benchmark"}', NULL, 4, 622, 753),
(623, 'benchmarking exercise', '/ˈbentʃmɑːrkɪŋ ˈeksəsaɪz/', 'noun', '{"zh-TW":["標竿比較練習；基準評估"],"en":["an activity comparing processes or performance against best-in-class standards"]}', NULL, 'conduct a benchmarking exercise / benchmarking exercise results', '[{"en":"The benchmarking exercise identified areas where the company underperformed.","zh-TW":"標竿比較練習確定了公司表現不佳的領域。"},{"en":"A regular benchmarking exercise helps drive continuous improvement.","zh-TW":"定期的標竿比較練習有助於推動持續改進。"}]', NULL, NULL, 5, 623, NULL),
(624, 'benchmarking study', '/ˈbentʃmɑːrkɪŋ ˈstʌdi/', 'noun', '{"zh-TW":["標竿研究；基準比較研究"],"en":["an analysis comparing a company performance to industry peers"]}', NULL, 'conduct a benchmarking study / publish a benchmarking study', '[{"en":"The consultants conducted a benchmarking study on HR practices.","zh-TW":"顧問們對人力資源實踐進行了標竿研究。"},{"en":"The benchmarking study revealed gaps in our customer service scores.","zh-TW":"標竿研究揭示了我們客戶服務評分中的差距。"}]', NULL, NULL, 5, 624, NULL),
(625, 'bend', '/bɛnd/', 'verb', '{"zh-TW":["彎曲；屈身"],"en":["to make something curved"]}', NULL, 'bend down / bend the rules', '[{"en":"Bend your knees slightly.","zh-TW":"稍微彎曲膝蓋。"},{"en":"She bent down to pick it up.","zh-TW":"她彎腰撿起來。"}]', NULL, NULL, 1, 625, NULL),
(626, 'beneath', '/bɪˈniːθ/', 'preposition', '{"zh-TW":["在…下方"],"en":["in or to a lower position than; under"]}', '{"prefix":{"text":"be-","meaning":"by (在)"},"root":{"text":"neath","meaning":"below (下方)"},"logic":"在下方的位置。"}', 'beneath the surface / beneath one''s dignity', '[{"en":"The treasure was buried beneath the old tree.","zh-TW":"寶藏埋在老樹下方。"},{"en":"Beneath the surface, there are many problems.","zh-TW":"表面之下有許多問題。"}]', NULL, NULL, 3, 626, NULL),
(627, 'beneficent', '/bɪˈnefɪsənt/', 'adjective', '{"zh-TW":["仁慈的；行善的"],"en":["generous or doing good; conferring benefits"]}', NULL, 'beneficent policy / beneficent organization / beneficent intent', '[{"en":"A beneficent climate policy would reduce emissions while creating jobs.","zh-TW":"一項仁慈的氣候政策將在創造就業機會的同時減少排放。"},{"en":"The foundation is known for its beneficent work in education and healthcare.","zh-TW":"該基金會因其在教育和醫療保健方面的善舉而聞名。"}]', '{"noun":"beneficence","adverb":"beneficently"}', NULL, 4, 627, NULL),
(628, 'beneficiary', '/ˌbenɪˈfɪʃiəri/', 'noun', '{"zh-TW":["受益人"],"en":["a person or entity entitled to receive benefits from a policy or trust"]}', NULL, 'name a beneficiary / policy beneficiary / trust beneficiary', '[{"en":"She named her children as beneficiaries of her life insurance policy.","zh-TW":"她將子女列為人壽保險保單的受益人。"},{"en":"The beneficiary received the full payout upon the policyholder''s death.","zh-TW":"受益人在保單持有人死亡後獲得了全額賠付。"}]', '{"plural":"beneficiaries"}', NULL, 4, 628, NULL),
(629, 'benefit', '/ˈbenɪfɪt/', 'noun', '{"zh-TW":["利益；好處","福利"],"en":["an advantage or profit gained","a payment made by the state or employer"]}', '{"root":{"text":"bene","meaning":"good (好)"},"suffix":{"text":"-fit","meaning":"do/make (做)"},"logic":"做好事帶來的，即「利益」。"}', 'benefit from / employee benefits / mutual benefit', '[{"en":"Both parties will benefit from this partnership.","zh-TW":"雙方都將從這個合作中受益。"},{"en":"The company offers excellent employee benefits.","zh-TW":"公司提供優秀的員工福利。"}]', '{"adjective":"beneficial"}', NULL, 3, 629, 12),
(630, 'benefit period', '/ˈbɛnɪfɪt ˈpɪəriəd/', 'noun', '{"zh-TW":["保險給付期間"],"en":["the length of time insurance benefits are payable"]}', NULL, 'annual benefit period / benefit period limit', '[{"en":"Your benefit period begins on the date of enrollment.","zh-TW":"您的保險給付期間從入保日期開始計算。"},{"en":"Hospitalization is covered during the benefit period.","zh-TW":"住院費用在保險給付期間內承保。"}]', NULL, NULL, 5, 630, NULL),
(631, 'benefits', '/ˈbɛnɪfɪts/', 'noun', '{"zh-TW":["福利；員工福利"],"en":["non-wage compensation provided to employees"]}', NULL, 'employee benefits / benefits package', '[{"en":"The benefits package includes health insurance and a pension.","zh-TW":"福利待遇包括健康保險和退休金。"},{"en":"Many employees value good benefits over higher salaries.","zh-TW":"許多員工重視良好福利勝過更高薪資。"}]', '{"verb":"benefit","adjective":"beneficial"}', NULL, 3, 631, NULL),
(632, 'benign', '/bɪˈnaɪn/', 'adjective', '{"zh-TW":["良性的；無害的"],"en":["(of a tumor or condition) not harmful or cancerous"]}', NULL, 'benign tumor / benign growth / benign condition', '[{"en":"The biopsy confirmed that the lump was benign.","zh-TW":"活檢確認腫塊是良性的。"},{"en":"Benign neglect of minor symptoms can sometimes allow self-healing.","zh-TW":"對輕微症狀的良性忽視有時可以讓自愈發生。"}]', '{"antonym":"malignant","adverb":"benignly"}', NULL, 2, 632, NULL),
(633, 'beside', '/bɪˈsaɪd/', 'preposition', '{"zh-TW":["在…旁邊"],"en":["next to; at the side of"]}', NULL, 'beside the point / sit beside', '[{"en":"Come and sit beside me.","zh-TW":"來坐在我旁邊。"},{"en":"That''s beside the point.","zh-TW":"那不是重點。"}]', NULL, NULL, 2, 633, NULL),
(634, 'besides', '/bɪˈsaɪdz/', 'preposition', '{"zh-TW":["除了…之外"],"en":["in addition to; apart from"]}', '{"prefix":{"text":"be-","meaning":"by (在旁)"},"root":{"text":"sides","meaning":"sides (邊)"},"logic":"在旁邊之外還有，即「除了…之外」。"}', 'besides that / besides me', '[{"en":"Besides English, she speaks French and German.","zh-TW":"除了英語，她還會說法語和德語。"},{"en":"Besides the cost, there are other concerns.","zh-TW":"除了費用之外，還有其他顧慮。"}]', NULL, NULL, 3, 634, NULL),
(635, 'best', '/best/', 'adjective, adverb, noun', '{"zh-TW":["最好的；最佳地"],"en":["of the highest quality; most well"]}', NULL, 'do one''s best / at best / best practice', '[{"en":"She is the best student in class.","zh-TW":"她是班上最好的學生。"},{"en":"We did our best to finish on time.","zh-TW":"我們盡了最大努力準時完成。"}]', NULL, NULL, 1, 635, NULL),
(636, 'best practice', '/best ˈpræktɪs/', 'noun', '{"zh-TW":["最佳實踐；最佳做法"],"en":["a method recognized as most effective in achieving results"]}', NULL, 'industry best practice / adopt best practices / share best practices', '[{"en":"We adopted best practices from leading companies worldwide.","zh-TW":"我們採用了全球領先公司的最佳實踐。"},{"en":"Best practices in cybersecurity should be followed strictly.","zh-TW":"應嚴格遵循網路安全最佳實踐。"}]', NULL, NULL, 5, 636, NULL),
(637, 'best practices', '/best ˈpræktɪsɪz/', 'noun', '{"zh-TW":["最佳實踐；最佳作法"],"en":["methods or techniques proven most effective in achieving a result"]}', NULL, 'adopt best practices / industry best practices', '[{"en":"The company adopted best practices from the manufacturing sector.","zh-TW":"公司採用了製造業的最佳實踐。"},{"en":"Sharing best practices across departments improves overall performance.","zh-TW":"跨部門分享最佳實踐改善了整體績效。"}]', NULL, NULL, 5, 637, NULL),
(638, 'beta', '/ˈbeɪtə/', 'noun', '{"zh-TW":["測試版"],"en":["an early version of a product for testing"]}', NULL, 'beta version / beta testing', '[{"en":"The app is still in beta.","zh-TW":"這個應用程式還在測試階段。"},{"en":"Beta testers found several bugs.","zh-TW":"測試用戶發現了幾個錯誤。"}]', NULL, NULL, 1, 638, NULL),
(639, 'better', '/ˈbetər/', 'adjective, adverb', '{"zh-TW":["更好的；更好地"],"en":["of a higher standard; more well"]}', NULL, 'had better (最好...) / get better', '[{"en":"This solution is better than the last one.","zh-TW":"這個方案比上一個好。"},{"en":"You''d better leave now.","zh-TW":"你最好現在離開。"}]', '{"verb":"better"}', NULL, 2, 639, NULL),
(640, 'between', '/bɪˈtwiːn/', 'preposition', '{"zh-TW":["在…之間","在...之間（兩者）"],"en":["in the space or time separating two things","in the space separating two things"]}', NULL, 'between meetings / in between; between you and me / in between; between A and B / in between', '[{"en":"The interview is between 2 and 3 p.m.","zh-TW":"面試在下午2點到3點之間。"},{"en":"Choose between the two options.","zh-TW":"在兩個選項之間做選擇。"},{"en":"The shop is between the bank and the post office.","zh-TW":"商店在銀行和郵局之間。"},{"en":"Between you and me, I don''t like him.","zh-TW":"你我之間說，我不喜歡他。"},{"en":"The meeting is between 2 and 4 PM.","zh-TW":"會議在下午2點到4點之間。"}]', '{"preposition":"between"}', NULL, 3, 640, NULL),
(641, 'beverage', '/ˈbɛvərɪdʒ/', 'noun', '{"zh-TW":["飲料；飲品"],"en":["a drink of any type"]}', NULL, 'hot beverage / cold beverage', '[{"en":"The beverage menu includes both alcoholic and non-alcoholic options.","zh-TW":"飲料菜單包含酒精和非酒精選項。"},{"en":"Complimentary beverages are served during the flight.","zh-TW":"飛行期間提供免費飲料。"}]', NULL, NULL, 3, 641, NULL),
(642, 'beyond', '/bɪˈjɒnd/', 'preposition', '{"zh-TW":["超越；在…之外"],"en":["further away than; outside the limits of"]}', '{"prefix":{"text":"be-","meaning":"by (在)"},"root":{"text":"yond","meaning":"that side (那邊)"},"logic":"在那邊之外，即「超越」。"}', 'beyond expectations / beyond doubt / go beyond', '[{"en":"The results went beyond our expectations.","zh-TW":"結果超出了我們的預期。"},{"en":"This task is beyond my abilities.","zh-TW":"這項任務超出了我的能力。"}]', NULL, NULL, 2, 642, NULL),
(643, 'biannual', '/baɪˈænjuəl/', 'adjective', '{"zh-TW":["每兩年一次的；每年兩次的"],"en":["occurring twice a year or every two years"]}', NULL, 'biannual review / biannual report', '[{"en":"A biannual performance review is conducted in June and December.","zh-TW":"每年兩次的績效審查在六月和十二月進行。"},{"en":"The board meets for a biannual strategic assessment.","zh-TW":"董事會每兩年進行一次戰略評估。"}]', '{"adverb":"biannually"}', NULL, 3, 643, NULL),
(644, 'bid', '/bɪd/', 'noun', '{"zh-TW":["出價；投標"],"en":["an offer of a price for something","an attempt to achieve something"]}', '{"root":{"text":"bid","meaning":"offer (提供)"},"logic":"提供價格，即「出價」。"}', 'submit a bid / highest bidder', '[{"en":"Three companies submitted bids for the project.","zh-TW":"三家公司對該專案提交了投標。"},{"en":"The winning bid was $4.5 million.","zh-TW":"中標金額為450萬美元。"}]', '{"noun":"bidder"}', NULL, 1, 644, NULL),
(645, 'bid bond', '/bɪd bɒnd/', 'noun', '{"zh-TW":["投標保函"],"en":["a guarantee that a bidder will enter into a contract if selected"]}', NULL, 'submit a bid bond / bid bond requirement', '[{"en":"A bid bond of 2% of the contract value was required.","zh-TW":"要求合約價值2%的投標保函。"},{"en":"The bid bond protects the client if the winning bidder withdraws.","zh-TW":"如果中標者撤回，投標保函保護了客戶。"}]', NULL, NULL, 3, 645, NULL),
(646, 'bid document', '/bɪd ˈdɒkjʊmənt/', 'noun', '{"zh-TW":["投標文件"],"en":["a formal submission outlining a company offer to win a contract"]}', NULL, 'prepare bid documents / submit bid documents', '[{"en":"All bid documents must be received before the 5 PM deadline.","zh-TW":"所有投標文件必須在下午5點截止日期前收到。"},{"en":"The bid documents included technical specifications and pricing.","zh-TW":"投標文件包括技術規格和定價。"}]', NULL, NULL, 4, 646, NULL),
(647, 'bid-ask spread', '/bɪd æsk spred/', 'noun', '{"zh-TW":["買賣差價"],"en":["the difference between the highest price a buyer will pay and the lowest a seller will accept"]}', NULL, 'narrow bid-ask spread / wide bid-ask spread / bid-ask spread compression', '[{"en":"A narrow bid-ask spread indicates a liquid and efficient market.","zh-TW":"較窄的買賣差價表明市場流動性好且效率高。"},{"en":"The bid-ask spread widens during periods of high volatility.","zh-TW":"買賣差價在高波動時期擴大。"}]', NULL, NULL, 5, 647, NULL),
(648, 'biennale', '/biˈenɑːli/', 'noun', '{"zh-TW":["雙年展"],"en":["an international art exhibition held every two years"]}', NULL, 'Venice Biennale / art biennale / participate in biennale', '[{"en":"The Venice Biennale is the world''s most prestigious contemporary art exhibition.","zh-TW":"威尼斯雙年展是世界上最負盛名的當代藝術展覽。"},{"en":"The artist was selected to represent her country at the biennale.","zh-TW":"這位藝術家被選中代表她的國家參加雙年展。"}]', NULL, NULL, 3, 648, NULL),
(649, 'bifurcate', '/ˈbaɪfərkeɪt/', 'verb', '{"zh-TW":["分叉；分成兩部分"],"en":["to divide into two branches or parts"]}', NULL, 'bifurcate the analysis / bifurcate into categories / bifurcate data', '[{"en":"The research bifurcates into qualitative and quantitative streams.","zh-TW":"研究分為質性和量化兩條路線。"},{"en":"The argument bifurcates around two competing theories.","zh-TW":"該論點圍繞兩種競爭理論分叉。"}]', '{"noun":"bifurcation","adjective":"bifurcated"}', NULL, 3, 649, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(650, 'big', '/bɪɡ/', 'adjective', '{"zh-TW":["大的","大的；重要的"],"en":["of considerable size or extent","large in size; important"]}', NULL, 'big deal / big picture; a big deal / big business', '[{"en":"They live in a big house.","zh-TW":"他們住在一棟大房子裡。"},{"en":"It''s no big deal.","zh-TW":"這沒什麼大不了的。"},{"en":"This is a big decision.","zh-TW":"這是一個重大決定。"}]', NULL, NULL, 1, 650, NULL),
(651, 'big data', '/bɪɡ ˈdeɪtə/', 'noun', '{"zh-TW":["大數據"],"en":["extremely large datasets analyzed to reveal patterns and trends"]}', NULL, 'big data analytics / leverage big data', '[{"en":"Big data analytics helps businesses make better decisions.","zh-TW":"大數據分析幫助企業做出更好的決策。"},{"en":"The company invested in big data infrastructure.","zh-TW":"公司投資了大數據基礎設施。"}]', NULL, NULL, 3, 651, NULL),
(652, 'bilateral', '/baɪˈlætərəl/', 'adjective', '{"zh-TW":["雙邊的"],"en":["involving two parties, especially countries"]}', '{"prefix":{"text":"bi-","meaning":"two (二)"},"root":{"text":"later","meaning":"side (邊)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"與兩邊有關的，即「雙邊的」。"}', 'bilateral agreement/trade/relations', '[{"en":"The two countries signed a bilateral trade agreement.","zh-TW":"兩國簽署了雙邊貿易協定。"},{"en":"Bilateral relations have improved significantly.","zh-TW":"雙邊關係已顯著改善。"}]', NULL, NULL, 3, 652, 959),
(653, 'bilateral agreement', '/ˌbaɪˈlætərəl əˈɡriːmənt/', 'noun', '{"zh-TW":["雙邊協議"],"en":["an agreement entered into by two parties, typically between two governments or organizations"]}', NULL, 'sign a bilateral agreement / bilateral trade agreement', '[{"en":"The two countries signed a bilateral agreement to reduce tariffs.","zh-TW":"兩國簽署了一項雙邊協議以降低關稅。"},{"en":"A bilateral agreement on data sharing was reached after months of talks.","zh-TW":"經過數月談判，達成了一項數據共享的雙邊協議。"}]', '{"opposite":"multilateral agreement"}', NULL, 5, 653, NULL),
(654, 'bilingual', '/''baɪˈlɪŋɡwəl/', 'adjective', '{"zh-TW":["雙語的；使用兩種語言的"],"en":["able to speak two languages fluently; relating to or expressed in two languages"]}', NULL, 'bilingual education / bilingual employee / fully bilingual', '[{"en":"The company prefers bilingual candidates who can communicate in both English and Mandarin.","zh-TW":"公司偏好能用英語和普通話溝通的雙語候選人。"},{"en":"Growing up in a bilingual household gave her a natural advantage in language learning.","zh-TW":"在雙語家庭中長大給了她語言學習的天然優勢。"}]', '{"noun":"bilingualism"}', NULL, 3, 654, NULL),
(655, 'bill', '/bɪl/', 'noun', '{"zh-TW":["帳單；費用"],"en":["a list of charges to be paid"]}', NULL, 'pay the bill / split the bill', '[{"en":"We asked the waiter for the bill after dessert.","zh-TW":"吃完甜點後我們要求服務生結帳。"},{"en":"Let''s split the bill equally among the four of us.","zh-TW":"讓我們四個人平分帳單。"}]', '{"verb":"bill","adjective":"billed"}', NULL, 1, 655, NULL),
(656, 'bill of exchange', '/bɪl əv ɪksˈtʃeɪndʒ/', 'noun', '{"zh-TW":["匯票"],"en":["a written order from one party to another to pay a specified amount at a set time"]}', NULL, 'draw a bill of exchange / accept a bill of exchange', '[{"en":"The exporter drew a bill of exchange on the importer for payment.","zh-TW":"出口商向進口商開立了匯票以獲取付款。"},{"en":"A bill of exchange is commonly used in international trade finance.","zh-TW":"匯票在國際貿易融資中廣泛使用。"}]', NULL, NULL, 5, 656, NULL),
(657, 'bill of lading', '/bɪl əv ˈleɪdɪŋ/', 'noun', '{"zh-TW":["提單"],"en":["a document acknowledging receipt of cargo for shipment"]}', NULL, 'issue a bill of lading / original bill of lading', '[{"en":"The shipper provided a bill of lading for the cargo.","zh-TW":"發貨人為貨物提供了提單。"},{"en":"A clean bill of lading indicates the goods arrived undamaged.","zh-TW":"清潔提單表明貨物完好無損地到達。"}]', NULL, NULL, 5, 657, NULL),
(658, 'billing cycle', '/ˈbɪlɪŋ ˈsaɪkəl/', 'noun', '{"zh-TW":["計費週期；帳單週期"],"en":["the recurring period between bills sent to a customer"]}', NULL, 'monthly billing cycle / end of billing cycle', '[{"en":"The billing cycle is 30 days from the date of service.","zh-TW":"計費週期為服務日期起30天。"},{"en":"Your statement arrives at the end of each billing cycle.","zh-TW":"您的帳單在每個計費週期結束時到達。"}]', NULL, NULL, 5, 658, NULL),
(659, 'billing rate', '/ˈbɪlɪŋ reɪt/', 'noun', '{"zh-TW":["計費率；收費率"],"en":["the rate at which a professional service charges clients for time or work"]}', NULL, 'set the billing rate / billing rate per hour', '[{"en":"The consulting firm''s billing rate is $250 per hour.","zh-TW":"諮詢公司的計費率為每小時250元。"},{"en":"Billing rates vary depending on the seniority of the assigned consultant.","zh-TW":"計費率因指派顧問的資歷不同而有所不同。"}]', NULL, NULL, 4, 659, NULL),
(660, 'billion', 'ˈbɪljən', 'noun', '{"zh-TW":["十億","龐大數量"],"en":["a thousand million","an extremely large number"]}', NULL, 'one billion/billion-dollar', '[{"en":"The company is now worth one billion dollars.","zh-TW":"公司現在價值十億美元。"}]', '{"adjective":"billion-dollar"}', NULL, 3, 660, NULL),
(661, 'binary classification', '/ˈbaɪnəri ˌklæsɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["二元分類"],"en":["a type of classification task involving two possible output categories"]}', NULL, 'binary classification model / binary classification problem / binary classification accuracy', '[{"en":"Email spam detection is a classic binary classification problem.","zh-TW":"電子郵件垃圾郵件檢測是一個經典的二元分類問題。"},{"en":"The model was trained to perform binary classification of medical images.","zh-TW":"該模型被訓練用於對醫學影像進行二元分類。"}]', NULL, NULL, 5, 661, NULL),
(662, 'binary tree', '/ˈbaɪnəri triː/', 'noun', '{"zh-TW":["二元樹"],"en":["a tree data structure where each node has at most two child nodes"]}', NULL, 'implement a binary tree / traverse a binary tree / balance a binary tree', '[{"en":"A binary search tree allows efficient data retrieval operations.","zh-TW":"二元搜索樹允許高效的數據檢索操作。"},{"en":"Binary trees are fundamental data structures taught in computer science.","zh-TW":"二元樹是計算機科學中教授的基本數據結構。"}]', NULL, NULL, 4, 662, NULL),
(663, 'bind', '/baɪnd/', 'verb', '{"zh-TW":["綁定；約束"],"en":["to tie or fasten tightly","to impose a legal obligation"]}', '{"root":{"text":"bind","meaning":"tie (綁)"},"logic":"源自古英語 bindan（綁住）。"}', 'legally binding / bind together', '[{"en":"The contract is legally binding.","zh-TW":"這份合約具有法律約束力。"},{"en":"The agreement binds both parties.","zh-TW":"協議對雙方都有約束力。"}]', '{"noun":"binding","adjective":"binding"}', NULL, 1, 663, NULL),
(664, 'binding', 'ˈbaɪndɪŋ', 'adjective', '{"zh-TW":["具有約束力的；有效的","必須遵守的"],"en":["legally enforceable","obligatory"]}', NULL, 'legally binding/binding agreement', '[{"en":"This is a legally binding contract.","zh-TW":"這是一份具有法律約束力的合約。"}]', '{"verb":"bind","noun":"binding"}', NULL, 3, 664, 515),
(665, 'binding agreement', '/ˈbaɪndɪŋ əˈɡriːmənt/', 'noun', '{"zh-TW":["具有法律約束力的協議"],"en":["a contract that is legally enforceable"]}', NULL, 'enter into a binding agreement / sign a binding agreement', '[{"en":"By signing, you enter into a legally binding agreement.","zh-TW":"簽署後，您進入具有法律約束力的協議。"},{"en":"The binding agreement outlines both parties'' responsibilities.","zh-TW":"具有法律約束力的協議概述了雙方的責任。"}]', NULL, NULL, 5, 665, NULL),
(666, 'binding contract', '/ˈbaɪndɪŋ ˈkɒntrækt/', 'noun', '{"zh-TW":["具有約束力的合約"],"en":["a legally enforceable agreement between two or more parties"]}', NULL, 'enter a binding contract / binding contract terms', '[{"en":"Both parties signed a binding contract specifying delivery deadlines.","zh-TW":"雙方簽署了一份規定交貨截止日期的具有約束力的合約。"},{"en":"A binding contract requires consideration, capacity, and mutual consent.","zh-TW":"具有約束力的合約需要代價、能力和雙方同意。"}]', '{"adjective":"binding"}', NULL, 5, 666, NULL),
(667, 'bioavailability', '/ˌbaɪəʊəˌveɪləˈbɪlɪti/', 'noun', '{"zh-TW":["生物利用度；生物可用性"],"en":["the proportion of a drug that enters circulation and has an active effect"]}', NULL, 'improve bioavailability / oral bioavailability / assess bioavailability', '[{"en":"The new formulation increased the bioavailability of the active compound.","zh-TW":"新製劑提高了活性化合物的生物利用度。"},{"en":"Bioavailability determines how much of a drug reaches its target.","zh-TW":"生物利用度決定了多少藥物到達其靶標。"}]', '{"adjective":"bioavailable"}', NULL, 5, 667, NULL),
(668, 'biodegradable', '/ˌbaɪəʊdɪˈɡreɪdəbəl/', 'adjective', '{"zh-TW":["可生物降解的"],"en":["capable of being decomposed naturally by living organisms"]}', NULL, 'biodegradable packaging / biodegradable material', '[{"en":"The company replaced plastic with biodegradable packaging.","zh-TW":"公司將塑膠替換為可生物降解包裝。"},{"en":"Biodegradable products reduce environmental pollution.","zh-TW":"可生物降解產品減少了環境污染。"}]', '{"noun":"biodegradation","verb":"biodegrade"}', NULL, 5, 668, NULL),
(669, 'biodiversity', '/ˌbaɪəʊdaɪˈvɜːrsɪti/', 'noun', '{"zh-TW":["生物多樣性"],"en":["the variety of plant and animal life in an ecosystem"]}', NULL, 'protect biodiversity / loss of biodiversity', '[{"en":"Deforestation threatens biodiversity in tropical regions.","zh-TW":"森林砍伐威脅熱帶地區的生物多樣性。"},{"en":"Conservation efforts aim to preserve biodiversity.","zh-TW":"保育工作旨在保護生物多樣性。"}]', '{"adjective":"biodiverse"}', NULL, 4, 669, NULL),
(670, 'biodiversity loss', '/''baɪəʊdaɪˌvɜːrsɪti lɒs/', 'noun', '{"zh-TW":["生物多樣性喪失"],"en":["the decline in the number and variety of species in an ecosystem, often due to human activity"]}', NULL, 'combat biodiversity loss / cause of biodiversity loss / biodiversity loss crisis', '[{"en":"Scientists warn that biodiversity loss threatens the stability of ecosystems worldwide.","zh-TW":"科學家警告，生物多樣性喪失威脅到全球生態系統的穩定性。"},{"en":"Deforestation is one of the primary drivers of biodiversity loss in tropical regions.","zh-TW":"森林砍伐是熱帶地區生物多樣性喪失的主要驅動因素之一。"}]', '{"noun":"biodiversity"}', NULL, 5, 670, NULL),
(671, 'biomass', '/ˈbaɪəʊmæs/', 'noun', '{"zh-TW":["生物質；生物量"],"en":["organic material from plants and animals used as a renewable energy source"]}', NULL, 'biomass energy / biomass fuel / biomass power plant', '[{"en":"Biomass energy is generated by burning organic materials such as wood and crop waste.","zh-TW":"生物質能源是通過燃燒木材和農作物廢料等有機材料產生的。"},{"en":"A new biomass power plant will provide clean electricity to 50,000 homes.","zh-TW":"一座新的生物質發電廠將為五萬戶家庭提供清潔電力。"}]', '{"adjective":"biomass-based"}', NULL, 3, 671, NULL),
(672, 'biometric', '/ˌbaɪəˈmetrɪk/', 'adjective', '{"zh-TW":["生物辨識的"],"en":["relating to unique physical or behavioral characteristics used for identification"]}', NULL, 'biometric authentication / biometric data / biometric scanner', '[{"en":"Biometric authentication uses fingerprints or facial recognition to verify identity.","zh-TW":"生物辨識認證使用指紋或臉部識別來驗證身份。"},{"en":"Mobile phones increasingly use biometric unlocking for security.","zh-TW":"行動電話越來越多地使用生物辨識解鎖以確保安全。"}]', '{"noun":"biometrics"}', NULL, 3, 672, NULL),
(673, 'biomimicry', '/ˌbaɪəʊˈmɪmɪkri/', 'noun', '{"zh-TW":["仿生學"],"en":["the design of products inspired by natural systems and biological processes"]}', NULL, 'apply biomimicry / biomimicry design / biomimicry principles', '[{"en":"Biomimicry draws on nature''s solutions to create sustainable technologies.","zh-TW":"仿生學借鑒自然的解決方案來創造可持續技術。"},{"en":"Velcro was invented through biomimicry inspired by burr seeds.","zh-TW":"魔鬼氈是通過受芒刺種子啟發的仿生學發明的。"}]', '{"adjective":"biomimetic"}', NULL, 4, 673, NULL),
(674, 'biopsy', '/ˈbaɪɒpsi/', 'noun', '{"zh-TW":["活組織切片檢查；活檢"],"en":["a medical procedure examining a tissue sample to diagnose disease"]}', NULL, 'perform a biopsy / tissue biopsy / biopsy result', '[{"en":"The biopsy revealed the presence of cancerous cells.","zh-TW":"活檢顯示存在癌細胞。"},{"en":"A biopsy is the definitive test for confirming cancer diagnoses.","zh-TW":"活檢是確認癌症診斷的決定性測試。"}]', '{"verb":"biopsy"}', NULL, 2, 674, NULL),
(675, 'biosphere', '/ˈbaɪəsfɪər/', 'noun', '{"zh-TW":["生物圈"],"en":["the regions of the surface of the earth occupied by living organisms"]}', NULL, 'preserve the biosphere / biosphere reserve / biosphere sustainability', '[{"en":"Human activity is altering the biosphere at an unprecedented rate.","zh-TW":"人類活動正在以前所未有的速度改變生物圈。"},{"en":"Maintaining biosphere integrity is essential for life on Earth.","zh-TW":"維護生物圈完整性對地球生命至關重要。"}]', '{"adjective":"biospheric"}', NULL, 3, 675, NULL),
(676, 'biotechnology', '/ˌbaɪəʊtekˈnɒlədʒi/', 'noun', '{"zh-TW":["生物技術"],"en":["the use of biological systems and organisms in technology and industry"]}', NULL, 'apply biotechnology / biotechnology research / biotechnology company', '[{"en":"Biotechnology has revolutionized drug development and agricultural yields.","zh-TW":"生物技術革命性地改變了藥物開發和農業產量。"},{"en":"CRISPR gene editing is a breakthrough biotechnology with wide applications.","zh-TW":"CRISPR基因編輯是一項具有廣泛應用的突破性生物技術。"}]', '{"adjective":"biotechnological","adverb":"biotechnologically"}', NULL, 5, 676, NULL),
(677, 'bipartisan', '/ˌbaɪˈpɑːrtɪzən/', 'adjective', '{"zh-TW":["兩黨的；跨黨派的"],"en":["supported by or consisting of members from two political parties"]}', NULL, 'bipartisan support / bipartisan agreement / bipartisan effort', '[{"en":"The infrastructure bill received rare bipartisan support in Congress.","zh-TW":"基礎設施法案在國會獲得了罕見的兩黨支持。"},{"en":"Bipartisan cooperation is needed to address long-term fiscal challenges.","zh-TW":"需要跨黨派合作來解決長期財政挑戰。"}]', '{"noun":"bipartisanship"}', NULL, 4, 677, NULL),
(678, 'bird', '/bɜːrd/', 'noun', '{"zh-TW":["鳥"],"en":["a creature with wings and feathers","an animal with wings and feathers that can usually fly"]}', NULL, 'early bird / bird''s eye view; early bird / bird''s-eye view', '[{"en":"A bird was singing in the tree.","zh-TW":"一隻鳥在樹上唱歌。"},{"en":"The early bird catches the worm.","zh-TW":"早起的鳥兒有蟲吃。"},{"en":"We saw many birds in the park.","zh-TW":"我們在公園看到很多鳥。"}]', NULL, NULL, 1, 678, NULL),
(679, 'birth', '/bɜːrθ/', 'noun', '{"zh-TW":["出生；誕生"],"en":["the process of being born"]}', NULL, 'give birth / date of birth', '[{"en":"She gave birth to twins.","zh-TW":"她生了雙胞胎。"},{"en":"What is your date of birth?","zh-TW":"你的出生日期是什麼？"}]', '{"noun2":"birthday"}', NULL, 2, 679, NULL),
(680, 'bistro', '/ˈbiːstrəʊ/', 'noun', '{"zh-TW":["小酒館；餐廳"],"en":["a small, informal restaurant"]}', NULL, 'French bistro / neighborhood bistro', '[{"en":"We found a charming bistro near the city center.","zh-TW":"我們在市中心附近找到了一家迷人的小酒館。"},{"en":"The bistro specializes in traditional French dishes.","zh-TW":"這家小酒館專門供應傳統法國菜餚。"}]', NULL, NULL, 2, 680, NULL),
(681, 'bite', '/baɪt/', 'verb', '{"zh-TW":["咬"],"en":["to use teeth to cut into something"]}', NULL, 'bite off / insect bite', '[{"en":"The dog bit his hand.","zh-TW":"狗咬了他的手。"},{"en":"Don''t bite off more than you can chew.","zh-TW":"不要貪多嚼不爛。"}]', NULL, NULL, 1, 681, NULL),
(682, 'bitter', '/ˈbɪtər/', 'adjective', '{"zh-TW":["苦的；痛苦的"],"en":["having a sharp unpleasant taste"]}', NULL, 'bitter cold / bitter experience', '[{"en":"This coffee tastes bitter.","zh-TW":"這咖啡嘗起來很苦。"},{"en":"It was a bitter experience.","zh-TW":"那是一段痛苦的經歷。"}]', '{"noun":"bitterness","adverb":"bitterly"}', NULL, 2, 682, NULL),
(683, 'black', '/blæk/', 'adjective', '{"zh-TW":["黑色的","黑色的；黑暗的"],"en":["the darkest color","having the darkest color; very dark"]}', NULL, 'black and white / black market; black and white / in the black (有盈餘)', '[{"en":"She was wearing a black dress.","zh-TW":"她穿著一件黑色洋裝。"},{"en":"It''s not a black and white issue.","zh-TW":"這不是一個非黑即白的問題。"},{"en":"The company is finally in the black.","zh-TW":"公司終於有盈餘了。"}]', NULL, NULL, 2, 683, NULL),
(684, 'blame', '/bleɪm/', 'verb', '{"zh-TW":["責備；歸咎"],"en":["to say someone is responsible for something bad"]}', NULL, 'blame for / take the blame', '[{"en":"Don''t blame me for your mistake.","zh-TW":"別把你的錯怪到我頭上。"},{"en":"He took the blame for everything.","zh-TW":"他承擔了所有的責任。"}]', NULL, NULL, 2, 684, NULL),
(685, 'blanch', '/''blɑːntʃ/', 'verb', '{"zh-TW":["汆燙；焯水"],"en":["to briefly cook vegetables in boiling water and then cool them in ice water to preserve color and texture"]}', NULL, 'blanch the vegetables / blanch for two minutes / briefly blanch', '[{"en":"Blanch the green beans for two minutes to preserve their bright color.","zh-TW":"汆燙青豆兩分鐘以保持其鮮亮的顏色。"},{"en":"She blanched the tomatoes to make it easier to peel their skins.","zh-TW":"她汆燙番茄，使其更容易去皮。"}]', NULL, NULL, 2, 685, NULL),
(686, 'blank', '/blæŋk/', 'adjective', '{"zh-TW":["空白的"],"en":["with nothing written or printed on it"]}', NULL, 'blank page / draw a blank', '[{"en":"Fill in the blank spaces.","zh-TW":"填寫空白處。"},{"en":"My mind went blank.","zh-TW":"我的腦袋一片空白。"}]', NULL, NULL, 2, 686, NULL),
(687, 'blended learning', '/''blendɪd ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["混成學習；混合式學習"],"en":["an approach combining traditional face-to-face teaching with online instruction"]}', NULL, 'implement blended learning / blended learning model / benefits of blended learning', '[{"en":"Blended learning gives students flexibility to study at their own pace online.","zh-TW":"混成學習讓學生可以靈活地按自己的節奏在線學習。"},{"en":"The university shifted to a blended learning model during the pandemic.","zh-TW":"大學在疫情期間轉向了混成學習模式。"}]', NULL, NULL, 5, 687, NULL),
(688, 'blended rate', '/ˈblendɪd reɪt/', 'noun', '{"zh-TW":["混合利率；綜合利率"],"en":["an average interest rate combining rates from multiple loans or periods"]}', NULL, 'calculate the blended rate / blended rate of return', '[{"en":"The blended rate on the portfolio loans was 4.8%.","zh-TW":"投資組合貸款的混合利率為4.8%。"},{"en":"Refinancing multiple loans into one reduces the blended rate.","zh-TW":"將多筆貸款合併再融資降低了混合利率。"}]', NULL, NULL, 4, 688, NULL),
(689, 'blind', '/blaɪnd/', 'adjective', '{"zh-TW":["瞎的；盲目的"],"en":["unable to see"]}', NULL, 'turn a blind eye / blind spot', '[{"en":"He has been blind since birth.","zh-TW":"他生下來就看不見。"},{"en":"Don''t turn a blind eye to injustice.","zh-TW":"不要對不公正視而不見。"}]', '{"noun":"blindness","adverb":"blindly"}', NULL, 2, 689, NULL),
(690, 'blizzard', '/ˈblɪzərd/', 'noun', '{"zh-TW":["暴風雪"],"en":["a severe snowstorm with strong winds"]}', '{"root":{"text":"blizzard","meaning":"violent blow (猛烈吹襲)"},"logic":"指伴隨強風的猛烈暴風雪。"}', 'caught in a blizzard / blizzard conditions', '[{"en":"The blizzard shut down all major highways.","zh-TW":"暴風雪導致所有主要公路關閉。"},{"en":"Schools were closed due to the blizzard.","zh-TW":"學校因暴風雪停課。"}]', NULL, NULL, 3, 690, NULL),
(691, 'block', '/blɒk/', 'noun', '{"zh-TW":["街區；障礙物"],"en":["a solid piece; an area of buildings"]}', NULL, 'road block / around the block', '[{"en":"The office is two blocks away.","zh-TW":"辦公室在兩個街區外。"},{"en":"A tree blocked the road.","zh-TW":"一棵樹擋住了路。"}]', '{"verb":"block"}', NULL, 2, 691, NULL),
(692, 'block booking', '/blɒk ˈbʊkɪŋ/', 'noun', '{"zh-TW":["整批預訂；大量預訂"],"en":["the reservation of a large quantity of rooms, tickets, or services at once"]}', NULL, 'make a block booking / block booking discount', '[{"en":"The conference organizer made a block booking at the hotel.","zh-TW":"會議組織者在飯店進行了整批預訂。"},{"en":"Block bookings often receive preferential rates from suppliers.","zh-TW":"整批預訂通常從供應商那裡獲得優惠費率。"}]', NULL, NULL, 5, 692, NULL),
(693, 'blockchain', '/ˈblɒktʃeɪn/', 'noun', '{"zh-TW":["區塊鏈"],"en":["a distributed digital ledger recording transactions securely across many computers"]}', NULL, 'blockchain technology / blockchain network / apply blockchain', '[{"en":"Blockchain technology ensures tamper-proof transaction records.","zh-TW":"區塊鏈技術確保了防篡改的交易記錄。"},{"en":"Supply chain transparency improved through blockchain implementation.","zh-TW":"通過實施區塊鏈改善了供應鏈透明度。"}]', '{"adjective":"blockchain-based"}', NULL, 4, 693, NULL),
(694, 'blood', '/blʌd/', 'noun', '{"zh-TW":["血液","血；血液","血液；血統"],"en":["the red liquid flowing through the body","the red liquid in your body","the red liquid that flows through the body"]}', NULL, 'blood pressure / blood test; blood pressure / blood test / in cold blood', '[{"en":"High blood pressure is a common issue.","zh-TW":"高血壓是常見的問題。"},{"en":"The doctor ordered a blood test.","zh-TW":"醫生安排了驗血。"},{"en":"She donated blood today.","zh-TW":"她今天捐了血。"},{"en":"High blood pressure is dangerous.","zh-TW":"高血壓是危險的。"},{"en":"He donated blood at the hospital.","zh-TW":"他在醫院捐血。"},{"en":"High blood pressure is a common condition.","zh-TW":"高血壓是常見的疾病。"}]', '{"noun":"blood","adjective":"bloody","verb":"bleed"}', NULL, 2, 694, NULL),
(695, 'blood bank', '/blʌd bæŋk/', 'noun', '{"zh-TW":["血庫"],"en":["a store of blood for use in medical treatment"]}', NULL, 'donate to a blood bank / blood bank supply', '[{"en":"Donate blood to help replenish the blood bank.","zh-TW":"捐血以幫助補充血庫存量。"},{"en":"The blood bank maintained adequate supplies for emergencies.","zh-TW":"血庫維持了足夠的緊急備用存量。"}]', NULL, NULL, 4, 695, NULL),
(696, 'blood pressure', '/blʌd ˈprɛʃər/', 'noun', '{"zh-TW":["血壓"],"en":["the pressure of blood circulating against vessel walls"]}', NULL, 'high blood pressure / check blood pressure', '[{"en":"The nurse checked his blood pressure every hour.","zh-TW":"護士每小時檢查他的血壓。"},{"en":"High blood pressure increases the risk of heart disease.","zh-TW":"高血壓增加了心臟病的風險。"}]', NULL, NULL, 5, 696, NULL),
(697, 'blood test', '/blʌd tɛst/', 'noun', '{"zh-TW":["血液檢查"],"en":["an examination of a blood sample for diagnosis"]}', NULL, 'take a blood test / blood test results', '[{"en":"The doctor ordered a blood test to check cholesterol.","zh-TW":"醫生要求進行血液檢查以檢測膽固醇。"},{"en":"Your blood test results will be ready in two days.","zh-TW":"您的血液檢查結果兩天後即可查看。"}]', NULL, NULL, 4, 697, NULL),
(698, 'blood type', '/blʌd taɪp/', 'noun', '{"zh-TW":["血型"],"en":["a classification of blood based on antigens"]}', NULL, 'blood type O / know your blood type', '[{"en":"It is important to know your blood type in case of emergency.","zh-TW":"在緊急情況下知道自己的血型非常重要。"},{"en":"The doctor asked about her blood type before surgery.","zh-TW":"醫生在手術前詢問了她的血型。"}]', NULL, NULL, 4, 698, NULL),
(699, 'blow', '/bloʊ/', 'verb', '{"zh-TW":["吹；打擊"],"en":["to send air from the mouth","to move air; a hard hit or shock"]}', NULL, 'blow up / blow out; blow up / blow out / a blow to', '[{"en":"The wind blew the leaves away.","zh-TW":"風把樹葉吹走了。"},{"en":"Blow out the candles.","zh-TW":"吹滅蠟燭。"},{"en":"The wind is blowing hard today.","zh-TW":"今天風吹得很大。"},{"en":"Losing the contract was a blow to the company.","zh-TW":"失去合約對公司是一個打擊。"}]', NULL, NULL, 1, 699, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(700, 'blue', '/bluː/', 'adjective', '{"zh-TW":["藍色的；憂鬱的"],"en":["the color of the sky on a clear day","having the color of the sky; sad"]}', NULL, 'out of the blue / feeling blue; out of the blue (突然) / feel blue', '[{"en":"The sky is bright blue today.","zh-TW":"今天天空是亮藍色的。"},{"en":"The news came out of the blue.","zh-TW":"這消息來得很突然。"},{"en":"The sky is clear and blue.","zh-TW":"天空清澈湛藍。"}]', NULL, NULL, 1, 700, NULL),
(701, 'blue chip', '/bluː tʃɪp/', 'adjective', '{"zh-TW":["績優的；藍籌的"],"en":["relating to a company that is well-established and financially stable"]}', NULL, 'blue chip company / blue chip investment', '[{"en":"Pension funds typically hold blue chip stocks for stable long-term returns.","zh-TW":"養老基金通常持有績優股票以獲得穩定的長期回報。"},{"en":"Blue chip companies are regarded as low-risk investments.","zh-TW":"績優公司被視為低風險投資。"}]', '{"noun":"blue chip stock"}', NULL, 3, 701, NULL),
(702, 'blue ocean strategy', '/bluː ˈoʊʃən ˈstrætədʒi/', 'noun', '{"zh-TW":["藍海策略"],"en":["a strategy of creating uncontested market space rather than competing"]}', NULL, 'pursue a blue ocean strategy / blue ocean vs red ocean', '[{"en":"The startup found a blue ocean by targeting an entirely new customer segment.","zh-TW":"新創公司通過針對全新客戶群找到了藍海。"},{"en":"Blue ocean strategy focuses on value innovation rather than competition.","zh-TW":"藍海策略著重於價值創新而非競爭。"}]', NULL, NULL, 5, 702, NULL),
(703, 'blue-chip stock', '/bluː tʃɪp stɒk/', 'noun', '{"zh-TW":["藍籌股"],"en":["shares in a large, reputable, and financially stable company"]}', NULL, 'invest in blue-chip stocks / blue-chip stock performance', '[{"en":"Blue-chip stocks provide stable dividends and lower volatility.","zh-TW":"藍籌股提供穩定的股息和較低的波動性。"},{"en":"Institutional investors favor blue-chip stocks for long-term portfolios.","zh-TW":"機構投資者青睞藍籌股用於長期投資組合。"}]', NULL, NULL, 5, 703, NULL),
(704, 'blueprint', '/ˈbluːprɪnt/', 'noun', '{"zh-TW":["藍圖；計畫","藍圖；詳細計畫"],"en":["a detailed plan or scheme","a detailed plan or design"]}', '{"root":{"text":"blue","meaning":"blue (藍色)"},"suffix":{"text":"print","meaning":"print (印刷)"},"logic":"藍色印刷的設計圖，即「藍圖」。"}', 'blueprint for success / strategic blueprint; blueprint for success / provide a blueprint', '[{"en":"The CEO presented a blueprint for the company''s future.","zh-TW":"執行長提出了公司未來的藍圖。"},{"en":"This plan serves as a blueprint for similar projects.","zh-TW":"此計畫可作為類似專案的藍圖。"},{"en":"This is our blueprint for expansion.","zh-TW":"這是我們的擴張藍圖。"},{"en":"The report provides a blueprint for reform.","zh-TW":"報告提供了改革的藍圖。"}]', '{"noun":"blueprint"}', NULL, 3, 704, 828),
(705, 'bluetooth', '/ˈbluːtuːθ/', 'noun', '{"zh-TW":["藍牙"],"en":["wireless technology for short-range data exchange"]}', NULL, 'bluetooth connection / bluetooth speaker', '[{"en":"Connect your headphones via Bluetooth.","zh-TW":"透過藍牙連接你的耳機。"},{"en":"Is your Bluetooth turned on?","zh-TW":"你的藍牙開了嗎？"}]', NULL, NULL, 3, 705, NULL),
(706, 'board', '/bɔːrd/', 'noun', '{"zh-TW":["董事會；委員會","板"],"en":["a group of people who manage an organization","to get on a vehicle"]}', '{"root":{"text":"board","meaning":"plank/table (桌板)"},"logic":"圍著桌子開會的人，即「董事會」。"}', 'board of directors / board meeting / on board', '[{"en":"The board of directors approved the acquisition.","zh-TW":"董事會批准了收購案。"},{"en":"All passengers must board 30 minutes before departure.","zh-TW":"所有乘客必須在起飛前30分鐘登機。"}]', NULL, NULL, 2, 706, 279),
(707, 'board meeting', '/bɔːrd ˈmiːtɪŋ/', 'noun', '{"zh-TW":["董事會會議"],"en":["a formal meeting of a company''s board of directors"]}', NULL, 'attend a board meeting / quarterly board meeting', '[{"en":"The board meeting approved the expansion strategy.","zh-TW":"董事會會議批准了擴張策略。"},{"en":"Minutes of the board meeting are distributed within 48 hours.","zh-TW":"董事會會議記錄在48小時內分發。"}]', NULL, NULL, 5, 707, NULL),
(708, 'board of directors', '/bɔːrd əv dɪˈrektərz/', 'noun', '{"zh-TW":["董事會"],"en":["the governing body of a corporation elected by shareholders"]}', NULL, 'board of directors meeting / sit on the board of directors', '[{"en":"The board of directors approved the acquisition.","zh-TW":"董事會批准了收購計劃。"},{"en":"She was elected to the board of directors last month.","zh-TW":"她上個月當選為董事會成員。"}]', '{"singular":"board member"}', NULL, 5, 708, NULL),
(709, 'board resolution', '/bɔːrd ˌrezəˈluːʃən/', 'noun', '{"zh-TW":["董事會決議"],"en":["a formal decision made and documented by a company''s board of directors"]}', NULL, 'pass a board resolution / board resolution required', '[{"en":"A board resolution was passed to approve the acquisition.","zh-TW":"通過了一項董事會決議以批准此次收購。"},{"en":"All major financial commitments require a board resolution.","zh-TW":"所有重大財務承諾都需要董事會決議。"}]', NULL, NULL, 5, 709, NULL),
(710, 'boarding pass', '/ˈbɔːrdɪŋ pæs/', 'noun', '{"zh-TW":["登機證"],"en":["a document allowing a passenger to board a plane"]}', NULL, 'print a boarding pass / mobile boarding pass', '[{"en":"Please have your boarding pass ready at the gate.","zh-TW":"請在登機口備好登機證。"},{"en":"You can download your boarding pass to your phone.","zh-TW":"您可以把登機證下載到手機。"}]', NULL, NULL, 5, 710, NULL),
(711, 'boardroom', '/ˈbɔːrdruːm/', 'noun', '{"zh-TW":["董事會會議室；會議室"],"en":["a room where a board of directors meets"]}', NULL, 'boardroom meeting / boardroom presentation', '[{"en":"The quarterly review was held in the boardroom.","zh-TW":"季度審查在董事會會議室舉行。"},{"en":"A major decision was announced from the boardroom.","zh-TW":"一項重大決定從董事會會議室宣布。"}]', NULL, NULL, 3, 711, NULL),
(712, 'boat', '/boʊt/', 'noun', '{"zh-TW":["船；小艇"],"en":["a vehicle for traveling on water","a small vessel for traveling on water"]}', NULL, 'by boat / in the same boat; by boat / in the same boat (同命運)', '[{"en":"We crossed the lake by boat.","zh-TW":"我們乘船穿過了湖。"},{"en":"We''re all in the same boat.","zh-TW":"我們都處於同樣的處境。"},{"en":"They crossed the river by boat.","zh-TW":"他們搭船渡河。"},{"en":"We''re all in the same boat.","zh-TW":"我們都處於相同的處境。"}]', NULL, NULL, 1, 712, NULL),
(713, 'body', '/ˈbɒdi/', 'noun', '{"zh-TW":["身體；主體；機構","身體；主體","身體；團體；主體"],"en":["physical structure of a person","an organized group","the physical structure of a person","the physical structure of a person; a group"]}', NULL, 'body language / governing body; body language / body of work', '[{"en":"Body language is important in interviews.","zh-TW":"面試時肢體語言很重要。"},{"en":"The governing body approved the plan.","zh-TW":"管理機構批准了計畫。"},{"en":"Exercise is good for the body.","zh-TW":"運動對身體有好處。"},{"en":"His body language shows confidence.","zh-TW":"他的肢體語言展現了自信。"},{"en":"Exercise is good for the body.","zh-TW":"運動對身體有益。"},{"en":"The governing body approved the plan.","zh-TW":"管理機構批准了這個計畫。"}]', '{"noun":"body","adjective":"bodily"}', NULL, 1, 713, NULL),
(714, 'body composition', '/''bɒdi ˌkɒmpəˈzɪʃən/', 'noun', '{"zh-TW":["身體組成；體格成分"],"en":["the proportion of fat, bone, water, and muscle in the body"]}', NULL, 'measure body composition / improve body composition / body composition analysis', '[{"en":"Changes in body composition, not just body weight, are a better indicator of fitness progress.","zh-TW":"身體組成的變化，而不僅僅是體重，是衡量健身進度的更好指標。"},{"en":"A body composition analysis showed she had increased muscle mass and reduced body fat.","zh-TW":"身體組成分析顯示她增加了肌肉質量並減少了體脂肪。"}]', NULL, NULL, 5, 714, NULL),
(715, 'body language', '/''bɒdi ˌlæŋɡwɪdʒ/', 'noun', '{"zh-TW":["肢體語言；身體語言"],"en":["the movements and postures of the body that express feelings and intentions unconsciously"]}', NULL, 'read body language / positive body language / confident body language', '[{"en":"Maintaining eye contact and open body language projects confidence during interviews.","zh-TW":"在面試中保持眼神接觸和開放的肢體語言能展現自信。"},{"en":"Her body language suggested she was uncomfortable with the proposed solution.","zh-TW":"她的肢體語言表明她對提出的解決方案感到不舒適。"}]', NULL, NULL, 5, 715, NULL),
(716, 'body mass index', '/''bɒdi mæs ˌɪndeks/', 'noun', '{"zh-TW":["身體質量指數；BMI"],"en":["a measure of body fat based on weight and height, used to classify underweight and obesity"]}', NULL, 'calculate body mass index / body mass index chart / healthy body mass index', '[{"en":"A body mass index above thirty is typically classified as obese.","zh-TW":"身體質量指數超過三十通常被歸類為肥胖。"},{"en":"Doctors use body mass index as one indicator of a patient''s overall health.","zh-TW":"醫生使用身體質量指數作為評估患者整體健康狀況的指標之一。"}]', NULL, NULL, 5, 716, NULL),
(717, 'boil', '/''bɔɪl/', 'verb', '{"zh-TW":["煮沸；沸騰"],"en":["to heat a liquid to the point where it boils; to cook food in boiling water"]}', NULL, 'bring to a boil / boil for ten minutes / boil the pasta', '[{"en":"Bring the water to a boil before adding the pasta.","zh-TW":"在加入義大利麵之前，將水煮沸。"},{"en":"Boil the eggs for eight minutes for a hard-boiled result.","zh-TW":"將雞蛋煮八分鐘，得到全熟的水煮蛋。"}]', '{"noun":"boil"}', NULL, 1, 717, NULL),
(718, 'boilerplate clause', '/ˈbɔɪlərpleɪt klɔːz/', 'noun', '{"zh-TW":["標準條款；樣板條款"],"en":["a standard contract clause included as a default in most agreements"]}', NULL, 'include boilerplate clauses / amend a boilerplate clause', '[{"en":"The boilerplate clause on governing law was modified for the jurisdiction.","zh-TW":"管轄法律的標準條款根據司法管轄區進行了修改。"},{"en":"Parties often overlook boilerplate clauses but they can have significant legal impact.","zh-TW":"各方通常忽視標準條款，但它們可能具有重大的法律影響。"}]', NULL, NULL, 5, 718, NULL),
(719, 'bold', '/boʊld/', 'adjective', '{"zh-TW":["大膽的；粗體的"],"en":["willing to take risks","(of text) in a thick dark type"]}', '{"root":{"text":"bold","meaning":"brave (勇敢)"},"logic":"源自古英語 bald（勇敢的）。"}', 'bold move / bold decision / bold font', '[{"en":"That was a bold decision to make.","zh-TW":"那是一個大膽的決定。"},{"en":"Please highlight the key words in bold.","zh-TW":"請用粗體標示關鍵字。"}]', '{"noun":"boldness","adverb":"boldly"}', NULL, 1, 719, NULL),
(720, 'bomb', '/bɒm/', 'noun', '{"zh-TW":["炸彈"],"en":["an explosive weapon"]}', NULL, 'drop a bomb / bomb threat', '[{"en":"The bomb was defused safely.","zh-TW":"炸彈被安全拆除了。"},{"en":"The news dropped like a bomb.","zh-TW":"這消息像炸彈一樣爆開。"}]', '{"verb":"bomb","noun2":"bomber","noun3":"bombing"}', NULL, 1, 720, NULL),
(721, 'bond', '/bɒnd/', 'noun', '{"zh-TW":["債券；紐帶"],"en":["a certificate of debt issued by a government or company","a connection or relationship"]}', '{"root":{"text":"bond","meaning":"bind (綁)"},"logic":"綁定的承諾，即「債券、紐帶」。"}', 'government bond / corporate bond / bond market', '[{"en":"Investors shifted their portfolio toward bonds.","zh-TW":"投資者將投資組合轉向債券。"},{"en":"The company issued bonds to raise capital.","zh-TW":"公司發行債券籌集資金。"}]', NULL, NULL, 1, 721, NULL),
(722, 'bond indenture', '/bɒnd ɪnˈdentʃər/', 'noun', '{"zh-TW":["債券契約"],"en":["a legal contract setting out the terms of a bond between issuer and bondholder"]}', NULL, 'review the bond indenture / bond indenture covenant', '[{"en":"The bond indenture specified a 6% annual coupon payable semi-annually.","zh-TW":"債券契約規定了每半年支付6%的年票息。"},{"en":"Bondholders can enforce their rights through the provisions of the bond indenture.","zh-TW":"債券持有人可以通過債券契約的條款執行其權利。"}]', NULL, NULL, 5, 722, NULL),
(723, 'bond rating', '/bɒnd ˈreɪtɪŋ/', 'noun', '{"zh-TW":["債券評級"],"en":["a score assigned by a rating agency reflecting a bond issuer''s creditworthiness"]}', NULL, 'check bond rating / investment-grade bond rating', '[{"en":"The bond''s rating was downgraded to BB due to weakening earnings.","zh-TW":"由於盈利減弱，債券評級被下調至BB。"},{"en":"A higher bond rating means lower borrowing costs for the issuer.","zh-TW":"較高的債券評級意味著發行人的借貸成本較低。"}]', '{"synonym":"credit rating"}', NULL, 4, 723, NULL),
(724, 'bond spread', '/bɒnd spred/', 'noun', '{"zh-TW":["債券利差"],"en":["the difference in yield between a corporate bond and a government bond of similar maturity"]}', NULL, 'narrow bond spread / widen bond spread / measure bond spread', '[{"en":"A widening bond spread signals that investors see increased credit risk in the issuer.","zh-TW":"債券利差擴大表明投資者認為發行人的信用風險增加了。"},{"en":"Investment-grade bonds typically have a smaller bond spread than high-yield bonds.","zh-TW":"投資級債券的利差通常比高收益債券小。"}]', NULL, NULL, 4, 724, NULL),
(725, 'bond yield', '/bɒnd jiːld/', 'noun', '{"zh-TW":["債券收益率"],"en":["the return an investor receives from a bond expressed as a percentage"]}', NULL, 'rising bond yield / bond yield calculation / compare bond yields', '[{"en":"A rising bond yield makes bonds more attractive to investors.","zh-TW":"上升的債券收益率使債券對投資者更具吸引力。"},{"en":"The government bond yield fell to a record low during the crisis.","zh-TW":"危機期間，政府債券收益率降至歷史最低點。"}]', NULL, NULL, 4, 725, NULL),
(726, 'bonded warehouse', '/''bɒndɪd ˌweərhaʊs/', 'noun', '{"zh-TW":["保稅倉庫；保稅倉"],"en":["a secure storage facility where imported goods are kept before customs duties have been paid"]}', NULL, 'store in a bonded warehouse / bonded warehouse facility / use a bonded warehouse', '[{"en":"Importers can store goods in a bonded warehouse to defer paying customs duties.","zh-TW":"進口商可以將貨物存放在保稅倉庫，以推遲繳納關稅。"},{"en":"The bonded warehouse allowed the company to delay duty payments until goods were sold.","zh-TW":"保稅倉庫使該公司能夠推遲繳納關稅，直到貨物售出。"}]', NULL, NULL, 5, 726, NULL),
(727, 'bone', '/boʊn/', 'noun', '{"zh-TW":["骨頭"],"en":["the hard parts inside the body","the hard parts inside the body that form the skeleton"]}', NULL, 'broken bone / bone dry; bone structure / to the bone', '[{"en":"She broke a bone in her foot.","zh-TW":"她腳上的一根骨頭斷了。"},{"en":"The dog buried the bone.","zh-TW":"狗把骨頭埋了起來。"},{"en":"She broke a bone in her leg.","zh-TW":"她腿骨骨折了。"},{"en":"The cold wind cut to the bone.","zh-TW":"寒風刺骨。"}]', '{"adjective":"bony"}', NULL, 1, 727, NULL),
(728, 'bonus', '/ˈboʊnəs/', 'noun', '{"zh-TW":["獎金；紅利"],"en":["additional payment given to an employee for good performance"]}', NULL, 'performance bonus / annual bonus / sign-on bonus / bonus scheme', '[{"en":"All employees received a year-end bonus this December.","zh-TW":"所有員工今年十二月都收到了年終獎金。"},{"en":"The sales team earned a bonus for exceeding targets.","zh-TW":"銷售團隊因超越目標而獲得獎金。"}]', '{"plural":"bonuses"}', NULL, 2, 728, 829),
(729, 'bonus scheme', '/ˈboʊnəs skiːm/', 'noun', '{"zh-TW":["獎金方案"],"en":["a structured program defining how and when bonuses are earned and paid"]}', NULL, 'implement a bonus scheme / bonus scheme criteria', '[{"en":"The annual bonus scheme rewards employees who exceed their targets.","zh-TW":"年度獎金方案獎勵超過目標的員工。"},{"en":"A transparent bonus scheme improves staff motivation and fairness.","zh-TW":"透明的獎金方案改善了員工積極性和公平性。"}]', '{"synonym":"bonus plan","synonym2":"incentive scheme"}', NULL, 4, 729, NULL),
(730, 'bonus structure', '/ˈboʊnəs ˈstrʌktʃər/', 'noun', '{"zh-TW":["獎金結構"],"en":["the system determining how bonuses are calculated and awarded"]}', NULL, 'design a bonus structure / performance-based bonus structure', '[{"en":"The bonus structure rewards top performers with up to 30% extra pay.","zh-TW":"獎金結構為頂尖表現者提供最高30%的額外薪酬。"},{"en":"The new bonus structure aligns employee incentives with company goals.","zh-TW":"新的獎金結構使員工激勵與公司目標保持一致。"}]', NULL, NULL, 5, 730, NULL),
(731, 'book', '/bʊk/', 'verb', '{"zh-TW":["【主要意義-名詞】書；書籍","【次要意義-動詞】預訂（座位/房間）；登記","【次要意義-動詞（法律/警察用語）】逮捕登記；記錄違規"],"en":["[primary - noun] a set of printed pages bound together","[secondary - verb] to reserve a seat, room, or service in advance","[secondary - verb] to officially record an arrest or charge against someone"]}', NULL, 'book a table / book a flight / fully booked / book someone for speeding', '[{"en":"All seats for the conference have been booked in advance.","zh-TW":"會議的所有座位都已提前預訂。"},{"en":"The hotel is fully booked during the trade show period.","zh-TW":"貿易展期間飯店已全部訂滿。"},{"en":"The officer booked him for driving without a valid license.","zh-TW":"警察以無有效駕照駕車的罪名將他逮捕登記。"}]', '{"noun":"booking, bookkeeper, bookkeeping"}', '動詞 book = 「預訂」是 TOEIC 最常考用法，book a room/flight/table 是必考句型；police book someone（逮捕登記）則較少見，但出現在新聞類文章中。', 1, 731, NULL),
(732, 'book value', '/bʊk ˈvæljuː/', 'noun', '{"zh-TW":["帳面價值"],"en":["the value of an asset as recorded in the financial statements"]}', NULL, 'book value per share / price-to-book ratio / carry at book value', '[{"en":"The stock was trading below its book value, suggesting undervaluation.","zh-TW":"股票以低於帳面價值的價格交易，表明被低估。"},{"en":"Goodwill is often carried on the balance sheet above its book value.","zh-TW":"商譽通常在資產負債表上以高於帳面價值的價格記錄。"}]', NULL, NULL, 4, 732, NULL),
(733, 'book-to-market ratio', '/bʊk tə ˈmɑːrkɪt ˈreɪʃɪəʊ/', 'noun', '{"zh-TW":["帳面市值比"],"en":["the ratio of a company''s book value to its market capitalization"]}', NULL, 'high book-to-market ratio / low book-to-market ratio / use book-to-market ratio', '[{"en":"A high book-to-market ratio can indicate an undervalued stock according to value investing principles.","zh-TW":"根據價值投資原則，高帳面市值比可能表明一支股票被低估。"},{"en":"The Fama-French model uses the book-to-market ratio as a factor to explain stock returns.","zh-TW":"法瑪-法蘭奇模型使用帳面市值比作為解釋股票回報的因子。"}]', NULL, NULL, 5, 733, NULL),
(734, 'booking', '/ˈbʊkɪŋ/', 'noun', '{"zh-TW":["預訂"],"en":["a reservation for accommodation or travel"]}', NULL, 'online booking / advance booking', '[{"en":"Make your booking at least two weeks in advance.","zh-TW":"請至少提前兩週預訂。"},{"en":"The booking was confirmed by email.","zh-TW":"預訂已通過電子郵件確認。"}]', '{"verb":"book","adjective":"booked"}', NULL, 3, 734, NULL),
(735, 'bookkeeping', '/ˈbʊkˌkiːpɪŋ/', 'noun', '{"zh-TW":["簿記；記帳"],"en":["recording financial transactions in a systematic and orderly manner"]}', NULL, 'double-entry bookkeeping / bookkeeping software / outsource bookkeeping', '[{"en":"Accurate bookkeeping is essential for tax compliance.","zh-TW":"準確的簿記對稅務合規至關重要。"},{"en":"She handles all bookkeeping for the small business.","zh-TW":"她處理小企業的所有簿記工作。"}]', '{"noun":"bookkeeper","verb":"keep books"}', NULL, 4, 735, NULL),
(736, 'boost', '/buːst/', 'verb', '{"zh-TW":["提升；促進"],"en":["to increase or improve something"]}', '{"root":{"text":"boost","meaning":"push up (推高)"},"logic":"推高，即「提升」。"}', 'boost sales/productivity/morale', '[{"en":"The promotion helped boost sales by 25%.","zh-TW":"促銷活動幫助銷售增長了25%。"},{"en":"Team-building events can boost employee morale.","zh-TW":"團建活動能提升員工士氣。"}]', NULL, NULL, 2, 736, NULL),
(737, 'border', '/ˈbɔːrdər/', 'noun', '{"zh-TW":["邊界；國界"],"en":["the line that separates two countries"]}', NULL, 'cross the border / border control', '[{"en":"They crossed the border at night.","zh-TW":"他們夜間越過了邊境。"},{"en":"The town is on the border of France.","zh-TW":"這個鎮在法國的邊境上。"}]', NULL, NULL, 2, 737, NULL),
(738, 'border control', '/ˈbɔːrdər kənˈtrəʊl/', 'noun', '{"zh-TW":["邊境管制"],"en":["the regulation of people crossing a country''s borders"]}', NULL, 'pass border control / strict border control', '[{"en":"All travelers must pass through border control upon arrival.","zh-TW":"所有旅客抵達時必須通過邊境管制。"},{"en":"Border control officers check passports and visas.","zh-TW":"邊境管制人員檢查護照和簽證。"}]', NULL, NULL, 5, 738, NULL),
(739, 'border crossing', '/''bɔːrdər ˈkrɒsɪŋ/', 'noun', '{"zh-TW":["邊境過境點；入境口岸"],"en":["a place where people and vehicles cross from one country or territory to another"]}', NULL, 'busy border crossing / border crossing procedure / border crossing checkpoint', '[{"en":"The border crossing was crowded with travelers during the holiday season.","zh-TW":"假日期間，邊境過境點擠滿了旅客。"},{"en":"We waited two hours at the border crossing before our passports were stamped.","zh-TW":"我們在邊境過境點等了兩個小時，才蓋上護照印章。"}]', NULL, NULL, 5, 739, NULL),
(740, 'born', '/bɔːrn/', 'adjective', '{"zh-TW":["出生的；天生的"],"en":["brought into life","brought into existence; having a natural ability"]}', NULL, 'born in / born leader; be born / born and raised', '[{"en":"She was born in 1990.","zh-TW":"她1990年出生。"},{"en":"He''s a born leader.","zh-TW":"他是一個天生的領導者。"},{"en":"She was born in 1990.","zh-TW":"她生於1990年。"},{"en":"He''s a born leader.","zh-TW":"他是天生的領導者。"}]', '{"noun":"birth"}', NULL, 1, 740, NULL),
(741, 'borrow', '/ˈbɒrəʊ/', 'verb', '{"zh-TW":["借入"],"en":["to take and use something belonging to someone else with the intention of returning it"]}', '{"root":{"text":"borrow","meaning":"pledge/surety (抵押)"},"logic":"以抵押方式取得，即「借入」。"}', 'borrow money/funds / borrow from', '[{"en":"The company borrowed $5 million to fund expansion.","zh-TW":"公司借入500萬美元資助擴張。"},{"en":"Interest rates affect how much businesses borrow.","zh-TW":"利率影響企業的借款金額。"}]', '{"noun":"borrower"}', NULL, 2, 741, NULL),
(742, 'boss', '/bɒs/', 'noun', '{"zh-TW":["老闆；上司","老闆；指揮"],"en":["a person who is in charge","a person in charge of others","the person in charge; to give orders"]}', NULL, 'the boss / report to the boss; like a boss / boss around; boss sb around', '[{"en":"My boss approved the budget.","zh-TW":"我的老闆批准了預算。"},{"en":"She is a great boss to work for.","zh-TW":"她是一個很好的上司。"},{"en":"My boss gave me a raise.","zh-TW":"我老闆給我加薪了。"},{"en":"Stop bossing me around.","zh-TW":"別再對我指手畫腳了。"},{"en":"My boss approved my vacation request.","zh-TW":"我的老闆批准了我的休假申請。"},{"en":"Stop bossing me around.","zh-TW":"別再對我發號施令。"}]', '{"noun":"boss","adjective":"bossy"}', NULL, 1, 742, NULL),
(743, 'both', '/boʊθ/', 'determiner', '{"zh-TW":["兩者都"],"en":["the two; each of two things","used to refer to two things or people together"]}', NULL, 'both... and / both sides; both...and... / both of', '[{"en":"Both answers are correct.","zh-TW":"兩個答案都正確。"},{"en":"She speaks both English and French.","zh-TW":"她英語和法語都會說。"},{"en":"Both options are acceptable.","zh-TW":"兩個選項都可以接受。"},{"en":"Both of them passed the exam.","zh-TW":"他們兩個都通過了考試。"}]', NULL, NULL, 1, 743, NULL),
(744, 'bother', '/ˈbɒðər/', 'verb', '{"zh-TW":["打擾；煩惱"],"en":["to annoy or trouble someone","to cause worry or annoyance","to make the effort to do something"]}', '{"root":{"text":"bother","meaning":"confuse/annoy (困擾)"},"logic":"指使人感到困擾或不安。"}', 'don''t bother / sorry to bother; don''t bother / sorry to bother you / it bothers me', '[{"en":"Sorry to bother you.","zh-TW":"抱歉打擾你了。"},{"en":"Don''t bother waiting for me.","zh-TW":"不用費心等我了。"},{"en":"Sorry to bother you, but I need help.","zh-TW":"抱歉打擾你，但我需要幫忙。"},{"en":"The noise doesn''t bother me.","zh-TW":"噪音不會困擾我。"}]', '{"noun":"bother","adjective":"bothersome"}', NULL, 2, 744, NULL),
(745, 'bottleneck', '/ˈbɒtəlnɛk/', 'noun', '{"zh-TW":["瓶頸"],"en":["a point of congestion that slows progress"]}', NULL, 'production bottleneck / identify bottlenecks', '[{"en":"Shipping is the main bottleneck.","zh-TW":"運輸是主要瓶頸。"},{"en":"We identified several bottlenecks in the process.","zh-TW":"我們找出了流程中的幾個瓶頸。"}]', '{"noun":"bottleneck"}', NULL, 4, 745, NULL),
(746, 'bottom', '/ˈbɒtəm/', 'noun', '{"zh-TW":["底部；最低處","底部；最低的"],"en":["the lowest part of something","the lowest part; at the lowest position"]}', NULL, 'at the bottom / from top to bottom; at the bottom of / bottom line', '[{"en":"Sign at the bottom of the page.","zh-TW":"在頁面底部簽名。"},{"en":"He started from the bottom.","zh-TW":"他從底層開始做起。"},{"en":"The bottom line is we need more funding.","zh-TW":"重點是我們需要更多資金。"}]', NULL, NULL, 2, 746, NULL),
(747, 'bottom line', '/ˈbɒtəm laɪn/', 'noun', '{"zh-TW":["底線；淨利潤；核心要點"],"en":["a company''s net income; the final or most essential point"]}', NULL, 'improve the bottom line / impact the bottom line / bottom-line results', '[{"en":"The cost cuts significantly improved the company''s bottom line.","zh-TW":"成本削減顯著改善了公司的淨利潤。"},{"en":"The bottom line is that we need to increase revenue by 20%.","zh-TW":"核心要點是我們需要將收入增加20%。"}]', NULL, NULL, 4, 747, NULL),
(748, 'bottom-up', '/ˈbɒtəm ʌp/', 'adjective', '{"zh-TW":["自下而上的"],"en":["proceeding from the most basic units to a larger structure"]}', NULL, 'bottom-up approach / bottom-up design / bottom-up analysis', '[{"en":"A bottom-up approach to budgeting involves input from all levels.","zh-TW":"自下而上的預算方法涉及各層級的意見。"},{"en":"The reform was driven by bottom-up pressure from community organizations.","zh-TW":"改革由社區組織的自下而上壓力推動。"}]', '{"antonym":"top-down"}', NULL, 3, 748, NULL),
(749, 'bounce back', '/baʊns bæk/', 'verb', '{"zh-TW":["反彈；恢復"],"en":["to recover quickly after a setback or decline"]}', NULL, 'bounce back from losses / bounce back quickly', '[{"en":"The company bounced back strongly in Q2 after Q1 losses.","zh-TW":"公司在第一季虧損後，第二季強勁反彈。"},{"en":"Markets bounced back within weeks after the initial shock.","zh-TW":"市場在最初衝擊後的數週內反彈了。"}]', '{"noun":"bounce-back","adjective":"bounced back"}', NULL, 4, 749, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(750, 'boundary', '/ˈbaʊndri/', 'noun', '{"zh-TW":["邊界；界線","邊界；界限"],"en":["a line that marks the limit of an area","a line marking the limits of an area"]}', '{"root":{"text":"bound","meaning":"limit (限制)"},"suffix":{"text":"-ary","meaning":"relating to (有關的)"},"logic":"與限制有關的，即「邊界」。"}', 'cross boundaries / set boundaries; set boundaries / cross a boundary / boundary line', '[{"en":"The project crosses departmental boundaries.","zh-TW":"該專案跨越了部門界線。"},{"en":"It''s important to set professional boundaries.","zh-TW":"設定專業界線很重要。"},{"en":"The river forms the boundary between the two countries.","zh-TW":"這條河構成兩國之間的邊界。"},{"en":"It''s important to set personal boundaries.","zh-TW":"設立個人界限很重要。"}]', '{"adjective":"bounded","verb":"bound"}', NULL, 3, 750, NULL),
(751, 'bounded rationality', '/ˈbaʊndɪd ˌræʃəˈnælɪti/', 'noun', '{"zh-TW":["有限理性"],"en":["the idea that decision-making is limited by available information, cognitive capacity, and time"]}', NULL, 'bounded rationality model / cognitive bounded rationality / bounded rationality in economics', '[{"en":"Herbert Simon''s bounded rationality concept transformed how economists model decision-making.","zh-TW":"赫伯特·賽門的有限理性概念改變了經濟學家對決策建模的方式。"},{"en":"Bounded rationality explains why people use heuristics rather than complex calculations.","zh-TW":"有限理性解釋了為什麼人們使用啟發法而不是複雜計算。"}]', NULL, NULL, 5, 751, NULL),
(752, 'boutique', '/buːˈtiːk/', 'noun', '{"zh-TW":["精品店；小型專賣店"],"en":["a small shop selling fashionable items"]}', '{"root":{"text":"boutique","meaning":"small shop (小店)"},"logic":"源自法語，指販售精品的小型商店。"}', 'boutique hotel / fashion boutique', '[{"en":"She opened a boutique selling handmade jewelry.","zh-TW":"她開了一家賣手工飾品的精品店。"},{"en":"The boutique hotel offers personalized service.","zh-TW":"這家精品旅館提供個人化服務。"}]', NULL, NULL, 3, 752, NULL),
(753, 'bowl', '/boʊl/', 'noun', '{"zh-TW":["碗"],"en":["a round deep dish"]}', NULL, 'bowl of soup / mixing bowl', '[{"en":"Have a bowl of soup.","zh-TW":"喝一碗湯吧。"},{"en":"Put the salad in a large bowl.","zh-TW":"把沙拉放在一個大碗裡。"}]', NULL, NULL, 1, 753, NULL),
(754, 'box', '/bɒks/', 'noun', '{"zh-TW":["箱子；盒子"],"en":["a container with flat sides"]}', NULL, 'cardboard box / think outside the box', '[{"en":"She opened the box carefully.","zh-TW":"她小心地打開了盒子。"},{"en":"We need to think outside the box.","zh-TW":"我們需要跳出框架思考。"}]', NULL, NULL, 1, 754, NULL),
(755, 'boycott', '/ˈbɔɪkɒt/', 'noun', '{"zh-TW":["抵制；聯合抵制"],"en":["a refusal to buy goods or participate in activities as a form of protest"]}', NULL, 'organize a boycott / consumer boycott / call for a boycott', '[{"en":"A consumer boycott of the company''s products hurt its sales significantly.","zh-TW":"消費者對該公司產品的抵制顯著損害了其銷售額。"},{"en":"The boycott was lifted after the company agreed to improve labor practices.","zh-TW":"在公司同意改善勞工做法後，抵制被解除。"}]', '{"verb":"boycott"}', NULL, 3, 755, NULL),
(756, 'brain', '/breɪn/', 'noun', '{"zh-TW":["大腦；腦力","大腦；頭腦"],"en":["the organ of thought","intelligence","the organ inside the head that controls the body"]}', NULL, 'brainstorm / brain drain; brain storm / brain power', '[{"en":"Let''s brainstorm some ideas.","zh-TW":"讓我們腦力激盪一些點子。"},{"en":"Brain drain is a serious issue.","zh-TW":"人才外流是嚴重的問題。"},{"en":"The brain controls all body functions.","zh-TW":"大腦控制所有的身體功能。"},{"en":"Use your brain!","zh-TW":"動動腦筋！"}]', '{"noun":"brain","adjective":"brainy","verb":"brainstorm"}', NULL, 2, 756, NULL),
(757, 'brainstorm', '/ˈbreɪnstɔːrm/', 'verb', '{"zh-TW":["腦力激盪；集思廣益"],"en":["to suggest many ideas quickly in a group"]}', NULL, 'brainstorm ideas / brainstorming session', '[{"en":"The team brainstormed solutions to the supply chain problem.","zh-TW":"團隊就供應鏈問題進行了腦力激盪。"},{"en":"The brainstorming session generated over 30 new ideas.","zh-TW":"腦力激盪會議產生了超過30個新想法。"}]', '{"noun":"brainstorm","noun2":"brainstorming"}', NULL, 4, 757, NULL),
(758, 'brainstorming session', '/ˈbreɪnstɔːmɪŋ ˈsɛʃən/', 'noun', '{"zh-TW":["腦力激盪會議"],"en":["a meeting held to generate creative ideas"]}', NULL, 'hold a brainstorming session / productive brainstorming session', '[{"en":"The team held a brainstorming session to develop new product ideas.","zh-TW":"團隊舉行了腦力激盪會議以開發新產品創意。"},{"en":"A good brainstorming session builds team creativity.","zh-TW":"良好的腦力激盪會議能夠增強團隊創造力。"}]', NULL, NULL, 5, 758, NULL),
(759, 'branch', '/brɑːntʃ/', 'noun', '{"zh-TW":["分公司；分支"],"en":["a division of a larger organization","a local office of a company"]}', '{"root":{"text":"branch","meaning":"arm/limb (樹枝/手臂)"},"logic":"從主體延伸出去的，即「分支」。"}', 'branch office / branch manager / open a branch', '[{"en":"The bank has over 200 branches nationwide.","zh-TW":"該銀行在全國有超過200家分行。"},{"en":"We plan to open a new branch in Taipei.","zh-TW":"我們計劃在台北開設新分公司。"}]', NULL, NULL, 2, 759, 77),
(760, 'brand', '/brænd/', 'noun', '{"zh-TW":["品牌","品牌；商標"],"en":["a type of product made by a particular company"]}', '{"root":{"text":"brand","meaning":"burn/mark (燒/標記)"},"logic":"燒印標記以識別，即「品牌」。"}', 'brand awareness / brand image / brand loyalty; brand name / brand loyalty / brand awareness', '[{"en":"Building a strong brand takes years of effort.","zh-TW":"建立強大的品牌需要多年努力。"},{"en":"The new campaign increased brand awareness by 30%.","zh-TW":"新活動將品牌知名度提高了30%。"},{"en":"This brand is known for its high quality.","zh-TW":"這個品牌以高品質聞名。"},{"en":"They are trying to build brand awareness.","zh-TW":"他們正努力建立品牌知名度。"}]', '{"noun":"branding","verb":"brand","adjective":"branded"}', NULL, 2, 760, NULL),
(761, 'brand ambassador', '/brænd æmˈbæsədər/', 'noun', '{"zh-TW":["品牌大使"],"en":["a person employed to promote and represent a brand publicly"]}', NULL, 'appoint a brand ambassador / brand ambassador deal / become a brand ambassador', '[{"en":"The athlete became a brand ambassador for the sportswear company.","zh-TW":"這位運動員成為了運動服裝公司的品牌大使。"},{"en":"Brand ambassadors help humanize the company''s image.","zh-TW":"品牌大使幫助使公司形象更加人性化。"}]', '{"plural":"brand ambassadors"}', NULL, 5, 761, NULL),
(762, 'brand awareness', '/brænd əˈweənəs/', 'noun', '{"zh-TW":["品牌知名度"],"en":["the extent to which consumers recognize a brand"]}', NULL, 'build brand awareness / increase brand awareness / measure brand awareness', '[{"en":"The campaign significantly increased brand awareness among millennials.","zh-TW":"該活動顯著提高了千禧世代對品牌的認知。"},{"en":"Social media is an effective tool for building brand awareness.","zh-TW":"社群媒體是建立品牌知名度的有效工具。"}]', '{"adjective":"brand-aware"}', NULL, 5, 762, NULL),
(763, 'brand equity', '/brænd ˈekwɪti/', 'noun', '{"zh-TW":["品牌資產；品牌價值"],"en":["the commercial value of a brand beyond its physical assets"]}', NULL, 'build brand equity / measure brand equity / strong brand equity', '[{"en":"Strong brand equity allows companies to charge premium prices.","zh-TW":"強大的品牌資產讓公司能夠收取溢價。"},{"en":"Consistent quality builds brand equity over time.","zh-TW":"持續的品質隨時間建立品牌資產。"}]', NULL, NULL, 4, 763, NULL),
