(2193, 'double-entry bookkeeping', '/ˈdʌbəl ˈentri ˈbʊkkiːpɪŋ/', 'noun', '{"zh-TW":["複式記帳法"],"en":["a system where every transaction is recorded as both a debit and a credit"]}', NULL, 'apply double-entry bookkeeping / double-entry bookkeeping system', '[{"en":"Double-entry bookkeeping ensures the accounting equation always balances.","zh-TW":"複式記帳法確保會計等式始終平衡。"},{"en":"The accounting software automatically applies double-entry bookkeeping.","zh-TW":"會計軟體自動應用複式記帳法。"}]', NULL, NULL, 5, 2193, NULL),
(2194, 'doubt', '/daʊt/', 'noun', '{"zh-TW":["懷疑；疑慮"],"en":["a feeling of uncertainty"]}', NULL, 'no doubt / beyond doubt', '[{"en":"There is no doubt about his ability.","zh-TW":"他的能力毫無疑問。"},{"en":"I doubt that will work.","zh-TW":"我懷疑那行不通。"}]', '{"noun":"doubt","verb":"doubt","adjective":"doubtful","adverb":"doubtfully"}', NULL, 2, 2194, NULL),
(2195, 'dough', '/''dəʊ/', 'noun', '{"zh-TW":["麵團；麵糰"],"en":["a thick, malleable mixture of flour and liquid, used for baking bread, pastries, and pasta"]}', NULL, 'knead the dough / let the dough rise / roll out the dough', '[{"en":"She kneaded the bread dough by hand for ten minutes before letting it rise.","zh-TW":"她用手揉捏麵團十分鐘，然後讓它發酵。"},{"en":"The pizza dough needs to rest for at least an hour before shaping.","zh-TW":"披薩麵團在塑形之前需要靜置至少一個小時。"}]', NULL, NULL, 2, 2195, NULL),
(2196, 'down payment', '/daʊn ˈpeɪmənt/', 'noun', '{"zh-TW":["頭期款；首付款"],"en":["an initial payment made when buying something on credit"]}', NULL, 'make a down payment / down payment requirement', '[{"en":"A 20% down payment is typically required for a mortgage.","zh-TW":"購買房屋通常需要20%的頭期款。"},{"en":"She saved for years to accumulate the down payment.","zh-TW":"她存了多年才積累到頭期款。"}]', NULL, NULL, 4, 2196, NULL),
(2197, 'downgrade', '/ˈdaʊnɡreɪd/', 'verb', '{"zh-TW":["降級；下調評級"],"en":["to reduce the grade, status, or rating of something"]}', NULL, 'downgrade a credit rating / stock downgraded', '[{"en":"The credit agency downgraded the company''s bond rating to junk.","zh-TW":"信用評級機構將公司的債券評級下調至垃圾級。"},{"en":"The analyst downgraded the stock from buy to hold.","zh-TW":"分析師將股票從買入下調至持有。"}]', '{"noun":"downgrade","adjective":"downgraded"}', NULL, 3, 2197, NULL),
(2198, 'download', '/ˈdaʊnloʊd/', 'verb', '{"zh-TW":["下載"],"en":["to copy data from the internet to a computer"]}', NULL, 'download a file / free download', '[{"en":"Download the app for free.","zh-TW":"免費下載這個應用程式。"},{"en":"The download is almost complete.","zh-TW":"下載快要完成了。"}]', '{"noun":"download"}', NULL, 3, 2198, NULL),
(2199, 'downsize', '/ˈdaʊnsaɪz/', 'verb', '{"zh-TW":["縮編；裁員"],"en":["to reduce the size or number of employees in an organization"]}', NULL, 'downsize the workforce / company downsizing', '[{"en":"The firm downsized its operations after the market contracted.","zh-TW":"市場萎縮後，公司縮減了其運營規模。"},{"en":"Thousands of employees were laid off during the downsizing.","zh-TW":"在縮編過程中，數千名員工被裁員。"}]', '{"noun":"downsizing","adjective":"downsized"}', NULL, 3, 2199, 674);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2200, 'downsizing', '/ˈdaʊnsaɪzɪŋ/', 'noun', '{"zh-TW":["裁員；縮減規模"],"en":["reducing the size of a workforce or organization"]}', NULL, 'corporate downsizing / downsizing plan', '[{"en":"Downsizing was necessary to cut operating costs.","zh-TW":"裁員是削減營運成本的必要措施。"},{"en":"The downsizing affected nearly every department.","zh-TW":"裁員幾乎影響到每個部門。"}]', '{"verb":"downsize","noun":"downsizer"}', NULL, 4, 2200, NULL),
(2201, 'downstream', '/ˈdaʊnstriːm/', 'adjective', '{"zh-TW":["下游的"],"en":["relating to the later stages of production or supply chain activities"]}', NULL, 'downstream distribution / downstream partner / downstream operations', '[{"en":"Downstream operations include packaging, distribution, and retail.","zh-TW":"下游運營包括包裝、分銷和零售。"},{"en":"Disruptions in downstream channels delay goods reaching end consumers.","zh-TW":"下游渠道的中斷延遲了商品到達最終消費者的時間。"}]', '{"opposite":"upstream"}', NULL, 4, 2201, 863),
(2202, 'downtime', '/ˈdaʊntaɪm/', 'noun', '{"zh-TW":["停機時間；系統停運"],"en":["a period when a system is not operational"]}', NULL, 'minimize downtime / planned downtime / unexpected downtime / downtime cost', '[{"en":"The system downtime lasted three hours due to a hardware failure.","zh-TW":"由於硬體故障，系統停機持續了三小時。"},{"en":"Unplanned downtime can cost millions in lost revenue.","zh-TW":"計劃外停機可能導致數百萬元的收入損失。"}]', '{"antonym":"uptime"}', NULL, 3, 2202, NULL),
(2203, 'downturn', '/ˈdaʊntɜːrn/', 'noun', '{"zh-TW":["低迷；下滑"],"en":["a decline in economic or business activity"]}', NULL, 'economic downturn / market downturn', '[{"en":"The economic downturn affected all sectors.","zh-TW":"經濟低迷影響了所有行業。"},{"en":"We survived the downturn by cutting costs.","zh-TW":"我們靠削減成本度過了低迷期。"}]', '{"noun":"downturn"}', NULL, 3, 2203, 778),
(2204, 'dozen', 'ˈdʌzən', 'noun', '{"zh-TW":["一打；十二個","很多"],"en":["a group of twelve","a large number"]}', NULL, 'a dozen/dozens of', '[{"en":"We ordered a dozen new computers.","zh-TW":"我們訂購了十二台新電腦。"}]', NULL, NULL, 2, 2204, NULL),
(2205, 'draft', '/dræft/', 'noun / verb', '{"zh-TW":["草稿；起草","草稿；草案"],"en":["a preliminary version; to write a first version","a preliminary version of a document"]}', '{"root":{"text":"draft","meaning":"draw (拉/畫)"},"logic":"源自 draw 的變體，指拉出的初步版本。"}', 'first/final draft; first draft / rough draft / draft proposal', '[{"en":"Please review the first draft of the proposal.","zh-TW":"請審閱提案的初稿。"},{"en":"He drafted the contract in one day.","zh-TW":"他一天內起草了合約。"},{"en":"I finished the first draft of my essay.","zh-TW":"我完成了論文的初稿。"},{"en":"The committee reviewed the draft proposal.","zh-TW":"委員會審查了提案草案。"}]', '{"noun":"draft","verb":"draft"}', NULL, 2, 2205, 340),
(2206, 'draft beer', '/drɑːft bɪər/', 'noun', '{"zh-TW":["生啤酒；桶裝啤酒"],"en":["beer served from a keg or barrel"]}', NULL, 'order draft beer / cold draft beer', '[{"en":"They have ten local draft beers on tap.","zh-TW":"他們有十種本地生啤酒可供選擇。"},{"en":"Draft beer is usually cheaper than bottled beer.","zh-TW":"生啤酒通常比瓶裝啤酒便宜。"}]', NULL, NULL, 4, 2206, NULL),
(2207, 'draft budget', '/drɑːft ˈbʌdʒɪt/', 'noun', '{"zh-TW":["預算草案"],"en":["an initial version of a budget submitted for review and approval"]}', NULL, 'prepare a draft budget / review the draft budget', '[{"en":"The draft budget was presented to the finance committee in November.","zh-TW":"預算草案在十一月提交給了財務委員會。"},{"en":"Several revisions were made before the draft budget was approved.","zh-TW":"預算草案在批准前進行了幾次修訂。"}]', NULL, NULL, 4, 2207, NULL),
(2208, 'draft contract', '/drɑːft ˈkɒntrækt/', 'noun', '{"zh-TW":["合約草案"],"en":["an initial version of a contract not yet signed or finalized"]}', NULL, 'review the draft contract / approve the draft contract', '[{"en":"The legal team reviewed the draft contract for any unfavorable clauses.","zh-TW":"法律團隊審查了合約草案中任何不利的條款。"},{"en":"Please sign and return the draft contract after review.","zh-TW":"請審閱後簽署並歸還合約草案。"}]', '{"verb":"draft","adjective":"drafted"}', NULL, 5, 2208, NULL),
(2209, 'drafting', '/ˈdrɑːftɪŋ/', 'noun', '{"zh-TW":["起草；草擬"],"en":["the process of writing an initial version of a document"]}', NULL, 'contract drafting / drafting a proposal / drafting process', '[{"en":"Contract drafting requires precision to avoid ambiguities.","zh-TW":"合約起草需要精確以避免歧義。"},{"en":"The drafting process for the terms of service took three weeks.","zh-TW":"服務條款的草擬過程耗時三週。"}]', '{"verb":"draft","noun":"draft"}', NULL, 3, 2209, NULL),
(2210, 'drain', '/dreɪn/', 'verb / noun', '{"zh-TW":["排水；耗盡"],"en":["to remove liquid; to use up resources","to remove liquid","to use up resources gradually"]}', '{"root":{"text":"drain","meaning":"dry (乾)"},"logic":"源自古英語 dreahnian（變乾），使水排去。"}', 'drain resources/energy; drain resources / brain drain / drain the water', '[{"en":"The project drained our budget.","zh-TW":"這個項目耗盡了我們的預算。"},{"en":"Brain drain is a serious issue for developing countries.","zh-TW":"人才外流對開發中國家是嚴重問題。"},{"en":"Please drain the water from the pool.","zh-TW":"請把游泳池的水排掉。"},{"en":"The long commute drains my energy.","zh-TW":"長途通勤耗盡我的精力。"}]', '{"noun":"drain/drainage","verb":"drain","noun2":"drainage"}', NULL, 2, 2210, NULL),
(2211, 'drama', '/ˈdrɑːmə/', 'noun', '{"zh-TW":["戲劇；戲劇性事件"],"en":["a play or performance for theater or TV"]}', NULL, 'drama series / drama queen', '[{"en":"She studied drama at university.","zh-TW":"她在大學學戲劇。"},{"en":"There''s always so much drama at work.","zh-TW":"工作中總是有那麼多戲劇性的事。"}]', '{"adjective":"dramatic","adverb":"dramatically"}', NULL, 2, 2211, NULL),
(2212, 'dramatic', '/drəˈmætɪk/', 'adjective', '{"zh-TW":["戲劇性的；顯著的","戲劇性的；巨大的"],"en":["sudden and striking; relating to drama","sudden and striking","relating to drama"]}', '{"root":{"text":"drama","meaning":"action/play (行動/戲)"},"suffix":{"text":"-tic","meaning":"relating to (相關的)"},"logic":"與戲劇性行動相關的。"}', 'dramatic increase/change; dramatic change / dramatic increase / dramatic effect', '[{"en":"There was a dramatic increase in profits.","zh-TW":"利潤有了顯著的增長。"},{"en":"The market saw dramatic changes.","zh-TW":"市場出現了劇烈的變化。"},{"en":"There has been a dramatic increase in sales.","zh-TW":"銷售額有了大幅增加。"},{"en":"The sunset was dramatic and beautiful.","zh-TW":"日落壯觀而美麗。"}]', '{"noun":"drama","adjective":"dramatic","adverb":"dramatically"}', NULL, 3, 2212, NULL),
(2213, 'draw', 'drɔː', 'verb', '{"zh-TW":["【主要意義-動詞】畫；拉；拔出","【次要意義-名詞】平局（比賽）","【次要意義-動詞】引起（注意/興趣）","【次要意義-動詞】（從帳戶）提取；得出（結論）"],"en":["[primary] to make a picture; to pull something","[secondary - noun] a tied result in a game or contest","[secondary - verb] to attract or pull in attention or interest","[secondary - verb] to withdraw money; to reach a conclusion"]}', NULL, 'draw a conclusion / draw attention to / draw on experience / draw up a contract', '[{"en":"The new product drew considerable attention at the trade fair.","zh-TW":"新產品在貿易展覽會上引起了相當大的關注。"},{"en":"The report draws on data collected over five years.","zh-TW":"報告借鑒了五年來收集的數據。"},{"en":"We can draw the conclusion that customer satisfaction has improved.","zh-TW":"我們可以得出結論，客戶滿意度已有所提高。"}]', '{"noun":"drawback, withdrawal"}', 'draw 有多個次要意義：draw attention（引起注意）、draw on（借鑒/依靠）、draw a conclusion（得出結論）、draw up a contract（起草合約），均為 TOEIC 高頻商業用語。', 1, 2213, NULL),
(2214, 'draw-down', '/ˈdrɔː daʊn/', 'noun', '{"zh-TW":["提款；資金提取"],"en":["the act of accessing funds from an available credit facility or loan"]}', NULL, 'draw-down schedule / draw-down on the credit line', '[{"en":"The company made a draw-down of $2 million from its credit facility.","zh-TW":"公司從其信貸額度提取了200萬元。"},{"en":"Multiple draw-downs are allowed under the revolving credit agreement.","zh-TW":"循環信貸協議允許多次提款。"}]', '{"verb":"draw down"}', NULL, 3, 2214, NULL),
(2215, 'drawback', '/ˈdrɔːbæk/', 'noun', '{"zh-TW":["缺點；不利之處"],"en":["a disadvantage or negative aspect of something"]}', NULL, 'main drawback / overcome the drawback', '[{"en":"The main drawback of the system is its high implementation cost.","zh-TW":"該系統的主要缺點是其高昂的實施成本。"},{"en":"The proposal was accepted despite its drawbacks.","zh-TW":"儘管有缺點，提案還是被接受了。"}]', NULL, NULL, 3, 2215, NULL),
(2216, 'drawdown', '/ˈdrɔːdaʊn/', 'noun', '{"zh-TW":["提款；資金提取"],"en":["the withdrawal of funds from a credit facility or investment account"]}', NULL, 'request a drawdown / drawdown schedule', '[{"en":"The company made a drawdown from its credit facility to fund operations.","zh-TW":"公司從信貸額度中提取資金以資助運營。"},{"en":"Each drawdown from the revolving credit was subject to lender approval.","zh-TW":"每次從循環信用中提取資金都需要貸款方批准。"}]', '{"verb":"draw down"}', NULL, 3, 2216, NULL),
(2217, 'drawdown facility', '/ˈdrɔːdaʊn fəˈsɪlɪti/', 'noun', '{"zh-TW":["提款設施；借款額度"],"en":["a credit arrangement allowing funds to be drawn as needed up to a limit"]}', NULL, 'access a drawdown facility / drawdown facility terms', '[{"en":"The project used a drawdown facility to manage construction phase spending.","zh-TW":"項目使用提款設施管理建設階段的支出。"},{"en":"A drawdown facility provides flexible access to funds without interest on unused portions.","zh-TW":"提款設施提供靈活的資金使用，未使用部分不計利息。"}]', NULL, NULL, 5, 2217, NULL),
(2218, 'drayage', '/''dreɪɪdʒ/', 'noun', '{"zh-TW":["短途運輸費；拖車費"],"en":["the transportation of freight over a short distance, especially from a port to a nearby warehouse"]}', NULL, 'arrange drayage / drayage cost / drayage service', '[{"en":"Drayage services transported containers from the port to the distribution center.","zh-TW":"拖車服務將貨櫃從港口運輸到配送中心。"},{"en":"Efficient drayage reduces the time cargo sits waiting at congested ports.","zh-TW":"高效的短途運輸減少了貨物在擁擠港口等待的時間。"}]', NULL, NULL, 3, 2218, NULL),
(2219, 'dream', '/driːm/', 'noun', '{"zh-TW":["夢想；夢"],"en":["a hope or ambition","images during sleep"]}', NULL, 'dream job / dream come true', '[{"en":"This is my dream job.","zh-TW":"這是我的夢想工作。"},{"en":"Starting my own business was a dream come true.","zh-TW":"創業是我夢想成真。"}]', '{"noun":"dream","verb":"dream","adjective":"dreamy","noun2":"dreamer"}', NULL, 2, 2219, NULL),
(2220, 'dressing', '/ˈdrɛsɪŋ/', 'noun', '{"zh-TW":["醬汁；調味醬"],"en":["a sauce or mixture used to flavor salads"]}', NULL, 'salad dressing / house dressing', '[{"en":"What dressing would you like on your salad?","zh-TW":"您的沙拉要什麼醬汁？"},{"en":"The house dressing is made with lemon and olive oil.","zh-TW":"本店醬汁是用檸檬和橄欖油製成的。"}]', NULL, NULL, 3, 2220, NULL),
(2221, 'dribble', '/''drɪbəl/', 'verb', '{"zh-TW":["帶球運球；運球"],"en":["in sports, to run while controlling a ball with small touches of the feet or hands"]}', NULL, 'dribble past / dribble skillfully / dribble down the court', '[{"en":"The basketball player dribbled past three defenders before shooting.","zh-TW":"這名籃球運動員運球越過三名防守球員後投籃。"},{"en":"She dribbled the soccer ball skillfully through the crowded midfield.","zh-TW":"她靈巧地運著足球穿越擁擠的中場。"}]', '{"noun":"dribble"}', NULL, 3, 2221, NULL),
(2222, 'drink', '/drɪŋk/', 'verb', '{"zh-TW":["喝；飲料"],"en":["to take liquid into the mouth","a liquid for drinking"]}', NULL, 'soft drink / drink water', '[{"en":"Would you like something to drink?","zh-TW":"你想喝點什麼嗎？"},{"en":"Soft drinks are available in the lounge.","zh-TW":"休息室有提供軟性飲料。"}]', '{"verb":"drink","noun":"drink","noun2":"drinker"}', NULL, 2, 2222, NULL),
(2223, 'drip campaign', '/drɪp kæmˈpeɪn/', 'noun', '{"zh-TW":["滴灌行銷活動；自動化郵件序列"],"en":["a series of automated emails sent over time to nurture leads"]}', NULL, 'run a drip campaign / drip campaign sequence / design a drip campaign', '[{"en":"The drip campaign guided prospects through the 30-day trial period.","zh-TW":"滴灌行銷活動引導潛在客戶完成30天試用期。"},{"en":"A well-designed drip campaign increases conversion rates.","zh-TW":"精心設計的滴灌行銷活動提高了轉換率。"}]', NULL, NULL, 5, 2223, NULL),
(2224, 'drive', '/draɪv/', 'verb', '{"zh-TW":["開車；驅動"],"en":["to operate a vehicle","to cause something to happen"]}', NULL, 'drive growth / drive to work', '[{"en":"Innovation drives our growth.","zh-TW":"創新驅動我們的成長。"},{"en":"She drives to work every day.","zh-TW":"她每天開車上班。"}]', '{"verb":"drive","noun":"driver","noun2":"drive"}', NULL, 2, 2224, NULL),
(2225, 'drop', '/drɑːp/', 'verb / noun', '{"zh-TW":["下降；放棄"],"en":["to fall or decrease; to stop doing"]}', NULL, 'drop in price/sales', '[{"en":"Sales dropped by 5% last month.","zh-TW":"上個月銷售額下降了5%。"},{"en":"They decided to drop the project.","zh-TW":"他們決定放棄這個項目。"}]', '{"noun":"drop","verb":"drop"}', NULL, 1, 2225, NULL),
(2226, 'drop shipment', '/drɒp ˈʃɪpmənt/', 'noun', '{"zh-TW":["直接發貨；代客發貨"],"en":["shipping goods directly from manufacturer to customer without going through the retailer"]}', NULL, 'use drop shipment / drop shipment model', '[{"en":"The online store uses a drop shipment model to avoid holding stock.","zh-TW":"網路商店使用代客發貨模式以避免持有庫存。"},{"en":"Drop shipment reduces warehousing costs for the retailer.","zh-TW":"代客發貨降低了零售商的倉儲成本。"}]', '{"verb":"drop ship"}', NULL, 5, 2226, NULL),
(2227, 'drought', '/draʊt/', 'noun', '{"zh-TW":["乾旱"],"en":["a prolonged period of abnormally low rainfall"]}', '{"root":{"text":"drought","meaning":"dryness (乾燥)"},"logic":"源自古英語 drugaþ（乾燥），指長期缺水。"}', 'severe drought / drought-resistant', '[{"en":"The drought destroyed most of the crops.","zh-TW":"乾旱摧毀了大部分的農作物。"},{"en":"The region is experiencing its worst drought in decades.","zh-TW":"該地區正經歷數十年來最嚴重的乾旱。"}]', NULL, NULL, 3, 2227, NULL),
(2228, 'dry', '/draɪ/', 'adjective', '{"zh-TW":["乾的；乾燥的"],"en":["not wet; without water"]}', NULL, 'dry season / dry cleaning', '[{"en":"The dry season affects our water supply.","zh-TW":"旱季影響我們的供水。"},{"en":"This suit needs dry cleaning.","zh-TW":"這套西裝需要乾洗。"}]', '{"adjective":"dry","verb":"dry","noun":"dryer","noun2":"drought"}', NULL, 1, 2228, NULL),
(2229, 'dry cleaning', '/draɪ ˈkliːnɪŋ/', 'noun', '{"zh-TW":["乾洗"],"en":["a cleaning process using solvents instead of water"]}', NULL, 'dry cleaning service / send to dry cleaning', '[{"en":"The hotel offers a same-day dry cleaning service.","zh-TW":"飯店提供當天乾洗服務。"},{"en":"Please leave your items at the front desk for dry cleaning.","zh-TW":"請將衣物留在前台進行乾洗。"}]', NULL, NULL, 4, 2229, NULL),
(2230, 'dry run', '/draɪ rʌn/', 'noun', '{"zh-TW":["試演；演習；預演"],"en":["a rehearsal or simulation of a process to identify problems before the real event"]}', NULL, 'conduct a dry run / dry run of the launch', '[{"en":"The team conducted a dry run of the system migration over the weekend.","zh-TW":"團隊在週末進行了系統遷移的演習。"},{"en":"A dry run of the product launch revealed several communication gaps.","zh-TW":"產品發布的預演揭示了幾個溝通空白。"}]', NULL, NULL, 3, 2230, NULL),
(2231, 'due', '/djuː/', 'adjective', '{"zh-TW":["到期的；應付的"],"en":["expected at a certain time; owed"]}', NULL, 'due date/due to', '[{"en":"The payment is due on the 15th.","zh-TW":"付款到期日是15號。"},{"en":"The delay was due to bad weather.","zh-TW":"延誤是由於惡劣天氣。"}]', '{"adjective":"due"}', NULL, 1, 2231, 341),
(2232, 'due date', '/djuː deɪt/', 'noun', '{"zh-TW":["到期日；截止日"],"en":["the date by which a payment or task must be completed"]}', NULL, 'payment due date / invoice due date / extend the due date', '[{"en":"The invoice has a due date of 30 days from the date of issue.","zh-TW":"發票的到期日為開票日起30天。"},{"en":"Missing the due date may result in late payment penalties.","zh-TW":"錯過到期日可能導致逾期付款罰款。"}]', NULL, NULL, 3, 2232, NULL),
(2233, 'due diligence', '/djuː ˈdɪlɪdʒəns/', 'noun', '{"zh-TW":["盡職調查"],"en":["a thorough investigation before a business transaction"]}', NULL, 'conduct due diligence / due diligence process / due diligence report', '[{"en":"Buyers must conduct due diligence before finalizing the deal.","zh-TW":"買家在完成交易前必須進行盡職調查。"},{"en":"The due diligence process uncovered hidden liabilities.","zh-TW":"盡職調查過程發現了隱藏的負債。"}]', '{"adjective":"due-diligent"}', NULL, 5, 2233, NULL),
(2234, 'due diligence checklist', '/djuː ˈdɪlɪdʒəns ˈtʃeklɪst/', 'noun', '{"zh-TW":["盡職調查清單"],"en":["a structured list of items to investigate during a due diligence process"]}', NULL, 'use a due diligence checklist / complete the due diligence checklist', '[{"en":"The due diligence checklist covered legal, financial, and operational areas.","zh-TW":"盡職調查清單涵蓋了法律、財務和運營領域。"},{"en":"A comprehensive checklist ensures no critical area is overlooked.","zh-TW":"全面的清單確保沒有關鍵領域被忽視。"}]', NULL, NULL, 5, 2234, NULL),
(2235, 'due diligence report', '/djuː ˈdɪlɪdʒəns rɪˈpɔːrt/', 'noun', '{"zh-TW":["盡職調查報告"],"en":["a detailed report summarizing the findings of a due diligence investigation"]}', NULL, 'prepare a due diligence report / review the due diligence report', '[{"en":"The due diligence report identified three significant risk areas.","zh-TW":"盡職調查報告識別了三個重要風險領域。"},{"en":"Investors rely on the due diligence report to inform acquisition decisions.","zh-TW":"投資者依賴盡職調查報告做出收購決策。"}]', NULL, NULL, 5, 2235, NULL),
(2236, 'due process', '/djuː ˈprɒses/', 'noun', '{"zh-TW":["正當程序"],"en":["fair legal treatment in accordance with established rules and principles"]}', NULL, 'follow due process / right to due process / ensure due process', '[{"en":"All employees have the right to due process in disciplinary matters.","zh-TW":"所有員工在紀律事項中均享有正當程序的權利。"},{"en":"The court ruled that due process had not been followed.","zh-TW":"法院裁定未遵循正當程序。"}]', NULL, NULL, 4, 2236, NULL),
(2237, 'duly', '/ˈdjuːli/', 'adverb', '{"zh-TW":["正式地；如期地"],"en":["in accordance with what is required; at the proper time"]}', NULL, 'duly signed / duly authorized / duly noted', '[{"en":"The contract was duly signed by both parties.","zh-TW":"合約由雙方正式簽署。"},{"en":"All submissions must be duly completed before the deadline.","zh-TW":"所有提交文件必須在截止日期前正式完成。"}]', '{"adjective":"due"}', NULL, 1, 2237, NULL),
(2238, 'duopoly', '/djuːˈɒpəli/', 'noun', '{"zh-TW":["雙頭壟斷"],"en":["a market situation in which only two companies dominate"]}', NULL, 'market duopoly / commercial duopoly / effective duopoly', '[{"en":"The smartphone market is often described as a duopoly dominated by Apple and Samsung.","zh-TW":"智能手機市場通常被描述為由蘋果和三星主導的雙頭壟斷。"},{"en":"A duopoly can reduce consumer choice as effectively as a monopoly.","zh-TW":"雙頭壟斷可以像壟斷一樣有效地減少消費者選擇。"}]', NULL, NULL, 3, 2238, NULL),
(2239, 'duplicate', '/ˈdjuːplɪkeɪt/', 'verb / noun', '{"zh-TW":["複製；副本"],"en":["to make an exact copy"]}', NULL, 'avoid duplication', '[{"en":"Please duplicate this report for all managers.","zh-TW":"請為所有經理複製這份報告。"},{"en":"We need to eliminate duplicate records.","zh-TW":"我們需要消除重複的記錄。"}]', '{"noun":"duplicate/duplication","verb":"duplicate"}', NULL, 3, 2239, 675),
(2240, 'durable goods', '/ˈdjʊərəbəl ɡʊdz/', 'noun', '{"zh-TW":["耐久財；耐用品"],"en":["products expected to last three or more years, such as appliances and vehicles"]}', NULL, 'orders for durable goods / durable goods market / decline in durable goods', '[{"en":"Orders for durable goods declined as consumer confidence fell.","zh-TW":"隨著消費者信心下降，耐久財訂單也有所減少。"},{"en":"Investment in durable goods is one measure of economic health and business confidence.","zh-TW":"耐久財投資是衡量經濟健康和商業信心的指標之一。"}]', NULL, NULL, 5, 2240, NULL),
(2241, 'duration', '/djuˈreɪʃən/', 'noun', '{"zh-TW":["持續時間"],"en":["the time during which something continues","the length of time something continues"]}', '{"root":{"text":"dur","meaning":"last/hard (持久)"},"suffix":{"text":"-ation","meaning":"state (狀態)"},"logic":"持續的狀態，即「持續時間」。"}', 'for the duration of; for the duration of / short duration', '[{"en":"The contract is valid for the duration of the project.","zh-TW":"合約在項目期間有效。"},{"en":"What is the duration of the training?","zh-TW":"培訓的持續時間是多長？"},{"en":"The flight duration is approximately 12 hours.","zh-TW":"飛行時間約12小時。"},{"en":"For the duration of the event, parking is free.","zh-TW":"活動期間停車免費。"}]', '{"noun":"duration","adjective":"durable","verb":"endure"}', NULL, 3, 2241, 108),
(2242, 'duty', '/ˈdjuːti/', 'noun', '{"zh-TW":["職責；關稅"],"en":["a moral or legal obligation; a tax on imports"]}', NULL, 'on/off duty', '[{"en":"It is your duty to report any safety issues.","zh-TW":"報告任何安全問題是你的職責。"},{"en":"Import duties have been raised.","zh-TW":"進口關稅已提高。"}]', '{"noun":"duty","adjective":"dutiful"}', NULL, 1, 2242, NULL),
(2243, 'duty of care', '/ˈdjuːti əv keər/', 'noun', '{"zh-TW":["注意義務；謹慎義務"],"en":["a legal obligation to take reasonable care to avoid causing harm to others"]}', NULL, 'fulfill duty of care / breach of duty of care', '[{"en":"Employers have a duty of care to maintain a safe working environment.","zh-TW":"雇主有注意義務維持安全的工作環境。"},{"en":"A breach of duty of care can result in legal liability.","zh-TW":"違反注意義務可能導致法律責任。"}]', NULL, NULL, 4, 2243, NULL),
(2244, 'duty roster', '/''djuːti ˌrɒstər/', 'noun', '{"zh-TW":["值班表；輪班表"],"en":["a list showing when each person in a group is to perform a particular duty"]}', NULL, 'check the duty roster / update the duty roster / post the duty roster', '[{"en":"The duty roster was posted each Monday for the following week.","zh-TW":"值班表每週一公布，適用於下一週。"},{"en":"She checked the duty roster to see when she was scheduled to work the weekend shift.","zh-TW":"她查看了值班表，確認她被安排在週末班工作。"}]', NULL, NULL, 4, 2244, NULL),
(2245, 'duty-free', '/ˈdjuːtiˌfriː/', 'adjective', '{"zh-TW":["免稅的"],"en":["not taxed, especially goods sold at airports"]}', NULL, 'duty-free shop / duty-free allowance', '[{"en":"Passengers can buy duty-free goods before boarding.","zh-TW":"乘客可以在登機前購買免稅商品。"},{"en":"The duty-free allowance is one liter of alcohol.","zh-TW":"免稅限額是一升酒精。"}]', NULL, NULL, 3, 2245, NULL),
(2246, 'duty-free shop', '/''djuːti friː ʃɒp/', 'noun', '{"zh-TW":["免稅店"],"en":["a store in an airport or on a ship where goods can be bought without paying customs duties"]}', NULL, 'browse the duty-free shop / duty-free shop allowance / luxury goods at duty-free', '[{"en":"She bought perfume and chocolates at the duty-free shop before boarding.","zh-TW":"她在登機前在免稅店買了香水和巧克力。"},{"en":"Duty-free shops offer international brands at reduced prices for travelers.","zh-TW":"免稅店為旅行者提供以優惠價格購買國際品牌商品的機會。"}]', NULL, NULL, 5, 2246, NULL),
(2247, 'dwell', '/dwel/', 'verb', '{"zh-TW":["居住；老是想著"],"en":["to live in a place","to think about something at length"]}', '{"root":{"text":"dwell","meaning":"lead astray/delay (耽擱)"},"logic":"源自古英語 dwellan（耽擱），引申為停留、居住。"}', 'dwell on / dwell in / dwelling place', '[{"en":"Don''t dwell on past mistakes.","zh-TW":"不要老想著過去的錯誤。"},{"en":"Many species dwell in the rainforest.","zh-TW":"許多物種棲息在雨林中。"}]', '{"noun":"dwelling","noun2":"dweller"}', NULL, 2, 2247, NULL),
(2248, 'dynamic', '/daɪˈnæmɪk/', 'adjective', '{"zh-TW":["動態的；有活力的","動態的；充滿活力的"],"en":["characterized by constant change and activity","characterized by constant change or activity"]}', '{"root":{"text":"dynam","meaning":"power (力量)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與力量和活動相關的，即「動態的」。"}', 'dynamic environment/market; dynamic environment / dynamic personality', '[{"en":"The tech industry is highly dynamic.","zh-TW":"科技產業高度動態。"},{"en":"She is a dynamic leader.","zh-TW":"她是一位有活力的領導者。"},{"en":"The business operates in a dynamic market.","zh-TW":"這家企業在活躍的市場中運營。"},{"en":"She has a very dynamic personality.","zh-TW":"她有非常有活力的個性。"}]', '{"noun":"dynamics","adjective":"dynamic","adverb":"dynamically"}', NULL, 3, 2248, 865),
(2249, 'dynamic pricing', '/daɪˈnæmɪk ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["動態定價"],"en":["adjusting prices in real-time based on supply, demand, or other factors"]}', NULL, 'implement dynamic pricing / dynamic pricing model / dynamic pricing algorithm', '[{"en":"Airlines use dynamic pricing to maximize revenue per seat.","zh-TW":"航空公司使用動態定價來最大化每個座位的收入。"},{"en":"Dynamic pricing can frustrate customers if changes are too frequent.","zh-TW":"如果變化過於頻繁，動態定價可能會讓客戶感到沮喪。"}]', NULL, NULL, 5, 2249, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2250, 'e-commerce', '/ˈiːkɒmɜːrs/', 'noun', '{"zh-TW":["電子商務"],"en":["buying and selling goods and services over the internet"]}', NULL, 'e-commerce platform / B2C e-commerce / e-commerce growth', '[{"en":"E-commerce sales surged during the pandemic.","zh-TW":"疫情期間電子商務銷售額激增。"},{"en":"The brand expanded into e-commerce to reach new customers.","zh-TW":"品牌拓展至電子商務以觸及新客戶。"}]', '{"adjective":"e-commerce"}', NULL, 4, 2250, NULL),
(2251, 'e-commerce platform', '/ˈiːkɒmɜːrs ˈplætfɔːrm/', 'noun', '{"zh-TW":["電子商務平台"],"en":["a digital marketplace facilitating online buying and selling"]}', NULL, 'launch an e-commerce platform / e-commerce platform features', '[{"en":"The retailer launched an e-commerce platform to reach global customers.","zh-TW":"零售商推出了電子商務平台以觸及全球客戶。"},{"en":"An integrated e-commerce platform simplifies order and inventory management.","zh-TW":"整合的電子商務平台簡化了訂單和庫存管理。"}]', NULL, NULL, 5, 2251, NULL),
(2252, 'e-learning', '/ˈiː ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["電子學習；線上學習"],"en":["learning conducted via electronic means, especially online"]}', NULL, 'e-learning platform / e-learning course', '[{"en":"E-learning allows students to study from anywhere.","zh-TW":"電子學習允許學生在任何地方學習。"},{"en":"The company launched an e-learning program for employee development.","zh-TW":"公司推出了員工發展的電子學習計劃。"}]', NULL, NULL, 4, 2252, NULL),
(2253, 'e-learning platform', '/''iː ˌlɜːrnɪŋ ˌplætfɔːrm/', 'noun', '{"zh-TW":["電子學習平台；線上學習平台"],"en":["a digital system that provides educational content and learning tools online"]}', NULL, 'use an e-learning platform / e-learning platform features / popular e-learning platform', '[{"en":"She used an e-learning platform to complete a professional certification from home.","zh-TW":"她使用電子學習平台在家完成了一項專業認證。"},{"en":"E-learning platforms allow learners to study at their own pace and schedule.","zh-TW":"電子學習平台讓學習者可以按自己的節奏和時間表學習。"}]', NULL, NULL, 5, 2253, NULL),
(2254, 'e-waste', '/ˈiː weɪst/', 'noun', '{"zh-TW":["電子廢棄物；電廢"],"en":["discarded electronic devices such as computers and phones"]}', NULL, 'recycle e-waste / e-waste disposal / e-waste management', '[{"en":"Proper e-waste recycling recovers valuable metals and prevents pollution.","zh-TW":"妥善的電子廢棄物回收可回收貴重金屬並防止污染。"},{"en":"Developing countries often receive e-waste from wealthier nations.","zh-TW":"發展中國家通常接收來自富裕國家的電子廢棄物。"}]', NULL, NULL, 3, 2254, NULL),
(2255, 'eager', '/ˈiːɡər/', 'adjective', '{"zh-TW":["渴望的；熱切的"],"en":["strongly wanting to do or have something"]}', '{"root":{"text":"eager","meaning":"sharp/keen (尖銳/敏銳)"},"logic":"源自拉丁語 acer（尖銳的），指熱切渴望的。"}', 'eager to learn / eager for', '[{"en":"Students were eager to start the project.","zh-TW":"學生們渴望開始這個專案。"},{"en":"She is eager for new experiences.","zh-TW":"她熱切期望新體驗。"}]', '{"noun":"eagerness","adverb":"eagerly"}', NULL, 2, 2255, NULL),
(2256, 'early', '/ˈɜːrli/', 'adjective', '{"zh-TW":["早的；提前的"],"en":["before the expected time","near the beginning of a period"]}', NULL, 'early morning / early stage', '[{"en":"We are still in the early stages.","zh-TW":"我們仍處於早期階段。"},{"en":"She arrived early for the interview.","zh-TW":"她面試提前到達。"}]', '{"adjective":"early","adverb":"early"}', NULL, 2, 2256, NULL),
(2257, 'early adopter', '/ˈɜːrli əˈdɒptər/', 'noun', '{"zh-TW":["早期採用者"],"en":["a customer who uses a new product or technology before most other consumers"]}', NULL, 'target early adopters / early adopter feedback', '[{"en":"Early adopters provided valuable feedback that shaped product development.","zh-TW":"早期採用者提供了寶貴的反饋，塑造了產品發展方向。"},{"en":"Companies reward early adopters with discounts and exclusive features.","zh-TW":"公司以折扣和獨家功能獎勵早期採用者。"}]', NULL, NULL, 5, 2257, NULL),
(2258, 'early check-in', '/ˈɜːrli ˈtʃɛkɪn/', 'noun', '{"zh-TW":["提前入住"],"en":["checking in before the standard check-in time"]}', NULL, 'request early check-in / early check-in fee', '[{"en":"She requested early check-in due to an early morning flight.","zh-TW":"她因早班機而要求提前入住。"},{"en":"Early check-in is subject to availability and may incur a fee.","zh-TW":"提前入住視空房情況而定，可能需要支付費用。"}]', NULL, NULL, 5, 2258, NULL),
(2259, 'earn', '/ɜːrn/', 'verb', '{"zh-TW":["賺取；贏得"],"en":["to receive money for work; to gain through effort"]}', NULL, 'earn a living/reputation', '[{"en":"She earns a good salary as a consultant.","zh-TW":"她作為顧問賺取了不錯的薪水。"},{"en":"He earned the respect of his colleagues.","zh-TW":"他贏得了同事的尊重。"}]', '{"noun":"earnings","verb":"earn"}', NULL, 1, 2259, NULL),
(2260, 'earn-out', '/ˈɜːrn aʊt/', 'noun', '{"zh-TW":["業績對賭安排；收益補充"],"en":["a payment structure where the seller earns additional amounts based on future performance"]}', NULL, 'earn-out provision / negotiate an earn-out', '[{"en":"The acquisition included an earn-out provision based on three-year profit targets.","zh-TW":"收購包含基於三年利潤目標的業績對賭安排。"},{"en":"An earn-out aligns seller and buyer incentives during the transition.","zh-TW":"業績對賭安排在過渡期間使賣方和買方的激勵保持一致。"}]', NULL, NULL, 3, 2260, NULL),
(2261, 'earnings before interest and tax', '/ˈɜːrnɪŋz bɪˌfɔːr ˈɪntrəst ænd tæks/', 'noun', '{"zh-TW":["息稅前利潤"],"en":["operating profit before deducting interest expense and income taxes"]}', NULL, 'calculate EBIT / improve EBIT margin', '[{"en":"A higher EBIT indicates stronger operational efficiency.","zh-TW":"較高的息稅前利潤表明更強的運營效率。"},{"en":"EBIT is used to compare profitability across companies with different capital structures.","zh-TW":"息稅前利潤用於比較具有不同資本結構的公司的盈利能力。"}]', '{"abbreviation":"EBIT"}', NULL, 5, 2261, NULL),
(2262, 'earnings before interest and taxes', '/ˈɜːrnɪŋz bɪˈfɔːr ˈɪntrɪst ənd tæksɪz/', 'noun', '{"zh-TW":["息稅前利潤"],"en":["a measure of a company''s profitability excluding interest and tax costs"]}', NULL, 'calculate earnings before interest and taxes / earnings before interest and taxes margin / use earnings before interest and taxes', '[{"en":"Earnings before interest and taxes is commonly used to compare profitability across companies.","zh-TW":"息稅前利潤常用於比較不同公司之間的盈利能力。"},{"en":"A rising earnings before interest and taxes margin indicates improving operational efficiency.","zh-TW":"息稅前利潤率上升表明業務效率的提升。"}]', NULL, NULL, 5, 2262, NULL),
(2263, 'earnings before interest tax depreciation amortization', '/ˈɜːrnɪŋz bɪˈfɔːr ˈɪntrɪst tæks dɪˌpriːʃiˈeɪʃən əˌmɔːrtɪˈzeɪʃən/', 'noun', '{"zh-TW":["息稅折舊攤銷前利潤"],"en":["a measure of core operating performance excluding non-cash charges"]}', NULL, 'calculate EBITDA / EBITDA margin', '[{"en":"EBITDA is widely used to compare operational performance across companies.","zh-TW":"EBITDA被廣泛用於比較各公司的運營績效。"},{"en":"The company''s EBITDA margin improved to 25% following cost restructuring.","zh-TW":"在成本重組後，公司的EBITDA利潤率提升至25%。"}]', '{"abbreviation":"EBITDA"}', NULL, 5, 2263, NULL),
(2264, 'earnings call', '/ˈɜːrnɪŋz kɔːl/', 'noun', '{"zh-TW":["業績發布電話會議"],"en":["a conference call where a company discusses its financial results with analysts"]}', NULL, 'host an earnings call / earnings call transcript', '[{"en":"Management highlighted strong revenue growth during the earnings call.","zh-TW":"管理層在業績發布電話會議上強調了強勁的收入增長。"},{"en":"Analysts submitted questions about margins during the quarterly earnings call.","zh-TW":"分析師在季度業績發布電話會議上提交了有關利潤率的問題。"}]', NULL, NULL, 5, 2264, NULL),
(2265, 'earnings per share', '/ˈɜːrnɪŋz pər ʃɛr/', 'noun', '{"zh-TW":["每股盈餘"],"en":["a company''s profit divided by the number of outstanding shares"]}', NULL, 'earnings per share growth / diluted earnings per share', '[{"en":"Earnings per share rose to $3.50 this fiscal year.","zh-TW":"本財政年度每股盈餘增至3.50美元。"},{"en":"Analysts expected earnings per share to beat estimates.","zh-TW":"分析師預期每股盈餘將超過預期。"}]', '{"abbreviation":"EPS"}', NULL, 5, 2265, NULL),
(2266, 'earnings release', '/ˈɜːrnɪŋz rɪˈliːs/', 'noun', '{"zh-TW":["業績公告"],"en":["a public announcement of a company''s financial results for a reporting period"]}', NULL, 'issue an earnings release / earnings release date', '[{"en":"The earnings release showed a 15% increase in quarterly net income.","zh-TW":"業績公告顯示季度淨利潤增加了15%。"},{"en":"Investors study the earnings release for signs of operational improvement.","zh-TW":"投資者研究業績公告以尋找運營改善的跡象。"}]', NULL, NULL, 5, 2266, NULL),
(2267, 'earnings yield', '/ˈɜːrnɪŋz jiːld/', 'noun', '{"zh-TW":["盈利收益率"],"en":["the ratio of earnings per share to the market price per share"]}', NULL, 'calculate earnings yield / compare earnings yield / earnings yield spread', '[{"en":"The earnings yield of the stock is higher than the risk-free rate.","zh-TW":"該股票的盈利收益率高於無風險利率。"},{"en":"Some investors use earnings yield to compare stocks with bonds.","zh-TW":"部分投資者使用盈利收益率來比較股票和債券。"}]', NULL, NULL, 5, 2267, NULL),
(2268, 'earth', '/ɜːrθ/', 'noun', '{"zh-TW":["地球；土地"],"en":["the planet we live on","soil"]}', NULL, 'on earth / earth-friendly', '[{"en":"We promote earth-friendly products.","zh-TW":"我們推廣環保產品。"},{"en":"What on earth happened?","zh-TW":"到底發生了什麼事？"}]', '{"noun":"earth","adjective":"earthy","adjective2":"earthly"}', NULL, 2, 2268, NULL),
(2269, 'earthquake', '/ˈɜːrθkweɪk/', 'noun', '{"zh-TW":["地震"],"en":["a sudden violent shaking of the ground"]}', '{"root":{"text":"earth","meaning":"ground (地面)"},"suffix":{"text":"quake","meaning":"shake (搖晃)"},"logic":"地面搖晃，即「地震」。"}', 'earthquake damage / earthquake-proof', '[{"en":"The earthquake measured 7.2 on the Richter scale.","zh-TW":"地震規模達到芮氏7.2級。"},{"en":"Buildings in Japan are designed to withstand earthquakes.","zh-TW":"日本的建築設計能承受地震。"}]', NULL, NULL, 4, 2269, NULL),
(2270, 'ease', '/iːz/', 'noun / verb', '{"zh-TW":["輕鬆；緩解"],"en":["absence of difficulty; to make less severe"]}', NULL, 'with ease / ease the pressure', '[{"en":"She completed the task with ease.","zh-TW":"她輕鬆地完成了任務。"},{"en":"The new policy will ease the financial burden.","zh-TW":"新政策將緩解經濟負擔。"}]', '{"noun":"ease","verb":"ease","adjective":"easy"}', NULL, 1, 2270, NULL),
(2271, 'easement', '/ˈiːzmənt/', 'noun', '{"zh-TW":["地役權；通行權"],"en":["the right to use another person''s land for a specific purpose"]}', NULL, 'grant an easement / easement rights / right-of-way easement', '[{"en":"The utility company has an easement to access the buried pipes.","zh-TW":"公用事業公司擁有進入埋地管道的地役權。"},{"en":"An easement was granted to allow access through the neighboring property.","zh-TW":"授予了通過鄰近物業的通行地役權。"}]', NULL, NULL, 3, 2271, NULL),
(2272, 'easy', '/ˈiːzi/', 'adjective', '{"zh-TW":["容易的；輕鬆的"],"en":["not difficult","comfortable"]}', NULL, 'easy to use / take it easy', '[{"en":"The software is easy to use.","zh-TW":"這個軟體很容易使用。"},{"en":"Take it easy this weekend.","zh-TW":"這週末輕鬆一下吧。"}]', '{"adjective":"easy","adverb":"easily","noun":"ease","verb":"ease"}', NULL, 1, 2272, NULL),
(2273, 'eat', '/iːt/', 'verb', '{"zh-TW":["吃"],"en":["to put food in the mouth, chew, and swallow"]}', NULL, 'eat out / eat healthy', '[{"en":"We often eat out with clients.","zh-TW":"我們常和客戶外出用餐。"},{"en":"Try to eat healthy during work trips.","zh-TW":"出差期間盡量吃得健康。"}]', '{"verb":"eat","noun":"eater","adjective":"edible"}', NULL, 1, 2273, NULL),
(2274, 'EBITDA', '/iːˈbɪtdɑː/', 'noun', '{"zh-TW":["息稅折舊攤銷前利潤"],"en":["earnings before interest, taxes, depreciation, and amortization"]}', NULL, 'EBITDA margin / adjusted EBITDA / EBITDA multiple', '[{"en":"Investors use EBITDA to compare companies across industries.","zh-TW":"投資者使用EBITDA跨行業比較公司。"},{"en":"The company reported strong EBITDA growth of 22%.","zh-TW":"公司報告了22%的強勁EBITDA增長。"}]', NULL, NULL, 2, 2274, NULL),
(2275, 'ebitda margin', '/iːˈbɪtdə ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["息稅折舊攤銷前利潤率"],"en":["EBITDA expressed as a percentage of total revenue"]}', NULL, 'calculate EBITDA margin / expand EBITDA margin', '[{"en":"The company reported an EBITDA margin of 22% for the fiscal year.","zh-TW":"公司報告了本財年22%的息稅折舊攤銷前利潤率。"},{"en":"Investors use EBITDA margin to compare profitability across companies.","zh-TW":"投資者使用息稅折舊攤銷前利潤率比較各公司的盈利能力。"}]', '{"abbreviation":"EBITDA margin"}', NULL, 5, 2275, NULL),
(2276, 'eclipse', '/ɪˈklɪps/', 'noun', '{"zh-TW":["日食；月食"],"en":["the blocking of light from the sun or moon"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"clips","meaning":"fail/leave (離去)"},"logic":"光芒離去，即「食」（日食/月食）。"}', 'solar eclipse / lunar eclipse / total eclipse', '[{"en":"A total solar eclipse will occur next month.","zh-TW":"下個月將發生日全食。"},{"en":"The lunar eclipse was visible across Asia.","zh-TW":"月食在亞洲各地都能看到。"}]', '{"verb":"eclipse"}', NULL, 3, 2276, NULL),
(2277, 'eco-friendly', '/ˈiːkəʊ ˈfrɛndli/', 'adjective', '{"zh-TW":["環保的；對環境友善的"],"en":["not harmful to the environment"]}', NULL, 'eco-friendly product / eco-friendly packaging', '[{"en":"The company switched to eco-friendly packaging.","zh-TW":"公司改用環保包裝。"},{"en":"Consumers are choosing eco-friendly products more often.","zh-TW":"消費者越來越多地選擇環保產品。"}]', NULL, NULL, 4, 2277, NULL),
(2278, 'eco-tourism', '/''iːkəʊˌtʊərɪzəm/', 'noun', '{"zh-TW":["生態旅遊"],"en":["responsible travel to natural areas that conserves the environment and improves local well-being"]}', NULL, 'promote eco-tourism / eco-tourism destination / sustainable eco-tourism', '[{"en":"Eco-tourism offers travelers a way to enjoy nature without damaging it.","zh-TW":"生態旅遊為旅行者提供了一種享受自然而不破壞它的方式。"},{"en":"The village built eco-tourism facilities to generate income while protecting the forest.","zh-TW":"這個村莊建立了生態旅遊設施，在保護森林的同時創造收入。"}]', '{"adjective":"eco-friendly"}', NULL, 4, 2278, NULL),
(2279, 'ecological corridor', '/ˌiːkəˈlɒdʒɪkəl kəˈrɪdər/', 'noun', '{"zh-TW":["生態廊道"],"en":["a strip of habitat connecting isolated wildlife populations"]}', NULL, 'create ecological corridors / ecological corridor project / wildlife ecological corridor', '[{"en":"Ecological corridors allow animals to move safely between habitat patches.","zh-TW":"生態廊道允許動物在棲息地斑塊之間安全移動。"},{"en":"Establishing ecological corridors reduces the risk of species extinction.","zh-TW":"建立生態廊道降低了物種滅絕的風險。"}]', NULL, NULL, 5, 2279, NULL),
(2280, 'ecological footprint', '/ˌiːkəˈlɒdʒɪkəl ˈfʊtprɪnt/', 'noun', '{"zh-TW":["生態足跡"],"en":["the impact of human activities on the environment"]}', NULL, 'reduce ecological footprint / calculate ecological footprint', '[{"en":"Reducing your ecological footprint helps preserve natural resources.","zh-TW":"減少您的生態足跡有助於保護自然資源。"},{"en":"The company monitors its ecological footprint annually.","zh-TW":"公司每年監測其生態足跡。"}]', NULL, NULL, 5, 2280, NULL),
(2281, 'ecommerce', '/ˈiːkɒmɜːrs/', 'noun', '{"zh-TW":["電子商務"],"en":["the buying and selling of goods and services over the internet"]}', NULL, 'invest in ecommerce / ecommerce platform / ecommerce growth', '[{"en":"The company''s ecommerce sales doubled in the past two years.","zh-TW":"公司的電子商務銷售在過去兩年翻倍了。"},{"en":"Strong ecommerce capabilities are now essential for retailers.","zh-TW":"強大的電子商務能力現在對零售商至關重要。"}]', NULL, NULL, 3, 2281, NULL),
(2282, 'economic cycle', '/ˌiːkəˈnɒmɪk ˈsaɪkəl/', 'noun', '{"zh-TW":["經濟周期"],"en":["the recurring pattern of expansion, peak, contraction, and trough in an economy"]}', NULL, 'navigate the economic cycle / economic cycle impact / economic cycle stages', '[{"en":"Businesses must plan for all phases of the economic cycle.","zh-TW":"企業必須為經濟周期的所有階段做好規劃。"},{"en":"Defensive stocks tend to perform well regardless of the economic cycle.","zh-TW":"防禦型股票往往在經濟周期的各個階段都表現良好。"}]', '{"adjective":"economic","noun":"economic"}', NULL, 5, 2282, NULL),
(2283, 'economic downturn', '/ˌiːkəˈnɒmɪk ˈdaʊntɜːrn/', 'noun', '{"zh-TW":["經濟下滑；經濟低迷"],"en":["a period of reduced economic activity and lower growth"]}', NULL, 'weather an economic downturn / economic downturn impact', '[{"en":"Sales fell sharply during the economic downturn.","zh-TW":"經濟低迷期間銷售大幅下降。"},{"en":"Companies that manage costs well can survive an economic downturn.","zh-TW":"善於管理成本的公司能夠度過經濟下滑。"}]', NULL, NULL, 5, 2283, NULL),
(2284, 'economic forecast', '/ˌiːkəˈnɒmɪk ˈfɔːrkɑːst/', 'noun', '{"zh-TW":["經濟預測"],"en":["a prediction about future economic conditions"]}', NULL, 'issue an economic forecast / economic forecast report', '[{"en":"The bank released an optimistic economic forecast for next year.","zh-TW":"銀行發布了對明年樂觀的經濟預測。"},{"en":"Businesses use economic forecasts to plan their investment strategy.","zh-TW":"企業使用經濟預測來規劃其投資策略。"}]', '{"verb":"forecast"}', NULL, 5, 2284, NULL),
(2285, 'economic growth', '/ˌiːkəˈnɒmɪk ɡroʊθ/', 'noun', '{"zh-TW":["經濟增長"],"en":["an increase in the production of goods and services over time"]}', NULL, 'drive economic growth / GDP growth / sustainable economic growth', '[{"en":"Strong economic growth led to increased business investment.","zh-TW":"強勁的經濟增長帶來了增加的商業投資。"},{"en":"Technology is a key driver of long-term economic growth.","zh-TW":"技術是長期經濟增長的關鍵驅動力。"}]', '{"adjective":"economically growing"}', NULL, 5, 2285, NULL),
(2286, 'economic indicator', '/ˌiːkəˈnɒmɪk ˈɪndɪkeɪtər/', 'noun', '{"zh-TW":["經濟指標"],"en":["a statistic used to assess the current or future state of an economy"]}', NULL, 'monitor economic indicators / leading economic indicator', '[{"en":"GDP growth and unemployment are key economic indicators watched by investors.","zh-TW":"GDP增長和失業率是投資者關注的關鍵經濟指標。"},{"en":"A leading economic indicator provides early signals of economic direction.","zh-TW":"領先經濟指標提供了經濟走向的早期信號。"}]', NULL, NULL, 5, 2286, NULL),
(2287, 'economic moat', '/ˌiːkəˈnɒmɪk məʊt/', 'noun', '{"zh-TW":["護城河（競爭優勢）"],"en":["a sustainable competitive advantage protecting a company from competitors"]}', NULL, 'build an economic moat / wide economic moat / narrow economic moat', '[{"en":"Brand loyalty creates a wide economic moat for consumer staples companies.","zh-TW":"品牌忠誠度為消費品公司創造了寬廣的護城河。"},{"en":"Warren Buffett popularized the concept of an economic moat in investing.","zh-TW":"沃倫·巴菲特在投資中普及了護城河的概念。"}]', NULL, NULL, 5, 2287, NULL),
(2288, 'economic stimulus', '/ˌiːkəˈnɒmɪk ˈstɪmjʊləs/', 'noun', '{"zh-TW":["經濟刺激"],"en":["government actions taken to boost economic activity"]}', NULL, 'provide economic stimulus / economic stimulus package', '[{"en":"The government announced an economic stimulus package of 50 billion.","zh-TW":"政府宣佈了500億元的經濟刺激計劃。"},{"en":"Economic stimulus measures helped reduce unemployment.","zh-TW":"經濟刺激措施有助於降低失業率。"}]', NULL, NULL, 5, 2288, NULL),
(2289, 'economical', 'ˌiːkəˈnɒmɪkəl', 'adjective', '{"zh-TW":["經濟的；節儉的","實惠的"],"en":["using resources carefully","avoiding waste"]}', NULL, 'economical solution/economical approach', '[{"en":"This is a more economical alternative.","zh-TW":"這是一個更經濟的替代方案。"}]', '{"noun":"economy","adverb":"economically"}', NULL, 4, 2289, NULL),
(2290, 'economies of scale', '/ɪˈkɒnəmiz əv skeɪl/', 'noun', '{"zh-TW":["規模經濟"],"en":["cost advantages gained through increased production or operational size"]}', NULL, 'achieve economies of scale / benefits of economies of scale', '[{"en":"Larger production volumes enabled the company to achieve economies of scale.","zh-TW":"較大的生產量使公司實現了規模經濟。"},{"en":"Economies of scale allow bigger companies to undercut smaller rivals on price.","zh-TW":"規模經濟讓大公司能夠在價格上超越小競爭對手。"}]', NULL, NULL, 5, 2290, NULL),
(2291, 'economies of scope', '/ɪˈkɒnəmiz əv skoʊp/', 'noun', '{"zh-TW":["範疇經濟"],"en":["cost savings from producing multiple different products together"]}', NULL, 'benefit from economies of scope / achieve economies of scope', '[{"en":"The conglomerate achieves economies of scope by sharing distribution networks.","zh-TW":"企業集團通過共享分銷網路實現了範疇經濟。"},{"en":"Economies of scope make diversified companies more cost-efficient.","zh-TW":"範疇經濟使多元化公司更具成本效益。"}]', NULL, NULL, 5, 2291, NULL),
(2292, 'economy', '/ɪˈkɑːnəmi/', 'noun', '{"zh-TW":["經濟；節約"],"en":["the system of trade and industry; careful use of resources"]}', NULL, 'global/national economy', '[{"en":"The economy is expected to grow by 3%.","zh-TW":"預計經濟將增長3%。"},{"en":"We need to practice economy in spending.","zh-TW":"我們需要節約開支。"}]', '{"noun":"economy/economics/economist","adjective":"economic/economical"}', NULL, 3, 2292, NULL),
(2293, 'economy class', '/ɪˈkɒnəmi klæs/', 'noun', '{"zh-TW":["經濟艙"],"en":["the lowest class of seating on a plane"]}', NULL, 'fly economy class / economy class fare', '[{"en":"Economy class tickets are the most affordable option.","zh-TW":"經濟艙機票是最實惠的選擇。"},{"en":"The seats in economy class were narrow but comfortable.","zh-TW":"經濟艙的座位雖然窄但很舒適。"}]', NULL, NULL, 5, 2293, NULL),
(2294, 'ecosystem', '/ˈiːkəʊˌsɪstəm/', 'noun', '{"zh-TW":["生態系統"],"en":["a biological community of interacting organisms and environment"]}', NULL, 'protect the ecosystem / marine ecosystem', '[{"en":"Pollution can severely damage a fragile ecosystem.","zh-TW":"污染可能嚴重損害脆弱的生態系統。"},{"en":"The coral reef ecosystem supports thousands of species.","zh-TW":"珊瑚礁生態系統支撐著數千個物種。"}]', NULL, NULL, 3, 2294, NULL),
(2295, 'ecosystem services', '/ˈiːkəʊˌsɪstəm ˈsɜːrvɪsɪz/', 'noun', '{"zh-TW":["生態系統服務"],"en":["benefits that humans receive from healthy natural ecosystems"]}', NULL, 'value ecosystem services / ecosystem services assessment / lost ecosystem services', '[{"en":"Deforestation destroys ecosystem services such as clean water filtration and carbon storage.","zh-TW":"森林砍伐破壞了清潔水過濾和碳儲存等生態系統服務。"},{"en":"Economists are developing methods to assign monetary value to ecosystem services.","zh-TW":"經濟學家正在開發方法，為生態系統服務賦予貨幣價值。"}]', NULL, NULL, 5, 2295, NULL),
(2296, 'ecotourism', '/ˈiːkəʊˌtʊərɪzəm/', 'noun', '{"zh-TW":["生態旅遊"],"en":["responsible travel to natural areas that conserves the environment"]}', NULL, 'promote ecotourism / ecotourism destination / sustainable ecotourism', '[{"en":"Ecotourism generates income for local communities while protecting nature.","zh-TW":"生態旅遊為當地社區創造收入同時保護自然。"},{"en":"Well-managed ecotourism reduces pressure on natural ecosystems.","zh-TW":"管理良好的生態旅遊減少了對自然生態系統的壓力。"}]', '{"adjective":"ecotourist","noun":"ecotourist"}', NULL, 4, 2296, NULL),
(2297, 'edge computing', '/edʒ kəmˈpjuːtɪŋ/', 'noun', '{"zh-TW":["邊緣計算"],"en":["processing data near the source rather than in a centralized cloud"]}', NULL, 'implement edge computing / edge computing architecture / edge computing device', '[{"en":"Edge computing reduces latency by processing data closer to the user.","zh-TW":"邊緣計算通過更靠近用戶處理數據來減少延遲。"},{"en":"Autonomous vehicles rely on edge computing for real-time decision-making.","zh-TW":"自動駕駛汽車依賴邊緣計算進行即時決策。"}]', NULL, NULL, 5, 2297, NULL),
(2298, 'edit', '/ˈedɪt/', 'verb', '{"zh-TW":["編輯；修改"],"en":["to prepare written material for publication"]}', NULL, 'edit a document/video', '[{"en":"Please edit the report before submission.","zh-TW":"請在提交前編輯報告。"},{"en":"The article was heavily edited.","zh-TW":"這篇文章經過大量修改。"}]', '{"noun":"edition/editor","verb":"edit","adjective":"editorial"}', NULL, 1, 2298, NULL),
(2299, 'editorial independence', '/ˌedɪˈtɔːriəl ˌɪndɪˈpendəns/', 'noun', '{"zh-TW":["編輯獨立性"],"en":["the freedom of journalists and editors to make editorial decisions without outside influence"]}', NULL, 'protect editorial independence / challenge to editorial independence / editorial independence standards', '[{"en":"Advertisers must not compromise the editorial independence of journalists.","zh-TW":"廣告商不得損害記者的編輯獨立性。"},{"en":"Editorial independence is a cornerstone of credible journalism.","zh-TW":"編輯獨立性是可信新聞業的基石。"}]', '{"adjective":"editorially independent"}', NULL, 5, 2299, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2300, 'educate', '/ˈedʒukeɪt/', 'verb', '{"zh-TW":["教育；培養"],"en":["to give intellectual or moral instruction"]}', NULL, 'educate the public', '[{"en":"The program aims to educate consumers about nutrition.","zh-TW":"該計畫旨在教育消費者有關營養的知識。"},{"en":"She was educated at Oxford University.","zh-TW":"她在牛津大學接受教育。"}]', '{"noun":"education/educator","verb":"educate","adjective":"educational/educated"}', NULL, 3, 2300, NULL),
(2301, 'education', 'ˌɛdʒʊˈkeɪʃən', 'noun', '{"zh-TW":["教育；學歷","培訓"],"en":["the process of learning","a person''s academic background"]}', NULL, 'higher education/continuing education', '[{"en":"Education is a key investment.","zh-TW":"教育是一項關鍵投資。"}]', '{"verb":"educate","adjective":"educational","adverb":"educationally"}', NULL, 3, 2301, NULL),
(2302, 'educational technology', '/''edʒʊˌkeɪʃənəl tekˈnɒlədʒi/', 'noun', '{"zh-TW":["教育科技；教育技術"],"en":["the use of digital tools, platforms, and resources to enhance learning and teaching"]}', NULL, 'adopt educational technology / educational technology platform / impact of educational technology', '[{"en":"Educational technology has transformed the way teachers deliver lessons.","zh-TW":"教育科技改變了教師授課的方式。"},{"en":"Many schools invest in educational technology to engage digital-native students.","zh-TW":"許多學校投資教育科技，以吸引數位原住民學生。"}]', NULL, NULL, 5, 2302, NULL),
(2303, 'effect', '/ɪˈfekt/', 'noun', '{"zh-TW":["效果；影響"],"en":["a change produced by an action or cause"]}', NULL, 'have an effect on / take effect', '[{"en":"The new law will take effect next month.","zh-TW":"新法律將於下個月生效。"},{"en":"The policy had a positive effect on sales.","zh-TW":"該政策對銷售產生了積極影響。"}]', '{"noun":"effect/effectiveness","adjective":"effective","adverb":"effectively"}', NULL, 2, 2303, NULL),
(2304, 'effective', '/ɪˈfektɪv/', 'adjective', '{"zh-TW":["有效的；效果顯著的"],"en":["producing a desired or intended result"]}', NULL, 'effective strategy / effective communication / cost-effective', '[{"en":"The training program was effective in improving sales skills.","zh-TW":"培訓計劃在提高銷售技能方面很有效果。"},{"en":"Cost-effective solutions are preferred when budgets are tight.","zh-TW":"預算緊張時，具成本效益的解決方案是首選。"}]', '{"adverb":"effectively","noun":"effectiveness","antonym":"ineffective"}', NULL, 3, 2304, 109),
(2305, 'effective date', '/ɪˈfɛktɪv deɪt/', 'noun', '{"zh-TW":["生效日期"],"en":["the date on which a contract or policy comes into force"]}', NULL, 'agreement effective date / policy effective date', '[{"en":"The contract''s effective date is the first of next month.","zh-TW":"合約的生效日期是下個月的第一天。"},{"en":"Benefits begin on the effective date of the policy.","zh-TW":"福利從保單生效日期開始生效。"}]', NULL, NULL, 5, 2305, NULL),
(2306, 'effective management', '/ɪˈfektɪv ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["有效管理"],"en":["management that achieves organizational goals through appropriate use of resources"]}', NULL, 'demonstrate effective management / principles of effective management', '[{"en":"Effective management requires clear goals, resources, and communication.","zh-TW":"有效管理需要明確的目標、資源和溝通。"},{"en":"The program taught effective management through case studies and coaching.","zh-TW":"該計劃通過案例研究和輔導教授了有效管理。"}]', NULL, NULL, 5, 2306, NULL),
(2307, 'effective tax rate', '/ɪˈfektɪv tæks reɪt/', 'noun', '{"zh-TW":["有效稅率；實際稅率"],"en":["the actual average rate at which income is taxed after deductions and credits"]}', NULL, 'calculate the effective tax rate / reduce the effective tax rate', '[{"en":"The company''s effective tax rate fell to 18% through strategic planning.","zh-TW":"通過戰略規劃，公司的有效稅率降至18%。"},{"en":"Investors compare effective tax rates across companies in different jurisdictions.","zh-TW":"投資者比較不同司法管轄區公司的有效稅率。"}]', NULL, NULL, 5, 2307, NULL),
(2308, 'effectiveness', 'ɪˈfɛktɪvnɪs', 'noun', '{"zh-TW":["有效性；效果","效力"],"en":["the quality of producing results","how well something works"]}', NULL, 'measure effectiveness/improve effectiveness', '[{"en":"We measure the effectiveness of campaigns.","zh-TW":"我們衡量活動的有效性。"}]', '{"adjective":"effective","adverb":"effectively"}', NULL, 5, 2308, NULL),
(2309, 'effectuate', '/ɪˈfektʃueɪt/', 'verb', '{"zh-TW":["實現；使生效"],"en":["to put into effect; to bring about"]}', NULL, 'effectuate a policy / effectuate change / effectuate a plan', '[{"en":"The legislation was designed to effectuate major reforms in the tax code.","zh-TW":"該立法旨在實現稅法的重大改革。"},{"en":"New management was brought in to effectuate a comprehensive restructuring.","zh-TW":"引進新管理層來實現全面的重組。"}]', '{"noun":"effectuation","adjective":"effectuated"}', NULL, 4, 2309, NULL),
(2310, 'efficacy', '/ˈefɪkəsi/', 'noun', '{"zh-TW":["效力；功效"],"en":["the ability to produce a desired result"]}', NULL, 'clinical efficacy / policy efficacy / demonstrate efficacy', '[{"en":"The clinical trial demonstrated the drug''s efficacy against the virus.","zh-TW":"臨床試驗證明了該藥物對病毒的效力。"},{"en":"Researchers measured the efficacy of the intervention across multiple outcomes.","zh-TW":"研究員在多個結果方面衡量了干預的功效。"}]', '{"adjective":"efficacious","adverb":"efficaciously"}', NULL, 3, 2310, NULL),
(2311, 'efficiency', '/ɪˈfɪʃənsi/', 'noun', '{"zh-TW":["效率；效能"],"en":["the ability to achieve a goal with minimum wasted effort"]}', NULL, 'operational efficiency / improve efficiency', '[{"en":"The new software improved workflow efficiency significantly.","zh-TW":"新軟體顯著提升了工作流程效率。"},{"en":"Efficiency is key to maintaining competitive advantage.","zh-TW":"效率是保持競爭優勢的關鍵。"}]', '{"adjective":"efficient","adverb":"efficiently"}', NULL, 4, 2311, 553),
(2312, 'efficiency ratio', '/ɪˈfɪʃənsi ˈreɪʃiəʊ/', 'noun', '{"zh-TW":["效率比率"],"en":["a measure comparing costs to revenues or outputs to inputs"]}', NULL, 'improve the efficiency ratio / calculate the efficiency ratio', '[{"en":"A lower efficiency ratio indicates better cost management.","zh-TW":"較低的效率比率表示更好的成本管理。"},{"en":"The bank''s efficiency ratio improved after restructuring.","zh-TW":"重組後銀行的效率比率有所改善。"}]', NULL, NULL, 5, 2312, NULL),
(2313, 'efficiency savings', '/ɪˈfɪʃənsi ˈseɪvɪŋz/', 'noun', '{"zh-TW":["效率節省；增效節省"],"en":["financial savings resulting from improved operational efficiency"]}', NULL, 'deliver efficiency savings / achieve efficiency savings', '[{"en":"The merger delivered 30 million in annual efficiency savings.","zh-TW":"合並帶來了每年3000萬元的效率節省。"},{"en":"Technology investment contributed significantly to efficiency savings.","zh-TW":"技術投資顯著促進了效率節省。"}]', NULL, NULL, 5, 2313, NULL),
(2314, 'efficient', '/ɪˈfɪʃənt/', 'adjective', '{"zh-TW":["高效的","有效率的"],"en":["achieving maximum output with minimum waste","achieving maximum productivity with minimum waste"]}', '{"prefix":{"text":"ef-","meaning":"out (出)"},"root":{"text":"fic","meaning":"make/do (做)"},"suffix":{"text":"-ient","meaning":"being (…的)"},"logic":"做出成果的，即「有效率的」。"}', 'cost-efficient / energy-efficient; energy-efficient / cost-efficient / highly efficient', '[{"en":"The new system is more efficient.","zh-TW":"新系統更加高效。"},{"en":"We need to find a more efficient solution.","zh-TW":"我們需要找到更高效的解決方案。"},{"en":"This engine is more fuel-efficient.","zh-TW":"這個引擎更省油。"},{"en":"We need a more efficient way to process orders.","zh-TW":"我們需要更有效率的方式處理訂單。"}]', '{"noun":"efficiency","adjective":"efficient","adverb":"efficiently"}', NULL, 3, 2314, 110),
(2315, 'effort', '/ˈefərt/', 'noun', '{"zh-TW":["努力；成果"],"en":["a determined attempt; physical or mental energy used"]}', NULL, 'make an effort / considerable effort', '[{"en":"It took a lot of effort to complete the project.","zh-TW":"完成這個項目花了很多努力。"},{"en":"Please make an effort to arrive on time.","zh-TW":"請努力準時到達。"}]', '{"noun":"effort","adjective":"effortless"}', NULL, 2, 2315, NULL),
(2316, 'egalitarianism', '/ɪˌɡælɪˈteəriənɪzəm/', 'noun', '{"zh-TW":["平等主義"],"en":["the belief in and pursuit of equal rights and opportunities for all people"]}', NULL, 'promote egalitarianism / social egalitarianism / egalitarianism in education', '[{"en":"Egalitarianism in education requires removing barriers that limit disadvantaged students.","zh-TW":"教育上的平等主義需要消除限制弱勢學生的障礙。"},{"en":"Critics argue that strict egalitarianism ignores differences in individual merit.","zh-TW":"批評者認為，嚴格的平等主義忽視了個人才能的差異。"}]', '{"adjective":"egalitarian","noun2":"egalitarian"}', NULL, 5, 2316, NULL),
(2317, 'ekphrasis', '/ˈekfrəsɪs/', 'noun', '{"zh-TW":["對視覺藝術的文字描述"],"en":["a literary description or commentary on a visual work of art"]}', NULL, 'ekphrasis poem / practice ekphrasis / ekphrasis in literature', '[{"en":"Keats''s Ode on a Grecian Urn is a celebrated example of ekphrasis.","zh-TW":"濟慈的《希臘古甕頌》是一個著名的對視覺藝術的文字描述例子。"},{"en":"Ekphrasis transforms the experience of visual art into language.","zh-TW":"對視覺藝術的文字描述將視覺藝術體驗轉化為語言。"}]', '{"adjective":"ekphrastic"}', NULL, 3, 2317, NULL),
(2318, 'elaborate', '/ɪˈlæbərət/', 'adjective / verb', '{"zh-TW":["精心的；詳述"],"en":["detailed and complicated; to explain in more detail"]}', NULL, 'elaborate on/plan', '[{"en":"Could you elaborate on your proposal?","zh-TW":"你能詳細說明你的提案嗎？"},{"en":"They developed an elaborate marketing strategy.","zh-TW":"他們制定了精心的行銷策略。"}]', '{"noun":"elaboration","verb":"elaborate","adjective":"elaborate"}', NULL, 3, 2318, 676),
(2319, 'elaborate on', '/''ɪˌlæbəreɪt ɒn/', 'phrase', '{"zh-TW":["詳細說明；進一步闡述"],"en":["to add more detail or information about a topic"]}', NULL, 'elaborate on a point / elaborate on an idea / elaborate on findings', '[{"en":"Could you elaborate on the reasons behind your decision?","zh-TW":"你能詳細說明你做出這個決定的原因嗎？"},{"en":"The speaker elaborated on the key challenges facing the industry today.","zh-TW":"演講者詳細闡述了當今行業面臨的關鍵挑戰。"}]', NULL, NULL, 4, 2319, NULL),
(2320, 'elasticity', '/ˌɪlæˈstɪsɪti/', 'noun', '{"zh-TW":["彈性"],"en":["the degree to which demand responds to a change in price"]}', NULL, 'price elasticity / demand elasticity / income elasticity', '[{"en":"The price elasticity of cigarettes is low because they are addictive.","zh-TW":"香菸的價格彈性低，因為它們具有成癮性。"},{"en":"Understanding elasticity helps firms set optimal pricing strategies.","zh-TW":"了解彈性幫助企業制定最佳定價策略。"}]', '{"adjective":"elastic","adverb":"elastically"}', NULL, 4, 2320, NULL),
(2321, 'elasticity of demand', '/ˌɪlæˈstɪsɪti əv dɪˈmɑːnd/', 'noun', '{"zh-TW":["需求彈性"],"en":["the degree to which consumer demand changes in response to a price change"]}', NULL, 'measure elasticity of demand / inelastic demand', '[{"en":"Luxury goods have high elasticity of demand and sales drop with price rises.","zh-TW":"奢侈品的需求彈性高，價格上漲時銷售量下降。"},{"en":"Essential services have low elasticity of demand regardless of price.","zh-TW":"基本服務無論價格如何都具有低需求彈性。"}]', NULL, NULL, 5, 2321, NULL),
(2322, 'elect', '/ɪˈlekt/', 'verb', '{"zh-TW":["選舉；選擇"],"en":["to choose by voting"]}', NULL, 'elect a president/chairperson', '[{"en":"She was elected as the new chairperson.","zh-TW":"她被選為新主席。"},{"en":"Members elect the board annually.","zh-TW":"成員每年選舉董事會。"}]', '{"noun":"election","verb":"elect","adjective":"elected/electoral"}', NULL, 2, 2322, NULL),
(2323, 'elective', '/ɪˈlɛktɪv/', 'noun', '{"zh-TW":["選修課"],"en":["a course that students can choose to take"]}', NULL, 'elective course / take an elective', '[{"en":"Art is an elective at our school.","zh-TW":"藝術在我們學校是選修課。"},{"en":"Students must take two electives.","zh-TW":"學生必須選修兩門選修課。"}]', NULL, NULL, 3, 2323, NULL),
(2324, 'elective course', '/''ɪˈlektɪv kɔːrs/', 'noun', '{"zh-TW":["選修課程"],"en":["an optional course chosen by a student from a range of options to complement their main studies"]}', NULL, 'take an elective course / choose an elective course / elective course options', '[{"en":"She chose creative writing as an elective course to complement her journalism degree.","zh-TW":"她選擇創意寫作作為選修課程，以補充她的新聞學學位。"},{"en":"Students must complete two elective courses outside their major field.","zh-TW":"學生必須在主修領域之外完成兩門選修課程。"}]', NULL, NULL, 5, 2324, NULL),
(2325, 'elective deferral', '/ɪˈlektɪv dɪˈfɜːrəl/', 'noun', '{"zh-TW":["自願遞延；自選遞延"],"en":["a voluntary contribution to a retirement plan made by an employee from pre-tax income"]}', NULL, 'make an elective deferral / elective deferral limit', '[{"en":"Employees can increase their elective deferral up to the annual contribution limit.","zh-TW":"員工可以將其自願遞延增加到年度供款上限。"},{"en":"Elective deferrals reduce current taxable income and grow tax-deferred.","zh-TW":"自願遞延降低了當前應稅收入並延稅增長。"}]', NULL, NULL, 5, 2325, NULL),
(2326, 'electric vehicle', '/ɪˈlɛktrɪk ˈviːɪkəl/', 'noun', '{"zh-TW":["電動車"],"en":["a vehicle powered by electricity rather than fossil fuels"]}', NULL, 'drive an electric vehicle / electric vehicle charging', '[{"en":"Electric vehicles produce no direct carbon emissions.","zh-TW":"電動車不直接產生碳排放。"},{"en":"The government offers subsidies for purchasing electric vehicles.","zh-TW":"政府為購買電動車提供補貼。"}]', '{"abbreviation":"EV"}', NULL, 5, 2326, NULL),
(2327, 'electrocardiogram', '/ɪˌlɛktrəʊˈkɑːrdiəˌɡræm/', 'noun', '{"zh-TW":["心電圖"],"en":["a recording of the electrical activity of the heart"]}', NULL, 'perform an electrocardiogram / electrocardiogram results', '[{"en":"The doctor ordered an electrocardiogram to check heart rhythm.","zh-TW":"醫生要求進行心電圖以檢查心律。"},{"en":"An electrocardiogram is a painless and non-invasive test.","zh-TW":"心電圖是無痛且非侵入性的測試。"}]', '{"abbreviation":"ECG","abbreviation2":"EKG"}', NULL, 5, 2327, NULL),
(2328, 'electrolyte', '/''ɪˌlektrəˌlaɪt/', 'noun', '{"zh-TW":["電解質"],"en":["a mineral in the body, such as sodium or potassium, that carries an electric charge and is essential for various body functions"]}', NULL, 'replenish electrolytes / electrolyte balance / electrolyte drink', '[{"en":"Athletes drink sports beverages to replenish electrolytes lost through sweat.","zh-TW":"運動員飲用運動飲料以補充汗液流失的電解質。"},{"en":"An electrolyte imbalance can cause fatigue, cramping, and dizziness.","zh-TW":"電解質失衡可能導致疲勞、痙攣和頭暈。"}]', '{"adjective":"electrolytic"}', NULL, 4, 2328, NULL),
(2329, 'electronic data interchange', '/ɪˌlektrɒnɪk ˈdeɪtə ˈɪntətʃeɪndʒ/', 'noun', '{"zh-TW":["電子數據交換"],"en":["the computer-to-computer exchange of business documents in a standard format"]}', NULL, 'implement electronic data interchange / electronic data interchange standards', '[{"en":"Electronic data interchange speeds up order processing between trading partners.","zh-TW":"電子數據交換加快了貿易夥伴之間的訂單處理。"},{"en":"Many large retailers require suppliers to use electronic data interchange.","zh-TW":"許多大型零售商要求供應商使用電子數據交換。"}]', '{"abbreviation":"EDI"}', NULL, 5, 2329, NULL),
(2330, 'electronic health record', '/ɪˌlektrɒnɪk helθ ˈrekɔːrd/', 'noun', '{"zh-TW":["電子健康記錄"],"en":["a digital version of a patient''s medical history and health information"]}', NULL, 'access electronic health records / electronic health record system / share electronic health records', '[{"en":"Electronic health records improve care coordination between providers.","zh-TW":"電子健康記錄改善了醫療提供者之間的護理協調。"},{"en":"Patients can view their electronic health records through a secure portal.","zh-TW":"患者可以通過安全門戶查看他們的電子健康記錄。"}]', NULL, NULL, 5, 2330, NULL),
(2331, 'element', '/ˈelɪmənt/', 'noun', '{"zh-TW":["要素；元素"],"en":["a component or part of something"]}', NULL, 'key/essential element', '[{"en":"Trust is a key element of teamwork.","zh-TW":"信任是團隊合作的關鍵要素。"},{"en":"The plan has several important elements.","zh-TW":"該計畫有幾個重要的要素。"}]', '{"noun":"element","adjective":"elementary"}', NULL, 3, 2331, NULL),
(2332, 'elevate', '/ˈelɪveɪt/', 'verb', '{"zh-TW":["提升；提高"],"en":["to raise to a higher position or level"]}', NULL, 'elevate standards/status', '[{"en":"The promotion elevated her to senior manager.","zh-TW":"升遷使她晉升為高級經理。"},{"en":"We aim to elevate customer experience.","zh-TW":"我們的目標是提升客戶體驗。"}]', '{"noun":"elevation/elevator","verb":"elevate","adjective":"elevated"}', NULL, 3, 2332, NULL),
(2333, 'elevator', '/''elɪveɪtər/', 'noun', '{"zh-TW":["電梯；升降機"],"en":["a platform or compartment housed in a shaft for raising and lowering people or things"]}', NULL, 'take the elevator / elevator button / elevator lobby', '[{"en":"Please take the elevator to the fifth floor to reach the conference room.","zh-TW":"請乘電梯到五樓到達會議室。"},{"en":"The hotel''s glass elevator offered a spectacular view of the atrium.","zh-TW":"飯店的玻璃電梯可以看到中庭的壯觀景色。"}]', NULL, NULL, 3, 2333, NULL),
(2334, 'elevator pitch', '/ˈelɪveɪtər pɪtʃ/', 'noun', '{"zh-TW":["電梯簡報；簡短推銷"],"en":["a brief persuasive speech used to spark interest in what you do"]}', NULL, 'prepare an elevator pitch / deliver an elevator pitch / perfect your elevator pitch', '[{"en":"His elevator pitch convinced the investor to request a full meeting.","zh-TW":"他的電梯簡報說服了投資者要求進行完整的會面。"},{"en":"Every entrepreneur should have a polished elevator pitch ready.","zh-TW":"每位創業家都應該準備好一個精心打磨的電梯簡報。"}]', NULL, NULL, 5, 2334, NULL),
(2335, 'elicit', '/ɪˈlɪsɪt/', 'verb', '{"zh-TW":["引出；誘導"],"en":["to draw out a response, answer, or fact from someone"]}', NULL, 'elicit a response / elicit information / elicit feedback', '[{"en":"Open-ended questions elicit more detailed answers.","zh-TW":"開放式問題能引出更詳細的回答。"},{"en":"The researcher elicited candid opinions through interviews.","zh-TW":"研究員通過訪談引出了坦率的意見。"}]', NULL, NULL, 2, 2335, NULL),
(2336, 'eligible', '/ˈelɪdʒəbəl/', 'adjective', '{"zh-TW":["合格的；有資格的"],"en":["meeting the conditions to do or receive something"]}', NULL, 'eligible for/to', '[{"en":"All full-time employees are eligible for benefits.","zh-TW":"所有全職員工都有資格享受福利。"},{"en":"You must be 18 to be eligible to vote.","zh-TW":"你必須年滿18歲才有投票資格。"}]', '{"noun":"eligibility","adjective":"eligible"}', NULL, 3, 2336, 866),
(2337, 'eligible expense', '/ˈelɪdʒɪbəl ɪkˈspens/', 'noun', '{"zh-TW":["合資格費用；可報銷費用"],"en":["an expense that qualifies for reimbursement or tax deduction under specific rules"]}', NULL, 'claim eligible expenses / eligible expense policy', '[{"en":"Only eligible expenses as per the policy are reimbursed.","zh-TW":"只有符合政策的合資格費用才能報銷。"},{"en":"The accountant reviewed all receipts to identify eligible expenses.","zh-TW":"會計師審查了所有收據以識別合資格費用。"}]', NULL, NULL, 5, 2337, NULL),
(2338, 'eliminate', '/ɪˈlɪmɪneɪt/', 'verb', '{"zh-TW":["消除；淘汰"],"en":["to completely remove or get rid of"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"limin","meaning":"threshold (門檻)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使超出門檻之外，即「淘汰」。"}', 'eliminate waste/errors; eliminate waste / eliminate the possibility', '[{"en":"We need to eliminate unnecessary costs.","zh-TW":"我們需要消除不必要的成本。"},{"en":"The company eliminated 200 positions.","zh-TW":"公司裁撤了200個職位。"},{"en":"The team was eliminated in the first round.","zh-TW":"該隊在第一輪就被淘汰了。"}]', '{"noun":"elimination","verb":"eliminate"}', NULL, 3, 2338, 342),
(2339, 'elite theory', '/ɪˈliːt ˈθɪəri/', 'noun', '{"zh-TW":["精英理論"],"en":["the political theory that a small elite group holds power in society"]}', NULL, 'apply elite theory / elite theory of democracy / challenge elite theory', '[{"en":"Elite theory argues that democracy is in practice controlled by a small group.","zh-TW":"精英理論認為民主在實踐中由一小群人控制。"},{"en":"Elite theory challenges pluralist views of power distribution.","zh-TW":"精英理論挑戰了關於權力分配的多元主義觀點。"}]', NULL, NULL, 4, 2339, NULL),
(2340, 'eloquence', '/''eləkwəns/', 'noun', '{"zh-TW":["口才；雄辯"],"en":["the ability to speak or write effectively and persuasively"]}', NULL, 'demonstrate eloquence / eloquence in speech / renowned for eloquence', '[{"en":"Her eloquence in the debate persuaded many undecided voters.","zh-TW":"她在辯論中的口才說服了許多未決定的選民。"},{"en":"The politician was celebrated for his eloquence and ability to inspire crowds.","zh-TW":"這位政治家因其口才和鼓舞人心的能力而備受讚揚。"}]', '{"adjective":"eloquent","adverb":"eloquently"}', NULL, 3, 2340, NULL),
(2341, 'eloquent', '/''eləkwənt/', 'adjective', '{"zh-TW":["雄辯的；有說服力的"],"en":["fluent or persuasive in speaking or writing"]}', NULL, 'eloquent speaker / eloquent speech / eloquent argument', '[{"en":"The CEO delivered an eloquent speech that inspired employees at all levels.","zh-TW":"首席執行官發表了一篇雄辯的演講，激勵了各個層次的員工。"},{"en":"An eloquent letter of complaint is more likely to receive a positive response.","zh-TW":"一封雄辯的投訴信更有可能獲得積極的回應。"}]', '{"adverb":"eloquently","noun":"eloquence"}', NULL, 3, 2341, NULL),
(2342, 'eloquently', '/''eləkwəntli/', 'adverb', '{"zh-TW":["雄辯地；有說服力地"],"en":["in a fluent, persuasive, and clearly expressed manner"]}', NULL, 'argue eloquently / express eloquently / speak eloquently', '[{"en":"She argued eloquently for the importance of investing in employee training.","zh-TW":"她雄辯地論證了投資員工培訓的重要性。"},{"en":"The director expressed eloquently how innovation drives the company''s vision.","zh-TW":"總監雄辯地表達了創新如何驅動公司願景。"}]', NULL, NULL, 4, 2342, NULL),
(2343, 'elucidate', '/ɪˈluːsɪdeɪt/', 'verb', '{"zh-TW":["闡明；解釋清楚"],"en":["to make something clear; to explain in detail"]}', NULL, 'elucidate a point / elucidate findings / elucidate a concept', '[{"en":"The professor elucidated the complex theorem with examples.","zh-TW":"教授用例子闡明了這個複雜的定理。"},{"en":"Could you elucidate what you mean by that statement?","zh-TW":"你能闡明你那句話的意思嗎？"}]', '{"noun":"elucidation","adjective":"elucidatory"}', NULL, 3, 2343, NULL),
(2344, 'elusive', '/''ɪˌluːsɪv/', 'adjective', '{"zh-TW":["難以捉摸的；難以達到的"],"en":["difficult to find, catch, or achieve; avoiding capture"]}', NULL, 'elusive goal / elusive answer / elusive solution', '[{"en":"The solution to the problem remained elusive despite months of research.","zh-TW":"儘管研究了數月，這個問題的解決方案仍然難以捉摸。"},{"en":"The elusive figure disappeared before the investigators could gather any evidence.","zh-TW":"這個難以捉摸的人物在調查人員收集任何證據之前就消失了。"}]', '{"adverb":"elusively","noun":"elusiveness","verb":"elude"}', NULL, 3, 2344, NULL),
(2345, 'email', 'ˈiːmeɪl', 'noun', '{"zh-TW":["電子郵件；電子信件","郵件"],"en":["a message sent electronically","an electronic message system"]}', NULL, 'send an email/check email', '[{"en":"Please check your email for the attachment.","zh-TW":"請查看您的電子郵件以獲取附件。"}]', '{"verb":"email","adjective":"email-based"}', NULL, 2, 2345, NULL),
(2346, 'email marketing', '/ˈiːmeɪl ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["電子郵件行銷"],"en":["using email to promote products and build customer relationships"]}', NULL, 'email marketing campaign / email marketing platform / email marketing automation', '[{"en":"Their email marketing campaign achieved a 25% open rate.","zh-TW":"他們的電子郵件行銷活動達到了25%的開信率。"},{"en":"Personalized email marketing improves click-through rates.","zh-TW":"個人化電子郵件行銷提高了點擊率。"}]', '{"noun":"email marketer"}', NULL, 5, 2346, NULL),
(2347, 'embargo', '/ɪmˈbɑːrɡəʊ/', 'noun', '{"zh-TW":["禁運令；貿易禁令"],"en":["an official ban on trade with a particular country"]}', NULL, 'impose an embargo / lift an embargo', '[{"en":"The government imposed an embargo on the export of technology.","zh-TW":"政府對技術出口實施了禁運令。"},{"en":"Lifting the trade embargo opened new market opportunities.","zh-TW":"解除貿易禁令開闢了新的市場機會。"}]', '{"verb":"embargo"}', NULL, 3, 2347, NULL),
(2348, 'embargo on imports', '/ɪmˈbɑːrɡoʊ ɒn ˈɪmpɔːrts/', 'noun', '{"zh-TW":["進口禁令"],"en":["a government ban on importing specific goods"]}', NULL, 'impose an embargo on imports / lift the embargo on imports', '[{"en":"The embargo on imports was lifted after diplomatic relations improved.","zh-TW":"隨著外交關係改善，進口禁令被解除了。"},{"en":"An embargo on imports was imposed to protect domestic producers.","zh-TW":"為保護國內生產商，進口禁令被實施了。"}]', NULL, NULL, 5, 2348, NULL),
(2349, 'embargo period', '/ɪmˈbɑːrɡoʊ ˌpɪəriəd/', 'noun', '{"zh-TW":["禁止期；封鎖期"],"en":["a period during which specific information or goods cannot be released"]}', NULL, 'observe the embargo period / during the embargo period', '[{"en":"Financial results are under an embargo period before the announcement.","zh-TW":"財務業績在公告前處於禁止期。"},{"en":"Press releases are shared in advance with an embargo period attached.","zh-TW":"新聞稿提前共享，並附有禁止期。"}]', NULL, NULL, 5, 2349, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2350, 'embark', '/ɪmˈbɑːrk/', 'verb', '{"zh-TW":["登船；開始"],"en":["to get on a ship or aircraft"]}', NULL, 'embark on a journey / embark passengers', '[{"en":"Passengers began to embark at noon.","zh-TW":"乘客在中午開始登船。"},{"en":"They embarked on an exciting new adventure.","zh-TW":"他們踏上了令人興奮的新冒險。"}]', '{"noun":"embarkation"}', NULL, 2, 2350, NULL),
(2351, 'embark on', '/''ɪmˌbɑːrk ɒn/', 'phrase', '{"zh-TW":["著手；開始"],"en":["to begin a new journey, project, or endeavor"]}', NULL, 'embark on a journey / embark on a new project / embark on a career', '[{"en":"She decided to embark on a new career in environmental consulting.","zh-TW":"她決定踏上環境諮詢的新職業道路。"},{"en":"The company is embarking on its biggest expansion in a decade.","zh-TW":"公司正在著手進行十年來最大的擴張。"}]', '{"verb":"embark","noun":"embarkation"}', NULL, 3, 2351, NULL),
(2352, 'embarkation', '/ˌɛmbɑːrˈkeɪʃən/', 'noun', '{"zh-TW":["登船；登機"],"en":["the action of getting on a ship or aircraft"]}', NULL, 'embarkation point / embarkation card', '[{"en":"Embarkation will begin at the main gate.","zh-TW":"登船將在主閘口開始。"},{"en":"Please complete the embarkation card before arrival.","zh-TW":"請在抵達前填妥入境卡。"}]', '{"verb":"embark"}', NULL, 4, 2352, NULL),
(2353, 'embarrassed', '/ɪmˈbærəst/', 'adjective', '{"zh-TW":["尷尬的；難為情的"],"en":["feeling ashamed or shy"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"barrass","meaning":"bar/obstruct (阻礙)"},"suffix":{"text":"-ed","meaning":"feeling (感受)"},"logic":"感覺被阻礙住的，即「尷尬的」。"}', 'feel embarrassed / embarrassed about', '[{"en":"He was embarrassed by his mistake.","zh-TW":"他因犯錯而感到尷尬。"},{"en":"She felt embarrassed in front of everyone.","zh-TW":"她在眾人面前感到難為情。"}]', '{"noun":"embarrassment","adjective":"embarrassing","verb":"embarrass"}', NULL, 4, 2353, NULL),
(2354, 'embassy', '/''embəsi/', 'noun', '{"zh-TW":["大使館"],"en":["the official residence or offices of an ambassador"]}', NULL, 'visit an embassy / report to an embassy / embassy staff', '[{"en":"Travelers in trouble abroad should contact their country''s embassy.","zh-TW":"在海外遇到麻煩的旅客應聯繫本國大使館。"},{"en":"She applied for her travel visa at the foreign embassy.","zh-TW":"她在外國大使館申請了旅遊簽證。"}]', '{"adjective":"ambassadorial"}', NULL, 3, 2354, NULL),
(2355, 'embedded system', '/ɪmˈbedɪd ˈsɪstəm/', 'noun', '{"zh-TW":["嵌入式系統"],"en":["a computer system built into a device to perform specific functions"]}', NULL, 'design an embedded system / embedded system firmware / real-time embedded system', '[{"en":"Modern cars contain dozens of embedded systems for various functions.","zh-TW":"現代汽車包含數十個嵌入式系統用於各種功能。"},{"en":"Medical devices rely on reliable embedded systems for patient safety.","zh-TW":"醫療設備依賴可靠的嵌入式系統來確保患者安全。"}]', NULL, NULL, 5, 2355, NULL),
(2356, 'embezzlement', '/ɪmˈbezəlmənt/', 'noun', '{"zh-TW":["侵吞；挪用公款"],"en":["the theft or misappropriation of funds placed in one''s trust"]}', NULL, 'charged with embezzlement / embezzlement of public funds / corporate embezzlement', '[{"en":"The treasurer was convicted of embezzlement after diverting client funds to personal accounts.","zh-TW":"財務主管在將客戶資金轉移到個人帳戶後被判定犯有挪用公款罪。"},{"en":"Embezzlement in the nonprofit sector often goes undetected due to weak internal controls.","zh-TW":"由於內部控制薄弱，非盈利部門的挪用公款行為往往未被發現。"}]', '{"verb":"embezzle","noun2":"embezzler"}', NULL, 4, 2356, NULL),
(2357, 'embrace', '/ɪmˈbreɪs/', 'verb', '{"zh-TW":["擁抱；接受"],"en":["to accept willingly; to hold closely"]}', NULL, 'embrace change/technology', '[{"en":"Companies must embrace new technology.","zh-TW":"企業必須擁抱新技術。"},{"en":"She embraced the opportunity eagerly.","zh-TW":"她熱切地接受了這個機會。"}]', '{"noun":"embrace","verb":"embrace"}', NULL, 3, 2357, NULL),
(2358, 'emerge', '/ɪˈmɜːrdʒ/', 'verb', '{"zh-TW":["出現；浮現"],"en":["to come into view; to become known","to come into view or existence"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"merge","meaning":"dip/plunge (浸入)"},"logic":"從水中浮出，即「出現」。"}', 'emerge as/from; emerge from / emerging market / emerge as', '[{"en":"New competitors are emerging in the market.","zh-TW":"市場上出現了新的競爭者。"},{"en":"The company emerged as a market leader.","zh-TW":"該公司成為市場領導者。"},{"en":"New evidence emerged during the investigation.","zh-TW":"調查期間浮現了新證據。"},{"en":"She emerged as the leading candidate.","zh-TW":"她脫穎而出成為領先的候選人。"}]', '{"noun":"emergence","verb":"emerge","adjective":"emerging/emergent"}', NULL, 2, 2358, NULL),
(2359, 'emergency', '/ɪˈmɜːrdʒənsi/', 'noun', '{"zh-TW":["緊急情況"],"en":["a serious unexpected situation requiring immediate action"]}', NULL, 'in case of emergency', '[{"en":"Call 911 in case of an emergency.","zh-TW":"緊急情況下請撥打911。"},{"en":"An emergency meeting was called.","zh-TW":"召開了緊急會議。"}]', '{"noun":"emergency","adjective":"emergency"}', NULL, 3, 2359, 343),
(2360, 'emergency contact', '/ɪˈmɜːrdʒənsi ˈkɒntækt/', 'noun', '{"zh-TW":["緊急聯絡人"],"en":["a person to be notified in case of an emergency"]}', NULL, 'list an emergency contact / emergency contact form', '[{"en":"Please provide an emergency contact on the registration form.","zh-TW":"請在登記表上提供緊急聯絡人。"},{"en":"The hospital called the patient''s emergency contact.","zh-TW":"醫院聯絡了患者的緊急聯絡人。"}]', NULL, NULL, 5, 2360, NULL),
(2361, 'emergency exit', '/ɪˈmɜːrdʒənsi ˈɛɡzɪt/', 'noun', '{"zh-TW":["緊急出口；安全出口"],"en":["a door used to escape a building in an emergency"]}', NULL, 'locate the emergency exit / emergency exit sign', '[{"en":"Familiarize yourself with the emergency exits upon arrival.","zh-TW":"抵達時請熟悉緊急出口的位置。"},{"en":"Emergency exit signs must be illuminated at all times.","zh-TW":"緊急出口標誌必須始終保持照明。"}]', NULL, NULL, 5, 2361, NULL),
(2362, 'emergency surgery', '/ɪˈmɜːrdʒənsi ˈsɜːrdʒəri/', 'noun', '{"zh-TW":["緊急手術"],"en":["an operation performed urgently to save a life"]}', NULL, 'undergo emergency surgery / perform emergency surgery', '[{"en":"He underwent emergency surgery after the accident.","zh-TW":"他在事故後接受了緊急手術。"},{"en":"The hospital''s surgical team is available for emergency surgery 24 hours.","zh-TW":"醫院的外科團隊全天24小時提供緊急手術服務。"}]', NULL, NULL, 5, 2362, NULL),
(2363, 'emerging market', '/ɪˈmɜːrdʒɪŋ ˈmɑːrkɪt/', 'noun', '{"zh-TW":["新興市場"],"en":["a developing economy with growing investment potential"]}', NULL, 'invest in emerging markets / expanding into emerging markets', '[{"en":"The fund allocates 30% of assets to emerging markets.","zh-TW":"基金將30%的資產配置到新興市場。"},{"en":"Emerging markets offer high growth but also higher risk.","zh-TW":"新興市場提供高增長但也有更高的風險。"}]', NULL, NULL, 5, 2363, NULL),
(2364, 'emerging markets', '/ɪˈmɜːrdʒɪŋ ˈmɑːrkɪts/', 'noun', '{"zh-TW":["新興市場"],"en":["developing countries whose economies are growing rapidly and becoming more integrated globally"]}', NULL, 'invest in emerging markets / emerging markets growth / emerging markets risk', '[{"en":"Emerging markets offer higher growth potential but also greater volatility for investors.","zh-TW":"新興市場為投資者提供了更高的增長潛力，但也帶來了更大的波動性。"},{"en":"Capital flows to emerging markets accelerated as interest rates fell in developed economies.","zh-TW":"隨著發達經濟體利率下降，資本流向新興市場加速。"}]', NULL, NULL, 5, 2364, NULL),
(2365, 'eminent domain', '/ˈemɪnənt dəˈmeɪn/', 'noun', '{"zh-TW":["徵用權；土地徵收權"],"en":["the government''s power to take private property for public use with compensation"]}', NULL, 'exercise eminent domain / eminent domain proceedings / just compensation for eminent domain', '[{"en":"The government used eminent domain to acquire land for the new highway.","zh-TW":"政府行使徵用權徵收土地用於新高速公路。"},{"en":"Property owners must receive fair compensation when eminent domain is exercised.","zh-TW":"行使徵用權時，財產所有人必須獲得公平補償。"}]', NULL, NULL, 5, 2365, NULL),
(2366, 'emission', '/ɪˈmɪʃən/', 'noun', '{"zh-TW":["排放；排放物"],"en":["the production and discharge of something, especially gas"]}', NULL, 'carbon/greenhouse emissions', '[{"en":"The factory must reduce its carbon emissions.","zh-TW":"工廠必須減少碳排放。"},{"en":"Emission standards are becoming stricter.","zh-TW":"排放標準越來越嚴格。"}]', '{"noun":"emission","verb":"emit"}', NULL, 3, 2366, NULL),
(2367, 'emission reduction', '/ɪˈmɪʃən rɪˈdʌkʃən/', 'noun', '{"zh-TW":["減排；降低排放量"],"en":["the decrease of pollutants released into the atmosphere"]}', NULL, 'achieve emission reductions / emission reduction target', '[{"en":"The government set ambitious emission reduction targets.","zh-TW":"政府設定了雄心勃勃的減排目標。"},{"en":"Emission reduction requires changes in energy use and transport.","zh-TW":"減排需要改變能源使用和交通方式。"}]', NULL, NULL, 5, 2367, NULL),
(2368, 'emissions trading', '/ɪˈmɪʃənz ˈtreɪdɪŋ/', 'noun', '{"zh-TW":["排放交易；碳排放交易"],"en":["a market-based system where companies buy and sell emission permits"]}', NULL, 'emissions trading scheme / international emissions trading / cap-and-trade emissions trading', '[{"en":"Emissions trading creates economic incentives to reduce pollution.","zh-TW":"排放交易為減少污染創造了經濟激勵。"},{"en":"The EU emissions trading system covers aviation and heavy industry.","zh-TW":"歐盟排放交易體系涵蓋航空業和重工業。"}]', NULL, NULL, 5, 2368, NULL),
(2369, 'emotion', '/ɪˈmoʊʃn/', 'noun', '{"zh-TW":["情緒；情感"],"en":["a strong feeling such as joy, anger, or sadness"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"mot","meaning":"move (移動)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"從內心移動出來的感覺，即「情緒」。"}', 'strong emotion / show emotion / mixed emotions', '[{"en":"She couldn''t hide her emotions.","zh-TW":"她無法隱藏自己的情緒。"},{"en":"The movie evoked strong emotions.","zh-TW":"這部電影激發了強烈的情感。"}]', '{"adjective":"emotional","adverb":"emotionally"}', NULL, 3, 2369, NULL),
(2370, 'emotional intelligence', '/''ɪˌməʊʃənəl ɪnˌtelɪdʒəns/', 'noun', '{"zh-TW":["情緒智力；EQ"],"en":["the capacity to be aware of, control, and express one''s emotions and to handle interpersonal relationships empathetically"]}', NULL, 'develop emotional intelligence / high emotional intelligence / benefit of emotional intelligence', '[{"en":"Leaders with high emotional intelligence are better at managing teams and resolving conflicts.","zh-TW":"具有高情緒智力的領導者在管理團隊和解決衝突方面更有能力。"},{"en":"Emotional intelligence is increasingly valued alongside technical skills in the workplace.","zh-TW":"在職場中，情緒智力與技術技能一同越來越受到重視。"}]', '{"adjective":"emotional","noun2":"EQ"}', NULL, 5, 2370, NULL),
(2371, 'empathy', '/ˈempəθi/', 'noun', '{"zh-TW":["同理心"],"en":["the ability to understand and share another''s feelings"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"path","meaning":"feeling (感受)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"進入他人感受中，即「同理心」。"}', 'show empathy / lack of empathy', '[{"en":"A good therapist shows empathy toward patients.","zh-TW":"好的治療師對病人展現同理心。"},{"en":"Empathy is important in building relationships.","zh-TW":"同理心在建立關係中很重要。"}]', '{"adjective":"empathetic","verb":"empathize"}', NULL, 3, 2371, NULL),
(2372, 'emphasis', '/ˈemfəsɪs/', 'noun', '{"zh-TW":["強調；重點"],"en":["special importance given to something"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"phas","meaning":"show (展現)"},"suffix":{"text":"-is","meaning":"state (狀態)"},"logic":"在其中展現出重要性，即「強調」。"}', 'place/put emphasis on; place emphasis on / with emphasis / special emphasis', '[{"en":"The company places great emphasis on quality.","zh-TW":"公司非常重視品質。"},{"en":"There is growing emphasis on sustainability.","zh-TW":"對永續發展的重視日益增長。"},{"en":"The school places emphasis on creative thinking.","zh-TW":"學校強調創意思考。"},{"en":"She spoke with great emphasis.","zh-TW":"她說話時特別加重語氣。"}]', '{"noun":"emphasis","verb":"emphasize","adjective":"emphatic"}', NULL, 3, 2372, NULL),
(2373, 'emphasize', '/ˈɛmfəsaɪz/', 'verb', '{"zh-TW":["強調；重視"],"en":["to give special attention to something"]}', NULL, 'emphasize the importance / emphasize key points', '[{"en":"The manager emphasized the importance of meeting deadlines.","zh-TW":"經理強調了按時完成工作的重要性。"},{"en":"Please emphasize the key benefits in your presentation.","zh-TW":"請在您的簡報中強調主要優勢。"}]', '{"noun":"emphasis","adjective":"emphatic"}', NULL, 3, 2373, NULL),
(2374, 'empirical', '/ɪmˈpɪrɪkəl/', 'adjective', '{"zh-TW":["實證的；以觀察為基礎的"],"en":["based on or verifiable by observation or experience"]}', NULL, 'empirical evidence / empirical study / empirical findings', '[{"en":"The empirical evidence supports the proposed theory.","zh-TW":"實證數據支持所提出的理論。"},{"en":"An empirical approach requires collecting measurable data.","zh-TW":"實證方法需要收集可測量的數據。"}]', '{"adverb":"empirically","noun":"empiricism"}', NULL, 3, 2374, NULL),
(2375, 'empirically', '/ɪmˈpɪrɪkli/', 'adverb', '{"zh-TW":["實證地；憑經驗地"],"en":["in a way based on observation or experience"]}', NULL, 'empirically tested / empirically supported / empirically validated', '[{"en":"The hypothesis was empirically tested across three different populations.","zh-TW":"假設在三個不同的人群中進行了實證測試。"},{"en":"Empirically grounded recommendations carry greater scientific authority.","zh-TW":"實證支持的建議具有更大的科學權威性。"}]', '{"adjective":"empirical","noun":"empiricism"}', NULL, 4, 2375, NULL),
(2376, 'empiricism', '/ɪmˈpɪrɪsɪzəm/', 'noun', '{"zh-TW":["經驗主義；實證論"],"en":["the theory that all knowledge is based on experience and observation"]}', NULL, 'scientific empiricism / philosophical empiricism / principle of empiricism', '[{"en":"Empiricism demands that theories be supported by observable data.","zh-TW":"經驗主義要求理論必須有可觀察的數據支持。"},{"en":"His approach to research was grounded in empiricism.","zh-TW":"他的研究方法以經驗主義為基礎。"}]', '{"adjective":"empiricist"}', NULL, 4, 2376, NULL),
(2377, 'employ', '/ɪmˈplɔɪ/', 'verb', '{"zh-TW":["僱用；使用","雇用；運用"],"en":["to give work to someone; to use","to give work to someone","to make use of"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"ploy","meaning":"fold/use (使用)"},"logic":"把人用進來，即「雇用」。"}', 'employ staff/methods; employ staff / employ a strategy / currently employed', '[{"en":"The company employs over 5,000 people.","zh-TW":"該公司僱用了5000多人。"},{"en":"We employ various strategies to boost sales.","zh-TW":"我們使用各種策略來促進銷售。"},{"en":"The company employs over 500 people.","zh-TW":"公司雇用超過500人。"},{"en":"She employed a new strategy to solve the problem.","zh-TW":"她運用了新策略來解決問題。"}]', '{"noun":"employment/employee/employer","verb":"employ","noun2":"employee","noun3":"employer"}', NULL, 2, 2377, 344),
(2378, 'employee', 'ɛmˈplɔɪiː', 'noun', '{"zh-TW":["員工；雇員","職員"],"en":["a person working for a company","a worker"]}', NULL, 'full-time employee/employee benefits', '[{"en":"Employees must complete safety training.","zh-TW":"員工必須完成安全培訓。"}]', '{"verb":"employ","noun":"employer","adjective":"employed"}', NULL, 3, 2378, 27),
(2379, 'employee benefits', '/ɪmˌplɔɪiː ˈbenɪfɪts/', 'noun', '{"zh-TW":["員工福利"],"en":["non-wage compensation provided to employees in addition to salary"]}', NULL, 'offer employee benefits / enhance employee benefits', '[{"en":"Comprehensive employee benefits helped the company attract top talent.","zh-TW":"全面的員工福利幫助公司吸引了頂尖人才。"},{"en":"Employee benefits include health insurance, pension, and paid leave.","zh-TW":"員工福利包括健康保險、退休金和帶薪假期。"}]', NULL, NULL, 5, 2379, NULL),
(2380, 'employee benefits package', '/ɪmˈplɔɪiː ˈbenɪfɪts ˈpækɪdʒ/', 'noun', '{"zh-TW":["員工福利套餐"],"en":["the collection of non-wage compensations offered to employees in addition to salary"]}', NULL, 'evaluate employee benefits package / competitive employee benefits package', '[{"en":"A comprehensive employee benefits package includes health and retirement plans.","zh-TW":"全面的員工福利套餐包括健康和退休計劃。"},{"en":"A competitive employee benefits package helps attract top candidates.","zh-TW":"有競爭力的員工福利套餐有助於吸引頂尖候選人。"}]', NULL, NULL, 5, 2380, NULL),
(2381, 'employee contract', '/ɪmˈplɔɪiː ˈkɒntrækt/', 'noun', '{"zh-TW":["雇用合約；勞動合約"],"en":["a legally binding agreement between an employer and employee specifying terms of work"]}', NULL, 'issue an employee contract / review the employee contract', '[{"en":"Every new hire must sign an employee contract before starting.","zh-TW":"每位新員工在入職前必須簽署雇用合約。"},{"en":"The employee contract outlines duties, salary, and termination conditions.","zh-TW":"雇用合約概述了職責、薪資和終止條件。"}]', NULL, NULL, 5, 2381, NULL),
(2382, 'employee engagement', '/ɪmˈplɔɪiː ɪnˈɡeɪdʒmənt/', 'noun', '{"zh-TW":["員工投入度；員工參與度"],"en":["the level of enthusiasm and commitment employees have toward their work"]}', NULL, 'measure employee engagement / improve employee engagement / employee engagement survey', '[{"en":"High employee engagement leads to better productivity and retention.","zh-TW":"高員工投入度帶來更好的生產力和留才率。"},{"en":"The annual engagement survey revealed areas for improvement.","zh-TW":"年度投入度調查揭示了需要改進的領域。"}]', '{"verb":"engage","adjective":"engaged"}', NULL, 5, 2382, NULL),
(2383, 'employee engagement survey', '/ɪmˈplɔɪiː ɪnˈɡeɪdʒmənt ˈsɜːrveɪ/', 'noun', '{"zh-TW":["員工敬業度調查"],"en":["a questionnaire measuring how motivated and committed employees are"]}', NULL, 'conduct an employee engagement survey / employee engagement survey results', '[{"en":"The employee engagement survey showed 75% of staff feel valued.","zh-TW":"員工敬業度調查顯示75%的員工感到受重視。"},{"en":"Acting on employee engagement survey results improves retention.","zh-TW":"根據員工敬業度調查結果採取行動改善了留任率。"}]', NULL, NULL, 5, 2383, NULL),
(2384, 'employee handbook', '/ɪmˌplɔɪiː ˈhændbʊk/', 'noun', '{"zh-TW":["員工手冊"],"en":["a document outlining company policies, procedures, and expectations for employees"]}', NULL, 'distribute the employee handbook / update the employee handbook', '[{"en":"New employees receive an employee handbook on their first day.","zh-TW":"新員工在第一天收到員工手冊。"},{"en":"The employee handbook was revised to include the new remote work policy.","zh-TW":"員工手冊修訂納入了新的遠程工作政策。"}]', NULL, NULL, 5, 2384, NULL),
(2385, 'employee stock ownership plan', '/ɪmˈplɔɪiː stɒk ˈoʊnərʃɪp plæn/', 'noun', '{"zh-TW":["員工持股計劃"],"en":["a benefit plan giving employees an ownership interest in the company"]}', NULL, 'implement an employee stock ownership plan / employee stock ownership plan contribution', '[{"en":"An employee stock ownership plan aligns worker interests with company performance.","zh-TW":"員工持股計劃使工人利益與公司績效保持一致。"},{"en":"Employees in the plan benefited from the company''s stock price increase.","zh-TW":"計劃中的員工從公司股價上漲中受益。"}]', '{"abbreviation":"ESOP"}', NULL, 5, 2385, NULL),
(2386, 'employer', 'ɪmˈplɔɪər', 'noun', '{"zh-TW":["雇主；僱主","用人單位"],"en":["a person or company that employs","an organization that hires"]}', NULL, 'current employer/prospective employer', '[{"en":"Please provide your current employer''s details.","zh-TW":"請提供您目前雇主的詳細信息。"}]', '{"verb":"employ","noun":"employment","adjective":"employing"}', NULL, 3, 2386, NULL),
(2387, 'employment agency', '/ɪmˈplɔɪmənt ˈeɪdʒənsi/', 'noun', '{"zh-TW":["職業介紹所；人力仲介"],"en":["a firm that helps match job seekers with employers"]}', NULL, 'use an employment agency / employment agency fee', '[{"en":"The company used an employment agency to fill specialist roles.","zh-TW":"公司通過職業介紹所填補了專業職位。"},{"en":"Employment agencies charge a placement fee based on salary.","zh-TW":"職業介紹所根據薪資收取安置費。"}]', NULL, NULL, 5, 2387, NULL),
(2388, 'employment contract', '/ɪmˈplɔɪmənt ˈkɒntrækt/', 'noun', '{"zh-TW":["僱傭合約；勞動合同"],"en":["a legal agreement between employer and employee outlining terms of work"]}', NULL, 'sign an employment contract / breach of employment contract', '[{"en":"She signed the employment contract before her start date.","zh-TW":"她在入職日期前簽署了僱傭合約。"},{"en":"The employment contract specifies salary, duties, and benefits.","zh-TW":"僱傭合約規定了薪資、職責和福利。"}]', '{"verb":"contract"}', NULL, 5, 2388, NULL),
(2389, 'employment law', '/ɪmˈplɔɪmənt lɔː/', 'noun', '{"zh-TW":["就業法；雇傭法"],"en":["the body of law governing the rights and duties of employers and employees"]}', NULL, 'employment law specialist / comply with employment law / employment law update', '[{"en":"The HR team consulted an employment law expert before the restructuring.","zh-TW":"人力資源團隊在重組前諮詢了就業法專家。"},{"en":"Understanding employment law is essential for all managers.","zh-TW":"了解就業法對所有管理者至關重要。"}]', NULL, NULL, 5, 2389, NULL),
(2390, 'empower', '/ɪmˈpaʊər/', 'verb', '{"zh-TW":["賦予權力；使能夠"],"en":["to give someone authority or confidence"]}', NULL, 'empower employees/women', '[{"en":"The training empowers employees to make decisions.","zh-TW":"培訓賦予員工做決定的能力。"},{"en":"Technology empowers small businesses to compete.","zh-TW":"技術使小企業能夠參與競爭。"}]', '{"noun":"empowerment","verb":"empower"}', NULL, 3, 2390, 737),
(2391, 'empowered', 'ɪmˈpaʊərd', 'adjective', '{"zh-TW":["被授權的；有能力的","賦權的"],"en":["given authority to act","made capable"]}', NULL, 'empowered employees/empowered to decide', '[{"en":"Managers are empowered to make decisions.","zh-TW":"經理們被授權做決定。"}]', '{"verb":"empower","noun":"empowerment"}', NULL, 3, 2391, NULL),
(2392, 'empty', '/ˈɛmpti/', 'adjective', '{"zh-TW":["空的"],"en":["containing nothing; not filled"]}', NULL, 'empty space / empty promise', '[{"en":"The meeting room is empty now.","zh-TW":"會議室現在是空的。"},{"en":"Don''t make empty promises.","zh-TW":"別做空洞的承諾。"}]', '{"adjective":"empty","verb":"empty","noun":"emptiness"}', NULL, 2, 2392, NULL),
(2393, 'emulate', '/ˈemjʊleɪt/', 'verb', '{"zh-TW":["仿效；模仿"],"en":["to match or surpass by imitation; to copy"]}', NULL, 'emulate success / emulate a model / emulate behavior', '[{"en":"New firms often emulate the strategies of industry leaders.","zh-TW":"新公司往往仿效行業領導者的策略。"},{"en":"Students are encouraged to emulate the writing style of great authors.","zh-TW":"學生被鼓勵仿效偉大作家的寫作風格。"}]', '{"noun":"emulation","adjective":"emulative"}', NULL, 3, 2393, NULL),
(2394, 'emulsify', '/''ɪˈmʌlsɪfaɪ/', 'verb', '{"zh-TW":["乳化；使乳化"],"en":["to combine two liquids that normally do not mix, such as oil and water, into a stable mixture"]}', NULL, 'emulsify the sauce / emulsify oil / emulsify with egg yolk', '[{"en":"Whisking egg yolks with oil helps to emulsify the mayonnaise.","zh-TW":"用蛋黃和油攪打有助於乳化美乃滋。"},{"en":"The chef uses lecithin as an emulsifier to create smooth, creamy sauces.","zh-TW":"廚師使用卵磷脂作為乳化劑，製作出順滑奶油般的醬汁。"}]', '{"noun":"emulsification","noun2":"emulsifier"}', NULL, 3, 2394, NULL),
(2395, 'enable', '/ɪˈneɪbəl/', 'verb', '{"zh-TW":["使能夠；啟用"],"en":["to make possible or allow","to make possible or provide the means for"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"able","meaning":"able (能夠)"},"logic":"使其能夠，即「使能夠」。"}', 'enable + 人 + to; enable access / enable growth', '[{"en":"The software enables users to track expenses.","zh-TW":"該軟體使用戶能夠追蹤支出。"},{"en":"This funding will enable further research.","zh-TW":"這筆資金將使進一步研究成為可能。"},{"en":"Technology enables people to work from home.","zh-TW":"科技使人們能在家工作。"},{"en":"The grant enabled her to continue her research.","zh-TW":"這筆補助使她能繼續研究。"}]', '{"verb":"enable","adjective":"enabling"}', NULL, 2, 2395, 345),
(2396, 'enact', '/ɪˈnækt/', 'verb', '{"zh-TW":["制定；頒布"],"en":["to make a bill into law"]}', NULL, 'enact legislation/a policy', '[{"en":"The government enacted new environmental regulations.","zh-TW":"政府制定了新的環境法規。"},{"en":"The law was enacted in 2020.","zh-TW":"該法律於2020年頒布。"}]', '{"noun":"enactment","verb":"enact"}', NULL, 2, 2396, NULL),
(2397, 'enclave', '/ˈenkleɪv/', 'noun', '{"zh-TW":["飛地；孤立地區"],"en":["a territory completely surrounded by another; a group or area distinct from its surroundings"]}', NULL, 'economic enclave / ethnic enclave / cultural enclave', '[{"en":"The industrial enclave offered tax advantages to attract foreign manufacturers.","zh-TW":"工業特區提供稅收優惠以吸引外國製造商。"},{"en":"The immigrant community formed a tight-knit cultural enclave in the city center.","zh-TW":"移民社區在市中心形成了一個緊密的文化飛地。"}]', NULL, NULL, 3, 2397, NULL),
(2398, 'enclosed', '/ɪnˈkləʊzd/', 'adjective', '{"zh-TW":["附件的；附上的"],"en":["included with a letter or document"]}', NULL, 'please find enclosed / enclosed herewith', '[{"en":"Please find enclosed a copy of the invoice.","zh-TW":"請查閱附件中的發票副本。"},{"en":"A brochure is enclosed for your reference.","zh-TW":"附上一份宣傳冊供您參考。"}]', '{"verb":"enclose","noun":"enclosure"}', NULL, 3, 2398, 111),
(2399, 'encompass', '/''ɪnˌkʌmpəs/', 'verb', '{"zh-TW":["包含；涵蓋；包括"],"en":["to surround and have or hold within; to include or cover a wide range of"]}', NULL, 'encompass a range / encompass all aspects / broadly encompass', '[{"en":"The new policy encompasses all aspects of workplace safety.","zh-TW":"新政策涵蓋了工作場所安全的所有方面。"},{"en":"The course encompasses both theoretical knowledge and practical skills.","zh-TW":"這門課程同時涵蓋了理論知識和實踐技能。"}]', '{"noun":"encompassment","adjective":"encompassing"}', NULL, 3, 2399, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2400, 'encompassing', '/''ɪnˌkʌmpəsɪŋ/', 'adjective', '{"zh-TW":["包羅萬象的；涵蓋廣泛的"],"en":["covering or including a large range of things; comprehensive"]}', NULL, 'all-encompassing / broad and encompassing / encompassing framework', '[{"en":"The new policy is all-encompassing and covers every aspect of employee conduct.","zh-TW":"新政策包羅萬象，涵蓋了員工行為的方方面面。"},{"en":"She developed an encompassing theory that drew from multiple disciplines.","zh-TW":"她發展了一個從多個學科汲取靈感的涵蓋廣泛的理論。"}]', '{"verb":"encompass","adverb":"encompassingly"}', NULL, 4, 2400, NULL),
(2401, 'encounter', '/ɪnˈkaʊntər/', 'verb / noun', '{"zh-TW":["遭遇；碰到","遭遇；偶遇"],"en":["to unexpectedly meet or face","to unexpectedly meet or face something"]}', '{"prefix":{"text":"en-","meaning":"in (在)"},"root":{"text":"counter","meaning":"against (對面)"},"logic":"在對面碰上，即「遭遇」。"}', 'encounter difficulties/problems; encounter problems / encounter difficulties', '[{"en":"We encountered several problems during installation.","zh-TW":"我們在安裝過程中遇到了幾個問題。"},{"en":"It was her first encounter with the CEO.","zh-TW":"這是她第一次與執行長碰面。"},{"en":"We encountered several problems along the way.","zh-TW":"我們一路上遇到了幾個問題。"},{"en":"I encountered an old friend at the airport.","zh-TW":"我在機場偶遇一位老朋友。"}]', '{"noun":"encounter","verb":"encounter"}', NULL, 3, 2401, NULL),
(2402, 'encourage', '/ɪnˈkɜːrɪdʒ/', 'verb', '{"zh-TW":["鼓勵；促進"],"en":["to give support or confidence"]}', NULL, 'encourage + 人 + to', '[{"en":"The manager encouraged her team to innovate.","zh-TW":"經理鼓勵她的團隊創新。"},{"en":"Low interest rates encourage borrowing.","zh-TW":"低利率鼓勵借貸。"}]', '{"noun":"encouragement","verb":"encourage","adjective":"encouraging"}', NULL, 3, 2402, 112),
(2403, 'encouragement', 'ɪnˈkɜːrɪdʒmənt', 'noun', '{"zh-TW":["鼓勵；激勵","支持"],"en":["support that motivates action","words that inspire confidence"]}', NULL, 'offer encouragement/positive encouragement', '[{"en":"Her encouragement helped the team succeed.","zh-TW":"她的鼓勵幫助團隊成功。"}]', '{"verb":"encourage","adjective":"encouraging","adverb":"encouragingly"}', NULL, 5, 2403, NULL),
(2404, 'encroachment', '/ɪnˈkrəʊtʃmənt/', 'noun', '{"zh-TW":["侵佔；侵犯"],"en":["the act of gradually going beyond proper limits; intrusion"]}', NULL, 'urban encroachment / encroachment on rights / land encroachment', '[{"en":"Coastal development resulted in encroachment on protected wetlands.","zh-TW":"沿海開發導致侵佔受保護的濕地。"},{"en":"The court ruled the fence construction was an encroachment on neighboring property.","zh-TW":"法院裁定建造圍欄是對鄰近房產的侵佔。"}]', '{"verb":"encroach","adjective":"encroaching"}', NULL, 4, 2404, NULL),
(2405, 'encryption', '/ɪnˈkrɪpʃən/', 'noun', '{"zh-TW":["加密"],"en":["the process of converting data into a secret code"]}', NULL, 'data encryption / end-to-end encryption', '[{"en":"The message uses end-to-end encryption.","zh-TW":"訊息使用端對端加密。"},{"en":"Encryption protects your data.","zh-TW":"加密保護你的資料。"}]', '{"verb":"encrypt","adjective":"encrypted"}', NULL, 4, 2405, NULL),
(2406, 'encumber', '/ɪnˈkʌmbər/', 'verb', '{"zh-TW":["抵押；使負擔"],"en":["to restrict property or assets with a debt or mortgage"]}', NULL, 'encumber an asset / encumber property / encumber a title', '[{"en":"The property was encumbered with a first and second mortgage.","zh-TW":"該財產被第一和第二抵押貸款抵押。"},{"en":"Do not encumber key assets without board approval.","zh-TW":"未經董事會批准不得抵押關鍵資產。"}]', '{"noun":"encumbrance","adjective":"encumbered"}', NULL, 3, 2406, NULL),
(2407, 'encumbrance', '/ɪnˈkʌmbrəns/', 'noun', '{"zh-TW":["負擔；抵押債務"],"en":["a claim, lien, or liability attached to an asset or property"]}', NULL, 'check for encumbrances / clear encumbrances', '[{"en":"The property was sold free of all encumbrances.","zh-TW":"房產以無任何負擔的方式出售了。"},{"en":"The title search revealed an outstanding encumbrance on the land.","zh-TW":"產權搜索揭示了土地上的未清償抵押債務。"}]', '{"verb":"encumber","adjective":"encumbered"}', NULL, 4, 2407, NULL),
(2408, 'end', '/ɛnd/', 'noun', '{"zh-TW":["結束；末端"],"en":["the final part","to finish"]}', NULL, 'at the end / end up', '[{"en":"At the end of the month, we review performance.","zh-TW":"月底我們會檢討績效。"},{"en":"The contract ends next year.","zh-TW":"合約明年到期。"}]', '{"noun":"end","verb":"end","adjective":"endless","noun2":"ending"}', NULL, 1, 2408, NULL),
(2409, 'end of contract', '/end əv ˈkɒntrækt/', 'noun', '{"zh-TW":["合約期滿"],"en":["the conclusion of a fixed-term employment or service agreement"]}', NULL, 'notify at end of contract / end of contract procedures', '[{"en":"She received a bonus at the end of her three-year contract.","zh-TW":"她在三年合約期滿時收到了獎金。"},{"en":"End of contract procedures include final settlement and document return.","zh-TW":"合約期滿程序包括最終結算和文件歸還。"}]', NULL, NULL, 5, 2409, NULL),
(2410, 'end user', '/end ˈjuːzər/', 'noun', '{"zh-TW":["最終用戶；終端用戶"],"en":["the person who ultimately uses a product or service"]}', NULL, 'understand the end user / end user needs', '[{"en":"The software is designed with the end user experience in mind.","zh-TW":"軟體的設計以最終用戶體驗為重心。"},{"en":"Feedback from end users guided the second version of the product.","zh-TW":"最終用戶的反饋指導了產品第二版的開發。"}]', NULL, NULL, 3, 2410, NULL),
(2411, 'end-of-day balance', '/end əv deɪ ˈbæləns/', 'noun', '{"zh-TW":["日終餘額"],"en":["the account balance recorded at the close of a business day"]}', NULL, 'check end-of-day balance / report end-of-day balance', '[{"en":"The bank sends an automated end-of-day balance notification.","zh-TW":"銀行發送自動化的日終餘額通知。"},{"en":"Treasury monitors the end-of-day balance to plan overnight financing.","zh-TW":"財務部門監控日終餘額以計劃隔夜融資。"}]', NULL, NULL, 5, 2411, NULL),
(2412, 'end-of-year report', '/end əv jɪər rɪˈpɔːrt/', 'noun', '{"zh-TW":["年終報告"],"en":["a comprehensive summary of activities and performance for the full fiscal year"]}', NULL, 'prepare an end-of-year report / review the end-of-year report', '[{"en":"The end-of-year report highlighted key achievements and areas for improvement.","zh-TW":"年終報告強調了主要成就和改進領域。"},{"en":"Stakeholders use the end-of-year report to assess overall organizational performance.","zh-TW":"利益相關者使用年終報告評估整體組織績效。"}]', NULL, NULL, 5, 2412, NULL),
(2413, 'end-of-year review', '/end əv jɪər rɪˈvjuː/', 'noun', '{"zh-TW":["年終審查；年度回顧"],"en":["an evaluation of performance and results at the end of a fiscal year"]}', NULL, 'conduct an end-of-year review / prepare for end-of-year review', '[{"en":"The end-of-year review identified areas for improvement in Q1.","zh-TW":"年終審查識別了第一季度的改進領域。"},{"en":"All departments submitted end-of-year review reports by December 31.","zh-TW":"所有部門在12月31日前提交了年終審查報告。"}]', NULL, NULL, 5, 2413, NULL),
(2414, 'end-to-end', '/''end tə end/', 'adjective', '{"zh-TW":["端到端的；全流程的"],"en":["covering all stages of a process from beginning to end; encompassing the entire system"]}', NULL, 'end-to-end solution / end-to-end process / end-to-end visibility', '[{"en":"The platform provides an end-to-end solution for managing the entire supply chain.","zh-TW":"該平台為管理整個供應鏈提供了端到端的解決方案。"},{"en":"End-to-end visibility in logistics helps companies track shipments at every stage.","zh-TW":"物流中的端到端可見性幫助公司在每個階段追蹤貨物。"}]', '{"adverb":"end-to-end"}', NULL, 4, 2414, NULL),
(2415, 'endangered species', '/ɪnˈdeɪndʒərd ˈspiːʃiːz/', 'noun', '{"zh-TW":["瀕危物種"],"en":["a species at risk of becoming extinct"]}', NULL, 'protect endangered species / list of endangered species', '[{"en":"Polar bears are classified as an endangered species.","zh-TW":"北極熊被列為瀕危物種。"},{"en":"Conservation programs help protect endangered species.","zh-TW":"保育計劃有助於保護瀕危物種。"}]', NULL, NULL, 5, 2415, NULL),
(2416, 'endemic', '/enˈdemɪk/', 'adjective', '{"zh-TW":["地方性的；特有的；流行性的"],"en":["regularly found among a particular group or area; widespread in a community"]}', NULL, 'endemic disease / endemic poverty / endemic corruption', '[{"en":"Malaria remains endemic in many tropical regions despite control efforts.","zh-TW":"儘管進行了控制工作，瘧疾在許多熱帶地區仍然是地方病。"},{"en":"Endemic corruption erodes public trust in government institutions.","zh-TW":"地方性腐敗侵蝕了公眾對政府機構的信任。"}]', '{"noun":"endemism","adverb":"endemically"}', NULL, 3, 2416, NULL),
(2417, 'endocrinologist', '/ˌendəʊkrɪˈnɒlədʒɪst/', 'noun', '{"zh-TW":["內分泌科醫師"],"en":["a specialist in disorders of the endocrine system and hormones"]}', NULL, 'consult an endocrinologist / qualified endocrinologist / referred to an endocrinologist', '[{"en":"The endocrinologist managed the patient''s thyroid disorder.","zh-TW":"內分泌科醫師管理患者的甲狀腺疾病。"},{"en":"Hormonal imbalances often require the expertise of an endocrinologist.","zh-TW":"荷爾蒙失衡通常需要內分泌科醫師的專業知識。"}]', NULL, NULL, 5, 2417, NULL),
(2418, 'endogenous', '/enˈdɒdʒɪnəs/', 'adjective', '{"zh-TW":["內源性的；內生的"],"en":["originating from within a system or organism"]}', NULL, 'endogenous growth / endogenous variable / endogenous factor', '[{"en":"Endogenous growth theory argues that innovation drives long-term growth.","zh-TW":"內生增長理論認為創新推動長期增長。"},{"en":"The model distinguishes between endogenous and exogenous variables.","zh-TW":"模型區分了內生和外生變量。"}]', '{"adverb":"endogenously","antonym":"exogenous"}', NULL, 4, 2418, NULL),
(2419, 'endorphin', '/''endɔːrfɪn/', 'noun', '{"zh-TW":["腦內啡；內啡肽"],"en":["a chemical released in the brain during exercise that relieves pain and creates feelings of pleasure"]}', NULL, 'release endorphins / endorphin rush / natural endorphin', '[{"en":"Exercise releases endorphins that naturally boost mood and reduce stress.","zh-TW":"運動會釋放腦內啡，自然地提升情緒並減輕壓力。"},{"en":"The endorphin rush after a long run is sometimes called the ''runner''s high.''","zh-TW":"長跑後的腦內啡湧現有時被稱為「跑者的愉悅感」。"}]', NULL, NULL, 3, 2419, NULL),
(2420, 'endorse', '/ɪnˈdɔːrs/', 'verb', '{"zh-TW":["背書；認可"],"en":["to publicly approve or support"]}', NULL, 'endorse a product/candidate', '[{"en":"Several celebrities endorsed the brand.","zh-TW":"多位名人為該品牌背書。"},{"en":"The board endorsed the new strategy.","zh-TW":"董事會認可了新策略。"}]', '{"noun":"endorsement","verb":"endorse"}', NULL, 3, 2420, 867),
(2421, 'endorsement', '/ɪnˈdɔːrsmənt/', 'noun', '{"zh-TW":["代言；背書"],"en":["public approval or support given by a prominent person or organization"]}', NULL, 'celebrity endorsement / brand endorsement / endorsement deal', '[{"en":"The athlete''s endorsement boosted product sales by 40%.","zh-TW":"這位運動員的代言使產品銷售額提升了40%。"},{"en":"An official endorsement from an industry body builds credibility.","zh-TW":"行業機構的官方背書建立了可信度。"}]', '{"verb":"endorse","noun":"endorser"}', NULL, 4, 2421, 781),
(2422, 'endorsement fee', '/ɪnˈdɔːrsmənt fiː/', 'noun', '{"zh-TW":["代言費；背書費"],"en":["payment made to a person or organization for promoting a product"]}', NULL, 'negotiate endorsement fees / pay endorsement fees', '[{"en":"The athlete earned a substantial endorsement fee for the campaign.","zh-TW":"運動員為廣告活動賺取了可觀的代言費。"},{"en":"Endorsement fees are a significant part of celebrity income.","zh-TW":"代言費是名人收入的重要組成部分。"}]', NULL, NULL, 5, 2422, NULL),
(2423, 'endorsement letter', '/ɪnˈdɔːrsmənt ˈlɛtər/', 'noun', '{"zh-TW":["推薦函；背書信"],"en":["a letter recommending a person or product"]}', NULL, 'write an endorsement letter / receive an endorsement letter', '[{"en":"The professor provided an endorsement letter for the scholarship.","zh-TW":"教授為獎學金申請提供了推薦函。"},{"en":"An endorsement letter from a client strengthens the proposal.","zh-TW":"來自客戶的背書信加強了提案。"}]', NULL, NULL, 5, 2423, NULL),
(2424, 'endowment', '/ɪnˈdaʊmənt/', 'noun', '{"zh-TW":["捐贈基金；捐款"],"en":["a fund or gift made to an institution for a specific purpose"]}', NULL, 'endowment fund / university endowment / establish an endowment', '[{"en":"The university endowment funds research and scholarships.","zh-TW":"大學捐贈基金支持研究和獎學金。"},{"en":"She made a substantial endowment to the hospital foundation.","zh-TW":"她向醫院基金會捐贈了一大筆款項。"}]', '{"verb":"endow"}', NULL, 3, 2424, NULL),
(2425, 'endurance', '/''ɪnˈdjʊərəns/', 'noun', '{"zh-TW":["耐力；持久力"],"en":["the ability to sustain prolonged physical or mental effort"]}', NULL, 'build endurance / test endurance / endurance training', '[{"en":"Marathon runners spend months building their endurance before race day.","zh-TW":"馬拉松跑者在比賽日前花幾個月時間訓練耐力。"},{"en":"Mental endurance is just as important as physical endurance in competitive sports.","zh-TW":"在競技運動中，精神耐力與體能耐力同樣重要。"}]', '{"adjective":"enduring","verb":"endure"}', NULL, 3, 2425, NULL),
(2426, 'endurance sport', '/''enˌdjʊərəns spɔːrt/', 'noun', '{"zh-TW":["耐力運動"],"en":["a type of sport that requires sustained physical effort over a long period, such as marathon running or cycling"]}', NULL, 'participate in endurance sports / endurance sport training / popular endurance sport', '[{"en":"Marathon running is one of the most demanding endurance sports in the world.","zh-TW":"馬拉松是世界上最具挑戰性的耐力運動之一。"},{"en":"Training for endurance sports requires both physical conditioning and mental toughness.","zh-TW":"訓練耐力運動既需要體能調整，也需要心理韌性。"}]', '{"noun":"endurance"}', NULL, 5, 2426, NULL),
(2427, 'enemy', '/ˈɛnəmi/', 'noun', '{"zh-TW":["敵人；敵方"],"en":["a person who is hostile to another"]}', NULL, 'worst enemy / make enemies', '[{"en":"Procrastination is your worst enemy.","zh-TW":"拖延是你最大的敵人。"},{"en":"Don''t make enemies in the industry.","zh-TW":"別在業界樹敵。"}]', '{"noun":"enemy","noun2":"enmity"}', NULL, 2, 2427, NULL),
(2428, 'energy', 'ˈɛnərdʒi', 'noun', '{"zh-TW":["能量；精力","能源"],"en":["the capacity to do work","enthusiasm and vitality"]}', NULL, 'renewable energy/full of energy', '[{"en":"The company is shifting to renewable energy.","zh-TW":"公司正在轉向可再生能源。"}]', '{"adjective":"energetic","adverb":"energetically"}', NULL, 2, 2428, NULL),
(2429, 'energy efficiency', '/ˈɛnərdʒi ɪˈfɪʃənsi/', 'noun', '{"zh-TW":["能源效率"],"en":["using less energy to provide the same level of service"]}', NULL, 'improve energy efficiency / energy efficiency standard', '[{"en":"New appliances are designed for greater energy efficiency.","zh-TW":"新家電的設計旨在提高能源效率。"},{"en":"Energy efficiency reduces both costs and environmental impact.","zh-TW":"能源效率降低了成本和環境影響。"}]', '{"adjective":"energy-efficient","adverb":"efficiently"}', NULL, 5, 2429, NULL),
(2430, 'enforce', '/ɪnˈfɔːrs/', 'verb', '{"zh-TW":["執行；強制","執行；強制實施"],"en":["to compel compliance with a law or rule","to make sure a law or rule is obeyed"]}', NULL, 'enforce regulations/rules; enforce the law / strictly enforced', '[{"en":"The police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The contract will be strictly enforced.","zh-TW":"合約將被嚴格執行。"},{"en":"Police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The rules are strictly enforced.","zh-TW":"規則被嚴格執行。"}]', '{"noun":"enforcement","verb":"enforce","adjective":"enforceable"}', NULL, 3, 2430, 677),
(2431, 'enforceable', '/ɪnˈfɔːrsəbəl/', 'adjective', '{"zh-TW":["可執行的；有法律效力的"],"en":["legally valid and capable of being enforced by courts"]}', NULL, 'legally enforceable / enforceable contract / make enforceable', '[{"en":"The agreement must be written to be legally enforceable.","zh-TW":"協議必須以書面形式才具有法律執行力。"},{"en":"Not all verbal agreements are enforceable in court.","zh-TW":"並非所有口頭協議都在法庭上具有可執行性。"}]', '{"verb":"enforce","noun":"enforcement"}', NULL, 4, 2431, NULL),
(2432, 'enforcement mechanism', '/ɪnˈfɔːrsmənt ˈmekənɪzəm/', 'noun', '{"zh-TW":["執行機制"],"en":["a system of rules and consequences ensuring compliance"]}', NULL, 'effective enforcement mechanism / weak enforcement mechanism / create an enforcement mechanism', '[{"en":"An effective enforcement mechanism is essential for regulatory compliance.","zh-TW":"有效的執行機制對法規遵循至關重要。"},{"en":"International agreements often lack binding enforcement mechanisms.","zh-TW":"國際協議往往缺乏具有約束力的執行機制。"}]', NULL, NULL, 5, 2432, NULL),
(2433, 'engage', '/ɪnˈɡeɪdʒ/', 'verb', '{"zh-TW":["【主要意義-動詞】吸引（注意力）；使參與","【次要意義-動詞】雇用；聘請（正式）","【次要意義-動詞】（齒輪/機器）嚙合；接合","【次要意義-動詞】與……交涉；與……接觸"],"en":["[primary] to attract and keep attention; to involve someone","[secondary] to hire or employ someone for a specific purpose","[secondary] to connect mechanical parts together; to put into gear","[secondary] to enter into discussion or conflict with someone"]}', '{"prefix":{"text":"en-","meaning":"in (進入)"},"root":{"text":"gage","meaning":"pledge (承諾)"},"logic":"進入承諾參與，即「參與」。"}', 'engage a consultant / engage with stakeholders / engage the clutch / fully engaged', '[{"en":"The company engaged a top law firm to handle the acquisition.","zh-TW":"公司聘請了一家頂級律師事務所來處理此次收購。"},{"en":"Management must engage with employees to address the low morale issue.","zh-TW":"管理層必須與員工進行溝通，以解決士氣低落的問題。"},{"en":"The new campaign effectively engages customers through interactive content.","zh-TW":"新活動通過互動內容有效地吸引了客戶。"}]', '{"noun":"engagement","adjective":"engaging"}', '動詞 engage = 「聘請」（engage a consultant = 聘請顧問）是正式書面英語用法，engage with（與……接觸/溝通）是 TOEIC 商業和管理文章的高頻表達，考生常誤以為只有「吸引注意力」的意思。', 2, 2433, 346),
(2434, 'engaged', 'ɪnˈɡeɪdʒd', 'adjective', '{"zh-TW":["投入的；積極的","參與的"],"en":["busy with or involved in","committed to work"]}', NULL, 'highly engaged/employee engaged', '[{"en":"Engaged employees are more productive.","zh-TW":"積極投入的員工更有生產力。"}]', '{"verb":"engage","noun":"engagement"}', NULL, 3, 2434, NULL),
(2435, 'engagement', '/ɪnˈɡeɪdʒmənt/', 'noun', '{"zh-TW":["互動；參與度"],"en":["interactions such as likes, comments, shares, and clicks on content"]}', NULL, 'social media engagement / engagement rate / increase engagement', '[{"en":"High engagement on the post signaled strong audience interest.","zh-TW":"貼文上的高互動率表明了強烈的受眾興趣。"},{"en":"Video content typically drives higher engagement than static images.","zh-TW":"視頻內容通常比靜態圖片產生更高的互動率。"}]', '{"verb":"engage","adjective":"engaging"}', NULL, 4, 2435, 557),
(2436, 'engagement rate', '/ɪnˈɡeɪdʒmənt reɪt/', 'noun', '{"zh-TW":["互動率；參與率"],"en":["the level of interaction an audience has with content or a brand"]}', NULL, 'measure engagement rate / high engagement rate / improve engagement', '[{"en":"The Instagram post had an engagement rate of 8%.","zh-TW":"Instagram貼文的互動率為8%。"},{"en":"Engagement rate is a better measure of audience connection than follower count.","zh-TW":"互動率比追蹤者數量更能衡量受眾連結。"}]', NULL, NULL, 5, 2436, NULL),
(2437, 'engender', '/ɪnˈdʒendər/', 'verb', '{"zh-TW":["引起；產生"],"en":["to cause or give rise to a feeling, situation, or condition"]}', NULL, 'engender trust / engender conflict / engender growth', '[{"en":"Transparent governance policies engender public trust in institutions.","zh-TW":"透明的治理政策能夠在機構中培養公眾信任。"},{"en":"Poor working conditions engender low morale and high staff turnover.","zh-TW":"惡劣的工作條件會引起士氣低落和員工高流失率。"}]', NULL, NULL, 3, 2437, NULL),
(2438, 'engine', '/ˈɛndʒɪn/', 'noun', '{"zh-TW":["引擎；發動機"],"en":["a machine that converts energy into motion"]}', NULL, 'search engine / engine of growth', '[{"en":"Use a search engine to find information.","zh-TW":"使用搜尋引擎查找資訊。"},{"en":"Technology is the engine of growth.","zh-TW":"科技是成長的引擎。"}]', '{"noun":"engine","noun2":"engineer","noun3":"engineering"}', NULL, 2, 2438, NULL),
(2439, 'enhance', '/ɪnˈhæns/', 'verb', '{"zh-TW":["增強；提高","增強；提升"],"en":["to improve the quality or value of","to improve the quality or value of something"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"hance","meaning":"high (高)"},"logic":"使其提高，即「增強」。"}', 'enhance performance/productivity; enhance performance / enhance quality / enhance the experience', '[{"en":"The update will enhance system performance.","zh-TW":"更新將增強系統性能。"},{"en":"Training enhances employee productivity.","zh-TW":"培訓提高員工生產力。"},{"en":"This software enhances image quality.","zh-TW":"這個軟體增強了影像品質。"},{"en":"The new features enhance the user experience.","zh-TW":"新功能提升了使用者體驗。"}]', '{"noun":"enhancement","verb":"enhance"}', NULL, 3, 2439, 113),
(2440, 'enhancement', 'ɪnˈhɑːnsmənt', 'noun', '{"zh-TW":["增強；改善","提升"],"en":["an improvement","making better"]}', NULL, 'product enhancement/service enhancement', '[{"en":"The software update includes several enhancements.","zh-TW":"軟體更新包含幾項改進。"}]', '{"verb":"enhance","adjective":"enhanced"}', NULL, 4, 2440, 558),
(2441, 'enjoy', '/ɪnˈdʒɔɪ/', 'verb', '{"zh-TW":["享受；喜歡"],"en":["to get pleasure from something"]}', NULL, 'enjoy doing / enjoy the benefits', '[{"en":"I enjoy working with this team.","zh-TW":"我喜歡和這個團隊一起工作。"},{"en":"Members enjoy special benefits.","zh-TW":"會員享有特殊福利。"}]', '{"verb":"enjoy","noun":"enjoyment","adjective":"enjoyable"}', NULL, 2, 2441, NULL),
(2442, 'enormous', '/ɪˈnɔːrməs/', 'adjective', '{"zh-TW":["巨大的"],"en":["very large in size, quantity, or extent","very large in size or quantity"]}', '{"prefix":{"text":"e-","meaning":"out (超出)"},"root":{"text":"norm","meaning":"rule/standard (標準)"},"suffix":{"text":"-ous","meaning":"having (具有)"},"logic":"超出正常標準的，即「巨大的」。"}', 'enormous amount/potential; enormous amount / enormous pressure / enormous success', '[{"en":"The project requires an enormous investment.","zh-TW":"該項目需要巨額投資。"},{"en":"There is enormous potential for growth.","zh-TW":"有巨大的增長潛力。"},{"en":"The project requires an enormous amount of work.","zh-TW":"這個專案需要大量的工作。"},{"en":"The concert was an enormous success.","zh-TW":"音樂會獲得了巨大的成功。"}]', '{"adjective":"enormous","adverb":"enormously"}', NULL, 3, 2442, NULL),
(2443, 'enough', '/ɪˈnʌf/', 'adjective', '{"zh-TW":["足夠的"],"en":["as much as is needed"]}', NULL, 'good enough / not enough', '[{"en":"We don''t have enough staff for this project.","zh-TW":"我們沒有足夠的人手做這個專案。"},{"en":"Is this good enough?","zh-TW":"這樣夠好嗎？"}]', '{"adjective":"enough","adverb":"enough"}', NULL, 2, 2443, NULL),
(2444, 'enroll', '/ɪnˈroʊl/', 'verb', '{"zh-TW":["註冊；登記","註冊；入學"],"en":["to officially register for a course or program","to officially join a course or school"]}', NULL, 'enroll in a course/program; enroll in / enrollment period', '[{"en":"Over 500 students enrolled in the program.","zh-TW":"超過500名學生註冊了該計畫。"},{"en":"You can enroll online.","zh-TW":"你可以在線上註冊。"},{"en":"She enrolled in a language course.","zh-TW":"她報名了一門語言課程。"},{"en":"Over 500 students enrolled this year.","zh-TW":"今年有超過500名學生入學。"}]', '{"noun":"enrollment","verb":"enroll"}', NULL, 2, 2444, NULL),
(2445, 'enrollment', '/ɪnˈrəʊlmənt/', 'noun', '{"zh-TW":["入學；註冊"],"en":["the act of registering for a course or school"]}', NULL, 'enrollment period / course enrollment', '[{"en":"Enrollment for the spring semester begins in January.","zh-TW":"春季學期的入學從一月開始。"},{"en":"The school saw a 10% increase in enrollment this year.","zh-TW":"學校今年的入學人數增加了10%。"}]', '{"verb":"enroll","adjective":"enrolled"}', NULL, 4, 2445, 347),
(2446, 'ensure', '/ɪnˈʃʊr/', 'verb', '{"zh-TW":["確保"],"en":["to make certain that something happens"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"sure","meaning":"sure (確定)"},"logic":"使其確定，即「確保」。"}', 'ensure quality/safety; ensure quality / ensure safety / ensure that', '[{"en":"Please ensure all data is backed up.","zh-TW":"請確保所有資料都已備份。"},{"en":"We must ensure customer satisfaction.","zh-TW":"我們必須確保客戶滿意度。"},{"en":"Please ensure all doors are locked.","zh-TW":"請確保所有門都已上鎖。"},{"en":"We must ensure the safety of our employees.","zh-TW":"我們必須確保員工的安全。"}]', '{"verb":"ensure"}', NULL, 2, 2446, 114),
(2447, 'enter', '/ˈɛntər/', 'verb', '{"zh-TW":["進入；輸入"],"en":["to go into a place","to type data"]}', NULL, 'enter the market / enter data', '[{"en":"They plan to enter the Asian market.","zh-TW":"他們計畫進入亞洲市場。"},{"en":"Please enter your password.","zh-TW":"請輸入你的密碼。"}]', '{"verb":"enter","noun":"entrance","noun2":"entry"}', NULL, 2, 2447, NULL),
(2448, 'enterprise', '/ˈentərpraɪz/', 'noun', '{"zh-TW":["企業；事業"],"en":["a business or company; a bold undertaking"]}', NULL, 'private/state enterprise', '[{"en":"Small enterprises drive economic growth.","zh-TW":"小型企業推動經濟增長。"},{"en":"The new enterprise launched last quarter.","zh-TW":"新企業上季度啟動了。"}]', '{"noun":"enterprise","adjective":"enterprising"}', NULL, 4, 2448, 348),
(2449, 'enterprise resource planning', '/ˈentərpraɪz rɪˈsɔːrs ˈplænɪŋ/', 'noun', '{"zh-TW":["企業資源規劃"],"en":["integrated software managing core business processes across departments"]}', NULL, 'implement ERP / ERP system / ERP migration', '[{"en":"The ERP system connects finance, HR, and supply chain in one platform.","zh-TW":"ERP系統將財務、人力資源和供應鏈連接在一個平台上。"},{"en":"Implementing ERP reduced data duplication and improved reporting.","zh-TW":"實施ERP減少了資料重複並改善了報告。"}]', '{"abbreviation":"ERP"}', NULL, 5, 2449, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2450, 'enterprise value', '/ˈentərpraɪz ˈvæljuː/', 'noun', '{"zh-TW":["企業價值"],"en":["the total value of a company including equity and net debt"]}', NULL, 'calculate enterprise value / enterprise value multiple', '[{"en":"The enterprise value of the target company was estimated at $2 billion.","zh-TW":"目標公司的企業價值估計為20億元。"},{"en":"Enterprise value is used in M&A to price takeover bids.","zh-TW":"企業價值用於併購中的收購出價定價。"}]', '{"abbreviation":"EV"}', NULL, 5, 2450, NULL),
(2451, 'entertainment', '/ˌɛntərˈteɪnmənt/', 'noun', '{"zh-TW":["娛樂"],"en":["activities for enjoyment"]}', NULL, 'entertainment industry / live entertainment', '[{"en":"The hotel offers nightly entertainment.","zh-TW":"飯店每晚提供娛樂節目。"},{"en":"The entertainment industry is growing.","zh-TW":"娛樂產業正在成長。"}]', '{"verb":"entertain","noun2":"entertainer","adjective":"entertaining"}', NULL, 5, 2451, NULL),
(2452, 'enthusiastic', '/ɪnˌθjuːziˈæstɪk/', 'adjective', '{"zh-TW":["熱情的；熱心的"],"en":["showing intense enjoyment or interest"]}', '{"prefix":{"text":"en-","meaning":"in (在內)"},"root":{"text":"thusi","meaning":"god (神)"},"suffix":{"text":"-astic","meaning":"relating to (相關的)"},"logic":"如同有神靈附體般的熱情。"}', 'enthusiastic about / enthusiastic response', '[{"en":"She is enthusiastic about her new job.","zh-TW":"她對新工作充滿熱情。"},{"en":"The audience gave an enthusiastic response.","zh-TW":"觀眾給予熱烈回應。"}]', '{"noun":"enthusiasm","adverb":"enthusiastically"}', NULL, 4, 2452, NULL),
(2453, 'entire', '/ɪnˈtaɪər/', 'adjective', '{"zh-TW":["整個的；全部的"],"en":["whole; complete","with no part left out; whole"]}', '{"prefix":{"text":"in-","meaning":"not (不)"},"root":{"text":"tire","meaning":"touch/diminish (觸及/削減)"},"logic":"未被削減的，即「完整的」。"}', 'the entire team/process; the entire team / the entire day / in its entirety', '[{"en":"The entire team was present at the meeting.","zh-TW":"整個團隊都出席了會議。"},{"en":"She spent the entire day on the report.","zh-TW":"她花了一整天在報告上。"},{"en":"The entire team worked overtime.","zh-TW":"整個團隊加班工作。"},{"en":"She read the entire book in one day.","zh-TW":"她一天內讀完了整本書。"}]', '{"adjective":"entire","adverb":"entirely","noun":"entirety"}', NULL, 2, 2453, 115),
(2454, 'entitle', '/ɪnˈtaɪtəl/', 'verb', '{"zh-TW":["賦予權利；命名"],"en":["to give someone the right to do something"]}', NULL, 'be entitled to', '[{"en":"Full-time staff are entitled to 20 days of leave.","zh-TW":"全職員工有權享有20天假期。"},{"en":"The book is entitled ''Modern Management''.","zh-TW":"這本書名為《現代管理》。"}]', '{"noun":"entitlement","verb":"entitle","adjective":"entitled"}', NULL, 3, 2454, NULL),
(2455, 'entitlement', '/ɪnˈtaɪtəlmənt/', 'noun', '{"zh-TW":["權利；應得福利"],"en":["a benefit that an employee has a right to receive"]}', NULL, 'leave entitlement / statutory entitlement / entitlement to benefits', '[{"en":"All employees have a minimum leave entitlement of 14 days.","zh-TW":"所有員工享有最低14天的假期權利。"},{"en":"She checked her entitlement to overtime pay.","zh-TW":"她查詢了她的加班費權利。"}]', '{"verb":"entitle","adjective":"entitled"}', NULL, 4, 2455, 559),
(2456, 'entree', '/ˈɒntreɪ/', 'noun', '{"zh-TW":["主菜"],"en":["the main dish of a meal"]}', NULL, 'entree selection / order an entree', '[{"en":"The entree includes a choice of fish or beef.","zh-TW":"主菜包含魚或牛肉的選擇。"},{"en":"Each entree is served with seasonal vegetables.","zh-TW":"每道主菜配有時令蔬菜。"}]', NULL, NULL, 2, 2456, NULL),
(2457, 'entrepreneur', '/ˌɑːntrəprəˈnɜːr/', 'noun', '{"zh-TW":["企業家；創業者"],"en":["a person who starts and runs a business"]}', NULL, 'successful entrepreneur', '[{"en":"She is a successful entrepreneur in tech.","zh-TW":"她是科技領域的成功企業家。"},{"en":"Entrepreneurs drive innovation.","zh-TW":"企業家推動創新。"}]', '{"noun":"entrepreneur/entrepreneurship","adjective":"entrepreneurial"}', NULL, 4, 2457, NULL),
(2458, 'enumerate', '/ɪˈnjuːməreɪt/', 'verb', '{"zh-TW":["列舉；逐一說明"],"en":["to list or count things individually"]}', NULL, 'enumerate the benefits / enumerate responsibilities', '[{"en":"The contract enumerates all deliverables and payment milestones.","zh-TW":"合約列舉了所有交付成果和付款里程碑。"},{"en":"Please enumerate the risks identified in the assessment.","zh-TW":"請列舉評估中識別的風險。"}]', '{"noun":"enumeration","adjective":"enumerated"}', NULL, 3, 2458, 679),
(2459, 'environment', '/ɪnˈvaɪrənmənt/', 'noun', '{"zh-TW":["環境"],"en":["the natural world; surrounding conditions"]}', NULL, 'work/business environment', '[{"en":"We must protect the environment.","zh-TW":"我們必須保護環境。"},{"en":"A positive work environment boosts morale.","zh-TW":"積極的工作環境提升士氣。"}]', '{"noun":"environment/environmentalist","adjective":"environmental","adverb":"environmentally"}', NULL, 4, 2459, 350),
(2460, 'environmental awareness', '/ɪnˌvaɪrənˈmɛntəl əˈwɛənɪs/', 'noun', '{"zh-TW":["環保意識"],"en":["knowledge and concern about environmental issues"]}', NULL, 'raise environmental awareness / environmental awareness campaign', '[{"en":"The school launched a campaign to raise environmental awareness.","zh-TW":"學校發起了一場提升環保意識的活動。"},{"en":"Environmental awareness drives consumer demand for green products.","zh-TW":"環保意識推動消費者對綠色產品的需求。"}]', NULL, NULL, 5, 2460, NULL),
(2461, 'environmental compliance', '/ɪnˌvaɪrənˈmentəl kəmˈplaɪəns/', 'noun', '{"zh-TW":["環境合規"],"en":["adherence to environmental laws, regulations, and standards"]}', NULL, 'ensure environmental compliance / environmental compliance audit', '[{"en":"The plant was fined for failing to meet environmental compliance standards.","zh-TW":"該工廠因未能達到環境合規標準而被罰款。"},{"en":"Regular audits are conducted to verify environmental compliance.","zh-TW":"定期審計用於驗證環境合規性。"}]', NULL, NULL, 5, 2461, NULL),
(2462, 'environmental governance', '/ɪnˌvaɪrənˈmentəl ˈɡʌvənəns/', 'noun', '{"zh-TW":["環境治理"],"en":["the processes and institutions for making and enforcing environmental decisions"]}', NULL, 'strengthen environmental governance / effective environmental governance / environmental governance framework', '[{"en":"Weak environmental governance allows industries to pollute without penalty.","zh-TW":"薄弱的環境治理允許工業在無懲罰的情況下污染。"},{"en":"Good environmental governance requires participation from communities and NGOs.","zh-TW":"良好的環境治理需要社區和非政府組織的參與。"}]', NULL, NULL, 5, 2462, NULL),
(2463, 'environmental impact', '/ɪnˌvaɪrənˈmɛntəl ˈɪmpækt/', 'noun', '{"zh-TW":["環境影響"],"en":["the effect of an activity on the natural environment"]}', NULL, 'assess environmental impact / reduce environmental impact', '[{"en":"Companies must assess the environmental impact of their operations.","zh-TW":"企業必須評估其運營的環境影響。"},{"en":"The construction project''s environmental impact was carefully reviewed.","zh-TW":"建設項目的環境影響受到了仔細審查。"}]', '{"adjective":"environmental","adverb":"environmentally"}', NULL, 5, 2463, NULL),
(2464, 'environmental impact assessment', '/ɪnˌvaɪrənˈmentəl ˈɪmpækt əˈsesmənt/', 'noun', '{"zh-TW":["環境影響評估"],"en":["a process to evaluate the environmental effects of a proposed project"]}', NULL, 'conduct an environmental impact assessment / environmental impact assessment results', '[{"en":"An environmental impact assessment was required before the factory was approved.","zh-TW":"在工廠獲批前需要進行環境影響評估。"},{"en":"The environmental impact assessment identified risks to local water resources.","zh-TW":"環境影響評估確定了對當地水資源的風險。"}]', '{"abbreviation":"EIA"}', NULL, 5, 2464, NULL),
(2465, 'environmental stewardship', '/''ɪnˌvaɪərənˌmentəl ˌstjuːərdˌʃɪp/', 'noun', '{"zh-TW":["環境管理責任；環境守護"],"en":["the responsible management and protection of the natural environment"]}', NULL, 'practice environmental stewardship / corporate environmental stewardship / environmental stewardship program', '[{"en":"Environmental stewardship requires businesses to consider the ecological impact of their operations.","zh-TW":"環境管理責任要求企業考慮其運營的生態影響。"},{"en":"The national park service is committed to environmental stewardship for future generations.","zh-TW":"國家公園服務致力於為後代承擔環境管理責任。"}]', '{"noun":"stewardship","noun2":"steward"}', NULL, 5, 2465, NULL),
(2466, 'epidemiology', '/ˌepɪˌdiːmiˈɒlədʒi/', 'noun', '{"zh-TW":["流行病學"],"en":["the study of how diseases spread and can be controlled in populations"]}', NULL, 'epidemiology study / molecular epidemiology / applied epidemiology', '[{"en":"Epidemiology identifies risk factors and helps design prevention strategies.","zh-TW":"流行病學識別風險因素並幫助設計預防策略。"},{"en":"Contact tracing is a key epidemiology tool in controlling outbreaks.","zh-TW":"接觸追蹤是控制疫情爆發的關鍵流行病學工具。"}]', '{"adjective":"epidemiological","adverb":"epidemiologically"}', NULL, 4, 2466, NULL),
(2467, 'epistemic', '/ˌepɪˈstiːmɪk/', 'adjective', '{"zh-TW":["認識論的；知識的"],"en":["relating to knowledge or the degree of its validation"]}', NULL, 'epistemic uncertainty / epistemic framework / epistemic value', '[{"en":"The study raises epistemic questions about measurement reliability.","zh-TW":"該研究提出了有關測量可靠性的認識論問題。"},{"en":"Epistemic humility is a virtue in academic research.","zh-TW":"認識謙遜是學術研究的一種美德。"}]', '{"noun":"epistemology","adverb":"epistemically"}', NULL, 3, 2467, NULL),
(2468, 'epistemic injustice', '/ɪˌpɪstəmɪk ɪnˈdʒʌstɪs/', 'noun', '{"zh-TW":["認識論不正義"],"en":["unfairness related to knowledge practices, such as dismissing someone as untrustworthy"]}', NULL, 'testimonial epistemic injustice / hermeneutical epistemic injustice / address epistemic injustice', '[{"en":"Epistemic injustice occurs when a speaker''s knowledge is unfairly dismissed.","zh-TW":"當說話者的知識被不公平地拒絕時，認識論不正義就會發生。"},{"en":"The concept of epistemic injustice helps analyze power dynamics in knowledge production.","zh-TW":"認識論不正義的概念有助於分析知識生產中的權力動態。"}]', '{"adjective":"epistemically unjust"}', NULL, 5, 2468, NULL),
(2469, 'epistemology', '/ɪˌpɪstəˈmɒlədʒi/', 'noun', '{"zh-TW":["認識論；知識論"],"en":["the branch of philosophy concerned with how knowledge is acquired"]}', NULL, 'philosophical epistemology / research epistemology / epistemology of science', '[{"en":"Epistemology asks how we can know what we claim to know.","zh-TW":"認識論探討我們如何能知道我們所宣稱知道的事。"},{"en":"Different epistemologies produce different research designs.","zh-TW":"不同的認識論產生不同的研究設計。"}]', '{"adjective":"epistemological","adverb":"epistemologically"}', NULL, 4, 2469, NULL),
(2470, 'equal', '/ˈiːkwəl/', 'adjective / verb', '{"zh-TW":["相等的；等於"],"en":["the same in quantity, size, or value"]}', NULL, 'equal opportunity/rights', '[{"en":"All employees should receive equal pay for equal work.","zh-TW":"所有員工同工應同酬。"},{"en":"The total equals $5,000.","zh-TW":"總計等於5000美元。"}]', '{"noun":"equality","verb":"equal","adjective":"equal","adverb":"equally"}', NULL, 2, 2470, NULL),
(2471, 'equal opportunity', '/ˌiːkwəl ˌɒpəˈtjuːnɪti/', 'noun', '{"zh-TW":["機會平等"],"en":["the principle that all people should have the same rights and chances"]}', NULL, 'equal opportunity employer / promote equal opportunity', '[{"en":"The company is committed to being an equal opportunity employer.","zh-TW":"公司致力於成為機會平等的雇主。"},{"en":"Equal opportunity policies promote diversity in the workplace.","zh-TW":"機會平等政策促進了職場多樣性。"}]', NULL, NULL, 5, 2471, NULL),
(2472, 'equilibrium price', '/ˌiːkwɪˈlɪbriəm praɪs/', 'noun', '{"zh-TW":["均衡價格"],"en":["the price at which the quantity supplied equals the quantity demanded in a market"]}', NULL, 'reach equilibrium price / equilibrium price determination / market equilibrium price', '[{"en":"At the equilibrium price, there is no tendency for the price to rise or fall.","zh-TW":"在均衡價格時，價格沒有上漲或下跌的趨勢。"},{"en":"A surplus or shortage will push the market toward its equilibrium price over time.","zh-TW":"供過於求或供不應求將隨時間推移推動市場趨向均衡價格。"}]', NULL, NULL, 5, 2472, NULL),
(2473, 'equip', '/ɪˈkwɪp/', 'verb', '{"zh-TW":["裝備；配備"],"en":["to provide with necessary items or skills"]}', NULL, 'well-equipped / equip with', '[{"en":"The office is equipped with modern technology.","zh-TW":"辦公室配備了現代技術。"},{"en":"Training equips employees with new skills.","zh-TW":"培訓為員工配備新技能。"}]', '{"noun":"equipment","verb":"equip","adjective":"equipped"}', NULL, 2, 2473, 680),
(2474, 'equipment', 'ɪˈkwɪpmənt', 'noun', '{"zh-TW":["設備；器材","裝備"],"en":["tools or machines needed","items supplied for a purpose"]}', NULL, 'office equipment/safety equipment', '[{"en":"All equipment must be properly maintained.","zh-TW":"所有設備必須妥善維護。"}]', '{"verb":"equip","adjective":"equipped"}', NULL, 3, 2474, 28),
(2475, 'equitable', '/ˈekwɪtəbəl/', 'adjective', '{"zh-TW":["公平的；公正的"],"en":["fair and impartial; dealing fairly with all concerned"]}', NULL, 'equitable distribution / equitable treatment / equitable solution', '[{"en":"An equitable distribution of resources reduces social inequality.","zh-TW":"公平分配資源可以減少社會不平等。"},{"en":"The mediator proposed an equitable solution acceptable to both parties.","zh-TW":"調解員提出了一個雙方都能接受的公平解決方案。"}]', '{"adverb":"equitably","noun":"equity"}', NULL, 3, 2475, NULL),
(2476, 'equity', '/ˈɛkwɪti/', 'noun', '{"zh-TW":["股權；權益"],"en":["the value of shares in a company","fairness"]}', NULL, 'private equity / home equity', '[{"en":"They raised capital through private equity.","zh-TW":"他們透過私募股權募集資金。"},{"en":"The company has strong brand equity.","zh-TW":"公司擁有強大的品牌價值。"}]', '{"noun":"equity","adjective":"equitable"}', NULL, 2, 2476, 351),
(2477, 'equity capital', '/ˈekwɪti ˈkæpɪtl/', 'noun', '{"zh-TW":["股本；權益資本"],"en":["funds raised through issuing shares rather than borrowing"]}', NULL, 'raise equity capital / equity capital base', '[{"en":"The company strengthened its equity capital base through a rights issue.","zh-TW":"公司通過配股增強了其股本基礎。"},{"en":"Equity capital does not require repayment but dilutes existing shareholders.","zh-TW":"股本不需要償還，但會稀釋現有股東的股份。"}]', NULL, NULL, 5, 2477, NULL),
(2478, 'equity carve-out', '/ˈekwɪti kɑːrv aʊt/', 'noun', '{"zh-TW":["股權分拆"],"en":["a partial IPO in which a parent company offers shares in a subsidiary"]}', NULL, 'conduct an equity carve-out / equity carve-out transaction / partial carve-out', '[{"en":"The conglomerate pursued an equity carve-out to unlock value in its tech division.","zh-TW":"該集團通過股權分拆來釋放其科技部門的價值。"},{"en":"An equity carve-out raises cash while allowing the parent to retain control.","zh-TW":"股權分拆籌集資金同時允許母公司保持控制。"}]', NULL, NULL, 5, 2478, NULL),
(2479, 'equity dilution', '/ˈekwɪti daɪˈluːʃən/', 'noun', '{"zh-TW":["股權稀釋"],"en":["reduction in existing shareholders percentage due to issuing new shares"]}', NULL, 'avoid equity dilution / equity dilution risk', '[{"en":"A large funding round caused significant equity dilution for founders.","zh-TW":"大規模融資輪次對創辦人造成了顯著的股權稀釋。"},{"en":"Anti-dilution provisions protect investors from equity dilution.","zh-TW":"反稀釋條款保護投資者免受股權稀釋影響。"}]', NULL, NULL, 5, 2479, NULL),
(2480, 'equity financing', '/ˈekwɪti ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["股權融資"],"en":["raising capital by issuing shares of stock to investors"]}', NULL, 'pursue equity financing / equity financing round / equity financing vs debt financing', '[{"en":"The company opted for equity financing to avoid increasing its debt.","zh-TW":"公司選擇股權融資以避免增加債務。"},{"en":"Equity financing dilutes existing shareholders'' ownership stake.","zh-TW":"股權融資稀釋了現有股東的持股比例。"}]', NULL, NULL, 5, 2480, NULL),
(2481, 'equity grant', '/ˈekwɪti ɡrɑːnt/', 'noun', '{"zh-TW":["股權授予"],"en":["shares or stock options awarded to employees as part of compensation"]}', NULL, 'equity grant schedule / equity grant vesting / receive an equity grant', '[{"en":"The equity grant vests over four years with a one-year cliff.","zh-TW":"股權授予在四年內歸屬，並有一年的懸崖期。"},{"en":"Equity grants align employee interests with company performance.","zh-TW":"股權授予使員工利益與公司績效保持一致。"}]', NULL, NULL, 4, 2481, NULL),
(2482, 'equity issuance', '/ˈekwɪti ɪˈʃuːəns/', 'noun', '{"zh-TW":["股票發行"],"en":["the process of creating and selling new shares to raise capital"]}', NULL, 'complete an equity issuance / equity issuance costs', '[{"en":"The equity issuance raised $30 million to fund expansion.","zh-TW":"股票發行籌集了3000萬元用於擴張。"},{"en":"Equity issuance dilutes existing shareholders but avoids adding debt.","zh-TW":"股票發行稀釋了現有股東，但避免了增加債務。"}]', NULL, NULL, 5, 2482, NULL),
(2483, 'equity premium', '/ˈekwɪti ˈpriːmiəm/', 'noun', '{"zh-TW":["股票風險溢價"],"en":["the extra return that investors expect from stocks over risk-free assets"]}', NULL, 'equity risk premium / historical equity premium / equity premium puzzle', '[{"en":"The equity premium compensates investors for bearing stock market risk.","zh-TW":"股票風險溢價補償投資者承擔股票市場風險。"},{"en":"Estimating the equity premium is central to asset pricing models.","zh-TW":"估計股票風險溢價是資產定價模型的核心。"}]', NULL, NULL, 5, 2483, NULL),
(2484, 'equity release', '/ˈekwɪti rɪˈliːs/', 'noun', '{"zh-TW":["房產淨值釋出"],"en":["accessing the value built up in property as tax-free cash"]}', NULL, 'equity release scheme / apply for equity release', '[{"en":"Equity release allowed the retiree to fund home improvements.","zh-TW":"房產淨值釋出使退休人士能夠為家居改善提供資金。"},{"en":"Equity release products are subject to strict regulation.","zh-TW":"房產淨值釋出產品受到嚴格監管。"}]', NULL, NULL, 5, 2484, NULL),
(2485, 'equity stake', '/ˈekwɪti steɪk/', 'noun', '{"zh-TW":["股權份額"],"en":["a percentage ownership interest in a company"]}', NULL, 'acquire an equity stake / equity stake of 20% / sell equity stake', '[{"en":"The investor acquired a 15% equity stake in the startup.","zh-TW":"投資者收購了新創公司15%的股權份額。"},{"en":"She negotiated an equity stake as part of her executive compensation.","zh-TW":"她在高管薪酬談判中爭取到了股權份額。"}]', NULL, NULL, 4, 2485, NULL),
(2486, 'equity-backed', '/ˈekwɪti bækt/', 'adjective', '{"zh-TW":["股權支持的"],"en":["financed or secured by equity"]}', NULL, 'equity-backed funding / equity-backed project / equity-backed venture', '[{"en":"The startup secured equity-backed financing to expand operations.","zh-TW":"這家初創公司獲得了股權支持的融資以擴大業務。"},{"en":"Equity-backed deals align investor and management interests.","zh-TW":"股權支持的交易使投資者和管理層的利益一致。"}]', NULL, NULL, 5, 2486, NULL),
(2487, 'equivalent', '/ɪˈkwɪvələnt/', 'adjective / noun', '{"zh-TW":["等同的；等價物","等同的；等價的"],"en":["equal in value, function, or meaning"]}', '{"prefix":{"text":"equi-","meaning":"equal (等同)"},"root":{"text":"val","meaning":"worth (價值)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"價值等同的。"}', 'equivalent to; equivalent to / the equivalent of / roughly equivalent', '[{"en":"One mile is equivalent to 1.6 kilometers.","zh-TW":"一英里等於1.6公里。"},{"en":"There is no equivalent product on the market.","zh-TW":"市場上沒有同等的產品。"},{"en":"One mile is roughly equivalent to 1.6 kilometers.","zh-TW":"一英里大約等於1.6公里。"},{"en":"There is no equivalent word in English.","zh-TW":"英語中沒有等同的字。"}]', '{"noun":"equivalent/equivalence","adjective":"equivalent"}', NULL, 4, 2487, 868),
(2488, 'equivocate', '/''ɪˌkwɪvəˌkeɪt/', 'verb', '{"zh-TW":["含糊其詞；說模稜兩可的話"],"en":["to use ambiguous language so as to conceal the truth or avoid committing oneself"]}', NULL, 'equivocate on / equivocate about / refuse to equivocate', '[{"en":"Politicians often equivocate when asked about controversial policy decisions.","zh-TW":"當被問及有爭議的政策決定時，政治家往往含糊其詞。"},{"en":"She refused to equivocate and gave a direct and honest answer.","zh-TW":"她拒絕含糊其詞，給出了直接而誠實的回答。"}]', '{"noun":"equivocation","adjective":"equivocal","adverb":"equivocally"}', NULL, 4, 2488, NULL),
(2489, 'ergonomics', '/ˌɜːrɡəˈnɒmɪks/', 'noun', '{"zh-TW":["人體工學；人因工程"],"en":["the science of designing workplaces to fit the user"]}', NULL, 'improve ergonomics / ergonomics assessment', '[{"en":"Good ergonomics reduces the risk of repetitive strain injuries.","zh-TW":"良好的人體工學設計降低了重複性損傷的風險。"},{"en":"The company conducted an ergonomics assessment for all workstations.","zh-TW":"公司對所有工作站進行了人體工學評估。"}]', '{"adjective":"ergonomic","adverb":"ergonomically"}', NULL, 4, 2489, NULL),
(2490, 'erode', '/ɪˈroʊd/', 'verb', '{"zh-TW":["侵蝕；削弱"],"en":["to gradually wear away or diminish"]}', NULL, 'erode confidence/trust', '[{"en":"Competition has eroded profit margins.","zh-TW":"競爭侵蝕了利潤率。"},{"en":"Public trust in the brand has eroded.","zh-TW":"公眾對品牌的信任已被削弱。"}]', '{"noun":"erosion","verb":"erode"}', NULL, 2, 2490, NULL),
(2491, 'erosion', '/ɪˈroʊʒn/', 'noun', '{"zh-TW":["侵蝕"],"en":["the gradual wearing away of soil or rock"]}', '{"prefix":{"text":"e-","meaning":"away (離去)"},"root":{"text":"ros","meaning":"gnaw (啃蝕)"},"suffix":{"text":"-ion","meaning":"process (過程)"},"logic":"被啃蝕掉的過程，即「侵蝕」。"}', 'soil erosion / coastal erosion', '[{"en":"Soil erosion is a serious environmental problem.","zh-TW":"土壤侵蝕是嚴重的環境問題。"},{"en":"Heavy rain accelerates erosion.","zh-TW":"大雨加速侵蝕。"}]', '{"verb":"erode"}', NULL, 3, 2491, NULL),
(2492, 'ERP', '/ˌiː ɑːr ˈpiː/', 'noun', '{"zh-TW":["企業資源規劃系統"],"en":["enterprise resource planning; integrated software for managing business processes"]}', NULL, 'implement an ERP / ERP system / ERP software / ERP upgrade', '[{"en":"The company implemented a new ERP to unify its global operations.","zh-TW":"公司實施了新的企業資源規劃系統以統一其全球業務。"},{"en":"ERP integration reduced manual data entry errors significantly.","zh-TW":"ERP整合顯著減少了手動數據輸入錯誤。"}]', '{"full form":"enterprise resource planning"}', NULL, 1, 2492, NULL),
(2493, 'erratic', '/''ɪˈrætɪk/', 'adjective', '{"zh-TW":["不穩定的；難以預測的"],"en":["not even or regular in pattern or movement; unpredictable"]}', NULL, 'erratic behavior / erratic performance / erratic market', '[{"en":"Erratic weather patterns are making agricultural planning more difficult.","zh-TW":"不穩定的天氣模式使農業規劃更加困難。"},{"en":"The stock''s erratic price movement made investors nervous.","zh-TW":"股票價格的不穩定波動讓投資者感到不安。"}]', '{"adverb":"erratically","noun":"erraticism"}', NULL, 3, 2493, NULL),
(2494, 'error', '/ˈerər/', 'noun', '{"zh-TW":["錯誤；失誤"],"en":["a mistake; something incorrectly done"]}', NULL, 'human/clerical error', '[{"en":"The report contained several errors.","zh-TW":"報告中有幾處錯誤。"},{"en":"The error was caused by a software bug.","zh-TW":"錯誤是由軟體缺陷造成的。"}]', '{"noun":"error","adjective":"erroneous"}', NULL, 2, 2494, NULL),
(2495, 'error and omission', '/ˈerər ænd əˈmɪʃən/', 'noun', '{"zh-TW":["錯誤與遺漏"],"en":["a type of liability insurance protecting against claims of inadequate work or negligent actions"]}', NULL, 'errors and omissions insurance / errors and omissions claim', '[{"en":"The consultant took out errors and omissions insurance before providing advice.","zh-TW":"顧問在提供建議之前購買了錯誤與遺漏保險。"},{"en":"An errors and omissions claim can arise from mistakes in professional reports.","zh-TW":"專業報告中的錯誤可能引發錯誤與遺漏索賠。"}]', '{"abbreviation":"E&O","synonym":"professional indemnity insurance"}', NULL, 5, 2495, NULL),
(2496, 'erudite', '/ˈerjʊdaɪt/', 'adjective', '{"zh-TW":["博學的；有學問的"],"en":["having or showing great knowledge or learning"]}', NULL, 'erudite scholar / erudite discussion / erudite commentary', '[{"en":"Her erudite commentary impressed the entire review panel.","zh-TW":"她博學的評論給整個評審小組留下了深刻印象。"},{"en":"The professor''s erudite lectures attracted students from many fields.","zh-TW":"教授博學的講座吸引了來自許多領域的學生。"}]', '{"noun":"erudition","adverb":"eruditely"}', NULL, 3, 2496, NULL),
(2497, 'escalate', '/ˈeskəleɪt/', 'verb', '{"zh-TW":["上報；升級"],"en":["to refer an issue to a higher authority or increase intensity"]}', NULL, 'escalate a complaint / escalate to management / escalate an issue', '[{"en":"She escalated the unresolved complaint to her supervisor.","zh-TW":"她將未解決的投訴上報給主管。"},{"en":"If a solution cannot be found, escalate the issue immediately.","zh-TW":"如果找不到解決方案，立即上報問題。"}]', '{"noun":"escalation","adjective":"escalated"}', NULL, 3, 2497, 681),
(2498, 'escalate costs', '/ˈeskəleɪt kɒsts/', 'verb', '{"zh-TW":["成本上升；費用升高"],"en":["to increase in costs over time, often unexpectedly"]}', NULL, 'escalating project costs / escalating operational costs', '[{"en":"Project costs escalated due to scope changes and material shortages.","zh-TW":"由於範圍變更和材料短缺，項目成本上升了。"},{"en":"The company took steps to prevent escalating labor costs.","zh-TW":"公司採取措施防止勞動力成本升高。"}]', NULL, NULL, 5, 2498, NULL),
(2499, 'escalation', '/ˌeskəˈleɪʃən/', 'noun', '{"zh-TW":["升級；上報"],"en":["raising an issue to a higher authority when it cannot be resolved at the current level"]}', NULL, 'escalation process / escalate an issue / escalation path', '[{"en":"The customer complaint required escalation to the director.","zh-TW":"客戶投訴需要上報給總監。"},{"en":"Clear escalation paths reduce delays in problem resolution.","zh-TW":"清晰的升級路徑減少了問題解決的延誤。"}]', '{"verb":"escalate","adjective":"escalated"}', NULL, 4, 2499, 784);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2500, 'escalation matrix', '/ˌeskəˈleɪʃən ˈmeɪtrɪks/', 'noun', '{"zh-TW":["升級矩陣"],"en":["a document defining when and how issues should be escalated to higher management"]}', NULL, 'use the escalation matrix / refer to the escalation matrix', '[{"en":"The escalation matrix defines who to contact for different severity levels.","zh-TW":"升級矩陣定義了針對不同嚴重程度應聯繫誰。"},{"en":"Following the escalation matrix ensures issues are resolved efficiently.","zh-TW":"遵循升級矩陣確保問題得到高效解決。"}]', NULL, NULL, 5, 2500, NULL),
(2501, 'escalation path', '/ˌeskəˈleɪʃən pɑːθ/', 'noun', '{"zh-TW":["升級路徑"],"en":["a defined process for routing unresolved issues to higher authority"]}', NULL, 'define escalation paths / follow the escalation path', '[{"en":"The escalation path ensures urgent issues reach managers quickly.","zh-TW":"升級路徑確保緊急問題迅速觸及管理者。"},{"en":"Clear escalation paths reduce customer wait times.","zh-TW":"清晰的升級路徑減少了客戶等待時間。"}]', NULL, NULL, 5, 2501, NULL),
(2502, 'escalation procedure', '/ˌeskəˈleɪʃən prəˈsiːdʒər/', 'noun', '{"zh-TW":["升級程序"],"en":["the defined steps for raising unresolved issues to higher management levels"]}', NULL, 'follow the escalation procedure / escalation procedure policy', '[{"en":"The escalation procedure ensures critical issues reach senior management.","zh-TW":"升級程序確保重大問題能夠達到高層管理人員。"},{"en":"All customer complaints must follow the escalation procedure.","zh-TW":"所有客戶投訴必須遵循升級程序。"}]', NULL, NULL, 5, 2502, NULL),
(2503, 'escape', '/ɪˈskeɪp/', 'verb', '{"zh-TW":["逃脫；避免"],"en":["to get free from","to avoid something unpleasant"]}', NULL, 'escape route / narrow escape', '[{"en":"Know the escape routes in case of fire.","zh-TW":"了解火災時的逃生路線。"},{"en":"We had a narrow escape from the flooding.","zh-TW":"我們險些遭遇洪水。"}]', '{"verb":"escape","noun":"escape"}', NULL, 2, 2503, NULL),
(2504, 'escrow', '/ˈeskroʊ/', 'noun', '{"zh-TW":["第三方託管；代管"],"en":["a financial arrangement where a third party holds assets until conditions are met"]}', NULL, 'hold in escrow / escrow account / place funds in escrow / release from escrow', '[{"en":"Funds were placed in escrow pending completion of the sale.","zh-TW":"資金被放入第三方託管，等待銷售完成。"},{"en":"The escrow agent released payment once all conditions were satisfied.","zh-TW":"所有條件滿足後，代管代理人釋放了付款。"}]', '{"verb":"escrow"}', NULL, 2, 2504, NULL),
(2505, 'escrow account', '/ˈeskroʊ əˈkaʊnt/', 'noun', '{"zh-TW":["托管帳戶"],"en":["a third-party account holding funds until specified conditions are met"]}', NULL, 'hold funds in escrow / open an escrow account', '[{"en":"The purchase price was placed in an escrow account pending due diligence.","zh-TW":"購買價款存放在托管帳戶中，等待完成盡職調查。"},{"en":"An escrow account protects both buyer and seller during a property transaction.","zh-TW":"托管帳戶在房產交易中保護買方和賣方雙方。"}]', NULL, NULL, 5, 2505, NULL),
(2506, 'escrow agent', '/ˈeskroʊ ˈeɪdʒənt/', 'noun', '{"zh-TW":["託管代理人"],"en":["a neutral third party holding funds or documents until conditions are met"]}', NULL, 'appoint an escrow agent / escrow agent fee', '[{"en":"The escrow agent released the funds after the contract conditions were satisfied.","zh-TW":"在合約條件得到滿足後，託管代理人釋放了資金。"},{"en":"An escrow agent provides security to both buyer and seller in a transaction.","zh-TW":"託管代理人在交易中為買賣雙方提供保障。"}]', NULL, NULL, 4, 2506, NULL),
(2507, 'ESOP', '/ˈiːsɒp/', 'noun', '{"zh-TW":["員工持股計劃"],"en":["employee stock ownership plan; a benefit giving employees company shares"]}', NULL, 'set up an ESOP / ESOP contribution / ESOP plan', '[{"en":"The ESOP aligned employees'' interests with the company''s success.","zh-TW":"員工持股計劃使員工利益與公司成功保持一致。"},{"en":"Many tech firms use ESOPs as a long-term retention tool.","zh-TW":"許多科技公司使用員工持股計劃作為長期留才工具。"}]', '{"full form":"employee stock ownership plan"}', NULL, 1, 2507, NULL),
(2508, 'espresso', '/ɪˈsprɛsəʊ/', 'noun', '{"zh-TW":["義式濃縮咖啡"],"en":["a strong coffee made by forcing steam through ground coffee"]}', NULL, 'double espresso / espresso shot', '[{"en":"She ordered a double espresso to start her morning.","zh-TW":"她點了一杯雙份義式濃縮咖啡開始她的早晨。"},{"en":"Espresso is the base for many coffee drinks.","zh-TW":"義式濃縮咖啡是許多咖啡飲品的基底。"}]', NULL, NULL, 3, 2508, NULL),
(2509, 'essential', '/ɪˈsenʃəl/', 'adjective', '{"zh-TW":["必要的；基本的","必要的；本質的"],"en":["absolutely necessary; extremely important"]}', '{"root":{"text":"essent","meaning":"being/existence (存在)"},"suffix":{"text":"-ial","meaning":"relating to (相關的)"},"logic":"與存在本質相關的（不可缺少的）。"}', 'essential for/to; essential skills / essential information / absolutely essential', '[{"en":"Communication skills are essential for this role.","zh-TW":"溝通技能對這個職位是必要的。"},{"en":"It is essential to meet the deadline.","zh-TW":"在截止日期前完成是必要的。"},{"en":"Water is essential for life.","zh-TW":"水是生命所必需的。"},{"en":"Good communication skills are essential for this job.","zh-TW":"良好的溝通能力對這份工作至關重要。"}]', '{"noun":"essential/essentials","adjective":"essential","adverb":"essentially"}', NULL, 3, 2509, 869),
(2510, 'essentialism', '/ɪˈsenʃəlɪzəm/', 'noun', '{"zh-TW":["本質主義"],"en":["the view that entities have inherent essential properties"]}', NULL, 'strategic essentialism / cultural essentialism / critique essentialism', '[{"en":"Critics argue that essentialism reinforces stereotypes about gender and culture.","zh-TW":"批評者認為本質主義強化了關於性別和文化的刻板印象。"},{"en":"Essentialism assumes fixed identities that postmodern theory challenges.","zh-TW":"本質主義假設後現代理論所挑戰的固定身份。"}]', '{"adjective":"essentialist"}', NULL, 4, 2510, NULL),
(2511, 'establish', '/ɪˈstæblɪʃ/', 'verb', '{"zh-TW":["建立；確立","建立；設立"],"en":["to set up; to prove or show","to set up on a firm or permanent basis"]}', '{"prefix":{"text":"e-","meaning":"out (完全)"},"root":{"text":"stabl","meaning":"stable (穩定)"},"suffix":{"text":"-ish","meaning":"make (使)"},"logic":"使其穩固確立，即「建立」。"}', 'establish a company/reputation; establish a company / well-established', '[{"en":"The company was established in 1990.","zh-TW":"公司成立於1990年。"},{"en":"We need to establish clear guidelines.","zh-TW":"我們需要建立明確的指導方針。"},{"en":"They established a new policy for remote work.","zh-TW":"他們制定了新的遠端工作政策。"}]', '{"noun":"establishment","verb":"establish","adjective":"established"}', NULL, 3, 2511, 116),
(2512, 'estate agent', '/''ɪˌsteɪt ˌeɪdʒənt/', 'noun', '{"zh-TW":["房地產中介；物業代理"],"en":["a person or business that arranges the selling, renting, or management of properties"]}', NULL, 'contact an estate agent / trusted estate agent / estate agent fee', '[{"en":"We visited three estate agents before finding a suitable rental apartment.","zh-TW":"我們拜訪了三家房地產中介，才找到一套合適的出租公寓。"},{"en":"The estate agent arranged viewings for six properties in one afternoon.","zh-TW":"房地產中介在一個下午安排了六套房產的看房。"}]', NULL, NULL, 4, 2512, NULL),
(2513, 'estate planning', '/ɪˈsteɪt ˈplænɪŋ/', 'noun', '{"zh-TW":["遺產規劃"],"en":["arranging for the transfer of assets after death to minimize taxes and disputes"]}', NULL, 'engage in estate planning / estate planning services', '[{"en":"Estate planning ensures assets are distributed according to your wishes.","zh-TW":"遺產規劃確保資產按照您的意願分配。"},{"en":"The wealth manager provided comprehensive estate planning services.","zh-TW":"財富管理者提供了全面的遺產規劃服務。"}]', NULL, NULL, 5, 2513, NULL),
(2514, 'estimate', '/ˈestɪmeɪt/', 'verb / noun', '{"zh-TW":["估計；預算","估計"],"en":["to roughly calculate; an approximate judgment","to roughly calculate or judge the value of"]}', '{"root":{"text":"estim","meaning":"value (評價)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"做出評價，即「估計」。"}', 'rough/conservative estimate; rough estimate / cost estimate / estimate the cost', '[{"en":"We estimate the cost at $50,000.","zh-TW":"我們估計成本為5萬美元。"},{"en":"The initial estimate was too low.","zh-TW":"最初的估計太低了。"},{"en":"We estimate the project will cost $2 million.","zh-TW":"我們估計這個專案將花費200萬美元。"},{"en":"Can you give me a rough estimate?","zh-TW":"你能給我一個粗略的估計嗎？"}]', '{"noun":"estimate/estimation","verb":"estimate","adjective":"estimated","noun2":"estimation"}', NULL, 3, 2514, 29),
(2515, 'estimated time of arrival', '/ˈɛstɪmɪtɪd taɪm əv əˈraɪvəl/', 'noun', '{"zh-TW":["預計到達時間"],"en":["the projected time when something will arrive"]}', NULL, 'check estimated time of arrival / estimated time of arrival alert', '[{"en":"The estimated time of arrival for the shipment is Friday.","zh-TW":"貨物的預計到達時間是週五。"},{"en":"Track your order to see the estimated time of arrival.","zh-TW":"追蹤您的訂單以查看預計到達時間。"}]', '{"abbreviation":"ETA"}', NULL, 5, 2515, NULL),
(2516, 'estimated useful life', '/ˈestɪmeɪtɪd ˈjuːsfəl laɪf/', 'noun', '{"zh-TW":["估計使用年限"],"en":["the projected period over which an asset is expected to be used productively"]}', NULL, 'determine estimated useful life / revise estimated useful life', '[{"en":"The estimated useful life of the equipment is 10 years.","zh-TW":"設備的估計使用年限為10年。"},{"en":"Depreciation is calculated based on the estimated useful life of each asset.","zh-TW":"折舊根據每項資產的估計使用年限計算。"}]', NULL, NULL, 5, 2516, NULL),
(2517, 'estimation', 'ˌɛstɪˈmeɪʃən', 'noun', '{"zh-TW":["估算；估計","評價"],"en":["a calculated guess","a judgment of value"]}', NULL, 'cost estimation/time estimation', '[{"en":"Please prepare an accurate cost estimation.","zh-TW":"請準備準確的成本估算。"}]', '{"verb":"estimate","adjective":"estimated"}', NULL, 4, 2517, 785),
(2518, 'estoppel', '/ɪˈstɒpəl/', 'noun', '{"zh-TW":["禁止反言"],"en":["a legal principle preventing someone from contradicting a prior statement"]}', NULL, 'promissory estoppel / doctrine of estoppel / equitable estoppel', '[{"en":"The doctrine of estoppel prevented the company from denying the promise.","zh-TW":"禁止反言原則阻止公司否認承諾。"},{"en":"Promissory estoppel can make an otherwise unenforceable promise binding.","zh-TW":"約因禁止反言可以使原本無法執行的承諾具有約束力。"}]', NULL, NULL, 3, 2518, NULL),
(2519, 'ethics code', '/ˈeθɪks koʊd/', 'noun', '{"zh-TW":["道德準則；倫理守則"],"en":["a set of rules defining ethical standards for members of an organization"]}', NULL, 'adopt an ethics code / sign the ethics code', '[{"en":"All staff are required to sign the ethics code annually.","zh-TW":"所有員工每年必須簽署道德準則。"},{"en":"The ethics code prohibits accepting gifts from suppliers.","zh-TW":"道德準則禁止接受供應商的禮物。"}]', NULL, NULL, 4, 2519, NULL),
(2520, 'ethnocentrism', '/ˌeθnəʊˈsentrɪzəm/', 'noun', '{"zh-TW":["民族中心主義"],"en":["judging other cultures by the standards of your own"]}', NULL, 'overcome ethnocentrism / ethnocentrism in research / avoid ethnocentrism', '[{"en":"Ethnocentrism distorts cross-cultural research and policy analysis.","zh-TW":"民族中心主義扭曲了跨文化研究和政策分析。"},{"en":"Anthropologists must guard against ethnocentrism when studying other societies.","zh-TW":"人類學家在研究其他社會時必須防範民族中心主義。"}]', '{"adjective":"ethnocentric","adverb":"ethnocentrically"}', NULL, 5, 2520, NULL),
(2521, 'ethnography', '/eθˈnɒɡrəfi/', 'noun', '{"zh-TW":["民族誌；人種誌"],"en":["the systematic study of people and cultures"]}', NULL, 'conduct ethnography / ethnography research / ethnographic study', '[{"en":"The researcher conducted ethnography among urban communities.","zh-TW":"研究員對城市社區進行了民族誌研究。"},{"en":"Ethnography requires extended fieldwork and observation.","zh-TW":"民族誌研究需要長期的田野調查和觀察。"}]', '{"adjective":"ethnographic","adverb":"ethnographically"}', NULL, 4, 2521, NULL),
(2522, 'etiology', '/ˌiːtiˈɒlədʒi/', 'noun', '{"zh-TW":["病因學；病因"],"en":["the cause or causes of a disease or condition"]}', NULL, 'unknown etiology / viral etiology / etiology of a disease', '[{"en":"The etiology of the condition remains unclear despite extensive research.","zh-TW":"儘管進行了廣泛研究，該病的病因仍不清楚。"},{"en":"Understanding the etiology of a disease is essential for effective treatment.","zh-TW":"了解疾病的病因對有效治療至關重要。"}]', '{"adjective":"etiological"}', NULL, 3, 2522, NULL),
(2523, 'euphemism', '/''juːfəmɪzəm/', 'noun', '{"zh-TW":["委婉語；婉辭"],"en":["a mild or indirect word or expression substituted for one that might be considered too harsh or blunt"]}', NULL, 'use a euphemism / common euphemism / polite euphemism', '[{"en":"Saying ''passed away'' is a common euphemism for ''died.''","zh-TW":"說「過世了」是「死了」的常用委婉說法。"},{"en":"Corporate language is full of euphemisms like ''downsizing'' instead of ''firing.''","zh-TW":"企業語言充滿了委婉語，比如用「裁員」代替「解雇」。"}]', '{"adjective":"euphemistic"}', NULL, 3, 2523, NULL),
(2524, 'eutrophication', '/juːˌtrɒfɪˈkeɪʃən/', 'noun', '{"zh-TW":["優養化；水體富營養化"],"en":["excessive richness of nutrients in water, causing algal blooms"]}', NULL, 'prevent eutrophication / eutrophication of lakes / control eutrophication', '[{"en":"Agricultural runoff contributes to eutrophication of rivers and lakes.","zh-TW":"農業逕流造成河流和湖泊的優養化。"},{"en":"Eutrophication depletes oxygen in water, killing fish and other aquatic life.","zh-TW":"優養化消耗水中的氧氣，殺死魚類和其他水生生物。"}]', '{"verb":"eutrophy","adjective":"eutrophic"}', NULL, 5, 2524, NULL),
(2525, 'evaluate', '/ɪˈvæljueɪt/', 'verb', '{"zh-TW":["評估；評價","評估"],"en":["to judge the value or quality of","to judge or determine the significance or value of"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"valu","meaning":"value (價值)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"衡量出價值來，即「評估」。"}', 'evaluate performance/options; evaluate performance / evaluate options', '[{"en":"We need to evaluate all options carefully.","zh-TW":"我們需要仔細評估所有選項。"},{"en":"Employee performance is evaluated annually.","zh-TW":"員工績效每年評估一次。"},{"en":"Teachers evaluate student performance regularly.","zh-TW":"老師定期評估學生表現。"},{"en":"We need to evaluate all the options.","zh-TW":"我們需要評估所有選項。"}]', '{"noun":"evaluation","verb":"evaluate"}', NULL, 3, 2525, 30),
(2526, 'evaluate performance', '/ɪˈvæljueɪt pəˈfɔːrməns/', 'verb', '{"zh-TW":["評估績效"],"en":["to systematically assess how well something or someone is performing"]}', NULL, 'evaluate employee performance / evaluate project performance', '[{"en":"Managers evaluate performance using a set of measurable criteria.","zh-TW":"管理者使用一套可衡量的標準評估績效。"},{"en":"The project was evaluated for performance against the original budget.","zh-TW":"項目按照原始預算評估了其績效。"}]', NULL, NULL, 5, 2526, NULL),
(2527, 'evaluation', 'ɪˌvæljʊˈeɪʃən', 'noun', '{"zh-TW":["評估；評價","考核"],"en":["the process of assessing","a judgment of value"]}', NULL, 'performance evaluation/project evaluation', '[{"en":"The evaluation report was submitted.","zh-TW":"評估報告已提交。"}]', '{"verb":"evaluate","adjective":"evaluative"}', NULL, 4, 2527, 561),
(2528, 'evaluation criteria', '/ɪˌvæljuˈeɪʃən kraɪˈtɪəriə/', 'noun', '{"zh-TW":["評估標準"],"en":["the standards and factors used to assess and select between options or proposals"]}', NULL, 'define evaluation criteria / meet evaluation criteria', '[{"en":"The tender documents listed price, quality, and experience as evaluation criteria.","zh-TW":"招標文件將價格、質量和經驗列為評估標準。"},{"en":"Clear evaluation criteria reduce subjectivity in supplier selection.","zh-TW":"清晰的評估標準減少了供應商選擇中的主觀性。"}]', NULL, NULL, 5, 2528, NULL),
(2529, 'evaluative', '/ɪˈvæljʊətɪv/', 'adjective', '{"zh-TW":["評估性的；判斷性的"],"en":["relating to making judgments or evaluations"]}', NULL, 'evaluative framework / evaluative criteria / evaluative approach', '[{"en":"The study uses an evaluative framework to assess program effectiveness.","zh-TW":"研究使用評估框架評估計畫效果。"},{"en":"Evaluative criteria must be established before data collection begins.","zh-TW":"評估標準必須在數據收集開始之前建立。"}]', '{"verb":"evaluate","noun":"evaluation"}', NULL, 4, 2529, NULL),
(2530, 'even', '/ˈiːvən/', 'verb, adjective, adverb', '{"zh-TW":["【主要意義-副詞/連接詞】甚至；連……也","【次要意義-動詞】使平整；使相等；使均衡","【次要意義-形容詞】平穩的；均等的；偶數的"],"en":["[primary] used to emphasize something unexpected","[secondary - verb] to make flat, level, or equal","[secondary - adjective] equal, level, or divisible by two"]}', NULL, 'even out / even up / even the score / on an even keel', '[{"en":"The extra payment will even out the discrepancy in the accounts.","zh-TW":"額外付款將消除帳目中的差異。"},{"en":"They worked to even the playing field for smaller companies.","zh-TW":"他們努力為小公司創造公平競爭的環境。"},{"en":"Production levels have evened out after the initial surge.","zh-TW":"初期激增後，生產水平已趨於平穩。"}]', '{"adverb":"evenly","noun":"evenness"}', '動詞 even out/up 意為「使平衡/消除差異」，常見於 TOEIC 財務或生產排程的語境，與副詞「甚至」的用法完全不同。', 1, 2530, NULL),
(2531, 'evening', '/ˈiːvnɪŋ/', 'noun', '{"zh-TW":["傍晚；晚上"],"en":["the part of the day between afternoon and night"]}', NULL, 'good evening / evening shift', '[{"en":"Good evening, everyone.","zh-TW":"大家晚上好。"},{"en":"She works the evening shift.","zh-TW":"她上晚班。"}]', '{"noun":"evening"}', NULL, 3, 2531, NULL),
(2532, 'event', 'ɪˈvɛnt', 'noun', '{"zh-TW":["事件；活動","賽事"],"en":["a thing that happens","a planned occasion"]}', NULL, 'corporate event/upcoming event', '[{"en":"The annual event is scheduled for May.","zh-TW":"年度活動定於五月舉行。"}]', '{"adjective":"eventful","adverb":"eventfully"}', NULL, 2, 2532, NULL),
(2533, 'event coordinator', '/ɪˈvɛnt kəʊˈɔːrdɪneɪtər/', 'noun', '{"zh-TW":["活動協調員"],"en":["a person responsible for planning and managing events"]}', NULL, 'hire an event coordinator / experienced event coordinator', '[{"en":"The event coordinator handled all logistics for the conference.","zh-TW":"活動協調員處理了會議的所有後勤工作。"},{"en":"A good event coordinator anticipates problems before they arise.","zh-TW":"優秀的活動協調員在問題出現之前預先考慮到。"}]', NULL, NULL, 5, 2533, NULL),
(2534, 'event planning', '/ɪˈvɛnt ˈplænɪŋ/', 'noun', '{"zh-TW":["活動策劃"],"en":["the process of organizing events from concept to execution"]}', NULL, 'event planning skills / professional event planning', '[{"en":"She works in event planning for corporate conferences.","zh-TW":"她從事企業會議的活動策劃工作。"},{"en":"Good event planning requires attention to detail and flexibility.","zh-TW":"良好的活動策劃需要關注細節和靈活性。"}]', '{"verb":"plan","noun":"event planner"}', NULL, 5, 2534, NULL),
(2535, 'event risk', '/ɪˈvent rɪsk/', 'noun', '{"zh-TW":["事件風險"],"en":["the risk of loss resulting from a sudden unexpected event affecting an investment"]}', NULL, 'mitigate event risk / event risk premium', '[{"en":"Political instability increased event risk in the emerging market portfolio.","zh-TW":"政治不穩定增加了新興市場投資組合中的事件風險。"},{"en":"Credit downgrades often reflect event risks not anticipated at issuance.","zh-TW":"信用降級通常反映了發行時未預期的事件風險。"}]', NULL, NULL, 4, 2535, NULL),
(2536, 'event-driven', '/ɪˈvent ˈdrɪvən/', 'adjective', '{"zh-TW":["事件驅動的"],"en":["relating to an architecture where actions are triggered by events"]}', NULL, 'event-driven architecture / event-driven programming / event-driven system', '[{"en":"Event-driven architecture enables loosely coupled, scalable systems.","zh-TW":"事件驅動架構支持鬆耦合、可擴展的系統。"},{"en":"Modern UIs rely on event-driven programming to handle user interactions.","zh-TW":"現代用戶界面依靠事件驅動程式設計來處理用戶交互。"}]', NULL, NULL, 4, 2536, NULL),
(2537, 'eventually', '/ɪˈventʃuəli/', 'adverb', '{"zh-TW":["最終；終於"],"en":["in the end; after a period of time"]}', NULL, 'eventually lead to', '[{"en":"The negotiations eventually led to an agreement.","zh-TW":"談判最終達成了協議。"},{"en":"He eventually became the CEO.","zh-TW":"他最終成為了執行長。"}]', '{"adjective":"eventual","adverb":"eventually"}', NULL, 4, 2537, NULL),
(2538, 'eviction notice', '/''ɪˌvɪkʃən ˌnəʊtɪs/', 'noun', '{"zh-TW":["驅逐通知；逐屋通知"],"en":["a formal legal document issued to a tenant requiring them to vacate the property by a certain date"]}', NULL, 'receive an eviction notice / issue an eviction notice / contest an eviction notice', '[{"en":"The tenant received an eviction notice after failing to pay rent for three months.","zh-TW":"房客在三個月未付租金後收到了驅逐通知。"},{"en":"She sought legal advice on how to contest the eviction notice she had received.","zh-TW":"她尋求法律建議，了解如何對她收到的驅逐通知提出異議。"}]', '{"verb":"evict","noun":"eviction"}', NULL, 5, 2538, NULL),
(2539, 'evidence', '/ˈevɪdəns/', 'noun', '{"zh-TW":["證據；跡象","證據"],"en":["facts or signs showing something is true","facts or information indicating whether something is true"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"vid","meaning":"see (看)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"看得出來的事實，即「證據」。"}', 'provide/present evidence; scientific evidence / evidence suggests / lack of evidence', '[{"en":"There is evidence of improvement in sales.","zh-TW":"有銷售改善的證據。"},{"en":"The data provides evidence of a trend.","zh-TW":"數據提供了趨勢的證據。"},{"en":"There is no evidence to support this claim.","zh-TW":"沒有證據支持這項說法。"},{"en":"The evidence suggests a link between the two.","zh-TW":"證據顯示兩者之間有關聯。"}]', '{"noun":"evidence","adjective":"evident","adverb":"evidently"}', NULL, 3, 2539, 562),
(2540, 'evidence-based', '/ˈevɪdəns beɪst/', 'adjective', '{"zh-TW":["實證的；循證的"],"en":["based on evidence from research rather than intuition or tradition"]}', NULL, 'evidence-based practice / evidence-based policy / evidence-based medicine', '[{"en":"Evidence-based medicine relies on clinical trials rather than anecdotal reports.","zh-TW":"循證醫學依賴臨床試驗而非個案報告。"},{"en":"Evidence-based policy design improves the effectiveness of public programs.","zh-TW":"實證政策設計提高了公共計畫的有效性。"}]', NULL, NULL, 5, 2540, NULL),
(2541, 'evolve', '/ɪˈvɑːlv/', 'verb', '{"zh-TW":["進化；發展"],"en":["to develop gradually over time"]}', NULL, 'evolve into/over time', '[{"en":"The company has evolved into a global brand.","zh-TW":"公司已發展成為全球品牌。"},{"en":"Consumer preferences evolve constantly.","zh-TW":"消費者偏好不斷演變。"}]', '{"noun":"evolution","verb":"evolve"}', NULL, 2, 2541, NULL),
(2542, 'exacerbate', '/ɪɡˈzæsərbeɪt/', 'verb', '{"zh-TW":["加劇；惡化"],"en":["to make a problem or bad situation worse"]}', NULL, 'exacerbate tensions / exacerbate inequality / exacerbate problems', '[{"en":"Inflation exacerbates the financial burden on low-income households.","zh-TW":"通貨膨脹加劇了低收入家庭的財務負擔。"},{"en":"Poor communication can exacerbate conflicts within teams.","zh-TW":"溝通不良會加劇團隊內部的衝突。"}]', '{"noun":"exacerbation"}', NULL, 4, 2542, NULL),
(2543, 'exact', '/ɪɡˈzækt/', 'adjective', '{"zh-TW":["精確的；確切的"],"en":["completely accurate; precise"]}', NULL, 'exact amount/location', '[{"en":"The exact cost has not been determined yet.","zh-TW":"確切費用尚未確定。"},{"en":"Please provide the exact date.","zh-TW":"請提供確切日期。"}]', '{"adjective":"exact","adverb":"exactly"}', NULL, 2, 2543, NULL),
(2544, 'exam', '/ɪɡˈzæm/', 'noun', '{"zh-TW":["考試"],"en":["a formal test of knowledge"]}', NULL, 'take an exam / pass an exam', '[{"en":"I have three exams next week.","zh-TW":"我下週有三場考試。"},{"en":"She passed all her exams.","zh-TW":"她通過了所有考試。"}]', '{"noun2":"examination","noun3":"examiner"}', NULL, 1, 2544, NULL),
(2545, 'examination', '/ɪɡˌzæmɪˈneɪʃən/', 'noun', '{"zh-TW":["檢查；診察"],"en":["a formal medical check of someone''s health"]}', NULL, 'physical examination / eye examination', '[{"en":"The doctor performed a thorough physical examination.","zh-TW":"醫生進行了徹底的身體檢查。"},{"en":"An eye examination is recommended every two years.","zh-TW":"建議每兩年進行一次眼科檢查。"}]', '{"verb":"examine","adjective":"examined"}', NULL, 4, 2545, 563),
(2546, 'examine', '/ɪɡˈzæmɪn/', 'verb', '{"zh-TW":["檢查；審查"],"en":["to inspect closely; to test knowledge"]}', NULL, 'examine closely/carefully', '[{"en":"The auditor examined the financial records.","zh-TW":"審計師審查了財務記錄。"},{"en":"We need to examine this issue more closely.","zh-TW":"我們需要更仔細地審查這個問題。"}]', '{"noun":"examination/examiner","verb":"examine"}', NULL, 3, 2546, 352),
(2547, 'example', '/ɪɡˈzæmpəl/', 'noun', '{"zh-TW":["例子；範例"],"en":["something typical of a group","a model to follow"]}', NULL, 'for example / set an example', '[{"en":"For example, we could reduce costs here.","zh-TW":"例如，我們可以在這裡降低成本。"},{"en":"She sets a good example for new staff.","zh-TW":"她為新員工樹立了好榜樣。"}]', '{"noun":"example","adjective":"exemplary","verb":"exemplify"}', NULL, 3, 2547, NULL),
(2548, 'exceed', '/ɪkˈsiːd/', 'verb', '{"zh-TW":["超過；超出","超過；超越"],"en":["to go beyond a limit or expectation","to go beyond a limit or standard"]}', '{"prefix":{"text":"ex-","meaning":"out (超出)"},"root":{"text":"ceed","meaning":"go (走)"},"logic":"走出去超越界限，即「超過」。"}', 'exceed expectations/limits; exceed expectations / exceed the limit', '[{"en":"Sales exceeded expectations this quarter.","zh-TW":"本季度銷售超出了預期。"},{"en":"Do not exceed the speed limit.","zh-TW":"不要超過速限。"},{"en":"Sales exceeded our expectations.","zh-TW":"銷售額超出了我們的預期。"}]', '{"adjective":"exceeding","adverb":"exceedingly"}', NULL, 2, 2548, 117),
(2549, 'excellent', '/ˈeksələnt/', 'adjective', '{"zh-TW":["優秀的；極好的"],"en":["extremely good; outstanding"]}', NULL, 'excellent performance/service', '[{"en":"She received excellent feedback from clients.","zh-TW":"她收到了客戶的優秀評價。"},{"en":"The hotel provides excellent service.","zh-TW":"這家飯店提供優質服務。"}]', '{"noun":"excellence","adjective":"excellent"}', NULL, 3, 2549, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2550, 'exception', '/ɪkˈsepʃən/', 'noun', '{"zh-TW":["例外"],"en":["something that does not follow a rule"]}', NULL, 'with the exception of / make an exception', '[{"en":"All staff must attend, with no exceptions.","zh-TW":"所有員工必須參加，沒有例外。"},{"en":"We can make an exception in this case.","zh-TW":"在這種情況下我們可以破例。"}]', '{"noun":"exception","adjective":"exceptional","adverb":"exceptionally"}', NULL, 3, 2550, NULL),
(2551, 'excess', '/ɪkˈses/', 'noun / adjective', '{"zh-TW":["過量；多餘的"],"en":["more than necessary or permitted"]}', NULL, 'in excess of / excess baggage', '[{"en":"Costs were in excess of the budget.","zh-TW":"費用超過了預算。"},{"en":"Excess inventory should be sold at a discount.","zh-TW":"多餘的庫存應打折出售。"}]', '{"noun":"excess","adjective":"excessive","adverb":"excessively"}', NULL, 2, 2551, NULL),
(2552, 'excess inventory', '/ɪkˈses ɪnˈventɔːri/', 'noun', '{"zh-TW":["過剩庫存；滯銷庫存"],"en":["stock that exceeds current or projected demand"]}', NULL, 'reduce excess inventory / clear excess inventory', '[{"en":"Excess inventory was sold at a discount to free up warehouse space.","zh-TW":"過剩庫存以折扣出售，以釋放倉庫空間。"},{"en":"Better demand forecasting helped reduce excess inventory by 40%.","zh-TW":"更好的需求預測有助於將過剩庫存減少40%。"}]', NULL, NULL, 5, 2552, NULL),
(2553, 'exchange', '/ɪksˈtʃeɪndʒ/', 'noun / verb', '{"zh-TW":["交換；兌換"],"en":["to give and receive; a place for trading","to give something and receive something in return"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"change","meaning":"change (改變)"},"logic":"把東西拿出來改變，即「交換」。"}', 'exchange rate / in exchange for; exchange rate / exchange information', '[{"en":"What is today''s exchange rate?","zh-TW":"今天的匯率是多少？"},{"en":"They exchanged business cards at the conference.","zh-TW":"他們在會議上交換了名片。"},{"en":"Can I exchange this shirt for a larger size?","zh-TW":"我可以把這件襯衫換大一號嗎？"},{"en":"They exchanged contact information.","zh-TW":"他們交換了聯絡資訊。"}]', '{"noun":"exchange","verb":"exchange","adjective":"exchangeable"}', NULL, 3, 2553, NULL),
(2554, 'exchange booth', '/''ɪkstʃeɪndʒ buːθ/', 'noun', '{"zh-TW":["外幣兌換亭；貨幣兌換處"],"en":["a small kiosk or counter where currencies are exchanged"]}', NULL, 'find an exchange booth / airport exchange booth / convenient exchange booth', '[{"en":"There is an exchange booth at the airport arrivals hall.","zh-TW":"機場入境大廳有一個外幣兌換亭。"},{"en":"Exchange booths at tourist areas often offer less favorable rates than banks.","zh-TW":"旅遊區的外幣兌換亭通常提供比銀行不太優惠的匯率。"}]', NULL, NULL, 5, 2554, NULL),
(2555, 'exchange controls', '/ɪksˈtʃeɪndʒ kənˈtroʊlz/', 'noun', '{"zh-TW":["外匯管制"],"en":["government restrictions on the purchase or sale of foreign currencies"]}', NULL, 'impose exchange controls / relax exchange controls', '[{"en":"Exchange controls limited the company''s ability to repatriate profits.","zh-TW":"外匯管制限制了公司匯回利潤的能力。"},{"en":"Some developing countries impose exchange controls to protect their currency.","zh-TW":"一些發展中國家實施外匯管制以保護其貨幣。"}]', NULL, NULL, 5, 2555, NULL),
(2556, 'exchange policy', '/ɪksˈtʃeɪndʒ ˈpɒlɪsi/', 'noun', '{"zh-TW":["換貨政策"],"en":["the rules governing the exchange of purchased items"]}', NULL, 'flexible exchange policy / review the exchange policy', '[{"en":"The store has a 30-day exchange policy.","zh-TW":"這家商店有30天的換貨政策。"},{"en":"Please read the exchange policy before making your purchase.","zh-TW":"購買前請閱讀換貨政策。"}]', NULL, NULL, 5, 2556, NULL),
(2557, 'exchange rate', '/ɪksˈtʃeɪndʒ reɪt/', 'noun', '{"zh-TW":["匯率"],"en":["the value of one currency compared to another"]}', NULL, 'favorable exchange rate / exchange rate fluctuation', '[{"en":"The exchange rate affected the cost of our overseas purchase.","zh-TW":"匯率影響了我們的海外採購成本。"},{"en":"Monitor exchange rate fluctuations before converting money.","zh-TW":"在換錢前監測匯率波動。"}]', NULL, NULL, 5, 2557, NULL),
(2558, 'exchange rate risk', '/ɪksˈtʃeɪndʒ reɪt rɪsk/', 'noun', '{"zh-TW":["匯率風險"],"en":["the risk that changes in currency values will affect business outcomes"]}', NULL, 'manage exchange rate risk / hedge exchange rate risk', '[{"en":"The importer hedged exchange rate risk using forward contracts.","zh-TW":"進口商使用遠期合約對沖了匯率風險。"},{"en":"Exchange rate risk is particularly relevant in cross-border transactions.","zh-TW":"匯率風險在跨境交易中尤為相關。"}]', NULL, NULL, 5, 2558, NULL),
(2559, 'exchange student', '/ɪksˈtʃeɪndʒ ˈstjuːdənt/', 'noun', '{"zh-TW":["交換學生"],"en":["a student who studies temporarily at another institution abroad"]}', NULL, 'host an exchange student / exchange student program', '[{"en":"She participated as an exchange student in Germany.","zh-TW":"她以交換學生的身份在德國學習。"},{"en":"Exchange student programs promote cultural understanding.","zh-TW":"交換學生計劃促進了文化理解。"}]', NULL, NULL, 5, 2559, NULL),
(2560, 'exchange-traded fund', '/ɪksˈtʃeɪndʒ ˈtreɪdɪd fʌnd/', 'noun', '{"zh-TW":["交易所買賣基金"],"en":["an investment fund traded on a stock exchange like a regular share"]}', NULL, 'invest in an ETF / ETF performance', '[{"en":"ETFs offer low-cost exposure to diversified portfolios.","zh-TW":"交易所買賣基金提供低成本的多元化投資組合敞口。"},{"en":"She shifted from actively managed funds to ETFs to reduce fees.","zh-TW":"她從主動管理基金轉向了交易所買賣基金以降低費用。"}]', '{"abbreviation":"ETF"}', NULL, 5, 2560, NULL),
(2561, 'excise duty', '/ˈeksaɪz ˈdjuːti/', 'noun', '{"zh-TW":["消費稅；貨物稅"],"en":["a tax levied on specific goods such as alcohol, tobacco, or fuel"]}', NULL, 'pay excise duty / excise duty rate', '[{"en":"Excise duty on alcohol was increased in the annual budget.","zh-TW":"消費稅在年度預算中提高了對酒精的稅率。"},{"en":"Importers must pay excise duty before goods are released from customs.","zh-TW":"進口商必須在貨物從海關放行前繳納消費稅。"}]', NULL, NULL, 4, 2561, NULL),
(2562, 'excited', '/ɪkˈsaɪtɪd/', 'adjective', '{"zh-TW":["興奮的；激動的"],"en":["feeling great enthusiasm"]}', NULL, 'get excited / excited about', '[{"en":"We are excited about the new product launch.","zh-TW":"我們對新產品上市感到興奮。"},{"en":"The team is excited to start.","zh-TW":"團隊很期待開始。"}]', '{"adjective":"excited","verb":"excite","noun":"excitement","adjective2":"exciting"}', NULL, 3, 2562, NULL),
(2563, 'exciting', 'ɪkˈsaɪtɪŋ', 'adjective', '{"zh-TW":["令人興奮的；刺激的","有趣的"],"en":["causing enthusiasm","stimulating"]}', NULL, 'exciting opportunity/exciting news', '[{"en":"This is an exciting opportunity for the company.","zh-TW":"這是公司的一個令人興奮的機會。"}]', '{"verb":"excite","noun":"excitement","adverb":"excitingly"}', NULL, 3, 2563, NULL),
(2564, 'exclude', '/ɪkˈskluːd/', 'verb', '{"zh-TW":["排除；排斥"],"en":["to prevent from being included"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"clude","meaning":"close (關閉)"},"logic":"關在外面，即「排除」。"}', 'exclude from; exclude from / exclude the possibility', '[{"en":"Tax is excluded from the listed price.","zh-TW":"標示價格不含稅。"},{"en":"Some items are excluded from the warranty.","zh-TW":"某些物品不在保固範圍內。"},{"en":"The price excludes tax and delivery.","zh-TW":"價格不含稅和運費。"},{"en":"Don''t exclude anyone from the discussion.","zh-TW":"不要把任何人排除在討論之外。"}]', '{"noun":"exclusion","verb":"exclude","adjective":"exclusive"}', NULL, 3, 2564, NULL),
(2565, 'exclusion clause', '/ɪkˈskluːʒən klɔːz/', 'noun', '{"zh-TW":["免責條款；排除條款"],"en":["a contract term that limits or excludes liability for certain events"]}', NULL, 'include an exclusion clause / rely on the exclusion clause', '[{"en":"The exclusion clause exempted the company from liability for force majeure.","zh-TW":"免責條款使公司免於對不可抗力事件承擔責任。"},{"en":"The exclusion clause was challenged and found to be unenforceable.","zh-TW":"免責條款受到質疑，被認定為不可執行。"}]', NULL, NULL, 5, 2565, NULL),
(2566, 'exclusive', '/ɪkˈskluːsɪv/', 'adjective', '{"zh-TW":["獨家的；專屬的"],"en":["limited to one person or group; high-end"]}', NULL, 'exclusive deal/rights', '[{"en":"We signed an exclusive distribution agreement.","zh-TW":"我們簽署了獨家經銷協議。"},{"en":"The hotel caters to an exclusive clientele.","zh-TW":"這家飯店專門服務高端客戶。"}]', '{"noun":"exclusivity","adjective":"exclusive","adverb":"exclusively"}', NULL, 3, 2566, 353),
(2567, 'exclusive distribution', '/ɪkˈskluːsɪv ˌdɪstrɪˈbjuːʃən/', 'noun', '{"zh-TW":["獨家分銷"],"en":["an arrangement where only one distributor is authorized to sell in a territory"]}', NULL, 'grant exclusive distribution rights / exclusive distribution agreement', '[{"en":"An exclusive distribution deal was signed for the Asia-Pacific region.","zh-TW":"簽署了亞太地區的獨家分銷協議。"},{"en":"Exclusive distribution limits competition but requires strong marketing efforts.","zh-TW":"獨家分銷限制了競爭，但需要強有力的行銷工作。"}]', NULL, NULL, 5, 2567, NULL),
(2568, 'exclusive rights', '/ɪkˈskluːsɪv raɪts/', 'noun', '{"zh-TW":["獨家權利"],"en":["the sole authorization to use, sell, or distribute something in a specific market"]}', NULL, 'grant exclusive rights / exclusive rights agreement', '[{"en":"The publisher acquired exclusive rights to distribute the series in Asia.","zh-TW":"出版商獲得了在亞洲分銷該系列的獨家權利。"},{"en":"Exclusive rights arrangements restrict competitors from entering the market.","zh-TW":"獨家權利安排限制了競爭對手進入市場。"}]', NULL, NULL, 5, 2568, NULL),
(2569, 'exclusivity clause', '/ɪkˌskluːˈsɪvɪti klɔːz/', 'noun', '{"zh-TW":["獨家條款"],"en":["a contract provision preventing parties from working with competitors"]}', NULL, 'include an exclusivity clause / exclusivity clause period', '[{"en":"The distribution agreement includes a two-year exclusivity clause.","zh-TW":"分銷協議包含兩年的獨家條款。"},{"en":"The exclusivity clause prevented the supplier from selling to rivals.","zh-TW":"獨家條款阻止了供應商向競爭對手出售。"}]', NULL, NULL, 5, 2569, NULL),
(2570, 'exculpatory', '/ɪkˈskʌlpətəri/', 'adjective', '{"zh-TW":["免罪的；開脫的"],"en":["tending to clear someone from fault or guilt"]}', NULL, 'exculpatory evidence / exculpatory clause / exculpatory statement', '[{"en":"The defense attorney found exculpatory evidence that changed the verdict.","zh-TW":"辯護律師找到了改變裁決的免罪證據。"},{"en":"Prosecutors must disclose exculpatory evidence to the defense.","zh-TW":"檢察官必須向辯護方披露免罪證據。"}]', NULL, NULL, 4, 2570, NULL),
(2571, 'excursion', '/ɪkˈskɜːrʒən/', 'noun', '{"zh-TW":["短途旅遊；遠足"],"en":["a short trip made for pleasure"]}', NULL, 'day excursion / optional excursion', '[{"en":"We booked an excursion to the nearby volcano.","zh-TW":"我們預訂了前往附近火山的一日遊。"},{"en":"The cruise offers several excursions at each port.","zh-TW":"郵輪在每個港口提供多種短途遊覽。"}]', NULL, NULL, 3, 2571, NULL),
(2572, 'excursion ticket', '/''ɪkˈskɜːʃən ˌtɪkɪt/', 'noun', '{"zh-TW":["短程旅行票；遊覽票"],"en":["a specially priced ticket for a short journey or trip, often at a reduced fare"]}', NULL, 'buy an excursion ticket / discounted excursion ticket', '[{"en":"She bought an excursion ticket to take a day trip to the countryside.","zh-TW":"她買了一張短程旅行票，前往鄉村進行一日遊。"},{"en":"Excursion tickets are available at reduced prices for group bookings.","zh-TW":"短程旅行票對於團體預訂可享有折扣價格。"}]', NULL, NULL, 5, 2572, NULL),
(2573, 'execute', '/ˈeksɪkjuːt/', 'verb', '{"zh-TW":["執行；實施"],"en":["to carry out a plan or action"]}', NULL, 'execute a plan/strategy', '[{"en":"The team executed the project flawlessly.","zh-TW":"團隊完美地執行了項目。"},{"en":"The strategy was well executed.","zh-TW":"該策略執行得很好。"}]', '{"noun":"execution/executive","verb":"execute"}', NULL, 3, 2573, 354),
(2574, 'executive', '/ɪɡˈzekjʊtɪv/', 'noun', '{"zh-TW":["高管；主管"],"en":["a senior manager with significant decision-making authority"]}', NULL, 'senior executive / top executive / executive team / executive decision', '[{"en":"The executive team approved the new strategic direction.","zh-TW":"高管團隊批准了新的戰略方向。"},{"en":"She joined as a senior executive responsible for global sales.","zh-TW":"她以負責全球銷售的高管身份加入。"}]', '{"plural":"executives","adjective":"executive"}', NULL, 3, 2574, 118),
(2575, 'executive committee', '/ɪɡˈzekjʊtɪv kəˈmɪti/', 'noun', '{"zh-TW":["執行委員會"],"en":["the senior leadership group responsible for running an organization"]}', NULL, 'executive committee meeting / executive committee decision / sit on the executive committee', '[{"en":"The executive committee approved the new acquisition strategy.","zh-TW":"執行委員會批准了新的收購策略。"},{"en":"Major decisions are escalated to the executive committee for approval.","zh-TW":"重大決策被上報執行委員會審批。"}]', '{"abbreviation":"ExCo"}', NULL, 5, 2575, NULL),
(2576, 'executive compensation', '/ɪɡˈzekjʊtɪv ˌkɒmpenˈseɪʃən/', 'noun', '{"zh-TW":["高管薪酬"],"en":["the total pay package provided to senior executives of a company"]}', NULL, 'disclose executive compensation / executive compensation structure', '[{"en":"The executive compensation package included salary, bonus, and stock options.","zh-TW":"高管薪酬方案包括薪資、獎金和股票期權。"},{"en":"Shareholders voted on the executive compensation policy at the annual meeting.","zh-TW":"股東在年會上就高管薪酬政策進行了投票。"}]', NULL, NULL, 5, 2576, NULL),
(2577, 'executive education', '/''ɪɡˌzekjʊtɪv ˌedʒʊˈkeɪʃən/', 'noun', '{"zh-TW":["高管教育；主管培訓"],"en":["educational programs designed for working professionals and corporate executives"]}', NULL, 'enroll in executive education / executive education program / executive education MBA', '[{"en":"She completed an executive education program to prepare for a senior leadership role.","zh-TW":"她完成了一個高管教育計劃，為高級領導職位做準備。"},{"en":"Top business schools offer executive education programs tailored to industry needs.","zh-TW":"頂尖商學院提供針對行業需求量身定制的高管教育計劃。"}]', NULL, NULL, 5, 2577, NULL),
(2578, 'executive lounge', '/ɪɡˈzɛkjʊtɪv laʊndʒ/', 'noun', '{"zh-TW":["行政貴賓室"],"en":["a premium lounge in a hotel for executive floor guests"]}', NULL, 'access the executive lounge / executive lounge benefits', '[{"en":"Executive lounge guests enjoy complimentary snacks and drinks.","zh-TW":"行政貴賓室賓客享有免費零食和飲料。"},{"en":"The executive lounge offers a quiet workspace for business travelers.","zh-TW":"行政貴賓室為商務旅客提供安靜的工作空間。"}]', NULL, NULL, 5, 2578, NULL),
(2579, 'executive summary', '/ɪɡˈzekjʊtɪv ˈsʌməri/', 'noun', '{"zh-TW":["執行摘要"],"en":["a brief overview of a longer document for quick decision-making"]}', NULL, 'prepare an executive summary / executive summary of the report', '[{"en":"The executive summary allowed the board to grasp the key points quickly.","zh-TW":"執行摘要讓董事會快速掌握了要點。"},{"en":"A well-written executive summary is essential for business proposals.","zh-TW":"精心撰寫的執行摘要對商業提案至關重要。"}]', NULL, NULL, 5, 2579, NULL),
(2580, 'exemplar', '/ɪɡˈzemplaːr/', 'noun', '{"zh-TW":["榜樣；典範"],"en":["a person or thing serving as a typical example or excellent model"]}', NULL, 'serve as an exemplar / follow as an exemplar / national exemplar', '[{"en":"She was held up as an exemplar of professional excellence in the field.","zh-TW":"她被譽為該領域職業卓越的典範。"},{"en":"The company''s ethical practices made it an exemplar for others in the industry to follow.","zh-TW":"公司的道德實踐使其成為行業內其他公司效仿的典範。"}]', '{"adjective":"exemplary","verb":"exemplify"}', NULL, 3, 2580, NULL),
(2581, 'exemplify', '/ɪɡˈzemplɪfaɪ/', 'verb', '{"zh-TW":["例示；說明"],"en":["to be a typical example of; to illustrate by example"]}', NULL, 'exemplify best practice / exemplify a concept / exemplify the trend', '[{"en":"This case study exemplifies the challenges of market entry.","zh-TW":"這個案例研究說明了市場進入的挑戰。"},{"en":"The diagram exemplifies how the components interact.","zh-TW":"該圖表說明了各組件如何相互作用。"}]', '{"noun":"exemplification","noun2":"example"}', NULL, 3, 2581, NULL),
(2582, 'exempt', '/ɪɡˈzempt/', 'adjective / verb', '{"zh-TW":["免除的；豁免"],"en":["free from an obligation or liability"]}', NULL, 'exempt from tax/duty', '[{"en":"Non-profit organizations are exempt from taxes.","zh-TW":"非營利組織免稅。"},{"en":"Small businesses may be exempted from the regulation.","zh-TW":"小型企業可能免於遵守該法規。"}]', '{"noun":"exemption","verb":"exempt","adjective":"exempt"}', NULL, 2, 2582, NULL),
(2583, 'exercise', '/ˈeksərsaɪz/', 'noun / verb', '{"zh-TW":["運動；行使"],"en":["physical activity; to use a right or power"]}', NULL, 'exercise caution/authority', '[{"en":"Please exercise caution when handling chemicals.","zh-TW":"處理化學品時請小心謹慎。"},{"en":"Shareholders may exercise their voting rights.","zh-TW":"股東可以行使投票權。"}]', '{"noun":"exercise","verb":"exercise"}', NULL, 3, 2583, NULL),
(2584, 'exhaust', '/ɪɡˈzɔːst/', 'verb / noun', '{"zh-TW":["耗盡；排氣"],"en":["to use up completely; waste gases"]}', NULL, 'exhaust all options/resources', '[{"en":"We have exhausted all possible solutions.","zh-TW":"我們已經用盡了所有可能的解決方案。"},{"en":"Vehicle exhaust contributes to air pollution.","zh-TW":"汽車排氣造成空氣污染。"}]', '{"noun":"exhaustion/exhaust","verb":"exhaust","adjective":"exhausting/exhausted/exhaustive"}', NULL, 3, 2584, NULL),
(2585, 'exhaustive', '/''ɪɡˈzɔːstɪv/', 'adjective', '{"zh-TW":["詳盡的；徹底的"],"en":["including or considering all elements or aspects; fully comprehensive"]}', NULL, 'exhaustive research / exhaustive list / exhaustive testing', '[{"en":"The committee conducted an exhaustive review of all applicants.","zh-TW":"委員會對所有申請人進行了詳盡的審查。"},{"en":"The engineer ran exhaustive tests before the software was released to the public.","zh-TW":"工程師在軟體向公眾發布之前進行了徹底的測試。"}]', '{"adverb":"exhaustively","noun":"exhaustiveness"}', NULL, 4, 2585, NULL),
(2586, 'exhibit', '/ɪɡˈzɪbɪt/', 'verb / noun', '{"zh-TW":["展覽；展示","展覽品；展覽"],"en":["to show publicly; a display","an object displayed in a museum","a public display of art or other items"]}', '{"prefix":{"text":"ex-","meaning":"out (外)"},"root":{"text":"hibit","meaning":"hold (持有)"},"logic":"拿出來展示，即「展覽」。"}', 'exhibit at a trade show; art exhibit / exhibit hall / on exhibit', '[{"en":"The company will exhibit at the trade fair.","zh-TW":"公司將在商展上展覽。"},{"en":"The museum has a new exhibit on technology.","zh-TW":"博物館有一個新的科技展覽。"},{"en":"The museum has a new dinosaur exhibit.","zh-TW":"博物館有新的恐龍展覽。"},{"en":"Her paintings are on exhibit at the gallery.","zh-TW":"她的畫作正在畫廊展出。"}]', '{"noun":"exhibit/exhibition/exhibitor","verb":"exhibit"}', NULL, 3, 2586, 119),
(2587, 'exhibition', '/ˌɛksɪˈbɪʃən/', 'noun', '{"zh-TW":["展覽"],"en":["a public display of art or objects"]}', NULL, 'art exhibition / on exhibition', '[{"en":"The exhibition runs until March.","zh-TW":"展覽持續到三月。"},{"en":"We visited an art exhibition.","zh-TW":"我們參觀了一場藝術展覽。"}]', '{"verb":"exhibit","noun2":"exhibit"}', NULL, 4, 2587, NULL),
(2588, 'exist', '/ɪɡˈzɪst/', 'verb', '{"zh-TW":["存在"],"en":["to be real; to have actual being"]}', NULL, 'already exist / cease to exist', '[{"en":"The problem still exists.","zh-TW":"問題仍然存在。"},{"en":"Does a solution already exist?","zh-TW":"已經有解決方案了嗎？"}]', '{"verb":"exist","noun":"existence","adjective":"existing","adjective2":"existent"}', NULL, 2, 2588, NULL),
(2589, 'exit barrier', '/ˈeksɪt ˈbæriər/', 'noun', '{"zh-TW":["退出壁壘"],"en":["factors that make it difficult for a company to leave a market or industry"]}', NULL, 'face exit barriers / overcome exit barriers', '[{"en":"High exit barriers trapped the company in a loss-making business segment.","zh-TW":"高退出壁壘使公司陷入虧損的業務板塊。"},{"en":"Long-term contracts with suppliers create significant exit barriers.","zh-TW":"與供應商的長期合約創造了顯著的退出壁壘。"}]', '{"opposite":"entry barrier"}', NULL, 4, 2589, NULL),
(2590, 'exit interview', '/ˈeksɪt ˈɪntərvjuː/', 'noun', '{"zh-TW":["離職面談"],"en":["a meeting conducted when an employee leaves to understand their reasons"]}', NULL, 'conduct an exit interview / exit interview questions / post-exit interview', '[{"en":"The exit interview revealed recurring issues with management style.","zh-TW":"離職面談揭示了與管理風格相關的反覆問題。"},{"en":"HR conducts exit interviews to identify areas of improvement.","zh-TW":"人力資源部進行離職面談以識別改進領域。"}]', NULL, NULL, 5, 2590, NULL),
(2591, 'exit multiple', '/ˈeksɪt ˈmʌltɪpəl/', 'noun', '{"zh-TW":["退出倍數"],"en":["the ratio of final investment value to initial investment at the time of exit"]}', NULL, 'calculate the exit multiple / target exit multiple', '[{"en":"The private equity fund achieved an exit multiple of 3.5 times invested capital.","zh-TW":"私募股權基金實現了3.5倍投入資本的退出倍數。"},{"en":"Exit multiple is a key return metric for private equity investors.","zh-TW":"退出倍數是私募股權投資者的關鍵回報指標。"}]', NULL, NULL, 5, 2591, NULL),
(2592, 'exit strategy', '/ˈɛɡzɪt ˈstrætɪdʒi/', 'noun', '{"zh-TW":["退場策略；出場策略"],"en":["a plan for leaving an investment or business position"]}', NULL, 'develop an exit strategy / execute an exit strategy', '[{"en":"Investors require a clear exit strategy before committing funds.","zh-TW":"投資者在投入資金前需要清晰的退場策略。"},{"en":"The founders planned their exit strategy carefully before selling.","zh-TW":"創辦人在出售前仔細規劃了退場策略。"}]', NULL, NULL, 5, 2592, NULL),
(2593, 'exogenous', '/eksˈɒdʒɪnəs/', 'adjective', '{"zh-TW":["外源性的；外生的"],"en":["originating from outside a system"]}', NULL, 'exogenous shock / exogenous variable / exogenous growth factor', '[{"en":"An oil price spike is an exogenous shock that can derail economic growth.","zh-TW":"油價飆升是一種可能破壞經濟增長的外生衝擊。"},{"en":"The model controls for exogenous factors beyond the firm''s control.","zh-TW":"模型控制了公司無法控制的外生因素。"}]', '{"adverb":"exogenously","antonym":"endogenous"}', NULL, 3, 2593, NULL),
(2594, 'expand', '/ɪkˈspænd/', 'verb', '{"zh-TW":["擴展；擴大"],"en":["to increase in size, number, or importance"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"pand","meaning":"spread (展開)"},"logic":"向外展開，即「擴展」。"}', 'expand operations/business; expand business / expand into new markets', '[{"en":"The company plans to expand into new markets.","zh-TW":"公司計劃擴展到新市場。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品範圍。"},{"en":"The company plans to expand into Asia.","zh-TW":"公司計畫擴展到亞洲。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品線。"}]', '{"noun":"expansion","verb":"expand"}', NULL, 2, 2594, 120),
(2595, 'expansion', '/ɪkˈspænʃən/', 'noun', '{"zh-TW":["擴張；擴展"],"en":["the process of increasing in size, scope, or reach"]}', NULL, 'market expansion / business expansion / rapid expansion', '[{"en":"The company is planning expansion into Asian markets.","zh-TW":"公司正計劃向亞洲市場擴張。"},{"en":"Expansion into new territories requires careful planning.","zh-TW":"進入新領域需要仔細規劃。"}]', '{"verb":"expand","adjective":"expanded"}', NULL, 3, 2595, 566),
(2596, 'expansion funding', '/ɪkˈspænʃən ˈfʌndɪŋ/', 'noun', '{"zh-TW":["擴張資金；擴展融資"],"en":["money raised specifically to finance business growth"]}', NULL, 'secure expansion funding / expansion funding round', '[{"en":"The company secured 15 million in expansion funding.","zh-TW":"公司獲得了1500萬元的擴張資金。"},{"en":"Expansion funding was used to open three new regional offices.","zh-TW":"擴張資金用於開設三個新的區域辦公室。"}]', NULL, NULL, 5, 2596, NULL),
(2597, 'expansion plan', '/ɪkˈspænʃən plæn/', 'noun', '{"zh-TW":["擴張計劃"],"en":["a strategy for growing a business into new markets or products"]}', NULL, 'approve an expansion plan / execute an expansion plan', '[{"en":"The board approved a three-year expansion plan into Southeast Asia.","zh-TW":"董事會批准了進入東南亞的三年擴張計劃。"},{"en":"The expansion plan was delayed due to market uncertainty.","zh-TW":"擴張計劃因市場不確定性而延遲了。"}]', NULL, NULL, 5, 2597, NULL),
(2598, 'expatriate', '/ˈekspætriət/', 'noun', '{"zh-TW":["外派員工；海外派駐人員"],"en":["an employee working in a country other than their home country"]}', NULL, 'expatriate assignment / expatriate package / manage expatriates', '[{"en":"The company sent several expatriates to manage the new office.","zh-TW":"公司派遣了幾名外派員工管理新辦公室。"},{"en":"Expatriate packages typically include housing and travel allowances.","zh-TW":"外派員工方案通常包括住房和差旅津貼。"}]', '{"abbreviation":"expat","verb":"expatriate"}', NULL, 4, 2598, NULL),
(2599, 'expect', '/ɪkˈspekt/', 'verb', '{"zh-TW":["期望；預期"],"en":["to believe something will happen"]}', NULL, 'expect + to / be expected to', '[{"en":"We expect revenue to increase next year.","zh-TW":"我們預期明年收入會增加。"},{"en":"Employees are expected to follow the dress code.","zh-TW":"員工被期望遵守服裝規定。"}]', '{"noun":"expectation","verb":"expect","adjective":"expected"}', NULL, 2, 2599, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2600, 'expedient', '/''ɪkˈspiːdiənt/', 'adjective', '{"zh-TW":["便利的；得當的"],"en":["convenient and practical, even if improper or immoral; based on what is useful rather than what is right"]}', NULL, 'expedient solution / politically expedient / expedient choice', '[{"en":"The company chose the most expedient solution rather than the most ethical one.","zh-TW":"公司選擇了最便利的解決方案，而不是最道德的。"},{"en":"An expedient decision might solve the immediate problem but create future complications.","zh-TW":"一個便利的決定可能解決了眼前的問題，但會造成未來的複雜性。"}]', '{"noun":"expediency","adverb":"expediently"}', NULL, 3, 2600, NULL),
(2601, 'expedient solution', '/''ɪkˌspiːdiənt səˌluːʃən/', 'noun', '{"zh-TW":["權宜之計；便宜行事的解決方案"],"en":["a solution that is convenient and practical but not always the most ethical or principled"]}', NULL, 'choose an expedient solution / short-term expedient solution', '[{"en":"The company chose an expedient solution to the problem rather than addressing the root cause.","zh-TW":"公司選擇了對問題的權宜之計，而不是解決根本原因。"},{"en":"An expedient solution may solve the immediate crisis but create bigger problems later.","zh-TW":"權宜之計可能解決了眼前的危機，但以後會製造更大的問題。"}]', NULL, NULL, 5, 2601, NULL),
(2602, 'expedite', '/ˈekspədaɪt/', 'verb', '{"zh-TW":["加快；促進"],"en":["to make a process happen more quickly"]}', NULL, 'expedite the process/delivery', '[{"en":"We can expedite shipping for an extra fee.","zh-TW":"我們可以加收費用加快出貨。"},{"en":"Please expedite the approval process.","zh-TW":"請加快審批流程。"}]', '{"verb":"expedite","adjective":"expedited"}', NULL, 3, 2602, 682),
(2603, 'expedited shipping', '/''ekspɪdaɪtɪd ˌʃɪpɪŋ/', 'noun', '{"zh-TW":["加急運輸；快速配送"],"en":["a faster shipping option that delivers goods more quickly than standard shipping for an additional fee"]}', NULL, 'choose expedited shipping / expedited shipping cost / offer expedited shipping', '[{"en":"She chose expedited shipping to ensure the birthday gift arrived on time.","zh-TW":"她選擇了加急運輸，確保生日禮物準時到達。"},{"en":"Expedited shipping costs three times more but guarantees delivery within two days.","zh-TW":"加急運輸的費用是普通運輸的三倍，但保證在兩天內送達。"}]', NULL, NULL, 5, 2603, NULL),
(2604, 'expedition', '/''ekspɪˌdɪʃən/', 'noun', '{"zh-TW":["遠征；考察旅行"],"en":["a journey undertaken for a specific purpose, especially exploration or research"]}', NULL, 'lead an expedition / join an expedition / polar expedition', '[{"en":"The scientific expedition discovered several new plant species.","zh-TW":"這次科學考察旅行發現了幾種新植物。"},{"en":"He organized an expedition to the summit of Mount Everest.","zh-TW":"他組織了一次攀登珠穆朗瑪峰的遠征。"}]', NULL, NULL, 4, 2604, NULL),
(2605, 'expenditure', '/ɪkˈspendɪtʃər/', 'noun', '{"zh-TW":["支出；開支"],"en":["the action of spending money; an amount spent"]}', NULL, 'capital/government expenditure', '[{"en":"Total expenditure exceeded the budget.","zh-TW":"總支出超過了預算。"},{"en":"Capital expenditure was reduced this year.","zh-TW":"今年資本支出減少了。"}]', '{"noun":"expenditure","verb":"expend"}', NULL, 4, 2605, 568),
(2606, 'expenditure control', '/ɪkˈspendɪtʃər kənˈtroʊl/', 'noun', '{"zh-TW":["支出控制"],"en":["managing and limiting how funds are spent within a budget"]}', NULL, 'tighten expenditure control / expenditure control measures', '[{"en":"Expenditure control was tightened after the budget overrun.","zh-TW":"預算超支後加強了支出控制。"},{"en":"Monthly expenditure control reports were submitted to the finance committee.","zh-TW":"每月支出控制報告提交給財務委員會。"}]', NULL, NULL, 5, 2606, NULL),
(2607, 'expenditure plan', '/ɪkˈspendɪtʃər plæn/', 'noun', '{"zh-TW":["支出計劃"],"en":["a document outlining planned spending activities and timing"]}', NULL, 'prepare an expenditure plan / approve the expenditure plan', '[{"en":"The department submitted its expenditure plan for the next fiscal year.","zh-TW":"部門提交了下一財政年度的支出計劃。"},{"en":"The expenditure plan was revised to align with budget constraints.","zh-TW":"支出計劃修訂以符合預算限制。"}]', NULL, NULL, 5, 2607, NULL),
(2608, 'expenditure review', '/ɪkˈspendɪtʃər rɪˈvjuː/', 'noun', '{"zh-TW":["支出審查"],"en":["an assessment of spending to identify inefficiencies or savings"]}', NULL, 'conduct an expenditure review / annual expenditure review', '[{"en":"The expenditure review revealed 10% in wasteful spending.","zh-TW":"支出審查揭示了10%的浪費性支出。"},{"en":"All departments participated in the annual expenditure review.","zh-TW":"所有部門參與了年度支出審查。"}]', NULL, NULL, 5, 2608, NULL),
(2609, 'expense', '/ɪkˈspens/', 'noun', '{"zh-TW":["費用；開支"],"en":["the cost of something; money spent"]}', NULL, 'at the expense of / business expense', '[{"en":"Travel expenses will be reimbursed.","zh-TW":"差旅費用將報銷。"},{"en":"Profit should not come at the expense of quality.","zh-TW":"利潤不應以犧牲品質為代價。"}]', '{"noun":"expense","adjective":"expensive"}', NULL, 3, 2609, 121),
(2610, 'expense account', '/ɪkˈspens əˈkaʊnt/', 'noun', '{"zh-TW":["費用帳戶；業務費用帳"],"en":["an account charged with approved work-related expenditures"]}', NULL, 'charge to expense account / expense account policy', '[{"en":"Business meals and travel can be charged to the expense account.","zh-TW":"商務餐和差旅費可以記入費用帳戶。"},{"en":"The expense account must be reconciled with receipts monthly.","zh-TW":"費用帳戶必須每月與收據進行對帳。"}]', NULL, NULL, 5, 2610, NULL),
(2611, 'expense claim', '/ɪkˈspens kleɪm/', 'noun', '{"zh-TW":["費用報銷申請"],"en":["a request by an employee to be reimbursed for work-related expenses"]}', NULL, 'submit an expense claim / approve an expense claim', '[{"en":"All expense claims must be submitted within 30 days of the expense.","zh-TW":"所有費用報銷申請必須在費用發生後30天內提交。"},{"en":"The expense claim was rejected as it lacked supporting receipts.","zh-TW":"費用報銷申請因缺少支持收據而被拒絕。"}]', NULL, NULL, 5, 2611, NULL),
(2612, 'expense management', '/ɪkˈspɛns ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["費用管理"],"en":["the process of controlling business spending"]}', NULL, 'improve expense management / expense management software', '[{"en":"Expense management software helps track all company spending.","zh-TW":"費用管理軟體有助於追蹤所有公司支出。"},{"en":"Effective expense management improves the company''s bottom line.","zh-TW":"有效的費用管理改善了公司的底線。"}]', NULL, NULL, 5, 2612, NULL),
(2613, 'expense ratio', '/ɪkˈspens ˈreɪʃioʊ/', 'noun', '{"zh-TW":["費用比率"],"en":["the percentage of fund assets used to cover management and operating expenses"]}', NULL, 'compare expense ratios / low expense ratio', '[{"en":"Index funds typically have a much lower expense ratio than active funds.","zh-TW":"指數基金的費用比率通常遠低於主動管理基金。"},{"en":"The expense ratio directly reduces investor returns over time.","zh-TW":"費用比率隨時間推移直接降低了投資者回報。"}]', NULL, NULL, 5, 2613, NULL),
(2614, 'expense reimbursement', '/ɪkˈspens ˌriːɪmˈbɜːrsmənt/', 'noun', '{"zh-TW":["費用報銷"],"en":["the repayment by an employer of work-related expenses paid by an employee"]}', NULL, 'submit expense reimbursement / expense reimbursement policy', '[{"en":"All expense reimbursement claims must be submitted with receipts.","zh-TW":"所有費用報銷申請必須附上收據提交。"},{"en":"The company updated its expense reimbursement policy for travel.","zh-TW":"公司更新了差旅費用報銷政策。"}]', NULL, NULL, 5, 2614, NULL),
(2615, 'expense report', '/ɪkˈspɛns rɪˈpɔːrt/', 'noun', '{"zh-TW":["費用報告；報銷單"],"en":["a document listing work-related expenses for reimbursement"]}', NULL, 'submit an expense report / approve an expense report', '[{"en":"Please submit your expense report by the end of the month.","zh-TW":"請在月底前提交您的費用報告。"},{"en":"All receipts must be attached to the expense report.","zh-TW":"所有收據必須附在費用報告上。"}]', NULL, NULL, 5, 2615, NULL),
(2616, 'expensive', 'ɪkˈspɛnsɪv', 'adjective', '{"zh-TW":["昂貴的；高價的","費用高的"],"en":["costing a lot of money","high-priced"]}', NULL, 'expensive product/too expensive', '[{"en":"This software is too expensive for our budget.","zh-TW":"這款軟體對我們的預算來說太貴了。"}]', '{"noun":"expense","adverb":"expensively"}', NULL, 3, 2616, NULL),
(2617, 'experience', '/ɪkˈspɪriəns/', 'noun / verb', '{"zh-TW":["經驗；體驗"],"en":["knowledge gained through involvement; to encounter"]}', NULL, 'work/customer experience', '[{"en":"Do you have experience in project management?","zh-TW":"你有項目管理經驗嗎？"},{"en":"Customers experienced technical difficulties.","zh-TW":"客戶遇到了技術困難。"}]', '{"noun":"experience","verb":"experience","adjective":"experienced"}', NULL, 4, 2617, 122),
(2618, 'experiment', '/ɪkˈsperɪmənt/', 'noun / verb', '{"zh-TW":["實驗；試驗"],"en":["a scientific test; to try something new"]}', NULL, 'conduct an experiment', '[{"en":"The team conducted an experiment to test the theory.","zh-TW":"團隊進行了實驗來測試理論。"},{"en":"We are experimenting with new marketing channels.","zh-TW":"我們正在嘗試新的行銷渠道。"}]', '{"noun":"experiment/experimentation","verb":"experiment","adjective":"experimental"}', NULL, 4, 2618, NULL),
(2619, 'expert', '/ˈekspɜːrt/', 'noun / adjective', '{"zh-TW":["專家；專業的"],"en":["a person with great knowledge in a subject"]}', NULL, 'industry/subject expert', '[{"en":"She is an expert in international trade.","zh-TW":"她是國際貿易專家。"},{"en":"We consulted an expert on tax law.","zh-TW":"我們諮詢了一位稅法專家。"}]', '{"noun":"expert/expertise","adjective":"expert"}', NULL, 2, 2619, NULL),
(2620, 'expert witness', '/ˈekspɜːrt ˈwɪtnɪs/', 'noun', '{"zh-TW":["專家證人"],"en":["a qualified professional who provides testimony in legal proceedings"]}', NULL, 'call an expert witness / expert witness report', '[{"en":"The company hired an expert witness to support its case.","zh-TW":"公司聘請了一名專家證人支持其案件。"},{"en":"The expert witness provided a detailed valuation report.","zh-TW":"專家證人提供了詳細的估值報告。"}]', NULL, NULL, 5, 2620, NULL),
(2621, 'expertise', 'ˌɛkspɜːrˈtiːz', 'noun', '{"zh-TW":["專業知識；技能","專長"],"en":["expert knowledge","a high level of skill"]}', NULL, 'domain expertise/technical expertise', '[{"en":"Her expertise in finance is valuable.","zh-TW":"她在財務方面的專業知識很有價值。"}]', '{"adjective":"expert","adverb":"expertly"}', NULL, 3, 2621, NULL),
(2622, 'expiration', '/ˌɛkspɪˈreɪʃən/', 'noun', '{"zh-TW":["到期；屆滿"],"en":["the end of the period during which something is valid"]}', NULL, 'contract expiration / expiration date', '[{"en":"The contract is approaching its expiration date.","zh-TW":"合約即將到期。"},{"en":"Renew your license before its expiration.","zh-TW":"請在到期前更新您的執照。"}]', '{"verb":"expire","adjective":"expired"}', NULL, 4, 2622, 356),
(2623, 'expire', '/ɪkˈspaɪər/', 'verb', '{"zh-TW":["到期；過期"],"en":["to come to the end of validity"]}', NULL, 'expire on/contract expires', '[{"en":"Your contract expires at the end of the month.","zh-TW":"你的合約月底到期。"},{"en":"The coupon expired yesterday.","zh-TW":"優惠券昨天過期了。"}]', '{"noun":"expiration/expiry","verb":"expire","adjective":"expired"}', NULL, 2, 2623, NULL),
(2624, 'explain', '/ɪkˈspleɪn/', 'verb', '{"zh-TW":["解釋；說明"],"en":["to make something clear"]}', NULL, 'explain how/why', '[{"en":"Can you explain the procedure?","zh-TW":"你能解釋一下流程嗎？"},{"en":"She explained why the project was delayed.","zh-TW":"她解釋了為什麼項目延遲了。"}]', '{"noun":"explanation","verb":"explain","adjective":"explanatory"}', NULL, 3, 2624, NULL),
(2625, 'explicit', '/ɪkˈsplɪsɪt/', 'adjective', '{"zh-TW":["明確的；清楚的"],"en":["stated clearly and in detail"]}', NULL, 'explicit instructions/consent', '[{"en":"The contract contains explicit terms.","zh-TW":"合約包含明確的條款。"},{"en":"You need explicit permission to proceed.","zh-TW":"你需要明確的許可才能繼續。"}]', '{"adjective":"explicit","adverb":"explicitly"}', NULL, 3, 2625, 683),
(2626, 'explicit cost', '/ɪkˈsplɪsɪt kɒst/', 'noun', '{"zh-TW":["顯性成本；明確成本"],"en":["a direct, clear, and easily measurable cost such as wages or rent"]}', NULL, 'calculate explicit costs / explicit vs implicit costs', '[{"en":"Rent and salaries are explicit costs that appear directly on financial statements.","zh-TW":"租金和薪資是直接出現在財務報表上的顯性成本。"},{"en":"Explicit costs are easier to track and control than implicit costs.","zh-TW":"顯性成本比隱性成本更容易追蹤和控制。"}]', '{"opposite":"implicit cost"}', NULL, 5, 2626, NULL),
(2627, 'explicitly', '/''ɪkˈsplɪsɪtli/', 'adverb', '{"zh-TW":["明確地；清楚地"],"en":["in a clear and detailed manner, leaving no room for confusion or doubt"]}', NULL, 'state explicitly / mention explicitly / explicitly require', '[{"en":"The contract explicitly states that late payments will incur a penalty fee.","zh-TW":"合同明確規定，逾期付款將產生罰款。"},{"en":"She explicitly instructed the team to avoid the use of informal language in reports.","zh-TW":"她明確指示團隊避免在報告中使用非正式語言。"}]', '{"adjective":"explicit"}', NULL, 4, 2627, NULL),
(2628, 'exploit', '/ɪkˈsplɔɪt/', 'verb', '{"zh-TW":["利用；開發"],"en":["to make full use of; to use unfairly"]}', NULL, 'exploit resources/opportunities', '[{"en":"We should exploit this market opportunity.","zh-TW":"我們應該利用這個市場機會。"},{"en":"The company exploited cheap labor.","zh-TW":"公司剝削了廉價勞動力。"}]', '{"noun":"exploitation","verb":"exploit"}', NULL, 3, 2628, NULL),
(2629, 'explore', '/ɪkˈsplɔːr/', 'verb', '{"zh-TW":["探索；調查"],"en":["to examine or investigate thoroughly"]}', NULL, 'explore options/possibilities', '[{"en":"Let''s explore all available options.","zh-TW":"讓我們探索所有可用的選項。"},{"en":"The team explored new business models.","zh-TW":"團隊探索了新的商業模式。"}]', '{"noun":"exploration/explorer","verb":"explore","adjective":"exploratory"}', NULL, 3, 2629, NULL),
(2630, 'exponential', '/ˌekspəˈnenʃəl/', 'adjective', '{"zh-TW":["指數的；急劇增長的"],"en":["involving an extremely rapid increase"]}', NULL, 'exponential growth / exponential curve / exponential rate', '[{"en":"The spread of the virus followed an exponential curve.","zh-TW":"病毒的傳播遵循指數曲線。"},{"en":"Computing power has grown at an exponential rate since the 1960s.","zh-TW":"自1960年代以來，計算能力以指數速率增長。"}]', '{"adverb":"exponentially","noun":"exponent"}', NULL, 4, 2630, NULL),
(2631, 'export', '/ˈekspɔːrt/', 'noun / verb', '{"zh-TW":["出口；輸出"],"en":["to sell goods to another country"]}', NULL, 'export goods/data', '[{"en":"Japan exports electronics worldwide.","zh-TW":"日本向全球出口電子產品。"},{"en":"Exports grew by 8% last year.","zh-TW":"去年出口增長了8%。"}]', '{"noun":"export/exporter","verb":"export"}', NULL, 2, 2631, 357),
(2632, 'export control', '/''ekspɔːrt kənˌtrəʊl/', 'noun', '{"zh-TW":["出口管制"],"en":["government regulations that restrict or control the export of certain goods and technologies"]}', NULL, 'comply with export controls / export control regulation / export control compliance', '[{"en":"Technology companies must comply with export controls for sensitive products.","zh-TW":"科技公司必須遵守敏感產品的出口管制。"},{"en":"Failure to comply with export controls can result in heavy fines and business restrictions.","zh-TW":"不遵守出口管制可能導致巨額罰款和業務限制。"}]', NULL, NULL, 5, 2632, NULL),
(2633, 'export financing', '/ˈekspɔːrt ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["出口融資"],"en":["financial products helping exporters fund international sales transactions"]}', NULL, 'arrange export financing / export financing facility', '[{"en":"Export financing allowed the company to offer extended payment terms to buyers.","zh-TW":"出口融資允許公司向買家提供延長的付款條款。"},{"en":"Government export financing agencies support national exporters competitively.","zh-TW":"政府出口融資機構支持本國出口商提高競爭力。"}]', NULL, NULL, 5, 2633, NULL),
(2634, 'export license', '/ˈekspɔːrt ˈlaɪsəns/', 'noun', '{"zh-TW":["出口許可證"],"en":["official approval required to export certain goods to specific countries"]}', NULL, 'obtain an export license / apply for an export license', '[{"en":"A special export license was required for the controlled technology.","zh-TW":"受管制技術需要特殊出口許可證。"},{"en":"The export license was delayed due to additional security checks.","zh-TW":"由於額外的安全檢查，出口許可證被延遲了。"}]', NULL, NULL, 5, 2634, NULL),
(2635, 'export subsidy', '/ˈekspɔːrt ˈsʌbsɪdi/', 'noun', '{"zh-TW":["出口補貼"],"en":["government financial support given to domestic producers to boost exports"]}', NULL, 'provide export subsidies / export subsidy program', '[{"en":"Export subsidies gave the domestic industry an unfair advantage.","zh-TW":"出口補貼給了國內產業不公平的優勢。"},{"en":"The WTO ruled that the export subsidies violated trade rules.","zh-TW":"世貿組織裁定出口補貼違反了貿易規則。"}]', '{"plural":"export subsidies"}', NULL, 5, 2635, NULL),
(2636, 'expose', '/ɪkˈspoʊz/', 'verb', '{"zh-TW":["暴露；揭發"],"en":["to make visible; to reveal","to make visible or reveal"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把東西放到外面讓人看到，即「暴露」。"}', 'expose to risk/information; expose to / expose the truth', '[{"en":"Workers were exposed to harmful chemicals.","zh-TW":"工人暴露在有害化學品中。"},{"en":"The investigation exposed fraud in the company.","zh-TW":"調查揭發了公司的詐騙行為。"},{"en":"Children should not be exposed to violence.","zh-TW":"兒童不應暴露在暴力之下。"},{"en":"The journalist exposed the corruption scandal.","zh-TW":"記者揭發了貪腐醜聞。"}]', '{"noun":"exposure","verb":"expose","adjective":"exposed"}', NULL, 2, 2636, NULL),
(2637, 'expository', '/ɪkˈspɒzɪtəri/', 'adjective', '{"zh-TW":["說明的；闡述的"],"en":["intended to explain or describe something"]}', NULL, 'expository writing / expository essay / expository style', '[{"en":"Expository writing requires clarity and logical organization.","zh-TW":"說明性寫作需要清晰和邏輯組織。"},{"en":"The textbook uses an expository style to present complex theories.","zh-TW":"教科書使用說明性風格來呈現複雜的理論。"}]', NULL, NULL, 4, 2637, NULL),
(2638, 'exposure', 'ɪkˈspoʊʒər', 'noun', '{"zh-TW":["曝光；接觸","暴露"],"en":["experience or knowledge gained","public attention"]}', NULL, 'market exposure/brand exposure', '[{"en":"International exposure helps career growth.","zh-TW":"國際接觸有助於職業發展。"}]', '{"verb":"expose","adjective":"exposed"}', NULL, 3, 2638, 570),
(2639, 'exposure limit', '/ɪkˈspoʊʒər ˈlɪmɪt/', 'noun', '{"zh-TW":["敞口限額"],"en":["the maximum amount of financial risk allowed toward a single counterparty or asset"]}', NULL, 'set an exposure limit / breach an exposure limit', '[{"en":"The bank set a $20 million exposure limit per borrower.","zh-TW":"銀行為每個借款人設定了2000萬元的敞口限額。"},{"en":"Breach of an exposure limit triggers a mandatory risk reduction.","zh-TW":"突破敞口限額觸發了強制性的風險降低。"}]', NULL, NULL, 5, 2639, NULL),
(2640, 'expound', '/ɪkˈspaʊnd/', 'verb', '{"zh-TW":["詳細解說；闡述"],"en":["to present and explain a theory or idea in detail"]}', NULL, 'expound a theory / expound on a topic / expound ideas', '[{"en":"He expounded his theory of organizational behavior at the conference.","zh-TW":"他在會議上詳細闡述了他的組織行為理論。"},{"en":"The professor expounded on the economic implications of the policy.","zh-TW":"教授詳細解說了該政策的經濟含意。"}]', NULL, NULL, 3, 2640, NULL),
(2641, 'express checkout', '/ɪkˈsprɛs ˈtʃɛkaʊt/', 'noun', '{"zh-TW":["快速退房"],"en":["a quick check-out process, often without visiting the desk"]}', NULL, 'use express checkout / express checkout option', '[{"en":"Express checkout is available via the hotel app.","zh-TW":"快速退房可通過飯店應用程式辦理。"},{"en":"Leave your key card and use express checkout to save time.","zh-TW":"留下鑰匙卡並使用快速退房節省時間。"}]', NULL, NULL, 5, 2641, NULL),
(2642, 'express delivery', '/''ɪkˌspres dɪˌlɪvəri/', 'noun', '{"zh-TW":["快遞；快速遞送"],"en":["a courier service that guarantees delivery within a short time frame, often next day"]}', NULL, 'use express delivery / offer express delivery / express delivery tracking', '[{"en":"She chose express delivery to send the documents urgently to the client.","zh-TW":"她選擇快遞，緊急將文件發送給客戶。"},{"en":"Express delivery services are widely used by businesses for time-sensitive shipments.","zh-TW":"快遞服務被企業廣泛用於時間敏感的貨物。"}]', NULL, NULL, 5, 2642, NULL),
(2643, 'expropriation', '/eksˌprəʊpriˈeɪʃən/', 'noun', '{"zh-TW":["徵收；沒收"],"en":["the taking of private property by a government for public use"]}', NULL, 'risk of expropriation / land expropriation / expropriation without compensation', '[{"en":"The government ordered the expropriation of land to build a new highway.","zh-TW":"政府下令徵收土地以建設新高速公路。"},{"en":"Foreign investors feared expropriation without fair compensation.","zh-TW":"外國投資者擔心在沒有公平補償的情況下遭到徵收。"}]', '{"verb":"expropriate","adjective":"expropriated"}', NULL, 5, 2643, NULL),
(2644, 'extend', '/ɪkˈstend/', 'verb', '{"zh-TW":["延長；擴展","延伸；延長"],"en":["to make longer or larger"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tend","meaning":"stretch (伸展)"},"logic":"向外伸展，即「延伸」。"}', 'extend a deadline/contract; extend a deadline / extend an invitation', '[{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以將截止日期延長一週嗎？"},{"en":"The company extended its operations to Asia.","zh-TW":"公司將業務擴展到亞洲。"},{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以把截止期限延長一週嗎？"},{"en":"The road extends for 200 kilometers.","zh-TW":"這條路延伸了200公里。"}]', '{"noun":"extension","verb":"extend","adjective":"extensive/extended","adjective2":"extended"}', NULL, 2, 2644, 123),
(2645, 'extension', 'ɪkˈstɛnʃən', 'noun', '{"zh-TW":["延期；延長","分機"],"en":["an additional period of time","a telephone number within a system"]}', NULL, 'request an extension/extension number', '[{"en":"Please call extension 204 for support.","zh-TW":"請撥打分機204以獲取支援。"}]', '{"verb":"extend","adjective":"extensible","adverb":"extensively"}', NULL, 3, 2645, 571),
(2646, 'extensive', '/ɪkˈstensɪv/', 'adjective', '{"zh-TW":["廣泛的；大量的"],"en":["covering a large area or having great range","covering a large area or having a wide scope"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tens","meaning":"stretch (伸展)"},"suffix":{"text":"-ive","meaning":"having quality (具有…特質)"},"logic":"具有向外伸展特質的，即「廣泛的」。"}', 'extensive experience/research; extensive research / extensive experience / extensive damage', '[{"en":"She has extensive experience in finance.","zh-TW":"她有豐富的金融經驗。"},{"en":"Extensive research was conducted.","zh-TW":"進行了廣泛的研究。"},{"en":"She has extensive experience in marketing.","zh-TW":"她在行銷方面有豐富的經驗。"},{"en":"The storm caused extensive damage.","zh-TW":"暴風雨造成了大範圍的損害。"}]', '{"adjective":"extensive","adverb":"extensively","noun":"extent"}', NULL, 3, 2646, 873),
(2647, 'external', '/ɪkˈstɜːrnəl/', 'adjective', '{"zh-TW":["外部的；外在的"],"en":["coming from outside"]}', NULL, 'external factors/audit', '[{"en":"External factors affected the company''s performance.","zh-TW":"外部因素影響了公司的績效。"},{"en":"An external audit will be conducted.","zh-TW":"將進行外部審計。"}]', '{"adjective":"external","adverb":"externally"}', NULL, 3, 2647, 358),
(2648, 'external audit', '/ɪkˈstɜːrnəl ˈɔːdɪt/', 'noun', '{"zh-TW":["外部審計"],"en":["an independent review of financial statements by an external auditor"]}', NULL, 'conduct an external audit / pass external audit', '[{"en":"The external audit confirmed the accuracy of the financial statements.","zh-TW":"外部審計確認了財務報表的準確性。"},{"en":"Listed companies are required to undergo an annual external audit.","zh-TW":"上市公司必須接受年度外部審計。"}]', NULL, NULL, 5, 2648, NULL),
(2649, 'external financing', '/ɪkˈstɜːrnəl ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["外部融資"],"en":["obtaining funds from outside the company through borrowing or equity"]}', NULL, 'seek external financing / external financing options', '[{"en":"The startup sought external financing to accelerate growth.","zh-TW":"新創公司尋求外部融資以加速增長。"},{"en":"External financing includes bank loans, bonds, and equity issuance.","zh-TW":"外部融資包括銀行貸款、債券和股本發行。"}]', NULL, NULL, 5, 2649, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2650, 'externality', '/ˌekstɜːrˈnælɪti/', 'noun', '{"zh-TW":["外部性"],"en":["a cost or benefit affecting parties not directly involved in a transaction"]}', NULL, 'negative externality / positive externality / internalize externalities', '[{"en":"Carbon emissions are a negative externality not reflected in market prices.","zh-TW":"碳排放是市場價格中沒有反映的負外部性。"},{"en":"Governments use taxes and regulations to internalize negative externalities.","zh-TW":"政府使用稅收和監管來使負外部性內部化。"}]', '{"adjective":"external","adverb":"externally"}', NULL, 4, 2650, NULL),
(2651, 'extract', '/ɪkˈstrækt/', 'verb / noun', '{"zh-TW":["提取；摘錄"],"en":["to remove or obtain"]}', NULL, 'extract data/information', '[{"en":"We need to extract data from the system.","zh-TW":"我們需要從系統中提取數據。"},{"en":"The dentist extracted the tooth.","zh-TW":"牙醫拔了那顆牙。"}]', '{"noun":"extract/extraction","verb":"extract"}', NULL, 3, 2651, NULL),
(2652, 'extracurricular', '/ˌɛkstrəkəˈrɪkjʊlər/', 'adjective', '{"zh-TW":["課外的"],"en":["outside the regular academic curriculum"]}', NULL, 'extracurricular activity / extracurricular involvement', '[{"en":"Extracurricular activities help students develop leadership skills.","zh-TW":"課外活動幫助學生培養領導能力。"},{"en":"Colleges value extracurricular involvement in applicants.","zh-TW":"大學重視申請者的課外活動參與。"}]', NULL, NULL, 5, 2652, NULL),
(2653, 'extracurricular activity', '/''ekstrəkəˌrɪkjələr ækˌtɪvɪti/', 'noun', '{"zh-TW":["課外活動"],"en":["an activity that students participate in outside of normal school or college curriculum"]}', NULL, 'join an extracurricular activity / extracurricular activity benefit / offer extracurricular activities', '[{"en":"Extracurricular activities like debate club help students develop communication skills.","zh-TW":"課外活動如辯論俱樂部幫助學生發展溝通技能。"},{"en":"Colleges look for applicants who demonstrate leadership through extracurricular activities.","zh-TW":"大學尋找通過課外活動展示領導力的申請人。"}]', '{"adjective":"extracurricular"}', NULL, 5, 2653, NULL),
(2654, 'extraordinary', '/ɪkˈstrɔːrdəneri/', 'adjective', '{"zh-TW":["非凡的；特別的"],"en":["very unusual or remarkable"]}', NULL, 'extraordinary achievement/circumstances', '[{"en":"She showed extraordinary leadership.","zh-TW":"她展示了非凡的領導力。"},{"en":"Due to extraordinary circumstances, the event was cancelled.","zh-TW":"由於特殊情況，活動被取消了。"}]', '{"adjective":"extraordinary","adverb":"extraordinarily"}', NULL, 5, 2654, NULL),
(2655, 'extrapolate', '/ɪkˈstræpəleɪt/', 'verb', '{"zh-TW":["推斷；外推"],"en":["to extend conclusions beyond known data by inferring from trends"]}', NULL, 'extrapolate from data / extrapolate trends / extrapolate results', '[{"en":"We cannot safely extrapolate these results to a larger population.","zh-TW":"我們無法安全地將這些結果外推到更大的群體。"},{"en":"The analyst extrapolated future growth from current indicators.","zh-TW":"分析師從當前指標推斷出未來的增長。"}]', '{"noun":"extrapolation","adjective":"extrapolative"}', NULL, 4, 2655, NULL),
(2656, 'extrapolation', '/ɪkˌstræpəˈleɪʃən/', 'noun', '{"zh-TW":["推斷；外推"],"en":["the extension of a method or conclusion to an unknown situation"]}', NULL, 'cautious extrapolation / invalid extrapolation / data extrapolation', '[{"en":"The extrapolation from laboratory to real-world conditions requires caution.","zh-TW":"從實驗室到現實世界條件的推斷需要謹慎。"},{"en":"Extrapolation of short-term trends to long-term predictions is often unreliable.","zh-TW":"將短期趨勢外推至長期預測通常是不可靠的。"}]', '{"verb":"extrapolate","adjective":"extrapolative"}', NULL, 5, 2656, NULL),
(2657, 'extrinsic', '/''ekˌstrɪnsɪk/', 'adjective', '{"zh-TW":["外在的；外部的"],"en":["not part of the essential nature of someone or something; coming from outside"]}', NULL, 'extrinsic reward / extrinsic motivation / extrinsic factor', '[{"en":"Extrinsic rewards like bonuses can motivate employees in the short term.","zh-TW":"獎金等外在獎勵可以在短期內激勵員工。"},{"en":"Extrinsic factors such as weather affected the outcome of the outdoor event.","zh-TW":"天氣等外在因素影響了戶外活動的結果。"}]', '{"adverb":"extrinsically"}', NULL, 3, 2657, NULL),
(2658, 'eye', '/aɪ/', 'noun', '{"zh-TW":["【主要意義-名詞】眼睛","【次要意義-動詞】注視；盯著看；端詳","【次要意義-名詞】眼力；鑒賞力"],"en":["[primary - noun] the organ of sight","[secondary - verb] to look at someone or something carefully","[secondary - noun] a keen sense of judgment or appreciation"]}', NULL, 'eye someone suspiciously / an eye for detail / keep an eye on / eye-catching', '[{"en":"She eyed the new candidate carefully during the interview.","zh-TW":"她在面試過程中仔細打量這位新候選人。"},{"en":"The manager has a good eye for talent and has recruited several top performers.","zh-TW":"這位經理很有識才的眼力，已招募了幾位頂尖績效員工。"},{"en":"Please keep an eye on the inventory levels and report any shortage.","zh-TW":"請留意庫存水平，並報告任何短缺情況。"}]', '{"adjective":"eye-catching, eagle-eyed"}', '動詞 eye = 「端詳/注視」，片語 have an eye for（對……有眼光）、keep an eye on（留意/監視）、eye-catching（引人注目的）均是 TOEIC 職場描述常見用法。', 1, 2658, NULL),
(2659, 'fabricate', '/ˈfæbrɪkeɪt/', 'verb', '{"zh-TW":["捏造；製造"],"en":["to invent false information; to construct"]}', NULL, 'fabricate evidence/a story', '[{"en":"He was accused of fabricating evidence.","zh-TW":"他被指控捏造證據。"},{"en":"The parts are fabricated in our factory.","zh-TW":"零件在我們工廠製造。"}]', '{"noun":"fabrication","verb":"fabricate"}', NULL, 3, 2659, NULL),
(2660, 'face', '/feɪs/', 'verb / noun', '{"zh-TW":["【主要意義-名詞/動詞】臉；面對","【次要意義-動詞】朝向；面向（某方向）","【次要意義-名詞】表面；外觀；正面","【次要意義-名詞】面子；聲譽"],"en":["[primary] the front part of the head; to look toward","[secondary - verb] to be positioned toward a particular direction","[secondary - noun] the surface or front of something","[secondary - noun] reputation or social standing"]}', NULL, 'face value / at face value / face the consequences / save face / lose face', '[{"en":"Do not take the contract terms at face value; read the fine print.","zh-TW":"不要只看合約條款的表面意思，要仔細閱讀細則。"},{"en":"The company managed to save face by issuing a public apology.","zh-TW":"公司通過發表公開道歉來保住了顏面。"},{"en":"The new building faces the main commercial district.","zh-TW":"新大樓面朝主要商業區。"}]', '{"adjective":"face-to-face, facing","noun":"facade"}', 'face value（表面價值/票面價值）、save face（保住面子）、at face value（按表面意思）均是 TOEIC 商業和社交文章的常見陷阱，face 的金融含義（票面）也常見。', 1, 2660, NULL),
(2661, 'face value', '/feɪs ˈvæljuː/', 'noun', '{"zh-TW":["面值；票面價值"],"en":["the nominal or stated value of a financial instrument, such as a bond or share"]}', NULL, 'issued at face value / redeem at face value', '[{"en":"The bond was issued at face value of $1000 per note.","zh-TW":"債券以每張1,000元的票面價值發行。"},{"en":"The face value of a share may differ significantly from its market value.","zh-TW":"股票的面值可能與其市場價值大不相同。"}]', '{"synonym":"par value","synonym2":"nominal value"}', NULL, 4, 2661, NULL),
(2662, 'face-to-face meeting', '/ˌfeɪs tə ˈfeɪs ˈmiːtɪŋ/', 'noun', '{"zh-TW":["面對面會議"],"en":["a meeting conducted in person rather than remotely"]}', NULL, 'schedule a face-to-face meeting / prefer face-to-face meetings', '[{"en":"A face-to-face meeting was arranged to finalize the contract terms.","zh-TW":"安排了面對面會議以最終確定合約條款。"},{"en":"Face-to-face meetings are more effective for building client relationships.","zh-TW":"面對面會議在建立客戶關係方面更有效。"}]', NULL, NULL, 5, 2662, NULL),
(2663, 'facet', '/ˈfæsɪt/', 'noun', '{"zh-TW":["方面；層面"],"en":["one side of something many-sided; an aspect"]}', NULL, 'facet of a problem / multiple facets / every facet', '[{"en":"The study examines every facet of the regulatory environment.","zh-TW":"該研究審視了監管環境的每個方面。"},{"en":"His personality has many interesting facets.","zh-TW":"他的個性有許多有趣的方面。"}]', '{"adjective":"faceted"}', NULL, 2, 2663, NULL),
(2664, 'facilitate', '/fəˈsɪlɪteɪt/', 'verb', '{"zh-TW":["促進；使便利"],"en":["to make an action or process easier"]}', NULL, 'facilitate communication/growth', '[{"en":"Technology facilitates remote collaboration.","zh-TW":"技術促進了遠端協作。"},{"en":"The mediator facilitated the discussion.","zh-TW":"調解人促進了討論。"}]', '{"noun":"facilitation/facilitator","verb":"facilitate"}', NULL, 4, 2664, 684),
(2665, 'facilitate learning', '/''fəˌsɪlɪˌteɪt ˌlɜːrnɪŋ/', 'phrase', '{"zh-TW":["促進學習；便於學習"],"en":["to make the process of learning easier or more effective"]}', NULL, 'facilitate learning through technology / facilitate active learning / facilitate deeper learning', '[{"en":"Technology can greatly facilitate learning by providing access to diverse resources.","zh-TW":"技術可以通過提供多元資源的訪問大大促進學習。"},{"en":"Collaborative group work facilitates learning by exposing students to different perspectives.","zh-TW":"協作小組工作通過讓學生接觸不同的觀點來促進學習。"}]', '{"verb":"facilitate","noun":"facilitation"}', NULL, 5, 2665, NULL),
(2666, 'facilitated', '/fəˈsɪlɪteɪtɪd/', 'adjective', '{"zh-TW":["被便利化的；有助推的"],"en":["made easier or less difficult with assistance"]}', NULL, 'facilitated discussion / facilitated learning / facilitated process', '[{"en":"A facilitated workshop helped the team reach consensus quickly.","zh-TW":"一個有助推的研討會幫助團隊迅速達成共識。"},{"en":"Facilitated negotiation is often used in complex multi-party disputes.","zh-TW":"有助推的談判通常用於複雜的多方爭議。"}]', '{"verb":"facilitate","noun":"facilitation"}', NULL, 4, 2666, NULL),
(2667, 'facilitator', '/fəˈsɪlɪteɪtər/', 'noun', '{"zh-TW":["主持人；促進者"],"en":["a person who helps a group or process operate more effectively"]}', NULL, 'act as a facilitator / workshop facilitator', '[{"en":"The HR manager served as facilitator for the conflict resolution session.","zh-TW":"人力資源管理者擔任了衝突解決會議的主持人。"},{"en":"A skilled facilitator keeps discussions productive and on track.","zh-TW":"熟練的主持人使討論保持高效並按計劃進行。"}]', '{"verb":"facilitate","adjective":"facilitated"}', NULL, 4, 2667, NULL),
(2668, 'facilities', '/fəˈsɪlɪtiz/', 'noun', '{"zh-TW":["設施；設備"],"en":["equipment and services available at a place"]}', NULL, 'hotel facilities / use the facilities', '[{"en":"The hotel''s facilities include a gym and outdoor pool.","zh-TW":"飯店設施包括健身房和室外游泳池。"},{"en":"Conference facilities are available for business travelers.","zh-TW":"會議設施供商務旅客使用。"}]', '{"verb":"facilitate","adjective":"facilitated"}', NULL, 4, 2668, 359),
(2669, 'facilities management', '/fəˈsɪlɪtiz ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["設施管理"],"en":["overseeing the physical workplace and related services"]}', NULL, 'facilities management team / outsource facilities management', '[{"en":"Facilities management ensures a safe and productive work environment.","zh-TW":"設施管理確保安全且有生產力的工作環境。"},{"en":"The facilities management team handled the office relocation.","zh-TW":"設施管理團隊處理了辦公室搬遷。"}]', '{"abbreviation":"FM","noun":"facilities manager"}', NULL, 5, 2669, NULL),
(2670, 'facility', '/fəˈsɪləti/', 'noun', '{"zh-TW":["設施；場所"],"en":["a building or place for a particular purpose"]}', NULL, 'manufacturing/training facility', '[{"en":"The company opened a new manufacturing facility.","zh-TW":"公司開設了新的生產設施。"},{"en":"Our facilities are available for conferences.","zh-TW":"我們的設施可供會議使用。"}]', '{"noun":"facility"}', NULL, 3, 2670, 31),
(2671, 'facility agreement', '/fəˈsɪlɪti əˈɡriːmənt/', 'noun', '{"zh-TW":["融資安排協議；信貸安排協議"],"en":["an agreement for a credit facility between a lender and borrower"]}', NULL, 'sign a facility agreement / facility agreement terms', '[{"en":"The facility agreement provided a 20 million revolving credit line.","zh-TW":"融資安排協議提供了2000萬元的循環信貸額度。"},{"en":"A facility agreement defines the borrowing limit, interest, and conditions.","zh-TW":"融資安排協議定義了借款限額、利息和條件。"}]', NULL, NULL, 5, 2671, NULL),
(2672, 'fact', '/fækt/', 'noun', '{"zh-TW":["事實"],"en":["something known to be true"]}', NULL, 'in fact / as a matter of fact', '[{"en":"In fact, sales increased by 20%.","zh-TW":"事實上，銷售增長了20%。"},{"en":"We need facts, not opinions.","zh-TW":"我們需要事實，不是意見。"}]', '{"noun":"fact","adjective":"factual","adverb":"factually"}', NULL, 1, 2672, NULL),
(2673, 'factor', '/ˈfæktər/', 'noun', '{"zh-TW":["因素；要素","因素"],"en":["a circumstance that contributes to a result"]}', '{"root":{"text":"fact","meaning":"make/do (做)"},"suffix":{"text":"-or","meaning":"that which (…的東西)"},"logic":"促成某事發生的東西，即「因素」。"}', 'key/determining factor; key factor / risk factor / contributing factor', '[{"en":"Cost is a major factor in the decision.","zh-TW":"成本是決策中的主要因素。"},{"en":"Several factors contributed to the failure.","zh-TW":"幾個因素導致了失敗。"},{"en":"Cost is an important factor in this decision.","zh-TW":"成本是這個決策中的重要因素。"},{"en":"Several factors contributed to the delay.","zh-TW":"多項因素導致了延遲。"}]', '{"noun":"factor","verb":"factor","adjective":"factorial"}', NULL, 2, 2673, 360),
(2674, 'factored receivables', '/ˈfæktərd rɪˈsiːvəblz/', 'noun', '{"zh-TW":["已保理應收帳款"],"en":["accounts receivable that have been sold to a factoring company for immediate cash"]}', NULL, 'sell factored receivables / factored receivables balance', '[{"en":"By using factored receivables, the company converted invoices to immediate cash.","zh-TW":"通過使用保理應收帳款，公司將發票轉換為即時現金。"},{"en":"Factored receivables reduce the book value of outstanding debtors.","zh-TW":"保理應收帳款減少了未付款客戶的帳面價值。"}]', NULL, NULL, 5, 2674, NULL),
(2675, 'factoring', '/ˈfæktərɪŋ/', 'noun', '{"zh-TW":["應收帳款融資；保理"],"en":["selling accounts receivable to a third party at a discount for immediate cash"]}', NULL, 'invoice factoring / factoring company / factoring facility', '[{"en":"Factoring provided the small business with immediate working capital.","zh-TW":"保理為小企業提供了即時營運資金。"},{"en":"The company used factoring to bridge the gap between invoicing and payment.","zh-TW":"公司使用保理來彌補開票和收款之間的差距。"}]', '{"verb":"factor","noun":"factor"}', NULL, 3, 2675, NULL),
(2676, 'faculty', '/ˈfækəlti/', 'noun', '{"zh-TW":["全體教職員；院系"],"en":["the teaching staff of a university"]}', NULL, 'faculty member / faculty meeting', '[{"en":"The faculty voted on the proposal.","zh-TW":"教職員對提案進行了投票。"},{"en":"She''s a faculty member in the science department.","zh-TW":"她是理學院的教職員。"}]', NULL, NULL, 3, 2676, NULL),
(2677, 'fail', '/feɪl/', 'verb', '{"zh-TW":["失敗；未能"],"en":["to be unsuccessful; to neglect"]}', NULL, 'fail to meet/deliver', '[{"en":"The project failed to meet its objectives.","zh-TW":"該項目未能達成目標。"},{"en":"The business failed within two years.","zh-TW":"這家企業在兩年內倒閉了。"}]', '{"noun":"failure","verb":"fail"}', NULL, 1, 2677, NULL),
(2678, 'failure', 'ˈfeɪljər', 'noun', '{"zh-TW":["失敗；失誤","故障"],"en":["a lack of success","a breakdown"]}', NULL, 'system failure/product failure', '[{"en":"We must analyze the causes of failure.","zh-TW":"我們必須分析失敗的原因。"}]', '{"verb":"fail","adjective":"failed","adverb":"failingly"}', NULL, 3, 2678, NULL),
(2679, 'fair', '/fer/', 'adjective / noun', '{"zh-TW":["公平的；展覽會"],"en":["treating people equally; a commercial exhibition"]}', NULL, 'fair price/trade fair', '[{"en":"We offer fair prices to all customers.","zh-TW":"我們對所有客戶提供公平的價格。"},{"en":"We met potential clients at the trade fair.","zh-TW":"我們在商展上認識了潛在客戶。"}]', '{"noun":"fairness","adjective":"fair","adverb":"fairly"}', NULL, 1, 2679, NULL),
(2680, 'fair competition', '/feər ˌkɒmpɪˈtɪʃən/', 'noun', '{"zh-TW":["公平競爭"],"en":["market conditions where no single company has an unfair advantage"]}', NULL, 'promote fair competition / ensure fair competition', '[{"en":"The regulator oversees markets to ensure fair competition.","zh-TW":"監管機構監督市場以確保公平競爭。"},{"en":"Fair competition benefits consumers through lower prices and better quality.","zh-TW":"公平競爭通過更低的價格和更好的品質使消費者受益。"}]', NULL, NULL, 5, 2680, NULL),
(2681, 'fair market value', '/feər ˈmɑːrkɪt ˈvæljuː/', 'noun', '{"zh-TW":["公平市場價值"],"en":["the price at which a willing buyer and seller would agree in a free market"]}', NULL, 'determine fair market value / transact at fair market value', '[{"en":"The property was sold at fair market value after an independent valuation.","zh-TW":"在獨立估值後，房產以公平市場價值出售了。"},{"en":"Tax authorities use fair market value to assess capital gains.","zh-TW":"稅務機關使用公平市場價值來評估資本利得。"}]', NULL, NULL, 5, 2681, NULL),
(2682, 'fair trade', '/feər treɪd/', 'noun', '{"zh-TW":["公平貿易"],"en":["trading practices ensuring producers receive fair pay and safe conditions"]}', NULL, 'support fair trade / fair trade certification', '[{"en":"The coffee was certified as fair trade by an independent body.","zh-TW":"咖啡被獨立機構認證為公平貿易產品。"},{"en":"Fair trade principles ensure workers in developing countries receive fair wages.","zh-TW":"公平貿易原則確保發展中國家的工人獲得公平薪資。"}]', NULL, NULL, 4, 2682, NULL),
(2683, 'fair value', '/feər ˈvæljuː/', 'noun', '{"zh-TW":["公平價值"],"en":["the estimated market value of an asset determined by agreed standards"]}', NULL, 'measure fair value / fair value accounting', '[{"en":"Under fair value accounting, assets are recorded at current market prices.","zh-TW":"在公平價值會計下，資產按當前市場價格記錄。"},{"en":"Fair value adjustments can cause significant income statement volatility.","zh-TW":"公平價值調整可能導致損益表的顯著波動。"}]', NULL, NULL, 4, 2683, NULL),
(2684, 'fall', '/fɔːl/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】落下；跌倒","【次要意義-名詞（美式）】秋天","【次要意義-名詞】瀑布（複數 falls）","【次要意義-動詞】淪為；變成某種狀態"],"en":["[primary] to drop or descend; the act of dropping","[secondary - noun (AmE)] autumn","[secondary - noun] a waterfall (often plural)","[secondary - verb] to enter or pass into a state"]}', NULL, 'fall due / fall short / fall into place / fall flat / Niagara Falls', '[{"en":"Sales figures fell short of the projected targets for the quarter.","zh-TW":"本季的銷售數字未達預期目標。"},{"en":"The payment falls due on the last business day of each month.","zh-TW":"款項在每月最後一個工作日到期。"},{"en":"The new marketing plan fell flat with focus groups.","zh-TW":"新的行銷計劃在焦點小組中未能引起反響。"}]', '{"noun":"downfall","adjective":"fallen"}', 'fall 有多個次要意義：fall short（未達到）、fall due（到期）、fall flat（失敗/未引起反響）均為 TOEIC 閱讀高頻商業用語，不可望文生義。', 1, 2684, NULL),
(2685, 'fallacy', '/ˈfæləsi/', 'noun', '{"zh-TW":["謬論；謬誤"],"en":["a mistaken belief or a failure in reasoning"]}', NULL, 'commit a fallacy / logical fallacy / common fallacy', '[{"en":"The argument contains a logical fallacy that undermines its conclusion.","zh-TW":"該論點包含一個邏輯謬誤，破壞了其結論。"},{"en":"It is a fallacy to assume that correlation implies causation.","zh-TW":"假設相關性意味著因果關係是一種謬論。"}]', '{"adjective":"fallacious","adverb":"fallaciously"}', NULL, 3, 2685, NULL),
(2686, 'false advertising', '/fɔːls ˈædvətaɪzɪŋ/', 'noun', '{"zh-TW":["虛假廣告"],"en":["advertising that makes misleading or false claims about products or services"]}', NULL, 'engage in false advertising / prosecuted for false advertising', '[{"en":"The company was fined for false advertising about product performance claims.","zh-TW":"公司因對產品性能聲明進行虛假廣告而被罰款。"},{"en":"False advertising damages consumer trust and invites regulatory action.","zh-TW":"虛假廣告損害了消費者信任並引發了監管行動。"}]', NULL, NULL, 5, 2686, NULL),
(2687, 'false consciousness', '/fɔːls ˈkɒnʃəsnəs/', 'noun', '{"zh-TW":["虛假意識"],"en":["a Marxist concept where workers internalize the ideology of the ruling class"]}', NULL, 'develop false consciousness / overcome false consciousness / false consciousness theory', '[{"en":"Marx argued that false consciousness prevents workers from recognizing their exploitation.","zh-TW":"馬克思認為虛假意識阻止工人認識到他們受到的剝削。"},{"en":"Critics use false consciousness to explain why people vote against their economic interests.","zh-TW":"批評者使用虛假意識來解釋為什麼人們投票反對自己的經濟利益。"}]', NULL, NULL, 5, 2687, NULL),
(2688, 'falsifiable', '/ˈfɔːlsɪfaɪəbəl/', 'adjective', '{"zh-TW":["可否證的；可驗偽的"],"en":["able to be proven false by observation or experiment"]}', NULL, 'falsifiable hypothesis / falsifiable claim / falsifiable theory', '[{"en":"Popper argued that scientific theories must be falsifiable.","zh-TW":"波普爾認為科學理論必須是可否證的。"},{"en":"A claim that cannot be falsified is metaphysical rather than scientific.","zh-TW":"不能被否證的主張是形而上學的而非科學的。"}]', '{"noun":"falsifiability","verb":"falsify"}', NULL, 4, 2688, NULL),
(2689, 'familiar', '/fəˈmɪliər/', 'adjective', '{"zh-TW":["熟悉的"],"en":["well known; often seen or experienced"]}', NULL, 'familiar with', '[{"en":"Are you familiar with this software?","zh-TW":"你熟悉這個軟體嗎？"},{"en":"The process should be familiar to all staff.","zh-TW":"所有員工應該熟悉這個流程。"}]', '{"noun":"familiarity","verb":"familiarize","adjective":"familiar"}', NULL, 3, 2689, NULL),
(2690, 'family', '/ˈfæməli/', 'noun', '{"zh-TW":["家庭；家族"],"en":["a group of related people","a group of related things"]}', NULL, 'family business / family-friendly', '[{"en":"It is a family-owned business.","zh-TW":"這是一家家族企業。"},{"en":"The company offers family-friendly policies.","zh-TW":"公司提供家庭友善政策。"}]', '{"noun":"family","adjective":"familiar","noun2":"familiarity"}', NULL, 2, 2690, NULL),
(2691, 'family medicine', '/ˈfæmɪli ˈmɛdɪsɪn/', 'noun', '{"zh-TW":["家庭醫學；家庭醫療"],"en":["medical care provided to patients of all ages by a generalist"]}', NULL, 'family medicine clinic / practice family medicine', '[{"en":"Her family medicine doctor handles all routine health issues.","zh-TW":"她的家庭醫學醫生處理所有例行健康問題。"},{"en":"Family medicine emphasizes preventive care and long-term relationships.","zh-TW":"家庭醫學強調預防護理和長期醫患關係。"}]', NULL, NULL, 5, 2691, NULL),
(2692, 'famous', 'ˈfeɪməs', 'adjective', '{"zh-TW":["著名的；有名的","出名的"],"en":["known by many people","well-known"]}', NULL, 'famous brand/world-famous', '[{"en":"The company is famous for its innovation.","zh-TW":"該公司以其創新而聞名。"}]', '{"noun":"fame","adverb":"famously"}', NULL, 2, 2692, NULL),
(2693, 'fan', '/fæn/', 'noun', '{"zh-TW":["粉絲；風扇"],"en":["a person who admires someone or something"]}', NULL, 'fan base / big fan', '[{"en":"I''m a big fan of this band.","zh-TW":"我是這個樂隊的忠實粉絲。"},{"en":"Turn on the fan, it''s hot.","zh-TW":"開風扇，好熱。"}]', NULL, NULL, 1, 2693, NULL),
(2694, 'far', '/fɑːr/', 'adverb', '{"zh-TW":["遠；遠遠地"],"en":["at a great distance","to a great degree"]}', NULL, 'so far / by far', '[{"en":"So far, everything is going well.","zh-TW":"到目前為止，一切順利。"},{"en":"This is by far the best option.","zh-TW":"這無疑是最好的選擇。"}]', '{"adverb":"far","adjective":"far","adjective2":"farther"}', NULL, 1, 2694, NULL),
(2695, 'far-reaching', '/''fɑːr ˌriːtʃɪŋ/', 'adjective', '{"zh-TW":["深遠的；廣泛影響的"],"en":["having wide-ranging effects or influence; extensive in scope"]}', NULL, 'far-reaching implications / far-reaching consequences / far-reaching reforms', '[{"en":"The government''s far-reaching economic reforms transformed the country''s financial system.","zh-TW":"政府深遠的經濟改革改造了該國的金融體系。"},{"en":"The technological advance had far-reaching implications for every sector of society.","zh-TW":"這項技術進步對社會各個部門都有深遠影響。"}]', NULL, NULL, 4, 2695, NULL),
(2696, 'fare', '/fer/', 'noun', '{"zh-TW":["票價；費用"],"en":["the money paid for a journey"]}', NULL, 'bus/air fare', '[{"en":"Air fares have increased significantly.","zh-TW":"機票價格大幅上漲。"},{"en":"What is the fare to the airport?","zh-TW":"到機場的票價是多少？"}]', '{"noun":"fare"}', NULL, 1, 2696, NULL),
(2697, 'fashion', '/ˈfæʃən/', 'noun', '{"zh-TW":["時尚；方式"],"en":["a popular trend; a manner of doing something"]}', NULL, 'in a timely fashion', '[{"en":"The fashion industry is worth billions.","zh-TW":"時尚產業價值數十億。"},{"en":"The work was completed in a professional fashion.","zh-TW":"工作以專業方式完成。"}]', '{"noun":"fashion","adjective":"fashionable"}', NULL, 3, 2697, NULL),
(2698, 'fast', '/fæst/', 'adjective', '{"zh-TW":["【主要意義-形容詞/副詞】快速的；快速地","【次要意義-名詞】齋戒；禁食期間","【次要意義-動詞】齋戒；禁食","【次要意義-形容詞】牢固的；緊緊的"],"en":["[primary] moving quickly; at high speed","[secondary - noun] a period of not eating for religious or health reasons","[secondary - verb] to abstain from food","[secondary - adjective] firmly fixed; secure"]}', NULL, 'break a fast / fast for a day / hold fast / fast asleep', '[{"en":"Employees observed a religious fast during the holiday period.","zh-TW":"員工在假期期間遵守宗教齋戒。"},{"en":"He decided to fast for 24 hours as part of the charity event.","zh-TW":"他決定禁食24小時以參與慈善活動。"},{"en":"The boat was held fast to the dock by two thick ropes.","zh-TW":"船被兩條粗繩牢牢地固定在碼頭上。"}]', '{"noun":"fasting","adjective":"fasting"}', 'fast 作名詞/動詞表「齋戒/禁食」，作形容詞表「固定的/牢固的」（如 fast asleep），這些用法在 TOEIC 文化或健康主題文章中偶爾出現。', 1, 2698, NULL),
(2699, 'fast food', '/fɑːst fuːd/', 'noun', '{"zh-TW":["速食；快餐"],"en":["food that is prepared and served quickly"]}', NULL, 'fast food restaurant / fast food chain', '[{"en":"Many travelers rely on fast food during long trips.","zh-TW":"許多旅行者在長途旅行中依賴速食。"},{"en":"Fast food chains are found in every major airport.","zh-TW":"每個主要機場都有速食連鎖店。"}]', NULL, NULL, 3, 2699, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2700, 'fast track', '/''fɑːst træk/', 'noun', '{"zh-TW":["快速通道；優先通道"],"en":["a route or method that allows faster passage, as through security or customs"]}', NULL, 'fast track lane / use the fast track / fast track program', '[{"en":"Premium passengers can use the fast track lane at security checkpoints.","zh-TW":"高端乘客可以在安全檢查站使用快速通道。"},{"en":"The fast track visa program allows approved applicants to enter within 24 hours.","zh-TW":"快速簽證計畫允許獲批准的申請人在24小時內入境。"}]', NULL, NULL, 4, 2700, NULL),
(2701, 'fast-moving consumer goods', '/fæst ˈmuːvɪŋ kənˈsjuːmər ɡʊdz/', 'noun', '{"zh-TW":["快速消費品"],"en":["products with high turnover sold at relatively low cost"]}', NULL, 'market fast-moving consumer goods / FMCG sector', '[{"en":"The FMCG sector relies on high volumes and efficient distribution.","zh-TW":"快速消費品行業依賴於高產量和高效配送。"},{"en":"Fast-moving consumer goods require strong shelf presence in retail stores.","zh-TW":"快速消費品需要在零售店中有強大的貨架存在感。"}]', '{"abbreviation":"FMCG"}', NULL, 5, 2701, NULL),
(2702, 'fasting', '/''fɑːstɪŋ/', 'noun', '{"zh-TW":["禁食；斷食"],"en":["the practice of going without food or drink for a period of time, often for health or religious reasons"]}', NULL, 'intermittent fasting / practice fasting / fasting period', '[{"en":"Intermittent fasting involves cycling between periods of eating and fasting.","zh-TW":"間歇性禁食涉及在進食和禁食期之間循環。"},{"en":"Research suggests that short-term fasting may have several metabolic benefits.","zh-TW":"研究表明，短期禁食可能有幾種代謝益處。"}]', '{"verb":"fast","adjective":"fasting"}', NULL, 3, 2702, NULL),
(2703, 'fatal', '/ˈfeɪtəl/', 'adjective', '{"zh-TW":["致命的；嚴重的"],"en":["causing death; leading to failure"]}', NULL, 'fatal error/accident', '[{"en":"The software had a fatal error.","zh-TW":"軟體出現了致命錯誤。"},{"en":"The accident proved to be fatal.","zh-TW":"事故被證明是致命的。"}]', '{"noun":"fatality","adjective":"fatal","adverb":"fatally"}', NULL, 2, 2703, NULL),
(2704, 'father', '/ˈfɑːðər/', 'noun', '{"zh-TW":["父親"],"en":["a male parent"]}', NULL, 'founding father / father figure', '[{"en":"He is considered the founding father of the company.","zh-TW":"他被視為公司的創始人。"},{"en":"My father works in banking.","zh-TW":"我的父親在銀行業工作。"}]', '{"noun":"father","adjective":"fatherly","noun2":"fatherhood"}', NULL, 2, 2704, NULL),
(2705, 'fault', '/fɔːlt/', 'noun', '{"zh-TW":["過失；缺陷"],"en":["responsibility for a mistake; a defect"]}', NULL, 'at fault / find fault with', '[{"en":"The delay was not our fault.","zh-TW":"延誤不是我們的過失。"},{"en":"A fault was found in the equipment.","zh-TW":"在設備中發現了缺陷。"}]', '{"noun":"fault","adjective":"faulty"}', NULL, 2, 2705, NULL),
(2706, 'fault tolerance', '/fɔːlt ˈtɒlərəns/', 'noun', '{"zh-TW":["容錯性；容錯能力"],"en":["the ability of a system to continue operating despite failures"]}', NULL, 'build fault tolerance / fault tolerance mechanism / improve fault tolerance', '[{"en":"The distributed database was designed with fault tolerance as a key requirement.","zh-TW":"分散式資料庫的設計將容錯性作為關鍵需求。"},{"en":"RAID systems provide fault tolerance by replicating data across drives.","zh-TW":"RAID系統通過跨驅動器複製數據提供容錯能力。"}]', '{"adjective":"fault-tolerant"}', NULL, 5, 2706, NULL),
(2707, 'favor', '/ˈfeɪvər/', 'noun / verb', '{"zh-TW":["偏好；支持"],"en":["approval or support; to prefer"]}', NULL, 'in favor of', '[{"en":"The board voted in favor of the merger.","zh-TW":"董事會投票支持合併。"},{"en":"Most customers favor online shopping.","zh-TW":"大多數客戶偏好網上購物。"}]', '{"noun":"favor","verb":"favor","adjective":"favorable/favorite"}', NULL, 2, 2707, NULL),
(2708, 'fax', '/fæks/', 'noun', '{"zh-TW":["傳真"],"en":["a system for transmitting documents electronically over phone lines"]}', NULL, 'send a fax / fax machine', '[{"en":"Please fax the signed contract to our office.","zh-TW":"請將已簽署的合約傳真至我們的辦公室。"},{"en":"The fax number is listed on our website.","zh-TW":"傳真號碼列在我們的網站上。"}]', '{"verb":"fax","adjective":"faxed"}', NULL, 1, 2708, NULL),
(2709, 'fear', '/fɪr/', 'noun', '{"zh-TW":["恐懼；擔心"],"en":["an unpleasant emotion caused by danger"]}', NULL, 'for fear of / overcome fear', '[{"en":"She quit for fear of being laid off.","zh-TW":"她因害怕被裁員而辭職。"},{"en":"Overcome your fear of public speaking.","zh-TW":"克服你對公開演講的恐懼。"}]', '{"noun":"fear","verb":"fear","adjective":"fearful","adjective2":"fearless"}', NULL, 1, 2709, NULL),
(2710, 'feasibility', '/ˌfiːzəˈbɪlɪti/', 'noun', '{"zh-TW":["可行性"],"en":["the likelihood of a plan succeeding"]}', NULL, 'feasibility study / assess feasibility', '[{"en":"A feasibility study was conducted before launching the project.","zh-TW":"在啟動項目之前進行了可行性研究。"},{"en":"The report assessed the feasibility of building a new factory.","zh-TW":"報告評估了建設新工廠的可行性。"}]', '{"adjective":"feasible","adverb":"feasibly"}', NULL, 4, 2710, 786),
(2711, 'feasibility report', '/ˌfiːzəˈbɪlɪti rɪˈpɔːrt/', 'noun', '{"zh-TW":["可行性報告"],"en":["a document evaluating whether a project is viable"]}', NULL, 'prepare a feasibility report / submit a feasibility report', '[{"en":"The feasibility report recommended proceeding with the expansion.","zh-TW":"可行性報告建議繼續推進擴張計劃。"},{"en":"A feasibility report must consider technical, financial, and market factors.","zh-TW":"可行性報告必須考慮技術、財務和市場因素。"}]', NULL, NULL, 5, 2711, NULL),
(2712, 'feasibility study', '/ˌfiːzəˈbɪlɪti ˈstʌdi/', 'noun', '{"zh-TW":["可行性研究"],"en":["an analysis assessing whether a proposed project is practical and viable"]}', NULL, 'conduct a feasibility study / feasibility study report', '[{"en":"A feasibility study was conducted before committing to the new plant.","zh-TW":"在承諾建設新廠前進行了可行性研究。"},{"en":"The feasibility study determined the project was financially viable.","zh-TW":"可行性研究確定該項目在財務上是可行的。"}]', '{"adjective":"feasible","noun":"feasibility"}', NULL, 5, 2712, NULL),
(2713, 'feasible', '/ˈfiːzəbəl/', 'adjective', '{"zh-TW":["可行的"],"en":["possible and practical to do"]}', NULL, 'financially/technically feasible', '[{"en":"Is the plan financially feasible?","zh-TW":"這個計畫在財務上可行嗎？"},{"en":"We need to determine if the project is feasible.","zh-TW":"我們需要確定項目是否可行。"}]', '{"noun":"feasibility","adjective":"feasible"}', NULL, 3, 2713, 966),
(2714, 'feature', '/ˈfiːtʃər/', 'noun / verb', '{"zh-TW":["【主要意義-名詞】特徵；特色；功能","【次要意義-動詞】以……為主角；重點介紹；包含（作為特色）","【次要意義-名詞】（報紙/雜誌）特寫文章；專題報導"],"en":["[primary - noun] a distinctive quality or aspect of something","[secondary - verb] to include someone or something as an important part","[secondary - noun] a long article or program about a specific topic"]}', NULL, 'feature article / feature film / feature prominently / as a key feature', '[{"en":"The new product features an advanced noise-canceling system.","zh-TW":"新產品以先進的降噪系統為特色。"},{"en":"The brochure features our best-selling products from the past year.","zh-TW":"宣傳冊重點介紹了我們過去一年的暢銷產品。"},{"en":"A feature on sustainable packaging will appear in the next issue.","zh-TW":"關於可持續包裝的特寫文章將出現在下一期。"}]', '{"adjective":"featured"}', '動詞 feature = 「以……為特色/重點介紹」，名詞 feature = 「特寫報導/專題文章」，均是 TOEIC 廣告和媒體文章的常見用法，考生容易只記住名詞「特徵/功能」的意思。', 3, 2714, 361),
(2715, 'feature engineering', '/ˈfiːtʃər ˌendʒɪˈnɪərɪŋ/', 'noun', '{"zh-TW":["特徵工程"],"en":["the process of using domain knowledge to create features for machine learning models"]}', NULL, 'perform feature engineering / feature engineering pipeline / automated feature engineering', '[{"en":"Feature engineering often determines the success of a machine learning model.","zh-TW":"特徵工程通常決定了機器學習模型的成功。"},{"en":"Good feature engineering requires both technical and domain expertise.","zh-TW":"良好的特徵工程需要技術和領域專業知識。"}]', NULL, NULL, 5, 2715, NULL),
(2716, 'federal', '/ˈfedərəl/', 'adjective', '{"zh-TW":["聯邦的"],"en":["relating to a central government","relating to the national government"]}', NULL, 'federal government/law; federal government / federal law', '[{"en":"The federal government announced new regulations.","zh-TW":"聯邦政府宣布了新法規。"},{"en":"Federal taxes apply to all states.","zh-TW":"聯邦稅適用於所有州。"},{"en":"It''s a federal offense.","zh-TW":"這是聯邦罪行。"},{"en":"The federal government announced new policies.","zh-TW":"聯邦政府宣布了新政策。"}]', '{"noun":"federation","adjective":"federal"}', NULL, 3, 2716, NULL),
(2717, 'fee', '/fiː/', 'noun', '{"zh-TW":["費用；手續費"],"en":["a payment made for professional services"]}', NULL, 'annual/membership fee', '[{"en":"There is a monthly membership fee of $50.","zh-TW":"每月會費為50美元。"},{"en":"Legal fees can be expensive.","zh-TW":"法律費用可能很昂貴。"}]', '{"noun":"fee"}', NULL, 1, 2717, NULL),
(2718, 'fee schedule', '/fiː ˈʃedjuːl/', 'noun', '{"zh-TW":["費用明細表；收費表"],"en":["a document listing the fees charged for specific services"]}', NULL, 'publish a fee schedule / review the fee schedule', '[{"en":"Clients can review the fee schedule before engaging services.","zh-TW":"客戶可在使用服務前查看費用明細表。"},{"en":"The fee schedule was revised to reflect increased operating costs.","zh-TW":"費用明細表經修訂以反映增加的運營成本。"}]', NULL, NULL, 4, 2718, NULL),
(2719, 'fee structure', '/fiː ˈstrʌktʃər/', 'noun', '{"zh-TW":["費用結構"],"en":["the framework defining what fees are charged and under what conditions"]}', NULL, 'review the fee structure / fee structure transparency', '[{"en":"The consultant explained the fee structure before engagement began.","zh-TW":"顧問在開始工作前解釋了費用結構。"},{"en":"A transparent fee structure builds trust with clients.","zh-TW":"透明的費用結構建立了與客戶的信任。"}]', NULL, NULL, 5, 2719, NULL),
(2720, 'feedback', '/ˈfiːdbæk/', 'noun', '{"zh-TW":["反饋；回饋"],"en":["information about reactions to a product or performance"]}', NULL, 'provide/give feedback', '[{"en":"We appreciate your feedback on our service.","zh-TW":"我們感謝您對我們服務的反饋。"},{"en":"The manager gave constructive feedback.","zh-TW":"經理給予了建設性的反饋。"}]', '{"noun":"feedback"}', NULL, 3, 2720, 362),
(2721, 'feedback loop', '/ˈfiːdbæk luːp/', 'noun', '{"zh-TW":["反饋循環"],"en":["a process where outputs are fed back as inputs to improve a system"]}', NULL, 'create a feedback loop / close the feedback loop / continuous feedback loop', '[{"en":"A feedback loop between sales and product improved feature development.","zh-TW":"銷售和產品之間的反饋循環改善了功能開發。"},{"en":"Customer feedback loops help companies continuously improve their services.","zh-TW":"客戶反饋循環幫助公司持續改善其服務。"}]', NULL, NULL, 5, 2721, NULL),
(2722, 'feedback mechanism', '/''fiːdbæk ˌmekənɪzəm/', 'noun', '{"zh-TW":["反饋機制"],"en":["a system through which information about performance or quality is returned to the appropriate party for improvement"]}', NULL, 'establish a feedback mechanism / feedback mechanism improvement / use a feedback mechanism', '[{"en":"The company implemented a feedback mechanism to collect employee suggestions.","zh-TW":"公司建立了一個反饋機制，收集員工建議。"},{"en":"A good feedback mechanism ensures that customer complaints lead to real improvements.","zh-TW":"一個好的反饋機制確保客戶投訴能帶來真正的改進。"}]', NULL, NULL, 5, 2722, NULL),
(2723, 'feel', '/fiːl/', 'verb', '{"zh-TW":["感覺；覺得"],"en":["to experience an emotion","to be aware of through touch"]}', NULL, 'feel free / feel like', '[{"en":"Feel free to ask any questions.","zh-TW":"請隨時提問。"},{"en":"I feel confident about this decision.","zh-TW":"我對這個決定感到有信心。"}]', '{"verb":"feel","noun":"feeling"}', NULL, 1, 2723, NULL),
(2724, 'feeling', 'ˈfiːlɪŋ', 'noun', '{"zh-TW":["感覺；情感","感受"],"en":["an emotion or sentiment","a physical sensation"]}', NULL, 'gut feeling/mixed feelings', '[{"en":"I have a good feeling about this deal.","zh-TW":"我對這筆交易有好的感覺。"}]', '{"verb":"feel","adjective":"feeling"}', NULL, 3, 2724, NULL),
(2725, 'fellowship', '/ˈfɛloʊʃɪp/', 'noun', '{"zh-TW":["獎學金；研究員資格"],"en":["money given for academic study; companionship"]}', NULL, 'research fellowship / fellowship program', '[{"en":"He received a research fellowship.","zh-TW":"他獲得了研究獎學金。"},{"en":"The fellowship covers tuition and living expenses.","zh-TW":"該獎學金包含學費和生活費。"}]', NULL, NULL, 4, 2725, NULL),
(2726, 'felony', '/ˈfɛləni/', 'noun', '{"zh-TW":["重罪"],"en":["a serious crime"]}', NULL, 'commit a felony / felony charge', '[{"en":"Murder is classified as a felony.","zh-TW":"謀殺被歸類為重罪。"},{"en":"He was charged with a felony.","zh-TW":"他被指控犯了重罪。"}]', NULL, NULL, 2, 2726, NULL),
(2727, 'feminist theory', '/ˈfemɪnɪst ˈθɪəri/', 'noun', '{"zh-TW":["女性主義理論"],"en":["frameworks analyzing gender inequality and promoting gender justice"]}', NULL, 'second-wave feminist theory / intersectional feminist theory / apply feminist theory', '[{"en":"Feminist theory examines how patriarchy operates in law, culture, and daily life.","zh-TW":"女性主義理論研究父權制如何在法律、文化和日常生活中運作。"},{"en":"Liberal feminist theory focuses on achieving equality through legal reform.","zh-TW":"自由主義女性主義理論聚焦於通過法律改革實現平等。"}]', NULL, NULL, 5, 2727, NULL),
(2728, 'fermentation', '/''fɜːrmenˈteɪʃən/', 'noun', '{"zh-TW":["發酵"],"en":["a metabolic process in which microorganisms convert sugar into acids, gases, or alcohol"]}', NULL, 'natural fermentation / lactic fermentation / fermentation process', '[{"en":"Fermentation is used to make bread, yogurt, and wine.","zh-TW":"發酵用於製作麵包、優格和葡萄酒。"},{"en":"The unique flavor of sourdough bread comes from the fermentation of wild yeast.","zh-TW":"酸麵包獨特的風味來自野生酵母的發酵。"}]', '{"verb":"ferment","adjective":"fermented"}', NULL, 4, 2728, NULL),
(2729, 'fermented', '/''fɜːrmentɪd/', 'adjective', '{"zh-TW":["發酵的"],"en":["having undergone fermentation; made through microbial activity"]}', NULL, 'fermented food / fermented drink / naturally fermented', '[{"en":"Fermented foods like kimchi and yogurt are beneficial for gut health.","zh-TW":"像泡菜和優格這樣的發酵食品對腸道健康有益。"},{"en":"Many traditional cuisines feature fermented ingredients for depth of flavor.","zh-TW":"許多傳統菜系都以發酵食材為特色，以增添風味深度。"}]', '{"noun":"fermentation"}', NULL, 3, 2729, NULL),
(2730, 'fermented drink', '/''fɜːrmentɪd drɪŋk/', 'noun', '{"zh-TW":["發酵飲料"],"en":["a beverage produced through the fermentation of sugars by yeast or bacteria"]}', NULL, 'traditional fermented drink / popular fermented drink / health benefits of fermented drinks', '[{"en":"Kombucha is a popular fermented drink known for its probiotic benefits.","zh-TW":"康普茶是一種以益生菌功效著稱的流行發酵飲料。"},{"en":"Kefir is a fermented drink made from milk and has a tangy, yogurt-like taste.","zh-TW":"克菲爾是一種由牛奶製成的發酵飲料，具有酸奶般的濃郁口感。"}]', NULL, NULL, 5, 2730, NULL),
(2731, 'fermented food', '/''fɜːrmentɪd fuːd/', 'noun', '{"zh-TW":["發酵食品"],"en":["food that has been preserved or transformed through fermentation by microorganisms"]}', NULL, 'eat fermented food / traditional fermented food / health benefits of fermented food', '[{"en":"Fermented foods like miso and sauerkraut have been part of human diets for centuries.","zh-TW":"像味噌和酸菜這樣的發酵食品已經是人類飲食的一部分長達幾個世紀。"},{"en":"The growing interest in gut health has boosted sales of fermented foods.","zh-TW":"對腸道健康的日益關注推動了發酵食品的銷售增長。"}]', NULL, NULL, 5, 2731, NULL),
(2732, 'ferry', '/''feri/', 'noun', '{"zh-TW":["渡輪；渡船"],"en":["a boat or ship for conveying passengers and goods, especially across a body of water"]}', NULL, 'catch a ferry / ferry terminal / take a ferry', '[{"en":"We took the ferry from the mainland to the island.","zh-TW":"我們乘渡輪從大陸到達島嶼。"},{"en":"The ferry crossing takes about forty-five minutes in calm weather.","zh-TW":"在平靜的天氣中，渡輪過海需要大約四十五分鐘。"}]', NULL, NULL, 2, 2732, NULL),
(2733, 'few', '/fjuː/', 'adjective', '{"zh-TW":["少數的；幾個"],"en":["a small number of"]}', NULL, 'a few / quite a few', '[{"en":"A few candidates were shortlisted.","zh-TW":"幾位候選人進入了決選名單。"},{"en":"Quite a few people attended.","zh-TW":"相當多人出席了。"}]', '{"adjective":"few","adjective2":"fewer","adjective3":"fewest"}', NULL, 1, 2733, NULL),
(2734, 'fiat', '/ˈfiːæt/', 'noun', '{"zh-TW":["命令；法令；法定"],"en":["an authoritative decree; currency backed by government authority rather than a commodity"]}', NULL, 'fiat money / government fiat / fiat currency', '[{"en":"Most modern currencies are fiat money not backed by gold or silver.","zh-TW":"大多數現代貨幣是不以黃金或白銀為後盾的法定貨幣。"},{"en":"The regulation was implemented by executive fiat rather than legislation.","zh-TW":"該法規是通過行政命令而非立法來實施的。"}]', NULL, NULL, 1, 2734, NULL),
(2735, 'fiber', '/''faɪbər/', 'noun', '{"zh-TW":["纖維素；膳食纖維"],"en":["a dietary component found in plant foods that aids digestion"]}', NULL, 'dietary fiber / high-fiber diet / fiber intake', '[{"en":"A diet high in fiber helps prevent digestive problems.","zh-TW":"高纖維飲食有助於預防消化問題。"},{"en":"Fruits, vegetables, and whole grains are excellent sources of dietary fiber.","zh-TW":"水果、蔬菜和全穀類是膳食纖維的絕佳來源。"}]', '{"adjective":"fiber-rich"}', NULL, 2, 2735, NULL),
(2736, 'fiduciary', '/fɪˈdjuːʃəri/', 'adjective', '{"zh-TW":["信託的；受託的"],"en":["involving the legal duty to act in another''s best interest"]}', NULL, 'fiduciary duty / fiduciary responsibility', '[{"en":"Trustees have a fiduciary duty to act in beneficiaries'' interests.","zh-TW":"受託人有法律義務以受益人的利益行事。"},{"en":"A fiduciary relationship requires the highest standard of care.","zh-TW":"信託關係要求最高標準的謹慎義務。"}]', '{"noun":"fiduciary"}', NULL, 3, 2736, NULL),
(2737, 'fiduciary duty', '/fɪˈdjuːʃɪeri ˈdjuːti/', 'noun', '{"zh-TW":["受託義務；信義義務"],"en":["the legal obligation of a person to act in the best interest of another party"]}', NULL, 'fulfill fiduciary duty / fiduciary duty to shareholders', '[{"en":"Directors owe a fiduciary duty to act in the best interest of shareholders.","zh-TW":"董事對股東負有以其最佳利益行事的受託義務。"},{"en":"Breaching fiduciary duty can lead to personal liability for executives.","zh-TW":"違反受託義務可能導致高管承擔個人責任。"}]', NULL, NULL, 5, 2737, NULL),
(2738, 'field', '/fiːld/', 'noun', '{"zh-TW":["【主要意義-名詞】田野；領域；專業範疇","【次要意義-動詞】處理；回應（問題/投訴）","【次要意義-動詞】派遣（球員/團隊）上場"],"en":["[primary - noun] an open area of land; an area of study or work","[secondary - verb] to deal with a question, complaint, or inquiry","[secondary - verb] to send out a team or person to deal with something"]}', NULL, 'field questions / field complaints / field a team / field of expertise', '[{"en":"The customer service team fielded over 200 calls on the first day of the sale.","zh-TW":"客服團隊在促銷活動第一天接聽了逾200通電話。"},{"en":"The spokesperson fielded difficult questions from reporters after the conference.","zh-TW":"發言人在記者招待會後處理了記者提出的棘手問題。"},{"en":"She is an expert in her field and consulted by major corporations.","zh-TW":"她是她所在領域的專家，被各大企業諮詢。"}]', '{"noun":"fieldwork"}', '動詞 field questions/calls/complaints = 「接聽/處理（詢問/投訴）」，是 TOEIC 客服和公關文章的常見用法，考生容易只認識名詞「田野/領域」的意思。', 2, 2738, NULL),
(2739, 'field trip', '/''fiːld trɪp/', 'noun', '{"zh-TW":["校外教學；實地參觀"],"en":["a trip organized by a school or college to a place of educational interest"]}', NULL, 'organize a field trip / go on a field trip / field trip permission slip', '[{"en":"The biology class went on a field trip to the nature reserve to study local wildlife.","zh-TW":"生物課前往自然保護區進行校外教學，研究當地野生動物。"},{"en":"Field trips make learning more memorable by connecting classroom knowledge to the real world.","zh-TW":"校外教學通過將課堂知識與現實世界聯繫起來，使學習更加難忘。"}]', NULL, NULL, 4, 2739, NULL),
(2740, 'fight', '/faɪt/', 'verb', '{"zh-TW":["戰鬥；奮鬥"],"en":["to struggle against","to try hard to achieve"]}', NULL, 'fight for / fight against', '[{"en":"We must fight for our market share.","zh-TW":"我們必須為市場份額而戰。"},{"en":"They fought against the unfair regulation.","zh-TW":"他們反對不公平的法規。"}]', '{"verb":"fight","noun":"fight","noun2":"fighter"}', NULL, 2, 2740, NULL),
(2741, 'figure', '/ˈfɪɡjər/', 'noun / verb', '{"zh-TW":["數字；認為"],"en":["a number or amount; to think or calculate"]}', NULL, 'sales/profit figures', '[{"en":"Sales figures exceeded projections.","zh-TW":"銷售數字超出了預測。"},{"en":"We need to figure out the best approach.","zh-TW":"我們需要想出最佳方法。"}]', '{"noun":"figure","verb":"figure"}', NULL, 2, 2741, NULL),
(2742, 'file', '/faɪl/', 'noun / verb', '{"zh-TW":["檔案；提交"],"en":["a collection of data; to submit officially"]}', NULL, 'file a report/complaint', '[{"en":"Please file the documents in order.","zh-TW":"請按順序歸檔文件。"},{"en":"She filed a complaint with HR.","zh-TW":"她向人資部門提出了投訴。"}]', '{"noun":"file","verb":"file"}', NULL, 1, 2742, NULL),
(2743, 'file a complaint', '/faɪl ə kəmˈpleɪnt/', 'verb', '{"zh-TW":["提出投訴；提交投訴"],"en":["to submit a formal record of dissatisfaction to the appropriate authority"]}', NULL, 'file a complaint with the regulator / file an official complaint', '[{"en":"The customer filed a complaint with the consumer protection agency.","zh-TW":"客戶向消費者保護機構提出了投訴。"},{"en":"Filing a complaint triggers a formal investigation process.","zh-TW":"提出投訴觸發了正式調查流程。"}]', NULL, NULL, 5, 2743, NULL),
(2744, 'filing', '/ˈfaɪlɪŋ/', 'noun', '{"zh-TW":["歸檔；存檔"],"en":["the organizing and storing of documents"]}', NULL, 'document filing / filing system', '[{"en":"Maintain an organized filing system for all records.","zh-TW":"為所有記錄維護有組織的歸檔系統。"},{"en":"The filing of tax documents must be completed by March.","zh-TW":"稅務文件的歸檔必須在三月前完成。"}]', '{"verb":"file","noun":"file","adjective":"filed"}', NULL, 2, 2744, NULL),
(2745, 'fill', '/fɪl/', 'verb', '{"zh-TW":["填寫；填充"],"en":["to make full; to complete a form"]}', NULL, 'fill in/out a form', '[{"en":"Please fill out this application form.","zh-TW":"請填寫此申請表。"},{"en":"The position has been filled.","zh-TW":"該職位已被填補。"}]', '{"noun":"filling","verb":"fill"}', NULL, 1, 2745, NULL),
(2746, 'film', '/fɪlm/', 'noun', '{"zh-TW":["電影；影片"],"en":["a movie","a thin layer"]}', NULL, 'film industry / short film', '[{"en":"The film industry employs thousands.","zh-TW":"電影產業雇用了數千人。"},{"en":"We made a short promotional film.","zh-TW":"我們製作了一部短宣傳影片。"}]', '{"noun":"film","verb":"film","noun2":"filmmaker","noun3":"filming"}', NULL, 1, 2746, NULL),
(2747, 'final', '/ˈfaɪnəl/', 'adjective', '{"zh-TW":["最終的；最後的"],"en":["last; conclusive"]}', NULL, 'final decision/version', '[{"en":"The final decision rests with the board.","zh-TW":"最終決定權在董事會。"},{"en":"Submit the final version by Friday.","zh-TW":"請在週五前提交最終版本。"}]', '{"noun":"final/finale/finalist","verb":"finalize","adjective":"final","adverb":"finally"}', NULL, 2, 2747, 363),
(2748, 'final accounts', '/ˈfaɪnəl əˈkaʊnts/', 'noun', '{"zh-TW":["最終帳目；年終帳目"],"en":["the financial statements prepared at the end of a financial period"]}', NULL, 'prepare final accounts / review final accounts', '[{"en":"The final accounts were submitted to the auditors by March 31.","zh-TW":"最終帳目在3月31日前提交給了審計師。"},{"en":"Final accounts include the balance sheet and profit and loss account.","zh-TW":"最終帳目包括資產負債表和損益帳。"}]', NULL, NULL, 5, 2748, NULL),
(2749, 'final examination', '/''faɪnəl ɪɡˌzæmɪˈneɪʃən/', 'noun', '{"zh-TW":["期末考試；終期測驗"],"en":["an examination held at the end of an academic term or course"]}', NULL, 'prepare for the final examination / pass the final examination / final examination schedule', '[{"en":"She spent two weeks preparing for the final examination in organic chemistry.","zh-TW":"她花了兩週時間準備有機化學的期末考試。"},{"en":"The final examination accounts for fifty percent of the total grade.","zh-TW":"期末考試佔總成績的百分之五十。"}]', NULL, NULL, 5, 2749, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2750, 'finale', '/fɪˈnɑːli/', 'noun', '{"zh-TW":["終曲；最後部分"],"en":["the last part of a piece of music, entertainment, or competition"]}', NULL, 'grand finale / spectacular finale / dramatic finale', '[{"en":"The symphony''s finale brought the audience to their feet.","zh-TW":"交響樂的終曲讓觀眾起立鼓掌。"},{"en":"The show''s season finale broke viewing records for the network.","zh-TW":"該節目的季終章打破了該頻道的收視紀錄。"}]', NULL, NULL, 2, 2750, NULL),
(2751, 'finalize', '/ˈfaɪnəlaɪz/', 'verb', '{"zh-TW":["確定；敲定"],"en":["to complete the last details of a plan or document"]}', NULL, 'finalize the contract / finalize the agenda', '[{"en":"Please finalize the report before the board meeting.","zh-TW":"請在董事會議前確定報告。"},{"en":"We need to finalize the terms before signing.","zh-TW":"我們需要在簽署前敲定條款。"}]', '{"noun":"finalization","adjective":"finalized"}', NULL, 3, 2751, NULL),
(2752, 'finance', '/ˈfaɪnæns/', 'noun / verb', '{"zh-TW":["財務；資助"],"en":["the management of money; to provide funds"]}', NULL, 'personal/corporate finance', '[{"en":"She works in the finance department.","zh-TW":"她在財務部門工作。"},{"en":"The project is financed by private investors.","zh-TW":"該項目由私人投資者資助。"}]', '{"noun":"finance/financing","verb":"finance","adjective":"financial","adverb":"financially"}', NULL, 3, 2752, NULL),
(2753, 'finance lease', '/ˈfaɪnæns liːs/', 'noun', '{"zh-TW":["融資租賃"],"en":["a lease that transfers substantially all risks and rewards of ownership"]}', NULL, 'enter a finance lease / classify as finance lease', '[{"en":"The machinery was acquired under a five-year finance lease.","zh-TW":"機械設備通過五年融資租賃取得。"},{"en":"Finance leases create both an asset and a liability on the balance sheet.","zh-TW":"融資租賃在資產負債表上同時產生資產和負債。"}]', NULL, NULL, 5, 2753, NULL),
(2754, 'finance team', '/faɪˈnæns tiːm/', 'noun', '{"zh-TW":["財務團隊"],"en":["the department responsible for managing a company financial activities"]}', NULL, 'consult the finance team / finance team approval', '[{"en":"The finance team prepared the quarterly budget review.","zh-TW":"財務團隊準備了季度預算審查。"},{"en":"Any large purchase requires sign-off from the finance team.","zh-TW":"任何大額採購都需要財務團隊的批准。"}]', NULL, NULL, 4, 2754, NULL),
(2755, 'financial accounting', '/faɪˈnænʃəl əˈkaʊntɪŋ/', 'noun', '{"zh-TW":["財務會計"],"en":["the process of recording and reporting financial transactions externally"]}', NULL, 'prepare financial accounting statements / financial accounting standards', '[{"en":"Financial accounting is governed by international reporting standards.","zh-TW":"財務會計受國際報告準則的約束。"},{"en":"The external auditor reviewed the financial accounting records.","zh-TW":"外部審計師審查了財務會計記錄。"}]', NULL, NULL, 5, 2755, NULL),
(2756, 'financial assets', '/faɪˈnænʃəl ˈæsets/', 'noun', '{"zh-TW":["金融資產"],"en":["assets that derive value from a claim or contractual obligation"]}', NULL, 'hold financial assets / value financial assets', '[{"en":"The company holds financial assets worth 100 million on its balance sheet.","zh-TW":"公司在資產負債表上持有價值1億元的金融資產。"},{"en":"Financial assets include cash, bonds, and equity holdings.","zh-TW":"金融資產包括現金、債券和股權持有。"}]', NULL, NULL, 5, 2756, NULL),
(2757, 'financial audit', '/faɪˈnænʃəl ˈɔːdɪt/', 'noun', '{"zh-TW":["財務審計"],"en":["an independent examination of a company financial statements"]}', NULL, 'conduct a financial audit / pass a financial audit', '[{"en":"The external financial audit was completed by the end of March.","zh-TW":"外部財務審計於三月底完成。"},{"en":"A clean financial audit report boosted investor confidence.","zh-TW":"乾淨的財務審計報告增強了投資者信心。"}]', NULL, NULL, 5, 2757, NULL),
(2758, 'financial close', '/faɪˈnænʃəl kloʊz/', 'noun', '{"zh-TW":["財務收尾；財務交割"],"en":["the completion of all financial documentation for a deal"]}', NULL, 'achieve financial close / financial close date', '[{"en":"The project reached financial close after months of negotiations.","zh-TW":"經過幾個月的談判後，項目完成了財務交割。"},{"en":"Financial close confirms all funding is in place for the transaction.","zh-TW":"財務交割確認交易的所有資金已到位。"}]', NULL, NULL, 5, 2758, NULL),
(2759, 'financial controller', '/faɪˈnænʃəl kənˈtroʊlər/', 'noun', '{"zh-TW":["財務主任；財務控制人"],"en":["a senior finance professional responsible for accounting, reporting, and controls"]}', NULL, 'appoint a financial controller / financial controller duties', '[{"en":"The financial controller ensured all regulatory filings were submitted on time.","zh-TW":"財務主任確保所有監管申報按時提交。"},{"en":"A financial controller oversees the budget process and manages the finance team.","zh-TW":"財務主任監督預算流程並管理財務團隊。"}]', NULL, NULL, 5, 2759, NULL),
(2760, 'financial covenant', '/faɪˈnænʃəl ˈkʌvənənt/', 'noun', '{"zh-TW":["財務契約"],"en":["a condition in a loan requiring the borrower to maintain certain financial ratios"]}', NULL, 'financial covenant breach / financial covenant waiver / maintenance covenant', '[{"en":"The lenders required the company to maintain a minimum financial covenant.","zh-TW":"貸款方要求公司維持最低財務契約。"},{"en":"A breach of a financial covenant can trigger immediate debt repayment.","zh-TW":"違反財務契約可能觸發即時還款要求。"}]', NULL, NULL, 5, 2760, NULL),
(2761, 'financial disclosure', '/faɪˈnænʃəl dɪsˈkləʊʒər/', 'noun', '{"zh-TW":["財務披露"],"en":["the public release of a company''s financial information"]}', NULL, 'require financial disclosure / financial disclosure statement', '[{"en":"Public companies are required to make regular financial disclosures.","zh-TW":"上市公司必須定期進行財務披露。"},{"en":"Full financial disclosure builds trust with investors.","zh-TW":"完整的財務披露建立了與投資者的信任。"}]', NULL, NULL, 5, 2761, NULL),
(2762, 'financial distress', '/faɪˈnænʃəl dɪˈstres/', 'noun', '{"zh-TW":["財務困境；財務危機"],"en":["a condition where a company cannot meet its financial obligations or is near insolvency"]}', NULL, 'enter financial distress / financial distress indicators', '[{"en":"The company entered financial distress after demand collapsed overnight.","zh-TW":"公司在需求一夜崩潰後陷入財務困境。"},{"en":"Financial distress often leads to debt restructuring or bankruptcy proceedings.","zh-TW":"財務困境通常導致債務重組或破產程序。"}]', NULL, NULL, 5, 2762, NULL),
(2763, 'financial exposure', '/faɪˈnænʃəl ɪkˈspoʊʒər/', 'noun', '{"zh-TW":["財務風險敞口"],"en":["the amount of money at risk from a particular financial position"]}', NULL, 'reduce financial exposure / limit financial exposure', '[{"en":"The company reduced its financial exposure to foreign exchange risk.","zh-TW":"公司降低了對外匯風險的財務風險敞口。"},{"en":"Financial exposure to a single customer should not exceed 30%.","zh-TW":"對單一客戶的財務風險敞口不應超過30%。"}]', NULL, NULL, 5, 2763, NULL),
(2764, 'financial forecast', '/faɪˈnænʃəl ˈfɔːrkæst/', 'noun', '{"zh-TW":["財務預測"],"en":["a projection of future financial performance based on historical data and assumptions"]}', NULL, 'prepare a financial forecast / revise the financial forecast', '[{"en":"The financial forecast predicted revenue growth of 12% next year.","zh-TW":"財務預測預計明年收入增長12%。"},{"en":"Inaccurate financial forecasts can lead to poor resource allocation decisions.","zh-TW":"不準確的財務預測可能導致資源配置決策失誤。"}]', '{"verb":"forecast"}', NULL, 5, 2764, NULL),
(2765, 'financial guarantee', '/faɪˈnænʃəl ˌɡærənˈtiː/', 'noun', '{"zh-TW":["財務擔保"],"en":["a promise by one party to meet another''s financial obligations if they default"]}', NULL, 'issue a financial guarantee / financial guarantee fee', '[{"en":"The subsidiary obtained a financial guarantee from the parent company.","zh-TW":"子公司從母公司獲得了財務擔保。"},{"en":"Banks charge a fee for providing financial guarantees to clients.","zh-TW":"銀行為客戶提供財務擔保收取費用。"}]', NULL, NULL, 5, 2765, NULL),
(2766, 'financial health', '/faɪˈnænʃəl helθ/', 'noun', '{"zh-TW":["財務健康狀況"],"en":["the overall condition of a company finances and ability to meet obligations"]}', NULL, 'assess financial health / maintain financial health', '[{"en":"The acquisition target had strong financial health with low debt levels.","zh-TW":"收購目標擁有強劲的財務健康狀況和低債務水平。"},{"en":"Monthly reviews ensure the company maintains its financial health.","zh-TW":"月度審查確保公司維持其財務健康狀況。"}]', NULL, NULL, 5, 2766, NULL),
(2767, 'financial institution', '/faɪˈnænʃəl ˌɪnstɪˈtjuːʃən/', 'noun', '{"zh-TW":["金融機構"],"en":["an organization such as a bank, insurance company, or investment firm"]}', NULL, 'regulated financial institution / financial institution deposit', '[{"en":"All financial institutions must comply with anti-money-laundering regulations.","zh-TW":"所有金融機構必須遵守反洗錢法規。"},{"en":"The company obtained financing from a leading financial institution.","zh-TW":"公司從一家領先的金融機構獲得了融資。"}]', NULL, NULL, 5, 2767, NULL),
(2768, 'financial intermediary', '/faɪˈnænʃəl ˌɪntərˈmiːdiɪri/', 'noun', '{"zh-TW":["金融中介"],"en":["an institution that channels funds between savers and borrowers"]}', NULL, 'use a financial intermediary / financial intermediary role', '[{"en":"Banks act as financial intermediaries between depositors and borrowers.","zh-TW":"銀行在存款人和借款人之間充當金融中介。"},{"en":"Financial intermediaries reduce transaction costs in capital markets.","zh-TW":"金融中介降低了資本市場的交易成本。"}]', NULL, NULL, 5, 2768, NULL),
(2769, 'financial leverage', '/faɪˈnænʃəl ˈlevərɪdʒ/', 'noun', '{"zh-TW":["財務槓桿"],"en":["using borrowed funds to increase the potential return on investment"]}', NULL, 'use financial leverage / high financial leverage', '[{"en":"Excessive financial leverage magnifies both gains and losses.","zh-TW":"過度的財務槓桿既放大了收益也放大了損失。"},{"en":"The company reduced financial leverage by paying down debt.","zh-TW":"公司通過還清債務減少了財務槓桿。"}]', NULL, NULL, 5, 2769, NULL),
(2770, 'financial literacy', '/faɪˈnænʃəl ˈlɪtərəsi/', 'noun', '{"zh-TW":["金融素養"],"en":["the ability to understand and effectively use financial skills"]}', NULL, 'improve financial literacy / financial literacy education / lack of financial literacy', '[{"en":"Financial literacy programs help people make better personal finance decisions.","zh-TW":"金融素養計畫幫助人們做出更好的個人理財決策。"},{"en":"Low financial literacy contributes to high household debt levels.","zh-TW":"低金融素養導致家庭債務水平高。"}]', '{"adjective":"financially literate"}', NULL, 5, 2770, NULL),
(2771, 'financial modeling', '/faɪˈnænʃəl ˈmɒdəlɪŋ/', 'noun', '{"zh-TW":["財務建模"],"en":["building mathematical representations of a company''s financial performance"]}', NULL, 'build a financial model / financial modeling skills / financial modeling software', '[{"en":"Financial modeling is essential for evaluating acquisition targets.","zh-TW":"財務建模對評估收購目標至關重要。"},{"en":"The analyst used financial modeling to project five-year cash flows.","zh-TW":"分析師使用財務建模預測了五年現金流。"}]', '{"verb":"model","noun":"financial model"}', NULL, 5, 2771, NULL),
(2772, 'financial obligation', '/faɪˈnænʃəl ˌɒblɪˈɡeɪʃən/', 'noun', '{"zh-TW":["財務義務"],"en":["a contractual or legal duty to pay money to another party"]}', NULL, 'meet financial obligations / financial obligation default', '[{"en":"The company met all its financial obligations despite difficult market conditions.","zh-TW":"儘管市場條件困難，公司履行了所有財務義務。"},{"en":"Failure to meet a financial obligation can trigger cross-default provisions.","zh-TW":"未能履行財務義務可能觸發交叉違約條款。"}]', NULL, NULL, 5, 2772, NULL),
(2773, 'financial planning', '/faɪˈnænʃəl ˈplænɪŋ/', 'noun', '{"zh-TW":["財務規劃"],"en":["the process of setting goals and creating a plan to achieve them financially"]}', NULL, 'engage in financial planning / long-term financial planning', '[{"en":"The CFO led the annual financial planning process.","zh-TW":"財務長主導了年度財務規劃流程。"},{"en":"Effective financial planning requires accurate forecasting and scenario analysis.","zh-TW":"有效的財務規劃需要準確的預測和情境分析。"}]', NULL, NULL, 5, 2773, NULL),
(2774, 'financial projection', '/''faɪˌnænʃəl prəˌdʒekʃən/', 'noun', '{"zh-TW":["財務預測；財務預估"],"en":["an estimate of future financial performance based on current data and assumptions"]}', NULL, 'create financial projections / review financial projections / realistic financial projections', '[{"en":"The startup''s financial projections showed profitability within three years.","zh-TW":"新創公司的財務預測顯示在三年內將實現盈利。"},{"en":"Investors scrutinize financial projections to assess the viability of a business plan.","zh-TW":"投資者仔細審查財務預測，以評估商業計劃的可行性。"}]', NULL, NULL, 5, 2774, NULL),
(2775, 'financial ratio', '/faɪˈnænʃəl ˈreɪʃioʊ/', 'noun', '{"zh-TW":["財務比率"],"en":["a quantitative measure derived from financial statements to assess performance"]}', NULL, 'calculate financial ratios / compare financial ratios', '[{"en":"Key financial ratios are used to benchmark performance against industry peers.","zh-TW":"關鍵財務比率用於基準化與同行業企業的績效。"},{"en":"Analysts compute multiple financial ratios before making investment recommendations.","zh-TW":"分析師在提出投資建議之前計算多種財務比率。"}]', NULL, NULL, 5, 2775, NULL),
(2776, 'financial reporting', '/faɪˈnænʃəl rɪˈpɔːrtɪŋ/', 'noun', '{"zh-TW":["財務報告"],"en":["the process of preparing and disclosing financial statements to stakeholders"]}', NULL, 'prepare financial reporting / financial reporting standards', '[{"en":"Quarterly financial reporting is required for all listed companies.","zh-TW":"所有上市公司都需要進行季度財務報告。"},{"en":"Transparent financial reporting builds investor trust.","zh-TW":"透明的財務報告建立了投資者信任。"}]', NULL, NULL, 5, 2776, NULL),
(2777, 'financial risk', '/faɪˈnænʃəl rɪsk/', 'noun', '{"zh-TW":["財務風險"],"en":["the possibility of losing money due to business or investment decisions"]}', NULL, 'manage financial risk / financial risk assessment', '[{"en":"The company''s expansion into new markets introduced significant financial risk.","zh-TW":"公司進入新市場引入了重大財務風險。"},{"en":"Diversification is a key tool for managing financial risk.","zh-TW":"多元化是管理財務風險的關鍵工具。"}]', NULL, NULL, 5, 2777, NULL),
(2778, 'financial risk management', '/faɪˈnænʃəl rɪsk ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["財務風險管理"],"en":["the identification and mitigation of financial risks facing an organization"]}', NULL, 'implement financial risk management / financial risk management framework', '[{"en":"The treasury team leads financial risk management for currency exposure.","zh-TW":"財務團隊負責主導貨幣風險敞口的財務風險管理。"},{"en":"A financial risk management policy includes liquidity and credit risk controls.","zh-TW":"財務風險管理政策包括流動性和信用風險控制。"}]', NULL, NULL, 5, 2778, NULL),
(2779, 'financial stability', '/faɪˈnænʃəl stəˈbɪlɪti/', 'noun', '{"zh-TW":["財務穩定性"],"en":["the ability of a company or system to remain financially sound over time"]}', NULL, 'ensure financial stability / financial stability report', '[{"en":"A three-month cash reserve contributes to financial stability.","zh-TW":"三個月的現金儲備有助於財務穩定性。"},{"en":"The central bank monitors financial stability across the banking sector.","zh-TW":"中央銀行監測整個銀行業的財務穩定性。"}]', NULL, NULL, 5, 2779, NULL),
(2780, 'financial statement', '/faɪˈnænʃəl ˈsteɪtmənt/', 'noun', '{"zh-TW":["財務報表"],"en":["formal records of the financial activities and position of a business"]}', NULL, 'prepare financial statements / audit financial statements / analyze financial statements', '[{"en":"Financial statements are required by law for listed companies.","zh-TW":"上市公司依法須編制財務報表。"},{"en":"Investors analyze financial statements to assess a company''s health.","zh-TW":"投資者分析財務報表以評估公司的健康狀況。"}]', NULL, NULL, 5, 2780, NULL),
(2781, 'financial transaction', '/faɪˈnænʃəl trænˈzækʃən/', 'noun', '{"zh-TW":["金融交易；財務交易"],"en":["an exchange of money or financial instruments between parties"]}', NULL, 'record a financial transaction / verify a financial transaction', '[{"en":"Each financial transaction is logged in the general ledger.","zh-TW":"每筆財務交易都記錄在總帳中。"},{"en":"Anti-money laundering checks apply to large financial transactions.","zh-TW":"反洗錢檢查適用於大額金融交易。"}]', NULL, NULL, 5, 2781, NULL),
(2782, 'find', 'faɪnd', 'verb', '{"zh-TW":["找到；發現","認為"],"en":["to locate something","to discover"]}', NULL, 'find a solution/error', '[{"en":"Please find the missing invoice.","zh-TW":"請找到遺失的發票。"}]', '{"noun":"finding","adjective":"findable"}', NULL, 1, 2782, NULL),
(2783, 'finding', '/ˈfaɪndɪŋ/', 'noun', '{"zh-TW":["發現；調查結果"],"en":["information discovered as a result of research"]}', NULL, 'key/research findings', '[{"en":"The findings were published in the report.","zh-TW":"調查結果已發表在報告中。"},{"en":"Key findings indicate a shift in trends.","zh-TW":"主要發現顯示趨勢轉變。"}]', '{"noun":"finding","verb":"find"}', NULL, 3, 2783, NULL),
(2784, 'fine', '/faɪn/', 'noun / verb / adjective', '{"zh-TW":["【主要意義-形容詞】好的；晴朗的；精緻的","【次要意義-名詞】罰款","【次要意義-動詞】對……處以罰款","【次要意義-副詞】很好地；細緻地"],"en":["[primary - adjective] of high quality; well; clear weather","[secondary - noun] a sum of money paid as a penalty","[secondary - verb] to require someone to pay a fine"]}', NULL, 'pay a fine / impose a fine / fine someone for / traffic fine', '[{"en":"The company was fined $50,000 for violating environmental regulations.","zh-TW":"該公司因違反環保法規被罰款5萬美元。"},{"en":"He received a fine for parking in a restricted zone.","zh-TW":"他因在禁止停車區停車而收到罰款單。"},{"en":"The regulator has the authority to fine companies for non-compliance.","zh-TW":"監管機構有權對不合規的公司進行罰款。"}]', '{"noun":"fining"}', 'fine 作名詞/動詞意為「罰款」，是 TOEIC 法規、合規或政府公告類文章的常見詞，考生容易只記住「好的/晴朗的」這個意思。', 1, 2784, NULL),
(2785, 'finger', '/ˈfɪŋɡər/', 'noun', '{"zh-TW":["手指"],"en":["one of the five parts at the end of the hand"]}', NULL, 'point the finger / finger on the pulse', '[{"en":"Don''t point the finger at others.","zh-TW":"別指責別人。"},{"en":"She has her finger on the pulse of the market.","zh-TW":"她對市場動態了然於胸。"}]', '{"noun":"finger","noun2":"fingertip","noun3":"fingerprint"}', NULL, 2, 2785, NULL),
(2786, 'finish', '/ˈfɪnɪʃ/', 'verb', '{"zh-TW":["完成；結束"],"en":["to complete","to come to an end"]}', NULL, 'finish on time / finish line', '[{"en":"We need to finish by the deadline.","zh-TW":"我們必須在截止日期前完成。"},{"en":"The project is nearly finished.","zh-TW":"專案快要完成了。"}]', '{"verb":"finish","noun":"finish"}', NULL, 2, 2786, NULL),
(2787, 'finite', '/''faɪnaɪt/', 'adjective', '{"zh-TW":["有限的；有限制的"],"en":["limited in size or extent; having an end or limit"]}', NULL, 'finite resources / finite time / finite amount', '[{"en":"Earth''s finite resources must be managed carefully to ensure sustainability.","zh-TW":"地球有限的資源必須被謹慎管理，以確保可持續性。"},{"en":"We have a finite amount of time to complete the project, so prioritization is essential.","zh-TW":"我們完成項目的時間有限，因此優先排序至關重要。"}]', '{"adverb":"finitely","noun":"finiteness","antonym":"infinite"}', NULL, 2, 2787, NULL),
(2788, 'fintech', '/ˈfɪntek/', 'noun', '{"zh-TW":["金融科技"],"en":["technology-driven innovation in financial services"]}', NULL, 'use fintech / fintech startup / fintech sector', '[{"en":"Fintech companies are disrupting traditional banking models.","zh-TW":"金融科技公司正在顛覆傳統銀行模式。"},{"en":"The fintech platform allows users to transfer money instantly.","zh-TW":"金融科技平台允許用戶即時轉帳。"}]', NULL, NULL, 3, 2788, NULL),
(2789, 'fire', '/ˈfaɪər/', 'noun', '{"zh-TW":["火；火災；解雇"],"en":["combustion","to dismiss from a job"]}', NULL, 'catch fire / fire drill', '[{"en":"We conduct fire drills every quarter.","zh-TW":"我們每季進行消防演練。"},{"en":"He was fired for misconduct.","zh-TW":"他因行為不當被解雇。"}]', '{"noun":"fire","verb":"fire","noun2":"firefighter"}', NULL, 1, 2789, NULL),
(2790, 'fire drill', '/ˈfaɪər drɪl/', 'noun', '{"zh-TW":["消防演習"],"en":["a practice evacuation in case of fire"]}', NULL, 'conduct a fire drill / participate in a fire drill', '[{"en":"The office conducts a fire drill every six months.","zh-TW":"辦公室每六個月進行一次消防演習。"},{"en":"All employees must participate in the scheduled fire drill.","zh-TW":"所有員工必須參加定期的消防演習。"}]', NULL, NULL, 4, 2790, NULL),
(2791, 'fire extinguisher', '/ˈfaɪər ɪkˌstɪŋɡwɪʃər/', 'noun', '{"zh-TW":["滅火器"],"en":["a device for putting out small fires"]}', NULL, 'operate a fire extinguisher / check the fire extinguisher', '[{"en":"Know how to operate a fire extinguisher in an emergency.","zh-TW":"了解如何在緊急情況下使用滅火器。"},{"en":"Fire extinguishers must be inspected and recharged regularly.","zh-TW":"滅火器必須定期檢查和充裝。"}]', NULL, NULL, 5, 2791, NULL),
(2792, 'firewall', '/ˈfaɪərwɔːl/', 'noun', '{"zh-TW":["防火牆"],"en":["a system that prevents unauthorized access"]}', NULL, 'set up a firewall / firewall protection', '[{"en":"The firewall blocked the attack.","zh-TW":"防火牆阻擋了攻擊。"},{"en":"Make sure your firewall is active.","zh-TW":"確認你的防火牆已啟用。"}]', NULL, NULL, 3, 2792, NULL),
(2793, 'firm', '/fɜːrm/', 'noun / adjective', '{"zh-TW":["公司；堅定的"],"en":["a business; strong and unlikely to change"]}', NULL, 'law/consulting firm', '[{"en":"She works for a consulting firm.","zh-TW":"她在一家顧問公司工作。"},{"en":"The manager was firm in her decision.","zh-TW":"經理對她的決定很堅定。"}]', '{"noun":"firm","adjective":"firm","adverb":"firmly"}', NULL, 1, 2793, NULL),
(2794, 'firmware', '/ˈfɜːrmwɛr/', 'noun', '{"zh-TW":["韌體"],"en":["software built into hardware devices"]}', NULL, 'firmware update / latest firmware', '[{"en":"Update the firmware to fix the issue.","zh-TW":"更新韌體以修復問題。"},{"en":"The firmware controls the hardware.","zh-TW":"韌體控制硬體。"}]', NULL, NULL, 3, 2794, NULL),
(2795, 'first aid kit', '/fɜːrst eɪd kɪt/', 'noun', '{"zh-TW":["急救箱"],"en":["a box containing supplies for emergency medical treatment"]}', NULL, 'use a first aid kit / stock a first aid kit', '[{"en":"Every office should have a stocked first aid kit.","zh-TW":"每個辦公室都應備有裝滿用品的急救箱。"},{"en":"The first aid kit included bandages, antiseptic, and pain relievers.","zh-TW":"急救箱包含繃帶、消毒液和止痛藥。"}]', NULL, NULL, 5, 2795, NULL),
(2796, 'first class', '/fɜːrst klæs/', 'noun', '{"zh-TW":["頭等艙"],"en":["the highest class of travel on a plane or train"]}', NULL, 'travel first class / first class lounge', '[{"en":"First class passengers receive premium meals and service.","zh-TW":"頭等艙乘客享有高級餐食和服務。"},{"en":"The first class cabin has fully flat beds.","zh-TW":"頭等艙客艙配有全平躺式座椅。"}]', NULL, NULL, 4, 2796, NULL),
(2797, 'first responder', '/fɜːrst rɪˈspɒndər/', 'noun', '{"zh-TW":["第一反應者；緊急救援人員"],"en":["a person trained to respond first to an emergency"]}', NULL, 'train first responders / paramedic first responder / support first responders', '[{"en":"First responders arrived at the scene within minutes of the emergency call.","zh-TW":"緊急救援人員在緊急呼叫後幾分鐘內到達現場。"},{"en":"First responder mental health support has become a major policy focus.","zh-TW":"第一反應者心理健康支持已成為主要政策焦點。"}]', NULL, NULL, 5, 2797, NULL),
(2798, 'first-mover advantage', '/fɜːrst ˈmuːvər ədˈvɑːntɪdʒ/', 'noun', '{"zh-TW":["先行者優勢"],"en":["the competitive edge gained by being the first to enter a new market"]}', NULL, 'exploit first-mover advantage / benefit from first-mover advantage', '[{"en":"Amazon''s first-mover advantage in e-commerce proved decisive.","zh-TW":"亞馬遜在電子商務中的先行者優勢被證明是決定性的。"},{"en":"First-mover advantage is most valuable in fast-moving technology markets.","zh-TW":"先行者優勢在快速變化的科技市場中最有價值。"}]', NULL, NULL, 5, 2798, NULL),
(2799, 'fiscal', '/ˈfɪskəl/', 'adjective', '{"zh-TW":["財政的"],"en":["relating to government revenue and spending"]}', NULL, 'fiscal year/policy', '[{"en":"The fiscal year ends in March.","zh-TW":"會計年度在三月結束。"},{"en":"Fiscal policy affects economic growth.","zh-TW":"財政政策影響經濟增長。"}]', '{"adjective":"fiscal"}', NULL, 2, 2799, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2800, 'fiscal deficit', '/ˈfɪskəl ˈdefɪsɪt/', 'noun', '{"zh-TW":["財政赤字"],"en":["when government spending exceeds government revenue"]}', NULL, 'reduce the fiscal deficit / widen the fiscal deficit', '[{"en":"The government introduced austerity measures to cut the fiscal deficit.","zh-TW":"政府引入緊縮措施以削減財政赤字。"},{"en":"A growing fiscal deficit raised concerns among international lenders.","zh-TW":"不斷擴大的財政赤字引發了國際貸款方的擔憂。"}]', NULL, NULL, 5, 2800, NULL),
(2801, 'fiscal policy', '/ˈfɪskəl ˈpɒlɪsi/', 'noun', '{"zh-TW":["財政政策"],"en":["government use of taxation and spending to influence the economy"]}', NULL, 'expansionary fiscal policy / tight fiscal policy', '[{"en":"Expansionary fiscal policy helped stimulate economic growth.","zh-TW":"擴張性財政政策有助於刺激經濟增長。"},{"en":"The government''s fiscal policy focused on reducing the deficit.","zh-TW":"政府的財政政策著重於減少赤字。"}]', '{"adjective":"fiscal"}', NULL, 5, 2801, NULL),
(2802, 'fiscal year', '/ˈfɪskəl jɪər/', 'noun', '{"zh-TW":["財政年度"],"en":["a 12-month accounting period used for financial reporting"]}', NULL, 'fiscal year end / fiscal year results / fiscal year 2025', '[{"en":"The company''s fiscal year runs from April to March.","zh-TW":"公司的財政年度從四月到三月。"},{"en":"Results are reported at the end of each fiscal year.","zh-TW":"業績在每個財政年度末報告。"}]', '{"abbreviation":"FY","adjective":"fiscal"}', NULL, 4, 2802, NULL),
(2803, 'fiscal year end', '/ˈfɪskəl jɪər end/', 'noun', '{"zh-TW":["財政年度末；會計年度結束"],"en":["the last day of a company''s accounting year"]}', NULL, 'report at fiscal year end / fiscal year end closing', '[{"en":"All accounts must be reconciled before fiscal year end.","zh-TW":"所有帳戶必須在財政年度末之前對帳。"},{"en":"The company''s fiscal year end is December 31 for all subsidiaries.","zh-TW":"公司所有子公司的財政年度末均為12月31日。"}]', '{"abbreviation":"FYE"}', NULL, 5, 2803, NULL),
(2804, 'fiscal year-end', '/ˈfɪskəl jɪər end/', 'noun', '{"zh-TW":["財務年度末；會計年度末"],"en":["the end date of a company''s 12-month accounting period"]}', NULL, 'prepare for fiscal year-end / fiscal year-end report', '[{"en":"All accounts must be finalized for fiscal year-end reporting.","zh-TW":"所有帳目必須在財務年度末報告前完成。"},{"en":"The fiscal year-end is March 31 for most Japanese companies.","zh-TW":"大多數日本公司的財務年度末為3月31日。"}]', NULL, NULL, 5, 2804, NULL),
(2805, 'fish', '/fɪʃ/', 'noun', '{"zh-TW":["魚"],"en":["a cold-blooded animal living in water"]}', NULL, 'a big fish / fish for compliments', '[{"en":"He is a big fish in the industry.","zh-TW":"他是業界的大人物。"},{"en":"Fresh fish is served daily.","zh-TW":"每天供應新鮮魚類。"}]', '{"noun":"fish","verb":"fish","noun2":"fishing","noun3":"fisherman"}', NULL, 1, 2805, NULL),
(2806, 'fit', '/fɪt/', 'verb / adjective', '{"zh-TW":["適合；健康的"],"en":["to be the right size; suitable"]}', NULL, 'fit for purpose / a good fit', '[{"en":"This candidate is a good fit for the role.","zh-TW":"這位候選人很適合這個職位。"},{"en":"The product must be fit for purpose.","zh-TW":"產品必須適合其用途。"}]', '{"noun":"fitness","verb":"fit","adjective":"fit/fitting"}', NULL, 1, 2806, NULL),
(2807, 'fitness', '/ˈfɪtnəs/', 'noun', '{"zh-TW":["健身；適合度"],"en":["the condition of being physically healthy"]}', NULL, 'fitness center / physical fitness', '[{"en":"She goes to the fitness center daily.","zh-TW":"她每天去健身中心。"},{"en":"Regular exercise improves fitness.","zh-TW":"規律運動能改善體能。"}]', '{"adjective":"fit"}', NULL, 3, 2807, NULL),
(2808, 'fitness center', '/ˈfɪtnɪs ˈsɛntər/', 'noun', '{"zh-TW":["健身中心"],"en":["a place equipped for physical exercise"]}', NULL, 'hotel fitness center / use the fitness center', '[{"en":"The fitness center is open 24 hours a day.","zh-TW":"健身中心全天24小時開放。"},{"en":"Guests can enjoy the fully equipped fitness center.","zh-TW":"住客可享用設備齊全的健身中心。"}]', NULL, NULL, 5, 2808, NULL),
(2809, 'fitness goal', '/''fɪtnəs ɡəʊl/', 'noun', '{"zh-TW":["健身目標"],"en":["a specific aim related to physical health, such as weight loss, muscle gain, or endurance improvement"]}', NULL, 'set a fitness goal / achieve a fitness goal / realistic fitness goal', '[{"en":"Setting clear fitness goals helps you stay motivated and track progress effectively.","zh-TW":"設定明確的健身目標有助於保持動力並有效追蹤進度。"},{"en":"Her long-term fitness goal was to complete a full triathlon within two years.","zh-TW":"她的長期健身目標是在兩年內完成一場全程鐵人三項比賽。"}]', '{"noun":"fitness"}', NULL, 4, 2809, NULL),
(2810, 'fitness room', '/''fɪtnəs ruːm/', 'noun', '{"zh-TW":["健身房；健身室"],"en":["a room or area in a hotel or building equipped with exercise equipment"]}', NULL, 'use the fitness room / fitness room access / hotel fitness room', '[{"en":"The hotel''s fitness room was open twenty-four hours a day.","zh-TW":"飯店的健身房全天二十四小時開放。"},{"en":"She started each morning with a thirty-minute workout in the fitness room.","zh-TW":"她每天早上在健身房鍛煉三十分鐘開始新的一天。"}]', NULL, NULL, 4, 2810, NULL),
(2811, 'fitting room', '/ˈfɪtɪŋ ruːm/', 'noun', '{"zh-TW":["試衣間"],"en":["a room where you can try on clothes before buying"]}', '{"root":{"text":"fit","meaning":"suit (合適)"},"logic":"確認衣物是否合適的房間。"}', 'fitting room area / go to the fitting room', '[{"en":"The fitting rooms are at the back of the store.","zh-TW":"試衣間在店的後方。"},{"en":"You can only take three items into the fitting room.","zh-TW":"試衣間一次只能帶三件。"}]', NULL, NULL, 4, 2811, NULL),
(2812, 'fix', '/fɪks/', 'verb', '{"zh-TW":["修理；固定"],"en":["to repair; to fasten securely"]}', NULL, 'fix a problem/bug', '[{"en":"The technician fixed the printer.","zh-TW":"技術人員修好了印表機。"},{"en":"We need to fix this issue urgently.","zh-TW":"我們需要緊急修復這個問題。"}]', '{"noun":"fix","verb":"fix","adjective":"fixed"}', NULL, 1, 2812, NULL),
(2813, 'fixed asset', '/fɪkst ˈæset/', 'noun', '{"zh-TW":["固定資產"],"en":["long-term tangible property used in business operations"]}', NULL, 'depreciate fixed assets / fixed asset register / purchase fixed assets', '[{"en":"Machinery and buildings are examples of fixed assets.","zh-TW":"機械和建築物是固定資產的例子。"},{"en":"Fixed assets are depreciated over their useful life.","zh-TW":"固定資產在其使用壽命內進行折舊。"}]', '{"plural":"fixed assets"}', NULL, 4, 2813, NULL),
(2814, 'fixed asset register', '/fɪkst ˈæset ˈredʒɪstər/', 'noun', '{"zh-TW":["固定資產登記冊"],"en":["a record of all fixed assets owned by an organization"]}', NULL, 'maintain a fixed asset register / fixed asset register audit', '[{"en":"The fixed asset register must be updated when equipment is purchased.","zh-TW":"購買設備時必須更新固定資產登記冊。"},{"en":"An accurate fixed asset register supports depreciation calculations.","zh-TW":"準確的固定資產登記冊支持折舊計算。"}]', NULL, NULL, 5, 2814, NULL),
(2815, 'fixed assets', '/fɪkst ˈæsets/', 'noun', '{"zh-TW":["固定資產"],"en":["long-term tangible assets used in the operation of a business"]}', NULL, 'manage fixed assets / depreciate fixed assets', '[{"en":"Fixed assets include property, machinery, and equipment.","zh-TW":"固定資產包括房產、機械和設備。"},{"en":"The company increased its fixed assets through the new factory investment.","zh-TW":"公司通過新工廠投資增加了固定資產。"}]', NULL, NULL, 4, 2815, NULL),
(2816, 'fixed cost', '/fɪkst kɒst/', 'noun', '{"zh-TW":["固定成本"],"en":["a cost that does not change with the level of output"]}', NULL, 'reduce fixed costs / fixed cost analysis', '[{"en":"Rent and salaries are examples of fixed costs.","zh-TW":"租金和薪資是固定成本的例子。"},{"en":"Fixed costs must be covered regardless of sales volume.","zh-TW":"無論銷售量如何，固定成本都必須承擔。"}]', NULL, NULL, 4, 2816, NULL),
(2817, 'fixed costs', '/fɪkst kɒsts/', 'noun', '{"zh-TW":["固定成本"],"en":["costs that remain constant regardless of how much a company produces"]}', NULL, 'manage fixed costs / reduce fixed costs', '[{"en":"Rent and salaries are the largest fixed costs for most businesses.","zh-TW":"租金和薪資是大多數企業最大的固定成本。"},{"en":"Reducing fixed costs is critical during a revenue downturn.","zh-TW":"在收入低迷期間降低固定成本至關重要。"}]', '{"opposite":"variable costs"}', NULL, 4, 2817, NULL),
(2818, 'fixed deposit', '/fɪkst dɪˈpɒzɪt/', 'noun', '{"zh-TW":["定期存款"],"en":["a savings account offering higher interest for a fixed period"]}', NULL, 'open a fixed deposit / fixed deposit interest rate / mature a fixed deposit', '[{"en":"He placed his savings in a 12-month fixed deposit.","zh-TW":"他將儲蓄存入12個月的定期存款。"},{"en":"Fixed deposit rates are higher than standard savings account rates.","zh-TW":"定期存款利率高於普通儲蓄帳戶利率。"}]', NULL, NULL, 5, 2818, NULL),
(2819, 'fixed income', '/fɪkst ˈɪnkʌm/', 'noun', '{"zh-TW":["固定收益"],"en":["investments that pay a regular set return, such as bonds"]}', NULL, 'invest in fixed income / fixed income portfolio', '[{"en":"Retirees often prefer fixed income investments for stable returns.","zh-TW":"退休人員通常偏好固定收益投資以獲得穩定回報。"},{"en":"The fund shifted toward fixed income securities as rates rose.","zh-TW":"隨著利率上升，基金轉向了固定收益證券。"}]', NULL, NULL, 4, 2819, NULL),
(2820, 'fixed income security', '/fɪkst ˈɪnkʌm sɪˈkjʊərɪti/', 'noun', '{"zh-TW":["固定收益證券"],"en":["an investment providing regular interest payments and return of principal at maturity"]}', NULL, 'invest in fixed income securities / fixed income security portfolio', '[{"en":"Government bonds are the most common type of fixed income security.","zh-TW":"政府債券是最常見的固定收益證券類型。"},{"en":"Fixed income securities provide predictable returns for conservative investors.","zh-TW":"固定收益證券為保守型投資者提供可預測的回報。"}]', NULL, NULL, 5, 2820, NULL),
(2821, 'fixed overhead', '/fɪkst ˈoʊvərhed/', 'noun', '{"zh-TW":["固定間接費用"],"en":["overhead costs that remain constant regardless of production volume"]}', NULL, 'absorb fixed overhead / allocate fixed overhead', '[{"en":"Fixed overhead includes rent, insurance, and management salaries.","zh-TW":"固定間接費用包括租金、保險和管理層薪資。"},{"en":"Higher output spreads fixed overhead over more units, reducing unit cost.","zh-TW":"更高的產量將固定間接費用分攤到更多單位，降低了單位成本。"}]', NULL, NULL, 5, 2821, NULL),
(2822, 'fixture', '/''fɪkstʃər/', 'noun', '{"zh-TW":["固定賽程；賽事安排"],"en":["a sporting event that has been scheduled to take place on a particular date"]}', NULL, 'upcoming fixture / challenging fixture / fixture list', '[{"en":"The team faces a difficult fixture against the league leaders this weekend.","zh-TW":"球隊本週末面臨與聯賽榜首的艱難賽事。"},{"en":"The fixture list for the new season was released last Monday.","zh-TW":"新賽季的賽程表於上週一公布。"}]', NULL, NULL, 3, 2822, NULL),
(2823, 'fixtures and fittings', '/''fɪkstʃəz ən ˈfɪtɪŋz/', 'noun', '{"zh-TW":["固定裝置和配件"],"en":["permanent items installed in a property, such as kitchen units and bathroom fittings, included in a sale"]}', NULL, 'included fixtures and fittings / remove fixtures and fittings / list of fixtures and fittings', '[{"en":"The fixtures and fittings included in the sale were listed in the contract.","zh-TW":"銷售中包含的固定裝置和配件已在合同中列出。"},{"en":"Buyers should confirm which fixtures and fittings will remain in the property.","zh-TW":"買家應確認哪些固定裝置和配件將保留在房產中。"}]', NULL, NULL, 5, 2823, NULL),
(2824, 'flag', '/flæɡ/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】旗子；旗幟","【次要意義-動詞】衰弱；精力下降；熱情減退","【次要意義-動詞】標記；標示（需注意之處）"],"en":["[primary - noun] a piece of cloth used as a symbol or signal","[secondary - verb] to become tired or less enthusiastic","[secondary - verb] to mark something for attention"]}', NULL, 'flag down / energy flags / flag a concern', '[{"en":"His enthusiasm for the project began to flag after months of setbacks.","zh-TW":"經過幾個月的挫折後，他對這個專案的熱情開始消退。"},{"en":"The editor flagged several errors in the report.","zh-TW":"編輯在報告中標記了幾個錯誤。"},{"en":"Sales flagged in the third quarter due to market uncertainty.","zh-TW":"由於市場不確定性，第三季度的銷售額下滑。"}]', '{"noun":"flagging","adjective":"flagging"}', '動詞 flag 表示「精力/興趣衰退」或「標記」，與旗子完全無關，常見於 TOEIC 閱讀描述業務下滑或編輯流程的文章中。', 1, 2824, NULL),
(2825, 'flagship publication', '/ˈflæɡʃɪp ˌpʌblɪˈkeɪʃən/', 'noun', '{"zh-TW":["旗艦刊物；核心出版物"],"en":["the most important or representative publication of an organization"]}', NULL, 'launch a flagship publication / promote a flagship publication / flagship journal', '[{"en":"The institute''s flagship publication reaches scholars in forty countries.","zh-TW":"該機構的旗艦刊物觸及了四十個國家的學者。"},{"en":"The newspaper''s flagship publication was supplemented by a weekly magazine.","zh-TW":"這份報紙的旗艦刊物輔以一份週刊。"}]', NULL, NULL, 5, 2825, NULL),
(2826, 'flagship species', '/ˈflæɡʃɪp ˈspiːʃiːz/', 'noun', '{"zh-TW":["旗艦物種"],"en":["a species chosen to represent conservation efforts and raise public awareness"]}', NULL, 'protect flagship species / flagship species conservation / use a flagship species', '[{"en":"The giant panda is China''s flagship species for conservation campaigns.","zh-TW":"大熊貓是中國保育活動的旗艦物種。"},{"en":"Flagship species generate public support for broader biodiversity protection.","zh-TW":"旗艦物種為更廣泛的生物多樣性保護爭取了公眾支持。"}]', NULL, NULL, 5, 2826, NULL),
(2827, 'flat', '/flæt/', 'adjective, adverb, noun', '{"zh-TW":["【主要意義-形容詞】平的；扁平的","【次要意義-副詞】斷然地；完全地；一口回絕地","【次要意義-形容詞】平淡的；無聊的；沒電的（電池）","【次要意義-名詞（英式）】公寓"],"en":["[primary - adjective] having a level surface","[secondary - adverb] in a direct and definite way; absolutely","[secondary - adjective] dull and lacking energy; (of a battery) having no charge","[secondary - noun (British English)] an apartment"]}', NULL, 'fall flat / flat out / flat rate / turn someone down flat / flat denial', '[{"en":"She turned down the offer flat, without any further discussion.","zh-TW":"她斷然拒絕了這個提議，沒有作進一步的討論。"},{"en":"The new product launch fell flat despite heavy promotion.","zh-TW":"儘管大力宣傳，新產品的發布還是沒有引起反響。"},{"en":"The company charges a flat rate of 200 dollars per month for the service.","zh-TW":"公司對該服務收取每月200美元的固定費率。"}]', '{"adverb":"flatly","noun":"flatness"}', 'flat 作副詞表「斷然地」（turn down flat = 斷然拒絕），fall flat（失敗/沒有效果），flat rate（固定費率）均是 TOEIC 商業文章的高頻表達，flat（英式）= 公寓也常出現。', 1, 2827, NULL),
(2828, 'flat organization', '/flæt ˌɔːrɡənəˈzeɪʃən/', 'noun', '{"zh-TW":["扁平化組織"],"en":["an organization with few management layers between staff and executives"]}', NULL, 'flat organization structure / benefits of a flat organization', '[{"en":"The startup adopted a flat organization to speed up decision-making.","zh-TW":"新創公司採用扁平化組織以加速決策。"},{"en":"A flat organization encourages open communication across all levels.","zh-TW":"扁平化組織鼓勵各層級之間的開放溝通。"}]', NULL, NULL, 5, 2828, NULL),
(2829, 'fledgling', '/ˈfledʒlɪŋ/', 'adjective', '{"zh-TW":["新興的；羽翼未豐的"],"en":["new and inexperienced; just beginning to develop"]}', NULL, 'fledgling company / fledgling democracy / fledgling industry', '[{"en":"The fledgling startup attracted venture capital funding in its first year.","zh-TW":"這家新興創業公司在第一年吸引了風險投資資金。"},{"en":"The country''s fledgling democracy faced significant challenges from entrenched interests.","zh-TW":"該國新興民主政體面臨根深蒂固利益集團的重大挑戰。"}]', NULL, NULL, 3, 2829, NULL),
(2830, 'fleet management', '/''fliːt ˌmænɪdʒmənt/', 'noun', '{"zh-TW":["車隊管理；機隊管理"],"en":["the management of a company''s vehicles including maintenance, tracking, and utilization"]}', NULL, 'improve fleet management / fleet management system / fleet management software', '[{"en":"The company reduced fuel costs by implementing GPS-based fleet management.","zh-TW":"公司通過實施基於GPS的車隊管理降低了燃油成本。"},{"en":"Effective fleet management reduces downtime and extends the lifespan of vehicles.","zh-TW":"有效的車隊管理可以減少停機時間並延長車輛的使用壽命。"}]', NULL, NULL, 5, 2830, NULL),
(2831, 'fleet operator', '/''fliːt ˌɒpərətor/', 'noun', '{"zh-TW":["車隊運營商；機隊運營者"],"en":["a company or individual that owns and operates a fleet of vehicles"]}', NULL, 'large fleet operator / fleet operator requirements / fleet operator compliance', '[{"en":"The fleet operator maintained over three hundred delivery vehicles across the country.","zh-TW":"這個車隊運營商在全國維護了超過三百輛送貨車輛。"},{"en":"Fleet operators must comply with safety and emissions regulations.","zh-TW":"車隊運營商必須遵守安全和排放法規。"}]', NULL, NULL, 5, 2831, NULL),
(2832, 'flexibility', 'ˌflɛksɪˈbɪlɪti', 'noun', '{"zh-TW":["靈活性；彈性","適應性"],"en":["the ability to adapt","being easily changed"]}', NULL, 'flexibility in scheduling/workplace flexibility', '[{"en":"We value flexibility in working arrangements.","zh-TW":"我們重視工作安排的靈活性。"}]', '{"adjective":"flexible","adverb":"flexibly"}', NULL, 4, 2832, NULL),
(2833, 'flexibility training', '/''fleksɪˌbɪlɪti ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["柔韌性訓練；伸展訓練"],"en":["exercise that improves the range of motion of muscles and joints"]}', NULL, 'add flexibility training / flexibility training routine / benefit of flexibility training', '[{"en":"Flexibility training reduces the risk of injury and improves overall athletic performance.","zh-TW":"柔韌性訓練降低了受傷風險並改善了整體運動表現。"},{"en":"She incorporated daily flexibility training to improve her gymnastics routine.","zh-TW":"她加入了每日柔韌性訓練，以改善她的體操套路。"}]', '{"adjective":"flexible","noun2":"flexibility"}', NULL, 5, 2833, NULL),
(2834, 'flexible', '/ˈfleksəbəl/', 'adjective', '{"zh-TW":["靈活的；彈性的","靈活的；有彈性的"],"en":["able to change or be changed easily","capable of bending easily","willing to change or compromise"]}', '{"root":{"text":"flex","meaning":"bend (彎曲)"},"suffix":{"text":"-ible","meaning":"able to (能夠)"},"logic":"能夠彎曲的，即「靈活的」。"}', 'flexible schedule/hours; flexible schedule / flexible approach', '[{"en":"We offer flexible working hours.","zh-TW":"我們提供彈性工作時間。"},{"en":"The policy needs to be more flexible.","zh-TW":"政策需要更加靈活。"},{"en":"We need a more flexible approach.","zh-TW":"我們需要更靈活的做法。"},{"en":"The company offers flexible working hours.","zh-TW":"公司提供彈性工作時間。"}]', '{"noun":"flexibility","adjective":"flexible","adverb":"flexibly"}', NULL, 3, 2834, 364),
(2835, 'flexible hours', '/ˈflɛksɪbəl ˈaʊərz/', 'noun', '{"zh-TW":["彈性工作時間"],"en":["a work arrangement with variable start and end times"]}', NULL, 'offer flexible hours / flexible hours policy', '[{"en":"The company introduced flexible hours to improve work-life balance.","zh-TW":"公司引入了彈性工作時間以改善工作生活平衡。"},{"en":"Flexible hours allow employees to avoid rush-hour commutes.","zh-TW":"彈性工作時間允許員工避開尖峰時間通勤。"}]', NULL, NULL, 5, 2835, NULL),
(2836, 'flexible workforce', '/ˈfleksɪbəl ˈwɜːrkfɔːrs/', 'noun', '{"zh-TW":["靈活勞動力"],"en":["a workforce that can be scaled up or down based on business needs"]}', NULL, 'maintain a flexible workforce / build a flexible workforce', '[{"en":"A flexible workforce allows the company to respond to seasonal demand.","zh-TW":"靈活勞動力使公司能夠應對季節性需求。"},{"en":"Contract workers contribute to a more flexible workforce.","zh-TW":"合約工人為更靈活的勞動力做出了貢獻。"}]', NULL, NULL, 5, 2836, NULL),
(2837, 'flexible working', '/ˈfleksɪbl ˈwɜːrkɪŋ/', 'noun', '{"zh-TW":["彈性工時；彈性辦公"],"en":["arrangements allowing employees to vary their hours or location"]}', NULL, 'flexible working arrangement / request flexible working / offer flexible working', '[{"en":"Flexible working arrangements improved employee satisfaction.","zh-TW":"彈性工時安排提高了員工滿意度。"},{"en":"She requested flexible working to manage childcare responsibilities.","zh-TW":"她申請彈性工時以管理育兒責任。"}]', '{"adjective":"flexible"}', NULL, 5, 2837, NULL),
(2838, 'flight', '/flaɪt/', 'noun', '{"zh-TW":["飛行；航班"],"en":["a journey made by flying"]}', NULL, 'scheduled flight / charter flight', '[{"en":"Our flight departs at seven in the morning.","zh-TW":"我們的航班早上七點出發。"},{"en":"The flight was smooth with no turbulence.","zh-TW":"航班飛行平穩，沒有亂流。"}]', '{"verb":"fly","adjective":"airborne"}', NULL, 2, 2838, NULL),
(2839, 'flight attendant', '/flaɪt əˈtɛndənt/', 'noun', '{"zh-TW":["空服員；空乘人員"],"en":["a person who serves passengers on a plane"]}', NULL, 'experienced flight attendant / flight attendant training', '[{"en":"The flight attendant helped the passenger with her luggage.","zh-TW":"空服員幫助乘客處理行李。"},{"en":"Flight attendants are trained in emergency procedures.","zh-TW":"空服員接受緊急程序培訓。"}]', NULL, NULL, 5, 2839, NULL),
(2840, 'flight delay', '/''flaɪt dɪˌleɪ/', 'noun', '{"zh-TW":["航班延誤"],"en":["a situation in which a flight departs or arrives later than its scheduled time"]}', NULL, 'experience a flight delay / cause a flight delay / flight delay compensation', '[{"en":"The storm caused a three-hour flight delay that affected hundreds of passengers.","zh-TW":"風暴導致了三小時的航班延誤，影響了數百名乘客。"},{"en":"Passengers are entitled to compensation for significant flight delays under EU regulations.","zh-TW":"根據歐盟法規，乘客有權就重大航班延誤獲得賠償。"}]', '{"verb":"delay","adjective":"delayed"}', NULL, 4, 2840, NULL),
(2841, 'flip chart', '/flɪp tʃɑːrt/', 'noun', '{"zh-TW":["掛圖；翻頁白板"],"en":["a large pad of paper on a stand used for presentations"]}', NULL, 'use a flip chart / flip chart notes', '[{"en":"The trainer used a flip chart to outline the training plan.","zh-TW":"培訓師使用掛圖概述了培訓計劃。"},{"en":"Key points were written on the flip chart for everyone to see.","zh-TW":"關鍵要點被寫在掛圖上，供所有人看到。"}]', NULL, NULL, 4, 2841, NULL),
(2842, 'flipped classroom', '/''flɪpt ˌklɑːsruːm/', 'noun', '{"zh-TW":["翻轉課堂"],"en":["an instructional approach where students review content at home and apply it in class"]}', NULL, 'implement a flipped classroom / benefit of flipped classroom / flipped classroom model', '[{"en":"In a flipped classroom, lectures are watched at home and class time is used for activities.","zh-TW":"在翻轉課堂中，課堂演講在家觀看，課堂時間用於活動。"},{"en":"The flipped classroom model increased student participation and critical thinking.","zh-TW":"翻轉課堂模式增加了學生參與度和批判性思維。"}]', NULL, NULL, 5, 2842, NULL),
(2843, 'float', '/floʊt/', 'verb', '{"zh-TW":["浮動；漂浮"],"en":["to rest on the surface; to allow exchange rate to vary"]}', NULL, 'float on the market', '[{"en":"The company floated on the stock exchange.","zh-TW":"公司在股票交易所上市。"},{"en":"The currency was allowed to float freely.","zh-TW":"貨幣被允許自由浮動。"}]', '{"noun":"flotation","verb":"float","adjective":"floating"}', NULL, 2, 2843, NULL),
(2844, 'floating charge', '/ˈfloʊtɪŋ tʃɑːrdʒ/', 'noun', '{"zh-TW":["浮動押記"],"en":["a security interest over a class of assets that changes from time to time"]}', NULL, 'create a floating charge / floating charge over assets', '[{"en":"The bank holds a floating charge over the company''s inventory and receivables.","zh-TW":"銀行對公司的庫存和應收帳款持有浮動押記。"},{"en":"A floating charge crystallizes on insolvency and becomes a fixed charge.","zh-TW":"浮動押記在破產時固化成為固定押記。"}]', '{"opposite":"fixed charge"}', NULL, 5, 2844, NULL),
(2845, 'floating exchange rate', '/ˈfloʊtɪŋ ɪksˈtʃeɪndʒ reɪt/', 'noun', '{"zh-TW":["浮動匯率"],"en":["an exchange rate determined by market forces rather than government"]}', NULL, 'floating exchange rate system / move to floating exchange rate', '[{"en":"Under a floating exchange rate, the currency adjusts to market conditions.","zh-TW":"在浮動匯率制度下，貨幣根據市場條件調整。"},{"en":"A floating exchange rate can create uncertainty for international traders.","zh-TW":"浮動匯率可能為國際貿易商創造不確定性。"}]', NULL, NULL, 5, 2845, NULL),
(2846, 'floating rate', '/ˈfloʊtɪŋ reɪt/', 'noun', '{"zh-TW":["浮動利率"],"en":["an interest rate that varies with market conditions"]}', NULL, 'floating rate loan / floating rate bond / switch to a floating rate', '[{"en":"The loan carries a floating rate tied to the central bank benchmark.","zh-TW":"貸款採用與中央銀行基準利率掛鉤的浮動利率。"},{"en":"Floating rate bonds protect investors from rising interest rates.","zh-TW":"浮動利率債券保護投資者免受利率上升影響。"}]', '{"opposite":"fixed rate"}', NULL, 5, 2846, NULL),
(2847, 'flood', '/flʌd/', 'noun', '{"zh-TW":["洪水"],"en":["an overflow of water onto normally dry land"]}', '{"root":{"text":"flood","meaning":"flow (流動)"},"logic":"源自古英語 flōd（大水流動）。"}', 'flash flood / flood damage / flood warning', '[{"en":"The flood destroyed hundreds of homes.","zh-TW":"洪水摧毀了數百戶房屋。"},{"en":"Heavy rains caused severe flooding in the area.","zh-TW":"大雨在該地區造成嚴重水災。"}]', '{"verb":"flood","noun":"flooding"}', NULL, 2, 2847, NULL),
(2848, 'floor', '/flɔːr/', 'noun', '{"zh-TW":["地板；樓層"],"en":["the lower surface of a room","a level of a building"]}', NULL, 'ground floor / sales floor', '[{"en":"The office is on the third floor.","zh-TW":"辦公室在三樓。"},{"en":"The sales floor is very spacious.","zh-TW":"銷售樓層很寬敞。"}]', '{"noun":"floor","noun2":"flooring"}', NULL, 2, 2848, NULL),
(2849, 'floor manager', '/flɔːr ˈmænɪdʒər/', 'noun', '{"zh-TW":["樓層管理員；店面主任"],"en":["a person responsible for overseeing a floor in a store"]}', NULL, 'contact the floor manager / experienced floor manager', '[{"en":"Ask the floor manager for assistance with large purchases.","zh-TW":"請聯繫樓層管理員協助大宗採購。"},{"en":"The floor manager resolved the customer complaint quickly.","zh-TW":"樓層管理員迅速解決了顧客投訴。"}]', NULL, NULL, 5, 2849, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2850, 'floor plan', '/''flɔːr plæn/', 'noun', '{"zh-TW":["平面圖；樓層平面"],"en":["a scale diagram of a room or building showing the arrangement of rooms and features"]}', NULL, 'review the floor plan / floor plan layout / open floor plan', '[{"en":"The open floor plan of the apartment made the space feel larger.","zh-TW":"公寓的開放式平面圖使空間感覺更寬敞。"},{"en":"She reviewed the floor plan carefully before signing the contract.","zh-TW":"她在簽署合同前仔細審查了平面圖。"}]', NULL, NULL, 4, 2850, NULL),
(2851, 'floor price', '/flɔːr praɪs/', 'noun', '{"zh-TW":["底價；最低價"],"en":["the minimum price at which a product or security can be sold"]}', NULL, 'set a floor price / floor price protection', '[{"en":"The government set a floor price for agricultural products to protect farmers.","zh-TW":"政府為農產品設定了底價以保護農民。"},{"en":"Auction items start at the floor price established by the seller.","zh-TW":"拍賣物品從賣方設定的底價開始。"}]', '{"opposite":"ceiling price"}', NULL, 4, 2851, NULL),
(2852, 'flotation', '/fləʊˈteɪʃən/', 'noun', '{"zh-TW":["上市；發行股票"],"en":["the process of launching a company''s shares on a stock exchange for the first time"]}', NULL, 'stock flotation / plan a flotation / flotation cost', '[{"en":"The company raised five hundred million dollars through its stock exchange flotation.","zh-TW":"公司通過股票交易所上市籌集了五億美元。"},{"en":"A flotation requires extensive regulatory disclosures and investor roadshows.","zh-TW":"股票上市需要廣泛的監管披露和投資者路演。"}]', '{"verb":"float"}', NULL, 3, 2852, NULL),
(2853, 'flourish', '/ˈflɜːrɪʃ/', 'verb', '{"zh-TW":["繁榮；蓬勃發展"],"en":["to grow or develop successfully"]}', NULL, 'business flourishes', '[{"en":"The business flourished under new management.","zh-TW":"在新管理層下企業蓬勃發展。"},{"en":"Creativity flourishes in a supportive environment.","zh-TW":"創造力在支持性環境中蓬勃發展。"}]', '{"verb":"flourish","adjective":"flourishing"}', NULL, 3, 2853, NULL),
(2854, 'flow', '/floʊ/', 'noun / verb', '{"zh-TW":["流動；流程"],"en":["the movement of something; to move steadily"]}', NULL, 'cash flow / workflow', '[{"en":"The company has positive cash flow.","zh-TW":"公司有正向的現金流。"},{"en":"Information flows between departments.","zh-TW":"資訊在部門間流動。"}]', '{"noun":"flow","verb":"flow"}', NULL, 1, 2854, NULL),
(2855, 'flow-through entity', '/floʊ θruː ˈentɪti/', 'noun', '{"zh-TW":["流通實體；穿透課稅實體"],"en":["a business entity whose income passes through to owners who report it on personal tax returns"]}', NULL, 'operate as a flow-through entity / flow-through entity structure', '[{"en":"Partnerships and LLCs are common examples of flow-through entities.","zh-TW":"合夥企業和有限責任公司是常見的流通實體例子。"},{"en":"A flow-through entity avoids double taxation at the corporate level.","zh-TW":"流通實體避免了在企業層面的雙重課稅。"}]', '{"synonym":"pass-through entity"}', NULL, 5, 2855, NULL),
(2856, 'flower', '/ˈflaʊər/', 'noun', '{"zh-TW":["花"],"en":["the colorful part of a plant"]}', NULL, 'flower arrangement / flower shop', '[{"en":"We ordered flower arrangements for the event.","zh-TW":"我們為活動訂了花藝。"},{"en":"The flower shop is on the corner.","zh-TW":"花店在轉角。"}]', '{"noun":"flower","adjective":"flowery","verb":"flower"}', NULL, 2, 2856, NULL),
(2857, 'flu shot', '/fluː ʃɒt/', 'noun', '{"zh-TW":["流感疫苗注射"],"en":["an injection that protects against influenza"]}', NULL, 'get a flu shot / annual flu shot', '[{"en":"She gets a flu shot every autumn to stay healthy.","zh-TW":"她每年秋天接種流感疫苗以保持健康。"},{"en":"Flu shots are recommended for elderly and high-risk individuals.","zh-TW":"建議老年人和高風險人群接種流感疫苗。"}]', NULL, NULL, 3, 2857, NULL),
(2858, 'fluctuate', '/ˈflʌktʃueɪt/', 'verb', '{"zh-TW":["波動；變動"],"en":["to rise and fall irregularly"]}', NULL, 'fluctuate between/widely', '[{"en":"Prices fluctuate depending on demand.","zh-TW":"價格隨需求波動。"},{"en":"The stock price fluctuated throughout the day.","zh-TW":"股價全天波動。"}]', '{"noun":"fluctuation","verb":"fluctuate"}', NULL, 3, 2858, 874),
(2859, 'fluctuation', '/ˌflʌktʃuˈeɪʃən/', 'noun', '{"zh-TW":["波動；起伏"],"en":["irregular changes in level, amount, or value"]}', NULL, 'price fluctuation / exchange rate fluctuation', '[{"en":"Currency fluctuations affected the cost of imported goods.","zh-TW":"貨幣波動影響了進口商品的成本。"},{"en":"The market experienced significant fluctuations last year.","zh-TW":"市場去年經歷了顯著的波動。"}]', '{"verb":"fluctuate","adjective":"fluctuating"}', NULL, 4, 2859, 787),
(2860, 'fluency', '/''fluːənsi/', 'noun', '{"zh-TW":["流利；流暢"],"en":["the ability to express oneself easily and articulately in a language or skill"]}', NULL, 'achieve fluency / oral fluency / reading fluency', '[{"en":"Achieving fluency in a second language requires years of consistent practice.","zh-TW":"在第二語言中達到流利需要多年持續的練習。"},{"en":"The new software helps learners build reading fluency through adaptive exercises.","zh-TW":"這款新軟件通過自適應練習幫助學習者建立閱讀流利度。"}]', '{"adjective":"fluent","adverb":"fluently"}', NULL, 3, 2860, NULL),
(2861, 'fluent', '/''fluːənt/', 'adjective', '{"zh-TW":["流暢的；流利的"],"en":["able to express oneself easily and articulately in a language or style"]}', NULL, 'fluent speaker / become fluent / fluent in English', '[{"en":"She became fluent in Mandarin after three years of intensive study.","zh-TW":"她在三年的密集學習後能夠流利地說普通話。"},{"en":"Being fluent in two languages opens many career opportunities.","zh-TW":"能流利地使用兩種語言可以開啟許多職業機會。"}]', '{"noun":"fluency","adverb":"fluently"}', NULL, 2, 2861, NULL),
(2862, 'fly', '/flaɪ/', 'verb', '{"zh-TW":["飛；搭飛機"],"en":["to move through the air","to travel by airplane"]}', NULL, 'fly abroad / fly business class', '[{"en":"I fly to Tokyo every month for work.","zh-TW":"我每個月飛東京出差。"},{"en":"Time flies when you are busy.","zh-TW":"忙碌時時間過得很快。"}]', '{"verb":"fly","noun":"flight","noun2":"flyer"}', NULL, 1, 2862, NULL),
(2863, 'focus', '/ˈfoʊkəs/', 'noun / verb', '{"zh-TW":["焦點；專注"],"en":["the center of attention; to concentrate"]}', NULL, 'focus on / main focus', '[{"en":"Our main focus is customer satisfaction.","zh-TW":"我們的主要焦點是客戶滿意度。"},{"en":"We need to focus on core business.","zh-TW":"我們需要專注於核心業務。"}]', '{"noun":"focus","verb":"focus","adjective":"focused"}', NULL, 2, 2863, NULL),
(2864, 'focused', 'ˈfoʊkəst', 'adjective', '{"zh-TW":["專注的；集中的","重點的"],"en":["directing attention to one thing","concentrated"]}', NULL, 'results-focused/customer-focused', '[{"en":"Stay focused on the main objective.","zh-TW":"保持對主要目標的專注。"}]', '{"verb":"focus","noun":"focus","adverb":"with focus"}', NULL, 3, 2864, NULL),
(2865, 'fog', '/fɒɡ/', 'noun', '{"zh-TW":["霧"],"en":["thick cloud of tiny water droplets near the ground"]}', '{"root":{"text":"fog","meaning":"mist (霧)"},"logic":"指地面附近的濃密水滴雲。"}', 'dense fog / fog advisory / foggy morning', '[{"en":"The fog reduced visibility to less than 50 meters.","zh-TW":"霧使能見度降到不足50公尺。"},{"en":"Drive carefully in the fog.","zh-TW":"在霧中小心開車。"}]', '{"adjective":"foggy"}', NULL, 1, 2865, NULL),
(2866, 'folio', '/ˈfəʊliəʊ/', 'noun', '{"zh-TW":["帳單；帳戶明細"],"en":["an itemized bill at a hotel"]}', NULL, 'review your folio / settle the folio', '[{"en":"Please review your folio before checking out.","zh-TW":"退房前請查看您的帳單。"},{"en":"Any incidental charges will appear on your folio.","zh-TW":"任何雜費將顯示在您的帳單上。"}]', NULL, NULL, 2, 2866, NULL),
(2867, 'follow', '/ˈfɑːloʊ/', 'verb', '{"zh-TW":["【主要意義-動詞】跟隨；跟著","【次要意義-動詞】理解；明白（口語）","【次要意義-動詞】從事（職業）；遵循（流程）","【次要意義-動詞】密切關注；追蹤（新聞/情況）"],"en":["[primary] to go behind or after someone","[secondary] to understand or keep track of an explanation","[secondary] to pursue an occupation or practice","[secondary] to pay close attention to events or developments"]}', NULL, 'follow up / follow through / follow suit / as follows / follow the procedure', '[{"en":"Please follow up with the client within 24 hours of the initial inquiry.","zh-TW":"請在初次詢問後24小時內跟進客戶。"},{"en":"I am not sure I follow your point; could you clarify?","zh-TW":"我不確定我是否理解您的觀點，您能澄清一下嗎？"},{"en":"The terms of payment are as follows: 30 percent upfront, 70 percent on delivery.","zh-TW":"付款條款如下：預付30%，交貨時支付70%。"}]', '{"noun":"follow-up, following","adjective":"following"}', 'follow up（跟進）、as follows（如下）、follow through（貫徹執行）均是 TOEIC 商業郵件和合約的必考表達，動詞 follow = 「理解」也是常見口語陷阱。', 2, 2867, NULL),
(2868, 'follow up', '/ˈfɒləʊ ʌp/', 'verb', '{"zh-TW":["跟進；追蹤"],"en":["to check on progress after an initial action"]}', NULL, 'follow up on an inquiry / follow up with a client', '[{"en":"I will follow up with the client after sending the proposal.","zh-TW":"發送提案後我將跟進聯繫客戶。"},{"en":"Please follow up on the pending order by tomorrow.","zh-TW":"請在明天之前跟進待處理的訂單。"}]', '{"noun":"follow-up","adjective":"follow-up"}', NULL, 3, 2868, NULL),
(2869, 'follow-up', '/ˈfɒloʊ ʌp/', 'noun', '{"zh-TW":["跟進；後續行動"],"en":["an action or communication taken after an initial contact or meeting"]}', NULL, 'send a follow-up / follow-up email / follow-up call / follow-up meeting', '[{"en":"She sent a follow-up email after the sales call.","zh-TW":"電話銷售後她發了一封跟進郵件。"},{"en":"All action items require a follow-up at the next meeting.","zh-TW":"所有行動事項都需要在下次會議上跟進。"}]', '{"verb":"follow up","adjective":"follow-up"}', NULL, 3, 2869, NULL),
(2870, 'follow-up action', '/ˈfɒləʊ ʌp ˈækʃən/', 'noun', '{"zh-TW":["後續行動"],"en":["steps taken after a meeting or event to continue progress"]}', NULL, 'assign follow-up action / track follow-up actions', '[{"en":"The manager assigned follow-up actions to each team member.","zh-TW":"經理向每位團隊成員分配了後續行動。"},{"en":"Follow-up actions should be completed within one week.","zh-TW":"後續行動應在一週內完成。"}]', NULL, NULL, 5, 2870, NULL),
(2871, 'follow-up communication', '/ˈfɒloʊ ʌp kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["後續溝通"],"en":["communication sent after an initial interaction to maintain progress or relationships"]}', NULL, 'send follow-up communication / effective follow-up communication', '[{"en":"A follow-up communication after the meeting confirmed next steps.","zh-TW":"會議後的後續溝通確認了後續步驟。"},{"en":"Timely follow-up communication strengthens client relationships.","zh-TW":"及時的後續溝通加強了客戶關係。"}]', NULL, NULL, 5, 2871, NULL),
(2872, 'food', '/fuːd/', 'noun', '{"zh-TW":["食物"],"en":["substances eaten for nutrition"]}', NULL, 'food industry / fast food', '[{"en":"The food industry is highly regulated.","zh-TW":"食品產業受到嚴格監管。"},{"en":"We provide food for the conference.","zh-TW":"我們為會議提供餐點。"}]', '{"noun":"food","noun2":"foodie"}', NULL, 1, 2872, NULL),
(2873, 'food allergy', '/fuːd ˈælərdʒi/', 'noun', '{"zh-TW":["食物過敏"],"en":["an immune response to a specific food"]}', NULL, 'severe food allergy / food allergy warning', '[{"en":"Please notify the staff if you have a food allergy.","zh-TW":"如果您有食物過敏，請通知工作人員。"},{"en":"The kitchen takes food allergies very seriously.","zh-TW":"廚房非常重視食物過敏問題。"}]', '{"adjective":"allergic","noun":"allergen"}', NULL, 4, 2873, NULL),
(2874, 'food intolerance', '/''fuːd ɪnˌtɒlərəns/', 'noun', '{"zh-TW":["食物不耐症；食物耐受不良"],"en":["an adverse reaction to a particular food that does not involve the immune system, unlike an allergy"]}', NULL, 'have food intolerance / test for food intolerance / common food intolerance', '[{"en":"Lactose intolerance is one of the most common forms of food intolerance.","zh-TW":"乳糖不耐症是最常見的食物不耐症之一。"},{"en":"A food diary can help identify a food intolerance by tracking reactions.","zh-TW":"食物日記可以通過追蹤反應幫助識別食物不耐症。"}]', '{"adjective":"intolerant"}', NULL, 5, 2874, NULL),
(2875, 'food labeling', '/''fuːd ˌleɪblɪŋ/', 'noun', '{"zh-TW":["食品標示；食品標籤"],"en":["the information printed on food packaging about its contents, nutrition, and ingredients"]}', NULL, 'read food labeling / food labeling requirement / accurate food labeling', '[{"en":"Food labeling helps consumers make informed choices about what they eat.","zh-TW":"食品標示幫助消費者對他們所吃的食物做出知情選擇。"},{"en":"Regulations require accurate food labeling on all packaged goods.","zh-TW":"法規要求所有包裝食品都有準確的食品標示。"}]', NULL, NULL, 5, 2875, NULL),
(2876, 'food pairing', '/''fuːd ˌpeərɪŋ/', 'noun', '{"zh-TW":["食物搭配；食材搭配"],"en":["the combination of two or more foods that complement each other in flavor or nutrition"]}', NULL, 'classic food pairing / creative food pairing / wine and food pairing', '[{"en":"Wine and food pairing enhances the dining experience by balancing flavors.","zh-TW":"葡萄酒和食物搭配通過平衡風味來增強用餐體驗。"},{"en":"Traditional food pairings like cheese and honey have stood the test of time.","zh-TW":"起司和蜂蜜等傳統食物搭配經受住了時間的考驗。"}]', NULL, NULL, 4, 2876, NULL),
(2877, 'food pyramid', '/''fuːd ˌpɪrəmɪd/', 'noun', '{"zh-TW":["食物金字塔；飲食指南"],"en":["a diagram representing the relative proportions of different food groups recommended for a healthy diet"]}', NULL, 'follow the food pyramid / food pyramid guidelines / traditional food pyramid', '[{"en":"The food pyramid recommends limiting sweets and increasing vegetable consumption.","zh-TW":"食物金字塔建議限制甜食並增加蔬菜攝取量。"},{"en":"Nutritionists updated the food pyramid to reflect new research on healthy eating.","zh-TW":"營養師更新了食物金字塔，以反映有關健康飲食的新研究。"}]', NULL, NULL, 4, 2877, NULL),
(2878, 'food security', '/fuːd sɪˈkjʊərɪti/', 'noun', '{"zh-TW":["糧食安全"],"en":["the state of having reliable access to sufficient and nutritious food"]}', NULL, 'ensure food security / food security crisis / achieve food security', '[{"en":"Climate change poses a major threat to global food security.","zh-TW":"氣候變化對全球糧食安全構成重大威脅。"},{"en":"Improving agricultural productivity is essential to food security.","zh-TW":"提高農業生產力對糧食安全至關重要。"}]', NULL, NULL, 5, 2878, NULL),
(2879, 'food waste', '/fuːd weɪst/', 'noun', '{"zh-TW":["食物浪費；廚餘"],"en":["food discarded or not used"]}', NULL, 'reduce food waste / food waste management', '[{"en":"The restaurant reduced food waste by 30% with better planning.","zh-TW":"餐廳透過更好的規劃將食物浪費減少了30%。"},{"en":"Food waste in landfills produces methane, a potent greenhouse gas.","zh-TW":"掩埋場中的廚餘會產生強效溫室氣體甲烷。"}]', NULL, NULL, 4, 2879, NULL),
(2880, 'foot', '/fʊt/', 'noun', '{"zh-TW":["【主要意義-名詞】腳；英尺（單位）","【次要意義-動詞】支付（帳單）；承擔費用","【次要意義-動詞】（數字）合計；加總"],"en":["[primary - noun] the body part at the bottom of the leg; a unit of length","[secondary - verb] to pay a bill or cost","[secondary - verb] to add up a column of numbers"]}', NULL, 'foot the bill / foot the cost / on foot / under foot', '[{"en":"The company agreed to foot the bill for all relocation expenses.","zh-TW":"公司同意承擔所有搬遷費用。"},{"en":"The client expected the contractor to foot the cost of any repairs.","zh-TW":"客戶期望承包商承擔所有修繕費用。"},{"en":"The sales team visited local branches on foot to meet clients personally.","zh-TW":"銷售團隊步行拜訪當地分支機構，親自會見客戶。"}]', '{"noun":"footage, footprint","verb":"footnote"}', 'foot the bill = 「承擔/支付費用」是 TOEIC 財務和商業協議文章的高頻表達，考生容易誤以為 foot 只有「腳」或「英尺」的意思。', 1, 2880, NULL),
(2881, 'footprint', '/ˈfʊtprɪnt/', 'noun', '{"zh-TW":["足跡；規模"],"en":["the extent of a company operations or presence in a market"]}', NULL, 'expand the footprint / reduce the environmental footprint', '[{"en":"The retailer expanded its footprint to 500 stores across the country.","zh-TW":"零售商將其規模擴展到全國500家門市。"},{"en":"The company worked to reduce its carbon footprint by 30%.","zh-TW":"公司致力於將其碳足跡減少30%。"}]', NULL, NULL, 3, 2881, NULL),
(2882, 'forbearance', '/fɔːrˈbeərəns/', 'noun', '{"zh-TW":["寬容；克制；延期還款"],"en":["patient restraint; the act of refraining from enforcing a right"]}', NULL, 'act with forbearance / mortgage forbearance / show forbearance', '[{"en":"The lender offered mortgage forbearance to borrowers affected by the economic downturn.","zh-TW":"貸方向受經濟衰退影響的借款人提供抵押貸款延期還款。"},{"en":"Forbearance in international disputes can prevent escalation to armed conflict.","zh-TW":"在國際爭端中保持克制可以防止升級為武裝衝突。"}]', '{"verb":"forbear","adjective":"forbearing"}', NULL, 4, 2882, NULL),
(2883, 'forbid', '/fərˈbɪd/', 'verb', '{"zh-TW":["禁止"],"en":["to order someone not to do something"]}', NULL, 'strictly forbidden', '[{"en":"Smoking is forbidden in this building.","zh-TW":"這棟建築內禁止吸菸。"},{"en":"Company policy forbids personal use of equipment.","zh-TW":"公司政策禁止私人使用設備。"}]', '{"verb":"forbid","adjective":"forbidden"}', NULL, 2, 2883, NULL),
(2884, 'force', '/fɔːrs/', 'noun / verb', '{"zh-TW":["力量；迫使"],"en":["strength or power; to make someone do something"]}', NULL, 'by force / in force', '[{"en":"The new regulations are now in force.","zh-TW":"新法規現已生效。"},{"en":"Budget cuts forced the company to downsize.","zh-TW":"預算削減迫使公司裁員。"}]', '{"noun":"force","verb":"force","adjective":"forceful"}', NULL, 2, 2884, NULL),
(2885, 'force majeure', '/ˌfɔːrs mæˈʒɜːr/', 'noun', '{"zh-TW":["不可抗力"],"en":["unforeseeable circumstances preventing a party from fulfilling a contract"]}', NULL, 'invoke force majeure / force majeure clause / force majeure event', '[{"en":"The pandemic was declared a force majeure event by the court.","zh-TW":"法院宣布疫情為不可抗力事件。"},{"en":"The force majeure clause exempted the supplier from penalty.","zh-TW":"不可抗力條款免除了供應商的罰款。"}]', NULL, NULL, 5, 2885, NULL),
(2886, 'force of habit', '/fɔːrs əv ˈhæbɪt/', 'noun', '{"zh-TW":["習慣的力量；慣性"],"en":["behavior that persists because it has been done repeatedly"]}', NULL, 'overcome force of habit / change by force of habit', '[{"en":"Process changes often fail due to the force of habit.","zh-TW":"流程變革往往因習慣的力量而失敗。"},{"en":"Employees returned to old methods by force of habit after training.","zh-TW":"員工在培訓後出於習慣慣性回到了舊方法。"}]', NULL, NULL, 5, 2886, NULL),
(2887, 'forecast', '/ˈfɔːrkæst/', 'noun / verb', '{"zh-TW":["預測；預報","預報；預測"],"en":["a prediction about future events","a prediction of future events, especially weather"]}', '{"prefix":{"text":"fore-","meaning":"before (預先)"},"root":{"text":"cast","meaning":"throw/plan (投/計劃)"},"logic":"預先計劃推測，即「預報」。"}', 'sales/weather forecast; weather forecast / sales forecast', '[{"en":"The sales forecast looks promising.","zh-TW":"銷售預測看起來很樂觀。"},{"en":"Analysts forecast steady growth next year.","zh-TW":"分析師預測明年穩定增長。"},{"en":"The forecast says it will rain tomorrow.","zh-TW":"天氣預報說明天會下雨。"},{"en":"The economic forecast looks positive.","zh-TW":"經濟預測看起來樂觀。"}]', '{"noun":"forecast","verb":"forecast"}', NULL, 3, 2887, 125),
(2888, 'forecast accuracy', '/ˈfɔːrkæst ˈækjərəsi/', 'noun', '{"zh-TW":["預測準確度"],"en":["the degree to which a financial or demand forecast matches actual results"]}', NULL, 'improve forecast accuracy / measure forecast accuracy', '[{"en":"High forecast accuracy reduces inventory and cash flow problems.","zh-TW":"高預測準確度降低了庫存和現金流問題。"},{"en":"Machine learning improved the company''s sales forecast accuracy significantly.","zh-TW":"機器學習顯著提高了公司的銷售預測準確度。"}]', NULL, NULL, 5, 2888, NULL),
(2889, 'forecast model', '/ˈfɔːrkæst ˈmɒdəl/', 'noun', '{"zh-TW":["預測模型"],"en":["a mathematical framework used to estimate future values"]}', NULL, 'build a forecast model / update the forecast model', '[{"en":"The forecast model predicted revenue within 5% of actual.","zh-TW":"預測模型對收入的預測誤差在實際5%以內。"},{"en":"Machine learning improved the company forecast model significantly.","zh-TW":"機器學習顯著改善了公司的預測模型。"}]', NULL, NULL, 5, 2889, NULL),
(2890, 'foreclosure', '/fɔːrˈkloʊʒər/', 'noun', '{"zh-TW":["法拍；喪失抵押品贖回權"],"en":["the legal process by which a lender seizes property due to mortgage default"]}', NULL, 'face foreclosure / foreclosure process / prevent foreclosure', '[{"en":"The family faced foreclosure after missing six mortgage payments.","zh-TW":"這個家庭在錯過六次按揭還款後面臨法拍。"},{"en":"Foreclosure proceedings were halted after the owners found a buyer.","zh-TW":"業主找到買家後，法拍程序被中止。"}]', '{"verb":"foreclose"}', NULL, 4, 2890, NULL),
(2891, 'foreclosure sale', '/fɔːrˈkloʊʒər seɪl/', 'noun', '{"zh-TW":["法拍屋出售"],"en":["selling a property seized by a lender after mortgage default"]}', NULL, 'purchase through foreclosure sale / attend a foreclosure sale', '[{"en":"Investors bought properties cheaply at foreclosure sales.","zh-TW":"投資者在法拍屋出售中以低價購買了房產。"},{"en":"A foreclosure sale recovered partial payment for the creditor.","zh-TW":"法拍屋出售為債權人回收了部分款項。"}]', NULL, NULL, 5, 2891, NULL),
(2892, 'foreign', '/ˈfɔːrən/', 'adjective', '{"zh-TW":["外國的；外來的"],"en":["of or from another country"]}', NULL, 'foreign investment/exchange', '[{"en":"Foreign investment has increased.","zh-TW":"外國投資已增加。"},{"en":"She has extensive foreign experience.","zh-TW":"她有豐富的海外經驗。"}]', '{"noun":"foreigner","adjective":"foreign"}', NULL, 3, 2892, NULL),
(2893, 'foreign direct investment', '/ˈfɒrɪn dɪˈrekt ɪnˈvestmənt/', 'noun', '{"zh-TW":["外國直接投資"],"en":["investment made by a company into a business in another country"]}', NULL, 'attract foreign direct investment / FDI incentives', '[{"en":"The government introduced incentives to attract foreign direct investment.","zh-TW":"政府推出激勵措施以吸引外國直接投資。"},{"en":"Foreign direct investment boosted employment in the manufacturing sector.","zh-TW":"外國直接投資促進了製造業的就業。"}]', '{"abbreviation":"FDI"}', NULL, 5, 2893, NULL),
(2894, 'foreign exchange', '/ˈfɒrən ɪksˈtʃeɪndʒ/', 'noun', '{"zh-TW":["外匯；外幣兌換"],"en":["the exchange of one currency for another in global markets"]}', NULL, 'foreign exchange rate / foreign exchange risk / foreign exchange market', '[{"en":"Foreign exchange risk was hedged through forward contracts.","zh-TW":"外匯風險通過遠期合約進行對沖。"},{"en":"The company reported a foreign exchange loss due to the weak dollar.","zh-TW":"由於美元疲軟，公司報告了外匯損失。"}]', '{"abbreviation":"FX","alternative":"forex"}', NULL, 5, 2894, NULL),
(2895, 'forensic', '/fəˈrensɪk/', 'adjective', '{"zh-TW":["法醫的；法庭的；用於偵查的"],"en":["relating to the use of scientific methods in legal investigations"]}', NULL, 'forensic evidence / forensic accounting / forensic analysis', '[{"en":"Forensic accounting uncovers financial fraud through systematic examination of records.","zh-TW":"法庭會計通過對記錄的系統審查揭露金融欺詐。"},{"en":"The crime scene yielded important forensic evidence linking the suspect to the crime.","zh-TW":"犯罪現場提供了將嫌疑人與犯罪聯繫起來的重要法醫證據。"}]', '{"adverb":"forensically","noun":"forensics"}', NULL, 3, 2895, NULL),
(2896, 'forensic audit', '/fəˈrensɪk ˈɔːdɪt/', 'noun', '{"zh-TW":["法庭審計；法證審計"],"en":["a detailed examination of financial records used as evidence in a legal case"]}', NULL, 'conduct a forensic audit / forensic audit findings / commission a forensic audit', '[{"en":"A forensic audit of the company''s accounts uncovered years of systematic fraud.","zh-TW":"對公司賬目的法證審計揭露了多年的系統性欺詐。"},{"en":"The court ordered a forensic audit to trace the movement of missing funds.","zh-TW":"法院命令進行法證審計，以追蹤失蹤資金的去向。"}]', NULL, NULL, 5, 2896, NULL),
(2897, 'forest', '/ˈfɒrɪst/', 'noun', '{"zh-TW":["森林"],"en":["a large area covered with trees"]}', NULL, 'forest management / rainforest', '[{"en":"Forest management is key to sustainability.","zh-TW":"森林管理是永續發展的關鍵。"},{"en":"The company pledged to protect the rainforest.","zh-TW":"公司承諾保護雨林。"}]', '{"noun":"forest","noun2":"forestry","noun3":"deforestation"}', NULL, 2, 2897, NULL),
(2898, 'forfeiture', '/ˈfɔːrfɪtʃər/', 'noun', '{"zh-TW":["沒收；喪失"],"en":["the loss of property or a right as a penalty for a crime or breach of contract"]}', NULL, 'asset forfeiture / bond forfeiture / civil forfeiture', '[{"en":"Asset forfeiture laws allow police to seize property connected to criminal activity.","zh-TW":"資產沒收法律允許警察沒收與犯罪活動相關的財產。"},{"en":"Breach of the non-compete clause resulted in forfeiture of the employee''s bonus.","zh-TW":"違反非競爭條款導致員工獎金被沒收。"}]', '{"verb":"forfeit","adjective":"forfeited"}', NULL, 4, 2898, NULL),
(2899, 'forget', '/fərˈɡɛt/', 'verb', '{"zh-TW":["忘記"],"en":["to fail to remember"]}', NULL, 'don''t forget / forget about', '[{"en":"Don''t forget to send the report.","zh-TW":"別忘了寄報告。"},{"en":"I forgot about the deadline.","zh-TW":"我忘了截止日期。"}]', '{"verb":"forget","adjective":"forgetful","adjective2":"unforgettable"}', NULL, 2, 2899, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2900, 'forklift', '/''fɔːrklɪft/', 'noun', '{"zh-TW":["叉車；堆高機"],"en":["a vehicle with a forked device at the front used for lifting and transporting heavy loads"]}', NULL, 'operate a forklift / forklift certification / warehouse forklift', '[{"en":"All warehouse staff must hold a forklift certification before operating one.","zh-TW":"所有倉庫工作人員在操作叉車前必須持有叉車認證。"},{"en":"The forklift moved the heavy crates from the truck to the storage area.","zh-TW":"叉車將沉重的板條箱從卡車移到儲存區。"}]', NULL, NULL, 3, 2900, NULL),
(2901, 'form', '/fɔːrm/', 'noun / verb', '{"zh-TW":["形式；形成"],"en":["a type or kind; to create or establish"]}', NULL, 'application form / form a team', '[{"en":"Please complete the application form.","zh-TW":"請填寫申請表。"},{"en":"A committee was formed to review the policy.","zh-TW":"成立了一個委員會來審查政策。"}]', '{"noun":"form/formation","verb":"form","adjective":"formal"}', NULL, 1, 2901, NULL),
(2902, 'form of payment', '/fɔːrm əv ˈpeɪmənt/', 'noun', '{"zh-TW":["付款方式"],"en":["the method used to make a financial payment, such as cash, card, or transfer"]}', NULL, 'specify the form of payment / acceptable form of payment', '[{"en":"The invoice specifies wire transfer as the required form of payment.","zh-TW":"發票規定電匯為要求的付款方式。"},{"en":"Customers can choose their preferred form of payment at checkout.","zh-TW":"客戶可以在結帳時選擇其首選的付款方式。"}]', NULL, NULL, 5, 2902, NULL),
(2903, 'formal', '/ˈfɔːrməl/', 'adjective', '{"zh-TW":["正式的"],"en":["following established rules or conventions"]}', NULL, 'formal agreement/meeting', '[{"en":"A formal complaint was submitted.","zh-TW":"提交了一份正式投訴。"},{"en":"Dress code is formal for the event.","zh-TW":"活動的著裝要求是正式的。"}]', '{"noun":"formality","adjective":"formal","adverb":"formally"}', NULL, 2, 2903, NULL),
(2904, 'formal proposal', '/ˈfɔːrməl prəˈpoʊzəl/', 'noun', '{"zh-TW":["正式提案"],"en":["a written document presenting a detailed plan for consideration"]}', NULL, 'submit a formal proposal / prepare a formal proposal', '[{"en":"Please submit a formal proposal outlining costs and timelines.","zh-TW":"請提交概述成本和時間表的正式提案。"},{"en":"The formal proposal was reviewed by the procurement committee.","zh-TW":"正式提案由採購委員會審查了。"}]', NULL, NULL, 5, 2904, NULL),
(2905, 'formality', '/''fɔːrˈmæləti/', 'noun', '{"zh-TW":["正式；正式行為"],"en":["the practice of strictly following rules and conventions; a formal act or procedure"]}', NULL, 'social formality / business formality / observe formality', '[{"en":"In some cultures, maintaining formality in business interactions is very important.","zh-TW":"在某些文化中，在商業互動中保持正式是非常重要的。"},{"en":"She dispensed with the usual formality and addressed her clients by first name.","zh-TW":"她省去了通常的正式禮節，直呼客戶的名字。"}]', '{"adjective":"formal","adverb":"formally"}', NULL, 3, 2905, NULL),
(2906, 'formalize', '/ˈfɔːrməlaɪz/', 'verb', '{"zh-TW":["正式化；使成為正式"],"en":["to give something an official or formal status"]}', NULL, 'formalize an agreement / formalize a process / formalize procedures', '[{"en":"The partnership was formalized with a signed memorandum.","zh-TW":"合作關係通過簽署的備忘錄正式化了。"},{"en":"The company formalized its remote work policy after the pandemic.","zh-TW":"公司在疫情後正式確立了遠端工作政策。"}]', '{"noun":"formalization","adjective":"formalized"}', NULL, 3, 2906, 875),
(2907, 'format', '/ˈfɔːrmæt/', 'noun / verb', '{"zh-TW":["格式；格式化"],"en":["the arrangement of data; to arrange"]}', NULL, 'file/report format', '[{"en":"Please submit the report in PDF format.","zh-TW":"請以PDF格式提交報告。"},{"en":"The document needs to be formatted properly.","zh-TW":"文件需要正確格式化。"}]', '{"noun":"format/formatting","verb":"format"}', NULL, 2, 2907, NULL),
(2908, 'formative', '/ˈfɔːrmətɪv/', 'adjective', '{"zh-TW":["形成性的；早期的"],"en":["having a strong influence on the development of something"]}', NULL, 'formative assessment / formative years / formative experience', '[{"en":"Formative assessment helps teachers adjust instruction in real time.","zh-TW":"形成性評估幫助教師即時調整教學。"},{"en":"Her formative years were spent in a multicultural environment.","zh-TW":"她的成長歲月在多元文化環境中度過。"}]', NULL, NULL, 3, 2908, NULL),
(2909, 'formative assessment', '/''fɔːrmətɪv əˌsesmənt/', 'noun', '{"zh-TW":["形成性評量；過程評量"],"en":["ongoing assessment aimed at monitoring student learning and providing feedback during instruction"]}', NULL, 'use formative assessment / formative assessment strategy / benefit of formative assessment', '[{"en":"Formative assessment helps teachers adjust their teaching to better meet student needs.","zh-TW":"形成性評量幫助教師調整教學以更好地滿足學生需求。"},{"en":"Quizzes and class participation are common forms of formative assessment.","zh-TW":"測驗和課堂參與是常見的形成性評量形式。"}]', NULL, NULL, 5, 2909, NULL),
(2910, 'former', '/ˈfɔːrmər/', 'adjective', '{"zh-TW":["前任的；從前的"],"en":["having previously been"]}', NULL, 'former president/employee', '[{"en":"The former CEO founded a new startup.","zh-TW":"前任執行長創辦了一家新公司。"},{"en":"She is a former employee of ours.","zh-TW":"她是我們的前員工。"}]', '{"adjective":"former","adverb":"formerly"}', NULL, 2, 2910, NULL),
(2911, 'formidable', '/''fɔːrmɪdəbəl/', 'adjective', '{"zh-TW":["令人敬畏的；可怕的；難以對付的"],"en":["inspiring fear or respect through being impressively large, powerful, intense, or capable"]}', NULL, 'formidable challenge / formidable opponent / formidable task', '[{"en":"Entering the global market is a formidable challenge for any startup.","zh-TW":"進入全球市場對任何新創公司來說都是一個令人敬畏的挑戰。"},{"en":"She has built a formidable reputation as a tough negotiator.","zh-TW":"她建立了作為強硬談判者的令人敬畏的聲譽。"}]', '{"adverb":"formidably"}', NULL, 4, 2911, NULL),
(2912, 'formula', '/ˈfɔːrmjələ/', 'noun', '{"zh-TW":["公式；配方"],"en":["a mathematical rule; a method for achieving something"]}', NULL, 'winning formula', '[{"en":"There is no simple formula for success.","zh-TW":"成功沒有簡單的公式。"},{"en":"The formula calculates annual revenue.","zh-TW":"該公式計算年收入。"}]', '{"noun":"formula/formulation","verb":"formulate"}', NULL, 3, 2912, NULL),
(2913, 'formulate', 'ˈfɔːrmjʊleɪt', 'verb', '{"zh-TW":["制定；擬定","構想"],"en":["to create or develop a plan","to express precisely"]}', NULL, 'formulate a strategy/formulate a response', '[{"en":"We need to formulate a clear policy.","zh-TW":"我們需要制定明確的政策。"}]', '{"noun":"formulation","adjective":"formulated"}', NULL, 3, 2913, 685),
(2914, 'forthright', '/''fɔːrθˌraɪt/', 'adjective', '{"zh-TW":["坦誠的；直率的"],"en":["direct and outspoken; frank and candid"]}', NULL, 'forthright feedback / forthright manner / be forthright', '[{"en":"She appreciated his forthright feedback because it helped her improve quickly.","zh-TW":"她欣賞他坦率的反饋，因為它幫助她快速進步。"},{"en":"A forthright leader communicates goals and concerns clearly without ambiguity.","zh-TW":"直率的領導者能夠清晰地溝通目標和關切，沒有模糊性。"}]', '{"adverb":"forthrightly","noun":"forthrightness"}', NULL, 4, 2914, NULL),
(2915, 'fortified food', '/''fɔːrtɪfaɪd fuːd/', 'noun', '{"zh-TW":["強化食品；添加營養素的食品"],"en":["food that has had nutrients added to it that do not naturally occur in it"]}', NULL, 'consume fortified food / fortified cereal / fortified milk', '[{"en":"Fortified milk contains added vitamin D to support bone health.","zh-TW":"強化牛奶含有額外添加的維生素D，有助於骨骼健康。"},{"en":"Many breakfast cereals are fortified foods with added vitamins and minerals.","zh-TW":"許多早餐穀物是添加了維生素和礦物質的強化食品。"}]', NULL, NULL, 5, 2915, NULL),
(2916, 'fortify', '/''fɔːrtɪfaɪ/', 'verb', '{"zh-TW":["強化；添加營養素"],"en":["to add vitamins or minerals to food in order to make it more nutritious"]}', NULL, 'fortify with vitamins / fortify milk / fortify cereal', '[{"en":"Orange juice is often fortified with calcium and vitamin D.","zh-TW":"橙汁通常會添加鈣和維生素D以強化其營養。"},{"en":"Food manufacturers fortify cereals with iron to help address nutritional deficiencies.","zh-TW":"食品製造商在穀物中添加鐵質以幫助解決營養缺乏問題。"}]', '{"adjective":"fortified","noun":"fortification"}', NULL, 3, 2916, NULL),
(2917, 'fortress', '/''fɔːtrɪs/', 'noun', '{"zh-TW":["要塞；堡壘"],"en":["a military stronghold, especially a strongly fortified town"]}', NULL, 'ancient fortress / visit a fortress / coastal fortress', '[{"en":"The fortress was built on a hilltop to defend the city from invasion.","zh-TW":"這座要塞建在山頂上，保護城市免受入侵。"},{"en":"The medieval fortress now serves as a popular tourist attraction.","zh-TW":"這座中世紀堡壘現在是熱門的旅遊景點。"}]', NULL, NULL, 3, 2917, NULL),
(2918, 'fortuitous', '/''fɔːrˌtjuːɪtəs/', 'adjective', '{"zh-TW":["偶然的；幸運的"],"en":["happening by a fortunate chance; occurring by luck rather than by design"]}', NULL, 'fortuitous meeting / fortuitous discovery / fortuitous event', '[{"en":"Their fortuitous meeting at a conference led to a successful business partnership.","zh-TW":"他們在會議上的偶然相遇帶來了成功的商業合作。"},{"en":"The company''s success was partly the result of fortuitous timing in a rising market.","zh-TW":"公司的成功部分是在上升市場中偶然時機的結果。"}]', '{"adverb":"fortuitously","noun":"fortuity"}', NULL, 4, 2918, NULL),
(2919, 'fortune', '/ˈfɔːrtʃən/', 'noun', '{"zh-TW":["財富；命運"],"en":["a large amount of money; luck"]}', NULL, 'make a fortune', '[{"en":"He made a fortune in real estate.","zh-TW":"他在房地產賺了大錢。"},{"en":"Fortune 500 companies attract top talent.","zh-TW":"財富500強公司吸引頂尖人才。"}]', '{"noun":"fortune","adjective":"fortunate","adverb":"fortunately"}', NULL, 3, 2919, NULL),
(2920, 'forum selection', '/ˈfɔːrəm sɪˈlekʃən/', 'noun', '{"zh-TW":["管轄法院選擇"],"en":["a contract clause specifying which court will resolve disputes"]}', NULL, 'forum selection clause / forum selection agreement / enforce forum selection', '[{"en":"The contract included a forum selection clause designating Hong Kong courts.","zh-TW":"合約包含指定香港法院的管轄法院選擇條款。"},{"en":"Courts generally enforce valid forum selection clauses in commercial contracts.","zh-TW":"法院通常執行商業合約中有效的管轄法院選擇條款。"}]', NULL, NULL, 5, 2920, NULL),
(2921, 'forward', '/ˈfɔːrwərd/', 'verb', '{"zh-TW":["轉發；轉寄"],"en":["to send or pass on to another person"]}', NULL, 'forward an email / forward the proposal', '[{"en":"Please forward the attached report to your manager.","zh-TW":"請將附件報告轉發給您的經理。"},{"en":"I''ve forwarded your inquiry to the relevant department.","zh-TW":"我已將您的查詢轉發給相關部門。"}]', '{"adjective":"forward","adverb":"forward"}', NULL, 3, 2921, 126),
(2922, 'forward contract', '/ˈfɔːrwərd ˈkɒntrækt/', 'noun', '{"zh-TW":["遠期合約"],"en":["an agreement to buy or sell an asset at a future date at an agreed price"]}', NULL, 'enter a forward contract / forward contract price / foreign exchange forward', '[{"en":"They used a forward contract to lock in the exchange rate.","zh-TW":"他們使用遠期合約鎖定匯率。"},{"en":"A forward contract eliminates price uncertainty for both parties.","zh-TW":"遠期合約消除了雙方的價格不確定性。"}]', NULL, NULL, 5, 2922, NULL),
(2923, 'forward guidance', '/ˈfɔːrwərd ˈɡaɪdəns/', 'noun', '{"zh-TW":["前瞻指引"],"en":["a central bank''s communication about its expected future monetary policy actions"]}', NULL, 'provide forward guidance / central bank forward guidance', '[{"en":"The central bank''s forward guidance indicated rates would remain low for two years.","zh-TW":"中央銀行的前瞻指引表明利率將在兩年內保持低位。"},{"en":"Forward guidance reduces market uncertainty and stabilizes investor expectations.","zh-TW":"前瞻指引減少了市場不確定性並穩定了投資者預期。"}]', NULL, NULL, 5, 2923, NULL),
(2924, 'forward integration', '/ˈfɔːrwərd ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["向前整合；向下游整合"],"en":["a strategy where a company expands to control distribution or retail activities"]}', NULL, 'pursue forward integration / forward integration strategy', '[{"en":"The manufacturer opened retail stores as part of its forward integration strategy.","zh-TW":"製造商作為其向前整合策略的一部分開設了零售店。"},{"en":"Forward integration allows producers to capture more value closer to the end consumer.","zh-TW":"向前整合允許生產者在更接近最終消費者的地方獲取更多價值。"}]', '{"opposite":"backward integration"}', NULL, 5, 2924, NULL),
(2925, 'forward-looking', 'ˈfɔːrwərd ˈlʊkɪŋ', 'adjective', '{"zh-TW":["前瞻性的；有遠見的","積極進取的"],"en":["planning for the future","optimistic and progressive"]}', NULL, 'forward-looking company/forward-looking strategy', '[{"en":"This is a forward-looking initiative.","zh-TW":"這是一個具有前瞻性的計畫。"}]', NULL, NULL, 5, 2925, NULL),
(2926, 'forwarder', '/ˈfɔːrwərdər/', 'noun', '{"zh-TW":["貨運代理商；承攬運送業者"],"en":["a company that organizes shipments on behalf of importers or exporters"]}', NULL, 'freight forwarder / appoint a forwarder / forwarder services', '[{"en":"They hired a freight forwarder to handle the customs documentation.","zh-TW":"他們聘請了貨運代理商處理海關文件。"},{"en":"The forwarder coordinated the entire shipment from factory to port.","zh-TW":"貨運代理商協調了從工廠到港口的整個運輸過程。"}]', '{"full":"freight forwarder"}', NULL, 3, 2926, NULL),
(2927, 'fossil fuel', '/ˈfɒsəl fjuːəl/', 'noun', '{"zh-TW":["化石燃料"],"en":["natural fuels such as coal, oil, and natural gas"]}', NULL, 'burn fossil fuels / fossil fuel dependency', '[{"en":"The world is trying to reduce its dependence on fossil fuels.","zh-TW":"世界各地都在努力減少對化石燃料的依賴。"},{"en":"Burning fossil fuels releases greenhouse gases into the atmosphere.","zh-TW":"燃燒化石燃料會向大氣層釋放溫室氣體。"}]', NULL, NULL, 4, 2927, NULL),
(2928, 'fossil fuel phase-out', '/ˈfɒsəl fjuːəl feɪz aʊt/', 'noun', '{"zh-TW":["化石燃料淘汰"],"en":["the gradual elimination of fossil fuels from energy systems"]}', NULL, 'fossil fuel phase-out timeline / accelerate fossil fuel phase-out / just fossil fuel phase-out', '[{"en":"A rapid fossil fuel phase-out is essential to limiting global warming to 1.5°C.","zh-TW":"快速淘汰化石燃料對於將全球暖化限制在1.5°C至關重要。"},{"en":"The fossil fuel phase-out must be managed to protect energy workers.","zh-TW":"化石燃料淘汰必須妥善管理以保護能源工人。"}]', NULL, NULL, 5, 2928, NULL),
(2929, 'foster', '/ˈfɑːstər/', 'verb', '{"zh-TW":["促進；培養"],"en":["to encourage or promote the development of"]}', NULL, 'foster growth/innovation', '[{"en":"The program fosters entrepreneurship.","zh-TW":"該計畫促進創業精神。"},{"en":"We aim to foster a culture of innovation.","zh-TW":"我們旨在培養創新文化。"}]', '{"verb":"foster"}', NULL, 2, 2929, NULL),
(2930, 'foul', '/''faʊl/', 'noun', '{"zh-TW":["犯規；違規動作"],"en":["an action in a sport that is contrary to the rules"]}', NULL, 'commit a foul / call a foul / technical foul', '[{"en":"The referee called a foul on the player for tripping his opponent.","zh-TW":"裁判因一名球員絆倒對手而判其犯規。"},{"en":"Accumulating too many fouls results in automatic ejection from the game.","zh-TW":"累積過多犯規導致自動被驅逐出比賽。"}]', '{"verb":"foul"}', NULL, 1, 2930, NULL),
(2931, 'found', '/faʊnd/', 'verb', '{"zh-TW":["創立；成立"],"en":["to establish an organization"]}', NULL, 'found a company', '[{"en":"The company was founded in 1985.","zh-TW":"公司成立於1985年。"},{"en":"She founded a successful charity.","zh-TW":"她創立了一個成功的慈善機構。"}]', '{"noun":"founder/foundation","verb":"found"}', NULL, 2, 2931, NULL),
(2932, 'foundation', '/faʊnˈdeɪʃən/', 'noun', '{"zh-TW":["基礎；基金會"],"en":["the basis for something; an organization for charity"]}', NULL, 'lay the foundation', '[{"en":"Education is the foundation of success.","zh-TW":"教育是成功的基礎。"},{"en":"The foundation donated $1 million to research.","zh-TW":"基金會捐贈了100萬美元用於研究。"}]', '{"noun":"foundation","verb":"found"}', NULL, 4, 2932, 127),
(2933, 'fraction', '/ˈfrækʃən/', 'noun', '{"zh-TW":["一小部分；分數"],"en":["a small part of something"]}', NULL, 'a fraction of', '[{"en":"Only a fraction of applicants were accepted.","zh-TW":"只有一小部分申請者被錄取。"},{"en":"It costs a fraction of the original price.","zh-TW":"它只花了原價的一小部分。"}]', '{"noun":"fraction","adjective":"fractional"}', NULL, 3, 2933, NULL),
(2934, 'fragile state', '/ˈfrædʒaɪl steɪt/', 'noun', '{"zh-TW":["脆弱國家"],"en":["a country experiencing severe political instability, conflict, or economic crisis"]}', NULL, 'assist fragile states / fragile state characteristics / fragile state governance', '[{"en":"Humanitarian organizations focus significant resources on fragile states.","zh-TW":"人道主義組織在脆弱國家集中投入大量資源。"},{"en":"Fragile states struggle to provide basic services and security to citizens.","zh-TW":"脆弱國家難以向公民提供基本服務和安全。"}]', NULL, NULL, 5, 2934, NULL),
(2935, 'frame', '/freɪm/', 'noun / verb', '{"zh-TW":["框架；構築"],"en":["a structure; to formulate"]}', NULL, 'time frame / frame a question', '[{"en":"What is the time frame for completion?","zh-TW":"完成的時間框架是什麼？"},{"en":"The question was framed carefully.","zh-TW":"問題被謹慎地構築。"}]', '{"noun":"frame/framework","verb":"frame"}', NULL, 2, 2935, NULL),
(2936, 'frame narrative', '/freɪm ˈnærətɪv/', 'noun', '{"zh-TW":["框架敘事"],"en":["a story within a story structure used as a narrative device"]}', NULL, 'use frame narrative / frame narrative technique / frame narrative structure', '[{"en":"The Canterbury Tales uses a frame narrative to link diverse stories together.","zh-TW":"《坎特伯雷故事集》使用框架敘事將多樣的故事連接在一起。"},{"en":"A frame narrative allows the author to present multiple perspectives.","zh-TW":"框架敘事允許作者呈現多個觀點。"}]', NULL, NULL, 5, 2936, NULL),
(2937, 'framework', '/ˈfreɪmwɜːrk/', 'noun', '{"zh-TW":["框架；架構"],"en":["a basic structure underlying a system"]}', NULL, 'legal/regulatory framework', '[{"en":"We need a clear framework for decision-making.","zh-TW":"我們需要一個明確的決策框架。"},{"en":"The project operates within a legal framework.","zh-TW":"該項目在法律框架內運作。"}]', '{"noun":"framework"}', NULL, 3, 2937, 877),
(2938, 'framework agreement', '/ˈfreɪmwɜːrk əˈɡriːmənt/', 'noun', '{"zh-TW":["框架協議；骨架合約"],"en":["a master agreement setting general terms for future individual contracts"]}', NULL, 'sign a framework agreement / operate under a framework agreement', '[{"en":"A framework agreement was established for all software purchases.","zh-TW":"為所有軟體採購建立了框架協議。"},{"en":"The framework agreement simplified the procurement of recurring services.","zh-TW":"框架協議簡化了定期服務的採購。"}]', NULL, NULL, 5, 2938, NULL),
(2939, 'franchise', '/ˈfræntʃaɪz/', 'noun / verb', '{"zh-TW":["特許經營權；加盟"],"en":["a license to sell products under a brand name"]}', NULL, 'franchise agreement/owner', '[{"en":"He owns a fast-food franchise.","zh-TW":"他擁有一家速食加盟店。"},{"en":"The brand is looking to franchise internationally.","zh-TW":"該品牌正在尋求國際特許經營。"}]', '{"noun":"franchise/franchisee/franchisor","verb":"franchise"}', NULL, 3, 2939, NULL),
(2940, 'franchise agreement', '/ˈfrænʧaɪz əˈɡriːmənt/', 'noun', '{"zh-TW":["特許經營協議"],"en":["a legal contract granting a franchisee the right to use a franchisor''s brand"]}', NULL, 'sign a franchise agreement / franchise agreement terms', '[{"en":"The franchise agreement outlines territory, royalties, and operational standards.","zh-TW":"特許經營協議概述了區域、特許使用費和運營標準。"},{"en":"Violating the franchise agreement may result in termination.","zh-TW":"違反特許經營協議可能導致終止。"}]', NULL, NULL, 5, 2940, NULL),
(2941, 'franchise fee', '/ˈfrænˌtʃaɪz fiː/', 'noun', '{"zh-TW":["特許經營費"],"en":["a fee paid to use a franchise''s brand and business model"]}', NULL, 'pay a franchise fee / franchise fee structure', '[{"en":"The franchise fee covers the right to use the brand and systems.","zh-TW":"特許經營費包括使用品牌和系統的權利。"},{"en":"Prospective franchisees must pay an upfront franchise fee.","zh-TW":"準加盟商必須支付前期特許經營費。"}]', NULL, NULL, 5, 2941, NULL),
(2942, 'franchisee', '/ˌfræntʃaɪˈziː/', 'noun', '{"zh-TW":["加盟商；受許可人"],"en":["a person or company that has purchased the right to operate a franchised business"]}', NULL, 'recruit franchisees / support franchisees', '[{"en":"Each franchisee operates under the franchisor''s brand and standards.","zh-TW":"每個加盟商在特許經營者的品牌和標準下運營。"},{"en":"The franchisor provides training and marketing support to all franchisees.","zh-TW":"特許經營者為所有加盟商提供培訓和行銷支持。"}]', '{"opposite":"franchisor"}', NULL, 4, 2942, NULL),
(2943, 'franchisor', '/ˈfræntʃaɪzər/', 'noun', '{"zh-TW":["特許經營者；授予特許權者"],"en":["a company that grants franchises to others to operate under its brand"]}', NULL, 'become a franchisor / franchisor obligations', '[{"en":"The franchisor is responsible for protecting the brand across all franchise locations.","zh-TW":"特許經營者負責保護所有加盟地點的品牌。"},{"en":"A franchisor earns royalties from franchisees based on sales revenue.","zh-TW":"特許經營者根據銷售收入從加盟商處獲取版稅。"}]', '{"opposite":"franchisee"}', NULL, 4, 2943, NULL),
(2944, 'free', '/friː/', 'adjective / verb', '{"zh-TW":["免費的；自由的"],"en":["without cost; not restricted"]}', NULL, 'free of charge / free up', '[{"en":"The seminar is free of charge.","zh-TW":"研討會免費。"},{"en":"We need to free up some budget.","zh-TW":"我們需要騰出一些預算。"}]', '{"noun":"freedom","verb":"free","adjective":"free","adverb":"freely"}', NULL, 1, 2944, NULL),
(2945, 'free cash flow', '/friː kæʃ floʊ/', 'noun', '{"zh-TW":["自由現金流"],"en":["cash generated after accounting for capital expenditures"]}', NULL, 'generate free cash flow / positive free cash flow / free cash flow yield', '[{"en":"Strong free cash flow enables the company to fund dividends and buybacks.","zh-TW":"強勁的自由現金流使公司能夠資助股利和股票回購。"},{"en":"Investors prize companies that generate consistent free cash flow.","zh-TW":"投資者重視能夠持續產生自由現金流的公司。"}]', '{"abbreviation":"FCF"}', NULL, 5, 2945, NULL),
(2946, 'free rider', '/friː ˈraɪdər/', 'noun', '{"zh-TW":["搭便車者；免費獲益者"],"en":["someone who benefits from a public good or collective action without paying for it"]}', NULL, 'free rider problem / avoid free riders / free rider in economics', '[{"en":"The free rider problem makes it difficult to fund public goods through voluntary contributions.","zh-TW":"搭便車問題使得通過自願捐款來資助公共財變得困難。"},{"en":"Nations that reduce emissions while others do not face a free rider problem in climate policy.","zh-TW":"在其他國家不減排的情況下減少排放的國家面臨氣候政策中的搭便車問題。"}]', NULL, NULL, 4, 2946, NULL),
(2947, 'free rider problem', '/friː ˈraɪdər ˈprɒbləm/', 'noun', '{"zh-TW":["搭便車問題"],"en":["the tendency of individuals to benefit from collective resources without contributing"]}', NULL, 'address the free rider problem / free rider problem in public goods / overcome free rider problem', '[{"en":"The free rider problem makes it difficult to fund public goods like national defense.","zh-TW":"搭便車問題使資助國防等公共物品變得困難。"},{"en":"Membership organizations design incentives to minimize the free rider problem.","zh-TW":"會員組織設計激勵機制以最小化搭便車問題。"}]', NULL, NULL, 5, 2947, NULL),
(2948, 'free trade agreement', '/friː treɪd əˈɡriːmənt/', 'noun', '{"zh-TW":["自由貿易協定"],"en":["a pact between countries to reduce trade barriers"]}', NULL, 'sign a free trade agreement / negotiate a free trade agreement', '[{"en":"The free trade agreement eliminated tariffs on agricultural goods.","zh-TW":"自由貿易協定消除了農產品關稅。"},{"en":"Both countries benefit from the terms of the free trade agreement.","zh-TW":"兩國都受益於自由貿易協定的條款。"}]', '{"abbreviation":"FTA"}', NULL, 5, 2948, NULL),
(2949, 'free-range', '/friː reɪndʒ/', 'adjective', '{"zh-TW":["放養的；自由放牧的"],"en":["allowing animals to roam freely"]}', NULL, 'free-range chicken / free-range eggs', '[{"en":"The restaurant uses free-range chicken in all dishes.","zh-TW":"餐廳在所有菜餚中使用放養雞肉。"},{"en":"Free-range eggs have a richer flavor.","zh-TW":"放養雞蛋風味更豐富。"}]', NULL, NULL, 4, 2949, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2950, 'freehold', '/''friːhəʊld/', 'noun', '{"zh-TW":["完全產權；永久業權"],"en":["permanent ownership of land or property, without time restriction"]}', NULL, 'freehold property / buy freehold / freehold ownership', '[{"en":"They purchased the freehold of the property, giving them full ownership of the land.","zh-TW":"他們購買了房產的永久業權，給予他們對土地的完全所有權。"},{"en":"Freehold properties are generally more expensive than leasehold ones.","zh-TW":"永久業權房產通常比租賃業權房產更昂貴。"}]', NULL, NULL, 3, 2950, NULL),
(2951, 'freemium', '/ˈfriːmiəm/', 'noun', '{"zh-TW":["免費增值模式"],"en":["a pricing model offering basic features free with paid premium upgrades"]}', NULL, 'freemium model / freemium strategy / convert freemium users', '[{"en":"The app uses a freemium model to attract users before upselling.","zh-TW":"該應用程式使用免費增值模式在向上銷售前吸引用戶。"},{"en":"Freemium services must balance free features with paid incentives.","zh-TW":"免費增值服務必須平衡免費功能與付費激勵。"}]', NULL, NULL, 3, 2951, NULL),
(2952, 'freight', '/freɪt/', 'noun', '{"zh-TW":["貨運；貨物"],"en":["goods transported in bulk by truck, train, ship, or aircraft"]}', NULL, 'air freight / sea freight / freight forwarding / freight cost', '[{"en":"Air freight was used for urgent shipments despite the higher cost.","zh-TW":"儘管成本較高，空運還是用於緊急貨物。"},{"en":"Sea freight is slower but much cheaper than air for bulky goods.","zh-TW":"海運比空運慢，但對大批量貨物便宜得多。"}]', '{"verb":"freight","adjective":"freight"}', NULL, 3, 2952, NULL),
(2953, 'freight broker', '/''freɪt ˌbrəʊkər/', 'noun', '{"zh-TW":["貨運經紀人；運輸中介"],"en":["an intermediary who connects shippers with carriers to arrange transportation of goods"]}', NULL, 'hire a freight broker / freight broker network / experienced freight broker', '[{"en":"A freight broker helped them find the most cost-effective carrier for the shipment.","zh-TW":"一位貨運經紀人幫助他們為貨物找到了最具成本效益的承運人。"},{"en":"Freight brokers save shippers time by negotiating rates and managing logistics.","zh-TW":"貨運經紀人通過談判費率和管理物流為托運人節省時間。"}]', NULL, NULL, 5, 2953, NULL),
(2954, 'freight cost', '/freɪt kɒst/', 'noun', '{"zh-TW":["運費；貨運成本"],"en":["the charges incurred for transporting goods from one place to another"]}', NULL, 'calculate freight costs / reduce freight costs', '[{"en":"Freight costs increased after fuel prices rose sharply.","zh-TW":"燃料價格急劇上漲後運費增加了。"},{"en":"Freight costs are included in the landed cost of imported goods.","zh-TW":"運費包含在進口商品的到岸成本中。"}]', '{"synonym":"shipping cost","synonym2":"carriage cost"}', NULL, 4, 2954, NULL),
(2955, 'freight forwarder', '/freɪt ˈfɔːrwɔːrdər/', 'noun', '{"zh-TW":["貨運代理商"],"en":["a company that organizes shipments on behalf of businesses"]}', NULL, 'use a freight forwarder / experienced freight forwarder', '[{"en":"The freight forwarder handled all customs paperwork.","zh-TW":"貨運代理商處理了所有海關文件。"},{"en":"Partnering with a reliable freight forwarder simplifies logistics.","zh-TW":"與可靠的貨運代理商合作簡化了物流。"}]', NULL, NULL, 5, 2955, NULL),
(2956, 'freight insurance', '/''freɪt ɪnˌʃʊərəns/', 'noun', '{"zh-TW":["運費保險；貨運保險"],"en":["insurance coverage for loss or damage to goods being transported"]}', NULL, 'purchase freight insurance / freight insurance claim / international freight insurance', '[{"en":"The company purchased freight insurance to cover all international shipments.","zh-TW":"公司購買了貨運保險以涵蓋所有國際貨物運輸。"},{"en":"Freight insurance is particularly important for high-value or fragile cargo.","zh-TW":"貨運保險對高價值或易碎貨物尤為重要。"}]', NULL, NULL, 5, 2956, NULL),
(2957, 'freight rate', '/''freɪt reɪt/', 'noun', '{"zh-TW":["運費率；貨運費率"],"en":["the price charged for transporting a unit of cargo from one location to another"]}', NULL, 'negotiate freight rate / freight rate increase / competitive freight rate', '[{"en":"The freight rate for shipping containers to Europe has tripled since last year.","zh-TW":"運輸貨櫃到歐洲的貨運費率自去年以來增加了三倍。"},{"en":"Shippers negotiate freight rates with carriers based on volume and contract length.","zh-TW":"托運人根據數量和合同期限與承運人協商貨運費率。"}]', NULL, NULL, 4, 2957, NULL),
(2958, 'freight terminal', '/''freɪt ˌtɜːrmɪnəl/', 'noun', '{"zh-TW":["貨運站；貨物轉運站"],"en":["a facility where freight is loaded, unloaded, and temporarily stored for further distribution"]}', NULL, 'operate a freight terminal / busy freight terminal / freight terminal facilities', '[{"en":"The city''s freight terminal handles over ten thousand containers per day.","zh-TW":"該市的貨運站每天處理超過一萬個貨櫃。"},{"en":"The new freight terminal was built with automated sorting and tracking technology.","zh-TW":"新貨運站建有自動化分揀和追蹤技術。"}]', NULL, NULL, 5, 2958, NULL),
(2959, 'frequent', '/ˈfriːkwənt/', 'adjective', '{"zh-TW":["頻繁的；經常的"],"en":["occurring often"]}', NULL, 'frequent traveler/visitor', '[{"en":"Frequent breaks improve productivity.","zh-TW":"頻繁休息可以提高生產力。"},{"en":"She is a frequent visitor to our office.","zh-TW":"她經常來我們辦公室。"}]', '{"noun":"frequency","adjective":"frequent","adverb":"frequently"}', NULL, 3, 2959, NULL),
(2960, 'frequent flyer', '/ˈfriːkwənt ˈflaɪər/', 'noun', '{"zh-TW":["常旅客；常飛旅客"],"en":["a person who travels by air often, usually in a loyalty program"]}', NULL, 'frequent flyer miles / frequent flyer program', '[{"en":"Frequent flyer miles can be redeemed for free flights.","zh-TW":"常旅客里程可以兌換免費機票。"},{"en":"She is a gold member of the airline''s frequent flyer program.","zh-TW":"她是航空公司常旅客計劃的金卡會員。"}]', NULL, NULL, 5, 2960, NULL),
(2961, 'frequently asked questions', '/ˈfriːkwəntli ɑːskt ˈkwestʃənz/', 'noun', '{"zh-TW":["常見問題"],"en":["a list of common questions and their answers"]}', NULL, 'check the FAQ / update the FAQ / FAQ page', '[{"en":"Check the FAQ page before contacting customer support.","zh-TW":"在聯繫客戶支援之前，請查看常見問題頁面。"},{"en":"The FAQ was updated to address recent customer inquiries.","zh-TW":"常見問題已更新以解答最近的客戶詢問。"}]', '{"abbreviation":"FAQ"}', NULL, 5, 2961, NULL),
(2962, 'fresh produce', '/''freʃ ˌprɒdjuːs/', 'noun', '{"zh-TW":["新鮮農產品；新鮮蔬果"],"en":["fresh fruits, vegetables, and other foods sold directly from the farm or market"]}', NULL, 'buy fresh produce / local fresh produce / seasonal fresh produce', '[{"en":"She shops at the farmers'' market every Saturday for fresh produce.","zh-TW":"她每個星期六在農夫市集購買新鮮農產品。"},{"en":"Using fresh produce rather than canned goods significantly improves the flavor of dishes.","zh-TW":"使用新鮮農產品而非罐裝食品可以顯著改善菜肴的風味。"}]', NULL, NULL, 5, 2962, NULL),
(2963, 'freshman', '/ˈfrɛʃmən/', 'noun', '{"zh-TW":["大一新生"],"en":["a first-year student"]}', NULL, 'freshman year / freshman orientation', '[{"en":"She''s a freshman at the university.","zh-TW":"她是大學一年級新生。"},{"en":"Freshman year can be challenging.","zh-TW":"大一可能充滿挑戰。"}]', NULL, NULL, 3, 2963, NULL),
(2964, 'friction', '/ˈfrɪkʃən/', 'noun', '{"zh-TW":["摩擦；阻力（比喻）"],"en":["resistance or conflict between people or processes; inefficiency"]}', NULL, 'reduce friction / internal friction / friction in supply chains', '[{"en":"Removing friction from the checkout process increases conversion rates.","zh-TW":"減少結帳流程中的摩擦提高了轉化率。"},{"en":"Trade friction between the two countries disrupted global supply chains.","zh-TW":"兩國之間的貿易摩擦擾亂了全球供應鏈。"}]', '{"adjective":"frictional","adverb":"frictionally"}', NULL, 3, 2964, NULL),
(2965, 'friend', '/frɛnd/', 'noun', '{"zh-TW":["朋友"],"en":["a person you know well and like"]}', NULL, 'make friends / close friend', '[{"en":"She made many friends at work.","zh-TW":"她在工作中交了很多朋友。"},{"en":"He is a close friend and business partner.","zh-TW":"他是好朋友也是商業夥伴。"}]', '{"noun":"friend","noun2":"friendship","adjective":"friendly","adjective2":"unfriendly"}', NULL, 2, 2965, NULL),
(2966, 'friendly', 'ˈfrɛndli', 'adjective', '{"zh-TW":["友好的；親切的","易用的"],"en":["kind and pleasant","not hostile"]}', NULL, 'user-friendly/customer-friendly', '[{"en":"The new interface is very user-friendly.","zh-TW":"新介面非常友好易用。"}]', '{"noun":"friendliness","adverb":"in a friendly way"}', NULL, 3, 2966, NULL),
(2967, 'fringe benefit', '/frɪndʒ ˈbenɪfɪt/', 'noun', '{"zh-TW":["附加福利；額外津貼"],"en":["an extra benefit given to employees beyond their salary"]}', NULL, 'fringe benefits include / taxable fringe benefits', '[{"en":"Fringe benefits such as gym memberships boost morale.","zh-TW":"健身房會員等附加福利提升員工士氣。"},{"en":"Some fringe benefits are subject to income tax.","zh-TW":"部分附加福利需繳納所得稅。"}]', NULL, NULL, 5, 2967, NULL),
(2968, 'frivolous', '/''frɪvələs/', 'adjective', '{"zh-TW":["輕率的；無聊的；不嚴肅的"],"en":["not having any serious purpose or value; lacking seriousness"]}', NULL, 'frivolous lawsuit / frivolous remark / frivolous behavior', '[{"en":"The court dismissed the frivolous lawsuit after determining it had no legal merit.","zh-TW":"法院在確定該案沒有法律依據後駁回了這起輕率的訴訟。"},{"en":"He was criticized for making frivolous comments during a serious meeting.","zh-TW":"他因在嚴肅的會議中發表輕率評論而受到批評。"}]', '{"adverb":"frivolously","noun":"frivolity"}', NULL, 3, 2968, NULL),
(2969, 'front', '/frʌnt/', 'noun / adjective', '{"zh-TW":["前面；前線"],"en":["the forward-facing part; leading position"]}', NULL, 'in front of / front desk', '[{"en":"The receptionist is at the front desk.","zh-TW":"接待員在前台。"},{"en":"Customer service is on the front line.","zh-TW":"客戶服務在第一線。"}]', '{"noun":"front","adjective":"front"}', NULL, 2, 2969, NULL),
(2970, 'front desk', '/frʌnt dɛsk/', 'noun', '{"zh-TW":["前台；接待台"],"en":["the reception area of a hotel"]}', NULL, 'check in at the front desk / contact the front desk', '[{"en":"Please collect your room key at the front desk.","zh-TW":"請在前台領取您的房間鑰匙。"},{"en":"The front desk is staffed 24 hours a day.","zh-TW":"前台全天24小時有工作人員。"}]', NULL, NULL, 4, 2970, NULL),
(2971, 'front-end loaded', '/frʌnt end ˈloʊdɪd/', 'adjective', '{"zh-TW":["前端費用偏高的；前期成本高的"],"en":["having a higher proportion of costs incurred at the beginning of a period or project"]}', NULL, 'front-end loaded fee structure / front-end loaded project', '[{"en":"The project was front-end loaded with heavy design and planning costs.","zh-TW":"該項目在設計和規劃方面前期成本偏高。"},{"en":"Front-end loaded loans have higher interest in early repayment periods.","zh-TW":"前期費用偏高的貸款在早期還款期間利息較高。"}]', NULL, NULL, 5, 2971, NULL),
(2972, 'front-running', '/ˈfrʌnt ˌrʌnɪŋ/', 'noun', '{"zh-TW":["搶先交易；超前交易"],"en":["the practice of a broker trading based on advance knowledge of pending client orders"]}', NULL, 'illegal front-running / front-running scandal / prohibit front-running', '[{"en":"Front-running by brokers who trade ahead of client orders is considered market manipulation.","zh-TW":"經紀商在客戶訂單之前進行交易的搶先交易行為被視為市場操縱。"},{"en":"The regulator investigated the firm for suspected front-running of large institutional orders.","zh-TW":"監管機構調查了該公司涉嫌搶先交易大型機構訂單的行為。"}]', NULL, NULL, 5, 2972, NULL),
(2973, 'fronting arrangement', '/ˈfrʌntɪŋ əˈreɪndʒmənt/', 'noun', '{"zh-TW":["先頭安排；前置安排"],"en":["an arrangement where a licensed insurer issues a policy on behalf of another entity"]}', NULL, 'enter a fronting arrangement / fronting arrangement requirements', '[{"en":"The company used a fronting arrangement to write insurance in markets where it lacked a license.","zh-TW":"公司在沒有許可證的市場使用了先頭安排來發行保單。"},{"en":"A fronting arrangement involves paying fees to the fronting insurer.","zh-TW":"先頭安排涉及向先頭保險公司支付費用。"}]', NULL, NULL, 5, 2973, NULL),
(2974, 'frontline workers', '/ˈfrʌntlaɪn ˈwɜːrkərz/', 'noun', '{"zh-TW":["前線工作者；一線人員"],"en":["employees who work directly with customers or in essential services"]}', NULL, 'support frontline workers / protect frontline workers / recognize frontline workers', '[{"en":"Frontline workers in healthcare faced extreme pressure during the pandemic.","zh-TW":"醫療保健領域的前線工作者在疫情期間面臨極大的壓力。"},{"en":"Compensation for frontline workers often does not reflect the risks and demands of their roles.","zh-TW":"前線工作者的薪酬通常不反映其職責的風險和要求。"}]', NULL, NULL, 5, 2974, NULL),
(2975, 'frost', '/frɒst/', 'noun', '{"zh-TW":["霜"],"en":["a thin layer of ice on a surface"]}', '{"root":{"text":"frost","meaning":"freeze (結凍)"},"logic":"結凍形成的薄冰層。"}', 'morning frost / frost damage / frostbite', '[{"en":"There was a heavy frost this morning.","zh-TW":"今天早上有很重的霜。"},{"en":"Frost can damage delicate plants.","zh-TW":"霜會損害嬌嫩的植物。"}]', '{"adjective":"frosty","noun":"frostbite"}', NULL, 2, 2975, NULL),
(2976, 'frugal', '/''fruːɡəl/', 'adjective', '{"zh-TW":["節儉的；省吃儉用的"],"en":["sparing or economical with regard to money or food; simple and plain"]}', NULL, 'frugal lifestyle / frugal with expenses / frugal company', '[{"en":"She lived a frugal lifestyle to save enough for her early retirement.","zh-TW":"她過著節儉的生活，為提前退休攢夠了錢。"},{"en":"The startup was frugal with spending in its early years to extend its runway.","zh-TW":"這家新創公司在早期節儉花費，以延長運作期限。"}]', '{"adverb":"frugally","noun":"frugality"}', NULL, 2, 2976, NULL),
(2977, 'fruit', '/fruːt/', 'noun', '{"zh-TW":["水果；成果"],"en":["food from a plant with seeds","a good result"]}', NULL, 'bear fruit / fruit of labor', '[{"en":"Our efforts are finally bearing fruit.","zh-TW":"我們的努力終於有了成果。"},{"en":"Fresh fruit is provided in the office.","zh-TW":"辦公室提供新鮮水果。"}]', '{"noun":"fruit","adjective":"fruitful","adjective2":"fruitless"}', NULL, 2, 2977, NULL),
(2978, 'frustrated', '/frʌˈstreɪtɪd/', 'adjective', '{"zh-TW":["沮喪的；受挫的"],"en":["feeling upset because of inability to change or achieve something"]}', '{"root":{"text":"frustr","meaning":"in vain (徒勞)"},"suffix":{"text":"-ated","meaning":"state (狀態)"},"logic":"感到徒勞的狀態，即「受挫的」。"}', 'feel frustrated / frustrated with', '[{"en":"He felt frustrated with the slow progress.","zh-TW":"他對緩慢的進度感到挫折。"},{"en":"Customers are frustrated by the long wait times.","zh-TW":"顧客對漫長的等待時間感到不滿。"}]', '{"noun":"frustration","verb":"frustrate","adjective":"frustrating"}', NULL, 4, 2978, NULL),
(2979, 'fulfill', '/fʊlˈfɪl/', 'verb', '{"zh-TW":["履行；實現"],"en":["to carry out a duty; to satisfy a requirement"]}', NULL, 'fulfill obligations/requirements', '[{"en":"The company fulfilled all contractual obligations.","zh-TW":"公司履行了所有合約義務。"},{"en":"We strive to fulfill customer expectations.","zh-TW":"我們努力滿足客戶期望。"}]', '{"noun":"fulfillment","verb":"fulfill"}', NULL, 3, 2979, 686),
(2980, 'fulfillment', '/fʊlˈfɪlmənt/', 'noun', '{"zh-TW":["訂單履行；完成"],"en":["the process of completing a customer order, including picking and shipping"]}', NULL, 'order fulfillment / fulfillment center / fulfillment speed / fulfillment process', '[{"en":"Same-day fulfillment became a key competitive advantage.","zh-TW":"當日訂單履行成為關鍵競爭優勢。"},{"en":"The company opened a new fulfillment center to serve the East Coast.","zh-TW":"公司開設了新的訂單履行中心以服務東海岸。"}]', '{"verb":"fulfill","adjective":"fulfilled"}', NULL, 4, 2980, 576),
(2981, 'full', '/fʊl/', 'adjective', '{"zh-TW":["滿的；完整的"],"en":["containing as much as possible","complete"]}', NULL, 'full-time / in full', '[{"en":"She works full-time at the firm.","zh-TW":"她在公司全職工作。"},{"en":"Payment must be made in full.","zh-TW":"必須全額付款。"}]', '{"adjective":"full","adverb":"fully","verb":"fulfill","noun":"fullness"}', NULL, 1, 2981, NULL),
(2982, 'full board', '/fʊl bɔːrd/', 'noun', '{"zh-TW":["全膳食服務"],"en":["accommodation including all meals"]}', NULL, 'full board package / full board rate', '[{"en":"The resort offers a full board package for families.","zh-TW":"度假村為家庭提供全膳食服務套餐。"},{"en":"Full board includes breakfast, lunch, and dinner.","zh-TW":"全膳食服務包含早餐、午餐和晚餐。"}]', NULL, NULL, 4, 2982, NULL),
(2983, 'full-time athlete', '/''fʊl taɪm ˌæθliːt/', 'noun', '{"zh-TW":["全職運動員；專業運動員"],"en":["a person who trains and competes as their primary occupation"]}', NULL, 'become a full-time athlete / support full-time athletes / schedule of a full-time athlete', '[{"en":"She quit her job to become a full-time athlete and focus on the upcoming Olympics.","zh-TW":"她辭去工作，成為一名全職運動員，專注於即將到來的奧運會。"},{"en":"Being a full-time athlete requires an enormous personal and financial commitment.","zh-TW":"成為全職運動員需要巨大的個人和財務承諾。"}]', NULL, NULL, 5, 2983, NULL),
(2984, 'full-time equivalent', '/fʊl taɪm ɪˈkwɪvələnt/', 'noun', '{"zh-TW":["全職當量"],"en":["a unit measuring the workload of an employed person in a way that makes workloads comparable"]}', NULL, 'calculate full-time equivalent / full-time equivalent headcount', '[{"en":"The project requires 10 full-time equivalent staff to complete on time.","zh-TW":"該項目需要10名全職當量員工才能按時完成。"},{"en":"Budgeting is simplified by expressing staffing needs in full-time equivalents.","zh-TW":"通過以全職當量表示人員需求來簡化預算編製。"}]', '{"abbreviation":"FTE"}', NULL, 5, 2984, NULL),
(2985, 'full-year results', '/fʊl jɪər rɪˈzʌlts/', 'noun', '{"zh-TW":["全年業績；年度業績"],"en":["the financial performance of a company over its entire fiscal year"]}', NULL, 'announce full-year results / full-year results presentation', '[{"en":"Full-year results showed a 15% increase in net profit.","zh-TW":"全年業績顯示淨利潤增加了15%。"},{"en":"Investors focused on full-year results to assess the CEO strategy.","zh-TW":"投資者關注全年業績以評估執行長的策略。"}]', NULL, NULL, 5, 2985, NULL),
(2986, 'function', '/ˈfʌŋkʃən/', 'noun / verb', '{"zh-TW":["功能；運作"],"en":["a purpose or role; to work properly"]}', NULL, 'key function / function as', '[{"en":"What is the function of this department?","zh-TW":"這個部門的功能是什麼？"},{"en":"The system is functioning normally.","zh-TW":"系統運作正常。"}]', '{"noun":"function/functionality","verb":"function","adjective":"functional"}', NULL, 3, 2986, NULL),
(2987, 'functional area', '/ˈfʌŋkʃənl ˈeəriə/', 'noun', '{"zh-TW":["職能領域；功能部門"],"en":["a department or division within an organization with a specific function"]}', NULL, 'manage a functional area / cross-functional area', '[{"en":"Each functional area submitted its budget request to finance.","zh-TW":"每個職能領域向財務部門提交了預算申請。"},{"en":"The new system affected every functional area in the company.","zh-TW":"新系統影響了公司的每個職能領域。"}]', NULL, NULL, 5, 2987, NULL),
(2988, 'functional currency', '/ˈfʌŋkʃənəl ˈkʌrənsi/', 'noun', '{"zh-TW":["功能貨幣"],"en":["the primary currency of a company''s operating environment used for accounting"]}', NULL, 'report in functional currency / functional currency translation', '[{"en":"The company''s functional currency is the US dollar for all reporting purposes.","zh-TW":"公司的功能貨幣在所有報告目的中為美元。"},{"en":"Transactions in other currencies are translated at the functional currency rate.","zh-TW":"其他貨幣的交易按功能貨幣匯率換算。"}]', NULL, NULL, 5, 2988, NULL),
(2989, 'fund', '/fʌnd/', 'noun / verb', '{"zh-TW":["基金；資助"],"en":["a sum of money for a purpose; to provide money"]}', NULL, 'raise/allocate funds', '[{"en":"The company raised funds for expansion.","zh-TW":"公司為擴張籌集了資金。"},{"en":"The project is funded by the government.","zh-TW":"該項目由政府資助。"}]', '{"noun":"fund/funding","verb":"fund"}', NULL, 1, 2989, 365),
(2990, 'fund management', '/fʌnd ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["基金管理"],"en":["professionally overseeing an investment portfolio to achieve a return"]}', NULL, 'outsource fund management / fund management company', '[{"en":"The pension fund outsourced its fund management to a specialist firm.","zh-TW":"退休金外包了其基金管理給專業公司。"},{"en":"Fund management requires balancing risk and return for investors.","zh-TW":"基金管理需要為投資者平衡風險和回報。"}]', NULL, NULL, 5, 2990, NULL),
(2991, 'fund manager', '/fʌnd ˈmænɪdʒər/', 'noun', '{"zh-TW":["基金經理"],"en":["a professional responsible for investment decisions within a fund"]}', NULL, 'appoint a fund manager / fund manager performance', '[{"en":"The fund manager achieved returns 3% above the benchmark index.","zh-TW":"基金經理取得了高出基準指數3%的回報。"},{"en":"Investors evaluate a fund manager''s track record before committing capital.","zh-TW":"投資者在投入資金前評估基金經理的業績記錄。"}]', NULL, NULL, 4, 2991, NULL),
(2992, 'fund of funds', '/fʌnd əv fʌndz/', 'noun', '{"zh-TW":["基金中的基金"],"en":["an investment fund that invests in a portfolio of other investment funds"]}', NULL, 'invest in a fund of funds / fund of funds strategy', '[{"en":"A fund of funds provides diversification across multiple managers.","zh-TW":"基金中的基金在多個管理人之間提供了多元化。"},{"en":"Fund of funds investors pay two layers of management fees.","zh-TW":"基金中的基金投資者支付兩層管理費。"}]', NULL, NULL, 5, 2992, NULL),
(2993, 'fundamental', '/ˌfʌndəˈmentəl/', 'adjective', '{"zh-TW":["基本的；根本的"],"en":["forming a necessary base; essential"]}', '{"root":{"text":"fund","meaning":"bottom/foundation (基礎)"},"suffix":{"text":"-amental","meaning":"relating to (相關的)"},"logic":"與基礎相關的，即「根本的」。"}', 'fundamental change/principle; fundamental principle / fundamental change / fundamental right', '[{"en":"Trust is fundamental to any business relationship.","zh-TW":"信任是任何商業關係的根本。"},{"en":"There are fundamental differences between the two plans.","zh-TW":"兩個計畫之間有根本的差異。"},{"en":"Respect is fundamental to any relationship.","zh-TW":"尊重是任何關係的根本。"},{"en":"There has been a fundamental change in policy.","zh-TW":"政策發生了根本性的改變。"}]', '{"noun":"fundamentals","adjective":"fundamental","adverb":"fundamentally"}', NULL, 4, 2993, NULL),
(2994, 'funding', 'ˈfʌndɪŋ', 'noun', '{"zh-TW":["資金；經費","撥款"],"en":["money provided for a purpose","financial support"]}', NULL, 'secure funding/government funding', '[{"en":"We secured additional funding for the project.","zh-TW":"我們為項目獲得了額外資金。"}]', '{"verb":"fund","adjective":"funded"}', NULL, 3, 2994, NULL),
(2995, 'funding gap', '/ˈfʌndɪŋ ɡæp/', 'noun', '{"zh-TW":["資金缺口"],"en":["the difference between what is available and what is needed for a project"]}', NULL, 'address the funding gap / identify the funding gap', '[{"en":"A funding gap of 5 million needed to be filled before construction.","zh-TW":"施工前需要填補500萬元的資金缺口。"},{"en":"The nonprofit sought donors to close its annual funding gap.","zh-TW":"非營利組織尋求捐款者填補其年度資金缺口。"}]', NULL, NULL, 4, 2995, NULL),
(2996, 'fungible', '/ˈfʌndʒɪbəl/', 'adjective', '{"zh-TW":["可互換的；等值可替代的"],"en":["(of goods or assets) able to be replaced or interchanged with an equivalent"]}', NULL, 'fungible asset / fungible commodity / fungible token', '[{"en":"Gold is a fungible commodity — one ounce equals another of the same purity.","zh-TW":"黃金是可互換的商品——相同純度的一盎司等於另一盎司。"},{"en":"Money is the quintessential fungible asset in economics.","zh-TW":"貨幣是經濟學中典型的可互換資產。"}]', '{"noun":"fungibility"}', NULL, 3, 2996, NULL),
(2997, 'funnel', '/ˈfʌnəl/', 'noun', '{"zh-TW":["漏斗；行銷漏斗"],"en":["the stages a customer goes through from awareness to purchase"]}', NULL, 'sales funnel / marketing funnel / top of funnel / bottom of funnel', '[{"en":"Most website visitors drop off at the top of the funnel.","zh-TW":"大多數網站訪客在漏斗頂端就流失了。"},{"en":"The team optimized the funnel to reduce drop-off at checkout.","zh-TW":"團隊優化了漏斗以減少結帳時的流失。"}]', '{"verb":"funnel"}', NULL, 2, 2997, NULL),
(2998, 'funny', '/ˈfʌni/', 'adjective', '{"zh-TW":["有趣的；好笑的"],"en":["causing laughter","strange or unexpected"]}', NULL, 'funny story / look funny', '[{"en":"He told a funny story at the dinner.","zh-TW":"他在晚餐上說了一個有趣的故事。"},{"en":"Something looks funny about these numbers.","zh-TW":"這些數字看起來有點奇怪。"}]', '{"adjective":"funny","adverb":"funnily","noun":"fun"}', NULL, 2, 2998, NULL),
(2999, 'furnish', '/ˈfɜːrnɪʃ/', 'verb', '{"zh-TW":["提供；配備"],"en":["to supply or provide; to equip with furniture"]}', NULL, 'furnish information/an office', '[{"en":"The apartment is fully furnished.","zh-TW":"公寓配備齊全。"},{"en":"Please furnish the required documents.","zh-TW":"請提供所需文件。"}]', '{"noun":"furnishing/furniture","verb":"furnish","adjective":"furnished"}', NULL, 3, 2999, 687);
