(3250, 'heuristics', '/hjʊˈrɪstɪks/', 'noun', '{"zh-TW":["啟發法；試探法"],"en":["the study or application of practical problem-solving methods"]}', NULL, 'use heuristics / apply heuristics / cognitive heuristics', '[{"en":"Heuristics help people make reasonable decisions with limited information.","zh-TW":"啟發法幫助人們在資訊有限的情況下做出合理決策。"},{"en":"Behavioral economics studies how heuristics lead to systematic biases.","zh-TW":"行為經濟學研究啟發法如何導致系統性偏見。"}]', '{"adjective":"heuristic"}', NULL, 4, 3250, NULL),
(3251, 'hide', '/haɪd/', 'verb', '{"zh-TW":["隱藏；躲藏"],"en":["to put out of sight","to keep secret"]}', NULL, 'hide information / hidden cost', '[{"en":"There are hidden costs in this contract.","zh-TW":"這份合約有隱藏成本。"},{"en":"Don''t hide mistakes from your manager.","zh-TW":"別對主管隱瞞錯誤。"}]', '{"verb":"hide","adjective":"hidden"}', NULL, 1, 3251, NULL),
