(3253, 'high', '/haɪ/', 'adjective', '{"zh-TW":["高的；高度的"],"en":["extending far upward","at a great level"]}', NULL, 'high quality / high demand', '[{"en":"There is high demand for skilled workers.","zh-TW":"對技術工人有很高的需求。"},{"en":"We maintain high quality standards.","zh-TW":"我們維持高品質標準。"}]', '{"adjective":"high","adverb":"highly","noun":"height","verb":"heighten"}', NULL, 1, 3253, NULL),
(3254, 'high net worth', '/haɪ net wɜːrθ/', 'adjective', '{"zh-TW":["高淨值的"],"en":["having significant personal wealth, typically over a million dollars"]}', NULL, 'high net worth individual / high net worth client', '[{"en":"Wealth management services target high net worth individuals.","zh-TW":"財富管理服務針對高淨值人士。"},{"en":"High net worth clients receive dedicated private banking services.","zh-TW":"高淨值客戶獲得專屬的私人銀行服務。"}]', '{"abbreviation":"HNW"}', NULL, 5, 3254, NULL),
(3255, 'high tea', '/haɪ tiː/', 'noun', '{"zh-TW":["英式下午茶"],"en":["a British meal taken in the afternoon with tea and snacks"]}', NULL, 'enjoy high tea / traditional high tea', '[{"en":"They enjoyed high tea at a luxury hotel.","zh-TW":"他們在豪華飯店享用了英式下午茶。"},{"en":"High tea typically includes finger sandwiches and scones.","zh-TW":"英式下午茶通常包括小三明治和司康。"}]', NULL, NULL, 3, 3255, NULL),
(3256, 'high-growth', '/haɪ ɡroʊθ/', 'adjective', '{"zh-TW":["高增長的"],"en":["characterized by rapid expansion in revenue or market presence"]}', NULL, 'high-growth market / high-growth company / high-growth segment', '[{"en":"The fund focuses on high-growth technology companies.","zh-TW":"基金專注於高增長科技公司。"},{"en":"The product line entered a high-growth phase after the rebranding.","zh-TW":"重塑品牌後，產品線進入了高增長階段。"}]', NULL, NULL, 4, 3256, NULL),
(3257, 'high-growth market', '/haɪ ɡroʊθ ˈmɑːrkɪt/', 'noun', '{"zh-TW":["高增長市場"],"en":["a market experiencing rapid expansion in sales or customer base"]}', NULL, 'enter a high-growth market / high-growth market opportunities', '[{"en":"Southeast Asia is seen as a high-growth market for e-commerce.","zh-TW":"東南亞被視為電子商務的高增長市場。"},{"en":"Investors seek high-growth markets to maximize portfolio returns.","zh-TW":"投資者尋求高增長市場以最大化投資組合回報。"}]', NULL, NULL, 5, 3257, NULL),
(3258, 'high-net-worth individual', '/haɪ net wɜːrθ ˌɪndɪˈvɪdʒuəl/', 'noun', '{"zh-TW":["高淨值人士；高資產人士"],"en":["a person with significant investable assets, typically over $1 million"]}', NULL, 'serve high-net-worth individuals / high-net-worth individual portfolio', '[{"en":"Private banks offer personalized services to high-net-worth individuals.","zh-TW":"私人銀行為高淨值人士提供個性化服務。"},{"en":"High-net-worth individuals often require complex estate planning advice.","zh-TW":"高淨值人士通常需要複雜的遺產規劃建議。"}]', '{"abbreviation":"HNWI"}', NULL, 5, 3258, NULL),
(3259, 'high-potential', '/haɪ pəˈtenʃəl/', 'adjective', '{"zh-TW":["高潛力的"],"en":["having the ability to perform at a much higher level with development"]}', NULL, 'high-potential employee / identify high-potential talent', '[{"en":"High-potential employees are fast-tracked for leadership positions.","zh-TW":"高潛力員工被加速培養以擔任領導職位。"},{"en":"The talent review process identifies high-potential performers.","zh-TW":"人才審查流程識別高潛力績效員工。"}]', NULL, NULL, 5, 3259, NULL),
(3260, 'high-value client', '/haɪ ˈvæljuː ˈklaɪənt/', 'noun', '{"zh-TW":["高價值客戶"],"en":["a customer that generates significant revenue for a business"]}', NULL, 'retain high-value clients / identify high-value clients', '[{"en":"High-value clients receive dedicated account management.","zh-TW":"高價值客戶獲得專屬客戶管理服務。"},{"en":"The sales strategy focused on attracting and retaining high-value clients.","zh-TW":"銷售策略專注於吸引和保留高價值客戶。"}]', NULL, NULL, 5, 3260, NULL),
(3261, 'high-yield bond', '/haɪ jiːld bɒnd/', 'noun', '{"zh-TW":["高收益債券；垃圾債券"],"en":["a bond with a high interest rate due to its below-investment-grade credit rating"]}', NULL, 'invest in high-yield bonds / high-yield bond spread', '[{"en":"High-yield bonds offer higher returns but carry greater default risk.","zh-TW":"高收益債券提供較高回報，但承擔較大的違約風險。"},{"en":"The fund allocated 15% of its portfolio to high-yield bonds.","zh-TW":"基金將其投資組合的15%分配到了高收益債券。"}]', '{"synonym":"junk bond"}', NULL, 5, 3261, NULL),
(3262, 'highbrow', '/ˈhaɪbraʊ/', 'adjective', '{"zh-TW":["高雅的；高智識的"],"en":["requiring or having an advanced level of knowledge or taste"]}', NULL, 'highbrow culture / highbrow audience / highbrow programming', '[{"en":"The documentary appeals to a highbrow audience interested in philosophy.","zh-TW":"這部紀錄片吸引了對哲學感興趣的高智識受眾。"},{"en":"Highbrow literary fiction often achieves critical acclaim rather than commercial success.","zh-TW":"高雅的文學小說通常獲得評論界讚譽而非商業成功。"}]', '{"antonym":"lowbrow","noun":"highbrow"}', NULL, 3, 3262, NULL),
(3263, 'higher education', '/''haɪər ˌedʒuˌkeɪʃən/', 'noun', '{"zh-TW":["高等教育"],"en":["education at universities and colleges that leads to a degree or professional qualification"]}', NULL, 'access higher education / higher education institution / invest in higher education', '[{"en":"Higher education opens doors to better career opportunities and higher earning potential.","zh-TW":"高等教育開啟了更好職業機會和更高收入潛力的大門。"},{"en":"Governments worldwide are increasing investment in higher education to drive economic growth.","zh-TW":"世界各地的政府正在增加對高等教育的投資，以推動經濟增長。"}]', '{"adjective":"higher-level"}', NULL, 5, 3263, NULL),
(3264, 'highlight', '/ˈhaɪlaɪt/', 'verb, noun', '{"zh-TW":["強調；突出","精彩部分"],"en":["to emphasize or draw attention to","the best or most important part"]}', NULL, 'highlight the importance / the highlight of', '[{"en":"The report highlights the need for reform.","zh-TW":"該報告強調了改革的必要性。"},{"en":"The concert was the highlight of the trip.","zh-TW":"音樂會是這趟旅行的精彩部分。"}]', '{"noun":"highlight","verb":"highlight"}', NULL, 3, 3264, 882),
