(4072, 'macroprudential', '/ˌmækrəʊˈpruːdenʃəl/', 'adjective', '{"zh-TW":["宏觀審慎的"],"en":["relating to the regulation of the financial system as a whole to prevent systemic risk"]}', NULL, 'macroprudential policy / macroprudential regulation / macroprudential framework', '[{"en":"Macroprudential tools include capital buffers and lending restrictions.","zh-TW":"宏觀審慎工具包括資本緩衝和貸款限制。"},{"en":"The central bank adopted macroprudential measures to cool the housing market.","zh-TW":"中央銀行採取了宏觀審慎措施以冷卻房地產市場。"}]', NULL, NULL, 5, 4072, NULL),
(4073, 'magnitude', '/ˈmæɡnɪtuːd/', 'noun', '{"zh-TW":["規模；重要性"],"en":["the great size or importance of something"]}', NULL, 'of this/such magnitude / order of magnitude', '[{"en":"We have never faced a crisis of this magnitude.","zh-TW":"我們從未面臨過如此規模的危機。"},{"en":"The magnitude of the problem was underestimated.","zh-TW":"問題的嚴重性被低估了。"}]', '{"noun":"magnitude"}', NULL, 3, 4073, NULL),
