(4076, 'mainstream', '/ˈmeɪnstriːm/', 'noun, adjective', '{"zh-TW":["主流"],"en":["the ideas or activities shared by most people"]}', NULL, 'mainstream media/culture/market', '[{"en":"Electric vehicles are entering the mainstream market.","zh-TW":"電動車正在進入主流市場。"},{"en":"The idea has now become mainstream.","zh-TW":"這個想法現在已成為主流。"}]', '{"noun":"mainstream","adjective":"mainstream","verb":"mainstream"}', NULL, 4, 4076, NULL),
(4077, 'maintain', '/meɪnˈteɪn/', 'verb', '{"zh-TW":["維持；保養","維持；保持；維修"],"en":["to keep in a particular state","to assert as true","to keep in good condition; to continue at the same level"]}', '{"root":{"text":"main","meaning":"hand (手)"},"suffix":{"text":"tain","meaning":"hold (持有)"},"logic":"用手持住不放，即「維持」。"}', 'maintain quality / maintain a relationship; maintain standards/quality/equipment', '[{"en":"It''s important to maintain a healthy lifestyle.","zh-TW":"維持健康的生活方式很重要。"},{"en":"The building is well maintained.","zh-TW":"這棟建築保養得很好。"},{"en":"It is important to maintain high standards of quality.","zh-TW":"保持高品質標準很重要。"},{"en":"The building is well maintained.","zh-TW":"這棟建築維護得很好。"}]', '{"noun":"maintenance","verb":"maintain"}', NULL, 3, 4077, 36),
(4078, 'maintain records', '/meɪnˈteɪn ˈrekərdz/', 'verb', '{"zh-TW":["保存記錄；維護記錄"],"en":["to keep and update official documents and data"]}', NULL, 'maintain accurate records / maintain financial records', '[{"en":"Companies are required to maintain records for at least seven years.","zh-TW":"公司須保存至少七年的記錄。"},{"en":"The IT department maintains records of all system access.","zh-TW":"IT部門保存所有系統存取記錄。"}]', NULL, NULL, 5, 4078, NULL),
(4079, 'maintenance', 'ˈmeɪntənəns', 'noun', '{"zh-TW":["維護；保養","維修"],"en":["the process of keeping something in good condition","upkeep"]}', NULL, 'regular maintenance/system maintenance', '[{"en":"Schedule regular maintenance for all machines.","zh-TW":"為所有機器安排定期維護。"}]', '{"verb":"maintain","adjective":"maintained"}', NULL, 4, 4079, 152),
(4080, 'maintenance fee', '/''meɪntənəns fiː/', 'noun', '{"zh-TW":["維護費；管理費"],"en":["a fee charged to cover the costs of maintaining shared facilities in a residential building"]}', NULL, 'pay maintenance fee / monthly maintenance fee / maintenance fee increase', '[{"en":"The maintenance fee covers cleaning, landscaping, and security for the building.","zh-TW":"維護費涵蓋大樓的清潔、綠化和安全。"},{"en":"The maintenance fee was raised by fifteen percent due to rising costs.","zh-TW":"由於成本上升，維護費提高了百分之十五。"}]', NULL, NULL, 5, 4080, NULL),
(4081, 'major', '/ˈmeɪdʒər/', 'noun', '{"zh-TW":["主修科目","主要的；重大的"],"en":["the main subject a student studies","very important or large","a university subject of specialization"]}', NULL, 'major in / change one''s major; major factor/issue/change / major in', '[{"en":"What''s your major?","zh-TW":"你的主修是什麼？"},{"en":"She majored in psychology.","zh-TW":"她主修心理學。"},{"en":"Cost reduction is a major priority this year.","zh-TW":"降低成本是今年的主要優先事項。"},{"en":"She majored in business administration.","zh-TW":"她主修企業管理。"}]', '{"adjective":"major","noun2":"majority","noun":"major, majority","verb":"major"}', NULL, 2, 4081, NULL),
(4082, 'majority', '/məˈdʒɔːrəti/', 'noun', '{"zh-TW":["多數；大多數"],"en":["the greater number or part"]}', NULL, 'the vast majority / majority vote / majority of', '[{"en":"The vast majority of employees support the change.","zh-TW":"絕大多數員工支持這項變革。"},{"en":"The proposal passed by a majority vote.","zh-TW":"該提案以多數票通過。"}]', '{"noun":"majority, major","adjective":"major"}', NULL, 3, 4082, NULL),
(4083, 'majority shareholder', '/məˈdʒɒrɪti ˈʃeərhoʊldər/', 'noun', '{"zh-TW":["多數股東；大股東"],"en":["a person or entity owning more than 50% of a company shares"]}', NULL, 'become the majority shareholder / identify the majority shareholder', '[{"en":"The family remained the majority shareholder after the IPO.","zh-TW":"家族在首次公開募股後仍是多數股東。"},{"en":"The majority shareholder has significant control over board decisions.","zh-TW":"多數股東對董事會決策有重大控制力。"}]', NULL, NULL, 5, 4083, NULL),
(4084, 'make', '/meɪk/', 'verb', '{"zh-TW":["製作；使得"],"en":["to produce or create","to cause to be"]}', NULL, 'make a decision / make progress', '[{"en":"We need to make a decision today.","zh-TW":"我們今天需要做出決定。"},{"en":"The team made great progress.","zh-TW":"團隊取得了很大的進展。"}]', '{"verb":"make","noun":"maker","noun2":"making"}', NULL, 1, 4084, NULL),
(4085, 'male', '/meɪl/', 'adjective', '{"zh-TW":["男性的"],"en":["relating to men or boys"]}', NULL, 'male employee / male-dominated', '[{"en":"The industry is still male-dominated.","zh-TW":"這個產業仍由男性主導。"},{"en":"Both male and female candidates are welcome.","zh-TW":"歡迎男性和女性候選人。"}]', '{"adjective":"male","noun":"male"}', NULL, 1, 4085, NULL),
(4086, 'malfeasance', '/mælˈfiːzəns/', 'noun', '{"zh-TW":["瀆職；不法行為"],"en":["wrongdoing, especially by a public official"]}', NULL, 'corporate malfeasance / political malfeasance / financial malfeasance', '[{"en":"The audit uncovered evidence of financial malfeasance by senior management.","zh-TW":"審計發現了高級管理人員財務瀆職的證據。"},{"en":"Malfeasance in office is grounds for dismissal and potential prosecution.","zh-TW":"在職瀆職是解雇和潛在起訴的依據。"}]', '{"adjective":"malfeasant"}', NULL, 4, 4086, NULL),
(4087, 'malfunction', '/mælˈfʌŋkʃn/', 'noun, verb', '{"zh-TW":["故障；失靈"],"en":["a failure to work correctly"]}', NULL, 'equipment/system malfunction', '[{"en":"A malfunction in the system caused the delay.","zh-TW":"系統故障導致了延誤。"},{"en":"The machine malfunctioned during production.","zh-TW":"機器在生產過程中出了故障。"}]', '{"noun":"malfunction","verb":"malfunction"}', NULL, 4, 4087, NULL),
(4088, 'malignant', '/məˈlɪɡnənt/', 'adjective', '{"zh-TW":["惡性的；惡性腫瘤的"],"en":["(of a tumor or disease) tending to spread and likely to be fatal"]}', NULL, 'malignant tumor / malignant cells / malignant disease', '[{"en":"The oncologist confirmed that the growth was malignant.","zh-TW":"腫瘤科醫師確認腫塊是惡性的。"},{"en":"Early detection greatly improves outcomes for malignant cancers.","zh-TW":"早期發現大大改善了惡性癌症的治療結果。"}]', '{"antonym":"benign","noun":"malignancy"}', NULL, 3, 4088, NULL),
(4089, 'mall', '/mɔːl/', 'noun', '{"zh-TW":["購物中心"],"en":["a large enclosed shopping area"]}', '{"root":{"text":"mall","meaning":"shaded walk (林蔭道)"},"logic":"原指林蔭步道，後指大型購物中心。"}', 'shopping mall / mall entrance', '[{"en":"The new mall has over 200 stores.","zh-TW":"新的購物中心有超過200家商店。"},{"en":"Let''s meet at the mall entrance.","zh-TW":"我們在購物中心入口碰面吧。"}]', NULL, NULL, 1, 4089, NULL),
(4090, 'malpractice', '/mælˈpræktɪs/', 'noun', '{"zh-TW":["瀆職；醫療事故"],"en":["improper or negligent professional behavior"]}', NULL, 'medical malpractice / malpractice lawsuit', '[{"en":"The doctor was sued for medical malpractice.","zh-TW":"醫生因醫療事故被起訴。"},{"en":"Malpractice insurance protects professionals from claims.","zh-TW":"瀆職保險保護專業人士免受索賠。"}]', '{"noun":"malpractice"}', NULL, 4, 4090, NULL),
(4091, 'malware', '/ˈmælwɛr/', 'noun', '{"zh-TW":["惡意軟體"],"en":["software designed to damage computers"]}', NULL, 'malware attack / malware protection', '[{"en":"The computer was infected with malware.","zh-TW":"電腦被惡意軟體感染了。"},{"en":"Install software to protect against malware.","zh-TW":"安裝軟體來防禦惡意軟體。"}]', NULL, NULL, 3, 4091, NULL),
(4092, 'man', '/mæn/', 'noun', '{"zh-TW":["男人；人類"],"en":["an adult male","a human being"]}', NULL, 'man-made / manpower', '[{"en":"We need more manpower for this task.","zh-TW":"我們需要更多人力來完成這個任務。"},{"en":"These are man-made materials.","zh-TW":"這些是人造材料。"}]', '{"noun":"man","noun2":"manpower","adjective":"man-made","noun3":"mankind"}', NULL, 1, 4092, NULL),
(4093, 'manage', '/ˈmænɪdʒ/', 'verb', '{"zh-TW":["管理；設法做到"],"en":["to be in charge of; to succeed in doing something"]}', NULL, 'manage a team/project/budget', '[{"en":"She manages a team of 15 people.","zh-TW":"她管理一個15人的團隊。"},{"en":"How do you manage your time effectively?","zh-TW":"你如何有效地管理時間？"}]', '{"noun":"management, manager","verb":"manage","adjective":"manageable, managerial"}', NULL, 2, 4093, 37),
(4094, 'management', 'ˈmænɪdʒmənt', 'noun', '{"zh-TW":["管理；經營","管理層"],"en":["the process of controlling","the people in charge"]}', NULL, 'senior management/project management', '[{"en":"Please escalate to senior management.","zh-TW":"請向高級管理層上報。"}]', '{"verb":"manage","adjective":"managerial","adverb":"managerially"}', NULL, 4, 4094, 389),
(4095, 'management buy-in', '/ˈmænɪdʒmənt ˌbaɪ ɪn/', 'noun', '{"zh-TW":["管理層認同；外部管理層收購"],"en":["acquiring management support; also external management acquiring a company"]}', NULL, 'gain management buy-in / management buy-in transaction', '[{"en":"Gaining management buy-in was essential for the cultural transformation.","zh-TW":"獲得管理層認同對文化轉型至關重要。"},{"en":"The management buy-in was funded by private equity.","zh-TW":"外部管理層收購由私募股權資助。"}]', '{"abbreviation":"MBI"}', NULL, 5, 4095, NULL),
(4096, 'management buyout', '/ˈmænɪdʒmənt ˈbaɪaʊt/', 'noun', '{"zh-TW":["管理層收購"],"en":["the purchase of a company by its own management team"]}', NULL, 'complete a management buyout / management buyout financing', '[{"en":"The management buyout allowed the founders to exit while keeping the business running.","zh-TW":"管理層收購允許創辦人退出同時保持業務運營。"},{"en":"A leveraged management buyout was financed with bank loans.","zh-TW":"槓桿管理層收購通過銀行貸款融資。"}]', '{"abbreviation":"MBO"}', NULL, 5, 4096, NULL),
(4097, 'management consultant', '/ˈmænɪdʒmənt kənˈsʌltənt/', 'noun', '{"zh-TW":["管理顧問"],"en":["a professional who provides expert advice to improve organizational performance"]}', NULL, 'hire a management consultant / management consultant report', '[{"en":"The management consultant recommended restructuring the supply chain.","zh-TW":"管理顧問建議重組供應鏈。"},{"en":"A management consultant brings external expertise and unbiased analysis.","zh-TW":"管理顧問帶來了外部專業知識和無偏見的分析。"}]', NULL, NULL, 5, 4097, NULL),
(4098, 'management consulting', '/ˈmænɪdʒmənt kənˈsʌltɪŋ/', 'noun', '{"zh-TW":["管理諮詢"],"en":["advisory services helping organizations improve performance and solve problems"]}', NULL, 'engage management consulting / management consulting firm', '[{"en":"The company hired a management consulting firm to review operations.","zh-TW":"公司聘請了管理諮詢公司審查業務。"},{"en":"Management consulting recommendations led to a 20% cost reduction.","zh-TW":"管理諮詢建議帶來了20%的成本降低。"}]', NULL, NULL, 5, 4098, NULL),
(4099, 'management fee', '/ˈmænɪdʒmənt fiː/', 'noun', '{"zh-TW":["管理費"],"en":["a fee charged by fund managers for managing investments"]}', NULL, 'charge a management fee / annual management fee', '[{"en":"The fund charges an annual management fee of 1.5%.","zh-TW":"基金收取每年1.5%的管理費。"},{"en":"Management fees were reduced to attract more investors.","zh-TW":"管理費降低了以吸引更多投資者。"}]', NULL, NULL, 5, 4099, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4100, 'management report', '/ˈmænɪdʒmənt rɪˈpɔːrt/', 'noun', '{"zh-TW":["管理報告"],"en":["a periodic report prepared for internal use by management"]}', NULL, 'prepare a management report / review the management report', '[{"en":"Management reports are prepared monthly to track performance.","zh-TW":"管理報告每月編制以追蹤業績。"},{"en":"The management report highlighted the need to cut discretionary spending.","zh-TW":"管理報告強調了需要削減可裁量支出。"}]', NULL, NULL, 5, 4100, NULL),
(4101, 'management team', '/ˈmænɪdʒmənt tiːm/', 'noun', '{"zh-TW":["管理團隊"],"en":["the group of senior leaders responsible for running an organization"]}', NULL, 'strengthen the management team / management team presentation', '[{"en":"A strong management team is essential for sustained business growth.","zh-TW":"強大的管理團隊對持續的業務增長至關重要。"},{"en":"The management team presented a turnaround plan to the board.","zh-TW":"管理團隊向董事會提交了扭轉計劃。"}]', NULL, NULL, 5, 4101, NULL),
(4102, 'manager', '/ˈmænɪdʒər/', 'noun', '{"zh-TW":["經理；管理者"],"en":["a person responsible for controlling a team or department"]}', NULL, 'line manager / senior manager / project manager / account manager', '[{"en":"She reported directly to the regional manager.","zh-TW":"她直接向區域經理匯報。"},{"en":"The manager held weekly team meetings to review progress.","zh-TW":"經理每週召開團隊會議審查進度。"}]', '{"plural":"managers","verb":"manage"}', NULL, 3, 4102, NULL),
(4103, 'managerial', '/ˌmænɪˈdʒɪəriəl/', 'adjective', '{"zh-TW":["管理的；經營的"],"en":["relating to the role or work of managing an organization"]}', NULL, 'managerial skills / managerial position / managerial responsibility', '[{"en":"Strong managerial skills are required for the team leader role.","zh-TW":"團隊領導角色需要強大的管理技能。"},{"en":"She was promoted to a managerial position after two years.","zh-TW":"她在兩年後晉升到了管理職位。"}]', '{"adverb":"managerially","noun":"manager"}', NULL, 4, 4103, NULL),
(4104, 'managing director', '/ˈmænɪdʒɪŋ dɪˈrektər/', 'noun', '{"zh-TW":["董事總經理；管理總監"],"en":["the senior executive responsible for running a company or division"]}', NULL, 'appoint a managing director / role of managing director', '[{"en":"The managing director oversees all company operations.","zh-TW":"董事總經理監督所有公司運營。"},{"en":"She was named managing director of the Asia-Pacific division.","zh-TW":"她被任命為亞太區董事總經理。"}]', '{"abbreviation":"MD","plural":"managing directors"}', NULL, 5, 4104, NULL),
(4105, 'mandate', '/ˈmændeɪt/', 'noun, verb', '{"zh-TW":["授權；命令","授權；強制要求"],"en":["authority given to act; an official order","to require something officially"]}', NULL, 'government mandate / mandate compliance', '[{"en":"The new regulation mandates regular safety inspections.","zh-TW":"新法規要求定期進行安全檢查。"},{"en":"The president received a clear mandate from voters.","zh-TW":"總統從選民那裡獲得了明確的授權。"}]', '{"noun":"mandate","adjective":"mandatory","verb":"mandate"}', NULL, 3, 4105, NULL),
(4106, 'mandatory', '/ˈmændətɔːri/', 'adjective', '{"zh-TW":["強制的；必須的"],"en":["required by law or rules"]}', NULL, 'mandatory training/requirement/retirement', '[{"en":"Safety training is mandatory for all employees.","zh-TW":"安全培訓對所有員工是強制性的。"},{"en":"The company introduced mandatory overtime.","zh-TW":"公司實行了強制加班。"}]', '{"noun":"mandate","adjective":"mandatory","verb":"mandate"}', NULL, 3, 4106, 888),
(4107, 'mandatory disclosure', '/ˈmændətəri dɪsˈkloʊʒər/', 'noun', '{"zh-TW":["強制披露"],"en":["information that must legally be disclosed to regulators or the public"]}', NULL, 'comply with mandatory disclosure / mandatory disclosure requirement', '[{"en":"All listed companies must make mandatory disclosure of material events.","zh-TW":"所有上市公司必須強制披露重大事件。"},{"en":"Failure to make mandatory disclosure can result in regulatory penalties.","zh-TW":"未能進行強制披露可能導致監管處罰。"}]', NULL, NULL, 5, 4107, NULL),
(4108, 'manifest', '/ˈmænɪfest/', 'verb, adjective', '{"zh-TW":["表明；顯示","明顯的"],"en":["to show or demonstrate clearly","obvious"]}', NULL, 'manifest itself / manifest in', '[{"en":"Stress can manifest itself in various physical symptoms.","zh-TW":"壓力可以通過各種身體症狀表現出來。"},{"en":"The problems manifested during the testing phase.","zh-TW":"問題在測試階段顯現出來。"}]', '{"noun":"manifestation","verb":"manifest","adjective":"manifest"}', NULL, 3, 4108, NULL),
(4109, 'manifesto', '/ˌmænɪˈfestəʊ/', 'noun', '{"zh-TW":["宣言；政綱"],"en":["a public declaration of policy and aims"]}', NULL, 'publish a manifesto / election manifesto / party manifesto', '[{"en":"The opposition party''s election manifesto promised tax cuts and public spending reform.","zh-TW":"反對黨的競選政綱承諾減稅和公共開支改革。"},{"en":"The environmental group released a manifesto calling for urgent climate action.","zh-TW":"環保團體發布了一份呼籲採取緊迫氣候行動的宣言。"}]', NULL, NULL, 3, 4109, NULL),
(4110, 'manipulate', '/məˈnɪpjuleɪt/', 'verb', '{"zh-TW":["操縱；操控"],"en":["to control or influence skillfully, often unfairly"]}', NULL, 'manipulate data/figures/people', '[{"en":"He was accused of manipulating financial data.","zh-TW":"他被指控操縱財務數據。"},{"en":"The software allows you to manipulate images easily.","zh-TW":"該軟體允許你輕鬆操作圖像。"}]', '{"noun":"manipulation, manipulator","verb":"manipulate","adjective":"manipulative"}', NULL, 4, 4110, NULL),
(4111, 'manner', '/ˈmænər/', 'noun', '{"zh-TW":["方式；態度；禮貌"],"en":["the way something is done; behavior"]}', NULL, 'in a professional manner / in this manner', '[{"en":"Please handle all complaints in a professional manner.","zh-TW":"請以專業的方式處理所有投訴。"},{"en":"His manner was calm and reassuring.","zh-TW":"他的態度冷靜而令人放心。"}]', '{"noun":"manner, manners","adjective":"mannered"}', NULL, 2, 4111, NULL),
(4112, 'manpower planning', '/ˈmænpaʊər ˈplænɪŋ/', 'noun', '{"zh-TW":["人力規劃"],"en":["the process of forecasting and meeting future staffing requirements"]}', NULL, 'conduct manpower planning / manpower planning forecast', '[{"en":"Manpower planning ensured adequate staffing for the new plant opening.","zh-TW":"人力規劃確保了新工廠開業的充足人員配置。"},{"en":"Effective manpower planning aligns recruitment with business growth projections.","zh-TW":"有效的人力規劃使招募與業務增長預測保持一致。"}]', '{"synonym":"workforce planning","synonym2":"human resource planning"}', NULL, 5, 4112, NULL),
(4113, 'manual', '/ˈmænjuəl/', 'noun, adjective', '{"zh-TW":["手冊；說明書","手動的；體力的"],"en":["a handbook; a book of instructions","done by hand; physical"]}', NULL, 'user/instruction manual / manual labor', '[{"en":"Please refer to the user manual for setup instructions.","zh-TW":"請參閱使用手冊了解安裝說明。"},{"en":"The process was switched from manual to automated.","zh-TW":"流程從手動改為自動化。"}]', '{"noun":"manual","adjective":"manual","adverb":"manually"}', NULL, 2, 4113, NULL),
(4114, 'manufacture', '/ˌmænjuˈfæktʃər/', 'verb', '{"zh-TW":["製造","製造；生產"],"en":["to make goods in large quantities by machinery","to make goods in large quantities"]}', '{"root":{"text":"manu","meaning":"hand (手)"},"suffix":{"text":"facture","meaning":"make (製造)"},"logic":"用手製造，現指大規模製造。"}', 'manufacture products / manufacturing industry; manufacture products/goods/components', '[{"en":"The company manufactures electronic components.","zh-TW":"公司製造電子零件。"},{"en":"Most of these goods are manufactured in China.","zh-TW":"這些商品大多在中國製造。"},{"en":"The company manufactures electronic components.","zh-TW":"該公司製造電子零件。"},{"en":"Most of their products are manufactured overseas.","zh-TW":"他們大部分產品都在海外製造。"}]', '{"noun":"manufacturer","noun2":"manufacturing","verb":"manufacture"}', NULL, 4, 4114, 38),
(4115, 'manuscript', '/ˈmænjuskrɪpt/', 'noun', '{"zh-TW":["手稿；原稿"],"en":["an author''s text that has not yet been published"]}', NULL, 'submit a manuscript / manuscript review', '[{"en":"The author submitted the manuscript to the publisher.","zh-TW":"作者向出版社提交了手稿。"},{"en":"The manuscript was reviewed by three experts.","zh-TW":"手稿由三位專家審閱。"}]', '{"noun":"manuscript"}', NULL, 4, 4115, NULL),
(4116, 'map', '/mæp/', 'noun', '{"zh-TW":["地圖；規劃"],"en":["a drawing of an area","to plan in detail"]}', NULL, 'road map / map out', '[{"en":"We mapped out our strategy for next year.","zh-TW":"我們規劃了明年的策略。"},{"en":"Here is the road map for the project.","zh-TW":"這是專案的路線圖。"}]', '{"noun":"map","verb":"map","noun2":"mapping"}', NULL, 1, 4116, NULL),
(4117, 'marathon', '/ˈmærəθɒn/', 'noun', '{"zh-TW":["馬拉松"],"en":["a long-distance running race of 42.195 km"]}', NULL, 'run a marathon / marathon runner', '[{"en":"She completed her first marathon.","zh-TW":"她完成了她的第一場馬拉松。"},{"en":"Training for a marathon takes months.","zh-TW":"馬拉松訓練需要數月時間。"}]', NULL, NULL, 3, 4117, NULL),
(4118, 'marbling', '/''mɑːrblɪŋ/', 'noun', '{"zh-TW":["油花；大理石紋"],"en":["the distribution of fat within meat that influences its flavor and tenderness"]}', NULL, 'good marbling / well-marbled / marbling grade', '[{"en":"Wagyu beef is prized for its exceptional marbling and rich flavor.","zh-TW":"和牛因其卓越的油花和豐富的風味而備受推崇。"},{"en":"Higher marbling in steak generally means juicier, more flavorful meat.","zh-TW":"牛排中較高的油花通常意味著更多汁、更有風味的肉質。"}]', NULL, NULL, 3, 4118, NULL),
(4119, 'margin', '/ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["邊緣；利潤率；差額"],"en":["the edge of something; the amount of profit"]}', NULL, 'profit margin / by a narrow margin / margin of error', '[{"en":"The company''s profit margin increased to 15%.","zh-TW":"公司的利潤率增至15%。"},{"en":"He won the election by a narrow margin.","zh-TW":"他以微弱的差距贏得了選舉。"}]', '{"noun":"margin","adjective":"marginal","adverb":"marginally"}', NULL, 2, 4119, 390),
(4120, 'margin call', '/ˈmɑːrdʒɪn kɔːl/', 'noun', '{"zh-TW":["追加保證金通知；補倉通知"],"en":["a demand to deposit more funds when a leveraged position falls below minimum"]}', NULL, 'receive a margin call / trigger a margin call', '[{"en":"The investor received a margin call as the stock price fell sharply.","zh-TW":"隨著股價急劇下跌，投資者收到了補倉通知。"},{"en":"Failing to meet a margin call results in forced liquidation.","zh-TW":"未能滿足補倉通知將導致強制平倉。"}]', NULL, NULL, 4, 4120, NULL),
(4121, 'margin compression', '/ˈmɑːrdʒɪn kəmˈpreʃən/', 'noun', '{"zh-TW":["利潤壓縮"],"en":["a reduction in the profit margin of a business"]}', NULL, 'experience margin compression / fight margin compression / margin compression trend', '[{"en":"Rising input costs led to significant margin compression for manufacturers.","zh-TW":"原料成本上漲導致製造商的利潤大幅壓縮。"},{"en":"Price competition often causes margin compression across industries.","zh-TW":"價格競爭往往導致行業普遍的利潤壓縮。"}]', NULL, NULL, 5, 4121, NULL),
(4122, 'marginal cost', '/ˈmɑːrdʒɪnəl kɒst/', 'noun', '{"zh-TW":["邊際成本"],"en":["the additional cost of producing one more unit of a product"]}', NULL, 'calculate marginal cost / minimize marginal cost', '[{"en":"Marginal cost decreases as production volume rises due to fixed cost spreading.","zh-TW":"由於固定成本分攤，邊際成本隨著生產量增加而降低。"},{"en":"Pricing below marginal cost is not sustainable in the long run.","zh-TW":"長期來看，定價低於邊際成本是不可持續的。"}]', '{"synonym":"incremental cost"}', NULL, 5, 4122, NULL),
(4123, 'marginalization', '/ˌmɑːrdʒɪnəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["邊緣化"],"en":["the process of treating a person or group as insignificant or peripheral"]}', NULL, 'economic marginalization / social marginalization / prevent marginalization', '[{"en":"Marginalization of minority communities perpetuates cycles of poverty.","zh-TW":"少數族裔社區的邊緣化使貧困循環持續。"},{"en":"Policy interventions aim to reverse the marginalization of rural populations.","zh-TW":"政策干預旨在逆轉農村人口的邊緣化。"}]', '{"verb":"marginalize","adjective":"marginalized"}', NULL, 5, 4123, NULL),
(4124, 'marina', '/''məˈriːnə/', 'noun', '{"zh-TW":["遊艇停泊處；小艇碼頭"],"en":["a harbor with facilities for yachts and small boats"]}', NULL, 'yacht marina / stay at a marina / marina facilities', '[{"en":"The marina could accommodate over three hundred boats.","zh-TW":"這個遊艇停泊處可以容納三百多艘船隻。"},{"en":"We dined at a restaurant overlooking the marina at sunset.","zh-TW":"我們在日落時分在俯瞰遊艇停泊處的餐廳用餐。"}]', NULL, NULL, 2, 4124, NULL),
(4125, 'marinade', '/''mærɪneɪd/', 'noun', '{"zh-TW":["醃料；醃汁"],"en":["a mixture of oil, vinegar, spices, and herbs used to flavor or tenderize food before cooking"]}', NULL, 'prepare a marinade / marinate in / spicy marinade', '[{"en":"The chicken was left in a garlic and herb marinade overnight.","zh-TW":"雞肉在大蒜和香草醃料中醃製了一夜。"},{"en":"A good marinade adds depth of flavor to grilled meats and vegetables.","zh-TW":"好的醃料為烤肉和蔬菜增添了豐富的風味。"}]', '{"verb":"marinate"}', NULL, 3, 4125, NULL),
(4126, 'marinate', '/''mærɪneɪt/', 'verb', '{"zh-TW":["醃製；浸泡醃料"],"en":["to soak food in a marinade before cooking to add flavor or tenderize"]}', NULL, 'marinate overnight / marinate for an hour / marinate in spices', '[{"en":"She marinated the tofu in soy sauce and ginger for an hour.","zh-TW":"她將豆腐在醬油和薑中醃製了一個小時。"},{"en":"Marinating the meat overnight resulted in a more tender and flavorful dish.","zh-TW":"將肉醃製一夜，使菜肴更加嫩滑和美味。"}]', '{"noun":"marinade"}', NULL, 3, 4126, NULL),
(4127, 'marine conservation', '/məˈriːn ˌkɒnsəˈveɪʃən/', 'noun', '{"zh-TW":["海洋保育"],"en":["the protection and preservation of marine ecosystems and biodiversity"]}', NULL, 'marine conservation efforts / marine conservation policy / support marine conservation', '[{"en":"Marine conservation protects fisheries and coastal communities.","zh-TW":"海洋保育保護漁業和沿海社區。"},{"en":"Establishing marine protected areas is a key marine conservation strategy.","zh-TW":"建立海洋保護區是海洋保育的關鍵策略。"}]', NULL, NULL, 5, 4127, NULL),
(4128, 'maritime', '/ˈmærɪtaɪm/', 'adjective', '{"zh-TW":["海事的；海運的"],"en":["relating to the sea or shipping"]}', NULL, 'maritime law/industry/trade', '[{"en":"Maritime trade accounts for 80% of global commerce.","zh-TW":"海運貿易佔全球商業的80%。"},{"en":"Maritime law governs shipping disputes.","zh-TW":"海事法管轄航運糾紛。"}]', '{"noun":"maritime","adjective":"maritime"}', NULL, 3, 4128, NULL),
(4129, 'mark', '/mɑːrk/', 'noun', '{"zh-TW":["【主要意義-動詞/名詞】標記；記號","【次要意義-動詞】留意；注意（尤其在命令句中）","【次要意義-名詞】成績；分數","【次要意義-動詞】紀念；標誌著（事件）"],"en":["[primary] to make a visible sign; a visible sign","[secondary - verb] to notice and remember something (especially in imperatives)","[secondary - noun] a score or grade in academic work","[secondary - verb] to commemorate; to indicate an important event"]}', NULL, 'mark my words / mark an occasion / up to the mark / on your mark / benchmark', '[{"en":"Mark my words, this policy will cause serious problems.","zh-TW":"請記住我的話，這項政策將引發嚴重問題。"},{"en":"The ceremony marks the 50th anniversary of the company.","zh-TW":"這個儀式標誌著公司成立50週年。"},{"en":"The new product launch marks a turning point in the company history.","zh-TW":"新產品的發布標誌著公司歷史的轉折點。"}]', '{"noun":"marker, marking, benchmark","adjective":"marked"}', 'mark my words（請記住我的話）、mark an occasion（紀念某場合）、marked improvement（顯著的改善）均為 TOEIC 常見用法，動詞 mark = 「標誌著/紀念」在公司周年文章中常見。', 1, 4129, NULL),
(4130, 'mark to market', '/mɑːrk tə ˈmɑːrkɪt/', 'verb', '{"zh-TW":["按市值計算；盯市"],"en":["to value an asset at its current market price rather than its book or historical cost"]}', NULL, 'mark assets to market / mark-to-market accounting / fair value mark to market', '[{"en":"Banks are required to mark their securities portfolios to market at the end of each quarter.","zh-TW":"銀行被要求在每個季度末按市值計算其證券投資組合。"},{"en":"Mark-to-market accounting caused significant volatility in reported earnings during the crisis.","zh-TW":"盯市會計在危機期間導致已報告收益出現重大波動。"}]', NULL, NULL, 5, 4130, NULL),
(4131, 'mark-to-market', '/mɑːrk tə ˈmɑːrkɪt/', 'verb', '{"zh-TW":["按市價計算；市值計算"],"en":["to revalue an asset at its current market price rather than its original cost"]}', NULL, 'mark-to-market valuation / mark-to-market accounting', '[{"en":"The portfolio is revalued daily using mark-to-market accounting.","zh-TW":"投資組合使用市值計算每日重新估值。"},{"en":"Mark-to-market accounting increases transparency but adds volatility.","zh-TW":"市值計算會計增加了透明度，但也增加了波動性。"}]', NULL, NULL, 5, 4131, NULL),
(4132, 'market', '/ˈmɑːrkɪt/', 'noun, verb', '{"zh-TW":["市場","推銷；銷售"],"en":["a place where goods are sold; demand for goods","to advertise and sell"]}', NULL, 'market share / target market / market research', '[{"en":"We need to conduct market research before launching.","zh-TW":"我們需要在推出前進行市場調查。"},{"en":"The product was successfully marketed to young professionals.","zh-TW":"該產品成功地向年輕專業人士推銷。"}]', '{"noun":"market, marketing, marketer","verb":"market","adjective":"marketable"}', NULL, 2, 4132, NULL),
(4133, 'market access', '/ˈmɑːrkɪt ˈækses/', 'noun', '{"zh-TW":["市場進入；市場准入"],"en":["the ability of a company to enter and operate in a particular market"]}', NULL, 'gain market access / restrict market access', '[{"en":"The trade deal improved market access for foreign companies.","zh-TW":"貿易協議改善了外國公司的市場准入。"},{"en":"Local partners can help provide market access in new regions.","zh-TW":"本地合作夥伴可以幫助在新地區提供市場准入。"}]', NULL, NULL, 5, 4133, NULL),
(4134, 'market analysis', '/ˈmɑːrkɪt əˈnælɪsɪs/', 'noun', '{"zh-TW":["市場分析"],"en":["a quantitative and qualitative assessment of a market"]}', NULL, 'competitive market analysis / market analysis report / conduct market analysis', '[{"en":"The market analysis identified a gap in the mid-range product segment.","zh-TW":"市場分析識別了中端產品市場的空缺。"},{"en":"Regular market analysis helps businesses stay ahead of trends.","zh-TW":"定期市場分析幫助企業保持領先趨勢。"}]', NULL, NULL, 5, 4134, NULL),
(4135, 'market capitalization', '/ˈmɑːrkɪt ˌkæpɪtlɪˈzeɪʃən/', 'noun', '{"zh-TW":["市值"],"en":["the total market value of a company''s outstanding shares"]}', NULL, 'large-cap / mid-cap / market capitalization of / calculate market cap', '[{"en":"The company''s market capitalization exceeded $100 billion.","zh-TW":"公司市值超過1000億美元。"},{"en":"Market capitalization is calculated by multiplying share price by shares outstanding.","zh-TW":"市值通過股價乘以流通股數來計算。"}]', '{"abbreviation":"market cap"}', NULL, 5, 4135, NULL),
(4136, 'market correction', '/ˈmɑːrkɪt kəˈrekʃən/', 'noun', '{"zh-TW":["市場修正；股市回調"],"en":["a decline of 10% or more in a security or market index from recent highs"]}', NULL, 'enter market correction territory / trigger a market correction', '[{"en":"The market correction wiped out gains made in the previous quarter.","zh-TW":"市場修正抹去了上一季的漲幅。"},{"en":"Analysts predicted a market correction after the rapid rally.","zh-TW":"分析師在快速上漲後預測市場將出現修正。"}]', NULL, NULL, 5, 4136, NULL),
(4137, 'market dynamics', '/ˈmɑːrkɪt daɪˈnæmɪks/', 'noun', '{"zh-TW":["市場動態"],"en":["the forces that affect supply and demand in a market"]}', NULL, 'understand market dynamics / respond to market dynamics', '[{"en":"Changing market dynamics required a shift in the company strategy.","zh-TW":"不斷變化的市場動態要求公司策略做出改變。"},{"en":"Technology is reshaping market dynamics across industries.","zh-TW":"技術正在重塑各行業的市場動態。"}]', NULL, NULL, 5, 4137, NULL),
(4138, 'market economy', '/ˈmɑːrkɪt ɪˈkɒnəmi/', 'noun', '{"zh-TW":["市場經濟"],"en":["an economic system based on supply, demand, and private ownership"]}', NULL, 'free market economy / market economy principles', '[{"en":"In a market economy, prices are determined by supply and demand.","zh-TW":"在市場經濟中，價格由供求關係決定。"},{"en":"The country transitioned to a market economy in the 1990s.","zh-TW":"該國在1990年代轉型為市場經濟。"}]', NULL, NULL, 5, 4138, NULL),
(4139, 'market entry', '/ˈmɑːrkɪt ˈentri/', 'noun', '{"zh-TW":["進入市場；市場進入"],"en":["the process of entering a new market with a product or service"]}', NULL, 'market entry strategy / market entry barriers / facilitate market entry', '[{"en":"The market entry strategy focused on partnerships with local distributors.","zh-TW":"市場進入策略側重於與當地分銷商的合作關係。"},{"en":"High capital requirements create barriers to market entry.","zh-TW":"高資本要求造成了市場進入壁壘。"}]', NULL, NULL, 4, 4139, NULL),
(4140, 'market entry barrier', '/ˈmɑːrkɪt ˈentri ˈbæriər/', 'noun', '{"zh-TW":["市場進入壁壘"],"en":["obstacles that prevent new companies from easily entering a market"]}', NULL, 'overcome market entry barriers / high market entry barriers', '[{"en":"Regulatory requirements are a significant market entry barrier in healthcare.","zh-TW":"監管要求是醫療保健領域的重大市場進入壁壘。"},{"en":"High capital requirements create market entry barriers for new competitors.","zh-TW":"高資本要求為新競爭者創造了市場進入壁壘。"}]', NULL, NULL, 5, 4140, NULL),
(4141, 'market exit', '/ˈmɑːrkɪt ˈeksɪt/', 'noun', '{"zh-TW":["退出市場"],"en":["the process of withdrawing a product or company from a market"]}', NULL, 'market exit strategy / execute a market exit', '[{"en":"The company planned an orderly market exit from underperforming regions.","zh-TW":"公司計劃從表現不佳的地區有序退出市場。"},{"en":"Market exit can release capital for more profitable ventures.","zh-TW":"退出市場可以為更有利可圖的企業釋放資金。"}]', NULL, NULL, 4, 4141, NULL),
(4142, 'market failure', '/ˈmɑːrkɪt ˈfeɪljər/', 'noun', '{"zh-TW":["市場失靈"],"en":["a situation where markets fail to allocate resources efficiently"]}', NULL, 'identify market failure / correct market failure', '[{"en":"Negative externalities are a classic example of market failure.","zh-TW":"負外部性是市場失靈的典型例子。"},{"en":"Government intervention aims to correct market failure in public goods.","zh-TW":"政府幹預旨在糾正公共物品方面的市場失靈。"}]', NULL, NULL, 5, 4142, NULL),
(4143, 'market forces', '/ˈmɑːrkɪt fɔːrsɪz/', 'noun', '{"zh-TW":["市場力量；市場機制"],"en":["natural economic pressures of supply and demand affecting prices"]}', NULL, 'respond to market forces / driven by market forces', '[{"en":"Prices are set by market forces rather than government intervention.","zh-TW":"價格由市場力量而非政府干預決定。"},{"en":"Market forces pushed down the price of smartphones significantly.","zh-TW":"市場力量顯著壓低了智慧型手機的價格。"}]', NULL, NULL, 5, 4143, NULL),
(4144, 'market forecast', '/''mɑːrkɪt ˌfɔːrkɑːst/', 'noun', '{"zh-TW":["市場預測"],"en":["a prediction of how a market will develop, typically based on trends and analysis"]}', NULL, 'prepare a market forecast / market forecast accuracy / update the market forecast', '[{"en":"Analysts revised their market forecast upward following stronger-than-expected economic data.","zh-TW":"分析師在強於預期的經濟數據公布後上調了市場預測。"},{"en":"A reliable market forecast is essential for making sound strategic investment decisions.","zh-TW":"可靠的市場預測對於做出健全的戰略投資決策至關重要。"}]', '{"verb":"forecast","noun2":"forecaster"}', NULL, 5, 4144, NULL),
(4145, 'market intelligence', '/ˈmɑːrkɪt ɪnˈtelɪdʒəns/', 'noun', '{"zh-TW":["市場情報"],"en":["information gathered about a market, its customers, and competitors"]}', NULL, 'gather market intelligence / market intelligence report', '[{"en":"Market intelligence revealed a growing demand for sustainable packaging.","zh-TW":"市場情報揭示了對可持續包裝日益增長的需求。"},{"en":"Sales teams regularly gather market intelligence from client interactions.","zh-TW":"銷售團隊定期從客戶互動中收集市場情報。"}]', NULL, NULL, 5, 4145, NULL),
(4146, 'market leader', '/ˈmɑːrkɪt ˈliːdər/', 'noun', '{"zh-TW":["市場領導者；市場龍頭"],"en":["the company with the largest share of a particular market"]}', NULL, 'become a market leader / defend market leader position', '[{"en":"The brand is the undisputed market leader in the region.","zh-TW":"該品牌是該地區無可爭議的市場領導者。"},{"en":"Being a market leader carries pricing power and brand recognition benefits.","zh-TW":"成為市場領導者帶來了定價能力和品牌認知優勢。"}]', NULL, NULL, 5, 4146, NULL),
(4147, 'market liquidity', '/ˈmɑːrkɪt lɪˈkwɪdɪti/', 'noun', '{"zh-TW":["市場流動性"],"en":["the ease with which securities can be bought and sold without affecting their price"]}', NULL, 'monitor market liquidity / improve market liquidity', '[{"en":"High market liquidity allows investors to exit positions with minimal price impact.","zh-TW":"高市場流動性允許投資者以最小的價格影響退出倉位。"},{"en":"Market liquidity dried up during the financial crisis of 2008.","zh-TW":"在2008年金融危機期間，市場流動性枯竭了。"}]', NULL, NULL, 5, 4147, NULL),
(4148, 'market maker', '/ˈmɑːrkɪt ˈmeɪkər/', 'noun', '{"zh-TW":["做市商"],"en":["a firm that actively quotes buy and sell prices to provide market liquidity"]}', NULL, 'role of market maker / market maker spread', '[{"en":"Market makers ensure continuous trading by quoting bid and ask prices.","zh-TW":"做市商通過報出買入價和賣出價確保持續交易。"},{"en":"The spread charged by a market maker is the primary source of revenue.","zh-TW":"做市商收取的差價是其主要收入來源。"}]', NULL, NULL, 4, 4148, NULL),
(4149, 'market outlook', '/ˈmɑːrkɪt ˈaʊtlʊk/', 'noun', '{"zh-TW":["市場前景"],"en":["a forecast or assessment of expected market conditions over a period"]}', NULL, 'assess market outlook / positive market outlook', '[{"en":"The analyst presented a positive market outlook for consumer goods.","zh-TW":"分析師對消費品提出了積極的市場前景。"},{"en":"A weak market outlook may delay investment decisions.","zh-TW":"疲軟的市場前景可能會推遲投資決策。"}]', NULL, NULL, 5, 4149, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4150, 'market penetration', '/ˈmɑːrkɪt ˌpɛnɪˈtreɪʃən/', 'noun', '{"zh-TW":["市場滲透"],"en":["the extent to which a product is known and used in a market"]}', NULL, 'increase market penetration / market penetration strategy', '[{"en":"The company''s goal is to increase market penetration in Asia.","zh-TW":"公司的目標是提高在亞洲的市場滲透率。"},{"en":"Competitive pricing is a common market penetration strategy.","zh-TW":"競爭性定價是常見的市場滲透策略。"}]', NULL, NULL, 5, 4150, NULL),
(4151, 'market position', '/ˈmɑːrkɪt pəˈzɪʃən/', 'noun', '{"zh-TW":["市場地位；市場定位"],"en":["a company standing in a market relative to competitors"]}', NULL, 'strengthen market position / defend market position', '[{"en":"The company strengthened its market position through innovation.","zh-TW":"公司通過創新強化了市場地位。"},{"en":"A strong market position provides pricing power and customer loyalty.","zh-TW":"強大的市場地位提供了定價能力和客戶忠誠度。"}]', NULL, NULL, 5, 4151, NULL),
(4152, 'market positioning', '/ˈmɑːrkɪt pəˈzɪʃənɪŋ/', 'noun', '{"zh-TW":["市場定位"],"en":["how a company or product is perceived relative to competitors in the market"]}', NULL, 'define market positioning / refine market positioning', '[{"en":"Clear market positioning as a premium brand justified higher prices.","zh-TW":"作為高端品牌的清晰市場定位證明了較高價格的合理性。"},{"en":"Market positioning guides all branding and communication decisions.","zh-TW":"市場定位指導了所有品牌和傳播決策。"}]', NULL, NULL, 5, 4152, NULL),
(4153, 'market research', '/ˈmɑːrkɪt rɪˈsɜːrtʃ/', 'noun', '{"zh-TW":["市場研究"],"en":["the process of gathering information about consumers and market conditions"]}', NULL, 'conduct market research / market research report / qualitative market research', '[{"en":"Market research revealed strong demand for the new product.","zh-TW":"市場研究顯示新產品有強烈需求。"},{"en":"The company invested heavily in market research before the launch.","zh-TW":"公司在上市前在市場研究上投入了大量資金。"}]', '{"verb":"research the market","noun":"market researcher"}', NULL, 5, 4153, NULL),
(4154, 'market research report', '/ˈmɑːrkɪt rɪˈsɜːrtʃ rɪˈpɔːrt/', 'noun', '{"zh-TW":["市場調研報告"],"en":["a document summarizing findings from research on a market or consumer group"]}', NULL, 'commission a market research report / market research report findings', '[{"en":"The market research report showed strong demand for eco-friendly packaging.","zh-TW":"市場調研報告顯示對環保包裝的需求強勁。"},{"en":"Market research reports inform product development and marketing strategy.","zh-TW":"市場調研報告為產品開發和行銷策略提供了信息。"}]', NULL, NULL, 5, 4154, NULL),
(4155, 'market risk', '/ˈmɑːrkɪt rɪsk/', 'noun', '{"zh-TW":["市場風險"],"en":["the risk of losses due to adverse movements in market prices or rates"]}', NULL, 'manage market risk / market risk assessment', '[{"en":"The portfolio manager hedged market risk using derivative instruments.","zh-TW":"投資組合管理人使用衍生品工具對沖市場風險。"},{"en":"Market risk includes equity risk, interest rate risk, and currency risk.","zh-TW":"市場風險包括股票風險、利率風險和貨幣風險。"}]', '{"synonym":"systematic risk"}', NULL, 4, 4155, NULL),
(4156, 'market saturation', '/ˈmɑːrkɪt ˌsætʃəˈreɪʃən/', 'noun', '{"zh-TW":["市場飽和"],"en":["when a product or service has been sold to most potential customers"]}', NULL, 'face market saturation / overcome market saturation', '[{"en":"Market saturation forced the company to look for new customer segments.","zh-TW":"市場飽和迫使公司尋找新的客戶細分。"},{"en":"Innovation can reverse market saturation by creating new demand.","zh-TW":"創新可以通過創造新需求逆轉市場飽和。"}]', NULL, NULL, 5, 4156, NULL),
(4157, 'market segment', '/ˈmɑːrkɪt ˈseɡmənt/', 'noun', '{"zh-TW":["市場區隔；細分市場"],"en":["a subgroup of consumers with similar needs or characteristics"]}', NULL, 'target a market segment / market segment analysis', '[{"en":"The company focused on the premium market segment for its new product.","zh-TW":"公司將新產品聚焦在高端市場區隔。"},{"en":"Identifying the right market segment improves marketing ROI.","zh-TW":"識別正確的市場區隔改善了行銷投資回報率。"}]', NULL, NULL, 5, 4157, NULL),
(4158, 'market segmentation', '/ˈmɑːrkɪt ˌseɡmənˈteɪʃən/', 'noun', '{"zh-TW":["市場細分"],"en":["dividing a market into distinct groups with similar needs or characteristics"]}', NULL, 'demographic segmentation / psychographic segmentation / target market segmentation', '[{"en":"Market segmentation helped the company tailor its messaging.","zh-TW":"市場細分幫助公司量身訂製其訊息傳遞。"},{"en":"Geographic market segmentation drives localized marketing strategies.","zh-TW":"地理市場細分推動了本地化行銷策略。"}]', '{"verb":"segment","adjective":"segmented"}', NULL, 5, 4158, NULL),
(4159, 'market share', '/ˈmɑːrkɪt ʃeər/', 'noun', '{"zh-TW":["市場份額"],"en":["the portion of a market controlled by a particular company or product"]}', NULL, 'increase market share / lose market share / dominant market share', '[{"en":"The company gained market share by reducing prices.","zh-TW":"公司通過降低價格獲得了市場份額。"},{"en":"Their market share rose to 35% following the acquisition.","zh-TW":"收購後，他們的市場份額上升至35%。"}]', '{"verb":"capture market share"}', NULL, 4, 4159, NULL),
(4160, 'market share analysis', '/ˈmɑːrkɪt ʃeər əˈnæləsɪs/', 'noun', '{"zh-TW":["市場份額分析"],"en":["assessing a company percentage of total market sales"]}', NULL, 'conduct a market share analysis / market share analysis report', '[{"en":"The market share analysis showed a 5% gain over competitors.","zh-TW":"市場份額分析顯示比競爭對手增加了5%。"},{"en":"Annual market share analysis tracks competitive trends over time.","zh-TW":"年度市場份額分析追蹤競爭趨勢。"}]', NULL, NULL, 5, 4160, NULL),
(4161, 'market share growth', '/ˈmɑːrkɪt ʃeər ɡroʊθ/', 'noun', '{"zh-TW":["市場份額增長"],"en":["an increase in the percentage of total market sales captured by a company"]}', NULL, 'achieve market share growth / market share growth strategy', '[{"en":"Aggressive pricing contributed to significant market share growth.","zh-TW":"激進的定價促成了顯著的市場份額增長。"},{"en":"Market share growth is a key metric for assessing competitive success.","zh-TW":"市場份額增長是評估競爭成功的關鍵指標。"}]', NULL, NULL, 5, 4161, NULL),
(4162, 'market trend', '/ˈmɑːrkɪt trend/', 'noun', '{"zh-TW":["市場趨勢"],"en":["the general direction in which a market is moving over time"]}', NULL, 'identify market trends / follow market trends / emerging market trends', '[{"en":"The market trend toward sustainability is reshaping consumer preferences.","zh-TW":"向永續性轉變的市場趨勢正在重塑消費者偏好。"},{"en":"Analysts track market trends to forecast future demand.","zh-TW":"分析師追蹤市場趨勢以預測未來需求。"}]', '{"plural":"market trends"}', NULL, 4, 4162, NULL),
(4163, 'market valuation', '/ˈmɑːrkɪt ˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["市值估算；市場估值"],"en":["an estimate of a company worth based on current market data"]}', NULL, 'assess market valuation / market valuation method', '[{"en":"The company market valuation doubled after the product launch.","zh-TW":"產品發佈後，公司市值估算翻了一倍。"},{"en":"Market valuation is used in M&A negotiations to set deal pricing.","zh-TW":"市場估值用於併購談判以設定交易定價。"}]', NULL, NULL, 5, 4163, NULL),
(4164, 'market value', '/''mɑːrkɪt ˌvæljuː/', 'noun', '{"zh-TW":["市場價值；市場估值"],"en":["the estimated amount for which a property should be bought or sold on the open market"]}', NULL, 'assess market value / determine market value / below market value', '[{"en":"The house sold for significantly above its assessed market value.","zh-TW":"房子的售價遠高於其評估的市場價值。"},{"en":"Properties near good schools typically have a higher market value.","zh-TW":"靠近好學校的房產通常具有更高的市場價值。"}]', NULL, NULL, 4, 4164, NULL),
(4165, 'marketing automation', '/ˈmɑːrkɪtɪŋ ˌɔːtəˈmeɪʃən/', 'noun', '{"zh-TW":["行銷自動化"],"en":["using software to automate repetitive marketing tasks"]}', NULL, 'marketing automation platform / implement marketing automation', '[{"en":"Marketing automation streamlines lead nurturing campaigns.","zh-TW":"行銷自動化簡化了潛在客戶培育活動。"},{"en":"The team uses marketing automation to send personalized emails at scale.","zh-TW":"團隊使用行銷自動化大規模發送個人化電子郵件。"}]', '{"verb":"automate marketing"}', NULL, 5, 4165, NULL),
(4166, 'marketing mix', '/ˈmɑːrkɪtɪŋ mɪks/', 'noun', '{"zh-TW":["行銷組合"],"en":["the combination of factors used to market a product"]}', NULL, 'develop a marketing mix / marketing mix strategy', '[{"en":"The classic marketing mix includes product, price, place, and promotion.","zh-TW":"傳統的行銷組合包括產品、價格、通路和促銷。"},{"en":"An effective marketing mix drives both sales and brand awareness.","zh-TW":"有效的行銷組合同時推動了銷售和品牌知名度。"}]', NULL, NULL, 5, 4166, NULL),
(4167, 'markup', '/ˈmɑːrkʌp/', 'noun', '{"zh-TW":["加價；標記"],"en":["the amount added to cost price for profit"]}', NULL, 'price markup / markup percentage', '[{"en":"Retailers typically apply a 50% markup on wholesale prices.","zh-TW":"零售商通常在批發價上加價50%。"},{"en":"The markup on luxury goods is significantly higher.","zh-TW":"奢侈品的加價幅度明顯更高。"}]', '{"noun":"markup","verb":"mark up"}', NULL, 2, 4167, NULL),
(4168, 'marry', '/ˈmæri/', 'verb', '{"zh-TW":["結婚"],"en":["to become the spouse of someone"]}', NULL, 'get married / married life', '[{"en":"They got married last summer.","zh-TW":"他們去年夏天結婚了。"},{"en":"She is married with two children.","zh-TW":"她已婚並育有兩個孩子。"}]', '{"verb":"marry","noun":"marriage","adjective":"married","adjective2":"unmarried"}', NULL, 2, 4168, NULL),
(4169, 'massive', '/ˈmæsɪv/', 'adjective', '{"zh-TW":["大量的；巨大的"],"en":["extremely large or serious"]}', NULL, 'massive investment/growth/change', '[{"en":"The project requires a massive investment.","zh-TW":"該項目需要大量投資。"},{"en":"There has been massive growth in online shopping.","zh-TW":"網上購物出現了大幅增長。"}]', '{"noun":"mass","adjective":"massive","adverb":"massively"}', NULL, 3, 4169, NULL),
(4170, 'master', '/ˈmæstər/', 'noun, verb, adjective', '{"zh-TW":["【主要意義-名詞】主人；碩士","【次要意義-動詞】精通；掌握（技能）","【次要意義-形容詞】主要的；最終版本的（文件）","【次要意義-名詞】原版；母片"],"en":["[primary - noun] a person with great skill or authority","[secondary - verb] to become skilled at something through practice","[secondary - adjective] relating to the main or original version of something","[secondary - noun] an original recording or document"]}', NULL, 'master plan / master copy / master a skill / master key', '[{"en":"It takes years of practice to master the art of negotiation.","zh-TW":"掌握談判藝術需要多年的練習。"},{"en":"Please send the master copy of the contract to the legal department.","zh-TW":"請將合約的原版副本發送至法律部門。"},{"en":"The company revealed its master plan for expansion into Southeast Asia.","zh-TW":"公司公布了其向東南亞擴張的總體計劃。"}]', '{"noun":"masterpiece, mastery","adjective":"masterful"}', '動詞 master = 「精通/掌握」是高頻用法；master plan（總體計劃）、master copy（原版）、master key（萬能鑰匙）均是 TOEIC 商業和管理文章常見搭配。', 2, 4170, NULL),
(4171, 'master agreement', '/ˈmɑːstər əˈɡriːmənt/', 'noun', '{"zh-TW":["主協議；框架協議"],"en":["an overarching contract governing a business relationship with multiple transactions"]}', NULL, 'sign a master agreement / operate under a master agreement', '[{"en":"The two parties signed a master agreement to govern all future transactions.","zh-TW":"雙方簽署了管理所有未來交易的主協議。"},{"en":"A master agreement simplifies individual transaction documentation.","zh-TW":"主協議簡化了個別交易的文件。"}]', NULL, NULL, 5, 4171, NULL),
(4172, 'master budget', '/ˈmɑːstər ˈbʌdʒɪt/', 'noun', '{"zh-TW":["主預算"],"en":["the comprehensive annual plan integrating all departmental budgets"]}', NULL, 'prepare the master budget / approve the master budget', '[{"en":"The master budget was finalized after each department submitted its budget.","zh-TW":"各部門提交預算後，主預算得以定稿。"},{"en":"The master budget serves as the financial roadmap for the entire year.","zh-TW":"主預算為全年提供了財務路線圖。"}]', NULL, NULL, 5, 4172, NULL),
(4173, 'master franchise', '/ˈmɑːstər ˈfrænʃaɪz/', 'noun', '{"zh-TW":["總特許經營權"],"en":["an arrangement granting a franchisee the right to sub-franchise in a territory"]}', NULL, 'grant a master franchise / master franchise agreement', '[{"en":"The company awarded a master franchise for the Middle East region.","zh-TW":"公司授予了中東地區的總特許經營權。"},{"en":"Master franchise holders are responsible for supporting sub-franchisees.","zh-TW":"總特許經營權持有人負責支援子加盟商。"}]', NULL, NULL, 5, 4173, NULL),
(4174, 'master of ceremonies', '/ˈmɑːstər əv ˈsɛrɪməniːz/', 'noun', '{"zh-TW":["司儀；主持人"],"en":["a person who oversees a formal event or ceremony"]}', NULL, 'act as master of ceremonies / experienced master of ceremonies', '[{"en":"The master of ceremonies welcomed the guests and introduced speakers.","zh-TW":"司儀歡迎了賓客並介紹了演講者。"},{"en":"She was chosen as master of ceremonies for the awards dinner.","zh-TW":"她被選為頒獎晚宴的司儀。"}]', '{"abbreviation":"MC"}', NULL, 5, 4174, NULL),
(4175, 'master service agreement', '/ˈmɑːstər ˈsɜːrvɪs əˈɡriːmənt/', 'noun', '{"zh-TW":["主服務協議"],"en":["a contract establishing the general terms governing a business relationship"]}', NULL, 'sign a master service agreement / master service agreement template', '[{"en":"The master service agreement covered all future projects between the two firms.","zh-TW":"主服務協議涵蓋了兩家公司之間所有未來的項目。"},{"en":"Individual project scopes are added as appendices to the master service agreement.","zh-TW":"個別項目範圍作為附件添加到主服務協議中。"}]', '{"abbreviation":"MSA"}', NULL, 5, 4175, NULL),
(4176, 'masterpiece', '/ˈmæstərpiːs/', 'noun', '{"zh-TW":["傑作"],"en":["a work of outstanding artistry or skill"]}', '{"root":{"text":"master","meaning":"master (大師)"},"suffix":{"text":"piece","meaning":"piece/work (作品)"},"logic":"大師的作品，即「傑作」。"}', 'literary masterpiece / create a masterpiece', '[{"en":"The Mona Lisa is considered a masterpiece.","zh-TW":"蒙娜麗莎被視為傑作。"},{"en":"This novel is his greatest masterpiece.","zh-TW":"這部小說是他最偉大的傑作。"}]', NULL, NULL, 4, 4176, NULL),
(4177, 'match', '/mætʃ/', 'verb', '{"zh-TW":["匹配；比賽"],"en":["to be equal to","a contest"]}', NULL, 'perfect match / match up', '[{"en":"We need a candidate who matches the job requirements.","zh-TW":"我們需要一位符合工作要求的候選人。"},{"en":"Her skills are a perfect match for the role.","zh-TW":"她的技能與這個職位完美匹配。"}]', '{"verb":"match","noun":"match","adjective":"matching"}', NULL, 2, 4177, NULL),
(4178, 'material', '/məˈtɪriəl/', 'noun, adjective', '{"zh-TW":["材料；物質","重要的；物質的"],"en":["the substance things are made from","significant; relating to physical things"]}', NULL, 'raw material / reading material / material change', '[{"en":"The cost of raw materials has risen sharply.","zh-TW":"原材料成本大幅上升。"},{"en":"There has been no material change in our financial position.","zh-TW":"我們的財務狀況沒有重大變化。"}]', '{"noun":"material, materialism","adjective":"material","adverb":"materially"}', NULL, 3, 4178, 391),
(4179, 'material breach', '/məˈtɪəriəl briːtʃ/', 'noun', '{"zh-TW":["實質性違約"],"en":["a serious violation of a contract that undermines its purpose"]}', NULL, 'commit a material breach / remedy a material breach', '[{"en":"A material breach entitles the other party to terminate the contract.","zh-TW":"實質性違約賦予另一方終止合約的權利。"},{"en":"The delayed payment was deemed a material breach.","zh-TW":"延遲付款被認定為實質性違約。"}]', NULL, NULL, 5, 4179, NULL),
(4180, 'material cost', '/məˈtɪəriəl kɒst/', 'noun', '{"zh-TW":["材料成本"],"en":["the cost of raw materials or components used in production"]}', NULL, 'manage material costs / reduce material costs', '[{"en":"Rising material costs were offset by efficiency gains.","zh-TW":"上漲的材料成本被效率提升所抵消。"},{"en":"Material costs represent 40% of the total production cost.","zh-TW":"材料成本占總生產成本的40%。"}]', NULL, NULL, 5, 4180, NULL),
(4181, 'material information', '/məˈtɪəriəl ˌɪnfəˈmeɪʃən/', 'noun', '{"zh-TW":["重大信息；重要信息"],"en":["information that could reasonably influence an investor''s decision"]}', NULL, 'disclose material information / material information obligation', '[{"en":"Listed companies must disclose material information without delay.","zh-TW":"上市公司必須毫不延遲地披露重大信息。"},{"en":"Withholding material information from investors may violate securities law.","zh-TW":"對投資者隱瞞重大信息可能違反證券法。"}]', NULL, NULL, 5, 4181, NULL),
(4182, 'materiality', '/məˌtɪəriˈæləti/', 'noun', '{"zh-TW":["重大性；重要性"],"en":["the significance of information in relation to financial decisions"]}', NULL, 'assess materiality / materiality threshold', '[{"en":"The auditor determined the materiality threshold at 1% of revenue.","zh-TW":"審計師將重大性門檻確定為收入的1%。"},{"en":"Materiality determines what information must be disclosed in accounts.","zh-TW":"重大性決定了帳目中必須披露的資訊。"}]', '{"adjective":"material","adverb":"materially"}', NULL, 4, 4182, NULL),
(4183, 'materiality threshold', '/məˌtɪəriˈælɪti ˈθreʃhoʊld/', 'noun', '{"zh-TW":["重要性門檻"],"en":["the level at which an omission or misstatement would influence a financial decision"]}', NULL, 'set a materiality threshold / below the materiality threshold', '[{"en":"The auditor set a materiality threshold of 5% of pre-tax income.","zh-TW":"審計師設定了稅前收入5%的重要性門檻。"},{"en":"Errors below the materiality threshold do not require correction.","zh-TW":"低於重要性門檻的錯誤不需要更正。"}]', NULL, NULL, 5, 4183, NULL),
(4184, 'maternity leave', '/məˈtɜːrnɪti liːv/', 'noun', '{"zh-TW":["產假"],"en":["paid or unpaid time off granted to mothers before and after childbirth"]}', NULL, 'take maternity leave / paid maternity leave / return from maternity leave', '[{"en":"She took 12 weeks of paid maternity leave after her baby was born.","zh-TW":"孩子出生後，她休了12週的有薪產假。"},{"en":"The company extended maternity leave to 26 weeks.","zh-TW":"公司將產假延長至26週。"}]', NULL, NULL, 5, 4184, NULL),
(4185, 'matrix', '/ˈmeɪtrɪks/', 'noun', '{"zh-TW":["矩陣；基質"],"en":["a grid arrangement; an environment in which something develops"]}', NULL, 'decision matrix / risk matrix / matrix organization', '[{"en":"We used a decision matrix to evaluate options.","zh-TW":"我們使用決策矩陣來評估選項。"},{"en":"The company operates under a matrix structure.","zh-TW":"公司以矩陣結構運作。"}]', '{"noun":"matrix"}', NULL, 2, 4185, NULL),
(4186, 'matrix management', '/ˈmeɪtrɪks ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["矩陣式管理"],"en":["a management structure where employees report to multiple managers"]}', NULL, 'work in a matrix management structure / benefits of matrix management', '[{"en":"Matrix management enables flexible resource sharing across projects.","zh-TW":"矩陣式管理實現了跨項目的靈活資源共享。"},{"en":"Clear communication is essential in a matrix management environment.","zh-TW":"在矩陣式管理環境中，清晰的溝通至關重要。"}]', NULL, NULL, 5, 4186, NULL),
(4187, 'matrix organization', '/ˈmeɪtrɪks ˌɔːrɡənəˈzeɪʃən/', 'noun', '{"zh-TW":["矩陣式組織"],"en":["an organizational structure with dual reporting relationships"]}', NULL, 'matrix organization structure / work in a matrix organization', '[{"en":"A matrix organization allows employees to report to both functional and project managers.","zh-TW":"矩陣式組織允許員工同時向職能和項目經理匯報。"},{"en":"Navigating a matrix organization requires strong communication skills.","zh-TW":"在矩陣式組織中運作需要強大的溝通技巧。"}]', NULL, NULL, 5, 4187, NULL),
(4188, 'matter', '/ˈmætər/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】事情；物質；問題","【次要意義-動詞】重要；有關係；有影響"],"en":["[primary - noun] a subject or situation; physical substance","[secondary - verb] to be important or significant"]}', NULL, 'it matters / matter of fact / no matter what / as a matter of course', '[{"en":"It matters a great deal how we communicate with our clients.","zh-TW":"我們與客戶的溝通方式非常重要。"},{"en":"As a matter of policy, all complaints must be addressed within 48 hours.","zh-TW":"按照慣例，所有投訴必須在48小時內處理。"},{"en":"The timing of the announcement matters more than its content.","zh-TW":"公告的時機比其內容更為重要。"}]', '{"adjective":"immaterial"}', '動詞 matter = 「重要/有意義」，常見句型 it matters that.../ what matters is...，片語 as a matter of + noun（作為……事項）是 TOEIC 商業文章常見正式表達。', 2, 4188, NULL),
(4189, 'mature', '/məˈtʃʊr/', 'adjective, verb', '{"zh-TW":["成熟的","到期；成熟"],"en":["fully developed; sensible","to reach full development; (of investments) to reach payment date"]}', NULL, 'mature market/industry / bond matures', '[{"en":"The market has matured and growth is slowing.","zh-TW":"市場已經成熟，增長正在放緩。"},{"en":"The bond matures in five years.","zh-TW":"債券五年後到期。"}]', '{"noun":"maturity","adjective":"mature","verb":"mature"}', NULL, 2, 4189, NULL),
(4190, 'mature student', '/''mətʃʊər ˌstjuːdənt/', 'noun', '{"zh-TW":["成熟學生；成年學生"],"en":["a student who is older than the typical university entry age, usually 21 or over"]}', NULL, 'support mature students / mature student experience / apply as a mature student', '[{"en":"As a mature student, she brought valuable work experience to the classroom.","zh-TW":"作為成熟學生，她為課堂帶來了寶貴的工作經驗。"},{"en":"Mature students often perform exceptionally well due to their high motivation.","zh-TW":"成熟學生往往因高度積極性而表現出色。"}]', NULL, NULL, 5, 4190, NULL),
(4191, 'maturity', '/məˈtʃʊərɪti/', 'noun', '{"zh-TW":["到期日；成熟"],"en":["the date on which a financial obligation becomes due; the state of being fully developed"]}', NULL, 'bond maturity / at maturity / maturity date', '[{"en":"Bondholders receive the principal at the bond''s maturity date.","zh-TW":"債券持有人在債券到期日收回本金。"},{"en":"The project reached maturity after years of development and investment.","zh-TW":"這個項目在多年的發展和投資後進入了成熟階段。"}]', '{"adjective":"mature","verb":"mature"}', NULL, 3, 4191, NULL),
(4192, 'maturity date', '/məˈtjʊərɪti deɪt/', 'noun', '{"zh-TW":["到期日；期滿日"],"en":["the date when a bond or loan becomes due and payable in full"]}', NULL, 'bond maturity date / loan maturity date', '[{"en":"The bond reaches its maturity date on December 31.","zh-TW":"債券在12月31日到達到期日。"},{"en":"The company planned to refinance the debt before its maturity date.","zh-TW":"公司計劃在到期日前對債務進行再融資。"}]', NULL, NULL, 5, 4192, NULL),
(4193, 'maturity mismatch', '/məˈtʃʊərɪti ˈmɪsmætʃ/', 'noun', '{"zh-TW":["期限錯配"],"en":["the difference between the maturities of a bank''s assets and liabilities"]}', NULL, 'address maturity mismatch / maturity mismatch risk / solve the maturity mismatch', '[{"en":"A maturity mismatch between short-term deposits and long-term loans can cause bank runs.","zh-TW":"短期存款和長期貸款之間的期限錯配可能導致銀行擠兌。"},{"en":"Regulators monitor maturity mismatch to ensure banks can meet withdrawal demands.","zh-TW":"監管機構監控期限錯配，以確保銀行能夠滿足提款需求。"}]', NULL, NULL, 5, 4193, NULL),
(4194, 'maximization of profit', '/ˌmæksɪmaɪˈzeɪʃən əv ˈprɒfɪt/', 'noun', '{"zh-TW":["利潤最大化"],"en":["the goal of a firm to achieve the highest possible profit"]}', NULL, 'focus on maximization of profit / profit maximization objective', '[{"en":"Shareholders expect management to pursue maximization of profit.","zh-TW":"股東期望管理層追求利潤最大化。"},{"en":"Maximization of profit must be balanced against long-term sustainability.","zh-TW":"利潤最大化必須與長期可持續性相平衡。"}]', NULL, NULL, 5, 4194, NULL),
(4195, 'maximize', '/ˈmæksɪmaɪz/', 'verb', '{"zh-TW":["最大化；充分利用"],"en":["to make as large or great as possible"]}', NULL, 'maximize profit/efficiency/potential', '[{"en":"We aim to maximize shareholder value.","zh-TW":"我們的目標是最大化股東價值。"},{"en":"How can we maximize the use of our resources?","zh-TW":"我們如何才能最大限度地利用資源？"}]', '{"noun":"maximum","verb":"maximize","adjective":"maximum"}', NULL, 3, 4195, 153),
(4196, 'maximum', 'ˈmæksɪməm', 'noun', '{"zh-TW":["最大值；最大量","極限"],"en":["the greatest possible amount","an upper limit"]}', NULL, 'maximum capacity/at maximum', '[{"en":"We are at maximum production capacity.","zh-TW":"我們處於最大生產能力。"}]', '{"adjective":"maximum","adverb":"maximally"}', NULL, 3, 4196, 392),
(4197, 'maître d''', '/ˌmeɪtrə ˈdiː/', 'noun', '{"zh-TW":["餐廳領班；接待長"],"en":["the head waiter of a restaurant"]}', NULL, 'ask the maître d'' / experienced maître d''', '[{"en":"The maître d'' escorted us to our reserved table.","zh-TW":"領班帶領我們到預訂的桌位。"},{"en":"The maître d'' ensured every guest was well taken care of.","zh-TW":"領班確保每位賓客都得到妥善照顧。"}]', NULL, NULL, 3, 4197, NULL),
(4198, 'meager', '/''miːɡər/', 'adjective', '{"zh-TW":["微薄的；不足的"],"en":["lacking in quantity or quality; insufficient"]}', NULL, 'meager salary / meager resources / meager return', '[{"en":"The startup survived on meager funding in its first year of operation.","zh-TW":"這家新創公司在第一年運營中靠著微薄的資金生存下來。"},{"en":"Despite meager resources, the team produced an impressive result.","zh-TW":"儘管資源匱乏，團隊仍產生了令人印象深刻的成果。"}]', '{"adverb":"meagerly","noun":"meagerness"}', NULL, 2, 4198, NULL),
(4199, 'meal', '/miːl/', 'noun', '{"zh-TW":["一餐；膳食"],"en":["food eaten at a particular time"]}', NULL, 'meal allowance / business meal', '[{"en":"Employees receive a meal allowance.","zh-TW":"員工有餐費補貼。"},{"en":"Business meals are tax-deductible.","zh-TW":"商務餐費可以扣稅。"}]', '{"noun":"meal"}', NULL, 1, 4199, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4200, 'meal prep', '/''miːl prep/', 'noun', '{"zh-TW":["備餐；預先備料"],"en":["the practice of preparing meals or components of meals in advance to save time during the week"]}', NULL, 'weekly meal prep / meal prep routine / batch meal prep', '[{"en":"She dedicates Sunday afternoons to meal prep for the entire week.","zh-TW":"她每個星期天下午都用來為整個星期備餐。"},{"en":"Meal prep helps people eat healthier by reducing the temptation of fast food.","zh-TW":"備餐通過減少快餐的誘惑幫助人們吃得更健康。"}]', NULL, NULL, 3, 4200, NULL),
(4201, 'mean', '/miːn/', 'verb', '{"zh-TW":["【主要意義-動詞】意味著；表示","【次要意義-形容詞】低賤的；吝嗇的；惡劣的；殘忍的","【次要意義-名詞（數學）】平均數；中間值","【次要意義-形容詞】出色的；高超的（非正式）"],"en":["[primary - verb] to signify or indicate something","[secondary - adjective] unkind or cruel; unwilling to give","[secondary - noun] a middle point or average value","[secondary - adjective] (informal) excellent or skillful"]}', NULL, 'mean business / by no means / means of communication / golden mean', '[{"en":"The new director means business and has already implemented major changes.","zh-TW":"新主任是認真的，已經實施了重大改革。"},{"en":"This is by no means a simple task and requires expert guidance.","zh-TW":"這絕非一項簡單的任務，需要專家指導。"},{"en":"The mean salary in the sector increased by 5 percent last year.","zh-TW":"該行業的平均薪資去年增加了5%。"}]', '{"noun":"meaning, means","adjective":"meaningful"}', 'mean business（認真對待）、by no means（絕不）、means（方法/手段）是 TOEIC 高頻表達；形容詞 mean = 「吝嗇的/惡劣的」，名詞 mean = 「平均值」均是次要意義陷阱。', 1, 4201, NULL),
(4202, 'mean reversion', '/miːn rɪˈvɜːrʃən/', 'noun', '{"zh-TW":["均值回歸"],"en":["the tendency of financial metrics to return toward their long-run average"]}', NULL, 'mean reversion strategy / test for mean reversion / evidence of mean reversion', '[{"en":"Mean reversion suggests that extreme performance is unlikely to persist.","zh-TW":"均值回歸表明極端業績不可能持續。"},{"en":"Value investors rely on mean reversion to justify buying undervalued assets.","zh-TW":"價值投資者依靠均值回歸來支持購買被低估資產的決策。"}]', NULL, NULL, 5, 4202, NULL),
(4203, 'meaning', 'ˈmiːnɪŋ', 'noun', '{"zh-TW":["意義；含義","目的"],"en":["what something represents","the importance of something"]}', NULL, 'hidden meaning/double meaning', '[{"en":"What is the meaning of this abbreviation?","zh-TW":"這個縮寫的含義是什麼？"}]', '{"verb":"mean","adjective":"meaningful, meaningless","adverb":"meaningfully"}', NULL, 3, 4203, NULL),
(4204, 'means-tested', '/miːnz test/', 'adjective', '{"zh-TW":["依收入審查的"],"en":["eligibility for which depends on the claimant''s income and assets"]}', NULL, 'means-tested benefit / means-tested welfare / means-tested program', '[{"en":"Means-tested benefits ensure that government aid reaches those most in need.","zh-TW":"依收入審查的福利確保政府援助惠及最需要的人。"},{"en":"Critics argue that means-tested programs create stigma and reduce take-up.","zh-TW":"批評者認為，依收入審查的計畫會產生污名化並降低申請率。"}]', NULL, NULL, 4, 4204, NULL),
(4205, 'measurable', 'ˈmɛʒərəbəl', 'adjective', '{"zh-TW":["可衡量的；可測量的","有具體結果的"],"en":["able to be measured","quantifiable"]}', NULL, 'measurable results/measurable goals', '[{"en":"Set measurable goals for each quarter.","zh-TW":"為每個季度設定可衡量的目標。"}]', '{"verb":"measure","noun":"measurement","adverb":"measurably"}', NULL, 4, 4205, NULL),
(4206, 'measure', '/ˈmeʒər/', 'noun, verb', '{"zh-TW":["措施；測量","測量；衡量"],"en":["an action taken to achieve a purpose; size or amount","to find the size or amount of something"]}', NULL, 'take measures / safety measures / measure performance', '[{"en":"The government took measures to reduce pollution.","zh-TW":"政府採取了減少污染的措施。"},{"en":"We need to measure the effectiveness of the campaign.","zh-TW":"我們需要衡量這次活動的效果。"}]', '{"noun":"measure, measurement","verb":"measure","adjective":"measurable"}', NULL, 3, 4206, 154),
(4207, 'mechanism', '/ˈmekənɪzəm/', 'noun', '{"zh-TW":["機制；機構"],"en":["a system of parts working together; a process"]}', NULL, 'feedback mechanism / pricing mechanism / defense mechanism', '[{"en":"We need a mechanism for handling complaints.","zh-TW":"我們需要一套處理投訴的機制。"},{"en":"The pricing mechanism is determined by supply and demand.","zh-TW":"定價機制由供需決定。"}]', '{"noun":"mechanism","adjective":"mechanical","verb":"mechanize"}', NULL, 3, 4207, NULL),
(4208, 'medal', '/ˈmɛdəl/', 'noun', '{"zh-TW":["獎牌"],"en":["a flat piece of metal given as a prize"]}', NULL, 'gold medal / win a medal', '[{"en":"She won a gold medal at the Olympics.","zh-TW":"她在奧運會上贏得了金牌。"},{"en":"The team brought home three medals.","zh-TW":"隊伍帶回了三面獎牌。"}]', '{"noun2":"medalist"}', NULL, 2, 4208, NULL),
(4209, 'medalist', '/''medəlɪst/', 'noun', '{"zh-TW":["獎牌得主；獲獎者"],"en":["a person who has been awarded a medal, especially in a sporting event"]}', NULL, 'Olympic medalist / gold medalist / defending medalist', '[{"en":"The gold medalist was welcomed home with a parade.","zh-TW":"金牌得主以遊行的方式受到了家鄉的歡迎。"},{"en":"She is a three-time Olympic medalist in the long jump.","zh-TW":"她是跳遠項目的三屆奧運獎牌得主。"}]', '{"noun":"medal"}', NULL, 3, 4209, NULL),
(4210, 'media', '/ˈmiːdiə/', 'noun', '{"zh-TW":["媒體"],"en":["the main means of mass communication"]}', NULL, 'social media / media coverage / media outlet', '[{"en":"Social media has transformed how companies market products.","zh-TW":"社群媒體改變了公司行銷產品的方式。"},{"en":"The event received extensive media coverage.","zh-TW":"這個活動獲得了廣泛的媒體報導。"}]', '{"noun":"media, medium","adjective":"medial"}', NULL, 2, 4210, 393),
(4211, 'media literacy', '/ˈmiːdiə ˈlɪtərəsi/', 'noun', '{"zh-TW":["媒體素養"],"en":["the ability to critically evaluate and create media content"]}', NULL, 'promote media literacy / media literacy skills / media literacy education', '[{"en":"Media literacy education helps students identify misinformation.","zh-TW":"媒體素養教育幫助學生識別錯誤資訊。"},{"en":"Low media literacy makes populations vulnerable to propaganda.","zh-TW":"低媒體素養使民眾容易受到宣傳的影響。"}]', '{"adjective":"media-literate"}', NULL, 5, 4211, NULL),
(4212, 'media training', '/''miːdiə ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["媒體培訓；媒體訓練"],"en":["coaching that prepares individuals for interviews, press conferences, and other media interactions"]}', NULL, 'receive media training / media training workshop / benefit of media training', '[{"en":"The new spokesperson received extensive media training before her first interview.","zh-TW":"新發言人在她的第一次採訪前接受了廣泛的媒體培訓。"},{"en":"Media training teaches executives how to deliver clear messages under pressure.","zh-TW":"媒體培訓教導高管如何在壓力下傳達清晰的信息。"}]', NULL, NULL, 5, 4212, NULL),
(4213, 'mediate', '/ˈmiːdieɪt/', 'verb', '{"zh-TW":["調解；斡旋"],"en":["to try to end a disagreement between parties"]}', NULL, 'mediate a dispute / mediate between', '[{"en":"A neutral party was brought in to mediate the dispute.","zh-TW":"引入了中立方來調解爭端。"},{"en":"She mediated between management and the union.","zh-TW":"她在管理層和工會之間進行調解。"}]', '{"noun":"mediation, mediator","verb":"mediate"}', NULL, 3, 4213, NULL),
(4214, 'mediation', '/ˌmiːdiˈeɪʃən/', 'noun', '{"zh-TW":["調解；斡旋"],"en":["a process where a neutral party helps resolve a dispute"]}', NULL, 'go to mediation / mediation process / employment mediation', '[{"en":"Mediation resolved the contract dispute without litigation.","zh-TW":"調解解決了合同糾紛，無需訴訟。"},{"en":"Both parties agreed to enter mediation to settle their differences.","zh-TW":"雙方同意進行調解以解決分歧。"}]', '{"verb":"mediate","noun":"mediator"}', NULL, 3, 4214, NULL),
(4215, 'mediator', '/ˈmiːdieɪtər/', 'noun', '{"zh-TW":["調解人；仲裁者"],"en":["a neutral party who helps resolve a dispute between two or more parties"]}', NULL, 'appoint a mediator / role of the mediator', '[{"en":"Both companies agreed to use a mediator to settle the contract dispute.","zh-TW":"兩家公司同意使用調解人解決合約糾紛。"},{"en":"A skilled mediator can prevent costly litigation.","zh-TW":"熟練的調解人可以防止代價高昂的訴訟。"}]', '{"verb":"mediate","noun2":"mediation"}', NULL, 3, 4215, NULL),
(4216, 'medical history', '/ˈmɛdɪkəl ˈhɪstəri/', 'noun', '{"zh-TW":["病史；醫療史"],"en":["a record of a person''s past medical conditions"]}', NULL, 'provide medical history / review medical history', '[{"en":"The doctor reviewed her medical history before the examination.","zh-TW":"醫生在檢查前查看了她的病史。"},{"en":"Always bring your medical history when seeing a new doctor.","zh-TW":"看新醫生時務必攜帶您的病史。"}]', NULL, NULL, 5, 4216, NULL),
(4217, 'medical insurance', '/ˈmɛdɪkəl ɪnˈʃʊərəns/', 'noun', '{"zh-TW":["醫療保險"],"en":["insurance that covers the cost of medical treatment"]}', NULL, 'apply for medical insurance / medical insurance plan', '[{"en":"Medical insurance helps cover the cost of unexpected health issues.","zh-TW":"醫療保險有助於支付意外健康問題的費用。"},{"en":"The company provides comprehensive medical insurance for all employees.","zh-TW":"公司為所有員工提供全面的醫療保險。"}]', NULL, NULL, 5, 4217, NULL),
(4218, 'medical record', '/ˈmɛdɪkəl ˈrɛkərd/', 'noun', '{"zh-TW":["病歷；醫療記錄"],"en":["a document containing a patient''s health history"]}', NULL, 'update medical record / request medical record', '[{"en":"Your medical record contains your full health history.","zh-TW":"您的病歷包含您完整的健康史。"},{"en":"Please bring your medical records to the appointment.","zh-TW":"請攜帶您的病歷前往就診。"}]', NULL, NULL, 5, 4218, NULL),
(4219, 'medication', '/ˌmɛdɪˈkeɪʃən/', 'noun', '{"zh-TW":["藥物；藥品"],"en":["a drug or medicine taken to treat illness"]}', NULL, 'take medication / prescription medication', '[{"en":"She takes daily medication to control her blood pressure.","zh-TW":"她每天服藥來控制血壓。"},{"en":"Never stop taking medication without consulting your doctor.","zh-TW":"不要在未諮詢醫生的情況下停藥。"}]', '{"verb":"medicate","adjective":"medicated"}', NULL, 4, 4219, NULL),
(4220, 'mediocre', '/ˌmiːdiˈoʊkər/', 'adjective', '{"zh-TW":["平庸的；普通的"],"en":["of only average quality; not very good"]}', NULL, 'mediocre performance/results/quality', '[{"en":"Mediocre performance will not be tolerated.","zh-TW":"平庸的表現將不被容忍。"},{"en":"The product received mediocre reviews.","zh-TW":"該產品獲得了普通的評價。"}]', '{"noun":"mediocrity","adjective":"mediocre"}', NULL, 3, 4220, NULL),
(4221, 'medium', '/ˈmiːdiəm/', 'noun, adjective', '{"zh-TW":["媒介；媒體","中等的"],"en":["a means of communication; a middle state","average in size or amount"]}', NULL, 'through the medium of / medium-sized / medium-term', '[{"en":"Email is an effective medium for business communication.","zh-TW":"電子郵件是商務溝通的有效媒介。"},{"en":"The company targets medium-sized businesses.","zh-TW":"該公司以中型企業為目標客戶。"}]', '{"noun":"medium, media","adjective":"medium"}', NULL, 2, 4221, NULL),
(4222, 'medium-term note', '/ˈmiːdiəm tɜːrm noʊt/', 'noun', '{"zh-TW":["中期票據"],"en":["a debt instrument with a maturity between one and ten years"]}', NULL, 'issue a medium-term note / medium-term note program', '[{"en":"The company issued $100 million in medium-term notes.","zh-TW":"公司發行了1億元的中期票據。"},{"en":"Medium-term notes are used to diversify a company''s debt maturity profile.","zh-TW":"中期票據用於多元化公司的債務到期期限結構。"}]', '{"abbreviation":"MTN"}', NULL, 5, 4222, NULL),
(4223, 'meet', '/miːt/', 'verb', '{"zh-TW":["見面；符合"],"en":["to come together with","to satisfy a requirement"]}', NULL, 'meet the deadline / meet expectations', '[{"en":"Can we meet tomorrow at 2?","zh-TW":"我們明天2點見面好嗎？"},{"en":"The product meets all safety standards.","zh-TW":"產品符合所有安全標準。"}]', '{"verb":"meet","noun":"meeting"}', NULL, 1, 4223, NULL),
(4224, 'meet targets', '/miːt ˈtɑːrɡɪts/', 'verb', '{"zh-TW":["達成目標；完成指標"],"en":["to achieve the goals set for performance or output"]}', NULL, 'consistently meet targets / fail to meet targets', '[{"en":"The sales team met all its quarterly targets for the first time.","zh-TW":"銷售團隊首次達成了所有季度目標。"},{"en":"Incentive bonuses are paid only when staff meet their individual targets.","zh-TW":"只有當員工達到個人目標時才發放績效獎金。"}]', NULL, NULL, 4, 4224, NULL),
(4225, 'meeting', 'ˈmiːtɪŋ', 'noun', '{"zh-TW":["會議；開會","集會"],"en":["a gathering to discuss something","an arranged encounter"]}', NULL, 'board meeting/team meeting', '[{"en":"The weekly meeting is on Monday morning.","zh-TW":"每週會議在週一上午舉行。"}]', '{"verb":"meet","adjective":"meeting-related"}', NULL, 3, 4225, 155),
(4226, 'meeting room', '/ˈmiːtɪŋ ruːm/', 'noun', '{"zh-TW":["會議室"],"en":["a room used for holding meetings"]}', NULL, 'book a meeting room / meeting room facilities', '[{"en":"Please book the meeting room in advance.","zh-TW":"請提前預訂會議室。"},{"en":"The meeting room is equipped with video conferencing tools.","zh-TW":"會議室配備了視訊會議工具。"}]', NULL, NULL, 4, 4226, NULL),
(4227, 'membership', '/ˈmembərʃɪp/', 'noun', '{"zh-TW":["會員資格；會員人數"],"en":["the state of being a member; the total number of members"]}', NULL, 'membership fee / apply for membership', '[{"en":"Membership is open to all employees.","zh-TW":"所有員工都可以申請會員資格。"},{"en":"The club''s membership has grown to 500.","zh-TW":"俱樂部的會員人數已增至500人。"}]', '{"noun":"membership, member"}', NULL, 4, 4227, NULL),
(4228, 'memo', '/ˈmemoʊ/', 'noun', '{"zh-TW":["備忘錄"],"en":["a short written message used in business"]}', NULL, 'send/write a memo / internal memo', '[{"en":"The manager sent a memo to all staff.","zh-TW":"經理向全體員工發送了一份備忘錄。"},{"en":"Please refer to the attached memo for details.","zh-TW":"詳情請參閱附件備忘錄。"}]', '{"noun":"memo, memorandum"}', NULL, 1, 4228, NULL),
(4229, 'memorandum', '/ˌmɛməˈrændəm/', 'noun', '{"zh-TW":["備忘錄"],"en":["a written message in an office or organization"]}', NULL, 'send a memorandum / internal memorandum', '[{"en":"A memorandum was circulated to all staff regarding the policy change.","zh-TW":"一份備忘錄已發送給所有員工，說明政策變更。"},{"en":"The memorandum outlined the new expense reimbursement procedure.","zh-TW":"備忘錄概述了新的費用報銷程序。"}]', '{"plural":"memoranda","abbreviation":"memo"}', NULL, 4, 4229, NULL),
(4230, 'memorandum of understanding', '/ˌmɛmərˈændəm əv ˌʌndəˈstændɪŋ/', 'noun', '{"zh-TW":["諒解備忘錄"],"en":["a formal agreement between two parties that is not legally binding"]}', NULL, 'sign a memorandum of understanding / memorandum of understanding terms', '[{"en":"They signed a memorandum of understanding to begin collaboration.","zh-TW":"他們簽署了諒解備忘錄開始合作。"},{"en":"A memorandum of understanding outlines the key terms before a formal contract.","zh-TW":"諒解備忘錄在正式合約之前概述了關鍵條款。"}]', '{"abbreviation":"MOU"}', NULL, 5, 4230, NULL),
(4231, 'mens rea', '/menz ˈriːə/', 'noun', '{"zh-TW":["犯罪意圖；犯意"],"en":["the mental state required for criminal liability"]}', NULL, 'establish mens rea / criminal mens rea / lack of mens rea', '[{"en":"Conviction requires proof of both actus reus and mens rea.","zh-TW":"定罪需要證明犯罪行為和犯罪意圖兩者。"},{"en":"The defendant''s attorney argued a lack of mens rea for the alleged offense.","zh-TW":"被告律師主張被告對被指控的罪行缺乏犯意。"}]', NULL, NULL, 3, 4231, NULL),
(4232, 'mention', 'ˈmɛnʃən', 'verb', '{"zh-TW":["提及；提到","說到"],"en":["to refer to briefly","to bring up"]}', NULL, 'mention a concern/mention details', '[{"en":"Please mention any special requirements.","zh-TW":"請提及任何特殊要求。"}]', '{"noun":"mention","adjective":"mentioned"}', NULL, 3, 4232, 156),
(4233, 'mentor', '/ˈmɛntɔːr/', 'noun', '{"zh-TW":["導師；良師益友","導師；顧問","指導"],"en":["an experienced person who advises","to guide and advise"]}', NULL, 'find a mentor / mentor program; mentor program / find a mentor / mentor someone', '[{"en":"She became my mentor at work.","zh-TW":"她成為了我工作中的導師。"},{"en":"Every student is assigned a mentor.","zh-TW":"每位學生都被分配了一位導師。"},{"en":"Every new employee is assigned a mentor.","zh-TW":"每位新員工都會被分配一位導師。"},{"en":"She mentored several junior colleagues.","zh-TW":"她指導了幾位初級同事。"}]', '{"verb":"mentor","noun2":"mentorship","noun":"mentor, mentorship, mentoring"}', NULL, 2, 4233, NULL),
(4234, 'mentor program', '/ˈmentər ˈproʊɡræm/', 'noun', '{"zh-TW":["導師計劃"],"en":["a structured initiative pairing experienced staff with junior employees for development"]}', NULL, 'launch a mentor program / join a mentor program', '[{"en":"The mentor program helped junior staff develop faster.","zh-TW":"導師計劃幫助初級員工更快地發展。"},{"en":"Participation in the mentor program is voluntary but encouraged.","zh-TW":"參與導師計劃是自願的，但受到鼓勵。"}]', NULL, NULL, 5, 4234, NULL),
(4235, 'mentoring', '/ˈmentərɪŋ/', 'noun', '{"zh-TW":["導師制；輔導"],"en":["a relationship where an experienced person guides a less experienced one"]}', NULL, 'mentoring program / provide mentoring / peer mentoring', '[{"en":"The mentoring program paired junior employees with senior leaders.","zh-TW":"導師計劃將初級員工與資深領導人配對。"},{"en":"She credited her success to strong mentoring early in her career.","zh-TW":"她將成功歸功於職業生涯早期的良好輔導。"}]', '{"verb":"mentor","noun":"mentor"}', NULL, 3, 4235, NULL),
(4236, 'mentoring program', '/ˈmentərɪŋ ˈproʊɡræm/', 'noun', '{"zh-TW":["導師計劃；輔導計劃"],"en":["a structured program pairing less experienced individuals with mentors"]}', NULL, 'launch a mentoring program / mentoring program effectiveness', '[{"en":"The mentoring program helped junior staff develop leadership skills.","zh-TW":"導師計劃幫助初級員工發展了領導技能。"},{"en":"Participants in the mentoring program reported higher job satisfaction.","zh-TW":"參與導師計劃的人員報告了更高的工作滿意度。"}]', NULL, NULL, 5, 4236, NULL),
(4237, 'mentorship', '/ˈmentərʃɪp/', 'noun', '{"zh-TW":["指導；師徒關係"],"en":["a relationship where an experienced person guides a junior one"]}', NULL, 'mentorship program / provide mentorship / mentorship relationship', '[{"en":"The mentorship program pairs new staff with senior employees.","zh-TW":"師徒計劃將新員工與資深員工配對。"},{"en":"She credits her success to strong mentorship early in her career.","zh-TW":"她將成功歸功於職業生涯早期良好的指導。"}]', '{"noun":"mentor","verb":"mentor"}', NULL, 4, 4237, NULL),
(4238, 'menu', '/ˈmɛnjuː/', 'noun', '{"zh-TW":["菜單"],"en":["a list of dishes available in a restaurant"]}', NULL, 'browse the menu / set menu', '[{"en":"Please take a moment to look over our menu.","zh-TW":"請花一點時間瀏覽我們的菜單。"},{"en":"The seasonal menu changes every month.","zh-TW":"季節性菜單每月更換。"}]', NULL, NULL, 1, 4238, NULL),
(4239, 'merchandise', '/ˈmɜːrtʃəndaɪz/', 'noun', '{"zh-TW":["商品；貨物","推銷"],"en":["goods that are bought and sold","goods for sale","to promote the sale of goods"]}', '{"root":{"text":"merch","meaning":"trade (貿易)"},"suffix":{"text":"-andise","meaning":"collective (集合)"},"logic":"貿易的集合，即「商品」。"}', 'merchandise display / branded merchandise', '[{"en":"The store sells a wide range of merchandise.","zh-TW":"這家店販售各種商品。"},{"en":"All merchandise must be paid for before leaving.","zh-TW":"所有商品在離開前必須付款。"},{"en":"The store offers a wide range of merchandise.","zh-TW":"這家商店提供各種各樣的商品。"},{"en":"The products were merchandised effectively.","zh-TW":"產品被有效地推銷。"}]', '{"noun":"merchant","verb":"merchandise"}', NULL, 4, 4239, 394),
(4240, 'merchandising', '/ˈmɜːrtʃəndaɪzɪŋ/', 'noun', '{"zh-TW":["商品展示；銷售陳列"],"en":["the promotion of goods for sale in a store"]}', NULL, 'visual merchandising / merchandising strategy', '[{"en":"Good merchandising draws attention to high-margin products.","zh-TW":"良好的商品陳列吸引了對高利潤產品的注意。"},{"en":"The merchandising team redesigned the store layout.","zh-TW":"商品展示團隊重新設計了商店佈局。"}]', '{"verb":"merchandise","noun":"merchandiser"}', NULL, 5, 4240, NULL),
(4241, 'merge', '/mɜːrdʒ/', 'verb', '{"zh-TW":["合併；融合"],"en":["to combine or join together"]}', NULL, 'merge with / merge into / merge companies', '[{"en":"The two companies merged to form a larger corporation.","zh-TW":"兩家公司合併成為一家更大的企業。"},{"en":"The lanes merge ahead.","zh-TW":"前方車道合併。"}]', '{"noun":"merger","verb":"merge"}', NULL, 2, 4241, NULL),
(4242, 'merger', '/ˈmɜːrdʒər/', 'noun', '{"zh-TW":["合併；併購"],"en":["the combination of two or more companies into one"]}', NULL, 'merger and acquisition / a merger between', '[{"en":"The merger created the largest bank in the country.","zh-TW":"這次合併創造了全國最大的銀行。"},{"en":"Both boards approved the merger last Friday.","zh-TW":"雙方董事會上週五批准了合併案。"}]', '{"verb":"merge","adjective":"merged"}', NULL, 2, 4242, NULL),
(4243, 'merger and acquisition', '/ˈmɜːrdʒər ənd ˌækwɪˈzɪʃən/', 'noun', '{"zh-TW":["併購"],"en":["the consolidation of companies through mergers or one company buying another"]}', NULL, 'pursue a merger and acquisition / merger and acquisition strategy', '[{"en":"The merger and acquisition activity in the sector increased last year.","zh-TW":"去年該行業的併購活動有所增加。"},{"en":"A successful merger and acquisition requires thorough due diligence.","zh-TW":"成功的併購需要徹底的盡職調查。"}]', '{"abbreviation":"M&A"}', NULL, 5, 4243, NULL),
(4244, 'merger arbitrage', '/ˈmɜːrdʒər ˈɑːrbɪtrɑːʒ/', 'noun', '{"zh-TW":["合併套利"],"en":["an investment strategy profiting from price differences in M&A transactions"]}', NULL, 'employ merger arbitrage / merger arbitrage fund', '[{"en":"Merger arbitrage funds profit from the spread between offer and market prices.","zh-TW":"合併套利基金從要約價格和市場價格之間的差價中獲利。"},{"en":"Merger arbitrage requires careful analysis of deal completion probabilities.","zh-TW":"合併套利需要對交易完成概率進行仔細分析。"}]', NULL, NULL, 5, 4244, NULL),
(4245, 'mergers and acquisitions', '/ˈmɜːrdʒərz ænd ˌækwɪˈzɪʃənz/', 'noun', '{"zh-TW":["合併與收購"],"en":["corporate transactions involving the combining of companies or acquisition of assets"]}', NULL, 'pursue mergers and acquisitions / mergers and acquisitions strategy', '[{"en":"The company''s mergers and acquisitions activity tripled over five years.","zh-TW":"公司的合併與收購活動在五年內增加了兩倍。"},{"en":"Mergers and acquisitions advisors are hired to negotiate deal terms.","zh-TW":"聘用合併與收購顧問來談判交易條款。"}]', '{"abbreviation":"M&A"}', NULL, 5, 4245, NULL),
(4246, 'merit', '/ˈmerɪt/', 'noun, verb', '{"zh-TW":["優點；功績","值得"],"en":["a good quality or feature","to deserve or be worthy of"]}', NULL, 'on merit / merit attention/consideration', '[{"en":"Each proposal will be judged on its own merit.","zh-TW":"每個提案將根據其本身的優點進行評判。"},{"en":"The idea merits further investigation.","zh-TW":"這個想法值得進一步研究。"}]', '{"noun":"merit","verb":"merit","adjective":"meritorious"}', NULL, 2, 4246, NULL),
(4247, 'meritocracy', '/ˌmerɪˈtɒkrəsi/', 'noun', '{"zh-TW":["精英政治；能力主義"],"en":["a system in which advancement depends on ability and talent"]}', NULL, 'promote meritocracy / meritocracy in education / critique of meritocracy', '[{"en":"Many believe meritocracy rewards effort, while others argue it reinforces privilege.","zh-TW":"許多人相信能力主義獎勵努力，而另一些人則認為它強化了特權。"},{"en":"A genuine meritocracy requires equal access to education and opportunity.","zh-TW":"真正的能力主義需要平等的教育和機會。"}]', '{"adjective":"meritocratic","noun":"meritocrat"}', NULL, 4, 4247, NULL),
(4248, 'meritorious', '/''merɪˌtɔːriəs/', 'adjective', '{"zh-TW":["有功績的；值得稱讚的"],"en":["deserving reward or praise; having merit"]}', NULL, 'meritorious service / meritorious achievement / meritorious conduct', '[{"en":"She received a meritorious service award for her outstanding contribution.","zh-TW":"她因其傑出貢獻而獲得了功績服務獎。"},{"en":"The judge praised the meritorious efforts of the volunteer organization.","zh-TW":"法官讚揚了志願組織的有功績努力。"}]', '{"adverb":"meritoriously","noun":"merit"}', NULL, 4, 4248, NULL),
(4249, 'message', 'ˈmɛsɪdʒ', 'noun', '{"zh-TW":["訊息；留言","要旨"],"en":["a spoken or written communication","the main point of something"]}', NULL, 'leave a message/key message', '[{"en":"I left a message with the receptionist.","zh-TW":"我留了一條留言給接待員。"}]', '{"verb":"message","adjective":"messaging"}', NULL, 3, 4249, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4250, 'metaphor', '/ˈmetəfɔːr/', 'noun', '{"zh-TW":["隱喻；比喻"],"en":["a figure of speech in which a word is applied to something it cannot literally describe"]}', NULL, 'use a metaphor / apt metaphor / powerful metaphor', '[{"en":"The CEO used the metaphor of a ship to describe the company''s direction.","zh-TW":"CEO用一艘船的隱喻來描述公司的方向。"},{"en":"Language is rich with metaphors that shape how we think.","zh-TW":"語言充滿了塑造我們思維方式的隱喻。"}]', '{"adjective":"metaphorical","adverb":"metaphorically"}', NULL, 3, 4250, NULL),
(4251, 'metaphysics', '/ˌmetəˈfɪzɪks/', 'noun', '{"zh-TW":["形而上學"],"en":["the branch of philosophy dealing with the fundamental nature of reality"]}', NULL, 'study metaphysics / philosophy of metaphysics / metaphysics of mind', '[{"en":"Metaphysics examines questions that go beyond physical science.","zh-TW":"形而上學探討超越物理科學的問題。"},{"en":"The debate involves deep questions of metaphysics and ethics.","zh-TW":"這場辯論涉及形而上學和倫理學的深層問題。"}]', '{"adjective":"metaphysical","adverb":"metaphysically"}', NULL, 4, 4251, NULL),
(4252, 'metastasis', '/mɪˈtæstəsɪs/', 'noun', '{"zh-TW":["轉移；癌細胞擴散"],"en":["the spread of cancer from its original site to other parts of the body"]}', NULL, 'prevent metastasis / distant metastasis / metastasis to the liver', '[{"en":"The cancer was caught before metastasis to other organs.","zh-TW":"癌症在轉移到其他器官之前被發現。"},{"en":"Metastasis significantly reduces the chances of a cure.","zh-TW":"轉移顯著降低了治癒的機會。"}]', '{"verb":"metastasize","adjective":"metastatic"}', NULL, 4, 4252, NULL),
(4253, 'metatheory', '/ˈmetəˌθɪəri/', 'noun', '{"zh-TW":["元理論"],"en":["a theory about the nature of theories themselves"]}', NULL, 'develop a metatheory / apply metatheory / metatheory of science', '[{"en":"Metatheory examines the assumptions underlying scientific practice.","zh-TW":"元理論審視科學實踐背後的假設。"},{"en":"A robust metatheory helps researchers choose appropriate methods.","zh-TW":"強健的元理論幫助研究員選擇適當的方法。"}]', '{"adjective":"metatheoretical"}', NULL, 4, 4253, NULL),
(4254, 'methane emissions', '/ˈmiːθeɪn ɪˈmɪʃənz/', 'noun', '{"zh-TW":["甲烷排放"],"en":["the release of methane gas, a potent greenhouse gas, into the atmosphere"]}', NULL, 'reduce methane emissions / methane emissions from livestock / capture methane emissions', '[{"en":"Methane emissions from livestock account for a significant share of agricultural pollution.","zh-TW":"來自牲畜的甲烷排放佔農業污染的重要份額。"},{"en":"Capturing methane emissions from landfills can generate renewable energy.","zh-TW":"捕獲填埋場的甲烷排放可以產生可再生能源。"}]', NULL, NULL, 5, 4254, NULL),
(4255, 'method', '/ˈmeθəd/', 'noun', '{"zh-TW":["方法；辦法"],"en":["a way of doing something systematically"]}', NULL, 'teaching/payment method / method of', '[{"en":"We need to find a more efficient method.","zh-TW":"我們需要找到一種更有效率的方法。"},{"en":"What payment methods do you accept?","zh-TW":"你們接受哪些付款方式？"}]', '{"noun":"method, methodology","adjective":"methodical","adverb":"methodically"}', NULL, 2, 4255, NULL),
(4256, 'methodically', '/''mɪˈθɒdɪkəli/', 'adverb', '{"zh-TW":["有條不紊地；系統地"],"en":["in an orderly and systematic way"]}', NULL, 'work methodically / proceed methodically / organize methodically', '[{"en":"The accountant methodically reviewed each line item in the annual budget.","zh-TW":"會計師有條不紊地審查了年度預算中的每一個項目。"},{"en":"She methodically approached the problem by breaking it down into smaller tasks.","zh-TW":"她通過將問題分解成較小的任務，有條不紊地解決問題。"}]', '{"adjective":"methodical"}', NULL, 4, 4256, NULL),
(4257, 'methodological', '/ˌmeθədəˈlɒdʒɪkəl/', 'adjective', '{"zh-TW":["方法論的"],"en":["relating to the system of methods used in a field"]}', NULL, 'methodological approach / methodological rigor / methodological challenge', '[{"en":"The study''s main contribution is its methodological innovation.","zh-TW":"該研究的主要貢獻是其方法論創新。"},{"en":"Methodological flaws can undermine even the best research questions.","zh-TW":"方法論缺陷可能破壞即使是最好的研究問題。"}]', '{"noun":"methodology","adverb":"methodologically"}', NULL, 5, 4257, NULL),
(4258, 'methodology', '/ˌmɛθəˈdɒlədʒi/', 'noun', '{"zh-TW":["方法論"],"en":["a system of methods used in a particular area"]}', NULL, 'research methodology / agile methodology', '[{"en":"We follow agile methodology in development.","zh-TW":"我們在開發中遵循敏捷方法論。"},{"en":"The research methodology is clearly defined.","zh-TW":"研究方法論有明確的定義。"},{"en":"The company adopted an agile methodology for software development.","zh-TW":"公司採用了敏捷方法論進行軟體開發。"},{"en":"Please describe the methodology used in your study.","zh-TW":"請描述你研究中使用的方法論。"}]', '{"noun":"methodology","adjective":"methodological","adverb":"methodologically"}', NULL, 4, 4258, NULL),
(4259, 'meticulous', '/mɪˈtɪkjələs/', 'adjective', '{"zh-TW":["一絲不苟的；極其仔細的"],"en":["showing great attention to detail"]}', NULL, 'meticulous attention to detail / meticulous planning', '[{"en":"She is meticulous in her work and rarely makes errors.","zh-TW":"她工作一絲不苟，很少犯錯。"},{"en":"Meticulous planning ensured the event''s success.","zh-TW":"細緻的規劃確保了活動的成功。"}]', '{"adjective":"meticulous","adverb":"meticulously"}', NULL, 4, 4259, NULL),
(4260, 'metrics', 'ˈmɛtrɪks', 'noun', '{"zh-TW":["指標；度量","衡量標準"],"en":["measures used to evaluate performance","data points"]}', NULL, 'key metrics/track metrics', '[{"en":"Monitor these key performance metrics.","zh-TW":"監控這些關鍵績效指標。"}]', '{"adjective":"metric"}', NULL, 3, 4260, NULL),
(4261, 'mezzanine', '/ˈmezəniːn/', 'noun', '{"zh-TW":["夾層融資；中間層"],"en":["an intermediate layer of financing between senior debt and equity"]}', NULL, 'mezzanine financing / mezzanine debt / mezzanine tranche', '[{"en":"Mezzanine financing bridges the gap between debt and equity.","zh-TW":"夾層融資填補了債務和股權之間的差距。"},{"en":"The deal''s mezzanine tranche carried a higher interest rate.","zh-TW":"該交易的夾層部分帶有更高的利率。"}]', '{"adjective":"mezzanine"}', NULL, 3, 4261, NULL),
(4262, 'microeconomics', '/ˌmaɪkroʊˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["微觀經濟學"],"en":["the study of individual economic behaviors and decisions"]}', NULL, 'apply microeconomics / microeconomics principles', '[{"en":"Microeconomics helps predict how consumers respond to price changes.","zh-TW":"微觀經濟學有助於預測消費者如何應對價格變化。"},{"en":"Understanding microeconomics is valuable for pricing and market analysis.","zh-TW":"了解微觀經濟學對定價和市場分析很有價值。"}]', NULL, NULL, 5, 4262, NULL),
(4263, 'microfinance', '/ˈmaɪkrəʊˌfaɪnæns/', 'noun', '{"zh-TW":["微型金融；小額信貸"],"en":["the provision of small financial services to low-income individuals or businesses"]}', NULL, 'microfinance institution / provide microfinance / microfinance program', '[{"en":"Microfinance loans helped women entrepreneurs in developing countries start businesses.","zh-TW":"小額信貸幫助發展中國家的女性企業家創辦了企業。"},{"en":"Microfinance programs have improved financial inclusion in rural communities.","zh-TW":"微型金融計畫改善了農村社區的金融普惠性。"}]', '{"adjective":"microfinancial"}', NULL, 4, 4263, NULL),
(4264, 'micromanage', '/ˈmaɪkroʊˌmænɪdʒ/', 'verb', '{"zh-TW":["過度管理；微觀管理"],"en":["to control every small detail of a task or person''s work"]}', NULL, 'avoid micromanaging / tendency to micromanage', '[{"en":"Micromanaging reduces employee autonomy and creativity.","zh-TW":"過度管理降低了員工的自主性和創造力。"},{"en":"Trust your team and avoid the urge to micromanage.","zh-TW":"信任你的團隊，避免過度管理的衝動。"}]', '{"noun":"micromanager","adjective":"micromanaged"}', NULL, 4, 4264, NULL),
(4265, 'micronutrient', '/''maɪkrəʊˌnjuːtriənt/', 'noun', '{"zh-TW":["微量營養素"],"en":["a vitamin or mineral required in small amounts but essential for health"]}', NULL, 'micronutrient deficiency / provide micronutrients / essential micronutrient', '[{"en":"Iron and vitamin D are common micronutrients that many people lack.","zh-TW":"鐵和維生素D是許多人缺乏的常見微量營養素。"},{"en":"A varied diet is the best way to ensure adequate micronutrient intake.","zh-TW":"多樣化的飲食是確保充足微量營養素攝取的最佳方式。"}]', NULL, NULL, 5, 4265, NULL),
(4266, 'microplastics', '/ˈmaɪkrəʊˌplæstɪks/', 'noun', '{"zh-TW":["微塑料"],"en":["tiny plastic particles less than five millimetres in size contaminating environments"]}', NULL, 'microplastics pollution / microplastics in the ocean / filter microplastics', '[{"en":"Microplastics have been found in human blood and ocean fish.","zh-TW":"在人類血液和海洋魚類中發現了微塑料。"},{"en":"Reducing single-use plastics is essential to combat microplastics pollution.","zh-TW":"減少一次性塑料對於應對微塑料污染至關重要。"}]', NULL, NULL, 5, 4266, NULL),
(4267, 'microservices', '/ˈmaɪkrəʊˌsɜːrvɪsɪz/', 'noun', '{"zh-TW":["微服務"],"en":["an architectural approach building software as small, independent services"]}', NULL, 'adopt microservices / microservices architecture / decompose into microservices', '[{"en":"Microservices allow teams to deploy and scale individual components independently.","zh-TW":"微服務允許團隊獨立部署和擴展各個組件。"},{"en":"The monolithic application was refactored into microservices over two years.","zh-TW":"單體應用程式花了兩年時間重構為微服務。"}]', NULL, NULL, 5, 4267, NULL),
(4268, 'mid-year review', '/ˌmɪd jɪər rɪˈvjuː/', 'noun', '{"zh-TW":["中期審查；半年回顧"],"en":["a review of performance conducted halfway through a fiscal year"]}', NULL, 'conduct a mid-year review / mid-year review process', '[{"en":"The mid-year review identified the need to reforecast revenue.","zh-TW":"中期審查識別了需要重新預測收入的必要性。"},{"en":"Mid-year reviews allow management to adjust strategies if needed.","zh-TW":"中期審查允許管理層在需要時調整策略。"}]', NULL, NULL, 5, 4268, NULL),
(4269, 'middle', '/ˈmɪdəl/', 'noun', '{"zh-TW":["中間；中部"],"en":["the central point or position"]}', NULL, 'middle management / in the middle of', '[{"en":"She is in middle management.","zh-TW":"她是中層管理人員。"},{"en":"We are in the middle of negotiations.","zh-TW":"我們正在談判中。"}]', '{"noun":"middle","adjective":"middle"}', NULL, 2, 4269, NULL),
(4270, 'middle seat', '/''mɪdəl siːt/', 'noun', '{"zh-TW":["中間座位"],"en":["the seat between the window seat and the aisle seat in an aircraft row"]}', NULL, 'stuck in the middle seat / avoid the middle seat', '[{"en":"Nobody likes the middle seat because it has no window or easy aisle access.","zh-TW":"沒有人喜歡中間座位，因為它沒有窗戶，也不方便進入走道。"},{"en":"She arrived late and was assigned the middle seat at the back of the plane.","zh-TW":"她到得很晚，被分配到飛機後部的中間座位。"}]', NULL, NULL, 4, 4270, NULL),
(4271, 'middleware', '/ˈmɪdəlweər/', 'noun', '{"zh-TW":["中間件"],"en":["software that connects different applications or components in a network"]}', NULL, 'integrate middleware / middleware layer / message middleware', '[{"en":"Middleware handles communication between the frontend and backend systems.","zh-TW":"中間件處理前端和後端系統之間的通信。"},{"en":"API gateways and message brokers are common forms of middleware.","zh-TW":"API閘道和訊息代理是常見的中間件形式。"}]', NULL, NULL, 4, 4271, NULL),
(4272, 'midterm', '/ˈmɪdtɜːrm/', 'noun', '{"zh-TW":["期中考"],"en":["an exam in the middle of a term"]}', NULL, 'midterm exam / midterm grades', '[{"en":"I''m studying for my midterms.","zh-TW":"我正在準備期中考。"},{"en":"Midterm grades will be posted Friday.","zh-TW":"期中成績將在週五公布。"}]', NULL, NULL, 3, 4272, NULL),
(4273, 'migrate', '/ˈmaɪɡreɪt/', 'verb', '{"zh-TW":["遷移；移民"],"en":["to move from one place to another"]}', NULL, 'migrate to / migrate data/systems', '[{"en":"Many companies are migrating their data to the cloud.","zh-TW":"許多公司正在將數據遷移到雲端。"},{"en":"Birds migrate south for the winter.","zh-TW":"鳥類冬天遷徙到南方。"}]', '{"noun":"migration, migrant","verb":"migrate","adjective":"migratory"}', NULL, 3, 4273, NULL),
(4274, 'migration', '/maɪˈɡreɪʃən/', 'noun', '{"zh-TW":["數據遷移；系統遷移"],"en":["the process of moving data or systems from one platform to another"]}', NULL, 'data migration / system migration / cloud migration / migration plan', '[{"en":"The cloud migration reduced infrastructure costs by 40%.","zh-TW":"雲端遷移將基礎設施成本降低了40%。"},{"en":"A data migration plan was developed to ensure zero data loss.","zh-TW":"制定了數據遷移計劃以確保零數據遺失。"}]', '{"verb":"migrate","adjective":"migrated"}', NULL, 3, 4274, NULL),
(4275, 'mileage reward', '/''maɪlɪdʒ rɪˈwɔːrd/', 'noun', '{"zh-TW":["里程獎勵；飛行里程獎勵"],"en":["points or miles earned through airline travel that can be redeemed for flights or upgrades"]}', NULL, 'earn mileage rewards / redeem mileage rewards / accumulate mileage', '[{"en":"She used her accumulated mileage rewards to book a free business class ticket.","zh-TW":"她使用累積的里程獎勵預訂了免費的商務艙機票。"},{"en":"Enrolling in a mileage reward program is worthwhile if you travel frequently.","zh-TW":"如果你經常旅行，加入里程獎勵計畫是值得的。"}]', NULL, NULL, 5, 4275, NULL),
(4276, 'milestone', '/ˈmaɪlstoʊn/', 'noun', '{"zh-TW":["里程碑；重要事件"],"en":["an important event in the development of something"]}', NULL, 'reach/achieve a milestone / project milestone', '[{"en":"Reaching 1 million users was a major milestone.","zh-TW":"達到100萬用戶是一個重要的里程碑。"},{"en":"The project has several key milestones to meet.","zh-TW":"該項目有幾個關鍵里程碑需要完成。"}]', '{"noun":"milestone"}', NULL, 3, 4276, 890),
(4277, 'milestone payment', '/ˈmaɪlstoʊn ˈpeɪmənt/', 'noun', '{"zh-TW":["里程碑付款"],"en":["a payment made upon achieving a specific project milestone"]}', NULL, 'agree on milestone payments / trigger a milestone payment', '[{"en":"Milestone payments ensure the contractor is paid progressively.","zh-TW":"里程碑付款確保了承包商按進度獲得報酬。"},{"en":"The project contract includes four milestone payments tied to deliverables.","zh-TW":"項目合約包含與可交付成果掛鈎的四項里程碑付款。"}]', NULL, NULL, 5, 4277, NULL),
(4278, 'milestone review', '/ˈmaɪlstoʊn rɪˈvjuː/', 'noun', '{"zh-TW":["里程碑審查"],"en":["a formal check at a defined project stage to assess progress and authorize continuation"]}', NULL, 'conduct a milestone review / pass the milestone review', '[{"en":"The steering committee approved the project to continue after the milestone review.","zh-TW":"指導委員會在里程碑審查後批准了項目繼續進行。"},{"en":"A milestone review ensures the project is on track before releasing more funds.","zh-TW":"里程碑審查確保在釋放更多資金前項目處於正軌。"}]', NULL, NULL, 5, 4278, NULL),
(4279, 'milk', '/mɪlk/', 'noun', '{"zh-TW":["牛奶"],"en":["a white liquid from cows"]}', NULL, 'milk products / don''t cry over spilled milk', '[{"en":"The cafeteria offers various milk products.","zh-TW":"自助餐廳提供各種乳製品。"},{"en":"Don''t cry over spilled milk; move forward.","zh-TW":"不要為打翻的牛奶哭泣；向前看。"}]', '{"noun":"milk","adjective":"milky","verb":"milk"}', NULL, 1, 4279, NULL),
(4280, 'million', 'ˈmɪljən', 'noun', '{"zh-TW":["百萬","大量"],"en":["a thousand thousand","an extremely large number"]}', NULL, 'one million/million-dollar', '[{"en":"The company earned five million in revenue.","zh-TW":"公司賺了五百萬的收入。"}]', '{"adjective":"million-dollar"}', NULL, 3, 4280, NULL),
(4281, 'mind', '/maɪnd/', 'noun', '{"zh-TW":["【主要意義-名詞】心智；思想；意見","【次要意義-動詞】照料；看管","【次要意義-動詞】介意；在乎","【次要意義-動詞】注意；小心（命令句）"],"en":["[primary - noun] the part of a person that thinks and feels","[secondary - verb] to look after or take care of something","[secondary - verb] to feel bothered or annoyed by something","[secondary - verb] to be careful about something (in imperatives)"]}', NULL, 'mind the gap / bear in mind / never mind / mind your own business / mind the store', '[{"en":"Could you mind the front desk while I attend the meeting?","zh-TW":"我去參加會議時，你能照看前台嗎？"},{"en":"Bear in mind that all expenses must be approved before submission.","zh-TW":"請記住，所有費用必須在提交前獲得批准。"},{"en":"Do you mind if I reschedule our appointment to next Tuesday?","zh-TW":"您介意將我們的預約改到下週二嗎？"}]', '{"adjective":"mindful, mindless","noun":"mindset"}', '動詞 mind = 「照料」（mind the store = 看顧業務），bear in mind（記住），do you mind if（您介意嗎？）均是 TOEIC 高頻職場用語，考生常誤以為 mind 只是名詞「心智」。', 1, 4281, NULL),
(4282, 'mindfulness', '/''maɪndfʊlnəs/', 'noun', '{"zh-TW":["正念；當下覺察"],"en":["a mental state of being conscious and aware, focusing on the present moment without judgment"]}', NULL, 'practice mindfulness / mindfulness meditation / benefit of mindfulness', '[{"en":"Practicing mindfulness for just ten minutes daily can reduce stress significantly.","zh-TW":"每天僅練習十分鐘正念就能顯著降低壓力。"},{"en":"Many corporations now offer mindfulness programs to improve employee well-being.","zh-TW":"許多企業現在提供正念計劃，以改善員工的健康。"}]', '{"adjective":"mindful","adverb":"mindfully"}', NULL, 4, 4282, NULL),
(4283, 'mindset', 'ˈmaɪndˌsɛt', 'noun', '{"zh-TW":["心態；思維方式","觀念"],"en":["an established set of attitudes","a way of thinking"]}', NULL, 'growth mindset/positive mindset', '[{"en":"Cultivate a growth mindset.","zh-TW":"培養成長型心態。"}]', NULL, NULL, 3, 4283, NULL),
(4284, 'mineral', '/ˈmɪnərəl/', 'noun, adjective', '{"zh-TW":["礦物；礦產"],"en":["a natural substance found in the earth"]}', NULL, 'mineral resources/deposits/water', '[{"en":"The country is rich in mineral resources.","zh-TW":"該國礦產資源豐富。"},{"en":"Mineral water is available at the front desk.","zh-TW":"前台有提供礦泉水。"}]', '{"noun":"mineral, mining","adjective":"mineral"}', NULL, 3, 4284, NULL),
(4285, 'minibar', '/ˈmɪnibɑːr/', 'noun', '{"zh-TW":["迷你吧；小型冰箱"],"en":["a small refrigerator stocked with drinks in a hotel room"]}', NULL, 'use the minibar / minibar charges', '[{"en":"The minibar is stocked with soft drinks and snacks.","zh-TW":"迷你吧備有軟性飲料和零食。"},{"en":"Minibar charges will appear on your bill.","zh-TW":"迷你吧費用將計入您的帳單。"}]', NULL, NULL, 3, 4285, NULL),
(4286, 'minimalism', '/ˈmɪnɪməlɪzəm/', 'noun', '{"zh-TW":["極簡主義"],"en":["a style or technique characterized by extreme spareness"]}', NULL, 'academic minimalism / design minimalism / apply minimalism', '[{"en":"Minimalism in academic writing means eliminating everything unnecessary.","zh-TW":"學術寫作中的極簡主義意味著消除所有不必要的內容。"},{"en":"Many modern apps adopt minimalism to improve user experience.","zh-TW":"許多現代應用程式採用極簡主義來改善用戶體驗。"}]', '{"adjective":"minimalist","adverb":"minimalistically"}', NULL, 4, 4286, NULL),
(4287, 'minimize', '/ˈmɪnɪmaɪz/', 'verb', '{"zh-TW":["最小化；減少"],"en":["to reduce to the smallest possible amount"]}', NULL, 'minimize risk/cost/damage', '[{"en":"We must minimize the risk of data loss.","zh-TW":"我們必須將數據丟失的風險降到最低。"},{"en":"The new procedure minimizes waste.","zh-TW":"新程序將浪費減到最少。"}]', '{"noun":"minimum","verb":"minimize","adjective":"minimum, minimal"}', NULL, 3, 4287, 157),
(4288, 'minimum', 'ˈmɪnɪməm', 'noun', '{"zh-TW":["最小值；最低限度","最少量"],"en":["the least possible amount","a lower limit"]}', NULL, 'minimum wage/at a minimum', '[{"en":"The minimum order is 100 units.","zh-TW":"最低訂購量為100件。"}]', '{"adjective":"minimum","adverb":"minimally"}', NULL, 3, 4288, 395),
(4289, 'minimum order quantity', '/ˈmɪnɪməm ˈɔːrdər ˈkwɒntɪti/', 'noun', '{"zh-TW":["最小訂購量"],"en":["the smallest amount a supplier requires to fulfill an order"]}', NULL, 'meet the minimum order quantity / negotiate minimum order quantity', '[{"en":"The supplier requires a minimum order quantity of 500 units.","zh-TW":"供應商要求最小訂購量為500件。"},{"en":"The startup struggled to meet the minimum order quantity.","zh-TW":"新創公司難以達到最小訂購量。"}]', '{"abbreviation":"MOQ"}', NULL, 5, 4289, NULL),
(4290, 'minimum viable product', '/ˈmɪnɪməm ˈvaɪəbl ˈprɒdʌkt/', 'noun', '{"zh-TW":["最小可行產品"],"en":["a version of a product with just enough features to satisfy early customers"]}', NULL, 'launch an MVP / build an MVP / MVP feedback', '[{"en":"The startup launched an MVP to validate the market before full development.","zh-TW":"新創公司在全面開發前推出最小可行產品以驗證市場。"},{"en":"An MVP allows rapid learning with minimal investment.","zh-TW":"最小可行產品允許以最少投資快速學習。"}]', '{"abbreviation":"MVP"}', NULL, 5, 4290, NULL),
(4291, 'minimum wage', '/ˈmɪnɪməm weɪdʒ/', 'noun', '{"zh-TW":["最低薪資"],"en":["the lowest hourly or monthly rate employers are legally required to pay workers"]}', NULL, 'comply with minimum wage / raise the minimum wage', '[{"en":"The government raised the minimum wage for the third consecutive year.","zh-TW":"政府連續第三年提高了最低薪資。"},{"en":"Paying above minimum wage helps companies attract better candidates.","zh-TW":"支付高於最低薪資有助於公司吸引更好的候選人。"}]', NULL, NULL, 4, 4291, NULL),
(4292, 'ministry', '/ˈmɪnɪstri/', 'noun', '{"zh-TW":["部；部門（政府）"],"en":["a government department led by a minister"]}', NULL, 'Ministry of Finance/Education/Health', '[{"en":"The Ministry of Finance released the annual budget.","zh-TW":"財政部發布了年度預算。"},{"en":"She works at the Ministry of Education.","zh-TW":"她在教育部工作。"}]', '{"noun":"ministry, minister","adjective":"ministerial"}', NULL, 3, 4292, NULL),
(4293, 'minor', '/ˈmaɪnər/', 'adjective, noun', '{"zh-TW":["次要的；較小的","未成年人"],"en":["not very important; smaller","a person under the legal age"]}', NULL, 'minor issue/problem/change', '[{"en":"It''s only a minor issue and can be fixed quickly.","zh-TW":"這只是一個小問題，可以很快解決。"},{"en":"There were a few minor adjustments to the schedule.","zh-TW":"行程有一些小的調整。"}]', '{"noun":"minor, minority","adjective":"minor"}', NULL, 2, 4293, NULL),
(4294, 'minority interest', '/maɪˈnɒrɪti ˈɪntrəst/', 'noun', '{"zh-TW":["少數股東權益"],"en":["the portion of a subsidiary not owned by the parent company"]}', NULL, 'disclose minority interest / minority interest holders', '[{"en":"The consolidated accounts include minority interest from the joint venture.","zh-TW":"合並帳目包括來自合資企業的少數股東權益。"},{"en":"Minority interest shareholders received a proportionate dividend.","zh-TW":"少數股東權益持有人獲得了按比例的股息。"}]', NULL, NULL, 5, 4294, NULL),
(4295, 'minority stake', '/maɪˈnɒrɪti steɪk/', 'noun', '{"zh-TW":["少數股份"],"en":["an ownership interest of less than 50% in a company"]}', NULL, 'acquire a minority stake / sell a minority stake', '[{"en":"The fund acquired a 20% minority stake in the startup.","zh-TW":"基金在新創公司中收購了20%的少數股份。"},{"en":"A minority stake can provide influence without full control.","zh-TW":"少數股份可以在沒有完全控制的情況下提供影響力。"}]', NULL, NULL, 5, 4295, NULL),
(4296, 'minute', '/maɪˈnjuːt/', 'adjective', '{"zh-TW":["【主要意義-名詞】分鐘","【次要意義-形容詞】微小的；極細緻的；極詳盡的（重音在第二音節）","【次要意義-複數名詞】會議記錄（minutes）"],"en":["[primary - noun] a unit of time (60 seconds)","[secondary - adjective] extremely small or detailed (stress on second syllable: /maɪˈnjuːt/)","[secondary - plural noun] the official written record of a meeting"]}', NULL, 'minute details / minute examination / take the minutes / approve the minutes', '[{"en":"The inspector carried out a minute examination of the document.","zh-TW":"檢查員對該文件進行了極為詳細的審查。"},{"en":"Could you take the minutes at today''s board meeting?","zh-TW":"你能記錄今天董事會議的會議記錄嗎？"},{"en":"The difference between the two samples was minute but significant.","zh-TW":"兩個樣本之間的差異微乎其微但卻意義重大。"}]', '{"adverb":"minutely","noun":"minuteness"}', 'minute 作形容詞時重音移至第二音節，意為「微小的」；複數 minutes 意為「會議記錄」，兩者都是 TOEIC 高頻陷阱字。', 2, 4296, NULL),
(4297, 'minutes', '/ˈmɪnɪts/', 'noun', '{"zh-TW":["會議記錄"],"en":["an official written record of what was discussed in a meeting"]}', NULL, 'take the minutes / circulate the minutes / approve the minutes', '[{"en":"She was asked to take the minutes during the board meeting.","zh-TW":"她被要求在董事會會議期間記錄會議記錄。"},{"en":"The minutes were approved at the start of the next meeting.","zh-TW":"會議記錄在下次會議開始時獲得批准。"}]', NULL, NULL, 3, 4297, NULL),
(4298, 'minutes of meeting', '/ˈmɪnɪts əv ˈmiːtɪŋ/', 'noun', '{"zh-TW":["會議記錄"],"en":["an official written record of a meeting"]}', NULL, 'circulate minutes of meeting / approve minutes of meeting', '[{"en":"The secretary circulated the minutes of meeting to all attendees.","zh-TW":"秘書將會議記錄發送給所有與會者。"},{"en":"Please review and approve the minutes of last week''s meeting.","zh-TW":"請查看並批准上週的會議記錄。"}]', NULL, NULL, 5, 4298, NULL),
(4299, 'miscellaneous expenses', '/ˌmɪsəˈleɪniəs ɪkˈspensɪz/', 'noun', '{"zh-TW":["雜項費用"],"en":["small or unplanned costs that do not fit into a specific expense category"]}', NULL, 'account for miscellaneous expenses / miscellaneous expenses budget', '[{"en":"Miscellaneous expenses were tracked separately in the expense report.","zh-TW":"雜項費用在費用報告中被單獨追蹤。"},{"en":"A budget line for miscellaneous expenses prevents overruns.","zh-TW":"雜項費用的預算項目可防止超支。"}]', NULL, NULL, 5, 4299, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4300, 'miscommunication', '/''mɪskəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["溝通不良；誤解"],"en":["a failure to communicate clearly, resulting in misunderstanding"]}', NULL, 'cause miscommunication / avoid miscommunication / result of miscommunication', '[{"en":"The project delay was caused by miscommunication between the client and the development team.","zh-TW":"項目延誤是由客戶和開發團隊之間的溝通不良造成的。"},{"en":"Regular team meetings help prevent miscommunication about goals and responsibilities.","zh-TW":"定期的團隊會議有助於防止關於目標和責任的溝通不良。"}]', '{"verb":"miscommunicate"}', NULL, 5, 4300, NULL),
(4301, 'misconduct', '/ˌmɪsˈkɑːndʌkt/', 'noun', '{"zh-TW":["不當行為；瀆職"],"en":["unacceptable or improper behavior, especially by a professional"]}', NULL, 'professional/employee misconduct / allegations of misconduct', '[{"en":"He was fired for gross misconduct.","zh-TW":"他因嚴重不當行為被解僱。"},{"en":"The investigation found evidence of financial misconduct.","zh-TW":"調查發現了財務不當行為的證據。"}]', '{"noun":"misconduct"}', NULL, 4, 4301, NULL),
(4302, 'mise en place', '/''miːz ɒn plɑːs/', 'noun', '{"zh-TW":["廚房備料；一切就緒"],"en":["a French culinary concept meaning ''everything in its place''; the preparation and organization of ingredients before cooking"]}', NULL, 'practice mise en place / mise en place technique / good mise en place', '[{"en":"Professional chefs use mise en place to ensure smooth and efficient cooking.","zh-TW":"專業廚師使用廚房備料確保烹飪順暢高效。"},{"en":"Preparing your mise en place before you start cooking reduces stress and mistakes.","zh-TW":"在開始烹飪之前準備好所有食材可以減少壓力和錯誤。"}]', NULL, NULL, 5, 4302, NULL),
(4303, 'misinformation', '/''mɪsɪnfəˌmeɪʃən/', 'noun', '{"zh-TW":["錯誤訊息；謊言"],"en":["false or inaccurate information, especially that which is deliberately intended to deceive"]}', NULL, 'spread misinformation / combat misinformation / misinformation campaign', '[{"en":"Social media platforms are working to reduce the spread of misinformation.","zh-TW":"社交媒體平台正在努力減少錯誤訊息的傳播。"},{"en":"Educators teach students how to identify and avoid misinformation online.","zh-TW":"教育工作者教學生如何識別和避免網絡上的錯誤訊息。"}]', '{"noun2":"misinformer","verb":"misinform"}', NULL, 5, 4303, NULL),
(4304, 'mislead', '/ˌmɪsˈliːd/', 'verb', '{"zh-TW":["誤導；使產生錯誤印象"],"en":["to cause someone to have a wrong impression"]}', NULL, 'mislead consumers/investors / misleading information', '[{"en":"The advertisement was found to mislead consumers.","zh-TW":"該廣告被發現誤導消費者。"},{"en":"Don''t be misled by the low price.","zh-TW":"不要被低價格所誤導。"}]', '{"verb":"mislead","adjective":"misleading"}', NULL, 3, 4304, NULL),
(4305, 'miss', '/mɪs/', 'verb', '{"zh-TW":["錯過；想念"],"en":["to fail to attend or catch","to feel sad about absence"]}', NULL, 'miss the point / miss a deadline', '[{"en":"We cannot miss this opportunity.","zh-TW":"我們不能錯過這個機會。"},{"en":"Don''t miss the deadline.","zh-TW":"別錯過截止日期。"}]', '{"verb":"miss","adjective":"missing","noun":"miss"}', NULL, 1, 4305, NULL),
(4306, 'mission', 'ˈmɪʃən', 'noun', '{"zh-TW":["使命；任務","宗旨"],"en":["a purpose or goal","a duty assigned"]}', NULL, 'company mission/mission statement', '[{"en":"Our mission is to serve customers globally.","zh-TW":"我們的使命是在全球服務客戶。"}]', '{"adjective":"mission-driven"}', NULL, 3, 4306, 158),
(4307, 'mission statement', '/ˈmɪʃən ˌsteɪtmənt/', 'noun', '{"zh-TW":["使命宣言"],"en":["a formal statement of a company''s purpose and objectives"]}', NULL, 'write a mission statement / company mission statement', '[{"en":"The mission statement guides all strategic decisions.","zh-TW":"使命宣言指導所有策略決策。"},{"en":"They revised the mission statement to reflect new goals.","zh-TW":"他們修訂了使命宣言以反映新目標。"}]', NULL, NULL, 5, 4307, NULL),
(4308, 'mistake', '/mɪˈsteɪk/', 'noun', '{"zh-TW":["錯誤"],"en":["something done incorrectly"]}', NULL, 'make a mistake / by mistake', '[{"en":"Everyone makes mistakes sometimes.","zh-TW":"每個人有時都會犯錯。"},{"en":"I sent the email by mistake.","zh-TW":"我不小心寄了那封郵件。"}]', '{"noun":"mistake","verb":"mistake","adjective":"mistaken"}', NULL, 3, 4308, NULL),
(4309, 'misunderstand', '/ˌmɪsʌndərˈstænd/', 'verb', '{"zh-TW":["誤解；誤會"],"en":["to fail to understand correctly"]}', NULL, 'misunderstand instructions/intentions', '[{"en":"I think you misunderstood my intentions.","zh-TW":"我想你誤解了我的意思。"},{"en":"The email was misunderstood by several recipients.","zh-TW":"這封電子郵件被幾位收件者誤解了。"}]', '{"noun":"misunderstanding","verb":"misunderstand"}', NULL, 5, 4309, NULL),
(4310, 'mitigate', '/ˈmɪtɪɡeɪt/', 'verb', '{"zh-TW":["減輕；緩和"],"en":["to make something less severe or harmful"]}', NULL, 'mitigate risk/damage/effects', '[{"en":"Steps were taken to mitigate the environmental impact.","zh-TW":"已採取措施減輕環境影響。"},{"en":"Insurance can help mitigate financial risk.","zh-TW":"保險可以幫助減輕財務風險。"}]', '{"noun":"mitigation","verb":"mitigate","adjective":"mitigating"}', NULL, 3, 4310, 698),
(4311, 'mitigation', '/ˌmɪtɪˈɡeɪʃən/', 'noun', '{"zh-TW":["緩解；減輕"],"en":["actions taken to reduce the severity of a risk or problem"]}', NULL, 'risk mitigation / mitigation measures / mitigation strategy', '[{"en":"The project team developed mitigation measures for identified risks.","zh-TW":"項目團隊為識別的風險制定了緩解措施。"},{"en":"Mitigation efforts reduced the financial impact of the disruption.","zh-TW":"緩解工作降低了中斷的財務影響。"}]', '{"verb":"mitigate","adjective":"mitigated"}', NULL, 4, 4311, 892),
(4312, 'mix', '/mɪks/', 'verb', '{"zh-TW":["混合"],"en":["to combine different things together"]}', NULL, 'product mix / mix up', '[{"en":"We need a better product mix.","zh-TW":"我們需要更好的產品組合。"},{"en":"There was a mix-up with the orders.","zh-TW":"訂單搞混了。"}]', '{"verb":"mix","noun":"mix","noun2":"mixture","noun3":"mix-up"}', NULL, 1, 4312, NULL),
(4313, 'mixed-use development', '/''mɪkst juːs dɪˌveləpmənt/', 'noun', '{"zh-TW":["混合用途開發；綜合用途發展"],"en":["a type of urban development that combines residential, commercial, and sometimes industrial uses"]}', NULL, 'plan a mixed-use development / mixed-use development project / benefit of mixed-use development', '[{"en":"Mixed-use developments create vibrant neighborhoods by placing housing, shops, and offices together.","zh-TW":"混合用途開發通過將住宅、商店和辦公室集中在一起，創造充滿活力的社區。"},{"en":"The city approved a mixed-use development that includes apartments, retail space, and a park.","zh-TW":"市政府批准了一個包含公寓、零售空間和公園的混合用途開發項目。"}]', '{"adjective":"mixed-use"}', NULL, 5, 4313, NULL),
(4314, 'mobile', '/ˈmoʊbl/', 'adjective, noun', '{"zh-TW":["移動的；手機的","行動電話"],"en":["able to move easily; relating to cell phones","a cell phone"]}', NULL, 'mobile device/app/phone / mobile banking', '[{"en":"Mobile banking has become increasingly popular.","zh-TW":"行動銀行越來越受歡迎。"},{"en":"More users access the site via mobile devices.","zh-TW":"越來越多用戶通過行動裝置訪問網站。"}]', '{"noun":"mobile, mobility","adjective":"mobile","verb":"mobilize"}', NULL, 2, 4314, NULL),
(4315, 'mobile check-in', '/ˈməʊbaɪl ˈtʃɛkɪn/', 'noun', '{"zh-TW":["手機報到"],"en":["the process of checking in using a smartphone"]}', NULL, 'use mobile check-in / mobile check-in option', '[{"en":"Mobile check-in saves time at the airport.","zh-TW":"手機報到可以節省在機場的時間。"},{"en":"Download the airline app to use mobile check-in.","zh-TW":"下載航空公司應用程式以使用手機報到。"}]', NULL, NULL, 5, 4315, NULL),
(4316, 'mobility', '/moʊˈbɪləti/', 'noun', '{"zh-TW":["流動性；移動性"],"en":["the ability to move freely; social advancement"]}', NULL, 'social/career mobility / labor mobility', '[{"en":"Career mobility is important to today''s workforce.","zh-TW":"職業流動性對當今勞動力很重要。"},{"en":"The new policy promotes upward social mobility.","zh-TW":"新政策促進了社會向上流動。"}]', '{"noun":"mobility, mobile","adjective":"mobile","verb":"mobilize"}', NULL, 3, 4316, NULL),
(4317, 'mobilize', '/ˈmoʊbɪlaɪz/', 'verb', '{"zh-TW":["動員；調動"],"en":["to organize resources or people for a specific purpose or action"]}', NULL, 'mobilize resources / mobilize a team', '[{"en":"The project manager mobilized the team quickly after contract signing.","zh-TW":"合約簽署後，項目經理迅速動員了團隊。"},{"en":"The government mobilized emergency funds to address the crisis.","zh-TW":"政府調動了緊急資金應對危機。"}]', '{"noun":"mobilization","adjective":"mobilized"}', NULL, 3, 4317, 699),
(4318, 'model drift', '/ˈmɒdəl drɪft/', 'noun', '{"zh-TW":["模型漂移"],"en":["the degradation of model performance over time as real-world data changes"]}', NULL, 'detect model drift / model drift monitoring / address model drift', '[{"en":"Model drift occurs when real-world patterns diverge from training data.","zh-TW":"當現實世界的模式與訓練數據分歧時，模型漂移就會發生。"},{"en":"Automated monitoring systems alert teams when model drift is detected.","zh-TW":"自動監控系統在檢測到模型漂移時提醒團隊。"}]', NULL, NULL, 4, 4318, NULL),
(4319, 'model portfolio', '/ˈmɒdəl pɔːrtˈfoʊlioʊ/', 'noun', '{"zh-TW":["示範投資組合；模型組合"],"en":["a pre-designed investment portfolio serving as a benchmark or recommendation"]}', NULL, 'follow a model portfolio / build a model portfolio', '[{"en":"The advisor presented a model portfolio aligned to a moderate risk profile.","zh-TW":"顧問展示了符合適中風險偏好的示範投資組合。"},{"en":"Model portfolios simplify investment decisions for retail clients.","zh-TW":"示範投資組合簡化了零售客戶的投資決策。"}]', NULL, NULL, 5, 4319, NULL),
(4320, 'moderate', '/ˈmɑːdərət/', 'adjective, verb', '{"zh-TW":["適度的；中等的","調節；緩和"],"en":["average in amount; not extreme","to make less extreme"]}', NULL, 'moderate growth/risk/climate', '[{"en":"The company experienced moderate growth this year.","zh-TW":"公司今年經歷了適度的增長。"},{"en":"The chairman moderated the discussion.","zh-TW":"主席主持了討論。"}]', '{"noun":"moderation, moderator","adjective":"moderate","verb":"moderate","adverb":"moderately"}', NULL, 3, 4320, 700),
(4321, 'modern', '/ˈmɒdərn/', 'adjective', '{"zh-TW":["現代的"],"en":["relating to the present time"]}', NULL, 'modern technology / modern design', '[{"en":"The office has a modern design.","zh-TW":"辦公室採用了現代設計。"},{"en":"Modern technology makes work easier.","zh-TW":"現代科技使工作更容易。"}]', '{"adjective":"modern","verb":"modernize","noun":"modernity","noun2":"modernization"}', NULL, 2, 4321, NULL),
(4322, 'modest', '/ˈmɒdɪst/', 'adjective', '{"zh-TW":["謙虛的；適度的"],"en":["unassuming in attitude","relatively moderate or small"]}', '{"root":{"text":"mod","meaning":"measure (適度)"},"suffix":{"text":"-est","meaning":"most (最)"},"logic":"保持適度的，即「謙虛的」。"}', 'modest income / modest improvement', '[{"en":"She is modest about her achievements.","zh-TW":"她對自己的成就很謙虛。"},{"en":"They live in a modest apartment.","zh-TW":"他們住在一間簡樸的公寓。"}]', '{"noun":"modesty","adverb":"modestly"}', NULL, 2, 4322, NULL),
(4323, 'modification', 'ˌmɒdɪfɪˈkeɪʃən', 'noun', '{"zh-TW":["修改；調整","變更"],"en":["a small change made","the act of modifying"]}', NULL, 'product modification/contract modification', '[{"en":"Please review the proposed modifications.","zh-TW":"請審查建議的修改。"}]', '{"verb":"modify","adjective":"modified"}', NULL, 4, 4323, 595),
(4324, 'modify', '/ˈmɒdɪfaɪ/', 'verb', '{"zh-TW":["修改；調整"],"en":["to make partial changes to something"]}', '{"root":{"text":"mod","meaning":"manner/measure (方式/適度)"},"suffix":{"text":"-ify","meaning":"make (使)"},"logic":"使其改變方式，即「修改」。"}', 'modify a plan / modify behavior / genetically modified; modify a plan/design/policy', '[{"en":"We need to modify the design slightly.","zh-TW":"我們需要稍微修改設計。"},{"en":"The software has been modified to fix the bug.","zh-TW":"軟體已被修改以修復錯誤。"},{"en":"We need to modify the proposal based on feedback.","zh-TW":"我們需要根據反饋修改提案。"},{"en":"The software was modified to fix the bug.","zh-TW":"軟體被修改以修復錯誤。"}]', '{"noun":"modification","adjective":"modified","verb":"modify"}', NULL, 2, 4324, 159),
(4325, 'modular', '/ˈmɒdjʊlər/', 'adjective', '{"zh-TW":["模組化的；組合式的"],"en":["employing or consisting of separable units or modules"]}', NULL, 'modular design / modular architecture / modular approach', '[{"en":"A modular software architecture allows components to be replaced independently.","zh-TW":"模組化軟件架構允許組件獨立替換。"},{"en":"Modular construction methods reduce costs and accelerate building timelines.","zh-TW":"模組化建設方法降低成本並加快建設時間表。"}]', '{"noun":"module","adverb":"modularly"}', NULL, 3, 4325, NULL),
(4326, 'module', '/ˈmɒdjuːl/', 'noun', '{"zh-TW":["模組；課程單元"],"en":["a self-contained unit of a course of study"]}', NULL, 'complete a module / module assessment', '[{"en":"Each module includes readings, videos, and a quiz.","zh-TW":"每個課程單元包含閱讀材料、影片和測驗。"},{"en":"The course is divided into six modules.","zh-TW":"課程分為六個單元。"}]', NULL, NULL, 2, 4326, 893),
(4327, 'moisture', '/ˈmɔɪstʃər/', 'noun', '{"zh-TW":["水分；濕氣"],"en":["tiny drops of water in the air or on a surface"]}', '{"root":{"text":"moist","meaning":"wet (潮濕)"},"suffix":{"text":"-ure","meaning":"state (狀態)"},"logic":"潮濕的狀態，即「水分」。"}', 'moisture level / retain moisture', '[{"en":"The cream helps your skin retain moisture.","zh-TW":"這款乳霜幫助肌膚保持水分。"},{"en":"Excess moisture can cause mold growth.","zh-TW":"過多的濕氣會導致黴菌生長。"}]', '{"adjective":"moist","verb":"moisturize","noun":"moisturizer"}', NULL, 3, 4327, NULL),
(4328, 'moment', '/ˈmoʊmənt/', 'noun', '{"zh-TW":["片刻；時刻"],"en":["a very short period of time"]}', NULL, 'at the moment / for the moment', '[{"en":"I am busy at the moment.","zh-TW":"我目前很忙。"},{"en":"For the moment, let''s wait.","zh-TW":"暫時我們等一下。"}]', '{"noun":"moment","adjective":"momentary","adjective2":"momentous"}', NULL, 2, 4328, NULL),
(4329, 'momentum', '/moʊˈmentəm/', 'noun', '{"zh-TW":["動力；勢頭"],"en":["the force gained by movement; impetus"]}', NULL, 'gain/build/lose momentum', '[{"en":"The project is gaining momentum.","zh-TW":"該項目正在獲得動力。"},{"en":"We must not lose the momentum we have built.","zh-TW":"我們不能失去已經建立的勢頭。"}]', '{"noun":"momentum"}', NULL, 3, 4329, NULL),
(4330, 'monetary', '/ˈmɑːnɪteri/', 'adjective', '{"zh-TW":["貨幣的；金融的"],"en":["relating to money or currency"]}', NULL, 'monetary policy / monetary value / monetary system', '[{"en":"The central bank adjusted its monetary policy.","zh-TW":"央行調整了其貨幣政策。"},{"en":"The painting has both monetary and sentimental value.","zh-TW":"這幅畫既有金錢價值，也有情感價值。"}]', '{"noun":"money","adjective":"monetary"}', NULL, 3, 4330, NULL),
(4331, 'monetary policy', '/ˈmɒnɪtəri ˈpɒlɪsi/', 'noun', '{"zh-TW":["貨幣政策"],"en":["central bank management of money supply and interest rates"]}', NULL, 'tighten monetary policy / loose monetary policy / monetary policy decision', '[{"en":"The central bank tightened monetary policy to cool inflation.","zh-TW":"中央銀行收緊貨幣政策以遏制通貨膨脹。"},{"en":"Monetary policy decisions affect borrowing costs nationwide.","zh-TW":"貨幣政策決定影響全國的借貸成本。"}]', '{"adjective":"monetary"}', NULL, 5, 4331, NULL),
(4332, 'monetary union', '/ˈmɒnɪtəri ˈjuːnjən/', 'noun', '{"zh-TW":["貨幣聯盟"],"en":["an agreement between countries to share a single currency and monetary policy"]}', NULL, 'join a monetary union / monetary union benefits', '[{"en":"Member states of a monetary union give up independent exchange rate policy.","zh-TW":"貨幣聯盟成員國放棄了獨立的匯率政策。"},{"en":"A monetary union reduces transaction costs in cross-border trade.","zh-TW":"貨幣聯盟降低了跨境貿易中的交易成本。"}]', NULL, NULL, 5, 4332, NULL),
(4333, 'monetize', '/ˈmɒnɪtaɪz/', 'verb', '{"zh-TW":["貨幣化；變現"],"en":["to convert an asset or activity into a source of income"]}', NULL, 'monetize a platform / monetize data / monetize content', '[{"en":"The startup found multiple ways to monetize its large user base.","zh-TW":"新創公司找到了多種方式將其龐大的用戶基礎變現。"},{"en":"Monetizing content through advertising is common for media companies.","zh-TW":"通過廣告將內容貨幣化對媒體公司來說很常見。"}]', '{"noun":"monetization","adjective":"monetized"}', NULL, 3, 4333, NULL),
(4334, 'money', '/ˈmʌni/', 'noun', '{"zh-TW":["金錢"],"en":["coins and notes used to buy things"]}', NULL, 'make money / money management', '[{"en":"The company makes money from subscriptions.","zh-TW":"公司靠訂閱賺錢。"},{"en":"Good money management is essential.","zh-TW":"良好的資金管理至關重要。"}]', '{"noun":"money","adjective":"monetary"}', NULL, 2, 4334, NULL),
(4335, 'money laundering', '/ˈmʌni ˈlɔːndərɪŋ/', 'noun', '{"zh-TW":["洗錢"],"en":["the process of making illegally obtained money appear legitimate"]}', NULL, 'prevent money laundering / anti-money laundering', '[{"en":"Banks must implement anti-money laundering controls.","zh-TW":"銀行必須實施反洗錢管控措施。"},{"en":"The compliance team monitors transactions to detect money laundering.","zh-TW":"合規團隊監控交易以發現洗錢行為。"}]', NULL, NULL, 5, 4335, NULL),
(4336, 'money market', '/ˈmʌni ˈmɑːrkɪt/', 'noun', '{"zh-TW":["貨幣市場"],"en":["the financial market for short-term borrowing and lending of funds"]}', NULL, 'invest in the money market / money market instrument', '[{"en":"Surplus funds were placed in money market instruments overnight.","zh-TW":"多餘資金被投入隔夜貨幣市場工具。"},{"en":"Money market rates influence the cost of short-term business financing.","zh-TW":"貨幣市場利率影響了短期商業融資成本。"}]', NULL, NULL, 4, 4336, NULL),
(4337, 'monitor', '/ˈmɒnɪtər/', 'verb', '{"zh-TW":["監控；監視","監控器；監視器","監控；監測"],"en":["to observe and check over a period of time","a screen or device for observing","to observe and check over time"]}', '{"root":{"text":"monit","meaning":"warn (警告)"},"suffix":{"text":"-or","meaning":"that which (…的東西)"},"logic":"提出警告的觀察，即「監控」。"}', 'monitor progress / monitor closely / heart monitor; monitor progress/performance/activity', '[{"en":"We will monitor the situation closely.","zh-TW":"我們將密切監控局勢。"},{"en":"The doctor monitors his blood pressure regularly.","zh-TW":"醫生定期監測他的血壓。"},{"en":"We use software to monitor network activity.","zh-TW":"我們使用軟體來監控網路活動。"},{"en":"The team monitors customer satisfaction closely.","zh-TW":"團隊密切監測客戶滿意度。"}]', '{"noun":"monitor","noun2":"monitoring","verb":"monitor"}', NULL, 3, 4337, 160),
(4338, 'monograph', '/ˈmɒnəɡrɑːf/', 'noun', '{"zh-TW":["專題論著；學術專著"],"en":["a detailed written study of a single specialized subject"]}', NULL, 'academic monograph / publish a monograph / scholarly monograph', '[{"en":"The historian published a monograph on the economic causes of the revolution.","zh-TW":"歷史學家發表了一部關於革命經濟原因的學術專著。"},{"en":"A monograph demonstrates mastery of a narrow but important topic.","zh-TW":"專題論著展示了對一個狹窄但重要主題的精通程度。"}]', NULL, NULL, 3, 4338, NULL),
(4339, 'monologue', '/ˈmɒnəlɒɡ/', 'noun', '{"zh-TW":["獨白；長篇大論"],"en":["a long speech by one person; a dramatic piece performed by one actor"]}', NULL, 'dramatic monologue / interior monologue / deliver a monologue', '[{"en":"The actor''s monologue captured the character''s inner turmoil beautifully.","zh-TW":"演員的獨白精美地捕捉了角色的內心動盪。"},{"en":"She performed a ten-minute monologue at the audition.","zh-TW":"她在試鏡時表演了十分鐘的獨白。"}]', '{"adjective":"monologic"}', NULL, 3, 4339, NULL),
(4340, 'monopolize', '/məˈnɑːpəlaɪz/', 'verb', '{"zh-TW":["壟斷；獨占"],"en":["to have exclusive control over"]}', NULL, 'monopolize the market/conversation', '[{"en":"One company should not monopolize the entire market.","zh-TW":"一家公司不應壟斷整個市場。"},{"en":"He tends to monopolize every meeting.","zh-TW":"他傾向於在每次會議中獨占發言。"}]', '{"noun":"monopoly","verb":"monopolize","adjective":"monopolistic"}', NULL, 4, 4340, NULL),
(4341, 'monopoly', '/məˈnɑːpəli/', 'noun', '{"zh-TW":["壟斷；獨占"],"en":["exclusive control of a commodity or service"]}', NULL, 'have a monopoly on / break a monopoly', '[{"en":"The company has a virtual monopoly on the market.","zh-TW":"該公司幾乎壟斷了市場。"},{"en":"The government moved to break up the monopoly.","zh-TW":"政府採取行動打破壟斷。"}]', '{"noun":"monopoly","verb":"monopolize","adjective":"monopolistic"}', NULL, 3, 4341, NULL),
(4342, 'monopsony', '/mɒˈnɒpsəni/', 'noun', '{"zh-TW":["買方壟斷"],"en":["a market situation in which only one buyer substantially controls the market as a purchaser"]}', NULL, 'labor monopsony / monopsony power / monopsony market', '[{"en":"A monopsony in the labor market allows one employer to set below-competitive wages.","zh-TW":"勞動力市場的買方壟斷使一個雇主能夠設定低於競爭水平的工資。"},{"en":"Amazon has been accused of using monopsony power in its dealings with suppliers.","zh-TW":"亞馬遜被指控在與供應商的交易中使用買方壟斷力量。"}]', '{"adjective":"monopsonistic"}', NULL, 3, 4342, NULL),
(4343, 'monsoon', '/mɒnˈsuːn/', 'noun', '{"zh-TW":["季風；雨季"],"en":["a seasonal wind bringing heavy rain"]}', '{"root":{"text":"mausim","meaning":"season (季節)"},"logic":"源自阿拉伯語 mausim（季節），指季節性風帶來的大雨。"}', 'monsoon season / monsoon rain', '[{"en":"The monsoon season brings heavy rainfall.","zh-TW":"雨季帶來大量降雨。"},{"en":"Flooding is common during the monsoon.","zh-TW":"雨季期間洪水很常見。"}]', '{"adjective":"monsoonal"}', NULL, 3, 4343, NULL),
(4344, 'month', '/mʌnθ/', 'noun', '{"zh-TW":["月份"],"en":["one of the twelve periods of a year"]}', NULL, 'per month / month-end', '[{"en":"Revenue increased month over month.","zh-TW":"營收逐月增加。"},{"en":"The report is due at month-end.","zh-TW":"報告月底截止。"}]', '{"noun":"month","adjective":"monthly"}', NULL, 2, 4344, NULL),
(4345, 'monthly recurring revenue', '/ˈmʌnθli rɪˈkɜːrɪŋ ˈrevənjuː/', 'noun', '{"zh-TW":["每月經常性收入"],"en":["the predictable revenue a business expects to receive every month from subscriptions"]}', NULL, 'track monthly recurring revenue / grow monthly recurring revenue', '[{"en":"The SaaS company''s monthly recurring revenue grew 15% quarter over quarter.","zh-TW":"SaaS公司的每月經常性收入環比增長了15%。"},{"en":"Investors value SaaS companies highly based on monthly recurring revenue.","zh-TW":"投資者根據每月經常性收入高度評估SaaS公司的價值。"}]', '{"abbreviation":"MRR"}', NULL, 5, 4345, NULL),
(4346, 'monthly report', '/ˈmʌnθli rɪˈpɔːrt/', 'noun', '{"zh-TW":["月度報告；月報"],"en":["a regular report covering a company performance over the previous month"]}', NULL, 'submit a monthly report / review the monthly report', '[{"en":"All department heads submit monthly reports on the fifth of each month.","zh-TW":"所有部門主管在每月五日提交月度報告。"},{"en":"Monthly reports track progress against annual targets.","zh-TW":"月度報告追蹤年度目標的進展。"}]', NULL, NULL, 5, 4346, NULL),
(4347, 'monument', '/''mɒnjʊmənt/', 'noun', '{"zh-TW":["紀念碑；遺址"],"en":["a statue or structure erected to commemorate a notable person or event"]}', NULL, 'erect a monument / national monument / historic monument', '[{"en":"The monument was erected to honor soldiers who died in the war.","zh-TW":"這座紀念碑是為了紀念在戰爭中犧牲的士兵而建立的。"},{"en":"Tourists flocked to photograph the iconic monument at sunset.","zh-TW":"遊客們蜂擁而至，在日落時分拍攝這座標誌性紀念碑。"}]', NULL, NULL, 3, 4347, NULL),
(4348, 'moral hazard', '/ˈmɒrəl ˈhæzərd/', 'noun', '{"zh-TW":["道德風險"],"en":["the tendency to take greater risks when one is insulated from the consequences"]}', NULL, 'reduce moral hazard / moral hazard in insurance', '[{"en":"Insurance creates moral hazard by reducing the insured''s incentive to avoid loss.","zh-TW":"保險通過降低被保險人避免損失的動力而產生了道德風險。"},{"en":"Moral hazard is a major concern in government bailouts of failing companies.","zh-TW":"道德風險是政府援助破產公司時的主要擔憂。"}]', NULL, NULL, 4, 4348, NULL),
(4349, 'moral panic', '/ˈmɒrəl ˈpænɪk/', 'noun', '{"zh-TW":["道德恐慌"],"en":["widespread fear about a perceived threat to social values"]}', NULL, 'media-fueled moral panic / create a moral panic / moral panic about youth', '[{"en":"The moral panic over video games led to excessive regulation.","zh-TW":"關於電子遊戲的道德恐慌導致了過度監管。"},{"en":"Social media amplifies moral panics by spreading alarm rapidly.","zh-TW":"社交媒體通過快速傳播警報來放大道德恐慌。"}]', NULL, NULL, 4, 4349, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4350, 'morale', '/məˈræl/', 'noun', '{"zh-TW":["士氣；精神面貌"],"en":["the confidence and enthusiasm of a person or group"]}', NULL, 'boost/raise morale / low/high morale / employee morale', '[{"en":"Employee morale has improved since the new policy.","zh-TW":"自從新政策實施以來，員工士氣有所提高。"},{"en":"The bonus helped boost team morale.","zh-TW":"獎金有助於提振團隊士氣。"}]', '{"noun":"morale"}', NULL, 2, 4350, NULL),
(4351, 'moratorium', '/ˌmɒrəˈtɔːriəm/', 'noun', '{"zh-TW":["暫停；延期執行"],"en":["a temporary suspension of an activity or obligation"]}', NULL, 'declare a moratorium / lift a moratorium / debt moratorium', '[{"en":"The government declared a moratorium on evictions during the crisis.","zh-TW":"政府在危機期間宣佈暫停驅逐令。"},{"en":"A debt moratorium gave companies time to restructure their obligations.","zh-TW":"債務延期給予公司時間重組其義務。"}]', '{"plural":"moratoriums"}', NULL, 4, 4351, NULL),
(4352, 'moreover', '/mɔːrˈoʊvər/', 'adverb', '{"zh-TW":["此外；而且"],"en":["in addition to what has been said"]}', NULL, 'moreover, ... (sentence connector)', '[{"en":"The plan is cost-effective; moreover, it is environmentally friendly.","zh-TW":"這個計劃具有成本效益；此外，它還環保。"},{"en":"Moreover, the new system will save time.","zh-TW":"此外，新系統將節省時間。"}]', '{"adverb":"moreover"}', NULL, 3, 4352, NULL),
(4353, 'morning', '/ˈmɔːrnɪŋ/', 'noun', '{"zh-TW":["早上；上午"],"en":["the early part of the day"]}', NULL, 'good morning / morning shift', '[{"en":"Good morning, everyone.","zh-TW":"大家早安。"},{"en":"The morning shift starts at 6 a.m.","zh-TW":"早班從早上6點開始。"}]', '{"noun":"morning"}', NULL, 3, 4353, NULL),
(4354, 'mortgage', '/ˈmɔːrɡɪdʒ/', 'noun, verb', '{"zh-TW":["抵押貸款；房貸"],"en":["a loan for buying property, secured against that property"]}', NULL, 'mortgage payment / pay off a mortgage / mortgage rate', '[{"en":"They took out a 30-year mortgage on their house.","zh-TW":"他們辦了一筆30年的房貸。"},{"en":"Mortgage rates have increased this quarter.","zh-TW":"本季度房貸利率有所上升。"}]', '{"noun":"mortgage","verb":"mortgage"}', NULL, 3, 4354, NULL),
(4355, 'mortgage approval', '/''mɔːrɡɪdʒ əˌpruːvəl/', 'noun', '{"zh-TW":["按揭批准；房貸核准"],"en":["official confirmation from a lender that a mortgage application has been accepted"]}', NULL, 'receive mortgage approval / obtain mortgage approval / conditional mortgage approval', '[{"en":"She received mortgage approval after submitting three years of financial statements.","zh-TW":"她在提交三年財務報表後獲得了按揭批准。"},{"en":"Mortgage approval was conditional on the property passing a structural survey.","zh-TW":"按揭批准以房產通過結構檢測為條件。"}]', NULL, NULL, 5, 4355, NULL),
