(5400, 'ratio', '/ˈreɪʃioʊ/', 'noun', '{"zh-TW":["比率；比例"],"en":["the relationship between two numbers"]}', '{"root":{"text":"rat","meaning":"reckon (計算)"}}', 'debt-to-equity ratio / ratio of...to... / maintain a ratio', '[{"en":"The debt-to-equity ratio is 2:1.","zh-TW":"債務權益比為2:1。"},{"en":"What is the ratio of managers to employees?","zh-TW":"經理與員工的比例是多少？"}]', NULL, NULL, 2, 5400, NULL),
(5401, 'rational', '/ˈræʃənəl/', 'adjective', '{"zh-TW":["理性的；合理的"],"en":["based on reason; logical"]}', '{"root":{"text":"ration","meaning":"reason (理性)"},"suffix":{"text":"-al","meaning":"...的"}}', 'rational decision / rational thinking / rational approach', '[{"en":"We need to make a rational decision.","zh-TW":"我們需要做出理性決定。"},{"en":"His approach was entirely rational.","zh-TW":"他的方法完全合理。"}]', '{"noun":"rationality, rationale","adverb":"rationally","verb":"rationalize"}', NULL, 3, 5401, NULL),
(5402, 'rational choice theory', '/ˈræʃənəl tʃɔɪs ˈθɪəri/', 'noun', '{"zh-TW":["理性選擇理論"],"en":["a framework assuming individuals make decisions to maximize utility"]}', NULL, 'apply rational choice theory / rational choice theory model / critique of rational choice theory', '[{"en":"Rational choice theory predicts that voters will support policies that benefit them.","zh-TW":"理性選擇理論預測選民將支持對其有利的政策。"},{"en":"Behavioral economics challenges rational choice theory by documenting cognitive biases.","zh-TW":"行為經濟學通過記錄認知偏見來挑戰理性選擇理論。"}]', NULL, NULL, 5, 5402, NULL),
(5403, 'rationale', '/ˌræʃəˈnɑːl/', 'noun', '{"zh-TW":["基本原理；理由"],"en":["the underlying reasons for a decision or action"]}', NULL, 'provide a rationale / explain the rationale', '[{"en":"Please provide the rationale for this budget request.","zh-TW":"請提供此預算申請的理由。"},{"en":"The rationale behind the restructuring was to improve efficiency.","zh-TW":"重組背後的基本原理是提高效率。"}]', NULL, NULL, 3, 5403, NULL),
(5404, 'rationalize', '/ˈræʃənəlaɪz/', 'verb', '{"zh-TW":["合理化；使合理"],"en":["to attempt to explain or justify behavior with logical reasons"]}', NULL, 'rationalize a decision / rationalize costs / rationalize behavior', '[{"en":"He rationalized his poor performance by blaming external factors.","zh-TW":"他通過怪罪外部因素來合理化自己的糟糕表現。"},{"en":"Companies rationalize their operations to improve efficiency.","zh-TW":"公司對運作進行合理化以提高效率。"}]', '{"noun":"rationalization","adjective":"rational"}', NULL, 4, 5404, NULL),
(5405, 'raw', '/rɔː/', 'adjective', '{"zh-TW":["原始的；未加工的"],"en":["not processed; in natural state"]}', NULL, 'raw materials / raw data / raw talent', '[{"en":"The cost of raw materials has increased.","zh-TW":"原材料成本已增加。"},{"en":"We need to analyze the raw data.","zh-TW":"我們需要分析原始數據。"}]', NULL, NULL, 1, 5405, NULL),
(5406, 'reach', '/riːtʃ/', 'verb', '{"zh-TW":["到達；達到"],"en":["to arrive at","to achieve"]}', NULL, 'reach an agreement / reach out', '[{"en":"We reached an agreement after long talks.","zh-TW":"經過長時間談判我們達成了協議。"},{"en":"Feel free to reach out anytime.","zh-TW":"隨時可以聯繫我們。"}]', '{"verb":"reach","noun":"reach"}', NULL, 2, 5406, NULL),
(5407, 'react', '/riˈækt/', 'verb', '{"zh-TW":["反應；回應"],"en":["to respond to something"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"act","meaning":"do (做)"}}', 'react to / react quickly / react negatively', '[{"en":"How did the market react to the news?","zh-TW":"市場對這消息如何反應？"},{"en":"She reacted quickly to the crisis.","zh-TW":"她對危機迅速做出反應。"}]', '{"noun":"reaction","adjective":"reactive"}', NULL, 2, 5407, NULL),
(5408, 'read', '/riːd/', 'verb', '{"zh-TW":["閱讀"],"en":["to look at and understand written words"]}', NULL, 'read carefully / well-read', '[{"en":"Please read the contract carefully.","zh-TW":"請仔細閱讀合約。"},{"en":"She is well-read in business literature.","zh-TW":"她廣泛閱讀商業文獻。"}]', '{"verb":"read","noun":"reader","noun2":"reading","adjective":"readable"}', NULL, 1, 5408, NULL),
(5409, 'readership', '/ˈriːdərʃɪp/', 'noun', '{"zh-TW":["讀者群；讀者人數"],"en":["the readers of a newspaper, magazine, or book collectively"]}', NULL, 'target readership / expand readership / loyal readership', '[{"en":"The magazine grew its readership through digital subscriptions.","zh-TW":"該雜誌通過數字訂閱擴大了讀者群。"},{"en":"A broad readership indicates a publication''s cultural influence.","zh-TW":"廣泛的讀者群表明出版物的文化影響力。"}]', NULL, NULL, 4, 5409, NULL),
(5410, 'reading comprehension', '/''riːdɪŋ ˌkɒmprɪˈhenʃən/', 'noun', '{"zh-TW":["閱讀理解"],"en":["the ability to understand and interpret written text"]}', NULL, 'improve reading comprehension / reading comprehension test / develop reading comprehension', '[{"en":"Reading comprehension is a fundamental skill assessed in most standardized tests.","zh-TW":"閱讀理解是大多數標準化測驗中評估的基本技能。"},{"en":"She practiced reading comprehension by summarizing each paragraph she read.","zh-TW":"她通過概括所讀的每個段落來練習閱讀理解。"}]', NULL, NULL, 5, 5410, NULL),
(5411, 'ready', '/ˈrɛdi/', 'adjective', '{"zh-TW":["準備好的"],"en":["prepared for action"]}', NULL, 'get ready / ready-made', '[{"en":"Are you ready for the presentation?","zh-TW":"你準備好報告了嗎？"},{"en":"We offer ready-made solutions.","zh-TW":"我們提供現成的解決方案。"}]', '{"adjective":"ready","noun":"readiness","verb":"ready"}', NULL, 2, 5411, NULL),
(5412, 'real', '/riːl/', 'adjective', '{"zh-TW":["真實的；實際的"],"en":["actually existing","genuine"]}', NULL, 'real estate / in real time', '[{"en":"She works in real estate.","zh-TW":"她從事房地產業。"},{"en":"We track data in real time.","zh-TW":"我們即時追蹤數據。"}]', '{"adjective":"real","noun":"reality","adverb":"really","adjective2":"realistic","verb":"realize"}', NULL, 1, 5412, NULL),
(5413, 'real assets', '/rɪəl ˈæsets/', 'noun', '{"zh-TW":["實物資產"],"en":["tangible assets with intrinsic value such as real estate, land, or commodities"]}', NULL, 'invest in real assets / real assets allocation / real assets portfolio', '[{"en":"Real assets provide inflation protection for long-term investors.","zh-TW":"實物資產為長期投資者提供通膨保護。"},{"en":"Pension funds allocate to real assets for stable, inflation-linked returns.","zh-TW":"養老基金配置實物資產以獲得穩定的通膨掛鉤回報。"}]', NULL, NULL, 4, 5413, NULL),
(5414, 'real estate', '/ˈrɪəl ɪˈsteɪt/', 'noun', '{"zh-TW":["房地產；不動產"],"en":["property consisting of land and buildings"]}', NULL, 'invest in real estate / commercial real estate', '[{"en":"Commercial real estate prices fell during the economic downturn.","zh-TW":"商業房地產價格在經濟低迷期間下跌了。"},{"en":"The company''s real estate portfolio includes offices in five cities.","zh-TW":"公司的房地產投資組合包括五個城市的辦公室。"}]', NULL, NULL, 4, 5414, NULL),
(5415, 'real estate agent', '/ˌrɪəl ɪˈsteɪt ˈeɪdʒənt/', 'noun', '{"zh-TW":["房地產經紀人"],"en":["a person who arranges the buying and selling of property"]}', NULL, 'hire a real estate agent / trusted real estate agent', '[{"en":"A real estate agent helped them find their dream home.","zh-TW":"房地產經紀人幫助他們找到了夢想中的家。"},{"en":"Choose a real estate agent with knowledge of the local market.","zh-TW":"選擇熟悉當地市場的房地產經紀人。"}]', NULL, NULL, 5, 5415, NULL),
(5416, 'real estate bubble', '/''riəl ɪˌsteɪt ˌbʌbəl/', 'noun', '{"zh-TW":["房地產泡沫"],"en":["a rapid increase in the value of real estate driven by speculation, often followed by a sharp decline"]}', NULL, 'real estate bubble burst / prevent a real estate bubble / recognize a real estate bubble', '[{"en":"Economists warned of a potential real estate bubble driven by speculative investment.","zh-TW":"經濟學家警告稱，投機性投資可能推動房地產泡沫的形成。"},{"en":"When the real estate bubble burst, many homeowners found themselves owing more than their homes were worth.","zh-TW":"當房地產泡沫破裂時，許多房主發現自己的欠款超過了房屋的價值。"}]', '{"noun":"bubble"}', NULL, 5, 5416, NULL),
(5417, 'real estate investment', '/''riəl ɪˌsteɪt ɪnˌvestmənt/', 'noun', '{"zh-TW":["房地產投資"],"en":["the purchase of property as a strategy to generate income or profit"]}', NULL, 'make a real estate investment / real estate investment trust / benefit of real estate investment', '[{"en":"Real estate investment is considered one of the most stable forms of wealth building.","zh-TW":"房地產投資被認為是最穩定的財富積累方式之一。"},{"en":"She diversified her portfolio by adding real estate investment to her financial strategy.","zh-TW":"她通過在財務策略中增加房地產投資來多元化其投資組合。"}]', '{"adjective":"real-estate","noun":"real estate investor"}', NULL, 5, 5417, NULL),
(5418, 'real estate investment trust', '/riːl ɪˈsteɪt ɪnˈvestmənt trʌst/', 'noun', '{"zh-TW":["不動產投資信託"],"en":["a company owning income-producing real estate that is publicly traded"]}', NULL, 'invest in a REIT / commercial REIT / residential REIT', '[{"en":"The REIT pays quarterly dividends from rental income.","zh-TW":"不動產投資信託從租金收入中每季支付股利。"},{"en":"REITs allow small investors to access commercial property markets.","zh-TW":"不動產投資信託允許小投資者進入商業地產市場。"}]', '{"abbreviation":"REIT"}', NULL, 5, 5418, NULL),
(5419, 'real-time data', '/ˌriːəl taɪm ˈdeɪtə/', 'noun', '{"zh-TW":["即時數據；實時數據"],"en":["information processed and available instantly as events occur"]}', NULL, 'access real-time data / real-time data dashboard', '[{"en":"The operations team uses real-time data to monitor production lines.","zh-TW":"運營團隊使用實時數據監控生產線。"},{"en":"Real-time data enables faster and more accurate business decisions.","zh-TW":"實時數據使業務決策更快更準確。"}]', NULL, NULL, 5, 5419, NULL),
(5420, 'realistic', 'rɪəˈlɪstɪk', 'adjective', '{"zh-TW":["現實的；實際的","可行的"],"en":["sensible and practical","based on reality"]}', NULL, 'realistic goal/realistic expectation', '[{"en":"Set realistic goals for the team.","zh-TW":"為團隊設定現實目標。"}]', '{"noun":"realism","adverb":"realistically"}', NULL, 3, 5420, NULL),
(5421, 'realize', '/ˈriːəlaɪz/', 'verb', '{"zh-TW":["【主要意義-動詞】意識到；理解","【次要意義-動詞】獲得（利潤）；實現（資產變現）","【次要意義-動詞】實現；成就（計劃）"],"en":["[primary] to become aware of a fact or situation","[secondary] to make a profit from selling assets; to convert assets to cash","[secondary] to achieve something that was planned"]}', '{"root":{"text":"real","meaning":"real (真實)"},"suffix":{"text":"-ize","meaning":"使...化"}}', 'realize a profit / realize assets / realize a goal / realize potential', '[{"en":"The company realized a substantial profit from the sale of its subsidiary.","zh-TW":"公司從出售子公司中獲得了可觀的利潤。"},{"en":"The new plan will help the organization realize its long-term strategic goals.","zh-TW":"新計劃將幫助組織實現其長期戰略目標。"},{"en":"Investors realized gains when the stock price hit a record high.","zh-TW":"當股價創下歷史新高時，投資者實現了收益。"}]', '{"noun":"realization"}', 'realize a profit/gain = 「實現（獲得）利潤/收益」是 TOEIC 財務文章的高頻表達，realize a goal = 「實現目標」也常見，考生常誤以為 realize 只有「意識到」的意思。', 3, 5421, NULL),
(5422, 'reallocation', '/ˌriːˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["重新分配；再分配"],"en":["the redistribution of resources, funds, or personnel to a different use"]}', NULL, 'budget reallocation / resource reallocation / labor reallocation', '[{"en":"Budget reallocation shifted funds from defense to social programs.","zh-TW":"預算重新分配將資金從國防轉移到社會計畫。"},{"en":"Economic shocks often require reallocation of labor across industries.","zh-TW":"經濟衝擊通常需要跨行業重新分配勞動力。"}]', '{"verb":"reallocate","adjective":"reallocated"}', NULL, 4, 5422, NULL),
(5423, 'reason', '/ˈriːzən/', 'noun', '{"zh-TW":["原因；理由"],"en":["the cause or explanation for something"]}', NULL, 'for this reason / the reason why / reason for / reasonable', '[{"en":"For this reason, we decided to postpone.","zh-TW":"基於這個原因，我們決定延期。"},{"en":"What is the reason for the delay?","zh-TW":"延遲的原因是什麼？"}]', '{"adjective":"reasonable","adverb":"reasonably","verb":"reason"}', NULL, 2, 5423, NULL),
(5424, 'reasonable', '/ˈriːzənəbl/', 'adjective', '{"zh-TW":["合理的；適當的"],"en":["fair; sensible; not too expensive"]}', '{"root":{"text":"reason","meaning":"reason (理由)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'reasonable price / reasonable request / within a reasonable time', '[{"en":"The price seems reasonable for the quality.","zh-TW":"就品質而言價格合理。"},{"en":"Please respond within a reasonable timeframe.","zh-TW":"請在合理時間內回覆。"}]', '{"adverb":"reasonably","noun":"reasonableness"}', NULL, 4, 5424, NULL),
(5425, 'rebalancing', '/riːˈbælənsɪŋ/', 'noun', '{"zh-TW":["重新平衡；再平衡"],"en":["restoring a portfolio or system to its intended state"]}', NULL, 'portfolio rebalancing / economic rebalancing / trigger rebalancing', '[{"en":"Annual rebalancing keeps an investment portfolio aligned with its target allocation.","zh-TW":"年度再平衡使投資組合與其目標配置保持一致。"},{"en":"China''s economic rebalancing shifted focus from exports to domestic consumption.","zh-TW":"中國的經濟再平衡將重心從出口轉向內需消費。"}]', '{"verb":"rebalance","adjective":"rebalanced"}', NULL, 4, 5425, NULL),
(5426, 'rebate', '/ˈriːbeɪt/', 'noun', '{"zh-TW":["回扣；折讓"],"en":["a partial refund or discount given after a purchase"]}', NULL, 'offer a rebate / volume rebate / claim a rebate / rebate program', '[{"en":"The manufacturer offered a $50 rebate on purchases over $200.","zh-TW":"製造商對超過200美元的購買提供50美元的回扣。"},{"en":"Volume rebates incentivize customers to buy in larger quantities.","zh-TW":"數量折讓激勵客戶以更大的數量購買。"}]', '{"verb":"rebate"}', NULL, 2, 5426, NULL),
(5427, 'rebranding', '/riːˈbrændɪŋ/', 'noun', '{"zh-TW":["重新品牌化；品牌重塑"],"en":["changing the brand identity of an existing company or product"]}', NULL, 'undergo rebranding / rebranding campaign / successful rebranding', '[{"en":"The rebranding campaign refreshed the company''s outdated image.","zh-TW":"重新品牌化活動更新了公司過時的形象。"},{"en":"Rebranding was necessary after the merger to unify identities.","zh-TW":"合併後需要重新品牌化以統一品牌形象。"}]', '{"verb":"rebrand"}', NULL, 4, 5427, NULL),
(5428, 'recalibrate', '/''riːˌkælɪbreɪt/', 'verb', '{"zh-TW":["重新校準；調整方向"],"en":["to calibrate again; to adjust or change to meet new conditions or requirements"]}', NULL, 'recalibrate the strategy / recalibrate expectations / recalibrate approach', '[{"en":"After the market changed, the team needed to recalibrate their sales strategy.","zh-TW":"市場改變後，團隊需要重新校準他們的銷售策略。"},{"en":"The project manager recalibrated the timeline after receiving new information.","zh-TW":"項目經理在收到新信息後重新調整了時間表。"}]', '{"noun":"recalibration"}', NULL, 4, 5428, NULL),
(5429, 'recapitalize', '/riːˈkæpɪtəlaɪz/', 'verb', '{"zh-TW":["重新資本化；重組資本結構"],"en":["to change the capital structure of a company"]}', NULL, 'recapitalize a bank / recapitalize the business / recapitalize the balance sheet', '[{"en":"The government recapitalized the struggling bank to prevent collapse.","zh-TW":"政府重新資本化了掙扎中的銀行以防止崩潰。"},{"en":"The firm recapitalized by issuing new shares and retiring old debt.","zh-TW":"公司通過發行新股和退休舊債進行了重新資本化。"}]', '{"noun":"recapitalization","adjective":"recapitalized"}', NULL, 4, 5429, NULL),
(5430, 'receipt', '/rɪˈsiːt/', 'noun', '{"zh-TW":["收據","收據；收到"],"en":["a written acknowledgment of payment","a written proof of payment"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ceipt","meaning":"take (拿取)"},"logic":"拿回的證明，即「收據」。"}', 'keep the receipt / receipt printer; keep the receipt / upon receipt of / acknowledge receipt', '[{"en":"Please keep your receipt for returns.","zh-TW":"請保留收據以便退貨。"},{"en":"The receipt shows the date of purchase.","zh-TW":"收據上顯示購買日期。"},{"en":"Upon receipt of your payment, we will ship the order.","zh-TW":"收到付款後我們將發貨。"}]', NULL, NULL, 3, 5430, 190),
(5431, 'receivable', '/rɪˈsiːvəbəl/', 'noun', '{"zh-TW":["應收帳款"],"en":["money owed to a business by its customers"]}', NULL, 'accounts receivable / collect receivables', '[{"en":"Accounts receivable totaled $3 million.","zh-TW":"應收帳款總計300萬美元。"},{"en":"We need to collect outstanding receivables.","zh-TW":"我們需要收取未結應收帳款。"}]', '{"noun":"receivable","adjective":"receivable","verb":"receive"}', NULL, 4, 5431, 917),
(5432, 'receivables', '/rɪˈsiːvəbəlz/', 'noun', '{"zh-TW":["應收帳款"],"en":["amounts owed to a company for goods or services already delivered"]}', NULL, 'collect receivables / days receivables outstanding', '[{"en":"The company improved cash flow by accelerating collection of receivables.","zh-TW":"公司通過加速應收帳款的收款改善了現金流。"},{"en":"Factoring receivables provides immediate liquidity.","zh-TW":"應收帳款保理提供了即時流動性。"}]', NULL, NULL, 4, 5432, NULL),
(5433, 'receivables management', '/rɪˈsiːvəblz ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["應收帳款管理"],"en":["the process of monitoring and collecting amounts owed to a business"]}', NULL, 'improve receivables management / receivables management system', '[{"en":"Effective receivables management reduces the risk of bad debts.","zh-TW":"有效的應收帳款管理降低了壞帳風險。"},{"en":"The finance team implemented a receivables management policy.","zh-TW":"財務團隊實施了應收帳款管理政策。"}]', NULL, NULL, 5, 5433, NULL),
(5434, 'receivables turnover', '/rɪˈsiːvəbəlz ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["應收帳款週轉率"],"en":["a ratio measuring how quickly a company collects payments owed to it"]}', NULL, 'improve receivables turnover / calculate receivables turnover', '[{"en":"A high receivables turnover ratio indicates efficient collections.","zh-TW":"高應收帳款週轉率表明收款效率高。"},{"en":"The receivables turnover improved after stricter credit terms were enforced.","zh-TW":"在實施更嚴格的信用條款後，應收帳款週轉率有所改善。"}]', NULL, NULL, 5, 5434, NULL),
(5435, 'receive', '/rɪˈsiːv/', 'verb', '{"zh-TW":["收到；接受"],"en":["to get something that is sent or given"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"ceive","meaning":"take (拿取)"}}', 'receive a letter / receive feedback / receive approval', '[{"en":"We received your application yesterday.","zh-TW":"我們昨天收到了你的申請。"},{"en":"The project received full approval.","zh-TW":"項目獲得了全面批准。"}]', '{"noun":"receipt, receiver, reception","adjective":"receivable"}', NULL, 3, 5435, 191),
(5436, 'receivership', '/rɪˈsiːvərʃɪp/', 'noun', '{"zh-TW":["接管；破產接管"],"en":["a legal process in which a receiver takes control of a company to manage its assets"]}', NULL, 'enter receivership / company in receivership', '[{"en":"The failing company was placed into receivership by the courts.","zh-TW":"法院將破產公司置於接管之下。"},{"en":"A receivership aims to repay creditors by managing and selling assets.","zh-TW":"接管旨在通過管理和出售資產來償還債權人。"}]', NULL, NULL, 4, 5436, NULL),
(5437, 'receiving', '/rɪˈsiːvɪŋ/', 'noun', '{"zh-TW":["收貨；驗收"],"en":["the process of accepting and inspecting incoming goods at a warehouse"]}', NULL, 'receiving department / receiving dock / receiving process', '[{"en":"All incoming goods go through the receiving department first.","zh-TW":"所有進貨先經過收貨部門處理。"},{"en":"The receiving team inspects shipments against purchase orders.","zh-TW":"收貨團隊根據採購訂單核查貨物。"}]', '{"verb":"receive","noun":"receiver"}', NULL, 3, 5437, NULL),
(5438, 'recent', '/ˈriːsənt/', 'adjective', '{"zh-TW":["最近的；近來的"],"en":["happening a short time ago"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cent","meaning":"new (新)"}}', 'in recent years / recent developments / most recent', '[{"en":"In recent years, the company has expanded rapidly.","zh-TW":"近年來公司快速擴張。"},{"en":"What are the most recent developments?","zh-TW":"最新的進展是什麼？"}]', '{"adverb":"recently"}', NULL, 2, 5438, NULL),
(5439, 'reception', '/rɪˈsɛpʃən/', 'noun', '{"zh-TW":["接待處；大廳"],"en":["the area of a hotel where guests are welcomed"]}', NULL, 'hotel reception / check in at reception', '[{"en":"Please ask at reception for any assistance.","zh-TW":"如需任何協助，請向接待處詢問。"},{"en":"Reception will hold your luggage until check-in time.","zh-TW":"接待處將為您保管行李直到入住時間。"}]', '{"verb":"receive","adjective":"receptive"}', NULL, 3, 5439, NULL),
(5440, 'recession', '/rɪˈseʃən/', 'noun', '{"zh-TW":["經濟衰退"],"en":["a significant decline in economic activity lasting more than two quarters"]}', NULL, 'economic recession / survive a recession / enter a recession / recession-proof', '[{"en":"The company survived the recession by cutting costs aggressively.","zh-TW":"公司通過積極削減成本度過了經濟衰退。"},{"en":"A recession typically leads to reduced consumer spending.","zh-TW":"經濟衰退通常導致消費者支出減少。"}]', '{"adjective":"recessionary"}', NULL, 3, 5440, NULL),
(5441, 'recidivism', '/rɪˈsɪdɪvɪzəm/', 'noun', '{"zh-TW":["累犯；再犯"],"en":["the tendency to relapse into criminal behavior after punishment"]}', NULL, 'reduce recidivism / high recidivism rate / recidivism prevention', '[{"en":"Rehabilitation programs help reduce recidivism by addressing the root causes of crime.","zh-TW":"康復計畫有助於通過解決犯罪根本原因來減少累犯。"},{"en":"The prison system''s high recidivism rate raised questions about its effectiveness.","zh-TW":"監獄系統的高累犯率引發了對其有效性的質疑。"}]', '{"noun2":"recidivist","adjective":"recidivist"}', NULL, 4, 5441, NULL),
(5442, 'recipe', '/''resɪpi/', 'noun', '{"zh-TW":["食譜；烹飪方法"],"en":["a set of instructions for preparing a dish, including a list of ingredients"]}', NULL, 'follow a recipe / recipe book / traditional recipe', '[{"en":"She followed the recipe carefully to make her grandmother''s soup.","zh-TW":"她仔細按照食譜製作奶奶的湯。"},{"en":"The chef shared his secret recipe for the restaurant''s most popular dish.","zh-TW":"廚師分享了餐廳最受歡迎菜肴的秘密食譜。"}]', NULL, NULL, 2, 5442, NULL),
(5443, 'recipient', '/rɪˈsɪpiənt/', 'noun', '{"zh-TW":["接收者；收件人"],"en":["a person who receives something"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"cipient","meaning":"take (拿取)"}}', 'award recipient / email recipient / intended recipient', '[{"en":"The recipient of the award was announced.","zh-TW":"獎項得主已公佈。"},{"en":"Please confirm the recipient''s email address.","zh-TW":"請確認收件人的電郵地址。"}]', NULL, NULL, 3, 5443, NULL),
(5444, 'recognition', '/ˌrɛkəɡˈnɪʃən/', 'noun', '{"zh-TW":["認可；表彰","認出","認可；識別"],"en":["acknowledgment; appreciation","identifying someone","acknowledgment; the act of identifying"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cogn","meaning":"know (知道)"},"suffix":{"text":"-ition","meaning":"行為"}}', 'in recognition of / gain recognition / brand recognition', '[{"en":"She received recognition for her contributions.","zh-TW":"她因貢獻而獲得表彰。"},{"en":"Brand recognition has improved significantly.","zh-TW":"品牌認知度顯著提升。"},{"en":"She won recognition for her work.","zh-TW":"她的工作獲得了認可。"},{"en":"Brand recognition is essential for growth.","zh-TW":"品牌認知對成長至關重要。"}]', '{"verb":"recognize","adjective":"recognizable"}', NULL, 4, 5444, 432),
(5445, 'recognize', '/ˈrɛkəɡnaɪz/', 'verb', '{"zh-TW":["認出；承認","認可"],"en":["to identify","to acknowledge"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cogn","meaning":"know (知道)"},"suffix":{"text":"-ize","meaning":"使..."}}', 'recognize the importance / widely recognized / recognize sb.', '[{"en":"We recognize the need for improvement.","zh-TW":"我們認識到需要改進。"},{"en":"She is widely recognized as an expert.","zh-TW":"她被廣泛認為是專家。"}]', '{"noun":"recognition","adjective":"recognizable"}', NULL, 3, 5445, 192),
(5446, 'recommend', '/ˌrɛkəˈmɛnd/', 'verb', '{"zh-TW":["推薦；建議"],"en":["to suggest as good; to advise"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"commend","meaning":"praise (讚美)"}}', 'highly recommend / recommend that / recommend sb. for', '[{"en":"I highly recommend this software.","zh-TW":"我強力推薦這個軟體。"},{"en":"The committee recommends that we proceed.","zh-TW":"委員會建議我們繼續。"}]', '{"noun":"recommendation"}', NULL, 3, 5446, 50),
(5447, 'recommendation', 'ˌrɛkəmɛnˈdeɪʃən', 'noun', '{"zh-TW":["建議；推薦","意見"],"en":["advice given","a positive suggestion"]}', NULL, 'make a recommendation/follow recommendations', '[{"en":"The committee made several recommendations.","zh-TW":"委員會提出了幾項建議。"}]', '{"verb":"recommend","adjective":"recommended"}', NULL, 5, 5447, 612),
(5448, 'reconcile', '/ˈrɛkənsaɪl/', 'verb', '{"zh-TW":["調和；使一致"],"en":["to make compatible; to settle differences"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"concile","meaning":"bring together (聚集)"}}', 'reconcile differences / reconcile accounts / hard to reconcile', '[{"en":"We need to reconcile the accounts by month-end.","zh-TW":"我們需要在月底前核對帳目。"},{"en":"It''s hard to reconcile the conflicting reports.","zh-TW":"很難調和相互矛盾的報告。"}]', '{"noun":"reconciliation"}', NULL, 3, 5448, 711),
(5449, 'reconcile accounts', '/ˈrekənsaɪl əˈkaʊnts/', 'verb', '{"zh-TW":["對帳；使帳戶一致"],"en":["to compare and match financial records to ensure they are correct"]}', NULL, 'reconcile bank accounts / reconcile accounts monthly', '[{"en":"The accountant reconciles accounts at the end of every month.","zh-TW":"會計師在每月末對帳。"},{"en":"Reconciling accounts helps detect errors and fraud.","zh-TW":"對帳有助於發現錯誤和欺詐。"}]', '{"noun":"reconciliation"}', NULL, 5, 5449, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5450, 'reconciliation', '/ˌrekənsɪliˈeɪʃən/', 'noun', '{"zh-TW":["帳目核對；對帳"],"en":["the process of comparing two sets of records to ensure they agree"]}', NULL, 'bank reconciliation / account reconciliation / monthly reconciliation', '[{"en":"Monthly bank reconciliation catches discrepancies early.","zh-TW":"月度銀行對帳能早期發現差異。"},{"en":"The accountant performed a reconciliation of all expense accounts.","zh-TW":"會計師對所有費用帳戶進行了對帳。"}]', '{"verb":"reconcile","adjective":"reconciled"}', NULL, 5, 5450, 809),
(5451, 'record', '/rɪˈkɔːrd/', 'verb', '{"zh-TW":["記錄","錄製"],"en":["to write down; to make a note","to capture audio/video"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cord","meaning":"heart (心)"}}', 'keep a record / on record / record-breaking / set a record', '[{"en":"All transactions are recorded in the system.","zh-TW":"所有交易都記錄在系統中。"},{"en":"Sales reached a record high this quarter.","zh-TW":"本季度銷售額創歷史新高。"}]', '{"noun":"record, recording","adjective":"recorded"}', NULL, 2, 5451, 193),
(5452, 'recourse', '/rɪˈkɔːrs/', 'noun', '{"zh-TW":["追索權；補救手段"],"en":["the right to demand compensation from a party if another fails to pay"]}', NULL, 'have recourse against / limited recourse', '[{"en":"The contract includes recourse provisions if the supplier defaults.","zh-TW":"合約包含了供應商違約時的追索權條款。"},{"en":"A non-recourse loan means the lender can only claim the collateral.","zh-TW":"無追索權貸款意味著貸款方只能索取抵押品。"}]', '{"adjective":"non-recourse"}', NULL, 3, 5452, NULL),
(5453, 'recover', '/rɪˈkʌvər/', 'verb', '{"zh-TW":["恢復；找回","恢復；復原","收回"],"en":["to return to a normal state","to get back something lost","to return to normal"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"cover","meaning":"cover/get (取得)"},"logic":"取回原來的狀態，即「恢復」。"}', 'recover from / fully recover / recover data; recover from / recover losses / full recovery', '[{"en":"She is recovering from surgery.","zh-TW":"她正在從手術中恢復。"},{"en":"The economy is slowly recovering.","zh-TW":"經濟正在緩慢復甦。"},{"en":"We managed to recover the lost data.","zh-TW":"我們設法恢復了丟失的數據。"}]', '{"noun":"recovery","adjective":"recoverable"}', NULL, 3, 5453, 712),
(5454, 'recovery day', '/''rɪˌkʌvəri deɪ/', 'noun', '{"zh-TW":["恢復日；休息日"],"en":["a day designated for rest and recuperation rather than intense physical exercise"]}', NULL, 'schedule a recovery day / take a recovery day / active recovery day', '[{"en":"Physical trainers recommend at least one recovery day per week for muscle repair.","zh-TW":"體能教練建議每週至少安排一天恢復日以修復肌肉。"},{"en":"She used her recovery day for gentle yoga and stretching.","zh-TW":"她利用恢復日進行輕柔瑜伽和伸展運動。"}]', NULL, NULL, 4, 5454, NULL),
(5455, 'recreation', '/ˌrɛkriˈeɪʃən/', 'noun', '{"zh-TW":["休閒；娛樂"],"en":["activities done for enjoyment"]}', NULL, 'recreation center / outdoor recreation', '[{"en":"The park is used for recreation.","zh-TW":"這個公園用於休閒活動。"},{"en":"Swimming is a popular form of recreation.","zh-TW":"游泳是一種受歡迎的休閒活動。"}]', '{"adjective":"recreational"}', NULL, 4, 5455, NULL),
(5456, 'recruit', '/rɪˈkruːt/', 'verb', '{"zh-TW":["招募；招聘"],"en":["to find new people to join"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"cruit","meaning":"grow (生長)"}}', 'recruit new employees / recruit talent / recruitment drive', '[{"en":"We are recruiting for several positions.","zh-TW":"我們正在招聘幾個職位。"},{"en":"The company recruited 50 new graduates.","zh-TW":"公司招募了50名應屆畢業生。"}]', '{"noun":"recruitment, recruiter, recruit"}', NULL, 3, 5456, NULL),
(5457, 'recruitment', '/rɪˈkruːtmənt/', 'noun', '{"zh-TW":["招募；招聘"],"en":["the process of finding and hiring candidates for jobs"]}', NULL, 'recruitment process / recruitment agency / talent recruitment', '[{"en":"The recruitment campaign attracted hundreds of applicants.","zh-TW":"招募活動吸引了數百名申請者。"},{"en":"Online recruitment platforms have transformed hiring.","zh-TW":"線上招募平台改變了招聘方式。"}]', '{"verb":"recruit","noun":"recruiter"}', NULL, 4, 5457, 433),
(5458, 'recurrence', '/rɪˈkɜːrəns/', 'noun', '{"zh-TW":["復發；再發"],"en":["the return of a disease after a period of improvement"]}', NULL, 'prevent recurrence / risk of recurrence / cancer recurrence', '[{"en":"The patient underwent maintenance therapy to reduce the risk of recurrence.","zh-TW":"患者接受了維持療法以降低復發風險。"},{"en":"Regular follow-up monitoring helps detect recurrence early.","zh-TW":"定期隨訪監測有助於早期發現復發。"}]', '{"verb":"recur","adjective":"recurrent"}', NULL, 4, 5458, NULL),
(5459, 'recurring costs', '/rɪˈkɜːrɪŋ kɒsts/', 'noun', '{"zh-TW":["經常性成本"],"en":["ongoing expenses that are incurred regularly as part of business operations"]}', NULL, 'manage recurring costs / reduce recurring costs', '[{"en":"Software subscriptions and rent are major recurring costs.","zh-TW":"軟件訂閱和租金是主要的經常性成本。"},{"en":"Reducing recurring costs directly improves profitability over time.","zh-TW":"減少經常性成本直接改善了長期盈利能力。"}]', '{"opposite":"one-time cost"}', NULL, 5, 5459, NULL),
(5460, 'recurring expense', '/rɪˈkɜːrɪŋ ɪkˈspens/', 'noun', '{"zh-TW":["經常性費用"],"en":["a cost that occurs regularly at set intervals"]}', NULL, 'manage recurring expenses / track recurring expenses', '[{"en":"Rent and utilities are the main recurring expenses.","zh-TW":"租金和水電費是主要的經常性費用。"},{"en":"Recurring expenses should be included in the annual budget plan.","zh-TW":"經常性費用應納入年度預算計劃。"}]', NULL, NULL, 5, 5460, NULL),
(5461, 'recurring revenue', '/rɪˈkɜːrɪŋ ˈrevɪnjuː/', 'noun', '{"zh-TW":["循環收入；經常性收入"],"en":["income generated repeatedly from ongoing subscriptions or contracts"]}', NULL, 'grow recurring revenue / subscription-based recurring revenue', '[{"en":"SaaS companies depend heavily on recurring revenue from subscriptions.","zh-TW":"SaaS公司嚴重依賴訂閱的循環收入。"},{"en":"Recurring revenue provides predictable cash flow for the business.","zh-TW":"循環收入為業務提供了可預測的現金流。"}]', NULL, NULL, 5, 5461, NULL),
(5462, 'recursive', '/rɪˈkɜːrsɪv/', 'adjective', '{"zh-TW":["遞迴的；循環的"],"en":["relating to a procedure that repeats itself; self-referential"]}', NULL, 'recursive algorithm / recursive process / recursive function', '[{"en":"A recursive function calls itself to solve a smaller version of the problem.","zh-TW":"遞迴函數通過調用自身來解決問題的較小版本。"},{"en":"Learning is a recursive process of building on prior knowledge.","zh-TW":"學習是建立在先前知識基礎上的遞迴過程。"}]', '{"noun":"recursion","adverb":"recursively"}', NULL, 3, 5462, NULL),
(5463, 'recycling', '/rɪˈsaɪklɪŋ/', 'noun', '{"zh-TW":["回收再利用"],"en":["converting waste into reusable material"]}', NULL, 'recycling program / recycling rate', '[{"en":"The city launched a new recycling program last year.","zh-TW":"市政府去年推出了新的回收計劃。"},{"en":"Recycling aluminum cans saves significant energy.","zh-TW":"回收鋁罐可節省大量能源。"}]', '{"verb":"recycle","adjective":"recyclable"}', NULL, 3, 5463, NULL),
(5464, 'redemption', '/rɪˈdempʃən/', 'noun', '{"zh-TW":["贖回；償還"],"en":["the action of repaying or regaining possession of something in exchange for payment"]}', NULL, 'bond redemption / redemption date / early redemption', '[{"en":"The bond is scheduled for redemption in five years.","zh-TW":"債券預定五年後贖回。"},{"en":"Early redemption may be subject to a penalty fee.","zh-TW":"提前贖回可能需支付違約金。"}]', '{"verb":"redeem","adjective":"redeemable"}', NULL, 4, 5464, NULL),
(5465, 'redress', '/rɪˈdres/', 'noun', '{"zh-TW":["補救；救濟；糾正"],"en":["the act of rectifying an injustice; compensation for a wrong"]}', NULL, 'seek redress / redress grievances / right of redress', '[{"en":"Consumers have the right to seek redress when companies fail to deliver services as promised.","zh-TW":"當公司未能按承諾提供服務時，消費者有權尋求補救。"},{"en":"The court awarded financial redress to victims of the illegal data breach.","zh-TW":"法院向非法數據洩露的受害者判給財務補救。"}]', '{"verb":"redress"}', NULL, 3, 5465, NULL),
(5466, 'reduce', '/rɪˈdjuːs/', 'verb', '{"zh-TW":["減少；降低"],"en":["to make smaller in size or amount"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"duce","meaning":"lead (引導)"}}', 'reduce costs / reduce emissions / reduce the risk', '[{"en":"We need to reduce operating costs.","zh-TW":"我們需要降低營運成本。"},{"en":"The new policy aims to reduce emissions.","zh-TW":"新政策旨在減少排放。"}]', '{"noun":"reduction"}', NULL, 2, 5466, 194),
(5467, 'reduction', 'rɪˈdʌkʃən', 'noun', '{"zh-TW":["減少；降低","縮減"],"en":["a decrease in amount","the act of making smaller"]}', NULL, 'cost reduction/price reduction', '[{"en":"Cost reduction is a key business objective.","zh-TW":"降低成本是主要的業務目標。"}]', '{"verb":"reduce","adjective":"reduced","adverb":"reducibly"}', NULL, 3, 5467, NULL),
(5468, 'reductive', '/rɪˈdʌktɪv/', 'adjective', '{"zh-TW":["簡化的；過度簡化的"],"en":["tending to present something in an overly simplified way"]}', NULL, 'reductive argument / reductive approach / reductive thinking', '[{"en":"His reductive analysis ignored the complexity of the issue.","zh-TW":"他的過度簡化分析忽略了問題的複雜性。"},{"en":"Reducing poverty to a single cause is a reductive approach.","zh-TW":"將貧困歸結為單一原因是一種過度簡化的方法。"}]', '{"noun":"reduction","adverb":"reductively"}', NULL, 3, 5468, NULL),
(5469, 'redundancy', '/rɪˈdʌndənsi/', 'noun', '{"zh-TW":["裁員；多餘"],"en":["the elimination of a job because it is no longer needed"]}', NULL, 'compulsory redundancy / voluntary redundancy / face redundancy', '[{"en":"Automation led to widespread redundancy in the factory.","zh-TW":"自動化導致工廠出現大規模裁員。"},{"en":"She took voluntary redundancy and started her own business.","zh-TW":"她選擇自願離職並創辦了自己的事業。"}]', '{"adjective":"redundant"}', NULL, 4, 5469, NULL),
(5470, 'redundancy package', '/rɪˈdʌndənsi ˈpækɪdʒ/', 'noun', '{"zh-TW":["裁員補償方案"],"en":["a financial settlement offered to employees being made redundant"]}', NULL, 'offer a redundancy package / accept a redundancy package', '[{"en":"The company offered a generous redundancy package to affected employees.","zh-TW":"公司向受影響的員工提供了慷慨的裁員補償方案。"},{"en":"The redundancy package included three months pay and career support.","zh-TW":"裁員補償方案包括三個月薪資和職業支持。"}]', NULL, NULL, 5, 5470, NULL),
(5471, 'redundancy payment', '/rɪˈdʌndənsi ˈpeɪmənt/', 'noun', '{"zh-TW":["裁員賠償；遣散費"],"en":["compensation paid to employees when their role is eliminated due to restructuring"]}', NULL, 'receive redundancy payment / redundancy payment calculation', '[{"en":"Employees affected by the restructuring received a redundancy payment.","zh-TW":"受重組影響的員工收到了遣散費。"},{"en":"Redundancy payments are calculated based on years of service.","zh-TW":"遣散費根據服務年限計算。"}]', NULL, NULL, 5, 5471, NULL),
(5472, 'redundant', '/rɪˈdʌndənt/', 'adjective', '{"zh-TW":["多餘的；被裁員的"],"en":["no longer needed; also describes a worker whose job has been eliminated"]}', NULL, 'made redundant / redundant position / redundant system', '[{"en":"He was made redundant when his department was downsized.","zh-TW":"他的部門縮編後，他遭到了裁員。"},{"en":"The redundant data backup system provided extra security.","zh-TW":"多餘的資料備份系統提供了額外的安全保障。"}]', '{"verb":"make redundant","noun":"redundancy"}', NULL, 3, 5472, NULL),
(5473, 'refactoring', '/riːˈfæktərɪŋ/', 'noun', '{"zh-TW":["重構"],"en":["restructuring existing code without changing its external behavior"]}', NULL, 'code refactoring / perform refactoring / refactoring session', '[{"en":"Regular refactoring keeps the codebase maintainable and readable.","zh-TW":"定期重構使程式碼庫保持可維護性和可讀性。"},{"en":"The team allocated one sprint for refactoring the payment module.","zh-TW":"團隊分配了一個衝刺用於重構支付模組。"}]', '{"verb":"refactor","adjective":"refactored"}', NULL, 4, 5473, NULL),
(5474, 'refer', '/rɪˈfɜːr/', 'verb', '{"zh-TW":["提到；參考","轉介"],"en":["to mention","to direct someone"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"fer","meaning":"carry (攜帶)"}}', 'refer to / refer sb. to / with reference to', '[{"en":"Please refer to the user manual.","zh-TW":"請參考用戶手冊。"},{"en":"I was referred to the HR department.","zh-TW":"我被轉介到人資部門。"}]', '{"noun":"reference, referral, referee"}', NULL, 2, 5474, 51),
(5475, 'referee', '/ˌrɛfəˈriː/', 'noun', '{"zh-TW":["裁判"],"en":["a person who makes sure rules are followed in a game"]}', NULL, 'referee a match / referee''s decision', '[{"en":"The referee blew the whistle.","zh-TW":"裁判吹響了哨子。"},{"en":"The referee''s decision is final.","zh-TW":"裁判的決定是最終的。"}]', NULL, NULL, 3, 5475, NULL),
(5476, 'reference', '/ˈrɛfərəns/', 'noun', '{"zh-TW":["參考；參照","推薦信"],"en":["a source of information","a letter of recommendation"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"fer","meaning":"carry"},"suffix":{"text":"-ence","meaning":"名詞後綴"}}', 'for reference / reference number / provide references', '[{"en":"Please keep this for future reference.","zh-TW":"請保留此文件以供未來參考。"},{"en":"Can you provide two professional references?","zh-TW":"你能提供兩份專業推薦嗎？"}]', '{"verb":"refer"}', NULL, 3, 5476, NULL),
(5477, 'reference check', '/ˈrefrəns tʃek/', 'noun', '{"zh-TW":["背景調查；推薦人查核"],"en":["the process of verifying a job candidate''s work history through previous employers"]}', NULL, 'conduct a reference check / reference check process', '[{"en":"Reference checks confirmed the candidate had an excellent performance record.","zh-TW":"背景調查確認了候選人有出色的績效記錄。"},{"en":"All final candidates undergo a reference check before an offer is made.","zh-TW":"所有最終候選人在提出邀約前都要接受推薦人查核。"}]', NULL, NULL, 5, 5477, NULL),
(5478, 'reference number', '/ˈrɛfrəns ˈnʌmbər/', 'noun', '{"zh-TW":["參考號碼；查詢編號"],"en":["a number assigned to identify a specific transaction or record"]}', NULL, 'provide a reference number / quote your reference number', '[{"en":"Please quote your reference number when contacting customer service.","zh-TW":"聯繫客服時請提供您的參考號碼。"},{"en":"The reference number is located on the top of your invoice.","zh-TW":"參考號碼位於您的發票頂部。"}]', NULL, NULL, 5, 5478, NULL),
(5479, 'reference rate', '/ˈrefrəns reɪt/', 'noun', '{"zh-TW":["參考利率；基準利率"],"en":["a benchmark interest rate used to price financial instruments"]}', NULL, 'set a reference rate / reference rate change', '[{"en":"Variable loans are priced based on a reference rate plus a spread.","zh-TW":"浮動貸款根據參考利率加差價定價。"},{"en":"Changes in the reference rate affect all floating-rate debt instruments.","zh-TW":"參考利率的變化影響了所有浮動利率債務工具。"}]', '{"synonym":"benchmark rate"}', NULL, 5, 5479, NULL),
(5480, 'referral', '/rɪˈfɜːrəl/', 'noun', '{"zh-TW":["轉介；轉診"],"en":["a direction of a patient to a specialist"]}', NULL, 'get a referral / specialist referral', '[{"en":"You need a referral from your primary doctor to see a specialist.","zh-TW":"您需要主治醫師的轉介才能看專科醫生。"},{"en":"The referral was approved by the insurance company.","zh-TW":"轉介已獲保險公司批准。"}]', '{"verb":"refer"}', NULL, 3, 5480, NULL),
(5481, 'refinancing', '/ˌriːˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["再融資"],"en":["replacing an existing loan with a new one, usually at better terms"]}', NULL, 'pursue refinancing / complete refinancing', '[{"en":"The company completed refinancing at a lower interest rate.","zh-TW":"公司以較低的利率完成了再融資。"},{"en":"Refinancing reduced annual debt servicing costs by $2 million.","zh-TW":"再融資將年度償債成本減少了200萬元。"}]', '{"verb":"refinance"}', NULL, 4, 5481, NULL),
(5482, 'refine', '/rɪˈfaɪn/', 'verb', '{"zh-TW":["完善；改善；提煉"],"en":["to make minor improvements to something"]}', NULL, 'refine a process / refine the strategy', '[{"en":"The team refined the proposal based on feedback.","zh-TW":"團隊根據反饋完善了提案。"},{"en":"Refining the manufacturing process reduced defect rates.","zh-TW":"改善製造流程降低了缺陷率。"}]', '{"noun":"refinement","adjective":"refined"}', NULL, 2, 5482, NULL),
(5483, 'reflect', '/rɪˈflɛkt/', 'verb', '{"zh-TW":["反映；反射","反思"],"en":["to show or express","to think carefully"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"flect","meaning":"bend (彎曲)"}}', 'reflect on / reflect changes / reflect the views', '[{"en":"The report reflects the current market conditions.","zh-TW":"報告反映了當前市場狀況。"},{"en":"Take time to reflect on your progress.","zh-TW":"花時間反思你的進展。"}]', '{"noun":"reflection","adjective":"reflective"}', NULL, 3, 5483, NULL),
(5484, 'reflexive', '/rɪˈfleksɪv/', 'adjective', '{"zh-TW":["反身的；自省的"],"en":["directed back on itself; relating to critical self-awareness"]}', NULL, 'reflexive thinking / reflexive practice / reflexive research', '[{"en":"Reflexive research requires the researcher to examine their own biases.","zh-TW":"自省性研究要求研究員審視自己的偏見。"},{"en":"Reflexive thinking helps professionals learn from their own experiences.","zh-TW":"反身思考幫助專業人士從自身經驗中學習。"}]', '{"noun":"reflexivity","adverb":"reflexively"}', NULL, 3, 5484, NULL),
(5485, 'reflexivity', '/ˌrɪflekˈsɪvɪti/', 'noun', '{"zh-TW":["反身性；自我反思能力"],"en":["the capacity of social systems to reflect on themselves"]}', NULL, 'researcher reflexivity / reflexivity in methods / critical reflexivity', '[{"en":"Reflexivity in research requires the scholar to examine their own position.","zh-TW":"研究中的反身性要求學者審視自己的立場。"},{"en":"Reflexivity distinguishes qualitative research from positivist approaches.","zh-TW":"反身性將質性研究與實證主義方法區別開來。"}]', '{"adjective":"reflexive","adverb":"reflexively"}', NULL, 4, 5485, NULL),
(5486, 'reforestation', '/ˌriːˌfɒrɪˈsteɪʃən/', 'noun', '{"zh-TW":["植樹造林；重新造林"],"en":["planting trees in an area where forest has been removed"]}', NULL, 'reforestation project / reforestation effort', '[{"en":"The charity funds reforestation projects in deforested areas.","zh-TW":"該慈善機構資助毀林地區的植樹造林項目。"},{"en":"Reforestation helps restore biodiversity and absorb carbon.","zh-TW":"植樹造林有助於恢復生物多樣性和吸收碳。"}]', '{"verb":"reforest","adjective":"reforested"}', NULL, 5, 5486, NULL),
(5487, 'reform', '/rɪˈfɔːrm/', 'noun', '{"zh-TW":["改革"],"en":["a change made to improve a system","a change made to improve something"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"form","meaning":"form/shape (形成)"},"logic":"重新形成，即「改革」。"}', 'education reform / tax reform / reform the system; economic reform / reform the system / tax reform', '[{"en":"The government introduced economic reforms.","zh-TW":"政府推行了經濟改革。"},{"en":"Healthcare reform is urgently needed.","zh-TW":"醫療改革迫在眉睫。"},{"en":"The government announced major tax reforms.","zh-TW":"政府宣布了重大稅制改革。"},{"en":"Healthcare reform is a priority.","zh-TW":"醫療改革是優先事項。"}]', '{"verb":"reform","noun2":"reformer","noun":"reformer"}', NULL, 2, 5487, NULL),
(5488, 'reformulate', '/riːˈfɔːrmjʊleɪt/', 'verb', '{"zh-TW":["重新制定；重新配製"],"en":["to revise or change the formulation of a plan, policy, or product"]}', NULL, 'reformulate the strategy / reformulate the product', '[{"en":"The company reformulated the product to remove allergens.","zh-TW":"公司重新配製了產品以去除過敏原。"},{"en":"Management reformulated its growth strategy after market conditions changed.","zh-TW":"市場條件變化後，管理層重新制定了增長策略。"}]', '{"noun":"reformulation","adjective":"reformulated"}', NULL, 4, 5488, NULL),
(5489, 'refund', '/ˈriːfʌnd/', 'noun', '{"zh-TW":["退款"],"en":["money returned to a buyer"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"fund","meaning":"pour/money (注入/資金)"},"logic":"把錢倒回去，即「退款」。"}', 'full refund / request a refund; full refund / request a refund / refund policy', '[{"en":"I would like to request a refund.","zh-TW":"我想要求退款。"},{"en":"They issued a full refund within 24 hours.","zh-TW":"他們在24小時內全額退款。"},{"en":"We will issue a full refund.","zh-TW":"我們將全額退款。"},{"en":"Please check our refund policy.","zh-TW":"請查看我們的退款政策。"}]', '{"verb":"refund","adjective":"refundable"}', NULL, 2, 5489, 195),
(5490, 'refund policy', '/ˈriːfʌnd ˈpɒlɪsi/', 'noun', '{"zh-TW":["退款政策"],"en":["the rules governing when and how customers can get money back"]}', NULL, 'review the refund policy / communicate the refund policy', '[{"en":"The company updated its refund policy to a 30-day returns window.","zh-TW":"公司將退款政策更新為30天退貨窗口。"},{"en":"Clear refund policies build customer trust and reduce disputes.","zh-TW":"清晰的退款政策建立了客戶信任並減少了糾紛。"}]', NULL, NULL, 5, 5490, NULL),
(5491, 'refundable deposit', '/rɪˈfʌndəbl dɪˈpɒzɪt/', 'noun', '{"zh-TW":["可退還押金"],"en":["a sum of money paid as security that will be returned when conditions are met"]}', NULL, 'pay a refundable deposit / claim back the refundable deposit', '[{"en":"A refundable deposit of $500 is required to hold the rental equipment.","zh-TW":"需要500元的可退還押金來預留租用設備。"},{"en":"The refundable deposit was returned in full after the lease term ended.","zh-TW":"租賃期限結束後，可退還押金全額退還了。"}]', '{"opposite":"non-refundable deposit"}', NULL, 5, 5491, NULL),
(5492, 'refute', '/rɪˈfjuːt/', 'verb', '{"zh-TW":["反駁；駁倒"],"en":["to prove a statement or person to be wrong"]}', NULL, 'refute an argument / refute a claim / refute the evidence', '[{"en":"The study refutes the commonly held assumption about consumer behavior.","zh-TW":"該研究反駁了關於消費者行為的普遍假設。"},{"en":"He could not refute the data presented by the opposing team.","zh-TW":"他無法反駁對方團隊提出的數據。"}]', '{"noun":"refutation","adjective":"irrefutable"}', NULL, 2, 5492, NULL),
(5493, 'regard', '/rɪˈɡɑːrd/', 'verb', '{"zh-TW":["認為；看待"],"en":["to consider; to think of"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"gard","meaning":"watch (看)"}}', 'regard as / with regard to / in this regard / regardless', '[{"en":"She is widely regarded as an expert.","zh-TW":"她被廣泛認為是專家。"},{"en":"With regard to your inquiry, please see below.","zh-TW":"關於您的詢問，請見下方。"}]', '{"noun":"regard, regards","preposition":"regarding"}', NULL, 2, 5493, NULL),
(5494, 'regarding', '/rɪˈɡɑːrdɪŋ/', 'preposition', '{"zh-TW":["關於；有關"],"en":["with reference to; concerning"]}', NULL, 'regarding the matter / regarding your inquiry', '[{"en":"I am writing regarding the invoice dated March 10th.","zh-TW":"我寫信是關於3月10日的發票。"},{"en":"Regarding your inquiry, please see the attached response.","zh-TW":"關於您的查詢，請參閱附件的回覆。"}]', '{"verb":"regard","noun":"regard"}', NULL, 3, 5494, NULL),
(5495, 'regardless', '/rɪˈɡɑːrdləs/', 'adverb', '{"zh-TW":["不管；無論如何"],"en":["without being affected by"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"gard","meaning":"watch"},"suffix":{"text":"-less","meaning":"without (無)"}}', 'regardless of / regardless of the cost', '[{"en":"We will proceed regardless of the obstacles.","zh-TW":"無論有什麼障礙我們都將繼續。"},{"en":"The rule applies regardless of seniority.","zh-TW":"規則不論資歷均適用。"}]', NULL, NULL, 4, 5495, NULL),
(5496, 'region', '/ˈriːdʒən/', 'noun', '{"zh-TW":["地區；區域"],"en":["a particular area or part"]}', NULL, 'in the region / regional office / Asia-Pacific region', '[{"en":"The company has offices in every region.","zh-TW":"公司在每個地區都有辦公室。"},{"en":"Economic growth varies by region.","zh-TW":"經濟增長因地區而異。"}]', '{"adjective":"regional","adverb":"regionally"}', NULL, 2, 5496, NULL),
(5497, 'regional manager', '/ˈriːdʒənl ˈmænɪdʒər/', 'noun', '{"zh-TW":["區域經理"],"en":["a manager responsible for business operations in a specific geographic region"]}', NULL, 'appoint a regional manager / regional manager responsibilities', '[{"en":"The regional manager oversees six branch offices.","zh-TW":"區域經理監管六個分支辦公室。"},{"en":"The regional manager reports directly to the vice president of operations.","zh-TW":"區域經理直接向運營副總裁匯報。"}]', NULL, NULL, 5, 5497, NULL),
(5498, 'regional office', '/ˈriːdʒənl ˈɒfɪs/', 'noun', '{"zh-TW":["地區辦公室；區域辦事處"],"en":["an office representing a company in a specific geographic area"]}', NULL, 'open a regional office / regional office operations', '[{"en":"The company opened a regional office in Singapore to cover Southeast Asia.","zh-TW":"公司在新加坡開設了地區辦公室以覆蓋東南亞。"},{"en":"Regional offices report monthly results to headquarters.","zh-TW":"地區辦公室每月向總部報告業績。"}]', NULL, NULL, 5, 5498, NULL),
(5499, 'register', '/ˈredʒɪstər/', 'noun', '{"zh-TW":["收銀機；登記","登記；註冊"],"en":["a cash register","to officially record information","to officially record or enroll"]}', '{"root":{"text":"gest","meaning":"carry (攜帶)"},"prefix":{"text":"re-","meaning":"back (回)"},"logic":"帶回紀錄，指登記或收銀機。"}', 'cash register / register for a course; register for / register a complaint / registered office', '[{"en":"The cashier opened the register to make change.","zh-TW":"收銀員打開收銀機找零。"},{"en":"Please register at the front desk.","zh-TW":"請在前台登記。"},{"en":"You must register before attending the event.","zh-TW":"參加活動前必須註冊。"},{"en":"The company is registered in Delaware.","zh-TW":"公司在德拉瓦州註冊。"}]', '{"noun":"registration","adjective":"registered"}', NULL, 3, 5499, 52);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5500, 'registered office', '/ˈredʒɪstərd ˈɒfɪs/', 'noun', '{"zh-TW":["注冊辦公室；法定地址"],"en":["the official address of a company as registered with the government"]}', NULL, 'establish a registered office / registered office address', '[{"en":"The registered office address must be available to the public.","zh-TW":"注冊辦公室地址必須向公眾公開。"},{"en":"Companies must notify the authorities if their registered office changes.","zh-TW":"如果公司的注冊辦公室地址有變更，必須通知有關機構。"}]', NULL, NULL, 5, 5500, NULL),
(5501, 'registered trademark', '/ˈredʒɪstərd ˈtreɪdmɑːrk/', 'noun', '{"zh-TW":["注冊商標"],"en":["a legally protected symbol, word, or phrase identifying a brand''s products"]}', NULL, 'obtain a registered trademark / registered trademark infringement', '[{"en":"Using another company''s registered trademark without permission is illegal.","zh-TW":"未經許可使用另一家公司的注冊商標是非法的。"},{"en":"A registered trademark provides exclusive rights to use the mark in commerce.","zh-TW":"注冊商標提供了在商業中使用該標誌的獨家權利。"}]', '{"symbol":"®","synonym":"trademark"}', NULL, 5, 5501, NULL),
(5502, 'registration', 'ˌrɛdʒɪˈstreɪʃən', 'noun', '{"zh-TW":["登記；註冊","掛號"],"en":["the process of signing up","an official record"]}', NULL, 'online registration/event registration', '[{"en":"Registration closes on Friday.","zh-TW":"登記在週五截止。"}]', '{"verb":"register","adjective":"registered"}', NULL, 4, 5502, 613),
(5503, 'registration desk', '/ˌrɛdʒɪˈstreɪʃən dɛsk/', 'noun', '{"zh-TW":["報名處；登記台"],"en":["a table or counter where attendees register for an event"]}', NULL, 'check in at the registration desk / registration desk hours', '[{"en":"Please check in at the registration desk upon arrival.","zh-TW":"抵達時請在報名處辦理登記。"},{"en":"The registration desk opens one hour before the event begins.","zh-TW":"報名處在活動開始前一小時開放。"}]', NULL, NULL, 5, 5503, NULL),
(5504, 'regression testing', '/rɪˈɡreʃən ˈtestɪŋ/', 'noun', '{"zh-TW":["回歸測試"],"en":["testing to ensure that previously working software still functions after changes"]}', NULL, 'perform regression testing / automated regression testing / regression test suite', '[{"en":"Regression testing prevents new code changes from breaking existing features.","zh-TW":"回歸測試防止新的代碼更改破壞現有功能。"},{"en":"The CI pipeline runs regression testing automatically on each commit.","zh-TW":"CI管道在每次提交時自動運行回歸測試。"}]', '{"verb":"regression test"}', NULL, 5, 5504, NULL),
(5505, 'regulate', '/ˈrɛɡjuleɪt/', 'verb', '{"zh-TW":["規範；調節","監管；調節"],"en":["to control something by rules","to control or supervise by rules","to control by rules"]}', '{"root":{"text":"regul","meaning":"rule (規則)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其按規則運行，即「規範」。"}', 'regulate industry / government regulated; regulate the industry / regulate temperature; regulate the industry / strictly regulated', '[{"en":"The government regulates the banking industry.","zh-TW":"政府規範銀行業。"},{"en":"This law regulates food safety.","zh-TW":"這項法律規範食品安全。"},{"en":"This thermostat regulates room temperature.","zh-TW":"這個恆溫器調節室溫。"},{"en":"The government regulates the financial sector.","zh-TW":"政府監管金融業。"},{"en":"Prices are regulated by market forces.","zh-TW":"價格由市場力量調節。"}]', '{"noun":"regulation","noun2":"regulator","adjective":"regulatory"}', NULL, 3, 5505, NULL),
(5506, 'regulation', '/ˌrɛɡjuˈleɪʃən/', 'noun', '{"zh-TW":["法規；規定"],"en":["an official rule or law"]}', '{"root":{"text":"regul","meaning":"rule (規則)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'comply with regulations / safety regulations / government regulation', '[{"en":"All companies must comply with safety regulations.","zh-TW":"所有公司必須遵守安全法規。"},{"en":"New regulations take effect next month.","zh-TW":"新法規下月生效。"}]', '{"verb":"regulate","adjective":"regulatory","noun":"regulator"}', NULL, 4, 5506, 434),
(5507, 'regulatory approval', '/ˌreɡjʊˈleɪtɔːri əˈpruːvəl/', 'noun', '{"zh-TW":["監管批准"],"en":["official permission from a regulatory body to proceed with an action"]}', NULL, 'obtain regulatory approval / pending regulatory approval', '[{"en":"The drug cannot be sold until regulatory approval is granted.","zh-TW":"在獲得監管批准之前，藥物不能出售。"},{"en":"The merger was completed after receiving regulatory approval.","zh-TW":"在獲得監管批准後完成了合併。"}]', NULL, NULL, 5, 5507, NULL),
(5508, 'regulatory authority', '/ˌreɡjəˈleɪtəri ɔːˈθɒrɪti/', 'noun', '{"zh-TW":["監管機構"],"en":["a government body responsible for overseeing a specific industry or sector"]}', NULL, 'comply with the regulatory authority / regulatory authority approval', '[{"en":"The drug required approval from the regulatory authority before launch.","zh-TW":"藥物在上市之前需要監管機構的批准。"},{"en":"Violations may result in sanctions imposed by the regulatory authority.","zh-TW":"違規行為可能導致監管機構實施制裁。"}]', NULL, NULL, 5, 5508, NULL),
(5509, 'regulatory body', '/ˈreɡjʊlətɔːri ˈbɒdi/', 'noun', '{"zh-TW":["監管機構"],"en":["an official organization responsible for overseeing a particular industry"]}', NULL, 'report to a regulatory body / comply with the regulatory body', '[{"en":"All financial institutions must be registered with the relevant regulatory body.","zh-TW":"所有金融機構必須向相關監管機構登記。"},{"en":"The regulatory body launched an investigation into the trading practices.","zh-TW":"監管機構對交易行為展開了調查。"}]', NULL, NULL, 5, 5509, NULL),
(5510, 'regulatory burden', '/ˈreɡjʊlətəri ˈbɜːrdən/', 'noun', '{"zh-TW":["監管負擔"],"en":["the cost and effort required to comply with government regulations"]}', NULL, 'reduce regulatory burden / regulatory burden on business / heavy regulatory burden', '[{"en":"Small businesses often struggle with the regulatory burden of compliance.","zh-TW":"小型企業通常難以應付合規的監管負擔。"},{"en":"Policymakers must balance consumer protection with the regulatory burden.","zh-TW":"政策制定者必須在消費者保護和監管負擔之間取得平衡。"}]', NULL, NULL, 5, 5510, NULL),
(5511, 'regulatory capture', '/ˈreɡjʊlətəri ˈkæptʃər/', 'noun', '{"zh-TW":["監管俘獲"],"en":["when a regulatory agency advances the interests of those it is supposed to regulate"]}', NULL, 'prevent regulatory capture / problem of regulatory capture / address regulatory capture', '[{"en":"Regulatory capture occurs when industries successfully influence their overseers.","zh-TW":"當行業成功影響其監管機構時，就會發生監管俘獲。"},{"en":"Revolving doors between government and industry can lead to regulatory capture.","zh-TW":"政府和工業界之間的旋轉門可能導致監管俘獲。"}]', NULL, NULL, 5, 5511, NULL),
(5512, 'regulatory change', '/ˌreɡjʊˈleɪtɔːri tʃeɪndʒ/', 'noun', '{"zh-TW":["監管變更"],"en":["a modification to laws or rules governing an industry"]}', NULL, 'prepare for regulatory change / adapt to regulatory changes', '[{"en":"The company updated its processes to comply with the regulatory change.","zh-TW":"公司更新了流程以遵守監管變更。"},{"en":"Regulatory changes in data protection required major system upgrades.","zh-TW":"資料保護方面的監管變更需要重大系統升級。"}]', NULL, NULL, 5, 5512, NULL),
(5513, 'regulatory compliance', '/ˌreɡjʊˈleɪtəri kəmˈplaɪəns/', 'noun', '{"zh-TW":["監管合規"],"en":["adhering to laws, regulations, and standards governing business activities"]}', NULL, 'ensure regulatory compliance / regulatory compliance framework', '[{"en":"The company invested in regulatory compliance systems.","zh-TW":"公司投資了監管合規系統。"},{"en":"Failure to achieve regulatory compliance resulted in substantial fines.","zh-TW":"未能達到監管合規導致了重大罰款。"}]', NULL, NULL, 5, 5513, NULL),
(5514, 'regulatory framework', '/ˌreɡjʊlətəri ˈfreɪmwɜːrk/', 'noun', '{"zh-TW":["監管框架"],"en":["the set of laws, guidelines, and standards governing an industry or sector"]}', NULL, 'comply with the regulatory framework / regulatory framework update', '[{"en":"Financial institutions must operate within the regulatory framework.","zh-TW":"金融機構必須在監管框架內運營。"},{"en":"Changes to the regulatory framework affect compliance costs and practices.","zh-TW":"監管框架的變化影響了合規成本和做法。"}]', NULL, NULL, 5, 5514, NULL),
(5515, 'regulatory sandbox', '/ˈreɡjʊlətəri ˈsændbɒks/', 'noun', '{"zh-TW":["監管沙盒"],"en":["a framework allowing businesses to test innovations under relaxed regulations"]}', NULL, 'enter a regulatory sandbox / regulatory sandbox program / regulatory sandbox trial', '[{"en":"The fintech firm tested its payment product within a regulatory sandbox.","zh-TW":"金融科技公司在監管沙盒中測試其支付產品。"},{"en":"Regulatory sandboxes allow innovation while protecting consumers.","zh-TW":"監管沙盒允許創新同時保護消費者。"}]', NULL, NULL, 5, 5515, NULL),
(5516, 'rehabilitate', '/''riːhəˈbɪlɪteɪt/', 'verb', '{"zh-TW":["康復；復健"],"en":["to restore to health or normal life through training and therapy after illness or injury"]}', NULL, 'rehabilitate an injury / rehabilitate fully / sports rehabilitation', '[{"en":"The athlete worked with a physiotherapist to rehabilitate his knee injury.","zh-TW":"這位運動員與物理治療師合作，對膝關節損傷進行復健。"},{"en":"After surgery, it took six months to fully rehabilitate and return to competition.","zh-TW":"手術後，花了六個月時間完全復健並重返賽場。"}]', '{"noun":"rehabilitation"}', NULL, 4, 5516, NULL),
(5517, 'rehabilitation', '/ˌriːhəˌbɪlɪˈteɪʃən/', 'noun', '{"zh-TW":["復健；康復治療"],"en":["therapy to restore health or ability after injury"]}', NULL, 'physical rehabilitation / rehabilitation program', '[{"en":"She attended rehabilitation sessions twice a week.","zh-TW":"她每週兩次參加復健課程。"},{"en":"The rehabilitation program helped him regain full mobility.","zh-TW":"復健計劃幫助他恢復了完全的行動能力。"}]', '{"verb":"rehabilitate","adjective":"rehabilitated"}', NULL, 5, 5517, NULL),
(5518, 'rehabilitation program', '/''riːˌhæbɪlɪˌteɪʃən ˌprəʊɡræm/', 'noun', '{"zh-TW":["康復計劃；復健計劃"],"en":["a structured set of therapeutic activities designed to restore an injured person''s physical functioning"]}', NULL, 'complete a rehabilitation program / design a rehabilitation program / enter a rehabilitation program', '[{"en":"After knee surgery, she followed a six-month rehabilitation program to regain full mobility.","zh-TW":"膝蓋手術後，她遵循了六個月的康復計劃，以恢復完整的活動能力。"},{"en":"A well-designed rehabilitation program helps athletes return to training safely.","zh-TW":"設計良好的康復計劃幫助運動員安全地恢復訓練。"}]', '{"verb":"rehabilitate","noun":"rehabilitation"}', NULL, 5, 5518, NULL),
(5519, 'rehearsal', '/rɪˈhɜːrsəl/', 'noun', '{"zh-TW":["排練；彩排"],"en":["a practice session before a performance"]}', NULL, 'dress rehearsal / rehearsal room', '[{"en":"We have rehearsal every evening this week.","zh-TW":"這週我們每晚都有排練。"},{"en":"The dress rehearsal is tomorrow.","zh-TW":"彩排在明天。"}]', '{"verb":"rehearse"}', NULL, 3, 5519, NULL),
(5520, 'reimbursable', '/ˌriːɪmˈbɜːrsəbəl/', 'adjective', '{"zh-TW":["可報銷的"],"en":["able to be repaid or compensated"]}', NULL, 'reimbursable expense / reimbursable cost', '[{"en":"Travel costs are reimbursable upon submission of receipts.","zh-TW":"提交收據後差旅費用可以報銷。"},{"en":"Check which expenses are reimbursable under the policy.","zh-TW":"請查看政策下哪些費用可以報銷。"}]', NULL, NULL, 4, 5520, 920),
(5521, 'reimburse', '/ˌriːɪmˈbɜːrs/', 'verb', '{"zh-TW":["報銷；償還"],"en":["to pay back money spent"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"im-burse","meaning":"purse (錢包)"}}', 'reimburse expenses / reimburse sb. for / reimbursement policy', '[{"en":"The company will reimburse travel expenses.","zh-TW":"公司將報銷差旅費。"},{"en":"You will be reimbursed within 30 days.","zh-TW":"你將在30天內獲得報銷。"}]', '{"noun":"reimbursement"}', NULL, 3, 5521, 53),
(5522, 'reimbursement', '/ˌriːɪmˈbɜːrsmənt/', 'noun', '{"zh-TW":["報銷；補償"],"en":["repayment for expenses incurred"]}', NULL, 'expense reimbursement / request reimbursement', '[{"en":"Submit your receipts to receive reimbursement.","zh-TW":"提交收據以獲得報銷。"},{"en":"Business travel expenses will be reimbursed within two weeks.","zh-TW":"商務旅行費用將在兩週內報銷。"}]', '{"verb":"reimburse","adjective":"reimbursed"}', NULL, 5, 5522, 614),
(5523, 'reimbursement claim', '/ˌriːɪmˈbɜːrsmənt kleɪm/', 'noun', '{"zh-TW":["報銷申請"],"en":["a request to be repaid for expenses already paid out of pocket"]}', NULL, 'submit a reimbursement claim / process a reimbursement claim', '[{"en":"Employees must submit a reimbursement claim within 30 days.","zh-TW":"員工必須在30天內提交報銷申請。"},{"en":"All reimbursement claims are reviewed by the finance department.","zh-TW":"所有報銷申請都由財務部門審查。"}]', NULL, NULL, 5, 5523, NULL),
(5524, 'reinforce', '/ˌriːɪnˈfɔːrs/', 'verb', '{"zh-TW":["加強；鞏固"],"en":["to make stronger"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"in-force","meaning":"strengthen (加強)"}}', 'reinforce the message / reinforce a policy', '[{"en":"This reinforces our commitment to quality.","zh-TW":"這強化了我們對品質的承諾。"},{"en":"Training reinforces best practices.","zh-TW":"培訓鞏固了最佳做法。"}]', '{"noun":"reinforcement"}', NULL, 3, 5524, 714),
(5525, 'reinstate', '/ˌriːɪnˈsteɪt/', 'verb', '{"zh-TW":["恢復；重新啟用"],"en":["to restore something to its previous position or status"]}', NULL, 'reinstate a policy / reinstate an employee', '[{"en":"The suspended policy was reinstated after regulatory review.","zh-TW":"暫停的政策在監管審查後恢復了。"},{"en":"The dismissed employee was reinstated following a successful appeal.","zh-TW":"被解雇的員工在成功上訴後被恢復職位。"}]', '{"noun":"reinstatement","adjective":"reinstated"}', NULL, 3, 5525, NULL),
(5526, 'reinvest', '/ˌriːɪnˈvɛst/', 'verb', '{"zh-TW":["再投資"],"en":["to invest money gained back into the same or different ventures"]}', NULL, 'reinvest profits / reinvest in the business', '[{"en":"The company decided to reinvest its profits into research.","zh-TW":"公司決定將利潤再投資於研究。"},{"en":"Reinvesting dividends can significantly grow your wealth over time.","zh-TW":"再投資股息可以隨時間大幅增加您的財富。"}]', '{"noun":"reinvestment","adjective":"reinvested"}', NULL, 3, 5526, NULL),
(5527, 'reject', '/rɪˈdʒekt/', 'verb', '{"zh-TW":["拒絕；駁回"],"en":["to refuse to accept or consider","to refuse to accept"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ject","meaning":"throw (丟)"},"logic":"丟回去，即「拒絕」。"}', 'reject an offer / reject a proposal; reject a proposal / reject an application / flat out reject', '[{"en":"The committee rejected his proposal.","zh-TW":"委員會駁回了他的提案。"},{"en":"She rejected the job offer.","zh-TW":"她拒絕了這份工作邀約。"},{"en":"The board rejected the merger proposal.","zh-TW":"董事會駁回了合併提案。"},{"en":"Her application was rejected.","zh-TW":"她的申請被拒絕了。"}]', '{"noun":"rejection"}', NULL, 2, 5527, NULL),
(5528, 'rejection', '/rɪˈdʒɛkʃən/', 'noun', '{"zh-TW":["拒絕；駁回"],"en":["the dismissal of something or someone"]}', NULL, 'face rejection / rejection letter', '[{"en":"She received a rejection letter from the university.","zh-TW":"她收到了大學的拒絕信。"},{"en":"Rejection of the proposal was unexpected but prompted a revision.","zh-TW":"提案被拒絕出乎意料，但促使了修訂。"}]', '{"verb":"reject","adjective":"rejected"}', NULL, 3, 5528, 435),
(5529, 'rejection letter', '/rɪˈdʒekʃən ˈletər/', 'noun', '{"zh-TW":["拒絕信；未錄用通知"],"en":["a letter informing a candidate or supplier that they have not been selected"]}', NULL, 'send a rejection letter / receive a rejection letter', '[{"en":"All unsuccessful candidates received a rejection letter within a week.","zh-TW":"所有未成功的候選人在一週內收到了拒絕信。"},{"en":"A professional rejection letter maintains goodwill with future applicants.","zh-TW":"專業的拒絕信與未來的申請人保持了良好關係。"}]', NULL, NULL, 5, 5529, NULL),
(5530, 'relate', '/rɪˈleɪt/', 'verb', '{"zh-TW":["與...有關","敘述"],"en":["to connect or be relevant","to tell"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"late","meaning":"carry (攜帶)"}}', 'relate to / related to / in relation to', '[{"en":"This issue relates to our earlier discussion.","zh-TW":"這問題與我們之前的討論有關。"},{"en":"The increase is related to market demand.","zh-TW":"增長與市場需求有關。"}]', '{"noun":"relation, relationship","adjective":"related, relative","adverb":"relatively"}', NULL, 2, 5530, NULL),
(5531, 'relate to', '/rɪˈleɪt tuː/', 'verb', '{"zh-TW":["與⋯有關；適用於"],"en":["to be connected with or have relevance to something"]}', NULL, 'expenses that relate to operations / results that relate to the quarter', '[{"en":"The legal matter relates to a contract dispute from 2023.","zh-TW":"該法律事項與2023年的合約糾紛有關。"},{"en":"All queries relating to billing should be directed to accounts.","zh-TW":"所有與計費相關的查詢應聯絡帳務部門。"}]', NULL, NULL, 3, 5531, NULL),
(5532, 'related party transaction', '/rɪˈleɪtɪd ˈpɑːrti trænˈzækʃən/', 'noun', '{"zh-TW":["關聯方交易"],"en":["a business transaction between parties with a prior relationship or shared interest"]}', NULL, 'disclose related party transactions / related party transaction approval', '[{"en":"All related party transactions must be disclosed in the financial statements.","zh-TW":"所有關聯方交易必須在財務報表中披露。"},{"en":"The audit committee reviewed the terms of the related party transaction.","zh-TW":"審計委員會審查了關聯方交易的條款。"}]', NULL, NULL, 5, 5532, NULL),
(5533, 'relationship', 'rɪˈleɪʃənʃɪp', 'noun', '{"zh-TW":["關係；關聯","業務關係"],"en":["a connection between people","how things are connected"]}', NULL, 'business relationship/working relationship', '[{"en":"Strong client relationships lead to success.","zh-TW":"強大的客戶關係帶來成功。"}]', '{"adjective":"relational","adverb":"relationally"}', NULL, 4, 5533, 436),
(5534, 'relationship management', '/rɪˈleɪʃənʃɪp ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["關係管理"],"en":["strategies and processes for building and maintaining business relationships"]}', NULL, 'improve relationship management / customer relationship management', '[{"en":"Strong relationship management led to contract renewals.","zh-TW":"強大的關係管理帶來了合約續期。"},{"en":"CRM software supports relationship management with clients.","zh-TW":"CRM軟體支持與客戶的關係管理。"}]', NULL, NULL, 5, 5534, NULL),
(5535, 'relativism', '/ˈrelətɪvɪzəm/', 'noun', '{"zh-TW":["相對主義；相對論"],"en":["the doctrine that knowledge and values are not absolute"]}', NULL, 'moral relativism / cultural relativism / philosophical relativism', '[{"en":"Cultural relativism encourages understanding practices within their context.","zh-TW":"文化相對主義鼓勵在其脈絡中理解習俗。"},{"en":"Critics argue that relativism undermines universal ethical standards.","zh-TW":"批評者認為相對主義破壞了普世倫理標準。"}]', '{"adjective":"relativist","noun":"relativist"}', NULL, 4, 5535, NULL),
(5536, 'relay race', '/''riːleɪ reɪs/', 'noun', '{"zh-TW":["接力賽"],"en":["a race between teams in which each team member successively covers part of the total distance"]}', NULL, 'run a relay race / relay race team / anchor the relay race', '[{"en":"The relay race team passed the baton smoothly to win by half a second.","zh-TW":"接力賽隊伍順暢地交接接力棒，以半秒之差獲勝。"},{"en":"She was selected as the anchor runner for the relay race team.","zh-TW":"她被選為接力賽隊伍的最後一棒選手。"}]', NULL, NULL, 4, 5536, NULL),
(5537, 'release', '/rɪˈliːs/', 'verb', '{"zh-TW":["發布；釋放"],"en":["to make available; to set free"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"lease","meaning":"let go (放開)"}}', 'release a product / press release / release information', '[{"en":"The company will release the new product in March.","zh-TW":"公司將於三月發布新產品。"},{"en":"A press release was issued today.","zh-TW":"今天發布了新聞稿。"}]', '{"noun":"release"}', NULL, 3, 5537, 197),
(5538, 'release clause', '/rɪˈliːs klɔːz/', 'noun', '{"zh-TW":["解除條款"],"en":["a contract provision allowing one party to terminate under specific conditions"]}', NULL, 'invoke a release clause / negotiate a release clause', '[{"en":"The release clause allowed the firm to exit the lease after two years.","zh-TW":"解除條款允許公司在兩年後退出租約。"},{"en":"The release clause was triggered by the project''s failure to proceed.","zh-TW":"解除條款因項目未能推進而被觸發。"}]', NULL, NULL, 5, 5538, NULL),
(5539, 'release funds', '/rɪˈliːs fʌndz/', 'verb', '{"zh-TW":["釋放資金；撥付款項"],"en":["to make money available for use by authorizing its transfer"]}', NULL, 'release funds for a project / approve and release funds', '[{"en":"The finance committee approved and released funds for the renovation.","zh-TW":"財務委員會批准並撥付了翻新資金。"},{"en":"Funds are released in stages as project milestones are reached.","zh-TW":"隨著項目里程碑的實現，資金分階段釋放。"}]', NULL, NULL, 5, 5539, NULL),
(5540, 'relentless', '/''rɪˈlentləs/', 'adjective', '{"zh-TW":["不懈的；無情的"],"en":["oppressively constant; incessant; harsh or inflexible"]}', NULL, 'relentless pursuit / relentless pressure / relentless effort', '[{"en":"Her relentless effort finally paid off when she received the promotion.","zh-TW":"她不懈的努力最終在獲得晉升時得到了回報。"},{"en":"The team faced relentless pressure to meet the quarterly targets.","zh-TW":"團隊面臨著不斷的壓力以達到季度目標。"}]', '{"adverb":"relentlessly","noun":"relentlessness"}', NULL, 4, 5540, NULL),
(5541, 'relevant', '/ˈreləvənt/', 'adjective', '{"zh-TW":["相關的；切題的"],"en":["closely connected to the matter at hand","closely connected to the matter"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"lev","meaning":"raise (提起)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"能再次被提起的重要資訊，即「相關的」。"}', 'relevant experience / relevant information / highly relevant; relevant experience / relevant to / relevant information', '[{"en":"Please include all relevant information.","zh-TW":"請包含所有相關資訊。"},{"en":"Her experience is highly relevant to this position.","zh-TW":"她的經驗與這個職位高度相關。"},{"en":"Please include all relevant experience on your resume.","zh-TW":"請在履歷中包含所有相關經驗。"},{"en":"This is not relevant to the discussion.","zh-TW":"這與討論無關。"}]', '{"noun":"relevance","adverb":"relevantly"}', NULL, 3, 5541, NULL),
(5542, 'reliable', '/rɪˈlaɪəbl/', 'adjective', '{"zh-TW":["可靠的；可信賴的"],"en":["able to be trusted"]}', '{"root":{"text":"rely","meaning":"depend (依賴)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'reliable source / reliable service / highly reliable', '[{"en":"We need a reliable supplier.","zh-TW":"我們需要可靠的供應商。"},{"en":"The system has proven to be highly reliable.","zh-TW":"系統已被證明非常可靠。"}]', '{"noun":"reliability","adverb":"reliably","verb":"rely"}', NULL, 3, 5542, 437),
(5543, 'relief', '/rɪˈliːf/', 'noun', '{"zh-TW":["緩解；減輕","救濟"],"en":["the feeling of comfort after anxiety","aid given"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"lief","meaning":"lift (舉起)"}}', 'tax relief / disaster relief / to one''s relief / provide relief', '[{"en":"The tax relief benefits small businesses.","zh-TW":"稅收減免有利於小企業。"},{"en":"To our relief, the problem was resolved quickly.","zh-TW":"令我們欣慰的是，問題很快解決了。"}]', '{"verb":"relieve"}', NULL, 2, 5543, NULL),
(5544, 'relocation package', '/ˌriːloʊˈkeɪʃən ˈpækɪdʒ/', 'noun', '{"zh-TW":["搬遷方案；異地補貼"],"en":["benefits provided to an employee who moves for their job"]}', NULL, 'offer a relocation package / relocation package terms / generous relocation package', '[{"en":"The relocation package covered moving costs and temporary housing.","zh-TW":"搬遷方案涵蓋搬遷費用和臨時住房。"},{"en":"She accepted the job offer partly because of the generous relocation package.","zh-TW":"她接受工作邀請部分原因是豐厚的搬遷方案。"}]', NULL, NULL, 5, 5544, NULL),
(5545, 'reluctant', '/rɪˈlʌktənt/', 'adjective', '{"zh-TW":["不情願的","不情願的；勉強的"],"en":["unwilling and hesitant","unwilling to do something"]}', '{"prefix":{"text":"re-","meaning":"against (反對)"},"root":{"text":"luct","meaning":"struggle (掙扎)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"對某事掙扎抗拒的，即「不情願的」。"}', 'reluctant to / a reluctant participant; reluctant to do / be reluctant', '[{"en":"He was reluctant to admit his mistake.","zh-TW":"他不情願承認自己的錯誤。"},{"en":"She was a reluctant participant in the debate.","zh-TW":"她是辯論中不情願的參與者。"},{"en":"He was reluctant to accept the transfer.","zh-TW":"他不情願接受調動。"},{"en":"Many employees are reluctant to change.","zh-TW":"許多員工不願意改變。"}]', '{"noun":"reluctance","adverb":"reluctantly"}', NULL, 3, 5545, NULL),
(5546, 'rely', '/rɪˈlaɪ/', 'verb', '{"zh-TW":["依賴；信賴","依賴；依靠"],"en":["to depend on with full trust","to depend on with confidence"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"ly","meaning":"bind (綁)"},"logic":"被綁回到某人身上（依靠），即「依賴」。"}', 'rely on / rely heavily on; rely on / rely heavily on / reliable', '[{"en":"We rely on technology for communication.","zh-TW":"我們依賴科技來溝通。"},{"en":"You can rely on her to do a good job.","zh-TW":"你可以信賴她會做好。"},{"en":"We rely heavily on technology.","zh-TW":"我們嚴重依賴技術。"},{"en":"You can rely on our team to deliver.","zh-TW":"你可以依靠我們團隊交付。"}]', '{"adjective":"reliable","noun":"reliance","noun2":"reliability"}', NULL, 1, 5546, NULL),
(5547, 'remain', '/rɪˈmeɪn/', 'verb', '{"zh-TW":["保持；仍然是","剩餘"],"en":["to continue in the same state","to be left"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"main","meaning":"stay (停留)"}}', 'remain unchanged / remain competitive / remaining balance', '[{"en":"Prices remain stable this quarter.","zh-TW":"本季度價格保持穩定。"},{"en":"Several issues remain unresolved.","zh-TW":"幾個問題仍未解決。"}]', '{"noun":"remainder, remains","adjective":"remaining"}', NULL, 2, 5547, 198),
(5548, 'remarkable', '/rɪˈmɑːrkəbl/', 'adjective', '{"zh-TW":["卓越的；非凡的"],"en":["worthy of attention; extraordinary"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"mark","meaning":"notice (注意)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'remarkable achievement / remarkable growth', '[{"en":"The company has shown remarkable growth.","zh-TW":"公司展現了非凡的增長。"},{"en":"Her performance was truly remarkable.","zh-TW":"她的表現真正非凡。"}]', '{"adverb":"remarkably"}', NULL, 4, 5548, NULL),
(5549, 'remedial class', '/''rɪˈmiːdiəl klɑːs/', 'noun', '{"zh-TW":["補救教學班；補救課程"],"en":["a class intended to help students who are struggling with the standard curriculum"]}', NULL, 'enroll in a remedial class / take a remedial class / benefit of remedial class', '[{"en":"Students who fail the placement test must take remedial math classes.","zh-TW":"未能通過分級測試的學生必須參加數學補救教學班。"},{"en":"Remedial classes helped her catch up and eventually join the mainstream program.","zh-TW":"補救課程幫助她趕上進度，最終加入主流計畫。"}]', NULL, NULL, 5, 5549, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5550, 'remediation', '/rɪˌmiːdiˈeɪʃən/', 'noun', '{"zh-TW":["補救措施；修復"],"en":["the action of rectifying a problem, error, or environmental issue"]}', NULL, 'complete remediation / remediation plan', '[{"en":"The company implemented a remediation plan after the audit findings.","zh-TW":"公司在審計發現後實施了補救措施計劃。"},{"en":"Environmental remediation was required before the land could be redeveloped.","zh-TW":"在土地重新開發前需要進行環境修復。"}]', '{"verb":"remediate"}', NULL, 4, 5550, NULL),
(5551, 'remedy', '/ˈrɛmɪdi/', 'noun', '{"zh-TW":["補救措施；療法"],"en":["a solution to a problem"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"med","meaning":"heal (治療)"}}', 'find a remedy / legal remedy / remedy the situation', '[{"en":"We must find a remedy for this issue.","zh-TW":"我們必須找到解決方案。"},{"en":"Legal remedies are available.","zh-TW":"可採取法律補救措施。"}]', '{"verb":"remedy","adjective":"remedial"}', NULL, 2, 5551, NULL),
(5552, 'remember', '/rɪˈmɛmbər/', 'verb', '{"zh-TW":["記得；想起"],"en":["to have in mind","to recall"]}', NULL, 'remember to / if I remember correctly', '[{"en":"Remember to submit the report.","zh-TW":"記得提交報告。"},{"en":"If I remember correctly, the deadline is Friday.","zh-TW":"如果我沒記錯，截止日期是週五。"}]', '{"verb":"remember","noun":"remembrance"}', NULL, 3, 5552, NULL),
(5553, 'remind', '/rɪˈmaɪnd/', 'verb', '{"zh-TW":["提醒"],"en":["to cause someone to remember"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"mind","meaning":"mind (心智)"}}', 'remind sb. of / remind sb. to do / a reminder', '[{"en":"Please remind me to call the client.","zh-TW":"請提醒我打給客戶。"},{"en":"This is a reminder that reports are due Friday.","zh-TW":"這是提醒：報告週五到期。"}]', '{"noun":"reminder"}', NULL, 2, 5553, 199),
(5554, 'reminder', 'rɪˈmaɪndər', 'noun', '{"zh-TW":["提醒；提示","催促"],"en":["a message to make someone remember","a note to remind"]}', NULL, 'send a reminder/friendly reminder', '[{"en":"Please send a reminder to all attendees.","zh-TW":"請向所有出席者發送提醒。"}]', '{"verb":"remind","adjective":"reminded"}', NULL, 3, 5554, NULL),
(5555, 'remission', '/rɪˈmɪʃən/', 'noun', '{"zh-TW":["緩解；病情暫時好轉"],"en":["a temporary or permanent decrease in the severity of a disease"]}', NULL, 'go into remission / achieve remission / complete remission', '[{"en":"The patient''s leukemia went into complete remission after treatment.","zh-TW":"患者的白血病在治療後完全緩解。"},{"en":"Maintaining remission requires ongoing medication and lifestyle management.","zh-TW":"維持緩解需要持續的藥物治療和生活方式管理。"}]', '{"verb":"remit","adjective":"in remission"}', NULL, 3, 5555, NULL),
(5556, 'remittance', '/rɪˈmɪtəns/', 'noun', '{"zh-TW":["匯款；匯寄"],"en":["a sum of money sent to someone abroad"]}', NULL, 'send a remittance / remittance service', '[{"en":"She sent a monthly remittance to support her family abroad.","zh-TW":"她每月匯款支持她在國外的家人。"},{"en":"Remittance fees vary between service providers.","zh-TW":"匯款費用因服務提供商而異。"}]', '{"verb":"remit"}', NULL, 4, 5556, NULL),
(5557, 'remittance advice', '/rɪˈmɪtəns ədˈvaɪs/', 'noun', '{"zh-TW":["匯款通知；付款通知"],"en":["a document sent by the payer to notify the recipient of a payment"]}', NULL, 'send a remittance advice / include remittance advice', '[{"en":"Please find the attached remittance advice for payment made today.","zh-TW":"請查找今天已付款的隨附匯款通知。"},{"en":"Remittance advice helps the recipient match payment to the invoice.","zh-TW":"匯款通知幫助收款人將付款與發票匹配。"}]', NULL, NULL, 5, 5557, NULL),
(5558, 'remote', '/rɪˈmoʊt/', 'adjective', '{"zh-TW":["遠程的；偏遠的"],"en":["far away; operating from a distance"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"mote","meaning":"move (移動)"}}', 'remote work / remote access / remote location', '[{"en":"Most employees now work remotely.","zh-TW":"大多數員工現在遠程工作。"},{"en":"Remote access to the system is available.","zh-TW":"系統可以遠程訪問。"}]', '{"adverb":"remotely","noun":"remoteness"}', NULL, 2, 5558, NULL),
(5559, 'remote access', '/rɪˈməʊt ˈæksɛs/', 'noun', '{"zh-TW":["遠端訪問"],"en":["the ability to access a computer or network from a different location"]}', NULL, 'enable remote access / secure remote access', '[{"en":"Employees require remote access to company systems when traveling.","zh-TW":"員工在出差時需要遠端訪問公司系統。"},{"en":"Remote access must be secured with multi-factor authentication.","zh-TW":"遠端訪問必須通過多因素驗證加以保護。"}]', NULL, NULL, 5, 5559, NULL),
(5560, 'remote collaboration', '/''rɪˌməʊt kəˌlæbəˌreɪʃən/', 'noun', '{"zh-TW":["遠程協作；線上合作"],"en":["working together with colleagues or partners who are in different physical locations"]}', NULL, 'enable remote collaboration / challenge of remote collaboration / remote collaboration tool', '[{"en":"Effective remote collaboration requires clear communication and reliable technology.","zh-TW":"有效的遠程協作需要清晰的溝通和可靠的技術。"},{"en":"The company invested in tools to support remote collaboration across multiple time zones.","zh-TW":"公司投資於支持跨多個時區遠程協作的工具。"}]', '{"verb":"collaborate","adjective":"remote"}', NULL, 5, 5560, NULL),
(5561, 'remote work', '/rɪˈmoʊt wɜːrk/', 'noun', '{"zh-TW":["遠端工作；遠距工作"],"en":["working outside a traditional office environment, often from home"]}', NULL, 'remote work policy / adopt remote work / fully remote', '[{"en":"Remote work became widespread during the pandemic.","zh-TW":"疫情期間，遠端工作變得普遍。"},{"en":"The company offers remote work options to attract global talent.","zh-TW":"公司提供遠端工作選項以吸引全球人才。"}]', '{"adjective":"remote","noun":"remote worker"}', NULL, 4, 5561, NULL),
(5562, 'remove', '/rɪˈmuːv/', 'verb', '{"zh-TW":["移除；消除"],"en":["to take away"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"move","meaning":"move (移動)"}}', 'remove from / remove obstacles / remove barriers', '[{"en":"Please remove your belongings from the desk.","zh-TW":"請把你的物品從桌上移走。"},{"en":"We need to remove barriers to entry.","zh-TW":"我們需要消除進入障礙。"}]', '{"noun":"removal","adjective":"removable"}', NULL, 2, 5562, NULL),
(5563, 'remunerate', '/rɪˈmjuːnəreɪt/', 'verb', '{"zh-TW":["酬勞；報酬"],"en":["to pay someone for services rendered"]}', NULL, 'remunerate fairly / remunerate employees / remunerate adequately', '[{"en":"The policy ensures all employees are remunerated fairly.","zh-TW":"該政策確保所有員工得到公平酬勞。"},{"en":"The contract specifies how consultants are to be remunerated.","zh-TW":"合約規定了顧問的酬勞方式。"}]', '{"noun":"remuneration","adjective":"remunerative"}', NULL, 4, 5563, NULL),
(5564, 'remuneration', '/rɪˌmjuːnəˈreɪʃən/', 'noun', '{"zh-TW":["報酬；薪資"],"en":["payment or reward for work or services provided"]}', NULL, 'total remuneration / remuneration package / executive remuneration', '[{"en":"The remuneration committee sets executive pay levels.","zh-TW":"薪酬委員會確定高管薪資水準。"},{"en":"Remuneration should reflect the employee''s level of responsibility.","zh-TW":"報酬應反映員工的責任水準。"}]', '{"verb":"remunerate","adjective":"remunerative"}', NULL, 4, 5564, 922),
(5565, 'remuneration package', '/rɪˌmjuːnəˈreɪʃən ˈpækɪdʒ/', 'noun', '{"zh-TW":["薪酬套餐"],"en":["the total pay and benefits offered to an employee in return for their work"]}', NULL, 'offer a remuneration package / review the remuneration package', '[{"en":"The executive''s remuneration package includes salary, bonus, and pension.","zh-TW":"高管的薪酬套餐包括薪資、獎金和退休金。"},{"en":"A competitive remuneration package helps attract senior talent.","zh-TW":"有競爭力的薪酬套餐有助於吸引高層人才。"}]', NULL, NULL, 5, 5565, NULL),
(5566, 'renegotiate', '/ˌriːnɪˈɡoʊʃieɪt/', 'verb', '{"zh-TW":["重新談判；重新協商"],"en":["to negotiate the terms of an existing agreement again"]}', NULL, 'renegotiate a contract / renegotiate payment terms', '[{"en":"The company renegotiated its supplier contracts to reduce costs.","zh-TW":"公司重新談判了供應商合約以降低成本。"},{"en":"Loan terms were renegotiated to improve cash flow.","zh-TW":"貸款條款重新談判以改善現金流。"}]', '{"noun":"renegotiation","adjective":"renegotiated"}', NULL, 4, 5566, NULL),
(5567, 'renew', '/rɪˈnjuː/', 'verb', '{"zh-TW":["更新；續約"],"en":["to make valid for another period"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"new","meaning":"new (新)"}}', 'renew a contract / renew a subscription / renewal date', '[{"en":"Don''t forget to renew your license.","zh-TW":"別忘了更新你的執照。"},{"en":"The contract was renewed for another year.","zh-TW":"合約續約了一年。"}]', '{"noun":"renewal","adjective":"renewable"}', NULL, 2, 5567, 716),
(5568, 'renewable energy', '/rɪˈnjuːəbəl ˈɛnərdʒi/', 'noun', '{"zh-TW":["再生能源；可再生能源"],"en":["energy from a source that is not depleted when used"]}', NULL, 'invest in renewable energy / renewable energy source', '[{"en":"Solar and wind are popular forms of renewable energy.","zh-TW":"太陽能和風能是受歡迎的再生能源形式。"},{"en":"Renewable energy is becoming more affordable each year.","zh-TW":"再生能源每年變得越來越實惠。"}]', '{"adjective":"renewable"}', NULL, 5, 5568, NULL),
(5569, 'renewable energy source', '/''rɪˌnjuːəbəl ˌenərʒi sɔːrs/', 'noun', '{"zh-TW":["可再生能源"],"en":["an energy source that is naturally replenished, such as solar, wind, or hydropower"]}', NULL, 'invest in renewable energy sources / switch to renewable energy sources / develop renewable energy sources', '[{"en":"The government increased investment in renewable energy sources to reduce carbon emissions.","zh-TW":"政府增加了對可再生能源的投資，以減少碳排放。"},{"en":"Renewable energy sources are expected to supply the majority of global power by mid-century.","zh-TW":"預計到本世紀中葉，可再生能源將供應全球大部分電力。"}]', '{"adjective":"renewable"}', NULL, 5, 5569, NULL),
(5570, 'renewable portfolio standard', '/rɪˈnjuːəbəl pɔːtˈfəʊliəʊ ˈstændərd/', 'noun', '{"zh-TW":["再生能源組合標準"],"en":["a regulatory mandate requiring utilities to generate a percentage of electricity from renewables"]}', NULL, 'meet renewable portfolio standard / implement renewable portfolio standard / renewable portfolio standard targets', '[{"en":"The state''s renewable portfolio standard requires forty percent clean energy by 2030.","zh-TW":"該州的再生能源組合標準要求到2030年使用百分之四十的清潔能源。"},{"en":"Renewable portfolio standards have driven significant growth in wind and solar power.","zh-TW":"再生能源組合標準推動了風能和太陽能的顯著增長。"}]', NULL, NULL, 5, 5570, NULL),
(5571, 'renewable resource', '/rɪˈnjuːəbəl rɪˈzɔːrs/', 'noun', '{"zh-TW":["可再生資源"],"en":["a natural resource that is replenished naturally over time"]}', NULL, 'use renewable resources / conserve renewable resources', '[{"en":"Wind and solar power are examples of renewable resources.","zh-TW":"風能和太陽能是可再生資源的例子。"},{"en":"Transitioning to renewable resources is essential for sustainability.","zh-TW":"過渡到可再生資源對永續發展至關重要。"}]', NULL, NULL, 5, 5571, NULL),
(5572, 'renewal', 'rɪˈnjuːəl', 'noun', '{"zh-TW":["續約；更新","復甦"],"en":["the act of renewing","continuing after a period"]}', NULL, 'contract renewal/subscription renewal', '[{"en":"Please confirm your contract renewal.","zh-TW":"請確認您的合約續簽。"}]', '{"verb":"renew","adjective":"renewable"}', NULL, 3, 5572, 439),
(5573, 'renewal clause', '/rɪˈnjuːəl klɔːz/', 'noun', '{"zh-TW":["續約條款"],"en":["a contract provision allowing automatic or optional renewal of an agreement"]}', NULL, 'include a renewal clause / exercise the renewal clause', '[{"en":"The lease included a renewal clause allowing a 3-year extension.","zh-TW":"租約包含了允許延長3年的續約條款。"},{"en":"The client exercised the renewal clause before the contract expired.","zh-TW":"客戶在合約到期前行使了續約條款。"}]', NULL, NULL, 5, 5573, NULL),
(5574, 'renewal rate', '/rɪˈnjuːəl reɪt/', 'noun', '{"zh-TW":["續約率"],"en":["the percentage of customers who renew a contract or subscription"]}', NULL, 'improve renewal rate / track renewal rate', '[{"en":"The software''s renewal rate increased after new features were added.","zh-TW":"添加新功能後軟件的續約率提高了。"},{"en":"A high renewal rate indicates strong customer satisfaction.","zh-TW":"高續約率表明客戶滿意度高。"}]', NULL, NULL, 4, 5574, NULL),
(5575, 'renewal terms', '/rɪˈnjuːəl tɜːrmz/', 'noun', '{"zh-TW":["續約條款"],"en":["the conditions under which a contract will be extended"]}', NULL, 'negotiate renewal terms / review renewal terms', '[{"en":"The supplier proposed new pricing as part of the renewal terms.","zh-TW":"供應商提出了新定價作為續約條款的一部分。"},{"en":"Renewal terms were accepted without modification by both parties.","zh-TW":"雙方未作修改地接受了續約條款。"}]', NULL, NULL, 5, 5575, NULL),
(5576, 'renovate', '/ˈrɛnəveɪt/', 'verb', '{"zh-TW":["翻新；修繕","翻修"],"en":["to repair and improve a building","to restore to good condition"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"nov","meaning":"new (新)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'renovate the office / recently renovated; renovate the building / newly renovated', '[{"en":"The office was recently renovated.","zh-TW":"辦公室最近進行了翻新。"},{"en":"They plan to renovate the building.","zh-TW":"他們計劃翻新大樓。"},{"en":"The hotel was recently renovated.","zh-TW":"酒店最近翻新了。"},{"en":"Plans to renovate the office were approved.","zh-TW":"翻新辦公室的計劃已獲批。"}]', '{"noun":"renovation"}', NULL, 3, 5576, NULL),
(5577, 'renovation', '/ˌrenəˈveɪʃən/', 'noun', '{"zh-TW":["翻新；整修"],"en":["the process of improving or restoring a building to good condition"]}', NULL, 'property renovation / renovation project / renovation costs', '[{"en":"The office underwent major renovation over the summer.","zh-TW":"辦公室在夏季進行了大規模翻新。"},{"en":"Renovation costs were higher than initially budgeted.","zh-TW":"翻新費用高於最初預算。"}]', '{"verb":"renovate","adjective":"renovated"}', NULL, 4, 5577, NULL),
(5578, 'rent', '/rɛnt/', 'noun', '{"zh-TW":["租金"],"en":["payment for use of property"]}', NULL, 'pay rent / rent out / for rent / rental agreement', '[{"en":"Office rent has increased significantly.","zh-TW":"辦公室租金大幅上漲。"},{"en":"The apartment is available for rent.","zh-TW":"公寓可供出租。"}]', '{"verb":"rent","noun":"rental, renter"}', NULL, 1, 5578, NULL),
(5579, 'rent stabilization', '/''rent ˌsteɪbɪlaɪˌzeɪʃən/', 'noun', '{"zh-TW":["租金穩定；租金管制"],"en":["a policy that limits how much landlords can increase rent for existing tenants"]}', NULL, 'implement rent stabilization / rent stabilization policy / benefit of rent stabilization', '[{"en":"Rent stabilization policies help protect low-income tenants from being priced out of their homes.","zh-TW":"租金穩定政策有助於保護低收入租戶免於因租金上漲而被迫搬離。"},{"en":"Critics argue that rent stabilization discourages property maintenance and investment.","zh-TW":"批評者認為，租金穩定政策阻礙了物業維護和投資。"}]', '{"verb":"stabilize","noun":"stabilization"}', NULL, 5, 5579, NULL),
(5580, 'rental agreement', '/''rentəl əˌɡriːmənt/', 'noun', '{"zh-TW":["租賃協議；租約"],"en":["a contract between a landlord and tenant outlining the terms and conditions of renting a property"]}', NULL, 'sign a rental agreement / review a rental agreement / rental agreement terms', '[{"en":"She carefully reviewed the rental agreement before signing to ensure the terms were fair.","zh-TW":"她在簽署租賃協議前仔細審查，確保條款公平。"},{"en":"The rental agreement specifies that no pets are allowed in the property.","zh-TW":"租賃協議規定該房產不允許養寵物。"}]', '{"noun":"rental","verb":"rent"}', NULL, 5, 5580, NULL),
(5581, 'rental contract', '/''rentəl ˌkɒntrækt/', 'noun', '{"zh-TW":["租賃合同；租約"],"en":["a legal agreement between a landlord and tenant that sets out the terms of renting a property"]}', NULL, 'sign a rental contract / renew a rental contract / breach a rental contract', '[{"en":"Before moving in, she carefully read through the rental contract.","zh-TW":"搬入之前，她仔細閱讀了租賃合同。"},{"en":"The rental contract prohibited pets and required two months'' notice before vacating.","zh-TW":"租賃合同禁止飼養寵物，並要求在搬出前兩個月通知。"}]', NULL, NULL, 5, 5581, NULL),
(5582, 'rental income', '/''rentəl ˌɪŋkʌm/', 'noun', '{"zh-TW":["租金收入；房租收入"],"en":["money received from tenants for the use of a property"]}', NULL, 'earn rental income / report rental income / rental income tax', '[{"en":"She invested in a second property to generate a steady stream of rental income.","zh-TW":"她投資了第二套房產，以產生穩定的租金收入。"},{"en":"Rental income must be declared to the tax authorities each year.","zh-TW":"租金收入每年必須向稅務機關申報。"}]', NULL, NULL, 5, 5582, NULL),
(5583, 'rental market', '/''rentəl ˌmɑːrkɪt/', 'noun', '{"zh-TW":["租賃市場；租房市場"],"en":["the sector of the housing market concerned with renting rather than buying properties"]}', NULL, 'tight rental market / rental market conditions / rental market analysis', '[{"en":"The tight rental market pushed rents to record highs in major cities.","zh-TW":"緊繃的租賃市場將主要城市的租金推至歷史新高。"},{"en":"An oversupply of apartments cooled the rental market significantly.","zh-TW":"公寓供應過剩大幅冷卻了租賃市場。"}]', NULL, NULL, 5, 5583, NULL),
(5584, 'rental yield', '/''rentəl jiːld/', 'noun', '{"zh-TW":["租金回報率；租賃收益"],"en":["the annual income from a property expressed as a percentage of its value"]}', NULL, 'calculate rental yield / high rental yield / rental yield comparison', '[{"en":"Investors look for properties with a rental yield of at least five percent.","zh-TW":"投資者尋找租金回報率至少為百分之五的房產。"},{"en":"The rental yield on the downtown apartment was much higher than suburban properties.","zh-TW":"市中心公寓的租金回報率遠高於郊區房產。"}]', NULL, NULL, 4, 5584, NULL),
(5585, 'reorder point', '/ˌriːˈɔːrdər pɔɪnt/', 'noun', '{"zh-TW":["再訂購點；補貨觸發點"],"en":["the inventory level at which a new order should be placed"]}', NULL, 'set the reorder point / reach the reorder point', '[{"en":"Stock fell below the reorder point, triggering a new order.","zh-TW":"庫存降至再訂購點以下，觸發了新訂單。"},{"en":"The reorder point accounts for lead time and average demand.","zh-TW":"再訂購點考慮了前置時間和平均需求。"}]', NULL, NULL, 5, 5585, NULL),
(5586, 'reorganize', 'riːˈɔːrɡənaɪz', 'verb', '{"zh-TW":["重組；重新整理","調整"],"en":["to arrange differently","to restructure"]}', NULL, 'reorganize a department/reorganize files', '[{"en":"Management decided to reorganize the team.","zh-TW":"管理層決定重組團隊。"}]', '{"noun":"reorganization","adjective":"reorganized"}', NULL, 4, 5586, NULL),
(5587, 'repair', '/rɪˈpɛr/', 'verb', '{"zh-TW":["修理；修復"],"en":["to fix something broken"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"pair","meaning":"prepare (準備)"}}', 'repair damage / under repair / repair costs', '[{"en":"The equipment is being repaired.","zh-TW":"設備正在維修中。"},{"en":"Repair costs exceeded our estimates.","zh-TW":"修理費用超出了我們的估計。"}]', '{"noun":"repair, reparation"}', NULL, 2, 5587, 54),
(5588, 'repay', '/rɪˈpeɪ/', 'verb', '{"zh-TW":["償還；歸還"],"en":["to pay back money that was borrowed"]}', NULL, 'repay a loan / repay debt / repay in full', '[{"en":"She repaid the business loan ahead of schedule.","zh-TW":"她提前償還了商業貸款。"},{"en":"The investment was repaid with a 15% return within two years.","zh-TW":"投資在兩年內以15%的回報率得到了償還。"}]', '{"noun":"repayment","adjective":"repaid"}', NULL, 2, 5588, NULL),
(5589, 'repayment plan', '/''rɪˌpeɪmənt plæn/', 'noun', '{"zh-TW":["還款計劃；還款方案"],"en":["a schedule for repaying a debt over time in installments"]}', NULL, 'agree on a repayment plan / follow a repayment plan / set up a repayment plan', '[{"en":"She negotiated a repayment plan with the bank after falling behind on mortgage payments.","zh-TW":"她在落後于按揭還款後與銀行協商了一個還款計劃。"},{"en":"A structured repayment plan helps borrowers manage debt without financial stress.","zh-TW":"有結構的還款計劃幫助借款人在不承受財務壓力的情況下管理債務。"}]', NULL, NULL, 5, 5589, NULL),
(5590, 'repayment schedule', '/rɪˈpeɪmənt ˈʃedjuːl/', 'noun', '{"zh-TW":["還款計劃；還款時間表"],"en":["a timetable detailing when and how much of a loan will be repaid"]}', NULL, 'set a repayment schedule / adhere to the repayment schedule', '[{"en":"The bank approved a flexible repayment schedule tied to revenue.","zh-TW":"銀行批准了與收入掛鉤的彈性還款計劃。"},{"en":"Missing payments on the repayment schedule triggers penalty clauses.","zh-TW":"未按還款計劃支付款項觸發了罰款條款。"}]', NULL, NULL, 5, 5590, NULL),
(5591, 'repeat order', '/rɪˈpiːt ˈɔːrdər/', 'noun', '{"zh-TW":["重複訂單；回頭訂單"],"en":["a subsequent order from a customer who has previously purchased the same product"]}', NULL, 'place a repeat order / encourage repeat orders', '[{"en":"The product''s quality led to a high rate of repeat orders.","zh-TW":"產品的品質帶來了高比率的重複訂單。"},{"en":"Repeat orders are more cost-effective than acquiring new customers.","zh-TW":"重複訂單比獲取新客戶更具成本效益。"}]', NULL, NULL, 4, 5591, NULL),
(5592, 'repercussion', '/''riːpərˌkʌʃən/', 'noun', '{"zh-TW":["反響；後果；影響"],"en":["an unintended consequence occurring some time after an event or action"]}', NULL, 'face repercussions / consider repercussions / serious repercussion', '[{"en":"The decision to cut costs had repercussions on product quality and customer satisfaction.","zh-TW":"削減成本的決定對產品質量和客戶滿意度產生了影響。"},{"en":"Ignoring employee feedback can have serious long-term repercussions for morale.","zh-TW":"忽視員工反饋可能對士氣產生嚴重的長期影響。"}]', NULL, NULL, 4, 5592, NULL),
(5593, 'repetition', '/''repɪˈtɪʃən/', 'noun', '{"zh-TW":["重複；組數中的次數"],"en":["the action of doing something again; in fitness, one complete movement of an exercise"]}', NULL, 'do ten repetitions / repetition and sets / controlled repetition', '[{"en":"Each set consisted of ten repetitions of the exercise.","zh-TW":"每組包含十次重複的練習動作。"},{"en":"Focus on quality of movement rather than the number of repetitions.","zh-TW":"專注於動作質量，而不是重複次數的多少。"}]', '{"verb":"repeat","adjective":"repetitive"}', NULL, 4, 5593, NULL),
(5594, 'replace', '/rɪˈpleɪs/', 'verb', '{"zh-TW":["取代；更換"],"en":["to put something new in place of"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"place","meaning":"place (放置)"}}', 'replace with / replace sb. / find a replacement', '[{"en":"We will replace the old system with a new one.","zh-TW":"我們將用新系統取代舊系統。"},{"en":"She was hired to replace the former manager.","zh-TW":"她被聘來接替前任經理。"}]', '{"noun":"replacement","adjective":"replaceable"}', NULL, 3, 5594, 200),
(5595, 'replacement', 'rɪˈpleɪsmənt', 'noun', '{"zh-TW":["更換；替代品","接替者"],"en":["someone or something substituted","the act of replacing"]}', NULL, 'find a replacement/product replacement', '[{"en":"The replacement part arrived yesterday.","zh-TW":"替換零件昨天到達了。"}]', '{"verb":"replace","adjective":"replaceable"}', NULL, 4, 5595, 615),
(5596, 'replenishment', '/rɪˈplenɪʃmənt/', 'noun', '{"zh-TW":["補貨；補充"],"en":["restoring a stock of goods to an adequate level"]}', NULL, 'schedule replenishment / automatic replenishment / stock replenishment', '[{"en":"Automated replenishment reduces the risk of stockouts.","zh-TW":"自動補貨降低了缺貨的風險。"},{"en":"The replenishment order was placed as soon as inventory hit the reorder point.","zh-TW":"庫存一觸及再訂購點就立即下達了補貨訂單。"}]', '{"verb":"replenish","adjective":"replenished"}', NULL, 5, 5596, NULL),
(5597, 'replicate', '/ˈreplɪkeɪt/', 'verb', '{"zh-TW":["複製；重複驗證"],"en":["to make an exact copy; to repeat an experiment to verify results"]}', NULL, 'replicate results / replicate a study / replicate the model', '[{"en":"Scientists must be able to replicate their experiments.","zh-TW":"科學家必須能夠重複驗證他們的實驗。"},{"en":"The findings could not be replicated in subsequent studies.","zh-TW":"這些發現在後續研究中無法被重複驗證。"}]', '{"noun":"replication","adjective":"replicable"}', NULL, 3, 5597, NULL),
(5598, 'replication', '/ˌreplɪˈkeɪʃən/', 'noun', '{"zh-TW":["重複驗證；複製"],"en":["the action of copying or reproducing something; repetition of an experiment"]}', NULL, 'replication of results / replication study / direct replication', '[{"en":"Replication is a cornerstone of the scientific method.","zh-TW":"重複驗證是科學方法的基石。"},{"en":"The replication crisis has challenged findings in social psychology.","zh-TW":"重複驗證危機挑戰了社會心理學的研究結果。"}]', '{"verb":"replicate","adjective":"replicable"}', NULL, 4, 5598, NULL),
(5599, 'reply', 'rɪˈplaɪ', 'noun', '{"zh-TW":["回覆；答覆","回應"],"en":["an answer to a message","a response"]}', NULL, 'await a reply/in reply to', '[{"en":"We are waiting for your reply.","zh-TW":"我們正在等待您的回覆。"}]', '{"verb":"reply","adjective":"replying"}', NULL, 2, 5599, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5600, 'report', '/rɪˈpɔːrt/', 'noun', '{"zh-TW":["報告；報告書"],"en":["a written or spoken account of a topic or event"]}', NULL, 'annual report / submit a report', '[{"en":"The team submitted the quarterly sales report.","zh-TW":"團隊提交了季度銷售報告。"},{"en":"Her report provided valuable insights for management.","zh-TW":"她的報告為管理層提供了寶貴見解。"}]', '{"verb":"report","noun":"reporter","adjective":"reported"}', NULL, 2, 5600, 201),
(5601, 'report on findings', '/rɪˈpɔːrt ɒn ˈfaɪndɪŋz/', 'verb', '{"zh-TW":["報告調查結果"],"en":["to present conclusions derived from research or investigation"]}', NULL, 'report on audit findings / report on research findings', '[{"en":"The inspector will report on findings to the board next week.","zh-TW":"檢查員將於下週向董事會報告調查結果。"},{"en":"The team was asked to report on findings from the customer survey.","zh-TW":"團隊被要求報告客戶調查的調查結果。"}]', NULL, NULL, 5, 5601, NULL),
(5602, 'report writing', '/rɪˈpɔːrt ˈraɪtɪŋ/', 'noun', '{"zh-TW":["報告撰寫"],"en":["the process of preparing a structured document communicating findings or recommendations"]}', NULL, 'improve report writing / professional report writing', '[{"en":"Clear report writing is essential for effective business communication.","zh-TW":"清晰的報告撰寫對於有效的業務溝通至關重要。"},{"en":"Report writing skills are highly valued in consulting and finance roles.","zh-TW":"報告撰寫技能在諮詢和財務職位中備受重視。"}]', NULL, NULL, 5, 5602, NULL),
(5603, 'reporting line', '/rɪˈpɔːrtɪŋ laɪn/', 'noun', '{"zh-TW":["匯報關係；匯報線"],"en":["the chain of authority defining who reports to whom in an organization"]}', NULL, 'clear reporting line / change the reporting line / reporting line structure', '[{"en":"His reporting line was changed after the reorganization.","zh-TW":"他的匯報關係在重組後發生了變化。"},{"en":"A clear reporting line prevents confusion about authority.","zh-TW":"清晰的匯報關係防止了對授權的混淆。"}]', NULL, NULL, 5, 5603, NULL),
(5604, 'repossession', '/''riːpəˌzeʃən/', 'noun', '{"zh-TW":["收回；沒收；取回"],"en":["the action of a creditor reclaiming possession of property when the owner defaults on payments"]}', NULL, 'face repossession / avoid repossession / repossession order', '[{"en":"The bank initiated repossession proceedings after twelve months of missed mortgage payments.","zh-TW":"銀行在十二個月的未付按揭款項後啟動了收回房產程序。"},{"en":"Seeking financial advice early can help homeowners avoid repossession.","zh-TW":"及早尋求財務建議可以幫助房主避免房產被收回。"}]', '{"verb":"repossess"}', NULL, 4, 5604, NULL),
(5605, 'represent', '/ˌrɛprɪˈzɛnt/', 'verb', '{"zh-TW":["代表；象徵"],"en":["to act or speak for someone; to symbolize"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"present","meaning":"present (呈現)"}}', 'represent the company / represent a change', '[{"en":"She represents the company at trade shows.","zh-TW":"她代表公司參加商展。"},{"en":"This represents a significant change in policy.","zh-TW":"這代表政策的重大改變。"}]', '{"noun":"representation, representative","adjective":"representative"}', NULL, 3, 5605, NULL),
(5606, 'representation', '/ˌreprɪzenˈteɪʃən/', 'noun', '{"zh-TW":["代表；陳述"],"en":["the action of speaking on behalf of someone; also a formal statement"]}', NULL, 'legal representation / seek representation / union representation', '[{"en":"All employees have the right to union representation.","zh-TW":"所有員工都有工會代表的權利。"},{"en":"She provided written representations to the regulatory committee.","zh-TW":"她向監管委員會提交了書面陳述。"}]', '{"verb":"represent","noun":"representative"}', NULL, 5, 5606, 616),
(5607, 'representative', 'ˌrɛprɪˈzɛntətɪv', 'noun', '{"zh-TW":["代表；代理人","業務員"],"en":["a person acting on behalf of another","a sales agent"]}', NULL, 'sales representative/customer representative', '[{"en":"Our sales representative will contact you.","zh-TW":"我們的銷售代表將與您聯繫。"}]', '{"verb":"represent","adjective":"representative","adverb":"representatively"}', NULL, 5, 5607, 440),
(5608, 'representative sample', '/ˌreprɪˈzentətɪv ˈsɑːmpəl/', 'noun', '{"zh-TW":["代表性樣本"],"en":["a sample reflecting the characteristics of the whole population"]}', NULL, 'draw a representative sample / ensure representative sample / large representative sample', '[{"en":"A representative sample is essential for results that can be generalized.","zh-TW":"代表性樣本對於可以推廣的結果至關重要。"},{"en":"The poll used a representative sample of five thousand voters.","zh-TW":"民調使用了五千名選民的代表性樣本。"}]', NULL, NULL, 5, 5608, NULL),
(5609, 'repudiate', '/rɪˈpjuːdieɪt/', 'verb', '{"zh-TW":["拒絕履行；否認；否定"],"en":["to refuse to accept or be associated with something; to refuse to fulfill an obligation"]}', NULL, 'repudiate a debt / repudiate a claim / repudiate a treaty', '[{"en":"The government repudiated the agreement, claiming it had been signed under duress.","zh-TW":"政府否認了該協議，聲稱它是在脅迫下簽署的。"},{"en":"The auditor repudiated the manipulated financial statements submitted by management.","zh-TW":"審計師否認了管理層提交的被操縱的財務報表。"}]', '{"noun":"repudiation","adjective":"repudiated"}', NULL, 3, 5609, NULL),
(5610, 'repurchase', '/riːˈpɜːrtʃəs/', 'verb', '{"zh-TW":["回購；買回"],"en":["to buy back something previously sold"]}', NULL, 'repurchase shares / repurchase agreement', '[{"en":"The company announced a plan to repurchase 10% of its shares.","zh-TW":"公司宣佈計劃回購10%的股份。"},{"en":"The repurchase agreement was settled within three days.","zh-TW":"回購協議在三天內結算。"}]', '{"noun":"repurchase","adjective":"repurchased"}', NULL, 4, 5610, NULL),
(5611, 'repurchase agreement', '/rɪˈpɜːrtʃɪs əˈɡriːmənt/', 'noun', '{"zh-TW":["回購協議"],"en":["a short-term borrowing arrangement where securities are sold and then repurchased"]}', NULL, 'enter a repurchase agreement / repurchase agreement rate', '[{"en":"The central bank uses repurchase agreements to manage short-term liquidity.","zh-TW":"中央銀行使用回購協議管理短期流動性。"},{"en":"Repurchase agreements are commonly used in money market operations.","zh-TW":"回購協議在貨幣市場操作中被廣泛使用。"}]', '{"abbreviation":"repo"}', NULL, 5, 5611, NULL),
(5612, 'reputation', '/ˌrɛpjuˈteɪʃən/', 'noun', '{"zh-TW":["聲譽；名譽"],"en":["the opinion people have about someone"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"put","meaning":"think (思考)"},"suffix":{"text":"-ation","meaning":"狀態"}}', 'good reputation / damage one''s reputation / build a reputation', '[{"en":"The company has an excellent reputation.","zh-TW":"公司享有卓越聲譽。"},{"en":"One mistake can damage your reputation.","zh-TW":"一個錯誤可以損害你的聲譽。"}]', '{"adjective":"reputable"}', NULL, 4, 5612, NULL),
(5613, 'reputation management', '/ˌrepjʊˈteɪʃən ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["聲譽管理"],"en":["protecting and improving a company''s public image"]}', NULL, 'online reputation management / crisis reputation management', '[{"en":"Reputation management became a priority after the incident.","zh-TW":"事件發生後，聲譽管理成為首要任務。"},{"en":"Social media has made reputation management more challenging.","zh-TW":"社群媒體使聲譽管理更具挑戰性。"}]', '{"verb":"manage reputation","adjective":"reputable"}', NULL, 5, 5613, NULL),
(5614, 'reputational risk', '/ˌrepjʊˈteɪʃənl rɪsk/', 'noun', '{"zh-TW":["聲譽風險"],"en":["the risk that negative perceptions will damage a company''s reputation"]}', NULL, 'manage reputational risk / reputational risk assessment', '[{"en":"A data breach creates significant reputational risk for the company.","zh-TW":"數據洩露對公司造成了重大聲譽風險。"},{"en":"Proactive crisis communication mitigates reputational risk.","zh-TW":"積極的危機溝通降低了聲譽風險。"}]', NULL, NULL, 5, 5614, NULL),
(5615, 'request', '/rɪˈkwɛst/', 'noun', '{"zh-TW":["請求；要求"],"en":["an act of asking for something"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quest","meaning":"seek (尋求)"}}', 'make a request / upon request / request for information', '[{"en":"We received a request for additional funding.","zh-TW":"我們收到了追加資金的請求。"},{"en":"Samples are available upon request.","zh-TW":"樣品可依要求提供。"}]', '{"verb":"request"}', NULL, 3, 5615, 202),
(5616, 'request for proposal', '/rɪˈkwest fɔːr prəˈpoʊzəl/', 'noun', '{"zh-TW":["提案邀請書；招標書"],"en":["a document inviting suppliers to submit proposals for a project"]}', NULL, 'issue a request for proposal / respond to a request for proposal', '[{"en":"The company issued a request for proposal for its new IT system.","zh-TW":"公司為其新IT系統發出了提案邀請書。"},{"en":"Suppliers had two weeks to respond to the request for proposal.","zh-TW":"供應商有兩週時間回應提案邀請書。"}]', '{"abbreviation":"RFP"}', NULL, 5, 5616, NULL),
(5617, 'request for quotation', '/rɪˈkwest fɔːr kwoʊˈteɪʃən/', 'noun', '{"zh-TW":["詢價書；報價請求"],"en":["a document sent to suppliers requesting a price for goods or services"]}', NULL, 'send a request for quotation / respond to a request for quotation', '[{"en":"The purchasing team sent a request for quotation to five vendors.","zh-TW":"採購團隊向五家供應商發送了詢價書。"},{"en":"Reviewing multiple quotations ensures competitive pricing.","zh-TW":"審查多份報價確保了有競爭力的定價。"}]', '{"abbreviation":"RFQ"}', NULL, 5, 5617, NULL),
(5618, 'require', '/rɪˈkwaɪər/', 'verb', '{"zh-TW":["需要；要求"],"en":["to need; to demand by rule"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quire","meaning":"seek (尋求)"}}', 'require approval / required by law / as required', '[{"en":"This position requires five years of experience.","zh-TW":"此職位需要五年經驗。"},{"en":"All visitors are required to sign in.","zh-TW":"所有訪客必須登記。"}]', '{"noun":"requirement","adjective":"required"}', NULL, 3, 5618, 55),
(5619, 'required', 'rɪˈkwaɪərd', 'adjective', '{"zh-TW":["必要的；規定的","必須的"],"en":["needed or demanded","obligatory"]}', NULL, 'required documents/required skills', '[{"en":"Please submit all required documents.","zh-TW":"請提交所有必要文件。"}]', '{"verb":"require","noun":"requirement"}', NULL, 3, 5619, NULL),
(5620, 'required rate of return', '/rɪˈkwaɪərd reɪt əv rɪˈtɜːrn/', 'noun', '{"zh-TW":["要求回報率"],"en":["the minimum return an investor expects before committing capital"]}', NULL, 'set a required rate of return / exceed the required rate of return', '[{"en":"The project was approved as its IRR exceeded the required rate of return.","zh-TW":"該項目獲得批准，因為其IRR超過了要求回報率。"},{"en":"The required rate of return reflects both risk and opportunity cost.","zh-TW":"要求回報率反映了風險和機會成本。"}]', NULL, NULL, 5, 5620, NULL),
(5621, 'requirement', 'rɪˈkwaɪərmənt', 'noun', '{"zh-TW":["要求；需求","條件"],"en":["something that is needed","a necessary condition"]}', NULL, 'meet requirements/list requirements', '[{"en":"Please review the project requirements.","zh-TW":"請查看專案要求。"}]', '{"verb":"require","adjective":"required"}', NULL, 4, 5621, 441),
(5622, 'reschedule', '/ˌriːˈʃedjuːl/', 'verb', '{"zh-TW":["重新安排時間；改期"],"en":["to arrange a new time for a meeting, event, or task"]}', NULL, 'reschedule a meeting / reschedule a delivery', '[{"en":"The client asked to reschedule the meeting to the following week.","zh-TW":"客戶要求將會議改期到下週。"},{"en":"We had to reschedule the product launch due to supply delays.","zh-TW":"由於供應延遲，我們不得不重新安排產品發布時間。"}]', '{"noun":"rescheduling"}', NULL, 4, 5622, NULL),
(5623, 'research', '/rɪˈsɜːrtʃ/', 'noun', '{"zh-TW":["研究；調查"],"en":["careful study of a subject"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"search","meaning":"search (搜索)"}}', 'conduct research / research and development / market research', '[{"en":"The company invests heavily in R&D.","zh-TW":"公司大量投資研發。"},{"en":"Further research is needed.","zh-TW":"需要進一步研究。"}]', '{"verb":"research","noun":"researcher"}', NULL, 3, 5623, 203),
(5624, 'research and development', '/rɪˈsɜːrtʃ ənd dɪˈveləpmənt/', 'noun', '{"zh-TW":["研究與開發"],"en":["activities undertaken to develop new products or improve existing ones"]}', NULL, 'invest in research and development / research and development budget', '[{"en":"The company allocated 10% of revenue to research and development.","zh-TW":"公司將10%的收入分配給研究與開發。"},{"en":"Strong research and development activity drives long-term innovation.","zh-TW":"強大的研究與開發活動推動了長期創新。"}]', '{"abbreviation":"R&D"}', NULL, 5, 5624, NULL),
(5625, 'research methodology', '/''rɪˌsɜːrtʃ meθəˌdɒlədʒi/', 'noun', '{"zh-TW":["研究方法論；研究方法"],"en":["the process used to collect data and information, including the theoretical framework"]}', NULL, 'explain research methodology / choose a research methodology / qualitative research methodology', '[{"en":"Her research methodology combined interviews with statistical analysis.","zh-TW":"她的研究方法論將訪談與統計分析相結合。"},{"en":"Selecting the right research methodology is critical for achieving valid results.","zh-TW":"選擇正確的研究方法論對於獲得有效結果至關重要。"}]', NULL, NULL, 5, 5625, NULL),
(5626, 'research paper', '/rɪˈsɜːrtʃ ˈpeɪpər/', 'noun', '{"zh-TW":["研究論文"],"en":["a written document presenting research findings"]}', NULL, 'write a research paper / publish a research paper', '[{"en":"She published a research paper in an international journal.","zh-TW":"她在國際期刊上發表了一篇研究論文。"},{"en":"The research paper must follow the APA citation format.","zh-TW":"研究論文必須遵循APA引用格式。"}]', NULL, NULL, 5, 5626, NULL),
(5627, 'reseller', '/riːˈselər/', 'noun', '{"zh-TW":["轉售商；經銷商"],"en":["a business that purchases products to resell them, often adding value"]}', NULL, 'authorized reseller / reseller agreement / reseller program', '[{"en":"The software company works with 300 authorized resellers worldwide.","zh-TW":"軟體公司在全球與300家授權經銷商合作。"},{"en":"Resellers often provide localized support and customization.","zh-TW":"轉售商通常提供本地化支援和客製化服務。"}]', '{"verb":"resell","plural":"resellers"}', NULL, 3, 5627, NULL),
(5628, 'reservation', '/ˌrɛzərˈveɪʃən/', 'noun', '{"zh-TW":["預訂","保留意見"],"en":["a booking","doubt or uncertainty"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serv","meaning":"keep (保持)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'make a reservation / have reservations about / without reservation', '[{"en":"I''d like to make a reservation for two.","zh-TW":"我想預訂兩人座。"},{"en":"I have some reservations about the plan.","zh-TW":"我對計劃有些保留意見。"}]', '{"verb":"reserve"}', NULL, 4, 5628, 56),
(5629, 'reserve', '/rɪˈzɜːrv/', 'verb', '{"zh-TW":["預訂；保留"],"en":["to book; to keep for later use"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serve","meaning":"keep (保持)"}}', 'reserve a room / cash reserves / reserve the right', '[{"en":"Please reserve a conference room.","zh-TW":"請預訂一間會議室。"},{"en":"We reserve the right to cancel.","zh-TW":"我們保留取消的權利。"}]', '{"noun":"reserve, reservation","adjective":"reserved"}', NULL, 3, 5629, 204),
(5630, 'reserve ratio', '/rɪˈzɜːrv ˈreɪʃioʊ/', 'noun', '{"zh-TW":["準備金比率"],"en":["the fraction of deposits a bank must hold in reserve and not lend out"]}', NULL, 'maintain reserve ratio / increase the reserve ratio', '[{"en":"The central bank raised the reserve ratio to reduce money supply.","zh-TW":"中央銀行提高了準備金比率以減少貨幣供給。"},{"en":"A lower reserve ratio allows banks to lend more and stimulate growth.","zh-TW":"較低的準備金比率允許銀行多放貸並刺激增長。"}]', NULL, NULL, 5, 5630, NULL),
(5631, 'reserve requirement', '/rɪˈzɜːrv rɪˈkwaɪərmənt/', 'noun', '{"zh-TW":["儲備金要求；準備金規定"],"en":["the minimum cash reserves a bank must hold as required by regulations"]}', NULL, 'comply with reserve requirements / reduce reserve requirements', '[{"en":"Banks adjust lending based on the central bank''s reserve requirements.","zh-TW":"銀行根據中央銀行的準備金規定調整貸款。"},{"en":"Reserve requirements act as a buffer against bank runs.","zh-TW":"準備金規定作為應對銀行擠兌的緩衝。"}]', NULL, NULL, 5, 5631, NULL),
(5632, 'reserves', '/rɪˈzɜːrvz/', 'noun', '{"zh-TW":["儲備金；準備金"],"en":["retained earnings or funds set aside for future needs or contingencies"]}', NULL, 'build up reserves / draw on reserves', '[{"en":"The company built up reserves to fund future expansion.","zh-TW":"公司積累了儲備金以資助未來的擴張。"},{"en":"Reserves provide a buffer against unexpected losses or economic downturns.","zh-TW":"儲備金在意外損失或經濟下滑時提供了緩衝。"}]', NULL, NULL, 3, 5632, NULL),
(5633, 'reside', '/rɪˈzaɪd/', 'verb', '{"zh-TW":["居住"],"en":["to live in a place"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"side","meaning":"sit (坐)"}}', 'reside in / place of residence', '[{"en":"She resides in Tokyo.","zh-TW":"她居住在東京。"},{"en":"Please provide your place of residence.","zh-TW":"請提供您的居住地。"}]', '{"noun":"residence, resident, residency","adjective":"residential"}', NULL, 2, 5633, NULL),
(5634, 'residential district', '/''rezɪdenʃəl ˌdɪstrɪkt/', 'noun', '{"zh-TW":["住宅區；住宅地段"],"en":["an area of a town or city designed primarily for housing"]}', NULL, 'live in a residential district / quiet residential district / upscale residential district', '[{"en":"The school is located in a quiet residential district close to public transportation.","zh-TW":"學校位於靠近公共交通的安靜住宅區。"},{"en":"New supermarkets opened in the residential district to serve the growing population.","zh-TW":"新的超市在住宅區開業，為不斷增長的人口提供服務。"}]', NULL, NULL, 5, 5634, NULL),
(5635, 'residual', '/rɪˈzɪdjuəl/', 'adjective', '{"zh-TW":["剩餘的；殘差的"],"en":["remaining after the greater part has been used or removed"]}', NULL, 'residual value / residual income / residual risk', '[{"en":"The residual value of the leased vehicle was set at 30%.","zh-TW":"租賃車輛的剩餘價值設定為30%。"},{"en":"Residual risk remains even after all mitigation measures are applied.","zh-TW":"即使採取了所有緩解措施後，殘餘風險仍然存在。"}]', '{"noun":"residual","adverb":"residually"}', NULL, 3, 5635, 925),
(5636, 'residual value', '/rɪˈzɪdjʊəl ˈvæljuː/', 'noun', '{"zh-TW":["殘值；剩餘價值"],"en":["the estimated value of an asset at the end of its useful life"]}', NULL, 'estimate residual value / factor in residual value', '[{"en":"The residual value of leased vehicles was estimated at 30%.","zh-TW":"租賃車輛的殘值估計為30%。"},{"en":"A higher residual value reduces depreciation charges.","zh-TW":"較高的殘值降低了折舊費用。"}]', NULL, NULL, 5, 5636, NULL),
(5637, 'resign', '/rɪˈzaɪn/', 'verb', '{"zh-TW":["辭職"],"en":["to voluntarily leave a job"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"sign","meaning":"sign (簽署)"}}', 'resign from / letter of resignation / resign as', '[{"en":"He resigned from his position as CEO.","zh-TW":"他辭去了執行長一職。"},{"en":"Please submit your resignation in writing.","zh-TW":"請以書面形式提交辭呈。"}]', '{"noun":"resignation"}', NULL, 2, 5637, 205),
(5638, 'resignation', '/ˌrezɪɡˈneɪʃən/', 'noun', '{"zh-TW":["辭職；辭呈"],"en":["the act of voluntarily leaving a job"]}', NULL, 'submit a resignation / letter of resignation / accept a resignation', '[{"en":"She submitted her resignation after accepting a better offer.","zh-TW":"她在接受更好的工作機會後提交了辭呈。"},{"en":"The CEO''s resignation surprised the entire board.","zh-TW":"執行長的辭職讓整個董事會感到驚訝。"}]', '{"verb":"resign","adjective":"resigned"}', NULL, 4, 5638, NULL),
(5639, 'resilience', '/rɪˈzɪliəns/', 'noun', '{"zh-TW":["恢復力；韌性"],"en":["the capacity to recover quickly from difficulties"]}', NULL, 'build resilience / community resilience / resilience against climate change', '[{"en":"Communities with strong social networks show greater resilience after disasters.","zh-TW":"擁有強大社會網絡的社區在災難後表現出更強的恢復力。"},{"en":"Biodiversity contributes to the resilience of ecosystems under stress.","zh-TW":"生物多樣性有助於生態系統在壓力下的恢復力。"}]', '{"adjective":"resilient","adverb":"resiliently"}', NULL, 4, 5639, NULL),
(5640, 'resilience building', '/''rɪˈzɪliəns ˌbɪldɪŋ/', 'noun', '{"zh-TW":["韌性培養；復原力建立"],"en":["the process of developing the ability to recover from difficulties or adapt to change"]}', NULL, 'resilience building program / focus on resilience building / benefit of resilience building', '[{"en":"The organization invested in resilience building programs to help staff cope with pressure.","zh-TW":"組織投資了韌性培養計劃，幫助員工應對壓力。"},{"en":"Resilience building is a key focus of modern leadership development training.","zh-TW":"韌性培養是現代領導力發展培訓的核心重點。"}]', '{"noun":"resilience"}', NULL, 5, 5640, NULL),
(5641, 'resilient', '/''rɪˈzɪliənt/', 'adjective', '{"zh-TW":["有韌性的；適應力強的"],"en":["able to withstand or recover quickly from difficult conditions"]}', NULL, 'resilient economy / resilient team / resilient mindset', '[{"en":"She demonstrated resilient leadership during the company''s financial crisis.","zh-TW":"她在公司財務危機期間展示了有韌性的領導力。"},{"en":"Building resilient supply chains is essential to handle unexpected disruptions.","zh-TW":"建立有韌性的供應鏈對於應對意外中斷至關重要。"}]', '{"noun":"resilience","adverb":"resiliently"}', NULL, 3, 5641, NULL),
(5642, 'resilient ecosystem', '/rɪˈzɪliənt ˈiːkəʊˌsɪstəm/', 'noun', '{"zh-TW":["有韌性的生態系統"],"en":["an ecosystem capable of absorbing disturbance and recovering quickly"]}', NULL, 'build resilient ecosystems / protect resilient ecosystems / resilient ecosystem services', '[{"en":"Diverse plant communities create resilient ecosystems that withstand drought.","zh-TW":"多樣化的植物群落創造了能夠抵抗乾旱的有韌性的生態系統。"},{"en":"Restoring soil biodiversity makes agricultural systems more resilient.","zh-TW":"恢復土壤生物多樣性使農業系統更具韌性。"}]', NULL, NULL, 5, 5642, NULL),
(5643, 'resilient infrastructure', '/rɪˈzɪliənt ˈɪnfrəstrʌktʃər/', 'noun', '{"zh-TW":["韌性基礎設施"],"en":["infrastructure designed to withstand and recover from disruptions"]}', NULL, 'build resilient infrastructure / invest in resilient infrastructure / resilient infrastructure standards', '[{"en":"Resilient infrastructure withstands climate extremes and rapid recovery.","zh-TW":"韌性基礎設施能夠承受極端氣候並快速恢復。"},{"en":"The city''s resilient infrastructure plan includes flood barriers and redundant power grids.","zh-TW":"城市的韌性基礎設施計畫包括防洪屏障和冗餘電網。"}]', NULL, NULL, 5, 5643, NULL),
(5644, 'resist', '/rɪˈzɪst/', 'verb', '{"zh-TW":["抵抗；抵制"],"en":["to oppose or fight against"]}', '{"prefix":{"text":"re-","meaning":"against"},"root":{"text":"sist","meaning":"stand (站立)"}}', 'resist change / resist pressure / hard to resist', '[{"en":"Many employees resist organizational change.","zh-TW":"許多員工抵制組織變革。"},{"en":"The offer was hard to resist.","zh-TW":"這個提議很難拒絕。"}]', '{"noun":"resistance","adjective":"resistant"}', NULL, 2, 5644, NULL),
(5645, 'resistance band', '/''rɪˌzɪstəns bænd/', 'noun', '{"zh-TW":["彈力帶；阻力帶"],"en":["a stretchable band used as an exercise tool to provide resistance for strength training"]}', NULL, 'use a resistance band / resistance band exercise / resistance band workout', '[{"en":"Resistance bands are versatile and effective tools for building strength without weights.","zh-TW":"彈力帶是無需啞鈴就能增強力量的多功能有效工具。"},{"en":"Physical therapists often use resistance bands in rehabilitation exercises.","zh-TW":"物理治療師通常在康復練習中使用彈力帶。"}]', '{"noun":"resistance"}', NULL, 5, 5645, NULL),
(5646, 'resolution', '/ˌrɛzəˈluːʃən/', 'noun', '{"zh-TW":["解決；決議"],"en":["the action of solving a problem or dispute"]}', NULL, 'conflict resolution / quick resolution', '[{"en":"The customer was pleased with the quick resolution of her issue.","zh-TW":"顧客對她的問題得到迅速解決感到滿意。"},{"en":"Resolution of the dispute took three weeks of negotiation.","zh-TW":"爭議的解決花了三週的談判時間。"}]', '{"verb":"resolve","adjective":"resolved"}', NULL, 4, 5646, 442),
(5647, 'resolve', '/rɪˈzɒlv/', 'verb', '{"zh-TW":["解決；決心","解決；決定"],"en":["to find a solution to a problem","to decide firmly","to find a solution; to decide firmly"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"solve","meaning":"loosen (鬆開)"},"logic":"再次鬆開（解開問題），即「解決」。"}', 'resolve a conflict / resolve an issue / resolve to; resolve an issue / resolve a dispute / resolve to do', '[{"en":"We need to resolve this issue quickly.","zh-TW":"我們需要快速解決這個問題。"},{"en":"She resolved to study harder.","zh-TW":"她決心更用功讀書。"},{"en":"We need to resolve this issue immediately.","zh-TW":"我們需要立即解決這問題。"},{"en":"The dispute was resolved through mediation.","zh-TW":"糾紛通過調解解決了。"}]', '{"noun":"resolution","adjective":"resolute"}', NULL, 3, 5647, 57),
(5648, 'resort', '/rɪˈzɔːrt/', 'noun', '{"zh-TW":["度假村","手段"],"en":["a vacation place","a course of action"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"sort","meaning":"go out (出去)"}}', 'as a last resort / resort to / tourist resort', '[{"en":"We should use legal action as a last resort.","zh-TW":"我們應將法律行動作為最後手段。"},{"en":"The conference was held at a beach resort.","zh-TW":"會議在海灘度假村舉行。"}]', '{"verb":"resort"}', NULL, 2, 5648, NULL),
(5649, 'resort fee', '/rɪˈzɔːrt fiː/', 'noun', '{"zh-TW":["度假村服務費"],"en":["an additional fee charged at a resort for amenities"]}', NULL, 'resort fee included / mandatory resort fee', '[{"en":"A daily resort fee covers access to the gym and pool.","zh-TW":"每日度假村服務費包含使用健身房和游泳池的費用。"},{"en":"The resort fee was not disclosed at the time of booking.","zh-TW":"度假村服務費在預訂時未予披露。"}]', NULL, NULL, 4, 5649, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5650, 'resource', '/rɪˈsɔːrs/', 'noun', '{"zh-TW":["資源"],"en":["a supply that can be used"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"source","meaning":"rise (升起)"}}', 'human resources / natural resources / allocate resources', '[{"en":"We need to allocate resources more efficiently.","zh-TW":"我們需要更有效地分配資源。"},{"en":"Human resources handles employee matters.","zh-TW":"人力資源部處理員工事務。"}]', '{"adjective":"resourceful","verb":"resource"}', NULL, 3, 5650, 206),
(5651, 'resource allocation', '/ˈriːsɔːrs ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["資源分配"],"en":["the process of assigning available resources to tasks or projects"]}', NULL, 'effective resource allocation / resource allocation plan', '[{"en":"Resource allocation was reviewed to align with the new priorities.","zh-TW":"資源分配根據新的優先事項進行了審查。"},{"en":"Poor resource allocation led to delays on three critical projects.","zh-TW":"資源分配不當導致三個關鍵項目延誤。"}]', '{"verb":"allocate resources"}', NULL, 5, 5651, NULL),
(5652, 'resource allocation plan', '/rɪˈsɔːrs ˌæləˈkeɪʃən plæn/', 'noun', '{"zh-TW":["資源分配計劃"],"en":["a plan specifying how resources will be assigned across projects or activities"]}', NULL, 'create a resource allocation plan / review the resource allocation plan', '[{"en":"The resource allocation plan was approved by the steering committee.","zh-TW":"資源分配計劃獲得了指導委員會的批准。"},{"en":"An accurate resource allocation plan prevents bottlenecks.","zh-TW":"準確的資源分配計劃可防止瓶頸。"}]', NULL, NULL, 5, 5652, NULL),
(5653, 'resource planning', '/ˈriːsɔːrs ˈplænɪŋ/', 'noun', '{"zh-TW":["資源規劃"],"en":["identifying and allocating resources needed to complete a project"]}', NULL, 'resource planning process / resource planning tool / effective resource planning', '[{"en":"Resource planning ensured the team had the right skills at each phase.","zh-TW":"資源規劃確保了團隊在每個階段都具備正確的技能。"},{"en":"Poor resource planning caused delays in the critical path.","zh-TW":"糟糕的資源規劃導致了關鍵路徑上的延遲。"}]', NULL, NULL, 5, 5653, NULL),
(5654, 'resource utilization', '/rɪˈsɔːrs ˌjuːtɪlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["資源利用率"],"en":["the extent to which available resources are being productively used"]}', NULL, 'monitor resource utilization / improve resource utilization', '[{"en":"High resource utilization means fewer idle assets and better returns.","zh-TW":"高資源利用率意味著更少的閒置資產和更好的回報。"},{"en":"Resource utilization reports help managers plan workloads efficiently.","zh-TW":"資源利用率報告幫助管理者有效地規劃工作量。"}]', NULL, NULL, 5, 5654, NULL),
(5655, 'respond', '/rɪˈspɒnd/', 'verb', '{"zh-TW":["回應；回覆"],"en":["to reply; to react"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"spond","meaning":"promise (承諾)"}}', 'respond to / respond quickly / respond in writing', '[{"en":"Please respond to the email by Friday.","zh-TW":"請於週五前回覆郵件。"},{"en":"The company responded quickly to the crisis.","zh-TW":"公司迅速回應了危機。"}]', '{"noun":"response, respondent","adjective":"responsive"}', NULL, 3, 5655, NULL),
(5656, 'response', 'rɪˈspɒns', 'noun', '{"zh-TW":["回應；答覆","響應"],"en":["an answer or reaction","something said or done in reply"]}', NULL, 'prompt response/in response to', '[{"en":"Thank you for your prompt response.","zh-TW":"感謝您的及時回應。"}]', '{"verb":"respond","adjective":"responsive","adverb":"responsively"}', NULL, 3, 5656, 58),
(5657, 'response time', '/rɪˈspɒns taɪm/', 'noun', '{"zh-TW":["回應時間"],"en":["the time taken to reply to a request or query"]}', NULL, 'reduce response time / average response time / response time SLA', '[{"en":"The help desk targets a two-hour response time for all tickets.","zh-TW":"服務台的目標是對所有工單在兩小時內回應。"},{"en":"Faster response times significantly improve customer experience.","zh-TW":"更快的回應時間顯著改善了客戶體驗。"}]', NULL, NULL, 5, 5657, NULL),
(5658, 'responsibility', 'rɪˌspɒnsɪˈbɪlɪti', 'noun', '{"zh-TW":["責任；職責","義務"],"en":["a duty to do something","something you are in charge of"]}', NULL, 'take responsibility/social responsibility', '[{"en":"Each team member has clear responsibilities.","zh-TW":"每個團隊成員都有明確的職責。"}]', '{"adjective":"responsible","adverb":"responsibly"}', NULL, 5, 5658, 617),
(5659, 'responsible', 'rɪˈspɒnsɪbəl', 'adjective', '{"zh-TW":["負責任的；可靠的","應負責的"],"en":["having a duty to do something","trustworthy"]}', NULL, 'responsible for/responsible person', '[{"en":"Who is responsible for this project?","zh-TW":"誰負責這個專案？"}]', '{"noun":"responsibility","adverb":"responsibly"}', NULL, 4, 5659, 59),
(5660, 'responsible tourism', '/rɪˈspɒnsɪbəl ˈtʊərɪzəm/', 'noun', '{"zh-TW":["負責任旅遊"],"en":["tourism that minimizes negative environmental and cultural impact"]}', NULL, 'practice responsible tourism / responsible tourism principles', '[{"en":"Responsible tourism benefits local communities and ecosystems.","zh-TW":"負責任旅遊有益於當地社區和生態系統。"},{"en":"Choose eco-certified hotels as part of responsible tourism.","zh-TW":"選擇具有環保認證的飯店作為負責任旅遊的一部分。"}]', NULL, NULL, 5, 5660, NULL),
(5661, 'rest', '/rɛst/', 'noun', '{"zh-TW":["休息；其餘的"],"en":["a period of relaxing","the remaining part"]}', NULL, 'the rest of / get some rest', '[{"en":"I will handle the rest of the tasks.","zh-TW":"我會處理剩下的任務。"},{"en":"Get some rest before the trip.","zh-TW":"出差前好好休息。"}]', '{"noun":"rest","verb":"rest","adjective":"restful","adjective2":"restless"}', NULL, 1, 5661, NULL),
(5662, 'restated financial', '/rɪˈsteɪtɪd faɪˈnænʃəl/', 'adjective', '{"zh-TW":["經重新申報的財務"],"en":["previously published financial results that have been corrected"]}', NULL, 'restated financial results / restated earnings', '[{"en":"The restated financial results showed lower profits than originally reported.","zh-TW":"經重新申報的財務結果顯示利潤低於原始報告。"},{"en":"An error in accounting led to restated financial statements.","zh-TW":"會計錯誤導致了財務報表的重新申報。"}]', '{"verb":"restate","noun":"restatement"}', NULL, 5, 5662, NULL),
(5663, 'resting heart rate', '/''restɪŋ hɑːrt reɪt/', 'noun', '{"zh-TW":["靜息心率"],"en":["the number of times the heart beats per minute while the body is at rest"]}', NULL, 'measure resting heart rate / lower resting heart rate / monitor resting heart rate', '[{"en":"A lower resting heart rate generally indicates better cardiovascular fitness.","zh-TW":"較低的靜息心率通常表示更好的心血管健康。"},{"en":"Regular aerobic exercise is one of the most effective ways to lower your resting heart rate.","zh-TW":"定期有氧運動是降低靜息心率最有效的方法之一。"}]', '{"noun":"heart rate"}', NULL, 5, 5663, NULL),
(5664, 'restitution', '/ˌrestɪˈtjuːʃən/', 'noun', '{"zh-TW":["賠償；歸還"],"en":["the restoration of something lost or stolen; compensation for loss"]}', NULL, 'order restitution / pay restitution / criminal restitution', '[{"en":"The judge ordered the defendant to pay restitution to the victims.","zh-TW":"法官命令被告向受害者支付賠償金。"},{"en":"Restitution aims to restore the victim to their original position.","zh-TW":"賠償旨在將受害者恢復到原來的狀況。"}]', '{"verb":"restore","adjective":"restorative"}', NULL, 4, 5664, NULL),
(5665, 'restoration', '/ˌrestəˈreɪʃn/', 'noun', '{"zh-TW":["修復；恢復"],"en":["the act of returning something to its original condition"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"stor","meaning":"set up (建立)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"重新建立的過程，即「修復」。"}', 'art restoration / building restoration', '[{"en":"The restoration of the painting took three years.","zh-TW":"這幅畫的修復花了三年。"},{"en":"The old building underwent a complete restoration.","zh-TW":"這棟老建築進行了全面修復。"}]', '{"verb":"restore"}', NULL, 4, 5665, NULL),
(5666, 'restore', '/rɪˈstɔːr/', 'verb', '{"zh-TW":["恢復；修復"],"en":["to bring back to a former condition"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"store","meaning":"build (建造)"}}', 'restore confidence / restore service / restore to', '[{"en":"We aim to restore customer confidence.","zh-TW":"我們旨在恢復客戶信心。"},{"en":"Service has been fully restored.","zh-TW":"服務已完全恢復。"}]', '{"noun":"restoration"}', NULL, 3, 5666, 926),
(5667, 'restrict', '/rɪˈstrɪkt/', 'verb', '{"zh-TW":["限制；約束"],"en":["to put a limit on"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"strict","meaning":"draw tight (拉緊)"}}', 'restrict access / restrict spending / restricted area', '[{"en":"Access is restricted to authorized personnel.","zh-TW":"僅限授權人員進入。"},{"en":"The budget restricts our spending options.","zh-TW":"預算限制了我們的開支選項。"}]', '{"noun":"restriction","adjective":"restrictive, restricted"}', NULL, 3, 5667, NULL),
(5668, 'restructure', '/ˌriːˈstrʌktʃər/', 'verb', '{"zh-TW":["重組；改組"],"en":["to organize differently"]}', NULL, 'restructure debt / corporate restructuring', '[{"en":"The company plans to restructure its divisions.","zh-TW":"公司計畫重組其部門。"},{"en":"Debt restructuring saved the business.","zh-TW":"債務重組拯救了這家企業。"}]', '{"verb":"restructure","noun":"restructuring"}', NULL, 4, 5668, 717),
(5669, 'restructuring', '/riːˈstrʌktʃərɪŋ/', 'noun', '{"zh-TW":["重組；改組"],"en":["reorganizing a company''s structure, operations, or finances"]}', NULL, 'corporate restructuring / debt restructuring', '[{"en":"The restructuring plan will eliminate 500 jobs.","zh-TW":"重組計劃將裁減500個職位。"},{"en":"Debt restructuring gave the firm a fresh start.","zh-TW":"債務重組給公司提供了重新開始的機會。"}]', '{"verb":"restructure","adjective":"restructured"}', NULL, 5, 5669, 618),
(5670, 'restructuring charge', '/riːˈstrʌktʃərɪŋ tʃɑːrdʒ/', 'noun', '{"zh-TW":["重組費用"],"en":["a one-time expense recorded when reorganizing a company"]}', NULL, 'recognize a restructuring charge / one-off restructuring charge', '[{"en":"The company recorded a 50 million restructuring charge for the layoffs.","zh-TW":"公司為裁員記錄了5000萬元的重組費用。"},{"en":"Restructuring charges were excluded from the adjusted profit figures.","zh-TW":"重組費用從調整後的利潤數字中排除了。"}]', NULL, NULL, 5, 5670, NULL),
(5671, 'restructuring plan', '/riːˈstrʌktʃərɪŋ plæn/', 'noun', '{"zh-TW":["重組計劃"],"en":["a documented strategy for reorganizing a company to improve performance"]}', NULL, 'implement a restructuring plan / restructuring plan announcement', '[{"en":"The board approved a three-year restructuring plan to cut costs.","zh-TW":"董事會批准了為期三年的降成本重組計劃。"},{"en":"A successful restructuring plan can restore profitability.","zh-TW":"成功的重組計劃可以恢復盈利能力。"}]', NULL, NULL, 5, 5671, NULL),
(5672, 'result', '/rɪˈzʌlt/', 'noun', '{"zh-TW":["結果"],"en":["an outcome; a consequence"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"sult","meaning":"jump (跳)"}}', 'as a result / achieve results / result in', '[{"en":"As a result of the merger, profits increased.","zh-TW":"合併的結果是利潤增加了。"},{"en":"The campaign resulted in higher sales.","zh-TW":"活動帶來了更高的銷售額。"}]', '{"verb":"result","adjective":"resulting, resultant"}', NULL, 2, 5672, 444),
(5673, 'results-oriented', 'rɪˈzʌlts ˈɔːriɛntɪd', 'adjective', '{"zh-TW":["以結果為導向的；注重成效的","目標明確的"],"en":["focused on achieving outcomes","driven by results"]}', NULL, 'results-oriented culture/results-oriented manager', '[{"en":"We foster a results-oriented culture.","zh-TW":"我們培育以結果為導向的文化。"}]', NULL, NULL, 5, 5673, NULL),
(5674, 'resume', '/rɪˈzjuːm/', 'verb', '{"zh-TW":["恢復；繼續"],"en":["to begin again after a pause"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"sume","meaning":"take (拿)"}}', 'resume work / resume operations / resume negotiations', '[{"en":"Operations will resume on Monday.","zh-TW":"營運將於週一恢復。"},{"en":"Talks are expected to resume next week.","zh-TW":"會談預計下週恢復。"}]', '{"noun":"resumption"}', NULL, 2, 5674, NULL),
(5675, 'retail', '/ˈriːteɪl/', 'noun', '{"zh-TW":["零售"],"en":["the sale of goods to the public in small quantities","the sale of goods to the public"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"tail","meaning":"cut (切割)"},"logic":"再次切割分售，即「零售」。"}', 'retail price / retail store / retail industry', '[{"en":"The retail price is higher than the wholesale price.","zh-TW":"零售價比批發價高。"},{"en":"She has years of experience in retail.","zh-TW":"她有多年零售業經驗。"},{"en":"The retail price is $49.99.","zh-TW":"零售價為49.99美元。"},{"en":"She has 10 years of retail experience.","zh-TW":"她有十年零售經驗。"}]', '{"noun":"retailer","verb":"retail"}', NULL, 2, 5675, 445),
(5676, 'retail price', '/ˈriːteɪl praɪs/', 'noun', '{"zh-TW":["零售價"],"en":["the price at which goods are sold to the public"]}', NULL, 'suggest retail price / retail price comparison', '[{"en":"The manufacturer suggested retail price is 99 dollars.","zh-TW":"製造商建議的零售價為99元。"},{"en":"Online retailers often undercut the recommended retail price.","zh-TW":"線上零售商通常低於建議零售價銷售。"}]', NULL, NULL, 4, 5676, NULL),
(5677, 'retain', '/rɪˈteɪn/', 'verb', '{"zh-TW":["保留；留住","保持；留住"],"en":["to keep; to continue to have","to continue to have; to keep"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"tain","meaning":"hold (持有)"}}', 'retain customers / retain employees / retain the right; retain customers / retain knowledge / retention rate', '[{"en":"The company strives to retain top talent.","zh-TW":"公司努力留住頂尖人才。"},{"en":"We retain the right to modify terms.","zh-TW":"我們保留修改條款的權利。"},{"en":"Customer retention is a key metric.","zh-TW":"客戶留存率是關鍵指標。"},{"en":"How do we retain skilled workers?","zh-TW":"我們如何留住熟練工人？"}]', '{"noun":"retention","adjective":"retentive"}', NULL, 2, 5677, 207),
(5678, 'retained earnings', '/rɪˈteɪnd ˈɜːrnɪŋz/', 'noun', '{"zh-TW":["保留盈餘；留存收益"],"en":["profits kept by the company rather than paid out as dividends"]}', NULL, 'reinvest retained earnings / retained earnings account', '[{"en":"Retained earnings fund future expansion without new debt.","zh-TW":"保留盈餘為未來擴張提供資金，無需新增債務。"},{"en":"The balance sheet showed $30 million in retained earnings.","zh-TW":"資產負債表顯示保留盈餘為3000萬美元。"}]', NULL, NULL, 5, 5678, NULL),
(5679, 'retention', 'rɪˈtɛnʃən', 'noun', '{"zh-TW":["留住；保留","記憶"],"en":["keeping employees or customers","the ability to retain"]}', NULL, 'employee retention/customer retention', '[{"en":"Improving retention is a top priority.","zh-TW":"提高留存率是首要任務。"}]', '{"verb":"retain","adjective":"retained"}', NULL, 3, 5679, 446),
(5680, 'retention rate', '/rɪˈtenʃən reɪt/', 'noun', '{"zh-TW":["留存率；客戶保留率"],"en":["the percentage of customers or employees retained over a period"]}', NULL, 'improve retention rate / customer retention rate / employee retention rate', '[{"en":"Improving the user interface increased retention rate by 15%.","zh-TW":"改善用戶介面使留存率提高了15%。"},{"en":"High employee retention rates reflect strong company culture.","zh-TW":"高員工留存率反映了強大的公司文化。"}]', '{"verb":"retain"}', NULL, 5, 5680, NULL),
(5681, 'retention strategy', '/rɪˈtenʃən ˈstrætɪdʒi/', 'noun', '{"zh-TW":["留存策略；保留策略"],"en":["a plan designed to keep customers or employees engaged and loyal"]}', NULL, 'develop a retention strategy / customer retention strategy', '[{"en":"A loyalty program is a key part of the customer retention strategy.","zh-TW":"忠誠度計劃是客戶留存策略的重要組成部分。"},{"en":"The retention strategy reduced employee turnover by 20%.","zh-TW":"留存策略將員工離職率降低了20%。"}]', NULL, NULL, 5, 5681, NULL),
(5682, 'reticent', '/''retɪsənt/', 'adjective', '{"zh-TW":["沉默寡言的；不願表達的"],"en":["not revealing one''s thoughts or feelings readily; reserved"]}', NULL, 'reticent personality / remain reticent / reticent about sharing', '[{"en":"He was reticent about his personal life and rarely discussed it at work.","zh-TW":"他對個人生活保持沉默，在工作中很少談及。"},{"en":"She was normally outgoing but became reticent whenever the topic turned to her past.","zh-TW":"她通常很外向，但話題一轉到她的過去時就變得沉默寡言。"}]', '{"adverb":"reticently","noun":"reticence"}', NULL, 3, 5682, NULL),
(5683, 'retire', '/rɪˈtaɪər/', 'verb', '{"zh-TW":["退休"],"en":["to stop working due to age"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"tire","meaning":"draw (拉)"}}', 'retire from / retirement age / retire early', '[{"en":"She plans to retire at 60.","zh-TW":"她計劃60歲退休。"},{"en":"He retired from the company after 30 years.","zh-TW":"他在公司工作30年後退休。"}]', '{"noun":"retirement, retiree","adjective":"retired"}', NULL, 2, 5683, NULL),
(5684, 'retreat', '/''rɪˈtriːt/', 'noun', '{"zh-TW":["靜修所；避靜；退修處"],"en":["a quiet or secluded place for rest or seclusion; a period spent in this way"]}', NULL, 'yoga retreat / meditation retreat / weekend retreat', '[{"en":"The wellness retreat offered yoga, meditation, and organic meals.","zh-TW":"這個健康靜修所提供瑜伽、冥想和有機餐食。"},{"en":"She attended a writing retreat in the mountains to complete her novel.","zh-TW":"她參加了山區的寫作退修活動，以完成她的小說。"}]', NULL, NULL, 3, 5684, NULL),
(5685, 'retrenchment', '/rɪˈtrentʃmənt/', 'noun', '{"zh-TW":["緊縮；削減；裁員"],"en":["the cutting of expenditure; a reduction in the size of a workforce"]}', NULL, 'economic retrenchment / corporate retrenchment / period of retrenchment', '[{"en":"Corporate retrenchment reduced operating costs but lowered employee morale.","zh-TW":"企業緊縮降低了運營成本，但降低了員工士氣。"},{"en":"The government''s fiscal retrenchment included cuts to public services and welfare programs.","zh-TW":"政府的財政緊縮包括削減公共服務和福利計畫。"}]', '{"verb":"retrench","adjective":"retrenched"}', NULL, 4, 5685, NULL),
(5686, 'retrieve', '/rɪˈtriːv/', 'verb', '{"zh-TW":["取回；檢索","取回"],"en":["to get back; to find and bring back","to get something back"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"trieve","meaning":"find (找到)"}}', 'retrieve data / retrieve information / retrieve from; retrieve data / retrieve information / information retrieval', '[{"en":"We can retrieve the deleted files.","zh-TW":"我們可以檢索已刪除的文件。"},{"en":"The system retrieves data automatically.","zh-TW":"系統自動檢索數據。"},{"en":"The system can retrieve archived records.","zh-TW":"系統可以檢索存檔記錄。"},{"en":"Click here to retrieve your password.","zh-TW":"點擊此處找回密碼。"}]', '{"noun":"retrieval"}', NULL, 3, 5686, NULL),
(5687, 'retrospective', '/ˌretrəˈspektɪv/', 'noun', '{"zh-TW":["回顧會議；回顧"],"en":["a meeting where a team reflects on past work to improve future performance"]}', NULL, 'run a retrospective / sprint retrospective / agile retrospective', '[{"en":"The retrospective highlighted that daily standups improved team sync.","zh-TW":"回顧會議強調每日站立會議改善了團隊同步。"},{"en":"Retrospectives are a core ceremony in agile development.","zh-TW":"回顧是敏捷開發的核心儀式。"}]', '{"adjective":"retrospective"}', NULL, 5, 5687, NULL),
(5688, 'return', '/rɪˈtɜːrn/', 'verb', '{"zh-TW":["返回；歸還","回報"],"en":["to come or go back","to give back","profit"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"turn","meaning":"turn (轉)"}}', 'return on investment / return a call / return policy', '[{"en":"The return on investment exceeded expectations.","zh-TW":"投資回報超出預期。"},{"en":"Please return the signed contract.","zh-TW":"請歸還已簽署的合約。"}]', '{"noun":"return"}', NULL, 2, 5688, NULL),
(5689, 'return merchandise authorization', '/rɪˈtɜːrn ˈmɜːrtʃəndaɪz ˌɔːθərɪˈzeɪʃən/', 'noun', '{"zh-TW":["退貨授權"],"en":["an approval for a customer to return a product for a refund or replacement"]}', NULL, 'issue a return merchandise authorization / return merchandise authorization number', '[{"en":"Customers need a return merchandise authorization number to send items back.","zh-TW":"客戶需要退貨授權號碼才能退回商品。"},{"en":"The return merchandise authorization was processed within 24 hours.","zh-TW":"退貨授權在24小時內完成了處理。"}]', '{"abbreviation":"RMA"}', NULL, 5, 5689, NULL),
(5690, 'return on assets', '/rɪˈtɜːrn ɒn ˈæsets/', 'noun', '{"zh-TW":["資產回報率"],"en":["net income divided by total assets, measuring how efficiently assets generate profit"]}', NULL, 'calculate return on assets / improve return on assets', '[{"en":"The company increased its return on assets by 3% through operational improvements.","zh-TW":"公司通過運營改善將資產回報率提高了3%。"},{"en":"Return on assets is used to compare companies within the same industry.","zh-TW":"資產回報率用於比較同一行業內的公司。"}]', '{"abbreviation":"ROA"}', NULL, 5, 5690, NULL),
(5691, 'return on capital employed', '/rɪˈtɜːrn ɒn ˈkæpɪtl ɪmˈplɔɪd/', 'noun', '{"zh-TW":["已動用資本回報率"],"en":["profit before interest and tax as a percentage of capital employed"]}', NULL, 'calculate return on capital employed / improve ROCE', '[{"en":"Return on capital employed of 15% exceeded the cost of capital.","zh-TW":"已動用資本回報率15%超過了資本成本。"},{"en":"ROCE is an important metric for capital-intensive industries.","zh-TW":"已動用資本回報率是資本密集型行業的重要指標。"}]', '{"abbreviation":"ROCE"}', NULL, 5, 5691, NULL),
(5692, 'return on equity', '/rɪˈtɜːrn ɒn ˈekwɪti/', 'noun', '{"zh-TW":["股東權益報酬率"],"en":["net profit expressed as a percentage of shareholders'' equity"]}', NULL, 'strong return on equity / improve return on equity', '[{"en":"A return on equity above 15% is considered excellent.","zh-TW":"股東權益報酬率超過15%被認為非常出色。"},{"en":"The bank reported a return on equity of 12% last year.","zh-TW":"銀行去年報告的股東權益報酬率為12%。"}]', '{"abbreviation":"ROE"}', NULL, 5, 5692, NULL),
(5693, 'return on invested capital', '/rɪˈtɜːrn ɒn ɪnˈvestɪd ˈkæpɪtəl/', 'noun', '{"zh-TW":["投入資本回報率"],"en":["a measure of how efficiently a company uses capital to generate profit"]}', NULL, 'improve return on invested capital / target return on invested capital / analyze return on invested capital', '[{"en":"A high return on invested capital indicates efficient capital allocation.","zh-TW":"高投入資本回報率表明資本配置效率高。"},{"en":"The CFO set a fifteen percent return on invested capital target for the group.","zh-TW":"財務長為集團設定了百分之十五的投入資本回報率目標。"}]', NULL, NULL, 5, 5693, NULL),
(5694, 'return on investment', '/rɪˈtɜːrn ɒn ɪnˈvestmənt/', 'noun', '{"zh-TW":["投資報酬率"],"en":["a measure of profitability relative to the cost of an investment"]}', NULL, 'high return on investment / calculate return on investment', '[{"en":"The project delivered a return on investment of 25%.","zh-TW":"該項目帶來了25%的投資報酬率。"},{"en":"Marketing campaigns are measured by their return on investment.","zh-TW":"行銷活動通過其投資報酬率來衡量。"}]', '{"abbreviation":"ROI"}', NULL, 5, 5694, NULL),
(5695, 'return policy', '/rɪˈtɜːrn ˈpɒlɪsi/', 'noun', '{"zh-TW":["退貨政策"],"en":["the rules under which a product can be returned"]}', NULL, 'flexible return policy / 30-day return policy', '[{"en":"The store offers a 30-day no-questions-asked return policy.","zh-TW":"商店提供30天無條件退貨政策。"},{"en":"Read the return policy before purchasing high-value items.","zh-TW":"購買高價商品前請閱讀退貨政策。"}]', NULL, NULL, 5, 5695, NULL),
(5696, 'return ticket', '/rɪˈtɜːrn ˈtɪkɪt/', 'noun', '{"zh-TW":["來回票"],"en":["a ticket valid for travel to a destination and back"]}', NULL, 'book a return ticket / return ticket price', '[{"en":"A return ticket is usually cheaper than two single tickets.","zh-TW":"來回票通常比兩張單程票便宜。"},{"en":"She bought a return ticket to visit her family.","zh-TW":"她買了一張來回票拜訪家人。"}]', NULL, NULL, 5, 5696, NULL),
(5697, 'returns management', '/rɪˈtɜːrnz ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["退貨管理"],"en":["the process of handling returned products from customers"]}', NULL, 'returns management process / improve returns management', '[{"en":"A simple returns management policy increases customer confidence.","zh-TW":"簡單的退貨管理政策增加了客戶信心。"},{"en":"Reverse logistics focuses on returns management and recycling.","zh-TW":"逆向物流專注於退貨管理和回收利用。"}]', NULL, NULL, 5, 5697, NULL),
(5698, 'reveal', '/rɪˈviːl/', 'verb', '{"zh-TW":["揭露；顯示","揭示；透露"],"en":["to make known something previously hidden","to make known; to show"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"veal","meaning":"veil/cover (遮蓋)"},"logic":"把遮蓋拉回，即「揭露」。"}', 'reveal the truth / reveal information / reveal a secret; reveal information / reveal the truth / reveal findings', '[{"en":"The investigation revealed new evidence.","zh-TW":"調查揭露了新證據。"},{"en":"She revealed her plans for the future.","zh-TW":"她透露了未來的計畫。"},{"en":"The audit revealed several discrepancies.","zh-TW":"審計揭示了幾處差異。"},{"en":"The survey revealed customer preferences.","zh-TW":"調查揭示了客戶偏好。"}]', '{"noun":"revelation","adjective":"revealing"}', NULL, 2, 5698, NULL),
(5699, 'revenue', '/ˈrevənjuː/', 'noun', '{"zh-TW":["收入；營收","營收"],"en":["income, especially of a company or organization","income from business activities","income earned by a company"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"venue","meaning":"come (來)"},"logic":"回來的錢，即「收入」。"}', 'annual revenue / revenue growth / generate revenue; revenue stream / revenue growth / total revenue', '[{"en":"The company''s annual revenue exceeded $1 billion.","zh-TW":"公司年營收超過10億美元。"},{"en":"Online sales are a major source of revenue.","zh-TW":"線上銷售是主要收入來源。"},{"en":"Annual revenue reached $50 million.","zh-TW":"年營收達到五千萬美元。"},{"en":"The new product line generates significant revenue.","zh-TW":"新產品線產生了可觀收入。"},{"en":"Total revenue exceeded expectations.","zh-TW":"總營收超出預期。"},{"en":"We need to diversify revenue streams.","zh-TW":"我們需要多元化收入來源。"}]', NULL, NULL, 3, 5699, 208);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5700, 'revenue forecast', '/ˈrɛvɪnjuː ˈfɔːrkɑːst/', 'noun', '{"zh-TW":["收益預測"],"en":["a projection of expected future revenue"]}', NULL, 'prepare a revenue forecast / accurate revenue forecast', '[{"en":"The revenue forecast for next year showed 20% growth.","zh-TW":"明年的收益預測顯示增長20%。"},{"en":"Management revised the revenue forecast after the market downturn.","zh-TW":"管理層在市場下滑後修訂了收益預測。"}]', NULL, NULL, 5, 5700, NULL),
(5701, 'revenue growth', '/ˈrevɪnjuː ɡroʊθ/', 'noun', '{"zh-TW":["收入增長"],"en":["an increase in a company''s total income from sales over a period"]}', NULL, 'drive revenue growth / revenue growth target', '[{"en":"The company achieved 15% revenue growth through new market entry.","zh-TW":"公司通過進入新市場實現了15%的收入增長。"},{"en":"Revenue growth is the primary metric for evaluating business performance.","zh-TW":"收入增長是評估業務績效的主要指標。"}]', NULL, NULL, 5, 5701, NULL),
(5702, 'revenue model', '/ˈrevɪnjuː ˈmɒdəl/', 'noun', '{"zh-TW":["收益模式"],"en":["the strategy a business uses to generate income"]}', NULL, 'subscription revenue model / freemium revenue model / advertising revenue model', '[{"en":"The startup switched from a freemium to a subscription revenue model.","zh-TW":"初創公司從免費增值轉換為訂閱收益模式。"},{"en":"A scalable revenue model is critical for investor confidence.","zh-TW":"可擴展的收益模式對於投資者信心至關重要。"}]', NULL, NULL, 5, 5702, NULL),
(5703, 'revenue per employee', '/ˈrevɪnjuː pɜːr ɪmˈplɔɪiː/', 'noun', '{"zh-TW":["人均收入"],"en":["a measure of how much revenue each employee generates on average"]}', NULL, 'calculate revenue per employee / improve revenue per employee', '[{"en":"Revenue per employee increased after the automation initiative.","zh-TW":"自動化計劃後人均收入增加了。"},{"en":"High revenue per employee indicates efficient use of human capital.","zh-TW":"高人均收入表明人力資本使用效率高。"}]', NULL, NULL, 5, 5703, NULL),
(5704, 'revenue recognition', '/ˈrevɪnjuː ˌrekəɡˈnɪʃən/', 'noun', '{"zh-TW":["收入確認"],"en":["the accounting principle governing when revenue is recognized in financial statements"]}', NULL, 'revenue recognition policy / apply revenue recognition standards', '[{"en":"Revenue recognition rules were updated under the new accounting standard.","zh-TW":"收入確認規則在新會計準則下進行了更新。"},{"en":"Improper revenue recognition led to the financial restatement.","zh-TW":"不當的收入確認導致了財務報表的重新申報。"}]', NULL, NULL, 5, 5704, NULL),
(5705, 'revenue stream', '/ˈrɛvɪnjuː striːm/', 'noun', '{"zh-TW":["收益來源"],"en":["a source of income for a business"]}', NULL, 'develop new revenue streams / diversify revenue streams', '[{"en":"The company developed multiple revenue streams to reduce risk.","zh-TW":"公司開發了多個收益來源以降低風險。"},{"en":"Subscription services became a significant revenue stream.","zh-TW":"訂閱服務成為了重要的收益來源。"}]', NULL, NULL, 5, 5705, NULL),
(5706, 'reverse', '/rɪˈvɜːrs/', 'verb', '{"zh-TW":["逆轉；撤銷"],"en":["to change to the opposite"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"verse","meaning":"turn (轉)"}}', 'reverse a decision / reverse the trend / in reverse', '[{"en":"The board reversed its earlier decision.","zh-TW":"董事會撤銷了先前的決定。"},{"en":"We need to reverse this downward trend.","zh-TW":"我們需要逆轉下降趨勢。"}]', '{"noun":"reversal","adjective":"reversible"}', NULL, 3, 5706, NULL),
(5707, 'reverse logistics', '/''rɪˈvɜːrs lɒˈdʒɪstɪks/', 'noun', '{"zh-TW":["逆向物流；退貨物流"],"en":["the process of moving goods from their final destination back to the manufacturer or seller for return or recycling"]}', NULL, 'manage reverse logistics / reverse logistics process / efficient reverse logistics', '[{"en":"Good reverse logistics management improves customer satisfaction for returned products.","zh-TW":"良好的逆向物流管理提高了退貨產品的客戶滿意度。"},{"en":"The company established a reverse logistics center to handle product recalls efficiently.","zh-TW":"公司建立了一個逆向物流中心，以有效地處理產品召回。"}]', NULL, NULL, 5, 5707, NULL),
(5708, 'reverse merger', '/rɪˈvɜːrs ˈmɜːrdʒər/', 'noun', '{"zh-TW":["反向合併"],"en":["a transaction in which a private company acquires a public company"]}', NULL, 'complete a reverse merger / pursue a reverse merger / reverse merger deal', '[{"en":"The startup went public through a reverse merger with a shell company.","zh-TW":"初創公司通過與殼公司的反向合併上市。"},{"en":"A reverse merger can be faster and cheaper than a traditional IPO.","zh-TW":"反向合併可以比傳統IPO更快更便宜。"}]', NULL, NULL, 5, 5708, NULL),
(5709, 'review', '/rɪˈvjuː/', 'noun', '{"zh-TW":["審查；評論"],"en":["an examination; an assessment"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"view","meaning":"see (看)"}}', 'performance review / under review / review process', '[{"en":"The application is currently under review.","zh-TW":"申請目前正在審查中。"},{"en":"Annual performance reviews start next week.","zh-TW":"年度績效考核下週開始。"}]', '{"verb":"review","noun":"reviewer"}', NULL, 2, 5709, 60),
(5710, 'revise', '/rɪˈvaɪz/', 'verb', '{"zh-TW":["修改；修訂","修訂"],"en":["to change or correct"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"vise","meaning":"see (看)"}}', 'revise the budget / revise upward / revised edition; revise the plan / revised estimate / subject to revision', '[{"en":"We need to revise the budget estimates.","zh-TW":"我們需要修改預算估計。"},{"en":"The forecast has been revised upward.","zh-TW":"預測已被上調修正。"},{"en":"The policy was revised last quarter.","zh-TW":"政策在上季度進行了修訂。"},{"en":"All figures are subject to revision.","zh-TW":"所有數字可能會修訂。"}]', '{"noun":"revision"}', NULL, 2, 5710, 209),
(5711, 'revolve', '/rɪˈvɒlv/', 'verb', '{"zh-TW":["圍繞；旋轉"],"en":["to move in a circle; to center on"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"volve","meaning":"roll (滾動)"}}', 'revolve around / revolving door / revolving credit', '[{"en":"The discussion revolved around cost reduction.","zh-TW":"討論圍繞著降低成本進行。"},{"en":"Our strategy revolves around innovation.","zh-TW":"我們的策略以創新為中心。"}]', '{"adjective":"revolving","noun":"revolution"}', NULL, 3, 5711, NULL),
(5712, 'revolving credit', '/rɪˈvɒlvɪŋ ˈkredɪt/', 'noun', '{"zh-TW":["循環信貸"],"en":["a credit facility that can be repeatedly used and repaid up to a limit"]}', NULL, 'draw on revolving credit / revolving credit facility', '[{"en":"The company used revolving credit to manage seasonal inventory needs.","zh-TW":"公司使用循環信貸來管理季節性庫存需求。"},{"en":"Revolving credit provides flexibility for short-term liquidity management.","zh-TW":"循環信貸為短期流動性管理提供了靈活性。"}]', NULL, NULL, 5, 5712, NULL),
(5713, 'reward', '/rɪˈwɔːrd/', 'noun', '{"zh-TW":["獎勵；報酬","獎勵"],"en":["something given in recognition","to give something good in return for effort"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"ward","meaning":"watch (看)"}}', 'reward for / rewards program / risk and reward; reward employees / reward loyalty / financially rewarding', '[{"en":"Hard work will bring its own reward.","zh-TW":"努力工作自有回報。"},{"en":"The company has a generous rewards program.","zh-TW":"公司有優厚的獎勵計劃。"},{"en":"We reward employees for excellent performance.","zh-TW":"我們獎勵表現優秀的員工。"},{"en":"The career is both challenging and rewarding.","zh-TW":"這份職業既有挑戰性又有回報。"}]', '{"verb":"reward","adjective":"rewarding","noun":"reward"}', NULL, 2, 5713, 210),
(5714, 'reward points', '/''rɪˈwɔːrd pɔɪnts/', 'noun', '{"zh-TW":["獎勵積分；回饋點數"],"en":["points accumulated through purchases or activities that can be redeemed for goods or services"]}', NULL, 'earn reward points / redeem reward points / accumulate reward points', '[{"en":"She earned reward points every time she used her travel credit card.","zh-TW":"她每次使用旅遊信用卡都能獲得獎勵積分。"},{"en":"Reward points can be redeemed for flights, hotel stays, or gift cards.","zh-TW":"獎勵積分可以兌換機票、飯店住宿或禮品卡。"}]', NULL, NULL, 5, 5714, NULL),
(5715, 'rhetoric', '/ˈretərɪk/', 'noun', '{"zh-TW":["修辭；花言巧語"],"en":["the art of effective or persuasive speaking or writing"]}', NULL, 'political rhetoric / empty rhetoric / rhetorical skill', '[{"en":"The politician''s rhetoric was powerful but lacking in substance.","zh-TW":"這位政治家的修辭很有力量，但缺乏實質內容。"},{"en":"Good rhetoric helps persuade audiences and win debates.","zh-TW":"良好的修辭有助於說服觀眾並贏得辯論。"}]', '{"adjective":"rhetorical","adverb":"rhetorically"}', NULL, 3, 5715, NULL),
(5716, 'rhetoric device', '/''retərɪk dɪˌvaɪs/', 'noun', '{"zh-TW":["修辭手法；修辭裝置"],"en":["a technique used in language to achieve a particular effect in writing or speech"]}', NULL, 'use a rhetoric device / effective rhetoric device / rhetorical device', '[{"en":"Metaphor is a common rhetoric device used to make abstract ideas more concrete.","zh-TW":"比喻是使抽象概念更具體的常用修辭手法。"},{"en":"Skilled speakers use rhetoric devices to make their presentations more memorable.","zh-TW":"熟練的演講者使用修辭手法使他們的演示更令人印象深刻。"}]', NULL, NULL, 5, 5716, NULL),
(5717, 'rheumatologist', '/ˌruːmətˈɒlədʒɪst/', 'noun', '{"zh-TW":["風濕科醫師"],"en":["a specialist in the diagnosis and treatment of autoimmune and rheumatic diseases"]}', NULL, 'consult a rheumatologist / qualified rheumatologist / rheumatologist appointment', '[{"en":"The rheumatologist prescribed biologics for the patient''s rheumatoid arthritis.","zh-TW":"風濕科醫師為患者的類風濕性關節炎開了生物製劑。"},{"en":"Autoimmune diseases like lupus are typically managed by a rheumatologist.","zh-TW":"狼瘡等自體免疫疾病通常由風濕科醫師管理。"}]', NULL, NULL, 5, 5717, NULL),
(5718, 'rich', '/rɪtʃ/', 'adjective', '{"zh-TW":["富有的；豐富的"],"en":["having a lot of money","containing a lot of something"]}', NULL, 'rich in / get rich', '[{"en":"The region is rich in natural resources.","zh-TW":"這個地區自然資源豐富。"},{"en":"The data provides rich insights.","zh-TW":"數據提供了豐富的洞見。"}]', '{"adjective":"rich","noun":"riches","adverb":"richly","verb":"enrich"}', NULL, 1, 5718, NULL),
(5719, 'ride', '/raɪd/', 'verb', '{"zh-TW":["騎；乘坐"],"en":["to sit on and control","to travel in a vehicle"]}', NULL, 'ride sharing / free ride', '[{"en":"Ride-sharing apps reduced transport costs.","zh-TW":"共乘應用程式降低了交通成本。"},{"en":"There is no free ride in business.","zh-TW":"商場上沒有不勞而獲。"}]', '{"verb":"ride","noun":"ride","noun2":"rider"}', NULL, 1, 5719, NULL),
(5720, 'right', 'raɪt', 'adjective', '{"zh-TW":["正確的；合適的","右邊的"],"en":["correct or appropriate","in the correct position"]}', NULL, 'right approach/right person', '[{"en":"Make sure you choose the right candidate.","zh-TW":"確保您選擇了正確的候選人。"}]', '{"noun":"right","adverb":"rightly"}', NULL, 2, 5720, NULL),
(5721, 'right of first refusal', '/raɪt əv fɜːrst rɪˈfjuːzəl/', 'noun', '{"zh-TW":["優先購買權"],"en":["the right to have the first opportunity to buy or accept an offer"]}', NULL, 'hold a right of first refusal / waive the right of first refusal', '[{"en":"The company holds a right of first refusal on any new share issuance.","zh-TW":"公司持有任何新股發行的優先購買權。"},{"en":"The partnership agreement includes a right of first refusal for buyouts.","zh-TW":"合夥協議包含收購的優先購買權條款。"}]', NULL, NULL, 5, 5721, NULL),
(5722, 'right to work', '/raɪt tə wɜːrk/', 'noun', '{"zh-TW":["工作權；勞動權"],"en":["the legal right of a person to be employed without discrimination"]}', NULL, 'protect the right to work / right to work legislation', '[{"en":"The company respects the right to work for all employees.","zh-TW":"公司尊重所有員工的工作權。"},{"en":"Right to work legislation affects union membership requirements.","zh-TW":"勞動權立法影響了工會成員資格要求。"}]', NULL, NULL, 5, 5722, NULL),
(5723, 'rights issue', '/raɪts ˈɪʃuː/', 'noun', '{"zh-TW":["供股；配股"],"en":["an offer to existing shareholders to buy new shares at a discounted price"]}', NULL, 'announce a rights issue / subscribe to a rights issue', '[{"en":"The company launched a rights issue to raise $50 million.","zh-TW":"公司啟動了供股以籌集5000萬元。"},{"en":"Shareholders who do not participate in a rights issue face dilution.","zh-TW":"未參與供股的股東面臨稀釋。"}]', NULL, NULL, 4, 5723, NULL),
(5724, 'rigid', '/ˈrɪdʒɪd/', 'adjective', '{"zh-TW":["嚴格的；僵硬的"],"en":["strict; not flexible"]}', '{"root":{"text":"rig","meaning":"stiff (僵硬)"}}', 'rigid rules / rigid structure / rigid schedule', '[{"en":"The company has very rigid policies.","zh-TW":"公司有非常嚴格的政策。"},{"en":"A rigid schedule leaves no room for creativity.","zh-TW":"僵化的日程不留創造空間。"}]', '{"noun":"rigidity","adverb":"rigidly"}', NULL, 2, 5724, NULL),
(5725, 'rigidity', '/rɪˈdʒɪdɪti/', 'noun', '{"zh-TW":["僵硬；死板；缺乏彈性"],"en":["the quality of being stiff or unyielding; inflexibility"]}', NULL, 'organizational rigidity / ideological rigidity / structural rigidity', '[{"en":"Excessive rigidity in rules can stifle creativity and innovation.","zh-TW":"規則中過度的死板會扼殺創造力和創新。"},{"en":"The rigidity of the framework made it difficult to adapt.","zh-TW":"框架的僵硬性使其難以適應變化。"}]', '{"adjective":"rigid","adverb":"rigidly"}', NULL, 3, 5725, NULL),
(5726, 'rigorous', '/ˈrɪɡərəs/', 'adjective', '{"zh-TW":["嚴格的；嚴謹的"],"en":["extremely thorough and careful"]}', NULL, 'rigorous testing / rigorous analysis / rigorous standards', '[{"en":"A rigorous peer review process ensures research quality.","zh-TW":"嚴格的同行評審過程確保研究品質。"},{"en":"The methodology must be rigorous to produce reliable results.","zh-TW":"方法論必須嚴謹才能產生可靠的結果。"}]', '{"noun":"rigor","adverb":"rigorously"}', NULL, 3, 5726, NULL),
(5727, 'ring', '/rɪŋ/', 'verb', '{"zh-TW":["響鈴；打電話"],"en":["to make a sound like a bell","to telephone"]}', NULL, 'ring a bell / give someone a ring', '[{"en":"Does the name ring a bell?","zh-TW":"這個名字你聽起來熟悉嗎？"},{"en":"Give me a ring tomorrow morning.","zh-TW":"明天早上打電話給我。"}]', '{"verb":"ring","noun":"ring"}', NULL, 1, 5727, NULL),
(5728, 'rise', '/raɪz/', 'verb', '{"zh-TW":["上升；增加"],"en":["to move upward","to increase"]}', NULL, 'give rise to / on the rise', '[{"en":"Remote work is on the rise.","zh-TW":"遠端工作正在增加。"},{"en":"This gave rise to new regulations.","zh-TW":"這引發了新的法規。"}]', '{"verb":"rise","noun":"rise"}', NULL, 1, 5728, NULL),
(5729, 'risk', '/rɪsk/', 'noun', '{"zh-TW":["風險","冒...的風險"],"en":["the possibility of danger or loss","to expose to danger"]}', NULL, 'take a risk / risk management / at risk / risk assessment; risk losing / risk assessment / risk management / at risk', '[{"en":"Every investment involves some degree of risk.","zh-TW":"每項投資都涉及一定程度的風險。"},{"en":"We need a comprehensive risk assessment.","zh-TW":"我們需要全面的風險評估。"},{"en":"We risk losing market share if we don''t innovate.","zh-TW":"如不創新我們就有失去市佔率的風險。"},{"en":"Effective risk management is crucial.","zh-TW":"有效的風險管理至關重要。"}]', '{"verb":"risk","adjective":"risky","noun":"risk"}', NULL, 1, 5729, NULL),
(5730, 'risk appetite', '/rɪsk ˈæpɪtaɪt/', 'noun', '{"zh-TW":["風險承受度；風險偏好"],"en":["the level of risk an organization is willing to accept"]}', NULL, 'define risk appetite / low risk appetite / risk appetite framework', '[{"en":"The board''s risk appetite guides all major investment decisions.","zh-TW":"董事會的風險承受度指導所有重大投資決策。"},{"en":"A higher risk appetite allows for more aggressive growth strategies.","zh-TW":"較高的風險偏好允許採取更激進的增長策略。"}]', NULL, NULL, 5, 5730, NULL),
(5731, 'risk assessment', '/rɪsk əˈsɛsmənt/', 'noun', '{"zh-TW":["風險評估"],"en":["an evaluation of potential hazards and their likelihood"]}', NULL, 'conduct a risk assessment / risk assessment report', '[{"en":"A risk assessment must be completed before the project begins.","zh-TW":"項目開始前必須完成風險評估。"},{"en":"Regular risk assessments help prevent workplace accidents.","zh-TW":"定期風險評估有助於預防工作場所事故。"}]', NULL, NULL, 5, 5731, NULL),
(5732, 'risk exposure', '/rɪsk ɪkˈspoʊʒər/', 'noun', '{"zh-TW":["風險敞口"],"en":["the extent to which a business or portfolio is affected by a particular risk"]}', NULL, 'manage risk exposure / reduce risk exposure', '[{"en":"The bank reduced its risk exposure by diversifying its loan portfolio.","zh-TW":"銀行通過多元化貸款組合降低了風險敞口。"},{"en":"Currency risk exposure must be hedged in international contracts.","zh-TW":"國際合約中的貨幣風險敞口必須進行對沖。"}]', NULL, NULL, 5, 5732, NULL),
(5733, 'risk management', '/rɪsk ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["風險管理"],"en":["identifying and mitigating potential threats to a business"]}', NULL, 'risk management framework / enterprise risk management', '[{"en":"Risk management helped the firm avoid costly mistakes.","zh-TW":"風險管理幫助公司避免了代價高昂的錯誤。"},{"en":"A solid risk management process is required by regulators.","zh-TW":"監管機構要求有健全的風險管理流程。"}]', '{"verb":"manage risk","adjective":"risk-managed"}', NULL, 5, 5733, NULL),
(5734, 'risk management framework', '/rɪsk ˈmænɪdʒmənt ˈfreɪmwɜːrk/', 'noun', '{"zh-TW":["風險管理框架"],"en":["a structured system for identifying, assessing, and controlling risks"]}', NULL, 'implement a risk management framework / update the risk management framework', '[{"en":"The company implemented an enterprise risk management framework last year.","zh-TW":"公司去年實施了企業風險管理框架。"},{"en":"A robust risk management framework is required by financial regulators.","zh-TW":"金融監管機構要求具有健全的風險管理框架。"}]', NULL, NULL, 5, 5734, NULL),
(5735, 'risk mitigation', '/rɪsk ˌmɪtɪˈɡeɪʃən/', 'noun', '{"zh-TW":["風險緩解；風險降低"],"en":["actions taken to reduce the probability or impact of a risk"]}', NULL, 'implement risk mitigation measures / risk mitigation strategy', '[{"en":"Risk mitigation plans were developed for all major project risks.","zh-TW":"為所有主要項目風險制定了風險緩解計劃。"},{"en":"Insurance is one form of risk mitigation for property damage.","zh-TW":"保險是財產損失的一種風險緩解形式。"}]', NULL, NULL, 5, 5735, NULL),
(5736, 'risk premium', '/rɪsk ˈpriːmiəm/', 'noun', '{"zh-TW":["風險溢酬"],"en":["the additional return investors require for taking on greater risk"]}', NULL, 'calculate risk premium / equity risk premium', '[{"en":"Investors demand a higher risk premium for investing in emerging markets.","zh-TW":"投資者要求在新興市場投資有更高的風險溢酬。"},{"en":"The risk premium compensates for uncertainty in projected cash flows.","zh-TW":"風險溢酬補償了預期現金流的不確定性。"}]', NULL, NULL, 4, 5736, NULL),
(5737, 'risk register', '/rɪsk ˈredʒɪstər/', 'noun', '{"zh-TW":["風險登記冊"],"en":["a document listing identified project risks and mitigation strategies"]}', NULL, 'maintain a risk register / update the risk register / review the risk register', '[{"en":"The risk register was updated after the supplier delayed delivery.","zh-TW":"供應商延遲交貨後，風險登記冊進行了更新。"},{"en":"All project risks are documented in the risk register.","zh-TW":"所有項目風險都記錄在風險登記冊中。"}]', NULL, NULL, 5, 5737, NULL),
(5738, 'risk-adjusted return', '/rɪsk əˈdʒʌstɪd rɪˈtɜːrn/', 'noun', '{"zh-TW":["風險調整後回報"],"en":["investment return adjusted to account for the risk taken"]}', NULL, 'calculate risk-adjusted return / compare risk-adjusted returns', '[{"en":"Investors compare risk-adjusted returns to evaluate fund performance.","zh-TW":"投資者比較風險調整後回報以評估基金績效。"},{"en":"A high risk-adjusted return indicates efficient use of risk capital.","zh-TW":"高風險調整後回報表明風險資本使用效率高。"}]', NULL, NULL, 5, 5738, NULL),
(5739, 'river', '/ˈrɪvər/', 'noun', '{"zh-TW":["河流"],"en":["a large natural stream of water"]}', NULL, 'down the river / river bank', '[{"en":"The factory is located along the river.","zh-TW":"工廠坐落在河邊。"},{"en":"Don''t sell your team down the river.","zh-TW":"不要出賣你的團隊。"}]', '{"noun":"river","noun2":"riverside"}', NULL, 2, 5739, NULL),
(5740, 'road', '/roʊd/', 'noun', '{"zh-TW":["道路"],"en":["a path for vehicles and people"]}', NULL, 'on the road / road map', '[{"en":"Our sales team is always on the road.","zh-TW":"我們的業務團隊總是在外跑。"},{"en":"Here is our product road map.","zh-TW":"這是我們的產品路線圖。"}]', '{"noun":"road","noun2":"roadblock"}', NULL, 1, 5740, NULL),
(5741, 'road trip', '/''rəʊd trɪp/', 'noun', '{"zh-TW":["公路旅行；駕車旅遊"],"en":["a long journey made by car, often with stops along the way"]}', NULL, 'plan a road trip / go on a road trip / road trip route', '[{"en":"They planned a two-week road trip along the Pacific Coast Highway.","zh-TW":"他們規劃了一次沿太平洋海岸公路的兩週公路旅行。"},{"en":"A road trip offers the freedom to stop wherever you want along the way.","zh-TW":"公路旅行提供了在途中隨意停車的自由。"}]', NULL, NULL, 3, 5741, NULL),
(5742, 'roadmap', '/ˈroʊdmæp/', 'noun', '{"zh-TW":["路線圖；發展規劃"],"en":["a strategic plan outlining goals and the steps to achieve them"]}', NULL, 'create a roadmap / product roadmap / technology roadmap', '[{"en":"The board approved a three-year roadmap for digital transformation.","zh-TW":"董事會批准了數位轉型的三年路線圖。"},{"en":"The product roadmap guides the development team''s priorities.","zh-TW":"產品路線圖指導了開發團隊的優先事項。"}]', NULL, NULL, 3, 5742, NULL),
(5743, 'roam', '/''rəʊm/', 'verb', '{"zh-TW":["漫游；四處漫步"],"en":["to move about or travel aimlessly or unsystematically over a wide area"]}', NULL, 'roam freely / roam the streets / roam the countryside', '[{"en":"Wild horses roam freely across the plains of the national park.","zh-TW":"野馬在國家公園的平原上自由漫游。"},{"en":"She loved to roam through the old neighborhoods, discovering hidden cafés.","zh-TW":"她喜歡在老街區漫步，發現隱藏的咖啡館。"}]', NULL, NULL, 1, 5743, NULL),
(5744, 'roast', '/''rəʊst/', 'verb', '{"zh-TW":["烘烤；烤"],"en":["to cook food in an oven or over a fire with dry heat"]}', NULL, 'roast in the oven / slow roast / roast vegetables', '[{"en":"She roasted the chicken at 200 degrees Celsius for one and a half hours.","zh-TW":"她在200攝氏度下烤了一個半小時的雞肉。"},{"en":"Roasting vegetables caramelizes their natural sugars and enhances their flavor.","zh-TW":"烤蔬菜會使其天然糖分焦糖化，增強風味。"}]', '{"noun":"roast","adjective":"roasted"}', NULL, 2, 5744, NULL),
(5745, 'robust', '/rəˈbʌst/', 'adjective', '{"zh-TW":["穩健的；強健的"],"en":["strong and unlikely to fail; thorough and effective"]}', NULL, 'robust system / robust evidence / robust approach', '[{"en":"The company needs a robust risk management framework.","zh-TW":"公司需要一個穩健的風險管理框架。"},{"en":"The study provides robust evidence supporting the intervention.","zh-TW":"研究提供了支持干預的強健證據。"}]', '{"noun":"robustness","adverb":"robustly"}', NULL, 2, 5745, NULL),
(5746, 'role', '/roʊl/', 'noun', '{"zh-TW":["角色；職責"],"en":["a function; a part played"]}', NULL, 'play a role / key role / role model / in the role of', '[{"en":"Technology plays a key role in our strategy.","zh-TW":"技術在我們策略中發揮關鍵作用。"},{"en":"She excels in her role as project lead.","zh-TW":"她在項目負責人的角色中表現出色。"}]', NULL, NULL, 1, 5746, 211),
(5747, 'rolling average', '/ˈroʊlɪŋ ˈævərɪdʒ/', 'noun', '{"zh-TW":["滾動平均"],"en":["an average recalculated over successive time periods as new data is added"]}', NULL, 'calculate rolling average / 3-month rolling average', '[{"en":"A 12-month rolling average smooths out short-term fluctuations in revenue.","zh-TW":"12個月滾動平均消除了收入的短期波動。"},{"en":"Rolling averages are used in trend analysis and forecasting.","zh-TW":"滾動平均用於趨勢分析和預測。"}]', NULL, NULL, 5, 5747, NULL),
(5748, 'rolling basis', '/ˈroʊlɪŋ ˈbeɪsɪs/', 'noun', '{"zh-TW":["滾動基準；持續更新的基準"],"en":["an ongoing arrangement reviewed and renewed continuously"]}', NULL, 'on a rolling basis / rolling basis contract', '[{"en":"Staff are admitted to the program on a rolling basis throughout the year.","zh-TW":"員工在全年滾動基準上入選計劃。"},{"en":"The contract renews automatically on a rolling basis annually.","zh-TW":"合約每年自動以滾動基準續期。"}]', NULL, NULL, 5, 5748, NULL),
(5749, 'rolling budget', '/ˈroʊlɪŋ ˈbʌdʒɪt/', 'noun', '{"zh-TW":["滾動預算"],"en":["a budget that is continuously updated by adding a new period as the current one ends"]}', NULL, 'use a rolling budget / rolling budget cycle', '[{"en":"A rolling budget ensures projections remain current throughout the year.","zh-TW":"滾動預算確保預測在全年保持最新狀態。"},{"en":"The company switched to a rolling budget to improve financial agility.","zh-TW":"公司改用滾動預算以提高財務靈活性。"}]', NULL, NULL, 5, 5749, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5750, 'rolling forecast', '/ˈroʊlɪŋ ˈfɔːrkæst/', 'noun', '{"zh-TW":["滾動預測"],"en":["a continuously updated projection extending a set number of months ahead"]}', NULL, 'use a rolling forecast / rolling forecast model', '[{"en":"The finance team uses a rolling forecast instead of fixed annual budgets.","zh-TW":"財務團隊使用滾動預測而非固定年度預算。"},{"en":"A rolling forecast provides more accurate and current projections.","zh-TW":"滾動預測提供了更準確和最新的預測。"}]', NULL, NULL, 5, 5750, NULL),
(5751, 'rollout', '/ˈroʊlaʊt/', 'noun', '{"zh-TW":["推出；逐步部署"],"en":["the gradual introduction of a product or system to users"]}', NULL, 'phased rollout / nationwide rollout / rollout plan / product rollout', '[{"en":"The phased rollout allowed issues to be fixed before full launch.","zh-TW":"分階段推出允許在全面上市前修復問題。"},{"en":"The software rollout was completed across all offices in six weeks.","zh-TW":"軟體部署在六週內完成了所有辦公室的覆蓋。"}]', '{"verb":"roll out"}', NULL, 3, 5751, 927),
(5752, 'rollout plan', '/ˈroʊlaʊt plæn/', 'noun', '{"zh-TW":["推出計劃；部署計劃"],"en":["a detailed schedule for implementing a new product or system"]}', NULL, 'create a rollout plan / follow the rollout plan', '[{"en":"The rollout plan described the phased launch across 10 regions.","zh-TW":"推出計劃描述了在10個地區的分階段推出。"},{"en":"A clear rollout plan minimizes disruption to daily operations.","zh-TW":"清晰的部署計劃最大限度地減少了對日常運營的干擾。"}]', NULL, NULL, 4, 5752, NULL),
(5753, 'rollover', '/ˈrəʊləʊvər/', 'noun', '{"zh-TW":["展期；滾存；轉存"],"en":["the extension of a debt or deposit beyond its maturity; the transfer of funds to a new account"]}', NULL, 'loan rollover / bond rollover / IRA rollover', '[{"en":"The bank agreed to a rollover of the short-term loan for an additional six months.","zh-TW":"銀行同意將短期貸款展期六個月。"},{"en":"Pension savers can use a rollover to transfer funds to a new retirement account tax-free.","zh-TW":"退休儲蓄者可以使用滾存方式將資金免稅轉入新的退休帳戶。"}]', NULL, NULL, 3, 5753, NULL),
(5754, 'room', '/ruːm/', 'noun', '{"zh-TW":["房間；空間"],"en":["a section of a building","available space"]}', NULL, 'meeting room / room for improvement', '[{"en":"There is room for improvement.","zh-TW":"還有改善的空間。"},{"en":"Book the meeting room for 2 p.m.","zh-TW":"預訂下午2點的會議室。"}]', '{"noun":"room","adjective":"roomy"}', NULL, 1, 5754, NULL),
(5755, 'room amenity', '/''ruːm əˈmiːnɪti/', 'noun', '{"zh-TW":["客房設施；房間備品"],"en":["items provided in a hotel room for the comfort and convenience of guests"]}', NULL, 'complimentary room amenity / luxury room amenity / standard room amenity', '[{"en":"The room amenity included a coffee maker, bathrobe, and toiletry kit.","zh-TW":"客房設施包括咖啡機、浴袍和盥洗用品套裝。"},{"en":"Guests can request additional room amenities from the housekeeping department.","zh-TW":"客人可以向客房服務部門索取額外的客房設施。"}]', NULL, NULL, 4, 5755, NULL),
(5756, 'room service', '/ruːm ˈsɜːrvɪs/', 'noun', '{"zh-TW":["客房服務"],"en":["the delivery of food and drinks to hotel rooms"]}', NULL, 'order room service / room service menu', '[{"en":"We ordered room service after arriving late at night.","zh-TW":"我們深夜抵達後點了客房服務。"},{"en":"Room service is available 24 hours a day.","zh-TW":"客房服務全天24小時提供。"}]', NULL, NULL, 4, 5756, NULL),
(5757, 'room upgrade', '/''ruːm ˌʌpˈɡreɪd/', 'noun', '{"zh-TW":["房間升級"],"en":["the allocation of a better or larger hotel room than originally booked"]}', NULL, 'complimentary room upgrade / receive a room upgrade / request a room upgrade', '[{"en":"As a gold member, she received a complimentary room upgrade to a suite.","zh-TW":"作為黃金會員，她獲得了免費升級至套房的待遇。"},{"en":"Room upgrades may be available at check-in depending on availability.","zh-TW":"房間升級可能在辦理入住手續時根據空房情況提供。"}]', NULL, NULL, 4, 5757, NULL),
(5758, 'root cause analysis', '/ruːt kɔːz əˈnælɪsɪs/', 'noun', '{"zh-TW":["根本原因分析"],"en":["a method for identifying the underlying cause of a problem"]}', NULL, 'conduct a root cause analysis / root cause analysis report / root cause analysis tools', '[{"en":"Root cause analysis revealed a software bug caused the outage.","zh-TW":"根本原因分析顯示軟體錯誤導致了中斷。"},{"en":"The team used root cause analysis to prevent recurrence.","zh-TW":"團隊使用根本原因分析防止問題再次發生。"}]', '{"abbreviation":"RCA"}', NULL, 5, 5758, NULL),
(5759, 'rotate', '/roʊˈteɪt/', 'verb', '{"zh-TW":["輪換；旋轉"],"en":["to move in a circle; to take turns"]}', '{"root":{"text":"rot","meaning":"wheel (輪)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'rotate duties / job rotation / rotating schedule', '[{"en":"Staff rotate between departments quarterly.","zh-TW":"員工每季度在部門間輪換。"},{"en":"The chairperson role rotates annually.","zh-TW":"主席一職每年輪換。"}]', '{"noun":"rotation","adjective":"rotating, rotational"}', NULL, 2, 5759, NULL),
(5760, 'rotation', '/roʊˈteɪʃən/', 'noun', '{"zh-TW":["輪調；輪換"],"en":["systematically moving employees between different roles or departments"]}', NULL, 'job rotation / rotation program / staff rotation', '[{"en":"Job rotation helps employees develop a broader skill set.","zh-TW":"職位輪調幫助員工培養更廣泛的技能。"},{"en":"The graduate program includes a rotation through all business units.","zh-TW":"研究生計劃包括在所有業務單位的輪調。"}]', '{"verb":"rotate","adjective":"rotating"}', NULL, 3, 5760, 928),
(5761, 'roughly', '/ˈrʌfli/', 'adverb', '{"zh-TW":["大約；粗略地"],"en":["approximately; in a rough way"]}', '{"root":{"text":"rough","meaning":"rough (粗糙)"},"suffix":{"text":"-ly","meaning":"副詞後綴"}}', 'roughly equal / roughly speaking / roughly estimated', '[{"en":"The project will cost roughly $100,000.","zh-TW":"項目大約花費十萬美元。"},{"en":"Roughly 60% of staff attended.","zh-TW":"大約60%的員工出席了。"}]', '{"adjective":"rough"}', NULL, 3, 5761, NULL),
(5762, 'round', '/raʊnd/', 'noun', '{"zh-TW":["一輪；回合"],"en":["a series or cycle","approximately"]}', NULL, 'round of funding / year-round', '[{"en":"The startup raised a second round of funding.","zh-TW":"新創公司完成了第二輪融資。"},{"en":"The resort is open year-round.","zh-TW":"度假村全年開放。"}]', '{"noun":"round","adjective":"round","verb":"round","adverb":"around"}', NULL, 2, 5762, NULL),
(5763, 'round-the-clock', '/ˌraʊnd ðə ˈklɒk/', 'adjective', '{"zh-TW":["全天候的；24小時的"],"en":["continuing or available at all times, day and night"]}', NULL, 'round-the-clock support / round-the-clock operations', '[{"en":"The call center provides round-the-clock customer support.","zh-TW":"呼叫中心提供全天候客戶支援。"},{"en":"Emergency services operate on a round-the-clock basis.","zh-TW":"緊急服務全天候運作。"}]', NULL, NULL, 5, 5763, NULL),
(5764, 'roundtrip', '/ˈraʊndtrɪp/', 'noun', '{"zh-TW":["來回旅程"],"en":["a journey to a place and back again"]}', NULL, 'roundtrip ticket / roundtrip fare', '[{"en":"A roundtrip ticket is usually cheaper than two one-way tickets.","zh-TW":"來回票通常比兩張單程票便宜。"},{"en":"We booked roundtrip flights to London.","zh-TW":"我們預訂了倫敦的來回機票。"}]', NULL, NULL, 3, 5764, NULL),
(5765, 'route optimization', '/''ruːt ˌɒptɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["路線優化"],"en":["the process of finding the most efficient route for delivering goods or providing services"]}', NULL, 'implement route optimization / route optimization software / benefit of route optimization', '[{"en":"Route optimization software reduced delivery times by twenty percent.","zh-TW":"路線優化軟體將配送時間縮短了百分之二十。"},{"en":"The logistics company uses AI-powered route optimization to plan driver schedules.","zh-TW":"這家物流公司使用人工智慧驅動的路線優化來規劃司機行程。"}]', NULL, NULL, 5, 5765, NULL),
(5766, 'route planning', '/''ruːt ˌplænɪŋ/', 'noun', '{"zh-TW":["路線規劃；行程規劃"],"en":["the process of determining the best path for delivery vehicles to minimize time and cost"]}', NULL, 'efficient route planning / route planning software / optimize route planning', '[{"en":"Advanced route planning software helps logistics companies reduce delivery costs.","zh-TW":"先進的路線規劃軟體幫助物流公司降低配送成本。"},{"en":"Manual route planning is being replaced by AI-driven systems.","zh-TW":"手動路線規劃正在被人工智慧驅動的系統所取代。"}]', NULL, NULL, 5, 5766, NULL),
(5767, 'router', '/ˈraʊtər/', 'noun', '{"zh-TW":["路由器"],"en":["a device that directs internet traffic"]}', NULL, 'wireless router / router settings', '[{"en":"Restart the router to fix the connection.","zh-TW":"重啟路由器來修復連線。"},{"en":"The wireless router covers the whole house.","zh-TW":"無線路由器覆蓋整棟房子。"}]', NULL, NULL, 2, 5767, NULL),
(5768, 'routine', '/ruːˈtiːn/', 'noun', '{"zh-TW":["例行公事；日常工作","例行的；常規的"],"en":["a regular way of doing things","regular; done as part of normal procedure"]}', NULL, 'daily routine / routine maintenance / routine procedure; routine check / routine inspection / routine maintenance', '[{"en":"Routine maintenance is scheduled for Sunday.","zh-TW":"例行維護安排在週日。"},{"en":"It became part of the daily routine.","zh-TW":"它成為了日常工作的一部分。"},{"en":"This is just a routine inspection.","zh-TW":"這只是例行檢查。"},{"en":"Routine maintenance keeps equipment running.","zh-TW":"例行維護使設備正常運行。"}]', '{"adjective":"routine","adverb":"routinely","noun":"routine"}', NULL, 3, 5768, 212),
(5769, 'royalty payment', '/ˈrɔɪəlti ˈpeɪmənt/', 'noun', '{"zh-TW":["版稅；專利使用費"],"en":["periodic payments made for the right to use intellectual property"]}', NULL, 'receive royalty payments / royalty payment structure', '[{"en":"The inventor receives annual royalty payments from the licensing deal.","zh-TW":"發明人從授權協議中獲得年度版稅。"},{"en":"Royalty payments are calculated as a percentage of licensed product sales.","zh-TW":"版稅根據授權產品銷售額的百分比計算。"}]', '{"verb":"license"}', NULL, 5, 5769, NULL),
(5770, 'RSU', '/ˌɑːr es ˈjuː/', 'noun', '{"zh-TW":["限制性股票單位"],"en":["restricted stock unit; shares awarded to employees that vest over time"]}', NULL, 'RSU vesting / RSU award / receive RSUs', '[{"en":"She received 500 RSUs as part of her compensation package.","zh-TW":"她收到了500個限制性股票單位作為薪酬方案的一部分。"},{"en":"RSUs provide ownership stake without requiring upfront purchase.","zh-TW":"限制性股票單位提供所有權份額，無需預先購買。"}]', '{"full form":"restricted stock unit"}', NULL, 1, 5770, NULL),
(5771, 'RSVP', '/ɑːr ɛs viː piː/', 'verb', '{"zh-TW":["回覆邀請"],"en":["to respond to an invitation"]}', NULL, 'please RSVP / RSVP by Friday', '[{"en":"Please RSVP by Friday to confirm your attendance.","zh-TW":"請在週五前回覆以確認您的出席。"},{"en":"We need to finalize the guest list, so RSVP is required.","zh-TW":"我們需要確定賓客名單，因此請回覆邀請。"}]', NULL, NULL, 1, 5771, NULL),
(5772, 'rubric', '/''ruːbrɪk/', 'noun', '{"zh-TW":["評分標準；評分規範"],"en":["a set of criteria used to evaluate or assess student work"]}', NULL, 'grading rubric / assessment rubric / rubric-based evaluation', '[{"en":"The teacher shared the rubric so students would understand how their essays would be graded.","zh-TW":"老師分享了評分標準，讓學生了解他們的文章將如何被評分。"},{"en":"A detailed rubric helps ensure consistent and fair grading across all submissions.","zh-TW":"詳細的評分標準有助於確保所有提交作業的評分一致且公平。"}]', NULL, NULL, 2, 5772, NULL),
(5773, 'rule', '/ruːl/', 'noun', '{"zh-TW":["規則；法規"],"en":["an official instruction"]}', NULL, 'follow the rules / rule out / as a rule / rule of thumb', '[{"en":"All participants must follow the rules.","zh-TW":"所有參與者必須遵守規則。"},{"en":"We cannot rule out the possibility.","zh-TW":"我們不能排除這種可能性。"}]', '{"verb":"rule","noun":"ruler, ruling"}', NULL, 1, 5773, NULL),
(5774, 'run', '/rʌn/', 'verb', '{"zh-TW":["【主要意義-動詞】跑；運行","【次要意義-動詞】管理；經營（業務）","【次要意義-名詞】一連串（事件）；連續期間","【次要意義-名詞】（機器）運作期間"],"en":["[primary] to move quickly on foot; to operate","[secondary - verb] to manage or operate a business or organization","[secondary - noun] a continuous series or period","[secondary - noun] the operation of a machine or system"]}', NULL, 'run a business / run a meeting / in the long run / a run on the bank / on the run', '[{"en":"She has run the family business for over 15 years.","zh-TW":"她已經經營家族企業超過15年了。"},{"en":"In the long run, investing in training pays off for companies.","zh-TW":"從長遠來看，投資培訓對公司來說是值得的。"},{"en":"The factory had a production run of 50,000 units last month.","zh-TW":"上個月工廠的生產批次達到了5萬件。"}]', '{"noun":"runner, running","adjective":"running"}', '動詞 run = 「管理/經營」是 TOEIC 極高頻用法，in the long run（從長遠來看）是必考片語，a production run（生產批次）出現在製造業文章中。', 1, 5774, NULL),
(5775, 'run rate', '/rʌn reɪt/', 'noun', '{"zh-TW":["年化運行率；估算全年業績"],"en":["an extrapolation of current financial performance to a full-year basis"]}', NULL, 'annual run rate / revenue run rate / calculate the run rate', '[{"en":"The company''s revenue run rate reached $100 million after Q2.","zh-TW":"公司第二季後的收入年化運行率達到1億美元。"},{"en":"Run rate is useful for startups that haven''t completed a full year.","zh-TW":"年化運行率對尚未完成一整年的新創公司很有用。"}]', NULL, NULL, 3, 5775, NULL),
(5776, 'running costs', '/ˈrʌnɪŋ kɒsts/', 'noun', '{"zh-TW":["運營成本；日常費用"],"en":["the ongoing expenses of operating a business or asset"]}', NULL, 'reduce running costs / calculate running costs', '[{"en":"Solar panels reduce the running costs of the factory significantly.","zh-TW":"太陽能板顯著降低了工廠的運營成本。"},{"en":"Running costs must be factored into any financial projection.","zh-TW":"任何財務預測都必須考慮運營成本。"}]', NULL, NULL, 5, 5776, NULL),
(5777, 'runtime', '/ˈrʌntaɪm/', 'noun', '{"zh-TW":["運行時；執行期間"],"en":["the period during which a program is running; an environment supporting program execution"]}', NULL, 'runtime error / runtime environment / at runtime', '[{"en":"The runtime error occurred because of an invalid memory access.","zh-TW":"由於無效的記憶體訪問，發生了運行時錯誤。"},{"en":"The application dynamically loads configurations at runtime.","zh-TW":"應用程式在運行時動態加載配置。"}]', NULL, NULL, 3, 5777, NULL),
(5778, 'runway', '/ˈrʌnweɪ/', 'noun', '{"zh-TW":["資金跑道；可支撐時間"],"en":["the amount of time a startup can operate before running out of cash"]}', NULL, 'extend the runway / 12 months of runway / calculate runway', '[{"en":"With $3M in the bank and a $250K burn rate, they had 12 months of runway.","zh-TW":"銀行有300萬美元，燒錢速度25萬美元，他們有12個月的資金跑道。"},{"en":"Raising a new round extended the company''s runway by two years.","zh-TW":"新一輪融資將公司的資金跑道延長了兩年。"}]', NULL, NULL, 2, 5778, NULL),
(5779, 'résumé', '/ˈrezjʊmeɪ/', 'noun', '{"zh-TW":["履歷；簡歷"],"en":["a document summarizing an individual''s work experience and qualifications"]}', NULL, 'submit a résumé / update your résumé / résumé review', '[{"en":"She tailored her résumé to highlight relevant experience.","zh-TW":"她客製化了簡歷以突出相關經驗。"},{"en":"A strong résumé increases the chance of landing an interview.","zh-TW":"一份強力的履歷提高了獲得面試機會的可能性。"}]', '{"alternative":"CV (curriculum vitae)","plural":"résumés"}', NULL, 2, 5779, NULL),
(5780, 'SaaS', '/sæs/', 'noun', '{"zh-TW":["軟體即服務"],"en":["software as a service; cloud-based software accessed via subscription"]}', NULL, 'SaaS platform / SaaS model / SaaS product / switch to SaaS', '[{"en":"The company switched from on-premise software to a SaaS solution.","zh-TW":"公司從本地軟體切換到了SaaS解決方案。"},{"en":"SaaS products offer automatic updates and lower upfront costs.","zh-TW":"SaaS產品提供自動更新和更低的前期成本。"}]', '{"full form":"software as a service"}', NULL, 1, 5780, NULL),
(5781, 'sabbatical', '/səˈbætɪkəl/', 'noun', '{"zh-TW":["休假；研究假"],"en":["an extended period of leave granted to an employee for rest or study"]}', NULL, 'sabbatical leave / take a sabbatical / paid sabbatical', '[{"en":"She took a six-month sabbatical to write her book.","zh-TW":"她請了六個月的休假來寫書。"},{"en":"The company offers sabbaticals after ten years of service.","zh-TW":"公司為服務滿十年的員工提供研究假。"}]', '{"adjective":"sabbatical"}', NULL, 4, 5781, NULL),
(5782, 'sacrifice', '/ˈsækrɪfaɪs/', 'noun, verb', '{"zh-TW":["犧牲；獻祭","犧牲；放棄"],"en":["an act of giving up something valued","to give up something important"]}', NULL, 'make a sacrifice / sacrifice for', '[{"en":"She made a great sacrifice for her family.","zh-TW":"她為家人做出了巨大的犧牲。"},{"en":"He sacrificed his career for his children.","zh-TW":"他為了孩子犧牲了自己的事業。"}]', '{"noun":"sacrifice","verb":"sacrifice","adjective":"sacrificial"}', NULL, 3, 5782, NULL),
(5783, 'sad', '/sæd/', 'adjective', '{"zh-TW":["悲傷的；令人遺憾的"],"en":["feeling unhappy","unfortunate"]}', NULL, 'sad news / sadly', '[{"en":"I have sad news about the layoffs.","zh-TW":"我有關於裁員的壞消息。"},{"en":"Sadly, the branch will close.","zh-TW":"不幸的是，分公司將關閉。"}]', '{"adjective":"sad","noun":"sadness","adverb":"sadly","verb":"sadden"}', NULL, 1, 5783, NULL),
(5784, 'safari', '/''səˈfɑːri/', 'noun', '{"zh-TW":["野生動物園之旅；狩獵旅行"],"en":["an overland journey, especially in Africa, to observe wild animals in their natural habitat"]}', NULL, 'go on a safari / wildlife safari / safari park', '[{"en":"They went on a safari in Kenya and saw lions, elephants, and giraffes.","zh-TW":"他們去肯亞參加野生動物觀賞之旅，看到了獅子、大象和長頸鹿。"},{"en":"A guided safari offers the best chance of spotting rare wildlife.","zh-TW":"導覽野生動物旅行提供了發現稀有野生動物的最佳機會。"}]', NULL, NULL, 2, 5784, NULL),
(5785, 'safe', '/seɪf/', 'adjective', '{"zh-TW":["安全的"],"en":["protected from danger"]}', NULL, 'safe and sound / play it safe', '[{"en":"All employees arrived safe and sound.","zh-TW":"所有員工都安全抵達。"},{"en":"Let''s play it safe with this investment.","zh-TW":"這項投資我們保守一點。"}]', '{"adjective":"safe","noun":"safety","adverb":"safely","verb":"safeguard"}', NULL, 1, 5785, NULL),
(5786, 'safe deposit', '/seɪf dɪˈpɒzɪt/', 'noun', '{"zh-TW":["保險箱；安全存款"],"en":["a secure container for valuables in a hotel room"]}', NULL, 'use the safe deposit box / in-room safe deposit', '[{"en":"Please use the safe deposit box for your valuables.","zh-TW":"請使用保險箱存放您的貴重物品。"},{"en":"The safe deposit box is located inside the wardrobe.","zh-TW":"保險箱位於衣櫥內。"}]', NULL, NULL, 4, 5786, NULL),
(5787, 'safeguard', '/ˈseɪfɡɑːrd/', 'noun, verb', '{"zh-TW":["保障措施；防護","保護；防衛"],"en":["a measure taken to protect","to protect from harm"]}', NULL, 'safeguard against / safeguard interests', '[{"en":"We need safeguards against data breaches.","zh-TW":"我們需要防範資料洩露的保障措施。"},{"en":"The policy safeguards employees'' rights.","zh-TW":"該政策保障了員工的權利。"}]', '{"noun":"safeguard","verb":"safeguard"}', NULL, 3, 5787, 929),
(5788, 'safety officer', '/ˈseɪfti ˈɒfɪsər/', 'noun', '{"zh-TW":["安全主任；安全官員"],"en":["a person responsible for managing safety in the workplace"]}', NULL, 'appoint a safety officer / report to the safety officer', '[{"en":"The safety officer conducted the monthly safety inspection.","zh-TW":"安全主任進行了每月安全檢查。"},{"en":"Contact the safety officer if you observe a potential hazard.","zh-TW":"如果您發現潛在危害，請聯繫安全主任。"}]', NULL, NULL, 5, 5788, NULL),
(5789, 'safety stock', '/ˈseɪfti stɒk/', 'noun', '{"zh-TW":["安全庫存"],"en":["extra inventory kept to prevent stockouts due to demand or supply variability"]}', NULL, 'maintain safety stock / safety stock level', '[{"en":"The company maintains a safety stock of 2 weeks of production materials.","zh-TW":"公司維持2週生產材料的安全庫存。"},{"en":"Safety stock acts as a buffer against unexpected supply disruptions.","zh-TW":"安全庫存作為應對意外供應中斷的緩衝。"}]', NULL, NULL, 4, 5789, NULL),
(5790, 'salary', '/ˈsæləri/', 'noun', '{"zh-TW":["薪水；薪資"],"en":["a fixed regular payment for work"]}', NULL, 'annual salary / salary increase / base salary', '[{"en":"Her annual salary is $80,000.","zh-TW":"她的年薪是八萬美元。"},{"en":"Employees received a 5% salary increase.","zh-TW":"員工獲得了5%的加薪。"}]', '{"noun":"salary","adjective":"salaried"}', NULL, 2, 5790, NULL),
(5791, 'salary band', '/ˈsæləri bænd/', 'noun', '{"zh-TW":["薪資範圍；薪酬帶"],"en":["a range of salaries for a particular job grade or level"]}', NULL, 'salary band structure / fall within the salary band', '[{"en":"The new hire''s salary fell within the band for that job grade.","zh-TW":"新員工的薪資在該職等的薪資範圍內。"},{"en":"Transparent salary bands promote fairness across the organization.","zh-TW":"透明的薪資範圍促進了組織內部的公平性。"}]', '{"plural":"salary bands"}', NULL, 4, 5791, NULL),
(5792, 'salary negotiation', '/ˈsæləri nɪˌɡoʊʃiˈeɪʃən/', 'noun', '{"zh-TW":["薪資談判"],"en":["the process of discussing and agreeing on compensation with an employer"]}', NULL, 'salary negotiation tips / enter salary negotiation / successful salary negotiation', '[{"en":"She researched market rates before entering salary negotiation.","zh-TW":"她在進入薪資談判前研究了市場薪資水準。"},{"en":"Salary negotiation is an expected part of the hiring process.","zh-TW":"薪資談判是招聘過程中的預期環節。"}]', '{"verb":"negotiate salary"}', NULL, 5, 5792, NULL),
(5793, 'salary review', '/ˈsæləri rɪˈvjuː/', 'noun', '{"zh-TW":["薪資審查；薪資評估"],"en":["a periodic assessment of an employee compensation level"]}', NULL, 'conduct a salary review / salary review process', '[{"en":"Annual salary reviews are aligned with the company budget cycle.","zh-TW":"年度薪資審查與公司的預算周期相一致。"},{"en":"The salary review resulted in an average 5% increase across the team.","zh-TW":"薪資審查導致整個團隊平均加薪5%。"}]', NULL, NULL, 5, 5793, NULL),
(5794, 'sale', '/seɪl/', 'noun', '{"zh-TW":["銷售；特賣"],"en":["the act of selling","a period when goods are sold at reduced prices"]}', '{"root":{"text":"sale","meaning":"sell (賣)"},"logic":"販售的行為或特賣活動。"}', 'on sale / sales figures / for sale', '[{"en":"The house is for sale.","zh-TW":"這棟房子出售中。"},{"en":"Winter coats are on sale this week.","zh-TW":"冬季外套本週特價。"}]', '{"noun":"salesperson","verb":"sell"}', NULL, 1, 5794, NULL),
(5795, 'sale and leaseback', '/seɪl ænd ˈliːsbæk/', 'noun', '{"zh-TW":["售後回租"],"en":["a transaction in which an owner sells an asset and then leases it back from the buyer"]}', NULL, 'arrange a sale and leaseback / sale and leaseback agreement / benefit from sale and leaseback', '[{"en":"The airline used a sale and leaseback of aircraft to raise immediate cash.","zh-TW":"航空公司使用飛機的售後回租方式來快速籌集現金。"},{"en":"A sale and leaseback allows companies to unlock capital tied up in fixed assets.","zh-TW":"售後回租使公司能夠解放積壓在固定資產中的資本。"}]', NULL, NULL, 5, 5795, NULL),
(5796, 'sales', 'seɪlz', 'noun', '{"zh-TW":["銷售額；銷售量","銷售"],"en":["the total money from selling","the activity of selling"]}', NULL, 'sales target/sales team', '[{"en":"The sales team exceeded its quarterly target.","zh-TW":"銷售團隊超過了季度目標。"}]', '{"verb":"sell","adjective":"sales-oriented"}', NULL, 2, 5796, NULL),
(5797, 'sales budget', '/seɪlz ˈbʌdʒɪt/', 'noun', '{"zh-TW":["銷售預算"],"en":["an estimate of expected sales revenue for a future period"]}', NULL, 'prepare a sales budget / exceed the sales budget', '[{"en":"The sales budget was increased by 20% for the next fiscal year.","zh-TW":"下一財政年度的銷售預算增加了20%。"},{"en":"A realistic sales budget guides hiring and inventory decisions.","zh-TW":"實際的銷售預算指導了聘用和庫存決策。"}]', NULL, NULL, 4, 5797, NULL),
(5798, 'sales conversion rate', '/seɪlz kənˈvɜːrʒən reɪt/', 'noun', '{"zh-TW":["銷售轉換率"],"en":["the percentage of leads or prospects that become actual customers"]}', NULL, 'improve sales conversion rate / track sales conversion rate', '[{"en":"Personalized follow-ups increased the sales conversion rate by 15%.","zh-TW":"個人化的跟進將銷售轉換率提高了15%。"},{"en":"A low sales conversion rate may indicate pricing or messaging issues.","zh-TW":"低銷售轉換率可能表明定價或訊息傳遞存在問題。"}]', NULL, NULL, 5, 5798, NULL),
(5799, 'sales forecast', '/seɪlz ˈfɔːrkæst/', 'noun', '{"zh-TW":["銷售預測"],"en":["an estimate of future sales volume or revenue"]}', NULL, 'prepare a sales forecast / revise the sales forecast', '[{"en":"The sales forecast was revised down after poor August results.","zh-TW":"在八月業績不佳後，銷售預測被下調了。"},{"en":"An accurate sales forecast allows production to be planned effectively.","zh-TW":"準確的銷售預測允許有效規劃生產。"}]', NULL, NULL, 5, 5799, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5800, 'sales funnel', '/seɪlz ˈfʌnəl/', 'noun', '{"zh-TW":["銷售漏斗"],"en":["a model representing the stages a customer passes through before buying"]}', NULL, 'top of the funnel / bottom of the funnel / optimize the sales funnel', '[{"en":"Content at the top of the sales funnel builds brand awareness.","zh-TW":"銷售漏斗頂部的內容建立品牌知名度。"},{"en":"The sales funnel revealed high drop-off at the pricing stage.","zh-TW":"銷售漏斗顯示在定價階段的高流失率。"}]', NULL, NULL, 4, 5800, NULL),
(5801, 'sales ledger', '/seɪlz ˈledʒər/', 'noun', '{"zh-TW":["銷售分類帳；應收帳款總帳"],"en":["a record of all sales transactions and amounts owed by customers"]}', NULL, 'update the sales ledger / sales ledger reconciliation', '[{"en":"The accounts team reconciles the sales ledger with bank receipts.","zh-TW":"帳務團隊將銷售分類帳與銀行收款對帳。"},{"en":"An accurate sales ledger is essential for tracking receivables.","zh-TW":"準確的銷售分類帳對於追蹤應收帳款至關重要。"}]', NULL, NULL, 4, 5801, NULL),
(5802, 'sales pipeline', '/seɪlz ˈpaɪplaɪn/', 'noun', '{"zh-TW":["銷售管道；業務流水線"],"en":["the progression of potential deals a sales team is working on"]}', NULL, 'build a sales pipeline / manage the sales pipeline', '[{"en":"The sales pipeline shows deals worth 5 million in the next quarter.","zh-TW":"銷售管道顯示下個季度有價值500萬元的交易。"},{"en":"Regular pipeline reviews identify stalled opportunities.","zh-TW":"定期管道審查識別了停滯的商機。"}]', NULL, NULL, 5, 5802, NULL),
(5803, 'sales quota', '/seɪlz ˈkwoʊtə/', 'noun', '{"zh-TW":["銷售配額"],"en":["a target amount of sales that a salesperson is expected to achieve in a period"]}', NULL, 'meet sales quota / sales quota attainment', '[{"en":"The sales team achieved 110% of their sales quota for the quarter.","zh-TW":"銷售團隊實現了本季度銷售配額的110%。"},{"en":"Sales quotas are set based on market potential and historical performance.","zh-TW":"銷售配額根據市場潛力和歷史業績設定。"}]', NULL, NULL, 4, 5803, NULL),
(5804, 'sales representative', '/seɪlz ˌrɛprɪˈzɛntətɪv/', 'noun', '{"zh-TW":["業務代表；銷售代表"],"en":["a person employed to sell goods or services"]}', NULL, 'contact a sales representative / field sales representative', '[{"en":"The sales representative visited three clients this week.","zh-TW":"業務代表本週拜訪了三位客戶。"},{"en":"A skilled sales representative builds long-term client relationships.","zh-TW":"熟練的業務代表建立了長期的客戶關係。"}]', NULL, NULL, 5, 5804, NULL),
(5805, 'sales target', '/seɪlz ˈtɑːrɡɪt/', 'noun', '{"zh-TW":["銷售目標"],"en":["the desired level of sales for a specific period"]}', NULL, 'meet the sales target / set sales targets', '[{"en":"The team met its quarterly sales target ahead of schedule.","zh-TW":"團隊提前完成了季度銷售目標。"},{"en":"Incentives are offered for exceeding the annual sales target.","zh-TW":"超過年度銷售目標可獲得獎勵。"}]', NULL, NULL, 4, 5805, NULL),
(5806, 'sales territory', '/seɪlz ˈterɪtɔːri/', 'noun', '{"zh-TW":["銷售區域"],"en":["a defined geographic area assigned to a sales representative"]}', NULL, 'assign a sales territory / cover a sales territory', '[{"en":"Each sales rep is responsible for a specific sales territory.","zh-TW":"每位銷售代表負責特定的銷售區域。"},{"en":"Expanding sales territories is a sign of business growth.","zh-TW":"擴大銷售區域是業務增長的標誌。"}]', NULL, NULL, 5, 5806, NULL),
(5807, 'salient', '/ˈseɪliənt/', 'adjective', '{"zh-TW":["顯著的；突出的"],"en":["most noticeable or important; prominent"]}', NULL, 'salient feature / salient point / salient fact', '[{"en":"The most salient finding is the gap between theory and practice.","zh-TW":"最顯著的發現是理論與實踐之間的差距。"},{"en":"Highlight the salient points in your summary.","zh-TW":"在摘要中突出顯著的要點。"}]', '{"adverb":"saliently","noun":"salience"}', NULL, 3, 5807, NULL),
(5808, 'salvage value', '/ˈsælvɪdʒ ˈvæljuː/', 'noun', '{"zh-TW":["殘值；清算價值"],"en":["the expected amount recoverable from an asset at the end of its useful life"]}', NULL, 'estimate salvage value / salvage value calculation', '[{"en":"The plant was depreciated to its estimated salvage value of $10000.","zh-TW":"工廠被折舊到估計殘值10,000元。"},{"en":"A higher salvage value reduces the annual depreciation charge.","zh-TW":"較高的殘值降低了年度折舊費用。"}]', '{"synonym":"residual value"}', NULL, 5, 5808, NULL),
(5809, 'sample', '/ˈsæmpl/', 'noun, verb', '{"zh-TW":["樣品；樣本","取樣；品嚐"],"en":["a small part representing the whole","to take a sample of"]}', NULL, 'free sample / sample size / random sample', '[{"en":"We collected a random sample of 500 customers.","zh-TW":"我們隨機抽樣了500位顧客。"},{"en":"Would you like to sample the new product?","zh-TW":"您想試用新產品嗎？"}]', '{"noun":"sample, sampling","verb":"sample"}', NULL, 2, 5809, NULL),
(5810, 'sampling method', '/ˈsɑːmplɪŋ ˈmeθəd/', 'noun', '{"zh-TW":["抽樣方法"],"en":["a technique for selecting a subset of a population for research or analysis"]}', NULL, 'apply a sampling method / random sampling method', '[{"en":"A stratified sampling method was used to ensure representative survey results.","zh-TW":"使用了分層抽樣方法以確保代表性的調查結果。"},{"en":"The sampling method must be documented for audit purposes.","zh-TW":"抽樣方法必須為審計目的而記錄在案。"}]', NULL, NULL, 5, 5810, NULL),
(5811, 'sanction', '/ˈsæŋkʃən/', 'noun', '{"zh-TW":["制裁；許可","制裁；處罰","批准；認可"],"en":["a penalty imposed on a country; official approval","a penalty for breaking a law","to give official permission"]}', NULL, 'economic sanctions / impose sanctions; impose sanctions / economic sanctions / lift sanctions', '[{"en":"The country faces economic sanctions.","zh-TW":"該國面臨經濟制裁。"},{"en":"Sanctions were imposed on the regime.","zh-TW":"對該政權實施了制裁。"},{"en":"The government imposed economic sanctions.","zh-TW":"政府實施了經濟制裁。"},{"en":"The plan was sanctioned by the board.","zh-TW":"該計畫已獲董事會批准。"}]', '{"verb":"sanction","noun":"sanction"}', NULL, 3, 5811, 930),
(5812, 'sanctions', '/ˈsæŋkʃənz/', 'noun', '{"zh-TW":["制裁；處罰"],"en":["penalties imposed by governments on other countries or entities"]}', NULL, 'impose sanctions / lift sanctions / economic sanctions', '[{"en":"Economic sanctions were imposed on the country for treaty violations.","zh-TW":"因違反條約，對該國實施了經濟制裁。"},{"en":"Sanctions disrupted the company''s ability to do business abroad.","zh-TW":"制裁干擾了公司在海外的業務能力。"}]', '{"verb":"sanction","singular":"sanction"}', NULL, 3, 5812, NULL),
(5813, 'satellite', '/ˈsætəlaɪt/', 'noun', '{"zh-TW":["衛星"],"en":["an object orbiting a planet; a device in space"]}', NULL, 'satellite TV / communication satellite', '[{"en":"The satellite orbits the Earth.","zh-TW":"衛星繞地球運行。"},{"en":"We get internet via satellite.","zh-TW":"我們透過衛星上網。"}]', NULL, NULL, 3, 5813, NULL),
(5814, 'satire', '/ˈsætaɪər/', 'noun', '{"zh-TW":["諷刺；諷刺文學"],"en":["the use of humor, irony, or exaggeration to criticize or expose foolishness"]}', NULL, 'political satire / social satire / biting satire', '[{"en":"The comedy show uses satire to challenge politicians and media.","zh-TW":"這個喜劇節目使用諷刺來挑戰政客和媒體。"},{"en":"Satire has been a powerful tool for social criticism throughout history.","zh-TW":"諷刺在歷史上一直是社會批評的有力工具。"}]', '{"adjective":"satirical","adverb":"satirically","verb":"satirize"}', NULL, 2, 5814, NULL),
(5815, 'satisfy', '/ˈsætɪsfaɪ/', 'verb', '{"zh-TW":["滿足；使滿意","符合（要求）"],"en":["to fulfill the needs or desires of","to meet requirements"]}', '{"suffix":{"text":"-fy","meaning":"使..."}}', 'satisfy demands / satisfy customers / satisfy requirements', '[{"en":"The results satisfied all stakeholders.","zh-TW":"結果讓所有利害關係人都滿意。"},{"en":"The candidate satisfies all the requirements.","zh-TW":"這位候選人符合所有要求。"}]', '{"noun":"satisfaction","verb":"satisfy","adjective":"satisfactory, satisfied, satisfying"}', NULL, 3, 5815, NULL),
(5816, 'saturated fat', '/''sætʃəreɪtɪd fæt/', 'noun', '{"zh-TW":["飽和脂肪"],"en":["a type of fat found mainly in animal products that is solid at room temperature and can raise cholesterol levels"]}', NULL, 'reduce saturated fat / high in saturated fat / saturated fat content', '[{"en":"Butter, cheese, and red meat are high in saturated fat.","zh-TW":"奶油、起司和紅肉富含飽和脂肪。"},{"en":"Health guidelines recommend limiting saturated fat intake to protect heart health.","zh-TW":"健康指南建議限制飽和脂肪攝取以保護心臟健康。"}]', NULL, NULL, 5, 5816, NULL),
(5817, 'sauna', '/ˈsɔːnə/', 'noun', '{"zh-TW":["桑拿浴室；三溫暖"],"en":["a room heated to a high temperature for relaxation"]}', NULL, 'use the sauna / hotel sauna', '[{"en":"The hotel''s sauna is open from 6 am to 10 pm.","zh-TW":"飯店的三溫暖從早上6點開放至晚上10點。"},{"en":"A sauna session can help you relax after a long flight.","zh-TW":"桑拿浴有助於長途飛行後放鬆。"}]', NULL, NULL, 2, 5817, NULL),
(5818, 'sauté', '/''soʊteɪ/', 'verb', '{"zh-TW":["煎炒；嫩煎"],"en":["to fry food quickly in a small amount of hot fat"]}', NULL, 'sauté in butter / sauté until golden / sauté vegetables', '[{"en":"Sauté the onions in olive oil until they are translucent and soft.","zh-TW":"在橄欖油中煎炒洋蔥，直到它們透明柔軟。"},{"en":"She sautéed the mushrooms with garlic and fresh thyme.","zh-TW":"她用大蒜和新鮮百里香煎炒了蘑菇。"}]', NULL, NULL, 2, 5818, NULL),
(5819, 'save', '/seɪv/', 'verb', '{"zh-TW":["節省；儲蓄","拯救；保存"],"en":["to keep money for future use","to rescue from danger"]}', NULL, 'save money / save time / save energy', '[{"en":"She saves 20% of her income every month.","zh-TW":"她每個月存下收入的20%。"},{"en":"The new system saves us a lot of time.","zh-TW":"新系統為我們節省了大量時間。"}]', '{"noun":"savings, saver","verb":"save"}', NULL, 1, 5819, NULL),
(5820, 'savings account', '/ˈseɪvɪŋz əˈkaʊnt/', 'noun', '{"zh-TW":["儲蓄帳戶"],"en":["a bank account that earns interest on deposits"]}', NULL, 'open a savings account / savings account interest rate', '[{"en":"Opening a savings account is the first step to financial security.","zh-TW":"開設儲蓄帳戶是財務安全的第一步。"},{"en":"The savings account offered a competitive interest rate.","zh-TW":"該儲蓄帳戶提供了有競爭力的利率。"}]', NULL, NULL, 5, 5820, NULL),
(5821, 'savory', '/''seɪvəri/', 'adjective', '{"zh-TW":["鹹味的；美味的"],"en":["belonging to the category of food that is salty or spicy rather than sweet"]}', NULL, 'savory dish / savory snack / savory flavor', '[{"en":"She preferred savory snacks like nuts and cheese over sweet ones.","zh-TW":"她更喜歡堅果和起司等鹹味零食而非甜食。"},{"en":"The savory pie was filled with chicken, mushrooms, and herbs.","zh-TW":"這個鹹味派裡填充著雞肉、蘑菇和香草。"}]', NULL, NULL, 2, 5821, NULL),
(5822, 'say', 'seɪ', 'verb', '{"zh-TW":["說；表示","聲稱"],"en":["to speak words","to express in words"]}', NULL, 'say something/that', '[{"en":"What did the manager say?","zh-TW":"經理說了什麼？"}]', '{"noun":"saying"}', NULL, 1, 5822, NULL),
(5823, 'scalability', '/ˌskeɪləˈbɪlɪti/', 'noun', '{"zh-TW":["可擴展性；擴展能力"],"en":["the ability of a system or business to grow efficiently"]}', NULL, 'business scalability / scalability of the model', '[{"en":"The platform was designed with scalability in mind.","zh-TW":"該平台設計時考慮了可擴展性。"},{"en":"Scalability is essential for any startup aiming to grow.","zh-TW":"可擴展性對任何目標成長的新創公司都至關重要。"}]', '{"adjective":"scalable","verb":"scale"}', NULL, 4, 5823, 810),
(5824, 'scalable', '/ˈskeɪləbl/', 'adjective', '{"zh-TW":["可擴展的；可規模化的"],"en":["able to grow or expand efficiently to meet increasing demand"]}', NULL, 'scalable business model / scalable solution / highly scalable', '[{"en":"The SaaS platform is highly scalable and can handle millions of users.","zh-TW":"SaaS平台具有高度可擴展性，可以處理數百萬用戶。"},{"en":"Investors seek scalable business models with large addressable markets.","zh-TW":"投資者尋求具有大型可觸達市場的可擴展商業模式。"}]', '{"noun":"scalability","verb":"scale"}', NULL, 3, 5824, NULL),
(5825, 'scalable architecture', '/ˈskeɪləbəl ˈɑːrkɪˌtekʧər/', 'noun', '{"zh-TW":["可擴展架構"],"en":["a system design that can handle increasing workloads by adding resources without redesigning the core structure"]}', NULL, 'design a scalable architecture / build a scalable architecture / scalable architecture pattern', '[{"en":"The engineering team built a scalable architecture that could support millions of users.","zh-TW":"工程團隊構建了一個可以支持數百萬用戶的可擴展架構。"},{"en":"A scalable architecture is essential for startups expecting rapid growth.","zh-TW":"對於預期快速增長的初創公司來說，可擴展架構至關重要。"}]', NULL, NULL, 5, 5825, NULL),
(5826, 'scalable solution', '/ˈskeɪləbəl səˈluːʃən/', 'noun', '{"zh-TW":["可擴展的解決方案"],"en":["a solution that can grow or adapt as demand or scope increases"]}', NULL, 'implement a scalable solution / design a scalable solution', '[{"en":"The company chose a cloud-based, scalable solution for its data needs.","zh-TW":"公司選擇了一個基於雲端的可擴展解決方案來滿足其數據需求。"},{"en":"A scalable solution prevents the need for costly system replacements.","zh-TW":"可擴展的解決方案防止了昂貴的系統更換需求。"}]', '{"adjective":"scalable"}', NULL, 5, 5826, NULL),
(5827, 'scale', '/skeɪl/', 'noun, verb', '{"zh-TW":["規模；比例","擴大規模；攀登"],"en":["the size or extent of something","to increase in size"]}', NULL, 'on a large scale / economies of scale / scale up', '[{"en":"The company plans to scale up production.","zh-TW":"公司計劃擴大生產規模。"},{"en":"The project was carried out on a large scale.","zh-TW":"該專案是大規模進行的。"}]', '{"noun":"scale","verb":"scale","adjective":"scalable"}', NULL, 2, 5827, NULL),
(5828, 'scale up', '/skeɪl ʌp/', 'verb', '{"zh-TW":["擴大規模；向上擴展"],"en":["to increase the size or capacity of a business or operation"]}', NULL, 'scale up production / scale up operations', '[{"en":"The startup scaled up quickly after receiving the Series B investment.","zh-TW":"新創公司在獲得B輪投資後迅速擴大了規模。"},{"en":"Scaling up requires more staff, systems, and financial resources.","zh-TW":"擴大規模需要更多的員工、系統和財務資源。"}]', '{"noun":"scale-up","adjective":"scaled up"}', NULL, 3, 5828, NULL),
(5829, 'scan', '/skæn/', 'verb, noun', '{"zh-TW":["掃描；瀏覽","掃描"],"en":["to examine quickly","a medical or electronic examination"]}', NULL, 'scan a document / brain scan / scan for errors', '[{"en":"Please scan the document and email it.","zh-TW":"請掃描文件並用電子郵件發送。"},{"en":"She scanned the report for key findings.","zh-TW":"她快速瀏覽了報告的主要發現。"}]', '{"noun":"scan, scanner","verb":"scan"}', NULL, 1, 5829, NULL),
(5830, 'scarce', '/skers/', 'adjective', '{"zh-TW":["稀少的；缺乏的"],"en":["insufficient for the demand; not enough"]}', NULL, 'scarce resources / increasingly scarce', '[{"en":"Clean water is scarce in many regions.","zh-TW":"乾淨的水在許多地區很稀缺。"},{"en":"Skilled workers are becoming increasingly scarce.","zh-TW":"技術工人越來越稀缺。"}]', '{"noun":"scarcity","adjective":"scarce","adverb":"scarcely"}', NULL, 2, 5830, NULL),
(5831, 'scarcity', '/ˈskeərsɪti/', 'noun', '{"zh-TW":["稀缺；稀缺性"],"en":["the limited availability of a resource relative to demand"]}', NULL, 'scarcity of resources / create scarcity / scarcity principle', '[{"en":"Scarcity of skilled engineers pushed salaries higher.","zh-TW":"技術工程師的稀缺推高了薪資。"},{"en":"The marketing campaign used scarcity to drive urgency.","zh-TW":"行銷活動利用稀缺性製造緊迫感。"}]', '{"adjective":"scarce","adverb":"scarcely"}', NULL, 3, 5831, NULL),
(5832, 'scenario', '/sɪˈnærioʊ/', 'noun', '{"zh-TW":["情境；劇本","可能的情況"],"en":["a possible sequence of events","a written outline of a story"]}', NULL, 'worst-case scenario / best-case scenario / likely scenario', '[{"en":"In the worst-case scenario, we lose 10% revenue.","zh-TW":"在最壞的情況下，我們會損失10%的收入。"},{"en":"Let''s consider various scenarios before deciding.","zh-TW":"讓我們在決定前考慮各種情境。"}]', '{"noun":"scenario"}', NULL, 3, 5832, NULL),
(5833, 'scenario analysis', '/sɪˈnɑːriəʊ əˈnæləsɪs/', 'noun', '{"zh-TW":["情景分析"],"en":["an assessment of possible future events and their implications"]}', NULL, 'conduct scenario analysis / scenario analysis approach / climate scenario analysis', '[{"en":"Scenario analysis prepares businesses for a range of possible futures.","zh-TW":"情景分析為企業應對各種可能的未來做準備。"},{"en":"The bank used scenario analysis to test its capital adequacy under stress conditions.","zh-TW":"銀行使用情景分析來測試壓力條件下的資本充足性。"}]', NULL, NULL, 5, 5833, NULL),
(5834, 'scenario planning', '/sɪˈneərioʊ ˈplænɪŋ/', 'noun', '{"zh-TW":["情境規劃"],"en":["a strategic planning method involving multiple future scenarios"]}', NULL, 'conduct scenario planning / scenario planning exercise', '[{"en":"The executive team used scenario planning to prepare for economic downturns.","zh-TW":"執行團隊使用情境規劃為經濟低迷做準備。"},{"en":"Scenario planning helps organizations respond flexibly to uncertainty.","zh-TW":"情境規劃幫助組織靈活應對不確定性。"}]', NULL, NULL, 5, 5834, NULL),
(5835, 'scenic', '/''siːnɪk/', 'adjective', '{"zh-TW":["風景優美的；景色宜人的"],"en":["providing or relating to views of impressive or beautiful natural scenery"]}', NULL, 'scenic route / scenic view / scenic drive', '[{"en":"We took the scenic route along the coast instead of the highway.","zh-TW":"我們走了沿海岸的風景路線，而不是高速公路。"},{"en":"The scenic overlook gave a panoramic view of the valley below.","zh-TW":"這個風景俯瞰點可以看到下方山谷的全景。"}]', '{"noun":"scenery"}', NULL, 2, 5835, NULL),
(5836, 'scenic flight', '/''siːnɪk flaɪt/', 'noun', '{"zh-TW":["觀光飛行；風景直升機遊覽"],"en":["a short flight taken primarily for the view rather than transportation"]}', NULL, 'take a scenic flight / book a scenic flight / scenic flight over', '[{"en":"She booked a scenic flight over the Grand Canyon for a bird''s-eye view.","zh-TW":"她預訂了一次在大峽谷上空的觀光飛行，以便欣賞鳥瞰景色。"},{"en":"A scenic flight at dawn offers the most spectacular views of the mountains.","zh-TW":"黎明時的觀光飛行提供了最壯觀的山脈景色。"}]', NULL, NULL, 5, 5836, NULL),
(5837, 'scenic overlook', '/''siːnɪk ˌəʊvəlʊk/', 'noun', '{"zh-TW":["觀景台；景觀瞭望點"],"en":["a designated area alongside a road providing a view of the surrounding landscape"]}', NULL, 'park at the scenic overlook / visit a scenic overlook', '[{"en":"The scenic overlook offered a breathtaking view of the valley below.","zh-TW":"觀景台提供了下方山谷令人嘆為觀止的景色。"},{"en":"Tourists stop at the scenic overlook to take photographs of the mountain range.","zh-TW":"遊客在觀景台停下來拍攝山脈的照片。"}]', NULL, NULL, 5, 5837, NULL),
(5838, 'scenic route', '/''siːnɪk ruːt/', 'noun', '{"zh-TW":["風景路線；景觀道路"],"en":["a longer, more picturesque route as opposed to the fastest or most direct one"]}', NULL, 'take the scenic route / follow the scenic route / recommend the scenic route', '[{"en":"We took the scenic route along the mountain ridge for breathtaking views.","zh-TW":"我們沿著山脊走風景路線，欣賞令人嘆為觀止的景色。"},{"en":"The scenic route added an hour to our journey but was well worth it.","zh-TW":"風景路線讓我們的旅程多了一個小時，但非常值得。"}]', NULL, NULL, 4, 5838, NULL),
(5839, 'schedule', '/ˈskedʒuːl/', 'noun, verb', '{"zh-TW":["時間表；計畫表","安排；排定"],"en":["a plan of activities or events","to arrange for something to happen"]}', NULL, 'on schedule / behind schedule / ahead of schedule', '[{"en":"The project is on schedule.","zh-TW":"專案如期進行。"},{"en":"The meeting has been scheduled for Monday.","zh-TW":"會議已排定在週一。"}]', '{"noun":"schedule, scheduling","verb":"schedule, reschedule","adjective":"scheduled, unscheduled"}', NULL, 3, 5839, 61),
(5840, 'scheme', '/skiːm/', 'noun, verb', '{"zh-TW":["計畫；方案","策劃；圖謀"],"en":["a systematic plan or arrangement","to make plans secretly"]}', NULL, 'color scheme / pension scheme / scheme to do sth.', '[{"en":"The company launched a new training scheme.","zh-TW":"公司推出了新的培訓方案。"},{"en":"They schemed to take over the business.","zh-TW":"他們密謀接管這家公司。"}]', '{"noun":"scheme, schemer","verb":"scheme"}', NULL, 2, 5840, NULL),
(5841, 'scholarship', '/ˈskɒlərʃɪp/', 'noun', '{"zh-TW":["獎學金"],"en":["money given to a student for their education"]}', NULL, 'win a scholarship / full scholarship', '[{"en":"She won a full scholarship.","zh-TW":"她獲得了全額獎學金。"},{"en":"Apply for scholarships early.","zh-TW":"要早點申請獎學金。"}]', '{"noun2":"scholar"}', NULL, 4, 5841, NULL),
(5842, 'scholastic', '/skəˈlæstɪk/', 'adjective', '{"zh-TW":["學術的；學業的"],"en":["of or concerning schools and education"]}', NULL, 'scholastic achievement / scholastic aptitude / scholastic record', '[{"en":"Her scholastic achievements earned her a prestigious scholarship.","zh-TW":"她的學業成就為她贏得了一份享有盛譽的獎學金。"},{"en":"The program aims to improve scholastic performance in underserved communities.","zh-TW":"該計畫旨在提升弱勢社區的學業表現。"}]', '{"noun":"scholarship","adverb":"scholastically"}', NULL, 4, 5842, NULL),
(5843, 'school', '/skuːl/', 'noun', '{"zh-TW":["學校"],"en":["an institution for educating children"]}', NULL, 'business school / school of thought', '[{"en":"He graduated from a top business school.","zh-TW":"他從頂尖商學院畢業。"},{"en":"There are two schools of thought on this.","zh-TW":"對此有兩種學派觀點。"}]', '{"noun":"school","noun2":"schooling"}', NULL, 2, 5843, NULL),
(5844, 'science', '/ˈsaɪəns/', 'noun', '{"zh-TW":["科學"],"en":["the study of the natural world through observation"]}', NULL, 'data science / computer science', '[{"en":"Data science drives our decisions.","zh-TW":"數據科學驅動我們的決策。"},{"en":"She has a degree in computer science.","zh-TW":"她有電腦科學學位。"}]', '{"noun":"science","noun2":"scientist","adjective":"scientific","adverb":"scientifically"}', NULL, 3, 5844, NULL),
(5845, 'science fair', '/''saɪəns feər/', 'noun', '{"zh-TW":["科學博覽會；科學展示會"],"en":["a competition or exhibition where students present their science projects"]}', NULL, 'enter a science fair / win a science fair / participate in a science fair', '[{"en":"She won first place at the regional science fair with her water purification project.","zh-TW":"她憑藉水淨化項目在地區科學博覽會上獲得了第一名。"},{"en":"The science fair inspired young students to pursue careers in research.","zh-TW":"科學博覽會激勵年輕學生追求研究職業。"}]', NULL, NULL, 4, 5845, NULL),
(5846, 'scope', '/skoʊp/', 'noun', '{"zh-TW":["範圍；領域","機會；餘地"],"en":["the range of a subject or activity","opportunity for action"]}', NULL, 'scope of work / beyond the scope / within scope', '[{"en":"This issue is beyond the scope of our project.","zh-TW":"這個問題超出了我們專案的範圍。"},{"en":"There is scope for improvement.","zh-TW":"仍有改進的空間。"}]', '{"noun":"scope"}', NULL, 2, 5846, NULL),
(5847, 'scope creep', '/skoʊp kriːp/', 'noun', '{"zh-TW":["範疇蔓延"],"en":["the gradual expansion of a project''s scope beyond its original boundaries"]}', NULL, 'prevent scope creep / manage scope creep / identify scope creep', '[{"en":"Scope creep caused the project to miss its deadline.","zh-TW":"範疇蔓延導致項目錯過了截止日期。"},{"en":"A change control process helps prevent scope creep.","zh-TW":"變更控制流程有助於防止範疇蔓延。"}]', NULL, NULL, 4, 5847, NULL),
(5848, 'scope of work', '/skoʊp əv wɜːrk/', 'noun', '{"zh-TW":["工作範圍"],"en":["a document describing all the tasks, deliverables, and timelines for a project"]}', NULL, 'define scope of work / scope of work agreement', '[{"en":"The scope of work was agreed upon and signed before the project started.","zh-TW":"工作範圍在項目開始前已達成協議並簽署。"},{"en":"Changes outside the scope of work may incur additional charges.","zh-TW":"工作範圍以外的更改可能會產生額外費用。"}]', NULL, NULL, 5, 5848, NULL),
(5849, 'score', '/skɔːr/', 'noun', '{"zh-TW":["得分；分數"],"en":["the number of points in a game"]}', NULL, 'final score / high score', '[{"en":"The final score was 3-2.","zh-TW":"最終比分是3比2。"},{"en":"She got a high score on the test.","zh-TW":"她考試得了高分。"}]', '{"verb":"score","noun2":"scoreboard"}', NULL, 2, 5849, NULL);
