(5850, 'scoreboard', '/''skɔːrbɔːrd/', 'noun', '{"zh-TW":["記分板；計分牌"],"en":["a large board or electronic display showing the current score in a game or competition"]}', NULL, 'check the scoreboard / scoreboard update / lead on the scoreboard', '[{"en":"With five minutes remaining, the scoreboard showed a tie.","zh-TW":"距比賽結束還有五分鐘，記分板顯示平局。"},{"en":"The crowd cheered as the home team''s score appeared on the scoreboard.","zh-TW":"當主隊的得分出現在記分板上時，觀眾歡呼雀躍。"}]', NULL, NULL, 4, 5850, NULL),
(5851, 'scorecard', '/ˈskɔːrkɑːrd/', 'noun', '{"zh-TW":["計分卡；績效記分卡"],"en":["a report summarizing performance across key metrics"]}', NULL, 'balanced scorecard / performance scorecard / update the scorecard', '[{"en":"The balanced scorecard tracks financial and non-financial performance.","zh-TW":"平衡計分卡追蹤財務和非財務績效。"},{"en":"The weekly scorecard is shared with all department heads.","zh-TW":"週報計分卡分享給所有部門主管。"}]', NULL, NULL, 3, 5851, NULL),
(5852, 'screen', '/skriːn/', 'noun, verb', '{"zh-TW":["螢幕；屏幕","篩選；審查"],"en":["a display surface","to examine or check systematically"]}', NULL, 'screen candidates / on screen / screening process', '[{"en":"All applicants are screened before the interview.","zh-TW":"所有應徵者在面試前都會經過篩選。"},{"en":"The presentation will appear on screen.","zh-TW":"簡報將顯示在螢幕上。"}]', '{"noun":"screen, screening","verb":"screen"}', NULL, 2, 5852, NULL),
(5853, 'screening', '/ˈskriːnɪŋ/', 'noun', '{"zh-TW":["篩選；審查","放映"],"en":["the testing or examining of a group","the showing of a film"]}', NULL, 'background screening / screening process / health screening', '[{"en":"All candidates undergo a background screening.","zh-TW":"所有候選人都會接受背景審查。"},{"en":"The screening process takes about two weeks.","zh-TW":"篩選過程大約需要兩週。"}]', '{"noun":"screening, screen","verb":"screen"}', NULL, 3, 5853, NULL),
(5854, 'Scrum', '/skrʌm/', 'noun', '{"zh-TW":["Scrum框架；敏捷開發框架"],"en":["an agile framework for managing and completing complex projects"]}', NULL, 'Scrum framework / Scrum master / Scrum team / daily Scrum', '[{"en":"The development team adopted Scrum to improve delivery speed.","zh-TW":"開發團隊採用Scrum框架以提高交付速度。"},{"en":"The daily Scrum is a 15-minute standup meeting.","zh-TW":"每日Scrum是一個15分鐘的站立會議。"}]', '{"noun":"Scrum master"}', NULL, 2, 5854, NULL),
(5855, 'scrupulous', '/''skruːpjʊləs/', 'adjective', '{"zh-TW":["謹慎的；一絲不苟的"],"en":["careful to do the right thing; very concerned with moral standards or precise accuracy"]}', NULL, 'scrupulous attention / scrupulous conduct / scrupulous honesty', '[{"en":"She maintained scrupulous records of all financial transactions for the audit.","zh-TW":"她為審計維護了所有財務交易的一絲不苟的記錄。"},{"en":"His scrupulous attention to contract details prevented many potential disputes.","zh-TW":"他對合同細節的謹慎關注防止了許多潜在糾紛。"}]', '{"adverb":"scrupulously","noun":"scrupulousness"}', NULL, 4, 5855, NULL),
(5856, 'scrutiny', '/ˈskruːtəni/', 'noun', '{"zh-TW":["仔細檢查；審查"],"en":["careful and thorough examination"]}', NULL, 'under scrutiny / public scrutiny / close scrutiny', '[{"en":"The company''s finances are under close scrutiny.","zh-TW":"公司的財務正在接受仔細審查。"},{"en":"His actions came under public scrutiny.","zh-TW":"他的行為受到了公眾的審視。"}]', '{"noun":"scrutiny","verb":"scrutinize"}', NULL, 3, 5856, NULL),
(5857, 'sculpture', '/ˈskʌlptʃər/', 'noun', '{"zh-TW":["雕塑"],"en":["a three-dimensional work of art"]}', '{"root":{"text":"sculpt","meaning":"carve (雕刻)"},"suffix":{"text":"-ure","meaning":"result (結果)"},"logic":"雕刻的結果，即「雕塑」。"}', 'marble sculpture / modern sculpture', '[{"en":"The sculpture was made entirely of recycled metal.","zh-TW":"這座雕塑完全由回收金屬製成。"},{"en":"There is a famous sculpture in the park.","zh-TW":"公園裡有一座著名的雕塑。"}]', '{"verb":"sculpt","noun":"sculptor"}', NULL, 3, 5857, NULL),
(5858, 'sea', '/siː/', 'noun', '{"zh-TW":["海"],"en":["a large body of saltwater"]}', NULL, 'by sea / at sea', '[{"en":"Goods are shipped by sea.","zh-TW":"貨物經由海運運送。"},{"en":"I am still at sea about the new policy.","zh-TW":"我對新政策還摸不著頭緒。"}]', '{"noun":"sea","adjective":"seaside","noun2":"seaport"}', NULL, 1, 5858, NULL),
(5859, 'sea freight', '/siː freɪt/', 'noun', '{"zh-TW":["海運貨物"],"en":["goods transported by sea"]}', NULL, 'ship by sea freight / sea freight schedule', '[{"en":"Sea freight is more economical for large shipments.","zh-TW":"海運對大宗貨物更為經濟。"},{"en":"The sea freight arrived on schedule with no damage.","zh-TW":"海運貨物按時到達，無損壞。"}]', NULL, NULL, 4, 5859, NULL),
(5860, 'sea level rise', '/siː ˈlɛvəl raɪz/', 'noun', '{"zh-TW":["海平面上升"],"en":["the increase in ocean levels caused by melting ice and warming"]}', NULL, 'address sea level rise / impact of sea level rise', '[{"en":"Sea level rise threatens coastal cities around the world.","zh-TW":"海平面上升威脅著世界各地的沿海城市。"},{"en":"Climate action is urgently needed to slow sea level rise.","zh-TW":"迫切需要氣候行動來減緩海平面上升。"}]', NULL, NULL, 5, 5860, NULL),
(5861, 'search engine optimization', '/sɜːrtʃ ˈendʒɪn ˌɒptɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["搜尋引擎優化"],"en":["techniques to improve a website ranking in organic search results"]}', NULL, 'invest in search engine optimization / search engine optimization strategy', '[{"en":"Search engine optimization increased organic traffic by 80%.","zh-TW":"搜尋引擎優化使自然流量增加了80%。"},{"en":"Content quality is the most important factor in search engine optimization.","zh-TW":"內容品質是搜尋引擎優化中最重要的因素。"}]', '{"abbreviation":"SEO"}', NULL, 5, 5861, NULL),
(5862, 'season', '/ˈsiːzən/', 'noun', '{"zh-TW":["季節；賽季"],"en":["one of the four periods of the year"]}', NULL, 'in season / off season', '[{"en":"Winter is my favorite season.","zh-TW":"冬天是我最喜歡的季節。"},{"en":"The team had a great season.","zh-TW":"這支球隊賽季表現出色。"}]', '{"adjective":"seasonal"}', NULL, 2, 5862, NULL),
(5863, 'seasonal demand', '/ˈsiːzənl dɪˈmɑːnd/', 'noun', '{"zh-TW":["季節性需求"],"en":["fluctuation in demand for a product or service based on the time of year"]}', NULL, 'manage seasonal demand / peak seasonal demand', '[{"en":"Retailers hire extra staff to manage seasonal demand during holidays.","zh-TW":"零售商在假期期間聘用額外員工來管理季節性需求。"},{"en":"Seasonal demand forecasting helps optimize inventory and staffing.","zh-TW":"季節性需求預測有助於優化庫存和人員配置。"}]', NULL, NULL, 5, 5863, NULL),
(5864, 'seasoning', '/ˈsiːzənɪŋ/', 'noun', '{"zh-TW":["調味料；調味"],"en":["salt, herbs, or spices added to food"]}', NULL, 'add seasoning / light seasoning', '[{"en":"The chef adjusted the seasoning before serving.","zh-TW":"主廚在上菜前調整了調味。"},{"en":"This dish requires very little seasoning.","zh-TW":"這道菜只需要很少的調味料。"}]', '{"verb":"season","adjective":"seasoned"}', NULL, 3, 5864, NULL),
(5865, 'seat', '/siːt/', 'noun', '{"zh-TW":["座位"],"en":["a place to sit"]}', NULL, 'take a seat / window seat', '[{"en":"Please take a seat.","zh-TW":"請坐。"},{"en":"I prefer a window seat on flights.","zh-TW":"搭飛機時我偏好靠窗的座位。"}]', '{"noun":"seat","verb":"seat","noun2":"seating"}', NULL, 1, 5865, NULL),
(5866, 'seat assignment', '/siːt əˈsaɪnmənt/', 'noun', '{"zh-TW":["座位分配"],"en":["the designation of a specific seat to a passenger"]}', NULL, 'request a seat assignment / change seat assignment', '[{"en":"You can select your seat assignment during check-in.","zh-TW":"您可以在辦理登機手續時選擇座位。"},{"en":"His seat assignment was changed at the last minute.","zh-TW":"他的座位在最後一刻被更換了。"}]', '{"verb":"assign"}', NULL, 5, 5866, NULL),
(5867, 'secondary market', '/ˈsekəndri ˈmɑːrkɪt/', 'noun', '{"zh-TW":["二級市場"],"en":["a market where previously issued securities are bought and sold"]}', NULL, 'trade on the secondary market / secondary market price / secondary market liquidity', '[{"en":"Investors can sell their shares on the secondary market.","zh-TW":"投資者可以在二級市場出售股票。"},{"en":"The secondary market provides liquidity for early investors.","zh-TW":"二級市場為早期投資者提供流動性。"}]', '{"antonym":"primary market"}', NULL, 5, 5867, NULL),
(5868, 'secondary offering', '/ˈsekəndəri ˈɒfərɪŋ/', 'noun', '{"zh-TW":["二次發行；增發"],"en":["the sale of additional shares by a listed company after its IPO"]}', NULL, 'complete a secondary offering / secondary offering proceeds', '[{"en":"The company raised 200 million through a secondary offering.","zh-TW":"公司通過二次發行籌集了2億元。"},{"en":"The secondary offering diluted existing shareholders by 5%.","zh-TW":"二次發行使現有股東的股份稀釋了5%。"}]', NULL, NULL, 5, 5868, NULL),
(5869, 'secondment', '/ˈsekəndmənt/', 'noun', '{"zh-TW":["借調；臨時派遣"],"en":["the temporary transfer of an employee to another role or organization"]}', NULL, 'secondment opportunity / on secondment / secondment agreement', '[{"en":"She went on a six-month secondment to the Singapore office.","zh-TW":"她被借調到新加坡辦公室工作六個月。"},{"en":"A secondment can broaden an employee''s skills and network.","zh-TW":"借調可以拓寬員工的技能和人際網絡。"}]', '{"verb":"second"}', NULL, 4, 5869, NULL),
(5870, 'secret', '/ˈsiːkrɪt/', 'noun', '{"zh-TW":["秘密"],"en":["something kept hidden"]}', NULL, 'trade secret / keep a secret', '[{"en":"That recipe is a trade secret.","zh-TW":"那個配方是商業機密。"},{"en":"The key to success is no secret.","zh-TW":"成功的關鍵不是秘密。"}]', '{"noun":"secret","adjective":"secret","noun2":"secrecy","adverb":"secretly"}', NULL, 2, 5870, NULL),
(5871, 'section', 'ˈsɛkʃən', 'noun', '{"zh-TW":["部分；章節","科室"],"en":["a distinct part of something","a department or subdivision"]}', NULL, 'first section/cross-section', '[{"en":"Please read the first section carefully.","zh-TW":"請仔細閱讀第一部分。"}]', '{"verb":"section","adjective":"sectional","adverb":"sectionly"}', NULL, 3, 5871, NULL),
(5872, 'sector', '/ˈsektər/', 'noun', '{"zh-TW":["部門；領域","行業"],"en":["a distinct area of activity; an industry"]}', NULL, 'private sector / public sector / financial sector', '[{"en":"The technology sector continues to grow rapidly.","zh-TW":"科技行業持續快速增長。"},{"en":"Both the public and private sectors are investing in AI.","zh-TW":"公私部門都在投資人工智慧。"}]', '{"noun":"sector"}', NULL, 2, 5872, 450),
(5873, 'secular', '/ˈsekjʊlər/', 'adjective', '{"zh-TW":["長期的；世俗的；非宗教的"],"en":["not connected with religious or spiritual matters; occurring over an extended period"]}', NULL, 'secular trend / secular stagnation / secular decline', '[{"en":"The secular decline in interest rates has compressed returns for fixed income investors.","zh-TW":"利率的長期下降壓縮了固定收益投資者的回報。"},{"en":"Secular stagnation describes a prolonged period of slow economic growth.","zh-TW":"長期停滯描述了一段持續緩慢的經濟增長時期。"}]', '{"adverb":"secularly","noun":"secularism"}', NULL, 3, 5873, NULL),
(5874, 'secularism', '/ˈsekjʊlərɪzəm/', 'noun', '{"zh-TW":["世俗主義；政教分離"],"en":["the principle of separation between religion and state or public life"]}', NULL, 'promote secularism / political secularism / secularism in education', '[{"en":"Secularism protects freedom of religion by keeping the state neutral.","zh-TW":"世俗主義通過保持國家中立來保護宗教自由。"},{"en":"The debate over secularism in public schools remains highly contested.","zh-TW":"關於公立學校世俗主義的辯論仍然極具爭議性。"}]', '{"adjective":"secular","adverb":"secularly"}', NULL, 4, 5874, NULL),
(5875, 'secure', '/sɪˈkjʊr/', 'adjective, verb', '{"zh-TW":["安全的；穩固的","獲得；確保"],"en":["safe from threat","to obtain or achieve"]}', NULL, 'secure a deal / secure environment / job security', '[{"en":"We secured a major contract with the client.","zh-TW":"我們與客戶簽下了一份大合約。"},{"en":"The building has a secure entrance.","zh-TW":"這棟建築有一個安全的入口。"}]', '{"noun":"security","verb":"secure","adjective":"secure, insecure","adverb":"securely"}', NULL, 2, 5875, 213),
(5876, 'secured creditor', '/sɪˈkjʊərd ˈkredɪtər/', 'noun', '{"zh-TW":["有擔保債權人"],"en":["a lender who holds collateral against a debt obligation"]}', NULL, 'rights of secured creditors / secured creditor priority', '[{"en":"Secured creditors have priority over unsecured creditors in insolvency.","zh-TW":"有擔保債權人在破產時優先於無擔保債權人。"},{"en":"The bank acted as a secured creditor with a charge over company assets.","zh-TW":"銀行作為有擔保債權人，對公司資產持有抵押權。"}]', '{"opposite":"unsecured creditor"}', NULL, 5, 5876, NULL),
(5877, 'secured debt', '/sɪˈkjʊərd det/', 'noun', '{"zh-TW":["有擔保債務"],"en":["debt backed by collateral that the lender can claim if the borrower defaults"]}', NULL, 'carry secured debt / secured debt obligation', '[{"en":"Secured debt is less risky for lenders because it is backed by assets.","zh-TW":"有擔保債務對貸款方風險較低，因為有資產擔保。"},{"en":"Secured debt holders have priority over unsecured creditors in bankruptcy.","zh-TW":"在破產時，有擔保債務持有人優先於無擔保債權人。"}]', '{"opposite":"unsecured debt"}', NULL, 4, 5877, NULL),
(5878, 'secured loan', '/sɪˈkjʊərd loʊn/', 'noun', '{"zh-TW":["有擔保貸款"],"en":["a loan backed by collateral that the lender can claim if repayment fails"]}', NULL, 'apply for a secured loan / secured loan interest rate', '[{"en":"The company obtained a secured loan using its property as collateral.","zh-TW":"公司以其物業作抵押獲得了有擔保貸款。"},{"en":"Secured loans typically offer lower interest rates than unsecured ones.","zh-TW":"有擔保貸款通常比無擔保貸款提供更低的利率。"}]', '{"opposite":"unsecured loan"}', NULL, 4, 5878, NULL),
(5879, 'securities', '/sɪˈkjʊərɪtiz/', 'noun', '{"zh-TW":["證券"],"en":["tradeable financial instruments including stocks and bonds"]}', NULL, 'invest in securities / trade securities / issue securities', '[{"en":"The fund invests in a mix of equities and fixed income securities.","zh-TW":"基金投資於股票和固定收益證券的組合。"},{"en":"Securities must be registered before they can be sold to the public.","zh-TW":"證券在向公眾出售前必須進行登記。"}]', '{"singular":"security","adjective":"secured"}', NULL, 4, 5879, NULL),
(5880, 'securitization', '/sɪˌkjʊərɪtɪˈzeɪʃən/', 'noun', '{"zh-TW":["資產證券化"],"en":["pooling financial assets and selling them as securities to investors"]}', NULL, 'mortgage securitization / asset securitization / securitization market', '[{"en":"Securitization allows banks to free up capital for new loans.","zh-TW":"資產證券化使銀行能夠釋放資本用於新貸款。"},{"en":"The securitization of subprime mortgages contributed to the financial crisis.","zh-TW":"次級抵押貸款的證券化加劇了金融危機。"}]', '{"verb":"securitize","adjective":"securitized"}', NULL, 5, 5880, NULL),
(5881, 'securitize', '/sɪˈkjʊərɪtaɪz/', 'verb', '{"zh-TW":["證券化"],"en":["to convert an asset or group of assets into a marketable security"]}', NULL, 'securitize loans / securitize mortgages / securitize receivables', '[{"en":"Banks securitize mortgage loans to free up capital for new lending.","zh-TW":"銀行將抵押貸款證券化以騰出資本用於新貸款。"},{"en":"The process of securitizing assets creates structured financial products.","zh-TW":"資產證券化過程創建了結構化金融產品。"}]', '{"noun":"securitization","adjective":"securitized"}', NULL, 4, 5881, NULL),
(5882, 'security badge', '/sɪˈkjʊərɪti bædʒ/', 'noun', '{"zh-TW":["安全通行證；識別徽章"],"en":["an ID card giving access to a secure area"]}', NULL, 'wear a security badge / security badge required', '[{"en":"All employees must wear their security badge at all times.","zh-TW":"所有員工必須隨時佩戴安全通行證。"},{"en":"Visitors are issued a temporary security badge at reception.","zh-TW":"訪客在接待處領取臨時安全通行證。"}]', NULL, NULL, 5, 5882, NULL),
(5883, 'security check', '/sɪˈkjʊrɪti tʃɛk/', 'noun', '{"zh-TW":["安全檢查"],"en":["the process of screening passengers at an airport"]}', NULL, 'pass a security check / security checkpoint', '[{"en":"Please remove your shoes at the security check.","zh-TW":"請在安全檢查時脫鞋。"},{"en":"Allow extra time for the security check at busy airports.","zh-TW":"在繁忙機場請預留安全檢查額外時間。"}]', NULL, NULL, 5, 5883, NULL),
(5884, 'sedative', '/ˈsedətɪv/', 'noun', '{"zh-TW":["鎮靜劑；安眠藥"],"en":["a drug that reduces excitement or anxiety and induces sleep"]}', NULL, 'prescribe a sedative / mild sedative / sedative effect', '[{"en":"The patient was given a sedative before the procedure to reduce anxiety.","zh-TW":"患者在手術前服用了鎮靜劑以減少焦慮。"},{"en":"Long-term use of sedatives can lead to dependency.","zh-TW":"長期使用鎮靜劑可能導致依賴性。"}]', '{"adjective":"sedative","verb":"sedate"}', NULL, 3, 5884, NULL),
(5885, 'sedimentation', '/ˌsedɪmenˈteɪʃən/', 'noun', '{"zh-TW":["沉積；沉積作用"],"en":["the process of matter settling to the bottom of a liquid"]}', NULL, 'natural sedimentation / rapid sedimentation / sedimentation rate', '[{"en":"Sedimentation in the reservoir reduced its water storage capacity over time.","zh-TW":"水庫中的沉積作用隨時間推移降低了其蓄水能力。"},{"en":"Scientists measure sedimentation rates to understand past environmental conditions.","zh-TW":"科學家測量沉積速率以了解過去的環境條件。"}]', '{"verb":"sediment","adjective":"sedimentary"}', NULL, 5, 5885, NULL),
(5886, 'see', 'siː', 'verb', '{"zh-TW":["看見；理解","確保"],"en":["to perceive with eyes","to understand"]}', NULL, 'see a problem/results', '[{"en":"I see your point clearly.","zh-TW":"我清楚地理解您的觀點。"}]', '{"noun":"sight","adjective":"sighted"}', NULL, 1, 5886, NULL),
(5887, 'seed funding', '/siːd ˈfʌndɪŋ/', 'noun', '{"zh-TW":["種子輪融資"],"en":["initial capital raised to start a new business"]}', NULL, 'raise seed funding / seed funding round / secure seed funding', '[{"en":"They raised $500,000 in seed funding to develop the app.","zh-TW":"他們籌集了50萬美元的種子輪融資來開發應用程式。"},{"en":"Seed funding typically comes from angel investors or accelerators.","zh-TW":"種子輪融資通常來自天使投資人或加速器。"}]', '{"noun":"seed investor"}', NULL, 4, 5887, NULL),
(5888, 'seek', '/siːk/', 'verb', '{"zh-TW":["尋求；追求","試圖"],"en":["to try to find or obtain","to attempt"]}', NULL, 'seek advice / seek approval / seek opportunities', '[{"en":"We are seeking qualified candidates for the position.","zh-TW":"我們正在尋找合格的職位候選人。"},{"en":"She sought advice from a financial consultant.","zh-TW":"她向財務顧問尋求建議。"}]', '{"noun":"seeker","verb":"seek"}', NULL, 1, 5888, NULL),
(5889, 'segment', '/ˈseɡmənt/', 'noun, verb', '{"zh-TW":["部分；區段","分割；區隔"],"en":["a part of something","to divide into parts"]}', NULL, 'market segment / customer segment / segment the market', '[{"en":"The luxury segment showed strong growth.","zh-TW":"奢侈品市場區隔顯示出強勁增長。"},{"en":"We segmented our customers by age group.","zh-TW":"我們按年齡層區隔了客戶。"}]', '{"noun":"segment, segmentation","verb":"segment"}', NULL, 3, 5889, 451),
(5890, 'segmentation', '/ˌseɡmənˈteɪʃən/', 'noun', '{"zh-TW":["分割；細分"],"en":["the division of a market or data into distinct groups"]}', NULL, 'market segmentation / customer segmentation / segmentation strategy', '[{"en":"Market segmentation allows companies to tailor products to specific customer needs.","zh-TW":"市場細分允許公司根據特定客戶需求定制產品。"},{"en":"Data segmentation improves the targeting accuracy of marketing campaigns.","zh-TW":"數據細分提高了行銷活動的定位準確性。"}]', '{"verb":"segment","adjective":"segmented"}', NULL, 4, 5890, NULL),
(5891, 'segregation of duties', '/ˌseɡrɪˈɡeɪʃən əv ˈdjuːtɪz/', 'noun', '{"zh-TW":["職責分離"],"en":["the division of critical tasks among different people to prevent fraud"]}', NULL, 'implement segregation of duties / segregation of duties control', '[{"en":"Segregation of duties requires different people to authorize and process payments.","zh-TW":"職責分離要求不同的人授權和處理付款。"},{"en":"Lack of segregation of duties is a major internal control weakness.","zh-TW":"缺乏職責分離是主要的內部控制薄弱環節。"}]', NULL, NULL, 5, 5891, NULL),
(5892, 'seize', '/siːz/', 'verb', '{"zh-TW":["抓住；奪取","沒收"],"en":["to take hold of suddenly","to confiscate"]}', NULL, 'seize an opportunity / seize control / seize assets', '[{"en":"You should seize this opportunity immediately.","zh-TW":"你應該立即抓住這個機會。"},{"en":"Authorities seized illegal goods at the border.","zh-TW":"當局在邊境沒收了非法貨物。"}]', '{"noun":"seizure","verb":"seize"}', NULL, 2, 5892, NULL),
(5893, 'select', '/sɪˈlekt/', 'verb, adjective', '{"zh-TW":["挑選；選擇","精選的"],"en":["to carefully choose","carefully chosen as the best"]}', NULL, 'select candidates / select from a list / select group', '[{"en":"Please select the most suitable option.","zh-TW":"請選擇最合適的選項。"},{"en":"A select group of investors was invited.","zh-TW":"一群精選的投資者受到了邀請。"}]', '{"noun":"selection","verb":"select","adjective":"selective, select"}', NULL, 2, 5893, 214),
(5894, 'self-assessment', '/ˌself əˈsesmənt/', 'noun', '{"zh-TW":["自我評估；自我評量"],"en":["evaluating one own performance, knowledge, or tax obligations"]}', NULL, 'complete a self-assessment / self-assessment process', '[{"en":"The annual self-assessment tax return is due by January 31.","zh-TW":"年度自我評估稅務申報在1月31日到期。"},{"en":"Self-assessment forms part of the 360-degree feedback process.","zh-TW":"自我評估是360度反饋流程的一部分。"}]', '{"verb":"self-assess","adjective":"self-assessed"}', NULL, 5, 5894, NULL),
(5895, 'self-efficacy', '/''self ˌefɪkəsi/', 'noun', '{"zh-TW":["自我效能感"],"en":["one''s belief in their own ability to succeed at specific tasks or achieve certain goals"]}', NULL, 'build self-efficacy / high self-efficacy / self-efficacy theory', '[{"en":"Students with high self-efficacy are more likely to persist through academic challenges.","zh-TW":"具有高自我效能感的學生更可能在學業挑戰中堅持下去。"},{"en":"Building self-efficacy in employees through achievable goals improves overall motivation.","zh-TW":"通過可實現的目標在員工中建立自我效能感可以提升整體動力。"}]', '{"adjective":"efficacious","noun2":"efficacy"}', NULL, 5, 5895, NULL),
(5896, 'self-guided', '/''selfˌɡaɪdɪd/', 'adjective', '{"zh-TW":["自助的；自行導覽的"],"en":["relating to travel or a tour conducted without a professional guide"]}', NULL, 'self-guided tour / self-guided walk / self-guided itinerary', '[{"en":"The museum offers a self-guided audio tour using a smartphone app.","zh-TW":"博物館提供使用智慧手機應用程式的自助語音導覽。"},{"en":"She preferred a self-guided approach so she could explore at her own pace.","zh-TW":"她偏好自助方式，這樣她可以按自己的節奏探索。"}]', NULL, NULL, 4, 5896, NULL),
(5897, 'self-regulation', '/ˌself ˌreɡjʊˈleɪʃən/', 'noun', '{"zh-TW":["自律；自我調節"],"en":["the ability of a body to control its own behavior without external intervention"]}', NULL, 'industry self-regulation / self-regulation mechanism / rely on self-regulation', '[{"en":"Critics argue that industry self-regulation is insufficient to protect consumers.","zh-TW":"批評者認為，行業自律不足以保護消費者。"},{"en":"Financial market self-regulation failed to prevent the 2008 banking crisis.","zh-TW":"金融市場自律未能阻止二○○八年的銀行業危機。"}]', '{"verb":"self-regulate","adjective":"self-regulated"}', NULL, 5, 5897, NULL),
(5898, 'sell', '/sɛl/', 'verb', '{"zh-TW":["賣；銷售"],"en":["to exchange for money"]}', NULL, 'best-selling / sell out', '[{"en":"This is our best-selling product.","zh-TW":"這是我們最暢銷的產品。"},{"en":"Tickets sold out in two hours.","zh-TW":"票兩小時內就賣完了。"}]', '{"verb":"sell","noun":"seller","noun2":"sale","noun3":"sales"}', NULL, 1, 5898, NULL),
(5899, 'selling price', '/ˈselɪŋ praɪs/', 'noun', '{"zh-TW":["售價；出售價格"],"en":["the price at which a good or service is sold to a customer"]}', NULL, 'set the selling price / adjust the selling price', '[{"en":"The selling price was raised by 10% after raw material costs increased.","zh-TW":"在原材料成本上漲後，售價提高了10%。"},{"en":"The selling price must cover costs and provide an acceptable profit margin.","zh-TW":"售價必須涵蓋成本並提供可接受的利潤率。"}]', NULL, NULL, 5, 5899, NULL);
