(6050, 'social innovation', '/ˈsəʊʃəl ˌɪnəˈveɪʃən/', 'noun', '{"zh-TW":["社會創新"],"en":["new approaches to social challenges that are more effective and sustainable"]}', NULL, 'promote social innovation / social innovation ecosystem / scale social innovation', '[{"en":"Social innovation can address challenges that neither government nor markets solve well.","zh-TW":"社會創新可以解決政府和市場都無法很好解決的挑戰。"},{"en":"The fellowship program supports entrepreneurs engaged in social innovation.","zh-TW":"獎學金計畫支持從事社會創新的創業者。"}]', NULL, NULL, 5, 6050, NULL),
(6051, 'social media', '/ˈsəʊʃəl ˈmiːdiə/', 'noun', '{"zh-TW":["社交媒體"],"en":["websites and apps enabling user interaction and content sharing"]}', NULL, 'post on social media / social media marketing', '[{"en":"Social media marketing has become essential for brands.","zh-TW":"社交媒體行銷已成為品牌的必要手段。"},{"en":"The post went viral on social media overnight.","zh-TW":"這篇帖子在一夜之間在社交媒體上瘋傳。"}]', NULL, NULL, 4, 6051, NULL),
(6052, 'social media marketing', '/ˈsoʊʃəl ˈmiːdiə ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["社群媒體行銷"],"en":["using social media platforms to promote products and engage audiences"]}', NULL, 'social media marketing strategy / social media marketing campaign', '[{"en":"Social media marketing drives brand awareness among younger consumers.","zh-TW":"社群媒體行銷在年輕消費者中提高了品牌知名度。"},{"en":"A consistent social media marketing presence builds trust over time.","zh-TW":"持續的社群媒體行銷存在隨時間建立信任。"}]', '{"noun":"social media marketer"}', NULL, 5, 6052, NULL),
(6053, 'social mobility', '/ˈsəʊʃəl məʊˈbɪlɪti/', 'noun', '{"zh-TW":["社會流動性"],"en":["the movement of individuals between different levels of social hierarchy"]}', NULL, 'upward social mobility / social mobility barriers / improve social mobility', '[{"en":"Education is traditionally seen as the primary driver of social mobility.","zh-TW":"教育傳統上被視為社會流動性的主要驅動力。"},{"en":"Social mobility has stalled in many countries over the past two decades.","zh-TW":"過去二十年，許多國家的社會流動性已陷入停滯。"}]', '{"adjective":"socially mobile"}', NULL, 5, 6053, NULL),
(6054, 'social responsibility', '/ˈsoʊʃəl rɪˌspɒnsɪˈbɪlɪti/', 'noun', '{"zh-TW":["社會責任"],"en":["a company''s commitment to act ethically and contribute to social well-being"]}', NULL, 'fulfill social responsibility / corporate social responsibility', '[{"en":"The company''s social responsibility program funds community schools.","zh-TW":"公司的社會責任計劃為社區學校提供資金。"},{"en":"Consumers increasingly choose brands with strong social responsibility.","zh-TW":"消費者越來越傾向於選擇具有強大社會責任感的品牌。"}]', '{"abbreviation":"CSR"}', NULL, 5, 6054, NULL),
(6055, 'social stratification', '/ˈsəʊʃəl ˌstrætɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["社會分層"],"en":["the hierarchical arrangement of individuals or groups in a society"]}', NULL, 'social stratification system / rigid social stratification / analyze social stratification', '[{"en":"Social stratification affects access to education, healthcare, and opportunity.","zh-TW":"社會分層影響到教育、醫療保健和機會的獲得。"},{"en":"Sociologists study social stratification to understand inequality patterns.","zh-TW":"社會學家研究社會分層以理解不平等模式。"}]', '{"adjective":"socially stratified"}', NULL, 5, 6055, NULL),
(6056, 'socialization', '/ˌsəʊʃəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["社會化"],"en":["the process by which individuals learn the values and norms of their society"]}', NULL, 'primary socialization / secondary socialization / socialization process', '[{"en":"Family is the primary agent of socialization for young children.","zh-TW":"家庭是幼兒社會化的主要媒介。"},{"en":"Schools play a crucial role in the secondary socialization of children.","zh-TW":"學校在兒童的次級社會化中發揮著至關重要的作用。"}]', '{"verb":"socialize","adjective":"socialized"}', NULL, 5, 6056, NULL),
(6057, 'socially responsible investing', '/ˈsoʊʃəli rɪˈspɒnsɪbəl ɪnˈvestɪŋ/', 'noun', '{"zh-TW":["社會責任投資"],"en":["an investment strategy incorporating environmental, social, and governance criteria"]}', NULL, 'adopt socially responsible investing / socially responsible investing fund', '[{"en":"Pension funds increasingly adopt socially responsible investing principles.","zh-TW":"養老基金越來越多地採用社會責任投資原則。"},{"en":"Socially responsible investing excludes companies in tobacco or weapons industries.","zh-TW":"社會責任投資排除了煙草或武器行業的公司。"}]', '{"abbreviation":"SRI","synonym":"ESG investing"}', NULL, 5, 6057, NULL),
(6058, 'society', 'səˈsaɪəti', 'noun', '{"zh-TW":["社會；社團","協會"],"en":["the community of people","an organization"]}', NULL, 'modern society/civil society', '[{"en":"Technology plays a huge role in modern society.","zh-TW":"技術在現代社會中扮演著重要角色。"}]', '{"adjective":"social","adverb":"socially"}', NULL, 3, 6058, NULL),
(6059, 'socioeconomic', '/''səʊsiəʊˌiːkəˌnɒmɪk/', 'adjective', '{"zh-TW":["社會經濟的；社經的"],"en":["relating to or concerned with the interaction of social and economic factors"]}', NULL, 'socioeconomic status / socioeconomic inequality / socioeconomic background', '[{"en":"Students from lower socioeconomic backgrounds often have less access to educational resources.","zh-TW":"來自較低社會經濟背景的學生通常獲得的教育資源較少。"},{"en":"The study examined how socioeconomic factors affect health outcomes in urban communities.","zh-TW":"這項研究考察了社會經濟因素如何影響城市社區的健康結果。"}]', '{"adverb":"socioeconomically","noun":"socioeconomics"}', NULL, 5, 6059, NULL),
(6060, 'soft', '/sɒft/', 'adjective', '{"zh-TW":["軟的；柔和的"],"en":["not hard","gentle"]}', NULL, 'soft skills / software', '[{"en":"Soft skills are as important as technical skills.","zh-TW":"軟實力和技術能力一樣重要。"},{"en":"The soft launch went smoothly.","zh-TW":"軟性上市進行順利。"}]', '{"adjective":"soft","verb":"soften","noun":"software","adverb":"softly"}', NULL, 1, 6060, NULL),
(6061, 'soft loan', '/sɒft loʊn/', 'noun', '{"zh-TW":["優惠貸款；軟貸款"],"en":["a loan with a low interest rate or subsidized terms, typically from a government"]}', NULL, 'apply for a soft loan / soft loan program', '[{"en":"The government offered soft loans to encourage small business investment.","zh-TW":"政府提供優惠貸款以鼓勵小企業投資。"},{"en":"Soft loans are often used to fund infrastructure in developing countries.","zh-TW":"優惠貸款通常用於在發展中國家為基礎設施融資。"}]', NULL, NULL, 3, 6061, NULL),
(6062, 'soft power', '/sɒft ˈpaʊər/', 'noun', '{"zh-TW":["軟實力"],"en":["the ability to influence others through culture, values, and diplomacy rather than force"]}', NULL, 'exercise soft power / soft power strategy / use soft power', '[{"en":"Cultural exports such as films and music are tools of a country''s soft power.","zh-TW":"電影和音樂等文化出口是一個國家軟實力的工具。"},{"en":"Education exchanges build soft power by creating positive relationships with future leaders.","zh-TW":"教育交流通過與未來領導人建立正面關係來增強軟實力。"}]', NULL, NULL, 4, 6062, NULL),
(6063, 'soft skills', '/sɒft skɪlz/', 'noun', '{"zh-TW":["軟技能；軟實力"],"en":["interpersonal and social skills valuable in a work environment"]}', NULL, 'develop soft skills / soft skills training', '[{"en":"Communication and teamwork are essential soft skills.","zh-TW":"溝通和團隊合作是重要的軟技能。"},{"en":"The training program focused on developing soft skills among managers.","zh-TW":"培訓計劃專注於培養管理者的軟技能。"}]', NULL, NULL, 4, 6063, NULL),
(6064, 'software', '/ˈsɒftwɛr/', 'noun', '{"zh-TW":["軟體"],"en":["programs used by a computer"]}', NULL, 'software update / software engineer', '[{"en":"Install the latest software update.","zh-TW":"安裝最新的軟體更新。"},{"en":"She develops educational software.","zh-TW":"她開發教育軟體。"}]', NULL, NULL, 3, 6064, 458),
(6065, 'software as a service', '/ˈsɒftweər æz ə ˈsɜːrvɪs/', 'noun', '{"zh-TW":["軟體即服務"],"en":["a software delivery model where applications are hosted and accessed online"]}', NULL, 'adopt SaaS / SaaS solution / SaaS subscription', '[{"en":"The company switched to a SaaS model to reduce IT overhead.","zh-TW":"公司轉向SaaS模式以降低IT管理費用。"},{"en":"SaaS applications are accessible from any device with internet access.","zh-TW":"SaaS應用程式可從任何有網路連接的設備存取。"}]', '{"abbreviation":"SaaS"}', NULL, 5, 6065, NULL),
(6066, 'software update', '/ˈsɒftwɛər ˈʌpdeɪt/', 'noun', '{"zh-TW":["軟體更新"],"en":["a new version of software to fix bugs or add features"]}', NULL, 'install a software update / automatic software update', '[{"en":"Install the latest software update for improved security.","zh-TW":"安裝最新的軟體更新以提升安全性。"},{"en":"Software updates often include important security patches.","zh-TW":"軟體更新通常包括重要的安全修補程式。"}]', NULL, NULL, 5, 6066, NULL),
(6067, 'soil erosion', '/sɔɪl ɪˈrəʊʒən/', 'noun', '{"zh-TW":["土壤侵蝕"],"en":["the wearing away of topsoil by water, wind, or human activity"]}', NULL, 'prevent soil erosion / soil erosion control / soil erosion damage', '[{"en":"Cover crops reduce soil erosion by protecting bare ground.","zh-TW":"覆蓋作物通過保護裸露地面來減少土壤侵蝕。"},{"en":"Soil erosion reduces agricultural productivity and pollutes waterways.","zh-TW":"土壤侵蝕降低農業生產力並污染水道。"}]', '{"verb":"erode","adjective":"eroded"}', NULL, 4, 6067, NULL),
(6068, 'solar energy', '/ˈsəʊlər ˈɛnərdʒi/', 'noun', '{"zh-TW":["太陽能"],"en":["energy from the sun converted into heat or electricity"]}', NULL, 'generate solar energy / solar energy panel', '[{"en":"The building generates its own electricity using solar energy.","zh-TW":"大樓使用太陽能自行發電。"},{"en":"Solar energy has become increasingly cost-competitive.","zh-TW":"太陽能的成本競爭力越來越強。"}]', NULL, NULL, 4, 6068, NULL),
(6069, 'sole', '/soʊl/', 'adjective', '{"zh-TW":["唯一的；獨有的"],"en":["one and only; exclusive"]}', NULL, 'sole purpose / sole responsibility / sole proprietor', '[{"en":"She is the sole owner of the company.","zh-TW":"她是公司的唯一所有人。"},{"en":"The sole purpose of the meeting was budget approval.","zh-TW":"會議的唯一目的是預算審批。"}]', '{"adjective":"sole","adverb":"solely"}', NULL, 1, 6069, NULL),
(6070, 'sole proprietor', '/soʊl prəˈpraɪɪtər/', 'noun', '{"zh-TW":["獨資企業主"],"en":["a person who owns and operates a business without partners"]}', NULL, 'register as sole proprietor / sole proprietor taxes', '[{"en":"As a sole proprietor, all profits and losses are personal income.","zh-TW":"作為獨資企業主，所有利潤和損失都是個人收入。"},{"en":"A sole proprietor has unlimited personal liability for business debts.","zh-TW":"獨資企業主對商業債務承擔無限個人責任。"}]', NULL, NULL, 5, 6070, NULL),
(6071, 'sole proprietorship', '/soʊl prəˈpraɪɪtərʃɪp/', 'noun', '{"zh-TW":["獨資企業；個人獨資企業"],"en":["a business owned and operated by a single person with unlimited liability"]}', NULL, 'operate as a sole proprietorship / sole proprietorship registration', '[{"en":"A sole proprietorship offers simplicity but involves personal liability.","zh-TW":"獨資企業結構簡單，但涉及個人責任。"},{"en":"Many small business owners start as a sole proprietorship.","zh-TW":"許多小企業主以獨資企業形式起步。"}]', NULL, NULL, 5, 6071, NULL),
(6072, 'sole trader', '/soʊl ˈtreɪdər/', 'noun', '{"zh-TW":["個體戶；自營業者"],"en":["a self-employed person who runs a business as an individual"]}', NULL, 'register as a sole trader / sole trader tax', '[{"en":"As a sole trader, all profits are taxed as personal income.","zh-TW":"作為個體戶，所有利潤作為個人收入徵稅。"},{"en":"A sole trader has full control but unlimited personal liability.","zh-TW":"個體戶擁有完全控制權但承擔無限個人責任。"}]', NULL, NULL, 4, 6072, NULL),
(6073, 'solicit', '/səˈlɪsɪt/', 'verb', '{"zh-TW":["徵求；請求"],"en":["to ask for something earnestly"]}', NULL, 'solicit feedback / solicit bids / solicit opinions', '[{"en":"The company solicited feedback from its customers.","zh-TW":"公司向客戶徵求回饋。"},{"en":"We solicited bids from multiple vendors.","zh-TW":"我們向多家供應商徵求報價。"}]', '{"noun":"solicitation","verb":"solicit"}', NULL, 3, 6073, 721),
(6074, 'solidify', '/səˈlɪdɪfaɪ/', 'verb', '{"zh-TW":["鞏固；使堅固"],"en":["to make or become firm or strong"]}', NULL, 'solidify one''s position / solidify partnerships', '[{"en":"The merger solidified the company''s market position.","zh-TW":"合併鞏固了公司的市場地位。"},{"en":"We aim to solidify our partnerships in the region.","zh-TW":"我們旨在鞏固在該地區的合作夥伴關係。"}]', '{"noun":"solidarity","verb":"solidify","adjective":"solid"}', NULL, 3, 6074, NULL),
(6075, 'solution', 'səˈluːʃən', 'noun', '{"zh-TW":["解決方案；答案","溶液"],"en":["a way of solving a problem","an answer to a question"]}', NULL, 'find a solution/cost-effective solution', '[{"en":"We need a cost-effective solution.","zh-TW":"我們需要一個具有成本效益的解決方案。"}]', '{"verb":"solve","adjective":"solvable"}', NULL, 3, 6075, 217),
(6076, 'solve', '/sɑːlv/', 'verb', '{"zh-TW":["解決；解答"],"en":["to find an answer to a problem"]}', NULL, 'solve a problem / solve an issue / problem-solving', '[{"en":"We need to solve this issue before launch.","zh-TW":"我們需要在上線前解決這個問題。"},{"en":"The team solved the technical challenge quickly.","zh-TW":"團隊很快解決了技術挑戰。"}]', '{"noun":"solution","verb":"solve","adjective":"solvable, unsolved"}', NULL, 2, 6076, NULL),
(6077, 'solvency', '/ˈsɒlvənsi/', 'noun', '{"zh-TW":["償債能力"],"en":["the ability to meet long-term financial obligations"]}', NULL, 'maintain solvency / solvency ratio / test of solvency', '[{"en":"The bank passed the solvency test with comfortable margins.","zh-TW":"銀行以舒適的空間通過了償債能力測試。"},{"en":"Declining sales raised concerns about the firm''s solvency.","zh-TW":"銷售額下降引發了對公司償債能力的擔憂。"}]', '{"adjective":"solvent","antonym":"insolvent"}', NULL, 3, 6077, NULL),
(6078, 'solvency ratio', '/ˈsɒlvənsi ˈreɪʃioʊ/', 'noun', '{"zh-TW":["償付能力比率"],"en":["a measure of a company ability to meet long-term financial obligations"]}', NULL, 'calculate solvency ratio / improve solvency ratio', '[{"en":"A solvency ratio above 20% indicates strong financial health.","zh-TW":"20%以上的償付能力比率表明財務狀況良好。"},{"en":"Regulators require insurance firms to maintain a minimum solvency ratio.","zh-TW":"監管機構要求保險公司維持最低償付能力比率。"}]', NULL, NULL, 5, 6078, NULL),
(6079, 'solvent', '/ˈsɒlvənt/', 'adjective', '{"zh-TW":["有償還能力的；有清償能力的"],"en":["having assets in excess of liabilities; able to pay debts"]}', NULL, 'financially solvent / remain solvent / technically solvent', '[{"en":"A company must remain solvent to avoid entering bankruptcy proceedings.","zh-TW":"公司必須保持償債能力，以避免進入破產程序。"},{"en":"The bank was declared solvent following an independent audit of its balance sheet.","zh-TW":"在對其資產負債表進行獨立審計後，銀行被宣告具有償付能力。"}]', '{"noun":"solvency"}', NULL, 3, 6079, NULL),
(6080, 'somewhat', '/ˈsʌmwɑːt/', 'adverb', '{"zh-TW":["有點；稍微"],"en":["to some extent; a little"]}', NULL, 'somewhat different / somewhat surprising / somewhat difficult', '[{"en":"The results were somewhat disappointing.","zh-TW":"結果有點令人失望。"},{"en":"The process is somewhat more complex than expected.","zh-TW":"這個流程比預期的稍微複雜一些。"}]', '{"adverb":"somewhat"}', NULL, 3, 6080, NULL),
(6081, 'sommelier', '/ˌsɒməˈljeɪ/', 'noun', '{"zh-TW":["侍酒師"],"en":["a wine expert who advises on wine in a restaurant"]}', NULL, 'consult the sommelier / ask the sommelier', '[{"en":"The sommelier recommended a local wine with the fish dish.","zh-TW":"侍酒師推薦了一款配魚料理的當地葡萄酒。"},{"en":"A skilled sommelier enhances the dining experience.","zh-TW":"熟練的侍酒師提升了用餐體驗。"}]', NULL, NULL, 3, 6081, NULL),
(6082, 'son', '/sʌn/', 'noun', '{"zh-TW":["兒子"],"en":["a male child"]}', NULL, 'only son / son-in-law', '[{"en":"His son joined the family business.","zh-TW":"他的兒子加入了家族企業。"},{"en":"My son-in-law works in accounting.","zh-TW":"我的女婿在會計部門工作。"}]', '{"noun":"son"}', NULL, 1, 6082, NULL),
(6083, 'soon', '/suːn/', 'adverb', '{"zh-TW":["很快；不久"],"en":["in a short time"]}', NULL, 'as soon as / sooner or later', '[{"en":"We will launch as soon as possible.","zh-TW":"我們會盡快推出。"},{"en":"Sooner or later, the truth will come out.","zh-TW":"遲早真相會水落石出。"}]', '{"adverb":"soon","adjective":"soon"}', NULL, 1, 6083, NULL),
(6084, 'sophisticated', '/səˈfɪstɪkeɪtɪd/', 'adjective', '{"zh-TW":["精密的；複雜的","世故的"],"en":["highly developed and complex","having refined taste"]}', NULL, 'sophisticated technology / sophisticated system / sophisticated approach', '[{"en":"The company uses sophisticated data analytics.","zh-TW":"公司使用精密的數據分析。"},{"en":"This requires a more sophisticated approach.","zh-TW":"這需要更精密的方法。"}]', '{"noun":"sophistication","adjective":"sophisticated"}', NULL, 5, 6084, NULL),
(6085, 'sophistry', '/ˈsɒfɪstri/', 'noun', '{"zh-TW":["詭辯；詭辯術"],"en":["the use of clever but false arguments"]}', NULL, 'engage in sophistry / resort to sophistry / mere sophistry', '[{"en":"His defense relied on sophistry rather than genuine evidence.","zh-TW":"他的辯護依賴詭辯而非真實證據。"},{"en":"The audience quickly saw through the speaker''s sophistry.","zh-TW":"聽眾很快看穿了演講者的詭辯。"}]', '{"noun":"sophist","adjective":"sophistic"}', NULL, 3, 6085, NULL),
(6086, 'sophomore', '/ˈsɒfəmɔːr/', 'noun', '{"zh-TW":["大二學生"],"en":["a second-year student"]}', NULL, 'sophomore year / sophomore album', '[{"en":"She''s a sophomore in college.","zh-TW":"她是大二學生。"},{"en":"His sophomore year was the hardest.","zh-TW":"他的大二是最辛苦的。"}]', NULL, NULL, 3, 6086, NULL),
(6087, 'sorry', '/ˈsɒri/', 'adjective', '{"zh-TW":["抱歉的"],"en":["feeling regret or apology"]}', NULL, 'sorry for / sorry to hear', '[{"en":"I am sorry for the inconvenience.","zh-TW":"很抱歉造成不便。"},{"en":"Sorry to hear about the delay.","zh-TW":"很遺憾聽到延遲的消息。"}]', '{"adjective":"sorry"}', NULL, 2, 6087, NULL),
(6088, 'sort', 'sɔːrt', 'verb', '{"zh-TW":["整理；排序","分類"],"en":["to put in order","to separate into groups"]}', NULL, 'sort files/sort by date', '[{"en":"Please sort the files alphabetically.","zh-TW":"請按字母順序整理文件。"}]', '{"noun":"sort, sorting","adjective":"sorted"}', NULL, 1, 6088, NULL),
(6089, 'sound', '/saʊnd/', 'noun', '{"zh-TW":["【主要意義-名詞】聲音；聲響","【次要意義-形容詞】健全的；穩固的；合理的；可靠的","【次要意義-副詞】徹底地（如 sound asleep）"],"en":["[primary - noun] vibrations that travel through air and are heard","[secondary - adjective] in good condition; reliable and sensible","[secondary - adverb] deeply and completely"]}', NULL, 'sound advice / sound investment / sound asleep / of sound mind', '[{"en":"The board agreed that it was a sound investment decision.","zh-TW":"董事會認為這是一個穩健的投資決定。"},{"en":"The auditor confirmed that the company finances were perfectly sound.","zh-TW":"審計師確認公司財務狀況完全健全。"},{"en":"He was sound asleep when the emergency call came through.","zh-TW":"當緊急電話打來時，他睡得正熟。"}]', '{"adverb":"soundly","noun":"soundness"}', '形容詞 sound = 「穩健的/健全的/合理的」，sound advice（正確建議）、sound investment（穩健投資）、sound judgment（合理判斷）是 TOEIC 財務和管理文章的高頻表達。', 2, 6089, NULL),
(6090, 'soundscape', '/ˈsaʊndˌskeɪp/', 'noun', '{"zh-TW":["音景；聲音環境"],"en":["the sonic environment of a place or piece of music"]}', NULL, 'create a soundscape / immersive soundscape / natural soundscape', '[{"en":"The film''s soundscape was as important as its visual imagery.","zh-TW":"電影的音景與其視覺影像同等重要。"},{"en":"Field recording artists document the disappearing soundscapes of nature.","zh-TW":"田野錄音藝術家記錄著正在消失的自然音景。"}]', NULL, NULL, 4, 6090, NULL),
(6091, 'sour', '/''saʊər/', 'adjective', '{"zh-TW":["酸的；酸味的"],"en":["having an acid taste like lemon or vinegar"]}', NULL, 'sour taste / sour cream / turn sour', '[{"en":"The yogurt had a pleasantly sour taste that balanced the sweetness.","zh-TW":"優格有一種令人愉快的酸味，平衡了甜味。"},{"en":"The unripe mango was too sour to eat on its own.","zh-TW":"這個未熟的芒果太酸，不適合單獨食用。"}]', NULL, NULL, 1, 6091, NULL),
(6092, 'source', '/sɔːrs/', 'noun, verb', '{"zh-TW":["來源；出處","採購；尋找來源"],"en":["a place from which something comes","to obtain from a particular place"]}', NULL, 'reliable source / source of income / source materials', '[{"en":"Tourism is the main source of income for the region.","zh-TW":"旅遊業是該地區的主要收入來源。"},{"en":"We source our materials from local suppliers.","zh-TW":"我們從當地供應商採購材料。"}]', '{"noun":"source","verb":"source, outsource"}', NULL, 2, 6092, NULL),
(6093, 'source of funds', '/sɔːrs əv fʌndz/', 'noun', '{"zh-TW":["資金來源"],"en":["where the money used in a transaction originates from"]}', NULL, 'verify the source of funds / disclose the source of funds', '[{"en":"Banks must verify the source of funds for large transactions.","zh-TW":"銀行必須核實大額交易的資金來源。"},{"en":"A clear source of funds declaration is required for compliance.","zh-TW":"合規要求提供明確的資金來源聲明。"}]', NULL, NULL, 5, 6093, NULL),
(6094, 'sourcing', '/ˈsɔːrsɪŋ/', 'noun', '{"zh-TW":["採購；尋源"],"en":["finding and selecting suppliers for goods or services"]}', NULL, 'strategic sourcing / global sourcing / sourcing process', '[{"en":"The sourcing team identified five potential suppliers for the component.","zh-TW":"採購團隊為該零件識別了五個潛在供應商。"},{"en":"Offshore sourcing reduced material costs by 30%.","zh-TW":"境外採購將材料成本降低了30%。"}]', '{"verb":"source","adjective":"sourced"}', NULL, 3, 6094, NULL),
(6095, 'sourcing strategy', '/ˈsɔːrsɪŋ ˈstrætədʒi/', 'noun', '{"zh-TW":["採購策略"],"en":["a plan for identifying and selecting suppliers for goods or services"]}', NULL, 'develop a sourcing strategy / sourcing strategy review', '[{"en":"The sourcing strategy focused on reducing supplier concentration risk.","zh-TW":"採購策略專注於降低供應商集中風險。"},{"en":"Global sourcing strategies can reduce costs but increase complexity.","zh-TW":"全球採購策略可以降低成本但增加複雜性。"}]', NULL, NULL, 5, 6095, NULL),
(6096, 'souvenir', '/''suːvəˌnɪər/', 'noun', '{"zh-TW":["紀念品"],"en":["a thing kept as a reminder of a person, place, or event visited"]}', NULL, 'buy a souvenir / souvenir shop / collect souvenirs', '[{"en":"She bought a small figurine as a souvenir from Paris.","zh-TW":"她在巴黎買了一個小塑像作為紀念品。"},{"en":"The souvenir shop near the museum sold local handicrafts.","zh-TW":"博物館附近的紀念品店出售當地手工藝品。"}]', NULL, NULL, 3, 6096, NULL),
(6097, 'sovereignty', '/ˈsɒvrənti/', 'noun', '{"zh-TW":["主權；最高統治權"],"en":["the authority of a state to govern itself without interference"]}', NULL, 'national sovereignty / state sovereignty / challenge sovereignty', '[{"en":"National sovereignty limits the ability of international bodies to enforce rules.","zh-TW":"國家主權限制了國際機構執行規則的能力。"},{"en":"The agreement respected the sovereignty of each nation to set its own policies.","zh-TW":"該協議尊重每個國家制定本國政策的主權。"}]', '{"adjective":"sovereign","adverb":"sovereignly"}', NULL, 4, 6097, NULL),
(6098, 'spa', '/''spɑː/', 'noun', '{"zh-TW":["水療中心；溫泉療養地"],"en":["a place with mineral spring water believed to have health-giving properties; a facility for health and beauty treatments"]}', NULL, 'visit a spa / spa treatment / luxury spa', '[{"en":"She booked a spa day to relax after months of hard work.","zh-TW":"她預訂了一天的水療服務，在幾個月辛苦工作後放鬆身心。"},{"en":"The resort''s spa offered massages, facials, and hydrotherapy treatments.","zh-TW":"度假村的水療中心提供按摩、臉部護理和水療治療。"}]', NULL, NULL, 1, 6098, NULL),
(6099, 'space', '/speɪs/', 'noun', '{"zh-TW":["空間；太空"],"en":["an area available for use","the universe beyond Earth"]}', NULL, 'office space / co-working space', '[{"en":"We are looking for new office space.","zh-TW":"我們正在尋找新的辦公空間。"},{"en":"Co-working spaces are popular with startups.","zh-TW":"共同工作空間很受新創公司歡迎。"}]', '{"noun":"space","adjective":"spacious","verb":"space"}', NULL, 2, 6099, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6100, 'span', '/spæn/', 'noun, verb', '{"zh-TW":["跨度；時間段","跨越"],"en":["the full extent of something","to extend across"]}', NULL, 'time span / attention span / span a period', '[{"en":"The project spans a period of three years.","zh-TW":"該專案跨越三年時間。"},{"en":"The average attention span is decreasing.","zh-TW":"平均注意力持續時間正在減少。"}]', '{"noun":"span","verb":"span"}', NULL, 1, 6100, NULL),
(6101, 'span of control', '/spæn əv kənˈtroʊl/', 'noun', '{"zh-TW":["管理幅度"],"en":["the number of subordinates a manager directly supervises"]}', NULL, 'widen the span of control / narrow the span of control', '[{"en":"Reducing layers increased the span of control for each manager.","zh-TW":"減少管理層次增加了每位管理者的管理幅度。"},{"en":"A wide span of control requires strong communication and delegation skills.","zh-TW":"寬廣的管理幅度需要強大的溝通和授權技巧。"}]', NULL, NULL, 5, 6101, NULL),
(6102, 'spare', '/sper/', 'adjective, verb', '{"zh-TW":["【主要意義-動詞】省去；免除；撥出（時間）","【次要意義-形容詞】多餘的；備用的；空閒的；瘦的","【次要意義-名詞】備用品；備胎"],"en":["[primary - verb] to make something available; to refrain from harming","[secondary - adjective] extra, not currently in use; lean and thin","[secondary - noun] a spare part or tire"]}', NULL, 'spare time / spare room / spare tire / spare no expense / to spare', '[{"en":"Could you spare a few minutes to review this proposal?","zh-TW":"您能撥出幾分鐘時間審閱這份提案嗎？"},{"en":"We have a spare conference room available on the third floor.","zh-TW":"三樓有一個空餘的會議室可供使用。"},{"en":"The company spared no expense in redesigning the headquarters.","zh-TW":"公司不惜重金重新設計總部。"}]', '{"adverb":"sparingly","adjective":"sparing"}', 'spare 最常見陷阱是形容詞用法「備用的/多餘的」及片語 spare no expense（不惜代價），TOEIC 閱讀中常見描述資源調度或設施的語境。', 2, 6102, NULL),
(6103, 'sparse', '/''spɑːrs/', 'adjective', '{"zh-TW":["稀少的；稀疏的"],"en":["thinly dispersed or scattered; not plentiful or abundant"]}', NULL, 'sparse population / sparse vegetation / sparse data', '[{"en":"The desert is characterized by sparse vegetation and extreme temperatures.","zh-TW":"沙漠的特點是植被稀疏和極端溫度。"},{"en":"Her notes were sparse and failed to capture all the important points from the lecture.","zh-TW":"她的筆記很稀少，未能記錄講座中所有的重要觀點。"}]', '{"adverb":"sparsely","noun":"sparseness"}', NULL, 2, 6103, NULL),
(6104, 'speak', '/spiːk/', 'verb', '{"zh-TW":["說話；發言"],"en":["to talk","to address an audience"]}', NULL, 'speak up / so to speak', '[{"en":"Please speak up if you disagree.","zh-TW":"如果不同意請大聲說出來。"},{"en":"She will speak at the conference.","zh-TW":"她將在會議上演講。"}]', '{"verb":"speak","noun":"speaker","noun2":"speech"}', NULL, 2, 6104, NULL),
(6105, 'special purpose vehicle', '/ˈspeʃəl ˈpɜːrpəs ˈviːɪkəl/', 'noun', '{"zh-TW":["特殊目的公司"],"en":["a separate legal entity created for a specific financial transaction or project"]}', NULL, 'set up a special purpose vehicle / special purpose vehicle structure', '[{"en":"The real estate fund used a special purpose vehicle for each property.","zh-TW":"房地產基金為每個物業使用了一個特殊目的公司。"},{"en":"A special purpose vehicle isolates financial risk from the parent company.","zh-TW":"特殊目的公司將財務風險從母公司中隔離出來。"}]', '{"abbreviation":"SPV"}', NULL, 5, 6105, NULL),
(6106, 'specialist', '/ˈspeʃəlɪst/', 'noun', '{"zh-TW":["專家；專業人員"],"en":["a person with expert knowledge in a particular field"]}', NULL, 'HR specialist / marketing specialist / technical specialist', '[{"en":"The company hired a cybersecurity specialist to strengthen its defenses.","zh-TW":"公司聘請了網路安全專家加強防禦。"},{"en":"She became a specialist in supply chain optimization.","zh-TW":"她成為供應鏈優化方面的專家。"}]', '{"plural":"specialists","adjective":"specialized"}', NULL, 4, 6106, NULL),
(6107, 'specialist referral', '/ˈspɛʃəlɪst rɪˈfɜːrəl/', 'noun', '{"zh-TW":["專科轉診"],"en":["a recommendation to see a specialist doctor"]}', NULL, 'obtain a specialist referral / specialist referral letter', '[{"en":"She obtained a specialist referral to see a cardiologist.","zh-TW":"她獲得了轉診心臟科專科醫生的推介信。"},{"en":"Insurance may require a specialist referral before coverage applies.","zh-TW":"保險可能要求專科轉診後才提供承保。"}]', NULL, NULL, 5, 6107, NULL),
(6108, 'specialty', '/ˈspɛʃəlti/', 'noun', '{"zh-TW":["特色菜；招牌菜"],"en":["a food item for which a place is particularly known"]}', NULL, 'house specialty / regional specialty', '[{"en":"The lobster bisque is the restaurant''s specialty.","zh-TW":"龍蝦濃湯是餐廳的招牌菜。"},{"en":"Try the local specialty when visiting a new city.","zh-TW":"造訪新城市時嘗試當地特色菜。"}]', '{"adjective":"special"}', NULL, 3, 6108, NULL),
(6109, 'species extinction', '/ˈspiːʃiːz ɪkˈstɪŋkʃən/', 'noun', '{"zh-TW":["物種滅絕"],"en":["the dying out of a species of plant or animal"]}', NULL, 'prevent species extinction / species extinction crisis / rate of species extinction', '[{"en":"Human activity is driving species extinction at an alarming rate.","zh-TW":"人類活動正在以令人震驚的速度推動物種滅絕。"},{"en":"Species extinction reduces biodiversity and weakens ecosystem functions.","zh-TW":"物種滅絕降低生物多樣性並削弱生態系統功能。"}]', '{"verb":"extinguish","adjective":"extinct"}', NULL, 5, 6109, NULL),
(6110, 'specific', '/spɪˈsɪfɪk/', 'adjective', '{"zh-TW":["具體的；明確的","特定的"],"en":["clearly defined or identified","particular"]}', NULL, 'specific requirements / specific details / industry-specific', '[{"en":"Please provide specific examples.","zh-TW":"請提供具體的例子。"},{"en":"The instructions are very specific.","zh-TW":"指示非常明確。"}]', '{"noun":"specification, specifics","adjective":"specific","adverb":"specifically"}', NULL, 3, 6110, NULL),
(6111, 'specification', '/ˌspesɪfɪˈkeɪʃn/', 'noun', '{"zh-TW":["規格；規範"],"en":["a detailed description of requirements"]}', NULL, 'technical specifications / meet specifications / product specifications', '[{"en":"The product must meet the client''s specifications.","zh-TW":"產品必須符合客戶的規格。"},{"en":"Please review the technical specifications document.","zh-TW":"請審閱技術規格文件。"}]', '{"noun":"specification","verb":"specify","adjective":"specific"}', NULL, 5, 6111, 459),
(6112, 'specify', '/ˈspesɪfaɪ/', 'verb', '{"zh-TW":["指定；詳細說明"],"en":["to state explicitly or in detail"]}', '{"suffix":{"text":"-ify","meaning":"使..."}}', 'specify requirements / as specified / specify the terms', '[{"en":"The contract specifies the delivery date.","zh-TW":"合約中明確指定了交貨日期。"},{"en":"Please specify your preferred payment method.","zh-TW":"請指定您偏好的付款方式。"}]', '{"noun":"specification","verb":"specify","adjective":"specific, specified"}', NULL, 3, 6112, 218),
(6113, 'spectator', '/ˈspɛkteɪtər/', 'noun', '{"zh-TW":["觀眾；旁觀者"],"en":["a person who watches a game or event"]}', NULL, 'spectator sport / thousands of spectators', '[{"en":"Thousands of spectators filled the stadium.","zh-TW":"數千名觀眾坐滿了體育場。"},{"en":"Football is a popular spectator sport.","zh-TW":"足球是一項受歡迎的觀賞性運動。"}]', NULL, NULL, 3, 6113, NULL),
(6114, 'spectator sport', '/''spekteɪtər spɔːrt/', 'noun', '{"zh-TW":["觀賞性運動；觀眾運動"],"en":["a sport that attracts a large number of spectators to watch"]}', NULL, 'popular spectator sport / major spectator sport', '[{"en":"Soccer is the most popular spectator sport in the world.","zh-TW":"足球是世界上最受歡迎的觀賞性運動。"},{"en":"The stadium holds eighty thousand fans, making it ideal for large spectator sports.","zh-TW":"球場可容納八萬名球迷，使其成為大型觀賞性運動的理想場所。"}]', NULL, NULL, 5, 6114, NULL),
(6115, 'speculate', '/ˈspekjuleɪt/', 'verb', '{"zh-TW":["推測；猜測","投機"],"en":["to form a theory without firm evidence","to invest in risky ventures"]}', NULL, 'speculate on / speculate about / speculate in stocks', '[{"en":"Analysts speculate that the merger will proceed.","zh-TW":"分析師推測合併將繼續進行。"},{"en":"He speculated in the stock market.","zh-TW":"他在股市進行投機。"}]', '{"noun":"speculation, speculator","verb":"speculate","adjective":"speculative"}', NULL, 3, 6115, NULL),
(6116, 'speculation', '/ˌspekjʊˈleɪʃən/', 'noun', '{"zh-TW":["投機；推測"],"en":["the activity of buying assets hoping for profit from short-term price changes"]}', NULL, 'financial speculation / currency speculation / market speculation', '[{"en":"Currency speculation can destabilize a country''s exchange rate.","zh-TW":"貨幣投機可能破壞一個國家匯率的穩定。"},{"en":"The housing bubble was fueled by speculation rather than genuine end-user demand.","zh-TW":"房地產泡沫是由投機而非真實的最終用戶需求推動的。"}]', '{"verb":"speculate","adjective":"speculative","noun2":"speculator"}', NULL, 4, 6116, NULL),
(6117, 'speculative', '/ˈspekjʊlətɪv/', 'adjective', '{"zh-TW":["投機的；推測的"],"en":["based on conjecture rather than knowledge; involving financial speculation"]}', NULL, 'speculative investment / speculative bubble / highly speculative', '[{"en":"Speculative investments in cryptocurrencies resulted in significant losses for many retail investors.","zh-TW":"對加密貨幣的投機性投資給許多散戶投資者造成了重大損失。"},{"en":"The analyst offered a speculative forecast based on limited early data.","zh-TW":"分析師根據有限的早期數據提出了推測性預測。"}]', '{"adverb":"speculatively","verb":"speculate","noun":"speculation"}', NULL, 4, 6117, NULL),
(6118, 'speculative investment', '/ˈspekjʊlətɪv ɪnˈvestmənt/', 'noun', '{"zh-TW":["投機性投資"],"en":["an investment with high risk made in the hope of large returns"]}', NULL, 'make a speculative investment / high-risk speculative investment', '[{"en":"The company avoided speculative investments in favor of stable bonds.","zh-TW":"公司避免了投機性投資，轉而選擇穩定的債券。"},{"en":"Speculative investments can generate high returns but also large losses.","zh-TW":"投機性投資可以帶來高回報，但也可能帶來巨大損失。"}]', NULL, NULL, 5, 6118, NULL),
(6119, 'speech impediment', '/''spiːtʃ ɪmˌpedɪmənt/', 'noun', '{"zh-TW":["語言障礙；口吃"],"en":["a difficulty in speaking that prevents normal fluent communication"]}', NULL, 'overcome a speech impediment / speech impediment treatment / speech impediment therapy', '[{"en":"Speech therapy helped her overcome a speech impediment and gain confidence.","zh-TW":"語言治療幫助她克服了語言障礙，獲得了自信。"},{"en":"Advances in speech therapy have helped many children overcome speech impediments.","zh-TW":"語言治療的進步幫助了許多兒童克服語言障礙。"}]', NULL, NULL, 5, 6119, NULL),
(6120, 'speed', '/spiːd/', 'noun', '{"zh-TW":["速度"],"en":["how fast something moves"]}', NULL, 'at full speed / speed up', '[{"en":"We need to speed up production.","zh-TW":"我們需要加快生產速度。"},{"en":"The project is moving at full speed.","zh-TW":"專案正在全速推進。"}]', '{"noun":"speed","verb":"speed","adjective":"speedy","adverb":"speedily"}', NULL, 2, 6120, NULL),
(6121, 'speed agility quickness', '/''spiːd əˌdʒɪlɪti ˌkwɪknəs/', 'noun', '{"zh-TW":["速度敏捷性訓練"],"en":["a type of training that develops an athlete''s ability to move rapidly and change direction effectively"]}', NULL, 'speed agility quickness training / speed agility quickness drill / speed agility quickness program', '[{"en":"Speed agility quickness drills are fundamental for basketball and soccer players.","zh-TW":"速度敏捷性訓練對籃球和足球運動員至關重要。"},{"en":"The coach incorporated speed agility quickness sessions into the weekly training schedule.","zh-TW":"教練將速度敏捷性訓練課程納入每週訓練計劃。"}]', NULL, NULL, 5, 6121, NULL),
(6122, 'spend', '/spɛnd/', 'verb', '{"zh-TW":["花費；消費"],"en":["to pay money","to use time"]}', NULL, 'spend money / spend time', '[{"en":"We spend 20% of revenue on R&D.","zh-TW":"我們將營收的20%用於研發。"},{"en":"Don''t spend too much time on this.","zh-TW":"不要在這上面花太多時間。"}]', '{"verb":"spend","noun":"spending","noun2":"expenditure"}', NULL, 2, 6122, NULL),
(6123, 'spend analysis', '/spend əˈnæləsɪs/', 'noun', '{"zh-TW":["支出分析"],"en":["reviewing all company purchases to identify savings opportunities"]}', NULL, 'conduct a spend analysis / spend analysis tool', '[{"en":"A spend analysis identified 500000 in potential annual savings.","zh-TW":"支出分析識別了每年50萬元的潛在節省。"},{"en":"Spend analysis is the foundation of a cost reduction initiative.","zh-TW":"支出分析是成本降低計劃的基礎。"}]', NULL, NULL, 5, 6123, NULL),
(6124, 'sphere', '/sfɪr/', 'noun', '{"zh-TW":["領域；範圍","球體"],"en":["an area of activity or influence","a round solid shape"]}', NULL, 'sphere of influence / public sphere / political sphere', '[{"en":"The decision falls within her sphere of influence.","zh-TW":"這個決定屬於她的影響範圍。"},{"en":"The company expanded into new spheres of business.","zh-TW":"公司擴展到新的商業領域。"}]', '{"noun":"sphere","adjective":"spherical"}', NULL, 2, 6124, NULL),
(6125, 'spice', '/''spaɪs/', 'noun', '{"zh-TW":["香料；調味品"],"en":["a strong-flavored or aromatic substance of plant origin used to flavor food"]}', NULL, 'add spice / exotic spice / spice blend', '[{"en":"Turmeric is a spice used widely in South Asian cooking for its color and health benefits.","zh-TW":"薑黃是南亞烹飪中廣泛使用的香料，因其顏色和健康功效而受到重視。"},{"en":"The chef created a unique spice blend that gave the dish a complex, warming flavor.","zh-TW":"廚師調製了獨特的香料混合物，賦予菜肴複雜溫暖的風味。"}]', '{"verb":"spice","adjective":"spicy"}', NULL, 2, 6125, NULL),
(6126, 'spin-off', '/ˈspɪn ɒf/', 'noun', '{"zh-TW":["分拆；子公司獨立上市"],"en":["a new independent company created from a division of an existing company"]}', NULL, 'create a spin-off / spin-off company', '[{"en":"The tech division was spun off as a separate listed company.","zh-TW":"技術部門被分拆為一家獨立的上市公司。"},{"en":"Spin-offs allow each business to pursue strategies more suited to their sector.","zh-TW":"分拆允許每個業務追求更適合其行業的策略。"}]', '{"verb":"spin off"}', NULL, 3, 6126, NULL),
(6127, 'spinoff', '/ˈspɪnɒf/', 'noun', '{"zh-TW":["分拆；衍生公司"],"en":["a new company created by separating part of an existing company"]}', NULL, 'spinoff company / corporate spinoff', '[{"en":"The spinoff allowed each business to focus on its core.","zh-TW":"分拆讓每個業務能夠專注於其核心。"},{"en":"Shareholders received shares in the spinoff entity.","zh-TW":"股東獲得了分拆實體的股份。"}]', '{"verb":"spin off"}', NULL, 3, 6127, NULL),
(6128, 'sponsor', '/ˈspɑːnsər/', 'noun, verb', '{"zh-TW":["贊助者；贊助商","贊助"],"en":["a person or company that pays for an event","to financially support"]}', NULL, 'corporate sponsor / sponsor an event / main sponsor', '[{"en":"The event was sponsored by a major bank.","zh-TW":"活動由一家大型銀行贊助。"},{"en":"We are looking for sponsors for the conference.","zh-TW":"我們正在尋找會議的贊助商。"}]', '{"noun":"sponsor, sponsorship","verb":"sponsor"}', NULL, 3, 6128, 460),
(6129, 'sporadic', '/''spəˈrædɪk/', 'adjective', '{"zh-TW":["零星的；偶發的"],"en":["occurring at irregular intervals or only in a few places; scattered or isolated"]}', NULL, 'sporadic attacks / sporadic growth / sporadic outages', '[{"en":"The company experienced sporadic disruptions to its online service.","zh-TW":"公司對其在線服務經歷了零星的中斷。"},{"en":"Progress was sporadic in the early months, but it accelerated after the first quarter.","zh-TW":"在最初幾個月進展零星，但在第一季度之後加速了。"}]', '{"adverb":"sporadically"}', NULL, 3, 6129, NULL),
(6130, 'sport', '/spɔːrt/', 'verb, noun, adjective', '{"zh-TW":["【主要意義】體育運動；娛樂消遣","【次要意義-動詞】炫耀地穿戴；誇示","【次要意義-名詞】光明磊落的人；有運動精神的人"],"en":["[primary] athletic activity or game","[secondary - verb] to wear or display something proudly or noticeably","[secondary - noun] a person who accepts defeat or teasing cheerfully"]}', NULL, 'sport a new hairstyle / sport a badge / be a good sport', '[{"en":"She sported a brand new designer handbag at the meeting.","zh-TW":"她在會議上炫耀地提著一個全新的設計師手提包。"},{"en":"He was a good sport about losing the competition.","zh-TW":"他輸了比賽後表現得很有運動精神。"},{"en":"The new employee sported a confident smile on his first day.","zh-TW":"新員工在第一天上班時臉上掛著自信的微笑。"}]', '{"noun":"sports, sportsmanship","adjective":"sporting, sporty"}', '動詞用法 sport = 炫耀地展示，常出現在描述外貌或穿著的語境中，TOEIC 閱讀常見陷阱。', 2, 6130, NULL),
(6131, 'sportsmanship', '/''spɔːrtsmənʃɪp/', 'noun', '{"zh-TW":["體育精神；運動精神"],"en":["fair and generous behavior or treatment of others in sports"]}', NULL, 'good sportsmanship / display sportsmanship / exemplary sportsmanship', '[{"en":"Shaking hands after the match is a sign of good sportsmanship.","zh-TW":"比賽後握手是良好體育精神的表現。"},{"en":"The coach emphasized sportsmanship as much as winning.","zh-TW":"教練同樣強調體育精神和獲勝的重要性。"}]', '{"noun":"sportsman"}', NULL, 5, 6131, NULL),
(6132, 'sportsmanship award', '/''spɔːrtsmənʃɪp əˌwɔːrd/', 'noun', '{"zh-TW":["體育精神獎"],"en":["an award given to an athlete who demonstrates exceptional sportsmanship"]}', NULL, 'receive a sportsmanship award / sportsmanship award winner', '[{"en":"He was honored with the tournament''s sportsmanship award for his fair play.","zh-TW":"他因公平競技精神而獲得了錦標賽的體育精神獎。"},{"en":"The sportsmanship award recognizes players who compete with integrity and respect.","zh-TW":"體育精神獎表彰以誠信和尊重競技的球員。"}]', NULL, NULL, 5, 6132, NULL),
(6133, 'spot', '/spɑːt/', 'noun, verb', '{"zh-TW":["地點；位置","發現；注意到"],"en":["a particular place","to notice or identify"]}', NULL, 'on the spot / spot a trend / weak spot', '[{"en":"She spotted an error in the financial report.","zh-TW":"她發現了財務報告中的一個錯誤。"},{"en":"The manager made a decision on the spot.","zh-TW":"經理當場做出了決定。"}]', '{"noun":"spot","verb":"spot"}', NULL, 1, 6133, NULL),
(6134, 'spot price', '/spɒt praɪs/', 'noun', '{"zh-TW":["即期價格；現貨價格"],"en":["the current market price for immediate purchase and delivery"]}', NULL, 'trade at the spot price / spot price volatility', '[{"en":"The spot price of oil rose to 90 dollars per barrel.","zh-TW":"原油即期價格漲至每桶90美元。"},{"en":"Buyers prefer spot price purchases when the market is declining.","zh-TW":"當市場下跌時，買方偏好以即期價格購買。"}]', '{"opposite":"forward price"}', NULL, 4, 6134, NULL),
(6135, 'spot rate', '/spɒt reɪt/', 'noun', '{"zh-TW":["即期匯率；即時利率"],"en":["the current exchange or interest rate for immediate settlement"]}', NULL, 'convert at the spot rate / spot rate fluctuation', '[{"en":"The invoice was converted at the spot rate on the payment date.","zh-TW":"發票在付款日以即期匯率換算。"},{"en":"Currency hedges allow companies to avoid spot rate volatility.","zh-TW":"貨幣對沖允許企業避免即期匯率波動。"}]', NULL, NULL, 3, 6135, NULL),
(6136, 'spread', '/spred/', 'verb, noun', '{"zh-TW":["擴散；傳播","擴展；差價"],"en":["to extend over a larger area","the extent or range of something"]}', NULL, 'spread awareness / spread across / spread the risk', '[{"en":"The company spread its operations across Asia.","zh-TW":"公司將業務擴展至亞洲各地。"},{"en":"We need to spread the investment risk.","zh-TW":"我們需要分散投資風險。"}]', '{"noun":"spread","verb":"spread"}', NULL, 2, 6136, NULL),
(6137, 'sprint', '/sprɪnt/', 'noun', '{"zh-TW":["衝刺；衝刺週期"],"en":["a short, time-boxed period in agile development to complete specific tasks"]}', NULL, 'run a sprint / sprint planning / sprint review / two-week sprint', '[{"en":"Each sprint lasts two weeks in the team''s agile process.","zh-TW":"在團隊的敏捷流程中，每個衝刺持續兩週。"},{"en":"The team completed all sprint goals ahead of schedule.","zh-TW":"團隊提前完成了所有衝刺目標。"}]', '{"verb":"sprint","adjective":"sprint-based"}', NULL, 2, 6137, NULL),
(6138, 'sprint finish', '/''sprɪnt ˌfɪnɪʃ/', 'noun', '{"zh-TW":["最後衝刺"],"en":["a final burst of speed at the end of a race"]}', NULL, 'make a sprint finish / strong sprint finish / impressive sprint finish', '[{"en":"His powerful sprint finish secured first place in the 1500-meter race.","zh-TW":"他強勁的最後衝刺在1500公尺賽跑中確保了第一名。"},{"en":"She was known for her devastating sprint finish in the final hundred meters.","zh-TW":"她因在最後一百公尺的毀滅性最後衝刺而聞名。"}]', NULL, NULL, 5, 6138, NULL),
(6139, 'sprint interval', '/''sprɪnt ˌɪntəvəl/', 'noun', '{"zh-TW":["短跑間歇；衝刺訓練"],"en":["a training method involving short periods of maximum-effort sprinting alternating with rest"]}', NULL, 'do sprint intervals / sprint interval protocol / add sprint intervals', '[{"en":"Sprint intervals improved his running speed more quickly than long-distance training.","zh-TW":"短跑間歇比長距離訓練更快地提高了他的跑步速度。"},{"en":"The training plan includes three sessions of sprint intervals per week.","zh-TW":"訓練計劃包括每週三次短跑間歇訓練。"}]', NULL, NULL, 5, 6139, NULL),
(6140, 'spurious', '/ˈspjʊəriəs/', 'adjective', '{"zh-TW":["偽造的；虛假的"],"en":["not being what it appears to be; false or misleading"]}', NULL, 'spurious correlation / spurious argument / spurious data', '[{"en":"The report excluded spurious data points from the analysis.","zh-TW":"報告從分析中排除了虛假的數據點。"},{"en":"His qualifications were later discovered to be spurious.","zh-TW":"他的資格後來被發現是偽造的。"}]', '{"adverb":"spuriously","noun":"spuriousness"}', NULL, 3, 6140, NULL),
(6141, 'SQL', '/ˌes kjuː ˈel/', 'noun', '{"zh-TW":["銷售合格潛在客戶"],"en":["sales qualified lead; a prospect evaluated as ready for a direct sales approach"]}', NULL, 'convert to SQL / SQL pipeline / track SQLs', '[{"en":"Sales reps focus their efforts on SQLs to maximize conversion.","zh-TW":"銷售代表將精力集中在銷售合格潛在客戶上以最大化轉換。"},{"en":"The SQL rate improved after tightening the qualification criteria.","zh-TW":"收緊資格標準後，銷售合格潛在客戶率有所提高。"}]', '{"full form":"sales qualified lead"}', NULL, 1, 6141, NULL),
(6142, 'squat', '/''skwɒt/', 'noun', '{"zh-TW":["深蹲；蹲"],"en":["an exercise in which you lower the body by bending the knees and hips while keeping the back straight"]}', NULL, 'do squats / squat exercise / barbell squat', '[{"en":"Squats are one of the most effective exercises for strengthening the legs and core.","zh-TW":"深蹲是增強腿部和核心力量最有效的運動之一。"},{"en":"She added one hundred squats to her daily workout routine.","zh-TW":"她在每日鍛煉計劃中增加了一百個深蹲。"}]', '{"verb":"squat"}', NULL, 2, 6142, NULL),
(6143, 'squeeze margin', '/skwiːz ˈmɑːrdʒɪn/', 'verb', '{"zh-TW":["壓縮利潤率"],"en":["to reduce profit margins through rising costs or competitive pricing pressure"]}', NULL, 'squeeze margins / margin squeeze', '[{"en":"Retailers had their margins squeezed by rising logistics costs.","zh-TW":"零售商的利潤率因不斷上升的物流成本而受到壓縮。"},{"en":"Intense competition continued to squeeze margins across the sector.","zh-TW":"激烈的競爭繼續壓縮整個行業的利潤率。"}]', '{"noun":"margin squeeze"}', NULL, 5, 6143, NULL),
(6144, 'stabilize', '/ˈsteɪbəlaɪz/', 'verb', '{"zh-TW":["穩定；使穩定"],"en":["to make or become steady"]}', NULL, 'stabilize prices / stabilize the economy / stabilize the situation', '[{"en":"The government took measures to stabilize the currency.","zh-TW":"政府採取措施穩定貨幣。"},{"en":"Prices have finally stabilized after months of volatility.","zh-TW":"經過數月的波動，價格終於穩定下來。"}]', '{"noun":"stability, stabilization","verb":"stabilize","adjective":"stable"}', NULL, 3, 6144, 722),
(6145, 'stable', '/ˈsteɪbl/', 'adjective', '{"zh-TW":["穩定的；穩固的"],"en":["not likely to change; firmly established"]}', NULL, 'stable economy / stable income / financially stable', '[{"en":"The economy has remained relatively stable.","zh-TW":"經濟保持相對穩定。"},{"en":"A stable income is important for loan approval.","zh-TW":"穩定的收入對貸款審批很重要。"}]', '{"noun":"stability","verb":"stabilize","adjective":"stable, unstable","adverb":"stably"}', NULL, 2, 6145, NULL),
(6146, 'stack overflow', '/stæk ˈəʊvərfləʊ/', 'noun', '{"zh-TW":["堆疊溢出"],"en":["an error that occurs when the call stack exceeds its maximum size"]}', NULL, 'cause a stack overflow / stack overflow error / handle stack overflow', '[{"en":"Recursive functions without proper base cases can cause a stack overflow.","zh-TW":"沒有適當基本案例的遞迴函數可能導致堆疊溢出。"},{"en":"The stack overflow bug was traced to an infinite loop in the parser.","zh-TW":"堆疊溢出錯誤被追蹤到解析器中的無限循環。"}]', NULL, NULL, 5, 6146, NULL),
(6147, 'stadium', '/ˈsteɪdiəm/', 'noun', '{"zh-TW":["體育場"],"en":["a large area for sports events with seats around it"]}', NULL, 'football stadium / stadium tour', '[{"en":"The stadium holds 80,000 people.","zh-TW":"這座體育場可容納八萬人。"},{"en":"The new stadium was built last year.","zh-TW":"新體育場去年建成。"}]', NULL, NULL, 3, 6147, NULL),
(6148, 'staff', '/stæf/', 'noun, verb', '{"zh-TW":["員工；職員","配備人員"],"en":["the people who work for an organization","to provide with workers"]}', NULL, 'staff members / staff training / fully staffed', '[{"en":"All staff must attend the safety briefing.","zh-TW":"所有員工都必須參加安全簡報。"},{"en":"The office is fully staffed during business hours.","zh-TW":"辦公室在營業時間有完整的人員配置。"}]', '{"noun":"staff, staffing","verb":"staff"}', NULL, 2, 6148, 461),
(6149, 'staff productivity', '/stɑːf prəˌdʌkˈtɪvɪti/', 'noun', '{"zh-TW":["員工生產力"],"en":["the output per employee over a given period"]}', NULL, 'measure staff productivity / improve staff productivity', '[{"en":"Flexible work arrangements increased staff productivity.","zh-TW":"彈性工作安排提高了員工生產力。"},{"en":"Staff productivity metrics include output per hour and error rates.","zh-TW":"員工生產力指標包括每小時產出和錯誤率。"}]', NULL, NULL, 5, 6149, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6150, 'staff turnover', '/stɑːf ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["員工流動率"],"en":["the rate at which employees leave and are replaced within an organization"]}', NULL, 'reduce staff turnover / high staff turnover', '[{"en":"A high staff turnover is costly and disrupts operations.","zh-TW":"高員工流動率成本高昂並擾亂運營。"},{"en":"Improved working conditions helped reduce staff turnover by 20%.","zh-TW":"改善工作條件幫助將員工流動率降低了20%。"}]', NULL, NULL, 5, 6150, NULL),
(6151, 'staff turnover rate', '/stɑːf ˈtɜːrnoʊvər reɪt/', 'noun', '{"zh-TW":["員工離職率"],"en":["the percentage of employees who leave an organization within a period"]}', NULL, 'reduce staff turnover rate / monitor staff turnover rate', '[{"en":"A high staff turnover rate is costly due to recruitment and training.","zh-TW":"由於招募和培訓成本，高員工離職率代價高昂。"},{"en":"Improving work culture helped lower the staff turnover rate.","zh-TW":"改善工作文化有助於降低員工離職率。"}]', NULL, NULL, 5, 6151, NULL),
(6152, 'staffing', '/ˈstæfɪŋ/', 'noun', '{"zh-TW":["人員配置；招募"],"en":["the process of hiring and placing workers in an organization"]}', NULL, 'staffing agency / staffing levels / staffing needs', '[{"en":"The project required a rapid increase in staffing levels.","zh-TW":"該項目需要迅速增加人員配置。"},{"en":"Staffing agencies provide temporary workers on short notice.","zh-TW":"人力仲介公司能在短時間內提供臨時工作人員。"}]', '{"verb":"staff","noun":"staff"}', NULL, 3, 6152, NULL),
(6153, 'staffing agency', '/ˈstɑːfɪŋ ˈeɪdʒənsi/', 'noun', '{"zh-TW":["人力資源機構；人才派遣機構"],"en":["an organization that provides temporary or permanent workers"]}', NULL, 'hire through a staffing agency / staffing agency contract', '[{"en":"The company used a staffing agency to fill temporary positions.","zh-TW":"公司通過人力資源機構填補臨時職位。"},{"en":"A staffing agency handles recruitment and payroll for temps.","zh-TW":"人力資源機構負責臨時員工的招聘和薪資。"}]', NULL, NULL, 5, 6153, NULL),
(6154, 'stage', '/steɪdʒ/', 'noun, verb', '{"zh-TW":["階段；時期","舉辦；籌劃"],"en":["a point in a process","to organize and present"]}', NULL, 'at this stage / early stage / stage an event', '[{"en":"The project is still in the early stages.","zh-TW":"專案仍處於早期階段。"},{"en":"The company staged a product launch event.","zh-TW":"公司舉辦了一場產品發布活動。"}]', '{"noun":"stage","verb":"stage"}', NULL, 2, 6154, NULL),
(6155, 'stagnant', '/ˈstæɡnənt/', 'adjective', '{"zh-TW":["停滯的；不景氣的"],"en":["showing no activity or growth"]}', NULL, 'stagnant economy / stagnant wages / stagnant market', '[{"en":"Wages have remained stagnant for years.","zh-TW":"薪資已停滯多年。"},{"en":"The stagnant market offers few opportunities.","zh-TW":"停滯的市場提供很少的機會。"}]', '{"noun":"stagnation","verb":"stagnate","adjective":"stagnant"}', NULL, 3, 6155, NULL),
(6156, 'stagnation', '/stæɡˈneɪʃən/', 'noun', '{"zh-TW":["停滯；不景氣"],"en":["a situation characterized by little or no growth or development"]}', NULL, 'economic stagnation / wage stagnation / period of stagnation', '[{"en":"Japan experienced a decade of economic stagnation in the 1990s.","zh-TW":"日本在1990年代經歷了十年的經濟停滯。"},{"en":"Wage stagnation despite rising productivity has increased inequality.","zh-TW":"儘管生產力提高，工資停滯加劇了不平等。"}]', '{"verb":"stagnate","adjective":"stagnant"}', NULL, 4, 6156, NULL),
(6157, 'stake', '/steɪk/', 'noun', '{"zh-TW":["股份；利害關係","賭注"],"en":["a share or interest in a business","something risked"]}', NULL, 'at stake / stakeholder / have a stake in', '[{"en":"Millions of dollars are at stake.","zh-TW":"數百萬美元面臨風險。"},{"en":"She has a 20% stake in the company.","zh-TW":"她擁有公司20%的股份。"}]', '{"noun":"stake, stakeholder"}', NULL, 2, 6157, NULL),
(6158, 'stakeholder', '/ˈsteɪkhoʊldər/', 'noun', '{"zh-TW":["利害關係人"],"en":["a person with an interest or concern in something"]}', NULL, 'key stakeholders / stakeholder engagement / stakeholder management', '[{"en":"All stakeholders were consulted before the decision.","zh-TW":"做決定之前諮詢了所有利害關係人。"},{"en":"Stakeholder engagement is crucial for project success.","zh-TW":"利害關係人參與對專案成功至關重要。"}]', '{"noun":"stakeholder, stake"}', NULL, 4, 6158, 934),
(6159, 'stakeholder analysis', '/ˈsteɪkhoʊldər əˈnæləsɪs/', 'noun', '{"zh-TW":["利害關係人分析"],"en":["a process of identifying and assessing the influence and interests of stakeholders"]}', NULL, 'conduct stakeholder analysis / stakeholder analysis matrix', '[{"en":"A stakeholder analysis was completed at the project initiation stage.","zh-TW":"在項目啟動階段完成了利害關係人分析。"},{"en":"Stakeholder analysis helps prioritize engagement and communication efforts.","zh-TW":"利害關係人分析幫助優先考慮參與和溝通工作。"}]', NULL, NULL, 5, 6159, NULL),
(6160, 'stakeholder capitalism', '/ˈsteɪkˌhəʊldər ˈkæpɪtəlɪzəm/', 'noun', '{"zh-TW":["利益相關者資本主義"],"en":["a model of capitalism in which corporations serve all stakeholders, not just shareholders"]}', NULL, 'embrace stakeholder capitalism / stakeholder capitalism model / debate stakeholder capitalism', '[{"en":"Stakeholder capitalism argues that businesses should balance profits with social and environmental responsibility.","zh-TW":"利益相關者資本主義認為，企業應在利潤與社會及環境責任之間取得平衡。"},{"en":"The Business Roundtable''s 2019 statement endorsed stakeholder capitalism as a guiding corporate principle.","zh-TW":"商業圓桌會議二○一九年的聲明認可了利益相關者資本主義作為指導公司原則。"}]', NULL, NULL, 5, 6160, NULL),
(6161, 'stakeholder communication', '/ˈsteɪkhoʊldər kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["利害關係人溝通"],"en":["the process of keeping all interested parties informed and engaged"]}', NULL, 'improve stakeholder communication / regular stakeholder communication', '[{"en":"Regular stakeholder communication prevents misunderstandings.","zh-TW":"定期的利害關係人溝通防止了誤解。"},{"en":"The project manager sent weekly updates as part of stakeholder communication.","zh-TW":"項目經理作為利害關係人溝通的一部分發送了每週更新。"}]', NULL, NULL, 5, 6161, NULL),
(6162, 'stakeholder engagement', '/ˈsteɪkhoʊldər ɪnˈɡeɪdʒmənt/', 'noun', '{"zh-TW":["利害關係人參與"],"en":["the process of involving relevant parties in decision-making"]}', NULL, 'improve stakeholder engagement / stakeholder engagement plan', '[{"en":"Stakeholder engagement ensured the policy change had broad support.","zh-TW":"利害關係人參與確保了政策變更獲得廣泛支持。"},{"en":"A stakeholder engagement plan was developed before the project launched.","zh-TW":"項目啟動前制定了利害關係人參與計劃。"}]', NULL, NULL, 5, 6162, NULL),
(6163, 'stakeholder management', '/ˈsteɪkˌhəʊldər ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["利害關係人管理"],"en":["the process of managing relationships with those affected by a project"]}', NULL, 'effective stakeholder management / stakeholder management plan', '[{"en":"Effective stakeholder management is critical for project success.","zh-TW":"有效的利害關係人管理對項目成功至關重要。"},{"en":"Regular updates are key to good stakeholder management.","zh-TW":"定期更新是良好的利害關係人管理的關鍵。"}]', NULL, NULL, 5, 6163, NULL),
(6164, 'stakeholder meeting', '/''steɪkˌhəʊldər ˌmiːtɪŋ/', 'noun', '{"zh-TW":["利害關係人會議；利益相關者會議"],"en":["a meeting that involves all parties who have an interest in a project or decision"]}', NULL, 'organize a stakeholder meeting / stakeholder meeting agenda / productive stakeholder meeting', '[{"en":"A stakeholder meeting was held to address concerns about the new development project.","zh-TW":"舉行了利害關係人會議，以解決對新開發項目的關切。"},{"en":"Regular stakeholder meetings ensure everyone stays informed and aligned on project goals.","zh-TW":"定期的利害關係人會議確保每個人都了解情況並與項目目標保持一致。"}]', '{"noun":"stakeholder"}', NULL, 5, 6164, NULL),
(6165, 'stakeholder report', '/ˈsteɪkˌhəʊldər rɪˈpɔːrt/', 'noun', '{"zh-TW":["利害關係人報告"],"en":["a report prepared for parties with an interest in an organization"]}', NULL, 'prepare a stakeholder report / distribute stakeholder report', '[{"en":"The annual stakeholder report summarizes company performance.","zh-TW":"年度利害關係人報告總結了公司的表現。"},{"en":"All stakeholder reports must be reviewed by senior management.","zh-TW":"所有利害關係人報告必須由高層管理人員審查。"}]', NULL, NULL, 5, 6165, NULL),
(6166, 'stakeholder value', '/ˈsteɪkhoʊldər ˈvæljuː/', 'noun', '{"zh-TW":["利害關係人價值"],"en":["the benefit delivered to all parties affected by a company''s activities"]}', NULL, 'create stakeholder value / maximize stakeholder value', '[{"en":"A stakeholder value approach considers employees, customers, and communities.","zh-TW":"利害關係人價值方法考慮了員工、客戶和社區。"},{"en":"Companies increasingly report on stakeholder value beyond shareholder returns.","zh-TW":"越來越多的公司報告了股東回報之外的利害關係人價值。"}]', NULL, NULL, 5, 6166, NULL),
(6167, 'stamina', '/''stæmɪnə/', 'noun', '{"zh-TW":["體力；精力；耐力"],"en":["the ability to sustain prolonged physical or mental effort over a long period"]}', NULL, 'build stamina / increase stamina / high stamina', '[{"en":"Cyclists develop exceptional stamina through years of training.","zh-TW":"自行車手通過多年的訓練培養出非凡的體力。"},{"en":"She improved her stamina by gradually increasing her daily run distance.","zh-TW":"她通過逐漸增加每日跑步距離來提高她的體力。"}]', NULL, NULL, 3, 6167, NULL),
(6168, 'stamina building', '/''stæmɪnə ˌbɪldɪŋ/', 'noun', '{"zh-TW":["體力訓練；耐力建設"],"en":["a training approach aimed at developing the ability to sustain prolonged physical effort"]}', NULL, 'focus on stamina building / stamina building exercise / benefit of stamina building', '[{"en":"Long-distance running is one of the most effective stamina building exercises.","zh-TW":"長距離跑步是最有效的體力訓練練習之一。"},{"en":"Her fitness program included stamina building exercises three times per week.","zh-TW":"她的健身計劃每週包含三次體力訓練練習。"}]', NULL, NULL, 5, 6168, NULL),
(6169, 'stamina test', '/''stæmɪnə test/', 'noun', '{"zh-TW":["耐力測試；體力測試"],"en":["a physical assessment designed to measure how long a person can sustain effort"]}', NULL, 'pass a stamina test / fail the stamina test / undergo a stamina test', '[{"en":"Firefighters must pass a stamina test before being certified for field duty.","zh-TW":"消防員在獲得野外任務認證之前必須通過耐力測試。"},{"en":"The stamina test showed that she had significantly improved her aerobic capacity.","zh-TW":"耐力測試顯示她的有氧能力已顯著提升。"}]', NULL, NULL, 4, 6169, NULL),
(6170, 'stamp duty', '/''stæmp ˌdjuːti/', 'noun', '{"zh-TW":["印花稅"],"en":["a government tax on the purchase of real estate, calculated as a percentage of the property value"]}', NULL, 'pay stamp duty / stamp duty exemption / stamp duty rate', '[{"en":"Stamp duty adds a significant cost to buying property, especially for first-time buyers.","zh-TW":"印花稅為購買房產增加了可觀的成本，特別是對首次購房者而言。"},{"en":"The government exempted first-time buyers from stamp duty below a certain threshold.","zh-TW":"政府免除了低於特定門檻的首次購房者的印花稅。"}]', NULL, NULL, 4, 6170, NULL),
(6171, 'stand', '/stænd/', 'verb', '{"zh-TW":["【主要意義-動詞】站立","【次要意義-動詞】忍受；容忍","【次要意義-名詞】立場；態度；主張","【次要意義-名詞】攤位；展台；貨架"],"en":["[primary] to be in an upright position","[secondary - verb] to tolerate or endure without objection","[secondary - noun] a position or attitude toward an issue","[secondary - noun] a small structure where things are sold or displayed"]}', NULL, 'take a stand / stand firm / stand for / exhibition stand / music stand', '[{"en":"The company took a firm stand against using suppliers with poor labor practices.","zh-TW":"公司對使用勞動條件惡劣的供應商採取了堅定的立場。"},{"en":"Our products will be displayed at Stand 24B at the trade fair.","zh-TW":"我們的產品將在貿易展覽會的24B號攤位展出。"},{"en":"I cannot stand the way the new system slows down productivity.","zh-TW":"我無法忍受新系統降低生產力的方式。"}]', '{"noun":"standpoint, standstill","adjective":"outstanding"}', 'stand 作動詞表「忍受」，作名詞表「立場」或「展台攤位」，TOEIC 展覽/貿易類文章常見 stand（攤位），take a stand（表明立場）出現在商業決策文章中。', 2, 6171, NULL),
(6172, 'standalone', '/ˈstænəloʊn/', 'adjective', '{"zh-TW":["獨立的；自立的"],"en":["operating independently without relying on other systems or entities"]}', NULL, 'standalone entity / standalone business / standalone solution', '[{"en":"The division was spun off as a standalone business.","zh-TW":"該部門被分拆為一個獨立業務。"},{"en":"A standalone software system runs without requiring other applications.","zh-TW":"獨立的軟件系統在不需要其他應用程序的情況下運行。"}]', NULL, NULL, 4, 6172, NULL),
(6173, 'standard', '/ˈstændərd/', 'noun, adjective', '{"zh-TW":["標準；水準","標準的；普通的"],"en":["a level of quality","usual or normal"]}', NULL, 'industry standard / standard procedure / set a standard', '[{"en":"Our products meet international quality standards.","zh-TW":"我們的產品符合國際品質標準。"},{"en":"This is standard procedure for all new hires.","zh-TW":"這是所有新進員工的標準程序。"}]', '{"noun":"standard, standardization","verb":"standardize","adjective":"standard"}', NULL, 3, 6173, 219),
(6174, 'standard deviation', '/ˈstændərd ˌdiːviˈeɪʃən/', 'noun', '{"zh-TW":["標準差"],"en":["a statistical measure of the dispersion of data values from the mean"]}', NULL, 'calculate standard deviation / high standard deviation', '[{"en":"A low standard deviation indicates consistent performance.","zh-TW":"低標準差表明績效一致。"},{"en":"Risk analysts use standard deviation to measure investment volatility.","zh-TW":"風險分析師使用標準差來衡量投資波動性。"}]', NULL, NULL, 5, 6174, NULL),
(6175, 'standard operating procedure', '/ˈstændərd ˈɒpəreɪtɪŋ prəˈsiːdʒər/', 'noun', '{"zh-TW":["標準作業程序"],"en":["a documented set of instructions for performing routine operations"]}', NULL, 'follow the SOP / write an SOP / update the SOP', '[{"en":"The standard operating procedure ensures consistent product quality.","zh-TW":"標準作業程序確保一致的產品品質。"},{"en":"New employees are trained on the standard operating procedures.","zh-TW":"新員工接受標準作業程序培訓。"}]', '{"abbreviation":"SOP","plural":"SOPs"}', NULL, 5, 6175, NULL),
(6176, 'standardization', '/ˌstændərdɪˈzeɪʃən/', 'noun', '{"zh-TW":["標準化"],"en":["the process of establishing uniform specifications or methods"]}', NULL, 'pursue standardization / standardization of processes', '[{"en":"Standardization of forms reduced administrative errors by 20%.","zh-TW":"表格的標準化將行政錯誤減少了20%。"},{"en":"Product standardization simplifies manufacturing and reduces costs.","zh-TW":"產品標準化簡化了製造並降低了成本。"}]', '{"verb":"standardize","adjective":"standardized"}', NULL, 5, 6176, 622),
(6177, 'standardize', 'ˈstændərdaɪz', 'verb', '{"zh-TW":["標準化；統一","規範化"],"en":["to make uniform","to apply a standard"]}', NULL, 'standardize processes/standardize formats', '[{"en":"We need to standardize the reporting format.","zh-TW":"我們需要標準化報告格式。"}]', '{"noun":"standardization","adjective":"standardized"}', NULL, 4, 6177, NULL),
(6178, 'standardized test', '/''stændədaɪzd test/', 'noun', '{"zh-TW":["標準化測驗；統一考試"],"en":["a test administered and scored in a consistent, standardized manner to measure knowledge or skills"]}', NULL, 'take a standardized test / prepare for a standardized test / standardized test score', '[{"en":"SAT and ACT are standardized tests used for university admissions in the United States.","zh-TW":"SAT和ACT是美國用於大學入學的標準化測驗。"},{"en":"Critics argue that standardized tests do not fully reflect a student''s potential.","zh-TW":"批評者認為標準化測驗不能完全反映學生的潛力。"}]', NULL, NULL, 5, 6178, NULL),
(6179, 'standardized testing', '/''stændərdaɪzd ˌtestɪŋ/', 'noun', '{"zh-TW":["標準化測驗"],"en":["assessment administered and scored in a consistent, predetermined way across all test-takers"]}', NULL, 'prepare for standardized testing / standardized testing requirements / standardized testing criticism', '[{"en":"Many universities rely on standardized testing results to assess applicants.","zh-TW":"許多大學依賴標準化測驗結果來評估申請人。"},{"en":"Critics argue that standardized testing does not accurately reflect a student''s true potential.","zh-TW":"批評者認為標準化測驗並不能準確反映學生的真正潛力。"}]', '{"adjective":"standardized","verb":"standardize"}', NULL, 5, 6179, NULL),
(6180, 'standby', '/''stænˌbaɪ/', 'noun', '{"zh-TW":["待機狀態；候補"],"en":["ready for immediate action; also a passenger traveling on standby without a confirmed seat"]}', NULL, 'fly standby / standby ticket / on standby', '[{"en":"He flew standby and managed to get a seat on the earlier flight.","zh-TW":"他以候補方式搭機，成功拿到了更早的航班座位。"},{"en":"Budget travelers sometimes fly standby to get cheaper fares.","zh-TW":"預算有限的旅客有時以候補方式搭機，以獲得更便宜的票價。"}]', NULL, NULL, 3, 6180, NULL),
(6181, 'standby letter of credit', '/ˈstændbɑɪ ˈletər əv ˈkredɪt/', 'noun', '{"zh-TW":["備用信用證"],"en":["a bank guarantee that pays if the applicant fails to meet a contractual obligation"]}', NULL, 'issue a standby letter of credit / draw on a standby letter of credit', '[{"en":"The contractor provided a standby letter of credit as performance security.","zh-TW":"承包商提供了備用信用證作為履約保障。"},{"en":"A standby letter of credit is triggered only when the primary obligation is not met.","zh-TW":"備用信用證僅在主要義務未得到履行時才被啟動。"}]', '{"abbreviation":"SBLC"}', NULL, 5, 6181, NULL),
(6182, 'standing order', '/ˈstændɪŋ ˈɔːrdər/', 'noun', '{"zh-TW":["定期自動轉帳指令"],"en":["an instruction to a bank to make regular automatic payments"]}', NULL, 'set up a standing order / cancel a standing order', '[{"en":"She set up a standing order to pay rent on the first of each month.","zh-TW":"她設置了定期自動轉帳指令，在每月一日支付租金。"},{"en":"A standing order ensures bills are paid on time without manual action.","zh-TW":"定期轉帳指令確保帳單按時支付，無需手動操作。"}]', NULL, NULL, 5, 6182, NULL),
(6183, 'standpoint', '/ˈstændpɔɪnt/', 'noun', '{"zh-TW":["觀點；立場"],"en":["a particular attitude or way of considering something"]}', NULL, 'from a standpoint / financial standpoint / legal standpoint', '[{"en":"From a financial standpoint, the deal makes sense.","zh-TW":"從財務的角度來看，這筆交易是合理的。"},{"en":"From the customer''s standpoint, the change is positive.","zh-TW":"從客戶的角度來看，這個改變是正面的。"}]', '{"noun":"standpoint"}', NULL, 4, 6183, NULL),
(6184, 'star', '/stɑːr/', 'noun', '{"zh-TW":["明星；星星"],"en":["a famous person","a bright point of light in the sky"]}', NULL, 'star performer / five-star', '[{"en":"She is a star performer on the team.","zh-TW":"她是團隊中的明星成員。"},{"en":"We stayed at a five-star hotel.","zh-TW":"我們住在一家五星級飯店。"}]', '{"noun":"star","adjective":"star","adjective2":"stellar"}', NULL, 1, 6184, NULL),
(6185, 'starchy', '/''stɑːrtʃi/', 'adjective', '{"zh-TW":["含澱粉的；澱粉類的"],"en":["containing a lot of starch; relating to starchy foods"]}', NULL, 'starchy food / starchy vegetable / avoid starchy carbs', '[{"en":"Potatoes, rice, and bread are common starchy foods.","zh-TW":"馬鈴薯、米飯和麵包是常見的澱粉類食物。"},{"en":"Replacing starchy carbs with vegetables can help reduce calorie intake.","zh-TW":"用蔬菜替換澱粉類碳水化合物可以幫助減少卡路里攝取。"}]', '{"noun":"starch"}', NULL, 3, 6185, NULL),
(6186, 'start', '/stɑːrt/', 'verb', '{"zh-TW":["開始；創辦"],"en":["to begin","to set up a company"]}', NULL, 'start a business / from the start', '[{"en":"She started the company in her garage.","zh-TW":"她在車庫裡創辦了這家公司。"},{"en":"We knew from the start it would be difficult.","zh-TW":"我們從一開始就知道會很困難。"}]', '{"verb":"start","noun":"start","noun2":"startup","noun3":"starter"}', NULL, 2, 6186, NULL),
(6187, 'start-up costs', '/ˈstɑːrt ʌp kɒsts/', 'noun', '{"zh-TW":["啟動成本"],"en":["expenses incurred when establishing a new business or project"]}', NULL, 'estimate start-up costs / fund start-up costs', '[{"en":"Total start-up costs for the new outlet were $150000.","zh-TW":"新門市的總啟動成本為15萬元。"},{"en":"Investors typically fund start-up costs in exchange for equity.","zh-TW":"投資者通常通過提供啟動成本換取股權。"}]', NULL, NULL, 5, 6187, NULL),
(6188, 'starting capital', '/ˈstɑːrtɪŋ ˈkæpɪtəl/', 'noun', '{"zh-TW":["啟動資金；創業資本"],"en":["funds used to establish and begin operations of a new business"]}', NULL, 'raise starting capital / starting capital requirement', '[{"en":"The entrepreneur raised starting capital from family and angel investors.","zh-TW":"企業家從家人和天使投資人那裡籌集了啟動資金。"},{"en":"Starting capital is used to cover initial costs like equipment and marketing.","zh-TW":"啟動資金用於涵蓋設備和行銷等初始成本。"}]', '{"synonym":"seed capital","synonym2":"startup capital"}', NULL, 5, 6188, NULL),
(6189, 'startup', '/ˈstɑːrtʌp/', 'noun', '{"zh-TW":["新創公司"],"en":["a newly established business"]}', NULL, 'tech startup / startup culture', '[{"en":"He founded a tech startup.","zh-TW":"他創立了一家科技新創公司。"},{"en":"The startup raised millions in funding.","zh-TW":"這家新創公司籌集了數百萬資金。"}]', NULL, NULL, 3, 6189, NULL),
(6190, 'startup capital', '/ˈstɑːrtʌp ˈkæpɪtəl/', 'noun', '{"zh-TW":["創業資本"],"en":["initial funding used to establish and launch a new business"]}', NULL, 'raise startup capital / startup capital requirements', '[{"en":"The founders raised startup capital from family and angel investors.","zh-TW":"創始人從家人和天使投資者那裏籌集了創業資本。"},{"en":"Startup capital covers initial costs such as equipment, marketing, and working capital.","zh-TW":"創業資本涵蓋初始費用，如設備、行銷和營運資金。"}]', '{"synonym":"seed capital","synonym2":"seed funding"}', NULL, 5, 6190, NULL),
(6191, 'state', '/steɪt/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】州；國家；狀態","【次要意義-動詞】說明；陳述；正式聲明","【次要意義-形容詞】國家的；官方的；正式的"],"en":["[primary - noun] a region or nation; a condition","[secondary - verb] to express something clearly and formally","[secondary - adjective] relating to the government or official ceremony"]}', NULL, 'state clearly / state that / state of affairs / state-of-the-art', '[{"en":"Please state your reason for requesting an extension in writing.","zh-TW":"請以書面說明您申請延期的原因。"},{"en":"The contract clearly states that all changes must be approved in advance.","zh-TW":"合約明確規定，所有變更必須事先獲得批准。"},{"en":"She stated that she had no prior knowledge of the financial irregularities.","zh-TW":"她聲明她事先不知道財務違規情況。"}]', '{"noun":"statement","adjective":"stated"}', '動詞 state = 「正式陳述/說明」，比 say 更正式，常見於合約或法律文件語境（as stated in the contract），是 TOEIC 閱讀最高頻動詞之一。', 2, 6191, NULL),
(6192, 'state of the art', '/steɪt əv ðə ɑːrt/', 'adjective', '{"zh-TW":["最先進的；最尖端的"],"en":["using the latest and most advanced techniques or technologies"]}', NULL, 'state-of-the-art technology / state-of-the-art facility', '[{"en":"The new factory uses state-of-the-art automation technology.","zh-TW":"新工廠使用了最先進的自動化技術。"},{"en":"State-of-the-art equipment reduces errors and improves output quality.","zh-TW":"最先進的設備減少了錯誤並提高了產出品質。"}]', NULL, NULL, 5, 6192, NULL),
(6193, 'stateful', '/ˈsteɪtfəl/', 'adjective', '{"zh-TW":["有狀態的"],"en":["(of an application or system) that remembers information between interactions"]}', NULL, 'stateful application / stateful protocol / stateful service', '[{"en":"Stateful applications store session information between requests.","zh-TW":"有狀態應用程式在請求之間存儲會話資訊。"},{"en":"Migrating from stateful to stateless architecture improves scalability.","zh-TW":"從有狀態遷移到無狀態架構提高了可擴展性。"}]', '{"noun":"state","antonym":"stateless"}', NULL, 3, 6193, NULL),
(6194, 'statement', '/ˈsteɪtmənt/', 'noun', '{"zh-TW":["帳單；聲明；陳述"],"en":["a document showing financial transactions over a period"]}', NULL, 'bank statement / review a statement', '[{"en":"Please review your monthly bank statement carefully.","zh-TW":"請仔細查看您的每月銀行帳單。"},{"en":"The accountant prepared a financial statement for the year.","zh-TW":"會計師準備了年度財務報表。"}]', '{"verb":"state","adjective":"stated"}', NULL, 3, 6194, 220),
(6195, 'statistic', '/stəˈtɪstɪk/', 'noun', '{"zh-TW":["統計數據；統計資料"],"en":["numerical data collected for analysis"]}', NULL, 'official statistics / statistical analysis / according to statistics', '[{"en":"Statistics show a decline in unemployment.","zh-TW":"統計數據顯示失業率下降。"},{"en":"We need statistical evidence to support the claim.","zh-TW":"我們需要統計證據來支持這項主張。"}]', '{"noun":"statistic, statistics","adjective":"statistical","adverb":"statistically"}', NULL, 3, 6195, NULL),
(6196, 'status', '/ˈsteɪtəs/', 'noun', '{"zh-TW":["地位；身分","狀態；情形"],"en":["relative social or professional position","the current situation"]}', NULL, 'status update / social status / status quo', '[{"en":"Please provide a status update on the project.","zh-TW":"請提供專案的狀態更新。"},{"en":"The company wants to maintain the status quo.","zh-TW":"公司想維持現狀。"}]', '{"noun":"status"}', NULL, 2, 6196, 221),
(6197, 'status quo', '/ˌsteɪtəs ˈkwoʊ/', 'noun', '{"zh-TW":["現狀；原有狀態"],"en":["the existing state of affairs at a particular point in time"]}', NULL, 'maintain the status quo / challenge the status quo', '[{"en":"Disrupting the status quo is necessary for meaningful change.","zh-TW":"打破現狀是實現有意義變革的必要條件。"},{"en":"Management decided to maintain the status quo until market conditions improve.","zh-TW":"管理層決定在市場條件改善之前維持現狀。"}]', NULL, NULL, 4, 6197, NULL),
(6198, 'status update', '/ˈsteɪtəs ˈʌpdeɪt/', 'noun', '{"zh-TW":["狀態更新；進度報告"],"en":["a brief report on the current state of a project or task"]}', NULL, 'provide a status update / weekly status update / status update meeting', '[{"en":"She provided a status update on the project every Friday.","zh-TW":"她每週五提供項目進度更新。"},{"en":"The client requested a daily status update during the critical phase.","zh-TW":"客戶在關鍵階段要求每日狀態更新。"}]', NULL, NULL, 5, 6198, NULL),
(6199, 'statute', '/ˈstætʃuːt/', 'noun', '{"zh-TW":["法規；法令"],"en":["a written law passed by a legislature","a written law passed by a legislative body"]}', NULL, 'statute of limitations / by statute; by statute / statute of limitations / federal statute', '[{"en":"The statute of limitations has expired.","zh-TW":"追訴時效已過。"},{"en":"It''s required by statute.","zh-TW":"這是法規要求的。"},{"en":"The regulation is required by statute.","zh-TW":"該法規是法律要求的。"},{"en":"The statute of limitations has expired.","zh-TW":"訴訟時效已過期。"}]', '{"adjective":"statutory","noun":"statute"}', NULL, 3, 6199, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6200, 'statute of limitations', '/ˈstætjuːt əv ˌlɪmɪˈteɪʃənz/', 'noun', '{"zh-TW":["訴訟時效；起訴限期"],"en":["the time limit within which legal action must be taken"]}', NULL, 'statute of limitations period / within the statute of limitations', '[{"en":"The lawsuit was filed before the statute of limitations expired.","zh-TW":"訴訟在訴訟時效到期前提起。"},{"en":"The statute of limitations for contract disputes varies by jurisdiction.","zh-TW":"合約爭議的訴訟時效因司法管轄區而異。"}]', NULL, NULL, 5, 6200, NULL),
(6201, 'statutory', '/ˈstætʃətɔːri/', 'adjective', '{"zh-TW":["法定的；依法規定的"],"en":["required or imposed by law"]}', NULL, 'statutory requirement / statutory obligations / statutory holiday', '[{"en":"Companies must comply with all statutory reporting requirements.","zh-TW":"公司必須遵守所有法定報告要求。"},{"en":"Employees are entitled to statutory sick pay under labor law.","zh-TW":"員工依勞動法有權獲得法定病假工資。"}]', '{"adverb":"statutorily","noun":"statute"}', NULL, 3, 6201, 935),
(6202, 'statutory requirement', '/stəˈtjuːtəri rɪˈkwaɪərmənt/', 'noun', '{"zh-TW":["法定要求"],"en":["an obligation imposed by law that must be fulfilled"]}', NULL, 'comply with statutory requirements / meet statutory requirements', '[{"en":"All employers must comply with statutory requirements for minimum wage.","zh-TW":"所有雇主必須遵守最低工資的法定要求。"},{"en":"Failure to meet statutory requirements can result in criminal charges.","zh-TW":"未能達到法定要求可能導致刑事指控。"}]', NULL, NULL, 5, 6202, NULL),
(6203, 'stay', '/steɪ/', 'verb', '{"zh-TW":["停留；保持"],"en":["to remain in a place","to continue in a state"]}', NULL, 'stay focused / stay in touch', '[{"en":"Stay focused on the goals.","zh-TW":"專注於目標。"},{"en":"Let''s stay in touch.","zh-TW":"讓我們保持聯繫。"}]', '{"verb":"stay","noun":"stay"}', NULL, 1, 6203, NULL),
(6204, 'staycation', '/''steɪˌkeɪʃən/', 'noun', '{"zh-TW":["宅度假；在家度假"],"en":["a vacation spent at home or in one''s local area rather than traveling abroad"]}', NULL, 'enjoy a staycation / plan a staycation / budget staycation', '[{"en":"During the staycation, she explored museums and restaurants in her own city.","zh-TW":"在宅度假期間，她探索了自己城市的博物館和餐廳。"},{"en":"A staycation can be just as refreshing as an overseas trip.","zh-TW":"宅度假可以和海外旅行一樣令人精神煥發。"}]', NULL, NULL, 4, 6204, NULL),
(6205, 'stayover', '/ˈsteɪoʊvər/', 'noun', '{"zh-TW":["延長住宿"],"en":["a guest who extends their stay beyond the original checkout date"]}', NULL, 'process a stayover / stayover extension', '[{"en":"She requested a stayover to extend her booking by one night.","zh-TW":"她要求延長住宿，將預訂延長一晚。"},{"en":"Stayovers are handled automatically if the room is available.","zh-TW":"如果房間有空，延長住宿將自動處理。"}]', NULL, NULL, 3, 6205, NULL),
(6206, 'steadfast', '/''stedfɑːst/', 'adjective', '{"zh-TW":["堅定的；不動搖的"],"en":["resolutely or dutifully firm and unwavering"]}', NULL, 'steadfast commitment / steadfast belief / steadfast support', '[{"en":"He remained steadfast in his commitment to quality throughout his career.","zh-TW":"他在整個職業生涯中對質量的承諾保持堅定不移。"},{"en":"Steadfast leadership during uncertain times builds trust and confidence.","zh-TW":"在不確定時期的堅定領導能夠建立信任和信心。"}]', '{"adverb":"steadfastly","noun":"steadfastness"}', NULL, 3, 6206, NULL),
(6207, 'steady', '/ˈstedi/', 'adjective', '{"zh-TW":["穩定的；持續的"],"en":["regular and continuous; not changing"]}', NULL, 'steady growth / steady income / steady progress', '[{"en":"The company has shown steady growth over five years.","zh-TW":"公司在五年內呈現穩定增長。"},{"en":"We are making steady progress on the project.","zh-TW":"我們在專案上穩步前進。"}]', '{"noun":"steadiness","adjective":"steady","adverb":"steadily"}', NULL, 2, 6207, NULL),
(6208, 'steep', '/stiːp/', 'adjective', '{"zh-TW":["陡峭的；急劇的"],"en":["rising or falling sharply; very high"]}', NULL, 'steep increase / steep decline / steep price', '[{"en":"There was a steep decline in profits.","zh-TW":"利潤急劇下降。"},{"en":"The learning curve is quite steep.","zh-TW":"學習曲線相當陡峭。"}]', '{"adjective":"steep","adverb":"steeply"}', NULL, 2, 6208, NULL),
(6209, 'steering committee', '/ˈstɪərɪŋ kəˈmɪti/', 'noun', '{"zh-TW":["指導委員會"],"en":["a committee that oversees and directs a project"]}', NULL, 'form a steering committee / report to the steering committee', '[{"en":"The project''s steering committee meets monthly to review progress.","zh-TW":"項目指導委員會每月開會審查進展。"},{"en":"The steering committee approved the revised project scope.","zh-TW":"指導委員會批准了修訂後的項目範圍。"}]', NULL, NULL, 5, 6209, NULL),
(6210, 'stem', '/stem/', 'verb, noun', '{"zh-TW":["起源於；阻止","莖；幹"],"en":["to originate from; to stop","the main body of a plant"]}', NULL, 'stem from / stem the tide / stem cell', '[{"en":"The problem stems from poor planning.","zh-TW":"這個問題源於規劃不良。"},{"en":"We must stem the flow of losses.","zh-TW":"我們必須遏止虧損的趨勢。"}]', '{"noun":"stem","verb":"stem"}', NULL, 1, 6210, NULL),
(6211, 'step', '/stɛp/', 'noun', '{"zh-TW":["步驟；一步"],"en":["a movement of the foot","a stage in a process"]}', NULL, 'step by step / next step', '[{"en":"Let''s go through the process step by step.","zh-TW":"讓我們一步一步地完成流程。"},{"en":"What is the next step?","zh-TW":"下一步是什麼？"}]', '{"noun":"step","verb":"step"}', NULL, 1, 6211, NULL),
(6212, 'stewardship', '/ˈstjuːədʃɪp/', 'noun', '{"zh-TW":["管理；托管責任"],"en":["the responsible management of something entrusted to one''s care"]}', NULL, 'environmental stewardship / financial stewardship / corporate stewardship', '[{"en":"Good environmental stewardship ensures natural resources are preserved for future generations.","zh-TW":"良好的環境管理確保自然資源為後代保護。"},{"en":"The board praised the CEO''s financial stewardship during the crisis.","zh-TW":"董事會讚揚了首席執行官在危機期間的財務管理。"}]', '{"noun2":"steward","verb":"steward"}', NULL, 4, 6212, NULL),
(6213, 'stigma', '/ˈstɪɡmə/', 'noun', '{"zh-TW":["污名；社會偏見"],"en":["a mark of disgrace associated with a particular circumstance or group"]}', NULL, 'social stigma / mental health stigma / overcome stigma', '[{"en":"Reducing stigma around mental illness encourages people to seek help.","zh-TW":"降低圍繞心理疾病的污名鼓勵人們尋求幫助。"},{"en":"Stigma against poverty prevents vulnerable people from accessing support.","zh-TW":"對貧困的污名使弱勢群體無法獲得支持。"}]', '{"verb":"stigmatize","adjective":"stigmatized"}', NULL, 2, 6213, NULL),
(6214, 'still', '/stɪl/', 'noun, adjective, adverb, verb', '{"zh-TW":["【主要意義-副詞】仍然；還是","【次要意義-名詞】蒸餾器（釀酒設備）","【次要意義-名詞】靜物畫；電影劇照","【次要意義-動詞】使平靜；使安靜"],"en":["[primary - adverb] up to this time; even now","[secondary - noun] apparatus for making alcohol by distillation","[secondary - noun] a single photograph from a film or video","[secondary - verb] to make quiet or calm"]}', NULL, 'still life / distilling still / still the crowd / keep still', '[{"en":"The director selected a still from the film for the promotional poster.","zh-TW":"導演從電影中選了一張劇照用於宣傳海報。"},{"en":"The company operates a whisky still in the Scottish Highlands.","zh-TW":"這家公司在蘇格蘭高地經營一台威士忌蒸餾器。"},{"en":"Her calm words stilled the anxious crowd.","zh-TW":"她平靜的話語讓焦慮的人群安靜下來。"}]', '{"noun":"stillness","adjective":"still"}', 'still 作名詞意為「蒸餾器」或「劇照」，動詞表「使平靜」，這些次要意義在 TOEIC 飲食業或媒體相關文章中偶爾出現，容易讓考生困惑。', 2, 6214, NULL),
(6215, 'stimulate', '/ˈstɪmjuleɪt/', 'verb', '{"zh-TW":["刺激；激勵"],"en":["to encourage activity or development"]}', NULL, 'stimulate growth / stimulate the economy / stimulate demand', '[{"en":"The government introduced measures to stimulate the economy.","zh-TW":"政府推出了刺激經濟的措施。"},{"en":"Lower prices stimulate consumer demand.","zh-TW":"較低的價格刺激了消費者需求。"}]', '{"noun":"stimulation, stimulus","verb":"stimulate","adjective":"stimulating"}', NULL, 3, 6215, NULL),
(6216, 'stipulate', '/ˈstɪpjʊleɪt/', 'verb', '{"zh-TW":["規定；明確要求"],"en":["to specify a condition or requirement as part of an agreement"]}', NULL, 'stipulate terms / stipulate conditions / as stipulated', '[{"en":"The contract stipulates that payment must be made within 30 days.","zh-TW":"合約規定付款必須在30天內完成。"},{"en":"Quality standards are clearly stipulated in the procurement guidelines.","zh-TW":"採購指南中明確規定了品質標準。"}]', '{"noun":"stipulation","adjective":"stipulated"}', NULL, 3, 6216, NULL),
(6217, 'stir-fry', '/''stɜːr fraɪ/', 'verb', '{"zh-TW":["大火炒；翻炒"],"en":["to fry ingredients quickly in a small amount of very hot oil while stirring constantly"]}', NULL, 'stir-fry vegetables / stir-fry with garlic / stir-fry in a wok', '[{"en":"She stir-fried the vegetables with ginger and soy sauce for a healthy dinner.","zh-TW":"她用薑和醬油翻炒了蔬菜，做了一頓健康的晚餐。"},{"en":"The best stir-fry requires a very hot wok and constant movement.","zh-TW":"最好的大火翻炒需要非常熱的鍋和不停地翻動。"}]', '{"noun":"stir-fry"}', NULL, 3, 6217, NULL),
(6218, 'stock', '/stɒk/', 'noun', '{"zh-TW":["存貨；股票","股票；庫存","儲備；進貨"],"en":["goods available for sale","shares in a company","shares in a company; goods kept for sale","to keep a supply of"]}', '{"root":{"text":"stock","meaning":"trunk/store (樹幹/儲存)"},"logic":"原指樹幹（根基），引申為儲存的貨物。"}', 'in stock / out of stock / stock market; stock market / in stock / out of stock / stock price', '[{"en":"Sorry, that item is out of stock.","zh-TW":"抱歉，那個商品缺貨了。"},{"en":"We need to restock the shelves.","zh-TW":"我們需要補貨上架。"},{"en":"The stock market rallied after the announcement.","zh-TW":"公告後股市反彈。"},{"en":"The item is currently out of stock.","zh-TW":"該商品目前缺貨。"}]', '{"verb":"stock","noun":"stockholder"}', NULL, 2, 6218, NULL),
(6219, 'stock exchange', '/stɒk ɪksˈtʃeɪndʒ/', 'noun', '{"zh-TW":["證券交易所"],"en":["a marketplace where securities are bought and sold"]}', NULL, 'listed on a stock exchange / major stock exchange', '[{"en":"The company listed its shares on the New York Stock Exchange.","zh-TW":"公司在紐約證券交易所上市。"},{"en":"Stock exchange regulations ensure fair trading practices.","zh-TW":"證券交易所法規確保公平的交易實踐。"}]', NULL, NULL, 5, 6219, NULL),
(6220, 'stock keeping unit', '/stɒk ˈkiːpɪŋ ˌjuːnɪt/', 'noun', '{"zh-TW":["庫存單位"],"en":["a unique identifier for each distinct product in inventory management"]}', NULL, 'assign a SKU / SKU management / track by SKU', '[{"en":"Each product variant has its own stock keeping unit.","zh-TW":"每個產品變體都有自己的庫存單位。"},{"en":"SKU management simplifies inventory tracking across warehouses.","zh-TW":"庫存單位管理簡化了跨倉庫的庫存追蹤。"}]', '{"abbreviation":"SKU"}', NULL, 5, 6220, NULL),
(6221, 'stock market', '/stɒk ˈmɑːrkɪt/', 'noun', '{"zh-TW":["股票市場；股市"],"en":["a market where shares of publicly listed companies are bought and sold"]}', NULL, 'invest in the stock market / stock market performance', '[{"en":"The stock market reacted negatively to the news.","zh-TW":"股市對這一消息作出了負面反應。"},{"en":"Stock market returns outpaced inflation over the long term.","zh-TW":"長期來看，股市回報超過了通貨膨脹。"}]', NULL, NULL, 4, 6221, NULL),
(6222, 'stock option', '/stɒk ˈɒpʃən/', 'noun', '{"zh-TW":["股票選擇權"],"en":["the right to buy company stock at a fixed price in the future"]}', NULL, 'exercise stock options / stock option plan / vest stock options', '[{"en":"The startup offered generous stock options to attract engineers.","zh-TW":"新創公司提供豐厚的股票選擇權吸引工程師。"},{"en":"Stock options vest over a four-year period.","zh-TW":"股票選擇權在四年內歸屬。"}]', '{"plural":"stock options"}', NULL, 4, 6222, NULL),
(6223, 'stock option plan', '/stɒk ˈɒpʃən plæn/', 'noun', '{"zh-TW":["股票選擇權計劃"],"en":["a benefit allowing employees to purchase company shares at a set price"]}', NULL, 'participate in a stock option plan / stock option plan grant', '[{"en":"The stock option plan attracted senior talent from competitors.","zh-TW":"股票選擇權計劃從競爭對手那裡吸引了高級人才。"},{"en":"Employees exercised their stock option plan shares after the IPO.","zh-TW":"首次公開招股後員工行使了股票選擇權計劃的股份。"}]', NULL, NULL, 5, 6223, NULL),
(6224, 'stock replenishment', '/stɒk rɪˈplenɪʃmənt/', 'noun', '{"zh-TW":["補貨；庫存補充"],"en":["the process of restoring stock levels to meet future demand"]}', NULL, 'trigger stock replenishment / stock replenishment cycle', '[{"en":"The inventory system sends automatic alerts for stock replenishment.","zh-TW":"庫存系統發送自動補貨提醒。"},{"en":"Timely stock replenishment prevents stockouts during peak demand.","zh-TW":"及時的補貨在需求高峰期間防止了缺貨。"}]', NULL, NULL, 5, 6224, NULL),
(6225, 'stock split', '/stɒk splɪt/', 'noun', '{"zh-TW":["股票分割；股票拆分"],"en":["a division of existing shares into multiple new shares at a lower price each"]}', NULL, 'announce a stock split / stock split ratio', '[{"en":"The company announced a 2-for-1 stock split to improve affordability.","zh-TW":"公司宣布進行2比1的股票分割以提高可負擔性。"},{"en":"A stock split increases the number of shares but does not change total market value.","zh-TW":"股票分割增加了股票數量，但不改變總市值。"}]', NULL, NULL, 4, 6225, NULL),
(6226, 'stomach', '/ˈstʌmək/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】胃；腹部","【次要意義-動詞】忍受；消化（情感上難以接受的事）"],"en":["[primary - noun] the organ that digests food; the abdomen","[secondary - verb] to tolerate or endure something unpleasant"]}', NULL, 'cannot stomach / stomach an insult / stomach the idea', '[{"en":"Many employees could not stomach the sudden pay cut announcement.","zh-TW":"許多員工無法接受突然宣布的薪資削減。"},{"en":"He found it hard to stomach the unfair criticism from upper management.","zh-TW":"他發現很難忍受來自高層管理的不公平批評。"},{"en":"She could not stomach the idea of working under such poor conditions.","zh-TW":"她無法忍受在如此惡劣的條件下工作的想法。"}]', '{"adjective":"stomach-turning"}', '動詞 stomach（尤其用於否定句 cannot stomach）= 「無法忍受/難以接受」，常見於 TOEIC 閱讀描述員工反應或職場情境的文章，與名詞「胃」完全不同。', 3, 6226, NULL),
(6227, 'stop', '/stɒp/', 'verb', '{"zh-TW":["停止"],"en":["to cease moving or doing"]}', NULL, 'stop by / non-stop', '[{"en":"Please stop by my office later.","zh-TW":"請待會過來我的辦公室一趟。"},{"en":"We worked non-stop to finish on time.","zh-TW":"我們不停地工作以準時完成。"}]', '{"verb":"stop","noun":"stop","noun2":"stoppage"}', NULL, 1, 6227, NULL),
(6228, 'stopover', '/ˈstɒpoʊvər/', 'noun', '{"zh-TW":["過境停留"],"en":["a break in a journey at an intermediate point"]}', NULL, 'overnight stopover / planned stopover', '[{"en":"They had a stopover in Singapore on the way to London.","zh-TW":"他們前往倫敦途中在新加坡過境停留。"},{"en":"A stopover can be a chance to explore a new city.","zh-TW":"過境停留可以是探索新城市的機會。"}]', NULL, NULL, 3, 6228, NULL),
(6229, 'storage', '/ˈstɔːrɪdʒ/', 'noun', '{"zh-TW":["儲存；儲存空間","儲存；倉儲"],"en":["the keeping of things for future use","the keeping of goods in a designated place"]}', NULL, 'cloud storage / storage space; data storage / storage capacity / cold storage', '[{"en":"I need more storage on my phone.","zh-TW":"我手機需要更多儲存空間。"},{"en":"Cloud storage is convenient.","zh-TW":"雲端儲存很方便。"},{"en":"Cloud storage has become essential for businesses.","zh-TW":"雲端儲存已成為企業的必需。"},{"en":"The warehouse has limited storage capacity.","zh-TW":"倉庫的儲存容量有限。"}]', '{"verb":"store","noun":"storage, store"}', NULL, 3, 6229, 462),
(6230, 'store', '/stɔːr/', 'noun', '{"zh-TW":["商店；儲存"],"en":["a retail shop","to keep for future use","a place where goods are sold"]}', '{"root":{"text":"store","meaning":"restore/keep (保存)"},"logic":"保存物品的地方，即「商店」或「倉庫」。"}', 'in store / store data; department store / store manager', '[{"en":"We have big changes in store.","zh-TW":"我們即將有重大變化。"},{"en":"Data is stored in the cloud.","zh-TW":"數據儲存在雲端。"},{"en":"The store opens at 9 a.m.","zh-TW":"商店早上九點開門。"},{"en":"Store the food in a cool dry place.","zh-TW":"將食物儲存在陰涼乾燥處。"}]', '{"noun":"store","verb":"store","noun2":"storage"}', NULL, 2, 6230, NULL),
(6231, 'storm', '/stɔːrm/', 'noun', '{"zh-TW":["暴風雨"],"en":["violent weather with strong winds and rain"]}', '{"root":{"text":"storm","meaning":"disturbance (擾動)"},"logic":"指大氣的劇烈擾動。"}', 'thunderstorm / storm warning / weather the storm', '[{"en":"A powerful storm is heading toward the coast.","zh-TW":"一場強烈暴風雨正朝海岸移動。"},{"en":"The company weathered the financial storm.","zh-TW":"公司挺過了金融風暴。"}]', '{"adjective":"stormy","verb":"storm"}', NULL, 2, 6231, NULL),
(6232, 'story', '/ˈstɔːri/', 'noun', '{"zh-TW":["故事；樓層"],"en":["a narrative","a level of a building"]}', NULL, 'success story / cover story', '[{"en":"Our company has a great success story.","zh-TW":"我們公司有一個精彩的成功故事。"},{"en":"The office building is ten stories tall.","zh-TW":"辦公大樓有十層樓高。"}]', '{"noun":"story","noun2":"storyline"}', NULL, 2, 6232, NULL),
(6233, 'storyboard', '/ˈstɔːrɪbɔːrd/', 'noun', '{"zh-TW":["故事板；分鏡腳本"],"en":["a sequence of drawings representing the shots in a film or advertisement"]}', NULL, 'create a storyboard / detailed storyboard / storyboard approval', '[{"en":"The director presented a detailed storyboard to the production team.","zh-TW":"導演向製作團隊展示了詳細的分鏡腳本。"},{"en":"A clear storyboard helps communicate the visual vision of the project.","zh-TW":"清晰的故事板有助於傳達項目的視覺願景。"}]', '{"verb":"storyboard"}', NULL, 4, 6233, NULL),
(6234, 'straight-line depreciation', '/streɪt laɪn dɪˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["直線折舊法"],"en":["a depreciation method that spreads asset cost equally over its useful life"]}', NULL, 'use straight-line depreciation / straight-line depreciation rate', '[{"en":"Straight-line depreciation charges $10000 per year on a $100000 asset.","zh-TW":"直線折舊法對10萬元資產每年計提1萬元折舊。"},{"en":"Straight-line depreciation is simple to apply and widely used.","zh-TW":"直線折舊法簡單易用且廣泛使用。"}]', '{"opposite":"accelerated depreciation"}', NULL, 5, 6234, NULL),
(6235, 'straightforward', '/ˌstreɪtˈfɔːrwərd/', 'adjective', '{"zh-TW":["直截了當的；簡單的"],"en":["easy to understand; uncomplicated"]}', NULL, 'straightforward process / straightforward answer / fairly straightforward', '[{"en":"The application process is straightforward.","zh-TW":"申請流程很簡單。"},{"en":"He gave a straightforward answer to the question.","zh-TW":"他對問題給出了直截了當的回答。"}]', '{"adjective":"straightforward","adverb":"straightforwardly"}', NULL, 5, 6235, NULL),
(6236, 'stranded asset', '/ˈstrændɪd ˈæset/', 'noun', '{"zh-TW":["擱淺資產"],"en":["an asset that has suffered unexpected devaluation due to regulation, market shifts, or technology"]}', NULL, 'stranded asset risk / avoid stranded assets / stranded fossil fuel assets', '[{"en":"Fossil fuel companies face the risk of stranded assets in the energy transition.","zh-TW":"化石燃料公司在能源轉型中面臨擱淺資產的風險。"},{"en":"Investors are increasingly pricing in stranded asset risk.","zh-TW":"投資者越來越多地將擱淺資產風險納入定價。"}]', NULL, NULL, 5, 6236, NULL),
(6237, 'strata', '/''strɑːtə/', 'noun', '{"zh-TW":["分層產權；公寓管理委員會"],"en":["a system of property ownership in which individual units are owned while common areas are managed collectively"]}', NULL, 'strata fees / strata committee / strata rules', '[{"en":"Monthly strata fees cover maintenance of common areas such as lifts and lobbies.","zh-TW":"每月分層產權費用涵蓋電梯和大廳等公共區域的維護。"},{"en":"The strata committee voted to repaint the exterior of the building.","zh-TW":"分層產權委員會投票決定重新粉刷大樓外觀。"}]', NULL, NULL, 2, 6237, NULL),
(6238, 'strata title', '/''strɑːtə ˌtaɪtəl/', 'noun', '{"zh-TW":["分層產權；公寓分割產權"],"en":["a system of land title for multi-story buildings where each unit is individually owned"]}', NULL, 'strata title property / strata title management / buy under strata title', '[{"en":"She bought an apartment under a strata title, which gave her ownership of the unit.","zh-TW":"她以分層產權購買了一套公寓，給予她對該單元的所有權。"},{"en":"Strata title owners share responsibility for maintaining common areas.","zh-TW":"分層產權業主共同承擔維護公共區域的責任。"}]', NULL, NULL, 4, 6238, NULL),
(6239, 'strategic', '/strəˈtiːdʒɪk/', 'adjective', '{"zh-TW":["戰略性的；策略性的"],"en":["relating to the planning and directing of overall business goals"]}', NULL, 'strategic decision / strategic priority / strategic partnership', '[{"en":"The acquisition was described as a strategic move into new markets.","zh-TW":"此次收購被描述為進入新市場的戰略舉措。"},{"en":"Strategic thinking sets leaders apart from operational managers.","zh-TW":"戰略思維將領導者與運營管理者區分開來。"}]', '{"adverb":"strategically","noun":"strategy"}', NULL, 3, 6239, NULL),
(6240, 'strategic alliance', '/strəˈtiːdʒɪk əˈlaɪəns/', 'noun', '{"zh-TW":["策略聯盟"],"en":["a formal agreement between companies to pursue shared goals"]}', NULL, 'form a strategic alliance / strategic alliance partner', '[{"en":"The strategic alliance gave both firms access to new markets.","zh-TW":"策略聯盟讓兩家公司都能進入新市場。"},{"en":"A strategic alliance was signed to share technology.","zh-TW":"簽署了技術共享的策略聯盟協議。"}]', '{"verb":"ally","adjective":"allied"}', NULL, 5, 6240, NULL),
(6241, 'strategic fit', '/strəˈtiːdʒɪk fɪt/', 'noun', '{"zh-TW":["戰略契合度"],"en":["the degree to which a deal or partnership aligns with a company''s strategy"]}', NULL, 'assess strategic fit / strong strategic fit / strategic fit analysis', '[{"en":"The acquisition scored highly on strategic fit metrics.","zh-TW":"收購在戰略契合度指標上得分很高。"},{"en":"A lack of strategic fit was cited as the reason for abandoning the merger.","zh-TW":"缺乏戰略契合度被引用為放棄合併的原因。"}]', NULL, NULL, 5, 6241, NULL),
(6242, 'strategic initiative', '/strəˈtiːdʒɪk ɪˈnɪʃɪətɪv/', 'noun', '{"zh-TW":["戰略倡議；策略計劃"],"en":["an action plan designed to achieve a specific strategic objective"]}', NULL, 'launch a strategic initiative / lead a strategic initiative', '[{"en":"The company launched a strategic initiative to expand into Asia.","zh-TW":"公司啟動了一項拓展亞洲市場的戰略倡議。"},{"en":"Board members review strategic initiatives every quarter.","zh-TW":"董事會成員每季度審查戰略倡議。"}]', NULL, NULL, 5, 6242, NULL),
(6243, 'strategic investment', '/strəˈtiːdʒɪk ɪnˈvestmənt/', 'noun', '{"zh-TW":["戰略投資"],"en":["an investment made to achieve long-term strategic goals beyond financial returns"]}', NULL, 'make a strategic investment / strategic investment decision', '[{"en":"The company made a strategic investment in its competitor to gain access.","zh-TW":"公司對競爭對手進行了戰略投資以獲取市場准入。"},{"en":"Strategic investments are evaluated on qualitative as well as financial criteria.","zh-TW":"戰略投資根據定性和財務標準進行評估。"}]', NULL, NULL, 5, 6243, NULL),
(6244, 'strategic partner', '/strəˈtiːdʒɪk ˈpɑːrtnər/', 'noun', '{"zh-TW":["戰略夥伴"],"en":["an organization allied with another for shared strategic goals"]}', NULL, 'identify a strategic partner / work with a strategic partner', '[{"en":"The company found a strategic partner to enter the Chinese market.","zh-TW":"公司找到了一家戰略夥伴進入中國市場。"},{"en":"A strategic partner provides complementary skills and market access.","zh-TW":"戰略夥伴提供互補的技能和市場准入。"}]', NULL, NULL, 5, 6244, NULL),
(6245, 'strategic partnership', '/strəˈtiːdʒɪk ˈpɑːrtnərˌshɪp/', 'noun', '{"zh-TW":["戰略夥伴關係；策略合作"],"en":["a cooperative arrangement between two organizations to pursue shared objectives"]}', NULL, 'form a strategic partnership / strategic partnership agreement / benefit from a strategic partnership', '[{"en":"The two tech companies announced a strategic partnership to develop AI-powered healthcare tools.","zh-TW":"兩家科技公司宣布建立戰略夥伴關係，共同開發人工智慧醫療工具。"},{"en":"A strong strategic partnership can open doors to new markets and resources.","zh-TW":"強大的戰略夥伴關係可以打開進入新市場和獲取資源的大門。"}]', NULL, NULL, 5, 6245, NULL),
(6246, 'strategic plan', '/strəˈtiːdʒɪk plæn/', 'noun', '{"zh-TW":["戰略計劃"],"en":["a document outlining an organization long-term goals and how to achieve them"]}', NULL, 'develop a strategic plan / implement the strategic plan', '[{"en":"The company released a new five-year strategic plan.","zh-TW":"公司發布了新的五年戰略計劃。"},{"en":"The strategic plan focuses on technology and sustainability.","zh-TW":"戰略計劃聚焦於技術和可持續性。"}]', NULL, NULL, 5, 6246, NULL),
(6247, 'strategic planning', '/strəˈtiːdʒɪk ˈplænɪŋ/', 'noun', '{"zh-TW":["戰略規劃"],"en":["the process of defining a company''s direction and making decisions on resources"]}', NULL, 'strategic planning process / strategic planning cycle / annual strategic planning', '[{"en":"Strategic planning sessions are held annually at the executive retreat.","zh-TW":"戰略規劃會議每年在高管靜修時舉行。"},{"en":"Effective strategic planning ensures the company is prepared for future challenges.","zh-TW":"有效的戰略規劃確保公司為未來挑戰做好準備。"}]', '{"adjective":"strategic","verb":"plan strategically"}', NULL, 5, 6247, NULL),
(6248, 'strategic planning process', '/strəˈtiːdʒɪk ˈplænɪŋ ˈprɒses/', 'noun', '{"zh-TW":["戰略規劃流程"],"en":["the structured approach to defining organizational strategy and goals"]}', NULL, 'follow the strategic planning process / annual strategic planning process', '[{"en":"The strategic planning process involves SWOT analysis and goal-setting.","zh-TW":"戰略規劃流程涉及SWOT分析和目標設定。"},{"en":"Senior leaders participate in the annual strategic planning process.","zh-TW":"高層領導參與年度戰略規劃流程。"}]', NULL, NULL, 5, 6248, NULL),
(6249, 'strategic review', '/strəˈtiːdʒɪk rɪˈvjuː/', 'noun', '{"zh-TW":["戰略審查"],"en":["a formal evaluation of an organization''s strategy, performance, and direction"]}', NULL, 'conduct a strategic review / strategic review findings', '[{"en":"The board commissioned a strategic review of the company''s global operations.","zh-TW":"董事會委託進行了公司全球運營的戰略審查。"},{"en":"A strategic review may result in significant changes to the business model.","zh-TW":"戰略審查可能導致商業模式的重大變化。"}]', NULL, NULL, 5, 6249, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6250, 'strategy', '/ˈstrætədʒi/', 'noun', '{"zh-TW":["策略","策略；戰略"],"en":["a plan of action to achieve a long-term goal","a plan designed to achieve a long-term goal"]}', '{"root":{"text":"strat","meaning":"army (軍隊)"},"suffix":{"text":"-egy","meaning":"leading (引領)"},"logic":"引領軍隊的計畫，即「策略」。"}', 'marketing strategy / business strategy / develop a strategy; business strategy / marketing strategy / develop a strategy', '[{"en":"We need a new strategy to increase sales.","zh-TW":"我們需要新策略來增加銷售。"},{"en":"The company developed a long-term growth strategy.","zh-TW":"公司制定了長期成長策略。"},{"en":"The company revised its marketing strategy.","zh-TW":"公司修改了行銷策略。"},{"en":"We need a clear strategy for expansion.","zh-TW":"我們需要明確的擴展策略。"}]', '{"adjective":"strategic","adverb":"strategically","noun2":"strategist","noun":"strategy, strategist"}', NULL, 3, 6250, 222),
(6251, 'streaming', '/ˈstriːmɪŋ/', 'noun', '{"zh-TW":["串流"],"en":["transmitting data continuously over the internet"]}', NULL, 'video streaming / streaming service', '[{"en":"Streaming has replaced traditional TV.","zh-TW":"串流取代了傳統電視。"},{"en":"Which streaming service do you subscribe to?","zh-TW":"你訂閱了哪個串流服務？"}]', '{"verb":"stream"}', NULL, 3, 6251, NULL),
(6252, 'streamline', '/ˈstriːmlaɪn/', 'verb', '{"zh-TW":["精簡；使流暢"],"en":["to make a process more efficient"]}', NULL, 'streamline operations / streamline processes / streamline workflow', '[{"en":"The company streamlined its production process.","zh-TW":"公司精簡了生產流程。"},{"en":"New technology helps streamline daily operations.","zh-TW":"新技術有助於精簡日常營運。"}]', '{"verb":"streamline","adjective":"streamlined"}', NULL, 4, 6252, 723),
(6253, 'streamline operations', '/''striːmˌlaɪn ˌɒpəˌreɪʃənz/', 'phrase', '{"zh-TW":["精簡運營；優化業務操作"],"en":["to make business operations more efficient by eliminating unnecessary steps or processes"]}', NULL, 'streamline operations to / need to streamline operations / successfully streamline operations', '[{"en":"The company brought in a consultant to help streamline operations and reduce waste.","zh-TW":"公司聘請了一位顧問幫助精簡運營並減少浪費。"},{"en":"By streamlining operations, the factory was able to double its output.","zh-TW":"通過精簡運營，工廠能夠將產量翻倍。"}]', '{"verb":"streamline"}', NULL, 5, 6253, NULL),
(6254, 'streamlined', '/ˈstriːmlaɪnd/', 'adjective', '{"zh-TW":["精簡的；流線型的"],"en":["designed for efficiency; having smooth lines"]}', NULL, 'streamlined process / streamlined design / streamlined operations', '[{"en":"The new streamlined process saves two hours per day.","zh-TW":"新的精簡流程每天節省兩小時。"},{"en":"We implemented a streamlined approval system.","zh-TW":"我們實施了精簡的審批系統。"}]', '{"adjective":"streamlined","verb":"streamline"}', NULL, 4, 6254, NULL),
(6255, 'streamlined process', '/''striːmˌlaɪnd ˌprɒses/', 'noun', '{"zh-TW":["精簡流程；優化流程"],"en":["a process that has been made more efficient by removing unnecessary steps"]}', NULL, 'implement a streamlined process / benefit of a streamlined process / create a streamlined process', '[{"en":"The new software enabled a streamlined process for approving expense reports.","zh-TW":"新軟件為批准費用報告提供了精簡流程。"},{"en":"A streamlined process reduces time wasted on bureaucratic steps.","zh-TW":"精簡流程減少了在官僚步驟上浪費的時間。"}]', '{"adjective":"streamlined","verb":"streamline"}', NULL, 5, 6255, NULL),
(6256, 'street', '/striːt/', 'noun', '{"zh-TW":["街道"],"en":["a public road in a city or town"]}', NULL, 'Wall Street / main street', '[{"en":"Wall Street reacted positively to the news.","zh-TW":"華爾街對這個消息反應正面。"},{"en":"The store is on the main street.","zh-TW":"商店在主要街道上。"}]', '{"noun":"street"}', NULL, 2, 6256, NULL),
(6257, 'strength training', '/''streŋkθ ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["力量訓練；重量訓練"],"en":["physical exercise designed to improve muscle strength and endurance"]}', NULL, 'start strength training / strength training routine / benefit of strength training', '[{"en":"Strength training helps prevent bone loss and improves posture.","zh-TW":"力量訓練有助於防止骨質流失並改善姿勢。"},{"en":"She added strength training to her routine to complement her cardio workouts.","zh-TW":"她在日常鍛煉中加入力量訓練，以補充有氧運動。"}]', NULL, NULL, 5, 6257, NULL),
(6258, 'strengthen', '/ˈstreŋθn/', 'verb', '{"zh-TW":["加強；增強"],"en":["to make or become stronger"]}', NULL, 'strengthen ties / strengthen the position / strengthen regulations', '[{"en":"The partnership will strengthen our market position.","zh-TW":"合作將加強我們的市場地位。"},{"en":"The government strengthened environmental regulations.","zh-TW":"政府加強了環境法規。"}]', '{"noun":"strength","verb":"strengthen","adjective":"strong"}', NULL, 4, 6258, NULL),
(6259, 'stress', '/stres/', 'noun, verb', '{"zh-TW":["壓力；緊張","強調"],"en":["mental or emotional pressure","to emphasize"]}', NULL, 'under stress / stress the importance / stress management', '[{"en":"She stressed the importance of meeting deadlines.","zh-TW":"她強調了遵守截止日期的重要性。"},{"en":"Many employees suffer from workplace stress.","zh-TW":"許多員工受到工作壓力的影響。"}]', '{"noun":"stress","verb":"stress","adjective":"stressful, stressed"}', NULL, 2, 6259, NULL),
(6260, 'stress testing', '/stres ˈtestɪŋ/', 'noun', '{"zh-TW":["壓力測試"],"en":["a simulation to evaluate how a portfolio or institution performs under adverse conditions"]}', NULL, 'conduct stress testing / regulatory stress testing / scenario stress testing', '[{"en":"Regulators require banks to conduct annual stress testing.","zh-TW":"監管機構要求銀行進行年度壓力測試。"},{"en":"Stress testing revealed vulnerabilities in the firm''s liquidity position.","zh-TW":"壓力測試揭示了公司流動性狀況中的弱點。"}]', '{"verb":"stress test","adjective":"stress-tested"}', NULL, 5, 6260, NULL),
(6261, 'stress-testing', '/stres ˈtestɪŋ/', 'noun', '{"zh-TW":["壓力測試"],"en":["testing a system to evaluate performance under extreme conditions"]}', NULL, 'conduct stress-testing / stress-testing scenario / regulatory stress-testing', '[{"en":"Annual stress-testing of banks ensures they can withstand economic shocks.","zh-TW":"銀行的年度壓力測試確保其能夠承受經濟衝擊。"},{"en":"Stress-testing software helps identify failure points before deployment.","zh-TW":"壓力測試軟件幫助在部署前識別故障點。"}]', '{"verb":"stress-test","adjective":"stress-tested"}', NULL, 5, 6261, NULL),
(6262, 'stretching', '/''stretʃɪŋ/', 'noun', '{"zh-TW":["伸展；拉伸"],"en":["the practice of flexing muscles and joints to improve flexibility and prevent injury"]}', NULL, 'do stretching / dynamic stretching / post-workout stretching', '[{"en":"Daily stretching reduces muscle tightness and improves range of motion.","zh-TW":"每日伸展可以減少肌肉緊繃並改善活動範圍。"},{"en":"She spends ten minutes on stretching after every workout session.","zh-TW":"她在每次訓練後花十分鐘進行伸展。"}]', '{"verb":"stretch"}', NULL, 4, 6262, NULL),
(6263, 'strict', '/strɪkt/', 'adjective', '{"zh-TW":["嚴格的；嚴謹的"],"en":["demanding that rules are obeyed"]}', NULL, 'strict regulations / strict deadline / strict compliance', '[{"en":"The company has strict policies on data privacy.","zh-TW":"公司對資料隱私有嚴格的政策。"},{"en":"Strict compliance with safety standards is required.","zh-TW":"必須嚴格遵守安全標準。"}]', '{"adjective":"strict","adverb":"strictly","noun":"strictness"}', NULL, 2, 6263, NULL),
(6264, 'strike', '/straɪk/', 'noun, verb', '{"zh-TW":["【主要意義-動詞/名詞】打擊；罷工","【次要意義-動詞】給……留下印象；使覺得","【次要意義-動詞】達成（協議）；達到","【次要意義-名詞】（油/礦）新發現"],"en":["[primary] to hit something; a work stoppage","[secondary - verb] to make a strong impression on someone","[secondary - verb] to reach an agreement or achieve a balance","[secondary - noun] a sudden discovery of oil, gold, or similar resources"]}', NULL, 'strike a deal / strike a balance / strike me as / go on strike / lucky strike', '[{"en":"After weeks of negotiation, both sides struck a deal on the new contract.","zh-TW":"經過數週的談判，雙方就新合約達成了協議。"},{"en":"It strikes me as odd that no one was informed of the policy change.","zh-TW":"沒有人被告知政策變更，這讓我覺得很奇怪。"},{"en":"Workers went on strike to protest against the proposed pay freeze.","zh-TW":"工人舉行罷工，抗議擬議中的薪酬凍結。"}]', '{"noun":"striker","adjective":"striking"}', 'strike a deal/balance（達成協議/取得平衡）、strike me as（讓我覺得）是 TOEIC 商業談判文章的高頻表達，go on strike（舉行罷工）也是常考詞彙。', 2, 6264, NULL),
(6265, 'stringently', '/''strɪndʒəntli/', 'adverb', '{"zh-TW":["嚴格地；嚴厲地"],"en":["in a strict, precise, and demanding manner"]}', NULL, 'enforce stringently / apply stringently / regulate stringently', '[{"en":"Environmental standards are stringently enforced in the manufacturing zone.","zh-TW":"製造區的環境標準受到嚴格執行。"},{"en":"The company stringently monitors supplier compliance with its ethical sourcing policy.","zh-TW":"公司嚴格監控供應商對其道德採購政策的遵守情況。"}]', '{"adjective":"stringent"}', NULL, 4, 6265, NULL),
(6266, 'strive', '/straɪv/', 'verb', '{"zh-TW":["努力；奮鬥"],"en":["to make great efforts to achieve something"]}', NULL, 'strive for excellence / strive to achieve / strive to improve', '[{"en":"We strive for excellence in customer service.","zh-TW":"我們在客戶服務方面追求卓越。"},{"en":"The team strives to meet all deadlines.","zh-TW":"團隊努力在所有截止日前完成工作。"}]', '{"verb":"strive"}', NULL, 2, 6266, NULL),
(6267, 'strong', '/strɒŋ/', 'adjective', '{"zh-TW":["強壯的；強大的"],"en":["having great power","solid and difficult to break"]}', NULL, 'strong demand / strong leadership', '[{"en":"There is strong demand for this product.","zh-TW":"這個產品需求強勁。"},{"en":"Strong leadership guided the company through the crisis.","zh-TW":"強有力的領導帶領公司度過了危機。"}]', '{"adjective":"strong","adverb":"strongly","noun":"strength","verb":"strengthen"}', NULL, 2, 6267, NULL),
(6268, 'structural adjustment', '/ˈstrʌktʃərəl əˈdʒʌstmənt/', 'noun', '{"zh-TW":["結構性調整"],"en":["major reforms to improve economic efficiency and competitiveness"]}', NULL, 'implement structural adjustment / structural adjustment program / structural adjustment costs', '[{"en":"Structural adjustment programs often require reducing government subsidies.","zh-TW":"結構性調整計畫通常需要減少政府補貼。"},{"en":"Developing countries underwent painful structural adjustment in the 1980s.","zh-TW":"發展中國家在1980年代經歷了痛苦的結構性調整。"}]', '{"verb":"adjust structurally","adjective":"structurally adjusted"}', NULL, 5, 6268, NULL),
(6269, 'structural change', '/ˈstrʌktʃərəl tʃeɪndʒ/', 'noun', '{"zh-TW":["結構性變化"],"en":["a fundamental shift in the way an economy or industry operates"]}', NULL, 'adapt to structural change / structural change in the market', '[{"en":"Digital commerce represents a structural change in retail.","zh-TW":"數位商務代表著零售業的結構性變化。"},{"en":"Structural change often displaces workers who must reskill.","zh-TW":"結構性變化往往使需要重新培訓的工人失業。"}]', NULL, NULL, 5, 6269, NULL),
(6270, 'structural survey', '/''strʌktʃərəl ˌsɜːrveɪ/', 'noun', '{"zh-TW":["結構檢測；房屋結構調查"],"en":["a detailed assessment of a building''s structural condition conducted by a qualified surveyor"]}', NULL, 'commission a structural survey / structural survey report / pass a structural survey', '[{"en":"A structural survey revealed significant cracks in the foundation of the old building.","zh-TW":"結構檢測發現舊建築地基上有明顯裂縫。"},{"en":"Buyers are advised to commission a structural survey before completing a purchase.","zh-TW":"建議買家在完成購買之前委託進行結構檢測。"}]', NULL, NULL, 5, 6270, NULL),
(6271, 'structural unemployment', '/ˈstrʌktʃərəl ˌʌnɪmˈplɔɪmənt/', 'noun', '{"zh-TW":["結構性失業"],"en":["unemployment caused by a mismatch between workers'' skills and available jobs"]}', NULL, 'address structural unemployment / reduce structural unemployment / measure structural unemployment', '[{"en":"Automation creates structural unemployment when workers lack the skills demanded by new industries.","zh-TW":"當工人缺乏新興行業所需的技能時，自動化會造成結構性失業。"},{"en":"Retraining programs are designed to address structural unemployment by upgrading worker skills.","zh-TW":"再培訓計畫旨在通過提升工人技能來解決結構性失業問題。"}]', NULL, NULL, 5, 6271, NULL),
(6272, 'structural violence', '/ˈstrʌktʃərəl ˈvaɪələns/', 'noun', '{"zh-TW":["結構性暴力"],"en":["harm caused by social structures and institutions rather than direct action"]}', NULL, 'structural violence in healthcare / address structural violence / structural violence theory', '[{"en":"Paul Farmer''s work showed how poverty and racism constitute structural violence.","zh-TW":"保羅·法默的工作表明了貧困和種族主義如何構成結構性暴力。"},{"en":"Structural violence is embedded in systems that prevent basic needs from being met.","zh-TW":"結構性暴力嵌入於阻止基本需求得到滿足的系統中。"}]', NULL, NULL, 5, 6272, NULL),
(6273, 'structure', '/ˈstrʌktʃər/', 'noun, verb', '{"zh-TW":["結構；組織","構建；組織"],"en":["the way something is organized","to arrange in a systematic way"]}', NULL, 'organizational structure / cost structure / well-structured', '[{"en":"The company restructured its organizational structure.","zh-TW":"公司重組了其組織結構。"},{"en":"The report is well-structured and easy to follow.","zh-TW":"報告結構完善，易於理解。"}]', '{"noun":"structure, restructuring","verb":"structure, restructure","adjective":"structural"}', NULL, 3, 6273, 223),
(6274, 'structured finance', '/ˈstrʌktʃəd ˈfaɪnæns/', 'noun', '{"zh-TW":["結構性金融"],"en":["complex financial instruments created to redistribute risk, such as CDOs and MBS"]}', NULL, 'structured finance product / structured finance market / structured finance deal', '[{"en":"Structured finance instruments allowed banks to distribute mortgage risk to capital markets.","zh-TW":"結構性金融工具使銀行能夠將抵押貸款風險分散到資本市場。"},{"en":"The collapse of structured finance markets in 2008 froze global credit.","zh-TW":"二○○八年結構性金融市場的崩潰凍結了全球信貸。"}]', NULL, NULL, 5, 6274, NULL),
(6275, 'structured learning', '/''strʌktʃərd ˌlɜːrnɪŋ/', 'noun', '{"zh-TW":["結構化學習；有組織的學習"],"en":["a planned and systematic approach to education with defined goals and methods"]}', NULL, 'benefit from structured learning / structured learning environment / structured learning plan', '[{"en":"Structured learning programs provide clear goals, materials, and progress metrics.","zh-TW":"結構化學習計劃提供明確的目標、材料和進度指標。"},{"en":"Children with learning differences often benefit from structured learning environments.","zh-TW":"有學習差異的兒童往往受益於結構化學習環境。"}]', NULL, NULL, 5, 6275, NULL),
(6276, 'stubborn', '/ˈstʌbərn/', 'adjective', '{"zh-TW":["固執的"],"en":["refusing to change one''s mind"]}', '{"root":{"text":"stub","meaning":"stump (樹樁)"},"logic":"如同樹樁般不動搖的，即「固執的」。"}', 'stubborn refusal / stubborn as a mule', '[{"en":"He is too stubborn to ask for help.","zh-TW":"他太固執不肯求助。"},{"en":"Her stubborn refusal caused problems.","zh-TW":"她固執的拒絕造成了問題。"}]', '{"noun":"stubbornness","adverb":"stubbornly"}', NULL, 3, 6276, NULL),
(6277, 'student', '/ˈstjuːdənt/', 'noun', '{"zh-TW":["學生"],"en":["a person who is studying"]}', NULL, 'student loan / exchange student', '[{"en":"Student loans are a heavy burden.","zh-TW":"學生貸款是沉重的負擔。"},{"en":"We hire exchange students as interns.","zh-TW":"我們聘請交換學生當實習生。"}]', '{"noun":"student","noun2":"study","verb":"study"}', NULL, 3, 6277, NULL),
(6278, 'student loan', '/ˈstjuːdənt ləʊn/', 'noun', '{"zh-TW":["學生貸款"],"en":["money borrowed to pay for education expenses"]}', NULL, 'apply for a student loan / repay a student loan', '[{"en":"Student loans must be repaid after graduation.","zh-TW":"學生貸款必須在畢業後償還。"},{"en":"Many students rely on student loans to fund their education.","zh-TW":"許多學生依靠學生貸款資助他們的教育。"}]', NULL, NULL, 4, 6278, NULL),
(6279, 'student union', '/''stjuːdənt ˌjuːniən/', 'noun', '{"zh-TW":["學生會；學生聯合會"],"en":["an organization representing the interests of students at a college or university"]}', NULL, 'join the student union / student union election / student union representative', '[{"en":"The student union organized several events to welcome new students to campus.","zh-TW":"學生會組織了幾個活動，歡迎新生入學。"},{"en":"She ran for president of the student union in her second year.","zh-TW":"她在第二年競選學生會主席。"}]', NULL, NULL, 5, 6279, NULL),
(6280, 'studio', '/ˈstjuːdioʊ/', 'noun', '{"zh-TW":["工作室；錄音室"],"en":["a room where an artist or musician works"]}', '{"root":{"text":"studi","meaning":"study/devote (研究/投入)"},"suffix":{"text":"-o","meaning":"place (場所)"},"logic":"投入研究創作的場所，即「工作室」。"}', 'art studio / recording studio / studio apartment', '[{"en":"The photographer works in her studio.","zh-TW":"攝影師在她的工作室工作。"},{"en":"The band recorded the album in a professional studio.","zh-TW":"樂團在專業錄音室錄製了這張專輯。"}]', NULL, NULL, 2, 6280, NULL),
(6281, 'study', '/ˈstʌdi/', 'verb', '{"zh-TW":["學習；研究"],"en":["to learn about a subject","to examine carefully"]}', NULL, 'case study / feasibility study', '[{"en":"We conducted a feasibility study.","zh-TW":"我們進行了可行性研究。"},{"en":"This case study shows best practices.","zh-TW":"這個案例研究展示了最佳實踐。"}]', '{"verb":"study","noun":"study","noun2":"student"}', NULL, 2, 6281, NULL),
(6282, 'study abroad', '/ˈstʌdi əˈbrɔːd/', 'noun', '{"zh-TW":["海外留學"],"en":["studying at an educational institution in another country"]}', NULL, 'study abroad program / apply to study abroad', '[{"en":"He spent one year in Germany as part of his study abroad program.","zh-TW":"他作為海外留學計劃的一部分在德國待了一年。"},{"en":"Study abroad experiences enhance cross-cultural understanding.","zh-TW":"海外留學經驗增強了跨文化理解。"}]', NULL, NULL, 4, 6282, NULL),
(6283, 'study group', '/''stʌdi ɡruːp/', 'noun', '{"zh-TW":["學習小組；讀書會"],"en":["a group of students who meet regularly to study together and help each other understand material"]}', NULL, 'form a study group / join a study group / benefit of study group', '[{"en":"She formed a study group with classmates to prepare for the final examination.","zh-TW":"她和同學組成了學習小組，為期末考試做準備。"},{"en":"A study group can help members tackle difficult topics more effectively.","zh-TW":"學習小組可以幫助成員更有效地處理困難的主題。"}]', NULL, NULL, 4, 6283, NULL),
(6284, 'style', 'staɪl', 'noun', '{"zh-TW":["風格；方式","樣式"],"en":["a way of doing something","a particular design"]}', NULL, 'work style/management style', '[{"en":"Her management style is collaborative.","zh-TW":"她的管理風格是協作式的。"}]', '{"verb":"style","adjective":"stylish","adverb":"stylishly"}', NULL, 2, 6284, NULL),
(6285, 'subagent', '/ˈsʌbeɪdʒənt/', 'noun', '{"zh-TW":["次代理；子代理人"],"en":["an agent authorized by another agent to perform certain duties"]}', NULL, 'appoint a subagent / subagent agreement', '[{"en":"The broker appointed a local subagent in each city.","zh-TW":"經紀人在每個城市任命了一名本地次代理。"},{"en":"The subagent is authorized to sign documents on behalf of the main agent.","zh-TW":"次代理有權代表主要代理人簽署文件。"}]', NULL, NULL, 3, 6285, NULL),
(6286, 'subcontract', '/ˌsʌbkənˈtrækt/', 'verb, noun', '{"zh-TW":["分包；轉包","分包合約"],"en":["to hire another company to do part of the work"]}', NULL, 'subcontract work / subcontract to / subcontractor', '[{"en":"The firm subcontracted the IT work to a specialist.","zh-TW":"公司將IT工作分包給專業人員。"},{"en":"We use subcontractors for maintenance services.","zh-TW":"我們使用分包商提供維護服務。"}]', '{"noun":"subcontract, subcontractor","verb":"subcontract"}', NULL, 4, 6286, NULL),
(6287, 'subcontractor', '/ˌsʌbkənˈtræktər/', 'noun', '{"zh-TW":["分包商；次承包商"],"en":["a company hired by the main contractor to complete specific work"]}', NULL, 'hire a subcontractor / subcontractor agreement', '[{"en":"The builder hired a subcontractor to install the electrical systems.","zh-TW":"建築商聘請了分包商安裝電力系統。"},{"en":"Subcontractor performance affects the main project timeline.","zh-TW":"分包商的表現影響著主項目的時間表。"}]', '{"verb":"subcontract","adjective":"subcontracted"}', NULL, 5, 6287, NULL),
(6288, 'subject', '/ˈsʌbdʒɪkt/', 'noun, adjective, verb', '{"zh-TW":["主題；科目","受...支配的","使遭受"],"en":["a topic; a branch of study","dependent on","to cause to experience"]}', NULL, 'subject to / on the subject of / subject matter', '[{"en":"The plan is subject to board approval.","zh-TW":"該計畫需經董事會批准。"},{"en":"Let''s not change the subject.","zh-TW":"我們不要改變話題。"}]', '{"noun":"subject","verb":"subject","adjective":"subject, subjective"}', NULL, 3, 6288, 463),
(6289, 'subjectivity', '/ˌsʌbdʒekˈtɪvɪti/', 'noun', '{"zh-TW":["主觀性"],"en":["the quality of being based on personal feelings, opinions, or experience"]}', NULL, 'overcome subjectivity / acknowledge subjectivity / reduce subjectivity', '[{"en":"Qualitative research involves inherent subjectivity that must be acknowledged.","zh-TW":"質性研究涉及必須承認的固有主觀性。"},{"en":"Performance reviews can be influenced by the subjectivity of the evaluator.","zh-TW":"績效評估可能受到評估者主觀性的影響。"}]', '{"adjective":"subjective","adverb":"subjectively"}', NULL, 4, 6289, NULL),
(6290, 'sublease', '/ˈsʌbliːs/', 'noun', '{"zh-TW":["轉租；分租"],"en":["renting property that you have leased from another party"]}', NULL, 'sublease agreement / enter a sublease / sublease the office', '[{"en":"The company subleased part of its office space to a startup.","zh-TW":"公司將部分辦公空間轉租給一家新創公司。"},{"en":"The sublease required approval from the original landlord.","zh-TW":"轉租需要原房東的批准。"}]', '{"verb":"sublease","noun":"sublessee"}', NULL, 3, 6290, NULL),
(6291, 'subletting', '/''sʌbˌletɪŋ/', 'noun', '{"zh-TW":["轉租；分租"],"en":["the practice of renting all or part of a property that you are already renting to another person"]}', NULL, 'allow subletting / prohibit subletting / subletting arrangement', '[{"en":"The lease agreement prohibited subletting without the landlord''s written consent.","zh-TW":"租賃協議禁止未經房東書面同意進行轉租。"},{"en":"She arranged subletting for the months she was abroad to help cover the rent.","zh-TW":"她安排了在海外幾個月的轉租，以幫助支付租金。"}]', '{"verb":"sublet"}', NULL, 4, 6291, NULL),
(6292, 'submission', 'səbˈmɪʃən', 'noun', '{"zh-TW":["提交；呈遞","服從"],"en":["the act of presenting formally","a document submitted"]}', NULL, 'on-time submission/final submission', '[{"en":"Please ensure on-time submission.","zh-TW":"請確保按時提交。"}]', '{"verb":"submit","adjective":"submitted"}', NULL, 4, 6292, 624),
(6293, 'submit', '/səbˈmɪt/', 'verb', '{"zh-TW":["提交；呈交","服從"],"en":["to present for consideration","to yield to authority"]}', '{"prefix":{"text":"sub-","meaning":"在...之下"},"root":{"text":"mit","meaning":"send (發送)"}}', 'submit a report / submit an application / submit a proposal', '[{"en":"Please submit your application by Friday.","zh-TW":"請在週五前提交您的申請。"},{"en":"All expenses must be submitted for approval.","zh-TW":"所有費用都必須提交審批。"}]', '{"noun":"submission","verb":"submit"}', NULL, 2, 6293, 62),
(6294, 'subordinate', '/səˈbɔːrdɪnət/', 'noun, adjective', '{"zh-TW":["下屬；部屬","次要的；從屬的"],"en":["a person under the authority of another","lower in rank"]}', NULL, 'subordinate to / direct subordinate', '[{"en":"Managers should support their subordinates.","zh-TW":"經理應該支持他們的下屬。"},{"en":"Personal interests are subordinate to company goals.","zh-TW":"個人利益從屬於公司目標。"}]', '{"noun":"subordinate, subordination","adjective":"subordinate","verb":"subordinate"}', NULL, 4, 6294, 937),
(6295, 'subpoena', '/səˈpiːnə/', 'noun', '{"zh-TW":["傳票；傳喚"],"en":["a legal document ordering someone to appear in court or produce evidence"]}', NULL, 'issue a subpoena / comply with a subpoena / receive a subpoena', '[{"en":"The court issued a subpoena requiring the executive to testify.","zh-TW":"法院發出傳票要求高管出庭作證。"},{"en":"Failure to comply with a subpoena can result in contempt of court.","zh-TW":"不遵守傳票可能導致藐視法庭。"}]', '{"verb":"subpoena"}', NULL, 3, 6295, NULL),
(6296, 'subprime', '/ˈsʌbˌpraɪm/', 'adjective', '{"zh-TW":["次級的；低於優質級的"],"en":["denoting loans or borrowers that don''t meet standard criteria for creditworthiness"]}', NULL, 'subprime mortgage / subprime lending / subprime market', '[{"en":"The collapse of the subprime mortgage market triggered the 2008 financial crisis.","zh-TW":"次級抵押貸款市場的崩潰引發了二○○八年的金融危機。"},{"en":"Subprime lending practices exposed banks to higher default risks.","zh-TW":"次級貸款做法使銀行面臨更高的違約風險。"}]', NULL, NULL, 3, 6296, NULL),
(6297, 'subscribe', '/səbˈskraɪb/', 'verb', '{"zh-TW":["訂閱；認購","同意"],"en":["to pay regularly for a service","to agree with an idea"]}', NULL, 'subscribe to / subscription service / subscribe to a newsletter', '[{"en":"Over 10,000 users subscribe to our newsletter.","zh-TW":"超過一萬名用戶訂閱我們的電子報。"},{"en":"I don''t subscribe to that theory.","zh-TW":"我不認同那個理論。"}]', '{"noun":"subscription, subscriber","verb":"subscribe"}', NULL, 3, 6297, NULL),
(6298, 'subscription', '/səbˈskrɪpʃən/', 'noun', '{"zh-TW":["訂閱；訂閱制"],"en":["a model where customers pay regularly for ongoing access to a product"]}', NULL, 'subscription model / subscription fee / annual subscription / cancel subscription', '[{"en":"The company switched to a subscription model for stable recurring revenue.","zh-TW":"公司轉向訂閱模式以獲得穩定的經常性收入。"},{"en":"Monthly subscriptions increased by 40% after the price reduction.","zh-TW":"降價後，月度訂閱數量增加了40%。"}]', '{"verb":"subscribe","noun":"subscriber"}', NULL, 4, 6298, NULL),
(6299, 'subscription fee', '/səbˈskrɪpʃən fiː/', 'noun', '{"zh-TW":["訂閱費；會員費"],"en":["a recurring charge paid for ongoing access to a service"]}', NULL, 'charge a subscription fee / monthly subscription fee', '[{"en":"The platform charges a monthly subscription fee of 15 dollars.","zh-TW":"平台收取每月15美元的訂閱費。"},{"en":"The subscription fee was reduced for annual payment plans.","zh-TW":"年度付款計劃的訂閱費降低了。"}]', NULL, NULL, 5, 6299, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6300, 'subscription model', '/səbˈskrɪpʃən ˈmɒdəl/', 'noun', '{"zh-TW":["訂閱模式"],"en":["a business model where customers pay regularly for ongoing access"]}', NULL, 'adopt a subscription model / subscription model revenue', '[{"en":"The software company moved to a subscription model for recurring revenue.","zh-TW":"軟體公司轉向了訂閱模式以獲得經常性收入。"},{"en":"A subscription model improves revenue predictability.","zh-TW":"訂閱模式提高了收入的可預測性。"}]', NULL, NULL, 5, 6300, NULL),
(6301, 'subsequent', '/ˈsʌbsɪkwənt/', 'adjective', '{"zh-TW":["隨後的；後續的"],"en":["coming after something in time"]}', NULL, 'subsequent to / subsequent events / in subsequent years', '[{"en":"Subsequent meetings will address remaining issues.","zh-TW":"後續會議將處理剩餘問題。"},{"en":"Sales improved in subsequent quarters.","zh-TW":"銷售額在接下來的幾季有所改善。"}]', '{"adjective":"subsequent","adverb":"subsequently"}', NULL, 4, 6301, NULL),
(6302, 'subsidiary', '/səbˈsɪdieri/', 'noun, adjective', '{"zh-TW":["子公司","附屬的；次要的"],"en":["a company controlled by another company","less important"]}', NULL, 'wholly-owned subsidiary / subsidiary company', '[{"en":"The company has subsidiaries in 20 countries.","zh-TW":"該公司在20個國家設有子公司。"},{"en":"This is a wholly-owned subsidiary of the group.","zh-TW":"這是集團的全資子公司。"}]', '{"noun":"subsidiary"}', NULL, 4, 6302, NULL),
(6303, 'subsidiary company', '/səbˈsɪdiəri ˈkʌmpəni/', 'noun', '{"zh-TW":["子公司"],"en":["a company controlled by a parent or holding company"]}', NULL, 'wholly-owned subsidiary / establish a subsidiary company', '[{"en":"The subsidiary company operates independently in the Asian market.","zh-TW":"子公司在亞洲市場獨立運營。"},{"en":"Revenue from the subsidiary company contributed 20% to group earnings.","zh-TW":"子公司的收入貢獻了集團盈利的20%。"}]', '{"plural":"subsidiary companies"}', NULL, 5, 6303, NULL),
(6304, 'subsidiary rights', '/səbˈsɪdiəri raɪts/', 'noun', '{"zh-TW":["附屬權利；衍生版權"],"en":["secondary rights derived from a primary work, such as foreign language or film rights"]}', NULL, 'license subsidiary rights / subsidiary rights agreement', '[{"en":"The publisher sold subsidiary rights for translation into 12 languages.","zh-TW":"出版商出售了翻譯成12種語言的附屬版權。"},{"en":"Subsidiary rights generate additional revenue beyond the primary publication.","zh-TW":"附屬版權在主要出版物之外產生了額外收入。"}]', NULL, NULL, 5, 6304, NULL),
(6305, 'subsidy', '/ˈsʌbsɪdi/', 'noun', '{"zh-TW":["補貼；補助金"],"en":["money granted by the government to assist an industry"]}', NULL, 'government subsidy / subsidy program', '[{"en":"The government provides subsidies for electric vehicle purchases.","zh-TW":"政府為購買電動車提供補貼。"},{"en":"Subsidies for renewable energy have driven its rapid expansion.","zh-TW":"對可再生能源的補貼推動了其快速擴展。"}]', '{"verb":"subsidize","adjective":"subsidized"}', NULL, 3, 6305, NULL),
(6306, 'substance', '/ˈsʌbstəns/', 'noun', '{"zh-TW":["物質；實質","要旨"],"en":["a type of matter","the real content or meaning"]}', NULL, 'chemical substance / in substance / substance abuse', '[{"en":"The report lacks substance.","zh-TW":"這份報告缺乏實質內容。"},{"en":"Hazardous substances must be handled carefully.","zh-TW":"危險物質必須小心處理。"}]', '{"noun":"substance","adjective":"substantial, substantive"}', NULL, 3, 6306, NULL),
(6307, 'substandard', '/ˌsʌbˈstændərd/', 'adjective', '{"zh-TW":["低於標準的；不合格的"],"en":["below the required or expected quality"]}', NULL, 'substandard goods / substandard work / substandard quality', '[{"en":"The supplier delivered substandard components that failed quality checks.","zh-TW":"供應商交付了未能通過品質檢查的不合格零件。"},{"en":"Substandard work will not be accepted by the client.","zh-TW":"客戶不會接受不合格的工作。"}]', '{"adverb":"substandard"}', NULL, 4, 6307, NULL),
(6308, 'substantial', '/səbˈstænʃl/', 'adjective', '{"zh-TW":["大量的；可觀的","實質的"],"en":["of considerable importance or size"]}', NULL, 'substantial amount / substantial improvement / substantial evidence', '[{"en":"We made a substantial investment in technology.","zh-TW":"我們在技術方面進行了大量投資。"},{"en":"There has been substantial improvement in quality.","zh-TW":"品質有了顯著的改善。"}]', '{"noun":"substance","adjective":"substantial","adverb":"substantially"}', NULL, 4, 6308, NULL),
(6309, 'substantially', '/''səbˈstænʃəli/', 'adverb', '{"zh-TW":["大幅地；顯著地"],"en":["to a great or significant extent; considerably"]}', NULL, 'substantially different / substantially improved / substantially increased', '[{"en":"The new policy substantially reduced administrative overhead.","zh-TW":"新政策大幅降低了行政費用。"},{"en":"Her performance substantially improved after she received targeted coaching.","zh-TW":"在獲得有針對性的指導後，她的表現顯著改善。"}]', '{"adjective":"substantial"}', NULL, 5, 6309, NULL),
(6310, 'substantiate', '/səbˈstænʃieɪt/', 'verb', '{"zh-TW":["證實；提供實質依據"],"en":["to provide evidence to support or prove the truth of something"]}', NULL, 'substantiate a claim / substantiate findings / substantiate evidence', '[{"en":"The data substantiate the researcher''s central claim.","zh-TW":"數據證實了研究員的核心主張。"},{"en":"You need concrete examples to substantiate your argument.","zh-TW":"你需要具體例子來為你的論點提供依據。"}]', '{"noun":"substantiation","adjective":"substantiated"}', NULL, 4, 6310, NULL),
(6311, 'substitute', '/ˈsʌbstɪtuːt/', 'noun, verb', '{"zh-TW":["替代品；代替者","替代；取代"],"en":["a person or thing acting in place of another","to use instead of"]}', NULL, 'substitute for / substitute teacher / no substitute for', '[{"en":"There is no substitute for hard work.","zh-TW":"勤奮是無可替代的。"},{"en":"You can substitute olive oil for butter.","zh-TW":"你可以用橄欖油代替奶油。"}]', '{"noun":"substitute, substitution","verb":"substitute"}', NULL, 4, 6311, NULL),
(6312, 'subtext', '/ˈsʌbtekst/', 'noun', '{"zh-TW":["潛台詞；言外之意"],"en":["the underlying theme in a piece of writing or conversation"]}', NULL, 'read the subtext / rich subtext / political subtext', '[{"en":"The dialogue has a powerful subtext about class and ambition.","zh-TW":"這段對話有一個關於階層和野心的深刻潛台詞。"},{"en":"Great acting requires understanding and conveying the subtext.","zh-TW":"出色的表演需要理解並傳達潛台詞。"}]', NULL, NULL, 3, 6312, NULL),
(6313, 'subtle', '/ˈsʌtl/', 'adjective', '{"zh-TW":["微妙的；細微的"],"en":["not immediately obvious; delicate"]}', NULL, 'subtle difference / subtle change / subtle hint', '[{"en":"There is a subtle difference between the two products.","zh-TW":"這兩款產品之間有微妙的差異。"},{"en":"She made a subtle hint about the promotion.","zh-TW":"她暗示了關於升遷的事。"}]', '{"noun":"subtlety","adjective":"subtle","adverb":"subtly"}', NULL, 2, 6313, NULL),
(6314, 'suburb', '/''sʌbɜːrb/', 'noun', '{"zh-TW":["郊區；郊外"],"en":["a residential area on the outskirts of a city or large town"]}', NULL, 'quiet suburb / suburban area / move to the suburbs', '[{"en":"Many families prefer the suburbs for their lower cost of living and safer environment.","zh-TW":"許多家庭偏好郊區，因為那裡生活費用較低且環境更安全。"},{"en":"The suburb was originally a small farming community but grew rapidly after urban expansion.","zh-TW":"郊區最初是一個小農業社區，但在城市擴張後迅速發展。"}]', '{"adjective":"suburban","noun":"suburbia"}', NULL, 2, 6314, NULL),
(6315, 'succeed', '/səkˈsiːd/', 'verb', '{"zh-TW":["成功；繼任"],"en":["to achieve a goal; to come after"]}', NULL, 'succeed in / succeed as / succeed someone', '[{"en":"The company succeeded in entering the Asian market.","zh-TW":"公司成功進入了亞洲市場。"},{"en":"She succeeded him as CEO.","zh-TW":"她接替他擔任執行長。"}]', '{"noun":"success, succession, successor","verb":"succeed","adjective":"successful, successive"}', NULL, 3, 6315, NULL),
(6316, 'success', 'səkˈsɛs', 'noun', '{"zh-TW":["成功；成就","好結果"],"en":["the achievement of a goal","a favorable outcome"]}', NULL, 'business success/measure of success', '[{"en":"Success depends on teamwork.","zh-TW":"成功取決於團隊合作。"}]', '{"verb":"succeed","adjective":"successful","adverb":"successfully"}', NULL, 3, 6316, NULL),
(6317, 'successful', 'səkˈsɛsfəl', 'adjective', '{"zh-TW":["成功的；有成就的","出色的"],"en":["having achieved a desired goal","prosperous"]}', NULL, 'successful project/successful launch', '[{"en":"The product launch was very successful.","zh-TW":"產品發布非常成功。"}]', '{"noun":"success","adverb":"successfully"}', NULL, 4, 6317, 224),
(6318, 'succession', '/səkˈseʃən/', 'noun', '{"zh-TW":["接替；繼承"],"en":["the process of one person taking over another''s role or position"]}', NULL, 'succession plan / succession of management / leadership succession', '[{"en":"Smooth succession is critical to maintaining business continuity.","zh-TW":"順暢的繼任對維持業務連續性至關重要。"},{"en":"The board developed a succession strategy for the retiring CFO.","zh-TW":"董事會為即將退休的財務長制定了繼任策略。"}]', '{"verb":"succeed","noun":"successor"}', NULL, 4, 6318, 938),
(6319, 'succession planning', '/səkˈseʃən ˈplænɪŋ/', 'noun', '{"zh-TW":["接班規劃；接任計劃"],"en":["preparing for future leadership transitions within an organization"]}', NULL, 'succession planning process / executive succession planning', '[{"en":"Succession planning ensures leadership continuity during transitions.","zh-TW":"接班規劃確保過渡期間的領導層連續性。"},{"en":"The board emphasized succession planning after the CEO retired.","zh-TW":"執行長退休後，董事會強調了接班規劃的重要性。"}]', '{"verb":"plan succession"}', NULL, 5, 6319, NULL),
(6320, 'succinct', '/səkˈsɪŋkt/', 'adjective', '{"zh-TW":["簡潔的；精練的"],"en":["briefly and clearly expressed"]}', NULL, 'succinct summary / succinct explanation / succinct response', '[{"en":"A succinct abstract conveys the key points of the research.","zh-TW":"簡潔的摘要傳達研究的關鍵點。"},{"en":"He gave a succinct answer that satisfied all the reviewers.","zh-TW":"他給出了一個簡潔的答案，讓所有評審都感到滿意。"}]', '{"adverb":"succinctly","noun":"succinctness"}', NULL, 3, 6320, NULL),
(6321, 'sufficient', '/səˈfɪʃnt/', 'adjective', '{"zh-TW":["足夠的","足夠的；充分的"],"en":["enough to meet the needs"]}', '{"prefix":{"text":"suf-","meaning":"under/up (從下)"},"root":{"text":"fic","meaning":"make/do (做)"},"suffix":{"text":"-ient","meaning":"being (…的)"},"logic":"做到位的，即「足夠的」。"}', 'sufficient evidence / sufficient time / self-sufficient; sufficient funds / sufficient evidence / self-sufficient', '[{"en":"Do we have sufficient time to finish?","zh-TW":"我們有足夠的時間完成嗎？"},{"en":"The evidence is not sufficient to prove guilt.","zh-TW":"證據不足以證明有罪。"},{"en":"We have sufficient funds to complete the project.","zh-TW":"我們有足夠的資金完成這個專案。"},{"en":"The evidence is not sufficient to prove the claim.","zh-TW":"證據不足以證明該主張。"}]', '{"noun":"sufficiency","adverb":"sufficiently","adjective":"sufficient, insufficient"}', NULL, 4, 6321, NULL),
(6322, 'suggest', '/səˈdʒest/', 'verb', '{"zh-TW":["建議；暗示"],"en":["to put forward an idea; to indicate"]}', NULL, 'suggest that / strongly suggest / suggest an alternative', '[{"en":"I suggest we postpone the meeting.","zh-TW":"我建議我們延後會議。"},{"en":"The data suggests a positive trend.","zh-TW":"數據暗示了一個正面的趨勢。"}]', '{"noun":"suggestion","verb":"suggest","adjective":"suggestive"}', NULL, 3, 6322, NULL),
(6323, 'suit', '/suːt/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】西裝；套裝","【次要意義-動詞】適合；對……合適","【次要意義-名詞】訴訟；法律行動","【次要意義-名詞】（撲克牌）花色"],"en":["[primary - noun] a set of matching clothes","[secondary - verb] to be convenient or appropriate for someone","[secondary - noun] a legal case or proceeding","[secondary - noun] one of the four sets of cards in a deck"]}', NULL, 'suit someone / file a suit / follow suit / a lawsuit / strong suit', '[{"en":"The new office hours suit most employees very well.","zh-TW":"新的辦公時間非常適合大多數員工。"},{"en":"The company filed a suit against its former partner for breach of contract.","zh-TW":"公司就違約問題對前合作夥伴提起了訴訟。"},{"en":"When the market leader lowered prices, competitors followed suit.","zh-TW":"當市場領導者降價時，競爭者也紛紛效仿。"}]', '{"adjective":"suitable, unsuitable","noun":"suitability"}', '動詞 suit = 「適合」，名詞 suit = 「訴訟」（lawsuit），片語 follow suit = 「效仿/跟進」，TOEIC 法律和商業文章的高頻詞彙。', 1, 6323, NULL),
(6324, 'suitable', 'ˈsuːtəbəl', 'adjective', '{"zh-TW":["合適的；適宜的","相稱的"],"en":["right for a particular purpose","appropriate"]}', NULL, 'suitable candidate/suitable time', '[{"en":"Is Monday a suitable time for the meeting?","zh-TW":"週一是開會的合適時間嗎？"}]', '{"noun":"suitability","adverb":"suitably"}', NULL, 3, 6324, NULL),
(6325, 'suite', '/swiːt/', 'noun', '{"zh-TW":["套房"],"en":["a set of connected rooms in a hotel"]}', NULL, 'luxury suite / book a suite', '[{"en":"They booked a suite for their honeymoon.","zh-TW":"他們為蜜月預訂了套房。"},{"en":"The suite includes a living room and a bedroom.","zh-TW":"套房包含客廳和臥室。"}]', NULL, NULL, 2, 6325, NULL),
(6326, 'summarize', '/ˈsʌməraɪz/', 'verb', '{"zh-TW":["總結；概述"],"en":["to give a brief statement of the main points"]}', NULL, 'summarize the findings / to summarize / briefly summarize', '[{"en":"Please summarize the key findings of the report.","zh-TW":"請總結報告的主要發現。"},{"en":"To summarize, we need to reduce costs by 15%.","zh-TW":"總結來說，我們需要降低15%的成本。"}]', '{"noun":"summary","verb":"summarize"}', NULL, 3, 6326, NULL),
(6327, 'summary', 'ˈsʌməri', 'noun', '{"zh-TW":["摘要；總結","概要"],"en":["a brief statement of main points","an overview"]}', NULL, 'executive summary/provide a summary', '[{"en":"Please provide a summary of the report.","zh-TW":"請提供報告的摘要。"}]', '{"verb":"summarize","adjective":"summary"}', NULL, 3, 6327, 464),
(6328, 'summative assessment', '/''sʌmətɪv əˌsesmənt/', 'noun', '{"zh-TW":["總結性評估；終結性評量"],"en":["evaluation of student learning at the end of an instructional period against a standard or benchmark"]}', NULL, 'summative assessment result / summative assessment design / use summative assessment', '[{"en":"Final exams and standardized tests are common forms of summative assessment.","zh-TW":"期末考試和標準化測驗是常見的總結性評估形式。"},{"en":"Summative assessment measures whether students have achieved the learning objectives.","zh-TW":"總結性評估衡量學生是否達到了學習目標。"}]', '{"adjective":"summative"}', NULL, 5, 6328, NULL),
(6329, 'summit', '/ˈsʌmɪt/', 'noun', '{"zh-TW":["高峰會；峰會","頂點"],"en":["a meeting between heads of government","the highest point"]}', NULL, 'economic summit / summit meeting / reach the summit', '[{"en":"Leaders gathered for the G20 summit.","zh-TW":"領袖們齊聚G20高峰會。"},{"en":"The summit addressed climate change issues.","zh-TW":"峰會討論了氣候變遷議題。"}]', '{"noun":"summit"}', NULL, 2, 6329, NULL),
(6330, 'sunk cost', '/sʌŋk kɒst/', 'noun', '{"zh-TW":["沉沒成本"],"en":["a cost that has already been incurred and cannot be recovered"]}', NULL, 'ignore sunk costs / sunk cost fallacy', '[{"en":"Managers should not let sunk costs influence future decisions.","zh-TW":"管理者不應讓沉沒成本影響未來的決策。"},{"en":"The project was cancelled despite the sunk cost of $2 million already spent.","zh-TW":"儘管已投入200萬元的沉沒成本，該項目仍被取消了。"}]', NULL, NULL, 3, 6330, NULL),
(6331, 'superficial', '/''suːpərˈfɪʃəl/', 'adjective', '{"zh-TW":["表面的；膚淺的"],"en":["existing or occurring at or on the surface; not thorough or deep; lacking depth"]}', NULL, 'superficial understanding / superficial analysis / superficial impression', '[{"en":"A superficial analysis of the data missed the underlying trends.","zh-TW":"對數據的表面分析遺漏了潛在趨勢。"},{"en":"Their business relationship remained superficial and never developed into a true partnership.","zh-TW":"他們的商業關係保持表面，從未發展成真正的合夥關係。"}]', '{"adverb":"superficially","noun":"superficiality"}', NULL, 4, 6331, NULL),
(6332, 'superfluous', '/''suːˈpɜːrfluəs/', 'adjective', '{"zh-TW":["多餘的；過剩的"],"en":["unnecessary, especially through being more than enough"]}', NULL, 'superfluous information / superfluous details / superfluous steps', '[{"en":"The editor removed several superfluous paragraphs to tighten the article.","zh-TW":"編輯刪除了幾個多餘的段落，使文章更精煉。"},{"en":"Superfluous meetings consume time that could be spent on productive work.","zh-TW":"多餘的會議消耗了本可用於生產性工作的時間。"}]', '{"adverb":"superfluously","noun":"superfluousness"}', NULL, 4, 6332, NULL),
(6333, 'superfood', '/''suːpərˌfuːd/', 'noun', '{"zh-TW":["超級食物"],"en":["a nutrient-rich food considered to be especially beneficial for health and well-being"]}', NULL, 'eat superfoods / superfood smoothie / popular superfood', '[{"en":"Quinoa, chia seeds, and kale are often cited as superfoods.","zh-TW":"藜麥、奇亞籽和羽衣甘藍常被列為超級食物。"},{"en":"The superfood trend has driven demand for ingredients like acai and spirulina.","zh-TW":"超級食物趨勢推動了對巴西莓和螺旋藻等食材的需求。"}]', NULL, NULL, 3, 6333, NULL),
(6334, 'supersede', '/''suːpərˌsiːd/', 'verb', '{"zh-TW":["取代；替代"],"en":["to take the place of something previously in use or accepted; to replace"]}', NULL, 'supersede a rule / supersede a technology / be superseded by', '[{"en":"The new regulation superseded the previous rules that had been in place for decades.","zh-TW":"新法規取代了已實施數十年的舊規定。"},{"en":"Digital music services have largely superseded physical CD sales.","zh-TW":"數字音樂服務在很大程度上已取代了實體CD銷售。"}]', '{"noun":"supersession","adjective":"superseding"}', NULL, 3, 6334, NULL),
(6335, 'supervise', '/ˈsuːpərvaɪz/', 'verb', '{"zh-TW":["監督；管理"],"en":["to oversee the work of others"]}', NULL, 'supervise employees / supervise a project / closely supervised', '[{"en":"She supervises a team of 15 engineers.","zh-TW":"她管理一個15人的工程師團隊。"},{"en":"The construction work is closely supervised.","zh-TW":"施工工程受到密切監督。"}]', '{"noun":"supervision, supervisor","verb":"supervise","adjective":"supervisory"}', NULL, 3, 6335, NULL),
(6336, 'supervisor', '/ˈsuːpərvaɪzər/', 'noun', '{"zh-TW":["主管；監督者"],"en":["a person who oversees the work of other employees"]}', NULL, 'direct supervisor / report to a supervisor / supervisory role', '[{"en":"He reported any issues directly to his supervisor.","zh-TW":"他直接向主管報告任何問題。"},{"en":"The supervisor provided daily guidance to the team.","zh-TW":"主管每天向團隊提供指導。"}]', '{"plural":"supervisors","verb":"supervise","adjective":"supervisory"}', NULL, 4, 6336, NULL),
(6337, 'supplement', '/ˈsʌplɪmənt/', 'noun, verb', '{"zh-TW":["補充；補充物","補充"],"en":["something added to complete","to add to something"]}', NULL, 'supplement income / dietary supplement / supplement with', '[{"en":"Many freelancers supplement their income with part-time work.","zh-TW":"許多自由工作者用兼職來補充收入。"},{"en":"The report is supplemented with charts.","zh-TW":"報告附有圖表作為補充。"}]', '{"noun":"supplement","verb":"supplement","adjective":"supplementary"}', NULL, 4, 6337, 724),
(6338, 'supplier', '/səˈplaɪər/', 'noun', '{"zh-TW":["供應商"],"en":["a company that provides goods or services to another business"]}', NULL, 'key supplier / supplier relationship / preferred supplier / supplier evaluation', '[{"en":"The company maintains long-term relationships with key suppliers.","zh-TW":"公司與關鍵供應商保持長期關係。"},{"en":"A supplier audit was conducted to verify quality standards.","zh-TW":"進行了供應商審計以驗證品質標準。"}]', '{"plural":"suppliers","verb":"supply"}', NULL, 3, 6338, NULL),
(6339, 'supplier audit', '/səˈplaɪər ˈɔːdɪt/', 'noun', '{"zh-TW":["供應商審計"],"en":["a formal inspection of a supplier operations, quality, and compliance"]}', NULL, 'conduct a supplier audit / annual supplier audit', '[{"en":"The procurement team conducted surprise supplier audits twice a year.","zh-TW":"採購團隊每年進行兩次突擊供應商審計。"},{"en":"A supplier audit revealed substandard conditions in the factory.","zh-TW":"供應商審計揭示了工廠中低於標準的條件。"}]', NULL, NULL, 5, 6339, NULL),
(6340, 'supplier evaluation', '/səˈplaɪər ɪˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["供應商評估"],"en":["a review of a supplier''s performance and reliability"]}', NULL, 'conduct supplier evaluation / supplier evaluation criteria', '[{"en":"Annual supplier evaluations help identify the best partners.","zh-TW":"年度供應商評估幫助識別最佳合作夥伴。"},{"en":"The procurement team uses a scorecard for supplier evaluation.","zh-TW":"採購團隊使用評分卡進行供應商評估。"}]', NULL, NULL, 5, 6340, NULL),
(6341, 'supply', '/səˈplaɪ/', 'noun, verb', '{"zh-TW":["供應；供給","供應；提供"],"en":["an amount available for use","to provide what is needed"]}', NULL, 'supply and demand / supply chain / supply shortage', '[{"en":"The supply chain was disrupted by the pandemic.","zh-TW":"供應鏈受到疫情的影響而中斷。"},{"en":"The company supplies parts to major automakers.","zh-TW":"這家公司為主要汽車製造商供應零件。"}]', '{"noun":"supply, supplier","verb":"supply"}', NULL, 2, 6341, 63),
(6342, 'supply agreement', '/səˈplaɪ əˈɡriːmənt/', 'noun', '{"zh-TW":["供應協議"],"en":["a contract between a supplier and buyer specifying terms for supply of goods"]}', NULL, 'sign a supply agreement / supply agreement terms', '[{"en":"A three-year supply agreement was signed to ensure pricing stability.","zh-TW":"簽署了三年供應協議以確保定價穩定。"},{"en":"The supply agreement includes volume commitments and delivery terms.","zh-TW":"供應協議包括數量承諾和交貨條款。"}]', NULL, NULL, 5, 6342, NULL),
(6343, 'supply and demand', '/səˈplaɪ ənd dɪˈmɑːnd/', 'noun', '{"zh-TW":["供求關係"],"en":["the relationship between the availability and desire for goods"]}', NULL, 'balance supply and demand / law of supply and demand', '[{"en":"Prices are determined by the law of supply and demand.","zh-TW":"價格由供求規律決定。"},{"en":"The shortage caused supply and demand to become severely imbalanced.","zh-TW":"短缺導致供求關係嚴重失衡。"}]', NULL, NULL, 5, 6343, NULL),
(6344, 'supply chain', '/səˈplaɪ tʃeɪn/', 'noun', '{"zh-TW":["供應鏈"],"en":["the network of businesses involved in producing and delivering a product"]}', NULL, 'global supply chain / supply chain disruption / supply chain resilience', '[{"en":"The pandemic exposed vulnerabilities in global supply chains.","zh-TW":"疫情暴露了全球供應鏈的脆弱性。"},{"en":"Diversifying the supply chain reduces dependency on single suppliers.","zh-TW":"多元化供應鏈降低了對單一供應商的依賴。"}]', '{"adjective":"supply-chain"}', NULL, 4, 6344, NULL),
(6345, 'supply chain disruption', '/səˈplaɪ tʃeɪn dɪsˈrʌpʃən/', 'noun', '{"zh-TW":["供應鏈中斷"],"en":["an interruption in the normal flow of goods in a supply chain"]}', NULL, 'manage supply chain disruption / supply chain disruption impact', '[{"en":"The pandemic caused significant supply chain disruptions worldwide.","zh-TW":"疫情在全球範圍內造成了重大的供應鏈中斷。"},{"en":"Companies built larger inventories to buffer against supply chain disruptions.","zh-TW":"公司建立了更大的庫存以緩衝供應鏈中斷的影響。"}]', NULL, NULL, 5, 6345, NULL),
(6346, 'supply chain management', '/səˈplaɪ tʃeɪn ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["供應鏈管理"],"en":["overseeing the flow of goods from supplier to customer"]}', NULL, 'supply chain management software / global supply chain management', '[{"en":"Supply chain management was disrupted by the pandemic.","zh-TW":"供應鏈管理因疫情而受到干擾。"},{"en":"Efficient supply chain management cuts delivery times.","zh-TW":"高效的供應鏈管理縮短了交貨時間。"}]', '{"adjective":"supply-chain"}', NULL, 5, 6346, NULL),
(6347, 'supply chain optimization', '/''sʌplaɪ tʃeɪn ˌɒptɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["供應鏈優化"],"en":["the process of making a supply chain as efficient and cost-effective as possible"]}', NULL, 'achieve supply chain optimization / supply chain optimization strategy', '[{"en":"Supply chain optimization reduced production costs and improved delivery times.","zh-TW":"供應鏈優化降低了生產成本並改善了交付時間。"},{"en":"Data analytics plays a crucial role in modern supply chain optimization.","zh-TW":"數據分析在現代供應鏈優化中發揮著至關重要的作用。"}]', NULL, NULL, 5, 6347, NULL),
(6348, 'supply chain visibility', '/səˈplaɪ tʃeɪn ˌvɪzɪˈbɪlɪti/', 'noun', '{"zh-TW":["供應鏈可視性"],"en":["the ability to track products and components throughout the supply chain"]}', NULL, 'improve supply chain visibility / supply chain visibility tools', '[{"en":"Real-time data improves supply chain visibility across all stages.","zh-TW":"實時數據改善了各階段的供應鏈可視性。"},{"en":"Greater supply chain visibility reduces the risk of stockouts.","zh-TW":"更強的供應鏈可視性降低了缺貨風險。"}]', NULL, NULL, 5, 6348, NULL),
(6349, 'supply contract', '/səˈplaɪ ˈkɒntrækt/', 'noun', '{"zh-TW":["供應合約"],"en":["a formal agreement for a supplier to provide goods or services"]}', NULL, 'sign a supply contract / long-term supply contract', '[{"en":"The company signed a five-year supply contract with the manufacturer.","zh-TW":"公司與製造商簽署了五年供應合約。"},{"en":"A supply contract locks in pricing to protect against cost increases.","zh-TW":"供應合約鎖定了定價以防止成本增加。"}]', NULL, NULL, 5, 6349, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6350, 'supply shock', '/səˈplaɪ ʃɒk/', 'noun', '{"zh-TW":["供給衝擊"],"en":["a sudden change in supply that dramatically affects the price of a good or service"]}', NULL, 'negative supply shock / positive supply shock / supply shock inflation', '[{"en":"The oil embargo caused a severe negative supply shock that triggered global inflation.","zh-TW":"石油禁運造成了嚴重的負面供給衝擊，引發了全球通膨。"},{"en":"New technology can create a positive supply shock by dramatically reducing production costs.","zh-TW":"新技術可以通過大幅降低生產成本來創造正面供給衝擊。"}]', NULL, NULL, 4, 6350, NULL),
(6351, 'supply-demand balance', '/səˈplaɪ dɪˈmɑːnd ˈbæləns/', 'noun', '{"zh-TW":["供需平衡"],"en":["the equilibrium between the amount of a good produced and consumer demand"]}', NULL, 'maintain supply-demand balance / disrupt the supply-demand balance', '[{"en":"Rising raw material costs disturbed the supply-demand balance.","zh-TW":"原材料成本上漲擾亂了供需平衡。"},{"en":"Market prices adjust automatically to restore supply-demand balance.","zh-TW":"市場價格自動調整以恢復供需平衡。"}]', NULL, NULL, 5, 6351, NULL),
(6352, 'supply-side economics', '/səˈplaɪ saɪd ˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["供給側經濟學"],"en":["economic theory that tax cuts and deregulation stimulate growth by boosting supply"]}', NULL, 'adopt supply-side economics / supply-side economics policy / critique of supply-side economics', '[{"en":"Supply-side economics argues that lowering corporate taxes boosts investment.","zh-TW":"供給側經濟學認為降低企業稅可以促進投資。"},{"en":"Critics argue that supply-side economics mainly benefits the wealthy.","zh-TW":"批評者認為供給側經濟學主要使富人受益。"}]', NULL, NULL, 5, 6352, NULL),
(6353, 'support', '/səˈpɔːrt/', 'noun, verb', '{"zh-TW":["支持；支援","支持；贊助"],"en":["help or encouragement","to give assistance to"]}', NULL, 'customer support / technical support / support a proposal', '[{"en":"The proposal received strong support from management.","zh-TW":"該提案獲得了管理層的大力支持。"},{"en":"We provide 24/7 customer support.","zh-TW":"我們提供全天候客戶支援。"}]', '{"noun":"support, supporter","verb":"support","adjective":"supportive"}', NULL, 3, 6353, 225),
(6354, 'suppose', '/səˈpoʊz/', 'verb', '{"zh-TW":["假設；認為"],"en":["to assume; to believe"]}', NULL, 'be supposed to / I suppose / suppose that', '[{"en":"You are supposed to submit the form by today.","zh-TW":"你應該在今天之前提交表格。"},{"en":"I suppose we could try a different approach.","zh-TW":"我想我們可以嘗試不同的方法。"}]', '{"noun":"supposition","verb":"suppose","adjective":"supposed"}', NULL, 3, 6354, NULL),
(6355, 'suppress', '/səˈpres/', 'verb', '{"zh-TW":["壓制；抑制"],"en":["to prevent from being expressed or known"]}', NULL, 'suppress information / suppress competition / suppress dissent', '[{"en":"The company tried to suppress negative reviews.","zh-TW":"公司試圖壓制負面評論。"},{"en":"Rising interest rates suppressed consumer spending.","zh-TW":"利率上升抑制了消費支出。"}]', '{"noun":"suppression","verb":"suppress"}', NULL, 3, 6355, NULL),
(6356, 'sure', '/ʃʊr/', 'adjective', '{"zh-TW":["確定的；當然"],"en":["certain; confident"]}', NULL, 'make sure / for sure', '[{"en":"Make sure you save the file.","zh-TW":"確保你儲存了檔案。"},{"en":"We will finish on time for sure.","zh-TW":"我們肯定會準時完成。"}]', '{"adjective":"sure","adverb":"surely"}', NULL, 1, 6356, NULL),
(6357, 'surety', '/ˈʃʊərɪti/', 'noun', '{"zh-TW":["保證人；保證金；擔保"],"en":["a formal guarantee or pledge; a person who takes responsibility for another''s obligation"]}', NULL, 'act as surety / provide surety / surety bond', '[{"en":"The defendant was released on bail after a surety was provided by a family member.","zh-TW":"在家庭成員提供擔保後，被告以保釋金釋放。"},{"en":"A surety bond protects clients against contractor default on a construction project.","zh-TW":"保證金保護客戶免受建設項目中承包商違約的影響。"}]', NULL, NULL, 2, 6357, NULL),
(6358, 'surge', '/sɜːrdʒ/', 'noun, verb', '{"zh-TW":["激增；猛漲","急增；湧現"],"en":["a sudden large increase","to increase suddenly"]}', NULL, 'surge in demand / price surge / power surge', '[{"en":"There was a surge in online orders during the holiday.","zh-TW":"假期期間線上訂單激增。"},{"en":"Oil prices surged after the announcement.","zh-TW":"公告後油價猛漲。"}]', '{"noun":"surge","verb":"surge"}', NULL, 2, 6358, NULL),
