(6968, 'VPN', '/viː piː ɛn/', 'noun', '{"zh-TW":["虛擬私人網路"],"en":["a secure network connection that encrypts internet traffic"]}', NULL, 'use a VPN / VPN access', '[{"en":"Employees must use a VPN when working remotely.","zh-TW":"員工遠端工作時必須使用VPN。"},{"en":"The VPN protects company data on public Wi-Fi networks.","zh-TW":"VPN在公共無線網路上保護公司數據。"}]', NULL, NULL, 1, 6968, NULL),
(6969, 'vulnerable', '/ˈvʌlnərəbl/', 'adjective', '{"zh-TW":["脆弱的；易受攻擊的"],"en":["susceptible to harm or attack"]}', NULL, 'vulnerable to / vulnerable position / economically vulnerable', '[{"en":"Small businesses are vulnerable to economic downturns.","zh-TW":"小型企業容易受經濟衰退的影響。"},{"en":"The system is vulnerable to cyber attacks.","zh-TW":"該系統容易受到網路攻擊。"}]', '{"noun":"vulnerability","adjective":"vulnerable"}', NULL, 4, 6969, NULL),
(6970, 'wage', '/weɪdʒ/', 'noun', '{"zh-TW":["工資；薪水"],"en":["a fixed regular payment for work, usually hourly"]}', NULL, 'minimum wage / wage increase / hourly wage', '[{"en":"The minimum wage was raised to $15 per hour.","zh-TW":"最低工資提高到每小時15美元。"},{"en":"Workers demanded a wage increase.","zh-TW":"工人要求加薪。"}]', '{"noun":"wage, wages"}', NULL, 1, 6970, NULL),
(6971, 'wage freeze', '/weɪdʒ friːz/', 'noun', '{"zh-TW":["工資凍結"],"en":["a policy of not increasing wages for a defined period"]}', NULL, 'implement a wage freeze / end the wage freeze', '[{"en":"A wage freeze was imposed across the organization to reduce costs.","zh-TW":"為降低成本在全組織範圍內實施了工資凍結。"},{"en":"After the wage freeze, staff received a 5% catch-up increase.","zh-TW":"工資凍結結束後，員工獲得了5%的補償性加薪。"}]', NULL, NULL, 4, 6971, NULL),
(6972, 'wage gap', '/weɪdʒ ɡæp/', 'noun', '{"zh-TW":["薪資差距"],"en":["the difference in earnings between different groups of workers"]}', NULL, 'address the wage gap / gender wage gap', '[{"en":"The company conducted a study to assess the gender wage gap.","zh-TW":"公司進行了一項研究以評估性別薪資差距。"},{"en":"Closing the wage gap requires transparent pay policies.","zh-TW":"縮小薪資差距需要透明的薪酬政策。"}]', NULL, NULL, 3, 6972, NULL),
(6973, 'wage growth', '/weɪdʒ ɡroʊθ/', 'noun', '{"zh-TW":["薪資增長"],"en":["the increase in wages over a given period"]}', NULL, 'accelerate wage growth / above-average wage growth', '[{"en":"Strong wage growth boosted consumer spending.","zh-TW":"強勁的薪資增長提升了消費者支出。"},{"en":"Wage growth lagged behind inflation, reducing real purchasing power.","zh-TW":"薪資增長落後於通脹，降低了實際購買力。"}]', NULL, NULL, 4, 6973, NULL),
(6974, 'wait', 'weɪt', 'verb', '{"zh-TW":["等待；等候","服務"],"en":["to stay until something happens","to serve at table"]}', NULL, 'wait for approval/a response', '[{"en":"Please wait for confirmation.","zh-TW":"請等待確認。"}]', '{"noun":"wait, waiter","adjective":"waiting"}', NULL, 1, 6974, NULL),
(6975, 'waiter', '/ˈweɪtər/', 'noun', '{"zh-TW":["服務生；侍者"],"en":["a person who serves food in a restaurant"]}', NULL, 'ask the waiter / experienced waiter', '[{"en":"The waiter was attentive and friendly throughout the meal.","zh-TW":"服務生在整個用餐過程中都很周到友善。"},{"en":"Please ask the waiter for today''s soup of the day.","zh-TW":"請詢問服務生今日例湯。"}]', '{"noun":"waitress","verb":"wait"}', NULL, 2, 6975, NULL),
(6976, 'waiting period', '/ˈweɪtɪŋ ˈpɪəriəd/', 'noun', '{"zh-TW":["等待期間"],"en":["a period before insurance benefits become effective"]}', NULL, 'waiting period requirement / six-month waiting period', '[{"en":"There is a six-month waiting period for maternity benefits.","zh-TW":"生育福利有六個月的等待期間。"},{"en":"The waiting period begins from the date of enrollment.","zh-TW":"等待期間從入保日期開始計算。"}]', NULL, NULL, 5, 6976, NULL),
(6977, 'waiting room', '/ˈweɪtɪŋ ruːm/', 'noun', '{"zh-TW":["候診室；等候室"],"en":["a room where patients wait before being seen"]}', NULL, 'sit in the waiting room / waiting room etiquette', '[{"en":"The waiting room was full of patients.","zh-TW":"候診室裡坐滿了患者。"},{"en":"Please wait in the waiting room until your name is called.","zh-TW":"請在候診室等候，直到叫到您的名字。"}]', NULL, NULL, 4, 6977, NULL),
(6978, 'waitlist', '/''weɪtlɪst/', 'noun', '{"zh-TW":["候補名單；等待名單"],"en":["a list of people waiting for something that is currently unavailable"]}', NULL, 'on the waitlist / join the waitlist / waitlist notification', '[{"en":"She was on the waitlist for the sold-out flight and got a seat at the last minute.","zh-TW":"她在售罄航班的候補名單上，並在最後一刻得到了一個座位。"},{"en":"The popular restaurant had a waitlist of over two hours on weekends.","zh-TW":"這家受歡迎的餐廳週末等待名單超過兩小時。"}]', NULL, NULL, 3, 6978, NULL),
(6979, 'waive', '/weɪv/', 'verb', '{"zh-TW":["放棄（權利）；免除"],"en":["to refrain from insisting on a right or claim"]}', NULL, 'waive a fee / waive the right / waive requirements', '[{"en":"The bank waived the processing fee.","zh-TW":"銀行免除了手續費。"},{"en":"She waived her right to appeal.","zh-TW":"她放棄了上訴權。"}]', '{"noun":"waiver","verb":"waive"}', NULL, 2, 6979, NULL),
(6980, 'waiver', '/ˈweɪvər/', 'noun', '{"zh-TW":["棄權；豁免聲明"],"en":["a voluntary relinquishment of a right or claim"]}', NULL, 'sign a waiver / liability waiver', '[{"en":"Participants must sign a liability waiver before joining.","zh-TW":"參與者在加入前必須簽署責任豁免聲明。"},{"en":"The company issued a waiver for the late payment.","zh-TW":"公司對逾期付款發出了豁免聲明。"}]', '{"verb":"waive"}', NULL, 2, 6980, NULL),
(6981, 'wake-up call', '/ˈweɪk ʌp kɔːl/', 'noun', '{"zh-TW":["叫醒服務"],"en":["a phone call to wake a guest at a requested time"]}', NULL, 'request a wake-up call / early wake-up call', '[{"en":"Please request a wake-up call for 6 am.","zh-TW":"請要求早上6點的叫醒服務。"},{"en":"The front desk will arrange a wake-up call for you.","zh-TW":"前台將為您安排叫醒服務。"}]', NULL, NULL, 4, 6981, NULL),
(6982, 'walk', 'wɔːk', 'verb', '{"zh-TW":["步行；走","帶領"],"en":["to move on foot","to guide through something"]}', NULL, 'walk through a process', '[{"en":"Let me walk you through the steps.","zh-TW":"讓我帶您了解這些步驟。"}]', '{"noun":"walk, walker","adjective":"walking"}', NULL, 1, 6982, NULL),
(6983, 'wander', '/''wɒndər/', 'verb', '{"zh-TW":["漫步；閒逛"],"en":["to walk or move in a leisurely, casual, or aimless way"]}', NULL, 'wander around / wander through / wander aimlessly', '[{"en":"They wandered through the cobblestone streets without any particular plan.","zh-TW":"他們漫步在鵝卵石街道上，沒有任何特定計劃。"},{"en":"I love to wander through the local market on Saturday mornings.","zh-TW":"我喜歡在星期六早上漫步在當地市場。"}]', '{"noun":"wanderer"}', NULL, 2, 6983, NULL),
(6984, 'wanderlust', '/''wɒndərlʌst/', 'noun', '{"zh-TW":["對旅行的渴望；流浪癖"],"en":["a strong desire to travel and explore the world"]}', NULL, 'feel wanderlust / satisfy wanderlust / overcome wanderlust', '[{"en":"Her wanderlust led her to visit over fifty countries before the age of thirty.","zh-TW":"她對旅行的渴望讓她在三十歲之前走訪了超過五十個國家。"},{"en":"His wanderlust was so strong that he quit his job to travel the world.","zh-TW":"他對旅行的渴望如此強烈，以至於他辭掉工作去環遊世界。"}]', NULL, NULL, 4, 6984, NULL),
(6985, 'want', 'wɒnt', 'verb', '{"zh-TW":["【主要意義-動詞】想要；希望","【次要意義-名詞】缺乏；匱乏；貧困"],"en":["[primary - verb] to desire or wish for something","[secondary - noun] a lack or shortage; poverty"]}', NULL, 'for want of / in want / want for nothing', '[{"en":"The project failed for want of adequate funding.","zh-TW":"由於缺乏足夠的資金，這個專案失敗了。"},{"en":"Many families in the region live in want.","zh-TW":"該地區許多家庭生活在貧困中。"},{"en":"The plan was abandoned for want of support from upper management.","zh-TW":"由於缺乏高層管理的支持，該計劃被放棄了。"}]', '{"adjective":"wanting"}', '名詞 want 意為「缺乏/匱乏」，片語 for want of = 由於缺乏……，常見於 TOEIC 閱讀正式書面語境，容易與動詞用法混淆。', 1, 6985, NULL),
(6986, 'ward round', '/wɔːrd raʊnd/', 'noun', '{"zh-TW":["巡房；病房巡診"],"en":["a visit by a doctor to all patients in a ward"]}', NULL, 'conduct a ward round / morning ward round / ward round assessment', '[{"en":"The consultant performs a ward round every morning to review patients.","zh-TW":"顧問醫師每天早上進行巡房審查患者情況。"},{"en":"Ward rounds ensure patients receive timely updates on their treatment.","zh-TW":"巡房確保患者及時獲得治療進展的更新。"}]', NULL, NULL, 4, 6986, NULL),
(6987, 'warehouse', '/ˈwerhɑʊs/', 'noun', '{"zh-TW":["倉庫；貨倉"],"en":["a large building for storing goods"]}', NULL, 'warehouse management / distribution warehouse / warehouse space', '[{"en":"The new warehouse doubles our storage capacity.","zh-TW":"新倉庫使我們的儲存容量翻倍。"},{"en":"Goods are shipped directly from the warehouse.","zh-TW":"貨物直接從倉庫出貨。"}]', '{"noun":"warehouse, warehousing"}', NULL, 3, 6987, 242),
(6988, 'warehousing', '/''weərˌhaʊzɪŋ/', 'noun', '{"zh-TW":["倉儲；倉庫業務"],"en":["the activity or business of storing goods in a warehouse"]}', NULL, 'cost of warehousing / efficient warehousing / outsource warehousing', '[{"en":"Outsourcing warehousing can reduce costs for small businesses.","zh-TW":"外包倉儲可以為小型企業降低成本。"},{"en":"Automated warehousing systems improve speed and accuracy in order fulfillment.","zh-TW":"自動化倉儲系統提高了訂單履行的速度和準確性。"}]', '{"noun":"warehouse"}', NULL, 4, 6988, NULL),
(6989, 'warm lead', '/wɔːrm liːd/', 'noun', '{"zh-TW":["暖潛在客戶；有意向客戶"],"en":["a potential customer who has already shown interest in a product"]}', NULL, 'follow up on warm leads / convert warm leads / qualify warm leads', '[{"en":"Warm leads are far more likely to convert than cold ones.","zh-TW":"暖潛在客戶比冷潛在客戶更有可能轉換。"},{"en":"She focused on warm leads to shorten the sales cycle.","zh-TW":"她專注於暖潛在客戶以縮短銷售週期。"}]', NULL, NULL, 3, 6989, NULL),
(6990, 'warm up', '/''wɔːrm ʌp/', 'verb', '{"zh-TW":["熱身；做準備運動"],"en":["to prepare the body for exercise by performing light activities"]}', NULL, 'warm up before exercise / warm up properly / spend time warming up', '[{"en":"It is important to warm up before any strenuous physical activity.","zh-TW":"在任何劇烈體育活動之前熱身是很重要的。"},{"en":"The athletes spent twenty minutes warming up before the championship game.","zh-TW":"運動員在錦標賽比賽前花了二十分鐘熱身。"}]', NULL, NULL, 3, 6990, NULL),
(6991, 'warm-up', '/''wɔːrm ʌp/', 'noun', '{"zh-TW":["暖身；熱身活動"],"en":["a period of gentle exercise done before more intense physical activity"]}', NULL, 'do a warm-up / proper warm-up / dynamic warm-up', '[{"en":"A proper warm-up reduces the risk of injury during exercise.","zh-TW":"適當的暖身可以降低運動時受傷的風險。"},{"en":"The team spent fifteen minutes on a warm-up before the match began.","zh-TW":"球隊在比賽開始前花了十五分鐘進行暖身。"}]', '{"verb":"warm up"}', NULL, 3, 6991, NULL),
(6992, 'warm-up exercise', '/''wɔːrm ʌp ˌeksəsaɪz/', 'noun', '{"zh-TW":["熱身運動；準備活動"],"en":["light physical activity done before more intense exercise to prepare the body"]}', NULL, 'do warm-up exercises / complete warm-up exercises / skip warm-up exercises', '[{"en":"The trainer guided the group through five minutes of warm-up exercises.","zh-TW":"教練帶領大家完成了五分鐘的熱身運動。"},{"en":"Never skip warm-up exercises before a strenuous workout to prevent injuries.","zh-TW":"劇烈運動前千萬不要跳過熱身運動，以防止受傷。"}]', NULL, NULL, 5, 6992, NULL),
(6993, 'warrant', '/ˈwɒrənt/', 'noun', '{"zh-TW":["搜索令；逮捕令","授權令；正當理由","保證；使有正當理由"],"en":["an official document allowing police action","a document authorizing action; justification","to justify; to guarantee"]}', NULL, 'search warrant / arrest warrant; warrant attention / arrest warrant / warrant further investigation', '[{"en":"Police obtained a search warrant.","zh-TW":"警方取得了搜索令。"},{"en":"There''s a warrant for his arrest.","zh-TW":"有一張對他的逮捕令。"},{"en":"The situation warrants immediate action.","zh-TW":"情況需要立即採取行動。"},{"en":"The findings warrant further investigation.","zh-TW":"這些發現值得進一步調查。"}]', '{"verb":"warrant","noun":"warrant, warranty"}', NULL, 3, 6993, NULL),
(6994, 'warranty', '/ˈwɒrənti/', 'noun', '{"zh-TW":["保固；保證書"],"en":["a written guarantee of product repair or replacement","a guarantee about the condition of a product"]}', '{"root":{"text":"warrant","meaning":"guarantee (保證)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"保證的狀態，即「保固」。"}', 'under warranty / warranty period / extended warranty', '[{"en":"The laptop is still under warranty.","zh-TW":"這台筆電還在保固期內。"},{"en":"Would you like to purchase an extended warranty?","zh-TW":"你要購買延長保固嗎？"},{"en":"The product comes with a two-year warranty.","zh-TW":"該產品附有兩年保固。"},{"en":"Repairs are free if the item is still under warranty.","zh-TW":"如果商品仍在保固期內，維修免費。"}]', '{"noun":"warranty, warrant"}', NULL, 3, 6994, NULL),
(6995, 'warranty claim', '/ˈwɒrənti kleɪm/', 'noun', '{"zh-TW":["保固索賠"],"en":["a request to repair or replace a product under warranty"]}', NULL, 'file a warranty claim / valid warranty claim', '[{"en":"She filed a warranty claim for the defective laptop.","zh-TW":"她就有問題的筆記型電腦提出了保固索賠。"},{"en":"Warranty claims must be submitted within the warranty period.","zh-TW":"保固索賠必須在保固期內提交。"}]', NULL, NULL, 5, 6995, NULL),
(6996, 'waste', '/weɪst/', 'noun, verb', '{"zh-TW":["浪費；廢物","浪費"],"en":["unwanted material; extravagant use","to use carelessly"]}', NULL, 'waste of time / reduce waste / waste disposal', '[{"en":"The company reduced waste by 30% through recycling.","zh-TW":"公司透過回收減少了30%的廢物。"},{"en":"Don''t waste time on unnecessary meetings.","zh-TW":"不要把時間浪費在不必要的會議上。"}]', '{"noun":"waste, wastage","verb":"waste","adjective":"wasteful"}', NULL, 2, 6996, 483),
(6997, 'wastewater treatment', '/ˈweɪstwɔːtər ˈtriːtmənt/', 'noun', '{"zh-TW":["污水處理；廢水處理"],"en":["the process of removing contaminants from water before discharge"]}', NULL, 'wastewater treatment plant / advanced wastewater treatment / wastewater treatment process', '[{"en":"Effective wastewater treatment prevents river and ocean pollution.","zh-TW":"有效的污水處理防止河流和海洋污染。"},{"en":"Investment in wastewater treatment infrastructure is a public health priority.","zh-TW":"投資污水處理基礎設施是公共衛生優先事項。"}]', NULL, NULL, 5, 6997, NULL),
(6998, 'watch', 'wɒtʃ', 'verb', '{"zh-TW":["觀看；注意","監視"],"en":["to look at something carefully","to monitor"]}', NULL, 'watch a trend/presentation', '[{"en":"Watch for any unusual expenses.","zh-TW":"注意任何不尋常的費用。"}]', '{"noun":"watch, watcher","adjective":"watchful","adverb":"watchfully"}', NULL, 2, 6998, NULL),
(6999, 'water conservation', '/ˈwɔːtər ˌkɒnsəˈveɪʃən/', 'noun', '{"zh-TW":["水資源保育；節水"],"en":["the careful use and protection of water resources"]}', NULL, 'promote water conservation / water conservation measure', '[{"en":"Water conservation is critical in drought-prone regions.","zh-TW":"水資源保育在乾旱易發地區至關重要。"},{"en":"Simple steps like fixing leaks support water conservation.","zh-TW":"修復漏水等簡單措施有助於節水。"}]', NULL, NULL, 5, 6999, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(7000, 'water scarcity', '/ˈwɔːtər ˈskeərsɪti/', 'noun', '{"zh-TW":["水資源匱乏；水荒"],"en":["a shortage of fresh water affecting communities and ecosystems"]}', NULL, 'address water scarcity / water scarcity crisis / water scarcity solutions', '[{"en":"Climate change is expected to worsen water scarcity in many regions.","zh-TW":"氣候變化預計將惡化許多地區的水資源匱乏狀況。"},{"en":"Water scarcity forces communities to choose between agriculture and drinking water.","zh-TW":"水資源匱乏迫使社區在農業和飲用水之間做出選擇。"}]', NULL, NULL, 5, 7000, NULL),
(7001, 'waterfall', '/''wɔːtəfɔːl/', 'noun', '{"zh-TW":["瀑布"],"en":["a cascade of water falling from a height, formed when a river flows over a precipice"]}', NULL, 'magnificent waterfall / visit a waterfall / waterfall hike', '[{"en":"The waterfall at the end of the trail was worth the three-hour hike.","zh-TW":"小徑盡頭的瀑布值得三小時的徒步旅行。"},{"en":"Visitors can swim in the pool at the base of the waterfall.","zh-TW":"遊客可以在瀑布底部的水潭游泳。"}]', NULL, NULL, 3, 7001, NULL),
(7002, 'waterfall methodology', '/ˈwɔːtərfɔːl meθəˈdɒlədʒi/', 'noun', '{"zh-TW":["瀑布式開發方法論"],"en":["a sequential project management approach where phases follow one after another"]}', NULL, 'waterfall methodology phases / use waterfall methodology', '[{"en":"The waterfall methodology requires completing each phase before moving to the next.","zh-TW":"瀑布式開發方法論要求在進入下一階段前完成每個階段。"},{"en":"Waterfall is suitable for projects with clearly defined requirements.","zh-TW":"瀑布式開發適用於需求明確的項目。"}]', NULL, NULL, 5, 7002, NULL),
(7003, 'way', 'weɪ', 'noun', '{"zh-TW":["方式；方法","路途"],"en":["a method or manner","a route or path"]}', NULL, 'find a way/on the way', '[{"en":"Is there a better way to handle this?","zh-TW":"有更好的方法來處理這個問題嗎？"}]', '{"adjective":"wayward","adverb":"anyway"}', NULL, 1, 7003, NULL),
(7004, 'wealth', '/welθ/', 'noun', '{"zh-TW":["財富；豐富"],"en":["an abundance of possessions or resources"]}', NULL, 'wealth management / wealth of experience / accumulate wealth', '[{"en":"Wealth management services cater to high-net-worth individuals.","zh-TW":"財富管理服務面向高淨值人士。"},{"en":"She brings a wealth of experience to the role.","zh-TW":"她為這個職位帶來了豐富的經驗。"}]', '{"noun":"wealth","adjective":"wealthy"}', NULL, 2, 7004, 484),
(7005, 'wealth accumulation', '/welθ ˌækjʊmjʊˈleɪʃən/', 'noun', '{"zh-TW":["財富積累"],"en":["the process of gradually building financial assets over time"]}', NULL, 'focus on wealth accumulation / wealth accumulation strategy', '[{"en":"Long-term investment is the most reliable path to wealth accumulation.","zh-TW":"長期投資是財富積累最可靠的途徑。"},{"en":"Compound interest is a powerful tool for wealth accumulation.","zh-TW":"複利是財富積累的強大工具。"}]', NULL, NULL, 5, 7005, NULL),
(7006, 'wealth management', '/welθ ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["財富管理"],"en":["financial services providing investment advice and management to high-net-worth clients"]}', NULL, 'use a wealth management firm / wealth management services', '[{"en":"She engaged a wealth management firm to manage her investment portfolio.","zh-TW":"她聘請了一家財富管理公司管理她的投資組合。"},{"en":"Wealth management services include tax planning and estate management.","zh-TW":"財富管理服務包括稅務規劃和遺產管理。"}]', NULL, NULL, 5, 7006, NULL),
(7007, 'weather', '/ˈweðər/', 'noun', '{"zh-TW":["天氣"],"en":["the state of the atmosphere at a particular time"]}', '{"root":{"text":"weather","meaning":"wind/air (風/空氣)"},"logic":"源自古英語 weder（大氣狀態）。"}', 'weather forecast / bad weather / weather conditions', '[{"en":"What''s the weather like today?","zh-TW":"今天天氣如何？"},{"en":"Bad weather delayed our flight.","zh-TW":"惡劣天氣延誤了我們的航班。"}]', '{"verb":"weather"}', NULL, 3, 7007, NULL),
(7008, 'web browser', '/wɛb ˈbraʊzər/', 'noun', '{"zh-TW":["網頁瀏覽器"],"en":["software used to access and navigate the internet"]}', NULL, 'open a web browser / web browser compatibility', '[{"en":"Clear your web browser''s cache to improve performance.","zh-TW":"清除您的網頁瀏覽器快取以提升效能。"},{"en":"The website is compatible with all major web browsers.","zh-TW":"該網站與所有主要網頁瀏覽器相容。"}]', NULL, NULL, 4, 7008, NULL),
(7009, 'webhook', '/ˈwebhʊk/', 'noun', '{"zh-TW":["網路回調；Webhook"],"en":["a way for apps to receive automated notifications when events occur"]}', NULL, 'configure a webhook / webhook endpoint / trigger a webhook', '[{"en":"The payment system uses a webhook to notify the server of successful transactions.","zh-TW":"支付系統使用Webhook通知伺服器成功交易。"},{"en":"Webhooks eliminate the need to poll an API for status updates.","zh-TW":"Webhook消除了輪詢API進行狀態更新的需要。"}]', NULL, NULL, 3, 7009, NULL),
(7010, 'website', '/ˈwɛbsaɪt/', 'noun', '{"zh-TW":["網站"],"en":["a set of pages on the internet"]}', NULL, 'visit a website / website design', '[{"en":"Visit our website for more info.","zh-TW":"請訪問我們的網站了解更多資訊。"},{"en":"The website was redesigned last month.","zh-TW":"網站上個月重新設計了。"}]', NULL, NULL, 3, 7010, NULL),
(7011, 'weight class', '/''weɪt klɑːs/', 'noun', '{"zh-TW":["量級；體重級別"],"en":["a category based on body weight within which competitors are matched in combat sports"]}', NULL, 'fight in the same weight class / move up a weight class / weight class limit', '[{"en":"The boxer moved up to the next weight class to face new competition.","zh-TW":"這位拳擊手晉升到更高的量級以面對新的競爭。"},{"en":"Wrestlers must stay within their weight class during competition.","zh-TW":"摔跤手在比賽期間必須保持在他們的量級範圍內。"}]', NULL, NULL, 4, 7011, NULL),
(7012, 'weight room', '/''weɪt ruːm/', 'noun', '{"zh-TW":["重量訓練室；舉重室"],"en":["a room in a gym or sports facility containing weight training equipment"]}', NULL, 'spend time in the weight room / weight room session / weight room workout', '[{"en":"He spent two hours in the weight room before practice each morning.","zh-TW":"他每天早上訓練前在重量訓練室訓練了兩個小時。"},{"en":"The new weight room was equipped with both free weights and resistance machines.","zh-TW":"新的重量訓練室配備了自由重量器材和阻力機器。"}]', NULL, NULL, 4, 7012, NULL),
(7013, 'weighted average', '/ˈweɪtɪd ˈævərɪdʒ/', 'noun', '{"zh-TW":["加權平均"],"en":["an average where different values are given different levels of importance"]}', NULL, 'calculate weighted average / weighted average cost', '[{"en":"Weighted average cost of capital reflects both debt and equity costs.","zh-TW":"加權平均資本成本反映了債務和股本成本。"},{"en":"The portfolio return was calculated as a weighted average across all holdings.","zh-TW":"投資組合回報按所有持倉的加權平均計算。"}]', '{"abbreviation":"WACC for capital cost"}', NULL, 5, 7013, NULL),
(7014, 'weighted average cost of capital', '/ˈweɪtɪd ˈævərɪdʒ kɒst əv ˈkæpɪtl/', 'noun', '{"zh-TW":["加權平均資本成本"],"en":["the average rate a company pays to finance its assets from all sources"]}', NULL, 'calculate weighted average cost of capital / above the WACC', '[{"en":"Projects must exceed the weighted average cost of capital to create value.","zh-TW":"項目必須超過加權平均資本成本才能創造價值。"},{"en":"The WACC is used as the discount rate in DCF valuations.","zh-TW":"加權平均資本成本用作折現現金流估值中的折現率。"}]', '{"abbreviation":"WACC"}', NULL, 5, 7014, NULL),
(7015, 'weightlifting', '/''weɪtˌlɪftɪŋ/', 'noun', '{"zh-TW":["舉重；重量訓練"],"en":["the sport or activity of lifting barbells or other heavy weights as an exercise or in competition"]}', NULL, 'train in weightlifting / weightlifting competition / weightlifting record', '[{"en":"She took up weightlifting to build muscle strength and improve bone density.","zh-TW":"她開始舉重訓練以增強肌肉力量並改善骨密度。"},{"en":"Proper form is essential in weightlifting to prevent serious injuries.","zh-TW":"正確的姿勢在舉重中是必不可少的，以防止嚴重受傷。"}]', '{"verb":"weightlift","noun":"weightlifter"}', NULL, 5, 7015, NULL),
(7016, 'welfare', '/ˈwelfer/', 'noun', '{"zh-TW":["福利；福祉"],"en":["the health and happiness of a person or group"]}', NULL, 'employee welfare / social welfare / welfare benefits', '[{"en":"Employee welfare is a top priority for the company.","zh-TW":"員工福利是公司的首要任務。"},{"en":"The government increased social welfare spending.","zh-TW":"政府增加了社會福利支出。"}]', '{"noun":"welfare"}', NULL, 3, 7016, 486),
(7017, 'welfare economics', '/ˈwelfeər ˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["福利經濟學"],"en":["the branch of economics that deals with the economic well-being of individuals and society"]}', NULL, 'study welfare economics / tools of welfare economics / applied welfare economics', '[{"en":"Welfare economics uses concepts such as efficiency and equity to evaluate policy outcomes.","zh-TW":"福利經濟學使用效率和公平等概念來評估政策結果。"},{"en":"Cost-benefit analysis is a key tool in applied welfare economics.","zh-TW":"成本效益分析是應用福利經濟學的關鍵工具。"}]', NULL, NULL, 5, 7017, NULL),
(7018, 'welfare state', '/ˈwelfɛər steɪt/', 'noun', '{"zh-TW":["福利國家"],"en":["a government system providing social protection to its citizens"]}', NULL, 'build a welfare state / welfare state reform / sustainable welfare state', '[{"en":"The welfare state provides a safety net for vulnerable populations.","zh-TW":"福利國家為弱勢族群提供安全網。"},{"en":"Aging populations are straining welfare state budgets across Europe.","zh-TW":"人口老齡化正在加重歐洲各地福利國家預算的壓力。"}]', NULL, NULL, 5, 7018, NULL),
(7019, 'well', '/wel/', 'verb, noun, adverb, adjective', '{"zh-TW":["【主要意義-副詞】好地；充分地","【次要意義-動詞】噴湧；湧出（情緒/液體）","【次要意義-名詞】水井；油井"],"en":["[primary - adverb] in a good or satisfactory way","[secondary - verb] to flow upward or outward like water from a spring","[secondary - noun] a hole drilled to obtain water or oil"]}', NULL, 'well up / tears welled / well of emotion / oil well', '[{"en":"Tears welled up in her eyes when she heard the news.","zh-TW":"當她聽到這個消息時，淚水湧上了她的眼眶。"},{"en":"Oil wells in the region produce over a million barrels per day.","zh-TW":"該地區的油井每天生產超過百萬桶石油。"},{"en":"A sense of pride welled up within the team after the successful launch.","zh-TW":"成功發布後，整個團隊湧現出一種自豪感。"}]', NULL, '動詞 well up 意為「（情緒）湧現；（液體）湧出」，名詞 well = 「水井/油井」，這兩種次要用法常見於 TOEIC 閱讀的能源或情感描述語境。', 1, 7019, NULL),
(7020, 'well-established', 'wɛl ɪˈstæblɪʃt', 'adjective', '{"zh-TW":["成熟的；成立已久的","信譽好的"],"en":["having been in existence for long","having a good reputation"]}', NULL, 'well-established company/well-established brand', '[{"en":"We are a well-established company in Taiwan.","zh-TW":"我們是台灣一家成立已久的公司。"}]', NULL, NULL, 5, 7020, NULL),
(7021, 'wellness center', '/ˈwɛlnɪs ˈsɛntər/', 'noun', '{"zh-TW":["健康中心"],"en":["a facility offering health and beauty treatments"]}', NULL, 'use the wellness center / wellness center services', '[{"en":"The resort''s wellness center offers yoga and meditation.","zh-TW":"度假村的健康中心提供瑜伽和冥想課程。"},{"en":"Book a treatment at the wellness center in advance.","zh-TW":"請提前預訂健康中心的療程。"}]', NULL, NULL, 5, 7021, NULL),
(7022, 'wellness program', '/ˈwɛlnɪs ˈprəʊɡræm/', 'noun', '{"zh-TW":["健康促進計劃"],"en":["a program aimed at promoting good health habits"]}', NULL, 'corporate wellness program / join a wellness program', '[{"en":"The company offers a wellness program including gym membership.","zh-TW":"公司提供包含健身房會員的健康促進計劃。"},{"en":"Participating in the wellness program reduces insurance premiums.","zh-TW":"參與健康促進計劃可降低保險費。"}]', NULL, NULL, 5, 7022, NULL),
(7023, 'wetland', '/ˈwetlænd/', 'noun', '{"zh-TW":["濕地"],"en":["land saturated with water, supporting unique plants and animals"]}', NULL, 'wetland conservation / wetland restoration / coastal wetland', '[{"en":"Wetlands provide natural flood protection and filter water pollutants.","zh-TW":"濕地提供天然防洪保護並過濾水污染物。"},{"en":"Many wetland areas have been drained for agricultural development.","zh-TW":"許多濕地地區已被排乾以用於農業開發。"}]', '{"adjective":"wetland"}', NULL, 3, 7023, NULL),
(7024, 'whereas', '/werˈæz/', 'conjunction', '{"zh-TW":["然而；反之"],"en":["in contrast to the fact that"]}', NULL, 'whereas in fact / whereas previously', '[{"en":"Sales increased in Asia, whereas they declined in Europe.","zh-TW":"銷售在亞洲增長，而在歐洲則下降。"},{"en":"The old system was manual, whereas the new one is automated.","zh-TW":"舊系統是手動的，而新系統是自動化的。"}]', NULL, NULL, 3, 7024, NULL),
(7025, 'whisk', '/''wɪsk/', 'verb', '{"zh-TW":["攪打；快速混合"],"en":["to beat or stir vigorously using a whisk or fork to incorporate air"]}', NULL, 'whisk together / whisk until smooth / whisk the eggs', '[{"en":"Whisk the eggs and sugar together until the mixture turns pale and fluffy.","zh-TW":"將雞蛋和糖一起攪打，直到混合物變得淡白而蓬鬆。"},{"en":"She whisked the cream into stiff peaks for the dessert topping.","zh-TW":"她將奶油攪打成硬性發泡，用作甜點的頂料。"}]', '{"noun":"whisk"}', NULL, 2, 7025, NULL),
(7026, 'whistleblower', '/ˈwɪslˌbloʊər/', 'noun', '{"zh-TW":["吹哨人；舉報人"],"en":["a person who reports illegal or unethical activity within an organization"]}', NULL, 'protect whistleblowers / whistleblower policy / whistleblower complaint', '[{"en":"The whistleblower exposed the company''s fraudulent accounting.","zh-TW":"吹哨人揭露了公司的欺詐性會計行為。"},{"en":"Whistleblower protections are essential for corporate accountability.","zh-TW":"吹哨人保護對公司問責至關重要。"}]', '{"verb":"blow the whistle"}', NULL, 5, 7026, NULL),
(7027, 'whistleblower protection', '/ˈwɪsəlbləʊər prəˈtekʃən/', 'noun', '{"zh-TW":["吹哨人保護"],"en":["legal safeguards for employees who report corporate wrongdoing"]}', NULL, 'provide whistleblower protection / whistleblower protection law / strengthen whistleblower protection', '[{"en":"Strong whistleblower protection laws encourage reporting of financial fraud.","zh-TW":"強有力的吹哨人保護法促進了財務欺詐的舉報。"},{"en":"The employee claimed the company retaliated against him in violation of whistleblower protection.","zh-TW":"員工聲稱公司違反吹哨人保護對他進行了報復。"}]', NULL, NULL, 5, 7027, NULL),
(7028, 'whistleblowing', '/ˈwɪsəlˌbləʊɪŋ/', 'noun', '{"zh-TW":["告發；揭弊"],"en":["the act of exposing illegal or unethical practices within an organization"]}', NULL, 'encourage whistleblowing / whistleblowing policy / protect whistleblowing', '[{"en":"Effective whistleblowing policies protect employees who report misconduct from retaliation.","zh-TW":"有效的揭弊政策保護舉報不當行為的員工免遭報復。"},{"en":"Whistleblowing by an accountant revealed the company''s accounting fraud.","zh-TW":"一位會計師的揭弊行為揭露了公司的會計欺詐。"}]', '{"noun2":"whistleblower","verb":"blow the whistle"}', NULL, 5, 7028, NULL),
(7029, 'white label', '/waɪt ˈleɪbəl/', 'noun', '{"zh-TW":["白標；貼牌"],"en":["a product made by one company but sold under another company brand"]}', NULL, 'white label product / white label service / white label solution', '[{"en":"The retailer sells white label products under its own brand name.","zh-TW":"零售商以自己的品牌名稱出售白標產品。"},{"en":"White label banking services allow fintech startups to launch quickly.","zh-TW":"白標銀行服務允許金融科技新創公司快速推出服務。"}]', '{"adjective":"white-label"}', NULL, 4, 7029, NULL),
(7030, 'white paper', '/waɪt ˈpeɪpər/', 'noun', '{"zh-TW":["白皮書"],"en":["an authoritative report or guide on a specific topic by an organization"]}', NULL, 'publish a white paper / technical white paper', '[{"en":"The company published a white paper on AI in supply chain management.","zh-TW":"公司發布了一份關於人工智慧在供應鏈管理中的白皮書。"},{"en":"A white paper establishes thought leadership and educates potential clients.","zh-TW":"白皮書確立了思想領導地位並教育了潛在客戶。"}]', NULL, NULL, 4, 7030, NULL),
(7031, 'white-collar', '/waɪt ˈkɒlər/', 'adjective', '{"zh-TW":["白領的；辦公室工作的"],"en":["relating to professional, managerial, or administrative work in an office"]}', NULL, 'white-collar worker / white-collar crime / white-collar profession', '[{"en":"The company employs mostly white-collar workers in its headquarters.","zh-TW":"公司總部主要聘用白領工作人員。"},{"en":"White-collar crime such as fraud has increased with digital transactions.","zh-TW":"隨著數位交易的發展，詐欺等白領犯罪有所增加。"}]', '{"opposite":"blue-collar"}', NULL, 4, 7031, NULL),
(7032, 'white-collar crime', '/ˌwaɪt ˈkɒlər kraɪm/', 'noun', '{"zh-TW":["白領犯罪"],"en":["non-violent crimes committed by business professionals for financial gain"]}', NULL, 'investigate white-collar crime / prosecute white-collar crime / white-collar crime case', '[{"en":"White-collar crime such as insider trading and embezzlement causes significant economic harm.","zh-TW":"內幕交易和挪用公款等白領犯罪造成重大經濟損失。"},{"en":"Regulators increased penalties to deter white-collar crime in the financial sector.","zh-TW":"監管機構加重懲罰以阻嚇金融領域的白領犯罪。"}]', NULL, NULL, 5, 7032, NULL),
(7033, 'whiteboard', '/ˈwaɪtbɔːrd/', 'noun', '{"zh-TW":["白板"],"en":["a smooth white board used for writing in meetings"]}', NULL, 'use a whiteboard / digital whiteboard', '[{"en":"The trainer drew diagrams on the whiteboard.","zh-TW":"培訓師在白板上畫了圖表。"},{"en":"Virtual whiteboards allow remote teams to collaborate visually.","zh-TW":"虛擬白板使遠端團隊能夠進行視覺協作。"}]', NULL, NULL, 4, 7033, NULL),
(7034, 'whole', 'hoʊl', 'adjective', '{"zh-TW":["整體的；全部的","完整的"],"en":["complete, not divided","all of something"]}', NULL, 'whole team/whole process', '[{"en":"The whole team contributed to the success.","zh-TW":"整個團隊為成功做出了貢獻。"}]', '{"noun":"whole","adverb":"wholly"}', NULL, 2, 7034, NULL),
(7035, 'wholesale', '/ˈhoʊlseɪl/', 'noun', '{"zh-TW":["批發","批發的"],"en":["the selling of goods in large quantities at low prices","the selling of goods in large quantities","on a large scale"]}', '{"root":{"text":"whole","meaning":"whole (整體)"},"suffix":{"text":"sale","meaning":"sale (銷售)"},"logic":"整批銷售，即「批發」。"}', 'wholesale price / wholesale market; wholesale price / wholesale market / wholesale distributor', '[{"en":"They buy wholesale and sell retail.","zh-TW":"他們批發購入，零售賣出。"},{"en":"The wholesale price is much lower.","zh-TW":"批發價便宜很多。"},{"en":"We buy materials at wholesale prices.","zh-TW":"我們以批發價購買材料。"},{"en":"The wholesale market opens at 5 AM.","zh-TW":"批發市場凌晨5點開門。"}]', '{"noun":"wholesaler","adjective":"wholesale"}', NULL, 3, 7035, NULL),
(7036, 'wholesale price', '/ˈhoʊlseɪl praɪs/', 'noun', '{"zh-TW":["批發價格"],"en":["the price at which goods are sold in large quantities to retailers"]}', NULL, 'negotiate wholesale price / wholesale price index', '[{"en":"Retailers buy at wholesale prices and sell at retail prices.","zh-TW":"零售商以批發價購買並以零售價出售。"},{"en":"A reduction in wholesale prices helped retailers improve margins.","zh-TW":"批發價格的降低幫助零售商提高了利潤率。"}]', NULL, NULL, 5, 7036, NULL),
(7037, 'wholesome', '/''həʊlsəm/', 'adjective', '{"zh-TW":["有益健康的；滋養的"],"en":["conducive to health or well-being; nourishing and natural"]}', NULL, 'wholesome meal / wholesome diet / wholesome ingredients', '[{"en":"She prepared a wholesome meal of grilled fish, brown rice, and steamed vegetables.","zh-TW":"她準備了一頓健康的餐食，包括烤魚、糙米和清蒸蔬菜。"},{"en":"The café attracted health-conscious customers with its wholesome menu.","zh-TW":"這家咖啡館以其健康菜單吸引了注重健康的顧客。"}]', '{"noun":"wholesomeness"}', NULL, 3, 7037, NULL),
(7038, 'wide', 'waɪd', 'adjective', '{"zh-TW":["寬廣的；廣泛的","大量的"],"en":["covering a large area or range","extensive"]}', NULL, 'wide range/wide variety', '[{"en":"We offer a wide range of products.","zh-TW":"我們提供廣泛的產品系列。"}]', '{"noun":"width","adverb":"widely"}', NULL, 1, 7038, NULL),
(7039, 'widen', '/ˈwaɪdn/', 'verb', '{"zh-TW":["加寬；擴大"],"en":["to make or become wider or more extensive"]}', NULL, 'widen the gap / widen the scope / widen access', '[{"en":"The gap between rich and poor continues to widen.","zh-TW":"貧富差距持續擴大。"},{"en":"We plan to widen the scope of our services.","zh-TW":"我們計劃擴大服務範圍。"}]', '{"noun":"width","verb":"widen","adjective":"wide"}', NULL, 2, 7039, NULL),
(7040, 'widespread', '/ˈwaɪdspred/', 'adjective', '{"zh-TW":["普遍的；廣泛的"],"en":["found or distributed over a large area"]}', NULL, 'widespread use / widespread concern / widespread adoption', '[{"en":"There is widespread concern about data privacy.","zh-TW":"人們普遍關注資料隱私問題。"},{"en":"The technology has gained widespread adoption.","zh-TW":"這項技術已被廣泛採用。"}]', '{"adjective":"widespread"}', NULL, 4, 7040, NULL),
(7041, 'wildfire', '/ˈwaɪldfaɪər/', 'noun', '{"zh-TW":["野火；山火"],"en":["an uncontrolled fire spreading rapidly through vegetation"]}', NULL, 'contain a wildfire / wildfire risk', '[{"en":"The wildfire destroyed thousands of acres of forest.","zh-TW":"野火摧毀了數千英畝的森林。"},{"en":"Climate change increases the frequency and intensity of wildfires.","zh-TW":"氣候變遷增加了野火的頻率和強度。"}]', NULL, NULL, 3, 7041, NULL),
(7042, 'willing', '/ˈwɪlɪŋ/', 'adjective', '{"zh-TW":["願意的；樂意的"],"en":["ready or eager to do something"]}', NULL, 'willing to / willing participant / willing and able', '[{"en":"Are you willing to relocate for the job?","zh-TW":"你願意為這份工作搬遷嗎？"},{"en":"We need willing participants for the pilot program.","zh-TW":"我們需要願意參加試驗計畫的人。"}]', '{"noun":"willingness","adjective":"willing, unwilling","adverb":"willingly"}', NULL, 3, 7042, NULL),
(7043, 'wind', '/wɪnd/', 'noun', '{"zh-TW":["風"],"en":["moving air"]}', '{"root":{"text":"wind","meaning":"blow (吹)"},"logic":"空氣的流動。"}', 'strong wind / wind speed / wind power', '[{"en":"The wind blew the leaves off the trees.","zh-TW":"風把樹葉從樹上吹落。"},{"en":"Wind power is a renewable energy source.","zh-TW":"風力是一種再生能源。"}]', '{"adjective":"windy"}', NULL, 1, 7043, NULL),
(7044, 'wind energy', '/wɪnd ˈɛnərdʒi/', 'noun', '{"zh-TW":["風能"],"en":["energy from wind converted into electricity"]}', NULL, 'harness wind energy / wind energy farm', '[{"en":"Wind energy is one of the fastest-growing energy sources.","zh-TW":"風能是增長最快的能源之一。"},{"en":"The offshore wind energy farm supplies power to 100,000 homes.","zh-TW":"離岸風力發電場為10萬戶家庭供電。"}]', NULL, NULL, 4, 7044, NULL),
(7045, 'window dressing', '/ˈwɪndoʊ ˈdresɪŋ/', 'noun', '{"zh-TW":["表面文章；橱窗裝飾"],"en":["the practice of making a company''s finances appear better than they actually are"]}', NULL, 'avoid window dressing / window dressing of accounts', '[{"en":"Some companies engage in window dressing before the annual report deadline.","zh-TW":"某些公司在年報截止日期前進行表面文章。"},{"en":"Window dressing distorts the true picture of a company''s financial health.","zh-TW":"表面文章歪曲了公司財務狀況的真實面貌。"}]', NULL, NULL, 5, 7045, NULL),
(7046, 'window of opportunity', '/ˈwɪndoʊ əv ˌɒpərˈtjuːnɪti/', 'noun', '{"zh-TW":["機會之窗；有利時機"],"en":["a brief period during which an action can be taken successfully"]}', NULL, 'identify a window of opportunity / act within the window of opportunity', '[{"en":"A window of opportunity exists before the competitor launches next month.","zh-TW":"在競爭對手下月推出產品之前存在一個機會之窗。"},{"en":"The company acted quickly to seize the window of opportunity.","zh-TW":"公司迅速行動以抓住機會之窗。"}]', NULL, NULL, 5, 7046, NULL),
(7047, 'window seat', '/ˈwɪndoʊ siːt/', 'noun', '{"zh-TW":["靠窗座位"],"en":["a seat next to the window in a plane"]}', NULL, 'request a window seat / enjoy the view from the window seat', '[{"en":"She chose a window seat to enjoy the view.","zh-TW":"她選擇靠窗座位以欣賞風景。"},{"en":"A window seat is great for sleeping on long flights.","zh-TW":"靠窗座位適合在長途飛行中睡覺。"}]', NULL, NULL, 4, 7047, NULL),
(7048, 'wine list', '/waɪn lɪst/', 'noun', '{"zh-TW":["酒單"],"en":["a list of wines available at a restaurant"]}', NULL, 'browse the wine list / extensive wine list', '[{"en":"The sommelier helped us choose from the wine list.","zh-TW":"侍酒師幫助我們從酒單中選擇。"},{"en":"Their wine list features bottles from around the world.","zh-TW":"他們的酒單有來自世界各地的酒款。"}]', NULL, NULL, 3, 7048, NULL),
(7049, 'wine pairing', '/waɪn ˈpɛərɪŋ/', 'noun', '{"zh-TW":["餐酒搭配"],"en":["the matching of wine to food for a better dining experience"]}', NULL, 'wine pairing suggestion / wine pairing menu', '[{"en":"The sommelier offered wine pairing suggestions with each course.","zh-TW":"侍酒師為每道菜提供了餐酒搭配建議。"},{"en":"Good wine pairing enhances both the food and the wine.","zh-TW":"良好的餐酒搭配同時提升了食物和葡萄酒的風味。"}]', NULL, NULL, 4, 7049, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(7050, 'winning streak', '/''wɪnɪŋ striːk/', 'noun', '{"zh-TW":["連勝；連贏"],"en":["a series of consecutive wins by a person or team"]}', NULL, 'extend a winning streak / end a winning streak / impressive winning streak', '[{"en":"The team''s impressive winning streak of twelve games came to an end last night.","zh-TW":"球隊令人印象深刻的十二場連勝昨晚宣告結束。"},{"en":"She was on a winning streak, winning every tournament she entered.","zh-TW":"她正處於連勝狀態，贏得了她參加的每一個比賽。"}]', NULL, NULL, 5, 7050, NULL),
(7051, 'wire transfer', '/ˈwaɪər ˈtrænsfɜːr/', 'noun', '{"zh-TW":["電匯；電子匯款"],"en":["an electronic transfer of funds between banks"]}', NULL, 'send a wire transfer / international wire transfer', '[{"en":"The company sent a wire transfer to pay the foreign supplier.","zh-TW":"公司發送了電匯支付給外國供應商。"},{"en":"Wire transfers usually arrive within one to two business days.","zh-TW":"電匯通常在一到兩個工作日內到達。"}]', NULL, NULL, 5, 7051, NULL),
(7052, 'wireless', '/ˈwaɪərlɪs/', 'adjective', '{"zh-TW":["無線的"],"en":["using radio signals instead of wires"]}', NULL, 'wireless network / wireless charging', '[{"en":"The hotel has free wireless internet.","zh-TW":"飯店有免費無線網路。"},{"en":"This phone supports wireless charging.","zh-TW":"這支手機支援無線充電。"}]', NULL, NULL, 3, 7052, NULL),
(7053, 'withdraw', '/wɪðˈdrɔː/', 'verb', '{"zh-TW":["撤回；提款","退出"],"en":["to take back; to remove money from a bank","to leave or pull out"]}', NULL, 'withdraw funds / withdraw from / withdraw support', '[{"en":"The investor withdrew funding from the project.","zh-TW":"投資者從專案中撤回了資金。"},{"en":"She withdrew her application for the position.","zh-TW":"她撤回了該職位的申請。"}]', '{"noun":"withdrawal","verb":"withdraw"}', NULL, 3, 7053, NULL),
(7054, 'withdrawal', 'wɪðˈdrɔːəl', 'noun', '{"zh-TW":["撤回；提款","退出"],"en":["the act of taking back","removing money from an account"]}', NULL, 'cash withdrawal/contract withdrawal', '[{"en":"Please process the withdrawal request.","zh-TW":"請處理提款申請。"}]', '{"verb":"withdraw","adjective":"withdrawn"}', NULL, 4, 7054, 487),
(7055, 'withhold', '/wɪðˈhoʊld/', 'verb', '{"zh-TW":["扣留；隱瞞"],"en":["to hold back; to refrain from giving"]}', NULL, 'withhold information / withhold payment / withhold tax', '[{"en":"The company withheld the bonus due to poor performance.","zh-TW":"公司因業績不佳而扣留了獎金。"},{"en":"Employers must withhold income tax from wages.","zh-TW":"雇主必須從薪資中預扣所得稅。"}]', '{"noun":"withholding","verb":"withhold"}', NULL, 3, 7055, NULL),
(7056, 'withholding tax', '/wɪðˈhoʊldɪŋ tæks/', 'noun', '{"zh-TW":["預扣稅；扣繳稅款"],"en":["a tax deducted at source from payments such as dividends, interest, or wages"]}', NULL, 'apply withholding tax / withholding tax rate', '[{"en":"Dividends paid to non-residents are subject to withholding tax.","zh-TW":"支付給非居民的股息須繳納預扣稅。"},{"en":"The withholding tax rate on interest payments is 15%.","zh-TW":"利息付款的預扣稅率為15%。"}]', NULL, NULL, 5, 7056, NULL),
(7057, 'withstand', '/wɪðˈstænd/', 'verb', '{"zh-TW":["承受；抵抗"],"en":["to remain undamaged by; to resist"]}', NULL, 'withstand pressure / withstand competition / withstand scrutiny', '[{"en":"The company withstood intense market competition.","zh-TW":"公司經受住了激烈的市場競爭。"},{"en":"The product is designed to withstand extreme conditions.","zh-TW":"該產品設計為可承受極端條件。"}]', '{"verb":"withstand"}', NULL, 3, 7057, NULL),
(7058, 'witness', '/ˈwɪtnəs/', 'noun, verb', '{"zh-TW":["目擊者；證人","目睹；見證"],"en":["a person who sees an event","to see something happen"]}', NULL, 'witness growth / bear witness / expert witness', '[{"en":"The industry witnessed rapid growth last year.","zh-TW":"該行業去年見證了快速增長。"},{"en":"We are witnessing a major shift in consumer behavior.","zh-TW":"我們正在見證消費者行為的重大轉變。"}]', '{"noun":"witness","verb":"witness"}', NULL, 3, 7058, NULL),
(7059, 'work', 'wɜːrk', 'verb', '{"zh-TW":["工作；運作","有效"],"en":["to do a job","to function correctly"]}', NULL, 'work on/together/remotely', '[{"en":"The team works remotely on Fridays.","zh-TW":"團隊週五遠程工作。"}]', '{"noun":"work, worker","adjective":"working","adverb":"workably"}', NULL, 1, 7059, NULL),
(7060, 'work breakdown structure', '/wɜːrk ˈbreɪkdaʊn ˈstrʌktʃər/', 'noun', '{"zh-TW":["工作分解結構"],"en":["a hierarchical decomposition of the total project work into components"]}', NULL, 'create a work breakdown structure / define the work breakdown structure', '[{"en":"The work breakdown structure was used to assign tasks and estimate costs.","zh-TW":"工作分解結構用於分配任務和估算成本。"},{"en":"A detailed work breakdown structure improves project planning accuracy.","zh-TW":"詳細的工作分解結構提高了項目計劃的準確性。"}]', '{"abbreviation":"WBS"}', NULL, 5, 7060, NULL),
(7061, 'work ethic', '/wɜːrk ˈeθɪk/', 'noun', '{"zh-TW":["工作倫理；敬業精神"],"en":["a set of values based on hard work and diligence in one''s job"]}', NULL, 'strong work ethic / demonstrate work ethic / professional work ethic', '[{"en":"Her strong work ethic was recognized at the performance review.","zh-TW":"她強烈的敬業精神在績效評估中得到了認可。"},{"en":"A strong work ethic is one of the most sought-after qualities in candidates.","zh-TW":"強烈的敬業精神是候選人最受歡迎的品質之一。"}]', NULL, NULL, 4, 7061, NULL),
(7062, 'work-life balance', '/wɜːrk laɪf ˈbæləns/', 'noun', '{"zh-TW":["工作與生活平衡"],"en":["achieving a healthy balance between professional and personal life"]}', NULL, 'improve work-life balance / achieve work-life balance / work-life balance policy', '[{"en":"Flexible hours help employees maintain a healthy work-life balance.","zh-TW":"彈性工時幫助員工保持健康的工作與生活平衡。"},{"en":"Poor work-life balance leads to burnout and high turnover.","zh-TW":"工作與生活失衡導致職業倦怠和高流動率。"}]', NULL, NULL, 5, 7062, NULL),
(7063, 'work-life integration', '/''wɜːrk laɪf ˌɪntɪˌɡreɪʃən/', 'noun', '{"zh-TW":["工作與生活整合"],"en":["an approach to balancing professional and personal life by blending the two more fluidly"]}', NULL, 'achieve work-life integration / work-life integration strategy / benefit of work-life integration', '[{"en":"She sought work-life integration rather than strict separation between her career and family time.","zh-TW":"她尋求工作與生活整合，而不是職業與家庭時間之間的嚴格分隔。"},{"en":"Technology has made work-life integration both easier and more challenging simultaneously.","zh-TW":"技術使工作與生活整合同時變得更容易也更具挑戰性。"}]', '{"noun":"integration"}', NULL, 5, 7063, NULL),
(7064, 'workaround', '/''wɜːrkəˌraʊnd/', 'noun', '{"zh-TW":["變通方法；臨時解決方案"],"en":["a method for circumventing a problem or limitation when a direct solution is unavailable"]}', NULL, 'find a workaround / use a workaround / develop a workaround', '[{"en":"The IT team found a temporary workaround while the system was being repaired.","zh-TW":"IT團隊在系統修復期間找到了臨時變通方法。"},{"en":"A quick workaround was implemented to keep operations running until the update was released.","zh-TW":"在更新發布之前，實施了一個快速的臨時解決方案以保持業務運行。"}]', '{"verb":"work around"}', NULL, 4, 7064, NULL),
(7065, 'workflow', '/ˈwɜːrkfloʊ/', 'noun', '{"zh-TW":["工作流程"],"en":["the sequence of steps in a business process"]}', NULL, 'optimize workflow / workflow management / automate workflow', '[{"en":"Automating the workflow saved hours of manual work each week.","zh-TW":"自動化工作流程每週節省了數小時的手動工作。"},{"en":"The new software streamlined our approval workflow.","zh-TW":"新軟體簡化了我們的審批工作流程。"}]', '{"verb":"workflow"}', NULL, 3, 7065, 949),
(7066, 'workforce', '/ˈwɜːrkfɔːrs/', 'noun', '{"zh-TW":["勞動力；員工總數"],"en":["the people engaged in work"]}', NULL, 'skilled workforce / workforce development / reduce the workforce', '[{"en":"The company has a workforce of 5,000 employees.","zh-TW":"公司擁有5000名員工。"},{"en":"Investing in workforce development is essential.","zh-TW":"投資勞動力發展至關重要。"}]', '{"noun":"workforce, work, worker"}', NULL, 3, 7066, NULL),
(7067, 'workforce development', '/ˈwɜːrkfɔːrs dɪˈveləpmənt/', 'noun', '{"zh-TW":["人才培育；勞動力發展"],"en":["the process of improving workers'' skills and creating employment opportunities"]}', NULL, 'invest in workforce development / workforce development program / national workforce development', '[{"en":"Workforce development programs help workers adapt to technological change.","zh-TW":"人才培育計畫幫助工人適應技術變革。"},{"en":"Effective workforce development requires collaboration between government and industry.","zh-TW":"有效的勞動力發展需要政府和工業界的合作。"}]', NULL, NULL, 5, 7067, NULL),
(7068, 'workforce planning', '/ˈwɜːrkfɔːrs ˈplænɪŋ/', 'noun', '{"zh-TW":["人力規劃"],"en":["aligning a company''s staffing needs with its strategic goals"]}', NULL, 'strategic workforce planning / workforce planning model', '[{"en":"Workforce planning identified a skills gap in the engineering team.","zh-TW":"人力規劃發現了工程團隊的技能缺口。"},{"en":"Effective workforce planning reduces unexpected staffing shortages.","zh-TW":"有效的人力規劃減少了意外的人員短缺。"}]', NULL, NULL, 5, 7068, NULL),
(7069, 'working capital', '/ˈwɜːrkɪŋ ˈkæpɪtl/', 'noun', '{"zh-TW":["營運資金；流動資金"],"en":["current assets minus current liabilities; funds available for day-to-day operations"]}', NULL, 'working capital management / positive working capital', '[{"en":"The company needs more working capital to fund operations.","zh-TW":"公司需要更多營運資金來支持運營。"},{"en":"Efficient inventory control improves working capital.","zh-TW":"有效的庫存控制改善了營運資金。"}]', NULL, NULL, 5, 7069, NULL),
(7070, 'working capital cycle', '/ˈwɜːrkɪŋ ˈkæpɪtəl ˈsaɪkəl/', 'noun', '{"zh-TW":["營運資金週期"],"en":["the time taken to convert working capital into cash through operations"]}', NULL, 'shorten the working capital cycle / manage working capital cycle / optimize the cycle', '[{"en":"Efficient inventory management shortens the working capital cycle.","zh-TW":"有效的庫存管理縮短了營運資金週期。"},{"en":"A longer working capital cycle ties up cash and reduces liquidity.","zh-TW":"更長的營運資金週期佔用現金並降低流動性。"}]', NULL, NULL, 5, 7070, NULL),
(7071, 'working capital management', '/ˈwɜːrkɪŋ ˈkæpɪtl ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["營運資金管理"],"en":["managing short-term assets and liabilities to ensure operational efficiency"]}', NULL, 'improve working capital management / working capital management strategy', '[{"en":"Effective working capital management prevents cash flow crises.","zh-TW":"有效的營運資金管理可防止現金流危機。"},{"en":"Inventory optimization is a core part of working capital management.","zh-TW":"庫存優化是營運資金管理的核心部分。"}]', NULL, NULL, 5, 7071, NULL),
(7072, 'working capital ratio', '/ˈwɜːrkɪŋ ˈkæpɪtəl ˈreɪʃioʊ/', 'noun', '{"zh-TW":["營運資金比率"],"en":["a ratio comparing current assets to current liabilities to assess short-term health"]}', NULL, 'calculate working capital ratio / improve working capital ratio', '[{"en":"A working capital ratio above 1 indicates the company can cover short-term debt.","zh-TW":"高於1的營運資金比率表明公司可以償還短期債務。"},{"en":"The CFO monitored the working capital ratio to manage liquidity risk.","zh-TW":"財務長監控營運資金比率以管理流動性風險。"}]', NULL, NULL, 5, 7072, NULL),
(7073, 'working group', '/ˈwɜːrkɪŋ ɡruːp/', 'noun', '{"zh-TW":["工作組"],"en":["a group of people working together to achieve a specific objective"]}', NULL, 'working group meeting / join a working group / working group recommendations', '[{"en":"The working group developed new data privacy guidelines.","zh-TW":"工作組制定了新的資料隱私指南。"},{"en":"Several working groups were formed to study the policy options.","zh-TW":"成立了幾個工作組研究政策選項。"}]', NULL, NULL, 5, 7073, NULL),
(7074, 'working hypothesis', '/ˈwɜːrkɪŋ haɪˈpɒθɪsɪs/', 'noun', '{"zh-TW":["工作假設"],"en":["a provisional hypothesis used as a basis for research"]}', NULL, 'develop a working hypothesis / test a working hypothesis / refine the working hypothesis', '[{"en":"The team began with a working hypothesis that was later confirmed by evidence.","zh-TW":"團隊從一個工作假設開始，後來被證據所證實。"},{"en":"A working hypothesis guides data collection and analysis in exploratory research.","zh-TW":"工作假設指導探索性研究中的數據收集和分析。"}]', NULL, NULL, 5, 7074, NULL),
(7075, 'working interest', '/ˈwɜːrkɪŋ ˈɪntrɪst/', 'noun', '{"zh-TW":["作業利益；工作利益"],"en":["an ownership interest in an oil or gas property entitling the holder to a share of production"]}', NULL, 'hold a working interest / working interest percentage', '[{"en":"The company sold its 30% working interest in the oil field.","zh-TW":"公司出售了其在油田中30%的作業利益。"},{"en":"A working interest holder bears both the costs and benefits of production.","zh-TW":"作業利益持有人承擔生產的成本和收益。"}]', NULL, NULL, 5, 7075, NULL),
(7076, 'working remotely', '/ˈwɜːrkɪŋ rɪˈmoʊtli/', 'verb', '{"zh-TW":["遠程辦公；在家工作"],"en":["carrying out work duties from a location other than the office"]}', NULL, 'work remotely / working remotely options', '[{"en":"The team has been working remotely since the pandemic.","zh-TW":"自疫情以來，團隊一直在遠程辦公。"},{"en":"Working remotely requires strong self-discipline and clear communication.","zh-TW":"遠程辦公需要強大的自律和清晰的溝通。"}]', NULL, NULL, 5, 7076, NULL),
(7077, 'workload', '/ˈwɜːrkloʊd/', 'noun', '{"zh-TW":["工作量；工作負擔"],"en":["the amount of work assigned to or done by an employee or team"]}', NULL, 'manage workload / heavy workload / workload balance / workload distribution', '[{"en":"The new hire helped reduce the team''s heavy workload.","zh-TW":"新員工幫助減輕了團隊沉重的工作量。"},{"en":"Workload distribution must be fair to prevent employee burnout.","zh-TW":"工作量分配必須公平以防止員工倦怠。"}]', '{"adjective":"workload-intensive"}', NULL, 3, 7077, 488),
(7078, 'workload management', '/''wɜːrkˌləʊd ˌmænɪdʒmənt/', 'noun', '{"zh-TW":["工作量管理；任務管理"],"en":["the process of distributing and controlling tasks among employees to ensure efficiency and prevent burnout"]}', NULL, 'improve workload management / workload management tools / effective workload management', '[{"en":"Effective workload management prevents burnout and maintains team productivity.","zh-TW":"有效的工作量管理可以防止職業倦怠並維持團隊生產力。"},{"en":"She used project management software to improve workload management across her team.","zh-TW":"她使用項目管理軟體改善了整個團隊的工作量管理。"}]', NULL, NULL, 5, 7078, NULL),
(7079, 'workout routine', '/''wɜːrkˌaʊt ruːˌtiːn/', 'noun', '{"zh-TW":["鍛煉例程；運動計劃"],"en":["a regular program of physical exercise followed consistently"]}', NULL, 'follow a workout routine / establish a workout routine / daily workout routine', '[{"en":"Sticking to a workout routine helps build long-term fitness habits.","zh-TW":"堅持鍛煉例程有助於建立長期的健身習慣。"},{"en":"Her workout routine consists of strength training three days a week and running on alternate days.","zh-TW":"她的鍛煉例程包括每週三天的力量訓練和隔天跑步。"}]', '{"noun":"routine"}', NULL, 5, 7079, NULL),
(7080, 'workplace', 'ˈwɜːrkpleɪs', 'noun', '{"zh-TW":["工作場所；職場","辦公場所"],"en":["where people work","an office or factory"]}', NULL, 'safe workplace/workplace culture', '[{"en":"Maintaining a safe workplace is essential.","zh-TW":"維持安全的工作場所至關重要。"}]', '{"adjective":"workplace-based"}', NULL, 3, 7080, 243),
(7081, 'workplace injury', '/ˈwɜːrkpleɪs ˈɪndʒəri/', 'noun', '{"zh-TW":["工作場所傷害；職業傷害"],"en":["an injury sustained while performing work duties"]}', NULL, 'prevent workplace injuries / report a workplace injury', '[{"en":"All workplace injuries must be reported immediately.","zh-TW":"所有工作場所傷害必須立即報告。"},{"en":"The company implemented new procedures to reduce workplace injuries.","zh-TW":"公司實施了新程序以減少工作場所傷害。"}]', NULL, NULL, 5, 7081, NULL),
(7082, 'workshop', '/ˈwɜːrkʃɑːp/', 'noun', '{"zh-TW":["研討會；工作坊"],"en":["a meeting for discussion or practical work"]}', NULL, 'training workshop / conduct a workshop / hands-on workshop', '[{"en":"The HR department organized a leadership workshop.","zh-TW":"人資部門組織了一場領導力工作坊。"},{"en":"The workshop covered project management skills.","zh-TW":"工作坊涵蓋了專案管理技能。"}]', '{"noun":"workshop"}', NULL, 3, 7082, NULL),
(7083, 'world', 'wɜːrld', 'noun', '{"zh-TW":["世界；全球","領域"],"en":["the Earth and its people","a particular field"]}', NULL, 'global world/world market', '[{"en":"We operate in a competitive world market.","zh-TW":"我們在競爭激烈的全球市場中運營。"}]', '{"adjective":"worldwide, worldly","adverb":"worldwide"}', NULL, 2, 7083, NULL),
(7084, 'worldbuilding', '/ˈwɜːldbɪldɪŋ/', 'noun', '{"zh-TW":["世界觀構建；世界設定"],"en":["the process of creating an imaginary world for a story or game"]}', NULL, 'extensive worldbuilding / worldbuilding details / rich worldbuilding', '[{"en":"The fantasy series is admired for its detailed and immersive worldbuilding.","zh-TW":"這部奇幻系列因其詳細而沉浸式的世界觀構建而備受讚譽。"},{"en":"Good worldbuilding makes a fictional universe feel real and consistent.","zh-TW":"良好的世界觀構建使虛構的宇宙感覺真實且一致。"}]', NULL, NULL, 5, 7084, NULL),
(7085, 'worldwide', 'ˈwɜːrldwaɪd', 'adjective', '{"zh-TW":["全球的；世界性的","世界範圍的"],"en":["extending throughout the world","international"]}', NULL, 'worldwide distribution/worldwide recognition', '[{"en":"Our products have worldwide distribution.","zh-TW":"我們的產品在全球分銷。"}]', '{"adverb":"worldwide"}', NULL, 3, 7085, 489),
(7086, 'worth', '/wɜːrθ/', 'noun, adjective', '{"zh-TW":["價值","值得的"],"en":["the value of something","deserving of"]}', NULL, 'worth mentioning / net worth / worth the effort', '[{"en":"The investment is definitely worth the risk.","zh-TW":"這項投資絕對值得冒險。"},{"en":"The company''s net worth exceeded $1 billion.","zh-TW":"公司淨值超過了10億美元。"}]', '{"noun":"worth","adjective":"worth, worthy, worthwhile"}', NULL, 2, 7086, NULL),
(7087, 'worthwhile', '/ˌwɜːrθˈwaɪl/', 'adjective', '{"zh-TW":["值得的；有價值的"],"en":["worth the time, money, or effort spent"]}', NULL, 'worthwhile investment / worthwhile endeavor / make it worthwhile', '[{"en":"The training program proved to be a worthwhile investment.","zh-TW":"培訓計畫被證明是一項值得的投資。"},{"en":"It''s worthwhile to compare prices before purchasing.","zh-TW":"購買前比較價格是值得的。"}]', '{"adjective":"worthwhile, worthy","noun":"worth"}', NULL, 4, 7087, NULL),
(7088, 'worthy', '/ˈwɜːrði/', 'adjective', '{"zh-TW":["值得的；有價值的"],"en":["deserving respect or attention"]}', NULL, 'worthy of / worthy cause / noteworthy', '[{"en":"The proposal is worthy of consideration.","zh-TW":"這個提案值得考慮。"},{"en":"They donated to a worthy cause.","zh-TW":"他們為一項有價值的事業捐款。"}]', '{"noun":"worth, worthiness","adjective":"worthy, unworthy, noteworthy"}', NULL, 2, 7088, NULL),
(7089, 'wrap', '/ræp/', 'noun', '{"zh-TW":["捲餅；包裹"],"en":["food wrapped in a flatbread or tortilla"]}', NULL, 'chicken wrap / veggie wrap', '[{"en":"She ordered a chicken wrap with a side salad.","zh-TW":"她點了一個雞肉捲餅配沙拉。"},{"en":"Wraps are a popular choice for a quick lunch.","zh-TW":"捲餅是快速午餐的熱門選擇。"}]', NULL, NULL, 1, 7089, NULL),
(7090, 'writ of execution', '/rɪt əv ˌeksɪˈkjuːʃən/', 'noun', '{"zh-TW":["執行令"],"en":["a court order directing that a judgment be enforced"]}', NULL, 'issue a writ of execution / obtain a writ of execution / enforce via writ of execution', '[{"en":"The creditor obtained a writ of execution to seize the debtor''s assets.","zh-TW":"債權人取得了執行令以扣押債務人的資產。"},{"en":"A writ of execution is the primary tool for enforcing money judgments.","zh-TW":"執行令是執行金錢判決的主要工具。"}]', NULL, NULL, 5, 7090, NULL),
(7091, 'write', 'raɪt', 'verb', '{"zh-TW":["書寫；撰寫","寫作"],"en":["to form letters or words","to compose"]}', NULL, 'write a report/email', '[{"en":"Please write a summary of the meeting.","zh-TW":"請撰寫會議摘要。"}]', '{"noun":"writing, writer","adjective":"written","adverb":"writely"}', NULL, 2, 7091, NULL),
(7092, 'write down', '/raɪt daʊn/', 'verb', '{"zh-TW":["減記；減值"],"en":["to reduce the recorded value of an asset"]}', NULL, 'write down an asset / write down inventory', '[{"en":"The company wrote down its goodwill by 30 million dollars.","zh-TW":"公司將商譽減記了3000萬元。"},{"en":"Inventory was written down after the market price fell below cost.","zh-TW":"市場價格跌破成本後，庫存被減記了。"}]', '{"noun":"write-down","adjective":"written down"}', NULL, 4, 7092, NULL),
(7093, 'write-down', '/ˈraɪt daʊn/', 'noun', '{"zh-TW":["資產減記"],"en":["a partial reduction in the book value of an asset that has decreased in value"]}', NULL, 'record a write-down / write-down of inventory', '[{"en":"A write-down of inventory was required after damaged goods were discovered.","zh-TW":"發現受損貨物後需要對庫存進行資產減記。"},{"en":"The write-down reduced the asset''s book value by 40%.","zh-TW":"資產減記將資產的帳面價值降低了40%。"}]', '{"verb":"write down"}', NULL, 4, 7093, NULL),
(7094, 'write-off', '/ˈraɪt ɒf/', 'noun', '{"zh-TW":["核銷；沖銷"],"en":["the removal of an uncollectable asset from the books"]}', NULL, 'write off a debt / tax write-off / bad debt write-off', '[{"en":"The company wrote off $5 million in uncollectable receivables.","zh-TW":"公司沖銷了500萬美元的無法收回應收帳款。"},{"en":"A write-off reduced taxable income for the year.","zh-TW":"核銷減少了當年的應稅收入。"}]', '{"verb":"write off"}', NULL, 3, 7094, NULL),
(7095, 'write-up', '/ˈraɪtʌp/', 'noun', '{"zh-TW":["書面報告；評論"],"en":["a written account or review of something"]}', NULL, 'prepare a write-up / formal write-up', '[{"en":"The journalist prepared a write-up of the product launch.","zh-TW":"記者準備了產品發布的書面報告。"},{"en":"Please submit a write-up of your project findings.","zh-TW":"請提交您的項目發現的書面報告。"}]', '{"verb":"write up"}', NULL, 3, 7095, NULL),
(7096, 'written', 'ˈrɪtən', 'adjective', '{"zh-TW":["書面的；成文的","文字的"],"en":["expressed in writing","documented"]}', NULL, 'written agreement/written confirmation', '[{"en":"Please provide written confirmation.","zh-TW":"請提供書面確認。"}]', '{"verb":"write","adverb":"in writing"}', NULL, 3, 7096, NULL),
(7097, 'written communication', '/''rɪtən kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["書面溝通；文字溝通"],"en":["the transmission of information, ideas, or messages in written form"]}', NULL, 'effective written communication / written communication skills / improve written communication', '[{"en":"Clear written communication is essential in business, especially in emails and reports.","zh-TW":"清晰的書面溝通在商業中至關重要，特別是在電子郵件和報告中。"},{"en":"She improved her written communication skills by taking a business writing course.","zh-TW":"她通過參加商務寫作課程提高了書面溝通技能。"}]', NULL, NULL, 5, 7097, NULL),
(7098, 'written consent', '/ˈrɪtən kənˈsent/', 'noun', '{"zh-TW":["書面同意"],"en":["formal approval given in writing, required for many legal or contractual actions"]}', NULL, 'obtain written consent / provide written consent', '[{"en":"Written consent from the landlord is needed before subletting.","zh-TW":"轉租前需要獲得房東的書面同意。"},{"en":"The data collection requires written consent from each participant.","zh-TW":"資料收集需要每位參與者的書面同意。"}]', NULL, NULL, 5, 7098, NULL),
(7099, 'wrong', 'rɒŋ', 'adjective', '{"zh-TW":["錯誤的；不對的","不適當的"],"en":["not correct","morally bad"]}', NULL, 'wrong decision/go wrong', '[{"en":"We made the wrong decision initially.","zh-TW":"我們最初做出了錯誤的決定。"}]', '{"adverb":"wrongly"}', NULL, 2, 7099, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(7100, 'X-ray', '/ˈɛks reɪ/', 'noun', '{"zh-TW":["X光；X射線"],"en":["a type of electromagnetic radiation used for imaging"]}', NULL, 'take an X-ray / chest X-ray', '[{"en":"The doctor ordered a chest X-ray to check for pneumonia.","zh-TW":"醫生要求胸部X光以檢查肺炎。"},{"en":"The X-ray showed no broken bones.","zh-TW":"X光顯示沒有骨折。"}]', '{"verb":"X-ray","adjective":"X-rayed"}', NULL, 2, 7100, NULL),
(7101, 'xenophobia', '/ˌzenəˈfəʊbiə/', 'noun', '{"zh-TW":["排外心理；恐外症"],"en":["extreme dislike or fear of people from other countries"]}', NULL, 'overcome xenophobia / rise of xenophobia / combat xenophobia', '[{"en":"Xenophobia often increases during economic downturns and social uncertainty.","zh-TW":"排外心理通常在經濟衰退和社會不確定性增加時加劇。"},{"en":"Anti-discrimination laws are designed to counter xenophobia in workplaces.","zh-TW":"反歧視法旨在打擊工作場所中的排外心理。"}]', '{"adjective":"xenophobic","noun":"xenophobe"}', NULL, 4, 7101, NULL),
(7102, 'yacht', '/''jɒt/', 'noun', '{"zh-TW":["遊艇"],"en":["a medium-sized sailing boat equipped for cruising or racing"]}', NULL, 'charter a yacht / sail a yacht / luxury yacht', '[{"en":"They chartered a yacht to explore the Greek islands.","zh-TW":"他們租了一艘遊艇探索希臘島嶼。"},{"en":"The yacht club hosts an annual regatta every summer.","zh-TW":"遊艇俱樂部每年夏天舉辦一次帆船賽。"}]', NULL, NULL, 2, 7102, NULL),
(7103, 'year', 'jɪr', 'noun', '{"zh-TW":["年；年份","一整年"],"en":["a period of 12 months","a specific calendar year"]}', NULL, 'fiscal year/last year', '[{"en":"The annual report covers the last fiscal year.","zh-TW":"年度報告涵蓋了最後一個財政年度。"}]', '{"adjective":"yearly, annual","adverb":"yearly, annually"}', NULL, 1, 7103, NULL),
(7104, 'year-end audit', '/jɪər end ˈɔːdɪt/', 'noun', '{"zh-TW":["年終審計"],"en":["a comprehensive review of a company''s financial records at the end of a fiscal year"]}', NULL, 'conduct a year-end audit / year-end audit findings', '[{"en":"The external auditors completed the year-end audit within four weeks.","zh-TW":"外部審計師在四週內完成了年終審計。"},{"en":"A clean year-end audit result builds confidence with investors.","zh-TW":"清潔的年終審計結果建立了投資者的信心。"}]', NULL, NULL, 5, 7104, NULL),
(7105, 'year-end closing', '/jɪər end ˈkloʊzɪŋ/', 'noun', '{"zh-TW":["年終結帳；年末結清"],"en":["the accounting process of finalizing records at the end of a fiscal year"]}', NULL, 'complete year-end closing / year-end closing procedures', '[{"en":"Year-end closing requires reconciling all accounts and reversing accruals.","zh-TW":"年終結帳需要對帳所有帳目並沖回應計項目。"},{"en":"The finance team starts year-end closing preparations in November.","zh-TW":"財務團隊在11月開始年終結帳準備工作。"}]', NULL, NULL, 5, 7105, NULL),
(7106, 'year-end review', '/jɪər ɛnd rɪˈvjuː/', 'noun', '{"zh-TW":["年度終結審查；年終檢討"],"en":["a review conducted at the end of the year"]}', NULL, 'conduct a year-end review / year-end review process', '[{"en":"All employees participate in the year-end review with their managers.","zh-TW":"所有員工與其管理者進行年終檢討。"},{"en":"The year-end review assesses performance against annual goals.","zh-TW":"年終檢討評估績效與年度目標的差距。"}]', NULL, NULL, 5, 7106, NULL),
(7107, 'year-over-year', '/ˌjɪər ˈoʊvər jɪər/', 'adjective', '{"zh-TW":["同比的；年比年的"],"en":["comparing a statistic for one period to the same period in the prior year"]}', NULL, 'year-over-year growth / year-over-year comparison', '[{"en":"The company reported a 20% year-over-year increase in revenue.","zh-TW":"公司報告了20%的同比收入增長。"},{"en":"Year-over-year performance metrics help remove seasonal distortions.","zh-TW":"同比績效指標有助於消除季節性扭曲。"}]', '{"abbreviation":"YoY"}', NULL, 5, 7107, NULL),
(7108, 'yeast', '/''jiːst/', 'noun', '{"zh-TW":["酵母；酵母菌"],"en":["a microscopic fungus used in baking and brewing to cause fermentation"]}', NULL, 'active yeast / dry yeast / yeast infection', '[{"en":"Active yeast is essential for bread dough to rise properly.","zh-TW":"活性酵母是麵包麵團正確膨發的必要條件。"},{"en":"She added a teaspoon of dry yeast to the warm water and let it activate.","zh-TW":"她將一茶匙乾酵母加入溫水中，讓其活化。"}]', '{"verb":"ferment"}', NULL, 2, 7108, NULL),
(7109, 'yield', '/jiːld/', 'verb, noun', '{"zh-TW":["【主要意義-動詞/名詞】讓步；屈服","【次要意義-名詞】產量；收益率","【次要意義-動詞】產出；獲得（利潤/成果）","【次要意義-動詞（交通）】讓行；讓路"],"en":["[primary] to give way; to surrender","[secondary - noun] the amount of something produced; financial return","[secondary - verb] to produce a result, crop, or profit","[secondary - verb] to give way to traffic"]}', NULL, 'crop yield / bond yield / yield to pressure / yield results', '[{"en":"The investment yielded a 12 percent annual return.","zh-TW":"這筆投資每年產生12%的回報。"},{"en":"The new farmland is expected to yield three harvests per year.","zh-TW":"新農地預計每年可收穫三次。"},{"en":"Government bonds currently yield around 4 percent.","zh-TW":"政府債券目前的收益率約為4%。"}]', '{"adjective":"high-yielding"}', 'yield 作名詞意為「產量/收益率」（bond yield = 債券殖利率），動詞意為「產出/獲得」，是 TOEIC 財務和農業文章的高頻詞彙，考生常誤以為只有「讓步」的意思。', 2, 7109, NULL),
(7110, 'yield curve', '/jiːld kɜːrv/', 'noun', '{"zh-TW":["殖利率曲線；收益率曲線"],"en":["a chart showing interest rates on bonds across different maturity dates"]}', NULL, 'inverted yield curve / yield curve steepening', '[{"en":"An inverted yield curve is often seen as a recession signal.","zh-TW":"殖利率曲線倒掛通常被視為衰退信號。"},{"en":"The yield curve steepened as long-term rates rose faster than short-term.","zh-TW":"隨著長期利率比短期利率上升得更快，殖利率曲線趨陡了。"}]', NULL, NULL, 4, 7110, NULL),
(7111, 'yield management', '/jiːld ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["收益管理"],"en":["a pricing strategy adjusting prices to maximize revenue from fixed capacity"]}', NULL, 'apply yield management / yield management system / airline yield management', '[{"en":"Airlines use yield management to optimize prices across booking windows.","zh-TW":"航空公司使用收益管理來優化各預訂窗口的定價。"},{"en":"Yield management balances occupancy rates and per-unit revenue in hotels.","zh-TW":"收益管理在酒店業平衡入住率和每單位收入。"}]', NULL, NULL, 5, 7111, NULL),
(7112, 'yield pickup', '/jiːld ˈpɪkʌp/', 'noun', '{"zh-TW":["殖利率提升；額外收益"],"en":["the incremental yield gained by switching from one investment to another"]}', NULL, 'achieve yield pickup / yield pickup strategy / seek yield pickup', '[{"en":"Investors shifted to corporate bonds for yield pickup over government securities.","zh-TW":"投資者轉向企業債券以獲得相對政府證券的殖利率提升。"},{"en":"The yield pickup from emerging market bonds comes with additional risk.","zh-TW":"新興市場債券的殖利率提升伴隨著額外的風險。"}]', NULL, NULL, 4, 7112, NULL),
(7113, 'yield spread', '/jiːld spred/', 'noun', '{"zh-TW":["殖利率利差"],"en":["the difference in yields between two different debt instruments"]}', NULL, 'credit yield spread / yield spread widening / yield spread compression', '[{"en":"A widening yield spread reflects increased credit risk.","zh-TW":"殖利率利差擴大反映了信用風險上升。"},{"en":"Investors monitor yield spreads as indicators of market stress.","zh-TW":"投資者監測殖利率利差作為市場壓力的指標。"}]', NULL, NULL, 4, 7113, NULL),
(7114, 'yield to maturity', '/jiːld tuː məˈtjʊərɪti/', 'noun', '{"zh-TW":["到期殖利率"],"en":["the total return expected on a bond if held until it matures"]}', NULL, 'calculate yield to maturity / yield to maturity calculation', '[{"en":"The bond''s yield to maturity of 5% exceeds the current coupon rate.","zh-TW":"債券的5%到期殖利率超過了當前票息率。"},{"en":"Investors compare yield to maturity when choosing between bonds.","zh-TW":"投資者在選擇債券時比較到期殖利率。"}]', '{"abbreviation":"YTM"}', NULL, 5, 7114, NULL),
(7115, 'youth league', '/''juːθ liːɡ/', 'noun', '{"zh-TW":["青少年聯賽；少年組聯賽"],"en":["a sports competition organized for young people below a certain age"]}', NULL, 'compete in a youth league / coach a youth league / youth league season', '[{"en":"He started playing in the youth league at age eight and turned professional at seventeen.","zh-TW":"他八歲開始參加青少年聯賽，十七歲時轉為職業選手。"},{"en":"Youth leagues develop skills and instill the values of teamwork and sportsmanship.","zh-TW":"青少年聯賽培養技能並灌輸團隊合作和體育精神的價值觀。"}]', NULL, NULL, 4, 7115, NULL),
(7116, 'zero coupon bond', '/ˈzɪəroʊ ˈkuːpɒn bɒnd/', 'noun', '{"zh-TW":["零息債券"],"en":["a bond that pays no regular interest but is sold at a discount"]}', NULL, 'issue a zero coupon bond / invest in zero coupon bonds', '[{"en":"Zero coupon bonds are popular for long-term retirement planning.","zh-TW":"零息債券在長期退休規劃中很受歡迎。"},{"en":"The return on a zero coupon bond comes entirely from the discount.","zh-TW":"零息債券的回報完全來自折扣差價。"}]', NULL, NULL, 5, 7116, NULL),
(7117, 'zero knowledge proof', '/ˈzɪərəʊ ˈnɒlɪdʒ pruːf/', 'noun', '{"zh-TW":["零知識證明"],"en":["a cryptographic method proving a statement without revealing any information"]}', NULL, 'implement zero knowledge proof / zero knowledge proof protocol / use zero knowledge proofs', '[{"en":"Zero knowledge proofs allow privacy-preserving authentication in digital systems.","zh-TW":"零知識證明允許數字系統中的隱私保護身份驗證。"},{"en":"Blockchain applications use zero knowledge proofs to validate transactions privately.","zh-TW":"區塊鏈應用使用零知識證明私密地驗證交易。"}]', NULL, NULL, 5, 7117, NULL),
(7118, 'zero waste', '/ˈzɪərəʊ weɪst/', 'noun', '{"zh-TW":["零廢棄"],"en":["a philosophy aimed at eliminating all waste sent to landfills"]}', NULL, 'zero waste policy / zero waste goal', '[{"en":"The office adopted a zero waste policy last year.","zh-TW":"辦公室去年採用了零廢棄政策。"},{"en":"Zero waste requires rethinking how products are designed.","zh-TW":"零廢棄需要重新思考產品的設計方式。"}]', NULL, NULL, 4, 7118, NULL),
(7119, 'zero-based budget', '/ˈzɪəroʊ beɪst ˈbʌdʒɪt/', 'noun', '{"zh-TW":["零基預算"],"en":["a budget where all expenses start at zero and must be justified each period"]}', NULL, 'prepare a zero-based budget / zero-based budget approach', '[{"en":"The finance director introduced zero-based budgeting to eliminate legacy spending.","zh-TW":"財務總監引入了零基預算以消除遺留支出。"},{"en":"Zero-based budgets prevent the automatic renewal of inefficient expenditures.","zh-TW":"零基預算防止了低效支出的自動更新。"}]', NULL, NULL, 5, 7119, NULL),
(7120, 'zero-based budgeting', '/ˌzɪərəʊ beɪst ˈbʌdʒɪtɪŋ/', 'noun', '{"zh-TW":["零基預算法"],"en":["a budgeting process starting from zero rather than the prior period"]}', NULL, 'adopt zero-based budgeting / zero-based budgeting process', '[{"en":"Zero-based budgeting requires justifying every expense from scratch.","zh-TW":"零基預算法要求從頭開始為每項費用提供理由。"},{"en":"The company switched to zero-based budgeting to cut unnecessary costs.","zh-TW":"公司改用零基預算法以削減不必要的費用。"}]', NULL, NULL, 5, 7120, NULL),
(7121, 'zero-coupon bond', '/ˌzɪərəʊ ˈkuːpɒn bɒnd/', 'noun', '{"zh-TW":["零息債券"],"en":["a bond that pays no periodic interest but is issued at a discount and redeemed at face value"]}', NULL, 'invest in zero-coupon bond / zero-coupon bond pricing / zero-coupon bond return', '[{"en":"Zero-coupon bonds provide no regular income but return the full face value at maturity.","zh-TW":"零息債券不提供定期收入，但在到期時返還全額面值。"},{"en":"Investors in zero-coupon bonds benefit when interest rates fall after purchase.","zh-TW":"在購買後利率下降時，零息債券的投資者受益。"}]', NULL, NULL, 5, 7121, NULL),
(7122, 'zero-day vulnerability', '/ˈzɪərəʊ deɪ ˌvʌlnərəˈbɪlɪti/', 'noun', '{"zh-TW":["零日漏洞"],"en":["a security flaw not yet known to the vendor and thus lacking a patch"]}', NULL, 'exploit a zero-day vulnerability / patch a zero-day vulnerability / zero-day attack', '[{"en":"Hackers exploited a zero-day vulnerability before the vendor released a fix.","zh-TW":"駭客在供應商發布修復程序之前利用了零日漏洞。"},{"en":"Zero-day vulnerabilities are extremely valuable on the dark web.","zh-TW":"零日漏洞在暗網上極為珍貴。"}]', NULL, NULL, 5, 7122, NULL),
(7123, 'zero-emissions vehicle', '/ˈzɪərəʊ ɪˈmɪʃənz ˈviːɪkəl/', 'noun', '{"zh-TW":["零排放車輛"],"en":["a vehicle that produces no direct exhaust emissions"]}', NULL, 'adopt zero-emissions vehicles / zero-emissions vehicle mandate / transition to zero-emissions vehicles', '[{"en":"Many cities are mandating zero-emissions vehicles for public transport.","zh-TW":"許多城市正在強制要求公共交通使用零排放車輛。"},{"en":"Sales of zero-emissions vehicles are growing rapidly as battery costs fall.","zh-TW":"隨著電池成本下降，零排放車輛的銷量正在快速增長。"}]', NULL, NULL, 5, 7123, NULL),
(7124, 'zero-sum', '/ˈzɪəroʊ sʌm/', 'adjective', '{"zh-TW":["零和的"],"en":["describing a situation where one party''s gain is exactly balanced by another''s loss"]}', NULL, 'zero-sum negotiation / zero-sum game / zero-sum competition', '[{"en":"Trade wars are often described as zero-sum games with no winners.","zh-TW":"貿易戰通常被描述為沒有贏家的零和遊戲。"},{"en":"A win-win deal avoids the zero-sum dynamic and benefits both parties.","zh-TW":"雙贏的交易避免了零和動態並使雙方受益。"}]', NULL, NULL, 3, 7124, NULL),
(7125, 'zero-waste', '/''zɪərəʊ weɪst/', 'adjective', '{"zh-TW":["零廢棄；零廢物"],"en":["describing a philosophy that aims to produce no waste by redesigning products and processes"]}', NULL, 'zero-waste approach / zero-waste lifestyle / zero-waste goal', '[{"en":"She adopted a zero-waste lifestyle and reduced her annual trash to a single jar.","zh-TW":"她採用了零廢棄生活方式，將她的年度垃圾減少到只有一個罐子。"},{"en":"The company committed to a zero-waste policy across all its manufacturing facilities.","zh-TW":"公司承諾在所有製造設施中實施零廢物政策。"}]', '{"noun":"waste"}', NULL, 4, 7125, NULL),
(7126, 'zest', '/''zest/', 'noun', '{"zh-TW":["柑橘皮屑；熱情"],"en":["the outer colored part of a citrus fruit peel used for flavoring; also great enthusiasm"]}', NULL, 'lemon zest / orange zest / grate the zest', '[{"en":"Add lemon zest to the batter for a bright, citrusy flavor.","zh-TW":"在麵糊中加入檸檬皮屑，增添清新的柑橘風味。"},{"en":"A little lime zest can transform a simple dish into something extraordinary.","zh-TW":"少量青檸皮屑可以將一道簡單的菜肴變成非凡之作。"}]', NULL, NULL, 1, 7126, NULL),
(7127, 'zone', '/zoʊn/', 'noun', '{"zh-TW":["地帶；區域"],"en":["an area with particular characteristics"]}', NULL, 'time zone / free trade zone / comfort zone', '[{"en":"The factory is located in a free trade zone.","zh-TW":"工廠位於自由貿易區。"},{"en":"Employees should step out of their comfort zones.","zh-TW":"員工應該走出舒適圈。"}]', '{"noun":"zone, zoning","verb":"zone"}', NULL, 1, 7127, NULL),
(7128, 'zone of negotiation', '/zoʊn əv nɪˌɡoʊʃiˈeɪʃən/', 'noun', '{"zh-TW":["談判空間；議價區間"],"en":["the range within which two parties can reach a mutually acceptable agreement"]}', NULL, 'identify the zone of negotiation / narrow the zone of negotiation', '[{"en":"Finding the zone of negotiation is the first step in any deal.","zh-TW":"找到談判空間是任何交易的第一步。"},{"en":"Both sides agreed there was a zone of negotiation between their offers.","zh-TW":"雙方同意在各自的出價之間存在議價區間。"}]', NULL, NULL, 5, 7128, NULL),
(7129, 'zone of possible agreement', '/zəʊn əv ˈpɒsɪbəl əˈɡriːmənt/', 'noun', '{"zh-TW":["可能達成協議的空間"],"en":["the range of possible outcomes in a negotiation that both parties could accept"]}', NULL, 'identify zone of possible agreement / negotiate within zone of possible agreement / expand zone of possible agreement', '[{"en":"Successful negotiations occur when both parties identify a zone of possible agreement.","zh-TW":"當雙方確定可能達成協議的空間時，談判就會成功。"},{"en":"A mediator helps parties discover whether a zone of possible agreement exists.","zh-TW":"調解員幫助各方發現是否存在可能達成協議的空間。"}]', NULL, NULL, 5, 7129, NULL),
(7130, 'zone pricing', '/zoʊn ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["區域定價"],"en":["a pricing strategy where prices vary by geographic area or delivery zone"]}', NULL, 'apply zone pricing / zone pricing policy', '[{"en":"The logistics company uses zone pricing based on delivery distance.","zh-TW":"物流公司根據交貨距離使用區域定價。"},{"en":"Zone pricing reflects the actual cost of serving different geographic areas.","zh-TW":"區域定價反映了服務不同地理區域的實際成本。"}]', NULL, NULL, 4, 7130, NULL),
(7131, 'zoning', '/ˈzəʊnɪŋ/', 'noun', '{"zh-TW":["分區；土地使用規劃"],"en":["the system of dividing land into zones for different uses"]}', NULL, 'zoning law / commercial zoning', '[{"en":"The land is zoned for mixed-use development.","zh-TW":"這片土地被劃定為混合用途開發區。"},{"en":"Zoning restrictions prevented the building of factories nearby.","zh-TW":"分區限制阻止了附近建造工廠。"}]', '{"verb":"zone","adjective":"zoned"}', NULL, 2, 7131, NULL),
(7132, 'zoning law', '/''zəʊnɪŋ lɔː/', 'noun', '{"zh-TW":["分區法規；都市規劃法"],"en":["regulations that govern how land in a specified area can be used"]}', NULL, 'comply with zoning laws / zoning law change / violate a zoning law', '[{"en":"The developer must comply with local zoning laws before breaking ground.","zh-TW":"開發商在開始施工前必須遵守當地的分區法規。"},{"en":"A change in zoning laws allowed the industrial area to be converted to residential use.","zh-TW":"分區法規的更改允許將工業區改為住宅用途。"}]', '{"adjective":"zoning","verb":"zone"}', NULL, 4, 7132, NULL);
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('account for', '解釋；佔（比例）', 'to explain or constitute a proportion', '[{"en":"Online sales account for 30% of total revenue.","zh-TW":"線上銷售佔總收入的30%。"},{"en":"How do you account for the discrepancy?","zh-TW":"你如何解釋這個差異？"},{"note":"也可表示「對…負責」。"}]', 'phrasal verb'),
('back up', '支持；備份', 'to support or make a copy of data', '[{"en":"Please back up all files before updating the system.","zh-TW":"請在更新系統前備份所有文件。"},{"en":"Can you back up your claim with evidence?","zh-TW":"你能用證據支持你的說法嗎？"},{"note":"名詞形式為 backup（備份）。"}]', 'phrasal verb'),
('break down', '分解；故障；崩潰', 'to divide into parts or stop functioning', '[{"en":"Let me break down the costs for you.","zh-TW":"讓我為你分解這些費用。"},{"en":"The machine broke down during production.","zh-TW":"機器在生產過程中故障了。"},{"note":"名詞 breakdown 指故障或明細表。"}]', 'phrasal verb'),
('bring about', '導致；引起', 'to cause something to happen', '[{"en":"The new policy brought about significant changes.","zh-TW":"新政策帶來了重大變化。"},{"en":"What brought about the merger?","zh-TW":"是什麼促成了合併？"},{"note":"較正式，可替換為 cause, lead to。"}]', 'phrasal verb'),
('bring up', '提出；養育', 'to mention or raise a topic', '[{"en":"She brought up an important issue at the meeting.","zh-TW":"她在會議上提出了一個重要問題。"},{"en":"I was brought up in a bilingual household.","zh-TW":"我在雙語家庭中長大。"},{"note":"在商務場合多指「提出議題」。"}]', 'phrasal verb'),
('call off', '取消', 'to cancel a planned event or activity', '[{"en":"They called off the conference due to the typhoon.","zh-TW":"他們因颱風取消了會議。"},{"en":"The strike was called off after negotiations.","zh-TW":"談判後罷工被取消了。"},{"note":"同義詞：cancel。"}]', 'phrasal verb'),
('carry out', '執行；實施；完成', 'to do or complete something, especially something planned', '[{"en":"The company carried out a customer satisfaction survey.","zh-TW":"公司進行了一項顧客滿意度調查。"},{"en":"We need to carry out the plan as scheduled.","zh-TW":"我們需要按計劃執行。"},{"note":"可替換為 conduct, execute, implement。"}]', 'phrasal verb'),
('catch up with', '趕上；跟上', 'to reach the same level or standard as someone', '[{"en":"We need to catch up with our competitors.","zh-TW":"我們需要趕上競爭對手。"},{"en":"I''ll catch up with you after the meeting.","zh-TW":"會議後我會跟你碰面。"},{"note":"也可表示「與…敘舊」。"}]', 'phrasal verb'),
('check in', '報到；登記入住', 'to register or report one''s arrival', '[{"en":"Guests can check in after 3 PM.","zh-TW":"客人可以在下午3點後辦理入住。"},{"en":"Please check in at the front desk upon arrival.","zh-TW":"請到達時在前台登記。"},{"note":"名詞 check-in 常用於飯店和機場。"}]', 'phrasal verb'),
('check out', '退房；查看', 'to leave a hotel or examine something', '[{"en":"We need to check out by noon.","zh-TW":"我們需要在中午前退房。"},{"en":"Check out the new product catalog.","zh-TW":"看看新的產品目錄。"},{"note":"口語中也表示「看看」。"}]', 'phrasal verb'),
('come across', '偶然遇到；給人印象', 'to find or meet by chance', '[{"en":"I came across an interesting article about AI.","zh-TW":"我偶然看到一篇關於AI的有趣文章。"},{"en":"She comes across as very professional.","zh-TW":"她給人非常專業的印象。"},{"note":"同義詞：run into, stumble upon。"}]', 'phrasal verb'),
('come up with', '想出；提出', 'to think of or produce an idea or solution', '[{"en":"The team came up with an innovative solution.","zh-TW":"團隊想出了一個創新的解決方案。"},{"en":"Can you come up with a better proposal?","zh-TW":"你能提出一個更好的提案嗎？"},{"note":"常用於腦力激盪和問題解決情境。"}]', 'phrasal verb'),
('count on', '依靠；指望', 'to rely or depend on someone or something', '[{"en":"You can always count on her to meet deadlines.","zh-TW":"你總是可以指望她在截止日期前完成。"},{"en":"We''re counting on your cooperation.","zh-TW":"我們指望您的合作。"},{"note":"同義詞：rely on, depend on。"}]', 'phrasal verb'),
('cut back on', '削減；縮減', 'to reduce the amount or level of something', '[{"en":"The company cut back on travel expenses.","zh-TW":"公司削減了差旅費用。"},{"en":"We need to cut back on unnecessary spending.","zh-TW":"我們需要削減不必要的開支。"},{"note":"也可用 cut down on。"}]', 'phrasal verb'),
('deal with', '處理；應對', 'to take action to handle a situation or problem', '[{"en":"How do you deal with difficult customers?","zh-TW":"你如何應對難纏的客戶？"},{"en":"We need to deal with this issue immediately.","zh-TW":"我們需要立即處理這個問題。"},{"note":"同義詞：handle, address, tackle。"}]', 'phrasal verb'),
('do away with', '廢除；去掉', 'to eliminate or get rid of something', '[{"en":"The company did away with the old filing system.","zh-TW":"公司廢除了舊的歸檔系統。"},{"en":"They plan to do away with unnecessary regulations.","zh-TW":"他們計劃廢除不必要的規定。"},{"note":"較正式，常見於政策或制度變更。"}]', 'phrasal verb'),
('draw up', '草擬；制定', 'to prepare a document, plan, or agreement', '[{"en":"The lawyer drew up the contract.","zh-TW":"律師草擬了合約。"},{"en":"We need to draw up a business plan.","zh-TW":"我們需要制定一份商業計畫。"},{"note":"同義詞：draft, prepare, formulate。"}]', 'phrasal verb'),
('drop off', '放下（人或物）；下降', 'to deliver or leave something/someone at a place', '[{"en":"I''ll drop off the documents at your office.","zh-TW":"我會把文件送到你的辦公室。"},{"en":"Sales dropped off significantly in Q4.","zh-TW":"第四季度銷售額大幅下降。"},{"note":"也可表示「減少、下降」。"}]', 'phrasal verb'),
('end up', '最終；結果是', 'to finally be in a particular place or situation', '[{"en":"We ended up postponing the launch.","zh-TW":"我們最終推遲了發佈。"},{"en":"He ended up as the CEO of the company.","zh-TW":"他最終成為了公司的CEO。"},{"note":"常用於描述意外的結果。"}]', 'phrasal verb'),
('fall behind', '落後；拖延', 'to fail to keep up with a schedule or standard', '[{"en":"The project has fallen behind schedule.","zh-TW":"這個專案已經落後於進度了。"},{"en":"Don''t fall behind on your payments.","zh-TW":"不要拖欠付款。"},{"note":"反義詞：keep up with, stay ahead of。"}]', 'phrasal verb'),
('figure out', '弄清楚；想出', 'to understand or solve something', '[{"en":"We need to figure out why sales declined.","zh-TW":"我們需要弄清楚為什麼銷售額下降了。"},{"en":"Can you figure out how to fix this?","zh-TW":"你能想出如何修復這個問題嗎？"},{"note":"同義詞：work out, solve, determine。"}]', 'phrasal verb'),
('fill in', '填寫；代替', 'to complete a form or substitute for someone', '[{"en":"Please fill in this application form.","zh-TW":"請填寫這份申請表。"},{"en":"Can you fill in for me at the meeting?","zh-TW":"你能代替我出席會議嗎？"},{"note":"fill in 側重填入資訊，fill out 側重完成整份表格。"}]', 'phrasal verb'),
('fill out', '填寫（完整表格）', 'to complete a form or document entirely', '[{"en":"All applicants must fill out the online form.","zh-TW":"所有申請人必須填寫線上表格。"},{"en":"Please fill out the survey before leaving.","zh-TW":"請在離開前填寫問卷。"},{"note":"美式英語較常用 fill out，英式用 fill in。"}]', 'phrasal verb'),
('find out', '發現；查明', 'to discover or learn information', '[{"en":"I just found out about the policy change.","zh-TW":"我剛得知政策變更的事。"},{"en":"We need to find out what went wrong.","zh-TW":"我們需要查明出了什麼問題。"},{"note":"同義詞：discover, learn, determine。"}]', 'phrasal verb'),
('follow up', '跟進；後續追蹤', 'to take further action after an initial step', '[{"en":"I''ll follow up with the client next week.","zh-TW":"我下週會跟進客戶。"},{"en":"Don''t forget to follow up on the proposal.","zh-TW":"別忘了追蹤那份提案。"},{"note":"名詞 follow-up 表示後續行動或追蹤。"}]', 'phrasal verb'),
('get along with', '與…相處融洽', 'to have a good relationship with someone', '[{"en":"She gets along well with all her colleagues.","zh-TW":"她和所有同事都相處得很好。"},{"en":"It''s important to get along with your team.","zh-TW":"和團隊相處融洽很重要。"},{"note":"同義詞：get on with（英式）。"}]', 'phrasal verb'),
('get back to', '回覆；稍後聯繫', 'to contact someone later with information', '[{"en":"Let me get back to you on that.","zh-TW":"讓我稍後回覆你這件事。"},{"en":"I''ll get back to you with the details.","zh-TW":"我會把細節回覆給你。"},{"note":"商務場合常用的禮貌用語。"}]', 'phrasal verb'),
('get rid of', '擺脫；丟掉', 'to remove or dispose of something unwanted', '[{"en":"We need to get rid of outdated inventory.","zh-TW":"我們需要處理掉過時的庫存。"},{"en":"The company got rid of the redundant positions.","zh-TW":"公司裁撤了多餘的職位。"},{"note":"同義詞：eliminate, dispose of, discard。"}]', 'phrasal verb'),
('give up', '放棄', 'to stop trying or surrender something', '[{"en":"Don''t give up on the project yet.","zh-TW":"先別放棄這個專案。"},{"en":"He gave up his position to pursue other interests.","zh-TW":"他放棄了職位去追求其他興趣。"},{"note":"反義詞：persist, keep trying。"}]', 'phrasal verb'),
('go ahead', '進行；開始做', 'to proceed with something', '[{"en":"We decided to go ahead with the merger.","zh-TW":"我們決定繼續進行合併。"},{"en":"Go ahead and submit the report.","zh-TW":"請繼續提交報告吧。"},{"note":"常用於給予許可或鼓勵。"}]', 'phrasal verb'),
('go over', '仔細檢查；複習', 'to review or examine something carefully', '[{"en":"Let''s go over the quarterly report together.","zh-TW":"讓我們一起審閱季度報告。"},{"en":"I need to go over my notes before the presentation.","zh-TW":"我需要在簡報前複習我的筆記。"},{"note":"同義詞：review, examine, look over。"}]', 'phrasal verb'),
('go through', '經歷；仔細查閱', 'to experience or examine carefully', '[{"en":"The company is going through a restructuring.","zh-TW":"公司正在經歷重組。"},{"en":"Please go through the contract carefully.","zh-TW":"請仔細審閱合約。"},{"note":"也可表示「用完」（go through supplies）。"}]', 'phrasal verb'),
('hand in', '提交；繳交', 'to submit or give something to someone in authority', '[{"en":"Please hand in your expense reports by Friday.","zh-TW":"請在週五前提交費用報告。"},{"en":"She handed in her resignation letter.","zh-TW":"她遞交了辭職信。"},{"note":"同義詞：submit, turn in。"}]', 'phrasal verb'),
('hand out', '分發', 'to distribute something to people', '[{"en":"They handed out brochures at the trade show.","zh-TW":"他們在展覽會上分發手冊。"},{"en":"The manager handed out the new guidelines.","zh-TW":"經理分發了新的指導方針。"},{"note":"名詞 handout 指講義或分發材料。"}]', 'phrasal verb'),
('hold on', '等一下；堅持', 'to wait or continue despite difficulty', '[{"en":"Hold on, I''ll transfer you to the right department.","zh-TW":"請稍等，我會把你轉到正確的部門。"},{"en":"Hold on to those documents; we''ll need them later.","zh-TW":"保留那些文件，我們之後會用到。"},{"note":"電話用語中常見。"}]', 'phrasal verb'),
('keep up with', '跟上；保持同步', 'to stay at the same level or pace', '[{"en":"It''s hard to keep up with the latest technology.","zh-TW":"很難跟上最新的技術。"},{"en":"Production can''t keep up with demand.","zh-TW":"生產跟不上需求。"},{"note":"反義詞：fall behind。"}]', 'phrasal verb'),
('lay off', '裁員；解僱', 'to dismiss workers because of lack of work', '[{"en":"The factory laid off 200 workers.","zh-TW":"工廠裁減了200名工人。"},{"en":"Several departments are facing layoffs.","zh-TW":"好幾個部門面臨裁員。"},{"note":"名詞 layoff 指裁員行為。與 fire（因表現不佳解僱）不同。"}]', 'phrasal verb'),
('leave out', '遺漏；省略', 'to not include or omit something', '[{"en":"Don''t leave out any important details.","zh-TW":"不要遺漏任何重要細節。"},{"en":"Some key data was left out of the report.","zh-TW":"報告中遺漏了一些關鍵數據。"},{"note":"同義詞：omit, exclude。"}]', 'phrasal verb'),
('let down', '使失望', 'to disappoint someone', '[{"en":"We can''t let our clients down.","zh-TW":"我們不能讓客戶失望。"},{"en":"The supplier really let us down this time.","zh-TW":"供應商這次真的讓我們失望了。"},{"note":"名詞 letdown 指令人失望的事。"}]', 'phrasal verb'),
('line up', '安排；排隊', 'to arrange or organize in order', '[{"en":"We''ve lined up three candidates for interviews.","zh-TW":"我們已安排了三位候選人面試。"},{"en":"Several investors are lined up for the project.","zh-TW":"已有幾位投資者對這個專案有興趣。"},{"note":"也指「排隊」（line up at the counter）。"}]', 'phrasal verb'),
('look after', '照顧；負責', 'to take care of someone or something', '[{"en":"Who will look after the department while you''re away?","zh-TW":"你不在的時候誰負責部門？"},{"en":"She looks after all the VIP accounts.","zh-TW":"她負責所有VIP帳戶。"},{"note":"同義詞：take care of。"}]', 'phrasal verb'),
('look forward to', '期待', 'to feel excited about something that will happen', '[{"en":"I look forward to hearing from you soon.","zh-TW":"我期待很快收到您的回覆。"},{"en":"We look forward to working with your team.","zh-TW":"我們期待與你們的團隊合作。"},{"note":"後接名詞或動名詞（V-ing）。商業書信常用。"}]', 'phrasal verb'),
('look into', '調查；研究', 'to investigate or examine something', '[{"en":"We will look into the matter immediately.","zh-TW":"我們會立即調查此事。"},{"en":"I''m looking into several options for the venue.","zh-TW":"我正在研究場地的幾個選項。"},{"note":"同義詞：investigate, examine, explore。"}]', 'phrasal verb'),
('look over', '瀏覽；檢查', 'to examine or inspect something quickly', '[{"en":"Could you look over this proposal for me?","zh-TW":"你能幫我看一下這份提案嗎？"},{"en":"I''ll look over the contract tonight.","zh-TW":"我今晚會看一下合約。"},{"note":"比 go over 更快速、不那麼仔細。"}]', 'phrasal verb'),
('look up', '查閱；好轉', 'to search for information or improve', '[{"en":"You can look up the details on our website.","zh-TW":"你可以在我們的網站上查閱詳情。"},{"en":"Business is finally looking up.","zh-TW":"生意終於好轉了。"},{"note":"look up to 表示「尊敬」。"}]', 'phrasal verb'),
('make up', '組成；編造；彌補', 'to constitute or compensate', '[{"en":"Women make up 45% of our workforce.","zh-TW":"女性佔我們勞動力的45%。"},{"en":"We need to make up for lost time.","zh-TW":"我們需要彌補失去的時間。"},{"note":"make up for 表示「彌補」。"}]', 'phrasal verb'),
('make up for', '彌補；補償', 'to compensate for something lost or missed', '[{"en":"The team worked overtime to make up for the delay.","zh-TW":"團隊加班以彌補延遲。"},{"en":"Nothing can make up for poor customer service.","zh-TW":"沒什麼能彌補糟糕的客戶服務。"},{"note":"同義詞：compensate for。"}]', 'phrasal verb'),
('move on', '繼續前進；轉向下一個', 'to proceed to the next thing', '[{"en":"Let''s move on to the next agenda item.","zh-TW":"讓我們進入下一個議程。"},{"en":"It''s time to move on from this issue.","zh-TW":"是時候放下這個問題往前走了。"},{"note":"會議中常用來轉換話題。"}]', 'phrasal verb'),
('narrow down', '縮小範圍', 'to reduce the number of options or possibilities', '[{"en":"We''ve narrowed down the candidates to three.","zh-TW":"我們已將候選人縮減到三位。"},{"en":"Let''s narrow down the options before deciding.","zh-TW":"讓我們在決定前縮小選項範圍。"},{"note":"常用於決策過程。"}]', 'phrasal verb'),
('opt for', '選擇', 'to choose one option over others', '[{"en":"Most employees opted for the flexible schedule.","zh-TW":"大多數員工選擇了彈性工時。"},{"en":"We opted for the more affordable solution.","zh-TW":"我們選擇了更經濟實惠的方案。"},{"note":"同義詞：choose, select, go for。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('pass on', '傳遞；轉交；拒絕', 'to give information to someone else or decline', '[{"en":"Could you pass on this message to the director?","zh-TW":"你能把這個訊息轉達給主管嗎？"},{"en":"I''ll have to pass on that offer.","zh-TW":"我必須拒絕那個提議。"},{"note":"pass on 也可委婉表示「拒絕」。"}]', 'phrasal verb'),
('pay off', '還清；得到回報', 'to finish paying a debt or yield good results', '[{"en":"All our hard work finally paid off.","zh-TW":"我們所有的努力終於得到了回報。"},{"en":"She paid off her student loans in five years.","zh-TW":"她在五年內還清了學生貸款。"},{"note":"作為成語意味「值得、有回報」。"}]', 'phrasal verb'),
('pick up', '拿起；學會；接載；好轉', 'to collect, learn, or improve', '[{"en":"She picked up some useful skills at the workshop.","zh-TW":"她在研討會上學到了一些有用的技能。"},{"en":"Sales usually pick up in the holiday season.","zh-TW":"銷售通常在假期旺季好轉。"},{"note":"多義詞，根據上下文判斷意思。"}]', 'phrasal verb'),
('point out', '指出', 'to draw attention to something', '[{"en":"I''d like to point out a few errors in the report.","zh-TW":"我想指出報告中的一些錯誤。"},{"en":"She pointed out the benefits of the new system.","zh-TW":"她指出了新系統的好處。"},{"note":"同義詞：highlight, indicate, note。"}]', 'phrasal verb'),
('put forward', '提出（建議或計畫）', 'to propose or suggest an idea', '[{"en":"He put forward a proposal for restructuring.","zh-TW":"他提出了一份重組提案。"},{"en":"Several ideas were put forward at the brainstorming session.","zh-TW":"腦力激盪會議上提出了幾個想法。"},{"note":"同義詞：propose, suggest, present。"}]', 'phrasal verb'),
('put off', '延期；使反感', 'to postpone or discourage someone', '[{"en":"We had to put off the product launch.","zh-TW":"我們不得不延期產品發佈。"},{"en":"Don''t be put off by the initial cost.","zh-TW":"不要被初始成本嚇退。"},{"note":"同義詞（延期）：postpone, delay, defer。"}]', 'phrasal verb'),
('put together', '組合；準備', 'to assemble or prepare something', '[{"en":"She put together a great presentation.","zh-TW":"她準備了一份很棒的簡報。"},{"en":"We need to put together a project team.","zh-TW":"我們需要組建一個專案團隊。"},{"note":"同義詞：assemble, compile, prepare。"}]', 'phrasal verb'),
('put up with', '忍受', 'to tolerate something unpleasant', '[{"en":"We can''t put up with any more delays.","zh-TW":"我們不能再忍受任何延誤了。"},{"en":"Employees shouldn''t have to put up with harassment.","zh-TW":"員工不應該忍受騷擾。"},{"note":"同義詞：tolerate, endure, bear。"}]', 'phrasal verb'),
('rely on', '依賴；信賴', 'to depend on or trust someone or something', '[{"en":"We rely heavily on our suppliers for timely delivery.","zh-TW":"我們非常依賴供應商的及時交貨。"},{"en":"You can rely on the accuracy of this data.","zh-TW":"你可以信賴這些數據的準確性。"},{"note":"同義詞：depend on, count on。"}]', 'phrasal verb'),
('run into', '偶遇；遇到（問題）', 'to meet by chance or encounter a problem', '[{"en":"We ran into some unexpected difficulties.","zh-TW":"我們遇到了一些意外的困難。"},{"en":"I ran into a former colleague at the conference.","zh-TW":"我在會議上偶遇了一位前同事。"},{"note":"同義詞：come across, encounter。"}]', 'phrasal verb'),
('run out of', '用完；耗盡', 'to have no more of something', '[{"en":"We''ve run out of printer paper.","zh-TW":"我們的印表機紙用完了。"},{"en":"Time is running out for the project deadline.","zh-TW":"專案截止日期的時間快到了。"},{"note":"也可不及物：The supplies ran out.（補給品用完了。）"}]', 'phrasal verb'),
('set up', '設立；安排；建立', 'to establish or arrange something', '[{"en":"They set up a new branch office in Taipei.","zh-TW":"他們在台北設立了一個新的分公司。"},{"en":"Can you help me set up the video conference?","zh-TW":"你能幫我設置視訊會議嗎？"},{"note":"名詞 setup 指設置或安排。"}]', 'phrasal verb'),
('show up', '出現；到場', 'to arrive or appear at a place', '[{"en":"Only half the team showed up for the meeting.","zh-TW":"只有一半的團隊成員出席了會議。"},{"en":"He didn''t show up for work today.","zh-TW":"他今天沒有來上班。"},{"note":"同義詞：appear, arrive, turn up。"}]', 'phrasal verb'),
('sign up', '報名；註冊', 'to register or enroll for something', '[{"en":"Over 100 people signed up for the seminar.","zh-TW":"超過100人報名了研討會。"},{"en":"You can sign up for the newsletter on our website.","zh-TW":"你可以在我們的網站上訂閱電子報。"},{"note":"名詞 sign-up 指報名或註冊。"}]', 'phrasal verb'),
('sort out', '解決；整理', 'to resolve a problem or organize something', '[{"en":"We need to sort out the scheduling conflict.","zh-TW":"我們需要解決排程衝突。"},{"en":"Let me sort out the paperwork first.","zh-TW":"讓我先把文件整理好。"},{"note":"同義詞：resolve, fix, organize。"}]', 'phrasal verb'),
('stand for', '代表；容忍', 'to represent or tolerate something', '[{"en":"CEO stands for Chief Executive Officer.","zh-TW":"CEO代表首席執行長。"},{"en":"We won''t stand for this kind of behavior.","zh-TW":"我們不會容忍這種行為。"},{"note":"在縮寫解釋中非常常見。"}]', 'phrasal verb'),
('step down', '辭職；退位', 'to resign from an important position', '[{"en":"The chairman stepped down due to health reasons.","zh-TW":"主席因健康原因辭職了。"},{"en":"She decided to step down as project lead.","zh-TW":"她決定辭去專案負責人一職。"},{"note":"同義詞：resign, retire, quit。"}]', 'phrasal verb'),
('switch off', '關閉；關掉', 'to turn off a device or stop paying attention', '[{"en":"Please switch off your mobile phones during the meeting.","zh-TW":"會議期間請關閉手機。"},{"en":"Remember to switch off the lights when you leave.","zh-TW":"離開時記得關燈。"},{"note":"同義詞：turn off。反義詞：switch on, turn on。"}]', 'phrasal verb'),
('take advantage of', '利用', 'to use an opportunity or situation to benefit', '[{"en":"You should take advantage of the training program.","zh-TW":"你應該利用這個培訓計畫。"},{"en":"Let''s take advantage of the current market conditions.","zh-TW":"讓我們利用當前的市場條件。"},{"note":"中性用法指善用機會，也可暗示不當利用。"}]', 'phrasal verb'),
('take into account', '考慮；納入考量', 'to consider something when making a decision', '[{"en":"We need to take all factors into account.","zh-TW":"我們需要考慮所有因素。"},{"en":"The budget takes inflation into account.","zh-TW":"預算已考慮了通貨膨脹。"},{"note":"同義詞：consider, factor in, take into consideration。"}]', 'phrasal verb'),
('take off', '起飛；脫下；開始成功', 'to leave the ground or become successful', '[{"en":"The startup really took off after the investment.","zh-TW":"新創公司在獲得投資後真正起飛了。"},{"en":"The flight takes off at 8 AM.","zh-TW":"航班早上8點起飛。"},{"note":"商務中常指事業或產品「起飛、成功」。"}]', 'phrasal verb'),
('take on', '承擔；僱用', 'to accept responsibility or hire someone', '[{"en":"She took on additional responsibilities.","zh-TW":"她承擔了額外的職責。"},{"en":"The company is taking on new staff.","zh-TW":"公司正在招聘新員工。"},{"note":"同義詞（承擔）：assume, undertake。"}]', 'phrasal verb'),
('take over', '接管；接手', 'to assume control of something', '[{"en":"A larger firm took over the company.","zh-TW":"一家較大的公司收購了該公司。"},{"en":"Who will take over when the manager retires?","zh-TW":"經理退休後誰來接手？"},{"note":"名詞 takeover 指收購或接管。"}]', 'phrasal verb'),
('take part in', '參加；參與', 'to participate in an activity or event', '[{"en":"All employees are encouraged to take part in the training.","zh-TW":"鼓勵所有員工參加培訓。"},{"en":"Over 500 companies took part in the trade fair.","zh-TW":"超過500家公司參加了貿易展覽會。"},{"note":"同義詞：participate in, join, engage in。"}]', 'phrasal verb'),
('take place', '發生；舉行', 'to happen or occur', '[{"en":"The annual meeting will take place on March 15.","zh-TW":"年度會議將於3月15日舉行。"},{"en":"Major changes have taken place in the industry.","zh-TW":"該行業發生了重大變化。"},{"note":"同義詞：occur, happen, be held。"}]', 'phrasal verb'),
('take up', '佔據；開始從事', 'to fill time/space or begin a new activity', '[{"en":"The new equipment takes up a lot of space.","zh-TW":"新設備佔了很多空間。"},{"en":"She took up the position of marketing director.","zh-TW":"她就任了行銷總監的職位。"},{"note":"take up on 表示「接受（提議）」。"}]', 'phrasal verb'),
('think over', '仔細考慮', 'to consider something carefully before deciding', '[{"en":"I need a few days to think over your offer.","zh-TW":"我需要幾天時間考慮你的提議。"},{"en":"Think it over and let me know by Monday.","zh-TW":"好好想想，週一前告訴我。"},{"note":"同義詞：consider, contemplate, deliberate。"}]', 'phrasal verb'),
('throw away', '丟掉；浪費', 'to discard or waste something', '[{"en":"Don''t throw away those receipts; we need them for tax purposes.","zh-TW":"別丟掉那些收據，我們報稅需要用。"},{"en":"We can''t throw away this opportunity.","zh-TW":"我們不能浪費這個機會。"},{"note":"同義詞：discard, dispose of, waste。"}]', 'phrasal verb'),
('try on', '試穿', 'to put on clothing to see if it fits', '[{"en":"You can try on the uniform in the fitting room.","zh-TW":"你可以在試衣間試穿制服。"},{"en":"She tried on several outfits before the interview.","zh-TW":"面試前她試穿了幾套服裝。"},{"note":"常見於購物情境。"}]', 'phrasal verb'),
('turn down', '拒絕；調低', 'to reject an offer or reduce volume/level', '[{"en":"They turned down our proposal.","zh-TW":"他們拒絕了我們的提案。"},{"en":"The bank turned down his loan application.","zh-TW":"銀行拒絕了他的貸款申請。"},{"note":"同義詞（拒絕）：reject, decline, refuse。"}]', 'phrasal verb'),
('turn in', '繳交；上交', 'to submit or hand over something', '[{"en":"All reports must be turned in by the end of the month.","zh-TW":"所有報告必須在月底前繳交。"},{"en":"He turned in his badge and ID card.","zh-TW":"他上交了他的證件和身分證。"},{"note":"同義詞：submit, hand in。"}]', 'phrasal verb'),
('turn off', '關閉', 'to stop a device or make someone lose interest', '[{"en":"Please turn off all electronic devices during the presentation.","zh-TW":"簡報期間請關閉所有電子裝置。"},{"en":"The long commute really turns off potential candidates.","zh-TW":"長途通勤真的讓潛在候選人失去興趣。"},{"note":"反義詞：turn on。"}]', 'phrasal verb'),
('turn on', '打開；開啟', 'to start a device or activate something', '[{"en":"Turn on the projector before the meeting starts.","zh-TW":"會議開始前打開投影機。"},{"en":"The heating system turns on automatically.","zh-TW":"暖氣系統會自動開啟。"},{"note":"反義詞：turn off, switch off。"}]', 'phrasal verb'),
('turn out', '結果是；證明是', 'to have a particular result', '[{"en":"The event turned out to be a great success.","zh-TW":"活動結果非常成功。"},{"en":"Things didn''t turn out as planned.","zh-TW":"事情沒有按計劃發展。"},{"note":"常用於描述意外或最終結果。"}]', 'phrasal verb'),
('turn up', '出現；調高', 'to appear or increase the level of something', '[{"en":"New evidence turned up during the audit.","zh-TW":"審計期間出現了新證據。"},{"en":"He turned up late for the interview.","zh-TW":"他面試遲到了。"},{"note":"同義詞（出現）：show up, appear。"}]', 'phrasal verb'),
('use up', '用完；耗盡', 'to consume all of something', '[{"en":"We''ve used up most of the budget already.","zh-TW":"我們已經用完了大部分預算。"},{"en":"The project used up all available resources.","zh-TW":"這個專案耗盡了所有可用資源。"},{"note":"同義詞：exhaust, deplete, consume。"}]', 'phrasal verb'),
('watch out', '小心；注意', 'to be careful or alert about something', '[{"en":"Watch out for hidden fees in the contract.","zh-TW":"注意合約中的隱藏費用。"},{"en":"Watch out for phishing emails.","zh-TW":"小心釣魚郵件。"},{"note":"同義詞：be careful, be cautious, beware。"}]', 'phrasal verb'),
('work on', '從事；致力於', 'to spend time and effort on something', '[{"en":"The team is working on the quarterly report.","zh-TW":"團隊正在撰寫季度報告。"},{"en":"We need to work on improving customer satisfaction.","zh-TW":"我們需要致力於提高客戶滿意度。"},{"note":"強調持續進行中的工作。"}]', 'phrasal verb'),
('work out', '解決；算出；結果良好', 'to solve or have a good result', '[{"en":"I''m sure everything will work out fine.","zh-TW":"我相信一切都會順利解決的。"},{"en":"We need to work out the logistics.","zh-TW":"我們需要把後勤細節弄清楚。"},{"note":"也可指「運動」（I work out every morning.）。"}]', 'phrasal verb'),
('wrap up', '完成；結束', 'to finish or conclude something', '[{"en":"Let''s wrap up the meeting; we''re running out of time.","zh-TW":"讓我們結束會議吧，我們時間不多了。"},{"en":"The project should be wrapped up by Friday.","zh-TW":"專案應該在週五前完成。"},{"note":"同義詞：conclude, finish, complete。"}]', 'phrasal verb'),
('at the latest', '最遲', 'no later than a specified time', '[{"en":"Please submit the report by Friday at the latest.","zh-TW":"請最遲在週五前提交報告。"},{"en":"The delivery will arrive by noon at the latest.","zh-TW":"交貨最遲在中午前到達。"},{"note":"用於設定截止日期。"}]', 'expression'),
('at short notice', '臨時通知；倉促地', 'with very little warning or preparation time', '[{"en":"She had to arrange the meeting at short notice.","zh-TW":"她不得不臨時安排會議。"},{"en":"We apologize for the change at such short notice.","zh-TW":"我們為如此倉促的變更致歉。"},{"note":"美式常用 on short notice。"}]', 'expression'),
('behind schedule', '落後於進度', 'later than planned', '[{"en":"The construction project is two weeks behind schedule.","zh-TW":"建設專案落後了兩週進度。"},{"en":"We can''t afford to fall further behind schedule.","zh-TW":"我們不能再繼續落後進度了。"},{"note":"反義詞：ahead of schedule, on schedule。"}]', 'expression'),
('bottom line', '底線；最終結果；利潤', 'the most important factor or the net profit', '[{"en":"The bottom line is we need to cut costs.","zh-TW":"最終結論是我們需要削減成本。"},{"en":"How will this affect our bottom line?","zh-TW":"這將如何影響我們的利潤？"},{"note":"原指財務報表的最後一行（淨利）。"}]', 'business idiom'),
('break even', '損益兩平', 'to have equal income and expenses, no profit or loss', '[{"en":"The company expects to break even by Q3.","zh-TW":"公司預計在第三季度達到損益兩平。"},{"en":"We need to sell 500 units to break even.","zh-TW":"我們需要賣出500個單位才能打平。"},{"note":"名詞 break-even point 指損益平衡點。"}]', 'business idiom'),
('bring to attention', '提請注意', 'to make someone aware of something', '[{"en":"I''d like to bring this issue to your attention.","zh-TW":"我想提請您注意這個問題。"},{"en":"It was brought to our attention that costs have risen.","zh-TW":"有人提醒我們注意成本上升了。"},{"note":"正式用語，常見於商務信件。"}]', 'expression'),
('by all means', '當然；請便', 'used to give permission or encourage', '[{"en":"By all means, feel free to contact me anytime.","zh-TW":"請隨時聯繫我，不用客氣。"},{"en":"By all means, take the day off if you need to.","zh-TW":"如果需要的話，請一定休假。"},{"note":"表示非常樂意同意的禮貌用語。"}]', 'expression'),
('close a deal', '成交；達成交易', 'to successfully complete a business agreement', '[{"en":"We managed to close the deal with the Japanese firm.","zh-TW":"我們成功與日本公司達成交易。"},{"en":"The sales team is close to closing the deal.","zh-TW":"銷售團隊即將達成交易。"},{"note":"同義詞：seal a deal, finalize an agreement。"}]', 'business idiom'),
('come into effect', '生效', 'to start being applied or enforced', '[{"en":"The new regulations come into effect next month.","zh-TW":"新法規下個月生效。"},{"en":"The policy came into effect on January 1st.","zh-TW":"該政策於1月1日生效。"},{"note":"同義詞：take effect, become effective。"}]', 'expression'),
('cut corners', '偷工減料；走捷徑', 'to do something in the cheapest or easiest way', '[{"en":"We can''t cut corners on product safety.","zh-TW":"我們不能在產品安全上偷工減料。"},{"en":"Cutting corners now will cost us more later.","zh-TW":"現在偷工減料以後會花更多錢。"},{"note":"通常帶有負面含義。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('day off', '休假日', 'a day when you do not work', '[{"en":"I''m taking a day off next Monday.","zh-TW":"下週一我要休一天假。"},{"en":"Employees get two days off per week.","zh-TW":"員工每週有兩天休假。"},{"note":"複數形式：days off。"}]', 'expression'),
('due to', '由於；因為', 'because of; caused by', '[{"en":"The flight was delayed due to bad weather.","zh-TW":"航班因天氣不佳而延誤。"},{"en":"Due to high demand, the product is sold out.","zh-TW":"由於需求量大，產品已售罄。"},{"note":"較正式，可替換為 because of, owing to。"}]', 'prepositional phrase'),
('first and foremost', '首先；最重要的是', 'most importantly; before anything else', '[{"en":"First and foremost, we need to ensure customer safety.","zh-TW":"首先且最重要的是，我們需要確保客戶安全。"},{"en":"First and foremost, I want to thank the team.","zh-TW":"首先，我想感謝團隊。"},{"note":"用於強調最重要的事項。"}]', 'expression'),
('from scratch', '從零開始', 'from the very beginning with no prior preparation', '[{"en":"We built the software from scratch.","zh-TW":"我們從零開始開發了這款軟體。"},{"en":"After the fire, they had to start from scratch.","zh-TW":"火災後，他們不得不從頭開始。"},{"note":"強調沒有任何基礎或現有材料。"}]', 'expression'),
('get the ball rolling', '開始行動；啟動', 'to start an activity or process', '[{"en":"Let''s get the ball rolling on the new marketing campaign.","zh-TW":"讓我們開始啟動新的行銷活動。"},{"en":"Who''s going to get the ball rolling?","zh-TW":"誰來帶頭開始？"},{"note":"同義詞：kick off, initiate, start。"}]', 'business idiom'),
('go bankrupt', '破產', 'to be unable to pay debts and officially declared insolvent', '[{"en":"Several small businesses went bankrupt during the recession.","zh-TW":"經濟衰退期間有幾家小企業破產了。"},{"en":"The company filed for bankruptcy last month.","zh-TW":"該公司上個月申請破產。"},{"note":"名詞形式：bankruptcy。"}]', 'business idiom'),
('in advance', '預先；提前', 'before a particular time or event', '[{"en":"Please confirm your attendance in advance.","zh-TW":"請提前確認您的出席。"},{"en":"Tickets should be purchased well in advance.","zh-TW":"門票應該提前購買。"},{"note":"同義詞：beforehand, ahead of time。"}]', 'prepositional phrase'),
('in bulk', '大量地', 'in large quantities', '[{"en":"We get a discount when we order in bulk.","zh-TW":"大量訂購時我們可以獲得折扣。"},{"en":"Buying office supplies in bulk saves money.","zh-TW":"大量購買辦公用品可以省錢。"},{"note":"常與折扣、採購相關。"}]', 'prepositional phrase'),
('in charge of', '負責；管理', 'responsible for managing or controlling', '[{"en":"Who is in charge of the marketing department?","zh-TW":"誰負責行銷部門？"},{"en":"She is in charge of all overseas operations.","zh-TW":"她負責所有海外業務。"},{"note":"同義詞：responsible for, in control of。"}]', 'prepositional phrase'),
('in compliance with', '遵照；符合', 'in accordance with rules or regulations', '[{"en":"All products must be in compliance with safety standards.","zh-TW":"所有產品必須符合安全標準。"},{"en":"We operate in compliance with local regulations.","zh-TW":"我們的營運遵照當地法規。"},{"note":"法律和商業文件中常見。"}]', 'prepositional phrase'),
('in demand', '有需求的；搶手的', 'wanted or needed by many people', '[{"en":"Skilled IT professionals are in high demand.","zh-TW":"技術熟練的IT專業人員非常搶手。"},{"en":"The product is in great demand this season.","zh-TW":"這個產品本季非常搶手。"},{"note":"反義詞：out of demand。"}]', 'prepositional phrase'),
('in effect', '實際上；生效中', 'in operation or essentially', '[{"en":"The new policy is now in effect.","zh-TW":"新政策現已生效。"},{"en":"In effect, this means a 10% pay cut.","zh-TW":"實際上，這意味著減薪10%。"},{"note":"同義詞（生效）：in force, operative。"}]', 'prepositional phrase'),
('in lieu of', '代替；取代', 'instead of; in place of', '[{"en":"He received stock options in lieu of a bonus.","zh-TW":"他獲得了股票選擇權以代替獎金。"},{"en":"Payment in lieu of notice is acceptable.","zh-TW":"以支付代替通知期是可接受的。"},{"note":"正式用語，常見於合約和HR文件。"}]', 'prepositional phrase'),
('in light of', '鑒於；考慮到', 'because of; considering', '[{"en":"In light of recent developments, we''ll revise our strategy.","zh-TW":"鑒於近期發展，我們將修改策略。"},{"en":"In light of the feedback, we made several changes.","zh-TW":"考慮到回饋意見，我們做了幾處修改。"},{"note":"同義詞：considering, given, in view of。"}]', 'prepositional phrase'),
('in progress', '進行中', 'happening or being done now', '[{"en":"The renovation is still in progress.","zh-TW":"裝修仍在進行中。"},{"en":"Please do not disturb; meeting in progress.","zh-TW":"請勿打擾，會議進行中。"},{"note":"WIP = Work In Progress。"}]', 'prepositional phrase'),
('in response to', '回應；針對', 'as a reply or reaction to something', '[{"en":"In response to your inquiry, please find the attached document.","zh-TW":"針對您的詢問，請查看附件文件。"},{"en":"The company issued a statement in response to the criticism.","zh-TW":"公司針對批評發表了一份聲明。"},{"note":"商業信件常見開頭用語。"}]', 'prepositional phrase'),
('in stock', '有庫存', 'available for purchase or use', '[{"en":"The item is currently in stock.","zh-TW":"該商品目前有庫存。"},{"en":"We always keep essential supplies in stock.","zh-TW":"我們始終保持必需品有庫存。"},{"note":"反義詞：out of stock。"}]', 'prepositional phrase'),
('in terms of', '在…方面；就…而言', 'regarding; with respect to', '[{"en":"In terms of revenue, this was our best year.","zh-TW":"就收入而言，這是我們最好的一年。"},{"en":"What does this mean in terms of budget?","zh-TW":"就預算而言，這意味著什麼？"},{"note":"用於限定討論範圍。"}]', 'prepositional phrase'),
('in the long run', '從長遠來看', 'over a long period of time; eventually', '[{"en":"This investment will pay off in the long run.","zh-TW":"這項投資從長遠來看會有回報。"},{"en":"In the long run, quality is more important than price.","zh-TW":"從長遠來看，品質比價格更重要。"},{"note":"反義詞：in the short run/term。"}]', 'prepositional phrase'),
('in the meantime', '在此期間；與此同時', 'during the time between two events', '[{"en":"The results won''t be ready until Friday. In the meantime, let''s prepare the presentation.","zh-TW":"結果要到週五才會出來。在此期間，讓我們準備簡報。"},{"en":"In the meantime, please review the attached documents.","zh-TW":"在此期間，請審閱附件文件。"},{"note":"同義詞：meanwhile, in the interim。"}]', 'prepositional phrase'),
('keep track of', '追蹤；記錄', 'to monitor or record information over time', '[{"en":"We use software to keep track of inventory.","zh-TW":"我們使用軟體來追蹤庫存。"},{"en":"It''s important to keep track of all expenses.","zh-TW":"追蹤所有開支很重要。"},{"note":"反義詞：lose track of。"}]', 'expression'),
('line of work', '行業；工作領域', 'a type of job or profession', '[{"en":"What line of work are you in?","zh-TW":"你從事什麼行業？"},{"en":"In this line of work, networking is essential.","zh-TW":"在這個行業中，人脈至關重要。"},{"note":"同義詞：field, industry, profession。"}]', 'expression'),
('make a reservation', '預約；預訂', 'to book or reserve in advance', '[{"en":"I''d like to make a reservation for six people.","zh-TW":"我想預訂六人的位子。"},{"en":"Please make a reservation at the hotel.","zh-TW":"請在飯店預訂房間。"},{"note":"同義詞：book, reserve。"}]', 'expression'),
('make ends meet', '收支平衡；勉強維持生計', 'to have just enough money to pay for necessities', '[{"en":"Many families struggle to make ends meet.","zh-TW":"許多家庭勉強維持收支平衡。"},{"en":"With rising costs, it''s harder to make ends meet.","zh-TW":"隨著成本上升，維持生計變得更困難。"},{"note":"描述財務困難的常用成語。"}]', 'business idiom'),
('on behalf of', '代表', 'as a representative of someone', '[{"en":"I''m writing on behalf of the management team.","zh-TW":"我代表管理團隊撰寫此信。"},{"en":"She accepted the award on behalf of the company.","zh-TW":"她代表公司接受了獎項。"},{"note":"正式用語，常見於商務信件和演講。"}]', 'prepositional phrase'),
('on the same page', '意見一致；有共識', 'having the same understanding or opinion', '[{"en":"Let''s make sure we''re all on the same page.","zh-TW":"讓我們確保大家都有共識。"},{"en":"Are we on the same page about the deadline?","zh-TW":"關於截止日期我們意見一致嗎？"},{"note":"常用於團隊協作和會議中。"}]', 'business idiom'),
('on time', '準時', 'at the scheduled or expected time', '[{"en":"The shipment arrived on time.","zh-TW":"貨物準時到達。"},{"en":"It''s important to always be on time for meetings.","zh-TW":"開會準時很重要。"},{"note":"on time（準時）vs. in time（及時）。"}]', 'prepositional phrase'),
('out of order', '故障；壞了', 'not functioning properly', '[{"en":"The elevator is out of order today.","zh-TW":"電梯今天故障了。"},{"en":"Sorry, the copier is out of order.","zh-TW":"抱歉，影印機壞了。"},{"note":"也可指「不合規矩」。"}]', 'expression'),
('out of stock', '缺貨', 'not available for purchase', '[{"en":"That item is temporarily out of stock.","zh-TW":"該商品暫時缺貨。"},{"en":"Popular products often go out of stock quickly.","zh-TW":"熱門產品通常很快就會缺貨。"},{"note":"反義詞：in stock。"}]', 'expression'),
('prior to', '在…之前', 'before a particular time or event', '[{"en":"Please review the agenda prior to the meeting.","zh-TW":"請在會議前審閱議程。"},{"en":"Prior to joining this company, she worked in finance.","zh-TW":"加入這家公司之前，她在金融業工作。"},{"note":"比 before 更正式。"}]', 'prepositional phrase'),
('pros and cons', '優缺點；利弊', 'the advantages and disadvantages', '[{"en":"Let''s weigh the pros and cons before deciding.","zh-TW":"讓我們在決定前權衡利弊。"},{"en":"There are pros and cons to both options.","zh-TW":"兩個選項都有優缺點。"},{"note":"同義詞：advantages and disadvantages。"}]', 'expression'),
('red tape', '繁文縟節；官僚程序', 'excessive bureaucracy or rules that delay action', '[{"en":"There''s too much red tape involved in getting a permit.","zh-TW":"取得許可證涉及太多繁文縟節。"},{"en":"We need to cut through the red tape to speed up the process.","zh-TW":"我們需要減少官僚程序以加快流程。"},{"note":"帶有負面含義，指不必要的行政障礙。"}]', 'business idiom'),
('regardless of', '不管；無論', 'without being affected by something', '[{"en":"All employees will be treated fairly regardless of gender.","zh-TW":"所有員工無論性別都將受到公平對待。"},{"en":"We''ll proceed regardless of the weather.","zh-TW":"無論天氣如何我們都會繼續進行。"},{"note":"同義詞：irrespective of, no matter。"}]', 'prepositional phrase'),
('run a business', '經營企業', 'to manage and operate a company', '[{"en":"She has been running her own business for ten years.","zh-TW":"她已經經營自己的企業十年了。"},{"en":"Running a business requires dedication and planning.","zh-TW":"經營企業需要奉獻精神和規劃。"},{"note":"同義詞：manage a company, operate a firm。"}]', 'expression'),
('state of the art', '最先進的；最新技術的', 'using the latest and most advanced technology', '[{"en":"Our factory uses state-of-the-art equipment.","zh-TW":"我們的工廠使用最先進的設備。"},{"en":"The new office features state-of-the-art technology.","zh-TW":"新辦公室配備了最先進的技術。"},{"note":"作形容詞時加連字號：state-of-the-art。"}]', 'expression'),
('take effect', '生效', 'to start to produce results or be enforced', '[{"en":"The price increase will take effect from next month.","zh-TW":"漲價將從下個月開始生效。"},{"en":"The new law takes effect immediately.","zh-TW":"新法律立即生效。"},{"note":"同義詞：come into effect, become effective。"}]', 'expression'),
('take measures', '採取措施', 'to take action to achieve something or solve a problem', '[{"en":"The government took measures to reduce pollution.","zh-TW":"政府採取了措施來減少污染。"},{"en":"We must take immediate measures to address this issue.","zh-TW":"我們必須立即採取措施來解決這個問題。"},{"note":"同義詞：take steps, take action。"}]', 'expression'),
('think outside the box', '跳脫框架思考', 'to think creatively and unconventionally', '[{"en":"We need to think outside the box to solve this problem.","zh-TW":"我們需要跳脫框架思考來解決這個問題。"},{"en":"The company encourages employees to think outside the box.","zh-TW":"公司鼓勵員工創新思考。"},{"note":"指創意思維、不受傳統限制。"}]', 'business idiom'),
('touch base', '聯繫；碰面討論', 'to briefly make or renew contact with someone', '[{"en":"Let''s touch base next week to discuss progress.","zh-TW":"下週我們碰面討論進度。"},{"en":"I just wanted to touch base with you about the project.","zh-TW":"我只是想跟你聯繫一下關於這個專案的事。"},{"note":"常用於工作中的簡短溝通。"}]', 'business idiom'),
('up to date', '最新的；更新的', 'having the latest information or version', '[{"en":"Make sure your software is up to date.","zh-TW":"確保你的軟體是最新的。"},{"en":"I''ll keep you up to date on any changes.","zh-TW":"有任何變動我會讓你保持最新資訊。"},{"note":"作形容詞時加連字號：up-to-date。反義：out of date。"}]', 'expression'),
('with regard to', '關於；有關', 'concerning; about a particular subject', '[{"en":"With regard to your request, we''ll get back to you shortly.","zh-TW":"關於您的要求，我們會盡快回覆您。"},{"en":"With regard to the budget, we need to make some cuts.","zh-TW":"關於預算，我們需要做一些削減。"},{"note":"同義詞：regarding, concerning, with respect to。正式用語。"}]', 'prepositional phrase'),
('year-round', '全年的', 'happening or available throughout the year', '[{"en":"The resort offers year-round activities.","zh-TW":"度假村提供全年活動。"},{"en":"We provide year-round customer support.","zh-TW":"我們提供全年客戶支援。"},{"note":"也可寫作 all year round。"}]', 'expression'),
('as soon as possible', '盡快', 'at the earliest opportunity', '[{"en":"Please respond as soon as possible.","zh-TW":"請盡快回覆。"},{"en":"We need to resolve this issue as soon as possible.","zh-TW":"我們需要盡快解決這個問題。"},{"note":"縮寫 ASAP 在商務溝通中非常常見。"}]', 'expression'),
('bear in mind', '記住；牢記', 'to remember or consider something', '[{"en":"Bear in mind that the deadline is next Friday.","zh-TW":"請記住截止日期是下週五。"},{"en":"We should bear in mind the budget constraints.","zh-TW":"我們應該牢記預算限制。"},{"note":"同義詞：keep in mind, remember。"}]', 'expression'),
('branch out', '擴展業務；涉足新領域', 'to expand into new areas or activities', '[{"en":"The company plans to branch out into Asia.","zh-TW":"公司計劃將業務擴展到亞洲。"},{"en":"We''re branching out into renewable energy.","zh-TW":"我們正在涉足再生能源領域。"},{"note":"同義詞：diversify, expand。"}]', 'phrasal verb'),
('brush up on', '複習；溫習', 'to review or improve a skill that has been neglected', '[{"en":"I need to brush up on my Excel skills.","zh-TW":"我需要溫習一下Excel技能。"},{"en":"She brushed up on her French before the business trip.","zh-TW":"出差前她溫習了法語。"},{"note":"常用於重新學習生疏的技能。"}]', 'phrasal verb'),
('burn out', '精疲力竭；過勞', 'to become exhausted from overwork', '[{"en":"Many employees burn out from excessive overtime.","zh-TW":"許多員工因過度加班而精疲力竭。"},{"en":"We need to prevent team burnout.","zh-TW":"我們需要防止團隊過勞。"},{"note":"名詞 burnout 指職業倦怠。"}]', 'phrasal verb'),
('carry on', '繼續進行', 'to continue doing something', '[{"en":"Let''s carry on with the discussion.","zh-TW":"讓我們繼續討論。"},{"en":"Please carry on while I take this call.","zh-TW":"我接這個電話時請繼續。"},{"note":"同義詞：continue, proceed, go on。"}]', 'phrasal verb'),
('come to terms with', '接受；妥協', 'to accept a difficult situation', '[{"en":"The company had to come to terms with declining sales.","zh-TW":"公司不得不接受銷售額下降的現實。"},{"en":"We need to come to terms with the new regulations.","zh-TW":"我們需要接受新的法規。"},{"note":"也可指「達成協議」。"}]', 'expression'),
('comply with', '遵守；符合', 'to act in accordance with rules or requests', '[{"en":"All vendors must comply with our safety standards.","zh-TW":"所有供應商必須遵守我們的安全標準。"},{"en":"Failure to comply with regulations will result in fines.","zh-TW":"不遵守法規將導致罰款。"},{"note":"名詞：compliance。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('consist of', '由…組成', 'to be made up of particular parts', '[{"en":"The committee consists of ten members.","zh-TW":"委員會由十名成員組成。"},{"en":"The training program consists of three modules.","zh-TW":"培訓計劃由三個模組組成。"},{"note":"不用被動語態，不說 is consisted of。"}]', 'phrasal verb'),
('cope with', '應對；處理', 'to deal with a difficult situation successfully', '[{"en":"How do you cope with work-related stress?","zh-TW":"你如何應對工作壓力？"},{"en":"The system can''t cope with the increased demand.","zh-TW":"系統無法應對增加的需求。"},{"note":"同義詞：deal with, handle, manage。"}]', 'phrasal verb'),
('for the time being', '暫時；目前', 'for now; temporarily', '[{"en":"For the time being, we''ll keep the current system.","zh-TW":"暫時，我們會維持現有系統。"},{"en":"Let''s leave this for the time being.","zh-TW":"我們暫時先放下這個。"},{"note":"同義詞：for now, temporarily, in the meantime。"}]', 'expression'),
('gain ground', '取得進展；擴大優勢', 'to become more popular or successful', '[{"en":"Our product is gaining ground in the Asian market.","zh-TW":"我們的產品在亞洲市場取得進展。"},{"en":"The startup is gaining ground on established competitors.","zh-TW":"這家新創正在縮小與老牌競爭對手的差距。"},{"note":"反義詞：lose ground。"}]', 'business idiom'),
('get down to', '開始認真做', 'to start to give serious attention to something', '[{"en":"Let''s get down to business.","zh-TW":"讓我們言歸正傳。"},{"en":"We need to get down to the details of the contract.","zh-TW":"我們需要開始認真討論合約細節。"},{"note":"get down to business 是非常常見的商務用語。"}]', 'phrasal verb'),
('give notice', '發出通知；提出辭職', 'to formally inform of departure or action', '[{"en":"He gave two weeks'' notice before leaving.","zh-TW":"他在離職前兩週提出了辭呈。"},{"en":"Please give us advance notice of any changes.","zh-TW":"請提前通知我們任何變更。"},{"note":"resignation notice 指辭職通知。"}]', 'expression'),
('go into detail', '詳細說明', 'to explain something thoroughly', '[{"en":"I won''t go into detail here, but the results are promising.","zh-TW":"我在這裡不詳細說明，但結果很有希望。"},{"en":"Could you go into more detail about the budget?","zh-TW":"你能更詳細地說明預算嗎？"},{"note":"同義詞：elaborate, explain in detail。"}]', 'expression'),
('hold up', '延誤；阻礙；支撐', 'to delay or remain strong', '[{"en":"The shipment was held up at customs.","zh-TW":"貨物在海關被耽擱了。"},{"en":"How are sales holding up this quarter?","zh-TW":"這季度銷售表現如何？"},{"note":"名詞 holdup 指延誤或障礙。"}]', 'phrasal verb'),
('iron out', '解決（問題）；消除（分歧）', 'to resolve problems or smooth out difficulties', '[{"en":"We still need to iron out a few details.","zh-TW":"我們還需要解決一些細節問題。"},{"en":"The two parties met to iron out their differences.","zh-TW":"雙方會面以消除分歧。"},{"note":"同義詞：resolve, work out, sort out。"}]', 'phrasal verb'),
('kick off', '開始；啟動', 'to begin or start an event or project', '[{"en":"We''ll kick off the new project next Monday.","zh-TW":"我們下週一啟動新專案。"},{"en":"The sales campaign kicks off in September.","zh-TW":"銷售活動在九月啟動。"},{"note":"名詞 kickoff 指啟動會議或開始。"}]', 'phrasal verb'),
('level off', '趨於平穩', 'to stop increasing or decreasing', '[{"en":"Sales growth has leveled off this quarter.","zh-TW":"本季度銷售增長已趨於平穩。"},{"en":"Housing prices are expected to level off.","zh-TW":"房價預計將趨於平穩。"},{"note":"常用於描述圖表趨勢。"}]', 'phrasal verb'),
('live up to', '符合；達到（期望）', 'to meet expectations or standards', '[{"en":"The product didn''t live up to customer expectations.","zh-TW":"產品未能達到客戶期望。"},{"en":"We strive to live up to our reputation for quality.","zh-TW":"我們努力達到我們的品質聲譽。"},{"note":"常用於討論品質或表現。"}]', 'phrasal verb'),
('phase out', '逐步淘汰', 'to gradually stop using or producing something', '[{"en":"The company is phasing out its older product line.","zh-TW":"公司正在逐步淘汰舊產品線。"},{"en":"Plastic bags will be phased out by next year.","zh-TW":"塑膠袋將在明年前逐步淘汰。"},{"note":"反義詞：phase in（逐步引入）。"}]', 'phrasal verb'),
('pull off', '成功完成（困難的事）', 'to succeed in doing something difficult', '[{"en":"They managed to pull off the deal despite the challenges.","zh-TW":"儘管面臨挑戰，他們還是成功達成了交易。"},{"en":"Can we pull off the launch in two weeks?","zh-TW":"我們能在兩週內成功推出嗎？"},{"note":"暗示完成的事具有挑戰性。"}]', 'phrasal verb'),
('rule out', '排除', 'to decide that something is not possible', '[{"en":"We can''t rule out the possibility of a delay.","zh-TW":"我們不能排除延遲的可能性。"},{"en":"The board ruled out the merger option.","zh-TW":"董事會排除了合併選項。"},{"note":"同義詞：exclude, eliminate, discount。"}]', 'phrasal verb'),
('scale up', '擴大規模', 'to increase the size or amount of something', '[{"en":"We need to scale up production to meet demand.","zh-TW":"我們需要擴大生產以滿足需求。"},{"en":"The startup is ready to scale up its operations.","zh-TW":"這家新創已準備好擴大營運規模。"},{"note":"反義詞：scale down。"}]', 'phrasal verb'),
('settle for', '勉強接受', 'to accept something less than what you wanted', '[{"en":"Don''t settle for second best.","zh-TW":"不要勉強接受次等品。"},{"en":"We had to settle for a later delivery date.","zh-TW":"我們不得不接受較晚的交貨日期。"},{"note":"暗示妥協或退讓。"}]', 'phrasal verb'),
('shut down', '關閉；停業', 'to close a business or stop operating', '[{"en":"The factory was shut down due to safety violations.","zh-TW":"工廠因安全違規而被關閉。"},{"en":"Several stores will shut down by year-end.","zh-TW":"幾家門市將在年底前關閉。"},{"note":"名詞 shutdown 指停工或關閉。"}]', 'phrasal verb'),
('speed up', '加速', 'to make something happen faster', '[{"en":"We need to speed up the approval process.","zh-TW":"我們需要加快審批流程。"},{"en":"New technology will speed up production.","zh-TW":"新技術將加快生產速度。"},{"note":"反義詞：slow down。"}]', 'phrasal verb'),
('stand out', '突出；脫穎而出', 'to be noticeably better or different', '[{"en":"What makes your product stand out from the competition?","zh-TW":"什麼讓你的產品從競爭中脫穎而出？"},{"en":"Her resume really stood out among the applicants.","zh-TW":"她的履歷在申請者中真的很突出。"},{"note":"常用於行銷和求職情境。"}]', 'phrasal verb'),
('stem from', '源於；起因於', 'to be caused by or originate from', '[{"en":"The delay stems from a shortage of materials.","zh-TW":"延誤源於材料短缺。"},{"en":"Most complaints stem from poor communication.","zh-TW":"大多數投訴源於溝通不良。"},{"note":"同義詞：result from, arise from, originate from。"}]', 'phrasal verb'),
('stick to', '堅持；遵守', 'to continue doing something or follow a plan', '[{"en":"We need to stick to the original budget.","zh-TW":"我們需要堅持原來的預算。"},{"en":"Let''s stick to the agenda.","zh-TW":"讓我們遵循議程。"},{"note":"同義詞：adhere to, follow, abide by。"}]', 'phrasal verb'),
('weigh up', '權衡；評估', 'to consider the advantages and disadvantages', '[{"en":"We need to weigh up the risks and benefits.","zh-TW":"我們需要權衡風險和收益。"},{"en":"Take some time to weigh up your options.","zh-TW":"花些時間權衡你的選項。"},{"note":"同義詞：evaluate, assess, consider。"}]', 'phrasal verb'),
('wind down', '逐漸結束；放鬆', 'to gradually end or relax', '[{"en":"The company is winding down its overseas operations.","zh-TW":"公司正在逐漸結束其海外業務。"},{"en":"The project will wind down by end of quarter.","zh-TW":"專案將在季末逐漸結束。"},{"note":"反義詞：ramp up。"}]', 'phrasal verb'),
('write off', '勾銷；報廢', 'to cancel a debt or accept a loss', '[{"en":"The bank wrote off $2 million in bad debt.","zh-TW":"銀行勾銷了200萬美元的壞帳。"},{"en":"We had to write off the damaged equipment.","zh-TW":"我們不得不將損壞的設備報廢。"},{"note":"名詞 write-off 指勾銷或報廢品。"}]', 'phrasal verb'),
('abide by', '遵守', 'to follow or accept a rule, decision, or agreement', '[{"en":"All parties must abide by the terms of the contract.","zh-TW":"各方必須遵守合約條款。"},{"en":"Employees are expected to abide by company policies.","zh-TW":"員工應遵守公司政策。"},{"note":"同義詞：comply with, adhere to, follow。"}]', 'phrasal verb'),
('amount to', '總計；等同於', 'to total or be equivalent to', '[{"en":"Total expenses amount to $50,000.","zh-TW":"總費用達到5萬美元。"},{"en":"His contribution didn''t amount to much.","zh-TW":"他的貢獻不算多。"},{"note":"也可表示「等同於」（amount to failure）。"}]', 'phrasal verb'),
('attend to', '處理；照料', 'to deal with or give attention to', '[{"en":"I have some urgent matters to attend to.","zh-TW":"我有一些緊急事務要處理。"},{"en":"A staff member will attend to your needs.","zh-TW":"一位工作人員會照料您的需求。"},{"note":"正式用法，同義詞：take care of, deal with。"}]', 'phrasal verb'),
('boil down to', '歸結為', 'to be summarized as the most important point', '[{"en":"It all boils down to cost.","zh-TW":"歸根結底就是成本問題。"},{"en":"The decision boils down to quality versus price.","zh-TW":"這個決定歸結為品質與價格的取捨。"},{"note":"用於總結核心問題。"}]', 'phrasal verb'),
('build up', '建立；逐漸增加', 'to gradually increase or develop', '[{"en":"It takes years to build up a good reputation.","zh-TW":"建立良好聲譽需要多年時間。"},{"en":"We''ve built up a loyal customer base.","zh-TW":"我們已建立了忠實的客戶群。"},{"note":"名詞 buildup 指積累或增長。"}]', 'phrasal verb'),
('call for', '要求；需要', 'to require or demand something', '[{"en":"The situation calls for immediate action.","zh-TW":"形勢需要立即採取行動。"},{"en":"This calls for a celebration!","zh-TW":"這值得慶祝一下！"},{"note":"同義詞：require, demand, necessitate。"}]', 'phrasal verb'),
('cater to', '迎合；滿足需求', 'to provide what someone needs or wants', '[{"en":"Our services cater to small and medium businesses.","zh-TW":"我們的服務面向中小企業。"},{"en":"The hotel caters to business travelers.","zh-TW":"這家飯店面向商務旅客。"},{"note":"同義詞：serve, accommodate。"}]', 'phrasal verb'),
('on account of', '因為；由於', 'because of a particular reason', '[{"en":"The event was postponed on account of rain.","zh-TW":"活動因雨延期。"},{"en":"On account of the merger, some positions will be eliminated.","zh-TW":"由於合併，一些職位將被裁撤。"},{"note":"較正式，同義詞：due to, because of。"}]', 'prepositional phrase'),
('as a result', '因此；結果', 'because of something that has happened', '[{"en":"Sales dropped 20%. As a result, layoffs were announced.","zh-TW":"銷售下降20%。因此宣佈了裁員。"},{"en":"We invested in training. As a result, productivity improved.","zh-TW":"我們投資了培訓。因此生產力提高了。"},{"note":"同義詞：consequently, therefore, hence。"}]', 'expression'),
('as of', '自…起；截至', 'starting from a particular date or time', '[{"en":"As of January 1st, the new policy will be in effect.","zh-TW":"自1月1日起，新政策將生效。"},{"en":"As of today, we have received 300 applications.","zh-TW":"截至今天，我們已收到300份申請。"},{"note":"常用於標明生效日期。"}]', 'prepositional phrase'),
('aside from', '除了…之外', 'in addition to; except for', '[{"en":"Aside from the cost, the plan is excellent.","zh-TW":"除了成本之外，這個計劃非常好。"},{"en":"Aside from English, she speaks three other languages.","zh-TW":"除了英語，她還會說另外三種語言。"},{"note":"同義詞：apart from, besides, in addition to。"}]', 'prepositional phrase'),
('provided that', '只要；假如', 'on the condition that; if', '[{"en":"We''ll approve the loan provided that you meet the requirements.","zh-TW":"只要您符合要求，我們就會批准貸款。"},{"en":"You may leave early provided that you finish your work.","zh-TW":"只要你完成工作就可以早走。"},{"note":"同義詞：as long as, on condition that。"}]', 'expression'),
('result in', '導致', 'to cause a particular outcome', '[{"en":"The merger resulted in significant cost savings.","zh-TW":"合併導致了顯著的成本節約。"},{"en":"Poor planning can result in project failure.","zh-TW":"計劃不當可能導致專案失敗。"},{"note":"同義詞：lead to, cause, bring about。result from 指「起因於」。"}]', 'phrasal verb'),
('with respect to', '關於；就…而言', 'regarding; concerning', '[{"en":"With respect to your proposal, we have a few concerns.","zh-TW":"關於您的提案，我們有一些疑慮。"},{"en":"No changes will be made with respect to pricing.","zh-TW":"定價方面不會有任何變動。"},{"note":"非常正式，同義詞：regarding, concerning, with regard to。"}]', 'prepositional phrase'),
('according to', '根據；按照', 'as stated by a source or in accordance with', '[{"en":"According to the report, profits increased by 15%.","zh-TW":"根據報告，利潤增加了15%。"},{"en":"Everything is proceeding according to plan.","zh-TW":"一切按計劃進行中。"},{"note":"後接名詞，不接 me（用 in my opinion 代替）。"}]', 'prepositional phrase'),
('ahead of', '在…之前；領先', 'before the expected time or in front of', '[{"en":"The project was completed ahead of schedule.","zh-TW":"專案提前完成了。"},{"en":"We''re ahead of our competitors in innovation.","zh-TW":"我們在創新方面領先競爭對手。"},{"note":"反義詞：behind schedule。"}]', 'prepositional phrase'),
('ramp up', '增加；加大力度', 'to increase or intensify activity', '[{"en":"We''re ramping up production for the holiday season.","zh-TW":"我們正在為假期旺季加大產量。"},{"en":"The company ramped up its marketing efforts.","zh-TW":"公司加大了行銷力度。"},{"note":"反義詞：wind down, scale down。"}]', 'phrasal verb'),
('roll out', '推出；發佈', 'to launch or introduce a new product or service', '[{"en":"The company rolled out its new mobile app last week.","zh-TW":"公司上週推出了新的手機應用程式。"},{"en":"We plan to roll out the update in phases.","zh-TW":"我們計劃分階段推出更新。"},{"note":"名詞 rollout 指產品發佈。"}]', 'phrasal verb'),
('tighten up', '加強；使更嚴格', 'to make rules or controls more strict', '[{"en":"We need to tighten up our security procedures.","zh-TW":"我們需要加強安全程序。"},{"en":"The budget has been tightened up considerably.","zh-TW":"預算已經大幅緊縮。"},{"note":"同義詞：strengthen, reinforce。"}]', 'phrasal verb'),
('on a regular basis', '定期地', 'regularly; at consistent intervals', '[{"en":"Team meetings are held on a regular basis.","zh-TW":"團隊會議定期舉行。"},{"en":"We review performance on a quarterly basis.","zh-TW":"我們每季度審查績效。"},{"note":"同義詞：regularly, periodically, routinely。"}]', 'expression'),
('take into consideration', '考慮；納入考量', 'to think carefully about something when making decisions', '[{"en":"Please take our budget constraints into consideration.","zh-TW":"請考慮我們的預算限制。"},{"en":"All feedback will be taken into consideration.","zh-TW":"所有回饋都會被納入考量。"},{"note":"同義詞：take into account, consider。"}]', 'expression'),
('at stake', '處於危險中；攸關', 'at risk; in danger of being lost', '[{"en":"Millions of dollars are at stake.","zh-TW":"數百萬美元面臨風險。"},{"en":"Our reputation is at stake.","zh-TW":"我們的聲譽攸關。"},{"note":"強調事態的嚴重性。"}]', 'expression'),
('at all costs', '不惜一切代價', 'regardless of the price or effort required', '[{"en":"We must avoid a data breach at all costs.","zh-TW":"我們必須不惜一切代價避免數據洩露。"},{"en":"Customer trust must be maintained at all costs.","zh-TW":"必須不惜一切代價維護客戶信任。"},{"note":"表示極度重視某事。"}]', 'expression'),
('for good', '永遠地', 'permanently; forever', '[{"en":"The factory closed for good last year.","zh-TW":"工廠去年永久關閉了。"},{"en":"He left the company for good.","zh-TW":"他永遠離開了公司。"},{"note":"同義詞：permanently, for ever。"}]', 'expression'),
('in person', '親自；本人', 'physically present rather than by phone or online', '[{"en":"You need to apply in person at the office.","zh-TW":"你需要親自到辦公室申請。"},{"en":"I''d prefer to discuss this in person.","zh-TW":"我比較想當面討論這件事。"},{"note":"反義詞：remotely, online, virtually。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('on the whole', '整體而言', 'considering everything; generally', '[{"en":"On the whole, the project was a success.","zh-TW":"整體而言，這個專案是成功的。"},{"en":"On the whole, employees are satisfied with the changes.","zh-TW":"整體而言，員工對變動感到滿意。"},{"note":"同義詞：overall, generally, all things considered。"}]', 'expression'),
('to a great extent', '在很大程度上', 'to a large degree', '[{"en":"Success depends to a great extent on teamwork.","zh-TW":"成功在很大程度上取決於團隊合作。"},{"en":"To a certain extent, I agree with you.","zh-TW":"在某種程度上，我同意你的看法。"},{"note":"程度可替換：great, large, certain, some。"}]', 'expression'),
('go out of one''s way', '特意；不辭辛苦', 'to make a special effort beyond what is expected', '[{"en":"She went out of her way to help the new employee.","zh-TW":"她特意幫助新員工。"},{"en":"The staff went out of their way to accommodate our requests.","zh-TW":"工作人員特意配合我們的要求。"},{"note":"表示超越本分的努力。"}]', 'business idiom'),
('from time to time', '偶爾；不時', 'occasionally; sometimes', '[{"en":"We review our policies from time to time.","zh-TW":"我們不時審查我們的政策。"},{"en":"Issues arise from time to time.","zh-TW":"問題偶爾會出現。"},{"note":"同義詞：occasionally, now and then, once in a while。"}]', 'expression'),
('bring back', '恢復；帶回', 'to restore or return something', '[{"en":"The promotion helped bring back lapsed customers.","zh-TW":"促销幫助將休眠客戶招回。"},{"en":"We brought back the popular product due to demand.","zh-TW":"由於需求我們從新推出了這個受歡迎的產品。"}]', 'phrasal verb'),
('miss out on', '錯過；失去機會', 'to fail to take advantage of something', '[{"en":"Do not miss out on this limited-time offer.","zh-TW":"不要錯過這個限時優惠。"},{"en":"She missed out on a great investment opportunity.","zh-TW":"她錯過了一個很好的投資機會。"}]', 'phrasal verb'),
('talk into', '勸說；說服…做某事', 'to persuade someone to do something', '[{"en":"The sales rep talked the client into upgrading the plan.","zh-TW":"業務代表說服客戶升級了方案。"},{"en":"She talked him into signing the contract early.","zh-TW":"她說服他提前簽署了合約。"}]', 'phrasal verb'),
('talk out of', '勸阻；說服不要做', 'to persuade someone not to do something', '[{"en":"She talked him out of making a hasty decision.","zh-TW":"她勸阻了他草率做出決定。"},{"en":"The advisor talked the investor out of a risky move.","zh-TW":"顧問勸阻投資者不要走高風險步驟。"}]', 'phrasal verb'),
('follow suit', '跟進；級繼随之', 'to follow the example of someone else', '[{"en":"After the market leader raised prices competitors followed suit.","zh-TW":"市場領導者提價後，競爭者也級繼跟進。"},{"en":"Other regions followed suit in adopting the new policy.","zh-TW":"其他地區也級繼採用了這項新政策。"}]', 'phrasal verb'),
('give away', '赈送；直接送出', 'to give for free or unintentionally reveal', '[{"en":"We give away free samples at trade shows.","zh-TW":"我們在展覽會發散免費樣品。"},{"en":"She gave away the surprise announcement by mistake.","zh-TW":"她不小心泄露了驚喜公告。"}]', 'phrasal verb'),
('trade in', '以舊換新；易貨', 'to exchange old for new or conduct trade', '[{"en":"Customers can trade in their old device for a discount.","zh-TW":"客戶可用舊機换取折扣。"},{"en":"He traded in his old laptop for the latest model.","zh-TW":"他將舊筆電易換為最新機型。"}]', 'phrasal verb'),
('hook up', '連接；安排指引', 'to connect or arrange access', '[{"en":"Let me hook you up with our product specialist.","zh-TW":"讓我為您安排我們的產品專家。"},{"en":"The technician hooked up the new equipment.","zh-TW":"技術人員連接安裝了新設備。"}]', 'phrasal verb'),
('push for', '主張；推動通過', 'to advocate strongly for something', '[{"en":"She pushed for faster approval of the proposal.","zh-TW":"她主張儘快批准該提案。"},{"en":"Management is pushing for higher productivity targets.","zh-TW":"管理層正在主張提高產能目標。"}]', 'phrasal verb'),
('win over', '爐服；諦導支持', 'to persuade or gain support from someone', '[{"en":"The presentation won over even the most skeptical investors.","zh-TW":"簡報諦服了甚至最多疑的投資者。"},{"en":"She won over the client with her detailed proposal.","zh-TW":"她用詳細的提案爐服了客戶。"}]', 'phrasal verb'),
('back off', '退讓；放棄创署', 'to withdraw or reduce pressure', '[{"en":"They backed off from their initial demands in the negotiation.","zh-TW":"在談判中他們退讓了最初的要求。"},{"en":"The supplier backed off when we threatened to switch.","zh-TW":"當我們表示要更換供應商時對方退讓了。"}]', 'phrasal verb'),
('trade up', '升級購買；買更好的', 'to buy a more expensive or better version of something', '[{"en":"Many customers trade up to the premium plan after trial.","zh-TW":"許多客戶在試用後升級至高階方案。"},{"en":"They traded up to a larger office as the team grew.","zh-TW":"隨著團隊成長他們升級到更大的辦公室。"}]', 'phrasal verb'),
('price out', '將…陀出市場；定價過高', 'to force out of the market by high prices', '[{"en":"High costs are pricing our product out of the mass market.","zh-TW":"高成本正將我們的產品陀出大眾市場。"},{"en":"The retailer priced out small buyers with minimum orders.","zh-TW":"零售商用最小訂單量陀駈了小型買家。"}]', 'phrasal verb'),
('hunt down', '搜尋；追蹤到底', 'to search for and find with great effort', '[{"en":"She hunted down the contact information we needed.","zh-TW":"她搜尋到了我們需要的聯絡資訊。"},{"en":"The analyst hunted down the missing data from archives.","zh-TW":"分析師從檔案中搜尋到了遺失的資料。"}]', 'phrasal verb'),
('deal in', '經營；從事交易', 'to trade in a particular type of goods', '[{"en":"They deal in high-end electronics and accessories.","zh-TW":"他們經營高檔電子產品及配件。"},{"en":"The broker deals in foreign exchange.","zh-TW":"這位中介從事外匯交易。"}]', 'phrasal verb'),
('talk through', '詳細討論；引導討論', 'to discuss in detail or guide through a process', '[{"en":"Let me talk you through the proposal step by step.","zh-TW":"讓我引導你一步一步討論該提案。"},{"en":"They talked through all possible scenarios before deciding.","zh-TW":"他們在決定前詳細討論了所有可能的情境。"}]', 'phrasal verb'),
('fend off', '擋尚；抵御', 'to defend against or ward off', '[{"en":"The company fended off a hostile takeover bid.","zh-TW":"公司抵御了一等恶意收購要符。"},{"en":"They fended off cheaper competitors by focusing on quality.","zh-TW":"他們通過專注品質來擋尚偶价競爭者。"}]', 'phrasal verb'),
('set apart', '使脱穎而出；區別', 'to make noticeably different from others', '[{"en":"Strong customer service sets our brand apart.","zh-TW":"出色的客戶服務讓我們的品牌脱穎而出。"},{"en":"What sets you apart from other candidates?","zh-TW":"是什麼讓你千利其中？"}]', 'phrasal verb'),
('a win-win situation', '雙贏局面；兩方都有利', 'a situation where all parties benefit', '[{"en":"The partnership is a win-win for both companies.","zh-TW":"這次合夸對兩家公司來說是雙贏局面。"},{"en":"This deal is structured as a win-win situation.","zh-TW":"這次交易被設計為雙贏局面。"}]', 'expression'),
('as a last resort', '万不得已的為下；最後手段', 'used only when all other options have failed', '[{"en":"As a last resort we will take the matter to court.","zh-TW":"万不得已的為下我們將提諏訟諸。"},{"en":"Layoffs are a last resort when other cost cuts fail.","zh-TW":"在其他成本削減失敗後，裁員是最後手段。"}]', 'expression'),
('drive a hard bargain', '挑刺的屣价者；難以奉承', 'to negotiate firmly and aggressively to get the best deal', '[{"en":"She drives a hard bargain but always seals the deal.","zh-TW":"她談判阻力很對不過這也讓她周山門就範。"},{"en":"The client drives a hard bargain every contract renewal.","zh-TW":"客戶每次合約續約都挑刺尺度議價。"}]', 'expression'),
('in the works', '在計劃中；尚在為處理中', 'being planned or prepared', '[{"en":"We have a major update in the works for Q4.","zh-TW":"我們為第四季在專層評辭一個重大更新。"},{"en":"There are several new hires in the works.","zh-TW":"目前有幾筆新招聘正在進行中。"}]', 'expression'),
('give someone the benefit of the doubt', '姓呪不知；實雙贏無疑；先信任對方', 'to trust someone even when unsure', '[{"en":"Let us give him the benefit of the doubt on this issue.","zh-TW":"在這個問題上讓我們先信任他。"},{"en":"We gave the vendor the benefit of the doubt on delivery.","zh-TW":"在交貨問題上我們先信任供應商。"}]', 'expression'),
('get down to business', '開始討論正题；隱入正願', 'to start dealing with the main matter at hand', '[{"en":"Let us get down to business and discuss the proposal.","zh-TW":"讓我們開始討論正题，審視該提案。"},{"en":"After the pleasantries they got down to business quickly.","zh-TW":"客套話說完後他們就隱入正题了。"}]', 'expression'),
('par for the course', '與預期相符；理所當然', 'what is normal or expected in a given situation', '[{"en":"Tight deadlines are par for the course in consulting.","zh-TW":"在訮詢業中緊迫的截止日期是常態。"},{"en":"A few bugs at launch are par for the course.","zh-TW":"上市時第一點程序小題是常態。"}]', 'expression'),
('get the most out of', '充分利用；最大化效益', 'to maximize benefit from something', '[{"en":"How do we get the most out of our existing talent?","zh-TW":"我們如何充分利用現有人才？"},{"en":"She gets the most out of her team through clear communication.","zh-TW":"她透過清晰溝通与團隊最大化產效。"}]', 'expression'),
('in due course', '屆時；屆後在適當時機', 'at the appropriate time in the future', '[{"en":"All applications will be reviewed in due course.","zh-TW":"所有申請將屆後審評。"},{"en":"The refund will be processed in due course.","zh-TW":"退款將會在適當時機處理。"}]', 'expression'),
('pour cold water on', '潑湿气气；打击熱情', 'to discourage or criticize an idea', '[{"en":"Do not pour cold water on their enthusiasm.","zh-TW":"不要潑湿他們的熱情。"},{"en":"She poured cold water on the expansion plan.","zh-TW":"她潑湿了擴展計劃的熱情。"}]', 'business idiom'),
('learn the ropes', '學習基本診討；入門', 'to learn the basics of a job or task', '[{"en":"It took him three months to learn the ropes.","zh-TW":"他花了三個月學會了基本工作診討。"},{"en":"She learned the ropes quickly and was promoted within a year.","zh-TW":"她很快就學會了診討，一年內就被升職了。"}]', 'business idiom'),
('know the ropes', '知道診討；經驗豐富', 'to be familiar with how a job or system works', '[{"en":"He knows the ropes of government contracting.","zh-TW":"他熟悉政府合同的診討。"},{"en":"We need someone who already knows the ropes.","zh-TW":"我們需要一個已熟知診討的人。"}]', 'business idiom'),
('change of pace', '改變節奏；變化', 'a shift in activity to break the routine', '[{"en":"The offsite retreat was a welcome change of pace.","zh-TW":"外勤逓修是一個受歡迎的變化。"},{"en":"Working on a new project was a change of pace.","zh-TW":"處理新專案是一種節奏變化。"}]', 'business idiom'),
('a sticking point', '紾級不決的點；難點', 'an issue that prevents progress in negotiations', '[{"en":"Pricing remains a sticking point in the deal.","zh-TW":"定價仍是這次交易中紾級不決的點。"},{"en":"The warranty terms were a sticking point.","zh-TW":"保證條款是連點。"}]', 'business idiom'),
('run a tight ship', '紀律嚴明；紀律嚴格', 'to manage an organization with strict discipline', '[{"en":"She runs a tight ship and all deadlines are met.","zh-TW":"她管理嚴格，所有截止日期一律遵守。"},{"en":"The finance department runs a tight ship with expenses.","zh-TW":"財務部門對支出管控嚴格。"}]', 'business idiom'),
('a tough nut to crack', '難以對付的人事物；難题', 'a difficult problem or person to deal with', '[{"en":"This client is a tough nut to crack in sales.","zh-TW":"這個客戶在銷售上很難對付。"},{"en":"The regulatory environment is a tough nut to crack.","zh-TW":"监管環境很難應對。"}]', 'business idiom'),
('in the driving seat', '握控主動權；居主導地位', 'in control and making key decisions', '[{"en":"After the restructuring she is firmly in the driving seat.","zh-TW":"重組後她穩穩捺揧大局。"},{"en":"We put our clients in the driving seat of their campaign.","zh-TW":"我們讓客戶主導自己的行銷活動。"}]', 'business idiom'),
('get a handle on', '摸清狀況；控制', 'to understand or take control of a situation', '[{"en":"We need to get a handle on the cost overruns.","zh-TW":"我們需要摸清成本超支的情況。"},{"en":"She got a handle on the project risks in her first week.","zh-TW":"她在第一週就摸清了專案風險。"}]', 'business idiom'),
('leave no stone unturned', '穵沒遙漏；尤陥不漏', 'to do everything possible to achieve a result', '[{"en":"We left no stone unturned in the due diligence process.","zh-TW":"我們在尥審過程中穵沒遙漏。"},{"en":"She left no stone unturned in her search for investors.","zh-TW":"她在尋找投資者時穵沒遙漏。"}]', 'business idiom'),
('take stock', '評估情況；盤點', 'to review and assess a situation', '[{"en":"After a year let us take stock of our achievements.","zh-TW":"一年後讓我們盤點我們的成就。"},{"en":"She took stock of her career and decided to change direction.","zh-TW":"她評估自己的職業後決定改變方向。"}]', 'phrasal verb'),
('drum up', '拼命裕招；機助', 'to generate or seek out actively', '[{"en":"We need to drum up more interest in the product.","zh-TW":"我們需要裕招更多人對這個產品的興趣。"},{"en":"She drummed up support for the initiative across departments.","zh-TW":"她在各部門裕招對該計劃的支持。"}]', 'phrasal verb'),
('come through', '成功完成；通過審核', 'to succeed or survive a difficulty', '[{"en":"She always comes through when the team needs her.","zh-TW":"團隊需要時她總是成功層現。"},{"en":"The proposal finally came through after three revisions.","zh-TW":"提案在三次修改後終於通過了。"}]', 'phrasal verb'),
('pin down', '確定；沂定準確細節', 'to fix or determine something precisely', '[{"en":"Can we pin down the exact delivery date?","zh-TW":"我們能確定準確的交貨日期嗎？"},{"en":"She pinned down the cause of the technical issue.","zh-TW":"她查出了技術問題的根本原因。"}]', 'phrasal verb'),
('check in on', '小查一下；確認進度', 'to check how someone is doing or progress of a task', '[{"en":"I will check in on the team mid-week.","zh-TW":"我會對團隊進行期中的進度檢查。"},{"en":"The manager checks in on all projects daily.","zh-TW":"經理每天檢查所有專案的進度。"}]', 'phrasal verb'),
('pile up', '堆積；越益增多', 'to accumulate in large amounts', '[{"en":"Work piled up while she was on leave.","zh-TW":"她請假期間工作不斷堆積。"},{"en":"Do not let tasks pile up - deal with them daily.","zh-TW":"不要讓任務堆積，每天處理。"}]', 'phrasal verb'),
('cover for', '代替；遡圖香噴', 'to substitute for someone or provide an alibi', '[{"en":"Can you cover for me while I am at the hospital?","zh-TW":"我在醒院期間你能代替我嗎？"},{"en":"She covered for the manager during his business trip.","zh-TW":"經理出差期間她代理職務。"}]', 'phrasal verb'),
('step in', '介入；緊急代理', 'to intervene or take over in a crisis', '[{"en":"Management stepped in to resolve the conflict.","zh-TW":"管理層介入解決了衝突。"},{"en":"She stepped in when the project fell behind schedule.","zh-TW":"專案進度落後時她緊急介入。"}]', 'phrasal verb'),
('on the same wavelength', '想法相同；志趣相投', 'thinking or feeling the same way', '[{"en":"We are on the same wavelength regarding the project goals.","zh-TW":"關於專案目標我們想法一致。"},{"en":"Finding a partner on the same wavelength is important.","zh-TW":"找到志趣相投的合作帥很重要。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('face the music', '接受懲罰；勇於承擔後果', 'to accept the consequences of actions', '[{"en":"He made errors and now must face the music.","zh-TW":"他犯了错誤現在必須接受懲罰。"},{"en":"It is time to face the music and apologize to the client.","zh-TW":"該勇於承擔并向客戶道歉了。"}]', 'expression'),
('off the record', '非正式地；不對外公开', 'not intended for official recording or publication', '[{"en":"Off the record she admitted the plan had flaws.","zh-TW":"非正式地她承認該計劃有缺陷。"},{"en":"Can you tell me off the record what happened?","zh-TW":"你能非正式地告訴我發生了什麼嗎？"}]', 'expression'),
('clear the air', '消除誤會；化解緊張', 'to resolve misunderstanding or tension', '[{"en":"We scheduled a meeting to clear the air.","zh-TW":"我們安排了一次會議來化解緊張。"},{"en":"Clearing the air helped them work together more effectively.","zh-TW":"化解誤會讓他們合作更順畅。"}]', 'expression'),
('in the pipeline', '將要推出；進行中', 'being developed or planned for release', '[{"en":"Several new products are in the pipeline for next year.","zh-TW":"明年有幾個新產品將要推出。"},{"en":"We have a new partnership in the pipeline.","zh-TW":"我們有一個新合作安排正在進行中。"}]', 'expression'),
('at the eleventh hour', '在最後一刻；山窮水盡時', 'at the last possible moment', '[{"en":"The deal was saved at the eleventh hour.","zh-TW":"在最後一刻協議得以保全。"},{"en":"They submitted the proposal at the eleventh hour.","zh-TW":"他們在最後期限前送出了提案。"}]', 'expression'),
('bite off more than one can chew', '貪多嘴小；承擔太多', 'to take on more responsibility than one can handle', '[{"en":"Do not bite off more than you can chew with these new clients.","zh-TW":"不要承擔超過自己能力的工作量。"},{"en":"She bit off more than she could chew by taking three projects at once.","zh-TW":"她同時承擔三個專案，已超贏。"}]', 'expression'),
('hit the nail on the head', '說對了；掉展對了', 'to describe something exactly right', '[{"en":"Your analysis hit the nail on the head.","zh-TW":"你的分析完全說中了問題核心。"},{"en":"She hit the nail on the head when she identified the bottleneck.","zh-TW":"她指出甉頼點，完全說對了。"}]', 'expression'),
('keep one''s options open', '保留選擇余地；不輕易下決定', 'to avoid committing to one choice', '[{"en":"She is keeping her options open before accepting the offer.","zh-TW":"她在接受還擞z之前保留選擇余地。"},{"en":"It is wise to keep your options open early in a career.","zh-TW":"職涯早期保留選擇余地是明智的。"}]', 'expression'),
('behind closed doors', '秘密進行；不公開', 'in private, without others present', '[{"en":"The negotiation was conducted behind closed doors.","zh-TW":"謈判在閃門後秘密進行。"},{"en":"Many major decisions are made behind closed doors.","zh-TW":"許多重大決策都是秘密制定的。"}]', 'expression'),
('up in the air', '尚未確定；淅空', 'uncertain or not yet decided', '[{"en":"The merger is still up in the air.","zh-TW":"併購案尚未定案。"},{"en":"Our expansion plans are up in the air pending funding.","zh-TW":"我們的擴展計劃尚需資金確定。"}]', 'expression'),
('ahead of the curve', '走在潮流前利；先進', 'more advanced or innovative than others', '[{"en":"Their R&D department keeps them ahead of the curve.","zh-TW":"他們的研發部門讓公司保持先進地位。"},{"en":"To stay ahead of the curve we must innovate constantly.","zh-TW":"要保持屎尖地位我們必須持續創新。"}]', 'expression'),
('raise the bar', '提高標準；設立更高目標', 'to set a higher standard or expectation', '[{"en":"This product launch really raised the bar for the industry.","zh-TW":"這次產品發展提高了整個行業標準。"},{"en":"We need to raise the bar on customer service.","zh-TW":"我們需要提高客戶服務的標準。"}]', 'expression'),
('get up to speed', '追上進度；蚫清情況', 'to become fully informed or as efficient as others', '[{"en":"Please get up to speed on the new system before Monday.","zh-TW":"請在星期一前熌清新系統的使用。"},{"en":"She spent the first week getting up to speed with her new role.","zh-TW":"她花了第一週熌清新職務的內容。"}]', 'expression'),
('read between the lines', '的弦外之音；理解言外之意', 'to understand the hidden meaning', '[{"en":"Reading between the lines the board is worried about costs.","zh-TW":"從弦外之音可得事源魁鮚成本。"},{"en":"You need to read between the lines to understand his feedback.","zh-TW":"你需要理解弦外之意才能領會他的意見。"}]', 'expression'),
('bite the bullet', '和袈作氣；和袈承受', 'to endure a painful or difficult situation', '[{"en":"We had to bite the bullet and announce the layoffs.","zh-TW":"我們不得不和袈宣布裁員消息。"},{"en":"She bit the bullet and requested a salary review.","zh-TW":"她和袈作氣提出了薪資審查申請。"}]', 'expression'),
('in accordance with', '按照；符合', 'following or complying with a rule or agreement', '[{"en":"The project was completed in accordance with the contract.","zh-TW":"專案按照合同完成。"},{"en":"In accordance with company policy all data must be encrypted.","zh-TW":"按照公司政策所有數據必須加密。"}]', 'prepositional phrase'),
('as a result of', '由於；因為…的結果', 'because of or following something', '[{"en":"As a result of the merger staff numbers increased.","zh-TW":"由於並購，員工人數增加。"},{"en":"As a result of poor planning the launch was delayed.","zh-TW":"由於規劃不居，發布會延遲。"}]', 'prepositional phrase'),
('for the sake of', '為了；看在…的分上', 'for the benefit or purpose of', '[{"en":"For the sake of clarity please use bullet points.","zh-TW":"為了清晰起見，請使用條列項目。"},{"en":"We accepted the compromise for the sake of the partnership.","zh-TW":"為了尊重合作關係我們接受了妙協。"}]', 'prepositional phrase'),
('at the expense of', '以…為代價；犧牲…', 'while causing harm or loss to something else', '[{"en":"Speed should not come at the expense of quality.","zh-TW":"速度不應以犧牲品質為代價。"},{"en":"They cut costs at the expense of customer satisfaction.","zh-TW":"他們以犧牲客戶滿意度為代價削減成本。"}]', 'prepositional phrase'),
('in the absence of', '在缺乏…的情況下；在…不在時', 'when something or someone is not present', '[{"en":"In the absence of clear guidelines staff were confused.","zh-TW":"在缺乏明確指引的情況下員工感到困惑。"},{"en":"In the absence of the manager her deputy took over.","zh-TW":"在經理不在時由其副手接管。"}]', 'prepositional phrase'),
('by virtue of', '憑藉；由於', 'because of or by means of a quality or authority', '[{"en":"She was promoted by virtue of her exceptional performance.","zh-TW":"她憑藉出色的表現獲得晉升。"},{"en":"By virtue of his seniority he chaired the meeting.","zh-TW":"憑藉資歷他主持了會議。"}]', 'prepositional phrase'),
('on the basis of', '基於；以…為依據', 'using something as the reason or foundation', '[{"en":"Promotions are given on the basis of performance.","zh-TW":"晉升是基於表現給予的。"},{"en":"On the basis of research we updated our strategy.","zh-TW":"基於研究我們更新了策略。"}]', 'prepositional phrase'),
('in favor of', '贊成；支持', 'in support of or preferring something', '[{"en":"The board voted in favor of the acquisition.","zh-TW":"董事會投票贊成收購。"},{"en":"She was in favor of a flexible work policy.","zh-TW":"她贊成彈性工作政策。"}]', 'prepositional phrase'),
('at the forefront of', '處於…的最前沿；引領', 'leading or most advanced in a field', '[{"en":"This company is at the forefront of AI research.","zh-TW":"這家公司處於人工智慧研究的最前沿。"},{"en":"She put her team at the forefront of industry change.","zh-TW":"她讓團隊站在行業變革的最前沿。"}]', 'prepositional phrase'),
('in conjunction with', '與…一起；配合', 'together with or in combination with', '[{"en":"This tool works best in conjunction with our CRM system.","zh-TW":"此工具與我們的CRM系統配合使用效果最佳。"},{"en":"The campaign was launched in conjunction with the product release.","zh-TW":"該活動與產品發布同時推出。"}]', 'prepositional phrase'),
('in the interest of', '為了…的利益；符合…的利益', 'for the benefit of or to help achieve', '[{"en":"In the interest of transparency we disclosed all costs.","zh-TW":"為了透明起見我們披露了所有費用。"},{"en":"The decision was made in the interest of all stakeholders.","zh-TW":"該決定是為了所有利益相關者的利益而做出的。"}]', 'prepositional phrase'),
('subsequent to', '在…之後；隨後', 'coming after something in time or order', '[{"en":"Subsequent to the audit corrective actions were taken.","zh-TW":"審計之後採取了糾正措施。"},{"en":"Subsequent to the meeting minutes will be distributed.","zh-TW":"會議之後將分發會議記錄。"}]', 'prepositional phrase'),
('back to the drawing board', '重頭再來；重新規劃', 'start over because the current plan failed', '[{"en":"After client rejection it was back to the drawing board.","zh-TW":"客戶拒絕後只好重頭再來。"},{"en":"We went back to the drawing board on the product design.","zh-TW":"我們重新規劃了產品設計。"}]', 'business idiom'),
('in the red', '虧損；赤字', 'spending more money than you earn; in debt', '[{"en":"The division has been in the red for two quarters.","zh-TW":"該部門連續兩個季度處於虧損狀態。"},{"en":"If costs rise further we will be in the red.","zh-TW":"若成本繼續上升我們將陷入虧損。"}]', 'business idiom'),
('in the black', '盈利；財務健康', 'making a profit; having a positive balance', '[{"en":"After restructuring the company is finally in the black.","zh-TW":"重組後公司終於扭虧為盈。"},{"en":"Our goal is to stay in the black throughout the year.","zh-TW":"我們的目標是全年保持盈利。"}]', 'business idiom'),
('hit the ground running', '迅速投入工作；立即高效運作', 'to start working immediately and energetically', '[{"en":"The new hire hit the ground running from day one.","zh-TW":"新員工從第一天就立即高效投入工作。"},{"en":"We need to hit the ground running after the holiday.","zh-TW":"假期後我們需要立即全速投入工作。"}]', 'business idiom'),
('move the needle', '產生顯著影響；推動進展', 'to make a noticeable change or impact', '[{"en":"This campaign really moved the needle on brand awareness.","zh-TW":"這次活動大幅提升了品牌知名度。"},{"en":"We need ideas that truly move the needle.","zh-TW":"我們需要能真正產生重大影響的想法。"}]', 'business idiom'),
('take it offline', '私下再討論；會後再談', 'to continue a discussion separately from the main meeting', '[{"en":"Let us take this offline and avoid delaying the meeting.","zh-TW":"我們把這個留到會後再談，避免耽誤會議。"},{"en":"I suggest we take the budget debate offline.","zh-TW":"我建議把預算辯論留到私下討論。"}]', 'business idiom'),
('crunch the numbers', '計算數據；分析數字', 'to perform mathematical calculations or analyze data', '[{"en":"I need time to crunch the numbers before deciding.","zh-TW":"我需要時間計算數據再做決定。"},{"en":"The finance team crunched the numbers overnight.","zh-TW":"財務團隊通宵分析了數字。"}]', 'business idiom'),
('have skin in the game', '在其中有利益；有切身利益', 'to have a personal financial or risk stake in an outcome', '[{"en":"Investors want founders who have skin in the game.","zh-TW":"投資者希望創始人在其中有切身利益。"},{"en":"He has skin in the game so he is motivated to succeed.","zh-TW":"他在其中有利益所以有動力成功。"}]', 'business idiom'),
('synergy', '協同效應；相輔相成', 'the combined effect being greater than individual parts', '[{"en":"The merger was expected to create synergy across departments.","zh-TW":"這次合併預計將在各部門間產生協同效應。"},{"en":"We look for synergy between our services and client needs.","zh-TW":"我們尋求服務與客戶需求之間的協同效應。"}]', 'business idiom'),
('sign off on', '正式批准；簽字同意', 'to give formal approval to something', '[{"en":"The manager needs to sign off on all expense reports.","zh-TW":"所有費用報告都需要主管簽字批准。"},{"en":"Has the legal team signed off on the contract?","zh-TW":"法務團隊已批准合同了嗎？"}]', 'phrasal verb'),
('run by', '向…徵詢意見；請某人審閱', 'to tell someone about something to get their opinion', '[{"en":"Let me run this proposal by the legal team.","zh-TW":"讓我先請法務團隊審閱這份提案。"},{"en":"Can you run this idea by the director before we proceed?","zh-TW":"在繼續之前你能先請總監審閱這個想法嗎？"}]', 'phrasal verb'),
('factor in', '將…納入考量；考慮在內', 'to include something as a factor in calculations or plans', '[{"en":"We need to factor in the shipping costs.","zh-TW":"我們需要將運費納入考量。"},{"en":"Did you factor in the risk of currency fluctuation?","zh-TW":"你考慮到匯率波動的風險了嗎？"}]', 'phrasal verb'),
('zero in on', '聚焦於；鎖定', 'to focus closely on a target or issue', '[{"en":"The team zeroed in on the root cause of the defect.","zh-TW":"團隊鎖定了缺陷的根本原因。"},{"en":"We need to zero in on our target demographic.","zh-TW":"我們需要聚焦於目標客群。"}]', 'phrasal verb'),
('capitalize on', '善加利用；抓住機會', 'to take advantage of an opportunity or strength', '[{"en":"We must capitalize on this market trend.","zh-TW":"我們必須善加利用這個市場趨勢。"},{"en":"She capitalized on her network to win the deal.","zh-TW":"她善用人脈贏得了這筆交易。"}]', 'phrasal verb'),
('bounce back', '反彈；恢復', 'to recover quickly after a setback', '[{"en":"The company bounced back after a difficult quarter.","zh-TW":"公司在艱困的季度後迅速反彈。"},{"en":"She bounced back from the failed launch and tried again.","zh-TW":"她從失敗的發布中恢復並再次嘗試。"}]', 'phrasal verb'),
('bring forward', '提前；提出', 'to move to an earlier time, or to put forward a proposal', '[{"en":"They brought the deadline forward by one week.","zh-TW":"他們將截止日期提前了一週。"},{"en":"She brought forward a new idea at the annual review.","zh-TW":"她在年度審查中提出了一個新想法。"}]', 'phrasal verb'),
('push back', '推遲；抵制；反駁', 'to delay or express opposition to something', '[{"en":"The client pushed back on the pricing proposal.","zh-TW":"客戶對定價提案提出了反駁。"},{"en":"We had to push back the product launch date.","zh-TW":"我們不得不推遲產品發布日期。"}]', 'phrasal verb'),
('tie up', '佔用；完成最後細節', 'to occupy fully, or to finalize loose ends', '[{"en":"Let us tie up any loose ends before the client visit.","zh-TW":"在客戶來訪前讓我們把所有細節都處理好。"},{"en":"Too much capital is tied up in unsold inventory.","zh-TW":"太多資金被積壓在未售庫存中。"}]', 'phrasal verb'),
('roll back', '撤回；回滾；降低', 'to reverse or reduce something previously set', '[{"en":"The government rolled back tariffs on imported goods.","zh-TW":"政府降低了進口商品的關稅。"},{"en":"They had to roll back the software update due to bugs.","zh-TW":"由於存在錯誤他們不得不回滾軟體更新。"}]', 'phrasal verb'),
('opt out of', '選擇退出；不參與', 'to choose not to participate in something', '[{"en":"Employees can opt out of the pension scheme.","zh-TW":"員工可以選擇退出養老金計劃。"},{"en":"Several partners opted out of the joint venture.","zh-TW":"幾個合作夥伴選擇退出了合資企業。"}]', 'phrasal verb'),
('head up', '領導；主持', 'to lead or be in charge of a group or project', '[{"en":"She will head up the new sustainability initiative.","zh-TW":"她將主持新的永續發展計劃。"},{"en":"He heads up our Asia-Pacific operations.","zh-TW":"他領導我們的亞太區業務。"}]', 'phrasal verb'),
('flag up', '標記；提出（問題）', 'to draw attention to or highlight an issue', '[{"en":"Please flag up any potential risks early.","zh-TW":"請及早提出任何潛在風險。"},{"en":"The auditor flagged up several compliance issues.","zh-TW":"審計員標記了幾個合規問題。"}]', 'phrasal verb'),
('chip in', '插嘴；貢獻一份力量；共同分擔', 'to contribute a share or add a comment', '[{"en":"Everyone chipped in to cover the project costs.","zh-TW":"大家各出一份力分擔了專案費用。"},{"en":"She chipped in with a great idea during the brainstorm.","zh-TW":"她在腦力激盪中提出了一個很好的想法。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('hammer out', '反覆協商達成；艱難制定', 'to reach an agreement through lengthy negotiation', '[{"en":"Both parties hammered out a deal after lengthy talks.","zh-TW":"雙方經過長時間談判終於達成了協議。"},{"en":"We need to hammer out the final terms of the contract.","zh-TW":"我們需要艱難地敲定合同的最終條款。"}]', 'phrasal verb'),
('tap into', '挖掘；利用（資源或市場）', 'to access or make use of a resource or market', '[{"en":"We plan to tap into the emerging Asian markets.","zh-TW":"我們計劃進入新興亞洲市場。"},{"en":"The app taps into user data to personalize recommendations.","zh-TW":"該應用程式利用用戶數據來個性化推薦。"}]', 'phrasal verb'),
('map out', '規劃；制定詳細計劃', 'to plan in detail or create a structured outline', '[{"en":"We mapped out the entire project timeline.","zh-TW":"我們詳細規劃了整個專案時間表。"},{"en":"She mapped out the steps needed to reach the goal.","zh-TW":"她規劃了達成目標所需的每個步驟。"}]', 'phrasal verb'),
('work around', '繞過；想辦法解決', 'to find a way to avoid or deal with a problem', '[{"en":"We found a way to work around the technical limitation.","zh-TW":"我們找到了繞過技術限制的方法。"},{"en":"Can you work around the schedule conflict?","zh-TW":"你能想辦法解決排程衝突嗎？"}]', 'phrasal verb'),
('at a crossroads', '處於十字路口；面臨抉擇', 'at a point where an important decision must be made', '[{"en":"The company is at a crossroads and must choose its path.","zh-TW":"公司處於十字路口必須選擇方向。"},{"en":"She felt at a crossroads after the merger announcement.","zh-TW":"並購宣布後她感到自己面臨抉擇。"}]', 'expression'),
('play it by ear', '隨機應變；見機行事', 'to proceed without a fixed plan; to improvise', '[{"en":"We do not have a set agenda so let us play it by ear.","zh-TW":"我們沒有固定議程就隨機應變吧。"},{"en":"Given the uncertainty she decided to play it by ear.","zh-TW":"鑑於不確定性她決定見機行事。"}]', 'expression'),
('hold your ground', '堅持立場；不退讓', 'to maintain your position under pressure', '[{"en":"In the negotiation she held her ground on the price.","zh-TW":"在談判中她堅持了自己的定價立場。"},{"en":"Hold your ground even when clients push back.","zh-TW":"即使客戶反對也要堅持立場。"}]', 'expression'),
('in the loop', '了解最新情況；在知情範圍內', 'kept informed about what is happening', '[{"en":"Please keep me in the loop on any developments.","zh-TW":"請讓我隨時了解任何進展。"},{"en":"She made sure all stakeholders were in the loop.","zh-TW":"她確保所有利益相關者都掌握最新資訊。"}]', 'expression'),
('out of the loop', '不知情；被排除在外', 'not informed about recent developments', '[{"en":"I felt out of the loop after missing the key meetings.","zh-TW":"錯過關鍵會議後我感到不知情。"},{"en":"She was left out of the loop on the strategic decision.","zh-TW":"她被排除在策略決策的知情範圍之外。"}]', 'expression'),
('take the lead', '帶頭；主導', 'to take primary responsibility or initiative', '[{"en":"He took the lead on the client presentation.","zh-TW":"他主導了客戶簡報。"},{"en":"We need someone to take the lead on this initiative.","zh-TW":"我們需要有人帶頭推動這個計劃。"}]', 'expression'),
('across the board', '全面；普遍', 'applying to all cases or categories equally', '[{"en":"Salaries were increased across the board this year.","zh-TW":"今年全面提高了薪資。"},{"en":"Performance improved across the board after training.","zh-TW":"培訓後各方面表現全面提升。"}]', 'expression'),
('on the cards', '很可能發生；在預料之中', 'likely to happen; predicted', '[{"en":"A restructuring has been on the cards for months.","zh-TW":"重組已在預料之中好幾個月了。"},{"en":"A price increase seems to be on the cards.","zh-TW":"漲價似乎很可能發生。"}]', 'expression'),
('put something on the back burner', '暫緩；擱置', 'to give something lower priority temporarily', '[{"en":"We put the expansion plan on the back burner for now.","zh-TW":"我們暫時把擴張計劃擱置了。"},{"en":"That idea is on the back burner until we have more funding.","zh-TW":"那個想法在獲得更多資金之前暫時擱置。"}]', 'expression'),
('a blessing in disguise', '因禍得福；塞翁失馬', 'something that seems bad but turns out to be good', '[{"en":"The contract loss was a blessing in disguise — it freed resources.","zh-TW":"失去那份合同因禍得福，讓我們釋放了資源。"},{"en":"The delay proved to be a blessing in disguise.","zh-TW":"這次延誤最終因禍得福。"}]', 'expression'),
('pull strings', '動用關係；幕後操控', 'to use personal influence to get things done', '[{"en":"He pulled strings to secure the government contract.","zh-TW":"他動用關係拿到了政府合同。"},{"en":"She does not like to pull strings to advance her career.","zh-TW":"她不喜歡動用關係來推進自己的職業生涯。"}]', 'expression'),
('get the green light', '獲得批准；得到許可', 'to receive approval to proceed with something', '[{"en":"The project got the green light from senior management.","zh-TW":"專案獲得了高層管理的批准。"},{"en":"Once we get the green light we can start immediately.","zh-TW":"一旦獲得批准我們可以立即開始。"}]', 'expression'),
('push the envelope', '突破極限；開拓疆界', 'to go beyond what is conventional or previously possible', '[{"en":"This product pushes the envelope of modern design.","zh-TW":"這款產品突破了現代設計的極限。"},{"en":"Our team is known for pushing the envelope.","zh-TW":"我們的團隊以突破常規著稱。"}]', 'expression'),
('take the bull by the horns', '勇敢面對；迎難而上', 'to confront a difficult problem directly and decisively', '[{"en":"She took the bull by the horns and addressed the budget shortfall.","zh-TW":"她勇敢面對並解決了預算缺口問題。"},{"en":"It is time to take the bull by the horns on this issue.","zh-TW":"是時候迎難而上解決這個問題了。"}]', 'expression'),
('have a lot on one''s plate', '事情繁多；工作量很大', 'to have many tasks or responsibilities to deal with', '[{"en":"She has a lot on her plate with three projects running.","zh-TW":"她同時運作三個專案，工作量很大。"},{"en":"I have a lot on my plate this week but I will manage.","zh-TW":"我這週事情很多但我會設法處理。"}]', 'expression'),
('in view of', '考慮到；鑑於', 'considering or in light of a particular situation', '[{"en":"In view of budget constraints we downsized the event.","zh-TW":"考慮到預算限制我們縮小了活動規模。"},{"en":"In view of the positive results we will continue the campaign.","zh-TW":"鑑於正面結果我們將繼續這次活動。"}]', 'prepositional phrase'),
('by means of', '藉由；透過', 'using a particular method or tool', '[{"en":"We resolved the issue by means of direct negotiation.","zh-TW":"我們藉由直接談判解決了問題。"},{"en":"Communication was maintained by means of video calls.","zh-TW":"透過視訊通話維持了溝通。"}]', 'prepositional phrase'),
('in pursuit of', '追求；為了實現', 'in the process of trying to achieve or obtain', '[{"en":"In pursuit of excellence we raised our standards.","zh-TW":"為了追求卓越我們提高了標準。"},{"en":"She travelled overseas in pursuit of business opportunities.","zh-TW":"她出國是為了尋求商業機會。"}]', 'prepositional phrase'),
('at the heart of', '在…的核心；最重要的部分', 'at the most important or central part of something', '[{"en":"Customer trust is at the heart of our business model.","zh-TW":"客戶信任是我們商業模式的核心。"},{"en":"At the heart of the problem is a lack of communication.","zh-TW":"問題的核心是缺乏溝通。"}]', 'prepositional phrase'),
('on the verge of', '即將；在…邊緣', 'very close to happening or doing something', '[{"en":"The startup is on the verge of its first major deal.","zh-TW":"新創公司即將完成第一筆重大交易。"},{"en":"They were on the verge of bankruptcy before the bailout.","zh-TW":"在救援前他們瀕臨破產邊緣。"}]', 'prepositional phrase'),
('in spite of', '儘管；不管', 'without being prevented by something; despite', '[{"en":"In spite of setbacks the project was completed on time.","zh-TW":"儘管有挫折，專案仍按時完成。"},{"en":"She succeeded in spite of limited resources.","zh-TW":"儘管資源有限她仍然成功了。"}]', 'prepositional phrase'),
('in contrast to', '與…相比；相比之下', 'when compared with something very different', '[{"en":"In contrast to last year profits have grown significantly.","zh-TW":"與去年相比利潤大幅增長。"},{"en":"In contrast to the competition we focus on quality.","zh-TW":"與競爭對手相比我們專注於品質。"}]', 'prepositional phrase'),
('in addition to', '除了…之外；再加上', 'as well as; also', '[{"en":"In addition to the salary we offer a generous bonus.","zh-TW":"除薪資外我們還提供豐厚的獎金。"},{"en":"In addition to English she speaks three other languages.","zh-TW":"除英語外她還會說三種其他語言。"}]', 'prepositional phrase'),
('in advance of', '在…之前；提前', 'before a particular time or event', '[{"en":"Please submit your report in advance of the meeting.","zh-TW":"請在會議前提前提交報告。"},{"en":"We ordered supplies in advance of the busy season.","zh-TW":"我們在旺季前提前訂購了物資。"}]', 'prepositional phrase'),
('with a view to', '為了；以…為目標', 'with the intention or goal of doing something', '[{"en":"She took the certification with a view to advancing her career.","zh-TW":"她取得認證是為了推進職業發展。"},{"en":"They partnered with a view to entering the Asian market.","zh-TW":"他們合作是為了進軍亞洲市場。"}]', 'prepositional phrase'),
('at the disposal of', '供…使用；任…支配', 'available for someone to use freely', '[{"en":"All resources are at the disposal of the project manager.","zh-TW":"所有資源都供專案經理使用。"},{"en":"Our technical support is at your disposal.","zh-TW":"我們的技術支援任您差遣。"}]', 'prepositional phrase'),
('under the supervision of', '在…的監督下', 'managed or watched over by someone', '[{"en":"Interns work under the supervision of senior staff.","zh-TW":"實習生在資深員工的監督下工作。"},{"en":"The trial was conducted under the supervision of experts.","zh-TW":"試驗在專家的監督下進行。"}]', 'prepositional phrase'),
('by way of', '作為；透過；途經', 'as a form of, or passing through', '[{"en":"By way of introduction let me explain our background.","zh-TW":"作為介紹讓我說明一下我們的背景。"},{"en":"She offered a discount by way of apology.","zh-TW":"她提供折扣作為道歉。"}]', 'prepositional phrase'),
('put all eggs in one basket', '孤注一擲；把所有賭注押在一件事上', 'to risk everything on a single plan or option', '[{"en":"Diversify to avoid putting all your eggs in one basket.","zh-TW":"要多元化以避免孤注一擲。"},{"en":"He put all his eggs in one basket with that investment.","zh-TW":"他把所有賭注押在那項投資上。"}]', 'business idiom'),
('a foot in the door', '打入市場；初步接觸', 'an initial position or first step toward a goal', '[{"en":"Internships can give you a foot in the door.","zh-TW":"實習可以讓你打入職場大門。"},{"en":"We got a foot in the door with a small pilot contract.","zh-TW":"我們通過一個小型試點合同打入了市場。"}]', 'business idiom'),
('cut to the chase', '直入主題；開門見山', 'to get to the main point without wasting time', '[{"en":"Let us cut to the chase — what is your budget?","zh-TW":"開門見山吧——你的預算是多少？"},{"en":"She cut to the chase and presented the key findings.","zh-TW":"她直入主題呈現了關鍵發現。"}]', 'business idiom'),
('bring to the table', '貢獻；帶來；提供', 'to contribute skills or value to a discussion or deal', '[{"en":"What experience can you bring to the table?","zh-TW":"你能帶來什麼樣的經驗？"},{"en":"She brings extensive global expertise to the table.","zh-TW":"她帶來了豐富的全球專業知識。"}]', 'business idiom'),
('fast track', '快速通道；加快進展', 'an accelerated path to completion or promotion', '[{"en":"This programme puts graduates on the fast track.","zh-TW":"這個計劃讓畢業生走上快速發展之路。"},{"en":"The project was fast-tracked due to urgency.","zh-TW":"由於緊迫性，專案被加快了進度。"}]', 'business idiom'),
('blue-sky thinking', '天馬行空的創意思維；無約束的創新', 'unrestricted, creative, and innovative thinking', '[{"en":"The workshop encouraged blue-sky thinking about the future.","zh-TW":"研討會鼓勵對未來進行天馬行空的創意思考。"},{"en":"We need blue-sky thinking to disrupt the market.","zh-TW":"我們需要創新思維來顛覆市場。"}]', 'business idiom'),
('get the ball in someone''s court', '讓對方做決定；把責任交給對方', 'to make it the other person''s responsibility to act', '[{"en":"We submitted the proposal — the ball is in their court now.","zh-TW":"我們提交了提案——現在輪到他們決定了。"},{"en":"She responded to put the ball back in their court.","zh-TW":"她做出了回應，把決定權還給了對方。"}]', 'business idiom'),
('window of opportunity', '良機；機會之窗', 'a limited time period in which action is possible', '[{"en":"We have a narrow window of opportunity to enter the market.","zh-TW":"我們有一個狹窄的良機可以進入市場。"},{"en":"Act now before the window of opportunity closes.","zh-TW":"趁機會還在趕快行動。"}]', 'business idiom'),
('keep the ball rolling', '保持進展；持續推動', 'to maintain momentum or progress in an activity', '[{"en":"Good communication helps keep the ball rolling.","zh-TW":"良好溝通有助於保持進展。"},{"en":"We need weekly check-ins to keep the ball rolling.","zh-TW":"我們需要每週檢查以維持專案動力。"}]', 'business idiom'),
('throw in the towel', '投降；認輸；放棄', 'to give up and admit defeat', '[{"en":"Despite setbacks we refused to throw in the towel.","zh-TW":"儘管遇到挫折我們拒絕放棄。"},{"en":"They threw in the towel after the third failed attempt.","zh-TW":"第三次失敗後他們認輸了。"}]', 'business idiom'),
('hit a wall', '碰壁；遭遇瓶頸', 'to encounter an obstacle that stops progress', '[{"en":"We hit a wall when negotiations stalled.","zh-TW":"談判停滯時我們遭遇了瓶頸。"},{"en":"The development team hit a wall with the new architecture.","zh-TW":"開發團隊在新架構方面遭遇了障礙。"}]', 'business idiom'),
('give the go-ahead', '給予批准；同意開始', 'to approve the start of something', '[{"en":"The board gave the go-ahead for the new factory.","zh-TW":"董事會批准了新工廠的建設。"},{"en":"Once we receive the go-ahead we will proceed.","zh-TW":"一旦收到批准我們就會推進。"}]', 'business idiom'),
('play hardball', '採取強硬立場；不讓步', 'to use tough tactics in negotiations or dealings', '[{"en":"They played hardball and refused to lower the price.","zh-TW":"他們採取強硬立場拒絕降價。"},{"en":"She knew when to play hardball to win better terms.","zh-TW":"她知道何時採取強硬立場以爭取更好的條款。"}]', 'business idiom'),
('behind the eight ball', '處於不利處境；進退兩難', 'in a difficult or unfavorable position', '[{"en":"With two missed deadlines we are behind the eight ball.","zh-TW":"錯過兩個截止日期後我們陷入了不利處境。"},{"en":"They found themselves behind the eight ball after the recall.","zh-TW":"召回事件後他們發現自己進退兩難。"}]', 'business idiom'),
('ahead of schedule', '提前於計劃；進度超前', 'completing work earlier than the planned timeline', '[{"en":"The project is two weeks ahead of schedule.","zh-TW":"專案比計劃提前了兩週。"},{"en":"They delivered the product ahead of schedule.","zh-TW":"他們提前交付了產品。"}]', 'business idiom'),
('speak out', '大聲說出；公開表態', 'to express opinions publicly or loudly', '[{"en":"She spoke out against the unfair policy.","zh-TW":"她公開反對這項不公平的政策。"},{"en":"Employees should feel free to speak out about problems.","zh-TW":"員工應該能夠自由表達問題。"}]', 'phrasal verb'),
('lay out', '陳列；說明；制定佈局', 'to present or arrange clearly', '[{"en":"She laid out the proposal clearly in the presentation.","zh-TW":"她在簡報中清晰地陳述了提案。"},{"en":"Let me lay out the timeline for this project.","zh-TW":"讓我說明這個專案的時間表。"}]', 'phrasal verb'),
('follow through', '貫徹到底；跟進落實', 'to complete an action that was started or promised', '[{"en":"It is important to follow through on your commitments.","zh-TW":"貫徹你的承諾非常重要。"},{"en":"She followed through on every promise she made.","zh-TW":"她兌現了自己做出的每個承諾。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('get behind', '支持；全力投入', 'to support or commit to something enthusiastically', '[{"en":"The whole team got behind the new direction.","zh-TW":"整個團隊都全力支持新方向。"},{"en":"Management needs to get behind this initiative.","zh-TW":"管理層需要支持這項計劃。"}]', 'phrasal verb'),
('stand by', '支持；準備就緒；堅守', 'to support, or to be ready and waiting', '[{"en":"I stand by our decision to expand.","zh-TW":"我堅守我們擴張的決定。"},{"en":"Please stand by for further instructions.","zh-TW":"請準備就緒等待進一步指示。"}]', 'phrasal verb'),
('follow up on', '跟進；後續追蹤', 'to check on progress or continue an action', '[{"en":"I will follow up on this issue with the team tomorrow.","zh-TW":"我明天會跟團隊跟進這個問題。"},{"en":"She followed up on the client inquiry the same day.","zh-TW":"她當天就跟進了客戶的詢問。"}]', 'phrasal verb'),
('give way to', '讓步給；被…取代', 'to be replaced by or yield to something', '[{"en":"Traditional processes gave way to digital solutions.","zh-TW":"傳統流程被數位解決方案所取代。"},{"en":"She gave way to pressure and revised the timeline.","zh-TW":"她在壓力下讓步並修訂了時間表。"}]', 'phrasal verb'),
('hold off', '推遲；暫緩；阻止', 'to delay or wait before doing something', '[{"en":"Let us hold off on the announcement until next week.","zh-TW":"讓我們把公告推遲到下週。"},{"en":"She held off the investors with a new timeline.","zh-TW":"她用新的時間表暫緩了投資者的要求。"}]', 'phrasal verb'),
('turn around', '扭轉局面；轉身；完成周轉', 'to reverse a negative situation or complete a task quickly', '[{"en":"The new CEO managed to turn the company around.","zh-TW":"新任執行長成功扭轉了公司的局面。"},{"en":"Can you turn around this report by tomorrow?","zh-TW":"你能在明天前完成這份報告嗎？"}]', 'phrasal verb'),
('take stock of', '評估；盤點', 'to carefully assess a situation or inventory', '[{"en":"Before planning we need to take stock of our current resources.","zh-TW":"規劃前我們需要評估目前的資源狀況。"},{"en":"She took stock of the situation and decided to pivot.","zh-TW":"她評估了情況後決定轉型。"}]', 'phrasal verb'),
('pull through', '度過難關；恢復', 'to survive a difficult situation or recover', '[{"en":"The company pulled through the financial crisis.","zh-TW":"公司度過了金融危機。"},{"en":"With the team''s support the project pulled through.","zh-TW":"在團隊支持下專案度過了難關。"}]', 'phrasal verb'),
('bring in', '引進；帶入；創造收入', 'to introduce or earn a certain amount', '[{"en":"The new service brought in significant revenue.","zh-TW":"新服務帶來了可觀的收入。"},{"en":"We brought in an external consultant to review our processes.","zh-TW":"我們引進了外部顧問來審查我們的流程。"}]', 'phrasal verb'),
('hand over', '移交；交接', 'to transfer control or responsibility to someone else', '[{"en":"She handed over the project to her successor.","zh-TW":"她將專案移交給了繼任者。"},{"en":"Please hand over the files before you leave.","zh-TW":"離開前請移交文件。"}]', 'phrasal verb'),
('set aside', '撥出；保留；擱置爭議', 'to reserve for a specific purpose or ignore temporarily', '[{"en":"We set aside funds for emergency repairs.","zh-TW":"我們為緊急維修撥出了資金。"},{"en":"Let us set aside our differences and focus on the goal.","zh-TW":"讓我們擱置分歧並專注於目標。"}]', 'phrasal verb'),
('measure up', '達到標準；符合期望', 'to meet expectations or required standards', '[{"en":"Does the new vendor measure up to our requirements?","zh-TW":"新供應商能符合我們的要求嗎？"},{"en":"The product did not measure up to the specifications.","zh-TW":"這款產品未能達到規格要求。"}]', 'phrasal verb'),
('pick up on', '注意到；察覺；接受', 'to notice or become aware of something', '[{"en":"She picked up on the tension in the meeting.","zh-TW":"她察覺到了會議中的緊張氣氛。"},{"en":"Our analysts picked up on the emerging market trend.","zh-TW":"我們的分析師注意到了新興市場趨勢。"}]', 'phrasal verb'),
('give out', '分發；精疲力竭；停止運作', 'to distribute, or to stop working properly', '[{"en":"Please give out the meeting agenda to all attendees.","zh-TW":"請將會議議程分發給所有與會者。"},{"en":"The system gave out during peak hours.","zh-TW":"系統在高峰時段停止了運作。"}]', 'phrasal verb'),
('spill the beans', '洩露秘密；說漏嘴', 'to reveal a secret or confidential information', '[{"en":"Someone spilled the beans about the product launch.","zh-TW":"有人洩露了產品發布的秘密。"},{"en":"Do not spill the beans before the official announcement.","zh-TW":"在正式公告前不要說漏嘴。"}]', 'expression'),
('go back to basics', '回歸基本；從基礎開始', 'to return to fundamental principles', '[{"en":"When results drop it is time to go back to basics.","zh-TW":"當成果下滑時是時候回歸基本了。"},{"en":"She advised the team to go back to basics with customer service.","zh-TW":"她建議團隊在客服方面回歸基本原則。"}]', 'expression'),
('show the ropes', '傳授訣竅；指導新人', 'to teach someone how things are done', '[{"en":"Could you show the new intern the ropes?","zh-TW":"你能指導一下新實習生嗎？"},{"en":"He showed her the ropes during her first week.","zh-TW":"她入職第一週他傳授了她訣竅。"}]', 'expression'),
('beat around the bush', '拐彎抹角；避而不談', 'to avoid talking about the main subject directly', '[{"en":"Stop beating around the bush and tell us the budget.","zh-TW":"別再拐彎抹角了，直接告訴我們預算吧。"},{"en":"She was beating around the bush during the negotiation.","zh-TW":"她在談判中拐彎抹角。"}]', 'expression'),
('draw a line in the sand', '劃定底線；設下不可逾越的界限', 'to set a firm limit that cannot be crossed', '[{"en":"Management drew a line in the sand on discount levels.","zh-TW":"管理層劃定了折扣底線。"},{"en":"She drew a line in the sand regarding overtime work.","zh-TW":"她對加班問題劃定了界限。"}]', 'expression'),
('on thin ice', '如履薄冰；處境危險', 'in a risky or precarious situation', '[{"en":"After missing three deadlines he is on thin ice.","zh-TW":"錯過三個截止日期後他如履薄冰。"},{"en":"Be careful — you are on thin ice with the client.","zh-TW":"小心——你與客戶的關係處於危險邊緣。"}]', 'expression'),
('go the extra mile', '加倍努力；付出額外心力', 'to do more than what is required or expected', '[{"en":"She always goes the extra mile for her clients.","zh-TW":"她總是為客戶付出額外的心力。"},{"en":"Going the extra mile sets us apart from the competition.","zh-TW":"加倍努力讓我們有別於競爭者。"}]', 'expression'),
('pass the buck', '推卸責任；推諉', 'to blame someone else or transfer responsibility', '[{"en":"Stop passing the buck — own the mistake and fix it.","zh-TW":"別再推卸責任了——承認錯誤並解決它。"},{"en":"The issue escalated because everyone was passing the buck.","zh-TW":"問題惡化是因為每個人都在推諉。"}]', 'expression'),
('call the shots', '做主；拍板決定', 'to be the person in control who makes decisions', '[{"en":"As CEO she calls the shots on major decisions.","zh-TW":"身為執行長她對重大決策拍板做主。"},{"en":"Who calls the shots in your organization?","zh-TW":"你們組織裡誰做主決策？"}]', 'expression'),
('close ranks', '團結一致；共同面對', 'to unite in support against a common challenge', '[{"en":"The team closed ranks in the face of media criticism.","zh-TW":"面對媒體批評團隊團結一致。"},{"en":"Management closed ranks to protect the company''s reputation.","zh-TW":"管理層齊心協力保護公司聲譽。"}]', 'expression'),
('ring a bell', '似乎耳熟；讓人想起', 'to seem familiar or remind someone of something', '[{"en":"Does the company name ring a bell?","zh-TW":"這個公司名字你聽起來耳熟嗎？"},{"en":"The client''s description rings a bell from last year.","zh-TW":"客戶的描述讓我想起了去年的事。"}]', 'expression'),
('come to a head', '達到頂點；情況趨於嚴峻', 'to reach a critical point where action must be taken', '[{"en":"The conflict came to a head during the board meeting.","zh-TW":"衝突在董事會會議上達到了頂點。"},{"en":"The budget dispute finally came to a head.","zh-TW":"預算爭議終於到了需要解決的關頭。"}]', 'expression'),
('bridge the gap', '縮小差距；彌合分歧', 'to reduce the difference between two things', '[{"en":"We need to bridge the gap between sales and operations.","zh-TW":"我們需要縮小銷售與運營之間的差距。"},{"en":"This training programme bridges the skills gap.","zh-TW":"這個培訓計劃填補了技能差距。"}]', 'expression'),
('have a stake in', '在…中有利益；與…有利害關係', 'to have a financial or personal interest in something', '[{"en":"Every employee has a stake in the company''s success.","zh-TW":"每位員工都與公司的成功有利害關係。"},{"en":"Investors have a stake in how this project performs.","zh-TW":"投資者在這個專案的表現上有切身利益。"}]', 'expression'),
('eat into', '侵蝕；蠶食；佔用', 'to reduce or use up gradually', '[{"en":"Rising costs are eating into our profit margins.","zh-TW":"不斷上漲的成本正在蠶食我們的利潤空間。"},{"en":"These meetings are eating into valuable work time.","zh-TW":"這些會議正在佔用寶貴的工作時間。"}]', 'expression'),
('at a premium', '以高價；很搶手', 'at a higher price than usual, or in short supply', '[{"en":"Office space in the city center is at a premium.","zh-TW":"市中心的辦公空間非常搶手。"},{"en":"This limited edition product is sold at a premium.","zh-TW":"這款限量版產品以高價出售。"}]', 'prepositional phrase'),
('at a glance', '一眼便知；一目了然', 'immediately or easily understood upon first look', '[{"en":"The dashboard shows key metrics at a glance.","zh-TW":"儀表板一目了然地顯示關鍵指標。"},{"en":"You can tell at a glance whether the status is green.","zh-TW":"你一眼就能看出狀態是否為綠色。"}]', 'prepositional phrase'),
('at odds with', '與…不一致；與…對立', 'in conflict or disagreement with', '[{"en":"His approach was at odds with company policy.","zh-TW":"他的做法與公司政策不一致。"},{"en":"The survey results were at odds with our assumptions.","zh-TW":"調查結果與我們的假設相悖。"}]', 'prepositional phrase'),
('in line with', '與…一致；符合', 'consistent with or following a rule or expectation', '[{"en":"The price increase is in line with market trends.","zh-TW":"此次漲價與市場趨勢一致。"},{"en":"Results were in line with our annual forecast.","zh-TW":"結果與我們的年度預測一致。"}]', 'prepositional phrase'),
('in excess of', '超過；多於', 'more than a specified amount or level', '[{"en":"Revenue grew in excess of 20% this year.","zh-TW":"今年收入增長超過了20%。"},{"en":"The project costs were in excess of the original estimate.","zh-TW":"專案費用超過了最初的估算。"}]', 'prepositional phrase'),
('in proportion to', '與…成比例；相應地', 'at a level relative or corresponding to something', '[{"en":"Bonuses are awarded in proportion to performance.","zh-TW":"獎金按績效比例發放。"},{"en":"Resources are allocated in proportion to project size.","zh-TW":"資源按專案規模比例分配。"}]', 'prepositional phrase'),
('subject to', '受制於；以…為前提', 'dependent on or likely to be affected by something', '[{"en":"This offer is subject to management approval.","zh-TW":"此報價須經管理層批准。"},{"en":"All prices are subject to change without notice.","zh-TW":"所有價格如有更改恕不另行通知。"}]', 'prepositional phrase'),
('in the wake of', '在…之後；繼…之後', 'following and as a result of something', '[{"en":"In the wake of the scandal the CEO resigned.","zh-TW":"醜聞發生後執行長辭職了。"},{"en":"New regulations emerged in the wake of the financial crisis.","zh-TW":"金融危機之後出現了新的監管法規。"}]', 'prepositional phrase'),
('in the context of', '在…背景下；就…而言', 'considering the surrounding circumstances or background', '[{"en":"In the context of globalization this strategy makes sense.","zh-TW":"在全球化的背景下這個策略是合理的。"},{"en":"The data must be read in the context of last year''s results.","zh-TW":"這些數據必須結合去年的結果來解讀。"}]', 'prepositional phrase'),
('on the grounds of', '以…為由；基於', 'because of or citing a particular reason', '[{"en":"The request was denied on the grounds of insufficient budget.","zh-TW":"請求以預算不足為由被拒絕了。"},{"en":"She was promoted on the grounds of exceptional leadership.","zh-TW":"她以卓越的領導能力為由獲得晉升。"}]', 'prepositional phrase'),
('as opposed to', '而非；與…相對', 'in contrast with or instead of', '[{"en":"We prefer direct sales as opposed to third-party channels.","zh-TW":"我們偏好直接銷售而非第三方渠道。"},{"en":"As opposed to last year revenue is now growing.","zh-TW":"與去年相比現在收入正在增長。"}]', 'prepositional phrase'),
('in isolation', '孤立地；單獨地', 'separately, without considering broader context', '[{"en":"Do not analyze this metric in isolation.","zh-TW":"不要孤立地分析這個指標。"},{"en":"The departments cannot operate in isolation.","zh-TW":"各部門不能孤立地運作。"}]', 'prepositional phrase'),
('in parallel with', '與…同步；平行進行', 'at the same time as something else', '[{"en":"Development will run in parallel with marketing preparation.","zh-TW":"開發將與行銷準備工作同步進行。"},{"en":"In parallel with cost cuts we are investing in new talent.","zh-TW":"在削減成本的同時我們正在投資新人才。"}]', 'prepositional phrase'),
('at the outset', '在開始時；最初', 'at the very beginning of something', '[{"en":"At the outset we defined clear success criteria.","zh-TW":"在開始時我們確定了明確的成功標準。"},{"en":"Set expectations at the outset to avoid confusion later.","zh-TW":"在開始時設定期望以避免後期混淆。"}]', 'prepositional phrase'),
('in full', '全額；完整地', 'completely; with nothing missing', '[{"en":"The invoice was paid in full within 30 days.","zh-TW":"發票在30天內全額付清。"},{"en":"Please read the agreement in full before signing.","zh-TW":"簽署前請完整閱讀協議。"}]', 'prepositional phrase'),
('by the book', '按規定；按章行事', 'strictly following rules and procedures', '[{"en":"Our compliance team always does things by the book.","zh-TW":"我們的合規團隊總是按規定行事。"},{"en":"He insisted on handling the audit by the book.","zh-TW":"他堅持按章程處理審計。"}]', 'prepositional phrase'),
('best of both worlds', '兩全其美；兼得', 'having the advantages of two different things simultaneously', '[{"en":"Working remotely gives us the best of both worlds.","zh-TW":"遠端工作讓我們兩全其美。"},{"en":"The hybrid model offers the best of both worlds.","zh-TW":"混合模式讓我們享受兩全其美的好處。"}]', 'business idiom'),
('add value', '增加價值；有貢獻', 'to improve something or make a positive contribution', '[{"en":"How does this feature add value for users?","zh-TW":"這個功能如何為用戶增加價值？"},{"en":"She adds value to every project she joins.","zh-TW":"她加入的每個專案都能增加價值。"}]', 'business idiom'),
('leverage', '善加利用；發揮槓桿效用', 'to use something to maximum advantage', '[{"en":"We leverage our global network to win new clients.","zh-TW":"我們善用全球網絡來開拓新客戶。"},{"en":"Leverage your existing skills to transition into this role.","zh-TW":"善用你現有的技能來轉換到這個職位。"}]', 'business idiom'),
('low-hanging fruit', '唾手可得的目標；容易實現的機會', 'easy targets or opportunities that can be achieved quickly', '[{"en":"Start with low-hanging fruit to show early results.","zh-TW":"從唾手可得的目標開始以展示早期成果。"},{"en":"The low-hanging fruit in cost saving has already been taken.","zh-TW":"成本節約方面容易實現的部分已被採用。"}]', 'business idiom'),
('bandwidth', '時間與精力；處理能力', 'the capacity or availability to handle more work', '[{"en":"I do not have the bandwidth for another project this month.","zh-TW":"這個月我沒有多餘的精力再接一個專案。"},{"en":"Do you have the bandwidth to take on this client?","zh-TW":"你有能力承接這個客戶嗎？"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('boil the ocean', '徒勞無功；試圖完成不可能的任務', 'to undertake an impossibly large task', '[{"en":"Do not try to boil the ocean — focus on key priorities.","zh-TW":"不要試圖做不可能的事——專注於關鍵優先事項。"},{"en":"The original scope was boiling the ocean so we cut it down.","zh-TW":"原本的範圍太過龐大所以我們縮減了。"}]', 'business idiom'),
('peel the onion', '逐層深入分析；深入研究', 'to analyze something layer by layer to find the root cause', '[{"en":"To solve this problem we need to peel the onion.","zh-TW":"要解決這個問題我們需要逐層深入分析。"},{"en":"She peeled the onion and found the real bottleneck.","zh-TW":"她逐層分析發現了真正的瓶頸所在。"}]', 'business idiom'),
('circle back', '再回來討論；稍後跟進', 'to return to a topic or conversation later', '[{"en":"Let us circle back to that question after the break.","zh-TW":"休息後讓我們再回到那個問題。"},{"en":"I will circle back with you once I have more information.","zh-TW":"等我有更多資訊後再回來跟你討論。"}]', 'business idiom'),
('deep dive', '深入分析；詳細調查', 'a thorough, in-depth examination of a topic', '[{"en":"We need to do a deep dive into the customer data.","zh-TW":"我們需要對客戶數據進行深入分析。"},{"en":"The consultant did a deep dive on our supply chain.","zh-TW":"顧問對我們的供應鏈進行了深入調查。"}]', 'business idiom'),
('pivot', '轉型；轉向；調整策略', 'to change direction or strategy significantly', '[{"en":"The startup pivoted to a subscription model.","zh-TW":"新創公司轉型為訂閱模式。"},{"en":"After the market shift they pivoted their entire strategy.","zh-TW":"市場轉變後他們調整了整個策略。"}]', 'business idiom'),
('scalable', '可擴展的；可規模化的', 'capable of growing or adapting without losing performance', '[{"en":"We need a scalable solution that grows with demand.","zh-TW":"我們需要一個能隨需求增長的可擴展解決方案。"},{"en":"The business model must be scalable to attract investors.","zh-TW":"商業模式必須具有可擴展性才能吸引投資者。"}]', 'business idiom'),
('disruptive innovation', '顛覆性創新', 'innovation that significantly alters an industry', '[{"en":"Disruptive innovation changed the entire retail landscape.","zh-TW":"顛覆性創新改變了整個零售業格局。"},{"en":"She led disruptive innovation at her previous company.","zh-TW":"她在上一家公司主導了顛覆性創新。"}]', 'business idiom'),
('stakeholder', '利益相關者；股東', 'any person who has an interest in a business or project', '[{"en":"All stakeholders must be informed of the decision.","zh-TW":"所有利益相關者必須被告知這個決定。"},{"en":"Stakeholder engagement is crucial for project success.","zh-TW":"利益相關者的參與對專案成功至關重要。"}]', 'business idiom'),
('buy-in', '認同；支持；首肯', 'agreement and support from key people', '[{"en":"We need buy-in from the board before proceeding.","zh-TW":"我們需要在繼續之前獲得董事會的認同。"},{"en":"Getting buy-in from all departments took two weeks.","zh-TW":"獲得所有部門的支持花了兩週時間。"}]', 'business idiom'),
('top line', '總收入；營收', 'total revenue before deductions', '[{"en":"The new product is expected to boost the top line.","zh-TW":"新產品預計將提升總收入。"},{"en":"We focus on top-line growth through new partnerships.","zh-TW":"我們通過新的合作關係專注於收入增長。"}]', 'business idiom'),
('agree on', '就…達成共識；同意', 'to reach an agreement about something', '[{"en":"We finally agreed on the contract terms.","zh-TW":"我們終於就合同條款達成了共識。"},{"en":"Can we agree on a delivery date by Friday?","zh-TW":"我們能在週五前就交貨日期達成共識嗎？"}]', 'phrasal verb'),
('build on', '以…為基礎；發展', 'to use as a foundation for further development', '[{"en":"Let us build on last year''s success.","zh-TW":"讓我們以去年的成功為基礎繼續發展。"},{"en":"She built on existing client relationships to expand business.","zh-TW":"她以現有客戶關係為基礎擴展了業務。"}]', 'phrasal verb'),
('close off', '關閉；截止', 'to end or prevent access to something', '[{"en":"By committing early you close off other options.","zh-TW":"早期承諾會關閉其他選項。"},{"en":"The deadline closes off submissions at midnight.","zh-TW":"截止日期在午夜關閉提交。"}]', 'phrasal verb'),
('fall through', '失敗；告吹', 'to fail to happen or to be cancelled', '[{"en":"The merger fell through at the last minute.","zh-TW":"合併在最後一刻告吹了。"},{"en":"The contract fell through after months of negotiation.","zh-TW":"合同在幾個月的談判後告吹了。"}]', 'phrasal verb'),
('gear up for', '為…做準備；積極備戰', 'to prepare for an important event or activity', '[{"en":"The team is gearing up for the product launch.","zh-TW":"團隊正在為產品發布做準備。"},{"en":"We are gearing up for the busiest quarter.","zh-TW":"我們正在為最繁忙的季度積極備戰。"}]', 'phrasal verb'),
('hang on to', '保留；緊抓；堅持', 'to keep or retain something', '[{"en":"We must hang on to our key clients.","zh-TW":"我們必須留住核心客戶。"},{"en":"It is hard to hang on to talent in this market.","zh-TW":"在這個市場留住人才很困難。"}]', 'phrasal verb'),
('invest in', '投資；投入資源', 'to spend money or effort on something for future benefit', '[{"en":"We invest heavily in employee development.","zh-TW":"我們大力投資員工發展。"},{"en":"She invested in new software to improve productivity.","zh-TW":"她投資了新軟體以提高生產力。"}]', 'phrasal verb'),
('knock back', '拒絕；擊退', 'to reject or refuse an offer or proposal', '[{"en":"The board knocked back the acquisition proposal.","zh-TW":"董事會拒絕了收購提案。"},{"en":"She was knocked back twice before landing the deal.","zh-TW":"她被拒絕兩次後才談成了交易。"}]', 'phrasal verb'),
('lead to', '導致；引起', 'to result in or cause something to happen', '[{"en":"This strategy could lead to significant cost savings.","zh-TW":"這個策略可能導致大幅成本節約。"},{"en":"Poor communication often leads to project failures.","zh-TW":"溝通不良往往導致專案失敗。"}]', 'phrasal verb'),
('lock in', '鎖定；確保', 'to secure or confirm an arrangement firmly', '[{"en":"We locked in the price before the rate increase.","zh-TW":"我們在漲價前鎖定了價格。"},{"en":"The long-term contract locks in the supply for two years.","zh-TW":"長期合同鎖定了兩年的供應。"}]', 'phrasal verb'),
('move ahead', '向前推進；繼續進行', 'to proceed or make progress', '[{"en":"We are ready to move ahead with the expansion.","zh-TW":"我們準備好推進擴張計劃了。"},{"en":"Please move ahead on the design phase.","zh-TW":"請繼續推進設計階段。"}]', 'phrasal verb'),
('object to', '反對；提出異議', 'to express disagreement or opposition', '[{"en":"Several members objected to the proposed changes.","zh-TW":"幾位成員反對提出的變更。"},{"en":"The union objected to the new working conditions.","zh-TW":"工會反對新的工作條件。"}]', 'phrasal verb'),
('patch up', '修補；和解', 'to repair a relationship or quickly fix a problem', '[{"en":"The two partners patched up their differences.","zh-TW":"兩位合夥人修補了他們的分歧。"},{"en":"They patched up the agreement with a compromise.","zh-TW":"他們通過妥協修補了協議。"}]', 'phrasal verb'),
('plan ahead', '提前規劃；預先計劃', 'to prepare in advance for future needs', '[{"en":"Always plan ahead to avoid last-minute problems.","zh-TW":"一定要提前規劃以避免最後一刻的問題。"},{"en":"She planned ahead for the transition period.","zh-TW":"她提前規劃了過渡期。"}]', 'phrasal verb'),
('reach out to', '聯繫；接觸', 'to make contact with someone for help or information', '[{"en":"Please reach out to the client for clarification.","zh-TW":"請聯繫客戶以獲得澄清。"},{"en":"She reached out to industry experts for advice.","zh-TW":"她聯繫了業界專家尋求建議。"}]', 'phrasal verb'),
('report back', '回報；匯報', 'to provide information or findings after investigation', '[{"en":"Please report back after your meeting with the client.","zh-TW":"請在與客戶開會後回報。"},{"en":"She reported back with a full analysis of the market.","zh-TW":"她回報了完整的市場分析。"}]', 'phrasal verb'),
('respond to', '回應；對…做出反應', 'to reply to or react to something', '[{"en":"Please respond to the client email by end of day.","zh-TW":"請在今天下班前回覆客戶的電子郵件。"},{"en":"The company responded to market changes quickly.","zh-TW":"公司迅速回應了市場變化。"}]', 'phrasal verb'),
('shake up', '大力改革；震動', 'to make major changes to an organization or system', '[{"en":"The new CEO shook up the management structure.","zh-TW":"新執行長大力改革了管理架構。"},{"en":"The startup is shaking up the traditional banking industry.","zh-TW":"這家新創公司正在顛覆傳統銀行業。"}]', 'phrasal verb'),
('slow down', '放慢速度；減緩', 'to reduce speed, pace, or intensity', '[{"en":"Supply chain issues slowed down our production.","zh-TW":"供應鏈問題減緩了我們的生產速度。"},{"en":"Growth has slowed down in the domestic market.","zh-TW":"國內市場的增長已經減緩。"}]', 'phrasal verb'),
('stand up to', '經得起；抵抗', 'to withstand scrutiny or challenges', '[{"en":"Does this proposal stand up to careful analysis?","zh-TW":"這個提案能經得起仔細分析嗎？"},{"en":"The product must stand up to harsh market conditions.","zh-TW":"產品必須能夠抵抗嚴苛的市場狀況。"}]', 'phrasal verb'),
('step up', '加強；提升；挺身而出', 'to increase effort, or to take greater responsibility', '[{"en":"The team stepped up during the critical phase.","zh-TW":"在關鍵階段團隊挺身而出。"},{"en":"We need to step up our marketing efforts.","zh-TW":"我們需要加強行銷工作。"}]', 'phrasal verb'),
('stick with', '堅持；繼續使用', 'to continue with something rather than changing', '[{"en":"We decided to stick with the current supplier.","zh-TW":"我們決定繼續使用現有的供應商。"},{"en":"She stuck with her original proposal and won.","zh-TW":"她堅持了原來的提案並成功了。"}]', 'phrasal verb'),
('sum up', '總結；概括', 'to briefly summarize the main points', '[{"en":"Can you sum up the key takeaways?","zh-TW":"你能總結主要收穫嗎？"},{"en":"She summed up the discussion in two clear points.","zh-TW":"她用兩個清晰的要點總結了討論。"}]', 'phrasal verb'),
('team up', '合作；組隊', 'to join forces with someone for a common purpose', '[{"en":"We teamed up with a local firm to enter the market.","zh-TW":"我們與一家本地公司合作進入市場。"},{"en":"The two departments teamed up on the project.","zh-TW":"兩個部門聯合推進了這個專案。"}]', 'phrasal verb'),
('think through', '仔細考慮；深思熟慮', 'to consider something carefully and thoroughly', '[{"en":"Please think through the implications before deciding.","zh-TW":"做決定前請仔細考慮其影響。"},{"en":"She thought through every scenario before presenting.","zh-TW":"她在發表前深思熟慮了每個情境。"}]', 'phrasal verb'),
('touch on', '提及；簡略談及', 'to mention briefly in passing', '[{"en":"She touched on the budget issue in her presentation.","zh-TW":"她在簡報中提及了預算問題。"},{"en":"The report touches on several key challenges.","zh-TW":"報告簡略提及了幾個關鍵挑戰。"}]', 'phrasal verb'),
('trade off', '以…換取；權衡取捨', 'to accept a disadvantage in exchange for a benefit', '[{"en":"We traded off speed for accuracy in the process.","zh-TW":"我們在流程中以犧牲速度換取準確性。"},{"en":"There are always trade-offs between cost and quality.","zh-TW":"成本與品質之間總是存在取捨。"}]', 'phrasal verb'),
('wind up', '結束；清算；最終到達', 'to end up in a situation, or to close down', '[{"en":"The failed startup wound up with huge debts.","zh-TW":"失敗的新創公司最終背負了巨額債務。"},{"en":"They wound up the subsidiary after three unprofitable years.","zh-TW":"三年虧損後他們清算了子公司。"}]', 'phrasal verb'),
('the ball is in your court', '現在輪到你了；決定權在你', 'it is now the other person''s turn to act or decide', '[{"en":"We submitted the offer — the ball is in their court.","zh-TW":"我們提交了報價——現在決定權在他們那邊。"},{"en":"I have made my position clear; the ball is in your court.","zh-TW":"我已表明立場；現在輪到你了。"}]', 'expression'),
('behind the scenes', '幕後；在檯面下', 'in private, without public visibility', '[{"en":"A lot of hard work happens behind the scenes.","zh-TW":"許多艱辛的工作都在幕後進行。"},{"en":"She worked behind the scenes to secure the partnership.","zh-TW":"她在幕後努力確保了合作關係的建立。"}]', 'expression'),
('break new ground', '開拓新領域；創新', 'to do something innovative or pioneering', '[{"en":"This product breaks new ground in renewable energy.","zh-TW":"這款產品在可再生能源領域開拓了新領域。"},{"en":"She broke new ground with her research on AI ethics.","zh-TW":"她在人工智慧倫理研究方面開拓了新領域。"}]', 'expression'),
('bring home the bacon', '養家；賺錢維持生計', 'to earn money to support oneself or family', '[{"en":"With two kids she is determined to bring home the bacon.","zh-TW":"有兩個孩子她下定決心要養家。"},{"en":"The new contract will really bring home the bacon.","zh-TW":"新合同真的能帶來可觀的收入。"}]', 'expression'),
('burn bridges', '斷絕關係；自絕退路', 'to permanently damage a relationship or future opportunities', '[{"en":"Do not burn bridges when leaving a company.","zh-TW":"離職時不要斷絕關係自絕退路。"},{"en":"She burned bridges with the client over a pricing dispute.","zh-TW":"她因定價糾紛與客戶斷絕了關係。"}]', 'expression'),
('change gears', '轉換策略；改變節奏', 'to change approach, pace, or direction', '[{"en":"After poor results we changed gears and tried a new approach.","zh-TW":"在成績不佳後我們轉換策略嘗試了新方法。"},{"en":"It is time to change gears and focus on retention.","zh-TW":"是時候改變節奏專注於客戶留存了。"}]', 'expression'),
('cover all bases', '面面俱到；覆蓋所有情況', 'to deal with every possible situation or eventuality', '[{"en":"The risk assessment covered all bases.","zh-TW":"風險評估面面俱到。"},{"en":"She made sure to cover all bases before the negotiation.","zh-TW":"她在談判前確保面面俱到。"}]', 'expression'),
('dig deep', '深入挖掘；付出極大努力', 'to make a great effort or examine something thoroughly', '[{"en":"We dug deep to understand the customer''s real needs.","zh-TW":"我們深入挖掘以了解客戶的真實需求。"},{"en":"When the market shifted she dug deep to find a solution.","zh-TW":"市場轉變時她付出了極大努力尋找解決方案。"}]', 'expression'),
('do the math', '算一算；考慮清楚', 'to think about the numbers or logic of a situation', '[{"en":"Do the math — at this rate we will not break even.","zh-TW":"算一算——以這個速度我們無法收支平衡。"},{"en":"She did the math and decided to outsource.","zh-TW":"她計算了一下決定外包。"}]', 'expression'),
('draw the line', '劃定界限；設定底線', 'to set a firm limit on what is acceptable', '[{"en":"We draw the line at requests that compromise quality.","zh-TW":"我們對損害品質的要求劃定了界限。"},{"en":"Management drew the line at offering further discounts.","zh-TW":"管理層對進一步折扣設定了底線。"}]', 'expression'),
('explore all avenues', '探索所有可能；窮盡選項', 'to investigate every possible option or solution', '[{"en":"We explored all avenues before accepting the loss.","zh-TW":"我們在接受損失之前探索了所有可能。"},{"en":"The team explored all avenues for cost reduction.","zh-TW":"團隊探索了所有降低成本的途徑。"}]', 'expression'),
('get to the bottom of', '查明真相；徹底調查', 'to find out the real cause of something', '[{"en":"We need to get to the bottom of this quality issue.","zh-TW":"我們需要查明這個品質問題的真相。"},{"en":"She got to the bottom of the data discrepancy.","zh-TW":"她徹底調查了數據差異的原因。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('give credit where it is due', '給予應有的肯定；功勞歸於應得者', 'to acknowledge someone''s contribution appropriately', '[{"en":"Give credit where it is due — this was her idea.","zh-TW":"功勞歸於應得者——這是她的想法。"},{"en":"Good managers always give credit where it is due.","zh-TW":"好的管理者總是給予應有的肯定。"}]', 'expression'),
('hit the jackpot', '大獲全勝；成功', 'to achieve a great success or unexpected benefit', '[{"en":"The company hit the jackpot with its new app.","zh-TW":"公司憑藉新應用程式大獲全勝。"},{"en":"Hiring her was hitting the jackpot.","zh-TW":"聘用她真的是非常成功的決定。"}]', 'expression'),
('in over one''s head', '不知所措；超出能力範圍', 'in a situation that is too complex or difficult to handle', '[{"en":"Without the training he was in over his head.","zh-TW":"缺乏培訓他完全不知所措。"},{"en":"She felt in over her head managing three offices alone.","zh-TW":"獨自管理三個辦公室讓她感到超出了自己的能力範圍。"}]', 'expression'),
('jump on the bandwagon', '跟風；隨大流', 'to join a popular trend or activity', '[{"en":"Many brands jumped on the sustainability bandwagon.","zh-TW":"許多品牌跟風追求永續發展。"},{"en":"Do not just jump on the bandwagon without a real strategy.","zh-TW":"不要只是跟風而沒有真正的策略。"}]', 'expression'),
('keep the lights on', '維持基本運作；保持運轉', 'to do the minimum to keep something functioning', '[{"en":"During the restructuring we just need to keep the lights on.","zh-TW":"在重組期間我們只需要維持基本運作。"},{"en":"The skeleton crew kept the lights on during the holiday.","zh-TW":"最少員工在假期期間維持了基本運轉。"}]', 'expression'),
('light at the end of the tunnel', '看到希望；苦盡甘來', 'signs that a long period of difficulty is ending', '[{"en":"After months of losses we finally see light at the end of the tunnel.","zh-TW":"經過幾個月的虧損我們終於看到了希望。"},{"en":"The new contract represents light at the end of the tunnel.","zh-TW":"新合同代表著苦盡甘來的希望。"}]', 'expression'),
('make a case for', '為…提出論據；力主', 'to argue in favor of something with evidence', '[{"en":"She made a strong case for increasing the marketing budget.","zh-TW":"她為增加行銷預算提出了有力論據。"},{"en":"Can you make a case for expanding to Asia?","zh-TW":"你能為拓展至亞洲提出論據嗎？"}]', 'expression'),
('make waves', '引起轟動；製造影響', 'to cause a significant impact or controversy', '[{"en":"Her bold strategy made waves in the industry.","zh-TW":"她大膽的策略在業界引起了轟動。"},{"en":"The new startup is already making waves.","zh-TW":"這家新創公司已經引起了廣泛關注。"}]', 'expression'),
('miss the mark', '未達目標；落空', 'to fail to achieve the intended result or standard', '[{"en":"The campaign missed the mark with the target audience.","zh-TW":"這次活動未能打動目標受眾。"},{"en":"His presentation missed the mark in terms of data.","zh-TW":"他的簡報在數據方面未達標準。"}]', 'expression'),
('on the cutting edge', '處於前沿；最先進的', 'at the most advanced or innovative level', '[{"en":"Our lab is on the cutting edge of AI research.","zh-TW":"我們的實驗室處於人工智慧研究的前沿。"},{"en":"They invest heavily to stay on the cutting edge.","zh-TW":"他們大量投資以保持在前沿地位。"}]', 'expression'),
('on the fence', '舉棋不定；態度模糊', 'undecided or neutral about an issue', '[{"en":"She is still on the fence about accepting the offer.","zh-TW":"她對是否接受邀請仍舉棋不定。"},{"en":"Many investors are on the fence given current uncertainty.","zh-TW":"鑑於當前不確定性許多投資者態度模糊。"}]', 'expression'),
('pick up the slack', '彌補不足；代勞', 'to do more work to compensate for others'' lack of effort', '[{"en":"The senior team picked up the slack during onboarding.","zh-TW":"在入職期間資深團隊彌補了工作不足。"},{"en":"Everyone had to pick up the slack after the layoffs.","zh-TW":"裁員後每個人都要彌補人手不足。"}]', 'expression'),
('pull one''s weight', '盡自己的本分；充分貢獻', 'to do one''s fair share of work in a group', '[{"en":"Every team member must pull their weight.","zh-TW":"每位團隊成員都必須盡自己的本分。"},{"en":"He was let go for not pulling his weight.","zh-TW":"他因為沒有充分貢獻而被解僱。"}]', 'expression'),
('put on the same footing', '建立平等地位；使處於同等條件', 'to make things or people equal in status or treatment', '[{"en":"The new policy puts all employees on the same footing.","zh-TW":"新政策使所有員工處於平等地位。"},{"en":"We put the two proposals on the same footing for comparison.","zh-TW":"我們將兩份提案放在同等條件下比較。"}]', 'expression'),
('separate the wheat from the chaff', '去蕪存菁；分辨優劣', 'to distinguish the good from the bad or valuable from worthless', '[{"en":"The rigorous interview separates the wheat from the chaff.","zh-TW":"嚴格的面試去蕪存菁。"},{"en":"Market competition helps separate the wheat from the chaff.","zh-TW":"市場競爭有助於分辨優劣企業。"}]', 'expression'),
('strike while the iron is hot', '趁熱打鐵；把握時機', 'to take advantage of an opportunity at the right moment', '[{"en":"Customer interest is high — strike while the iron is hot.","zh-TW":"客戶興趣高漲——要趁熱打鐵。"},{"en":"She struck while the iron was hot and closed the deal.","zh-TW":"她趁熱打鐵完成了交易。"}]', 'expression'),
('in keeping with', '符合；與…一致', 'consistent with or appropriate to', '[{"en":"The decision was in keeping with company values.","zh-TW":"這個決定符合公司價值觀。"},{"en":"In keeping with tradition the annual award was presented.","zh-TW":"依照傳統頒發了年度獎項。"}]', 'prepositional phrase'),
('with the exception of', '除了…之外', 'excluding a particular person or thing', '[{"en":"All branches are profitable with the exception of the newest one.","zh-TW":"除最新分店外所有分店都盈利。"},{"en":"With the exception of a few issues the rollout was smooth.","zh-TW":"除了幾個問題外推出很順利。"}]', 'prepositional phrase'),
('to the extent that', '在…的程度上；以致於', 'to the degree that something is true or happens', '[{"en":"To the extent that demand allows we will increase production.","zh-TW":"在需求允許的程度上我們將增加生產。"},{"en":"Cuts were made to the extent that performance suffered.","zh-TW":"削減達到了影響績效的程度。"}]', 'prepositional phrase'),
('in the event of', '萬一；如果發生', 'if something happens, especially something undesirable', '[{"en":"In the event of a system failure please contact support.","zh-TW":"萬一系統故障請聯繫支援。"},{"en":"In the event of non-payment legal action will be taken.","zh-TW":"萬一未付款將採取法律行動。"}]', 'prepositional phrase'),
('on the strength of', '憑借；依據', 'because of evidence or a quality that supports action', '[{"en":"She was hired on the strength of her portfolio.","zh-TW":"她憑借作品集被錄用了。"},{"en":"On the strength of our track record we won the bid.","zh-TW":"憑借我們的業績記錄我們贏得了競標。"}]', 'prepositional phrase'),
('in the face of', '面對；不顧', 'when confronted by or despite a challenging situation', '[{"en":"In the face of competition we maintained market share.","zh-TW":"面對競爭我們維持了市場份額。"},{"en":"She succeeded in the face of significant obstacles.","zh-TW":"她面對重大障礙依然成功了。"}]', 'prepositional phrase'),
('as a matter of', '作為…問題；在…方面', 'considered as a question of or relating to a specific area', '[{"en":"As a matter of policy all decisions require documentation.","zh-TW":"作為政策問題所有決策都需要記錄在案。"},{"en":"She reviews every proposal as a matter of routine.","zh-TW":"她作為慣例審查每份提案。"}]', 'prepositional phrase'),
('in partnership with', '與…合作；攜手', 'working together with another party', '[{"en":"We launched the product in partnership with a major retailer.","zh-TW":"我們與一家大型零售商合作推出了這款產品。"},{"en":"In partnership with the city we are building a tech hub.","zh-TW":"我們與市政府攜手建設科技中心。"}]', 'prepositional phrase'),
('ahead of time', '提前；事先', 'before the scheduled or expected time', '[{"en":"Please submit the report ahead of time if possible.","zh-TW":"如有可能請提前提交報告。"},{"en":"They completed the installation ahead of time.","zh-TW":"他們提前完成了安裝。"}]', 'prepositional phrase'),
('at your convenience', '在您方便的時候；按您的時間', 'whenever it suits the other person''s schedule', '[{"en":"Please reply at your convenience.","zh-TW":"請在您方便的時候回覆。"},{"en":"We can schedule the demo at your convenience.","zh-TW":"我們可以在您方便的時候安排演示。"}]', 'prepositional phrase'),
('under no circumstances', '在任何情況下都不；絕不', 'not in any situation; absolutely not', '[{"en":"Under no circumstances should client data be shared.","zh-TW":"在任何情況下都不得共享客戶數據。"},{"en":"Under no circumstances are employees permitted to accept gifts.","zh-TW":"員工在任何情況下都不得接受禮品。"}]', 'prepositional phrase'),
('as a consequence of', '由於；因為…的後果', 'resulting from or because of something', '[{"en":"As a consequence of the review new guidelines were issued.","zh-TW":"作為審查的後果頒布了新指引。"},{"en":"As a consequence of missing the deadline we lost the client.","zh-TW":"由於錯過截止日期我們失去了客戶。"}]', 'prepositional phrase'),
('with effect from', '自…起生效', 'beginning to apply from a specified date', '[{"en":"The new pricing is with effect from July 1.","zh-TW":"新定價自7月1日起生效。"},{"en":"With effect from next month all requests must go through the system.","zh-TW":"自下個月起所有申請必須通過系統提交。"}]', 'prepositional phrase'),
('on the condition that', '條件是；以…為前提', 'only if a specific requirement is met', '[{"en":"They approved the budget on the condition that costs are tracked.","zh-TW":"他們以追蹤成本為前提批准了預算。"},{"en":"We will proceed on the condition that the terms are revised.","zh-TW":"我們將以修訂條款為前提繼續推進。"}]', 'prepositional phrase'),
('at the initiative of', '在…的倡議下；由…發起', 'started or driven by a particular person or body', '[{"en":"The programme was launched at the initiative of the CEO.","zh-TW":"該計劃由執行長發起。"},{"en":"At the initiative of the R&D team a new lab was opened.","zh-TW":"在研發團隊的倡議下新實驗室開放了。"}]', 'prepositional phrase'),
('game changer', '改變局面的事物；革命性變化', 'something that fundamentally alters a situation or industry', '[{"en":"This technology is a real game changer for logistics.","zh-TW":"這項技術是物流業真正的革命性變化。"},{"en":"Her hire was a game changer for the team.","zh-TW":"她的加入改變了整個團隊的局面。"}]', 'business idiom'),
('thought leader', '思想領袖；行業影響者', 'a recognized authority whose ideas influence others', '[{"en":"She is a well-known thought leader in digital marketing.","zh-TW":"她是數位行銷領域公認的思想領袖。"},{"en":"Publishing articles helped him become a thought leader.","zh-TW":"發表文章幫助他成為行業思想領袖。"}]', 'business idiom'),
('paradigm shift', '典範轉移；根本性的轉變', 'a fundamental change in approach or understanding', '[{"en":"Remote work represents a paradigm shift in employment.","zh-TW":"遠端工作代表了就業模式的典範轉移。"},{"en":"The digital revolution was a paradigm shift for business.","zh-TW":"數位革命是商業模式的根本性轉變。"}]', 'business idiom'),
('pain point', '痛點；困擾點', 'a specific problem that customers or employees experience', '[{"en":"Our product directly addresses customer pain points.","zh-TW":"我們的產品直接解決客戶的痛點。"},{"en":"Understanding pain points helps develop better solutions.","zh-TW":"了解痛點有助於開發更好的解決方案。"}]', 'business idiom'),
('going concern', '持續經營；有活力的事業', 'a business that is expected to continue operating normally', '[{"en":"The auditors confirmed the company is a going concern.","zh-TW":"審計師確認公司是持續經營實體。"},{"en":"Investors look for businesses that are proven going concerns.","zh-TW":"投資者尋找持續盈利的企業。"}]', 'business idiom'),
('net net', '最終結果；總結而言', 'the final result after all factors are considered', '[{"en":"Net net the project was a success despite the delays.","zh-TW":"總結而言儘管有延誤這個專案是成功的。"},{"en":"Net net we saved more money than we spent.","zh-TW":"最終結果是我們省的錢多於花的錢。"}]', 'business idiom'),
('onboarding', '入職培訓；客戶引導', 'the process of integrating a new employee or customer', '[{"en":"A strong onboarding process reduces turnover.","zh-TW":"完善的入職培訓流程能降低員工流動率。"},{"en":"Client onboarding took three days with the new system.","zh-TW":"使用新系統客戶引導只需三天。"}]', 'business idiom'),
('pipeline', '業務管道；潛在機會', 'potential clients or opportunities being developed', '[{"en":"We have a strong pipeline heading into Q4.","zh-TW":"我們在進入第四季時有強勁的業務管道。"},{"en":"The sales team is working to fill the pipeline.","zh-TW":"銷售團隊正在努力填充業務管道。"}]', 'business idiom'),
('run rate', '年化運行率；按現行速度推算', 'the projected performance extrapolated from current results', '[{"en":"Our run rate puts us on track for record revenue.","zh-TW":"我們的運行率顯示有望實現創紀錄的收入。"},{"en":"Based on run rate we will exceed annual targets.","zh-TW":"根據運行率我們將超額完成年度目標。"}]', 'business idiom'),
('headcount', '員工人數；頭人數', 'the total number of employees in an organization', '[{"en":"Management approved increasing headcount by 10%.","zh-TW":"管理層批准將員工人數增加10%。"},{"en":"Headcount was reduced to cut costs during the downturn.","zh-TW":"在經濟下滑期間透過裁員削減了成本。"}]', 'business idiom'),
('benchmark', '基準；比較標準', 'a standard used to measure or compare performance', '[{"en":"We benchmark our prices against industry leaders.","zh-TW":"我們以行業領導者為基準比較我們的價格。"},{"en":"The project set a new benchmark for quality.","zh-TW":"這個專案為品質設定了新的基準。"}]', 'business idiom'),
('agile', '靈活的；敏捷開發的', 'responsive to change; using iterative development methods', '[{"en":"We shifted to an agile methodology for faster delivery.","zh-TW":"我們轉向敏捷方法論以加快交付速度。"},{"en":"An agile team can adapt quickly to client needs.","zh-TW":"靈活的團隊能迅速適應客戶需求。"}]', 'business idiom'),
('outsource', '外包', 'to hire external parties to perform business functions', '[{"en":"We outsource IT support to reduce overhead.","zh-TW":"我們將IT支援外包以降低開銷。"},{"en":"The company outsourced manufacturing to Southeast Asia.","zh-TW":"公司將製造業務外包至東南亞。"}]', 'business idiom'),
('return on investment', '投資回報率', 'the profit or benefit gained relative to the cost of investment', '[{"en":"The return on investment for this campaign was excellent.","zh-TW":"此次活動的投資回報率非常高。"},{"en":"We must demonstrate a strong return on investment.","zh-TW":"我們必須展示強勁的投資回報率。"}]', 'business idiom'),
('market share', '市場份額；市佔率', 'the percentage of a market controlled by a company', '[{"en":"We grew our market share by 5% last year.","zh-TW":"去年我們的市場份額增長了5%。"},{"en":"The new entrant is eating into our market share.","zh-TW":"新進入者正在蠶食我們的市場份額。"}]', 'business idiom'),
('call in', '請來；召喚；致電', 'to request someone to come, or to phone in', '[{"en":"We called in an external expert to assess the risk.","zh-TW":"我們請來了外部專家評估風險。"},{"en":"She called in a favor from her former colleague.","zh-TW":"她請了前同事幫忙。"}]', 'phrasal verb'),
('cut through', '突破；穿透；直截了當', 'to get through complexity or red tape efficiently', '[{"en":"Her concise email cut through all the confusion.","zh-TW":"她簡潔的郵件一下子消除了所有混亂。"},{"en":"We need to cut through bureaucracy to move faster.","zh-TW":"我們需要突破官僚主義才能加快進度。"}]', 'phrasal verb'),
('double up', '加倍；合用；臨時合併', 'to increase to twice the amount, or to share', '[{"en":"We doubled up on marketing to boost awareness.","zh-TW":"我們加倍了行銷投入以提高知名度。"},{"en":"The two teams doubled up to meet the deadline.","zh-TW":"兩個團隊合力趕上了截止日期。"}]', 'phrasal verb'),
('edge out', '略勝；擠掉；緩慢超越', 'to narrowly defeat or overtake a competitor', '[{"en":"We edged out our competitor on price.","zh-TW":"我們在價格上略勝競爭對手。"},{"en":"The new product edged out the leading brand.","zh-TW":"新產品悄悄超越了領先品牌。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('flesh out', '充實；補充細節', 'to add details or substance to an idea or plan', '[{"en":"Please flesh out this concept with specific examples.","zh-TW":"請用具體例子充實這個概念。"},{"en":"She fleshed out the proposal before the board meeting.","zh-TW":"她在董事會會議前充實了提案細節。"}]', 'phrasal verb'),
('free up', '釋放；騰出', 'to make time, money, or resources available', '[{"en":"Automating this process will free up staff for other work.","zh-TW":"自動化這個流程將釋放員工去做其他工作。"},{"en":"We restructured to free up capital for investment.","zh-TW":"我們重組以騰出資金進行投資。"}]', 'phrasal verb'),
('get across', '傳達；讓人理解', 'to successfully communicate a message or idea', '[{"en":"She struggled to get her point across in the meeting.","zh-TW":"她在會議中努力傳達自己的觀點。"},{"en":"Good visuals help get complex ideas across.","zh-TW":"好的視覺資料有助於傳達複雜的想法。"}]', 'phrasal verb'),
('jump in', '加入；插話；立即行動', 'to enter or participate suddenly and enthusiastically', '[{"en":"Feel free to jump in with your questions at any time.","zh-TW":"歡迎隨時插話提問。"},{"en":"She jumped in to help when the project was falling behind.","zh-TW":"當專案進度落後時她立即加入幫忙。"}]', 'phrasal verb'),
('make the most of', '充分利用；善加運用', 'to use something as effectively as possible', '[{"en":"Make the most of this networking event.","zh-TW":"好好把握這次人脈拓展活動。"},{"en":"She made the most of her international assignment.","zh-TW":"她充分利用了海外派駐的機會。"}]', 'phrasal verb'),
('narrow in on', '逐步鎖定；縮小焦點', 'to focus increasingly on a specific thing', '[{"en":"The investigators narrowed in on three suspects.","zh-TW":"調查人員逐步縮小到三名嫌疑人。"},{"en":"We narrowed in on the most cost-effective solution.","zh-TW":"我們逐步鎖定了最具成本效益的解決方案。"}]', 'phrasal verb'),
('open up', '開放；打開；拓展', 'to become available, or to expand access', '[{"en":"The new trade deal opens up the Asian market.","zh-TW":"新的貿易協議打開了亞洲市場。"},{"en":"She opened up a discussion about remote work policies.","zh-TW":"她開放了關於遠端工作政策的討論。"}]', 'phrasal verb'),
('phase in', '逐步引入；分階段實施', 'to introduce something gradually in stages', '[{"en":"The new regulations will be phased in over two years.","zh-TW":"新法規將分兩年逐步實施。"},{"en":"They phased in the software changes with minimal disruption.","zh-TW":"他們在最小干擾的情況下分階段引入了軟體變更。"}]', 'phrasal verb'),
('play up', '強調；過分渲染', 'to emphasize or exaggerate a quality or problem', '[{"en":"The sales pitch played up the product''s unique features.","zh-TW":"銷售宣傳強調了產品的獨特功能。"},{"en":"Do not play up minor issues in the negotiation.","zh-TW":"談判中不要過分渲染小問題。"}]', 'phrasal verb'),
('push through', '強行推進；使通過', 'to force something to completion despite opposition', '[{"en":"The CEO pushed through the restructuring plan.","zh-TW":"執行長強行推進了重組計劃。"},{"en":"They pushed through the policy despite resistance.","zh-TW":"他們不顧阻力推進了政策實施。"}]', 'phrasal verb'),
('put through', '使接通；使承受；完成', 'to connect a call, or to subject someone to an ordeal', '[{"en":"Let me put you through to the accounts department.","zh-TW":"我幫您轉接到帳務部門。"},{"en":"New employees are put through a rigorous training programme.","zh-TW":"新員工要接受嚴格的培訓計劃。"}]', 'phrasal verb'),
('queue up', '排隊；等待', 'to stand in line or wait in order', '[{"en":"Multiple projects are queued up for approval.","zh-TW":"多個專案正在排隊等待批准。"},{"en":"Customers queued up for the limited release.","zh-TW":"顧客排隊等候限量版產品。"}]', 'phrasal verb'),
('reach an agreement', '達成協議', 'to come to a mutual understanding or deal', '[{"en":"After three rounds of talks we reached an agreement.","zh-TW":"經過三輪談判我們達成了協議。"},{"en":"Both parties reached an agreement on the payment terms.","zh-TW":"雙方就付款條款達成了協議。"}]', 'phrasal verb'),
('rebound from', '從…中反彈；恢復', 'to recover after a setback or negative event', '[{"en":"The market rebounded from last quarter''s losses.","zh-TW":"市場從上季度的虧損中反彈了。"},{"en":"The company rebounded from the crisis stronger than before.","zh-TW":"公司從危機中比以前更強壯地反彈了。"}]', 'phrasal verb'),
('reconcile with', '與…和解；核對', 'to resolve differences, or to make consistent', '[{"en":"The team needs to reconcile the budget figures.","zh-TW":"團隊需要核對預算數字。"},{"en":"They reconciled their differences after the mediation.","zh-TW":"調解後他們化解了分歧。"}]', 'phrasal verb'),
('rotate out', '輪換；調換崗位', 'to replace in a rotation system', '[{"en":"Staff are rotated out every two years for fresh perspective.","zh-TW":"員工每兩年輪換一次以帶來新視角。"},{"en":"The committee chairman is rotated out annually.","zh-TW":"委員會主席每年輪換。"}]', 'phrasal verb'),
('segment out', '細分；劃分市場', 'to divide into distinct groups for analysis or targeting', '[{"en":"We segment out customers by purchase frequency.","zh-TW":"我們按購買頻率細分客戶。"},{"en":"Please segment out the B2B data for separate analysis.","zh-TW":"請將B2B數據單獨分離出來進行分析。"}]', 'phrasal verb'),
('ship out', '運出；出貨', 'to send goods out for delivery', '[{"en":"All orders will be shipped out within 48 hours.","zh-TW":"所有訂單將在48小時內出貨。"},{"en":"We shipped out the last batch of products yesterday.","zh-TW":"我們昨天發出了最後一批產品。"}]', 'phrasal verb'),
('size up', '評估；打量', 'to assess or evaluate a person or situation', '[{"en":"She quickly sized up the competitive landscape.","zh-TW":"她迅速評估了競爭格局。"},{"en":"Before the negotiation he sized up his counterpart.","zh-TW":"談判前他仔細打量了對方。"}]', 'phrasal verb'),
('start up', '創業；啟動', 'to begin a new business or start a machine', '[{"en":"She started up her own consultancy last year.","zh-TW":"她去年創辦了自己的顧問公司。"},{"en":"The system takes two minutes to start up.","zh-TW":"系統需要兩分鐘才能啟動。"}]', 'phrasal verb'),
('streamline', '精簡；優化流程', 'to make a process more efficient by removing unnecessary steps', '[{"en":"We streamlined the approval process to save time.","zh-TW":"我們精簡了審批流程以節省時間。"},{"en":"The software helps streamline our operations.","zh-TW":"這個軟體有助於優化我們的運作。"}]', 'phrasal verb'),
('take a hit', '遭受損失；受打擊', 'to suffer a loss or negative impact', '[{"en":"Sales took a hit during the pandemic.","zh-TW":"疫情期間銷售遭受了打擊。"},{"en":"The brand took a hit after the recall.","zh-TW":"召回事件後品牌聲譽受到了損害。"}]', 'phrasal verb'),
('trim down', '削減；精簡', 'to reduce the size or number of something', '[{"en":"We trimmed down the project scope to fit the budget.","zh-TW":"我們縮減了專案範圍以符合預算。"},{"en":"The team was trimmed down after the restructure.","zh-TW":"重組後團隊規模被削減了。"}]', 'phrasal verb'),
('try out', '試用；測試', 'to test something to see if it works or is suitable', '[{"en":"We are trying out a new scheduling tool.","zh-TW":"我們正在試用新的排程工具。"},{"en":"She tried out several vendors before choosing one.","zh-TW":"她在選定供應商前試用了幾家。"}]', 'phrasal verb'),
('take a back seat', '退到幕後；讓位', 'to take a less active or prominent role', '[{"en":"After the merger the founder took a back seat.","zh-TW":"合併後創辦人退居幕後。"},{"en":"She took a back seat to let her team shine.","zh-TW":"她退到幕後讓團隊大放異彩。"}]', 'expression'),
('take the plunge', '大膽行動；鼓起勇氣', 'to decide to do something after hesitating', '[{"en":"We finally took the plunge and opened an overseas office.","zh-TW":"我們終於鼓起勇氣開設了海外辦事處。"},{"en":"She took the plunge and launched her startup.","zh-TW":"她大膽行動創辦了自己的新創公司。"}]', 'expression'),
('there is no going back', '無法回頭；不可逆', 'when a decision or action cannot be undone', '[{"en":"Once you sign the contract there is no going back.","zh-TW":"一旦簽了合同就無法回頭了。"},{"en":"There is no going back after announcing the merger.","zh-TW":"宣布合併後就無法回頭了。"}]', 'expression'),
('tip of the iceberg', '冰山一角；只是表面', 'a small visible part of a much larger problem or issue', '[{"en":"These complaints are just the tip of the iceberg.","zh-TW":"這些投訴只是冰山一角。"},{"en":"The losses revealed were the tip of the iceberg.","zh-TW":"揭露的損失只是冰山一角。"}]', 'expression'),
('turn the tide', '扭轉局勢；改變形勢', 'to reverse a difficult or losing situation', '[{"en":"The new product launch turned the tide for the company.","zh-TW":"新產品發布扭轉了公司的局勢。"},{"en":"A bold strategy can turn the tide in our favor.","zh-TW":"大膽的策略可以扭轉形勢讓我們佔優。"}]', 'expression'),
('under the radar', '低調；未被注意', 'not attracting attention or scrutiny', '[{"en":"The startup operated under the radar for two years.","zh-TW":"這家新創公司低調運作了兩年。"},{"en":"She kept the project under the radar until launch day.","zh-TW":"她在發布當天之前讓專案保持低調。"}]', 'expression'),
('wear many hats', '身兼多職；扮演多種角色', 'to perform multiple roles or responsibilities simultaneously', '[{"en":"In a startup everyone wears many hats.","zh-TW":"在新創公司每個人都要身兼多職。"},{"en":"She wears many hats as both designer and developer.","zh-TW":"她身兼設計師和開發人員多職。"}]', 'expression'),
('win-win situation', '雙贏局面', 'a situation where everyone involved benefits', '[{"en":"The deal is a win-win situation for both companies.","zh-TW":"這筆交易對兩家公司都是雙贏局面。"},{"en":"We aim to create a win-win situation with every partner.","zh-TW":"我們的目標是與每個合作夥伴創造雙贏局面。"}]', 'expression'),
('working against the clock', '與時間賽跑；趕時間', 'working under extreme time pressure to finish something', '[{"en":"We were working against the clock to meet the deadline.","zh-TW":"我們與時間賽跑趕上截止日期。"},{"en":"The engineering team worked against the clock to fix the bug.","zh-TW":"工程團隊與時間賽跑修復了漏洞。"}]', 'expression'),
('worth its weight in gold', '價值連城；非常有用', 'extremely valuable or useful', '[{"en":"A reliable vendor is worth its weight in gold.","zh-TW":"一個可靠的供應商價值連城。"},{"en":"Her experience is worth its weight in gold for the team.","zh-TW":"她的經驗對團隊來說非常寶貴。"}]', 'expression'),
('you reap what you sow', '一分耕耘一分收穫', 'results reflect the effort or actions invested', '[{"en":"Our growth is no surprise — you reap what you sow.","zh-TW":"我們的增長並不令人驚訝——一分耕耘一分收穫。"},{"en":"Invest in your team and you reap what you sow.","zh-TW":"投資你的團隊你就會得到回報。"}]', 'expression'),
('zero tolerance', '零容忍', 'a policy of strict punishment for any violation, no exceptions', '[{"en":"We have zero tolerance for workplace harassment.","zh-TW":"我們對職場騷擾採取零容忍態度。"},{"en":"The company maintains zero tolerance for data breaches.","zh-TW":"公司對數據洩露保持零容忍。"}]', 'expression'),
('food for thought', '值得深思；引人思考的觀點', 'something that stimulates serious consideration', '[{"en":"The report gives us a lot of food for thought.","zh-TW":"這份報告給我們很多值得深思的觀點。"},{"en":"Her questions provided food for thought.","zh-TW":"她的問題引人深思。"}]', 'expression'),
('get the wrong end of the stick', '誤解；理解錯誤', 'to misunderstand a situation completely', '[{"en":"He got the wrong end of the stick about the promotion.","zh-TW":"他誤解了有關晉升的情況。"},{"en":"She got the wrong end of the stick from my email.","zh-TW":"她從我的郵件中得出了錯誤的理解。"}]', 'expression'),
('keep one''s cards close to one''s chest', '守口如瓶；不透露計劃', 'to keep plans or intentions secret', '[{"en":"During negotiations she kept her cards close to her chest.","zh-TW":"在談判期間她守口如瓶不透露底牌。"},{"en":"Keep your cards close to your chest until the right moment.","zh-TW":"在適當時機到來之前不要透露你的計劃。"}]', 'expression'),
('let the dust settle', '讓塵埃落定；等局勢穩定', 'to wait for a confusing or stressful situation to calm down', '[{"en":"Let the dust settle before announcing any changes.","zh-TW":"在宣布任何變更之前讓塵埃先落定。"},{"en":"After the merger we let the dust settle for a month.","zh-TW":"合併後我們等了一個月讓局勢穩定。"}]', 'expression'),
('in proportion with', '與…成比例；相稱', 'in a balanced relationship with something else', '[{"en":"Pay should increase in proportion with responsibility.","zh-TW":"薪資應與責任相稱地增加。"},{"en":"Risk is in proportion with the potential return.","zh-TW":"風險與潛在回報相稱。"}]', 'prepositional phrase'),
('under pressure', '在壓力下；被迫', 'experiencing stress or being forced to do something', '[{"en":"She performs well even under pressure.","zh-TW":"她即使在壓力下也表現良好。"},{"en":"Under pressure the team delivered an excellent result.","zh-TW":"在壓力下團隊交出了優秀的成果。"}]', 'prepositional phrase'),
('in contrast with', '與…對比；相比之下', 'when compared against something different', '[{"en":"In contrast with last year this quarter shows growth.","zh-TW":"與去年相比本季呈現出增長。"},{"en":"In contrast with competitors we offer free support.","zh-TW":"與競爭對手相比我們提供免費支援。"}]', 'prepositional phrase'),
('under review', '正在審查中', 'currently being examined or assessed', '[{"en":"The pricing model is currently under review.","zh-TW":"定價模型目前正在審查中。"},{"en":"All submitted proposals are under review.","zh-TW":"所有提交的提案都在審查中。"}]', 'prepositional phrase'),
('on reflection', '經過反思；仔細考慮後', 'after thinking carefully about something', '[{"en":"On reflection we decided to revise the proposal.","zh-TW":"經過反思我們決定修改提案。"},{"en":"On reflection her decision proved to be correct.","zh-TW":"仔細考慮後她的決定被證明是正確的。"}]', 'prepositional phrase'),
('in default of', '在缺乏…的情況下；因未履行', 'in the absence of, or because of failure to fulfill', '[{"en":"In default of payment the contract will be terminated.","zh-TW":"在未付款的情況下合同將被終止。"},{"en":"In default of a response we will proceed unilaterally.","zh-TW":"在缺乏回覆的情況下我們將單方面推進。"}]', 'prepositional phrase'),
('given that', '鑑於；考慮到', 'taking into account the fact that', '[{"en":"Given that resources are limited we must prioritize.","zh-TW":"鑑於資源有限我們必須排定優先順序。"},{"en":"Given that the deadline is close we need to act now.","zh-TW":"考慮到截止日期臨近我們需要立刻行動。"}]', 'prepositional phrase'),
('beyond the scope of', '超出…的範圍', 'outside the boundaries of what has been agreed or planned', '[{"en":"This request is beyond the scope of our contract.","zh-TW":"這個要求超出了我們合同的範圍。"},{"en":"The issue is beyond the scope of this meeting.","zh-TW":"這個問題超出了本次會議的範圍。"}]', 'prepositional phrase'),
('within the bounds of', '在…範圍之內；在…限制內', 'inside the limits that are allowed or reasonable', '[{"en":"All decisions must be within the bounds of the law.","zh-TW":"所有決定必須在法律範圍之內。"},{"en":"The team operates within the bounds of company policy.","zh-TW":"團隊在公司政策的範圍內運作。"}]', 'prepositional phrase'),
('from the ground up', '從頭開始；從零開始', 'starting completely from the beginning', '[{"en":"We built the system from the ground up.","zh-TW":"我們從零開始建立了這個系統。"},{"en":"The new platform was redesigned from the ground up.","zh-TW":"新平台從頭開始重新設計。"}]', 'prepositional phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('above and beyond', '超出預期；額外付出', 'more than what is expected or required', '[{"en":"She went above and beyond in serving the client.","zh-TW":"她在服務客戶方面超越了期望。"},{"en":"The team went above and beyond to deliver on time.","zh-TW":"團隊額外付出以準時交付。"}]', 'prepositional phrase'),
('to the detriment of', '有損於；危害到', 'causing harm or damage to something or someone', '[{"en":"Shortcuts were taken to the detriment of quality.","zh-TW":"走捷徑有損於品質。"},{"en":"Speed was prioritized to the detriment of accuracy.","zh-TW":"速度被優先考慮而犧牲了準確性。"}]', 'prepositional phrase'),
('in conjunction', '聯合；同時；協同', 'together or at the same time as something else', '[{"en":"The two teams worked in conjunction on the launch.","zh-TW":"兩個團隊聯合推進了發布活動。"},{"en":"Marketing and sales should work in conjunction.","zh-TW":"行銷與銷售應協同工作。"}]', 'prepositional phrase'),
('the elephant in the room', '房間裡的大象；顯而易見卻被刻意忽略的問題', 'an obvious problem that people avoid discussing', '[{"en":"Let us address the elephant in the room — costs are too high.","zh-TW":"讓我們直面顯而易見的問題——成本太高了。"},{"en":"The elephant in the room is the lack of leadership.","zh-TW":"被刻意忽略的問題是領導力的缺乏。"}]', 'business idiom'),
('ballpark figure', '概略數字；大概估算', 'an approximate number or estimate', '[{"en":"Can you give me a ballpark figure for the project cost?","zh-TW":"你能給我一個專案費用的大概數字嗎？"},{"en":"A ballpark figure suggests the renovation will cost about 1 million.","zh-TW":"大概估算翻新費用約為一百萬。"}]', 'business idiom'),
('bread and butter', '主要收入來源；核心業務', 'the primary source of income or most important activity', '[{"en":"Software subscriptions are our bread and butter.","zh-TW":"軟體訂閱是我們的主要收入來源。"},{"en":"Repeat customers are the bread and butter of any business.","zh-TW":"回頭客是任何業務的核心。"}]', 'business idiom'),
('burning question', '迫切的問題；燃眉之急', 'an urgent or highly important question that needs answering', '[{"en":"The burning question is whether to expand overseas.","zh-TW":"迫切的問題是是否要拓展海外市場。"},{"en":"Investors have a burning question about profitability.","zh-TW":"投資者對盈利能力有一個迫切的問題。"}]', 'business idiom'),
('buzz word', '流行語；時髦術語', 'a fashionable term often used to sound current', '[{"en":"Innovation is a buzzword that needs concrete meaning.","zh-TW":"創新是一個需要具體含義的流行語。"},{"en":"Good reports avoid unnecessary buzzwords.","zh-TW":"好的報告避免使用不必要的流行語。"}]', 'business idiom'),
('cash cow', '搖錢樹；穩定盈利的業務', 'a product or business that consistently generates profit', '[{"en":"This product line has been our cash cow for a decade.","zh-TW":"這條產品線十年來一直是我們的搖錢樹。"},{"en":"Protecting the cash cow is essential for long-term stability.","zh-TW":"保護搖錢樹對長期穩定至關重要。"}]', 'business idiom'),
('on autopilot', '自動運行；按慣例行事', 'operating automatically without active thought or control', '[{"en":"The department has been running on autopilot for months.","zh-TW":"這個部門幾個月來一直在按慣例運作。"},{"en":"Innovation suffers when teams operate on autopilot.","zh-TW":"當團隊按慣例行事時創新就會受到影響。"}]', 'business idiom'),
('dead in the water', '毫無進展；陷入僵局', 'unable to move forward; completely stopped', '[{"en":"Without funding the project is dead in the water.","zh-TW":"沒有資金專案就毫無進展。"},{"en":"After the scandal the partnership was dead in the water.","zh-TW":"醜聞後這個合作關係陷入了僵局。"}]', 'business idiom'),
('dot the i''s and cross the t''s', '一絲不苟；注意所有細節', 'to pay careful attention to every detail', '[{"en":"Make sure to dot the i''s and cross the t''s before filing.","zh-TW":"提交前務必一絲不苟地核對每個細節。"},{"en":"She dotted every i and crossed every t in the contract.","zh-TW":"她仔細核對了合同中的每個細節。"}]', 'business idiom'),
('elevator pitch', '電梯提案；簡短有力的推介', 'a brief and persuasive speech about an idea or product', '[{"en":"He practiced his elevator pitch before the investor meeting.","zh-TW":"他在投資者會議前練習了他的電梯提案。"},{"en":"A good elevator pitch should last no more than 60 seconds.","zh-TW":"好的電梯提案應不超過60秒。"}]', 'business idiom'),
('fall flat', '失敗；反應冷淡', 'to fail to produce the intended effect or response', '[{"en":"The rebranding campaign fell flat with consumers.","zh-TW":"品牌重塑活動在消費者中反應冷淡。"},{"en":"His presentation fell flat without concrete data.","zh-TW":"他的簡報因缺乏具體數據而失敗了。"}]', 'business idiom'),
('fat cat', '大老闆；富豪', 'a powerful or wealthy person, especially in business', '[{"en":"The fat cats at the top received large bonuses.","zh-TW":"高層的大老闆們獲得了豐厚的獎金。"},{"en":"Workers resented the fat cat executives during layoffs.","zh-TW":"裁員期間員工對富豪高管們感到憤憤不平。"}]', 'business idiom'),
('feel the pinch', '感到拮据；受到財務壓力', 'to experience difficulty due to reduced money or resources', '[{"en":"Small businesses are feeling the pinch of rising costs.","zh-TW":"小企業正感受到成本上漲的財務壓力。"},{"en":"We are starting to feel the pinch from budget cuts.","zh-TW":"我們開始感受到預算削減的壓力。"}]', 'business idiom'),
('fire on all cylinders', '全力運轉；全速前進', 'working at maximum efficiency or capacity', '[{"en":"After the restructuring the team is firing on all cylinders.","zh-TW":"重組後團隊全力運轉。"},{"en":"The factory is firing on all cylinders this quarter.","zh-TW":"這個季度工廠在全速前進。"}]', 'business idiom'),
('flagship product', '旗艦產品；代表性產品', 'a company''s best or most important product', '[{"en":"The new smartphone is the company''s flagship product.","zh-TW":"新智慧型手機是公司的旗艦產品。"},{"en":"Flagship products should reflect brand values.","zh-TW":"旗艦產品應體現品牌價值觀。"}]', 'business idiom'),
('flying colors', '出色地；大獲全勝', 'with great success or distinction', '[{"en":"She passed the certification exam with flying colors.","zh-TW":"她以優異成績通過了認證考試。"},{"en":"The audit was completed with flying colors.","zh-TW":"審計以優異結果完成。"}]', 'business idiom'),
('action on', '對…採取行動；執行', 'to act on or implement a decision or request', '[{"en":"Please action on the client''s feedback by Friday.","zh-TW":"請在週五前對客戶的反饋採取行動。"},{"en":"We will action on the board''s recommendation immediately.","zh-TW":"我們將立即執行董事會的建議。"}]', 'phrasal verb'),
('check off', '勾除；完成並標記', 'to mark as completed on a list', '[{"en":"She checked off each task as it was completed.","zh-TW":"她完成每項任務後都勾除了它。"},{"en":"Before shipping, check off every item on the checklist.","zh-TW":"出貨前勾除清單上的每個項目。"}]', 'phrasal verb'),
('circle around', '圍繞；再次討論', 'to return to a topic or hover around an issue', '[{"en":"The discussion kept circling around the same problem.","zh-TW":"討論一直圍繞著同一個問題打轉。"},{"en":"Let us stop circling around and address the issue.","zh-TW":"讓我們停止繞圈子直接解決問題。"}]', 'phrasal verb'),
('delegate to', '授權給；委派給', 'to assign a task or responsibility to someone else', '[{"en":"Managers should delegate to their team members.","zh-TW":"管理者應將任務授權給團隊成員。"},{"en":"She delegated the research to junior staff.","zh-TW":"她將研究工作委派給了初級員工。"}]', 'phrasal verb'),
('expand on', '詳細說明；展開闡述', 'to provide more details or information about something', '[{"en":"Could you expand on your proposal?","zh-TW":"你能詳細說明你的提案嗎？"},{"en":"She expanded on the financial projections in the appendix.","zh-TW":"她在附錄中詳細說明了財務預測。"}]', 'phrasal verb'),
('finalize', '最終確定；完成定稿', 'to reach final agreement on or complete something', '[{"en":"We need to finalize the contract by end of week.","zh-TW":"我們需要在本週末前最終確定合同。"},{"en":"The team finalized the product specifications.","zh-TW":"團隊完成了產品規格的定稿。"}]', 'phrasal verb'),
('hold back', '阻礙；保留；克制', 'to restrain, withhold, or prevent progress', '[{"en":"Lack of funding is holding back our expansion.","zh-TW":"資金不足阻礙了我們的擴張。"},{"en":"She held back her comments until the end.","zh-TW":"她保留了評論直到最後。"}]', 'phrasal verb'),
('identify with', '認同；與…產生共鳴', 'to feel a strong connection or similarity with', '[{"en":"Customers who identify with our brand are loyal.","zh-TW":"認同我們品牌的客戶都是忠實客戶。"},{"en":"She identifies with the company''s sustainability mission.","zh-TW":"她與公司的永續發展使命產生共鳴。"}]', 'phrasal verb'),
('key in', '鍵入；輸入', 'to type data into a system', '[{"en":"Please key in your order number to check the status.","zh-TW":"請輸入您的訂單號查詢狀態。"},{"en":"She keyed in the client information to the database.","zh-TW":"她將客戶資訊鍵入了資料庫。"}]', 'phrasal verb'),
('level up', '提升；升級', 'to improve skills or advance to a higher level', '[{"en":"The training programme helped the team level up.","zh-TW":"培訓計劃幫助團隊提升了技能。"},{"en":"She leveled up her project management skills online.","zh-TW":"她通過線上課程提升了專案管理技能。"}]', 'phrasal verb'),
('network with', '與…建立人脈；社交', 'to make professional connections with others', '[{"en":"She networked with industry leaders at the conference.","zh-TW":"她在會議上與業界領袖建立了人脈。"},{"en":"Always take opportunities to network with peers.","zh-TW":"一定要把握機會與同行建立人脈。"}]', 'phrasal verb'),
('open to', '對…持開放態度；願意接受', 'willing to consider or receive something', '[{"en":"We are open to feedback from all departments.","zh-TW":"我們對所有部門的反饋持開放態度。"},{"en":"She is open to new approaches to the problem.","zh-TW":"她願意接受解決問題的新方法。"}]', 'phrasal verb'),
('pencil in', '暫定安排；預先填入（行程）', 'to make a tentative arrangement for something', '[{"en":"Let us pencil in Thursday for a review meeting.","zh-TW":"讓我們暫定週四開審查會議。"},{"en":"She penciled in the conference dates for next quarter.","zh-TW":"她將下個季度的會議日期暫定填入了行程。"}]', 'phrasal verb'),
('press ahead', '繼續前進；堅持推進', 'to continue despite difficulties or opposition', '[{"en":"We will press ahead with the launch as planned.","zh-TW":"我們將按計劃繼續推進發布活動。"},{"en":"She pressed ahead despite the budget freeze.","zh-TW":"她在預算凍結的情況下堅持推進。"}]', 'phrasal verb'),
('refer to', '參考；稱呼為；轉介', 'to mention, consult, or direct to a source', '[{"en":"Please refer to the attached guidelines.","zh-TW":"請參考附件中的指引。"},{"en":"She referred the client to our technical support team.","zh-TW":"她將客戶轉介給我們的技術支援團隊。"}]', 'phrasal verb'),
('report to', '向…匯報；向…負責', 'to be answerable to a manager or authority', '[{"en":"The sales team reports to the regional director.","zh-TW":"銷售團隊向區域總監匯報。"},{"en":"She will report directly to the CEO in the new role.","zh-TW":"在新職位上她將直接向執行長匯報。"}]', 'phrasal verb'),
('ring up', '打電話給；合計（金額）', 'to make a phone call, or to record a sale amount', '[{"en":"Ring up the supplier and confirm the delivery date.","zh-TW":"打電話給供應商確認送貨日期。"},{"en":"The cashier rang up the total at the counter.","zh-TW":"收銀員在櫃台計算了總金額。"}]', 'phrasal verb'),
('at face value', '按字面意思；不加懷疑地', 'accepting something at its apparent meaning without questioning', '[{"en":"Do not take the offer at face value — read the fine print.","zh-TW":"不要不加懷疑地接受報價——要仔細閱讀細則。"},{"en":"She accepted the report at face value without verification.","zh-TW":"她未加驗證就按字面接受了報告。"}]', 'expression'),
('ahead of the game', '領先一步；優於競爭對手', 'more advanced or prepared than others', '[{"en":"Early investment kept us ahead of the game.","zh-TW":"早期投資讓我們領先一步。"},{"en":"She stayed ahead of the game by attending industry events.","zh-TW":"她透過參加業界活動保持領先地位。"}]', 'expression'),
('bite the hand that feeds you', '恩將仇報；傷害支持者', 'to harm or act against those who support you', '[{"en":"Publicly criticizing your main client is biting the hand that feeds you.","zh-TW":"公開批評主要客戶是恩將仇報。"},{"en":"He bit the hand that fed him by leaking company secrets.","zh-TW":"他洩露公司機密是恩將仇報。"}]', 'expression'),
('chain of command', '指揮系統；層級體制', 'the hierarchy of authority through which orders are passed', '[{"en":"Always follow the chain of command when escalating issues.","zh-TW":"升級問題時一定要遵循指揮系統。"},{"en":"The chain of command was unclear during the transition.","zh-TW":"過渡期間指揮系統不清晰。"}]', 'expression'),
('cost-effective', '具有成本效益；划算', 'providing good value relative to cost', '[{"en":"Outsourcing is a cost-effective solution for small teams.","zh-TW":"外包對小型團隊來說是具有成本效益的解決方案。"},{"en":"We chose the most cost-effective supplier.","zh-TW":"我們選擇了最具成本效益的供應商。"}]', 'expression'),
('due diligence', '盡職調查；謹慎調查', 'the investigation of a business or investment before commitment', '[{"en":"We conducted thorough due diligence before the acquisition.","zh-TW":"我們在收購前進行了徹底的盡職調查。"},{"en":"Due diligence revealed several financial irregularities.","zh-TW":"盡職調查發現了幾處財務不規則事項。"}]', 'expression'),
('economies of scale', '規模經濟；大規模生產的成本優勢', 'cost advantages gained from increased production volume', '[{"en":"Larger companies benefit from economies of scale.","zh-TW":"較大的公司從規模經濟中受益。"},{"en":"To compete we must achieve economies of scale.","zh-TW":"為了競爭我們必須實現規模經濟。"}]', 'expression'),
('exit strategy', '退出策略', 'a plan for leaving a business or investment position', '[{"en":"Before investing consider your exit strategy.","zh-TW":"在投資前考慮好你的退出策略。"},{"en":"The founders had no exit strategy when the market shifted.","zh-TW":"市場轉變時創辦人沒有退出策略。"}]', 'expression'),
('first mover advantage', '先行者優勢', 'the benefit gained by being first in a market or industry', '[{"en":"We gained first mover advantage by launching early.","zh-TW":"我們透過早期推出獲得了先行者優勢。"},{"en":"First mover advantage is critical in technology markets.","zh-TW":"在技術市場先行者優勢至關重要。"}]', 'expression'),
('flat organizational structure', '扁平組織架構', 'a hierarchy with few management levels', '[{"en":"A flat organizational structure improves communication.","zh-TW":"扁平組織架構改善了溝通。"},{"en":"The startup adopted a flat structure from the beginning.","zh-TW":"這家新創公司從一開始就採用了扁平結構。"}]', 'expression'),
('have second thoughts', '再三考慮；猶豫', 'to reconsider a decision; to have doubts', '[{"en":"She had second thoughts about accepting the role.","zh-TW":"她對是否接受這個職位再三考慮。"},{"en":"The client had second thoughts after reviewing the contract.","zh-TW":"客戶審閱合同後產生了猶豫。"}]', 'expression'),
('hit the headlines', '成為頭條；引起廣泛關注', 'to receive prominent media coverage', '[{"en":"The product launch hit the headlines globally.","zh-TW":"產品發布成為全球頭條新聞。"},{"en":"The company hit the headlines after the data breach.","zh-TW":"數據洩露後公司成為了頭條新聞。"}]', 'expression'),
('level playing field', '公平競爭環境', 'a situation where everyone has an equal chance', '[{"en":"New regulations create a level playing field for all businesses.","zh-TW":"新法規為所有企業創造了公平競爭環境。"},{"en":"We advocate for a level playing field in the industry.","zh-TW":"我們倡導行業內的公平競爭環境。"}]', 'expression'),
('keep pace with', '跟上；跟上步伐', 'to move or develop at the same speed as', '[{"en":"It is challenging to keep pace with technology changes.","zh-TW":"跟上技術變革是一大挑戰。"},{"en":"We invest in training to keep pace with industry developments.","zh-TW":"我們投資培訓以跟上行業發展。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('make a difference', '產生影響；有所作為', 'to have a significant effect or impact', '[{"en":"Good leadership makes a real difference to team morale.","zh-TW":"好的領導力對團隊士氣產生真正的影響。"},{"en":"We believe our product makes a difference to users'' lives.","zh-TW":"我們相信我們的產品對用戶的生活有所改變。"}]', 'expression'),
('no-brainer', '顯而易見的決定；不假思索的選擇', 'a decision or choice that is obviously correct', '[{"en":"With these savings it is a no-brainer to switch suppliers.","zh-TW":"有了這些節省換供應商是顯而易見的選擇。"},{"en":"Investing in training is a no-brainer.","zh-TW":"投資培訓是理所當然的選擇。"}]', 'expression'),
('once in a blue moon', '難得一見；偶爾', 'very rarely; only occasionally', '[{"en":"Opportunities like this come once in a blue moon.","zh-TW":"像這樣的機會難得一見。"},{"en":"We get a client like that once in a blue moon.","zh-TW":"我們難得遇到這樣的客戶。"}]', 'expression'),
('out of the question', '不可能；絕對不行', 'completely impossible or not permissible', '[{"en":"A budget increase is out of the question this year.","zh-TW":"今年增加預算絕對不可能。"},{"en":"Meeting that deadline is out of the question.","zh-TW":"趕上那個截止日期是不可能的。"}]', 'expression'),
('par excellence', '首屈一指；卓越的', 'better than all others of the same kind; supreme', '[{"en":"She is a communicator par excellence.","zh-TW":"她是首屈一指的溝通者。"},{"en":"This is innovation par excellence in the industry.","zh-TW":"這是業界卓越的創新典範。"}]', 'expression'),
('pick someone''s brain', '請教某人；請某人獻策', 'to ask someone for ideas or information based on their knowledge', '[{"en":"Can I pick your brain about the market strategy?","zh-TW":"我能請教你關於市場策略的想法嗎？"},{"en":"She picked his brain for insights on the Asian market.","zh-TW":"她請教他關於亞洲市場的見解。"}]', 'expression'),
('regardless of the circumstances', '不論情況如何', 'no matter what the situation may be', '[{"en":"Quality must be maintained regardless of the circumstances.","zh-TW":"不論情況如何品質都必須維持。"},{"en":"We deliver on time regardless of the circumstances.","zh-TW":"不論情況如何我們都準時交付。"}]', 'prepositional phrase'),
('in the short run', '短期而言；在短期內', 'over a brief time period; in the near future', '[{"en":"In the short run costs will rise after the change.","zh-TW":"短期而言變革後成本會上升。"},{"en":"These measures help in the short run but not long term.","zh-TW":"這些措施短期有效但長期不夠。"}]', 'prepositional phrase'),
('at a loss', '不知所措；虧損', 'uncertain what to do, or selling below cost', '[{"en":"After the failed pilot she was at a loss for next steps.","zh-TW":"試點失敗後她不知道下一步該怎麼辦。"},{"en":"We cannot afford to sell at a loss.","zh-TW":"我們不能虧本銷售。"}]', 'prepositional phrase'),
('to good effect', '有效地；達到良好效果', 'with a positive and noticeable result', '[{"en":"She used humor to good effect to ease the tension.","zh-TW":"她有效地運用幽默緩解了緊張氣氛。"},{"en":"The new software was deployed to good effect.","zh-TW":"新軟體被有效部署並達到了良好效果。"}]', 'prepositional phrase'),
('in a nutshell', '簡言之；簡而言之', 'in a brief and concise summary', '[{"en":"In a nutshell our strategy is to focus on quality.","zh-TW":"簡言之我們的策略是專注於品質。"},{"en":"Can you explain the issue in a nutshell?","zh-TW":"你能簡而言之地解釋一下這個問題嗎？"}]', 'prepositional phrase'),
('with the aim of', '以…為目的；旨在', 'with the purpose or intention of achieving something', '[{"en":"We are restructuring with the aim of improving efficiency.","zh-TW":"我們正在重組旨在提高效率。"},{"en":"With the aim of reducing costs we reviewed all contracts.","zh-TW":"以降低成本為目的我們審查了所有合同。"}]', 'prepositional phrase'),
('in terms of reference', '就職責範圍而言；依照職權範圍', 'within the boundaries of a defined scope or mandate', '[{"en":"The committee acts within its terms of reference.","zh-TW":"委員會在其職責範圍內行事。"},{"en":"This falls outside our terms of reference.","zh-TW":"這超出了我們的職責範圍。"}]', 'prepositional phrase'),
('in one''s capacity as', '以…的身份', 'in the role or position of a particular function', '[{"en":"In her capacity as CFO she approved the budget.","zh-TW":"以財務長的身份她批准了預算。"},{"en":"In his capacity as legal counsel he reviewed the contract.","zh-TW":"以法律顧問的身份他審查了合同。"}]', 'prepositional phrase'),
('as a token of', '作為…的表示；作為紀念', 'as a symbolic gesture expressing something', '[{"en":"As a token of appreciation we sent gifts to all clients.","zh-TW":"作為感謝的表示我們向所有客戶送了禮品。"},{"en":"The discount was offered as a token of goodwill.","zh-TW":"折扣是作為善意的表示提供的。"}]', 'prepositional phrase'),
('against all odds', '克服重重困難；不顧一切', 'despite very low chances of success', '[{"en":"Against all odds the startup became a market leader.","zh-TW":"克服重重困難這家新創公司成為了市場領導者。"},{"en":"She completed the project against all odds.","zh-TW":"她不顧一切完成了這個專案。"}]', 'prepositional phrase'),
('at the mercy of', '任由…擺布；受制於', 'entirely dependent on or vulnerable to something', '[{"en":"Small farmers are at the mercy of global price fluctuations.","zh-TW":"小農戶任由全球價格波動擺布。"},{"en":"Without a contract we are at the mercy of the supplier.","zh-TW":"沒有合同我們受制於供應商。"}]', 'prepositional phrase'),
('on equal terms', '在平等條件下；平起平坐', 'having the same position or conditions as others', '[{"en":"Smaller firms cannot always compete on equal terms.","zh-TW":"小公司不總是能在平等條件下競爭。"},{"en":"We want to negotiate on equal terms.","zh-TW":"我們希望在平等條件下進行談判。"}]', 'prepositional phrase'),
('in a timely manner', '及時地；迅速地', 'done at a suitable or efficient time', '[{"en":"All requests must be processed in a timely manner.","zh-TW":"所有請求都必須及時處理。"},{"en":"The team delivered results in a timely manner.","zh-TW":"團隊及時交付了結果。"}]', 'prepositional phrase'),
('with due respect', '恕我直言；請恕我冒昧', 'used politely before expressing disagreement', '[{"en":"With due respect I disagree with this assessment.","zh-TW":"恕我直言我不同意這個評估。"},{"en":"With due respect there are flaws in the proposal.","zh-TW":"恕我冒昧提案中存在缺陷。"}]', 'prepositional phrase'),
('at the bottom of', '在…的底部；是…的根本原因', 'the real or fundamental cause of something', '[{"en":"Poor planning is at the bottom of all these delays.","zh-TW":"規劃不當是所有這些延誤的根本原因。"},{"en":"What is really at the bottom of the conflict?","zh-TW":"這場衝突的真正根本原因是什麼？"}]', 'prepositional phrase'),
('to no avail', '徒勞無益；無濟於事', 'without success; making no difference', '[{"en":"We tried to contact them but to no avail.","zh-TW":"我們試圖聯繫他們但徒勞無益。"},{"en":"The marketing push drove traffic but to no avail on conversions.","zh-TW":"行銷推廣帶來了流量但在轉化方面無濟於事。"}]', 'prepositional phrase'),
('with immediate effect', '即時生效；立即執行', 'starting right away; with no delay', '[{"en":"The new policy takes effect with immediate effect.","zh-TW":"新政策即時生效。"},{"en":"His resignation was accepted with immediate effect.","zh-TW":"他的辭呈即時生效被接受。"}]', 'prepositional phrase'),
('from rags to riches', '白手起家；從一窮二白到富貴', 'going from poverty to wealth through hard work or luck', '[{"en":"The founder went from rags to riches in ten years.","zh-TW":"這位創辦人在十年內白手起家。"},{"en":"Her from rags to riches story inspires many entrepreneurs.","zh-TW":"她白手起家的故事激勵了許多創業者。"}]', 'business idiom'),
('get the big picture', '把握全局；了解整體情況', 'to understand the overall situation or main point', '[{"en":"To make good decisions you need to get the big picture.","zh-TW":"要做出好決策你需要把握全局。"},{"en":"She always gets the big picture before diving into details.","zh-TW":"她總是先把握全局再深入細節。"}]', 'business idiom'),
('go down the drain', '付諸東流；浪費', 'to be wasted or to go to waste', '[{"en":"Without follow-through all that effort went down the drain.","zh-TW":"沒有跟進所有的努力都付諸東流了。"},{"en":"The failed deal sent months of work down the drain.","zh-TW":"交易失敗讓幾個月的工作付諸東流。"}]', 'business idiom'),
('go from strength to strength', '蒸蒸日上；持續進步', 'to continue to improve or become more successful', '[{"en":"The company has gone from strength to strength since the pivot.","zh-TW":"自從轉型後公司蒸蒸日上。"},{"en":"She has gone from strength to strength in her career.","zh-TW":"她的職業生涯持續進步。"}]', 'business idiom'),
('high-octane', '高效能的；充滿活力的', 'very energetic, powerful, or intense', '[{"en":"Working in a startup is a high-octane experience.","zh-TW":"在新創公司工作是充滿活力的體驗。"},{"en":"The sales floor is a high-octane environment.","zh-TW":"銷售樓層是一個高效能的環境。"}]', 'business idiom'),
('move the goalposts', '改變標準；臨時更改要求', 'to change requirements or expectations after the fact', '[{"en":"Clients who keep moving the goalposts delay delivery.","zh-TW":"不斷改變要求的客戶會延誤交付。"},{"en":"Management moved the goalposts after we met the target.","zh-TW":"我們達成目標後管理層臨時更改了要求。"}]', 'business idiom'),
('new kid on the block', '新入場者；新的競爭者', 'a newcomer to a field or industry', '[{"en":"As the new kid on the block we had to prove ourselves.","zh-TW":"作為新入場者我們必須證明自己的實力。"},{"en":"The new startup is the new kid on the block disrupting the market.","zh-TW":"這家新創公司是顛覆市場的新入場者。"}]', 'business idiom'),
('over and above', '超出；不僅如此', 'in addition to or exceeding the standard amount or expectation', '[{"en":"She delivered results over and above what was asked.","zh-TW":"她交付的成果超出了要求。"},{"en":"The bonus was paid over and above the base salary.","zh-TW":"獎金是在基本薪資之外額外支付的。"}]', 'business idiom'),
('raise capital', '籌集資金', 'to gather funding for a business or project', '[{"en":"The founder traveled worldwide to raise capital.","zh-TW":"創辦人走遍全球籌集資金。"},{"en":"Raising capital requires a solid business plan.","zh-TW":"籌集資金需要有扎實的商業計劃。"}]', 'business idiom'),
('reinvent the wheel', '多此一舉；重複造車輪', 'to waste time creating something that already exists', '[{"en":"Use existing templates — there is no need to reinvent the wheel.","zh-TW":"使用現有範本——沒有必要重複造車輪。"},{"en":"They reinvented the wheel instead of adopting proven solutions.","zh-TW":"他們多此一舉而不採用成熟的解決方案。"}]', 'business idiom'),
('rule of thumb', '經驗法則', 'a practical general principle based on experience', '[{"en":"As a rule of thumb budget 10% for unexpected costs.","zh-TW":"根據經驗法則為意外費用預留10%的預算。"},{"en":"Our rule of thumb is to respond within 24 hours.","zh-TW":"我們的經驗法則是在24小時內回覆。"}]', 'business idiom'),
('run circles around', '遠勝於；輕而易舉地超越', 'to perform much better than someone else', '[{"en":"Our new system runs circles around the old one.","zh-TW":"我們的新系統遠勝於舊系統。"},{"en":"She runs circles around her peers in sales numbers.","zh-TW":"她在銷售數字上輕而易舉地超越了同儕。"}]', 'business idiom'),
('short-term gain', '短期收益', 'a benefit achieved quickly but possibly at the expense of future gain', '[{"en":"Do not sacrifice quality for short-term gain.","zh-TW":"不要為了短期收益而犧牲品質。"},{"en":"The short-term gain was not worth the long-term loss.","zh-TW":"短期收益不值得長期損失。"}]', 'business idiom'),
('silver lining', '塞翁失馬之福；壞事中的好處', 'a positive aspect of a difficult situation', '[{"en":"The silver lining is that we learned from the failure.","zh-TW":"壞事中的好處是我們從失敗中學到了東西。"},{"en":"She found a silver lining in every setback.","zh-TW":"她在每次挫折中都找到了塞翁失馬之福。"}]', 'business idiom'),
('stop the bleeding', '止損；阻止惡化', 'to prevent further losses or damage', '[{"en":"The first priority is to stop the bleeding on losses.","zh-TW":"首要任務是止損。"},{"en":"Cost controls were put in place to stop the bleeding.","zh-TW":"成本控制措施被實施以阻止虧損惡化。"}]', 'business idiom'),
('sustainable growth', '可持續增長', 'growth that can be maintained over time without depleting resources', '[{"en":"We focus on sustainable growth rather than rapid expansion.","zh-TW":"我們專注於可持續增長而非快速擴張。"},{"en":"Sustainable growth requires investment in quality and people.","zh-TW":"可持續增長需要在品質和人才上投資。"}]', 'business idiom'),
('take a rain check', '改天再說；暫時婉拒', 'to postpone an offer or invitation to a later time', '[{"en":"Can I take a rain check on the lunch? I have a conflict.","zh-TW":"我能改天再吃午餐嗎？我有衝突。"},{"en":"She took a rain check on the seminar for next month.","zh-TW":"她把研討會推到了下個月。"}]', 'business idiom'),
('talk the talk and walk the walk', '言行一致；說到做到', 'to back up words with actions', '[{"en":"Great leaders talk the talk and walk the walk.","zh-TW":"優秀的領導者言行一致。"},{"en":"If you promote innovation you must walk the walk.","zh-TW":"如果你倡導創新你必須說到做到。"}]', 'business idiom'),
('run with', '大力推進；採納並執行', 'to proceed enthusiastically with an idea or plan', '[{"en":"She ran with the concept and developed it into a product.","zh-TW":"她大力推進這個概念並將其發展成產品。"},{"en":"Once approved we ran with the project.","zh-TW":"獲批後我們全力推進這個專案。"}]', 'phrasal verb'),
('sell on', '說服；繼續銷售', 'to convince someone of the value of something', '[{"en":"He sold the board on the new direction.","zh-TW":"他說服董事會接受了新方向。"},{"en":"Can you sell the client on upgrading their plan?","zh-TW":"你能說服客戶升級他們的方案嗎？"}]', 'phrasal verb'),
('settle on', '決定；選定', 'to choose or make a final decision about something', '[{"en":"We finally settled on a design after weeks of review.","zh-TW":"幾週審查後我們終於選定了一個設計。"},{"en":"Have you settled on a vendor yet?","zh-TW":"你決定好供應商了嗎？"}]', 'phrasal verb'),
('sign on', '簽約加入；同意合作', 'to commit formally to a job or project', '[{"en":"Three new sponsors signed on for the event.","zh-TW":"三個新贊助商簽約參加了這次活動。"},{"en":"She signed on as a consultant for the project.","zh-TW":"她以顧問身份簽約加入了專案。"}]', 'phrasal verb'),
('snap up', '搶購；迅速把握機會', 'to buy or take something quickly before others can', '[{"en":"Investors snapped up shares at the lower price.","zh-TW":"投資者以較低價格搶購了股票。"},{"en":"The company snapped up top talent from competitors.","zh-TW":"公司從競爭對手那裡搶到了頂尖人才。"}]', 'phrasal verb'),
('square away', '處理好；安排妥當', 'to settle or organize something completely', '[{"en":"Let me square away the remaining details.","zh-TW":"讓我把剩餘的細節都處理好。"},{"en":"Once logistics are squared away we can proceed.","zh-TW":"物流安排妥當後我們就可以繼續了。"}]', 'phrasal verb'),
('steer toward', '引導朝向；轉向', 'to guide or direct toward a particular direction', '[{"en":"She steered the company toward digital transformation.","zh-TW":"她引導公司走向數位轉型。"},{"en":"He steered the team toward a more innovative approach.","zh-TW":"他引導團隊朝向更具創新性的方式發展。"}]', 'phrasal verb'),
('supply with', '供應；提供給', 'to provide with goods or materials', '[{"en":"We supply the factory with raw materials monthly.","zh-TW":"我們每月向工廠提供原材料。"},{"en":"The vendor supplied us with high-quality components.","zh-TW":"供應商為我們提供了高品質零件。"}]', 'phrasal verb'),
('sustain with', '維持；以…支撐', 'to maintain or keep alive with resources or support', '[{"en":"We sustain operations with strong cash flow.","zh-TW":"我們以強健的現金流維持運作。"},{"en":"Innovation sustains the business through changes.","zh-TW":"創新使業務在變化中得以維持。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('switch over', '切換；轉換到', 'to change from one system or activity to another', '[{"en":"We switched over to the cloud-based system last year.","zh-TW":"我們去年切換到了雲端系統。"},{"en":"It takes time to switch over from the old process.","zh-TW":"從舊流程轉換需要時間。"}]', 'phrasal verb'),
('target toward', '針對；以…為目標', 'to aim an effort or product at a specific group or goal', '[{"en":"The campaign is targeted toward young professionals.","zh-TW":"這次活動針對年輕專業人士。"},{"en":"We target our services toward mid-size enterprises.","zh-TW":"我們的服務以中型企業為目標。"}]', 'phrasal verb'),
('think ahead', '預先考慮；未雨綢繆', 'to consider future needs or plan in advance', '[{"en":"We need to think ahead and anticipate market shifts.","zh-TW":"我們需要預先考慮並預測市場轉變。"},{"en":"Good leaders always think ahead.","zh-TW":"好的領導者總是未雨綢繆。"}]', 'phrasal verb'),
('transition to', '過渡到；轉型至', 'to move gradually from one state or role to another', '[{"en":"She transitioned to a management position this year.","zh-TW":"她今年過渡到了管理職位。"},{"en":"The company is transitioning to a subscription model.","zh-TW":"公司正在轉型至訂閱模式。"}]', 'phrasal verb'),
('turn to', '求助於；轉向', 'to go to someone for help or to change to an alternative', '[{"en":"When issues arise she turns to her mentor.","zh-TW":"當出現問題時她向導師求助。"},{"en":"The company turned to outsourcing to reduce costs.","zh-TW":"公司轉向外包以降低成本。"}]', 'phrasal verb'),
('update on', '更新；告知最新情況', 'to provide the latest information about something', '[{"en":"Please update me on the project status.","zh-TW":"請告知我專案的最新狀態。"},{"en":"She updated the team on the client''s requirements.","zh-TW":"她向團隊通報了客戶的最新需求。"}]', 'phrasal verb'),
('veer away from', '偏離；避開', 'to change direction away from something', '[{"en":"The discussion veered away from the agenda.","zh-TW":"討論偏離了議程。"},{"en":"She veered away from the risky option.","zh-TW":"她避開了風險較高的選項。"}]', 'phrasal verb'),
('validate against', '與…進行驗證；核對', 'to confirm accuracy by checking against a standard', '[{"en":"Please validate the figures against the source data.","zh-TW":"請將數字與源數據進行核對。"},{"en":"All results are validated against industry benchmarks.","zh-TW":"所有結果都與行業基準進行了驗證。"}]', 'phrasal verb'),
('walk through', '逐步說明；引導完成', 'to guide someone through a process step by step', '[{"en":"Let me walk you through the onboarding process.","zh-TW":"讓我逐步引導你完成入職流程。"},{"en":"She walked the client through the platform features.","zh-TW":"她逐步向客戶介紹了平台功能。"}]', 'phrasal verb'),
('yield to', '讓步；服從', 'to submit to pressure or give way to a superior force', '[{"en":"The company yielded to public pressure and revised the policy.","zh-TW":"公司在公眾壓力下讓步並修訂了政策。"},{"en":"She did not yield to the client''s unreasonable demands.","zh-TW":"她沒有屈服於客戶不合理的要求。"}]', 'phrasal verb'),
('put your best foot forward', '全力以赴；展現最佳狀態', 'to try as hard as possible to make a good impression', '[{"en":"Always put your best foot forward when meeting new clients.","zh-TW":"見新客戶時一定要全力以赴展現最佳狀態。"},{"en":"She put her best foot forward in the job interview.","zh-TW":"她在求職面試中展現了最佳狀態。"}]', 'expression'),
('put something into perspective', '以正確角度看待；客觀地評估', 'to consider something in a realistic way relative to other factors', '[{"en":"To put things into perspective our growth is still above average.","zh-TW":"以正確角度看待我們的增長仍高於平均水準。"},{"en":"She put the setback into perspective and moved forward.","zh-TW":"她客觀評估了挫折並繼續前進。"}]', 'expression'),
('raise the stakes', '提高賭注；加大風險或報酬', 'to increase the risks, importance, or rewards involved', '[{"en":"The acquisition raised the stakes for all competitors.","zh-TW":"這次收購提高了所有競爭者的賭注。"},{"en":"She raised the stakes by proposing a bolder strategy.","zh-TW":"她提出更大膽的策略提高了賭注。"}]', 'expression'),
('read the room', '察言觀色；感受現場氣氛', 'to assess the mood or expectations of others in a situation', '[{"en":"A good presenter reads the room and adjusts accordingly.","zh-TW":"優秀的演講者能察言觀色並相應調整。"},{"en":"He failed to read the room and misjudged the tone.","zh-TW":"他未能察言觀色並誤判了氣氛。"}]', 'expression'),
('rock the boat', '惹是生非；打破現狀', 'to cause trouble or upset a stable situation', '[{"en":"He was afraid to rock the boat by suggesting changes.","zh-TW":"他害怕提出改變建議而惹是生非。"},{"en":"Sometimes you need to rock the boat to drive improvement.","zh-TW":"有時你需要打破現狀來推動改進。"}]', 'expression'),
('smooth sailing', '一帆風順；順利進行', 'a situation where things proceed without difficulty', '[{"en":"After the initial phase it was smooth sailing.","zh-TW":"初期階段後一切一帆風順。"},{"en":"Getting the first client was tough but smooth sailing after that.","zh-TW":"獲得第一個客戶很艱難但之後就一帆風順了。"}]', 'expression'),
('step up to the plate', '挺身而出；承擔責任', 'to take on responsibility or rise to a challenge', '[{"en":"The team stepped up to the plate during the crisis.","zh-TW":"危機期間團隊挺身而出。"},{"en":"She stepped up to the plate when no one else would.","zh-TW":"她在沒有人願意的情況下挺身而出。"}]', 'expression'),
('swim against the tide', '逆流而上；反潮流', 'to go against the majority opinion or trend', '[{"en":"The brand swims against the tide by focusing on traditional methods.","zh-TW":"這個品牌通過專注於傳統方法逆流而上。"},{"en":"She swam against the tide and predicted the market correctly.","zh-TW":"她逆潮流而上並準確預測了市場走向。"}]', 'expression'),
('take it one step at a time', '一步一步來；循序漸進', 'to deal with things gradually and without rushing', '[{"en":"With such a complex project we should take it one step at a time.","zh-TW":"面對如此複雜的專案我們應該一步一步來。"},{"en":"Take it one step at a time and do not get overwhelmed.","zh-TW":"循序漸進不要因此感到不知所措。"}]', 'expression'),
('the writing is on the wall', '大難將至；徵兆已現', 'signs that something bad is about to happen are obvious', '[{"en":"The writing was on the wall when revenues fell three quarters in a row.","zh-TW":"連續三個季度收入下降時徵兆已現。"},{"en":"Many employees saw the writing on the wall before the layoffs.","zh-TW":"許多員工在裁員前就看到了大難將至的跡象。"}]', 'expression'),
('throw money at the problem', '砸錢解決問題；用金錢代替策略', 'to try to resolve a problem by spending money rather than fixing the cause', '[{"en":"You cannot just throw money at this problem — you need a strategy.","zh-TW":"你不能只是砸錢解決問題——你需要一個策略。"},{"en":"They threw money at the issue without diagnosing the root cause.","zh-TW":"他們未診斷根本原因就砸錢試圖解決問題。"}]', 'expression'),
('tread carefully', '謹慎行事；小心翼翼', 'to proceed with great caution', '[{"en":"Tread carefully when discussing sensitive topics with clients.","zh-TW":"與客戶討論敏感話題時要謹慎行事。"},{"en":"She tread carefully when delivering bad news.","zh-TW":"她在傳達壞消息時小心翼翼。"}]', 'expression'),
('turn a blind eye', '視而不見；裝作不知道', 'to deliberately ignore something problematic', '[{"en":"Management turned a blind eye to the compliance issues.","zh-TW":"管理層對合規問題視而不見。"},{"en":"Do not turn a blind eye to workplace misconduct.","zh-TW":"不要對職場不當行為裝作不知道。"}]', 'expression'),
('two sides of the same coin', '一體兩面；相互關聯的兩個方面', 'two things that seem different but are closely related', '[{"en":"Risk and opportunity are two sides of the same coin.","zh-TW":"風險和機會是一體兩面。"},{"en":"Customer satisfaction and profitability are two sides of the same coin.","zh-TW":"客戶滿意度和盈利能力是一體兩面。"}]', 'expression'),
('up the ante', '提高賭注；加大投入', 'to increase the stakes or demands in a situation', '[{"en":"The competitor upped the ante with aggressive pricing.","zh-TW":"競爭對手以積極的定價提高了賭注。"},{"en":"She upped the ante by proposing a 20% cost reduction.","zh-TW":"她提出20%成本降低要求加大了籌碼。"}]', 'expression'),
('fall on deaf ears', '充耳不聞；被忽視', 'to be heard but ignored or have no effect', '[{"en":"His concerns about quality fell on deaf ears.","zh-TW":"他對品質的擔憂充耳不聞。"},{"en":"The team''s suggestions fell on deaf ears.","zh-TW":"團隊的建議被忽視了。"}]', 'expression'),
('get your ducks in a row', '做好充分準備；安排妥當', 'to organize things properly before taking action', '[{"en":"Before the meeting get your ducks in a row.","zh-TW":"會議前做好充分準備。"},{"en":"We need to get our ducks in a row before the product launch.","zh-TW":"在產品發布前我們需要安排妥當。"}]', 'expression'),
('have the upper hand', '佔上風；處於優勢', 'to be in a position of advantage over others', '[{"en":"With better data we had the upper hand in the negotiation.","zh-TW":"有了更好的數據我們在談判中佔了上風。"},{"en":"Early movers have the upper hand in new markets.","zh-TW":"早期進入者在新市場中處於優勢地位。"}]', 'expression'),
('hit the spot', '正合心意；完全符合需求', 'to be exactly right or to satisfy a need perfectly', '[{"en":"That solution really hit the spot for the client.","zh-TW":"那個解決方案完全符合客戶的需求。"},{"en":"The new design hits the spot in terms of user experience.","zh-TW":"新設計在用戶體驗方面完全符合需求。"}]', 'expression'),
('lay the groundwork', '奠定基礎；打下基礎', 'to do the preparatory work for something in the future', '[{"en":"The pilot programme laid the groundwork for full rollout.","zh-TW":"試點計劃為全面推出奠定了基礎。"},{"en":"She spent months laying the groundwork for the merger.","zh-TW":"她花了幾個月為合併打下基礎。"}]', 'expression'),
('in the event that', '萬一；如果發生的話', 'if a particular situation should happen', '[{"en":"In the event that the delivery is late please inform us.","zh-TW":"萬一送貨延誤請告知我們。"},{"en":"In the event that the merger fails we have a backup plan.","zh-TW":"如果合併失敗我們有備選計劃。"}]', 'prepositional phrase'),
('pending approval', '待批准；等待批准', 'waiting for official authorization', '[{"en":"The project is on hold pending approval.","zh-TW":"專案暫停等待批准。"},{"en":"Pending approval from the board we can begin.","zh-TW":"等待董事會批准後我們即可開始。"}]', 'prepositional phrase'),
('under the auspices of', '在…的主持下；由…贊助', 'with the support or sponsorship of an organization', '[{"en":"The conference was held under the auspices of the UN.","zh-TW":"會議在聯合國的主持下舉行。"},{"en":"The project operates under the auspices of the government.","zh-TW":"該項目在政府的主持下運作。"}]', 'prepositional phrase'),
('with a grain of salt', '保留懷疑態度；半信半疑地', 'with some skepticism or caution', '[{"en":"Take the competitor''s claims with a grain of salt.","zh-TW":"對競爭對手的聲明要保留懷疑態度。"},{"en":"Initial sales projections should be taken with a grain of salt.","zh-TW":"初步銷售預測應該半信半疑。"}]', 'prepositional phrase'),
('off the top of one''s head', '不假思索地；憑印象', 'from memory without careful thought or research', '[{"en":"Off the top of my head I would estimate 50 units.","zh-TW":"憑我的印象我估計是50個單位。"},{"en":"She answered off the top of her head in the meeting.","zh-TW":"她在會議中不假思索地回答了問題。"}]', 'prepositional phrase'),
('on the premise that', '以…為前提；假設', 'based on the assumption that something is true', '[{"en":"On the premise that demand grows we are expanding.","zh-TW":"以需求增長為前提我們正在擴張。"},{"en":"We planned on the premise that budgets would not be cut.","zh-TW":"我們以預算不會被削減為前提進行規劃。"}]', 'prepositional phrase'),
('in the pipeline for', '即將推出；在籌備中', 'being prepared or planned for future release', '[{"en":"We have several updates in the pipeline for next quarter.","zh-TW":"我們有幾個更新正在籌備中將於下季度推出。"},{"en":"New features are in the pipeline for the platform.","zh-TW":"新功能正在為平台籌備中。"}]', 'prepositional phrase'),
('at the helm of', '掌舵；領導', 'in control of or leading an organization or team', '[{"en":"She has been at the helm of the company for six years.","zh-TW":"她已掌舵公司六年了。"},{"en":"With an experienced CEO at the helm the company thrived.","zh-TW":"在有經驗的執行長掌舵下公司蓬勃發展。"}]', 'prepositional phrase'),
('by mutual agreement', '經雙方同意；互相協議', 'with the consent of all involved parties', '[{"en":"The contract was terminated by mutual agreement.","zh-TW":"合同經雙方同意終止了。"},{"en":"By mutual agreement the meeting was rescheduled.","zh-TW":"經雙方同意會議重新安排了時間。"}]', 'prepositional phrase'),
('at the behest of', '在…的要求下；奉…之命', 'at the instruction or request of someone in authority', '[{"en":"At the behest of the board the audit was launched.","zh-TW":"在董事會的要求下審計啟動了。"},{"en":"At the behest of the client we revised the proposal.","zh-TW":"奉客戶之命我們修改了提案。"}]', 'prepositional phrase'),
('to the letter', '嚴格按照；一字不差地', 'following instructions or rules exactly and precisely', '[{"en":"We follow the safety protocol to the letter.","zh-TW":"我們嚴格按照安全規程執行。"},{"en":"The contract must be executed to the letter.","zh-TW":"合同必須一字不差地執行。"}]', 'prepositional phrase'),
('in pursuit of excellence', '追求卓越', 'in the effort to achieve the highest possible standards', '[{"en":"In pursuit of excellence we never stop improving.","zh-TW":"在追求卓越的過程中我們永不停止改進。"},{"en":"The team operates in pursuit of excellence in every project.","zh-TW":"團隊在每個專案中都追求卓越。"}]', 'prepositional phrase'),
('on a case-by-case basis', '逐案處理；按具體情況', 'dealing with each situation individually as it arises', '[{"en":"Exceptions will be handled on a case-by-case basis.","zh-TW":"例外情況將逐案處理。"},{"en":"Pricing is negotiated on a case-by-case basis.","zh-TW":"定價按具體情況協商。"}]', 'prepositional phrase'),
('in an advisory capacity', '以顧問身份', 'in a role providing guidance without decision-making power', '[{"en":"She joined the board in an advisory capacity.","zh-TW":"她以顧問身份加入了董事會。"},{"en":"The expert served in an advisory capacity throughout the project.","zh-TW":"專家在整個專案中以顧問身份提供服務。"}]', 'prepositional phrase'),
('in preparation for', '為…做準備；準備期間', 'in readiness or anticipation of something', '[{"en":"We held workshops in preparation for the product launch.","zh-TW":"我們舉辦了研討會為產品發布做準備。"},{"en":"In preparation for the audit all records were organized.","zh-TW":"為審計做準備所有記錄都整理好了。"}]', 'prepositional phrase'),
('on the strength of the results', '憑借結果；依據成效', 'justified or supported by the performance achieved', '[{"en":"On the strength of the results we received more funding.","zh-TW":"憑借成效我們獲得了更多資金。"},{"en":"Further contracts were awarded on the strength of the results.","zh-TW":"依據成效我們獲得了進一步的合同。"}]', 'prepositional phrase'),
('commensurate with', '與…相稱；成比例的', 'proportionate or matching in size, quality, or value', '[{"en":"Compensation is commensurate with experience and skills.","zh-TW":"薪酬與經驗和技能相稱。"},{"en":"The role offers rewards commensurate with performance.","zh-TW":"該職位提供與績效相稱的獎酬。"}]', 'prepositional phrase'),
('throughout the duration of', '在整個期間；持續整個過程', 'during the entire length of time something takes', '[{"en":"Quality must be maintained throughout the duration of the contract.","zh-TW":"在整個合同期間必須保持品質。"},{"en":"She supported the team throughout the duration of the change.","zh-TW":"她在整個變革過程中支持了團隊。"}]', 'prepositional phrase'),
('net of', '扣除…後的淨額；不含', 'after deducting or excluding something', '[{"en":"Net of taxes the profit was quite healthy.","zh-TW":"扣除稅款後利潤相當健康。"},{"en":"Please report revenue net of refunds.","zh-TW":"請報告扣除退款後的淨收入。"}]', 'prepositional phrase'),
('a tall order', '難以完成的任務；要求過高', 'a demand or requirement that is difficult to achieve', '[{"en":"Completing the project in one week is a tall order.","zh-TW":"在一週內完成這個專案是難以實現的任務。"},{"en":"Satisfying every stakeholder is always a tall order.","zh-TW":"滿足每位利益相關者總是難以實現的要求。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('bang for the buck', '性價比；划算', 'value obtained relative to the money spent', '[{"en":"This software gives us great bang for the buck.","zh-TW":"這個軟體性價比非常高。"},{"en":"We want the best bang for the buck on our marketing spend.","zh-TW":"我們希望在行銷支出上獲得最高性價比。"}]', 'business idiom'),
('at the coal face', '在第一線；從事實際工作', 'doing the difficult, hands-on work directly', '[{"en":"Staff at the coal face see issues that managers miss.","zh-TW":"在第一線工作的員工看到了管理者忽略的問題。"},{"en":"Insights from those at the coal face are invaluable.","zh-TW":"來自第一線工作者的見解是無價的。"}]', 'business idiom'),
('bite off', '承擔過多；貪多嚼不爛', 'to take on more than can be handled', '[{"en":"We bit off more than we could chew with five projects at once.","zh-TW":"我們同時承擔五個專案貪多嚼不爛了。"},{"en":"Do not bite off more tasks than you can manage.","zh-TW":"不要承擔超出能力範圍的任務。"}]', 'business idiom'),
('blue chip', '績優；一流的', 'of the highest quality or most reliable type', '[{"en":"Blue chip clients bring stability to the business.","zh-TW":"績優客戶為業務帶來穩定性。"},{"en":"She only invests in blue chip companies.","zh-TW":"她只投資於一流公司。"}]', 'business idiom'),
('boots on the ground', '第一線人員；實地執行人員', 'staff actively working in the field rather than from an office', '[{"en":"We need boots on the ground in the Asian market.","zh-TW":"我們需要在亞洲市場有第一線人員。"},{"en":"Boots on the ground feedback is more reliable than surveys.","zh-TW":"第一線人員的反饋比調查更可靠。"}]', 'business idiom'),
('brain drain', '人才外流', 'the emigration or loss of educated or skilled workers', '[{"en":"Retaining talent prevents a brain drain.","zh-TW":"留住人才可以防止人才外流。"},{"en":"The company suffered a brain drain after the restructuring.","zh-TW":"重組後公司遭遇了人才外流。"}]', 'business idiom'),
('build bridges', '建立橋梁；促進溝通合作', 'to improve relationships between groups or departments', '[{"en":"The HR initiative helped build bridges between departments.","zh-TW":"人力資源計劃幫助建立了部門間的溝通橋梁。"},{"en":"She worked hard to build bridges with the new partners.","zh-TW":"她努力與新合作夥伴建立橋梁。"}]', 'business idiom'),
('burning the midnight oil', '挑燈夜戰；熬夜工作', 'working very late into the night to complete something', '[{"en":"The team was burning the midnight oil before the deadline.","zh-TW":"截止日期前團隊在挑燈夜戰。"},{"en":"She burned the midnight oil to prepare the pitch.","zh-TW":"她熬夜準備提案。"}]', 'business idiom'),
('can of worms', '棘手的問題；麻煩一堆', 'a situation that is complicated and causes many problems', '[{"en":"Changing that policy would open a can of worms.","zh-TW":"改變那項政策會引發一連串的麻煩。"},{"en":"The audit opened a can of worms.","zh-TW":"審計打開了一個棘手的局面。"}]', 'business idiom'),
('change of direction', '轉變方向；策略轉向', 'a significant shift in strategy or approach', '[{"en":"The company underwent a change of direction after the CEO changed.","zh-TW":"更換執行長後公司轉變了方向。"},{"en":"A change of direction was needed to stay competitive.","zh-TW":"為了保持競爭力需要轉變方向。"}]', 'business idiom'),
('commercial viability', '商業可行性', 'the ability of something to generate sufficient profit', '[{"en":"We evaluate the commercial viability of every new idea.","zh-TW":"我們評估每個新想法的商業可行性。"},{"en":"The project lacked commercial viability.","zh-TW":"這個專案缺乏商業可行性。"}]', 'business idiom'),
('competitive edge', '競爭優勢', 'an advantage that makes a company better than competitors', '[{"en":"Innovation gives us a competitive edge.","zh-TW":"創新給我們帶來了競爭優勢。"},{"en":"Our service quality is our competitive edge.","zh-TW":"我們的服務品質是我們的競爭優勢。"}]', 'business idiom'),
('conflict of interest', '利益衝突', 'a situation where personal interests clash with professional duties', '[{"en":"She declared a conflict of interest and recused herself.","zh-TW":"她宣布了利益衝突並迴避了投票。"},{"en":"Directors must avoid conflicts of interest.","zh-TW":"董事必須避免利益衝突。"}]', 'business idiom'),
('core competency', '核心競爭力', 'a company''s main strength or unique capability', '[{"en":"Our core competency is supply chain optimization.","zh-TW":"我們的核心競爭力是供應鏈優化。"},{"en":"Focusing on core competency drives long-term success.","zh-TW":"專注於核心競爭力推動長期成功。"}]', 'business idiom'),
('cost benefit analysis', '成本效益分析', 'a process of comparing the costs and benefits of a decision', '[{"en":"A cost benefit analysis supports our expansion decision.","zh-TW":"成本效益分析支持了我們的擴張決定。"},{"en":"Run a cost benefit analysis before investing.","zh-TW":"在投資前進行成本效益分析。"}]', 'business idiom'),
('cross the line', '越界；超出可接受範圍', 'to behave in a way that is unacceptable or unethical', '[{"en":"He crossed the line with his aggressive sales tactics.","zh-TW":"他的攻擊性銷售手法越界了。"},{"en":"The ad campaign crossed the line and was pulled.","zh-TW":"廣告活動越界後被撤回了。"}]', 'business idiom'),
('deliver on promises', '履行承諾；兌現諾言', 'to actually do what was promised or committed to', '[{"en":"We always deliver on our promises to clients.","zh-TW":"我們總是向客戶履行承諾。"},{"en":"A brand that delivers on promises builds loyalty.","zh-TW":"能履行承諾的品牌能建立忠誠度。"}]', 'business idiom'),
('zero out', '清零；歸零', 'to reduce to zero or remove completely from accounts', '[{"en":"The budget was zeroed out at year end.","zh-TW":"預算在年底被清零了。"},{"en":"She zeroed out the remaining inventory costs.","zh-TW":"她把剩餘庫存成本歸零了。"}]', 'phrasal verb'),
('draw on', '運用；借助；動用', 'to make use of a skill, resource, or experience', '[{"en":"She drew on her ten years of experience to solve the problem.","zh-TW":"她運用了十年的經驗來解決問題。"},{"en":"The company drew on its cash reserves during the downturn.","zh-TW":"經濟下滑期間公司動用了現金儲備。"}]', 'phrasal verb'),
('set out', '出發；設定；概述', 'to begin a task, or to present information in a structured way', '[{"en":"The report sets out the key findings.","zh-TW":"報告概述了關鍵發現。"},{"en":"We set out to expand our market share this year.","zh-TW":"我們今年出發去擴大市場份額。"}]', 'phrasal verb'),
('put pressure on', '向…施壓；給…壓力', 'to try to make someone do something by applying pressure', '[{"en":"Shareholders put pressure on management to improve returns.","zh-TW":"股東向管理層施壓要求提高回報。"},{"en":"Rising costs are putting pressure on profit margins.","zh-TW":"不斷上漲的成本正在給利潤率施壓。"}]', 'phrasal verb'),
('break into', '進入（新市場或行業）；闖入', 'to enter a new market or field successfully', '[{"en":"We are trying to break into the European market.","zh-TW":"我們正在嘗試進入歐洲市場。"},{"en":"Breaking into the luxury segment requires repositioning.","zh-TW":"進入高端市場需要重新定位。"}]', 'phrasal verb'),
('cash out', '套現；兌現', 'to convert an investment into cash or withdraw profits', '[{"en":"He cashed out his shares at the peak.","zh-TW":"他在股價高峰時套現了他的股份。"},{"en":"Some early investors cashed out after the IPO.","zh-TW":"部分早期投資者在IPO後套現了。"}]', 'phrasal verb'),
('walk away', '離開；放棄', 'to leave a situation or deal without reaching an agreement', '[{"en":"They walked away from the deal after negotiations broke down.","zh-TW":"談判破裂後他們放棄了這筆交易。"},{"en":"Sometimes it is better to walk away than accept bad terms.","zh-TW":"有時候放棄比接受不好的條款更明智。"}]', 'phrasal verb'),
('come up against', '遇到（困難或阻礙）', 'to encounter a problem or obstacle', '[{"en":"We came up against strong resistance from the local market.","zh-TW":"我們在本地市場遇到了強烈阻力。"},{"en":"The proposal came up against regulatory hurdles.","zh-TW":"提案遇到了監管障礙。"}]', 'phrasal verb'),
('bridge a gap', '彌合差距；縮短距離', 'to reduce the difference between two positions or groups', '[{"en":"This feature bridges a gap in user workflow.","zh-TW":"這個功能彌合了用戶工作流程中的差距。"},{"en":"Training helps bridge the gap between expectations and skills.","zh-TW":"培訓有助於彌合期望與技能之間的差距。"}]', 'phrasal verb'),
('cash in on', '藉機獲利；趁機利用', 'to take advantage of a situation for profit or benefit', '[{"en":"The company cashed in on the e-commerce boom.","zh-TW":"公司藉電商熱潮大幅獲利。"},{"en":"She cashed in on her expertise to land premium clients.","zh-TW":"她藉助自身專業知識爭取到了高端客戶。"}]', 'phrasal verb'),
('close down', '關閉；停業', 'to permanently stop operations or business', '[{"en":"The underperforming branch was closed down.","zh-TW":"表現不佳的分店被關閉了。"},{"en":"Factories closed down due to new environmental laws.","zh-TW":"由於新的環境法律工廠關閉了。"}]', 'phrasal verb'),
('cycle through', '循環；逐一處理', 'to go through a series of things in order', '[{"en":"We cycled through several vendors before deciding.","zh-TW":"我們逐一評估了幾家供應商後才做決定。"},{"en":"The system cycles through scenarios automatically.","zh-TW":"系統自動循環處理各種情況。"}]', 'phrasal verb'),
('dial back', '降低；收斂；減少', 'to reduce the level or intensity of something', '[{"en":"We need to dial back our growth expectations.","zh-TW":"我們需要降低增長預期。"},{"en":"She dialed back her tone in subsequent emails.","zh-TW":"她在後續電子郵件中降低了語氣強度。"}]', 'phrasal verb'),
('drive down', '壓低；降低', 'to reduce or lower costs, prices, or numbers', '[{"en":"Competition drives down prices over time.","zh-TW":"競爭會隨著時間推移壓低價格。"},{"en":"Automation helped drive down production costs.","zh-TW":"自動化幫助降低了生產成本。"}]', 'phrasal verb'),
('drive up', '推高；提高', 'to increase or raise costs, prices, or numbers', '[{"en":"Surging demand is driving up raw material costs.","zh-TW":"需求激增正在推高原材料成本。"},{"en":"Viral marketing drove up site traffic overnight.","zh-TW":"病毒式行銷在一夜之間推高了網站流量。"}]', 'phrasal verb'),
('firm up', '確定；使更穩固', 'to make something more definite or strengthen it', '[{"en":"Let us firm up the details before the next meeting.","zh-TW":"在下次會議前讓我們確定細節。"},{"en":"She firmed up the offer after the second interview.","zh-TW":"第二次面試後她確定了邀請。"}]', 'phrasal verb'),
('give rise to', '引起；導致；產生', 'to cause something to happen or come into existence', '[{"en":"The change in leadership gave rise to new strategies.","zh-TW":"領導層的更迭引發了新的策略。"},{"en":"Miscommunication can give rise to serious problems.","zh-TW":"溝通不良可能引發嚴重問題。"}]', 'phrasal verb'),
('hand back', '歸還；退還', 'to return something to its original owner or holder', '[{"en":"After the audit the documents were handed back.","zh-TW":"審計結束後文件被歸還了。"},{"en":"He handed back control of the project to the original team.","zh-TW":"他將專案控制權歸還給了原來的團隊。"}]', 'phrasal verb'),
('burn the candle at both ends', '日夜操勞；精力過度消耗', 'to work excessively hard, sleeping and resting very little', '[{"en":"He was burning the candle at both ends during the product launch.","zh-TW":"他在產品發布期間日夜操勞。"},{"en":"Burning the candle at both ends leads to burnout.","zh-TW":"日夜操勞最終會導致過勞。"}]', 'expression'),
('carry the day', '大獲全勝；贏得勝利', 'to win or succeed decisively in an argument or competition', '[{"en":"Her strong data carried the day in the board presentation.","zh-TW":"她強有力的數據在董事會簡報中大獲全勝。"},{"en":"Good preparation carried the day in the negotiation.","zh-TW":"充分準備贏得了談判的勝利。"}]', 'expression'),
('catch someone off guard', '出其不意；令人措手不及', 'to surprise someone who is unprepared', '[{"en":"The competitor''s announcement caught us off guard.","zh-TW":"競爭對手的公告讓我們措手不及。"},{"en":"Be prepared so clients cannot catch you off guard.","zh-TW":"要做好準備以免客戶讓你措手不及。"}]', 'expression'),
('change of heart', '改變主意；心意改變', 'a change in attitude or decision', '[{"en":"He had a change of heart and withdrew the proposal.","zh-TW":"他改變了主意並撤回了提案。"},{"en":"A change of heart led her to accept the offer.","zh-TW":"改變主意讓她接受了邀請。"}]', 'expression'),
('come clean', '坦白交代；承認錯誤', 'to tell the truth after concealing it', '[{"en":"He came clean about the financial irregularities.","zh-TW":"他坦白交代了財務不規則事項。"},{"en":"It is better to come clean early than hide mistakes.","zh-TW":"早坦白比隱瞞錯誤更好。"}]', 'expression'),
('count one''s chickens', '過早樂觀；未成功就先慶祝', 'to assume success before it is certain', '[{"en":"Do not count your chickens before the deal is signed.","zh-TW":"合同簽署前不要過早樂觀。"},{"en":"She counted her chickens and was disappointed when the deal fell through.","zh-TW":"她過早慶祝結果交易失敗令她失望。"}]', 'expression'),
('cut both ways', '雙面刃；利弊兼具', 'to have both positive and negative effects', '[{"en":"That policy cuts both ways — it helps and hurts different teams.","zh-TW":"那項政策是雙面刃——對不同團隊有利有弊。"},{"en":"Price cuts cut both ways in a competitive market.","zh-TW":"在競爭市場中降價是雙面刃。"}]', 'expression'),
('do a U-turn', '來個大轉彎；完全改變立場', 'to completely reverse a position or decision', '[{"en":"The company did a U-turn on its pricing strategy.","zh-TW":"公司在定價策略上來了個大轉彎。"},{"en":"Management did a U-turn after the staff backlash.","zh-TW":"員工強烈反對後管理層完全改變了立場。"}]', 'expression'),
('drop the ball', '搞砸；失誤；掉球', 'to fail to handle a responsibility properly', '[{"en":"We dropped the ball on the client''s request.","zh-TW":"我們在客戶請求方面搞砸了。"},{"en":"The project failed because someone dropped the ball.","zh-TW":"有人失誤導致專案失敗。"}]', 'expression'),
('earn one''s stripes', '在實踐中證明自己；靠努力贏得地位', 'to prove oneself through hard work and experience', '[{"en":"She earned her stripes managing difficult clients.","zh-TW":"她透過管理難相處的客戶證明了自己。"},{"en":"You need to earn your stripes before leading a team.","zh-TW":"領導團隊前你需要靠努力證明自己的價值。"}]', 'expression'),
('every cloud has a silver lining', '否極泰來；每件壞事都有其好的一面', 'every difficult situation contains a positive aspect', '[{"en":"The lost contract forced us to improve — every cloud has a silver lining.","zh-TW":"失去合同迫使我們改進——否極泰來。"},{"en":"Even this setback has a silver lining if we look.","zh-TW":"即使是這次挫折也有其好的一面。"}]', 'expression'),
('face the facts', '面對現實；承認事實', 'to accept the truth of a situation even if unpleasant', '[{"en":"We need to face the facts — our market share is declining.","zh-TW":"我們需要面對現實——我們的市場份額正在下降。"},{"en":"She faced the facts and restructured the team.","zh-TW":"她面對現實並重組了團隊。"}]', 'expression'),
('gain traction', '取得進展；越來越受到重視', 'to start to become successful or accepted', '[{"en":"The new product is gaining traction in the market.","zh-TW":"新產品正在市場上越來越受到重視。"},{"en":"Our social media campaign is finally gaining traction.","zh-TW":"我們的社交媒體活動終於取得了進展。"}]', 'expression'),
('get ahead of oneself', '操之過急；走在自己的能力之前', 'to be too hasty or ambitious before being ready', '[{"en":"Do not get ahead of yourself — confirm the facts first.","zh-TW":"不要操之過急——先確認事實。"},{"en":"She got ahead of herself and overpromised.","zh-TW":"她操之過急做出了過度承諾。"}]', 'expression'),
('get wind of', '得知；聞到風聲', 'to find out about something that was meant to be secret', '[{"en":"Competitors got wind of our product launch plans.","zh-TW":"競爭對手得知了我們的產品發布計劃。"},{"en":"She got wind of the restructuring before it was announced.","zh-TW":"她在宣布重組前就聞到了風聲。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('go belly up', '倒閉；失敗', 'to fail or go bankrupt', '[{"en":"Three competitors went belly up during the recession.","zh-TW":"三家競爭對手在經濟衰退期間倒閉了。"},{"en":"The startup went belly up after the funding dried up.","zh-TW":"資金枯竭後這家新創公司倒閉了。"}]', 'expression'),
('grease the wheels', '疏通關係；使運作更順暢', 'to do things that make a process work more smoothly', '[{"en":"A small concession helped grease the wheels of negotiation.","zh-TW":"一個小小的讓步幫助疏通了談判的進展。"},{"en":"She used her network to grease the wheels of the project.","zh-TW":"她利用人脈使專案運作更順暢。"}]', 'expression'),
('from the outset', '從一開始；自始', 'from the very beginning', '[{"en":"Clear expectations should be set from the outset.","zh-TW":"從一開始就應該設定清晰的期望。"},{"en":"From the outset the team knew the project was ambitious.","zh-TW":"從一開始團隊就知道這個專案很有野心。"}]', 'prepositional phrase'),
('in tandem with', '與…同步；配合', 'at the same time as or in coordination with', '[{"en":"Growth targets were set in tandem with hiring plans.","zh-TW":"增長目標與招聘計劃同步設定。"},{"en":"Marketing works in tandem with sales at this company.","zh-TW":"在這家公司行銷與銷售協同工作。"}]', 'prepositional phrase'),
('courtesy of', '承蒙…提供；因…而實現', 'provided by or thanks to someone or something', '[{"en":"The training was offered courtesy of our sponsor.","zh-TW":"培訓承蒙我們的贊助商提供。"},{"en":"Courtesy of the new system we processed twice the orders.","zh-TW":"因為新系統我們處理了兩倍的訂單。"}]', 'prepositional phrase'),
('on a tight deadline', '在緊迫的截止日期下', 'working with very little time remaining', '[{"en":"The team is on a tight deadline and needs extra support.","zh-TW":"團隊在緊迫的截止日期下需要額外支援。"},{"en":"On a tight deadline she still delivered excellent work.","zh-TW":"在緊迫的截止日期下她仍然交出了優秀的工作。"}]', 'prepositional phrase'),
('at a standstill', '停滯不前；陷入僵局', 'completely stopped or not progressing', '[{"en":"Production was at a standstill after the power cut.","zh-TW":"停電後生產陷入停滯。"},{"en":"Negotiations are at a standstill due to budget issues.","zh-TW":"由於預算問題談判陷入僵局。"}]', 'prepositional phrase'),
('at someone''s disposal', '可供某人使用；任某人支配', 'available for a particular person to use freely', '[{"en":"All resources are at your disposal for this project.","zh-TW":"所有資源都可供你在這個專案中使用。"},{"en":"She put her expertise at the team''s disposal.","zh-TW":"她將自己的專業知識供團隊任意使用。"}]', 'prepositional phrase'),
('in collaboration with', '與…合作；共同', 'working jointly with others', '[{"en":"The report was written in collaboration with three universities.","zh-TW":"報告是與三所大學合作撰寫的。"},{"en":"In collaboration with local agencies we launched the project.","zh-TW":"我們與當地機構合作啟動了專案。"}]', 'prepositional phrase'),
('in deference to', '出於對…的尊重；考量到', 'out of respect or in consideration of someone''s wishes', '[{"en":"In deference to the client''s wishes the deadline was extended.","zh-TW":"出於對客戶意願的尊重截止日期被延長了。"},{"en":"In deference to the board we revised the proposal.","zh-TW":"考量到董事會的意見我們修改了提案。"}]', 'prepositional phrase'),
('on target', '按計劃進行；達標', 'progressing as planned; achieving goals as expected', '[{"en":"The project is on target for completion by Q4.","zh-TW":"專案按計劃預計在第四季完成。"},{"en":"We are on target to exceed annual sales goals.","zh-TW":"我們有望超額完成年度銷售目標。"}]', 'prepositional phrase'),
('in partnership', '以合夥方式；共同合作', 'working together as partners', '[{"en":"We launched the campaign in partnership with a media agency.","zh-TW":"我們與一家媒體公司合作推出了這次活動。"},{"en":"Working in partnership amplifies our reach.","zh-TW":"合作擴大了我們的影響範圍。"}]', 'prepositional phrase'),
('on an ongoing basis', '持續地；長期地', 'happening continuously or regularly over time', '[{"en":"Performance is reviewed on an ongoing basis.","zh-TW":"績效會持續進行評估。"},{"en":"We communicate with clients on an ongoing basis.","zh-TW":"我們持續與客戶保持溝通。"}]', 'prepositional phrase'),
('within reach', '在可企及的範圍內；觸手可及', 'close enough to be achieved or obtained', '[{"en":"Profitability is now within reach.","zh-TW":"盈利能力現在觸手可及。"},{"en":"The funding goal is within reach after the last round.","zh-TW":"上一輪融資後資金目標近在咫尺。"}]', 'prepositional phrase'),
('in recognition of', '為了表彰；以表示肯定', 'to show appreciation or acknowledgment of something', '[{"en":"She received a bonus in recognition of her leadership.","zh-TW":"她因領導力而獲得了獎金表彰。"},{"en":"In recognition of his service the team gave him an award.","zh-TW":"為了表彰他的貢獻團隊頒給了他一個獎項。"}]', 'prepositional phrase'),
('by all accounts', '據大家說；就各方看法而言', 'according to most people or all available evidence', '[{"en":"By all accounts the launch was a great success.","zh-TW":"據大家說這次發布會非常成功。"},{"en":"By all accounts she is an exceptional negotiator.","zh-TW":"就各方看法而言她是一位出色的談判者。"}]', 'prepositional phrase'),
('short of', '不足；差一點；除了', 'lacking a required amount, or except for something', '[{"en":"We fell short of the quarterly target by 5%.","zh-TW":"我們的季度目標差了5%。"},{"en":"Short of a last-minute deal the merger is off.","zh-TW":"除非最後一刻達成協議否則合並告吹。"}]', 'prepositional phrase'),
('to the tune of', '高達；以…的金額', 'to the amount of (usually a large sum)', '[{"en":"The renovation cost to the tune of 5 million dollars.","zh-TW":"翻新費用高達500萬美元。"},{"en":"They invested to the tune of 20 million in the startup.","zh-TW":"他們向這家新創公司投資了高達2000萬。"}]', 'prepositional phrase'),
('in the absence', '在缺乏…的情況下', 'when something important is not present or available', '[{"en":"In the absence of clear data we will estimate.","zh-TW":"在缺乏明確數據的情況下我們將進行估算。"},{"en":"In the absence of the director the deputy took charge.","zh-TW":"在總監缺席的情況下副手接管了。"}]', 'prepositional phrase'),
('drop in the bucket', '九牛一毛；微不足道的數量', 'a very small amount compared to what is needed', '[{"en":"The savings are a drop in the bucket compared to total costs.","zh-TW":"這些節省與總成本相比是九牛一毛。"},{"en":"Our marketing budget is a drop in the bucket against global players.","zh-TW":"我們的行銷預算與全球參與者相比微不足道。"}]', 'business idiom'),
('early adopter', '早期採用者；先行使用者', 'someone who starts using a new product or technology early', '[{"en":"Early adopters provide valuable feedback on new features.","zh-TW":"早期採用者對新功能提供了寶貴的反饋。"},{"en":"We offered early adopters a discounted subscription.","zh-TW":"我們為早期採用者提供了折扣訂閱。"}]', 'business idiom'),
('expand the market', '開拓市場；擴大市場', 'to grow the number of customers or geographic reach', '[{"en":"Our goal is to expand the market for renewable energy.","zh-TW":"我們的目標是開拓可再生能源市場。"},{"en":"Localized content helped expand the market in Asia.","zh-TW":"在地化內容幫助在亞洲拓展了市場。"}]', 'business idiom'),
('eye-opener', '令人大開眼界的事；大開眼界', 'something that is surprising and reveals new information', '[{"en":"The audit was an eye-opener for senior management.","zh-TW":"審計對高層管理者來說是大開眼界的事。"},{"en":"Visiting the factory was a real eye-opener.","zh-TW":"參觀工廠真的讓人大開眼界。"}]', 'business idiom'),
('fall short', '達不到；不足', 'to not meet the required standard or amount', '[{"en":"Sales fell short of the Q3 target by 10%.","zh-TW":"銷售額比第三季度目標低了10%。"},{"en":"The proposal fell short of what the client expected.","zh-TW":"提案未能達到客戶的期望。"}]', 'business idiom'),
('fast follower', '快速跟進者；敏捷跟跑策略', 'a company that lets others innovate then quickly adapts the winning approach', '[{"en":"Being a fast follower reduces the risk of being first.","zh-TW":"作為快速跟進者降低了率先行動的風險。"},{"en":"Their fast follower strategy paid off in the mobile market.","zh-TW":"他們的快速跟進策略在移動市場上獲得了回報。"}]', 'business idiom'),
('financial year end', '財政年度結束；年末', 'the conclusion of the twelve-month accounting period', '[{"en":"All budgets must be reconciled at financial year end.","zh-TW":"所有預算必須在財政年度結束時核對。"},{"en":"She prepared the annual report for financial year end.","zh-TW":"她為財政年度結束準備了年度報告。"}]', 'business idiom'),
('fly high', '飛黃騰達；業績卓越', 'to be very successful or profitable', '[{"en":"The company is flying high after the successful IPO.","zh-TW":"成功上市後公司飛黃騰達。"},{"en":"Their new product line is flying high in consumer reviews.","zh-TW":"他們的新產品線在消費者評論中業績卓越。"}]', 'business idiom'),
('foothold', '立足點；初步進入', 'an initial and secure position in a competitive market', '[{"en":"We established a foothold in Southeast Asia this year.","zh-TW":"今年我們在東南亞建立了立足點。"},{"en":"Gaining a foothold in the enterprise market was difficult.","zh-TW":"在企業市場取得立足點很困難。"}]', 'business idiom'),
('free ride', '搭便車；不勞而獲', 'to benefit from others'' work without contributing', '[{"en":"You cannot get a free ride in a results-driven culture.","zh-TW":"在注重結果的文化中你不能搭便車。"},{"en":"He was seen as taking a free ride on the team''s success.","zh-TW":"他被認為在搭團隊成功的便車。"}]', 'business idiom'),
('full steam ahead', '全力前進；全速推進', 'moving forward with maximum effort and speed', '[{"en":"With budget approved it was full steam ahead.","zh-TW":"預算獲批後我們全力前進。"},{"en":"The team went full steam ahead on the product launch.","zh-TW":"團隊全速推進產品發布。"}]', 'business idiom'),
('get a foot in the door', '取得初步機會；邁出第一步', 'to gain an initial opportunity in a competitive field', '[{"en":"A small pilot project helped us get a foot in the door.","zh-TW":"一個小型試點項目幫助我們邁出了第一步。"},{"en":"She got a foot in the door through an internship.","zh-TW":"她通過實習獲得了初步機會。"}]', 'business idiom'),
('get on board', '加入；同意；支持', 'to join a plan, team, or cause enthusiastically', '[{"en":"We need to get the sales team on board with the new process.","zh-TW":"我們需要讓銷售團隊支持新流程。"},{"en":"Once the CEO got on board the project accelerated.","zh-TW":"一旦執行長加入專案就加速了。"}]', 'business idiom'),
('get the upper hand', '佔上風；取得優勢', 'to gain an advantage over others in a contest', '[{"en":"They got the upper hand by reducing prices first.","zh-TW":"他們率先降價而佔了上風。"},{"en":"Better data gives us the upper hand in negotiations.","zh-TW":"更好的數據讓我們在談判中佔有優勢。"}]', 'business idiom'),
('golden opportunity', '千載難逢的機會', 'an exceptionally good chance to achieve something', '[{"en":"This market gap is a golden opportunity for us.","zh-TW":"這個市場缺口對我們來說是千載難逢的機會。"},{"en":"Do not let this golden opportunity pass.","zh-TW":"不要讓這個千載難逢的機會溜走。"}]', 'business idiom'),
('grab the bull by the horns', '勇於面對難題；迎難而上', 'to tackle a difficult problem directly and decisively', '[{"en":"It is time to grab the bull by the horns and restructure.","zh-TW":"是時候勇於面對難題進行重組了。"},{"en":"She grabbed the bull by the horns and resolved the crisis.","zh-TW":"她迎難而上解決了危機。"}]', 'business idiom'),
('grow organically', '有機增長；自然增長', 'to grow through internal development rather than acquisitions', '[{"en":"We grew organically rather than through acquisitions.","zh-TW":"我們通過有機增長而非收購來發展。"},{"en":"Growing organically builds a more sustainable business.","zh-TW":"有機增長建立了更可持續的業務。"}]', 'business idiom'),
('gut feeling', '直覺；第六感', 'a strong intuition about something without clear evidence', '[{"en":"His gut feeling told him the deal was risky.","zh-TW":"他的直覺告訴他這筆交易有風險。"},{"en":"Sometimes gut feeling is as important as data in decisions.","zh-TW":"有時直覺在決策中與數據同樣重要。"}]', 'business idiom'),
('hands-on approach', '親力親為；實踐型方式', 'getting directly involved in work rather than just supervising', '[{"en":"The CEO takes a hands-on approach to product development.","zh-TW":"執行長對產品開發採取親力親為的方式。"},{"en":"A hands-on approach helps managers understand daily challenges.","zh-TW":"親力親為的方式幫助管理者了解日常挑戰。"}]', 'business idiom'),
('hard sell', '強力推銷；強硬銷售', 'an aggressive attempt to persuade someone to buy or agree', '[{"en":"A hard sell approach often alienates potential clients.","zh-TW":"強力推銷往往會疏遠潛在客戶。"},{"en":"She avoided the hard sell and focused on building trust.","zh-TW":"她避免了強硬推銷而是專注於建立信任。"}]', 'business idiom'),
('liaise with', '聯絡；協調', 'to communicate and cooperate with another person or organization', '[{"en":"She liaises with the finance team on budget matters.","zh-TW":"她與財務團隊就預算事宜保持聯絡。"},{"en":"We liaise closely with clients to understand their needs.","zh-TW":"我們與客戶密切協調以了解他們的需求。"}]', 'phrasal verb'),
('nail down', '確定；明確固定', 'to specify exactly or finalize clearly', '[{"en":"Let us nail down the exact scope of work.","zh-TW":"讓我們明確固定工作範圍。"},{"en":"She nailed down the project timeline in the first meeting.","zh-TW":"她在第一次會議中確定了專案時間表。"}]', 'phrasal verb'),
('phase out of', '逐步淘汰；逐漸停止使用', 'to eliminate something gradually over time', '[{"en":"Fossil fuels are being phased out of the energy mix.","zh-TW":"化石燃料正被逐步淘汰出能源組合。"},{"en":"We are phasing this legacy product out of the lineup.","zh-TW":"我們正在將這款舊產品從產品線中逐步淘汰。"}]', 'phrasal verb'),
('plug into', '融入；接入；利用', 'to connect or integrate with a larger system or community', '[{"en":"Our API plugs into most existing CRM systems.","zh-TW":"我們的API可以接入大多數現有CRM系統。"},{"en":"She plugged into the startup ecosystem immediately.","zh-TW":"她立即融入了新創生態系統。"}]', 'phrasal verb'),
('prime for', '為…做好準備；使準備就緒', 'to prepare something for a particular purpose', '[{"en":"We need to prime the market before the launch.","zh-TW":"我們需要在發布前為市場做好準備。"},{"en":"Months of training primed the team for the expansion.","zh-TW":"幾個月的培訓使團隊為擴張做好了準備。"}]', 'phrasal verb'),
('put a stop to', '終止；阻止', 'to cause something harmful to end', '[{"en":"Management put a stop to the unauthorized spending.","zh-TW":"管理層終止了未經授權的支出。"},{"en":"She put a stop to the meeting when it became unproductive.","zh-TW":"當會議變得低效時她終止了會議。"}]', 'phrasal verb'),
('qualify for', '符合資格；具備條件', 'to meet the requirements for something', '[{"en":"Small businesses may qualify for the government grant.","zh-TW":"小企業可能符合政府補助的資格。"},{"en":"She qualifies for the leadership development programme.","zh-TW":"她具備參加領導力發展計劃的資格。"}]', 'phrasal verb'),
('read through', '通讀；仔細閱讀', 'to read something carefully from beginning to end', '[{"en":"Please read through the agreement before signing.","zh-TW":"簽署前請仔細通讀協議。"},{"en":"She read through the report and flagged three issues.","zh-TW":"她通讀了報告並標記了三個問題。"}]', 'phrasal verb'),
('recover from', '從…中恢復；恢復元氣', 'to return to a normal state after a setback', '[{"en":"The company is slowly recovering from the market downturn.","zh-TW":"公司正在緩慢地從市場下滑中恢復。"},{"en":"She recovered from the failed campaign with a fresh strategy.","zh-TW":"她以新策略從失敗的活動中恢復。"}]', 'phrasal verb'),
('review against', '與…對照審查；對比評審', 'to evaluate by comparing against a standard or baseline', '[{"en":"We review results against last year''s benchmarks.","zh-TW":"我們將結果與去年的基準進行對照審查。"},{"en":"She reviewed the proposal against the client requirements.","zh-TW":"她將提案與客戶要求進行了對比評審。"}]', 'phrasal verb'),
('reward with', '以…獎勵；給予獎勵', 'to give something positive in return for good performance', '[{"en":"High performers are rewarded with performance bonuses.","zh-TW":"績效優秀者以績效獎金獎勵。"},{"en":"She was rewarded with a promotion for her hard work.","zh-TW":"她因努力工作而以晉升為獎勵。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('scale across', '跨範圍擴展；橫向擴展', 'to expand or apply a model across multiple areas', '[{"en":"We plan to scale the solution across all regions.","zh-TW":"我們計劃在所有地區擴展這個解決方案。"},{"en":"The approach scaled across three product lines successfully.","zh-TW":"這個方法成功地在三條產品線上橫向擴展了。"}]', 'phrasal verb'),
('shut out', '排除；拒之門外', 'to exclude or prevent from accessing or participating', '[{"en":"Strict regulations shut out new competitors.","zh-TW":"嚴格的法規將新競爭者拒之門外。"},{"en":"She felt shut out of the decision-making process.","zh-TW":"她感到被排除在決策過程之外。"}]', 'phrasal verb'),
('sign off', '批准；結束；簽字確認', 'to give final approval or sign to confirm completion', '[{"en":"The director needs to sign off on all purchases over 5000.","zh-TW":"所有超過5000的採購都需要總監簽字確認。"},{"en":"She signed off on the project before handing it over.","zh-TW":"她在移交前批准了該專案。"}]', 'phrasal verb'),
('sleep on it', '等明天再決定；先想一想', 'to take more time before making a decision', '[{"en":"It is a big decision — sleep on it before responding.","zh-TW":"這是個重大決定——先想一想再回覆。"},{"en":"She slept on it and came back with a better answer.","zh-TW":"她想了想後給出了更好的答案。"}]', 'phrasal verb'),
('slow roll', '緩慢推進；刻意拖延', 'to do something slowly and deliberately, often to delay', '[{"en":"They slow rolled the integration to manage disruption.","zh-TW":"他們緩慢推進整合以管理干擾。"},{"en":"Do not slow roll the update — clients are waiting.","zh-TW":"不要刻意拖延更新——客戶在等待。"}]', 'phrasal verb'),
('speak up for', '為…發聲；支持', 'to defend or advocate on behalf of someone or something', '[{"en":"She spoke up for her team when management criticized them.","zh-TW":"管理層批評她的團隊時她為他們發聲。"},{"en":"Be willing to speak up for what you believe in.","zh-TW":"要願意為你所相信的事情發聲。"}]', 'phrasal verb'),
('stake out', '確立立場；劃定範圍', 'to establish a clear position or claim something firmly', '[{"en":"She staked out a clear position in the debate.","zh-TW":"她在辯論中確立了清晰的立場。"},{"en":"The company staked out its territory in the premium segment.","zh-TW":"公司在高端市場劃定了自己的領域。"}]', 'phrasal verb'),
('stand down', '撤退；停止；辭職', 'to withdraw from a position or cease an action', '[{"en":"The executive stood down under board pressure.","zh-TW":"在董事會壓力下高管辭職了。"},{"en":"Both parties agreed to stand down from their positions.","zh-TW":"雙方同意撤退各自的立場。"}]', 'phrasal verb'),
('steer clear of', '避開；遠離', 'to avoid something or someone deliberately', '[{"en":"Steer clear of political topics in business meetings.","zh-TW":"在商務會議中遠離政治話題。"},{"en":"She steered clear of the volatile market segments.","zh-TW":"她避開了波動劇烈的市場細分領域。"}]', 'phrasal verb'),
('have one''s work cut out', '面臨艱鉅任務；任務繁重', 'to have a very difficult task ahead', '[{"en":"With three deadlines this week she has her work cut out.","zh-TW":"這週有三個截止日期她面臨艱鉅任務。"},{"en":"The new director has his work cut out turning around the division.","zh-TW":"新主管面臨扭轉部門局面的艱鉅任務。"}]', 'expression'),
('hedge one''s bets', '雙邊下注；降低風險', 'to reduce risk by supporting more than one option', '[{"en":"By investing in multiple markets we hedge our bets.","zh-TW":"通過投資多個市場我們降低了風險。"},{"en":"He hedged his bets by keeping two options open.","zh-TW":"他通過保留兩個選項來雙邊下注。"}]', 'expression'),
('hold the fort', '守住陣地；維持秩序', 'to manage a situation while others are away', '[{"en":"Can you hold the fort while I am at the conference?","zh-TW":"我去參加會議時你能維持秩序嗎？"},{"en":"She held the fort for a month during the director''s leave.","zh-TW":"總監請假期間她守住了陣地一個月。"}]', 'expression'),
('in hot water', '陷入麻煩；有大麻煩', 'in a difficult or troubled situation', '[{"en":"The company is in hot water over data privacy issues.","zh-TW":"公司因數據隱私問題陷入了麻煩。"},{"en":"He found himself in hot water after the announcement.","zh-TW":"公告後他發現自己惹上了大麻煩。"}]', 'expression'),
('jump the gun', '操之過急；倉促行動', 'to act before the appropriate time', '[{"en":"Do not jump the gun and announce before approval.","zh-TW":"在獲得批准前不要操之過急地發布公告。"},{"en":"He jumped the gun and sent the email before the deal closed.","zh-TW":"他在交易完成前倉促地發送了電子郵件。"}]', 'expression'),
('keep a low profile', '保持低調；不引人注目', 'to avoid attracting attention or publicity', '[{"en":"During the investigation the company kept a low profile.","zh-TW":"調查期間公司保持了低調。"},{"en":"She kept a low profile after the failed product launch.","zh-TW":"產品發布失敗後她保持了低調。"}]', 'expression'),
('kick the can down the road', '拖延問題；把問題留給以後', 'to postpone dealing with a problem to a future time', '[{"en":"We cannot keep kicking this issue down the road.","zh-TW":"我們不能一直拖延這個問題。"},{"en":"Kicking the can down the road only makes things worse.","zh-TW":"把問題留給以後只會讓事情更糟。"}]', 'expression'),
('lead by example', '以身作則', 'to demonstrate through one''s own behavior the standards expected of others', '[{"en":"Effective managers lead by example.","zh-TW":"有效的管理者以身作則。"},{"en":"She leads by example by always being on time.","zh-TW":"她通過總是準時到達來以身作則。"}]', 'expression'),
('look at the big picture', '著眼大局；從整體角度考慮', 'to consider the overall situation rather than details', '[{"en":"When stressed look at the big picture and priorities.","zh-TW":"壓力大時要著眼大局和優先事項。"},{"en":"She always looks at the big picture before deciding.","zh-TW":"她在決定前總是從整體角度考慮。"}]', 'expression'),
('lose the plot', '失控；亂了陣腳；失去重點', 'to lose focus or control of a situation', '[{"en":"The team lost the plot when three managers left at once.","zh-TW":"三位管理者同時離開後團隊亂了陣腳。"},{"en":"Do not lose the plot when clients push for changes.","zh-TW":"當客戶推動變更時不要失去重點。"}]', 'expression'),
('make a mark', '留下印記；創造顯著影響', 'to have a lasting, positive impact on something', '[{"en":"She made a mark in the tech industry with her innovation.","zh-TW":"她以創新在科技業留下了印記。"},{"en":"This product made a real mark on the market.","zh-TW":"這款產品對市場產生了真正的顯著影響。"}]', 'expression'),
('make or break', '成敗關鍵；決定成敗', 'determining whether something succeeds or fails', '[{"en":"This quarter is make or break for the startup.","zh-TW":"這個季度是新創公司成敗的關鍵。"},{"en":"The negotiation is make or break for the partnership.","zh-TW":"這次談判是合作關係成敗的決定性因素。"}]', 'expression'),
('make the cut', '入選；符合標準', 'to meet the standard required to be chosen or included', '[{"en":"Only three candidates made the cut.","zh-TW":"只有三位候選人入選。"},{"en":"Her presentation made the cut for the final pitch.","zh-TW":"她的簡報入選了最終提案。"}]', 'expression'),
('mind the gap', '注意差距；填補缺口', 'to be aware of and address gaps or weaknesses', '[{"en":"Mind the gap between promised and delivered service.","zh-TW":"注意承諾服務與實際交付之間的差距。"},{"en":"Regularly mind the gap in skills within your team.","zh-TW":"定期注意並填補團隊內的技能差距。"}]', 'expression'),
('move mountains', '排除萬難；取得非凡成就', 'to accomplish something very difficult', '[{"en":"She moved mountains to get the project approved.","zh-TW":"她排除萬難讓專案獲得了批准。"},{"en":"The team moved mountains to deliver on time.","zh-TW":"團隊排除萬難準時交付。"}]', 'expression'),
('nail the landing', '完美收尾；漂亮地完成', 'to execute a conclusion or final stage perfectly', '[{"en":"She nailed the landing with a compelling call to action.","zh-TW":"她以有力的行動呼籲完美收尾了簡報。"},{"en":"After months of preparation they nailed the landing.","zh-TW":"經過幾個月的準備他們漂亮地完成了任務。"}]', 'expression'),
('name of the game', '關鍵所在；核心要素', 'the most important quality or skill needed for success', '[{"en":"In e-commerce speed is the name of the game.","zh-TW":"在電商中速度是關鍵所在。"},{"en":"Client retention is the name of the game in our industry.","zh-TW":"在我們的行業中客戶留存是核心要素。"}]', 'expression'),
('on borrowed time', '時日無多；快到盡頭', 'continuing in a situation that is likely to end soon', '[{"en":"That business model is on borrowed time.","zh-TW":"那個商業模式時日無多了。"},{"en":"Without innovation the product line is on borrowed time.","zh-TW":"沒有創新這條產品線快到盡頭了。"}]', 'expression'),
('own the outcome', '承擔結果責任；掌控成果', 'to take full responsibility for the result of one''s actions', '[{"en":"Leaders must own the outcome whether positive or negative.","zh-TW":"領導者必須對成果承擔責任無論是正面還是負面。"},{"en":"She owned the outcome and presented it transparently.","zh-TW":"她承擔了成果責任並透明地呈報了結果。"}]', 'expression'),
('play to one''s strengths', '發揮優勢；利用強項', 'to use one''s best qualities or abilities to gain advantage', '[{"en":"Play to your strengths and let others handle the rest.","zh-TW":"發揮你的優勢讓其他人處理其餘事宜。"},{"en":"The team played to its strengths in the final pitch.","zh-TW":"團隊在最後提案中發揮了自己的優勢。"}]', 'expression'),
('in hindsight', '事後看來；回頭來看', 'looking back at the past with new understanding', '[{"en":"In hindsight we should have launched earlier.","zh-TW":"事後看來我們應該更早推出的。"},{"en":"In hindsight the acquisition was a mistake.","zh-TW":"回頭來看這次收購是個錯誤。"}]', 'prepositional phrase'),
('going forward', '今後；從現在起', 'from now on; in the future', '[{"en":"Going forward all approvals must be documented.","zh-TW":"從現在起所有批准都必須記錄在案。"},{"en":"Going forward we will focus on quality over speed.","zh-TW":"今後我們將注重品質而非速度。"}]', 'prepositional phrase'),
('on the agenda', '在議程上；待討論的', 'listed as a topic to be discussed at a meeting', '[{"en":"Budget allocation is on the agenda for today.","zh-TW":"預算分配在今天的議程上。"},{"en":"She made sure sustainability was on the agenda.","zh-TW":"她確保永續發展被列入了議程。"}]', 'prepositional phrase'),
('on the horizon', '即將來臨；在不遠的將來', 'expected to happen in the near future', '[{"en":"A major product update is on the horizon.","zh-TW":"一個重大產品更新即將來臨。"},{"en":"With new regulations on the horizon we must prepare.","zh-TW":"隨著新法規即將來臨我們必須做好準備。"}]', 'prepositional phrase'),
('in step with', '與…步調一致；緊跟', 'in agreement or keeping pace with something', '[{"en":"Our pricing is in step with market expectations.","zh-TW":"我們的定價與市場期望一致。"},{"en":"The strategy is in step with the latest consumer trends.","zh-TW":"該策略緊跟最新的消費者趨勢。"}]', 'prepositional phrase'),
('in line for', '有望晉升為；即將獲得', 'positioned to receive or be appointed to something', '[{"en":"She is in line for the regional director position.","zh-TW":"她有望晉升為區域總監。"},{"en":"He is in line for a significant pay rise.","zh-TW":"他即將獲得大幅加薪。"}]', 'prepositional phrase'),
('in transition', '處於過渡期；轉型中', 'in the process of changing from one state to another', '[{"en":"The company is in transition to a new operating model.","zh-TW":"公司正處於轉型到新運作模式的過渡期。"},{"en":"She is in transition between her old and new roles.","zh-TW":"她正處於新舊職位之間的過渡期。"}]', 'prepositional phrase'),
('up to standard', '達到標準；符合要求', 'meeting the required level of quality or performance', '[{"en":"The product was not up to standard and was recalled.","zh-TW":"產品未達到標準並被召回了。"},{"en":"All deliverables must be up to standard before release.","zh-TW":"所有交付物在發布前必須達到標準。"}]', 'prepositional phrase'),
('in default', '違約；拖欠', 'having failed to meet a financial or legal obligation', '[{"en":"The company is in default on its loan repayments.","zh-TW":"公司在貸款還款上違約了。"},{"en":"Failure to deliver constitutes being in default.","zh-TW":"未能交付即構成違約。"}]', 'prepositional phrase'),
('on good terms', '關係良好；和睦相處', 'having a positive relationship with someone', '[{"en":"Despite the dispute we remain on good terms.","zh-TW":"儘管有爭議我們仍然保持良好關係。"},{"en":"She left the company on good terms with everyone.","zh-TW":"她離職時與每個人都保持良好關係。"}]', 'prepositional phrase'),
('at a discount', '以折扣價；打折', 'at a lower price than usual or standard', '[{"en":"The product is offered at a discount for bulk orders.","zh-TW":"大批量訂單提供折扣價。"},{"en":"They acquired the assets at a steep discount.","zh-TW":"他們以大幅折扣收購了這些資產。"}]', 'prepositional phrase'),
('in the spotlight', '在公眾目光下；受到關注', 'receiving a lot of public or media attention', '[{"en":"The CEO has been in the spotlight since the announcement.","zh-TW":"執行長自公告以來一直處於公眾目光下。"},{"en":"In the spotlight every decision is scrutinized.","zh-TW":"在受到關注的情況下每個決定都受到審視。"}]', 'prepositional phrase'),
('ahead of the pack', '領先群雄；走在前面', 'more advanced than one''s competitors', '[{"en":"Continuous investment keeps us ahead of the pack.","zh-TW":"持續投資讓我們領先群雄。"},{"en":"She ran ahead of the pack in the talent acquisition race.","zh-TW":"她在人才獲取競賽中走在前面。"}]', 'prepositional phrase'),
('in hot demand', '需求旺盛；炙手可熱', 'wanted by many people; very popular or sought-after', '[{"en":"Data scientists are in hot demand across all industries.","zh-TW":"數據科學家在所有行業都炙手可熱。"},{"en":"The product was in hot demand after the media coverage.","zh-TW":"媒體報導後該產品需求旺盛。"}]', 'prepositional phrase'),
('at a pace', '以某種速度；按某種節奏', 'at a particular speed or rate', '[{"en":"The business is growing at an impressive pace.","zh-TW":"業務以驚人的速度增長。"},{"en":"We are implementing changes at a manageable pace.","zh-TW":"我們以可控的節奏實施變革。"}]', 'prepositional phrase'),
('under scrutiny', '受到審查；接受仔細檢查', 'being carefully examined or investigated', '[{"en":"The firm''s accounting practices are under scrutiny.","zh-TW":"公司的會計做法正受到審查。"},{"en":"Under scrutiny all decisions must be justifiable.","zh-TW":"在受到審查的情況下所有決定都必須合理。"}]', 'prepositional phrase'),
('in a position to', '能夠；有條件去', 'having the ability or means to do something', '[{"en":"We are in a position to offer a better deal now.","zh-TW":"我們現在有條件提供更好的交易。"},{"en":"Are you in a position to commit by Friday?","zh-TW":"你能在週五前做出承諾嗎？"}]', 'prepositional phrase'),
('under the microscope', '受到嚴密審視；被仔細調查', 'being examined very carefully for problems', '[{"en":"After the recall every process was put under the microscope.","zh-TW":"召回後每個流程都受到嚴密審視。"},{"en":"The regulator put their practices under the microscope.","zh-TW":"監管機構對他們的做法進行了嚴密調查。"}]', 'prepositional phrase'),
('in the same boat', '同舟共濟；處境相同', 'in the same difficult situation as others', '[{"en":"We are all in the same boat with rising energy costs.","zh-TW":"面對不斷上漲的能源成本我們都同舟共濟。"},{"en":"The whole industry is in the same boat this year.","zh-TW":"今年整個行業處境相同。"}]', 'prepositional phrase'),
('from all angles', '從各個角度；全方位地', 'considering every perspective or approach', '[{"en":"We analyzed the proposal from all angles before deciding.","zh-TW":"我們在做決定前從各個角度分析了提案。"},{"en":"View the risk from all angles to ensure thorough assessment.","zh-TW":"從各個角度看待風險以確保全面評估。"}]', 'prepositional phrase'),
('have the edge over', '勝人一籌；比…略佔優勢', 'to have a slight advantage over a competitor', '[{"en":"Our after-sales service gives us the edge over rivals.","zh-TW":"我們的售後服務讓我們勝競爭對手一籌。"},{"en":"They have the edge over us in brand recognition.","zh-TW":"他們在品牌認知度方面略佔優勢。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('head start', '搶先起步；先發優勢', 'an advantage gained by starting before others', '[{"en":"Early investment gave us a head start in AI.","zh-TW":"早期投資讓我們在AI領域搶先起步。"},{"en":"She got a head start on the project by researching early.","zh-TW":"她通過提前研究在專案上獲得了先發優勢。"}]', 'business idiom'),
('hit the road running', '立刻開始；全速出發', 'to start very quickly and with great energy', '[{"en":"The new team hit the road running from day one.","zh-TW":"新團隊從第一天就立刻全速開始工作。"},{"en":"A strong onboarding ensures people hit the road running.","zh-TW":"完善的入職培訓確保員工立刻投入工作。"}]', 'business idiom'),
('in a bind', '進退兩難；陷入困境', 'in a difficult situation where no option seems good', '[{"en":"With two conflicting deadlines we are in a bind.","zh-TW":"兩個截止日期相衝突讓我們進退兩難。"},{"en":"She was in a bind when both clients demanded priority.","zh-TW":"兩個客戶都要求優先時她陷入了困境。"}]', 'business idiom'),
('keep up appearances', '維持門面；裝作沒事', 'to continue to appear successful even when facing difficulties', '[{"en":"They kept up appearances while seeking emergency funding.","zh-TW":"他們在尋求緊急資金的同時維持著門面。"},{"en":"Keeping up appearances can mislead investors.","zh-TW":"維持門面可能會誤導投資者。"}]', 'business idiom'),
('long shot', '成功機會渺茫；勝算不大的嘗試', 'an attempt that has little chance of success', '[{"en":"Winning the contract is a long shot but worth pursuing.","zh-TW":"贏得合同成功機會渺茫但值得追求。"},{"en":"They took a long shot and it paid off.","zh-TW":"他們進行了一次勝算不大的嘗試結果成功了。"}]', 'business idiom'),
('look sharp', '行動迅速；精神抖擻', 'to move quickly or make a good impression', '[{"en":"Look sharp — the client will be here in five minutes.","zh-TW":"行動迅速——客戶五分鐘後到達。"},{"en":"Everyone looked sharp for the investor presentation.","zh-TW":"大家在投資者簡報中精神抖擻。"}]', 'business idiom'),
('lose ground', '失去優勢；落後', 'to fall behind or lose one''s advantage', '[{"en":"We are losing ground to cheaper overseas competitors.","zh-TW":"我們在對較便宜的海外競爭者上失去了優勢。"},{"en":"The product is losing ground in market share.","zh-TW":"該產品在市場份額上正在落後。"}]', 'business idiom'),
('make hay while the sun shines', '把握良機；趁機大幅獲利', 'to take advantage of a good situation while it lasts', '[{"en":"With demand high we need to make hay while the sun shines.","zh-TW":"需求旺盛時我們要趁機大幅獲利。"},{"en":"Make hay while the sun shines by expanding market reach.","zh-TW":"趁情況大好時擴大市場覆蓋。"}]', 'business idiom'),
('meet halfway', '各讓一步；妥協', 'to compromise by each party giving up something', '[{"en":"Both sides agreed to meet halfway on the price.","zh-TW":"雙方同意在價格上各讓一步。"},{"en":"She was willing to meet halfway to save the deal.","zh-TW":"她願意各讓一步以挽救交易。"}]', 'business idiom'),
('no silver bullet', '沒有萬靈藥；沒有一勞永逸的解決方案', 'there is no single perfect solution to a complex problem', '[{"en":"There is no silver bullet for retention — it requires multiple approaches.","zh-TW":"留才沒有萬靈藥——需要多種方法。"},{"en":"We tried various tactics because there is no silver bullet.","zh-TW":"因為沒有一勞永逸的解決方案我們嘗試了各種策略。"}]', 'business idiom'),
('not in the cards', '不可能發生；命中注定不成', 'unlikely or impossible to happen', '[{"en":"An acquisition is not in the cards given the budget.","zh-TW":"鑑於預算狀況收購是不可能的。"},{"en":"A raise was simply not in the cards this year.","zh-TW":"今年加薪實在是不可能的事。"}]', 'business idiom'),
('off the top', '劈頭就；未加思索地', 'first, before anything else is done; impromptu', '[{"en":"Off the top I would say we need at least 50 units.","zh-TW":"未加思索我會說我們至少需要50個單位。"},{"en":"She gave a rough estimate off the top of her head.","zh-TW":"她不假思索地給了一個粗略估算。"}]', 'business idiom'),
('on a shoestring', '以極少的錢；預算極為有限', 'with very limited money or resources', '[{"en":"We launched the startup on a shoestring budget.","zh-TW":"我們以極為有限的預算創辦了新創公司。"},{"en":"She managed the marketing on a shoestring.","zh-TW":"她以極少的錢管理了行銷工作。"}]', 'business idiom'),
('on the back foot', '處於劣勢；防禦性地', 'in a disadvantaged or defensive position', '[{"en":"After the recall we were on the back foot with clients.","zh-TW":"召回事件後我們在客戶面前處於劣勢。"},{"en":"Late entry put the company on the back foot.","zh-TW":"晚進入市場讓公司處於劣勢。"}]', 'business idiom'),
('on the fast lane', '快速發展中；高速前進', 'moving or progressing at a very fast rate', '[{"en":"The startup is on the fast lane to expansion.","zh-TW":"這家新創公司正在快速擴張。"},{"en":"With strong funding they are in the fast lane.","zh-TW":"有強勁資金他們正在高速前進。"}]', 'business idiom'),
('on thin margins', '在利潤微薄的情況下', 'operating with very little profit relative to revenue', '[{"en":"Retail operates on thin margins and requires efficiency.","zh-TW":"零售業在利潤微薄的情況下運作需要高效率。"},{"en":"On thin margins every cost saving matters.","zh-TW":"在利潤微薄的情況下每一項成本節省都很重要。"}]', 'business idiom'),
('open books policy', '透明帳目政策；開放帳目', 'a business practice of sharing financial information openly', '[{"en":"The open books policy built trust with suppliers.","zh-TW":"透明帳目政策建立了與供應商的信任。"},{"en":"An open books policy is key in long-term partnerships.","zh-TW":"透明帳目政策是長期合作夥伴關係的關鍵。"}]', 'business idiom'),
('put in the legwork', '付出實際行動；跑腿努力', 'to do the necessary ground-level work to make something happen', '[{"en":"To win this contract we need to put in the legwork.","zh-TW":"要贏得這份合同我們需要付出實際行動。"},{"en":"She put in the legwork and the results showed.","zh-TW":"她付出了努力成果也顯現出來了。"}]', 'expression'),
('raise eyebrows', '引起驚訝；令人側目', 'to cause surprise or slight disapproval', '[{"en":"The unusual pricing raised eyebrows in the market.","zh-TW":"不尋常的定價在市場上令人側目。"},{"en":"Her bold proposal raised eyebrows but was approved.","zh-TW":"她大膽的提案令人驚訝但被批准了。"}]', 'expression'),
('ride the wave', '乘勢而上；借助潮流', 'to take advantage of a trend or period of success', '[{"en":"We rode the wave of digital adoption post-pandemic.","zh-TW":"我們在疫情後乘著數位化浪潮而上。"},{"en":"Smart companies ride the wave of consumer trends.","zh-TW":"聰明的公司會借助消費者趨勢乘勢而上。"}]', 'expression'),
('right off the bat', '一開始就；立刻', 'immediately; at the very beginning', '[{"en":"Right off the bat she established clear expectations.","zh-TW":"一開始她就建立了清晰的期望。"},{"en":"He identified the core issue right off the bat.","zh-TW":"他一開始就識別了核心問題。"}]', 'expression'),
('run the numbers', '計算數字；做數據分析', 'to calculate or analyze financial data', '[{"en":"Let me run the numbers before we decide.","zh-TW":"讓我計算一下數字再做決定。"},{"en":"She ran the numbers and the deal looked profitable.","zh-TW":"她計算了數字後發現這筆交易看起來有利可圖。"}]', 'expression'),
('run with an idea', '積極推進一個想法', 'to take an idea and develop it enthusiastically', '[{"en":"She heard the concept and ran with it immediately.","zh-TW":"她聽到這個概念後立即積極推進。"},{"en":"Run with the best idea from today''s brainstorm.","zh-TW":"積極推進今天腦力激盪中最好的想法。"}]', 'expression'),
('set the tone', '定調；奠定基調', 'to establish the character or attitude for something', '[{"en":"The opening remarks set the tone for the whole conference.","zh-TW":"開幕發言為整個會議定調。"},{"en":"Strong leadership sets the tone for company culture.","zh-TW":"強有力的領導力為公司文化奠定基調。"}]', 'expression'),
('sharpen the pencil', '精確計算；重新計算以降低報價', 'to recalculate to achieve a better price or estimate', '[{"en":"Can you sharpen the pencil on this quote?","zh-TW":"你能精確計算一下這份報價嗎？"},{"en":"We sharpened the pencil and reduced the bid by 8%.","zh-TW":"我們精確計算後將報價降低了8%。"}]', 'expression'),
('show of hands', '舉手表決；直接投票', 'a vote where people raise hands to indicate preference', '[{"en":"By a show of hands how many agree with the proposal?","zh-TW":"舉手表決有多少人同意這個提案？"},{"en":"A quick show of hands confirmed the decision.","zh-TW":"快速的舉手表決確認了這個決定。"}]', 'expression'),
('sign of the times', '時代的標誌；時勢的反映', 'something that reflects the current state of society or business', '[{"en":"Remote work is a sign of the times.","zh-TW":"遠端工作是時代的標誌。"},{"en":"Digital-first strategies are a sign of the times.","zh-TW":"數位優先策略是時勢的反映。"}]', 'expression'),
('sit on the fence', '騎牆觀望；態度不明朗', 'to be neutral or avoid taking a side in an issue', '[{"en":"You cannot sit on the fence in a competitive market.","zh-TW":"在競爭激烈的市場中你不能騎牆觀望。"},{"en":"She sat on the fence during the heated debate.","zh-TW":"她在激烈辯論中保持中立態度。"}]', 'expression'),
('speak volumes', '說明很多；意味深長', 'to express or reveal a great deal without words', '[{"en":"The customer return rate speaks volumes about quality.","zh-TW":"客戶回購率說明了很多關於品質的問題。"},{"en":"Her dedication speaks volumes about her character.","zh-TW":"她的投入意味深長地展現了她的品格。"}]', 'expression'),
('start from scratch', '從零開始；白手起家', 'to begin again from the very beginning with nothing', '[{"en":"After the failed launch we started from scratch.","zh-TW":"失敗的發布後我們從零開始。"},{"en":"Building the brand from scratch required patience.","zh-TW":"從零開始建立品牌需要耐心。"}]', 'expression'),
('stay the course', '堅持到底；保持方向', 'to persist with a plan despite difficulties', '[{"en":"Despite short-term losses we must stay the course.","zh-TW":"儘管有短期損失我們必須堅持到底。"},{"en":"She urged the board to stay the course.","zh-TW":"她敦促董事會保持既定方向。"}]', 'expression'),
('stop the rot', '防止惡化；阻止繼續惡化', 'to take action to prevent further decline or deterioration', '[{"en":"New management was brought in to stop the rot.","zh-TW":"引進了新管理層以防止進一步惡化。"},{"en":"Quick action stopped the rot before it became serious.","zh-TW":"迅速行動在情況嚴重前阻止了惡化。"}]', 'expression'),
('the bottom has fallen out', '市場崩潰；基礎崩塌', 'to collapse or fail suddenly and completely', '[{"en":"The bottom has fallen out of the retail sector.","zh-TW":"零售業市場已崩潰。"},{"en":"When demand evaporated the bottom fell out of pricing.","zh-TW":"需求消失後定價基礎崩塌了。"}]', 'expression'),
('the crux of the matter', '問題的關鍵；核心', 'the most important part or central issue of something', '[{"en":"The crux of the matter is whether the model is scalable.","zh-TW":"問題的關鍵是商業模式是否可擴展。"},{"en":"She identified the crux of the matter quickly.","zh-TW":"她迅速識別了問題的關鍵。"}]', 'expression'),
('the end of the road', '走到盡頭；終點', 'a point at which no further progress is possible', '[{"en":"This product line has reached the end of the road.","zh-TW":"這條產品線已走到盡頭。"},{"en":"Without funding the project has reached the end of the road.","zh-TW":"沒有資金這個專案已走到了終點。"}]', 'expression'),
('think on your feet', '臨場應變；隨機應變', 'to respond or make decisions quickly under pressure', '[{"en":"Client presentations require you to think on your feet.","zh-TW":"客戶簡報要求你能臨場應變。"},{"en":"She thinks on her feet and handles any question.","zh-TW":"她能隨機應變並回答任何問題。"}]', 'expression'),
('advocate for', '倡導；支持', 'to publicly support or recommend a cause or person', '[{"en":"She advocates for inclusive hiring practices.","zh-TW":"她倡導包容性的招聘做法。"},{"en":"He advocates for greater transparency in reporting.","zh-TW":"他支持更高透明度的報告做法。"}]', 'phrasal verb'),
('align on', '就…達成一致；對齊', 'to reach agreement or consensus on something', '[{"en":"We need to align on the project objectives.","zh-TW":"我們需要就專案目標達成一致。"},{"en":"Both teams aligned on the launch date.","zh-TW":"兩個團隊就發布日期達成了一致。"}]', 'phrasal verb'),
('appeal to', '吸引；呼籲；上訴', 'to attract or make a request to someone', '[{"en":"This campaign appeals to young professionals.","zh-TW":"這次活動吸引年輕專業人士。"},{"en":"She appealed to the board for additional funding.","zh-TW":"她向董事會呼籲追加資金。"}]', 'phrasal verb'),
('circle back to', '稍後回到；稍後再討論', 'to return to a topic after addressing other matters', '[{"en":"Let us circle back to the budget in the next meeting.","zh-TW":"讓我們在下次會議回到預算問題。"},{"en":"I will circle back to your question after the break.","zh-TW":"休息後我再回到你的問題。"}]', 'phrasal verb'),
('close in on', '逼近；接近', 'to get progressively closer to a goal or target', '[{"en":"We are closing in on the annual revenue target.","zh-TW":"我們正在接近年度收入目標。"},{"en":"The team closed in on the deadline with extra effort.","zh-TW":"團隊加倍努力逐漸接近截止日期。"}]', 'phrasal verb'),
('consult with', '諮詢；與…商量', 'to seek advice or information from someone', '[{"en":"Before proceeding please consult with legal.","zh-TW":"在繼續之前請諮詢法務部門。"},{"en":"She consulted with three experts before deciding.","zh-TW":"她在決定前諮詢了三位專家。"}]', 'phrasal verb'),
('contribute to', '貢獻；有助於', 'to give something toward a result or goal', '[{"en":"Every team member contributes to the overall success.","zh-TW":"每位團隊成員都為整體成功做出貢獻。"},{"en":"Innovation contributes to long-term competitiveness.","zh-TW":"創新有助於長期競爭力。"}]', 'phrasal verb'),
('convert into', '轉換為；轉化成', 'to change something into a different form', '[{"en":"We converted the leads into paying customers.","zh-TW":"我們將潛在客戶轉化為付費客戶。"},{"en":"Data is converted into actionable insights.","zh-TW":"數據被轉化為可執行的洞見。"}]', 'phrasal verb'),
('curb back', '抑制；縮減', 'to reduce or limit the amount or extent of something', '[{"en":"We need to curb back unnecessary spending.","zh-TW":"我們需要抑制不必要的支出。"},{"en":"The management curbed back expansion after the downturn.","zh-TW":"經濟下行後管理層縮減了擴張。"}]', 'phrasal verb'),
('deconstruct', '分解；解構', 'to break down into component parts for analysis', '[{"en":"She deconstructed the issue to find the root cause.","zh-TW":"她分解了問題以找到根本原因。"},{"en":"We deconstructed the failed campaign to learn from it.","zh-TW":"我們解構了失敗的活動以從中學習。"}]', 'phrasal verb'),
('defer to', '尊重；遵從；讓步於', 'to yield to someone else''s authority or judgment', '[{"en":"In technical matters we defer to the engineering team.","zh-TW":"在技術問題上我們遵從工程團隊的判斷。"},{"en":"She deferred to the senior partner''s recommendation.","zh-TW":"她尊重了資深合夥人的建議。"}]', 'phrasal verb'),
('divert from', '偏離；轉移', 'to cause something to go in a different direction', '[{"en":"The discussion diverted from the main agenda.","zh-TW":"討論偏離了主要議程。"},{"en":"Do not divert from the key objectives.","zh-TW":"不要偏離關鍵目標。"}]', 'phrasal verb'),
('downgrade', '降級；降低評級', 'to lower in rank, quality, or importance', '[{"en":"The agency downgraded the company''s credit rating.","zh-TW":"機構下調了公司的信用評級。"},{"en":"We had to downgrade the project scope due to budget cuts.","zh-TW":"由於預算削減我們不得不降低專案範圍。"}]', 'phrasal verb'),
('draft out', '起草；草擬', 'to write or compose a first version of something', '[{"en":"Please draft out the key terms for the agreement.","zh-TW":"請起草協議的關鍵條款。"},{"en":"She drafted out the project brief over the weekend.","zh-TW":"她在週末草擬了專案說明。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('drive forward', '推動前進；積極推進', 'to make something progress or move ahead', '[{"en":"The CEO is committed to driving forward the transformation agenda.","zh-TW":"執行長致力於推動轉型議程前進。"},{"en":"Her energy drives the project forward.","zh-TW":"她的活力推動著專案向前推進。"}]', 'phrasal verb'),
('eliminate from', '從…中排除；淘汰', 'to remove or exclude from a group or process', '[{"en":"Several suppliers were eliminated from the shortlist.","zh-TW":"幾家供應商從最終名單中被排除了。"},{"en":"Eliminate from the options any that do not meet requirements.","zh-TW":"從選項中淘汰任何不符合要求的。"}]', 'phrasal verb'),
('escalate to', '向上呈報；升級到', 'to refer an issue to a higher level of authority', '[{"en":"Unresolved complaints are escalated to the director.","zh-TW":"未解決的投訴會向上呈報給總監。"},{"en":"She escalated the issue to senior management.","zh-TW":"她將問題升級到了高層管理。"}]', 'phrasal verb'),
('extend beyond', '超出；延伸超過', 'to go further in scope or duration than expected', '[{"en":"The timeline may extend beyond the initial estimate.","zh-TW":"時間表可能延伸超過最初的估算。"},{"en":"Impact extended beyond our target market.","zh-TW":"影響超出了我們的目標市場範圍。"}]', 'phrasal verb'),
('fund through', '通過…資助；透過籌資', 'to provide money via a specific source or mechanism', '[{"en":"The project was funded through venture capital.","zh-TW":"該專案通過風險投資資助。"},{"en":"We fund operations through subscription revenue.","zh-TW":"我們通過訂閱收入資助運作。"}]', 'phrasal verb'),
('out of sync', '不同步；不協調', 'not working together smoothly or in the same rhythm', '[{"en":"The two departments are out of sync on priorities.","zh-TW":"兩個部門在優先事項上不同步。"},{"en":"Our pricing is out of sync with market realities.","zh-TW":"我們的定價與市場現實不協調。"}]', 'business idiom'),
('outside the comfort zone', '超出舒適圈；走出舒適圈', 'beyond familiar or safe territory in terms of challenge', '[{"en":"Growth requires stepping outside your comfort zone.","zh-TW":"成長需要走出舒適圈。"},{"en":"She pushed her team outside their comfort zones.","zh-TW":"她推動團隊走出舒適圈。"}]', 'business idiom'),
('pain point analysis', '痛點分析', 'the process of identifying and analyzing specific customer problems', '[{"en":"A thorough pain point analysis guides product development.","zh-TW":"全面的痛點分析指導產品開發。"},{"en":"We used pain point analysis to redesign the user journey.","zh-TW":"我們使用痛點分析重新設計了用戶體驗旅程。"}]', 'business idiom'),
('passing the torch', '交棒；傳承', 'handing over responsibility or leadership to someone else', '[{"en":"The founder passed the torch to the new CEO.","zh-TW":"創辦人把棒子交給了新任執行長。"},{"en":"Passing the torch well ensures continuity.","zh-TW":"順利交棒確保了業務的延續性。"}]', 'business idiom'),
('pay lip service to', '口頭支持；言而無實', 'to express support without taking real action', '[{"en":"Do not just pay lip service to sustainability — act on it.","zh-TW":"不要只是口頭支持永續發展——付諸行動。"},{"en":"Some companies pay lip service to diversity.","zh-TW":"一些公司對多元化只是口頭支持。"}]', 'business idiom'),
('pick up steam', '逐漸加速；蒸蒸日上', 'to gain momentum and speed over time', '[{"en":"Sales are picking up steam after the initial launch.","zh-TW":"初次發布後銷售正在逐漸加速。"},{"en":"The new product line is picking up steam in Europe.","zh-TW":"新產品線在歐洲蒸蒸日上。"}]', 'business idiom'),
('play it safe', '謹慎行事；不冒險', 'to choose the cautious option to avoid risk', '[{"en":"In uncertain times we played it safe with investments.","zh-TW":"在不確定時期我們謹慎行事進行投資。"},{"en":"Playing it safe can mean missing out on big opportunities.","zh-TW":"謹慎行事可能意味著錯失重大機會。"}]', 'business idiom'),
('pound the pavement', '積極開展業務；挨家挨戶推銷', 'to actively work to develop sales or find opportunities', '[{"en":"The sales team pounded the pavement to find new accounts.","zh-TW":"銷售團隊積極開展業務尋找新客戶。"},{"en":"When starting out you have to pound the pavement.","zh-TW":"剛開始時你必須積極地跑業務。"}]', 'business idiom'),
('power play', '權力角力；強勢舉措', 'an attempt to gain power or leverage over others', '[{"en":"The CEO''s announcement was a strategic power play.","zh-TW":"執行長的公告是一個策略性的權力角力行動。"},{"en":"Acquiring the competitor was a power play.","zh-TW":"收購競爭對手是一個強勢舉措。"}]', 'business idiom'),
('price point', '價格點；價位', 'the specific price at which a product is sold to consumers', '[{"en":"We found the right price point to attract mid-market buyers.","zh-TW":"我們找到了吸引中端市場買家的合適價位。"},{"en":"The premium price point limits our customer base.","zh-TW":"高端價位限制了我們的客戶群。"}]', 'business idiom'),
('profit margin', '利潤率', 'the percentage of revenue that becomes profit', '[{"en":"Automation improved our profit margins significantly.","zh-TW":"自動化大幅提高了我們的利潤率。"},{"en":"Rising wages are compressing profit margins.","zh-TW":"不斷上漲的薪資正在壓縮利潤率。"}]', 'business idiom'),
('pull out all the stops', '不遺餘力；全力以赴', 'to do everything possible to achieve a goal', '[{"en":"We pulled out all the stops to win the contract.","zh-TW":"我們不遺餘力地爭取合同。"},{"en":"The event team pulled out all the stops for the gala.","zh-TW":"活動團隊為晚宴全力以赴。"}]', 'business idiom'),
('put something in motion', '啟動；使…開始運作', 'to start a process or plan in action', '[{"en":"The decision has put the restructuring in motion.","zh-TW":"這個決定啟動了重組進程。"},{"en":"She put the new strategy in motion immediately.","zh-TW":"她立即啟動了新策略的執行。"}]', 'business idiom'),
('raise the profile of', '提升…的知名度；提高曝光度', 'to increase awareness or prominence of something', '[{"en":"The campaign raised the profile of the charity.","zh-TW":"這次活動提升了慈善機構的知名度。"},{"en":"Public speaking helped raise her professional profile.","zh-TW":"公開演講有助於提升她的職業知名度。"}]', 'business idiom'),
('reality check', '現實核查；回歸現實', 'an assessment that brings expectations back to reality', '[{"en":"Before overpromising do a reality check on timelines.","zh-TW":"在過度承諾之前對時間表做一個現實核查。"},{"en":"The market data provided a sobering reality check.","zh-TW":"市場數據提供了一個讓人警醒的現實核查。"}]', 'business idiom'),
('results-driven', '以結果為導向', 'focused on achieving measurable outcomes', '[{"en":"Our company culture is results-driven above all.","zh-TW":"我們公司的文化首先是以結果為導向的。"},{"en":"She is a results-driven leader who expects delivery.","zh-TW":"她是一位以結果為導向、期望交付成果的領導者。"}]', 'business idiom'),
('risk appetite', '風險承受能力；風險偏好', 'the level of risk that an organization is willing to accept', '[{"en":"Our risk appetite determines where we invest.","zh-TW":"我們的風險承受能力決定了我們的投資方向。"},{"en":"The board''s risk appetite is conservative.","zh-TW":"董事會的風險偏好是保守的。"}]', 'business idiom'),
('run rings around', '遠超；把…比下去', 'to far outperform a competitor in skills or results', '[{"en":"Our product runs rings around the competition.","zh-TW":"我們的產品遠超競爭對手。"},{"en":"She ran rings around other candidates in the interview.","zh-TW":"她在面試中把其他候選人比下去了。"}]', 'business idiom'),
('sales funnel', '銷售漏斗；客戶轉化流程', 'the stages a customer goes through from awareness to purchase', '[{"en":"We optimized the sales funnel to increase conversion rates.","zh-TW":"我們優化了銷售漏斗以提高轉化率。"},{"en":"Leads enter the top of the sales funnel.","zh-TW":"潛在客戶從銷售漏斗頂端進入。"}]', 'business idiom'),
('scope creep', '範疇蔓延；工作範圍擴大', 'uncontrolled changes or continuous growth in project scope', '[{"en":"Scope creep delayed the project by three months.","zh-TW":"範疇蔓延使專案延遲了三個月。"},{"en":"Define deliverables clearly to prevent scope creep.","zh-TW":"明確定義交付物以防止範疇蔓延。"}]', 'business idiom'),
('turn over a new leaf', '改過自新；重新開始', 'to change behavior or start fresh with better practices', '[{"en":"After the failed quarter the team turned over a new leaf.","zh-TW":"糟糕的季度後團隊改過自新。"},{"en":"The new CEO turned over a new leaf in company culture.","zh-TW":"新任執行長在公司文化上開始了新篇章。"}]', 'expression'),
('under new management', '換了新管理層；新管理下', 'now being operated by different people in charge', '[{"en":"The division is under new management and improving rapidly.","zh-TW":"該部門換了新管理層，正在快速改善。"},{"en":"Under new management the brand regained customer trust.","zh-TW":"在新管理下品牌重新贏得了客戶信任。"}]', 'expression'),
('up for grabs', '待人爭奪；可供競爭', 'available to whoever can get it first', '[{"en":"Market share is up for grabs after the leader exited.","zh-TW":"行業領袖退出後市場份額待人爭奪。"},{"en":"Several senior positions are up for grabs.","zh-TW":"幾個高級職位目前可供競爭。"}]', 'expression'),
('value for money', '物有所值；性價比好', 'good quality relative to the price paid', '[{"en":"Clients expect value for money from every engagement.","zh-TW":"客戶期望每次合作都物有所值。"},{"en":"Our services consistently deliver value for money.","zh-TW":"我們的服務始終提供物有所值的體驗。"}]', 'expression'),
('walking a tightrope', '如履薄冰；要求極度謹慎', 'managing a very difficult situation requiring extreme care', '[{"en":"The CEO is walking a tightrope between cutting costs and retaining talent.","zh-TW":"執行長在削減成本和留住人才之間如履薄冰。"},{"en":"Balancing growth and profitability means walking a tightrope.","zh-TW":"平衡增長與盈利需要如履薄冰。"}]', 'expression'),
('with open arms', '熱誠歡迎；張開雙臂', 'in a very welcoming manner', '[{"en":"The team welcomed the new process with open arms.","zh-TW":"團隊熱情地歡迎了新流程。"},{"en":"Clients received our upgrade proposal with open arms.","zh-TW":"客戶熱誠接受了我們的升級提案。"}]', 'expression'),
('world-class', '世界一流的；頂尖的', 'of the highest international standard or quality', '[{"en":"Our goal is to deliver world-class customer service.","zh-TW":"我們的目標是提供世界一流的客戶服務。"},{"en":"World-class products require world-class processes.","zh-TW":"世界一流的產品需要頂尖的流程支撐。"}]', 'expression'),
('yield results', '產生結果；取得成效', 'to produce a positive outcome or effect', '[{"en":"The new strategy is already yielding results.","zh-TW":"新策略已開始取得成效。"},{"en":"Consistent effort yields results over time.","zh-TW":"持續的努力隨著時間的推移會產生結果。"}]', 'expression'),
('zero in on the target', '精準鎖定目標', 'to focus precisely and clearly on a specific objective', '[{"en":"We zeroed in on the target audience with data.","zh-TW":"我們憑藉數據精準鎖定了目標受眾。"},{"en":"Zero in on the target and do not get distracted.","zh-TW":"精準鎖定目標不要分心。"}]', 'expression'),
('add to the mix', '加入；納入考量', 'to include as an additional factor or element', '[{"en":"Adding flexibility to the mix improved team morale.","zh-TW":"將彈性加入其中提升了團隊士氣。"},{"en":"Social media was added to the marketing mix.","zh-TW":"社交媒體被納入行銷組合中。"}]', 'expression'),
('all things considered', '整體而言；綜合考量之下', 'considering all the relevant factors together', '[{"en":"All things considered the project was a success.","zh-TW":"整體而言這個專案是成功的。"},{"en":"All things considered I recommend we proceed.","zh-TW":"綜合考量之下我建議我們繼續推進。"}]', 'expression'),
('at first glance', '乍看之下；初看', 'when first viewed or considered', '[{"en":"At first glance the costs seem high but they are justified.","zh-TW":"乍看之下成本似乎很高但是是合理的。"},{"en":"At first glance the proposal looks promising.","zh-TW":"初看之下這份提案看起來很有前景。"}]', 'expression'),
('at one''s disposal', '可供某人使用；任某人支配', 'available for one''s use or benefit freely', '[{"en":"We have the best tools at our disposal.","zh-TW":"我們有最好的工具可以使用。"},{"en":"Put all available resources at the team''s disposal.","zh-TW":"將所有可用資源供團隊使用。"}]', 'expression'),
('be caught off guard', '被打個措手不及；出乎意料', 'to be surprised and unprepared for something', '[{"en":"The sudden market shift caught us off guard.","zh-TW":"突然的市場轉變打了我們個措手不及。"},{"en":"She was caught off guard by the client''s question.","zh-TW":"她被客戶的問題問得措手不及。"}]', 'expression'),
('beyond reasonable doubt', '超出合理懷疑；確鑿無疑', 'without any realistic possibility of being wrong', '[{"en":"The data proves beyond reasonable doubt that demand is growing.","zh-TW":"數據確鑿無疑地證明需求正在增長。"},{"en":"Beyond reasonable doubt this strategy is superior.","zh-TW":"無可置疑地這個策略更勝一籌。"}]', 'expression'),
('break ground on', '動工；開始建設', 'to start construction of a new building or initiative', '[{"en":"We broke ground on the new headquarters this spring.","zh-TW":"我們今春開始了新總部的建設。"},{"en":"Breaking ground on the factory marks a major milestone.","zh-TW":"工廠動工標誌著一個重要的里程碑。"}]', 'expression'),
('build a rapport', '建立良好關係；建立信任', 'to develop a harmonious and trusting relationship', '[{"en":"Building a rapport with clients leads to repeat business.","zh-TW":"與客戶建立良好關係帶來了回頭生意。"},{"en":"She has a natural ability to build rapport quickly.","zh-TW":"她有迅速建立信任關係的天賦。"}]', 'expression'),
('carry weight', '有份量；具有影響力', 'to have significant influence or importance', '[{"en":"Her endorsement carries significant weight.","zh-TW":"她的認可具有重大影響力。"},{"en":"That argument carries weight with the board.","zh-TW":"那個論點在董事會中很有份量。"}]', 'expression'),
('in a similar vein', '同樣地；類似地', 'in a related or similar way to what was just mentioned', '[{"en":"In a similar vein we should streamline procurement.","zh-TW":"同樣地我們應該精簡採購流程。"},{"en":"In a similar vein to the previous model this one excels.","zh-TW":"與前一個模型類似這個也表現出色。"}]', 'prepositional phrase'),
('off to a good start', '有個好的開始；開門紅', 'beginning well with positive initial results', '[{"en":"The new partnership is off to a good start.","zh-TW":"新合作關係有個好的開始。"},{"en":"We are off to a good start with over 100 sign-ups.","zh-TW":"我們開門紅獲得了超過100個注冊。"}]', 'prepositional phrase'),
('not to be underestimated', '不可低估', 'important or difficult enough that one should take it seriously', '[{"en":"The competitor is not to be underestimated.","zh-TW":"競爭對手不可低估。"},{"en":"The cost implications are not to be underestimated.","zh-TW":"成本影響不可低估。"}]', 'prepositional phrase'),
('on multiple fronts', '在多個方面；在多條戰線上', 'addressing several areas or challenges simultaneously', '[{"en":"The company is competing on multiple fronts.","zh-TW":"公司在多個方面同時展開競爭。"},{"en":"We are improving on multiple fronts this quarter.","zh-TW":"本季我們在多個方面取得了改進。"}]', 'prepositional phrase'),
('at your fingertips', '唾手可得；隨手可得', 'easily available or accessible when needed', '[{"en":"With this app all client data is at your fingertips.","zh-TW":"有了這個應用程式所有客戶數據唾手可得。"},{"en":"Good systems put decisions at your fingertips.","zh-TW":"好的系統讓決策資訊隨手可得。"}]', 'prepositional phrase'),
('free of charge', '免費；不收費', 'without any cost or payment required', '[{"en":"Shipping is free of charge for orders over 100.","zh-TW":"訂單超過100時免費送貨。"},{"en":"The consultation is provided free of charge.","zh-TW":"諮詢服務免費提供。"}]', 'prepositional phrase'),
('off the shelf', '現成的；不需定制的', 'available immediately without customization', '[{"en":"We chose an off-the-shelf software to reduce cost.","zh-TW":"我們選擇了現成的軟體以降低成本。"},{"en":"Not every solution needs to be custom — off the shelf works.","zh-TW":"並非每個解決方案都需要定制——現成的也可以。"}]', 'prepositional phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('on the cusp of', '在…的臨界點；即將', 'at the point of transitioning to a new state', '[{"en":"We are on the cusp of a major market breakthrough.","zh-TW":"我們即將迎來重大的市場突破。"},{"en":"The company is on the cusp of profitability.","zh-TW":"公司處於盈利的臨界點。"}]', 'prepositional phrase'),
('in accordance to', '按照；遵照', 'following or conforming to a standard or instruction', '[{"en":"All work must proceed in accordance to safety rules.","zh-TW":"所有工作必須按照安全規則進行。"},{"en":"In accordance to the SLA we respond within 24 hours.","zh-TW":"按照服務等級協議我們在24小時內回覆。"}]', 'prepositional phrase'),
('under the umbrella of', '在…的範疇下；屬於', 'falling within the scope or authority of a larger entity', '[{"en":"All subsidiaries operate under the umbrella of the parent company.","zh-TW":"所有子公司在母公司的範疇下運作。"},{"en":"The new initiative falls under the umbrella of corporate social responsibility.","zh-TW":"這項新計劃屬於企業社會責任的範疇。"}]', 'prepositional phrase'),
('within budget', '在預算內；不超支', 'not exceeding the amount of money allocated', '[{"en":"The renovation was completed within budget.","zh-TW":"翻新工程在預算內完成了。"},{"en":"It is essential to stay within budget this quarter.","zh-TW":"本季度保持在預算內至關重要。"}]', 'prepositional phrase'),
('at great lengths', '不厭其煩地；費盡心力地', 'with a great deal of effort or in great detail', '[{"en":"She went to great lengths to explain the risk factors.","zh-TW":"她不厭其煩地解釋了風險因素。"},{"en":"They went to great lengths to ensure client satisfaction.","zh-TW":"他們費盡心力確保客戶滿意度。"}]', 'prepositional phrase'),
('at the end of the day', '歸根究底；最後說來', 'ultimately or when everything is considered', '[{"en":"At the end of the day results speak for themselves.","zh-TW":"歸根究底成果自會說話。"},{"en":"At the end of the day client satisfaction is the priority.","zh-TW":"最後說來客戶滿意度是首要。"}]', 'prepositional phrase'),
('given the circumstances', '鑑於情況；考慮到當時的情形', 'considering the current situation or conditions', '[{"en":"Given the circumstances the team did remarkably well.","zh-TW":"鑑於情況團隊的表現非常出色。"},{"en":"Given the circumstances we chose the conservative option.","zh-TW":"考慮到當時的情形我們選擇了保守選項。"}]', 'prepositional phrase'),
('in many respects', '在許多方面；從多個角度', 'in several ways or from several points of view', '[{"en":"In many respects this year was better than the last.","zh-TW":"在許多方面今年比去年好。"},{"en":"In many respects the two products are similar.","zh-TW":"從多個角度來看這兩款產品是相似的。"}]', 'prepositional phrase'),
('in no uncertain terms', '毫不含糊地；直截了當地', 'in a way that is absolutely clear and unmistakable', '[{"en":"She told them in no uncertain terms to stop the practice.","zh-TW":"她毫不含糊地告訴他們停止這種做法。"},{"en":"The manager explained in no uncertain terms the expectations.","zh-TW":"主管直截了當地說明了期望。"}]', 'prepositional phrase'),
('in relation to', '與…相關；相較於', 'concerning or when compared to something', '[{"en":"Performance is evaluated in relation to set KPIs.","zh-TW":"績效是相較於設定的KPI來評估的。"},{"en":"In relation to competitors our pricing is competitive.","zh-TW":"與競爭對手相比我們的定價具有競爭力。"}]', 'prepositional phrase'),
('in the wake', '在…之後；隨之', 'following as a consequence of an event', '[{"en":"Changes were made in the wake of the data breach.","zh-TW":"數據洩露之後進行了相應的改變。"},{"en":"In the wake of staff departures morale was low.","zh-TW":"員工離職之後士氣低落。"}]', 'prepositional phrase'),
('to this end', '為此；為了這個目的', 'for this purpose; in order to achieve this goal', '[{"en":"To this end we have increased our R&D budget.","zh-TW":"為此我們增加了研發預算。"},{"en":"To this end she organized weekly review sessions.","zh-TW":"為了這個目的她組織了每週的審查會議。"}]', 'prepositional phrase'),
('against the backdrop of', '在…的背景下；以…為背景', 'as context or setting for something that is happening', '[{"en":"Against the backdrop of inflation we revised pricing.","zh-TW":"在通貨膨脹的背景下我們修訂了定價。"},{"en":"Against the backdrop of change we maintained stability.","zh-TW":"以變革為背景我們維持了穩定。"}]', 'prepositional phrase'),
('gather momentum', '積聚動力；加速', 'to build up increasing speed or support', '[{"en":"The campaign is gathering momentum.","zh-TW":"這次活動正在積聚動力。"},{"en":"The project gathered momentum after the first milestone.","zh-TW":"專案在第一個里程碑後加速推進。"}]', 'phrasal verb'),
('hold firm', '堅守立場；保持穩定', 'to remain resolute or stable under pressure', '[{"en":"We held firm on pricing despite pressure.","zh-TW":"我們在壓力下依然堅守定價立場。"},{"en":"The manager held firm on the quality standards.","zh-TW":"主管在品質標準上保持了堅定立場。"}]', 'phrasal verb'),
('link up', '建立聯繫；合作', 'to form a connection or partnership', '[{"en":"We linked up with a regional distributor.","zh-TW":"我們與一家區域分銷商建立了聯繫。"},{"en":"The two startups linked up to create a joint offering.","zh-TW":"兩家新創公司合作推出了聯合服務。"}]', 'phrasal verb'),
('move in on', '插足；進入競爭', 'to begin to compete in someone else''s territory', '[{"en":"Competitors are moving in on our client base.","zh-TW":"競爭對手正在插足我們的客戶群。"},{"en":"We moved in on the premium segment successfully.","zh-TW":"我們成功地進入了高端市場競爭。"}]', 'phrasal verb'),
('originate from', '來自；起源於', 'to begin or develop from a particular place or cause', '[{"en":"The idea originated from a customer complaint.","zh-TW":"這個想法來源於一則客戶投訴。"},{"en":"Delays originate from poor planning.","zh-TW":"延誤源自規劃不足。"}]', 'phrasal verb'),
('pool resources', '整合資源；共享資源', 'to combine resources or skills with others', '[{"en":"The two firms pooled resources for the joint project.","zh-TW":"兩家公司整合資源進行了合作專案。"},{"en":"Pooling resources reduces duplication.","zh-TW":"整合資源減少了重複工作。"}]', 'phrasal verb'),
('put to use', '加以利用；付諸實施', 'to use something for a practical purpose', '[{"en":"She put her analytical skills to use on the project.","zh-TW":"她在專案中加以利用了她的分析技能。"},{"en":"Put this feedback to use to improve the service.","zh-TW":"將這份反饋付諸實施以改善服務。"}]', 'phrasal verb'),
('regroup', '重新集結；重新組織', 'to reorganize after a setback or to plan afresh', '[{"en":"After the failed product launch the team regrouped.","zh-TW":"產品發布失敗後團隊重新集結。"},{"en":"They regrouped and came back with a stronger strategy.","zh-TW":"他們重新組織並帶著更強的策略回來了。"}]', 'phrasal verb'),
('restructure around', '以…為中心重組；圍繞…重構', 'to reorganize with a specific focus or principle', '[{"en":"We restructured around client needs.","zh-TW":"我們以客戶需求為中心重新組織架構。"},{"en":"The team was restructured around three product areas.","zh-TW":"團隊圍繞三個產品領域進行了重組。"}]', 'phrasal verb'),
('sharpen up', '提高；改善；加強', 'to improve performance, skills, or processes', '[{"en":"We need to sharpen up our proposal writing.","zh-TW":"我們需要提高提案撰寫能力。"},{"en":"She sharpened up the team''s presentation skills.","zh-TW":"她提高了團隊的簡報技能。"}]', 'phrasal verb'),
('spell out', '明確說明；逐一解釋', 'to explain something in detail so there is no ambiguity', '[{"en":"Please spell out the deliverables in the contract.","zh-TW":"請在合同中明確說明交付物。"},{"en":"She spelled out the expectations to the new hire.","zh-TW":"她向新員工逐一說明了期望。"}]', 'phrasal verb'),
('spin off', '分拆；衍生出', 'to create a separate company from part of an existing one', '[{"en":"The tech division was spun off as an independent company.","zh-TW":"技術部門被分拆為獨立公司。"},{"en":"The new brand is a spin-off of the parent company.","zh-TW":"新品牌是母公司的衍生品牌。"}]', 'phrasal verb'),
('stand behind', '支持；擔保', 'to confirm support for a decision or product', '[{"en":"We stand behind the quality of every product we sell.","zh-TW":"我們對所售每款產品的品質提供擔保。"},{"en":"She stood behind her team''s recommendation.","zh-TW":"她支持了團隊的建議。"}]', 'phrasal verb'),
('submit for', '提交；送交審批', 'to formally send something for review or approval', '[{"en":"The report was submitted for board review.","zh-TW":"報告已提交給董事會審查。"},{"en":"Please submit for signature by end of day.","zh-TW":"請在今天下班前提交簽字。"}]', 'phrasal verb'),
('supplement with', '以…補充；輔以', 'to add to or enhance something with additional elements', '[{"en":"We supplemented the workshop with online materials.","zh-TW":"我們以線上材料補充了研討會內容。"},{"en":"Supplement the report with charts for clarity.","zh-TW":"用圖表補充報告以增加清晰度。"}]', 'phrasal verb'),
('tackle head-on', '正面應對；迎頭解決', 'to deal with a problem directly and without hesitation', '[{"en":"We tackled the compliance issue head-on.","zh-TW":"我們正面應對了合規問題。"},{"en":"She tackled the conflict head-on and resolved it.","zh-TW":"她迎頭解決了衝突。"}]', 'phrasal verb'),
('tailor to', '針對…量身定制；客製化', 'to adapt something specifically for a particular need', '[{"en":"The training is tailored to each department''s needs.","zh-TW":"培訓是針對每個部門的需求量身定制的。"},{"en":"We tailor our services to each client.","zh-TW":"我們為每位客戶量身定制服務。"}]', 'phrasal verb'),
('test out', '測試；試驗', 'to evaluate whether something works by trying it', '[{"en":"We will test out the new interface with a sample group.","zh-TW":"我們將用一個樣本群體測試新界面。"},{"en":"She tested out the approach in a small pilot.","zh-TW":"她在一個小型試點中測試了這個方法。"}]', 'phrasal verb'),
('threshold on', '達到…門檻；越過界限', 'to cross or set a minimum level or limit', '[{"en":"Set a threshold on expenses before escalating.","zh-TW":"在升級之前為費用設定門檻。"},{"en":"The threshold on losses triggers an automatic review.","zh-TW":"損失門檻觸發自動審查。"}]', 'phrasal verb'),
('train up', '培訓；培養至勝任', 'to give someone the training needed to do a job well', '[{"en":"We trained up the team before the system went live.","zh-TW":"系統上線前我們對團隊進行了培訓。"},{"en":"New hires are trained up within their first month.","zh-TW":"新員工在入職第一個月內接受培訓。"}]', 'phrasal verb'),
('unlock potential', '釋放潛力；激發潛能', 'to reveal or enable hidden capability or value', '[{"en":"Good management unlocks potential in every team member.","zh-TW":"好的管理能夠釋放每個團隊成員的潛力。"},{"en":"AI helps unlock potential in large data sets.","zh-TW":"人工智慧幫助激發大型數據集的潛能。"}]', 'phrasal verb'),
('vary across', '在…之間有所不同；因…而異', 'to differ depending on the context or group', '[{"en":"Pricing strategies vary across different regions.","zh-TW":"定價策略因地區不同而有所差異。"},{"en":"Performance levels vary across team members.","zh-TW":"各團隊成員的績效水準因人而異。"}]', 'phrasal verb'),
('weigh against', '與…比較衡量；考慮利弊', 'to consider the disadvantage of something against its benefit', '[{"en":"Weigh the cost against the long-term benefit.","zh-TW":"把成本與長期效益進行比較衡量。"},{"en":"She weighed the risk against the potential return.","zh-TW":"她將風險與潛在回報進行了比較衡量。"}]', 'phrasal verb'),
('work toward', '努力朝向；致力於', 'to make progress or effort toward achieving a goal', '[{"en":"Both parties are working toward a resolution.","zh-TW":"雙方正在努力朝向解決方案前進。"},{"en":"We are working toward industry certification.","zh-TW":"我們正致力於獲取行業認證。"}]', 'phrasal verb'),
('zero tolerance for', '對…零容忍', 'to completely refuse to accept any instance of something', '[{"en":"We have zero tolerance for discrimination.","zh-TW":"我們對歧視行為零容忍。"},{"en":"Zero tolerance for data breaches was our policy.","zh-TW":"對數據洩露零容忍是我們的政策。"}]', 'phrasal verb'),
('cash flow positive', '現金流為正；現金流盈餘', 'having more cash coming in than going out', '[{"en":"The startup became cash flow positive in year two.","zh-TW":"這家新創公司在第二年實現了現金流為正。"},{"en":"Being cash flow positive is essential for sustainability.","zh-TW":"現金流為正對可持續發展至關重要。"}]', 'business idiom'),
('change agent', '變革推動者；推動改革的人', 'a person who actively works to bring about organizational change', '[{"en":"She acts as a change agent in the digital transformation.","zh-TW":"她在數位轉型中擔任變革推動者。"},{"en":"Change agents are essential for organizational growth.","zh-TW":"變革推動者對組織成長至關重要。"}]', 'business idiom'),
('churn rate', '客戶流失率', 'the rate at which customers stop using a product or service', '[{"en":"A high churn rate signals customer dissatisfaction.","zh-TW":"高客戶流失率表明客戶不滿意。"},{"en":"We focused on support to reduce churn rate.","zh-TW":"我們專注於支援以降低客戶流失率。"}]', 'business idiom'),
('collateral damage', '附帶損失；連帶受害', 'unintended harm caused to people not directly targeted', '[{"en":"The cost cuts caused collateral damage to morale.","zh-TW":"成本削減對士氣造成了附帶損失。"},{"en":"Minimize collateral damage when making major changes.","zh-TW":"進行重大變革時要將附帶損失降到最低。"}]', 'business idiom'),
('content is king', '內容為王', 'valuable content is the most important driver of online success', '[{"en":"In digital marketing content is king.","zh-TW":"在數位行銷中內容為王。"},{"en":"She built her strategy around content is king.","zh-TW":"她圍繞內容為王的原則建立了策略。"}]', 'business idiom'),
('cookie-cutter approach', '千篇一律的方法；模板式做法', 'a standardized approach applied without regard for individual differences', '[{"en":"Avoid a cookie-cutter approach with enterprise clients.","zh-TW":"對企業客戶避免千篇一律的方法。"},{"en":"A cookie-cutter approach rarely works in complex markets.","zh-TW":"在複雜市場中千篇一律的做法很少奏效。"}]', 'business idiom'),
('corporate ladder', '職業晉升階梯；職場等級', 'the hierarchical structure of advancement in a company', '[{"en":"She climbed the corporate ladder through hard work.","zh-TW":"她通過努力工作攀上了職業晉升階梯。"},{"en":"Success on the corporate ladder requires both skill and networking.","zh-TW":"在職場等級上取得成功需要技能和人脈。"}]', 'business idiom'),
('creative destruction', '創造性破壞；破舊立新', 'innovation that destroys old industries while creating new ones', '[{"en":"Creative destruction is reshaping the retail industry.","zh-TW":"創造性破壞正在重塑零售業。"},{"en":"Digital platforms are agents of creative destruction.","zh-TW":"數位平台是創造性破壞的推動者。"}]', 'business idiom'),
('cross-functional team', '跨職能團隊', 'a team with members from different departments or functions', '[{"en":"A cross-functional team was assembled for the launch.","zh-TW":"為了發布活動組建了一個跨職能團隊。"},{"en":"Cross-functional teams drive better innovation.","zh-TW":"跨職能團隊推動更好的創新。"}]', 'business idiom'),
('cross-sell', '交叉銷售；推銷相關產品', 'to sell additional related products to an existing customer', '[{"en":"We cross-sell insurance products to banking clients.","zh-TW":"我們向銀行客戶進行保險產品的交叉銷售。"},{"en":"Cross-selling is a cost-effective growth strategy.","zh-TW":"交叉銷售是具有成本效益的增長策略。"}]', 'business idiom'),
('customer-centric', '以客戶為中心的', 'placing the customer''s needs and experience at the core of decisions', '[{"en":"Our customer-centric approach has driven loyalty.","zh-TW":"我們以客戶為中心的方法推動了忠誠度。"},{"en":"Being customer-centric means listening to feedback.","zh-TW":"以客戶為中心意味著傾聽反饋。"}]', 'business idiom'),
('data-driven decision making', '數據驅動決策', 'using data and analysis as the basis for business decisions', '[{"en":"We moved to data-driven decision making company-wide.","zh-TW":"我們在全公司推行數據驅動決策。"},{"en":"Data-driven decision making reduces guesswork.","zh-TW":"數據驅動決策減少了猜測。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('day one mentality', '第一天心態；保持創業初心', 'maintaining the energy and urgency of a startup even as a large company', '[{"en":"Amazon is famous for its day one mentality.","zh-TW":"亞馬遜以保持第一天心態而聞名。"},{"en":"A day one mentality drives continuous innovation.","zh-TW":"第一天心態推動持續創新。"}]', 'business idiom'),
('deal breaker', '交易破局點；不可接受的條件', 'a condition that would prevent agreement if not met', '[{"en":"The payment terms were a deal breaker for us.","zh-TW":"付款條款對我們來說是交易破局點。"},{"en":"Identify deal breakers early to save time.","zh-TW":"早期識別不可接受的條件以節省時間。"}]', 'business idiom'),
('decision tree', '決策樹；決策圖', 'a diagram showing choices and their consequences to aid decisions', '[{"en":"We used a decision tree to map out options.","zh-TW":"我們使用決策樹來映射選項。"},{"en":"A decision tree helps visualize complex choices.","zh-TW":"決策樹有助於視覺化複雜的選擇。"}]', 'business idiom'),
('deep pockets', '財力雄厚；資金充裕', 'having a lot of money available to spend', '[{"en":"Entering that market requires deep pockets.","zh-TW":"進入那個市場需要財力雄厚。"},{"en":"Competitors with deep pockets can outspend us.","zh-TW":"財力雄厚的競爭對手在支出上可以超過我們。"}]', 'business idiom'),
('deliverable', '交付物；成果物', 'a product or result that must be produced and delivered', '[{"en":"Each phase has specific deliverables and deadlines.","zh-TW":"每個階段都有特定的交付物和截止日期。"},{"en":"Review deliverables with the client before starting.","zh-TW":"在開始前與客戶審查交付物。"}]', 'business idiom'),
('demand generation', '需求創造；需求拉動', 'marketing activities aimed at generating awareness and demand', '[{"en":"Demand generation is the foundation of our growth strategy.","zh-TW":"需求創造是我們增長策略的基礎。"},{"en":"Content marketing drives demand generation effectively.","zh-TW":"內容行銷有效地推動需求創造。"}]', 'business idiom'),
('differentiated offering', '差異化產品；差異化服務', 'a product or service that stands out from competitors', '[{"en":"Our differentiated offering is based on superior support.","zh-TW":"我們的差異化服務基於卓越的支援。"},{"en":"A differentiated offering is key to winning clients.","zh-TW":"差異化產品是贏得客戶的關鍵。"}]', 'business idiom'),
('digital footprint', '數位足跡；網路影響力', 'the trail of data left by an organization''s online activities', '[{"en":"Building a digital footprint helps attract talent.","zh-TW":"建立數位足跡有助於吸引人才。"},{"en":"Their digital footprint grew after the rebranding.","zh-TW":"品牌重塑後他們的數位影響力增長了。"}]', 'business idiom'),
('digital transformation', '數位轉型', 'integrating digital technology into all areas of a business', '[{"en":"Digital transformation is essential for modern businesses.","zh-TW":"數位轉型對現代企業至關重要。"},{"en":"She led the digital transformation of the entire division.","zh-TW":"她主導了整個部門的數位轉型。"}]', 'business idiom'),
('disruptive technology', '顛覆性技術', 'technology that fundamentally changes an industry or market', '[{"en":"Blockchain is a disruptive technology in finance.","zh-TW":"區塊鏈是金融業的顛覆性技術。"},{"en":"Disruptive technology creates both risk and opportunity.","zh-TW":"顛覆性技術既帶來風險也帶來機遇。"}]', 'business idiom'),
('due diligence process', '盡職調查流程', 'the systematic procedure for evaluating a business before a deal', '[{"en":"The due diligence process uncovered significant liabilities.","zh-TW":"盡職調查流程揭示了重大負債。"},{"en":"A rigorous due diligence process protects investors.","zh-TW":"嚴格的盡職調查流程保護投資者。"}]', 'business idiom'),
('economies of scope', '範疇經濟；多元化成本優勢', 'cost advantages from producing multiple products together', '[{"en":"Economies of scope allow us to serve multiple segments efficiently.","zh-TW":"範疇經濟使我們能夠高效服務多個市場細分。"},{"en":"The merger created economies of scope across divisions.","zh-TW":"合併在各部門創造了範疇經濟效益。"}]', 'business idiom'),
('end game', '最終目標；最終結局', 'the final stage or ultimate goal of a strategy', '[{"en":"What is the end game of this acquisition?","zh-TW":"這次收購的最終目標是什麼？"},{"en":"Define the end game before committing resources.","zh-TW":"在投入資源前確定最終目標。"}]', 'business idiom'),
('act on', '依據…採取行動；落實', 'to take action based on information or advice', '[{"en":"We acted on the consultant''s recommendations immediately.","zh-TW":"我們立即依據顧問的建議採取了行動。"},{"en":"They failed to act on the early warning signs.","zh-TW":"他們未能對早期預警信號採取行動。"}]', 'phrasal verb'),
('add up', '累計；合計；說得通', 'to total a sum; to make sense logically', '[{"en":"The expenses add up to more than we budgeted.","zh-TW":"費用累計超過了我們的預算。"},{"en":"His explanation just doesn''t add up.","zh-TW":"他的解釋就是說不通。"}]', 'phrasal verb'),
('adhere to', '遵守；堅持；遵循', 'to follow rules, plans, or principles strictly', '[{"en":"All teams must adhere to the new compliance policy.","zh-TW":"所有團隊必須遵守新的合規政策。"},{"en":"We adhere to international quality standards.","zh-TW":"我們遵循國際品質標準。"}]', 'phrasal verb'),
('align with', '與…一致；符合', 'to be in agreement or consistent with something', '[{"en":"Our proposal aligns with the company''s long-term strategy.","zh-TW":"我們的提案與公司的長期策略一致。"},{"en":"Ensure your KPIs align with organizational objectives.","zh-TW":"確保你的關鍵績效指標與組織目標一致。"}]', 'phrasal verb'),
('answer to', '向…負責；向…匯報', 'to be accountable to someone; to report to a superior', '[{"en":"The project manager answers to the VP of Operations.","zh-TW":"專案經理向營運副總裁匯報。"},{"en":"Every team member answers to their direct supervisor.","zh-TW":"每位團隊成員都向其直屬上司負責。"}]', 'phrasal verb'),
('apply for', '申請', 'to formally request something such as a job or funding', '[{"en":"She applied for the senior analyst position last week.","zh-TW":"她上週申請了高級分析師職位。"},{"en":"We are applying for a government innovation grant.","zh-TW":"我們正在申請政府創新補助。"}]', 'phrasal verb'),
('ask for', '要求；請求', 'to request something from someone', '[{"en":"Don''t hesitate to ask for clarification during meetings.","zh-TW":"在會議中不要猶豫，請求澄清。"},{"en":"We asked for an extension on the deadline.","zh-TW":"我們請求延長截止日期。"}]', 'phrasal verb'),
('back down', '退讓；讓步；撤回立場', 'to withdraw from a claim or position under pressure', '[{"en":"He refused to back down from his pricing proposal.","zh-TW":"他拒絕從定價提案上退讓。"},{"en":"She backed down when presented with the data.","zh-TW":"面對數據後她撤回了立場。"}]', 'phrasal verb'),
('bank on', '依賴；指望；寄望於', 'to rely heavily on something happening', '[{"en":"Don''t bank on landing that account this quarter.","zh-TW":"這個季度不要太指望拿下那個客戶。"},{"en":"We banked on the market recovering quickly.","zh-TW":"我們寄望於市場迅速復甦。"}]', 'phrasal verb'),
('bear out', '證實；支持（說法）', 'to confirm or support the truth of something', '[{"en":"The sales figures bear out our earlier forecast.","zh-TW":"銷售數字證實了我們早前的預測。"},{"en":"The research bears out the hypothesis.","zh-TW":"研究支持了這個假說。"}]', 'phrasal verb'),
('block out', '預留時間；遮蔽；屏蔽', 'to reserve time in a schedule; to prevent something from entering', '[{"en":"Block out two hours on Friday for strategic planning.","zh-TW":"在週五預留兩個小時用於策略規劃。"},{"en":"Use noise-canceling headphones to block out distractions.","zh-TW":"使用降噪耳機來屏蔽干擾。"}]', 'phrasal verb'),
('bottom out', '跌到谷底；達到最低點', 'to reach the lowest point before recovering', '[{"en":"Sales bottomed out in Q2 before recovering.","zh-TW":"銷售在第二季跌到谷底後才開始回升。"},{"en":"The stock price bottomed out at five dollars.","zh-TW":"股價跌至谷底為五美元。"}]', 'phrasal verb'),
('burn through', '燒錢；快速耗盡（資源）', 'to use up money or resources rapidly', '[{"en":"The startup burned through its funding in six months.","zh-TW":"這家新創公司在六個月內燒光了資金。"},{"en":"Be careful not to burn through your goodwill too quickly.","zh-TW":"注意不要過快消耗你積累的商譽。"}]', 'phrasal verb'),
('buy in', '認同；取得支持；入股', 'to agree with and support an idea; to purchase a stake', '[{"en":"We need senior leadership to buy in to the new strategy.","zh-TW":"我們需要高層管理人員認同新策略。"},{"en":"She bought in to the startup early and profited greatly.","zh-TW":"她早期入股了這家新創公司並獲得了豐厚回報。"}]', 'phrasal verb'),
('buy out', '收購；買斷；買走（股份）', 'to purchase all shares or interests from a partner or owner', '[{"en":"The firm bought out its minority partner last year.","zh-TW":"這家公司去年買斷了少數股東的股份。"},{"en":"They plan to buy out the founders after the IPO.","zh-TW":"他們計劃在首次公開發行後買斷創始人股份。"}]', 'phrasal verb'),
('carry forward', '結轉；延續；繼承', 'to transfer a balance or principle to the next period or context', '[{"en":"Unused vacation days can be carried forward to next year.","zh-TW":"未使用的假期可以結轉到明年。"},{"en":"Carry forward the lessons from this project.","zh-TW":"延續這個專案的經驗教訓。"}]', 'phrasal verb'),
('cash in', '兌現；從…獲益；套現', 'to convert assets into money; to take advantage of an opportunity', '[{"en":"He cashed in his stock options before the dip.","zh-TW":"他在股價下跌前兌現了股票期權。"},{"en":"The company cashed in on the e-commerce boom.","zh-TW":"該公司從電子商務熱潮中獲益。"}]', 'phrasal verb'),
('chase down', '追查；追蹤；催要', 'to follow up persistently to obtain something or find information', '[{"en":"I had to chase down three clients for overdue invoices.","zh-TW":"我不得不催促三位客戶支付逾期發票。"},{"en":"She chased down the missing data before the report deadline.","zh-TW":"她在報告截止前追查到了遺失的數據。"}]', 'phrasal verb'),
('a bitter pill to swallow', '難以接受的事；苦澀的教訓', 'something unpleasant that must be accepted', '[{"en":"Losing that contract was a bitter pill to swallow.","zh-TW":"失去那份合約是一件難以接受的事。"},{"en":"The pay cut was a bitter pill to swallow for everyone.","zh-TW":"減薪對所有人來說都是難以接受的事。"}]', 'expression'),
('a catch-22 situation', '兩難困境；無論怎樣都有問題的局面', 'a paradoxical situation where no good solution exists', '[{"en":"It''s a catch-22 situation — we need experience to get the job but need the job for experience.","zh-TW":"這是兩難困境——我們需要經驗才能獲得工作，但需要工作來獲取經驗。"},{"en":"The budget freeze created a catch-22 situation for expansion.","zh-TW":"預算凍結為擴張創造了兩難困境。"}]', 'expression'),
('a step in the right direction', '朝正確方向邁出的一步', 'progress that moves toward a goal, even if it''s small', '[{"en":"The new policy is a step in the right direction.","zh-TW":"新政策是朝正確方向邁出的一步。"},{"en":"Approving the pilot is a step in the right direction.","zh-TW":"批准試點項目是朝正確方向邁出的一步。"}]', 'expression'),
('all hands on deck', '全體出動；全力以赴', 'everyone is needed to help with an urgent situation', '[{"en":"It''s all hands on deck for the product launch.","zh-TW":"為了產品發布大家全體出動。"},{"en":"All hands on deck when the system goes down.","zh-TW":"系統崩潰時需要全員全力以赴。"}]', 'expression'),
('back to basics', '回歸基本；返璞歸真', 'returning to simple, fundamental principles', '[{"en":"After several failed initiatives we went back to basics.","zh-TW":"幾次失敗的計劃後我們回歸了基本原則。"},{"en":"The new manager advocated going back to basics.","zh-TW":"新任經理倡導回歸基本。"}]', 'expression'),
('bear the brunt', '承受主要的衝擊；首當其衝', 'to suffer the worst part of something unpleasant', '[{"en":"The front-line staff bore the brunt of customer complaints.","zh-TW":"前線員工首當其衝承受了客戶投訴。"},{"en":"The sales team bore the brunt of the market downturn.","zh-TW":"銷售團隊承受了市場下滑的主要衝擊。"}]', 'expression'),
('burning platform', '燃燒的平台；迫切的危機', 'a situation so urgent that immediate action is required', '[{"en":"Leadership used the data breach as a burning platform for IT reform.","zh-TW":"領導層利用數據洩露事件作為推動IT改革的迫切危機。"},{"en":"A burning platform can motivate rapid organizational change.","zh-TW":"迫切的危機能夠推動快速的組織變革。"}]', 'expression'),
('by the same token', '同樣地；基於同樣的理由', 'in the same way or for the same reason', '[{"en":"We reward hard work; by the same token we address underperformance.","zh-TW":"我們獎勵努力工作；同樣地我們也處理表現不佳的問題。"},{"en":"By the same token if targets rise bonuses also rise.","zh-TW":"基於同樣的理由，如果目標提高獎金也會提高。"}]', 'expression'),
('call a spade a spade', '直言不諱；實話實說', 'to speak plainly and honestly, even if uncomfortable', '[{"en":"The manager called a spade a spade about the project''s failures.","zh-TW":"經理對專案的失敗直言不諱。"},{"en":"In performance reviews we call a spade a spade.","zh-TW":"在績效審查中我們實話實說。"}]', 'expression'),
('change horses midstream', '中途換人；中途改變計劃', 'to change strategy or leadership in the middle of a project', '[{"en":"Changing horses midstream disrupted the project timeline.","zh-TW":"中途換人打亂了專案時間表。"},{"en":"It''s risky to change horses midstream in a product launch.","zh-TW":"在產品發布中途改變計劃是有風險的。"}]', 'expression'),
('clear the decks', '清理工作；清除障礙；準備就緒', 'to remove obstacles or distractions to prepare for action', '[{"en":"Clear the decks before the new project kicks off.","zh-TW":"在新專案啟動前清理工作。"},{"en":"We cleared the decks of low-priority tasks to focus on the launch.","zh-TW":"我們清除了低優先級任務以專注於發布。"}]', 'expression'),
('climb on the bandwagon', '跟風；隨波逐流', 'to join a trend or popular movement, often without deep conviction', '[{"en":"Every firm seems to be climbing on the AI bandwagon.","zh-TW":"每家公司似乎都在跟風人工智慧浪潮。"},{"en":"Don''t just climb on the bandwagon — ensure it fits your strategy.","zh-TW":"不要只是跟風——確保它符合你的策略。"}]', 'expression'),
('come up short', '未達標；不足；差一點', 'to fail to meet a goal or expectation', '[{"en":"We came up short of our revenue target this quarter.","zh-TW":"本季我們未達到收入目標。"},{"en":"The proposal came up short on key details.","zh-TW":"提案在關鍵細節上有所不足。"}]', 'expression'),
('connect the dots', '串連線索；理清脈絡', 'to find the relationship between separate pieces of information', '[{"en":"The analyst connected the dots to uncover the fraud.","zh-TW":"分析師串連了線索揭露了詐騙行為。"},{"en":"Connect the dots between customer feedback and product issues.","zh-TW":"理清客戶反饋與產品問題之間的脈絡。"}]', 'expression'),
('cost an arm and a leg', '花費昂貴；所費不貲', 'to be very expensive', '[{"en":"Hiring top talent in this city costs an arm and a leg.","zh-TW":"在這座城市招募頂尖人才所費不貲。"},{"en":"The renovation is going to cost an arm and a leg.","zh-TW":"這次翻新將會花費昂貴。"}]', 'expression'),
('count one''s chickens before they hatch', '過早樂觀；打如意算盤', 'to make plans based on something that hasn''t happened yet', '[{"en":"Don''t count your chickens before they hatch — the deal isn''t signed yet.","zh-TW":"別打如意算盤——合約還沒簽。"},{"en":"Forecasting huge profits before launch is counting chickens.","zh-TW":"在發布前預測巨大利潤是打如意算盤。"}]', 'expression'),
('at arm''s length', '保持距離；客觀獨立（的關係）', 'maintaining an independent, non-personal relationship', '[{"en":"Keep contractors at arm''s length during the bid process.","zh-TW":"在投標過程中與承包商保持適當距離。"},{"en":"The board is kept at arm''s length from daily operations.","zh-TW":"董事會與日常業務保持客觀獨立的距離。"}]', 'prepositional phrase'),
('at breakneck speed', '以飛快的速度；極速地', 'at an extremely fast and possibly dangerous pace', '[{"en":"The startup expanded at breakneck speed last year.","zh-TW":"這家新創公司去年以飛快的速度擴張。"},{"en":"Technology is advancing at breakneck speed.","zh-TW":"技術正在以極快的速度進步。"}]', 'prepositional phrase'),
('at the helm', '掌舵；擔任領導職位', 'in charge or in a leadership position', '[{"en":"She has been at the helm of the company for five years.","zh-TW":"她擔任公司領導職位已有五年。"},{"en":"With an experienced CEO at the helm growth accelerated.","zh-TW":"在經驗豐富的執行長掌舵下，成長加速了。"}]', 'prepositional phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('below the radar', '未引起注意；低調', 'not attracting attention or notice', '[{"en":"The competitor has been operating below the radar.","zh-TW":"這個競爭對手一直在低調運營。"},{"en":"We kept the new product below the radar until launch.","zh-TW":"我們在發布前讓新產品保持低調。"}]', 'prepositional phrase'),
('beyond one''s control', '超出控制範圍；無法控制的', 'outside the ability to influence or manage', '[{"en":"The delay is beyond our control due to weather.","zh-TW":"由於天氣原因，延誤超出了我們的控制範圍。"},{"en":"Some risks are beyond any team''s control.","zh-TW":"有些風險超出任何團隊的控制範圍。"}]', 'prepositional phrase'),
('by default', '預設情況下；在無其他選項時', 'because no other option was chosen; as a fallback', '[{"en":"We won the contract by default when the rival withdrew.","zh-TW":"競爭對手退出後，我們預設獲得了合約。"},{"en":"By default the system logs all transactions.","zh-TW":"預設情況下系統記錄所有交易。"}]', 'prepositional phrase'),
('contrary to expectations', '與預期相反；出乎意料地', 'opposite to what was expected or predicted', '[{"en":"Contrary to expectations sales rose in Q4.","zh-TW":"與預期相反，第四季銷售額上升了。"},{"en":"Contrary to expectations the product found a new market.","zh-TW":"出乎意料地，產品找到了新市場。"}]', 'prepositional phrase'),
('down to the wire', '到最後一刻；直到最後關頭', 'continuing until the very last moment', '[{"en":"Negotiations went down to the wire before an agreement was reached.","zh-TW":"談判持續到最後一刻才達成協議。"},{"en":"The project was completed down to the wire.","zh-TW":"專案一直到最後關頭才完成。"}]', 'prepositional phrase'),
('for good measure', '附帶地；順便再加上', 'in addition to what is needed, as an extra precaution or bonus', '[{"en":"He added a year of warranty for good measure.","zh-TW":"他附帶地增加了一年保固。"},{"en":"Send the summary and attach the original report for good measure.","zh-TW":"傳送摘要並附上原始報告以作補充。"}]', 'prepositional phrase'),
('for the record', '為了存檔；鄭重聲明', 'stated formally so it is noted or documented', '[{"en":"For the record I objected to this proposal from the start.","zh-TW":"鄭重聲明，我從一開始就反對這個提案。"},{"en":"Let me note for the record that the budget was approved.","zh-TW":"為了存檔，我要記錄預算已獲批准。"}]', 'prepositional phrase'),
('close out', '結清；結束；平倉', 'to finalize or conclude; to clear remaining inventory or positions', '[{"en":"We need to close out the project before year end.","zh-TW":"我們需要在年底前結束這個專案。"},{"en":"Close out the inventory at a discount to make space.","zh-TW":"以折扣清倉以騰出空間。"}]', 'phrasal verb'),
('come apart', '崩潰；分裂；瓦解', 'to fall apart or break down; to lose cohesion', '[{"en":"The plan came apart when the key vendor dropped out.","zh-TW":"當關鍵供應商退出後計劃崩潰了。"},{"en":"The team came apart under the pressure of tight deadlines.","zh-TW":"在緊迫截止日期的壓力下團隊開始瓦解。"}]', 'phrasal verb'),
('come around', '轉變立場；接受新想法', 'to change one''s opinion and agree with someone', '[{"en":"He eventually came around to supporting the new policy.","zh-TW":"他最終轉變立場，支持了新政策。"},{"en":"The board came around to the restructuring proposal.","zh-TW":"董事會最終接受了重組提案。"}]', 'phrasal verb'),
('cut across', '跨越；橫切；涉及多個領域', 'to affect or involve multiple categories or groups', '[{"en":"This policy cuts across all departments.","zh-TW":"這項政策涉及所有部門。"},{"en":"The initiative cuts across traditional industry boundaries.","zh-TW":"這項計劃跨越了傳統行業界限。"}]', 'phrasal verb'),
('dig into', '深入探討；仔細研究', 'to examine or explore something thoroughly', '[{"en":"Let''s dig into the Q3 numbers more carefully.","zh-TW":"讓我們更仔細地深入研究第三季的數字。"},{"en":"She dug into the customer complaints to find the root cause.","zh-TW":"她深入探討了客戶投訴以找到根本原因。"}]', 'phrasal verb'),
('double down', '加倍努力；加大投入', 'to increase commitment to a strategy or action', '[{"en":"We decided to double down on our core market.","zh-TW":"我們決定加倍投入核心市場。"},{"en":"Double down on what''s working before exploring new channels.","zh-TW":"在探索新渠道之前加倍專注於有效的方法。"}]', 'phrasal verb'),
('fire up', '激勵；激發熱情；啟動', 'to energize or motivate someone; to start a system', '[{"en":"The CEO''s speech fired up the sales team.","zh-TW":"執行長的演講激勵了銷售團隊。"},{"en":"Fire up the new CRM system before the client meeting.","zh-TW":"在客戶會議前啟動新的CRM系統。"}]', 'phrasal verb'),
('front-load', '前置（費用或工作量）；提前集中', 'to place a larger portion of work, cost, or effort at the beginning', '[{"en":"The project was front-loaded with heavy testing phases.","zh-TW":"這個專案在前期集中了大量測試階段。"},{"en":"Front-load training to avoid costly mistakes later.","zh-TW":"提前集中培訓以避免後期代價高昂的錯誤。"}]', 'phrasal verb'),
('gear up', '準備就緒；備戰；積極準備', 'to prepare or get ready for an activity or challenge', '[{"en":"We are gearing up for the busy holiday season.","zh-TW":"我們正在為繁忙的假日旺季準備就緒。"},{"en":"The factory geared up production ahead of peak demand.","zh-TW":"工廠在需求高峰前積極準備提升產量。"}]', 'phrasal verb'),
('get ahead', '取得進展；先行一步；超越', 'to make progress; to advance ahead of others', '[{"en":"To get ahead we must invest in talent development.","zh-TW":"要取得進展，我們必須投資人才發展。"},{"en":"Get ahead of the regulatory changes by acting now.","zh-TW":"現在採取行動，以便在監管變化前先行一步。"}]', 'phrasal verb'),
('deliver on the promise', '兌現承諾；落實諾言', 'to follow through on what was promised', '[{"en":"The product must deliver on the promise made in the ads.","zh-TW":"產品必須兌現廣告中所做的承諾。"},{"en":"Deliver on the promise or risk losing trust.","zh-TW":"兌現承諾否則會失去信任。"}]', 'expression'),
('dog-eat-dog', '弱肉強食；激烈競爭的', 'highly competitive with little concern for others'' welfare', '[{"en":"It''s a dog-eat-dog market out there.","zh-TW":"外面是個弱肉強食的市場。"},{"en":"In a dog-eat-dog industry differentiation is crucial.","zh-TW":"在激烈競爭的行業中差異化至關重要。"}]', 'expression'),
('don''t burn bridges', '不要毀掉人脈；不要斷了退路', 'avoid damaging relationships that may be useful in the future', '[{"en":"Don''t burn bridges when you leave a company.","zh-TW":"離開公司時不要毀掉人脈。"},{"en":"Even in tough negotiations don''t burn bridges.","zh-TW":"即使在艱難談判中也不要斷了退路。"}]', 'expression'),
('elephant in the room', '眾所周知卻被刻意迴避的問題', 'an obvious problem that no one wants to discuss', '[{"en":"Let''s address the elephant in the room — we missed our targets.","zh-TW":"讓我們面對眾所周知的問題——我們沒有達到目標。"},{"en":"The budget shortfall was the elephant in the room.","zh-TW":"預算短缺是眾人迴避的問題。"}]', 'expression'),
('give the green light', '批准；開綠燈', 'to give approval to proceed with something', '[{"en":"Management gave the green light to the expansion.","zh-TW":"管理層批准了擴張計劃。"},{"en":"The committee gave the green light for the new policy.","zh-TW":"委員會批准了新政策。"}]', 'expression'),
('in the driver''s seat', '掌控局面；主導地位', 'in a position of control or authority', '[{"en":"Our brand is in the driver''s seat in the premium segment.","zh-TW":"我們的品牌在高端市場佔據主導地位。"},{"en":"With more data we put customers in the driver''s seat.","zh-TW":"有了更多數據，我們讓客戶掌控局面。"}]', 'expression'),
('keep one''s eye on the ball', '專注目標；保持專注', 'to remain focused on the main objective', '[{"en":"Keep your eye on the ball and don''t get distracted by secondary issues.","zh-TW":"保持專注，不要被次要問題分心。"},{"en":"Good managers keep their eye on the ball even under pressure.","zh-TW":"優秀的經理即使在壓力下也能保持目標專注。"}]', 'expression'),
('lay one''s cards on the table', '攤牌；坦誠相告', 'to be open and honest about one''s intentions or information', '[{"en":"In the final negotiation we laid our cards on the table.","zh-TW":"在最後談判中我們攤牌了。"},{"en":"Lay your cards on the table to build trust.","zh-TW":"坦誠相告以建立信任。"}]', 'expression'),
('outside the box', '突破常規；有創意地', 'thinking in a creative or unconventional way', '[{"en":"We need to think outside the box to solve this issue.","zh-TW":"我們需要突破常規來解決這個問題。"},{"en":"Thinking outside the box led to a breakthrough product.","zh-TW":"突破常規思維帶來了突破性產品。"}]', 'expression'),
('put one''s best foot forward', '全力以赴；展現最佳狀態', 'to make the best possible impression or effort', '[{"en":"Put your best foot forward in the client pitch.","zh-TW":"在客戶推介中全力以赴展現最佳狀態。"},{"en":"We put our best foot forward during the investor meeting.","zh-TW":"我們在投資者會議中展現了最佳狀態。"}]', 'expression'),
('seal the deal', '完成交易；成交', 'to finalize an agreement or close a sale', '[{"en":"The free pilot project helped seal the deal.","zh-TW":"免費試點項目幫助促成了交易。"},{"en":"A personal visit from the CEO sealed the deal.","zh-TW":"執行長的親自拜訪完成了這筆交易。"}]', 'expression'),
('take it to the next level', '更上一層樓；提升到更高境界', 'to improve or advance something to a higher standard', '[{"en":"We plan to take our customer experience to the next level.","zh-TW":"我們計劃將客戶體驗更上一層樓。"},{"en":"The new investment will take the platform to the next level.","zh-TW":"新投資將使平台提升到更高境界。"}]', 'expression'),
('the devil is in the details', '細節決定成敗；魔鬼藏在細節裡', 'small, often overlooked details can cause serious problems', '[{"en":"The devil is in the details of the contract terms.","zh-TW":"合約條款的細節決定成敗。"},{"en":"Review every clause — the devil is in the details.","zh-TW":"審查每個條款——魔鬼藏在細節裡。"}]', 'expression'),
('think on one''s feet', '即興應對；臨機應變', 'to make quick decisions without time to prepare', '[{"en":"Good salespeople can think on their feet during tough questions.","zh-TW":"優秀的銷售人員在面對棘手問題時能夠臨機應變。"},{"en":"She thinks on her feet brilliantly under pressure.","zh-TW":"她在壓力下即興應對的能力非常出色。"}]', 'expression'),
('turn the tables', '扭轉局勢；反敗為勝', 'to reverse a situation in your favor', '[{"en":"The competitor turned the tables with a surprise price cut.","zh-TW":"競爭對手以突然降價扭轉了局勢。"},{"en":"Innovation allowed us to turn the tables on industry rivals.","zh-TW":"創新使我們能夠反敗為勝對抗行業競爭者。"}]', 'expression'),
('on par with', '與…相當；旗鼓相當', 'equal to or at the same level as', '[{"en":"Our service quality is on par with industry leaders.","zh-TW":"我們的服務品質與行業領先者相當。"},{"en":"Salaries must be on par with market rates.","zh-TW":"薪資必須與市場水準相當。"}]', 'prepositional phrase'),
('on the brink of', '瀕臨；即將到達', 'very close to a significant event, often negative', '[{"en":"The company was on the brink of bankruptcy when rescued.","zh-TW":"公司在被救助時瀕臨破產。"},{"en":"We are on the brink of a major technology breakthrough.","zh-TW":"我們即將達到一個重大技術突破。"}]', 'prepositional phrase'),
('out of proportion', '不成比例；誇大其詞', 'not matching the scale or importance of something', '[{"en":"The media coverage was out of proportion to the actual issue.","zh-TW":"媒體報導相對於實際問題不成比例。"},{"en":"Don''t let a small setback grow out of proportion.","zh-TW":"不要讓小挫折被誇大其詞。"}]', 'prepositional phrase'),
('without prejudice', '在不損害權益的情況下；保留法律權益', 'without affecting one''s legal rights; used in negotiations to protect positions', '[{"en":"The settlement was discussed without prejudice.","zh-TW":"和解在保留法律權益的情況下進行了討論。"},{"en":"Mark offers as without prejudice in sensitive negotiations.","zh-TW":"在敏感談判中將提議標注為保留法律權益。"}]', 'prepositional phrase'),
('work in tandem', '協同合作；齊頭並進', 'to work together closely or simultaneously', '[{"en":"Sales and marketing work in tandem to close deals.","zh-TW":"銷售和行銷協同合作以達成交易。"},{"en":"The two systems work in tandem to process orders.","zh-TW":"這兩個系統齊頭並進地處理訂單。"}]', 'prepositional phrase'),
('leverage existing assets', '善用現有資產；充分利用現有資源', 'to use current resources or capabilities to gain advantage', '[{"en":"We leveraged existing assets to enter new markets quickly.","zh-TW":"我們善用現有資產快速進入新市場。"},{"en":"Leverage existing assets before investing in new ones.","zh-TW":"在投資新資產之前充分利用現有資產。"}]', 'business idiom'),
('market intelligence', '市場情報；市場資訊', 'information gathered about competitors, customers, and the market environment', '[{"en":"We invest in market intelligence to stay competitive.","zh-TW":"我們投資於市場情報以保持競爭力。"},{"en":"Market intelligence guided our pricing strategy.","zh-TW":"市場情報指導了我們的定價策略。"}]', 'business idiom'),
('net out', '淨餘；扣除後剩餘', 'to calculate the final amount after deductions', '[{"en":"Net out the fees before reporting profits.","zh-TW":"在報告利潤前扣除費用後的淨餘。"},{"en":"The gain netted out to about two million after taxes.","zh-TW":"扣除稅款後收益淨餘約兩百萬。"}]', 'phrasal verb'),
('opt in', '選擇加入；積極參與', 'to choose to participate in something', '[{"en":"Customers must opt in to receive marketing emails.","zh-TW":"客戶必須選擇加入才能接收行銷電子郵件。"},{"en":"Employees can opt in to the flexible work scheme.","zh-TW":"員工可以選擇加入彈性工作計劃。"}]', 'phrasal verb'),
('opt out', '選擇退出；放棄參與', 'to choose not to participate in something', '[{"en":"Users can opt out of data sharing at any time.","zh-TW":"用戶可以隨時選擇退出數據共享。"},{"en":"Several countries opted out of the trade deal.","zh-TW":"幾個國家選擇退出了這項貿易協議。"}]', 'phrasal verb'),
('pipe up', '開口說話；提出意見', 'to speak up and offer an opinion or suggestion', '[{"en":"Don''t hesitate to pipe up if you have a better idea.","zh-TW":"如果你有更好的想法不要猶豫，開口說出來。"},{"en":"He piped up with a valid concern during the briefing.","zh-TW":"他在簡報中提出了一個合理的問題。"}]', 'phrasal verb'),
('pitch in', '幫忙；出力；分擔', 'to contribute effort or resources to help', '[{"en":"Everyone pitched in to meet the urgent deadline.","zh-TW":"大家都幫忙以達到緊急截止日期。"},{"en":"Pitch in and help the team when it''s busy.","zh-TW":"在繁忙時出力幫助團隊。"}]', 'phrasal verb'),
('play out', '發展；展開；結果如何', 'to happen or develop in a particular way', '[{"en":"Let''s wait and see how the strategy plays out.","zh-TW":"讓我們等著看這個策略如何發展。"},{"en":"The worst-case scenario did not play out.","zh-TW":"最壞的情況沒有發展出來。"}]', 'phrasal verb'),
('plug away', '努力不懈；堅持做', 'to continue working hard at something despite difficulty', '[{"en":"The team plugged away at the issue for weeks.","zh-TW":"團隊在這個問題上努力不懈了好幾週。"},{"en":"Keep plugging away and the results will come.","zh-TW":"堅持努力，結果終將到來。"}]', 'phrasal verb'),
('reach out', '聯繫；主動接觸', 'to contact someone, especially to offer help or start a conversation', '[{"en":"Reach out to the client within 24 hours of the meeting.","zh-TW":"在會議後24小時內與客戶聯繫。"},{"en":"We reached out to potential investors at the conference.","zh-TW":"我們在會議上主動接觸了潛在投資者。"}]', 'phrasal verb'),
('ramp down', '逐步減少；縮減', 'to gradually reduce production, activity, or effort', '[{"en":"We ramped down production ahead of the retooling period.","zh-TW":"我們在改裝期前逐步減少了產量。"},{"en":"Ramp down project activities during the holiday season.","zh-TW":"在假日期間縮減專案活動。"}]', 'phrasal verb'),
('revolve around', '圍繞；以…為中心', 'to have something as the main focus or concern', '[{"en":"Our strategy revolves around customer satisfaction.","zh-TW":"我們的策略以客戶滿意度為中心。"},{"en":"The discussion revolved around budget allocation.","zh-TW":"討論圍繞預算分配展開。"}]', 'phrasal verb'),
('scale back', '縮減規模；削減', 'to reduce the size or scope of something', '[{"en":"We scaled back the project scope due to budget cuts.","zh-TW":"由於預算削減，我們縮減了專案範圍。"},{"en":"Scaling back expansion plans shows fiscal discipline.","zh-TW":"縮減擴張計劃顯示了財務紀律。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('scope out', '考察；評估；摸清情況', 'to investigate or assess the details of a situation or location', '[{"en":"She scoped out the competition before entering the market.","zh-TW":"她在進入市場之前考察了競爭情況。"},{"en":"Scope out the new location before committing to a lease.","zh-TW":"在簽訂租約前評估新地點。"}]', 'phrasal verb'),
('smooth out', '平息；消除；使順暢', 'to remove problems or difficulties; to make a process easier', '[{"en":"Let''s smooth out the onboarding process before launch.","zh-TW":"讓我們在發布前使入職流程更順暢。"},{"en":"She smoothed out the tensions between the two teams.","zh-TW":"她平息了兩個團隊之間的緊張局勢。"}]', 'phrasal verb'),
('move fast and break things', '快速行動，勇於嘗試', 'to prioritize speed of innovation over caution', '[{"en":"The startup culture was move fast and break things.","zh-TW":"這家新創公司的文化是快速行動，勇於嘗試。"},{"en":"Move fast and break things works until compliance matters.","zh-TW":"快速行動勇於嘗試在合規不重要前是可行的。"}]', 'business idiom'),
('nail it and scale it', '先做好再擴大規模', 'to perfect a process or product before scaling widely', '[{"en":"The team focused on nail it and scale it for the first product.","zh-TW":"團隊專注於先把第一個產品做好再擴大規模。"},{"en":"Nail it and scale it prevents costly expansion mistakes.","zh-TW":"先做好再擴大規模可以防止代價高昂的擴張錯誤。"}]', 'business idiom'),
('needle mover', '帶來重大影響的事項；關鍵推動因素', 'an action or initiative that significantly impacts key metrics', '[{"en":"The partnership was a real needle mover for brand awareness.","zh-TW":"這次合作是品牌知名度的關鍵推動因素。"},{"en":"Focus resources on needle movers not vanity projects.","zh-TW":"將資源集中在帶來重大影響的事項上而不是形象工程。"}]', 'business idiom'),
('on the back burner', '暫時擱置；列為低優先', 'postponed or given low priority for now', '[{"en":"The expansion plan is on the back burner for now.","zh-TW":"擴張計劃目前暫時擱置。"},{"en":"Don''t put customer satisfaction on the back burner.","zh-TW":"不要將客戶滿意度列為低優先。"}]', 'business idiom'),
('one-stop shop', '一站式服務；全方位服務提供者', 'a provider that offers everything needed in one place', '[{"en":"We position ourselves as a one-stop shop for SME accounting.","zh-TW":"我們定位為中小企業會計的一站式服務提供者。"},{"en":"A one-stop shop approach increases client retention.","zh-TW":"一站式服務方法提高了客戶留存率。"}]', 'business idiom'),
('open the kimono', '公開資訊；透明化', 'to share confidential information or be fully transparent', '[{"en":"We opened the kimono to investors during due diligence.","zh-TW":"在盡職調查期間我們向投資者公開了資訊。"},{"en":"Opening the kimono can build trust with key partners.","zh-TW":"透明化可以與主要合作夥伴建立信任。"}]', 'business idiom'),
('over-index', '過度集中於；偏重某方面', 'to allocate disproportionately more attention or resources to something', '[{"en":"We tend to over-index on enterprise clients.","zh-TW":"我們傾向於過度集中於企業客戶。"},{"en":"Avoid over-indexing on short-term metrics.","zh-TW":"避免偏重短期指標。"}]', 'business idiom'),
('paralysis by analysis', '分析癱瘓；過度分析導致無法決策', 'being unable to make a decision because of excessive analysis', '[{"en":"Paralysis by analysis prevented us from launching on time.","zh-TW":"分析癱瘓使我們無法按時推出產品。"},{"en":"Set a deadline to avoid paralysis by analysis.","zh-TW":"設定截止日期以避免過度分析導致無法決策。"}]', 'business idiom'),
('peel back the layers', '層層剖析；深入了解', 'to analyze something progressively to understand its true nature', '[{"en":"We need to peel back the layers of this issue.","zh-TW":"我們需要層層剖析這個問題。"},{"en":"Peel back the layers before proposing a solution.","zh-TW":"在提出解決方案前深入了解情況。"}]', 'business idiom'),
('people-first culture', '以人為本的文化', 'an organizational philosophy that prioritizes employee well-being', '[{"en":"A people-first culture drives long-term retention.","zh-TW":"以人為本的文化推動長期員工留任。"},{"en":"The company is known for its people-first culture.","zh-TW":"這家公司以其以人為本的文化而聞名。"}]', 'business idiom'),
('pick your battles', '選擇性地應對；只爭最重要的', 'to choose carefully which issues to confront and which to let go', '[{"en":"In corporate politics you need to pick your battles.","zh-TW":"在企業政治中你需要選擇性地應對。"},{"en":"Pick your battles so you have energy for what truly matters.","zh-TW":"選擇你要爭的事，留精力給真正重要的事。"}]', 'business idiom'),
('pivot or persevere', '轉向還是堅持；策略抉擇', 'the decision whether to change strategy or continue as planned', '[{"en":"After the failed launch we faced a pivot or persevere decision.","zh-TW":"發布失敗後我們面臨轉向還是堅持的策略抉擇。"},{"en":"Pivot or persevere is a question every startup must answer.","zh-TW":"轉向還是堅持是每家新創公司必須回答的問題。"}]', 'business idiom'),
('plug a gap', '填補空缺；彌補不足', 'to fill a need or deficiency in a market, team, or process', '[{"en":"The new product plugs a significant gap in the market.","zh-TW":"新產品填補了市場上的重大空缺。"},{"en":"Hire a specialist to plug the skill gap.","zh-TW":"聘請專家來彌補技能不足。"}]', 'business idiom'),
('power player', '有影響力的人；重要玩家', 'a person or organization with significant influence or authority', '[{"en":"She became a power player in the fintech space within three years.","zh-TW":"她在三年內成為了金融科技領域的重要玩家。"},{"en":"Partnering with a power player accelerates growth.","zh-TW":"與有影響力的人合作加速了增長。"}]', 'business idiom'),
('proof of concept', '概念驗證', 'a demonstration that an idea or plan is feasible', '[{"en":"We ran a proof of concept before full development.","zh-TW":"在全面開發之前我們進行了概念驗證。"},{"en":"A proof of concept reduces investment risk.","zh-TW":"概念驗證降低了投資風險。"}]', 'business idiom'),
('pull the plug', '叫停；中止；終止', 'to stop a project, program, or initiative entirely', '[{"en":"The board pulled the plug on the unprofitable division.","zh-TW":"董事會叫停了不盈利的部門。"},{"en":"Know when to pull the plug before sinking more resources.","zh-TW":"在投入更多資源之前知道何時該中止。"}]', 'business idiom'),
('put a stake in the ground', '確立立場；明確目標', 'to make a definitive claim or decision about a position or goal', '[{"en":"We need to put a stake in the ground on pricing strategy.","zh-TW":"我們需要確立定價策略的立場。"},{"en":"Put a stake in the ground so the team has a clear goal.","zh-TW":"確立明確目標讓團隊有方向感。"}]', 'business idiom'),
('quick win', '快速見效的成果；短期勝利', 'a small, achievable goal that shows early progress', '[{"en":"Focus on quick wins to build team momentum early.","zh-TW":"專注於快速見效的成果以及早建立團隊動力。"},{"en":"Quick wins help secure stakeholder support.","zh-TW":"短期勝利有助於獲得利益相關者的支持。"}]', 'business idiom'),
('red ocean strategy', '紅海策略；激烈競爭市場', 'competing in an existing highly competitive market', '[{"en":"A red ocean strategy requires exceptional efficiency.","zh-TW":"紅海策略需要卓越的效率。"},{"en":"Consider a blue ocean approach rather than red ocean strategy.","zh-TW":"考慮藍海方法而不是紅海策略。"}]', 'business idiom'),
('revenue driver', '收入驅動因素', 'a product, channel, or activity that generates significant revenue', '[{"en":"The enterprise segment is our primary revenue driver.","zh-TW":"企業客戶群是我們主要的收入驅動因素。"},{"en":"Focus on the top revenue drivers for maximum impact.","zh-TW":"專注於最重要的收入驅動因素以獲得最大影響。"}]', 'business idiom'),
('right-size', '適當調整規模；優化規模', 'to adjust the size of a workforce or budget to fit current needs', '[{"en":"The company right-sized its workforce after the merger.","zh-TW":"合併後公司適當調整了員工規模。"},{"en":"Right-sizing the budget ensures sustainable operations.","zh-TW":"優化預算規模確保了可持續運營。"}]', 'business idiom'),
('roadblock', '障礙；阻礙', 'an obstacle preventing progress toward a goal', '[{"en":"Identify and remove roadblocks early in the project.","zh-TW":"在專案早期識別並移除障礙。"},{"en":"Bureaucracy is a major roadblock to innovation.","zh-TW":"官僚主義是創新的主要阻礙。"}]', 'business idiom'),
('scalable solution', '可擴展的解決方案', 'a solution that can grow efficiently as demand increases', '[{"en":"We designed a scalable solution that grows with customer needs.","zh-TW":"我們設計了一個隨客戶需求成長的可擴展解決方案。"},{"en":"A scalable solution reduces per-unit costs as volume grows.","zh-TW":"可擴展的解決方案在數量增長時降低單位成本。"}]', 'business idiom'),
('silo mentality', '孤島心態；各自為政', 'when departments or teams avoid sharing information with others', '[{"en":"Silo mentality hinders cross-functional collaboration.","zh-TW":"孤島心態阻礙了跨職能協作。"},{"en":"Break down silo mentality to improve efficiency.","zh-TW":"打破各自為政以提高效率。"}]', 'business idiom'),
('skin in the game', '切身利益；真正的投入', 'having a personal stake or investment in the outcome', '[{"en":"Founders should have skin in the game to stay motivated.","zh-TW":"創始人應有切身利益才能保持動力。"},{"en":"Partners with skin in the game work harder for results.","zh-TW":"有真正投入的合作夥伴更努力爭取成果。"}]', 'business idiom'),
('soft launch', '軟發布；低調推出', 'a limited or quiet product launch without full marketing support', '[{"en":"We did a soft launch to test the market reaction.","zh-TW":"我們進行了軟發布以測試市場反應。"},{"en":"A soft launch allows for quick iteration before full rollout.","zh-TW":"軟發布允許在全面推出前快速迭代。"}]', 'business idiom'),
('stakeholder alignment', '利益相關者一致性；達成各方共識', 'ensuring all involved parties have a shared understanding and goal', '[{"en":"Stakeholder alignment is critical before starting major initiatives.","zh-TW":"在開始重大計劃之前達成利益相關者一致性至關重要。"},{"en":"Lack of stakeholder alignment caused project delays.","zh-TW":"缺乏利益相關者一致性導致了專案延誤。"}]', 'business idiom'),
('stretch goal', '延伸性目標；挑戰性目標', 'an ambitious target that is beyond normal expectations', '[{"en":"Our stretch goal is to double revenue in one year.","zh-TW":"我們的挑戰性目標是在一年內使收入翻倍。"},{"en":"Stretch goals inspire innovation but must be realistic.","zh-TW":"挑戰性目標激發創新但必須現實。"}]', 'business idiom'),
('sweet spot', '最佳平衡點；黃金地帶', 'the ideal intersection of two factors for optimal results', '[{"en":"Find the sweet spot between cost and quality.","zh-TW":"找到成本與品質之間的最佳平衡點。"},{"en":"The new product sits in the sweet spot for the market.","zh-TW":"新產品處於市場的黃金地帶。"}]', 'business idiom'),
('synergy realization', '協同效益實現', 'achieving the expected benefits from combining organizations or teams', '[{"en":"Synergy realization was slower than expected post-merger.","zh-TW":"合併後協同效益實現比預期慢。"},{"en":"Set clear milestones for synergy realization.","zh-TW":"為協同效益實現設定明確里程碑。"}]', 'business idiom'),
('time to market', '上市時間；從開發到推出的時間', 'the time from product development to commercial availability', '[{"en":"Agile methods reduce time to market significantly.","zh-TW":"敏捷方法顯著縮短了上市時間。"},{"en":"Time to market is a key competitive advantage.","zh-TW":"上市時間是關鍵的競爭優勢。"}]', 'business idiom'),
('tipping point', '引爆點；臨界點', 'the moment when a trend or change becomes unstoppable', '[{"en":"Digital payments reached a tipping point during the pandemic.","zh-TW":"數位支付在疫情期間達到了引爆點。"},{"en":"We are at the tipping point of mainstream AI adoption.","zh-TW":"我們正處於人工智慧主流採用的臨界點。"}]', 'business idiom'),
('top of mind', '首要考量；念念不忘', 'being the first thing thought of when considering a category', '[{"en":"Keep your brand top of mind with regular touchpoints.","zh-TW":"通過定期接觸點讓你的品牌保持在首要考量中。"},{"en":"Customer retention should be top of mind for leadership.","zh-TW":"客戶留存率應該是領導層念念不忘的事。"}]', 'business idiom'),
('stumble upon', '偶然發現；碰巧遇到', 'to find or encounter something unexpectedly', '[{"en":"We stumbled upon a potential acquisition target at the conference.","zh-TW":"我們在會議上偶然發現了一個潛在的收購目標。"},{"en":"She stumbled upon a creative solution while reviewing old data.","zh-TW":"她在查看舊數據時碰巧遇到了一個創意解決方案。"}]', 'phrasal verb'),
('take away', '帶走；扣除；學到', 'to remove or learn something from a situation', '[{"en":"What do you take away from this project experience?","zh-TW":"你從這個專案經驗中學到了什麼？"},{"en":"Take away the high performer''s support and morale drops.","zh-TW":"如果帶走了高績效員工的支持，士氣就會下降。"}]', 'phrasal verb'),
('unlock value', '釋放價值；創造潛在價值', 'to reveal or realize potential value in an asset or situation', '[{"en":"The merger unlocked significant value for shareholders.","zh-TW":"合併為股東釋放了顯著的價值。"},{"en":"Our goal is to unlock value in underperforming assets.","zh-TW":"我們的目標是在表現不佳的資產中創造潛在價值。"}]', 'phrasal verb'),
('zoom in', '深入聚焦；放大關注細節', 'to focus closely on a specific detail or aspect', '[{"en":"Let''s zoom in on the Q3 performance numbers.","zh-TW":"讓我們深入聚焦第三季績效數字。"},{"en":"Zoom in on the biggest cost driver before analyzing others.","zh-TW":"在分析其他因素之前放大關注最大的成本驅動因素。"}]', 'phrasal verb'),
('zoom out', '拉遠視角；從大局看', 'to take a broader perspective; to consider the bigger picture', '[{"en":"Sometimes you need to zoom out and see the bigger picture.","zh-TW":"有時你需要拉遠視角從大局看。"},{"en":"Zoom out to understand how the market is shifting.","zh-TW":"從大局出發了解市場如何在轉變。"}]', 'phrasal verb'),
('bank on it', '對此有把握；確信會發生', 'to be absolutely certain that something will happen', '[{"en":"If we deliver quality you can bank on repeat business.","zh-TW":"如果我們提供品質你可以對回購業務有把握。"},{"en":"She said she''d close the deal — you can bank on it.","zh-TW":"她說她會完成交易——你可以確信這一點。"}]', 'phrasal verb'),
('carve out', '開拓；劃出；創造（一席之地）', 'to create or establish a distinct area or share of something', '[{"en":"We carved out a niche in premium pet care products.","zh-TW":"我們在高端寵物護理產品中開拓了一個利基市場。"},{"en":"Carve out dedicated time for innovation projects.","zh-TW":"劃出專門的時間用於創新專案。"}]', 'phrasal verb'),
('cobble together', '拼湊；臨時組合', 'to put something together quickly from available materials', '[{"en":"We cobbled together a proposal overnight for the client.","zh-TW":"我們通宵為客戶拼湊了一份提案。"},{"en":"The team cobbled together a workaround before the fix.","zh-TW":"團隊在修復方案出來之前拼湊了一個臨時解決方法。"}]', 'phrasal verb'),
('collaborate on', '在…上合作；共同研發', 'to work together with others on a shared project or goal', '[{"en":"The two firms collaborated on a joint product launch.","zh-TW":"兩家公司在聯合產品發布上合作。"},{"en":"Collaborate on the proposal to strengthen your bid.","zh-TW":"共同合作提案以加強你的投標。"}]', 'phrasal verb'),
('communicate across', '跨越…進行溝通；向…傳達', 'to convey information effectively across different levels or groups', '[{"en":"Leaders must communicate across all levels of the organization.","zh-TW":"領導者必須跨越組織各層級進行溝通。"},{"en":"The policy change was communicated across all departments.","zh-TW":"政策變更向所有部門傳達了。"}]', 'phrasal verb'),
('compete for', '競爭；爭奪', 'to try to win or obtain something against others', '[{"en":"Three firms are competing for the government contract.","zh-TW":"三家公司在競爭政府合約。"},{"en":"We compete for top talent with tech giants.","zh-TW":"我們與科技巨頭爭奪頂尖人才。"}]', 'phrasal verb'),
('concentrate on', '專注於；集中精力於', 'to direct effort and attention to a specific task or goal', '[{"en":"This quarter we concentrate on improving retention.","zh-TW":"這個季度我們專注於提高留存率。"},{"en":"Concentrate on the highest-value activities first.","zh-TW":"首先集中精力於最高價值的活動。"}]', 'phrasal verb'),
('confirm in writing', '書面確認', 'to officially verify an agreement or decision via written document', '[{"en":"Always confirm in writing after a verbal agreement.","zh-TW":"口頭協議後務必書面確認。"},{"en":"Please confirm in writing your acceptance of the terms.","zh-TW":"請書面確認你接受條款。"}]', 'phrasal verb'),
('consolidate around', '圍繞…整合；集中於', 'to combine and organize resources or activities around a central focus', '[{"en":"The industry is consolidating around three major players.","zh-TW":"行業正在圍繞三大主要參與者整合。"},{"en":"Consolidate around your strongest product lines first.","zh-TW":"首先集中於你最強的產品線。"}]', 'phrasal verb'),
('contract out', '外包；委外', 'to hire an outside company to perform services', '[{"en":"We contracted out logistics to a third-party provider.","zh-TW":"我們將物流外包給了第三方供應商。"},{"en":"Contracting out IT support reduced our overhead.","zh-TW":"將IT支援委外降低了我們的間接費用。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('converge on', '集中；聚焦；達成共識', 'to come together or agree on a common point or solution', '[{"en":"The team converged on a single pricing model after debate.","zh-TW":"經過辯論後團隊就單一定價模型達成了共識。"},{"en":"Multiple trends are converging on the same market opportunity.","zh-TW":"多個趨勢正在集中於同一市場機會。"}]', 'phrasal verb'),
('cost out', '估算成本；計算費用', 'to calculate the cost of a project or action in detail', '[{"en":"We need to cost out the expansion before the board meeting.","zh-TW":"在董事會會議之前我們需要估算擴張的成本。"},{"en":"Cost out each option so we can compare them fairly.","zh-TW":"估算每個選項的成本以便公平比較。"}]', 'phrasal verb'),
('course correct', '糾正方向；調整路線', 'to adjust strategy or actions based on feedback or results', '[{"en":"The team course corrected after the mid-year review.","zh-TW":"團隊在年中審查後糾正了方向。"},{"en":"Agile teams are designed to course correct quickly.","zh-TW":"敏捷團隊的設計就是為了快速調整路線。"}]', 'phrasal verb'),
('crowd out', '排擠；佔據…的空間', 'to push out or displace something by taking up space or priority', '[{"en":"Large platforms crowd out smaller competitors.","zh-TW":"大型平台排擠了小型競爭者。"},{"en":"Urgent tasks can crowd out strategic work.","zh-TW":"緊急任務可能會排擠戰略性工作。"}]', 'phrasal verb'),
('a race to the bottom', '惡性競爭；爭相降低標準', 'a competition to offer the lowest price or lowest standards', '[{"en":"Competing purely on price leads to a race to the bottom.","zh-TW":"純粹在價格上競爭導致惡性競爭。"},{"en":"We refuse to enter a race to the bottom with low-cost rivals.","zh-TW":"我們拒絕與低成本競爭對手展開惡性競爭。"}]', 'expression'),
('against the clock', '與時間賽跑；爭分奪秒', 'working urgently because there is very little time left', '[{"en":"The team was working against the clock to meet the launch date.","zh-TW":"團隊正在與時間賽跑以趕上發布日期。"},{"en":"Against the clock we still delivered a quality product.","zh-TW":"儘管爭分奪秒我們仍然交付了高品質的產品。"}]', 'prepositional phrase'),
('bang for your buck', '物超所值；高性價比', 'getting maximum value for the money spent', '[{"en":"Digital ads give us the best bang for our buck.","zh-TW":"數位廣告讓我們物超所值。"},{"en":"Choose suppliers who offer bang for your buck.","zh-TW":"選擇提供高性價比的供應商。"}]', 'expression'),
('between a rock and a hard place', '進退兩難；兩難困境', 'facing two equally difficult or unpleasant options', '[{"en":"We are between a rock and a hard place with this vendor.","zh-TW":"我們與這個供應商陷入了進退兩難的困境。"},{"en":"Between a rock and a hard place we chose the lesser risk.","zh-TW":"在進退兩難中我們選擇了風險較小的一方。"}]', 'expression'),
('blow the budget', '超出預算；大幅超支', 'to spend significantly more than the allocated budget', '[{"en":"The renovation blew the budget by 30%.","zh-TW":"翻修超出預算30%。"},{"en":"Avoid blowing the budget in the first half of the year.","zh-TW":"避免在上半年就大幅超支。"}]', 'expression'),
('break the ice', '打破僵局；活絡氣氛', 'to do or say something to relieve tension and start a conversation', '[{"en":"A quick team activity can break the ice at the start of a workshop.","zh-TW":"在工作坊開始時進行快速的團隊活動可以活絡氣氛。"},{"en":"She broke the ice with a relevant story.","zh-TW":"她用一個相關的故事打破了僵局。"}]', 'expression'),
('bring to the fore', '使突出；凸顯', 'to cause something to become prominent or important', '[{"en":"The crisis brought the team''s resilience to the fore.","zh-TW":"危機凸顯了團隊的韌性。"},{"en":"New data brought the efficiency gap to the fore.","zh-TW":"新數據使效率差距突出了。"}]', 'expression'),
('by a wide margin', '以相當大的差距；遙遙領先', 'by a large or significant amount', '[{"en":"Our product outperformed competitors by a wide margin.","zh-TW":"我們的產品以相當大的差距超越了競爭對手。"},{"en":"She won the client vote by a wide margin.","zh-TW":"她以遙遙領先的差距贏得了客戶投票。"}]', 'prepositional phrase'),
('by any measure', '無論以哪種標準衡量；毫無疑問', 'considered in any way; unquestionably', '[{"en":"By any measure the campaign was a success.","zh-TW":"無論以哪種標準衡量，這個活動都是成功的。"},{"en":"The cost savings are significant by any measure.","zh-TW":"無論怎麼看，成本節省都是顯著的。"}]', 'prepositional phrase'),
('by design', '有意為之；故意設計的', 'intentionally planned or intended', '[{"en":"The product is simple by design to reduce errors.","zh-TW":"產品有意為之地設計簡單以減少錯誤。"},{"en":"Our flat structure is by design to speed up decisions.","zh-TW":"我們的扁平化結構是故意設計的以加快決策。"}]', 'prepositional phrase'),
('case in point', '典型例子；恰當的例子', 'a clear example that illustrates the point being made', '[{"en":"The recent data breach is a case in point for stronger security.","zh-TW":"最近的數據洩露事件是加強安全性的典型例子。"},{"en":"Her rapid promotion is a case in point for performance-based culture.","zh-TW":"她的快速晉升是績效文化的恰當例子。"}]', 'expression'),
('common ground', '共同點；共識', 'shared beliefs or interests that can serve as a basis for agreement', '[{"en":"Find common ground before entering tough negotiations.","zh-TW":"在進入艱難談判前找到共同點。"},{"en":"There is common ground between the two proposals.","zh-TW":"兩個提案之間有共識。"}]', 'expression'),
('devil''s advocate', '故意反駁者；提出反對意見以測試論點', 'someone who argues a position they may not personally hold to test an argument', '[{"en":"Let me play devil''s advocate and challenge the assumptions.","zh-TW":"讓我扮演反對者的角色來挑戰這些假設。"},{"en":"We need someone to play devil''s advocate before the pitch.","zh-TW":"在推介前我們需要有人提出反對意見。"}]', 'expression'),
('fat chance', '幾乎不可能；機會渺茫', 'very unlikely to happen', '[{"en":"There''s a fat chance of closing that deal this quarter.","zh-TW":"這個季度完成那筆交易的機會渺茫。"},{"en":"Fat chance they''ll reduce prices in a seller''s market.","zh-TW":"在賣方市場他們幾乎不可能降低價格。"}]', 'expression'),
('firing on all cylinders', '全力以赴；全力運轉', 'operating at maximum capacity and efficiency', '[{"en":"The sales team is finally firing on all cylinders.","zh-TW":"銷售團隊終於全力以赴了。"},{"en":"When we''re firing on all cylinders results multiply.","zh-TW":"當我們全力運轉時結果就會倍增。"}]', 'expression'),
('for the long haul', '為了長遠；長久地', 'prepared for a long-term commitment or effort', '[{"en":"We are investing for the long haul in this market.","zh-TW":"我們在這個市場為了長遠進行投資。"},{"en":"Our partnerships are built for the long haul.","zh-TW":"我們的合作關係是為了長久而建立的。"}]', 'prepositional phrase'),
('from top to bottom', '從上到下；全面地', 'completely; involving all levels or aspects', '[{"en":"The organization was audited from top to bottom.","zh-TW":"組織從上到下進行了全面審計。"},{"en":"We redesigned the process from top to bottom.","zh-TW":"我們全面重新設計了這個流程。"}]', 'prepositional phrase'),
('give it your best shot', '盡力而為；全力嘗試', 'to make the greatest effort possible', '[{"en":"Give it your best shot even if success isn''t guaranteed.","zh-TW":"即使成功沒有保障也要盡力而為。"},{"en":"We gave it our best shot in the final bid round.","zh-TW":"在最後一輪投標中我們全力嘗試了。"}]', 'expression'),
('go back to the drawing board', '重頭開始；重新規劃', 'to abandon the current plan and start planning from the beginning', '[{"en":"After the failed test we went back to the drawing board.","zh-TW":"測試失敗後我們重頭開始了。"},{"en":"Go back to the drawing board if the client rejects the concept.","zh-TW":"如果客戶拒絕了概念就重新規劃。"}]', 'expression'),
('go-to person', '靈魂人物；首選對象', 'the person most relied upon for a particular skill or area', '[{"en":"She is the go-to person for regulatory compliance.","zh-TW":"她是監管合規方面的靠山人物。"},{"en":"Become the go-to person in your field to advance faster.","zh-TW":"成為你領域的首選對象以更快晉升。"}]', 'expression'),
('hang in the balance', '懸而未決；前途未卜', 'in a state of uncertainty where either outcome is possible', '[{"en":"The merger hung in the balance for three weeks.","zh-TW":"合併懸而未決長達三週。"},{"en":"With the vote tomorrow everything hangs in the balance.","zh-TW":"明天投票決定一切前途未卜。"}]', 'expression'),
('have the edge', '具有優勢；佔有上風', 'to have a slight advantage over competitors', '[{"en":"Our technology gives us the edge over rivals.","zh-TW":"我們的技術讓我們具有優勢超越對手。"},{"en":"Having the edge in talent is a sustainable advantage.","zh-TW":"在人才方面佔有上風是可持續的優勢。"}]', 'expression'),
('hold one''s ground', '堅守立場；不退讓', 'to refuse to change position under pressure', '[{"en":"She held her ground on the contract terms.","zh-TW":"她在合約條款上堅守了立場。"},{"en":"Holding your ground during a tough negotiation is essential.","zh-TW":"在艱難談判中不退讓至關重要。"}]', 'expression'),
('in a nutshell it', '簡而言之就是；一言以蔽之', 'to summarize a complex situation in very few words', '[{"en":"In a nutshell it comes down to cost and speed.","zh-TW":"簡而言之就是歸結為成本和速度。"},{"en":"Can you put the strategy in a nutshell for the board?","zh-TW":"你能為董事會一言以蔽之地概括策略嗎？"}]', 'expression'),
('in safe hands', '由可靠的人負責；安全託付', 'being looked after by a trustworthy and capable person', '[{"en":"The client account is in safe hands with our senior team.","zh-TW":"客戶帳戶由我們的資深團隊負責，十分可靠。"},{"en":"With her experience the project is in safe hands.","zh-TW":"憑藉她的經驗這個專案安全託付了。"}]', 'prepositional phrase'),
('in the driver''s seat on', '主導；掌控', 'in full control of the direction of something', '[{"en":"Sales is in the driver''s seat on this client relationship.","zh-TW":"銷售團隊主導著這個客戶關係。"},{"en":"We put the product team in the driver''s seat on strategy.","zh-TW":"我們讓產品團隊掌控策略方向。"}]', 'prepositional phrase'),
('in the final analysis', '歸根究柢；最終分析下來', 'when all factors are considered; ultimately', '[{"en":"In the final analysis growth depends on customer trust.","zh-TW":"歸根究柢增長取決於客戶信任。"},{"en":"In the final analysis results speak louder than promises.","zh-TW":"最終分析下來結果比承諾更有說服力。"}]', 'prepositional phrase'),
('know-how', '專業知識；技術訣竅', 'practical knowledge or expertise in doing something', '[{"en":"Our competitive edge is our deep industry know-how.","zh-TW":"我們的競爭優勢是我們深厚的行業知識。"},{"en":"Transfer know-how from senior staff to new hires.","zh-TW":"將技術訣竅從資深員工傳授給新員工。"}]', 'expression'),
('make headway', '取得進展；向前推進', 'to make steady progress towards a goal', '[{"en":"We are finally making headway on the partnership deal.","zh-TW":"我們終於在合夥交易上取得了進展。"},{"en":"Make headway early to build team confidence.","zh-TW":"儘早取得進展以建立團隊信心。"}]', 'expression'),
('nail it', '做得很好；完美執行', 'to do something perfectly or succeed brilliantly', '[{"en":"She really nailed it in the final pitch.","zh-TW":"她在最後的推介中真的做得非常好。"},{"en":"Nail it consistently and your reputation builds itself.","zh-TW":"持續完美執行你的聲譽自然建立。"}]', 'expression'),
('navigate through', '穿越；應對；在…中前行', 'to steer or work through a complex situation', '[{"en":"The team navigated through regulatory hurdles efficiently.","zh-TW":"團隊高效地應對了監管障礙。"},{"en":"Navigating through market volatility requires clear strategy.","zh-TW":"在市場波動中前行需要清晰的策略。"}]', 'phrasal verb'),
('negotiate down', '議價壓低；談判降低（價格）', 'to reduce a price or condition through negotiation', '[{"en":"We negotiated down the contract price by 15%.","zh-TW":"我們通過談判將合約價格壓低了15%。"},{"en":"Negotiate down the initial offer before signing.","zh-TW":"在簽署前談判壓低初始報價。"}]', 'phrasal verb'),
('number-crunch', '數字運算；詳細計算', 'to perform detailed financial or statistical calculations', '[{"en":"The finance team spent a week number-crunching the proposals.","zh-TW":"財務團隊花了一週時間詳細計算這些提案。"},{"en":"Number-crunch the data before the board presentation.","zh-TW":"在董事會演示前進行詳細的數字運算。"}]', 'phrasal verb'),
('onboard quickly', '快速入職；迅速上手', 'to train and integrate a new employee or client rapidly', '[{"en":"We redesigned the process to onboard clients more quickly.","zh-TW":"我們重新設計了流程以更快速地為客戶辦理入職。"},{"en":"Onboard quickly to reduce the ramp-up period.","zh-TW":"快速入職以縮短適應期。"}]', 'phrasal verb'),
('outsource to', '外包給；委外給', 'to contract work out to an external party', '[{"en":"We outsourced payroll processing to a specialist firm.","zh-TW":"我們將薪資處理外包給了專業公司。"},{"en":"Outsource to partners who have deeper expertise.","zh-TW":"外包給擁有更深專業知識的合作夥伴。"}]', 'phrasal verb'),
('overcommunicate', '過度溝通；頻繁傳達訊息', 'to communicate more frequently or thoroughly than might seem necessary', '[{"en":"During change management it''s better to overcommunicate.","zh-TW":"在變革管理過程中過度溝通總比不夠好。"},{"en":"Overcommunicate expectations so nothing is assumed.","zh-TW":"頻繁傳達期望以避免任何假設。"}]', 'phrasal verb'),
('overhaul completely', '全面改革；徹底改造', 'to completely redesign or reorganize something', '[{"en":"The HR process was completely overhauled last year.","zh-TW":"人力資源流程去年被全面改革了。"},{"en":"We overhauled the pricing model to improve margins.","zh-TW":"我們徹底改造了定價模型以提高利潤率。"}]', 'phrasal verb'),
('package up', '打包；包裝成產品形式', 'to bundle or present something as a complete offering', '[{"en":"Package up the services as a bundled solution for SMEs.","zh-TW":"將服務打包為中小企業的捆綁解決方案。"},{"en":"She packaged up the insights into an executive summary.","zh-TW":"她將洞察打包成了一份高管摘要。"}]', 'phrasal verb'),
('partner with', '與…合作；與…建立夥伴關係', 'to form a partnership with another organization or person', '[{"en":"We partnered with a local distributor to enter the market.","zh-TW":"我們與當地分銷商合作進入市場。"},{"en":"Partner with industry leaders to build credibility.","zh-TW":"與行業領先者建立夥伴關係以建立信譽。"}]', 'phrasal verb'),
('prioritize over', '優先於；把…放在…之前', 'to treat something as more important than something else', '[{"en":"Prioritize customer satisfaction over short-term profit.","zh-TW":"將客戶滿意度置於短期利潤之上。"},{"en":"We prioritized speed over perfection for the MVP.","zh-TW":"對最小可行性產品我們優先考慮速度而非完美。"}]', 'phrasal verb'),
('probe into', '深入調查；探究', 'to investigate or examine something closely', '[{"en":"The audit team probed into the financial discrepancies.","zh-TW":"審計團隊深入調查了財務差異。"},{"en":"Probe into customer complaints to find systemic issues.","zh-TW":"深入調查客戶投訴以找到系統性問題。"}]', 'phrasal verb'),
('prototype quickly', '快速製作原型；快速驗證', 'to rapidly build a basic version to test an idea', '[{"en":"Prototype quickly to test the concept with real users.","zh-TW":"快速製作原型以與真實用戶測試概念。"},{"en":"We prototype quickly and iterate based on feedback.","zh-TW":"我們快速製作原型並根據反饋進行迭代。"}]', 'phrasal verb'),
('pull together', '齊心協力；聯合起來', 'to work as a team toward a common goal', '[{"en":"The whole company pulled together to meet the deadline.","zh-TW":"全公司齊心協力趕上了截止日期。"},{"en":"We need to pull together and support each other.","zh-TW":"我們需要聯合起來相互支持。"}]', 'phrasal verb'),
('push back on', '反駁；抵制；推遲', 'to resist or object to something; to delay', '[{"en":"She pushed back on the unrealistic timeline.","zh-TW":"她反駁了不現實的時間表。"},{"en":"Push back on requests that fall outside scope.","zh-TW":"對超出範圍的請求予以抵制。"}]', 'phrasal verb'),
('quantify the impact', '量化影響；衡量成效', 'to measure the effect of something in numerical terms', '[{"en":"We tried to quantify the impact of the price change.","zh-TW":"我們試圖量化價格變化的影響。"},{"en":"Quantify the impact before presenting to leadership.","zh-TW":"在向領導層彙報前量化影響。"}]', 'phrasal verb'),
('rally around', '齊聚支持；共同支援', 'to come together to support a cause or person', '[{"en":"The team rallied around the new vision quickly.","zh-TW":"團隊很快齊聚支持新願景。"},{"en":"Employees rallied around the CEO during the crisis.","zh-TW":"危機期間員工齊聚支援執行長。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('resonate with', '引起共鳴；打動', 'to appeal to or make a strong impression on someone', '[{"en":"The brand''s message resonated with millennials.","zh-TW":"品牌信息引起了千禧一代的共鳴。"},{"en":"Create content that resonates with your target audience.","zh-TW":"創建能打動目標受眾的內容。"}]', 'phrasal verb'),
('revisit later', '稍後再討論；日後重新審視', 'to return to something at a future point', '[{"en":"Let''s table that and revisit it in the next meeting.","zh-TW":"讓我們先擱置那個問題，下次會議再討論。"},{"en":"Revisit the pricing model after the market test.","zh-TW":"市場測試後再重新審視定價模型。"}]', 'phrasal verb'),
('shift focus', '轉移焦點；改變重點', 'to change the emphasis or direction of attention', '[{"en":"We shifted focus from acquisition to retention.","zh-TW":"我們將焦點從獲客轉移到了留存。"},{"en":"Shift focus to enterprise clients for higher margins.","zh-TW":"將重點轉移到企業客戶以獲得更高利潤率。"}]', 'phrasal verb'),
('shore up', '強化；鞏固；支撐', 'to strengthen or reinforce something that is weak or threatened', '[{"en":"The new investment shores up our balance sheet.","zh-TW":"新投資強化了我們的資產負債表。"},{"en":"We need to shore up client confidence after the incident.","zh-TW":"事件後我們需要鞏固客戶信心。"}]', 'phrasal verb'),
('showcase to', '向…展示；展現給', 'to present something impressively to an audience', '[{"en":"The event showcases our innovation to global buyers.","zh-TW":"這個活動向全球買家展示了我們的創新。"},{"en":"Showcase the prototype to gather investor interest.","zh-TW":"向投資者展示原型以引起興趣。"}]', 'phrasal verb'),
('sign up for', '報名；訂閱；簽約加入', 'to formally register or commit to something', '[{"en":"Over 5000 businesses signed up for the beta.","zh-TW":"超過5000家企業報名參加了測試版。"},{"en":"Sign up for the training before spots fill up.","zh-TW":"在名額填滿之前報名參加培訓。"}]', 'phrasal verb'),
('slice and dice', '多角度分析；細分數據', 'to analyze data from multiple perspectives or categories', '[{"en":"We slice and dice the sales data by region and segment.","zh-TW":"我們按地區和細分市場對銷售數據進行多角度分析。"},{"en":"Slice and dice the results to identify hidden trends.","zh-TW":"細分結果以識別隱藏趨勢。"}]', 'phrasal verb'),
('stay on track', '保持進度；按計劃進行', 'to continue following the planned schedule or approach', '[{"en":"Weekly reviews help the team stay on track.","zh-TW":"每週審查幫助團隊保持進度。"},{"en":"Stay on track despite distractions or scope creep.","zh-TW":"儘管有干擾或範圍蔓延也要按計劃進行。"}]', 'phrasal verb'),
('streamline processes', '簡化流程；優化程序', 'to make processes more efficient by removing unnecessary steps', '[{"en":"We streamlined the approval process from five steps to two.","zh-TW":"我們將審批流程從五個步驟簡化到了兩個步驟。"},{"en":"Streamline processes to free up staff for higher-value tasks.","zh-TW":"簡化流程以釋放員工去做更高價值的任務。"}]', 'phrasal verb'),
('stress-test', '壓力測試；嚴格考驗', 'to evaluate how something performs under extreme or challenging conditions', '[{"en":"We stress-tested the financial model under adverse scenarios.","zh-TW":"我們在不利情景下對財務模型進行了壓力測試。"},{"en":"Stress-test your assumptions before the board presentation.","zh-TW":"在董事會演示前嚴格考驗你的假設。"}]', 'phrasal verb'),
('stretch budgets', '盡量延伸預算；最大化預算利用', 'to use resources more efficiently to do more with limited funds', '[{"en":"We had to stretch budgets to cover all initiatives.","zh-TW":"我們不得不盡量延伸預算以涵蓋所有計劃。"},{"en":"Stretch your marketing budget with organic content.","zh-TW":"通過有機內容最大化你的行銷預算利用。"}]', 'phrasal verb'),
('never mind the details', '不必在意細節；跳過細節', 'used to dismiss minor points and focus on the main issue', '[{"en":"Never mind the details — is the deal viable?","zh-TW":"不必在意細節——這筆交易可行嗎？"},{"en":"Never mind the minor errors and focus on the big picture.","zh-TW":"不要在意小錯誤，專注於大局。"}]', 'expression'),
('no questions asked', '不追問原因；無條件地', 'without requiring an explanation or justification', '[{"en":"We offer a 30-day refund no questions asked.","zh-TW":"我們提供30天退款，不追問原因。"},{"en":"The policy covers all returns no questions asked.","zh-TW":"政策涵蓋所有退貨，無條件受理。"}]', 'expression'),
('nothing ventured nothing gained', '不入虎穴焉得虎子；不冒險不成功', 'you cannot achieve success without taking risks', '[{"en":"We entered the new market — nothing ventured nothing gained.","zh-TW":"我們進入了新市場——不入虎穴焉得虎子。"},{"en":"Nothing ventured nothing gained is the entrepreneur''s motto.","zh-TW":"不冒險不成功是創業者的座右銘。"}]', 'expression'),
('odds are', '很可能；機率上來說', 'it is likely that something will happen', '[{"en":"Odds are the deal will close this month.","zh-TW":"很可能這筆交易本月就會完成。"},{"en":"The odds are in our favor given the market trends.","zh-TW":"從市場趨勢看機率對我們有利。"}]', 'expression'),
('on equal footing', '平等地；在同等基礎上', 'having the same standing or advantage as others', '[{"en":"The new rules put small firms on equal footing with large ones.","zh-TW":"新規則讓小公司與大公司在平等基礎上競爭。"},{"en":"We want all candidates assessed on equal footing.","zh-TW":"我們希望所有候選人都在平等基礎上接受評估。"}]', 'prepositional phrase'),
('on short notice', '短時間內；臨時通知地', 'with very little advance warning or preparation time', '[{"en":"We managed to organize the event on short notice.","zh-TW":"我們在短時間內設法籌辦了這次活動。"},{"en":"Thank you for responding on such short notice.","zh-TW":"感謝你在如此短的時間內做出回應。"}]', 'prepositional phrase'),
('on solid ground', '基礎穩固；立場站得住腳', 'in a secure or well-supported position', '[{"en":"Our legal position is on solid ground.","zh-TW":"我們的法律立場基礎穩固。"},{"en":"Ensure you are on solid ground before making the announcement.","zh-TW":"在發表聲明之前確保你的立場站得住腳。"}]', 'prepositional phrase'),
('on the front line', '在第一線；直接面對挑戰', 'in the most active or challenging position of an operation', '[{"en":"Customer service teams are on the front line of brand experience.","zh-TW":"客戶服務團隊在品牌體驗的第一線。"},{"en":"People on the front line understand real challenges best.","zh-TW":"在第一線的人最了解真實的挑戰。"}]', 'prepositional phrase'),
('on the go', '忙個不停；在行動中', 'very busy; in the middle of activities', '[{"en":"She''s always on the go with back-to-back client meetings.","zh-TW":"她總是忙個不停，客戶會議一個接一個。"},{"en":"Mobile tools help teams work on the go.","zh-TW":"行動工具幫助團隊在移動中工作。"}]', 'prepositional phrase'),
('on the right track', '方向正確；走在正軌上', 'proceeding correctly toward a desired goal', '[{"en":"The early results show we are on the right track.","zh-TW":"早期結果顯示我們走在正軌上。"},{"en":"We''re on the right track but need to accelerate.","zh-TW":"我們方向正確但需要加速。"}]', 'prepositional phrase'),
('on the spot', '當場；立即；在現場', 'immediately; without delay; in the exact location', '[{"en":"He made the decision on the spot without consulting others.","zh-TW":"他當場做出了決定，沒有諮詢其他人。"},{"en":"Be prepared to answer tough questions on the spot.","zh-TW":"準備好當場回答棘手問題。"}]', 'prepositional phrase'),
('on the upswing', '上升中；好轉中', 'in a period of improvement or growth', '[{"en":"Our market share is on the upswing after the relaunch.","zh-TW":"重新推出後我們的市場份額正在上升中。"},{"en":"The economy is on the upswing heading into Q4.","zh-TW":"進入第四季前經濟正在好轉中。"}]', 'prepositional phrase'),
('open to negotiation', '可以談判；有商量餘地', 'willing to discuss and adjust terms through negotiation', '[{"en":"The price is open to negotiation for volume orders.","zh-TW":"批量訂單的價格可以談判。"},{"en":"We''re open to negotiation on delivery terms.","zh-TW":"我們在交貨條款上有商量餘地。"}]', 'expression'),
('over the long term', '從長遠來看；長期內', 'considering a long period of time', '[{"en":"Over the long term brand equity outweighs short-term gains.","zh-TW":"從長遠來看品牌資產超過短期收益。"},{"en":"Our sustainability goals are designed over the long term.","zh-TW":"我們的可持續發展目標是著眼於長期規劃的。"}]', 'prepositional phrase'),
('pay dirt', '找到有利可圖的東西；獲得成功', 'to find or achieve something very valuable or successful', '[{"en":"The team hit pay dirt with the new product feature.","zh-TW":"團隊在新產品功能上找到了有利可圖的東西。"},{"en":"We finally hit pay dirt after months of market research.","zh-TW":"幾個月的市場研究後我們終於獲得了成功。"}]', 'expression'),
('piece of the pie', '分一杯羹；獲得一份份額', 'a share of something valuable, especially profits or market', '[{"en":"Everyone wants a piece of the pie in the booming sector.","zh-TW":"每個人都想在蓬勃發展的行業中分一杯羹。"},{"en":"We claim our piece of the pie with premium offerings.","zh-TW":"我們通過高端產品獲得市場份額。"}]', 'expression'),
('plain sailing', '一帆風順；順利無阻', 'an easy and trouble-free process', '[{"en":"After approval it should be plain sailing.","zh-TW":"獲批後應該一帆風順了。"},{"en":"The integration was plain sailing thanks to good planning.","zh-TW":"由於良好的規劃，整合過程一帆風順。"}]', 'expression'),
('play safe', '求穩；謹慎行事', 'to avoid risks by choosing safer options', '[{"en":"In uncertain markets it''s wise to play safe.","zh-TW":"在不確定的市場中謹慎行事是明智的。"},{"en":"Play safe with cash reserves when forecasting is unclear.","zh-TW":"在預測不清楚時對現金儲備求穩。"}]', 'expression'),
('play to strengths', '發揮優勢；揚長避短', 'to focus on areas where one has the greatest advantage', '[{"en":"Play to your team''s strengths when assigning roles.","zh-TW":"分配職責時要發揮團隊的優勢。"},{"en":"Our strategy is to play to our brand strengths.","zh-TW":"我們的策略是發揮我們的品牌優勢。"}]', 'expression'),
('position for growth', '為成長做好佈局；為增長做定位', 'to organize or develop in preparation for future expansion', '[{"en":"We are positioning the company for growth in Southeast Asia.","zh-TW":"我們正在為公司在東南亞的成長做佈局。"},{"en":"Position your team for growth by investing in training.","zh-TW":"通過投資培訓為團隊的成長做定位。"}]', 'expression'),
('practice what you preach', '言行一致；以身作則', 'to behave in a way consistent with your own advice or values', '[{"en":"Good leaders practice what they preach on transparency.","zh-TW":"優秀的領導者在透明度上言行一致。"},{"en":"Practice what you preach on work-life balance.","zh-TW":"在工作與生活平衡上以身作則。"}]', 'expression'),
('press the flesh', '握手寒暄；社交應酬', 'to shake hands and meet people at a social or business event', '[{"en":"The CEO pressed the flesh at the industry gala.","zh-TW":"執行長在行業晚宴上廣泛握手寒暄。"},{"en":"Pressing the flesh at trade shows builds lasting contacts.","zh-TW":"在貿易展覽上社交應酬建立了持久的聯繫。"}]', 'expression'),
('prior commitment', '預先承諾；既有的安排', 'an obligation that was already agreed to before a new request', '[{"en":"I can''t attend due to a prior commitment.","zh-TW":"我因為預先承諾無法出席。"},{"en":"Check for prior commitments before scheduling new meetings.","zh-TW":"在安排新會議前檢查既有的安排。"}]', 'prepositional phrase'),
('prove one''s worth', '證明自身價值；展示能力', 'to demonstrate that you are capable or valuable', '[{"en":"She proved her worth within the first three months.","zh-TW":"她在前三個月就證明了自身價值。"},{"en":"New hires must prove their worth before earning autonomy.","zh-TW":"新員工必須展示能力後才能獲得自主權。"}]', 'expression'),
('pull in the same direction', '朝同一方向努力；齊心協力', 'to work toward the same goal in a unified manner', '[{"en":"For success we all need to pull in the same direction.","zh-TW":"為了成功我們都需要朝同一方向努力。"},{"en":"Leadership must pull in the same direction or confuse the team.","zh-TW":"領導層必須齊心協力否則會讓團隊困惑。"}]', 'expression'),
('punch above one''s weight', '超水準發揮；表現優於預期', 'to perform at a higher level than your size or resources would suggest', '[{"en":"Our small team punches above its weight on innovation.","zh-TW":"我們的小型團隊在創新上超水準發揮。"},{"en":"The startup punches above its weight by partnering strategically.","zh-TW":"這家新創公司通過策略性合作表現優於預期。"}]', 'expression'),
('put the cart before the horse', '本末倒置；次序顛倒', 'to do things in the wrong order', '[{"en":"Launching before validating is putting the cart before the horse.","zh-TW":"在驗證之前就發布是本末倒置。"},{"en":"Don''t put the cart before the horse — test before scaling.","zh-TW":"不要次序顛倒——先測試再擴大規模。"}]', 'expression'),
('return to the fold', '回歸組織；重新加入', 'to come back to a group after a period of absence', '[{"en":"The veteran employee returned to the fold after two years away.","zh-TW":"這位資深員工離開兩年後回歸了組織。"},{"en":"Win back churned customers and help them return to the fold.","zh-TW":"贏回流失的客戶並幫助他們重新加入。"}]', 'expression'),
('rocket science', '困難的事；複雜難懂的事', 'something that is very difficult to understand or do (often used negatively)', '[{"en":"Improving customer response time isn''t rocket science.","zh-TW":"提高客戶響應時間並不是什麼複雜難懂的事。"},{"en":"It''s not rocket science — listen to the customer.","zh-TW":"這並不難——傾聽客戶就好了。"}]', 'expression'),
('second nature', '第二天性；自然而然', 'a skill or behavior that has become automatic through practice', '[{"en":"After training upselling became second nature for the team.","zh-TW":"培訓後向上銷售對團隊來說變得自然而然。"},{"en":"Managing objections becomes second nature with experience.","zh-TW":"處理異議隨著經驗積累變得自然而然。"}]', 'expression'),
('sell short', '低估；不重視自己（或他人）的能力', 'to undervalue someone or something; to sell stocks expecting price to fall', '[{"en":"Don''t sell yourself short in salary negotiations.","zh-TW":"在薪資談判中不要低估自己的能力。"},{"en":"The brand sold itself short by focusing only on price.","zh-TW":"這個品牌只專注於價格而不重視自身的價值。"}]', 'phrasal verb'),
('serve as', '作為；充當；擔任', 'to function as or act in a particular role', '[{"en":"This project serves as a model for future launches.","zh-TW":"這個專案作為未來發布的參考範本。"},{"en":"The pilot serves as proof of concept for investors.","zh-TW":"試點作為投資者的概念驗證。"}]', 'phrasal verb'),
('shed light on', '揭示；闡明；解釋', 'to clarify or provide insight into something', '[{"en":"The audit shed light on inefficiencies in the supply chain.","zh-TW":"審計揭示了供應鏈中的低效問題。"},{"en":"The research shed light on customer behavior patterns.","zh-TW":"研究闡明了客戶行為模式。"}]', 'phrasal verb'),
('shift gears', '改變方向；轉換策略', 'to change approach, topic, or direction', '[{"en":"Let''s shift gears and talk about the budget.","zh-TW":"讓我們改變方向談談預算問題。"},{"en":"The company shifted gears from hardware to software.","zh-TW":"公司從硬體轉換到了軟體策略。"}]', 'phrasal verb'),
('shoot for', '力求達到；設定目標', 'to aim for a particular goal or achievement', '[{"en":"We''re shooting for 20% growth this year.","zh-TW":"我們力求今年達到20%的增長。"},{"en":"Shoot for the stars but plan for realistic outcomes.","zh-TW":"力求最高目標但規劃現實的結果。"}]', 'phrasal verb'),
('shortlist candidates', '列入候選名單；入圍', 'to create a list of the most suitable candidates for selection', '[{"en":"We shortlisted three vendors for the final review.","zh-TW":"我們將三個供應商列入了最終審查的候選名單。"},{"en":"Shortlist based on both price and capability.","zh-TW":"根據價格和能力進行入圍篩選。"}]', 'phrasal verb'),
('show results', '展現成果；顯示效果', 'to demonstrate tangible outcomes from effort or investment', '[{"en":"The new campaign is already showing results.","zh-TW":"新的行銷活動已經在展現成果了。"},{"en":"We need to show results before the next funding round.","zh-TW":"在下一輪融資前我們需要展現成果。"}]', 'phrasal verb'),
('slim down', '精簡；縮減規模', 'to reduce the size or number of something, especially a team or process', '[{"en":"We slimmed down operations to improve profitability.","zh-TW":"我們精簡了運營以提高盈利能力。"},{"en":"Slim down the management layers for faster decisions.","zh-TW":"精簡管理層次以加快決策速度。"}]', 'phrasal verb'),
('speak to', '涉及；說明；回應', 'to address or relate to a specific topic or concern', '[{"en":"The proposal speaks to the client''s core needs.","zh-TW":"這份提案涉及了客戶的核心需求。"},{"en":"The data speaks to the effectiveness of the program.","zh-TW":"數據說明了這個計劃的有效性。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('strengthen ties', '加強聯繫；鞏固關係', 'to improve relationships or connections', '[{"en":"We strengthened ties with key suppliers through joint training.","zh-TW":"我們通過聯合培訓加強了與主要供應商的聯繫。"},{"en":"Strengthen ties with the community to build brand goodwill.","zh-TW":"加強與社區的聯繫以建立品牌商譽。"}]', 'phrasal verb'),
('test the waters', '試探；小規模測試市場', 'to cautiously try something new before fully committing', '[{"en":"We tested the waters with a limited product launch.","zh-TW":"我們通過有限的產品發布試探了市場。"},{"en":"Test the waters before committing to full expansion.","zh-TW":"在承諾全面擴張之前小規模測試市場。"}]', 'phrasal verb'),
('track down', '追蹤；找到；查明', 'to find someone or something after searching', '[{"en":"She tracked down the original vendor after years.","zh-TW":"她在多年後找到了原來的供應商。"},{"en":"Track down the source of the data inconsistency.","zh-TW":"查明數據不一致的來源。"}]', 'phrasal verb'),
('transition into', '轉變為；過渡到', 'to change gradually from one state, role, or situation to another', '[{"en":"She transitioned into a leadership role seamlessly.","zh-TW":"她順暢地過渡到了領導角色。"},{"en":"The company transitioned into the digital economy.","zh-TW":"公司過渡到了數位經濟。"}]', 'phrasal verb'),
('turbocharge', '大力推進；大幅提速', 'to accelerate significantly using additional resources or strategies', '[{"en":"The partnership turbocharged our international expansion.","zh-TW":"合作大力推進了我們的國際擴張。"},{"en":"Turbocharge product development with additional funding.","zh-TW":"利用額外資金大幅提速產品開發。"}]', 'phrasal verb'),
('undercut competitors', '以低價競爭；壓低對手的價格', 'to charge less than competitors to win business', '[{"en":"We won the contract by undercutting competitors on price.","zh-TW":"我們以低價壓制競爭對手贏得了合約。"},{"en":"Undercutting on price alone is not a sustainable strategy.","zh-TW":"單純以低價競爭並不是可持續的策略。"}]', 'phrasal verb'),
('value proposition', '價值主張；價值定位', 'the unique benefit a product or service offers to customers', '[{"en":"Our value proposition is speed combined with quality.","zh-TW":"我們的價值主張是速度與品質的結合。"},{"en":"A clear value proposition sets you apart from competitors.","zh-TW":"清晰的價值主張讓你與競爭對手有所區別。"}]', 'business idiom'),
('vendor lock-in', '供應商鎖定；被迫依賴特定供應商', 'a situation where a customer is dependent on one vendor', '[{"en":"Vendor lock-in increases costs and reduces flexibility.","zh-TW":"供應商鎖定增加了成本並降低了靈活性。"},{"en":"Build contracts that prevent vendor lock-in.","zh-TW":"建立防止供應商鎖定的合約。"}]', 'business idiom'),
('vertical integration', '垂直整合', 'when a company controls multiple stages of its supply chain', '[{"en":"Vertical integration gives us more control over quality.","zh-TW":"垂直整合讓我們對品質有更多控制。"},{"en":"Vertical integration was key to Amazon''s dominance.","zh-TW":"垂直整合是亞馬遜主導地位的關鍵。"}]', 'business idiom'),
('voice of the customer', '客戶之聲；客戶反饋', 'a process of capturing customers'' expectations, preferences, and aversions', '[{"en":"We built the feature based on voice of the customer insights.","zh-TW":"我們根據客戶之聲的洞察建立了這個功能。"},{"en":"Voice of the customer should guide product roadmap decisions.","zh-TW":"客戶之聲應該指導產品路線圖決策。"}]', 'business idiom'),
('war chest', '戰略資金儲備；充裕的資金', 'funds reserved for a major competitive initiative or battle', '[{"en":"The company built a war chest of 500 million for acquisitions.","zh-TW":"公司為收購建立了五億的戰略資金儲備。"},{"en":"A strong war chest positions you to act on opportunities quickly.","zh-TW":"充裕的戰略儲備讓你能夠迅速把握機會。"}]', 'business idiom'),
('whale client', '大客戶；超大型客戶', 'an exceptionally large or high-value customer', '[{"en":"Landing a whale client transformed our quarterly results.","zh-TW":"拿下大客戶改變了我們的季度業績。"},{"en":"Whale clients can make up 50% of revenue but carry risk.","zh-TW":"大客戶可能佔收入的50%但帶來風險。"}]', 'business idiom'),
('win-win scenario', '雙贏情景；互利共贏', 'a situation that benefits all parties involved', '[{"en":"We structured the deal as a win-win scenario for both sides.","zh-TW":"我們將這筆交易構建為雙方互利共贏的情景。"},{"en":"Look for win-win scenarios in every negotiation.","zh-TW":"在每次談判中尋求雙贏情景。"}]', 'business idiom'),
('work the room', '在場內廣泛交際；圓融地交流', 'to interact with many people at a social or business event', '[{"en":"He worked the room at the gala and made three new contacts.","zh-TW":"他在晚宴上廣泛交際並建立了三個新聯繫。"},{"en":"Work the room at conferences to maximize networking.","zh-TW":"在會議上圓融地交流以最大化人脈建立。"}]', 'business idiom'),
('zero-sum game', '零和遊戲；一方所得即另一方所失', 'a situation where one party''s gain equals another''s loss', '[{"en":"Pricing wars become a zero-sum game that hurts everyone.","zh-TW":"價格戰成為損害所有人的零和遊戲。"},{"en":"Collaboration often beats the zero-sum game mentality.","zh-TW":"合作往往優於零和遊戲的思維方式。"}]', 'business idiom'),
('zone of comfort', '舒適區', 'a situation where one feels safe and not challenged', '[{"en":"Growth comes when you step outside your zone of comfort.","zh-TW":"走出舒適區才能獲得成長。"},{"en":"Leaders must challenge teams to leave their zone of comfort.","zh-TW":"領導者必須挑戰團隊離開他們的舒適區。"}]', 'expression'),
('abundance mentality', '豐盛心態；不害怕與人共享成功', 'the belief that there is enough opportunity for everyone to succeed', '[{"en":"Leaders with an abundance mentality share credit generously.","zh-TW":"有豐盛心態的領導者慷慨地分享功勞。"},{"en":"Cultivate abundance mentality to reduce internal competition.","zh-TW":"培養豐盛心態以減少內部競爭。"}]', 'business idiom'),
('accountability culture', '問責文化；責任感文化', 'an organizational environment where people take responsibility for results', '[{"en":"An accountability culture reduces blame-shifting.","zh-TW":"問責文化減少了推卸責任的情況。"},{"en":"Build accountability culture through transparent metrics.","zh-TW":"通過透明的指標建立責任感文化。"}]', 'business idiom'),
('adjacent market', '相鄰市場；相關市場', 'a market that is related to but distinct from the current core market', '[{"en":"We expanded into adjacent markets to diversify revenue.","zh-TW":"我們進入相鄰市場以多元化收入來源。"},{"en":"Adjacent markets offer lower risk than entirely new sectors.","zh-TW":"相鄰市場比全新的行業風險更低。"}]', 'business idiom'),
('agile mindset', '敏捷思維；靈活應變的心態', 'a flexible and iterative approach to work and problem-solving', '[{"en":"An agile mindset enables rapid response to change.","zh-TW":"敏捷思維能夠快速響應變化。"},{"en":"Foster an agile mindset across all departments.","zh-TW":"在所有部門培養靈活應變的心態。"}]', 'business idiom'),
('all-in', '全力投入；不留後路', 'committed to a course of action with full resources', '[{"en":"We went all-in on cloud infrastructure.","zh-TW":"我們在雲端基礎設施上全力投入。"},{"en":"Going all-in means accepting higher risk for higher reward.","zh-TW":"全力投入意味著接受更高風險以獲取更高回報。"}]', 'business idiom'),
('anchor client', '核心客戶；支柱客戶', 'a major, foundational customer whose business supports a company''s stability', '[{"en":"Winning an anchor client opened doors to the whole sector.","zh-TW":"贏得核心客戶為整個行業打開了大門。"},{"en":"An anchor client provides revenue stability for startups.","zh-TW":"支柱客戶為新創公司提供了收入穩定性。"}]', 'business idiom'),
('arm yourself with data', '用數據武裝自己；充分準備數據', 'to prepare thoroughly with relevant facts and figures before a meeting or negotiation', '[{"en":"Arm yourself with data before the salary negotiation.","zh-TW":"在薪資談判前用數據武裝自己。"},{"en":"She walked in armed with data and won the argument.","zh-TW":"她帶著充分的數據走進去並贏得了爭論。"}]', 'expression'),
('ask the hard questions', '提出棘手問題；做出深入追問', 'to raise difficult but necessary questions', '[{"en":"A good board asks the hard questions management avoids.","zh-TW":"優秀的董事會提出管理層迴避的棘手問題。"},{"en":"Ask the hard questions before the product launch.","zh-TW":"在產品發布前提出棘手問題。"}]', 'expression'),
('balance the books', '帳目平衡；收支平衡', 'to ensure income equals expenditure in financial records', '[{"en":"The finance team worked overtime to balance the books.","zh-TW":"財務團隊加班以使帳目平衡。"},{"en":"Balance the books monthly to catch discrepancies early.","zh-TW":"每月平衡帳目以儘早發現差異。"}]', 'expression'),
('barnstorm', '大力宣傳；到處推廣', 'to travel widely making presentations or promoting something energetically', '[{"en":"The CEO barnstormed major cities to promote the launch.","zh-TW":"執行長走遍主要城市大力宣傳這次發布。"},{"en":"They barnstormed the market to build early traction.","zh-TW":"他們到處推廣以建立早期關注度。"}]', 'phrasal verb'),
('be in safe hands', '處於妥善照顧中；由可靠人負責', 'to be well looked after by a competent person or team', '[{"en":"The new project is in safe hands with that team.","zh-TW":"這個新專案由那個團隊負責，妥善可靠。"},{"en":"Investors felt the company was in safe hands.","zh-TW":"投資者感到公司由可靠的人負責。"}]', 'expression'),
('benchmark against', '與…作標竿比較；對標', 'to compare performance or practices with a reference standard', '[{"en":"We benchmark our KPIs against industry leaders annually.","zh-TW":"我們每年將我們的KPI與行業領導者對標。"},{"en":"Benchmark the process against global best practices.","zh-TW":"將流程與全球最佳實踐對標比較。"}]', 'phrasal verb'),
('big-ticket item', '大宗採購；高價項目', 'a costly purchase or investment item', '[{"en":"Big-ticket items require board approval.","zh-TW":"大宗採購需要董事會批准。"},{"en":"Negotiate big-ticket items carefully to protect margins.","zh-TW":"仔細談判高價項目以保護利潤率。"}]', 'business idiom'),
('blue-chip client', '頂級客戶；藍籌客戶', 'a highly reputable and reliable large corporate client', '[{"en":"Adding a blue-chip client to our portfolio boosts credibility.","zh-TW":"將頂級客戶加入我們的客戶組合提升了可信度。"},{"en":"Blue-chip clients demand the highest service standards.","zh-TW":"藍籌客戶要求最高的服務標準。"}]', 'business idiom'),
('boardroom dynamics', '董事會生態；高層決策氛圍', 'the relationships and power structures within a board of directors', '[{"en":"Understanding boardroom dynamics helps you present effectively.","zh-TW":"了解董事會生態有助於你有效展示。"},{"en":"Boardroom dynamics shifted after the new chair was appointed.","zh-TW":"新主席就任後董事會生態發生了變化。"}]', 'business idiom'),
('brain trust', '智囊團；核心智庫', 'a group of experts who advise on strategy or decisions', '[{"en":"The CEO assembled a brain trust to guide the digital transformation.","zh-TW":"執行長組建了一個智囊團來指導數位轉型。"},{"en":"A diverse brain trust leads to more innovative solutions.","zh-TW":"多元化的智囊團帶來了更具創新性的解決方案。"}]', 'business idiom'),
('break even point', '損益兩平點；收支平衡點', 'the production or sales level at which total costs equal total revenue', '[{"en":"The break even point is 500 units per month.","zh-TW":"損益兩平點是每月500個單位。"},{"en":"Know your break even point before setting pricing.","zh-TW":"在設定定價前知道你的收支平衡點。"}]', 'business idiom'),
('brick-and-mortar', '實體店；線下商業', 'a traditional physical store as opposed to an online business', '[{"en":"We still maintain brick-and-mortar stores for experience.","zh-TW":"我們仍然保留實體店以提供體驗。"},{"en":"Brick-and-mortar retail is evolving to blend with digital.","zh-TW":"實體零售正在演變為與數位融合。"}]', 'business idiom'),
('budget cycle', '預算週期', 'the recurring period during which a budget is planned, implemented, and reviewed', '[{"en":"Submit proposals before the budget cycle closes.","zh-TW":"在預算週期結束前提交提案。"},{"en":"The budget cycle determines when resources can be allocated.","zh-TW":"預算週期決定了何時可以分配資源。"}]', 'business idiom'),
('business continuity', '業務連續性；持續運營能力', 'the ability to maintain essential functions during and after a crisis', '[{"en":"Business continuity planning became a priority after the pandemic.","zh-TW":"業務連續性規劃在疫情後成為優先事項。"},{"en":"Test your business continuity plan annually.","zh-TW":"每年測試你的業務連續性計劃。"}]', 'business idiom'),
('buy-in from stakeholders', '獲得利益相關者的認同', 'obtaining agreement and support from key stakeholders', '[{"en":"Securing buy-in from stakeholders accelerated the rollout.","zh-TW":"獲得利益相關者的認同加速了推出進程。"},{"en":"Without buy-in from stakeholders projects often stall.","zh-TW":"沒有利益相關者的認同專案往往停滯不前。"}]', 'business idiom'),
('by the numbers', '從數字看；根據統計', 'based on statistical data; following exact rules or formulas', '[{"en":"Let''s look at the campaign by the numbers.","zh-TW":"讓我們從數字看這次活動的結果。"},{"en":"By the numbers our performance exceeds industry average.","zh-TW":"根據統計我們的表現超過了行業平均水準。"}]', 'prepositional phrase'),
('c-suite', 'C字輩高管；最高管理層', 'the highest level executives in a company (CEO, CFO, COO, etc.)', '[{"en":"The proposal was escalated to the c-suite for final approval.","zh-TW":"提案被上報給最高管理層最終批准。"},{"en":"C-suite buy-in is essential for large-scale change.","zh-TW":"最高管理層的認同對大規模變革至關重要。"}]', 'business idiom'),
('capability gap', '能力差距；技能缺口', 'the difference between current capabilities and what is needed', '[{"en":"We identified a capability gap in data analytics.","zh-TW":"我們識別了數據分析方面的能力差距。"},{"en":"Close capability gaps through targeted training or hiring.","zh-TW":"通過針對性培訓或招聘來填補技能缺口。"}]', 'business idiom'),
('capacity planning', '產能規劃；資源容量規劃', 'the process of determining how much production or resource capacity is needed', '[{"en":"Proper capacity planning prevents bottlenecks during peak periods.","zh-TW":"適當的產能規劃可以防止高峰期出現瓶頸。"},{"en":"Capacity planning aligns supply with anticipated demand.","zh-TW":"產能規劃使供應與預期需求一致。"}]', 'business idiom'),
('carry the torch', '承擔責任繼承使命；傳承領導棒', 'to continue a tradition or cause started by someone else', '[{"en":"She carried the torch of innovation after the founder retired.","zh-TW":"創始人退休後她承擔起了創新的使命。"},{"en":"Carry the torch with integrity to honor the company''s legacy.","zh-TW":"以誠信傳承領導棒以尊重公司的遺產。"}]', 'expression'),
('catch up with the competition', '追趕競爭對手', 'to reduce the gap between yourself and competitors', '[{"en":"We invested heavily to catch up with the competition.","zh-TW":"我們大力投資以追趕競爭對手。"},{"en":"Catching up with the competition requires bold moves.","zh-TW":"追趕競爭對手需要大膽的行動。"}]', 'expression'),
('change the game', '改變遊戲規則；顛覆現狀', 'to fundamentally alter how something works, creating an advantage', '[{"en":"The new technology changed the game for our industry.","zh-TW":"新技術改變了我們行業的遊戲規則。"},{"en":"You need to change the game to compete against established players.","zh-TW":"你需要顛覆現狀才能與成熟的競爭者競爭。"}]', 'expression'),
('circle of influence', '影響圈；可影響的範圍', 'the area or people over which one has direct control or impact', '[{"en":"Focus on your circle of influence rather than worrying about what you can''t control.","zh-TW":"專注於你的影響圈而不是擔心你無法控制的事。"},{"en":"Expand your circle of influence by building expertise.","zh-TW":"通過建立專業知識來擴大你的影響圈。"}]', 'expression'),
('close the loop', '形成閉環；完成跟進；收尾', 'to complete a cycle by following up or providing a resolution', '[{"en":"Always close the loop with customers after resolving issues.","zh-TW":"解決問題後務必與客戶形成閉環。"},{"en":"Close the loop on all action items from the last meeting.","zh-TW":"完成上次會議所有行動項目的收尾。"}]', 'expression'),
('command a premium', '可以定較高的價格；具有溢價能力', 'to be able to charge more than others due to superior value', '[{"en":"Our reputation allows us to command a premium.","zh-TW":"我們的聲譽使我們能夠定較高的價格。"},{"en":"High-quality brands command a premium in any market.","zh-TW":"高品質品牌在任何市場都具有溢價能力。"}]', 'expression'),
('competitor landscape', '競爭格局；競爭對手全貌', 'an overview of all competitors in a market and their positions', '[{"en":"Map out the competitor landscape before entering the market.","zh-TW":"在進入市場前描繪競爭格局。"},{"en":"The competitor landscape shifted with the new entrant.","zh-TW":"隨著新競爭者進入，競爭格局發生了變化。"}]', 'business idiom'),
('compliance framework', '合規框架', 'the set of guidelines and processes for meeting regulatory requirements', '[{"en":"We implemented a compliance framework to meet GDPR.","zh-TW":"我們建立了合規框架以符合GDPR要求。"},{"en":"A strong compliance framework protects the company from fines.","zh-TW":"強大的合規框架保護公司免受罰款。"}]', 'business idiom'),
('conversion rate', '轉換率；轉化率', 'the percentage of potential customers who take the desired action', '[{"en":"We improved our website conversion rate by 15%.","zh-TW":"我們將網站轉換率提高了15%。"},{"en":"A higher conversion rate means better return on marketing spend.","zh-TW":"更高的轉換率意味著更好的行銷投入回報。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('cost center', '成本中心', 'a department that incurs costs but does not directly generate revenue', '[{"en":"IT was historically treated as a cost center.","zh-TW":"IT部門過去一直被視為成本中心。"},{"en":"Transform the cost center into a value generator.","zh-TW":"將成本中心轉變為價值創造者。"}]', 'business idiom'),
('cost overrun', '成本超支；費用超預算', 'expenses that exceed the planned budget for a project', '[{"en":"Cost overruns on the project delayed the timeline.","zh-TW":"專案的成本超支推遲了時間表。"},{"en":"Rigorous cost tracking prevents unexpected cost overruns.","zh-TW":"嚴格的成本追蹤防止了意外的費用超支。"}]', 'business idiom'),
('critical path', '關鍵路徑；決定最短完工時間的工作序列', 'the sequence of dependent tasks that determines the minimum project duration', '[{"en":"Identify the critical path to avoid delaying the whole project.","zh-TW":"識別關鍵路徑以避免延誤整個專案。"},{"en":"Any delay on the critical path extends the project deadline.","zh-TW":"關鍵路徑上的任何延誤都會延長專案截止日期。"}]', 'business idiom'),
('customer acquisition cost', '客戶獲取成本', 'the total cost of acquiring a new customer through marketing and sales efforts', '[{"en":"Referral programs can reduce customer acquisition cost significantly.","zh-TW":"推薦計劃可以顯著降低客戶獲取成本。"},{"en":"Track customer acquisition cost by channel.","zh-TW":"按渠道追蹤客戶獲取成本。"}]', 'business idiom'),
('customer lifetime value', '客戶終身價值', 'the total revenue a business can expect from a single customer relationship', '[{"en":"Increasing customer lifetime value is more cost-effective than acquisition.","zh-TW":"提高客戶終身價值比獲取新客戶更具成本效益。"},{"en":"Calculate customer lifetime value to guide marketing spend.","zh-TW":"計算客戶終身價值以指導行銷支出。"}]', 'business idiom'),
('customer touchpoint', '客戶接觸點', 'any interaction between a customer and a company at any stage', '[{"en":"Map all customer touchpoints to improve the experience.","zh-TW":"繪製所有客戶接觸點以改善體驗。"},{"en":"Consistent messaging across every customer touchpoint builds trust.","zh-TW":"在每個客戶接觸點保持一致的信息建立信任。"}]', 'business idiom'),
('day-to-day operations', '日常運營；日常業務', 'the regular, routine activities that keep a business running', '[{"en":"She manages day-to-day operations while the CEO focuses on strategy.","zh-TW":"她管理日常運營而執行長專注於策略。"},{"en":"Automate day-to-day operations to free up management time.","zh-TW":"自動化日常運營以釋放管理層的時間。"}]', 'business idiom'),
('decision maker', '決策者', 'the person with the authority to make final decisions', '[{"en":"Identify the decision maker early in the sales process.","zh-TW":"在銷售流程的早期識別決策者。"},{"en":"Tailor your pitch to the decision maker''s priorities.","zh-TW":"根據決策者的優先事項量身訂制你的推介。"}]', 'business idiom'),
('emerging market', '新興市場', 'a country with a developing economy that offers growth opportunities', '[{"en":"Emerging markets are a major growth driver for our sector.","zh-TW":"新興市場是我們行業的主要增長驅動力。"},{"en":"Entry into emerging markets requires cultural adaptation.","zh-TW":"進入新興市場需要文化適應。"}]', 'business idiom'),
('enterprise solution', '企業解決方案', 'a product or service designed for large organizations', '[{"en":"We developed an enterprise solution for Fortune 500 clients.","zh-TW":"我們為財富500強客戶開發了企業解決方案。"},{"en":"Enterprise solutions require longer sales cycles.","zh-TW":"企業解決方案需要更長的銷售週期。"}]', 'business idiom'),
('find a middle ground', '找到折中方案；達成妥協', 'to reach a compromise between two opposing positions', '[{"en":"We found a middle ground on the contract length.","zh-TW":"我們在合約期限上找到了折中方案。"},{"en":"Good negotiators always look for a middle ground.","zh-TW":"優秀的談判者總是尋求達成妥協。"}]', 'expression'),
('first-mover advantage', '先發優勢', 'the competitive benefit of being the first to enter a new market', '[{"en":"Our first-mover advantage in mobile payments is significant.","zh-TW":"我們在移動支付領域的先發優勢是顯著的。"},{"en":"First-mover advantage quickly erodes without continuous innovation.","zh-TW":"沒有持續創新先發優勢很快就會消退。"}]', 'business idiom'),
('flat organization', '扁平化組織', 'a company with few or no levels of management between executives and staff', '[{"en":"A flat organization speeds up decision-making.","zh-TW":"扁平化組織加快了決策速度。"},{"en":"The startup operates as a flat organization to stay agile.","zh-TW":"新創公司以扁平化組織運作以保持靈活性。"}]', 'business idiom'),
('game plan', '行動計劃；策略計劃', 'a detailed strategy or plan of action', '[{"en":"We drafted a clear game plan before the merger.","zh-TW":"在合併之前我們制定了清晰的行動計劃。"},{"en":"Share the game plan with the entire team before launch.","zh-TW":"在發布前與整個團隊分享策略計劃。"}]', 'business idiom'),
('good faith effort', '誠信努力；真誠的嘗試', 'an honest and sincere attempt to do something', '[{"en":"We made a good faith effort to resolve the dispute.","zh-TW":"我們誠信地努力解決了這場爭議。"},{"en":"A good faith effort is expected before escalating issues.","zh-TW":"在升級問題之前應先做出真誠的嘗試。"}]', 'expression'),
('go-to-market strategy', '市場進入策略', 'the plan a company uses to launch a product into the market', '[{"en":"Our go-to-market strategy focuses on digital-first distribution.","zh-TW":"我們的市場進入策略專注於數位優先分銷。"},{"en":"A strong go-to-market strategy is essential for launch success.","zh-TW":"強大的市場進入策略對發布成功至關重要。"}]', 'business idiom'),
('hard stop', '硬性截止；絕對不超過的時間點', 'a non-negotiable end time or limit for a meeting or deadline', '[{"en":"I have a hard stop at 3 PM for another call.","zh-TW":"我在下午3點有硬性截止，要接另一個電話。"},{"en":"Set a hard stop on negotiations if no progress by Friday.","zh-TW":"如果週五前沒有進展就設定硬性截止談判。"}]', 'business idiom'),
('headcount freeze', '凍結人員編制；停止招聘', 'a temporary ban on hiring new employees', '[{"en":"A headcount freeze was announced during the budget review.","zh-TW":"預算審查期間宣布了凍結人員編制。"},{"en":"The headcount freeze affected all departments equally.","zh-TW":"凍結人員編制對所有部門都有同等影響。"}]', 'business idiom'),
('high-level overview', '高層次概覽；整體概述', 'a broad summary without detailed specifics', '[{"en":"Give the board a high-level overview of the project.","zh-TW":"向董事會提供專案的高層次概覽。"},{"en":"Start with a high-level overview before diving into details.","zh-TW":"在深入細節之前先提供整體概述。"}]', 'expression'),
('hold the line', '守住底線；堅守立場', 'to maintain a position or standard under pressure', '[{"en":"We held the line on pricing despite competitive pressure.","zh-TW":"儘管面臨競爭壓力我們守住了定價底線。"},{"en":"Hold the line on quality standards no matter the pressure.","zh-TW":"無論壓力多大都要堅守品質標準。"}]', 'expression'),
('horizontal expansion', '水平擴張；橫向擴展', 'growth by moving into new markets at the same level of the supply chain', '[{"en":"Horizontal expansion into adjacent markets boosted revenue.","zh-TW":"水平擴張進入相鄰市場提升了收入。"},{"en":"Horizontal expansion is often faster than vertical integration.","zh-TW":"水平擴張往往比垂直整合速度更快。"}]', 'business idiom'),
('incentivize behavior', '激勵行為；用激勵機制促進', 'to motivate certain actions by offering rewards or benefits', '[{"en":"We incentivize upselling with a tiered bonus structure.","zh-TW":"我們用分層獎金結構激勵交叉銷售行為。"},{"en":"Incentivize customers to refer others through discounts.","zh-TW":"通過折扣激勵客戶向他人推薦。"}]', 'phrasal verb'),
('infer from', '從…推斷；根據…得出結論', 'to draw a conclusion from evidence or reasoning', '[{"en":"What can we infer from this trend in the data?","zh-TW":"我們能從數據中的這個趨勢推斷什麼？"},{"en":"Infer customer intent from their browsing behavior.","zh-TW":"根據客戶的瀏覽行為推斷其意圖。"}]', 'phrasal verb'),
('integrate into', '整合進；融入', 'to combine something into a larger system or structure', '[{"en":"We integrated the new API into the existing platform.","zh-TW":"我們將新的API整合進了現有平台。"},{"en":"Integrate sustainability into your core business model.","zh-TW":"將可持續發展融入你的核心商業模式。"}]', 'phrasal verb'),
('iterate on', '對…進行迭代；持續改進', 'to repeatedly refine and improve something based on feedback', '[{"en":"We iterate on the product monthly based on user feedback.","zh-TW":"我們根據用戶反饋每月對產品進行迭代。"},{"en":"Iterate on the prototype until it meets user expectations.","zh-TW":"對原型持續改進直到達到用戶期望。"}]', 'phrasal verb'),
('key into', '深入了解；切入核心', 'to tap into or connect with something significant', '[{"en":"Their campaign keyed into the emotions of young consumers.","zh-TW":"他們的活動深入了解年輕消費者的情感。"},{"en":"Key into what your audience truly values.","zh-TW":"切入核心了解你的受眾真正重視什麼。"}]', 'phrasal verb'),
('knock out', '消除；淘汰；完成（任務）', 'to eliminate or complete quickly and efficiently', '[{"en":"Let''s knock out the easy items on the agenda first.","zh-TW":"讓我們先快速完成議程上容易的項目。"},{"en":"Knock out your competitors by outperforming on service.","zh-TW":"通過在服務上表現更好來淘汰競爭對手。"}]', 'phrasal verb'),
('lay down', '制定（規則）；確立', 'to establish rules, principles, or guidelines firmly', '[{"en":"The board laid down clear governance principles.","zh-TW":"董事會制定了清晰的治理原則。"},{"en":"Lay down ground rules before the negotiation begins.","zh-TW":"在談判開始前確立基本規則。"}]', 'phrasal verb'),
('lean into', '積極面對；主動投入；強化優勢', 'to embrace or fully engage with a situation, challenge, or strength', '[{"en":"Lean into your brand''s heritage to differentiate.","zh-TW":"積極利用品牌的傳承來差異化。"},{"en":"She leaned into the critical feedback and improved her pitch.","zh-TW":"她主動面對批評性反饋並改進了她的推介。"}]', 'phrasal verb'),
('leverage off', '借助…的優勢；從…中獲益', 'to use something as a foundation or advantage to advance', '[{"en":"We leveraged off the existing brand to launch the new line.","zh-TW":"我們借助現有品牌的優勢推出了新系列。"},{"en":"Leverage off your network to break into new markets.","zh-TW":"借助你的人脈進入新市場。"}]', 'phrasal verb'),
('make inroads into', '逐步進入；有所突破', 'to make progress in penetrating a market or solving a problem', '[{"en":"We''re making inroads into the enterprise market this year.","zh-TW":"今年我們正在逐步進入企業市場。"},{"en":"Make inroads into the competitor''s client base.","zh-TW":"在競爭對手的客戶群中有所突破。"}]', 'phrasal verb'),
('marshal resources', '整合調度資源；動員資源', 'to organize and deploy available resources efficiently', '[{"en":"We marshaled all available resources for the product launch.","zh-TW":"我們整合調度了所有可用資源以進行產品發布。"},{"en":"Marshal your best team for the most critical projects.","zh-TW":"為最關鍵的專案動員你最好的團隊。"}]', 'phrasal verb'),
('maximize potential', '最大化潛力；充分發揮', 'to use all available ability or opportunity to the fullest extent', '[{"en":"Our goal is to maximize the potential of each employee.","zh-TW":"我們的目標是最大化每位員工的潛力。"},{"en":"Maximize the potential of the technology before upgrading.","zh-TW":"在升級之前充分發揮技術的潛力。"}]', 'phrasal verb'),
('mitigate risks', '降低風險；緩解風險', 'to take action to reduce the likelihood or impact of risks', '[{"en":"Diversifying suppliers mitigates risks in the supply chain.","zh-TW":"多樣化供應商降低了供應鏈中的風險。"},{"en":"Mitigate risks with thorough due diligence.","zh-TW":"通過徹底的盡職調查緩解風險。"}]', 'phrasal verb'),
('monetize assets', '將資產變現；貨幣化資產', 'to convert assets or capabilities into revenue', '[{"en":"We found new ways to monetize our data assets.","zh-TW":"我們找到了將數據資產變現的新方法。"},{"en":"Monetize your content with subscriptions and sponsorships.","zh-TW":"通過訂閱和贊助將你的內容貨幣化。"}]', 'phrasal verb'),
('move toward', '朝向；逐步走向', 'to progress in the direction of a particular state or goal', '[{"en":"We are moving toward a subscription-based model.","zh-TW":"我們正在逐步走向訂閱制模式。"},{"en":"Move toward a data-driven culture step by step.","zh-TW":"逐步走向數據驅動的文化。"}]', 'phrasal verb'),
('negotiate in good faith', '誠信談判；真誠協商', 'to negotiate honestly and sincerely, without deceptive tactics', '[{"en":"We always negotiate in good faith with our partners.","zh-TW":"我們始終與合作夥伴誠信談判。"},{"en":"Negotiating in good faith builds long-term trust.","zh-TW":"真誠協商建立了長期信任。"}]', 'phrasal verb'),
('act with urgency', '以緊迫感行動；緊迫應對', 'to respond with speed and importance proportional to the situation', '[{"en":"Act with urgency when customer satisfaction is at risk.","zh-TW":"當客戶滿意度面臨風險時以緊迫感行動。"},{"en":"Act with urgency to capitalize on the market window.","zh-TW":"緊迫應對以把握市場機會窗口。"}]', 'expression'),
('across functional lines', '跨越職能界限；橫跨各部門', 'spanning multiple departments or functional areas', '[{"en":"Effective innovation requires collaboration across functional lines.","zh-TW":"有效的創新需要跨越職能界限的協作。"},{"en":"The project team worked across functional lines to deliver.","zh-TW":"專案團隊跨越各部門界限進行交付。"}]', 'prepositional phrase'),
('after the fact', '事後；事情發生後', 'after the event or situation has already occurred', '[{"en":"Don''t wait to discover problems after the fact.","zh-TW":"不要等到事後才發現問題。"},{"en":"We''ll review the decision after the fact with data.","zh-TW":"我們將在事後用數據審查這個決定。"}]', 'prepositional phrase'),
('along the lines of', '類似於；沿著…的思路', 'similar to or following the general idea of something', '[{"en":"We''re looking for something along the lines of their model.","zh-TW":"我們正在尋找類似於他們模式的東西。"},{"en":"Think along the lines of a subscription tier system.","zh-TW":"沿著訂閱等級系統的思路思考。"}]', 'prepositional phrase'),
('as a benchmark', '作為基準；以…為參照', 'using something as a reference point for comparison or evaluation', '[{"en":"Use industry average margins as a benchmark.","zh-TW":"以行業平均利潤率作為基準。"},{"en":"As a benchmark the top performer converts at 20%.","zh-TW":"以頂尖表現者為基準，轉換率達到20%。"}]', 'prepositional phrase'),
('as a fallback', '作為備案；備用方案', 'as an alternative option if the primary plan fails', '[{"en":"Keep a contingency plan as a fallback.","zh-TW":"保留一個備案作為應急方案。"},{"en":"As a fallback we can delay the launch by one quarter.","zh-TW":"作為備案我們可以將發布推遲一個季度。"}]', 'prepositional phrase'),
('as the situation demands', '視情況所需；因應情況需要', 'responding appropriately to whatever the circumstances require', '[{"en":"Be ready to pivot as the situation demands.","zh-TW":"準備好視情況所需進行轉向。"},{"en":"As the situation demands we scale up or down quickly.","zh-TW":"因應情況需要我們迅速擴大或縮小規模。"}]', 'prepositional phrase'),
('at a moment''s notice', '隨時；一聲令下就可以', 'with very little or no advance warning', '[{"en":"Our response team can deploy at a moment''s notice.","zh-TW":"我們的響應團隊可以隨時部署。"},{"en":"Be ready to present at a moment''s notice to senior leadership.","zh-TW":"隨時準備好向高層管理人員做演示。"}]', 'prepositional phrase'),
('at the bottom line', '歸結到最後；最終而言', 'ultimately; when all considerations are weighed', '[{"en":"At the bottom line we need to show profit.","zh-TW":"歸結到最後我們需要展示利潤。"},{"en":"At the bottom line client satisfaction drives retention.","zh-TW":"最終而言客戶滿意度推動留存率。"}]', 'prepositional phrase'),
('at the discretion of', '由…決定；依…的判斷', 'left to the judgment or choice of a specific person or authority', '[{"en":"Bonuses are awarded at the discretion of the manager.","zh-TW":"獎金由經理決定發放。"},{"en":"The terms are flexible at the discretion of both parties.","zh-TW":"條款依雙方的判斷靈活調整。"}]', 'prepositional phrase'),
('at the intersection of', '在…的交叉點上；處於…兩者之間', 'at the point where two or more fields, trends, or ideas meet', '[{"en":"Our product lives at the intersection of health and technology.","zh-TW":"我們的產品處於健康與技術的交叉點上。"},{"en":"Innovation often happens at the intersection of disciplines.","zh-TW":"創新往往發生在學科的交叉點上。"}]', 'prepositional phrase'),
('at this juncture', '在此關鍵時刻；此時此刻', 'at this particular important moment in time', '[{"en":"At this juncture the board must make a clear decision.","zh-TW":"在此關鍵時刻董事會必須做出明確的決定。"},{"en":"At this juncture any delay would be costly.","zh-TW":"此時此刻任何延誤都會造成代價。"}]', 'prepositional phrase'),
('at your earliest convenience', '方便時儘快；在你方便的最早時間', 'as soon as it is possible for you to do something', '[{"en":"Please reply at your earliest convenience.","zh-TW":"請方便時儘快回覆。"},{"en":"Submit the form at your earliest convenience to secure your spot.","zh-TW":"請在方便時儘快提交表格以確保你的席位。"}]', 'prepositional phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('barring unforeseen circumstances', '除非有意外情況；若無意外', 'unless something unexpected happens to prevent it', '[{"en":"Barring unforeseen circumstances the project will launch on time.","zh-TW":"若無意外這個專案將按時發布。"},{"en":"Barring unforeseen circumstances we should close the deal this week.","zh-TW":"除非有意外情況，我們本週應該可以完成交易。"}]', 'prepositional phrase'),
('based on merit', '以能力為依據；依靠實力', 'judged or decided according to performance or ability', '[{"en":"All promotions are decided based on merit.","zh-TW":"所有晉升都以能力為依據決定。"},{"en":"We hire and promote based on merit not seniority.","zh-TW":"我們依靠實力而不是資歷進行招聘和晉升。"}]', 'prepositional phrase'),
('below market rate', '低於市場價格', 'priced or compensated at a level lower than the average market level', '[{"en":"They accepted the deal at below market rate to enter the territory.","zh-TW":"他們以低於市場價格接受了這筆交易以進入該市場。"},{"en":"Offering below market rate risks attracting lower-quality hires.","zh-TW":"提供低於市場的薪資有吸引低品質人才的風險。"}]', 'prepositional phrase'),
('between the lines', '話中有話；言外之意', 'the implied or hidden meaning behind what is written or said', '[{"en":"You need to read between the lines of their proposal.","zh-TW":"你需要看出他們提案的言外之意。"},{"en":"There''s something between the lines — ask them directly.","zh-TW":"話中有話——直接問他們。"}]', 'prepositional phrase'),
('bring under control', '控制住；加以管控', 'to manage or restrain something that was difficult to handle', '[{"en":"Management worked to bring costs under control.","zh-TW":"管理層努力控制住了成本。"},{"en":"Bring the project timeline under control before it derails.","zh-TW":"在專案脫軌之前把時間表控制住。"}]', 'phrasal verb'),
('broker a deal', '促成交易；中介達成協議', 'to negotiate and arrange a deal between parties', '[{"en":"The investment bank brokered a deal between the two firms.","zh-TW":"投資銀行促成了兩家公司之間的交易。"},{"en":"She brokered a deal that satisfied all stakeholders.","zh-TW":"她促成了一筆令所有利益相關者滿意的交易。"}]', 'phrasal verb'),
('build consensus', '建立共識；達成一致意見', 'to develop agreement among multiple people or groups', '[{"en":"Build consensus before announcing the strategic change.","zh-TW":"在宣布策略性變化之前建立共識。"},{"en":"She built consensus through individual conversations.","zh-TW":"她通過個人談話建立了共識。"}]', 'phrasal verb'),
('build momentum', '積累動力；建立勢頭', 'to gradually increase the speed or strength of progress', '[{"en":"Build momentum with quick wins before the big push.","zh-TW":"在大力推進之前通過快速勝利積累動力。"},{"en":"The campaign built momentum through social media.","zh-TW":"這個活動通過社交媒體建立了勢頭。"}]', 'phrasal verb'),
('build rapport', '建立融洽關係；拉近距離', 'to establish a friendly and trusting relationship', '[{"en":"Build rapport with clients before pitching.","zh-TW":"在推介前與客戶建立融洽關係。"},{"en":"She builds rapport quickly by genuinely listening.","zh-TW":"她通過真正傾聽快速拉近距離。"}]', 'phrasal verb'),
('buy time', '爭取時間；拖延（以便準備）', 'to delay something intentionally to gain more time', '[{"en":"We bought time by requesting a contract extension.","zh-TW":"我們通過請求合約延期來爭取時間。"},{"en":"Buying time is only useful if you use it wisely.","zh-TW":"爭取到的時間只有明智使用才有價值。"}]', 'phrasal verb'),
('capture attention', '吸引注意力；抓住眼球', 'to attract and hold someone''s interest or focus', '[{"en":"The new packaging captures attention on retail shelves.","zh-TW":"新包裝在零售貨架上吸引了注意力。"},{"en":"Capture attention in the first five seconds of your pitch.","zh-TW":"在推介的前五秒抓住眼球。"}]', 'phrasal verb'),
('capture market share', '搶佔市場份額', 'to gain a percentage of the total sales in a market', '[{"en":"The new pricing strategy helped capture market share.","zh-TW":"新定價策略有助於搶佔市場份額。"},{"en":"We captured 5% market share in the first year.","zh-TW":"我們在第一年就搶佔了5%的市場份額。"}]', 'phrasal verb'),
('change the narrative', '改變敘事；改變輿論走向', 'to alter the story or perception surrounding a situation', '[{"en":"We need to change the narrative after the PR crisis.","zh-TW":"在公關危機後我們需要改變敘事。"},{"en":"The new strategy changed the narrative from decline to growth.","zh-TW":"新策略將敘事從衰退轉變為增長。"}]', 'expression'),
('circle the wagons', '聚集自衛；抱緊成一團應對危機', 'to gather together to defend against threats', '[{"en":"The company circled the wagons after the media attack.","zh-TW":"媒體攻擊後公司聚集起來進行自衛。"},{"en":"Circle the wagons and focus on your core strengths.","zh-TW":"抱緊成一團應對危機，專注於核心優勢。"}]', 'expression'),
('come in under budget', '預算有結餘；花費低於預算', 'to complete a project while spending less than the allocated budget', '[{"en":"The team came in under budget by 10% this quarter.","zh-TW":"這個季度團隊預算有10%的結餘。"},{"en":"Coming in under budget builds trust with leadership.","zh-TW":"預算有結餘建立了與領導層的信任。"}]', 'expression'),
('competitive bidding', '競爭性投標；公開競標', 'a process where multiple vendors submit bids and the best one wins', '[{"en":"We use competitive bidding for all major contracts.","zh-TW":"我們對所有重大合約使用競爭性投標。"},{"en":"Competitive bidding ensures we get the best value.","zh-TW":"競爭性投標確保我們獲得最佳價值。"}]', 'business idiom'),
('compound interest effect', '複利效應；積累效應', 'the accelerating power of gains that build upon previous gains over time', '[{"en":"Small daily improvements create a compound interest effect.","zh-TW":"每日的小進步會產生積累效應。"},{"en":"The compound interest effect explains why consistent marketing wins.","zh-TW":"複利效應解釋了為什麼持續行銷最終獲勝。"}]', 'business idiom'),
('control the narrative', '掌控敘事；主導輿論', 'to manage how a story or situation is perceived and discussed', '[{"en":"Control the narrative by communicating proactively.","zh-TW":"通過主動溝通掌控敘事。"},{"en":"Brands that control the narrative during crises recover faster.","zh-TW":"在危機中主導輿論的品牌恢復更快。"}]', 'expression'),
('core values alignment', '核心價值觀一致；價值觀契合', 'the match between a person''s or organization''s values and those of a partner', '[{"en":"Core values alignment is essential in long-term partnerships.","zh-TW":"核心價值觀一致在長期合作中至關重要。"},{"en":"We screen candidates for core values alignment.","zh-TW":"我們篩選與核心價值觀契合的候選人。"}]', 'business idiom'),
('cost-benefit analysis', '成本效益分析', 'a systematic comparison of the costs and benefits of a decision or action', '[{"en":"We ran a cost-benefit analysis before approving the investment.","zh-TW":"在批准投資之前我們進行了成本效益分析。"},{"en":"A cost-benefit analysis guides smarter resource allocation.","zh-TW":"成本效益分析指導更智慧的資源分配。"}]', 'business idiom'),
('crisis management', '危機管理', 'the process of handling unexpected negative events to minimize damage', '[{"en":"The team activated their crisis management protocol immediately.","zh-TW":"團隊立即啟動了危機管理協議。"},{"en":"Effective crisis management preserves brand reputation.","zh-TW":"有效的危機管理保護了品牌聲譽。"}]', 'business idiom'),
('cross the finish line', '完成目標；達到終點', 'to complete a goal or project successfully', '[{"en":"We''re almost there — just need to cross the finish line.","zh-TW":"我們幾乎到了——只需完成最後的目標。"},{"en":"Help the team cross the finish line by removing blockers.","zh-TW":"通過移除阻礙幫助團隊達到終點。"}]', 'expression'),
('data-backed decision', '有數據支撐的決策', 'a decision supported by evidence from data analysis', '[{"en":"Every budget allocation should be a data-backed decision.","zh-TW":"每個預算分配都應該是有數據支撐的決策。"},{"en":"Data-backed decisions reduce costly guesswork.","zh-TW":"有數據支撐的決策減少了代價高昂的猜測。"}]', 'business idiom'),
('dead on arrival', '一開始就失敗的；從一開始就沒希望的', 'doomed to fail from the very start', '[{"en":"The proposal was dead on arrival without executive support.","zh-TW":"沒有高層支持，這個提案從一開始就沒有希望。"},{"en":"A product without customer research is often dead on arrival.","zh-TW":"沒有客戶研究的產品往往從一開始就失敗。"}]', 'expression'),
('deliver value', '創造價值；提供價值', 'to provide tangible benefits or results that meet or exceed expectations', '[{"en":"Our mission is to deliver value at every customer touchpoint.","zh-TW":"我們的使命是在每個客戶接觸點創造價值。"},{"en":"Delivering value consistently builds brand loyalty.","zh-TW":"持續提供價值建立了品牌忠誠度。"}]', 'expression'),
('design thinking', '設計思維', 'a human-centered approach to innovation that focuses on empathy and iteration', '[{"en":"We applied design thinking to redesign the customer journey.","zh-TW":"我們應用設計思維重新設計了客戶旅程。"},{"en":"Design thinking leads to more user-friendly solutions.","zh-TW":"設計思維帶來了更易用的解決方案。"}]', 'business idiom'),
('develop a thick skin', '培養抗壓能力；學會不怕批評', 'to become less sensitive to criticism or setbacks', '[{"en":"In sales you need to develop a thick skin for rejections.","zh-TW":"在銷售工作中你需要培養對拒絕的抗壓能力。"},{"en":"Develop a thick skin while still staying open to growth.","zh-TW":"培養抗壓能力的同時保持對成長的開放態度。"}]', 'expression'),
('dial in', '調整到最佳狀態；精確調整', 'to fine-tune or optimize something to the right level', '[{"en":"We need to dial in the pricing before the launch.","zh-TW":"發布前我們需要將定價調整到最佳狀態。"},{"en":"Dial in the messaging to resonate with the target segment.","zh-TW":"精確調整信息以引起目標細分市場的共鳴。"}]', 'phrasal verb'),
('differentiate or die', '差異化或被淘汰', 'the business imperative to stand out from competitors or face failure', '[{"en":"In a crowded market it''s differentiate or die.","zh-TW":"在擁擠的市場中就是差異化或被淘汰。"},{"en":"The brand understood the differentiate or die reality.","zh-TW":"品牌理解了差異化或被淘汰的現實。"}]', 'expression'),
('digital-first', '數位優先', 'prioritizing digital channels and solutions in strategy and operations', '[{"en":"Our digital-first strategy reaches younger consumers effectively.","zh-TW":"我們的數位優先策略有效地接觸了年輕消費者。"},{"en":"Going digital-first reduced our operational costs by 20%.","zh-TW":"採用數位優先使我們的運營成本降低了20%。"}]', 'business idiom'),
('do a 180', '完全改變方向；大逆轉', 'to completely reverse one''s position or approach', '[{"en":"The company did a 180 on its remote work policy.","zh-TW":"公司在遠端工作政策上完全改變了方向。"},{"en":"Doing a 180 too quickly can confuse stakeholders.","zh-TW":"大逆轉太快可能會讓利益相關者感到困惑。"}]', 'expression'),
('dominant market position', '市場主導地位', 'when one company has a very strong hold on a market', '[{"en":"Amazon maintains a dominant market position in e-commerce.","zh-TW":"亞馬遜在電子商務中保持市場主導地位。"},{"en":"A dominant market position provides pricing power.","zh-TW":"市場主導地位提供了定價能力。"}]', 'business idiom'),
('double-edged sword', '雙刃劍；有利有弊', 'something that has both benefits and drawbacks at the same time', '[{"en":"Rapid expansion is a double-edged sword.","zh-TW":"快速擴張是一把雙刃劍。"},{"en":"Transparency can be a double-edged sword in negotiations.","zh-TW":"透明度在談判中可以是一把雙刃劍。"}]', 'expression'),
('drill down into', '深入細節；逐層分析', 'to examine or analyze something at a more detailed level', '[{"en":"Drill down into the sales data by region.","zh-TW":"深入細節按地區分析銷售數據。"},{"en":"We drilled down into the customer complaints to find the root cause.","zh-TW":"我們逐層分析了客戶投訴以找到根本原因。"}]', 'phrasal verb'),
('drop everything', '放下一切；立即處理', 'to stop all other activities to focus on something urgent', '[{"en":"When the server went down everyone dropped everything.","zh-TW":"伺服器崩潰時所有人都放下了一切。"},{"en":"Drop everything and respond to the key client''s request.","zh-TW":"放下一切立即回應重要客戶的請求。"}]', 'expression'),
('drive change', '推動變革；推動改變', 'to be the catalyst for significant organizational or behavioral transformation', '[{"en":"Leadership must drive change from the top.","zh-TW":"領導層必須從頂層推動變革。"},{"en":"Data-driven insights can drive change in marketing strategy.","zh-TW":"數據驅動的洞察可以推動行銷策略的改變。"}]', 'phrasal verb'),
('drive efficiency', '提高效率；推動效率提升', 'to improve the ratio of output to input in operations', '[{"en":"Automation drives efficiency across the supply chain.","zh-TW":"自動化在整個供應鏈中提高了效率。"},{"en":"Drive efficiency by standardizing repetitive processes.","zh-TW":"通過標準化重複流程推動效率提升。"}]', 'phrasal verb'),
('earn trust', '贏得信任', 'to build confidence and credibility through consistent behavior', '[{"en":"We earned trust by delivering on every promise.","zh-TW":"我們通過兌現每一個承諾贏得了信任。"},{"en":"Earning trust takes time but can be lost instantly.","zh-TW":"贏得信任需要時間，但可以在瞬間失去。"}]', 'phrasal verb'),
('elevate performance', '提升表現；提高業績', 'to raise the level of results or output beyond current standards', '[{"en":"Coaching elevates performance across the team.","zh-TW":"輔導提升了整個團隊的表現。"},{"en":"Elevate performance by setting ambitious but realistic targets.","zh-TW":"通過設定雄心勃勃但現實的目標提升業績。"}]', 'phrasal verb'),
('engage stakeholders', '與利益相關者互動；吸引利益相關者參與', 'to involve or communicate with all relevant parties', '[{"en":"Engage stakeholders early to prevent resistance later.","zh-TW":"早期與利益相關者互動以防止後來的阻力。"},{"en":"We engage stakeholders through regular updates and feedback.","zh-TW":"我們通過定期更新和反饋吸引利益相關者參與。"}]', 'phrasal verb'),
('escalate quickly', '迅速升級；快速上報', 'to move an issue to a higher level of authority without delay', '[{"en":"Escalate quickly when a client issue risks the relationship.","zh-TW":"當客戶問題危及關係時迅速上報。"},{"en":"Don''t hesitate to escalate quickly to prevent larger problems.","zh-TW":"不要猶豫，迅速升級以防止更大的問題。"}]', 'phrasal verb'),
('execute flawlessly', '完美執行；無誤落實', 'to carry out a plan with precision and without errors', '[{"en":"The team executed the campaign flawlessly.","zh-TW":"團隊完美地執行了這次活動。"},{"en":"A great strategy counts for nothing if not executed flawlessly.","zh-TW":"如果沒有完美執行，再好的策略也毫無用處。"}]', 'phrasal verb'),
('expand footprint', '擴大業務範圍；擴展版圖', 'to increase the geographic or market presence of a business', '[{"en":"We plan to expand our footprint in Southeast Asia.","zh-TW":"我們計劃在東南亞擴大業務範圍。"},{"en":"Expanding your digital footprint increases brand awareness.","zh-TW":"擴展數位版圖增加了品牌知名度。"}]', 'phrasal verb'),
('experiment with', '嘗試；試驗', 'to try out new methods or ideas to see how they perform', '[{"en":"We experimented with dynamic pricing to optimize revenue.","zh-TW":"我們嘗試了動態定價以優化收益。"},{"en":"Experiment with different formats to find what resonates.","zh-TW":"試驗不同格式以找到什麼能引起共鳴。"}]', 'phrasal verb'),
('face down', '直面；應對；克服', 'to confront and overcome a challenging situation or opponent', '[{"en":"The CEO faced down intense pressure from shareholders.","zh-TW":"執行長直面了股東的強大壓力。"},{"en":"Face down the competition with better innovation.","zh-TW":"以更好的創新應對競爭。"}]', 'phrasal verb'),
('field test', '現場測試；實地驗證', 'to test a product or idea in real-world conditions', '[{"en":"We field tested the app with 200 users before launch.","zh-TW":"發布前我們與200位用戶進行了現場測試。"},{"en":"Field testing reveals issues that lab testing misses.","zh-TW":"現場測試揭示了實驗室測試遺漏的問題。"}]', 'phrasal verb'),
('fine-tune', '微調；精確調整', 'to make small precise adjustments to improve performance', '[{"en":"We fine-tuned the onboarding flow based on user feedback.","zh-TW":"我們根據用戶反饋對入職流程進行了微調。"},{"en":"Fine-tune your pitch for each specific client.","zh-TW":"針對每個具體客戶精確調整你的推介。"}]', 'phrasal verb'),
('focus group', '焦點小組；用戶研究小組', 'a small group of people whose opinions are used to represent a wider market', '[{"en":"We conducted a focus group before the rebrand.","zh-TW":"在品牌重塑之前我們進行了焦點小組研究。"},{"en":"Focus group feedback shaped the product roadmap.","zh-TW":"焦點小組反饋塑造了產品路線圖。"}]', 'business idiom'),
('foothold in', '在…中站穩腳跟；進入的立足點', 'an initial position in a new market or area that allows further development', '[{"en":"Winning that client gave us a foothold in the sector.","zh-TW":"贏得那個客戶讓我們在該行業站穩了腳跟。"},{"en":"Establish a foothold in the Asian market within two years.","zh-TW":"在兩年內在亞洲市場建立立足點。"}]', 'expression'),
('forecast accurately', '準確預測；精確預報', 'to predict future performance with a high degree of precision', '[{"en":"It''s difficult to forecast accurately in a volatile market.","zh-TW":"在波動的市場中很難準確預測。"},{"en":"We use AI to forecast more accurately.","zh-TW":"我們使用AI進行更精確的預測。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('forge ahead', '勇往直前；繼續推進', 'to continue moving forward with determination despite challenges', '[{"en":"We forged ahead with the launch despite supply constraints.","zh-TW":"儘管有供應限制我們仍勇往直前推進了發布。"},{"en":"Forge ahead with innovation even when the path is uncertain.","zh-TW":"即使道路不確定也要繼續推進創新。"}]', 'phrasal verb'),
('foster innovation', '培育創新；促進創新', 'to create conditions that encourage new ideas and approaches', '[{"en":"We foster innovation through cross-functional workshops.","zh-TW":"我們通過跨職能工作坊培育創新。"},{"en":"Foster innovation by tolerating thoughtful failure.","zh-TW":"通過容忍有意義的失敗促進創新。"}]', 'phrasal verb'),
('fuel growth', '推動增長；促進增長', 'to provide the resources or momentum needed for expansion', '[{"en":"The new funding will fuel growth into new markets.","zh-TW":"新的融資將推動進入新市場的增長。"},{"en":"Product innovation continues to fuel growth quarter over quarter.","zh-TW":"產品創新持續推動著季度增長。"}]', 'phrasal verb'),
('gain a foothold', '站穩腳跟；取得立足點', 'to establish a small but stable position in a new market or area', '[{"en":"We gained a foothold in the European market through a local partner.","zh-TW":"我們通過當地合作夥伴在歐洲市場站穩了腳跟。"},{"en":"Gain a foothold early before the market consolidates.","zh-TW":"在市場整合之前儘早取得立足點。"}]', 'phrasal verb'),
('garner support', '獲得支持；爭取支持', 'to collect or attract backing, approval, or endorsement', '[{"en":"The initiative garnered support from all departments.","zh-TW":"這個計劃從所有部門獲得了支持。"},{"en":"Garner support early to avoid obstacles later.","zh-TW":"早期爭取支持以避免後來的障礙。"}]', 'phrasal verb'),
('get sign-off', '獲得批准；取得核可', 'to obtain formal approval from a person in authority', '[{"en":"Get sign-off from legal before sending the contract.","zh-TW":"在發送合約之前獲得法律部門的批准。"},{"en":"She got sign-off from the CFO for the extra budget.","zh-TW":"她從首席財務官那裡取得了額外預算的核可。"}]', 'phrasal verb'),
('give the benefit of the doubt', '給予信任；暫時相信對方', 'to treat someone as honest or capable despite uncertainty', '[{"en":"Give new hires the benefit of the doubt during the first month.","zh-TW":"在第一個月給新員工信任的機會。"},{"en":"Give the client the benefit of the doubt when payment is late.","zh-TW":"當付款延誤時暫時相信客戶。"}]', 'expression'),
('go the distance', '堅持到底；完成全程', 'to see something through to the end despite difficulty', '[{"en":"We will go the distance to ensure client success.","zh-TW":"我們將堅持到底確保客戶成功。"},{"en":"Only those who go the distance earn sustainable success.","zh-TW":"只有堅持到底的人才能獲得可持續的成功。"}]', 'expression'),
('govern by committee', '委員會式管理；集體決策', 'to make decisions through a group rather than individually', '[{"en":"Governing by committee slows down decision-making.","zh-TW":"委員會式管理減慢了決策速度。"},{"en":"Balance governance by committee with empowered individuals.","zh-TW":"在集體決策與授權個人之間取得平衡。"}]', 'expression'),
('grind to a halt', '停擺；陷入停頓', 'to stop completely after slowing down gradually', '[{"en":"The supply disruption brought production to a grind to a halt.","zh-TW":"供應中斷使生產陷入停頓。"},{"en":"Without capital the startup ground to a halt.","zh-TW":"沒有資金這家新創公司完全停擺了。"}]', 'expression'),
('grounded in reality', '立足現實；腳踏實地', 'based on practical facts rather than wishful thinking', '[{"en":"Keep your projections grounded in reality.","zh-TW":"讓你的預測立足現實。"},{"en":"Grounded in reality our forecast is conservative but achievable.","zh-TW":"腳踏實地我們的預測是保守但可實現的。"}]', 'expression'),
('hands on deck', '全員就位；緊急需要人手', 'all available people needed to help', '[{"en":"We need all hands on deck for the data migration.","zh-TW":"數據遷移需要全員就位。"},{"en":"When the system crashed it was all hands on deck.","zh-TW":"系統崩潰時需要緊急全員就位。"}]', 'expression'),
('have a game-changer', '有改變遊戲規則的優勢；有關鍵突破', 'to possess something that significantly changes competitive dynamics', '[{"en":"We have a game-changer with our new AI feature.","zh-TW":"我們擁有改變遊戲規則的新AI功能。"},{"en":"Having a game-changer creates first-mover advantage.","zh-TW":"擁有關鍵突破創造了先發優勢。"}]', 'expression'),
('heavy hitter', '重量級人物；有影響力的人或公司', 'a very important or influential person or organization', '[{"en":"We brought in a heavy hitter from the industry to lead negotiations.","zh-TW":"我們引進了行業重量級人物來主導談判。"},{"en":"Landing a heavy hitter client validates your product.","zh-TW":"拿下有影響力的客戶驗證了你的產品。"}]', 'expression'),
('high-touch service', '高度個性化服務；密集互動服務', 'a service approach that involves frequent, personal interaction', '[{"en":"Enterprise clients expect high-touch service.","zh-TW":"企業客戶期望高度個性化服務。"},{"en":"High-touch service builds loyalty in premium segments.","zh-TW":"密集互動服務在高端細分市場建立了忠誠度。"}]', 'business idiom'),
('hire for attitude train for skill', '招有態度的人再培訓技能', 'the belief that attitude matters more than existing skills in hiring', '[{"en":"Our approach is hire for attitude train for skill.","zh-TW":"我們的方法是招有態度的人再培訓技能。"},{"en":"Hire for attitude train for skill produces more loyal employees.","zh-TW":"招有態度的人再培訓技能產生了更忠誠的員工。"}]', 'expression'),
('hold harmless', '免責；不追究責任', 'to protect someone from legal liability or losses', '[{"en":"The contract includes a hold harmless clause for third-party damages.","zh-TW":"合約中包含了對第三方損害的免責條款。"},{"en":"Hold harmless agreements protect service providers.","zh-TW":"免責協議保護了服務提供者。"}]', 'expression'),
('hold to account', '追究責任；問責', 'to require someone to explain or take responsibility for their actions', '[{"en":"Managers are held to account for team performance.","zh-TW":"經理要對團隊績效負責。"},{"en":"Hold vendors to account when they miss SLA targets.","zh-TW":"當供應商未達到服務水準協議目標時追究其責任。"}]', 'expression'),
('horizon scanning', '前景掃描；未來趨勢探查', 'the systematic review of potential future developments and trends', '[{"en":"Horizon scanning helps us anticipate market shifts.","zh-TW":"前景掃描幫助我們預測市場轉變。"},{"en":"Include horizon scanning in your annual strategic review.","zh-TW":"在年度策略審查中包含前景掃描。"}]', 'business idiom'),
('house in order', '把自己的問題解決好；整頓內部', 'to sort out one''s own affairs or internal problems before addressing others', '[{"en":"Get your house in order before entering new markets.","zh-TW":"在進入新市場之前整頓好內部問題。"},{"en":"The CEO focused on getting the house in order after the merger.","zh-TW":"合併後執行長專注於整頓內部。"}]', 'expression'),
('human capital', '人力資本', 'the skills, knowledge, and experience of employees as an economic resource', '[{"en":"Investing in human capital is investing in the company''s future.","zh-TW":"投資人力資本就是投資公司的未來。"},{"en":"Human capital development is a priority in our HR strategy.","zh-TW":"人力資本發展是我們人力資源策略的優先事項。"}]', 'business idiom'),
('identify gaps', '識別差距；找出缺口', 'to find missing areas or weaknesses in a plan, process, or market', '[{"en":"We identified gaps in the current product offering.","zh-TW":"我們識別了當前產品組合中的差距。"},{"en":"Identify gaps in your team''s capabilities through assessment.","zh-TW":"通過評估找出團隊能力中的缺口。"}]', 'phrasal verb'),
('impact-driven', '以影響力為導向；注重影響力', 'focused on creating measurable positive outcomes', '[{"en":"Our impact-driven culture attracts mission-aligned talent.","zh-TW":"我們以影響力為導向的文化吸引了有使命感的人才。"},{"en":"Investors value impact-driven businesses in today''s market.","zh-TW":"今天的市場中投資者重視注重影響力的業務。"}]', 'business idiom'),
('impossible ask', '不合理的要求；過分的請求', 'a request or demand that cannot reasonably be fulfilled', '[{"en":"Delivering in 24 hours is an impossible ask without more staff.","zh-TW":"在沒有更多員工的情況下24小時內交付是不合理的要求。"},{"en":"Explain why a request is an impossible ask rather than just refusing.","zh-TW":"解釋為什麼一個請求是不合理的而不是簡單拒絕。"}]', 'expression'),
('in a vacuum', '孤立地；脫離背景地', 'without considering the surrounding context or related factors', '[{"en":"No business decision exists in a vacuum.","zh-TW":"沒有商業決策是孤立存在的。"},{"en":"Don''t evaluate this in a vacuum — consider the broader market.","zh-TW":"不要脫離背景評估這個——考慮更廣泛的市場。"}]', 'prepositional phrase'),
('in every sense of the word', '從各種意義上說；完全地', 'completely and in all respects', '[{"en":"She is a leader in every sense of the word.","zh-TW":"從各種意義上說她是一位領導者。"},{"en":"This was a successful launch in every sense of the word.","zh-TW":"從各種意義上說這是一次成功的發布。"}]', 'prepositional phrase'),
('in flux', '處於變動中；不穩定', 'in a state of continuous change or uncertainty', '[{"en":"The regulatory landscape is in flux.","zh-TW":"監管環境正處於變動中。"},{"en":"Our strategy is in flux as we respond to new market data.","zh-TW":"我們的策略因應新市場數據而不穩定。"}]', 'prepositional phrase'),
('in good standing', '信譽良好；帳戶正常', 'meeting all requirements or obligations and in a satisfactory position', '[{"en":"All vendors must be in good standing to bid.","zh-TW":"所有供應商必須信譽良好才能投標。"},{"en":"We ensure our accounts are in good standing with regulators.","zh-TW":"我們確保我們的帳戶與監管機構保持正常狀態。"}]', 'prepositional phrase'),
('in lock-step', '步調一致；完全協調地', 'moving or progressing in complete agreement or simultaneously', '[{"en":"The two departments moved in lock-step on the launch.","zh-TW":"兩個部門在發布上步調一致。"},{"en":"Stay in lock-step with your partners to avoid misalignment.","zh-TW":"與合作夥伴保持步調一致以避免不一致。"}]', 'prepositional phrase'),
('in real time', '即時地；實時地', 'happening immediately as events unfold', '[{"en":"We monitor customer feedback in real time.","zh-TW":"我們即時監控客戶反饋。"},{"en":"In real time adjustments are possible with our dashboards.","zh-TW":"使用我們的儀表板可以進行實時調整。"}]', 'prepositional phrase'),
('in short order', '迅速地；短時間內', 'quickly and without delay', '[{"en":"The team resolved the issue in short order.","zh-TW":"團隊迅速解決了這個問題。"},{"en":"Deliver a prototype in short order to show momentum.","zh-TW":"在短時間內交付原型以展示勢頭。"}]', 'prepositional phrase'),
('in the best interest of', '符合…的最大利益', 'for the benefit or advantage of a particular person or group', '[{"en":"All decisions are made in the best interest of our clients.","zh-TW":"所有決策都符合我們客戶的最大利益。"},{"en":"Act in the best interest of all stakeholders.","zh-TW":"以所有利益相關者的最大利益行事。"}]', 'prepositional phrase'),
('in the same vein', '以同樣的方式；沿著同樣的思路', 'in the same style or following the same idea as before', '[{"en":"In the same vein we should cut costs in operations too.","zh-TW":"以同樣的方式，我們也應該削減運營成本。"},{"en":"In the same vein the marketing team needs to streamline.","zh-TW":"沿著同樣的思路行銷團隊也需要精簡。"}]', 'prepositional phrase'),
('in the wings', '待命中；即將登場', 'waiting in readiness to step in when needed', '[{"en":"We have a new product line waiting in the wings.","zh-TW":"我們有一條新產品線即將登場。"},{"en":"Keep a successor candidate in the wings for key roles.","zh-TW":"為關鍵職位準備待命的繼任候選人。"}]', 'prepositional phrase'),
('income statement', '損益表', 'a financial statement showing revenues, costs, and profits over a period', '[{"en":"The income statement showed a 15% increase in net profit.","zh-TW":"損益表顯示淨利潤增長了15%。"},{"en":"Analyze the income statement before the investor meeting.","zh-TW":"在投資者會議前分析損益表。"}]', 'business idiom'),
('incremental improvement', '漸進式改進；逐步提升', 'making small continuous improvements rather than large leaps', '[{"en":"Incremental improvement compounds over time into significant gains.","zh-TW":"漸進式改進隨時間積累成顯著的收益。"},{"en":"Focus on incremental improvement when radical change is too risky.","zh-TW":"當激進變革風險太高時專注於漸進式改進。"}]', 'business idiom'),
('industry benchmark', '行業基準；行業標準', 'a standard or reference point used to compare performance in an industry', '[{"en":"Our NPS score exceeds the industry benchmark by 20 points.","zh-TW":"我們的NPS分數超過行業基準20分。"},{"en":"Set targets using industry benchmarks as a reference.","zh-TW":"以行業基準作為參考設定目標。"}]', 'business idiom'),
('industry disruptor', '行業顛覆者', 'a company or product that fundamentally changes how an industry operates', '[{"en":"The startup emerged as an industry disruptor in logistics.","zh-TW":"這家新創公司在物流業崛起為行業顛覆者。"},{"en":"Industry disruptors create new market categories.","zh-TW":"行業顛覆者創造了新的市場類別。"}]', 'business idiom'),
('information asymmetry', '資訊不對稱', 'when one party in a transaction has more or better information than the other', '[{"en":"Information asymmetry often gives negotiators an advantage.","zh-TW":"資訊不對稱往往給談判者帶來優勢。"},{"en":"Transparency reduces information asymmetry in markets.","zh-TW":"透明度降低了市場中的資訊不對稱。"}]', 'business idiom'),
('innovation pipeline', '創新管道；待開發的創新項目', 'a structured set of ideas or projects being developed for future use', '[{"en":"A healthy innovation pipeline ensures long-term growth.","zh-TW":"健康的創新管道確保了長期增長。"},{"en":"Our innovation pipeline includes 12 new products.","zh-TW":"我們的創新管道包含12個新產品。"}]', 'business idiom'),
('input from stakeholders', '利益相關者的意見；各方投入', 'feedback or contributions from relevant parties involved in a process', '[{"en":"We gathered input from stakeholders before finalizing the plan.","zh-TW":"在最終確定計劃之前我們收集了利益相關者的意見。"},{"en":"Input from stakeholders improves the quality of decisions.","zh-TW":"利益相關者的意見提高了決策品質。"}]', 'expression'),
('intrapreneur', '內部創業家；公司內的創業者', 'an employee who develops new ventures or ideas within an organization', '[{"en":"We encourage intrapreneurs to test ideas within the company.","zh-TW":"我們鼓勵員工作為內部創業家在公司內測試想法。"},{"en":"Intrapreneurs drive organic innovation inside large firms.","zh-TW":"內部創業家在大公司內部推動有機創新。"}]', 'business idiom'),
('keep a pulse on', '了解最新動態；密切關注', 'to stay continuously aware of what is happening in a situation', '[{"en":"Leaders should keep a pulse on team morale regularly.","zh-TW":"領導者應該定期了解團隊士氣的最新動態。"},{"en":"Keep a pulse on industry trends to stay ahead.","zh-TW":"密切關注行業趨勢以保持領先。"}]', 'expression'),
('key account management', '重點客戶管理', 'a strategy focused on developing long-term relationships with the most valuable clients', '[{"en":"Key account management requires dedicated relationship managers.","zh-TW":"重點客戶管理需要專職的關係經理。"},{"en":"Our key account management program reduced churn by 30%.","zh-TW":"我們的重點客戶管理計劃將流失率降低了30%。"}]', 'business idiom'),
('key performance indicator', '關鍵績效指標', 'a measurable value that shows how effectively a company is achieving key objectives', '[{"en":"Define clear key performance indicators for each department.","zh-TW":"為每個部門定義清晰的關鍵績效指標。"},{"en":"Tie compensation to key performance indicators.","zh-TW":"將薪酬與關鍵績效指標掛鉤。"}]', 'business idiom'),
('kill it', '表現出色；大殺四方', 'to perform extremely well or achieve great success', '[{"en":"The new sales rep is killing it in the northeast region.","zh-TW":"新銷售代表在東北地區表現出色。"},{"en":"We killed it at the trade show with the new demo.","zh-TW":"我們在貿易展覽上用新演示大殺四方。"}]', 'expression'),
('know your numbers', '了解你的數字；熟悉財務數據', 'to be fully aware of one''s financial metrics and performance data', '[{"en":"Know your numbers before meeting with investors.","zh-TW":"在與投資者見面之前了解你的數字。"},{"en":"Every business leader should know their numbers cold.","zh-TW":"每個商業領導者都應該對財務數據瞭如指掌。"}]', 'expression'),
('knowledge transfer', '知識傳遞；技術交接', 'the process of sharing skills, information, and expertise between people', '[{"en":"Knowledge transfer during handover prevents costly errors.","zh-TW":"交接期間的知識傳遞防止了代價高昂的錯誤。"},{"en":"Invest in knowledge transfer when key employees leave.","zh-TW":"當關鍵員工離職時投資於知識傳遞。"}]', 'business idiom'),
('launch pad', '起點；跳板；發射台', 'a platform or starting point for launching a new initiative', '[{"en":"This partnership serves as a launch pad into Asia.","zh-TW":"這次合作是進入亞洲的跳板。"},{"en":"The pilot program is a launch pad for full deployment.","zh-TW":"試點計劃是全面部署的起點。"}]', 'business idiom'),
('lead magnet', '潛在客戶吸引工具；引流工具', 'a free offer used to attract potential customers and capture their contact information', '[{"en":"The free report acts as a lead magnet for our webinars.","zh-TW":"免費報告作為我們網絡研討會的引流工具。"},{"en":"A strong lead magnet accelerates top-of-funnel growth.","zh-TW":"有力的引流工具加速了漏斗頂端的增長。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('leave money on the table', '讓錢白白流失；錯失獲利機會', 'to fail to take advantage of all the value available in a deal or situation', '[{"en":"By not upselling we''re leaving money on the table.","zh-TW":"不進行向上銷售，我們讓錢白白流失。"},{"en":"Optimize your pricing to avoid leaving money on the table.","zh-TW":"優化你的定價以避免錯失獲利機會。"}]', 'expression'),
('let the data speak', '讓數據說話；以數據為決策依據', 'to allow evidence and analysis to drive conclusions without bias', '[{"en":"Rather than opinions let the data speak in this review.","zh-TW":"在這次審查中讓數據說話而不是意見。"},{"en":"Let the data speak and you''ll make more confident decisions.","zh-TW":"讓數據說話你會做出更有自信的決策。"}]', 'expression'),
('leverage technology', '善用科技；運用技術優勢', 'to use technological tools to gain efficiency or advantage', '[{"en":"We leverage technology to reduce manual processes.","zh-TW":"我們善用科技來減少手動流程。"},{"en":"Leverage technology to deliver a personalized customer experience.","zh-TW":"運用技術優勢提供個性化的客戶體驗。"}]', 'phrasal verb'),
('lock in prices', '鎖定價格；固定價格', 'to secure a price or rate before it changes', '[{"en":"We locked in prices with our supplier for two years.","zh-TW":"我們與供應商鎖定了兩年的價格。"},{"en":"Lock in prices now before the market rises further.","zh-TW":"趁市場進一步上漲之前鎖定價格。"}]', 'phrasal verb'),
('long-term vision', '長遠願景', 'a clear picture of where an organization aims to be in the distant future', '[{"en":"The CEO shared a long-term vision at the annual meeting.","zh-TW":"執行長在年度會議上分享了長遠願景。"},{"en":"A long-term vision guides daily decision-making.","zh-TW":"長遠願景指導日常決策。"}]', 'business idiom'),
('loss leader', '虧本招徠商品；引流商品', 'a product sold at a loss to attract customers who then buy other profitable items', '[{"en":"The printer was sold as a loss leader to generate ink revenue.","zh-TW":"打印機作為虧本招徠商品銷售以產生墨水收入。"},{"en":"A loss leader strategy works when customer lifetime value is high.","zh-TW":"當客戶終身價值高時虧本招徠策略有效。"}]', 'business idiom'),
('lower the barrier', '降低門檻；減少障礙', 'to make it easier for people to access something or get started', '[{"en":"We lower the barrier to entry with a free trial.","zh-TW":"我們通過免費試用降低了入門門檻。"},{"en":"Lower the barrier for referrals to grow your user base.","zh-TW":"降低推薦門檻以擴大用戶群。"}]', 'expression'),
('make a dent', '取得一定進展；造成明顯影響', 'to make meaningful progress in reducing or solving something large', '[{"en":"This strategy will make a dent in our backlog.","zh-TW":"這個策略將在我們的積壓工作上取得一定進展。"},{"en":"We are starting to make a dent in the market.","zh-TW":"我們開始在市場上造成明顯影響了。"}]', 'expression'),
('make an impact', '產生影響；帶來改變', 'to have a noticeable and significant effect on something', '[{"en":"She made an impact from her very first week.","zh-TW":"她從第一週就產生了影響。"},{"en":"Invest in initiatives that will make an impact at scale.","zh-TW":"投資於能夠帶來大規模影響的計劃。"}]', 'expression'),
('make good on', '兌現；履行（承諾）', 'to fulfill a promise or commitment', '[{"en":"We made good on our promise to cut response times.","zh-TW":"我們兌現了縮短響應時間的承諾。"},{"en":"Make good on your commitments to build stakeholder trust.","zh-TW":"履行你的承諾以建立利益相關者的信任。"}]', 'expression'),
('manage expectations', '管理期望；調整預期', 'to ensure all parties have a realistic understanding of what can be delivered', '[{"en":"Set clear timelines to manage client expectations.","zh-TW":"設定明確的時間表來管理客戶期望。"},{"en":"Managing expectations prevents disappointment and builds trust.","zh-TW":"管理期望防止了失望並建立了信任。"}]', 'expression'),
('market correction', '市場修正；市場調整', 'a temporary decline in asset prices after an excessive rise', '[{"en":"The company prepared for a market correction by building reserves.","zh-TW":"公司通過建立儲備為市場修正做好了準備。"},{"en":"A market correction is healthy for long-term stability.","zh-TW":"市場修正對長期穩定是有益的。"}]', 'business idiom'),
('market dynamics', '市場動態；市場力量', 'the forces and factors that affect supply, demand, and pricing in a market', '[{"en":"Market dynamics shifted rapidly with the new regulations.","zh-TW":"市場動態隨著新規定迅速改變了。"},{"en":"Understanding market dynamics helps you anticipate opportunities.","zh-TW":"了解市場動態幫助你預測機會。"}]', 'business idiom'),
('market penetration', '市場滲透；市場占有', 'the extent to which a product is known and used in a market', '[{"en":"Our goal is to double market penetration within two years.","zh-TW":"我們的目標是在兩年內將市場滲透率翻倍。"},{"en":"Market penetration strategy requires aggressive pricing and promotion.","zh-TW":"市場滲透策略需要積極的定價和促銷。"}]', 'business idiom'),
('market saturation', '市場飽和', 'the point at which most potential customers in a market already use a product', '[{"en":"Market saturation forced the brand to innovate.","zh-TW":"市場飽和迫使品牌進行創新。"},{"en":"Diversify when facing market saturation in your core segment.","zh-TW":"面對核心細分市場的飽和時進行多元化。"}]', 'business idiom'),
('market share grab', '搶奪市場份額；爭取市場份額', 'an aggressive strategy to rapidly capture a larger portion of the market', '[{"en":"The pricing campaign was a market share grab.","zh-TW":"定價活動是一次搶奪市場份額的行動。"},{"en":"A market share grab requires significant upfront investment.","zh-TW":"爭取市場份額需要大量前期投資。"}]', 'expression'),
('meaningful metrics', '有意義的指標；重要的衡量標準', 'measurements that provide genuine insight into performance', '[{"en":"Focus on meaningful metrics not just vanity numbers.","zh-TW":"專注於有意義的指標而不只是虛榮數字。"},{"en":"Meaningful metrics guide strategic decisions effectively.","zh-TW":"有意義的指標有效地指導策略決策。"}]', 'expression'),
('milestone-based payment', '里程碑付款；分階段付款', 'a payment structure tied to the completion of specific project milestones', '[{"en":"We use a milestone-based payment structure for long projects.","zh-TW":"對長期專案我們使用里程碑付款結構。"},{"en":"Milestone-based payment reduces financial risk for both parties.","zh-TW":"里程碑付款降低了雙方的財務風險。"}]', 'business idiom'),
('minimize friction', '減少摩擦；降低阻力', 'to remove obstacles or inefficiencies from a process or interaction', '[{"en":"Minimize friction in the checkout process to increase conversions.","zh-TW":"減少結帳流程中的摩擦以增加轉換率。"},{"en":"Minimize friction between teams through clear communication norms.","zh-TW":"通過清晰的溝通規範降低團隊間的阻力。"}]', 'phrasal verb'),
('mission-critical', '任務關鍵性的；至關重要的', 'essential for the success of an operation or organization', '[{"en":"Prioritize mission-critical systems in the upgrade plan.","zh-TW":"在升級計劃中優先考慮至關重要的系統。"},{"en":"Mission-critical tasks should never be deprioritized.","zh-TW":"任務關鍵性的工作永遠不應該降低優先級。"}]', 'business idiom'),
('mobilize resources', '動員資源；調配資源', 'to organize and prepare resources for action', '[{"en":"We mobilized resources across four countries for the launch.","zh-TW":"我們動員了四個國家的資源進行發布。"},{"en":"Mobilize resources quickly when a strategic opportunity arises.","zh-TW":"當戰略機會出現時迅速調配資源。"}]', 'phrasal verb'),
('model behavior', '樹立榜樣；以身作則', 'to demonstrate the behaviors you want others to follow', '[{"en":"Leaders must model behavior that reflects company values.","zh-TW":"領導者必須樹立反映公司價值觀的榜樣。"},{"en":"Model behavior around accountability and transparency.","zh-TW":"在問責制和透明度方面以身作則。"}]', 'expression'),
('multistakeholder approach', '多方利益相關者方法', 'a strategy that involves and balances the interests of multiple parties', '[{"en":"A multistakeholder approach ensures all voices are heard.","zh-TW":"多方利益相關者方法確保所有聲音都被聽到。"},{"en":"ESG initiatives require a multistakeholder approach.","zh-TW":"ESG倡議需要多方利益相關者方法。"}]', 'business idiom'),
('mutual benefit', '互惠互利；共同受益', 'an arrangement that advantages all parties involved', '[{"en":"The partnership was designed for mutual benefit.","zh-TW":"這次合作是為了互惠互利而設計的。"},{"en":"Mutual benefit is the foundation of lasting business relationships.","zh-TW":"互惠互利是持久商業關係的基礎。"}]', 'expression'),
('navigate ambiguity', '應對模糊性；在不確定中前行', 'to make effective decisions when the situation is unclear or uncertain', '[{"en":"Strong leaders navigate ambiguity without losing confidence.","zh-TW":"強大的領導者在不確定中前行而不失去信心。"},{"en":"The ability to navigate ambiguity is crucial in fast-moving markets.","zh-TW":"應對模糊性的能力在快速變化的市場中至關重要。"}]', 'phrasal verb'),
('net promoter score', '淨推薦值', 'a metric measuring customer loyalty by how likely they are to recommend a company', '[{"en":"Our net promoter score increased 15 points after the redesign.","zh-TW":"重新設計後我們的淨推薦值增加了15分。"},{"en":"Net promoter score is a leading indicator of customer retention.","zh-TW":"淨推薦值是客戶留存率的領先指標。"}]', 'business idiom'),
('new normal', '新常態', 'a previously uncommon situation that has become standard practice', '[{"en":"Remote work has become the new normal for many industries.","zh-TW":"遠端工作已成為許多行業的新常態。"},{"en":"Adapt your strategy to thrive in the new normal.","zh-TW":"調整你的策略在新常態中蓬勃發展。"}]', 'business idiom'),
('not cut out for', '不適合；沒有能力做', 'to not have the right abilities or temperament for something', '[{"en":"He realized he was not cut out for sales and moved to operations.","zh-TW":"他意識到自己不適合銷售，轉去了運營部門。"},{"en":"Not everyone is cut out for the pressure of leadership.","zh-TW":"不是每個人都有能力承受領導層的壓力。"}]', 'expression'),
('object strenuously', '強烈反對；力排眾議', 'to oppose something strongly and with urgency', '[{"en":"Several directors objected strenuously to the cost reduction plan.","zh-TW":"幾位董事強烈反對成本削減計劃。"},{"en":"Object strenuously when a decision will harm the team.","zh-TW":"當一個決定會傷害團隊時強烈反對。"}]', 'phrasal verb'),
('on a roll', '連續成功；勢頭強勁', 'experiencing a series of successes or positive momentum', '[{"en":"The team is on a roll after three consecutive record quarters.","zh-TW":"在連續三個破紀錄的季度後團隊勢頭強勁。"},{"en":"We''re on a roll — keep up the momentum.","zh-TW":"我們連續成功——保持這個勢頭。"}]', 'expression'),
('on board with', '同意；支持；加入', 'in agreement with and supporting a plan or decision', '[{"en":"We need all managers on board with the new policy.","zh-TW":"我們需要所有經理同意這個新政策。"},{"en":"Once leadership is on board with the vision execution accelerates.","zh-TW":"一旦領導層支持這個願景，執行就會加速。"}]', 'expression'),
('on your radar', '在你的關注範圍內；被你注意到', 'something you are aware of and monitoring', '[{"en":"Keep emerging technologies on your radar.","zh-TW":"把新興技術保持在你的關注範圍內。"},{"en":"Is the regulatory change on your radar for planning?","zh-TW":"監管變化是否在你的規劃關注範圍內？"}]', 'expression'),
('operational excellence', '卓越運營；業務卓越', 'a commitment to improving processes and performance continuously', '[{"en":"Operational excellence differentiates us from competitors.","zh-TW":"卓越運營使我們與競爭對手有所區別。"},{"en":"We invest in operational excellence through training and systems.","zh-TW":"我們通過培訓和系統投資於業務卓越。"}]', 'business idiom'),
('opportunity cost', '機會成本', 'the value of the best alternative forgone when making a decision', '[{"en":"The opportunity cost of delaying the launch is significant.","zh-TW":"延遲發布的機會成本是顯著的。"},{"en":"Consider the opportunity cost before saying no to a project.","zh-TW":"在拒絕一個專案之前考慮機會成本。"}]', 'business idiom'),
('organic traffic', '有機流量；自然流量', 'visitors who arrive at a website through unpaid search results', '[{"en":"SEO investment doubled our organic traffic.","zh-TW":"SEO投資使我們的有機流量翻倍了。"},{"en":"Organic traffic reduces long-term customer acquisition cost.","zh-TW":"自然流量降低了長期客戶獲取成本。"}]', 'business idiom'),
('out of commission', '停用中；停止運作', 'not working or not available for use', '[{"en":"The server was out of commission for three hours.","zh-TW":"伺服器停止運作了三小時。"},{"en":"Three team members are out of commission due to illness.","zh-TW":"三位團隊成員因病停工中。"}]', 'prepositional phrase'),
('overdeliver on', '超越承諾；超出預期交付', 'to provide more than what was promised or expected', '[{"en":"We aim to overdeliver on every client commitment.","zh-TW":"我們致力於在每個客戶承諾上超越預期交付。"},{"en":"Overdelivering on quality builds long-term loyalty.","zh-TW":"在品質上超出預期建立了長期忠誠度。"}]', 'phrasal verb'),
('pace of change', '變革的步調；變化速度', 'the speed at which change is happening in an industry or organization', '[{"en":"The pace of change in technology is unprecedented.","zh-TW":"技術變革的步調是前所未有的。"},{"en":"Companies that match the pace of change thrive.","zh-TW":"能夠跟上變化速度的公司才能蓬勃發展。"}]', 'expression'),
('participate in', '參與；參加', 'to take part in an activity, discussion, or process', '[{"en":"All team leaders must participate in the strategy workshop.","zh-TW":"所有團隊領導者必須參加策略研討會。"},{"en":"We participate in industry forums to stay connected.","zh-TW":"我們參加行業論壇以保持聯繫。"}]', 'phrasal verb'),
('path of least resistance', '阻力最小的路；容易做的選擇', 'the easiest course of action, often at the expense of long-term results', '[{"en":"Don''t take the path of least resistance in strategy.","zh-TW":"在策略上不要選擇阻力最小的路。"},{"en":"The team took the path of least resistance and chose familiar tools.","zh-TW":"團隊選擇了容易做的選擇，使用了熟悉的工具。"}]', 'expression'),
('performance gap', '績效差距', 'the difference between current performance and desired performance', '[{"en":"We identified a performance gap in the sales team.","zh-TW":"我們識別了銷售團隊的績效差距。"},{"en":"Close the performance gap through targeted coaching.","zh-TW":"通過針對性的輔導縮小績效差距。"}]', 'business idiom'),
('performance review', '績效評估；績效考核', 'a formal evaluation of an employee''s work and achievements', '[{"en":"Annual performance reviews help identify development needs.","zh-TW":"年度績效評估有助於識別發展需求。"},{"en":"Tie promotions to objective performance review criteria.","zh-TW":"將晉升與客觀的績效考核標準掛鉤。"}]', 'business idiom'),
('pilot program', '試點計劃；試行方案', 'a small-scale test or trial run of a larger program', '[{"en":"We ran a pilot program in three cities before the national launch.","zh-TW":"全國推出前我們在三個城市進行了試點計劃。"},{"en":"A pilot program reduces risk of large-scale failure.","zh-TW":"試點計劃降低了大規模失敗的風險。"}]', 'business idiom'),
('play the long game', '下長遠棋；著眼長期', 'to focus on long-term outcomes rather than short-term gains', '[{"en":"We play the long game by investing in customer relationships.","zh-TW":"我們通過投資客戶關係下長遠棋。"},{"en":"Playing the long game builds sustainable competitive advantage.","zh-TW":"著眼長期建立了可持續的競爭優勢。"}]', 'expression'),
('point of no return', '回不了頭的那一步；不歸點', 'the stage at which a decision or action can no longer be reversed', '[{"en":"Signing the contract is the point of no return.","zh-TW":"簽署合約是回不了頭的那一步。"},{"en":"We assessed risks before reaching the point of no return.","zh-TW":"我們在到達不歸點之前評估了風險。"}]', 'expression'),
('post-mortem analysis', '事後分析；項目覆盤', 'a review conducted after a project to assess what worked and what didn''t', '[{"en":"The post-mortem analysis revealed key lessons from the launch.","zh-TW":"事後分析揭示了發布的關鍵教訓。"},{"en":"Schedule a post-mortem within two weeks of project completion.","zh-TW":"在專案完成後兩週內安排項目覆盤。"}]', 'business idiom'),
('product-market fit', '產品市場契合度', 'the degree to which a product satisfies strong market demand', '[{"en":"The startup struggled to find product-market fit.","zh-TW":"新創公司努力尋求產品市場契合度。"},{"en":"Once you have product-market fit scale aggressively.","zh-TW":"一旦你達到產品市場契合度就積極擴大規模。"}]', 'business idiom'),
('profit center', '利潤中心', 'a department or unit that generates its own revenue and profits', '[{"en":"We transformed the consulting arm into a profit center.","zh-TW":"我們將諮詢部門轉變為利潤中心。"},{"en":"Each region operates as an independent profit center.","zh-TW":"每個地區作為獨立的利潤中心運作。"}]', 'business idiom'),
('proactively address', '主動解決；積極應對', 'to deal with something before it becomes a larger problem', '[{"en":"Proactively address compliance risks before the audit.","zh-TW":"在審計之前主動解決合規風險。"},{"en":"She proactively addressed the team''s concerns in a meeting.","zh-TW":"她在會議中積極應對了團隊的擔憂。"}]', 'phrasal verb'),
('pull levers', '採取措施；使用可用手段', 'to use available tools or mechanisms to achieve a desired result', '[{"en":"We pulled multiple levers to boost Q4 revenue.","zh-TW":"我們採取了多項措施來提升第四季收入。"},{"en":"Identify which levers to pull for the fastest impact.","zh-TW":"識別哪些手段能產生最快的影響。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('push toward profitability', '推進盈利；朝盈利方向努力', 'to take actions that move a business closer to generating profit', '[{"en":"The board urged management to push toward profitability.","zh-TW":"董事會敦促管理層推進盈利。"},{"en":"Every initiative should push us toward profitability.","zh-TW":"每個計劃都應該讓我們朝盈利方向努力。"}]', 'phrasal verb'),
('put into practice', '付諸實踐；實際運用', 'to actually use or apply knowledge, a plan, or an idea', '[{"en":"The challenge is putting strategy into practice.","zh-TW":"挑戰在於將策略付諸實踐。"},{"en":"Put the training insights into practice from day one.","zh-TW":"從第一天開始將培訓洞察實際運用。"}]', 'expression'),
('rally the troops', '鼓舞士氣；激勵團隊', 'to inspire and motivate a group of people to take action', '[{"en":"The manager rallied the troops before the product launch.","zh-TW":"經理在產品發布前鼓舞了團隊士氣。"},{"en":"Rally the troops with a clear vision and concrete action plan.","zh-TW":"用清晰的願景和具體的行動計劃激勵團隊。"}]', 'expression'),
('reach a consensus', '達成共識；取得一致意見', 'to achieve general agreement among all members of a group', '[{"en":"The committee reached a consensus after three hours of debate.","zh-TW":"委員會在三小時的辯論後達成了共識。"},{"en":"Reach a consensus on priorities before starting the project.","zh-TW":"在開始專案前對優先事項取得一致意見。"}]', 'expression'),
('retain talent', '留住人才；保留優秀員工', 'to keep valuable employees from leaving the organization', '[{"en":"We invest in culture to retain talent long-term.","zh-TW":"我們投資於文化以長期留住人才。"},{"en":"Retaining talent is cheaper than replacing it.","zh-TW":"留住人才比替換人才的成本更低。"}]', 'phrasal verb'),
('revenue recognition', '收入認列；收入確認', 'the accounting principle of when and how revenue is recorded', '[{"en":"Revenue recognition rules affected our quarterly reporting.","zh-TW":"收入認列規則影響了我們的季度報告。"},{"en":"Understand revenue recognition before structuring multi-year deals.","zh-TW":"在制定多年交易結構之前了解收入確認規則。"}]', 'business idiom'),
('reverse engineer', '逆向工程；反推分析', 'to analyze how something works by working backward from the result', '[{"en":"We reverse engineered the competitor''s pricing model.","zh-TW":"我們對競爭對手的定價模型進行了反推分析。"},{"en":"Reverse engineer your desired outcome to build your plan.","zh-TW":"從你期望的結果反推來建立你的計劃。"}]', 'phrasal verb'),
('right person right role', '人崗匹配；適才適所', 'placing individuals in positions that match their skills and strengths', '[{"en":"The right person in the right role maximizes team output.","zh-TW":"人崗匹配使團隊產出最大化。"},{"en":"Evaluate roles annually to ensure right person right role.","zh-TW":"每年評估職位以確保適才適所。"}]', 'expression'),
('risk tolerance', '風險承受度；風險承受能力', 'the degree of variability in outcomes an entity is willing to accept', '[{"en":"Define your risk tolerance before entering volatile markets.","zh-TW":"在進入波動市場前確定你的風險承受度。"},{"en":"Risk tolerance varies across business units.","zh-TW":"各業務部門的風險承受能力各不相同。"}]', 'business idiom'),
('road test', '試行；實際測試', 'to test something in real-world conditions before full deployment', '[{"en":"We road tested the new interface with 50 users.","zh-TW":"我們與50位用戶試行了新界面。"},{"en":"Road test your message with a small audience first.","zh-TW":"先與小部分受眾實際測試你的信息。"}]', 'phrasal verb'),
('roll out across', '在…全面推出；跨範圍部署', 'to deploy or implement something across all locations or units', '[{"en":"The new ERP will roll out across all regions in Q2.","zh-TW":"新ERP將在第二季在所有地區全面推出。"},{"en":"Roll out the training across all levels simultaneously.","zh-TW":"在所有層級同時跨範圍部署培訓。"}]', 'phrasal verb'),
('safe to fail', '容許失敗；可以安全失敗', 'an environment where trying new things and failing is acceptable and encouraged', '[{"en":"We create a safe to fail environment for innovation.","zh-TW":"我們為創新建立容許失敗的環境。"},{"en":"A safe to fail culture enables faster learning.","zh-TW":"容許失敗的文化使學習更快。"}]', 'expression'),
('saturate the market', '佔領市場；充斥市場', 'to supply a market so fully that there is no room for growth', '[{"en":"We saturated the market with advertising before the launch.","zh-TW":"發布前我們用廣告佔領了市場。"},{"en":"Once you saturate the market focus on adjacent opportunities.","zh-TW":"一旦充斥市場就專注於相鄰的機會。"}]', 'phrasal verb'),
('sell the dream', '販賣夢想；推銷願景', 'to market a product or service based on an aspirational vision', '[{"en":"Early-stage startups must sell the dream to attract investors.","zh-TW":"早期新創公司必須向投資者販賣夢想。"},{"en":"Sell the dream but deliver on the fundamentals.","zh-TW":"販賣夢想但要落實基本功。"}]', 'expression'),
('serial entrepreneur', '連續創業者', 'a person who repeatedly starts new businesses after selling or completing previous ones', '[{"en":"As a serial entrepreneur she has launched five companies.","zh-TW":"作為連續創業者她已經創辦了五家公司。"},{"en":"Serial entrepreneurs apply lessons from each venture to the next.","zh-TW":"連續創業者將每次創業的教訓應用到下一次。"}]', 'business idiom'),
('shareholder value', '股東價值', 'the value delivered to equity owners of a corporation', '[{"en":"Every major decision must be evaluated for its impact on shareholder value.","zh-TW":"每個重大決策都必須評估其對股東價值的影響。"},{"en":"Long-term shareholder value comes from sustainable operations.","zh-TW":"長期股東價值來自可持續的運營。"}]', 'business idiom'),
('short-term pain for long-term gain', '短期陣痛換取長期收益', 'accepting current difficulties to achieve better results in the future', '[{"en":"Cost cuts now are short-term pain for long-term gain.","zh-TW":"現在的成本削減是短期陣痛換取長期收益。"},{"en":"Investing in new technology is short-term pain for long-term gain.","zh-TW":"投資新技術是短期陣痛換取長期收益。"}]', 'expression'),
('situational awareness', '情境意識；掌握局勢', 'the ability to understand and respond to one''s current environment effectively', '[{"en":"Situational awareness helps leaders make timely decisions.","zh-TW":"情境意識幫助領導者做出及時的決策。"},{"en":"Develop situational awareness by listening to frontline feedback.","zh-TW":"通過傾聽一線反饋培養情境意識。"}]', 'business idiom'),
('slash costs', '大幅削減成本', 'to reduce costs dramatically and quickly', '[{"en":"The company slashed costs by 30% through automation.","zh-TW":"公司通過自動化大幅削減了30%的成本。"},{"en":"Slashing costs too aggressively can harm quality.","zh-TW":"過於激進地大幅削減成本可能損害品質。"}]', 'phrasal verb'),
('social proof', '社交證明；口碑效應', 'evidence that others are using and endorsing a product or service', '[{"en":"Customer testimonials serve as social proof.","zh-TW":"客戶見證充當社交證明。"},{"en":"Social proof reduces purchase hesitation among new customers.","zh-TW":"社交證明減少了新客戶的購買猶豫。"}]', 'business idiom'),
('soft skills', '軟技能；人際技能', 'interpersonal and communication abilities as opposed to technical skills', '[{"en":"Soft skills like empathy are crucial for effective leadership.","zh-TW":"同理心等軟技能對有效領導至關重要。"},{"en":"We train both hard and soft skills across all levels.","zh-TW":"我們在各層級同時培訓硬技能和軟技能。"}]', 'business idiom'),
('sole proprietor', '獨資經營者；個人業主', 'an individual who owns and operates a business alone with full liability', '[{"en":"She started as a sole proprietor before registering a company.","zh-TW":"她在登記公司之前以獨資方式開始業務。"},{"en":"A sole proprietor takes on all business risks personally.","zh-TW":"獨資經營者個人承擔所有業務風險。"}]', 'business idiom'),
('speculate on', '推測；猜測；投機於', 'to form opinions without full evidence; to invest in high-risk assets', '[{"en":"Don''t speculate on results before the data is in.","zh-TW":"在數據出來之前不要推測結果。"},{"en":"Avoid speculating on commodities without expertise.","zh-TW":"沒有專業知識不要投機於商品市場。"}]', 'phrasal verb'),
('stakeholder map', '利益相關者地圖', 'a diagram showing all stakeholders and their relationships to a project', '[{"en":"A stakeholder map helps prioritize communication efforts.","zh-TW":"利益相關者地圖幫助優先安排溝通工作。"},{"en":"Build a stakeholder map before starting any major initiative.","zh-TW":"在開始任何重大計劃之前建立利益相關者地圖。"}]', 'business idiom'),
('strategic partnership', '戰略合作關係；策略聯盟', 'a formal alliance between organizations for mutual strategic benefit', '[{"en":"We formed a strategic partnership to enter the Asian market.","zh-TW":"我們建立了戰略合作關係以進入亞洲市場。"},{"en":"A strategic partnership accelerates growth beyond organic means.","zh-TW":"戰略合作關係使增長超越了有機手段。"}]', 'business idiom'),
('subject matter expert', '主題專家；領域專家', 'a person with deep knowledge or expertise in a particular area', '[{"en":"We brought in a subject matter expert on GDPR compliance.","zh-TW":"我們引進了GDPR合規方面的主題專家。"},{"en":"Subject matter experts reduce costly errors in specialized work.","zh-TW":"領域專家減少了專業工作中代價高昂的錯誤。"}]', 'business idiom'),
('succession planning', '繼任計劃；接班規劃', 'preparing and identifying future leaders to fill key positions', '[{"en":"Succession planning ensures business continuity.","zh-TW":"繼任計劃確保了業務連續性。"},{"en":"Start succession planning early to avoid talent gaps.","zh-TW":"提早開始接班規劃以避免人才缺口。"}]', 'business idiom'),
('supply chain resilience', '供應鏈韌性；供應鏈抗風險能力', 'the ability of a supply chain to recover quickly from disruptions', '[{"en":"Diversifying suppliers improves supply chain resilience.","zh-TW":"多樣化供應商提高了供應鏈韌性。"},{"en":"Supply chain resilience became a boardroom priority after the pandemic.","zh-TW":"疫情後供應鏈抗風險能力成為了董事會的優先事項。"}]', 'business idiom'),
('surge in demand', '需求激增；需求驟升', 'a sudden and sharp increase in demand for a product or service', '[{"en":"A surge in demand during the holidays strained our inventory.","zh-TW":"假日期間需求激增使我們的庫存緊張。"},{"en":"We scaled up production to meet the surge in demand.","zh-TW":"我們擴大了生產以滿足需求驟升。"}]', 'expression'),
('swing for the fences', '放手一搏；雄心勃勃', 'to aim for the highest possible outcome, accepting greater risk', '[{"en":"We swung for the fences with a bold new market entry.","zh-TW":"我們以大膽的新市場進入放手一搏。"},{"en":"Sometimes you need to swing for the fences to win big.","zh-TW":"有時你需要放手一搏才能大獲全勝。"}]', 'expression'),
('synergy between', '兩者之間的協同效應', 'mutual benefit or enhanced effectiveness that comes from two things working together', '[{"en":"There is strong synergy between our sales and marketing teams.","zh-TW":"我們的銷售和行銷團隊之間有強大的協同效應。"},{"en":"The merger created synergy between complementary product lines.","zh-TW":"合併在互補的產品線之間創造了協同效應。"}]', 'prepositional phrase'),
('talent acquisition', '人才招募；人才獲取', 'the process of finding and hiring skilled employees', '[{"en":"Talent acquisition is a key investment for our expansion.","zh-TW":"人才招募是我們擴張的關鍵投資。"},{"en":"A strong employer brand supports talent acquisition.","zh-TW":"強大的雇主品牌支持人才招募。"}]', 'business idiom'),
('talent pipeline', '人才儲備；人才管道', 'a pool of qualified candidates prepared to fill future vacancies', '[{"en":"Building a talent pipeline prevents urgent hiring mistakes.","zh-TW":"建立人才儲備防止緊急招聘的錯誤。"},{"en":"Internship programs feed directly into our talent pipeline.","zh-TW":"實習計劃直接補充我們的人才管道。"}]', 'business idiom'),
('total addressable market', '總可服務市場；市場總規模', 'the total revenue opportunity available if a company achieves 100% market share', '[{"en":"The total addressable market for our product is 50 billion dollars.","zh-TW":"我們產品的總可服務市場為500億美元。"},{"en":"Define the total addressable market before seeking funding.","zh-TW":"在尋求融資之前定義總可服務市場。"}]', 'business idiom'),
('track record', '過往記錄；業績記錄', 'a record of past achievements or failures used to judge future performance', '[{"en":"Our track record of successful launches builds client confidence.","zh-TW":"我們成功發布的過往記錄建立了客戶信心。"},{"en":"Investors look at the team''s track record before funding.","zh-TW":"投資者在融資前查看團隊的業績記錄。"}]', 'business idiom'),
('transition period', '過渡期；交接期', 'the time during which change is occurring from one state to another', '[{"en":"Communicate clearly during the transition period.","zh-TW":"在過渡期間清晰溝通。"},{"en":"The transition period requires extra support for affected teams.","zh-TW":"交接期需要對受影響的團隊提供額外支持。"}]', 'business idiom'),
('transparent communication', '透明溝通', 'open and honest sharing of information with relevant parties', '[{"en":"Transparent communication builds trust with stakeholders.","zh-TW":"透明溝通建立了與利益相關者的信任。"},{"en":"We practice transparent communication at all levels.","zh-TW":"我們在各層級實踐透明溝通。"}]', 'business idiom'),
('turnover rate', '人員流動率；離職率', 'the rate at which employees leave and are replaced in an organization', '[{"en":"A high turnover rate is costly and disrupts culture.","zh-TW":"高離職率代價高昂且破壞文化。"},{"en":"We reduced turnover rate by 40% with flexible work policies.","zh-TW":"我們通過彈性工作政策將離職率降低了40%。"}]', 'business idiom'),
('two-track approach', '雙軌策略；兩路並進', 'pursuing two different strategies or channels simultaneously', '[{"en":"We used a two-track approach — organic growth and acquisitions.","zh-TW":"我們採用了雙軌策略——有機增長和收購並進。"},{"en":"A two-track approach reduces risk by diversifying efforts.","zh-TW":"兩路並進通過多元化努力降低了風險。"}]', 'business idiom'),
('underperforming asset', '表現不佳的資產；低效資產', 'an asset that is not generating returns in line with expectations', '[{"en":"We divested underperforming assets to free up capital.","zh-TW":"我們剝離了低效資產以釋放資金。"},{"en":"Identify underperforming assets and decide to fix or exit.","zh-TW":"識別表現不佳的資產並決定修復還是退出。"}]', 'business idiom'),
('up and running', '正常運作；啟動運行', 'functioning and operating as expected', '[{"en":"We had the new CRM up and running within a week.","zh-TW":"我們在一週內讓新CRM系統正常運作了。"},{"en":"Get the team up and running before the launch window closes.","zh-TW":"在發布窗口關閉之前讓團隊啟動運行。"}]', 'expression'),
('upmarket', '高端市場；高檔的', 'targeting wealthier or more sophisticated customers or products', '[{"en":"We repositioned the brand upmarket to improve margins.","zh-TW":"我們將品牌重新定位到高端市場以提高利潤率。"},{"en":"Moving upmarket requires investment in quality and service.","zh-TW":"進入高端市場需要在品質和服務上的投資。"}]', 'business idiom'),
('upside potential', '上升空間；增長潛力', 'the potential for value, revenue, or performance to increase further', '[{"en":"The upside potential of this market is enormous.","zh-TW":"這個市場的上升空間是巨大的。"},{"en":"We invested because the upside potential outweighed the risk.","zh-TW":"我們投資是因為增長潛力超過了風險。"}]', 'business idiom'),
('validate assumptions', '驗證假設', 'to test whether your beliefs or predictions about a situation are correct', '[{"en":"Validate assumptions with real user data before scaling.","zh-TW":"在擴大規模之前用真實用戶數據驗證假設。"},{"en":"We validated our assumptions with a small focus group.","zh-TW":"我們用小型焦點小組驗證了我們的假設。"}]', 'phrasal verb'),
('value chain', '價值鏈', 'the series of activities through which a company creates value for its customers', '[{"en":"We optimize every step in the value chain to reduce costs.","zh-TW":"我們優化價值鏈中的每一個步驟以降低成本。"},{"en":"Understanding the value chain reveals opportunities for improvement.","zh-TW":"了解價值鏈揭示了改進的機會。"}]', 'business idiom'),
('verify accuracy', '核實準確性；確認精確度', 'to confirm that information or data is correct and precise', '[{"en":"Always verify the accuracy of financial data before reporting.","zh-TW":"報告前務必核實財務數據的準確性。"},{"en":"Verify accuracy by cross-checking multiple sources.","zh-TW":"通過交叉核查多個來源確認精確度。"}]', 'phrasal verb'),
('vertical market', '垂直市場；特定行業市場', 'a market focusing on a specific industry or group of customers with similar needs', '[{"en":"We focus on the healthcare vertical market for deeper expertise.","zh-TW":"我們專注於醫療保健垂直市場以積累更深的專業知識。"},{"en":"Vertical market specialization improves sales conversion rates.","zh-TW":"垂直市場專業化提高了銷售轉換率。"}]', 'business idiom'),
('visibility into', '對…的可見度；對…的了解', 'the ability to see or understand what is happening in a process or area', '[{"en":"We need better visibility into our supply chain costs.","zh-TW":"我們需要對供應鏈成本有更好的可見度。"},{"en":"Real-time dashboards provide visibility into key metrics.","zh-TW":"即時儀表板提供了對關鍵指標的了解。"}]', 'expression'),
('walk the talk', '言行一致；知行合一', 'to actually do the things you say or promise, not just talk about them', '[{"en":"Leaders must walk the talk on work-life balance.","zh-TW":"領導者必須在工作與生活平衡上言行一致。"},{"en":"Walk the talk to earn respect from your team.","zh-TW":"知行合一以從團隊中贏得尊重。"}]', 'expression'),
('watch your back', '小心謹慎；提防他人', 'to be careful and protect yourself from potential threats', '[{"en":"In highly competitive markets you need to watch your back.","zh-TW":"在競爭激烈的市場中你需要小心謹慎。"},{"en":"Watch your back when entering a new territory alone.","zh-TW":"單獨進入新市場時要提防他人。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('waterfall methodology', '瀑布式開發方法', 'a sequential project management approach where each phase must complete before the next begins', '[{"en":"We use waterfall methodology for compliance-heavy projects.","zh-TW":"我們對合規要求高的專案使用瀑布式開發方法。"},{"en":"Waterfall methodology works well when requirements are stable.","zh-TW":"當需求穩定時瀑布式開發方法效果良好。"}]', 'business idiom'),
('weigh the pros and cons', '權衡利弊；評估優缺點', 'to carefully consider the advantages and disadvantages of a decision', '[{"en":"Weigh the pros and cons before committing to the vendor.","zh-TW":"在確定供應商之前權衡利弊。"},{"en":"We weighed the pros and cons of each market entry strategy.","zh-TW":"我們評估了每種市場進入策略的優缺點。"}]', 'expression'),
('what''s in it for me', '我能得到什麼；對我有什麼好處', 'the question of personal or organizational benefit from an action', '[{"en":"Always answer the what''s in it for me question for your client.","zh-TW":"始終為你的客戶回答我能得到什麼的問題。"},{"en":"People adopt change when they understand what''s in it for them.","zh-TW":"當人們了解對他們有什麼好處時他們才會接受改變。"}]', 'expression'),
('white glove service', '白手套服務；最高端的個性化服務', 'an exceptionally high level of personalized, attentive service', '[{"en":"We offer white glove service to our top 10 clients.","zh-TW":"我們向前10名客戶提供白手套服務。"},{"en":"White glove service commands a significant price premium.","zh-TW":"最高端的個性化服務可以定顯著的溢價。"}]', 'expression'),
('win at all costs', '不惜一切代價贏得；不擇手段', 'to be determined to succeed regardless of the means or consequences', '[{"en":"A win at all costs approach often damages long-term relationships.","zh-TW":"不惜一切代價的做法往往損害了長期關係。"},{"en":"Avoid win at all costs thinking in partnerships.","zh-TW":"在合作關係中避免不擇手段的想法。"}]', 'expression'),
('win the argument', '贏得爭論；說服對方', 'to successfully persuade others that your position is correct', '[{"en":"Win the argument with data not just opinions.","zh-TW":"用數據而不只是意見贏得爭論。"},{"en":"She won the argument by presenting a clear cost-benefit analysis.","zh-TW":"她通過提出清晰的成本效益分析說服了對方。"}]', 'expression'),
('word of mouth', '口口相傳；口碑', 'the passing of information or recommendations by spoken communication', '[{"en":"Most of our early growth came from word of mouth.","zh-TW":"我們早期的大部分增長來自口口相傳。"},{"en":"Word of mouth remains the most trusted form of marketing.","zh-TW":"口碑仍然是最受信任的行銷形式。"}]', 'business idiom'),
('work backward from', '從…倒推；從目標倒推計劃', 'to plan by starting from the desired end result and working toward the present', '[{"en":"Work backward from the launch date to set milestones.","zh-TW":"從發布日期倒推以設定里程碑。"},{"en":"She worked backward from the target revenue to build the plan.","zh-TW":"她從目標收入倒推建立了計劃。"}]', 'phrasal verb'),
('working capital', '運營資金；流動資金', 'the funds available for day-to-day business operations', '[{"en":"Proper working capital management ensures smooth operations.","zh-TW":"適當的運營資金管理確保了業務順暢。"},{"en":"A working capital shortage can stall growth.","zh-TW":"流動資金短缺可能會停滯增長。"}]', 'business idiom'),
('write the book on', '在某方面是頂級專家', 'to be the definitive expert on a particular subject', '[{"en":"She practically wrote the book on enterprise sales strategy.","zh-TW":"她在企業銷售策略上幾乎是頂級專家。"},{"en":"They write the book on efficient supply chain management.","zh-TW":"他們在高效供應鏈管理方面是頂級專家。"}]', 'expression'),
('zero-based budgeting', '零基預算', 'a budgeting method where all expenses must be justified from scratch each period', '[{"en":"We adopted zero-based budgeting to eliminate unnecessary spend.","zh-TW":"我們採用了零基預算以消除不必要的支出。"},{"en":"Zero-based budgeting forces discipline in resource allocation.","zh-TW":"零基預算強制了資源分配的紀律。"}]', 'business idiom'),
('act as a catalyst', '起催化劑作用；促進發展', 'to trigger or accelerate a process or change', '[{"en":"The new CEO acted as a catalyst for cultural transformation.","zh-TW":"新任執行長作為文化轉型的催化劑。"},{"en":"Technology acts as a catalyst for business model innovation.","zh-TW":"技術作為商業模式創新的催化劑。"}]', 'expression'),
('adapt or die', '適應或被淘汰', 'the necessity to evolve with changing conditions or face failure', '[{"en":"In today''s digital market it''s adapt or die.","zh-TW":"在今天的數位市場中就是適應或被淘汰。"},{"en":"Brands that fail to adapt or die end up irrelevant.","zh-TW":"不能適應的品牌最終會被淘汰。"}]', 'expression'),
('advocate loudly', '大聲倡導；積極推動', 'to actively and strongly promote a cause or idea', '[{"en":"She advocates loudly for diversity and inclusion.","zh-TW":"她積極推動多樣性和包容性。"},{"en":"Advocate loudly for resources your team needs.","zh-TW":"大聲倡導你的團隊所需的資源。"}]', 'phrasal verb'),
('at a watershed moment', '在關鍵轉折點；在歷史性時刻', 'at a turning point that marks a significant change', '[{"en":"The industry is at a watershed moment with AI adoption.","zh-TW":"行業在人工智慧採用方面處於關鍵轉折點。"},{"en":"We are at a watershed moment — act decisively.","zh-TW":"我們處於歷史性時刻——果斷行動。"}]', 'prepositional phrase'),
('attract investment', '吸引投資', 'to draw in financial backing from investors', '[{"en":"Strong metrics attract investment from venture capital.","zh-TW":"強勁的指標吸引了風險投資。"},{"en":"Attract investment by clearly articulating your value proposition.","zh-TW":"通過清晰表達價值主張來吸引投資。"}]', 'phrasal verb'),
('back-end', '後端；背後的部分', 'the behind-the-scenes systems or processes that support a product or service', '[{"en":"We improved the back-end processes to speed up delivery.","zh-TW":"我們改善了後端流程以加快交付速度。"},{"en":"Back-end improvements often have the biggest ROI.","zh-TW":"後端改進往往具有最大的投資回報率。"}]', 'business idiom'),
('balance risk and reward', '平衡風險與回報', 'to weigh potential gains against potential losses in a decision', '[{"en":"Good investors balance risk and reward carefully.","zh-TW":"優秀的投資者仔細平衡風險與回報。"},{"en":"Balance risk and reward when entering new markets.","zh-TW":"進入新市場時平衡風險與回報。"}]', 'expression'),
('be a game-changer', '是一個改變遊戲規則的事物', 'to significantly alter how something is done or perceived', '[{"en":"This new feature will be a game-changer for our users.","zh-TW":"這個新功能將是我們用戶的改變遊戲規則者。"},{"en":"Automation has been a game-changer for our logistics.","zh-TW":"自動化改變了我們物流的遊戲規則。"}]', 'expression'),
('be ahead of the pack', '領先群雄；走在前端', 'to be more advanced than competitors or peers', '[{"en":"Our early investment keeps us ahead of the pack.","zh-TW":"我們的早期投資使我們領先群雄。"},{"en":"Being ahead of the pack requires constant innovation.","zh-TW":"走在前端需要不斷的創新。"}]', 'expression'),
('be at a premium', '供不應求；有溢價', 'scarce and therefore available only at a higher price or value', '[{"en":"Office space in the city center is at a premium.","zh-TW":"市中心的辦公空間供不應求。"},{"en":"Skilled engineers are at a premium in the tech industry.","zh-TW":"在科技行業中熟練工程師供不應求。"}]', 'expression'),
('be at a standstill', '陷入停頓；僵持不前', 'completely stopped with no progress being made', '[{"en":"Negotiations are at a standstill over the pricing terms.","zh-TW":"因為定價條款談判陷入了僵持。"},{"en":"The project is at a standstill due to funding issues.","zh-TW":"由於資金問題專案陷入了停頓。"}]', 'expression'),
('be going places', '前途無量；會有大成就', 'to be on a path toward success or advancement', '[{"en":"With her skill set she''s definitely going places.","zh-TW":"憑藉她的技能她肯定前途無量。"},{"en":"High performers who are going places stay motivated.","zh-TW":"前途無量的高績效員工保持積極性。"}]', 'expression'),
('be in the black', '盈利；收支有盈餘', 'generating profit; having positive financial results', '[{"en":"After two years we''re finally in the black.","zh-TW":"兩年後我們終於開始盈利了。"},{"en":"Being in the black allows us to reinvest in growth.","zh-TW":"盈利使我們能夠再投資於增長。"}]', 'expression'),
('benchmark study', '基準研究；對標研究', 'research that compares performance metrics across similar organizations', '[{"en":"The benchmark study showed we lead on customer satisfaction.","zh-TW":"對標研究顯示我們在客戶滿意度方面領先。"},{"en":"Commission a benchmark study before setting performance targets.","zh-TW":"在設定績效目標之前委託進行對標研究。"}]', 'business idiom'),
('best-in-class', '同類最佳；業界標竿', 'the best example or standard of its kind in the market', '[{"en":"We aim to deliver best-in-class customer experience.","zh-TW":"我們致力於提供同類最佳的客戶體驗。"},{"en":"Benchmark against best-in-class performers in your sector.","zh-TW":"對比你行業中的業界標竿進行對標。"}]', 'business idiom'),
('bolt-on acquisition', '附加收購；補充性收購', 'a small acquisition that adds capability to an existing business without major integration', '[{"en":"A bolt-on acquisition added AI capability to our platform.","zh-TW":"一次附加收購為我們的平台添加了AI能力。"},{"en":"Bolt-on acquisitions are less risky than full mergers.","zh-TW":"附加收購比全面合併風險更低。"}]', 'business idiom'),
('bottom-up approach', '自下而上的方法', 'a planning process that starts with input from frontline staff or individual units', '[{"en":"A bottom-up approach to budgeting improves accuracy.","zh-TW":"自下而上的預算方法提高了準確性。"},{"en":"The bottom-up approach empowers teams and builds ownership.","zh-TW":"自下而上的方法賦能團隊並建立歸屬感。"}]', 'business idiom'),
('brand equity', '品牌資產；品牌價值', 'the commercial value derived from a brand''s name and reputation', '[{"en":"Consistent messaging builds brand equity over time.","zh-TW":"一致的信息隨著時間建立了品牌資產。"},{"en":"High brand equity allows premium pricing.","zh-TW":"高品牌資產使溢價定價成為可能。"}]', 'business idiom'),
('break the mold', '打破常規；突破固有模式', 'to do something in a completely new and different way', '[{"en":"The startup broke the mold with a subscription-free model.","zh-TW":"新創公司以無訂閱模式打破了常規。"},{"en":"Breaking the mold attracts attention but requires courage.","zh-TW":"打破固有模式吸引眼球但需要勇氣。"}]', 'expression'),
('budget envelope', '預算範圍；預算額度', 'the maximum amount of money allocated for a specific purpose', '[{"en":"We must deliver the project within the budget envelope.","zh-TW":"我們必須在預算範圍內交付這個專案。"},{"en":"Define the budget envelope before scoping the work.","zh-TW":"在規劃工作範圍之前確定預算額度。"}]', 'business idiom'),
('build a track record', '積累業績記錄；建立信譽', 'to establish a history of successful performance over time', '[{"en":"Build a track record with smaller clients before targeting enterprises.","zh-TW":"在瞄準企業客戶之前先與小型客戶積累業績記錄。"},{"en":"Building a track record takes time but is invaluable.","zh-TW":"積累業績記錄需要時間但是無價的。"}]', 'expression'),
('bundle services', '捆綁銷售服務；打包提供服務', 'to offer multiple services together as a single package', '[{"en":"We bundle services to increase average deal size.","zh-TW":"我們捆綁銷售服務以增加平均交易額。"},{"en":"Bundling services can improve customer retention.","zh-TW":"打包提供服務可以提高客戶留存率。"}]', 'phrasal verb'),
('business case', '商業案例；可行性論述', 'a justified recommendation or justification for a particular business decision', '[{"en":"Build a solid business case before requesting budget.","zh-TW":"在申請預算之前建立紮實的商業案例。"},{"en":"The business case for automation was overwhelming.","zh-TW":"自動化的商業案例十分充分。"}]', 'business idiom'),
('call out', '點名批評；提出（問題）', 'to specifically identify or criticize someone or something', '[{"en":"She called out the bottleneck in the process during the review.","zh-TW":"她在審查中點名指出了流程中的瓶頸。"},{"en":"Call out issues early rather than letting them fester.","zh-TW":"盡早提出問題而不是讓它們惡化。"}]', 'phrasal verb'),
('capacity constraint', '產能限制；資源瓶頸', 'a limitation in the ability to produce or service due to available resources', '[{"en":"We hit a capacity constraint during the peak season.","zh-TW":"旺季期間我們遭遇了產能限制。"},{"en":"Outsourcing resolved our capacity constraint overnight.","zh-TW":"外包在一夜之間解決了我們的資源瓶頸。"}]', 'business idiom'),
('capture value', '獲取價值；實現價值', 'to convert created value into revenue or profit', '[{"en":"Creating value is important but capturing value is essential.","zh-TW":"創造價值很重要但獲取價值至關重要。"},{"en":"Capture value from your intellectual property through licensing.","zh-TW":"通過許可實現知識產權的價值。"}]', 'phrasal verb'),
('cash burn rate', '現金消耗率；燒錢速度', 'the rate at which a company spends its cash reserves before generating profit', '[{"en":"Our cash burn rate gives us 18 months of runway.","zh-TW":"我們的現金消耗率給了我們18個月的資金跑道。"},{"en":"Reduce cash burn rate during slow growth periods.","zh-TW":"在增長緩慢期間降低燒錢速度。"}]', 'business idiom'),
('catch up on', '補上；補救；跟上', 'to do something that you missed or to update on something', '[{"en":"I need to catch up on the emails from last week.","zh-TW":"我需要補上上週的電子郵件。"},{"en":"Let''s catch up on the project status after the holiday.","zh-TW":"假期後讓我們跟上專案的最新狀態。"}]', 'phrasal verb'),
('center of excellence', '卓越中心；專業能力中心', 'a team or entity that provides leadership and best practices in a specific area', '[{"en":"We established a center of excellence for data analytics.","zh-TW":"我們建立了數據分析的卓越中心。"},{"en":"Centers of excellence share best practices across the organization.","zh-TW":"卓越中心在整個組織中分享最佳實踐。"}]', 'business idiom'),
('channel strategy', '渠道策略', 'the plan for how a company distributes its products or services to customers', '[{"en":"Our channel strategy combines direct sales and resellers.","zh-TW":"我們的渠道策略結合了直接銷售和分銷商。"},{"en":"Revisit your channel strategy as the market evolves.","zh-TW":"隨著市場演變重新審視你的渠道策略。"}]', 'business idiom'),
('chief concern', '主要關切；首要問題', 'the most important worry or priority at a given time', '[{"en":"Customer retention is our chief concern this quarter.","zh-TW":"客戶留存率是我們本季的首要問題。"},{"en":"What is the chief concern for investors right now?","zh-TW":"現在投資者的主要關切是什麼？"}]', 'expression'),
('choke point', '瓶頸點；阻塞點', 'a critical point where congestion or limitation severely restricts flow', '[{"en":"The inspection process is a choke point in our supply chain.","zh-TW":"檢驗流程是我們供應鏈中的瓶頸點。"},{"en":"Eliminate choke points to improve overall throughput.","zh-TW":"消除阻塞點以提高整體吞吐量。"}]', 'business idiom'),
('cold call', '冷電話；主動推銷電話', 'an unsolicited phone call or visit to a potential customer', '[{"en":"Cold calling is challenging but still effective in B2B.","zh-TW":"冷電話很有挑戰性但在B2B中仍然有效。"},{"en":"We train the team on how to make effective cold calls.","zh-TW":"我們培訓團隊如何進行有效的冷電話。"}]', 'business idiom'),
('collective responsibility', '集體責任；共同擔當', 'the shared accountability of a group for outcomes or actions', '[{"en":"Collective responsibility ensures no one blames others.","zh-TW":"集體責任確保沒有人互相推卸責任。"},{"en":"Build a culture of collective responsibility for results.","zh-TW":"建立對成果共同擔當的文化。"}]', 'expression'),
('competitive moat', '競爭護城河；持久競爭優勢', 'a durable competitive advantage that protects a company''s market position', '[{"en":"Network effects create a powerful competitive moat.","zh-TW":"網絡效應創造了強大的競爭護城河。"},{"en":"Investing in brand loyalty builds a competitive moat.","zh-TW":"投資於品牌忠誠度建立了競爭護城河。"}]', 'business idiom'),
('compound growth', '複合增長；複利式增長', 'growth that accelerates over time by building on previous gains', '[{"en":"We achieved 25% compound growth over five years.","zh-TW":"我們在五年內實現了25%的複合增長。"},{"en":"Compound growth turns small investments into significant assets.","zh-TW":"複利式增長將小投資轉變為重要資產。"}]', 'business idiom'),
('confidence interval', '信賴區間；信心範圍', 'a statistical range that indicates the reliability of an estimate', '[{"en":"The forecast has a 95% confidence interval.","zh-TW":"預測具有95%的信賴區間。"},{"en":"Understanding confidence intervals prevents overconfidence in projections.","zh-TW":"了解信賴區間防止了對預測過度自信。"}]', 'business idiom'),
('consensus-driven', '共識驅動的；基於一致意見的', 'relying on agreement from all parties before making decisions', '[{"en":"Consensus-driven decision-making is thorough but slow.","zh-TW":"基於共識的決策非常徹底但很慢。"},{"en":"A consensus-driven culture reduces conflict but requires trust.","zh-TW":"共識驅動的文化減少了衝突但需要信任。"}]', 'business idiom'),
('contextualize data', '解讀數據背景；在背景下理解數據', 'to present data in a way that considers its surrounding circumstances', '[{"en":"Contextualize the sales data within the industry downturn.","zh-TW":"在行業下滑的背景下解讀銷售數據。"},{"en":"Always contextualize data to prevent misleading conclusions.","zh-TW":"始終在背景下理解數據以防止誤導性結論。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('contingency fund', '應急基金；備用資金', 'a financial reserve set aside to cover unexpected costs or emergencies', '[{"en":"We keep a 10% contingency fund for every project.","zh-TW":"我們為每個專案保留10%的應急基金。"},{"en":"A contingency fund protects operations during cash flow gaps.","zh-TW":"應急基金在現金流缺口期間保護了業務。"}]', 'business idiom'),
('core message', '核心信息；中心訊息', 'the most important point you want your audience to take away', '[{"en":"Align all materials around the core message.","zh-TW":"讓所有材料圍繞核心信息。"},{"en":"The core message should be simple and memorable.","zh-TW":"核心信息應該簡單易記。"}]', 'expression'),
('creative tension', '創意張力；建設性衝突', 'productive conflict between differing ideas that sparks innovation', '[{"en":"Creative tension between design and engineering improves products.","zh-TW":"設計與工程之間的創意張力改善了產品。"},{"en":"Encourage creative tension as a tool for innovation.","zh-TW":"鼓勵建設性衝突作為創新工具。"}]', 'expression'),
('critical thinking', '批判性思維；批判性思考', 'the ability to analyze facts objectively to reach a reasoned conclusion', '[{"en":"Critical thinking prevents costly decision-making errors.","zh-TW":"批判性思維防止了代價高昂的決策錯誤。"},{"en":"Develop critical thinking skills through scenario training.","zh-TW":"通過情境培訓發展批判性思考技能。"}]', 'business idiom'),
('cross-border', '跨境的；跨國的', 'involving or happening across national borders', '[{"en":"Cross-border transactions require careful tax planning.","zh-TW":"跨境交易需要仔細的稅務規劃。"},{"en":"Our cross-border operations span 12 countries.","zh-TW":"我們的跨國業務跨越12個國家。"}]', 'business idiom'),
('culture fit', '文化契合度', 'the alignment between an individual''s values and behaviors and those of an organization', '[{"en":"We assess culture fit as carefully as technical skills.","zh-TW":"我們對文化契合度的評估與技術技能同樣仔細。"},{"en":"Poor culture fit is the leading cause of early employee turnover.","zh-TW":"文化契合度差是早期員工流動的主要原因。"}]', 'business idiom'),
('customer journey', '客戶旅程', 'the complete experience a customer has from first awareness to post-purchase', '[{"en":"Map the customer journey to identify friction points.","zh-TW":"繪製客戶旅程以識別摩擦點。"},{"en":"Optimize each stage of the customer journey for better retention.","zh-TW":"優化客戶旅程的每個階段以提高留存率。"}]', 'business idiom'),
('customer obsession', '以客戶為執念；極致關注客戶', 'an extreme focus on understanding and serving the customer''s needs', '[{"en":"Amazon''s customer obsession drives its competitive advantage.","zh-TW":"亞馬遜對客戶的執念推動了其競爭優勢。"},{"en":"Customer obsession means listening first and building second.","zh-TW":"以客戶為執念意味著先傾聽再建設。"}]', 'business idiom'),
('cut-throat competition', '激烈競爭；白熱化競爭', 'extremely intense and ruthless competition in a market', '[{"en":"The retail sector is known for cut-throat competition.","zh-TW":"零售行業以激烈競爭著稱。"},{"en":"In cut-throat competition differentiation is the only defense.","zh-TW":"在白熱化競爭中差異化是唯一的防禦。"}]', 'expression'),
('day-to-day basis', '日常地；以天為單位', 'happening or considered on a daily routine basis', '[{"en":"He manages the team on a day-to-day basis.","zh-TW":"他日常管理這個團隊。"},{"en":"Track KPIs on a day-to-day basis for early detection.","zh-TW":"以日常方式追蹤KPI以便早期發現問題。"}]', 'prepositional phrase'),
('deadline pressure', '截止日期壓力；時限壓力', 'the stress and urgency created by having to complete work by a set date', '[{"en":"The team performs well even under deadline pressure.","zh-TW":"團隊即使在截止日期壓力下也表現良好。"},{"en":"Deadline pressure can drive focus but also cause burnout.","zh-TW":"截止日期壓力可以驅動專注但也可能導致倦怠。"}]', 'expression'),
('deal flow', '交易流量；投資機會流入', 'the rate at which investment proposals or business deals are received', '[{"en":"Strong networking improves deal flow for the investment team.","zh-TW":"強大的人脈改善了投資團隊的交易流量。"},{"en":"High deal flow allows for selectivity in choosing partners.","zh-TW":"高交易流量使選擇合作夥伴時更具選擇性。"}]', 'business idiom'),
('decision framework', '決策框架', 'a structured approach for making consistent, objective decisions', '[{"en":"Use a decision framework to evaluate strategic options objectively.","zh-TW":"使用決策框架客觀評估策略選項。"},{"en":"A shared decision framework reduces bias.","zh-TW":"共享的決策框架減少了偏見。"}]', 'business idiom'),
('dedicated team', '專屬團隊；專職團隊', 'a group assigned exclusively to a particular client or project', '[{"en":"We assign a dedicated team to each enterprise account.","zh-TW":"我們為每個企業客戶分配一個專屬團隊。"},{"en":"A dedicated team ensures faster response and deeper expertise.","zh-TW":"專職團隊確保了更快的響應和更深的專業知識。"}]', 'expression'),
('deliberate practice', '刻意練習', 'focused, intentional practice designed to improve specific skills', '[{"en":"Deliberate practice develops negotiation skills faster.","zh-TW":"刻意練習更快地發展了談判技能。"},{"en":"Build deliberate practice into your team''s development program.","zh-TW":"將刻意練習納入團隊的發展計劃。"}]', 'expression'),
('deliver ahead of time', '提前交付；提前完成', 'to complete and hand over work before the scheduled deadline', '[{"en":"We delivered the project two weeks ahead of time.","zh-TW":"我們提前兩週交付了這個專案。"},{"en":"Delivering ahead of time builds a strong reputation.","zh-TW":"提前交付建立了良好的聲譽。"}]', 'expression'),
('demand-driven', '需求驅動的', 'responsive to customer demand rather than based on supply availability', '[{"en":"Our demand-driven production model reduces waste.","zh-TW":"我們的需求驅動生產模型減少了浪費。"},{"en":"Demand-driven strategies improve inventory efficiency.","zh-TW":"需求驅動的策略改善了庫存效率。"}]', 'business idiom'),
('democratize access', '使機會平等；普及化', 'to make something available to a wider or more diverse group of people', '[{"en":"Our platform democratizes access to financial tools.","zh-TW":"我們的平台使金融工具的機會平等。"},{"en":"Technology can democratize access to quality education.","zh-TW":"技術可以使優質教育的機會普及化。"}]', 'phrasal verb'),
('deployment roadmap', '部署路線圖', 'a plan showing the timeline and stages for rolling out a product or system', '[{"en":"Share the deployment roadmap with all stakeholders early.","zh-TW":"盡早與所有利益相關者分享部署路線圖。"},{"en":"The deployment roadmap includes three phases over six months.","zh-TW":"部署路線圖包括六個月內的三個階段。"}]', 'business idiom'),
('design for scale', '為規模化設計；可擴展設計', 'to create systems or processes with future growth in mind from the start', '[{"en":"Design for scale from day one to avoid costly rework later.","zh-TW":"從第一天就為規模化設計以避免後來代價高昂的返工。"},{"en":"Designing for scale prevents architectural bottlenecks.","zh-TW":"可擴展設計防止了架構瓶頸。"}]', 'expression'),
('differentiated value', '差異化價值；獨特的價值', 'unique benefits that distinguish a product or service from alternatives', '[{"en":"We deliver differentiated value through superior customer support.","zh-TW":"我們通過卓越的客戶支持提供差異化價值。"},{"en":"Articulate your differentiated value clearly in every pitch.","zh-TW":"在每次推介中清晰表達你的獨特價值。"}]', 'expression'),
('direct report', '直屬下屬；直接匯報的員工', 'an employee who is managed directly by a specific supervisor', '[{"en":"She manages four direct reports in the product team.","zh-TW":"她在產品團隊中管理四位直屬下屬。"},{"en":"Invest time in developing your direct reports.","zh-TW":"投入時間培養你的直屬下屬。"}]', 'business idiom'),
('distribute evenly', '均勻分配；平均分佈', 'to divide or spread something equally across all parts or people', '[{"en":"Distribute the workload evenly to prevent burnout.","zh-TW":"均勻分配工作量以防止倦怠。"},{"en":"Ensure marketing spend is distributed evenly across channels.","zh-TW":"確保行銷支出均勻分佈在各渠道。"}]', 'phrasal verb'),
('diversify revenue streams', '多元化收入來源', 'to develop multiple different sources of income to reduce dependence on any one', '[{"en":"We diversify revenue streams to reduce reliance on one client.","zh-TW":"我們多元化收入來源以減少對一個客戶的依賴。"},{"en":"Diversifying revenue streams protects against market volatility.","zh-TW":"多元化收入來源防範了市場波動。"}]', 'phrasal verb'),
('double down on strengths', '在優勢上加倍投入', 'to significantly increase focus and resources on areas where you are already strong', '[{"en":"Double down on strengths rather than trying to fix all weaknesses.","zh-TW":"在優勢上加倍投入而不是試圖修復所有弱點。"},{"en":"We doubled down on our data strengths to win enterprise clients.","zh-TW":"我們在數據優勢上加倍投入以贏得企業客戶。"}]', 'expression'),
('drive adoption', '推動採用；促進普及', 'to encourage widespread use of a product, service, or process', '[{"en":"Training and support drive adoption of new software.","zh-TW":"培訓和支持推動了新軟體的採用。"},{"en":"Incentives drive adoption in the early stages.","zh-TW":"激勵機制促進了早期階段的普及。"}]', 'phrasal verb'),
('economic headwind', '經濟逆風；不利的經濟環境', 'economic conditions that make it harder for a business to achieve its goals', '[{"en":"We maintained growth despite economic headwinds.","zh-TW":"儘管面臨經濟逆風我們仍然保持了增長。"},{"en":"Economic headwinds require conservative financial planning.","zh-TW":"不利的經濟環境需要保守的財務規劃。"}]', 'expression'),
('economic tailwind', '經濟順風；有利的經濟環境', 'economic conditions that make it easier for a business to grow', '[{"en":"We benefit from strong economic tailwinds this year.","zh-TW":"今年我們受益於強勁的經濟順風。"},{"en":"Economic tailwinds boosted our growth well above targets.","zh-TW":"有利的經濟環境推動我們的增長遠超目標。"}]', 'expression'),
('effective immediately', '即時生效；立即有效', 'taking effect right now without any delay', '[{"en":"The new policy is effective immediately.","zh-TW":"新政策即時生效。"},{"en":"The changes are effective immediately following the board vote.","zh-TW":"更改在董事會投票後立即有效。"}]', 'expression'),
('employee value proposition', '員工價值主張', 'the unique benefits offered to employees in exchange for their skills and contributions', '[{"en":"A compelling employee value proposition attracts top talent.","zh-TW":"有說服力的員工價值主張吸引了頂尖人才。"},{"en":"Review your employee value proposition annually.","zh-TW":"每年審查你的員工價值主張。"}]', 'business idiom'),
('empowerment culture', '賦權文化；授權文化', 'an organizational culture where employees are given the authority to make decisions', '[{"en":"Empowerment culture reduces bottlenecks in decision-making.","zh-TW":"賦權文化減少了決策中的瓶頸。"},{"en":"We built an empowerment culture by trusting teams with autonomy.","zh-TW":"我們通過給予團隊自主權建立了授權文化。"}]', 'business idiom'),
('end-to-end solution', '端到端解決方案；全流程解決方案', 'a product or service that covers every stage of a process from beginning to end', '[{"en":"We provide an end-to-end solution from sourcing to delivery.","zh-TW":"我們提供從採購到交付的端到端解決方案。"},{"en":"An end-to-end solution simplifies vendor management.","zh-TW":"全流程解決方案簡化了供應商管理。"}]', 'business idiom'),
('engagement rate', '參與率；互動率', 'the percentage of an audience that interacts with content or a program', '[{"en":"Our social media engagement rate doubled after the redesign.","zh-TW":"重新設計後我們的社交媒體互動率翻倍了。"},{"en":"Track engagement rate to measure content effectiveness.","zh-TW":"追蹤參與率以衡量內容有效性。"}]', 'business idiom'),
('enterprise value', '企業價值', 'the total value of a company including its debt and equity', '[{"en":"The enterprise value of the target was 500 million.","zh-TW":"目標公司的企業價值為五億。"},{"en":"Enterprise value reflects the total cost of acquisition.","zh-TW":"企業價值反映了收購的總成本。"}]', 'business idiom'),
('equity stake', '股權份額；股權比例', 'a percentage ownership in a company', '[{"en":"We offered an equity stake to key early employees.","zh-TW":"我們向關鍵早期員工提供了股權份額。"},{"en":"The investor received a 15% equity stake in exchange.","zh-TW":"投資者獲得了15%的股權份額作為交換。"}]', 'business idiom'),
('established player', '既有業者；市場老手', 'a company or organization that is already well-known and stable in a market', '[{"en":"Competing with established players requires a differentiated approach.","zh-TW":"與既有業者競爭需要差異化的方法。"},{"en":"Established players often have deep customer relationships.","zh-TW":"市場老手通常擁有深厚的客戶關係。"}]', 'business idiom'),
('event-driven', '事件驅動的', 'responding or triggered by specific events rather than time periods', '[{"en":"Event-driven marketing reaches customers at the right moment.","zh-TW":"事件驅動的行銷在正確的時機接觸客戶。"},{"en":"An event-driven architecture improves system responsiveness.","zh-TW":"事件驅動的架構提高了系統響應能力。"}]', 'business idiom'),
('execution risk', '執行風險', 'the risk that a plan will fail due to poor implementation', '[{"en":"Execution risk is often higher than strategic risk.","zh-TW":"執行風險通常高於策略風險。"},{"en":"Rigorous project management reduces execution risk.","zh-TW":"嚴格的專案管理降低了執行風險。"}]', 'business idiom'),
('expand the pie', '擴大整體利益；創造更多價值', 'to create additional value for everyone rather than fighting over a fixed amount', '[{"en":"A good negotiation expands the pie rather than just divides it.","zh-TW":"好的談判擴大整體利益而不只是分配它。"},{"en":"Think about how to expand the pie before dividing it.","zh-TW":"在分配之前思考如何擴大整體利益。"}]', 'expression'),
('expedite delivery', '加快交付；加速交貨', 'to speed up the process of delivering something', '[{"en":"We expedited delivery to meet the client''s urgent deadline.","zh-TW":"我們加快交付以滿足客戶的緊急截止日期。"},{"en":"Expedite delivery when customer satisfaction is at risk.","zh-TW":"當客戶滿意度面臨風險時加快交付。"}]', 'phrasal verb'),
('exponential growth', '指數級增長', 'growth that accelerates at an increasingly rapid rate', '[{"en":"Network effects can lead to exponential growth.","zh-TW":"網絡效應可以帶來指數級增長。"},{"en":"Few companies sustain exponential growth beyond five years.","zh-TW":"很少有公司能夠維持五年以上的指數級增長。"}]', 'business idiom'),
('fail fast', '快速失敗；早日失敗', 'to test ideas quickly so that failures can be identified and corrected early', '[{"en":"We adopt a fail fast approach to product experimentation.","zh-TW":"我們採用快速失敗的方法進行產品實驗。"},{"en":"Fail fast to avoid investing too much in the wrong direction.","zh-TW":"快速失敗以避免在錯誤方向上投入太多。"}]', 'expression'),
('feedback loop', '反饋迴路；回饋循環', 'a process where outputs are used as inputs to improve performance', '[{"en":"We built a feedback loop between sales and product development.","zh-TW":"我們在銷售和產品開發之間建立了反饋迴路。"},{"en":"Tight feedback loops accelerate product-market fit.","zh-TW":"緊密的回饋循環加速了產品市場契合度。"}]', 'business idiom'),
('financial runway', '資金跑道；可運營時間', 'the amount of time a company can operate before running out of money', '[{"en":"We have 18 months of financial runway before needing new funding.","zh-TW":"我們有18個月的資金跑道在需要新融資之前。"},{"en":"Extend your financial runway by reducing non-essential costs.","zh-TW":"通過減少非必要成本延長你的資金跑道。"}]', 'business idiom'),
('fixed cost', '固定成本', 'a cost that does not change with the level of production or sales', '[{"en":"High fixed costs create break-even pressure.","zh-TW":"高固定成本造成了收支平衡壓力。"},{"en":"Converting fixed costs to variable reduces risk.","zh-TW":"將固定成本轉為變動成本降低了風險。"}]', 'business idiom'),
('flat fee', '固定費用；統一費率', 'a single price that covers all services regardless of use or duration', '[{"en":"We charge a flat fee for the annual subscription.","zh-TW":"我們對年度訂閱收取固定費用。"},{"en":"A flat fee model gives customers predictable costs.","zh-TW":"固定費用模型讓客戶的成本可預期。"}]', 'business idiom'),
('focus on execution', '專注於執行；注重落實', 'to prioritize the actual implementation of plans over further planning', '[{"en":"It''s time to stop planning and focus on execution.","zh-TW":"是時候停止規劃而專注於執行了。"},{"en":"Focus on execution and measure outcomes weekly.","zh-TW":"專注於落實並每週衡量成果。"}]', 'expression'),
('force multiplier', '力量倍增器；放大影響的因素', 'something that greatly amplifies the effectiveness of a force or effort', '[{"en":"Good tooling acts as a force multiplier for small teams.","zh-TW":"好的工具作為小型團隊的力量倍增器。"},{"en":"A strong brand is a force multiplier in sales.","zh-TW":"強大的品牌是銷售中的力量倍增器。"}]', 'expression'),
('foreground the benefits', '突出強調好處；將好處置於前景', 'to highlight or emphasize the advantages of something prominently', '[{"en":"Foreground the benefits before mentioning the costs.","zh-TW":"在提到成本之前突出強調好處。"},{"en":"Good presentations foreground the benefits for the audience.","zh-TW":"好的演示為受眾突出強調好處。"}]', 'phrasal verb'),
('form alliances', '結盟；建立聯盟', 'to create formal agreements of cooperation between organizations', '[{"en":"We formed alliances with key distributors in new markets.","zh-TW":"我們與新市場的關鍵分銷商結盟。"},{"en":"Forming alliances can accelerate market entry.","zh-TW":"建立聯盟可以加速市場進入。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('full-stack', '全棧的；端到端的', 'covering all aspects or levels of a system or service', '[{"en":"We offer a full-stack HR solution from hire to retire.","zh-TW":"我們提供從招聘到退休的全棧人力資源解決方案。"},{"en":"Full-stack providers simplify vendor management.","zh-TW":"全棧提供商簡化了供應商管理。"}]', 'business idiom'),
('gain leverage', '獲得優勢；取得談判籌碼', 'to obtain a position of power or advantage in a situation', '[{"en":"We gain leverage by building switching costs for clients.","zh-TW":"我們通過為客戶建立轉換成本來獲得優勢。"},{"en":"Gain leverage in negotiations by understanding the other party''s needs.","zh-TW":"通過了解對方的需求在談判中取得籌碼。"}]', 'phrasal verb'),
('gap analysis', '差距分析', 'the process of comparing current performance to desired outcomes to identify gaps', '[{"en":"A gap analysis revealed weaknesses in our service delivery.","zh-TW":"差距分析揭示了我們服務交付的弱點。"},{"en":"Use gap analysis to prioritize training investments.","zh-TW":"使用差距分析來優先安排培訓投資。"}]', 'business idiom'),
('go beyond expectations', '超出預期；超越期望', 'to perform or deliver at a higher level than what was expected', '[{"en":"Our team consistently goes beyond expectations.","zh-TW":"我們的團隊始終超出預期。"},{"en":"Going beyond expectations creates loyal brand advocates.","zh-TW":"超越期望創造了忠誠的品牌擁護者。"}]', 'expression'),
('go on the record', '公開表態；留下紀錄', 'to make a statement officially or for formal documentation', '[{"en":"I want to go on the record supporting this initiative.","zh-TW":"我想公開表態支持這個計劃。"},{"en":"Going on the record shows accountability and transparency.","zh-TW":"公開表態顯示了問責制和透明度。"}]', 'expression'),
('go through channels', '通過正式渠道；按正規程序辦理', 'to follow proper official procedures rather than taking shortcuts', '[{"en":"Go through channels when requesting budget increases.","zh-TW":"申請預算增加時通過正式渠道進行。"},{"en":"She went through channels to resolve the compliance issue.","zh-TW":"她按正規程序辦理解決了合規問題。"}]', 'expression'),
('good enough', '夠用就好；足夠了', 'meeting minimum requirements without needing to be perfect', '[{"en":"In the MVP phase good enough beats perfect every time.","zh-TW":"在最小可行性產品階段夠用就好每次都優於完美。"},{"en":"Sometimes good enough allows you to move faster.","zh-TW":"有時候夠用就好讓你移動更快。"}]', 'expression'),
('granular data', '細粒度數據；精細數據', 'highly detailed data broken into small, specific categories', '[{"en":"Granular data reveals patterns invisible in aggregate views.","zh-TW":"細粒度數據揭示了彙總視圖中不可見的模式。"},{"en":"Collect granular data to improve personalization.","zh-TW":"收集精細數據以改善個性化。"}]', 'expression'),
('greenfield opportunity', '新建機會；全新未開發機會', 'an opportunity in a completely new market or situation without existing constraints', '[{"en":"The rural market is a greenfield opportunity for us.","zh-TW":"農村市場對我們來說是一個全新的未開發機會。"},{"en":"Greenfield opportunities allow you to build without legacy constraints.","zh-TW":"全新機會讓你可以不受舊有限制地建設。"}]', 'business idiom'),
('gross margin', '毛利率', 'the percentage of revenue remaining after subtracting the cost of goods sold', '[{"en":"Our gross margin improved from 35% to 42% this year.","zh-TW":"今年我們的毛利率從35%提高到了42%。"},{"en":"A higher gross margin gives more room for investment.","zh-TW":"更高的毛利率提供了更多的投資空間。"}]', 'business idiom'),
('guard against', '防範；預防', 'to take precautions to prevent something harmful from happening', '[{"en":"Guard against complacency after a successful quarter.","zh-TW":"在成功的季度後防範自滿情緒。"},{"en":"Diversify to guard against market concentration risk.","zh-TW":"通過多元化防範市場集中風險。"}]', 'phrasal verb'),
('growth hacking', '增長駭客；低成本快速增長策略', 'using creative, low-cost strategies to acquire and retain customers rapidly', '[{"en":"Our growth hacking team doubled user sign-ups in 90 days.","zh-TW":"我們的增長駭客團隊在90天內使用戶註冊翻倍了。"},{"en":"Growth hacking requires constant experimentation.","zh-TW":"增長駭客需要持續的實驗。"}]', 'business idiom'),
('growth mindset', '成長型思維', 'the belief that abilities can be developed through dedication and hard work', '[{"en":"A growth mindset turns failures into learning opportunities.","zh-TW":"成長型思維將失敗轉變為學習機會。"},{"en":"Foster a growth mindset culture to attract ambitious talent.","zh-TW":"培養成長型思維文化以吸引有抱負的人才。"}]', 'business idiom'),
('gut-check', '直覺審視；以直覺驗證', 'a check of one''s instincts or basic values before making a decision', '[{"en":"Before signing do a gut-check on whether this feels right.","zh-TW":"在簽署之前用直覺審視這是否感覺正確。"},{"en":"A gut-check is the final sanity test before committing.","zh-TW":"直覺審視是承諾之前的最後理性測試。"}]', 'expression'),
('hand off', '交接；移交', 'to pass responsibility or a task to another person', '[{"en":"She handed off the account to a new manager.","zh-TW":"她將帳戶交接給了新的經理。"},{"en":"A clean handoff prevents information loss during transitions.","zh-TW":"乾淨的交接防止了過渡期間的信息損失。"}]', 'phrasal verb'),
('hard skills', '硬技能；專業技能', 'specific, teachable technical abilities or knowledge', '[{"en":"The role requires hard skills in data analysis and coding.","zh-TW":"這個職位需要數據分析和編程方面的硬技能。"},{"en":"Pair hard skills training with soft skills development.","zh-TW":"將硬技能培訓與軟技能發展配對。"}]', 'business idiom'),
('have a say', '有發言權；有影響力', 'to have the right or opportunity to express one''s views on a matter', '[{"en":"Every team member should have a say in the planning process.","zh-TW":"每位團隊成員都應該在規劃過程中有發言權。"},{"en":"Employees want to have a say in how the company is run.","zh-TW":"員工希望對公司的運營方式有影響力。"}]', 'expression'),
('have an edge over', '在…方面具有優勢', 'to have a competitive advantage compared to someone or something', '[{"en":"We have an edge over competitors in customer support.","zh-TW":"我們在客戶支持方面比競爭對手具有優勢。"},{"en":"Proprietary technology gives us an edge over rivals.","zh-TW":"專有技術使我們在競爭對手方面具有優勢。"}]', 'expression'),
('have skin in it', '有切身利益在其中；真正有投入', 'to have a personal stake or investment in the outcome', '[{"en":"Founders who have skin in it make better long-term decisions.","zh-TW":"有切身利益的創始人做出更好的長期決策。"},{"en":"When you have skin in it you work harder for success.","zh-TW":"當你真正有投入時你更努力追求成功。"}]', 'expression'),
('high visibility project', '高曝光度專案；受矚目的專案', 'a project that is closely watched by senior leadership or the organization', '[{"en":"Leading a high visibility project accelerated her promotion.","zh-TW":"主導一個高曝光度專案加速了她的晉升。"},{"en":"High visibility projects require extra preparation and polish.","zh-TW":"受矚目的專案需要額外的準備和打磨。"}]', 'expression'),
('home run', '大成功；全壘打式的勝利', 'a major, outstanding success or achievement', '[{"en":"The product launch was a home run for the division.","zh-TW":"產品發布對這個部門來說是個大成功。"},{"en":"We hit a home run by landing the government contract.","zh-TW":"我們通過拿下政府合約取得了全壘打式的勝利。"}]', 'expression'),
('hustle culture', '拼搏文化；奮鬥文化', 'a work culture that glorifies overworking and constant productivity', '[{"en":"Hustle culture can lead to burnout if unchecked.","zh-TW":"如果不加以控制拼搏文化可能導致倦怠。"},{"en":"We prioritize results over hustle culture.","zh-TW":"我們優先考慮結果而不是奮鬥文化。"}]', 'business idiom'),
('hybrid model', '混合模式', 'combining two different approaches or structures, such as remote and in-office work', '[{"en":"We adopted a hybrid model combining in-person and online delivery.","zh-TW":"我們採用了結合線上和線下交付的混合模式。"},{"en":"A hybrid model offers flexibility for employees.","zh-TW":"混合模式為員工提供了靈活性。"}]', 'business idiom'),
('ideation process', '創意發想流程', 'the creative process of generating and developing new ideas', '[{"en":"We run a structured ideation process for product features.","zh-TW":"我們為產品功能運行結構化的創意發想流程。"},{"en":"Diverse teams produce richer ideation processes.","zh-TW":"多元化的團隊產生更豐富的創意發想流程。"}]', 'business idiom'),
('improve the bottom line', '改善盈利；提升利潤', 'to increase profit or financial performance', '[{"en":"Automation improved the bottom line by 12%.","zh-TW":"自動化將利潤改善了12%。"},{"en":"Every cost reduction initiative improves the bottom line.","zh-TW":"每項成本削減計劃都改善了盈利。"}]', 'expression'),
('in-depth analysis', '深入分析', 'a thorough and detailed examination of a topic or situation', '[{"en":"We conducted an in-depth analysis of the competitive landscape.","zh-TW":"我們對競爭格局進行了深入分析。"},{"en":"An in-depth analysis requires time but reveals critical insights.","zh-TW":"深入分析需要時間但揭示了關鍵洞察。"}]', 'expression'),
('initial public offering', '首次公開發行；上市', 'the first time a company offers shares to the public on a stock exchange', '[{"en":"The startup is preparing for an initial public offering next year.","zh-TW":"新創公司正在為明年的首次公開發行做準備。"},{"en":"An initial public offering provides capital for major expansion.","zh-TW":"首次公開發行為重大擴張提供了資金。"}]', 'business idiom'),
('insourcing', '內製；回收自製', 'bringing work that was previously outsourced back in-house', '[{"en":"We decided on insourcing IT support for better control.","zh-TW":"我們決定將IT支援內製以獲得更好的控制。"},{"en":"Insourcing critical functions reduces vendor dependency.","zh-TW":"將關鍵職能內製降低了對供應商的依賴。"}]', 'business idiom'),
('intellectual property', '知識產權；智慧財產', 'creations of the mind owned by a company, such as patents, trademarks, and copyrights', '[{"en":"Protecting intellectual property is essential for innovation.","zh-TW":"保護知識產權對創新至關重要。"},{"en":"Our intellectual property portfolio is a strategic asset.","zh-TW":"我們的知識產權組合是一個戰略資產。"}]', 'business idiom'),
('internal alignment', '內部一致；組織內部協調', 'the state in which all parts of an organization agree on and work toward common goals', '[{"en":"Internal alignment on strategy is the first step to execution.","zh-TW":"策略上的內部一致是執行的第一步。"},{"en":"Lack of internal alignment leads to conflicting initiatives.","zh-TW":"缺乏內部一致性導致計劃相互衝突。"}]', 'business idiom'),
('inventory turnover', '庫存週轉率', 'a ratio showing how many times inventory is sold and replaced in a period', '[{"en":"A higher inventory turnover improves cash flow.","zh-TW":"更高的庫存週轉率改善了現金流。"},{"en":"Track inventory turnover by product category.","zh-TW":"按產品類別追蹤庫存週轉率。"}]', 'business idiom'),
('joint venture', '合資企業；合資合作', 'a business arrangement where two companies combine resources for a project', '[{"en":"We formed a joint venture to enter the Chinese market.","zh-TW":"我們建立了合資企業以進入中國市場。"},{"en":"A joint venture shares both the risks and rewards.","zh-TW":"合資企業共享風險和回報。"}]', 'business idiom'),
('killer app', '殺手級應用；決定性功能', 'a feature or product so valuable that it justifies adopting the entire platform', '[{"en":"Our analytics dashboard is the killer app of the suite.","zh-TW":"我們的分析儀表板是這個套件的殺手級應用。"},{"en":"A killer app drives platform adoption faster than any marketing.","zh-TW":"殺手級應用比任何行銷都更快推動平台採用。"}]', 'business idiom'),
('know-how transfer', '技術轉移；知識傳遞', 'the sharing of technical skills or operational knowledge between parties', '[{"en":"The deal included a know-how transfer agreement.","zh-TW":"交易中包含了技術轉移協議。"},{"en":"Know-how transfer is essential for scaling operations.","zh-TW":"知識傳遞對於擴大業務規模至關重要。"}]', 'expression'),
('label + as', '把…標記為；將…歸類為', 'to categorize or classify something with a specific description', '[{"en":"Label the expense as marketing for easier tracking.","zh-TW":"把這筆費用標記為行銷以便更容易追蹤。"},{"en":"Avoid labeling people as low performers without sufficient data.","zh-TW":"避免在沒有足夠數據的情況下將人們歸類為低績效者。"}]', 'phrasal verb'),
('lean startup', '精益創業', 'a methodology that uses rapid prototyping and customer feedback to build businesses efficiently', '[{"en":"We follow lean startup principles to minimize waste.","zh-TW":"我們遵循精益創業原則以減少浪費。"},{"en":"Lean startup methodology accelerates learning cycles.","zh-TW":"精益創業方法加速了學習週期。"}]', 'business idiom'),
('leverage data', '善用數據；利用數據優勢', 'to use data effectively to gain insights, make decisions, or improve outcomes', '[{"en":"We leverage data to personalize the customer experience.","zh-TW":"我們善用數據個性化客戶體驗。"},{"en":"Leverage data from every touchpoint to reduce churn.","zh-TW":"利用每個接觸點的數據來降低流失率。"}]', 'phrasal verb'),
('licensing agreement', '授權協議', 'a contract granting permission to use intellectual property in exchange for compensation', '[{"en":"The licensing agreement gives us access to their patent portfolio.","zh-TW":"授權協議使我們能夠訪問他們的專利組合。"},{"en":"A licensing agreement is a low-risk market entry strategy.","zh-TW":"授權協議是低風險的市場進入策略。"}]', 'business idiom'),
('life cycle management', '生命週期管理', 'overseeing a product or asset from creation through to end of life', '[{"en":"Life cycle management prevents premature product discontinuation.","zh-TW":"生命週期管理防止了產品過早停產。"},{"en":"Track costs across the full life cycle for better decisions.","zh-TW":"追蹤整個生命週期的成本以做出更好的決策。"}]', 'business idiom'),
('limited resources', '資源有限；資源匱乏', 'having insufficient time, money, or people to accomplish all goals', '[{"en":"With limited resources we prioritized the highest-impact work.","zh-TW":"在資源有限的情況下我們優先考慮影響最大的工作。"},{"en":"Creative thinking compensates for limited resources.","zh-TW":"創意思維彌補了資源有限的不足。"}]', 'expression'),
('lock in clients', '鎖定客戶；綁定客戶', 'to secure long-term commitments from customers through contracts or switching costs', '[{"en":"Long-term contracts lock in clients and stabilize revenue.","zh-TW":"長期合約鎖定了客戶並穩定了收入。"},{"en":"We lock in clients by embedding our software into their workflow.","zh-TW":"我們通過將軟體嵌入他們的工作流程來鎖定客戶。"}]', 'phrasal verb'),
('main takeaway', '主要收穫；核心要點', 'the most important message or lesson from a presentation or discussion', '[{"en":"The main takeaway from today''s meeting is that we need more data.","zh-TW":"今天會議的主要收穫是我們需要更多數據。"},{"en":"Summarize the main takeaway at the end of every presentation.","zh-TW":"在每次演示結束時總結核心要點。"}]', 'expression'),
('market gap', '市場缺口', 'an unmet need or underserved segment in a market', '[{"en":"We identified a market gap in affordable premium fitness equipment.","zh-TW":"我們識別了實惠高端健身設備的市場缺口。"},{"en":"Addressing a market gap first can create a loyal customer base.","zh-TW":"首先填補市場缺口可以創建忠實的客戶群。"}]', 'business idiom'),
('market leader', '市場領導者；行業龍頭', 'the company with the largest market share in an industry', '[{"en":"We aim to overtake the market leader in customer service.","zh-TW":"我們的目標是在客戶服務上超越市場領導者。"},{"en":"Market leaders must innovate continuously to maintain position.","zh-TW":"市場領導者必須持續創新以保持地位。"}]', 'business idiom'),
('market research', '市場研究；市場調查', 'the systematic collection and analysis of information about a market', '[{"en":"Thorough market research shaped our product strategy.","zh-TW":"全面的市場研究塑造了我們的產品策略。"},{"en":"Market research reduces the risk of product failure.","zh-TW":"市場研究降低了產品失敗的風險。"}]', 'business idiom'),
('matrix organization', '矩陣式組織', 'a structure where employees have dual reporting relationships to both functional and project managers', '[{"en":"A matrix organization promotes collaboration across functions.","zh-TW":"矩陣式組織促進了跨職能的協作。"},{"en":"Matrix organizations can be complex to manage.","zh-TW":"矩陣式組織可能難以管理。"}]', 'business idiom'),
('merit-based', '以能力為基礎的；按功績的', 'decided or awarded based on performance and ability rather than seniority', '[{"en":"Our merit-based pay system motivates high performance.","zh-TW":"我們以能力為基礎的薪酬體系激勵了高績效。"},{"en":"Merit-based promotions reduce bias in advancement decisions.","zh-TW":"按功績晉升減少了晉升決策中的偏見。"}]', 'business idiom'),
('minimize exposure', '降低風險敞口；減少暴露', 'to reduce the degree to which one is at risk or vulnerable', '[{"en":"Hedge your positions to minimize exposure to currency risk.","zh-TW":"對冲倉位以降低匯率風險敞口。"},{"en":"Diversification minimizes exposure to any single sector.","zh-TW":"多元化減少了對任何單一行業的暴露。"}]', 'phrasal verb'),
('mission statement', '使命宣言', 'a formal declaration of an organization''s purpose and core values', '[{"en":"A clear mission statement aligns teams around a shared purpose.","zh-TW":"清晰的使命宣言使團隊圍繞共同目標保持一致。"},{"en":"Revisit your mission statement as the company evolves.","zh-TW":"隨著公司發展重新審視你的使命宣言。"}]', 'business idiom'),
('mobilize stakeholders', '動員利益相關者；召集相關方', 'to engage and activate key parties to participate in an initiative', '[{"en":"Mobilizing stakeholders early prevented resistance later.","zh-TW":"早期動員利益相關者防止了後來的阻力。"},{"en":"We mobilized stakeholders across three departments.","zh-TW":"我們動員了三個部門的利益相關者。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('moment of truth', '關鍵時刻；決定性時刻', 'a critical point at which the true quality or character of something is revealed', '[{"en":"The product launch was a moment of truth for the team.","zh-TW":"產品發布是團隊的關鍵時刻。"},{"en":"Customer service is a moment of truth for any brand.","zh-TW":"客戶服務是任何品牌的決定性時刻。"}]', 'expression'),
('monetization strategy', '商業化策略；變現策略', 'a plan for generating revenue from a product, service, or platform', '[{"en":"Our monetization strategy combines subscriptions and advertising.","zh-TW":"我們的變現策略結合了訂閱和廣告。"},{"en":"Test multiple monetization strategies before committing.","zh-TW":"在確定之前測試多種變現策略。"}]', 'business idiom'),
('multi-channel approach', '多渠道方法', 'a strategy using multiple communication or distribution channels simultaneously', '[{"en":"A multi-channel approach reaches customers wherever they are.","zh-TW":"多渠道方法在任何地方都能接觸客戶。"},{"en":"Our multi-channel approach includes email, social, and direct sales.","zh-TW":"我們的多渠道方法包括電子郵件、社交媒體和直接銷售。"}]', 'business idiom'),
('net present value', '淨現值', 'the current value of future cash flows discounted at a required rate of return', '[{"en":"The net present value analysis supports the project approval.","zh-TW":"淨現值分析支持了專案批准。"},{"en":"Use net present value to compare long-term investment options.","zh-TW":"使用淨現值比較長期投資選項。"}]', 'business idiom'),
('niche market', '利基市場；小眾市場', 'a small, specific segment of a larger market with distinct needs', '[{"en":"Dominating a niche market can be more profitable than competing broadly.","zh-TW":"主導利基市場可能比廣泛競爭更有利可圖。"},{"en":"We found our niche market in sustainable corporate gifting.","zh-TW":"我們在可持續企業禮品市場找到了我們的利基市場。"}]', 'business idiom'),
('no strings attached', '無附加條件；沒有附帶要求', 'without any conditions or obligations attached to an offer', '[{"en":"Try the product free for 30 days no strings attached.","zh-TW":"免費試用產品30天，無附加條件。"},{"en":"We offered the pilot with no strings attached.","zh-TW":"我們提供了沒有附帶要求的試點。"}]', 'expression'),
('non-disclosure agreement', '保密協議', 'a legal contract preventing parties from sharing confidential information', '[{"en":"All partners sign a non-disclosure agreement before discussions.","zh-TW":"所有合作夥伴在討論前簽署保密協議。"},{"en":"A non-disclosure agreement protects proprietary information.","zh-TW":"保密協議保護了專有信息。"}]', 'business idiom'),
('north star metric', '北極星指標；最重要的核心指標', 'the single most important metric that guides an organization''s strategy', '[{"en":"Our north star metric is daily active users.","zh-TW":"我們的北極星指標是日活躍用戶數。"},{"en":"Align all teams behind the north star metric.","zh-TW":"讓所有團隊圍繞北極星指標保持一致。"}]', 'business idiom'),
('operate at capacity', '全力運轉；達到最大產能', 'to work at full output or resource utilization', '[{"en":"The factory operates at capacity during the holiday season.","zh-TW":"工廠在假日期間全力運轉。"},{"en":"Operating at capacity reduces flexibility for new orders.","zh-TW":"達到最大產能減少了處理新訂單的靈活性。"}]', 'expression'),
('operational efficiency', '運營效率', 'the ratio of useful output to total resources used in operations', '[{"en":"We improved operational efficiency by 20% through lean methods.","zh-TW":"我們通過精益方法將運營效率提高了20%。"},{"en":"Operational efficiency is a key driver of margin improvement.","zh-TW":"運營效率是利潤率改善的關鍵驅動因素。"}]', 'business idiom'),
('opportunity window', '機會窗口；窗口期', 'a limited time period during which an opportunity is available', '[{"en":"The opportunity window in this market is only 12 months.","zh-TW":"這個市場的機會窗口只有12個月。"},{"en":"Don''t miss the opportunity window by over-planning.","zh-TW":"不要因為過度規劃而錯過機會窗口。"}]', 'expression'),
('order of magnitude', '數量級；極大的差異', 'a factor of ten; a dramatically large difference in scale', '[{"en":"The new algorithm improved performance by an order of magnitude.","zh-TW":"新算法將性能提高了一個數量級。"},{"en":"We need to reduce costs by an order of magnitude to compete.","zh-TW":"我們需要將成本降低一個數量級才能競爭。"}]', 'expression'),
('out of pocket', '自費；自掏腰包', 'paying for something from one''s own personal funds', '[{"en":"Employees pay out of pocket and are reimbursed later.","zh-TW":"員工先自費後再報銷。"},{"en":"Avoid making clients pay out of pocket for extra services.","zh-TW":"避免讓客戶自費支付額外服務費用。"}]', 'expression'),
('out-of-the-box thinking', '突破框架的思維；創新思考', 'creative problem-solving that goes beyond conventional approaches', '[{"en":"Out-of-the-box thinking led to an unexpected solution.","zh-TW":"突破框架的思維帶來了意想不到的解決方案。"},{"en":"We encourage out-of-the-box thinking in brainstorming sessions.","zh-TW":"我們在頭腦風暴會議中鼓勵創新思考。"}]', 'expression'),
('output-focused', '以輸出為導向；注重結果', 'concentrating on the results produced rather than the process followed', '[{"en":"Our output-focused culture values results over hours worked.","zh-TW":"我們以輸出為導向的文化重視結果勝過工作時間。"},{"en":"An output-focused manager empowers teams to choose their methods.","zh-TW":"注重結果的經理讓團隊自主選擇方法。"}]', 'business idiom'),
('overarching goal', '總體目標；首要目標', 'the main, encompassing goal that all other objectives support', '[{"en":"Our overarching goal is to become the market leader in five years.","zh-TW":"我們的總體目標是在五年內成為市場領導者。"},{"en":"Keep the overarching goal in sight during daily decisions.","zh-TW":"在日常決策中保持對總體目標的關注。"}]', 'expression'),
('overcome objections', '克服異議；消除反對意見', 'to address and resolve the concerns or objections of a potential buyer or stakeholder', '[{"en":"Good salespeople overcome objections with evidence and empathy.","zh-TW":"優秀的銷售人員用證據和同理心克服異議。"},{"en":"Prepare to overcome common objections in every pitch.","zh-TW":"準備在每次推介中克服常見異議。"}]', 'phrasal verb'),
('own the conversation', '主導對話；掌控談話方向', 'to control the direction and tone of a discussion', '[{"en":"Own the conversation around sustainability in your industry.","zh-TW":"在你的行業中主導關於可持續發展的對話。"},{"en":"Thought leadership lets you own the conversation.","zh-TW":"思想領導力讓你掌控談話方向。"}]', 'expression'),
('pass the baton', '交棒；移交責任', 'to transfer responsibility or leadership to the next person in a process', '[{"en":"The retiring CEO passed the baton to her chosen successor.","zh-TW":"退休的執行長將責任交棒給了她選定的繼任者。"},{"en":"Pass the baton clearly to avoid workflow disruptions.","zh-TW":"清晰地移交責任以避免工作流程中斷。"}]', 'expression'),
('pay attention to detail', '注重細節；關注細節', 'to carefully focus on small but important elements', '[{"en":"Clients appreciate when you pay attention to detail.","zh-TW":"客戶欣賞你注重細節。"},{"en":"Pay attention to detail in every client communication.","zh-TW":"在每次客戶溝通中關注細節。"}]', 'expression'),
('pay the price', '付出代價；承擔後果', 'to suffer the consequences of an action or decision', '[{"en":"We paid the price for launching without enough testing.","zh-TW":"我們為在沒有足夠測試的情況下發布付出了代價。"},{"en":"Cutting corners now means paying the price later.","zh-TW":"現在走捷徑意味著以後要承擔後果。"}]', 'expression'),
('peak performance', '巔峰表現；最佳狀態', 'the highest level of quality or productivity one can achieve', '[{"en":"We create conditions for teams to reach peak performance.","zh-TW":"我們為團隊達到巔峰表現創造條件。"},{"en":"Peak performance requires rest as well as effort.","zh-TW":"巔峰表現需要休息和努力。"}]', 'expression'),
('per your request', '按照您的要求；依您所請', 'in response to what someone has asked for', '[{"en":"Per your request I have attached the full report.","zh-TW":"按照您的要求我附上了完整的報告。"},{"en":"Per your request the delivery has been rescheduled.","zh-TW":"依您所請交付時間已重新安排。"}]', 'prepositional phrase'),
('perfect storm', '完美風暴；各種不利因素同時發生', 'a set of circumstances that combine to produce an especially bad situation', '[{"en":"A perfect storm of supply issues and demand spikes hit us.","zh-TW":"供應問題和需求激增的完美風暴擊中了我們。"},{"en":"The company thrived despite the perfect storm of 2020.","zh-TW":"公司儘管遭遇了2020年的完美風暴仍然蓬勃發展。"}]', 'expression'),
('phase approach', '分階段方法；逐步推進', 'breaking a project or implementation into sequential stages', '[{"en":"A phase approach to rollout reduces implementation risk.","zh-TW":"分階段推出降低了實施風險。"},{"en":"The phase approach allows for learning between stages.","zh-TW":"分階段方法允許在各階段之間學習。"}]', 'business idiom'),
('plug-and-play', '即插即用；快速可用', 'a solution that works immediately without complex setup or integration', '[{"en":"Our plug-and-play solution requires no technical setup.","zh-TW":"我們的即插即用解決方案不需要技術設置。"},{"en":"Clients prefer plug-and-play tools for faster adoption.","zh-TW":"客戶更喜歡即插即用工具以加快採用。"}]', 'business idiom'),
('portfolio approach', '組合方法；多元投資組合方式', 'managing a diverse set of investments, products, or projects as a whole', '[{"en":"A portfolio approach to R&D spreads innovation risk.","zh-TW":"研發的組合方法分散了創新風險。"},{"en":"We take a portfolio approach to market investments.","zh-TW":"我們以組合方法進行市場投資。"}]', 'business idiom'),
('position statement', '定位宣言；品牌定位陳述', 'a brief description of how a product or brand is positioned in the market', '[{"en":"The position statement clarifies our target audience and differentiation.","zh-TW":"定位宣言澄清了我們的目標受眾和差異化。"},{"en":"A strong position statement guides all marketing communications.","zh-TW":"有力的品牌定位陳述指導了所有行銷傳播。"}]', 'business idiom'),
('pre-emptive strike', '先發制人；主動出擊', 'taking action before a competitor or opponent to prevent them from acting first', '[{"en":"The price cut was a pre-emptive strike against the new entrant.","zh-TW":"降價是對新進入者的先發制人。"},{"en":"A pre-emptive strike can shift competitive dynamics.","zh-TW":"主動出擊可以改變競爭動態。"}]', 'expression'),
('preferred vendor', '優選供應商；首選供應商', 'a supplier that has been approved and given priority in purchasing decisions', '[{"en":"Becoming a preferred vendor gives us guaranteed business.","zh-TW":"成為優選供應商使我們獲得了有保障的業務。"},{"en":"Preferred vendor status comes with better payment terms.","zh-TW":"優選供應商狀態伴隨著更好的付款條款。"}]', 'business idiom'),
('price elasticity', '價格彈性', 'the degree to which demand changes when the price of a product changes', '[{"en":"Price elasticity tests showed we could raise prices 10%.","zh-TW":"價格彈性測試表明我們可以提高10%的價格。"},{"en":"Understanding price elasticity informs optimal pricing decisions.","zh-TW":"了解價格彈性為最佳定價決策提供了依據。"}]', 'business idiom'),
('proactive outreach', '主動外聯；積極觸達', 'initiating contact before a need arises rather than waiting to be asked', '[{"en":"Proactive outreach to at-risk accounts prevents churn.","zh-TW":"對高風險帳戶的主動外聯防止了流失。"},{"en":"Schedule proactive outreach to top clients quarterly.","zh-TW":"每季度與頂級客戶進行主動外聯。"}]', 'expression'),
('product differentiation', '產品差異化', 'the process of distinguishing a product from competitors through unique features or value', '[{"en":"Product differentiation is our key defense against commoditization.","zh-TW":"產品差異化是我們抵禦商品化的關鍵防禦。"},{"en":"Strong product differentiation commands premium pricing.","zh-TW":"強大的產品差異化支持溢價定價。"}]', 'business idiom'),
('product roadmap', '產品路線圖', 'a strategic plan showing the vision and direction for a product over time', '[{"en":"Share the product roadmap with enterprise clients to build commitment.","zh-TW":"與企業客戶分享產品路線圖以建立承諾。"},{"en":"The product roadmap is updated quarterly based on feedback.","zh-TW":"產品路線圖根據反饋每季度更新。"}]', 'business idiom'),
('profit and loss', '損益；盈虧', 'the financial statement showing revenues, expenses, and net profit or loss', '[{"en":"Review the profit and loss statement monthly.","zh-TW":"每月審查損益表。"},{"en":"Each business unit owns its own profit and loss.","zh-TW":"每個業務部門負責自己的損益。"}]', 'business idiom'),
('proposal stage', '提案階段；投標階段', 'the phase in a sales or procurement process where a formal offer is submitted', '[{"en":"We are at the proposal stage with three enterprise clients.","zh-TW":"我們正與三個企業客戶處於提案階段。"},{"en":"Invest time in tailoring your pitch at the proposal stage.","zh-TW":"在投標階段投入時間量身訂制你的推介。"}]', 'business idiom'),
('put a price on', '為…定價；衡量…的價值', 'to determine the monetary value of something', '[{"en":"It''s hard to put a price on brand trust.","zh-TW":"很難為品牌信任定價。"},{"en":"Put a price on your time to prioritize high-value activities.","zh-TW":"為你的時間定價以優先考慮高價值活動。"}]', 'expression'),
('reach saturation point', '達到飽和點', 'to reach the stage where growth stops because the market is fully penetrated', '[{"en":"The core market has reached saturation point — we need to diversify.","zh-TW":"核心市場已達到飽和點——我們需要多元化。"},{"en":"When you reach saturation point explore adjacent markets.","zh-TW":"當達到飽和點時探索相鄰市場。"}]', 'expression'),
('refinance', '再融資；重新融資', 'to replace an existing loan or debt with new financing on different terms', '[{"en":"We refinanced the corporate debt to lower our interest burden.","zh-TW":"我們為公司債務再融資以降低利息負擔。"},{"en":"Refinancing now while rates are low makes strategic sense.","zh-TW":"趁現在利率低時再融資在策略上是有意義的。"}]', 'phrasal verb'),
('relationship capital', '關係資本；人脈資本', 'the network of professional relationships and goodwill built over time', '[{"en":"Relationship capital is one of our most valuable assets.","zh-TW":"關係資本是我們最有價值的資產之一。"},{"en":"Use relationship capital to open doors in new markets.","zh-TW":"利用人脈資本在新市場打開大門。"}]', 'expression'),
('reprioritize tasks', '重新排列優先順序；調整優先級', 'to change the order of importance of tasks based on new information or needs', '[{"en":"Reprioritize tasks when a high-value client needs urgent support.","zh-TW":"當高價值客戶需要緊急支持時重新排列任務優先順序。"},{"en":"Teams must be willing to reprioritize tasks in a fast-changing environment.","zh-TW":"在快速變化的環境中團隊必須願意調整優先級。"}]', 'phrasal verb'),
('research and development', '研究與開發；研發', 'investment in discovering new knowledge and translating it into products or processes', '[{"en":"We allocate 15% of revenue to research and development.","zh-TW":"我們將15%的收入用於研究與開發。"},{"en":"Research and development is the engine of long-term growth.","zh-TW":"研究與開發是長期增長的引擎。"}]', 'business idiom'),
('resilient organization', '有韌性的組織；抗壓能力強的組織', 'an organization capable of adapting and recovering quickly from challenges', '[{"en":"Building a resilient organization requires diverse capabilities.","zh-TW":"建立有韌性的組織需要多元化的能力。"},{"en":"A resilient organization turns crises into opportunities.","zh-TW":"有韌性的組織將危機轉化為機會。"}]', 'expression'),
('revenue target', '收入目標', 'the planned level of sales or income a business aims to achieve in a period', '[{"en":"We exceeded the revenue target for Q3 by 20%.","zh-TW":"我們超出了第三季收入目標20%。"},{"en":"Break down the revenue target by product and region.","zh-TW":"將收入目標按產品和地區分解。"}]', 'business idiom'),
('role clarity', '職責明確；角色清晰度', 'a clear understanding of one''s responsibilities and how they fit into the organization', '[{"en":"Role clarity reduces conflict and improves efficiency.","zh-TW":"職責明確減少了衝突並提高了效率。"},{"en":"Review role clarity after organizational restructuring.","zh-TW":"組織重組後審查角色清晰度。"}]', 'business idiom'),
('sandbox testing', '沙盒測試；隔離環境測試', 'testing in an isolated environment to prevent impact on production systems', '[{"en":"We use sandbox testing before any production deployment.","zh-TW":"在任何生產部署之前我們使用沙盒測試。"},{"en":"Sandbox testing reduces risk of system failures.","zh-TW":"沙盒測試降低了系統故障的風險。"}]', 'business idiom'),
('scenario planning', '情境規劃；情景規劃', 'developing strategies for multiple possible future situations', '[{"en":"Scenario planning prepared us for the market downturn.","zh-TW":"情境規劃讓我們為市場下滑做好了準備。"},{"en":"Include three scenarios: best case, worst case, and expected.","zh-TW":"包括三種情景：最佳情況、最差情況和預期情況。"}]', 'business idiom'),
('secure funding', '獲取資金；籌集資金', 'to obtain the money needed to start or continue a project or business', '[{"en":"We secured Series B funding of 50 million dollars.","zh-TW":"我們獲取了5000萬美元的B輪融資。"},{"en":"Secure funding early to avoid cash flow problems.","zh-TW":"儘早籌集資金以避免現金流問題。"}]', 'phrasal verb'),
('self-disruption', '自我顛覆；主動創新顛覆自身', 'when a company proactively disrupts its own business model before a competitor does', '[{"en":"Netflix embraced self-disruption by moving from DVD to streaming.","zh-TW":"Netflix通過從DVD轉向流媒體擁抱了自我顛覆。"},{"en":"Self-disruption is painful but necessary for survival.","zh-TW":"自我顛覆是痛苦的但對生存是必要的。"}]', 'business idiom'),
('service level agreement', '服務水準協議', 'a contract defining the expected level of service between a provider and client', '[{"en":"We consistently meet our service level agreement targets.","zh-TW":"我們始終達到服務水準協議的目標。"},{"en":"A service level agreement sets clear expectations for both parties.","zh-TW":"服務水準協議為雙方設定了明確的期望。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('shift the paradigm', '改變範式；轉變思維框架', 'to fundamentally change the way something is understood or done', '[{"en":"Cloud computing shifted the paradigm for enterprise software.","zh-TW":"雲計算改變了企業軟體的範式。"},{"en":"Our research aims to shift the paradigm on customer loyalty.","zh-TW":"我們的研究旨在改變客戶忠誠度的思維框架。"}]', 'expression'),
('short-list', '列入候選名單；入圍', 'to reduce a list of applicants or options to only the most suitable few', '[{"en":"We short-listed five vendors for the final evaluation.","zh-TW":"我們將五個供應商列入了最終評估的候選名單。"},{"en":"Short-list based on both technical fit and culture alignment.","zh-TW":"根據技術契合度和文化一致性進行入圍篩選。"}]', 'phrasal verb'),
('silent majority', '沉默的多數；無聲的大多數', 'the large group of people who hold a view but rarely express it publicly', '[{"en":"The silent majority supported the change but didn''t speak up.","zh-TW":"沉默的多數支持這個改變但沒有發言。"},{"en":"Seek input from the silent majority through anonymous surveys.","zh-TW":"通過匿名調查徵求沉默多數的意見。"}]', 'expression'),
('single source of truth', '唯一可信來源；統一數據來源', 'a central repository that holds the most accurate and up-to-date version of data', '[{"en":"We built a single source of truth for all customer data.","zh-TW":"我們建立了所有客戶數據的唯一可信來源。"},{"en":"A single source of truth prevents data inconsistency.","zh-TW":"統一數據來源防止了數據不一致。"}]', 'business idiom'),
('six sigma', '六西格瑪；品質管理方法', 'a data-driven quality improvement methodology aimed at reducing defects', '[{"en":"Six sigma reduced our defect rate to near zero.","zh-TW":"六西格瑪將我們的缺陷率降低到近乎零。"},{"en":"Six sigma principles guide our manufacturing quality processes.","zh-TW":"六西格瑪原則指導著我們的製造品質流程。"}]', 'business idiom'),
('skill gap', '技能差距；能力缺口', 'the difference between the skills required for a job and those actually held by employees', '[{"en":"We conducted a survey to identify skill gaps across departments.","zh-TW":"我們進行了調查以識別各部門的技能差距。"},{"en":"Addressing the skill gap is a priority for HR this year.","zh-TW":"解決技能差距是人力資源部門今年的優先事項。"}]', 'business idiom'),
('slow burn', '緩慢發展；慢熱效應', 'a situation that develops gradually over a long period before becoming significant', '[{"en":"The product was a slow burn — it took two years to gain traction.","zh-TW":"該產品是慢熱型的——花了兩年時間才取得進展。"},{"en":"Regulatory approvals can create a slow burn for new industries.","zh-TW":"監管審批可能為新行業帶來緩慢發展的效應。"}]', 'expression'),
('smart goals', 'SMART目標；具體可衡量的目標', 'goals that are Specific, Measurable, Achievable, Relevant, and Time-bound', '[{"en":"Set smart goals so employees know exactly what is expected.","zh-TW":"設定SMART目標讓員工確切知道期望是什麼。"},{"en":"Smart goals improve focus and accountability.","zh-TW":"具體可衡量的目標提高了專注度和問責制。"}]', 'business idiom'),
('soft close', '軟性成交；溫和收尾', 'a gentle way of asking for a buying decision without pressure', '[{"en":"A soft close like \"Does this solution look right to you?\" builds trust.","zh-TW":"像\"這個解決方案看起來適合您嗎？\"這樣的軟性成交建立了信任。"},{"en":"Use a soft close when the prospect needs more time.","zh-TW":"當潛在客戶需要更多時間時使用軟性成交方式。"}]', 'business idiom'),
('solution selling', '解決方案銷售；顧問式銷售', 'a sales methodology focused on identifying customer problems and offering tailored solutions', '[{"en":"Solution selling requires deep understanding of the customer''s challenges.","zh-TW":"解決方案銷售需要對客戶挑戰的深刻理解。"},{"en":"We train our sales team in solution selling techniques.","zh-TW":"我們對銷售團隊進行解決方案銷售技術的培訓。"}]', 'business idiom'),
('speak truth to power', '對掌權者說真話；勇於諫言', 'to tell the truth or challenge those in authority even when it is uncomfortable', '[{"en":"A good advisor must be willing to speak truth to power.","zh-TW":"好的顧問必須願意對掌權者說真話。"},{"en":"Speaking truth to power is how organizations avoid blind spots.","zh-TW":"對掌權者說真話是組織避免盲點的方式。"}]', 'expression'),
('stand one''s ground', '堅持立場；不退讓', 'to maintain one''s position or argument despite pressure to change', '[{"en":"Stand your ground when negotiating key contract terms.","zh-TW":"在談判關鍵合同條款時堅持立場。"},{"en":"She stood her ground against pressure to cut the budget.","zh-TW":"她在削減預算的壓力下堅持了立場。"}]', 'expression'),
('strategic initiative', '戰略舉措；重大戰略行動', 'a specific high-priority action designed to achieve a strategic objective', '[{"en":"Cost reduction is our primary strategic initiative this year.","zh-TW":"降低成本是我們今年的主要戰略舉措。"},{"en":"Each strategic initiative has a dedicated owner and timeline.","zh-TW":"每個戰略舉措都有專門的負責人和時間表。"}]', 'business idiom'),
('strategic sourcing', '戰略採購', 'a procurement approach focused on optimizing value from supplier relationships', '[{"en":"Strategic sourcing reduced our supply costs by 18%.","zh-TW":"戰略採購將我們的供應成本降低了18%。"},{"en":"Strategic sourcing evaluates quality, price, and reliability.","zh-TW":"戰略採購評估品質、價格和可靠性。"}]', 'business idiom'),
('stretch target', '延伸目標；挑戰性目標', 'an ambitious goal set beyond what is considered easily achievable to motivate higher performance', '[{"en":"The stretch target of 200% growth pushed the team to innovate.","zh-TW":"200%增長的延伸目標推動了團隊創新。"},{"en":"Stretch targets foster a growth mindset when framed correctly.","zh-TW":"當框架正確時延伸目標培養了成長心態。"}]', 'business idiom'),
('sunk cost', '沉沒成本', 'money or resources already spent that cannot be recovered, and should not influence future decisions', '[{"en":"Don''t let sunk costs drive the decision to continue a failing project.","zh-TW":"不要讓沉沒成本驅動繼續失敗項目的決定。"},{"en":"Sunk cost thinking keeps organizations stuck in bad investments.","zh-TW":"沉沒成本思維使組織陷入糟糕的投資。"}]', 'business idiom'),
('sustainability reporting', '永續報告；可持續性報告', 'corporate disclosure of environmental, social, and governance performance metrics', '[{"en":"Sustainability reporting is now required by major investors.","zh-TW":"永續報告現已被主要投資者所要求。"},{"en":"Our sustainability reporting follows GRI standards.","zh-TW":"我們的永續報告遵循GRI標準。"}]', 'business idiom'),
('switch gears', '換個話題；轉換方向', 'to change the focus or direction of a conversation or activity', '[{"en":"Let''s switch gears and discuss the Q4 launch plan.","zh-TW":"讓我們換個話題討論第四季度的啟動計劃。"},{"en":"The team switched gears mid-project when priorities changed.","zh-TW":"當優先事項改變時團隊在項目中途轉換了方向。"}]', 'expression'),
('synergy effect', '協同效應', 'the additional value created when two or more entities work together beyond their individual capacities', '[{"en":"The merger created a synergy effect in combined R&D operations.","zh-TW":"合并在聯合研發業務中創造了協同效應。"},{"en":"Synergy effects can take time to materialize after acquisition.","zh-TW":"協同效應在收購後可能需要時間才能實現。"}]', 'business idiom'),
('take a calculated risk', '承擔經過計算的風險；謹慎冒險', 'to deliberately accept a risk after evaluating the potential benefits and downsides', '[{"en":"We took a calculated risk by entering the emerging market early.","zh-TW":"我們謹慎冒險提早進入了新興市場。"},{"en":"Taking a calculated risk is different from reckless gambling.","zh-TW":"承擔經過計算的風險不同於魯莽賭博。"}]', 'expression'),
('target demographic', '目標人口統計；目標客群', 'the specific segment of the population a product or service is aimed at', '[{"en":"Define your target demographic before designing the campaign.","zh-TW":"在設計活動之前定義您的目標客群。"},{"en":"Our target demographic is professionals aged 25 to 40.","zh-TW":"我們的目標客群是25至40歲的專業人士。"}]', 'business idiom'),
('tear down silos', '打破部門壁壘；消除孤立', 'to break down barriers between departments that prevent information sharing and collaboration', '[{"en":"Our new CRM helps tear down silos between sales and marketing.","zh-TW":"我們的新CRM有助於打破銷售和行銷之間的壁壘。"},{"en":"Leadership must model cross-functional behavior to tear down silos.","zh-TW":"領導層必須以跨職能行為來消除孤立。"}]', 'expression'),
('thought experiment', '思想實驗；假設性思考', 'a hypothetical scenario used to explore ideas and their implications', '[{"en":"Let''s run a thought experiment: what if we doubled prices?","zh-TW":"讓我們進行一個思想實驗：如果我們把價格翻倍呢？"},{"en":"A thought experiment can reveal unexpected strategic options.","zh-TW":"思想實驗可以揭示意想不到的戰略選擇。"}]', 'expression'),
('through the lens of', '從…的角度；透過…的視角', 'viewing or evaluating something from a particular perspective or framework', '[{"en":"Evaluate the decision through the lens of customer value.","zh-TW":"從客戶價值的角度評估這個決定。"},{"en":"Through the lens of sustainability the choice is clear.","zh-TW":"從可持續性的視角來看選擇是明確的。"}]', 'prepositional phrase'),
('tier-one supplier', '一級供應商', 'a supplier that sells directly to the final manufacturer or company', '[{"en":"Tier-one suppliers must meet our quality and delivery standards.","zh-TW":"一級供應商必須達到我們的品質和交付標準。"},{"en":"We consolidated to fewer tier-one suppliers for better control.","zh-TW":"我們整合成較少的一級供應商以獲得更好的控制。"}]', 'business idiom'),
('trade-off analysis', '權衡分析；取捨分析', 'evaluating the costs and benefits of different options to find the best compromise', '[{"en":"A trade-off analysis showed cost and speed favor option B.","zh-TW":"權衡分析顯示成本和速度方面選項B更優。"},{"en":"Trade-off analysis helps teams make transparent decisions.","zh-TW":"取捨分析有助於團隊做出透明的決定。"}]', 'business idiom'),
('trigger point', '觸發點；臨界點', 'a specific event or condition that causes a process or reaction to begin', '[{"en":"The discount email was the trigger point for the purchase surge.","zh-TW":"折扣電子郵件是購買激增的觸發點。"},{"en":"Know the trigger points that move prospects from interest to action.","zh-TW":"了解將潛在客戶從興趣轉變為行動的觸發點。"}]', 'expression'),
('turn the corner', '轉機；渡過難關', 'to reach a point where a difficult situation begins to improve', '[{"en":"After two tough quarters we finally turned the corner.","zh-TW":"在兩個艱難的季度後我們終於迎來了轉機。"},{"en":"Turning the corner requires persistent effort and adaptability.","zh-TW":"渡過難關需要持續的努力和適應性。"}]', 'expression'),
('under contract', '在合約約束下；已簽合約', 'bound by the terms of a legal agreement', '[{"en":"The supplier is under contract until the end of the year.","zh-TW":"供應商在合約約束下直到年底。"},{"en":"Ensure all freelancers are under contract before work begins.","zh-TW":"確保所有自由職業者在工作開始前已簽合約。"}]', 'prepositional phrase'),
('unique selling point', '獨特賣點；核心競爭優勢', 'the feature or benefit that distinguishes a product or service from competitors', '[{"en":"Our unique selling point is same-day delivery anywhere in the city.","zh-TW":"我們的獨特賣點是城市任何地方的當天送達。"},{"en":"Know your unique selling point before entering a competitive pitch.","zh-TW":"在進行競爭性推介之前了解您的核心競爭優勢。"}]', 'business idiom'),
('up to speed', '了解情況；跟上進度', 'having the latest information or being current with developments', '[{"en":"Bring the new manager up to speed on the current project status.","zh-TW":"讓新經理了解當前項目的狀況。"},{"en":"A clear onboarding plan gets employees up to speed faster.","zh-TW":"清晰的入職計劃讓員工更快地跟上進度。"}]', 'prepositional phrase'),
('upstream process', '上游流程', 'earlier stages in a workflow or supply chain that feed into downstream activities', '[{"en":"Fixing the upstream process eliminated delays at assembly.","zh-TW":"改善上游流程消除了組裝階段的延誤。"},{"en":"Issues in the upstream process cascade into delivery problems.","zh-TW":"上游流程中的問題會波及到交付問題。"}]', 'business idiom'),
('user journey', '用戶旅程', 'the complete sequence of steps a user takes when interacting with a product or service', '[{"en":"Mapping the user journey revealed friction at checkout.","zh-TW":"繪製用戶旅程揭示了結帳時的摩擦點。"},{"en":"Optimize the user journey to reduce drop-off at each stage.","zh-TW":"優化用戶旅程以減少每個階段的流失。"}]', 'business idiom'),
('value creation', '價值創造', 'the process of delivering products or services that benefit customers and generate returns', '[{"en":"Our strategy centers on value creation for long-term shareholders.","zh-TW":"我們的策略以為長期股東創造價值為中心。"},{"en":"Value creation is the foundation of sustainable business.","zh-TW":"價值創造是可持續業務的基礎。"}]', 'business idiom'),
('velocity of change', '變化速度；改變的快慢', 'the speed at which change is occurring in an industry or organization', '[{"en":"The velocity of change in AI requires continuous learning.","zh-TW":"人工智慧領域的變化速度要求持續學習。"},{"en":"Organizations must increase agility to match the velocity of change.","zh-TW":"組織必須提高靈活性以跟上變化速度。"}]', 'expression'),
('vested interest', '既得利益；切身利益', 'a personal stake in an outcome, often influencing one''s objectivity', '[{"en":"Investors have a vested interest in the success of the merger.","zh-TW":"投資者對合並的成功有切身利益。"},{"en":"Acknowledge vested interests when presenting proposals.","zh-TW":"在提交提案時承認切身利益。"}]', 'expression'),
('vision statement', '願景宣言；企業願景', 'a brief aspirational description of what an organization hopes to achieve in the future', '[{"en":"Our vision statement guides every strategic decision we make.","zh-TW":"我們的願景宣言指導著我們做出的每一個戰略決策。"},{"en":"Align the team around the vision statement during planning.","zh-TW":"在規劃期間讓團隊圍繞企業願景保持一致。"}]', 'business idiom'),
('walk away from the table', '退出談判；離開談判桌', 'to leave a negotiation without reaching an agreement', '[{"en":"Know your minimum acceptable terms before you walk away from the table.","zh-TW":"在退出談判之前了解您的最低可接受條款。"},{"en":"Walking away from the table reset the dynamic in our favor.","zh-TW":"退出談判重置了有利於我們的談判動態。"}]', 'expression'),
('waste reduction', '減少浪費；廢棄物減量', 'the process of eliminating unnecessary use of resources, time, or materials', '[{"en":"Lean methods achieved significant waste reduction in our factory.","zh-TW":"精益方法在我們的工廠實現了顯著的廢棄物減量。"},{"en":"Waste reduction initiatives cut operating costs by 12%.","zh-TW":"減少浪費舉措將運營成本降低了12%。"}]', 'business idiom'),
('win-win outcome', '雙贏結果', 'a result that is beneficial for all parties involved', '[{"en":"A win-win outcome builds long-term relationships.","zh-TW":"雙贏結果建立了長期關係。"},{"en":"Seek a win-win outcome rather than maximizing at the other side''s expense.","zh-TW":"尋求雙贏結果而不是以犧牲另一方為代價最大化利益。"}]', 'expression'),
('workforce optimization', '勞動力優化；人力資源最佳化', 'aligning staff skills, schedules, and workloads to maximize productivity and efficiency', '[{"en":"Workforce optimization tools reduced overtime costs by 20%.","zh-TW":"勞動力優化工具將加班成本降低了20%。"},{"en":"Workforce optimization aligns headcount with business demand.","zh-TW":"人力資源最佳化將員工人數與業務需求相對應。"}]', 'business idiom'),
('year-over-year growth', '年同比增長；逐年增長', 'the comparison of a period''s performance with the same period in the previous year', '[{"en":"We posted 22% year-over-year growth in recurring revenue.","zh-TW":"我們的經常性收入實現了22%的年同比增長。"},{"en":"Year-over-year growth metrics matter more than month-to-month changes.","zh-TW":"年同比增長指標比月度變化更重要。"}]', 'business idiom'),
('yield to pressure', '屈服於壓力；讓步', 'to give in to demands or pressure from others', '[{"en":"Don''t yield to pressure when you know the terms are unacceptable.","zh-TW":"當您知道條款不可接受時不要屈服於壓力。"},{"en":"Yielding to pressure early sets a bad precedent.","zh-TW":"過早讓步設定了不好的先例。"}]', 'expression'),
('allocate resources', '分配資源', 'to distribute available resources such as money, time, or staff to various activities', '[{"en":"Allocate resources based on strategic impact, not seniority.","zh-TW":"根據戰略影響而不是資歷分配資源。"},{"en":"We need to allocate resources more effectively across teams.","zh-TW":"我們需要更有效地在各團隊之間分配資源。"}]', 'phrasal verb'),
('assess the damage', '評估損失；了解損害程度', 'to evaluate the negative consequences of a bad event or decision', '[{"en":"After the data breach we quickly moved to assess the damage.","zh-TW":"數據洩露後我們迅速開始評估損失。"},{"en":"Assessing the damage is the first step in any crisis response.","zh-TW":"評估損失是任何危機應對的第一步。"}]', 'expression'),
('baseline measurement', '基準測量；基線衡量', 'an initial data point used as a reference for measuring future progress', '[{"en":"Establish a baseline measurement before implementing any change.","zh-TW":"在實施任何更改之前建立基準測量。"},{"en":"Without a baseline measurement it is impossible to gauge improvement.","zh-TW":"沒有基線衡量就無法衡量改進。"}]', 'business idiom'),
('basis points', '基點', 'a unit of measure equal to one hundredth of a percentage point, used in finance', '[{"en":"The central bank raised rates by 25 basis points.","zh-TW":"央行將利率提高了25個基點。"},{"en":"A rise of 50 basis points significantly increases borrowing costs.","zh-TW":"上升50個基點顯著增加了借貸成本。"}]', 'business idiom'),
('below the line', '非常規行銷；線下行銷', 'marketing activities targeted at specific individuals rather than mass audiences', '[{"en":"Below the line campaigns like direct mail drove strong conversions.","zh-TW":"直郵等線下行銷活動帶動了強勁的轉化率。"},{"en":"Below the line activities allow for personalized messaging.","zh-TW":"線下行銷活動允許個性化訊息傳遞。"}]', 'business idiom'),
('bid and tender', '競標；投標', 'the process of submitting competitive proposals to win a contract or project', '[{"en":"We won the government bid and tender for infrastructure services.","zh-TW":"我們贏得了基礎設施服務的政府競標。"},{"en":"The bid and tender process required detailed cost breakdowns.","zh-TW":"競標過程需要詳細的成本明細。"}]', 'business idiom'),
('brand loyalty', '品牌忠誠度', 'the tendency of consumers to continue buying a particular brand over alternatives', '[{"en":"Brand loyalty reduces customer acquisition costs over time.","zh-TW":"品牌忠誠度隨著時間的推移降低了客戶獲取成本。"},{"en":"Reward programs are one of the best tools for building brand loyalty.","zh-TW":"獎勵計劃是建立品牌忠誠度的最佳工具之一。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('breakeven analysis', '損益平衡分析；盈虧平衡分析', 'the calculation of the point at which revenue equals costs and no profit or loss is made', '[{"en":"Breakeven analysis showed profitability within 18 months.","zh-TW":"損益平衡分析顯示18個月內可盈利。"},{"en":"Run a breakeven analysis before approving capital expenditure.","zh-TW":"在批准資本支出之前進行損益平衡分析。"}]', 'business idiom'),
('bridge the communication gap', '彌合溝通差距', 'to improve understanding and exchange between people or groups with different communication styles', '[{"en":"A liaison role helps bridge the communication gap between tech and business.","zh-TW":"聯絡角色幫助彌合技術和業務之間的溝通差距。"},{"en":"Regular cross-team meetings bridge the communication gap.","zh-TW":"定期的跨團隊會議彌合了溝通差距。"}]', 'expression'),
('build trust', '建立信任', 'to develop confidence and credibility in a relationship over time through consistent actions', '[{"en":"Consistent delivery is the fastest way to build trust with clients.","zh-TW":"一致的交付是與客戶建立信任最快的方式。"},{"en":"It takes years to build trust and seconds to destroy it.","zh-TW":"建立信任需要多年，摧毀它只需幾秒。"}]', 'phrasal verb'),
('business continuity plan', '業務持續計劃；緊急應變計劃', 'a strategy ensuring essential functions can continue during and after a disaster or disruption', '[{"en":"We tested our business continuity plan through simulation exercises.","zh-TW":"我們通過模擬演練測試了業務持續計劃。"},{"en":"Every department must have a business continuity plan in place.","zh-TW":"每個部門都必須有業務持續計劃。"}]', 'business idiom'),
('calibrate expectations', '校準預期；調整期望', 'to align what is expected with what is realistically possible', '[{"en":"Calibrate expectations at the start of every client engagement.","zh-TW":"在每次客戶合作開始時校準預期。"},{"en":"Underpromising and overdelivering is one way to calibrate expectations.","zh-TW":"承諾少但交付多是校準預期的一種方式。"}]', 'expression'),
('capitalize on trends', '利用趨勢；把握趨勢機會', 'to use emerging trends as an opportunity to grow or gain advantage', '[{"en":"Companies that capitalized on the remote work trend grew rapidly.","zh-TW":"利用遠程辦公趨勢的公司迅速成長。"},{"en":"Capitalize on sustainability trends to attract new customers.","zh-TW":"利用可持續性趨勢吸引新客戶。"}]', 'phrasal verb'),
('carry out due diligence', '進行盡職調查', 'to thoroughly research and verify facts before making a decision or investment', '[{"en":"We carry out due diligence on every potential acquisition target.","zh-TW":"我們對每個潛在的收購目標進行盡職調查。"},{"en":"Carry out due diligence before committing to a new vendor.","zh-TW":"在與新供應商合作前進行盡職調查。"}]', 'expression'),
('change management strategy', '變革管理策略', 'a structured approach for transitioning individuals and organizations to a desired future state', '[{"en":"A solid change management strategy ensures employee adoption.","zh-TW":"健全的變革管理策略確保員工採納。"},{"en":"Communication is the cornerstone of any change management strategy.","zh-TW":"溝通是任何變革管理策略的基石。"}]', 'business idiom'),
('co-invest', '共同投資；聯合投資', 'to invest jointly with another party, sharing both risk and potential returns', '[{"en":"We co-invested with the local partner to enter the Asian market.","zh-TW":"我們與當地合作夥伴共同投資進入了亞洲市場。"},{"en":"Co-investing reduces individual exposure to market risk.","zh-TW":"共同投資降低了個別投資者的市場風險敞口。"}]', 'phrasal verb'),
('competitive benchmarking', '競爭基準分析', 'evaluating your performance against that of direct competitors to identify gaps', '[{"en":"Competitive benchmarking revealed we lag behind in customer onboarding speed.","zh-TW":"競爭基準分析顯示我們在客戶入職速度上落後。"},{"en":"Competitive benchmarking should inform your product roadmap.","zh-TW":"競爭基準分析應該影響您的產品路線圖。"}]', 'business idiom'),
('contingency budget', '應急預算；備用預算', 'a reserve of funds set aside for unexpected expenses or emergencies', '[{"en":"Include a 10% contingency budget in all project plans.","zh-TW":"在所有項目計劃中納入10%的應急預算。"},{"en":"The contingency budget covered the unplanned equipment repair.","zh-TW":"應急預算涵蓋了計劃外的設備維修費用。"}]', 'business idiom'),
('conversion funnel', '轉化漏斗', 'the step-by-step process a prospect follows before becoming a paying customer', '[{"en":"Analyzing the conversion funnel showed a 40% drop at checkout.","zh-TW":"分析轉化漏斗顯示結帳時有40%的流失。"},{"en":"Simplify each stage of the conversion funnel to increase sign-ups.","zh-TW":"簡化轉化漏斗的每個階段以增加註冊。"}]', 'business idiom'),
('corporate culture', '企業文化；公司文化', 'the shared values, behaviors, and practices that define how an organization operates', '[{"en":"Corporate culture impacts talent retention and innovation.","zh-TW":"企業文化影響人才留存和創新。"},{"en":"The CEO sets the tone for corporate culture from the top.","zh-TW":"執行長從高層定下了企業文化的基調。"}]', 'business idiom'),
('decision-making framework', '決策框架', 'a structured approach for evaluating options and choosing among them', '[{"en":"Our decision-making framework considers cost, risk, and alignment.","zh-TW":"我們的決策框架考慮成本、風險和一致性。"},{"en":"A clear decision-making framework speeds up team consensus.","zh-TW":"清晰的決策框架加速了團隊共識。"}]', 'business idiom'),
('deliverable milestone', '可交付里程碑', 'a specific output or achievement marking a stage in a project timeline', '[{"en":"Each deliverable milestone requires sign-off before the next phase.","zh-TW":"每個可交付里程碑在進入下一階段之前需要簽署批准。"},{"en":"Track deliverable milestones in the project dashboard.","zh-TW":"在項目儀表板中跟蹤可交付里程碑。"}]', 'business idiom'),
('demand forecasting', '需求預測', 'the process of estimating future customer demand for products or services', '[{"en":"Accurate demand forecasting prevents stockouts and overstock.","zh-TW":"準確的需求預測防止缺貨和積壓。"},{"en":"We use AI-powered demand forecasting to optimize supply chains.","zh-TW":"我們使用AI驅動的需求預測優化供應鏈。"}]', 'business idiom'),
('deployment timeline', '部署時間表；上線計劃', 'the schedule for when a system, product, or plan will be launched or implemented', '[{"en":"The deployment timeline was pushed back due to testing delays.","zh-TW":"由於測試延誤部署時間表被推遲了。"},{"en":"Share the deployment timeline with all affected teams.","zh-TW":"與所有受影響的團隊分享部署時間表。"}]', 'business idiom'),
('discussion paper', '討論文件；諮詢文件', 'a document presenting ideas or proposals for discussion rather than as final decisions', '[{"en":"We circulated a discussion paper on restructuring options.","zh-TW":"我們分發了關於重組選項的討論文件。"},{"en":"The discussion paper invited feedback from all managers.","zh-TW":"討論文件邀請了所有管理人員的反饋。"}]', 'business idiom'),
('document best practices', '記錄最佳實踐', 'to write down the most effective methods or procedures for future reference', '[{"en":"Document best practices after successful campaigns.","zh-TW":"在成功的活動後記錄最佳實踐。"},{"en":"Documented best practices reduce ramp-up time for new staff.","zh-TW":"記錄的最佳實踐減少了新員工的磨合時間。"}]', 'phrasal verb'),
('due for renewal', '即將到期；需要續約', 'a contract or agreement that is approaching its expiration and needs to be renewed', '[{"en":"All annual service contracts due for renewal will be reviewed.","zh-TW":"所有即將到期的年度服務合約將被審查。"},{"en":"Reach out 90 days before a contract is due for renewal.","zh-TW":"在合約即將到期前90天聯繫客戶。"}]', 'prepositional phrase'),
('efficient allocation', '有效分配；高效配置', 'distributing resources in a way that maximizes output or value', '[{"en":"Efficient allocation of capital is the CFO''s primary responsibility.","zh-TW":"資本的有效分配是財務長的主要職責。"},{"en":"Efficient allocation requires clear visibility into demand.","zh-TW":"有效配置需要對需求有清晰的能見度。"}]', 'expression'),
('embed in the culture', '融入文化；根植於文化', 'to make a practice or value a permanent part of an organization''s way of operating', '[{"en":"We worked to embed continuous improvement in the culture.","zh-TW":"我們致力於將持續改進融入文化中。"},{"en":"Safety is embedded in the culture at every level of operations.","zh-TW":"安全在各個運營層面都根植於文化中。"}]', 'expression'),
('empower decision-making', '賦予決策權；授權決策', 'to give individuals or teams the authority and tools to make decisions on their own', '[{"en":"Empowering decision-making at the front line speeds up response times.","zh-TW":"在一線賦予決策權加快了反應時間。"},{"en":"Leaders who empower decision-making build stronger teams.","zh-TW":"授權決策的領導者建立了更強大的團隊。"}]', 'expression'),
('escalation path', '升級路徑；問題上報流程', 'the defined route through which unresolved issues are passed to higher authority', '[{"en":"Every support team must have a clear escalation path.","zh-TW":"每個支持團隊必須有清晰的問題上報流程。"},{"en":"Follow the escalation path to resolve disputes quickly.","zh-TW":"遵循升級路徑快速解決爭議。"}]', 'business idiom'),
('executive sponsorship', '高管贊助；高層支持', 'support from a senior leader who champions a project and removes obstacles', '[{"en":"Executive sponsorship was crucial to the digital transformation success.","zh-TW":"高管贊助對數字化轉型的成功至關重要。"},{"en":"Without executive sponsorship cross-functional projects stall.","zh-TW":"沒有高層支持跨職能項目會停滯不前。"}]', 'business idiom'),
('exit interview', '離職面談', 'a meeting with a departing employee to gather feedback on their experience', '[{"en":"Exit interviews provide honest insights into company culture gaps.","zh-TW":"離職面談提供了對公司文化差距的誠實見解。"},{"en":"Use exit interview data to improve retention strategies.","zh-TW":"使用離職面談數據改善留才策略。"}]', 'business idiom'),
('face-to-face meeting', '面對面會議；當面會談', 'a meeting where participants are physically present together rather than communicating remotely', '[{"en":"A face-to-face meeting built trust faster than video calls.","zh-TW":"面對面會議比視訊會議更快地建立了信任。"},{"en":"For complex negotiations a face-to-face meeting is essential.","zh-TW":"對於複雜的談判面對面會談是必要的。"}]', 'expression'),
('feedback mechanism', '反饋機制', 'a system or process for collecting and acting on feedback from stakeholders or users', '[{"en":"Our NPS survey is the primary feedback mechanism for service quality.","zh-TW":"我們的NPS調查是服務品質的主要反饋機制。"},{"en":"A strong feedback mechanism accelerates product iteration.","zh-TW":"強大的反饋機制加速了產品迭代。"}]', 'business idiom'),
('field-test', '實地測試；現場驗證', 'to test a product or process in real-world conditions before full deployment', '[{"en":"We field-tested the device in extreme temperatures before launch.","zh-TW":"我們在上市前在極端溫度下對設備進行了實地測試。"},{"en":"Field-testing revealed usability issues not found in the lab.","zh-TW":"實地測試揭示了實驗室中未發現的易用性問題。"}]', 'phrasal verb'),
('financial due diligence', '財務盡職調查', 'an in-depth review of a company''s financial records before a transaction or investment', '[{"en":"Financial due diligence uncovered significant undisclosed liabilities.","zh-TW":"財務盡職調查發現了重大未披露負債。"},{"en":"Never skip financial due diligence no matter how trusted the partner.","zh-TW":"無論合作夥伴多麼值得信任都不要跳過財務盡職調查。"}]', 'business idiom'),
('first-mover disadvantage', '先行者劣勢', 'the costs and risks borne by the first company to enter a market, which later entrants avoid', '[{"en":"First-mover disadvantage meant we spent years educating the market.","zh-TW":"先行者劣勢意味著我們花了數年時間教育市場。"},{"en":"Weigh first-mover disadvantage against the opportunity before entering early.","zh-TW":"在提早進入之前衡量先行者劣勢與機會。"}]', 'business idiom'),
('flag as a priority', '標記為優先事項；列為首要任務', 'to mark or designate something as needing immediate attention or resources', '[{"en":"Flag the delivery delay as a priority before it escalates.","zh-TW":"在問題升級之前將交付延誤標記為優先事項。"},{"en":"The compliance team flagged the audit finding as a priority.","zh-TW":"合規團隊將審計發現列為首要任務。"}]', 'expression'),
('follow-up action', '後續行動；跟進措施', 'steps taken after a meeting, discussion, or event to advance progress', '[{"en":"Document follow-up actions with owners and deadlines after every meeting.","zh-TW":"每次會議後記錄帶有負責人和截止日期的後續行動。"},{"en":"Follow-up action within 24 hours shows professionalism.","zh-TW":"24小時內的跟進行動展現了專業素養。"}]', 'expression'),
('free cash flow', '自由現金流', 'the cash a company generates after accounting for capital expenditures', '[{"en":"Strong free cash flow gives us the flexibility to invest in growth.","zh-TW":"強劲的自由現金流給了我們投資增長的靈活性。"},{"en":"Investors pay close attention to free cash flow as a health indicator.","zh-TW":"投資者密切關注自由現金流作為健康指標。"}]', 'business idiom'),
('fulfill obligations', '履行義務', 'to complete or carry out duties, commitments, or legal requirements', '[{"en":"We fulfilled all obligations under the service agreement on time.","zh-TW":"我們按時履行了服務協議下的所有義務。"},{"en":"Failing to fulfill obligations can result in financial penalties.","zh-TW":"未能履行義務可能導致財務罰款。"}]', 'phrasal verb'),
('gain momentum', '獲得動力；勢頭增強', 'to steadily increase in speed, strength, or support over time', '[{"en":"The product launch gained momentum after early positive reviews.","zh-TW":"早期正面評價後產品上市勢頭增強。"},{"en":"Use early wins to gain momentum for broader adoption.","zh-TW":"利用早期勝利為更廣泛的採用獲得動力。"}]', 'phrasal verb'),
('get to the point', '說重點；直接切入主題', 'to communicate the most important information without unnecessary preamble', '[{"en":"In a 15-minute meeting always get to the point immediately.","zh-TW":"在15分鐘的會議中始終立即說重點。"},{"en":"Executives appreciate emails that get to the point.","zh-TW":"高管欣賞直接切入主題的電子郵件。"}]', 'expression'),
('go-to-market plan', '市場進入計劃；上市策略', 'the strategy for launching a product to the target market effectively', '[{"en":"Our go-to-market plan targeted early adopters in the tech sector.","zh-TW":"我們的市場進入計劃針對了科技行業的早期採用者。"},{"en":"A strong go-to-market plan coordinates sales and marketing.","zh-TW":"強大的上市策略協調了銷售和行銷。"}]', 'business idiom'),
('implementation gap', '執行差距；落實差距', 'the difference between what a strategy intends and what is actually executed', '[{"en":"The implementation gap was caused by unclear ownership of tasks.","zh-TW":"執行差距是由任務所有權不清晰造成的。"},{"en":"Tracking metrics weekly helps close the implementation gap.","zh-TW":"每週跟蹤指標有助於縮小落實差距。"}]', 'business idiom'),
('in parallel', '同時進行；並行', 'at the same time as something else, rather than one after another', '[{"en":"Run testing and documentation in parallel to shorten delivery time.","zh-TW":"同時進行測試和文件編寫以縮短交付時間。"},{"en":"Managing two projects in parallel requires careful coordination.","zh-TW":"並行管理兩個項目需要仔細協調。"}]', 'prepositional phrase'),
('intellectual capital', '智識資本；知識資本', 'the intangible value of a company''s knowledge, expertise, and intellectual assets', '[{"en":"Our intellectual capital is protected through patents and trade secrets.","zh-TW":"我們的知識資本通過專利和商業秘密受到保護。"},{"en":"Investing in talent builds the intellectual capital of the organization.","zh-TW":"投資人才建立了組織的知識資本。"}]', 'business idiom'),
('inventory management', '庫存管理', 'the process of ordering, storing, and controlling goods to meet demand efficiently', '[{"en":"Effective inventory management cuts carrying costs by 20%.","zh-TW":"有效的庫存管理將持有成本降低了20%。"},{"en":"Real-time data improves inventory management accuracy.","zh-TW":"實時數據提高了庫存管理的準確性。"}]', 'business idiom'),
('kickstart', '啟動；推動', 'to cause something to start or be reinvigorated with extra effort or a fresh impetus', '[{"en":"We kickstarted growth by launching a referral incentive program.","zh-TW":"我們通過推出推薦激勵計劃啟動了增長。"},{"en":"The government grant kickstarted the startup''s product development.","zh-TW":"政府補助金推動了初創公司的產品開發。"}]', 'phrasal verb'),
('lean methodology', '精益方法論', 'a management philosophy focused on minimizing waste while maximizing value delivery', '[{"en":"Lean methodology helped us cut production cycle time by 30%.","zh-TW":"精益方法論幫助我們將生產週期時間縮短了30%。"},{"en":"Training staff in lean methodology yields measurable efficiency gains.","zh-TW":"培訓員工掌握精益方法論帶來了可衡量的效率提升。"}]', 'business idiom'),
('line of business', '業務線；業務部門', 'a specific product or service area within a larger organization', '[{"en":"We launched cloud services as a new line of business.","zh-TW":"我們推出了雲服務作為新的業務線。"},{"en":"Each line of business has its own P&L and leadership team.","zh-TW":"每個業務線都有自己的損益表和領導團隊。"}]', 'business idiom'),
('market consolidation', '市場整合', 'the process by which a market becomes dominated by fewer, larger players through mergers and exits', '[{"en":"Market consolidation reduced our main competitors from ten to three.","zh-TW":"市場整合將我們的主要競爭對手從十個減少到三個。"},{"en":"During market consolidation scale becomes a critical advantage.","zh-TW":"在市場整合過程中規模成為關鍵優勢。"}]', 'business idiom'),
('market share gain', '市場份額增長', 'the increase in a company''s portion of total sales within its market', '[{"en":"Our product innovation drove a 5-point market share gain last year.","zh-TW":"我們的產品創新去年推動了5個百分點的市場份額增長。"},{"en":"Aggressive pricing resulted in significant market share gains.","zh-TW":"積極的定價策略帶來了顯著的市場份額增長。"}]', 'business idiom'),
('milestone review', '里程碑評審', 'a formal assessment conducted at each major stage of a project to verify progress', '[{"en":"A milestone review confirmed we were on track for the Q3 launch.","zh-TW":"里程碑評審確認了我們按計劃進行第三季度的上市。"},{"en":"Use milestone reviews to realign if scope has changed.","zh-TW":"如果範圍發生了變化請使用里程碑評審重新調整。"}]', 'business idiom'),
('minimum viable product', '最小可行產品', 'the simplest version of a product that delivers core value and can be tested with users', '[{"en":"We launched a minimum viable product to test demand before full investment.","zh-TW":"我們在全面投資之前推出了最小可行產品測試需求。"},{"en":"A minimum viable product lets you learn without building everything first.","zh-TW":"最小可行產品讓您在不先構建一切的情況下學習。"}]', 'business idiom'),
('mission critical', '關鍵任務；核心關鍵', 'describing a system or component whose failure would halt essential operations', '[{"en":"Backup power is mission critical for our data center.","zh-TW":"備用電源對我們的數據中心至關重要。"},{"en":"Mission critical software requires 99.99% uptime.","zh-TW":"關鍵任務軟體需要99.99%的正常運行時間。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('morale booster', '士氣提振；振奮人心之舉', 'an action, event, or reward that increases motivation and positive energy in a team', '[{"en":"Celebrating small wins is a powerful morale booster.","zh-TW":"慶祝小勝利是強大的士氣提振措施。"},{"en":"A team outing worked as a morale booster after a stressful quarter.","zh-TW":"在壓力大的季度後團隊外出活動起到了振奮人心的作用。"}]', 'expression'),
('onboard a client', '客戶入職；接洽新客戶', 'to guide a new client through the initial setup and orientation to your products or services', '[{"en":"We onboard each new client with a dedicated success manager.","zh-TW":"我們為每個新客戶配備專屬的成功經理進行入職引導。"},{"en":"A smooth onboarding process reduces early churn.","zh-TW":"順暢的客戶入職流程減少了早期流失。"}]', 'phrasal verb'),
('operating leverage', '經營槓桿', 'the degree to which fixed costs amplify profit changes relative to revenue changes', '[{"en":"High operating leverage means profits grow faster than revenue.","zh-TW":"高經營槓桿意味著利潤增長快於收入。"},{"en":"Software companies often have strong operating leverage.","zh-TW":"軟體公司通常具有強大的經營槓桿。"}]', 'business idiom'),
('organic reach', '自然觸及；有機觸及', 'the number of people who see content without paid promotion', '[{"en":"Our organic reach doubled after consistently publishing educational content.","zh-TW":"持續發布教育性內容後我們的自然觸及翻了一番。"},{"en":"Build organic reach before investing heavily in paid advertising.","zh-TW":"在大量投資付費廣告之前先建立有機觸及。"}]', 'business idiom'),
('outcome-based contract', '以結果為基礎的合約', 'an agreement where payment is tied to achieving specific measurable results', '[{"en":"Our outcome-based contract ties fees to measurable KPIs.","zh-TW":"我們以結果為基礎的合約將費用與可衡量的KPI掛鉤。"},{"en":"Outcome-based contracts align vendor incentives with client success.","zh-TW":"以結果為基礎的合約使供應商激勵與客戶成功保持一致。"}]', 'business idiom'),
('payback period', '回收期；投資回收期', 'the time required to recover the cost of an investment from its net cash inflows', '[{"en":"The payback period for the new equipment is 18 months.","zh-TW":"新設備的投資回收期為18個月。"},{"en":"A shorter payback period reduces investment risk.","zh-TW":"較短的回收期降低了投資風險。"}]', 'business idiom'),
('performance appraisal', '績效考核；工作評估', 'a formal evaluation of an employee''s performance, usually conducted annually', '[{"en":"Performance appraisals help align individual goals with company objectives.","zh-TW":"績效考核有助於將個人目標與公司目標保持一致。"},{"en":"Provide specific examples during a performance appraisal.","zh-TW":"在績效考核期間提供具體例子。"}]', 'business idiom'),
('put on the table', '提出；擺上台面', 'to formally introduce or offer something for consideration in a discussion', '[{"en":"We put a 10% discount on the table to close the deal faster.","zh-TW":"我們提出了10%的折扣以更快地達成交易。"},{"en":"All options should be put on the table before a final decision.","zh-TW":"在做出最終決定之前應將所有選項擺上台面。"}]', 'expression'),
('quality assurance', '品質保證', 'systematic processes to ensure products or services meet defined standards', '[{"en":"Quality assurance processes reduced defect rates by 40%.","zh-TW":"品質保證流程將缺陷率降低了40%。"},{"en":"Quality assurance must be built into every stage of development.","zh-TW":"品質保證必須融入開發的每個階段。"}]', 'business idiom'),
('quarterly business review', '季度業務審查', 'a regular meeting where performance, challenges, and plans are reviewed with clients or leadership', '[{"en":"A quarterly business review strengthens the partnership with major clients.","zh-TW":"季度業務審查加強了與主要客戶的合作關係。"},{"en":"Use a quarterly business review to realign on strategic priorities.","zh-TW":"利用季度業務審查重新調整戰略優先事項。"}]', 'business idiom'),
('reduce friction', '減少阻力；降低摩擦', 'to remove barriers or difficulties that slow down a process or user experience', '[{"en":"Simplifying checkout reduced friction and improved conversion.","zh-TW":"簡化結帳減少了阻力並提高了轉化率。"},{"en":"Reduce friction in the onboarding flow to drive faster adoption.","zh-TW":"減少入職流程中的阻力以推動更快的採用。"}]', 'phrasal verb'),
('request for proposal', '建議書邀請；招標書', 'a formal document issued by an organization asking vendors to submit proposals for a service', '[{"en":"We submitted a comprehensive response to the request for proposal.","zh-TW":"我們提交了對建議書邀請的全面回應。"},{"en":"A well-crafted request for proposal attracts higher-quality vendors.","zh-TW":"精心制定的招標書吸引了更高品質的供應商。"}]', 'business idiom'),
('return on equity', '股東權益報酬率', 'a measure of profitability showing how much profit is generated per unit of equity', '[{"en":"Strong return on equity signals effective use of shareholder capital.","zh-TW":"強勁的股東權益報酬率表明股東資本的有效利用。"},{"en":"Investors compare return on equity across competitors to find value.","zh-TW":"投資者比較各競爭對手的股東權益報酬率以尋找價值。"}]', 'business idiom'),
('risk mitigation plan', '風險緩解計劃', 'a strategy for reducing the likelihood or impact of identified risks', '[{"en":"A risk mitigation plan was approved before construction began.","zh-TW":"施工開始之前批准了風險緩解計劃。"},{"en":"Update the risk mitigation plan whenever new threats are identified.","zh-TW":"每當識別出新威脅時更新風險緩解計劃。"}]', 'business idiom'),
('root cause', '根本原因；根源', 'the fundamental underlying reason for a problem rather than its surface symptoms', '[{"en":"We identified the root cause of the defect as inconsistent supplier quality.","zh-TW":"我們將缺陷的根本原因確定為供應商品質不一致。"},{"en":"Fix the root cause, not just the symptoms, of operational problems.","zh-TW":"解決運營問題的根本原因而不僅僅是症狀。"}]', 'business idiom'),
('sales cycle', '銷售週期', 'the series of steps from first contact with a prospect to closing a deal', '[{"en":"A clear ROI case shortens the sales cycle considerably.","zh-TW":"清晰的投資回報案例大大縮短了銷售週期。"},{"en":"Track conversion at every stage of the sales cycle.","zh-TW":"在銷售週期的每個階段跟蹤轉化。"}]', 'business idiom'),
('scale operations', '擴大運營規模；規模化', 'to increase the capacity and reach of a business process to handle more volume', '[{"en":"We scaled operations from 5 to 50 countries in three years.","zh-TW":"我們在三年內將業務規模從5個國家擴展到了50個國家。"},{"en":"Automation is key to scaling operations without proportional cost increases.","zh-TW":"自動化是在不按比例增加成本的情況下規模化運營的關鍵。"}]', 'phrasal verb'),
('secondary market', '二級市場', 'a market where previously issued securities or goods are bought and sold between investors', '[{"en":"The bond rallied in the secondary market after the credit upgrade.","zh-TW":"信用評級上調後債券在二級市場上漲。"},{"en":"Secondary market activity reflects investor confidence in the company.","zh-TW":"二級市場活動反映了投資者對公司的信心。"}]', 'business idiom'),
('segment the market', '細分市場', 'to divide the market into distinct groups with similar characteristics or needs', '[{"en":"We segmented the market by purchase frequency to target high-value customers.","zh-TW":"我們按購買頻率細分市場以針對高價值客戶。"},{"en":"Segmenting the market allows for more personalized marketing.","zh-TW":"細分市場使更個性化的行銷成為可能。"}]', 'phrasal verb'),
('share of wallet', '錢包份額；客戶總消費佔比', 'the percentage of a customer''s total spending in a category that goes to your company', '[{"en":"Cross-selling grew our share of wallet from 20% to 35%.","zh-TW":"交叉銷售使我們的錢包份額從20%增加到了35%。"},{"en":"Focus on share of wallet to grow revenue from existing accounts.","zh-TW":"關注錢包份額以從現有帳戶增加收入。"}]', 'business idiom'),
('stakeholder management', '利害關係人管理', 'the process of identifying and engaging people who are affected by or influence a project', '[{"en":"Effective stakeholder management prevented conflict during the merger.","zh-TW":"有效的利害關係人管理防止了合併期間的衝突。"},{"en":"Map all stakeholders and their influence before the project starts.","zh-TW":"在項目開始之前繪製所有利害關係人及其影響力。"}]', 'business idiom'),
('statement of work', '工作說明書', 'a document describing the scope, deliverables, and timeline for a contracted project', '[{"en":"A clear statement of work prevents scope creep.","zh-TW":"清晰的工作說明書防止了範圍蔓延。"},{"en":"Both parties signed the statement of work before work began.","zh-TW":"雙方在工作開始之前簽署了工作說明書。"}]', 'business idiom'),
('streamline the process', '簡化流程；精簡程序', 'to make a process more efficient by removing unnecessary steps', '[{"en":"We streamlined the approval process from five steps to two.","zh-TW":"我們將審批流程從五個步驟簡化為兩個。"},{"en":"Streamlining the process cut order processing time by half.","zh-TW":"簡化流程將訂單處理時間縮短了一半。"}]', 'phrasal verb'),
('technical debt', '技術債；技術欠債', 'the cost of future rework caused by taking shortcuts in software development', '[{"en":"Accumulating technical debt slows down future feature development.","zh-TW":"積累技術債會減慢未來功能開發速度。"},{"en":"Allocate 20% of each sprint to reducing technical debt.","zh-TW":"分配每個衝刺20%的時間來減少技術債。"}]', 'business idiom'),
('total cost of ownership', '總擁有成本', 'all direct and indirect costs incurred over the entire lifecycle of an asset or service', '[{"en":"Total cost of ownership analysis showed the cheaper option was more expensive long-term.","zh-TW":"總擁有成本分析顯示較便宜的選項長期來看更貴。"},{"en":"Always present total cost of ownership when evaluating vendor proposals.","zh-TW":"評估供應商提案時始終呈現總擁有成本。"}]', 'business idiom'),
('upsell opportunity', '追加銷售機會；升級銷售機會', 'a chance to persuade an existing customer to buy a higher-value product or service', '[{"en":"The annual review uncovered several upsell opportunities.","zh-TW":"年度評審發現了幾個追加銷售機會。"},{"en":"Train support staff to recognize upsell opportunities.","zh-TW":"培訓支持人員識別升級銷售機會。"}]', 'business idiom'),
('upward mobility', '向上流動；晉升機會', 'the ability to advance to higher positions or greater success in a career or organization', '[{"en":"Clear career paths and upward mobility reduce staff turnover.","zh-TW":"清晰的職業路徑和晉升機會減少了員工流失。"},{"en":"Promote upward mobility to create a high-performance culture.","zh-TW":"促進向上流動以創建高績效文化。"}]', 'expression'),
('user-centric design', '以用戶為中心的設計', 'a design philosophy that prioritizes the needs, preferences, and behaviors of end users', '[{"en":"User-centric design led to a 50% increase in app engagement.","zh-TW":"以用戶為中心的設計使應用程式參與度提高了50%。"},{"en":"Interview real users before finalizing user-centric design decisions.","zh-TW":"在最終確定以用戶為中心的設計決策之前採訪真實用戶。"}]', 'business idiom'),
('value-added service', '增值服務', 'an extra service provided beyond the core offering to increase its value to the customer', '[{"en":"Free training is a value-added service that increases retention.","zh-TW":"免費培訓是增加留存率的增值服務。"},{"en":"Bundle value-added services to justify a premium price.","zh-TW":"捆綁增值服務以證明溢價的合理性。"}]', 'business idiom'),
('vendor evaluation', '供應商評估', 'the process of assessing suppliers against defined criteria before selection or renewal', '[{"en":"Vendor evaluation includes financial stability, capacity, and quality metrics.","zh-TW":"供應商評估包括財務穩定性、產能和品質指標。"},{"en":"Run a vendor evaluation annually to ensure continued performance.","zh-TW":"每年進行供應商評估以確保持續的績效。"}]', 'business idiom'),
('workforce planning', '人力規劃；人力資源規劃', 'the strategic process of aligning workforce capacity with current and future business needs', '[{"en":"Workforce planning identified a critical shortage in data engineering.","zh-TW":"人力規劃確定了數據工程的嚴重短缺。"},{"en":"Use workforce planning to anticipate hiring needs 12 months ahead.","zh-TW":"使用人力規劃提前12個月預測招聘需求。"}]', 'business idiom'),
('year-end review', '年終回顧；年末盤點', 'a comprehensive assessment of performance, achievements, and challenges at the end of a fiscal year', '[{"en":"The year-end review highlighted our strongest performing product lines.","zh-TW":"年終回顧突出了我們表現最好的產品線。"},{"en":"Use the year-end review to celebrate wins and set next year''s goals.","zh-TW":"利用年末盤點慶祝勝利並設定明年的目標。"}]', 'expression'),
('zero defects', '零缺陷', 'a quality management goal of eliminating all defects from production or service delivery', '[{"en":"Our zero defects policy raised customer satisfaction scores significantly.","zh-TW":"我們的零缺陷政策顯著提高了客戶滿意度分數。"},{"en":"Zero defects requires continuous process monitoring and improvement.","zh-TW":"零缺陷需要持續的過程監控和改進。"}]', 'business idiom'),
('zone in on', '聚焦於；集中關注', 'to direct one''s focus to a specific area or detail', '[{"en":"Zone in on the top three revenue drivers for this quarter.","zh-TW":"聚焦於本季度前三大收入驅動因素。"},{"en":"During the meeting zone in on decisions that need immediate resolution.","zh-TW":"在會議期間集中關注需要立即解決的決定。"}]', 'phrasal verb'),
('above the fold', '首屏位置；頭版顯眼位置', 'the portion of a webpage or document visible without scrolling; the most prominent position', '[{"en":"Put the call-to-action above the fold for maximum visibility.","zh-TW":"將行動號召放在首屏位置以獲得最大曝光。"},{"en":"Above-the-fold placement commands a premium in digital advertising.","zh-TW":"首屏位置在數位廣告中需要溢價。"}]', 'expression'),
('accounts payable', '應付帳款', 'money owed by a company to its suppliers for goods or services received but not yet paid', '[{"en":"Optimizing accounts payable extended our payment cycle by 15 days.","zh-TW":"優化應付帳款將我們的付款週期延長了15天。"},{"en":"Accounts payable automation reduces manual processing errors.","zh-TW":"應付帳款自動化減少了手動處理錯誤。"}]', 'business idiom'),
('accounts receivable', '應收帳款', 'money owed to a company by its customers for goods or services delivered but not yet paid', '[{"en":"Slow accounts receivable collection hurt our working capital.","zh-TW":"緩慢的應收帳款收款損害了我們的營運資金。"},{"en":"We offer early payment discounts to accelerate accounts receivable.","zh-TW":"我們提供提前付款折扣以加速應收帳款回收。"}]', 'business idiom'),
('adopt a framework', '採用框架；應用方法論', 'to implement a structured approach or system for solving problems or making decisions', '[{"en":"We adopted an OKR framework to align goals across the company.","zh-TW":"我們採用了OKR框架來對齊公司各層級的目標。"},{"en":"Adopting a risk framework improved our project governance.","zh-TW":"採用風險框架改善了我們的項目治理。"}]', 'phrasal verb'),
('all-in cost', '全包成本；總成本', 'the complete cost including all fees, overhead, and hidden charges', '[{"en":"The all-in cost of hiring includes salary, benefits, and onboarding.","zh-TW":"招聘的全包成本包括薪資、福利和入職培訓。"},{"en":"Present the all-in cost so clients are not surprised later.","zh-TW":"呈現全包成本讓客戶之後不會感到意外。"}]', 'business idiom'),
('annual recurring revenue', '年度經常性收入', 'the predictable revenue a business expects to receive each year from subscriptions or contracts', '[{"en":"Annual recurring revenue grew 40% after improving the subscription model.","zh-TW":"改善訂閱模式後年度經常性收入增長了40%。"},{"en":"Annual recurring revenue is a key SaaS health metric.","zh-TW":"年度經常性收入是SaaS健康狀況的關鍵指標。"}]', 'business idiom'),
('approval workflow', '審批流程；批核工作流程', 'the defined sequence of review and sign-off steps required to complete an action', '[{"en":"Automating the approval workflow reduced cycle time from days to hours.","zh-TW":"自動化審批流程將週期時間從幾天縮短到了幾個小時。"},{"en":"A clear approval workflow avoids ambiguity about who decides.","zh-TW":"清晰的審批流程避免了關於誰決策的模糊性。"}]', 'business idiom'),
('asset utilization', '資產利用率', 'a measure of how efficiently a company uses its assets to generate revenue', '[{"en":"Asset utilization improved after we switched to a shared equipment model.","zh-TW":"轉向共享設備模式後資產利用率提高了。"},{"en":"Track asset utilization monthly to identify inefficiencies.","zh-TW":"每月跟蹤資產利用率以識別低效率。"}]', 'business idiom'),
('balanced scorecard', '平衡計分卡', 'a strategic management tool measuring performance across financial, customer, process, and learning dimensions', '[{"en":"The balanced scorecard gave a holistic view of organizational health.","zh-TW":"平衡計分卡提供了組織健康狀況的全面視角。"},{"en":"Align KPIs to each dimension of the balanced scorecard.","zh-TW":"將KPI與平衡計分卡的每個維度對齊。"}]', 'business idiom'),
('bandwidth constraints', '資源限制；容量限制', 'limits on the time, energy, or people available to take on additional work', '[{"en":"Bandwidth constraints forced us to delay two initiatives.","zh-TW":"資源限制迫使我們推遲了兩個舉措。"},{"en":"Be transparent about bandwidth constraints when accepting new projects.","zh-TW":"在接受新項目時對資源限制保持透明。"}]', 'expression'),
('be on the same page', '意見一致；達成共識', 'to have the same understanding or agreement as others in a group', '[{"en":"Before starting the project we need to be on the same page about scope.","zh-TW":"在開始項目之前我們需要就範圍達成共識。"},{"en":"A kick-off call ensures all teams are on the same page.","zh-TW":"啟動電話確保所有團隊意見一致。"}]', 'expression'),
('below budget', '低於預算；節省開支', 'spending less than the amount allocated for a task or project', '[{"en":"The construction project came in 8% below budget.","zh-TW":"建設項目比預算低了8%。"},{"en":"Finishing below budget earned the team a performance bonus.","zh-TW":"低於預算完成為團隊贏得了績效獎金。"}]', 'prepositional phrase'),
('brand architecture', '品牌架構', 'the organized structure of a company''s brand portfolio and how they relate to each other', '[{"en":"A clear brand architecture reduces customer confusion in the market.","zh-TW":"清晰的品牌架構減少了市場上的客戶困惑。"},{"en":"After the merger we redesigned the brand architecture for clarity.","zh-TW":"合並後我們重新設計了品牌架構以提高清晰度。"}]', 'business idiom'),
('build a case', '建立論據；積累佐證', 'to gather evidence and arguments to support a proposal or decision', '[{"en":"Build a case with data before requesting additional headcount.","zh-TW":"在申請增加人手之前用數據建立論據。"},{"en":"A well-built case speeds up executive approval.","zh-TW":"充分的論據加速了高管批准。"}]', 'expression'),
('business acumen', '商業敏銳度；商業頭腦', 'a keen understanding of business principles and the ability to make sound commercial decisions', '[{"en":"Strong business acumen distinguishes great leaders from good managers.","zh-TW":"強大的商業敏銳度將優秀領導者與優秀管理者區分開來。"},{"en":"Develop business acumen by studying P&L statements and strategy cases.","zh-TW":"通過研究損益表和戰略案例培養商業頭腦。"}]', 'expression'),
('business intelligence', '商業智能', 'data analysis tools and processes that help organizations make better decisions', '[{"en":"Business intelligence dashboards give leadership real-time visibility.","zh-TW":"商業智能儀表板為領導層提供了實時可見度。"},{"en":"Investing in business intelligence paid off with faster and better decisions.","zh-TW":"投資商業智能帶來了更快更好的決策回報。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('C-suite buy-in', '高管層認可；執行委員會支持', 'agreement and support from the highest executives in an organization', '[{"en":"C-suite buy-in is essential for any large-scale transformation.","zh-TW":"C-suite buy-in對任何大規模轉型都是必不可少的。"},{"en":"Present the business case in financial terms to gain C-suite buy-in.","zh-TW":"以財務術語呈現業務案例以獲得高管層認可。"}]', 'expression'),
('call to action', '行動號召', 'a prompt that encourages an audience to take a specific next step', '[{"en":"Every email campaign should have a single clear call to action.","zh-TW":"每個電子郵件活動都應該有一個清晰的行動號召。"},{"en":"A compelling call to action increased our click-through rate by 35%.","zh-TW":"引人注目的行動號召使我們的點擊率提高了35%。"}]', 'expression'),
('capital allocation', '資本分配', 'the process of deciding where to invest or deploy available financial resources', '[{"en":"Disciplined capital allocation is a hallmark of great management teams.","zh-TW":"嚴格的資本分配是優秀管理團隊的標誌。"},{"en":"Review capital allocation annually against strategic priorities.","zh-TW":"每年根據戰略優先事項審查資本分配。"}]', 'business idiom'),
('cash conversion cycle', '現金轉換週期', 'the number of days it takes to convert investments in inventory into cash from sales', '[{"en":"Improving collections reduced our cash conversion cycle by 10 days.","zh-TW":"改善收款將我們的現金轉換週期縮短了10天。"},{"en":"A short cash conversion cycle improves liquidity and financial health.","zh-TW":"較短的現金轉換週期改善了流動性和財務健康。"}]', 'business idiom'),
('client retention', '客戶留存；留住客戶', 'the ability to keep existing customers and prevent them from switching to competitors', '[{"en":"Client retention is five times cheaper than acquiring new customers.","zh-TW":"留住客戶比獲取新客戶便宜五倍。"},{"en":"We measure client retention rate quarterly across all segments.","zh-TW":"我們每季度按所有細分市場衡量客戶留存率。"}]', 'business idiom'),
('consolidate gains', '鞏固成果；穩固優勢', 'to secure and build on progress already made before advancing further', '[{"en":"Consolidate gains from the first quarter before entering new markets.","zh-TW":"在進入新市場之前鞏固第一季度的成果。"},{"en":"Strong teams consolidate gains quickly and are ready for the next challenge.","zh-TW":"強大的團隊迅速鞏固成果並為下一個挑戰做好準備。"}]', 'phrasal verb'),
('contact person', '聯絡人；窗口人員', 'the specific individual responsible for handling communication on a matter', '[{"en":"Please direct all enquiries to your designated contact person.","zh-TW":"請將所有詢問轉交給您指定的聯絡人。"},{"en":"Having a single contact person reduces confusion in client relationships.","zh-TW":"擁有單一聯絡人減少了客戶關係中的混亂。"}]', 'business idiom'),
('content marketing', '內容行銷', 'a strategy of creating valuable content to attract and engage a target audience', '[{"en":"Content marketing generated 60% of our inbound leads last year.","zh-TW":"內容行銷去年為我們帶來了60%的入站潛在客戶。"},{"en":"Great content marketing educates buyers before they contact sales.","zh-TW":"出色的內容行銷在買家聯繫銷售之前就教育了他們。"}]', 'business idiom'),
('data-driven decision', '數據驅動的決策', 'a choice made based on analysis of data rather than intuition or anecdote', '[{"en":"Data-driven decisions reduced our product return rate by 18%.","zh-TW":"數據驅動的決策將我們的產品退貨率降低了18%。"},{"en":"Build a culture of data-driven decisions to stay competitive.","zh-TW":"建立數據驅動決策的文化以保持競爭力。"}]', 'business idiom'),
('dynamic pricing', '動態定價', 'a pricing strategy where prices are adjusted in real time based on demand and other factors', '[{"en":"Dynamic pricing increased revenue per seat on high-demand routes.","zh-TW":"動態定價增加了高需求航線的每座收入。"},{"en":"Be transparent about dynamic pricing to maintain customer trust.","zh-TW":"對動態定價保持透明以維護客戶信任。"}]', 'business idiom'),
('ecosystem play', '生態系統策略；平台生態佈局', 'a strategy of building or joining a network of complementary products and partners', '[{"en":"The ecosystem play attracted 200 partner integrations in one year.","zh-TW":"生態系統策略在一年內吸引了200個合作夥伴整合。"},{"en":"An ecosystem play makes it harder for customers to switch.","zh-TW":"生態系統佈局使客戶更難以轉換。"}]', 'business idiom'),
('raise a red flag', '發出警告信號；引起警覺', 'to signal a warning or potential problem', '[{"en":"The sudden drop in sales raised a red flag for management.","zh-TW":"销售額的驟降對管理層發出了警告信號。"},{"en":"Unusual account activity raised a red flag with the auditors.","zh-TW":"異常的帳戶活動引起了審計人員的警覺。"},{"note":"Used when something indicates a potential problem"}]', 'idiom'),
('a ballpark figure', '大概的數字；粗略估計値', 'a rough or approximate estimate', '[{"en":"Can you give me a ballpark figure for the renovation cost?","zh-TW":"你能給我一個裝修費用的大概估計嗎？"},{"en":"The ballpark figure for the project is around two million dollars.","zh-TW":"這個專案的粗略費用大約兩百萬美元。"},{"note":"Used when an exact figure is not available"}]', 'business phrase'),
('miss the boat', '錯失良機；太遲了', 'to miss an opportunity by being too late or slow', '[{"en":"We missed the boat on entering the mobile payment market early.","zh-TW":"我們錯失了早期進入行動支付市場的良機。"},{"en":"Do not miss the boat on this partnership as it will not come again.","zh-TW":"不要錯失這次合作機會，它不會再來了。"}]', 'idiom'),
('not rocket science', '並不複雜；並非難事', 'not difficult or complicated to understand or do', '[{"en":"The onboarding process is not rocket science just follow the checklist.","zh-TW":"入職流程並不複雜，只要按照清單操作就好。"},{"en":"Managing cash flow is not rocket science but it requires consistency.","zh-TW":"管理現金流並非難事，但需要持之以恒。"}]', 'expression'),
('corner the market', '壟斷市場；獨佔市場', 'to dominate a market by controlling its supply', '[{"en":"The company has cornered the market on cloud security solutions.","zh-TW":"該公司已壟斷了雲端安全解決方案市場。"},{"en":"They aim to corner the market before competitors can react.","zh-TW":"他們希望在競爭對手反應之前佔領市場。"}]', 'idiom'),
('the bigger picture', '整體局面；宏觀視野', 'the overall situation or long-term perspective rather than details', '[{"en":"It is easy to get lost in details so keep the bigger picture in mind.","zh-TW":"很容易迷失在細節中，所以要記得從宏觀角度看問題。"},{"en":"The bigger picture shows this investment will pay off in five years.","zh-TW":"從宏觀角度來看，這項投資將在五年內得到回報。"}]', 'expression'),
('get one''s foot in the door', '打入；獲得初步機會', 'to gain an initial opportunity that may lead to greater ones', '[{"en":"An internship is a great way to get your foot in the door at a top firm.","zh-TW":"實習是進入頂級公司的好方法。"},{"en":"He got his foot in the door by presenting at the industry conference.","zh-TW":"他透過在行業會議上發言獲得了初步機會。"}]', 'idiom'),
('under wraps', '保密；秘而不宣', 'kept secret or not yet revealed to the public', '[{"en":"The new product is still under wraps until the official launch.","zh-TW":"新產品在官方發布前仍保密。"},{"en":"Keep the merger under wraps until both boards approve it.","zh-TW":"在雙方薑事會批准之前，請對合併消息保密。"}]', 'idiom'),
('the tip of the iceberg', '冰山一角；問題的表面部分', 'a small visible part of a much larger problem', '[{"en":"The reported losses are just the tip of the iceberg.","zh-TW":"所報告的損失只是冰山一角。"},{"en":"The customer complaints we received are just the tip of the iceberg.","zh-TW":"我們收到的客戶投訴只是問題的冰山一角。"}]', 'idiom'),
('a double-edged sword', '雙刃劍；有利有弊', 'something that has both advantages and disadvantages', '[{"en":"Rapid growth can be a double-edged sword if infrastructure is not ready.","zh-TW":"如果基礎設施尚未就緒，快速增長可能是一把雙刃劍。"},{"en":"Social media is a double-edged sword for brand reputation.","zh-TW":"社交媒體對於品牌聲譽而言是一把雙刃劍。"}]', 'idiom'),
('a game changer', '改變格局的事物；重大突破', 'something that fundamentally changes the way things are done', '[{"en":"The new AI platform was a game changer for customer service.","zh-TW":"新的人工智慧平台彻底改變了客服的運作方式。"},{"en":"Remote work technology has been a real game changer for global teams.","zh-TW":"遠端工作技術真正改變了全球團隊的格局。"}]', 'business phrase'),
('bring on board', '纳入團隊；引入新成員', 'to include someone in a project or team', '[{"en":"We need to bring a data analyst on board for this project.","zh-TW":"我們需要為這個專案引入一位數據分析師。"},{"en":"They brought several local partners on board to expand operations.","zh-TW":"他們引入了幾個小地合作夥伴以擴大業務。"}]', 'phrasal verb'),
('back out of', '退出；撤回承諾', 'to withdraw from an agreement or commitment', '[{"en":"The investor backed out of the deal at the last minute.","zh-TW":"投資者在最後一刻退出了這筆交易。"},{"en":"We cannot back out of the contract without a penalty.","zh-TW":"我們不能在沒有懲罰的情況下撤回合約。"}]', 'phrasal verb'),
('team up with', '與…合作；與…聆手', 'to join forces or work together with someone', '[{"en":"We teamed up with a local distributor to enter the Asian market.","zh-TW":"我們與一家小地經销商合作，進入亞洲市場。"},{"en":"The two firms teamed up to bid on the contract together.","zh-TW":"這兩家公司聆手共同競標。"}]', 'phrasal verb'),
('come aboard', '加入團隊；加入公司', 'to join a team or organization', '[{"en":"We are thrilled to have you come aboard as our new CFO.","zh-TW":"我們很高興歡迎您加入擔任新的財務長。"},{"en":"When did the new sales director come aboard?","zh-TW":"新的銷售總監是何時加入的？"}]', 'phrasal verb'),
('stand in for', '代替；暫代其職', 'to substitute for someone temporarily', '[{"en":"Can you stand in for me at the client meeting on Friday?","zh-TW":"星期五的客戶會議，你能代替我嗎？"},{"en":"She stood in for the director while he was on leave.","zh-TW":"她在總監請假期間代行其職。"}]', 'phrasal verb'),
('double down on', '加倍投入；加大力度堅持某策略', 'to increase commitment to a course of action', '[{"en":"Despite criticism the company decided to double down on its expansion.","zh-TW":"對山面批評，公司卻決定加大力度推動擴張。"},{"en":"We should double down on digital marketing to capture more market share.","zh-TW":"我們應加大力度投入數位行銷以佔領更大市場份額。"}]', 'phrasal verb'),
('press ahead with', '繼續推進；堅持實行', 'to continue with something despite difficulties', '[{"en":"Management decided to press ahead with the restructuring plan.","zh-TW":"管理層決定繼續推進重組計畫。"},{"en":"We will press ahead with the launch despite the delay in approvals.","zh-TW":"面對審批延遲，我們將繼續推進發布。"}]', 'phrasal verb'),
('weigh in on', '就…發表意見；參與討論', 'to give one''s opinion or contribute to a discussion', '[{"en":"The CEO weighed in on the debate about remote work policy.","zh-TW":"執行長就遠端工作政策的討論發表了意見。"},{"en":"Please weigh in on the proposal before the deadline.","zh-TW":"請在截止日期前就提案發表您的意見。"}]', 'phrasal verb'),
('put in for', '申請；提出請求', 'to formally apply or request something', '[{"en":"She put in for a promotion after completing the project.","zh-TW":"她在完成專案後申請晉升。"},{"en":"He put in for two weeks of leave during the holiday period.","zh-TW":"他在假期期間申請了兩週休假。"}]', 'phrasal verb'),
('ease off', '放鬆；減輕壓力', 'to reduce pressure or slow down on something', '[{"en":"The workload eased off after the peak season ended.","zh-TW":"旺季結束後，工作量減輕了。"},{"en":"Management asked staff to ease off on overtime to prevent burnout.","zh-TW":"管理層要求員工減少加班，以防止過勞。"}]', 'phrasal verb'),
('grow into', '逐漸勝任；成長融入', 'to develop the skills needed for a role over time', '[{"en":"She is young but she will grow into the leadership role.","zh-TW":"她雖然年輕，但她將逐漸勝任領導職位。"},{"en":"New hires are expected to grow into their positions within six months.","zh-TW":"新員工預計在六個月內逐漸勝任各自的職位。"}]', 'phrasal verb'),
('check in with', '與…確認進度；向…報告', 'to contact someone to provide or receive an update', '[{"en":"Please check in with the team by end of day Friday.","zh-TW":"請在週五下班前與團隊確認進度。"},{"en":"The project manager checks in with each member every morning.","zh-TW":"專案經理每天早上與每位成員確認進度。"}]', 'phrasal verb'),
('table a proposal', '提出提案供討論；將提案納入議程', 'to formally present a proposal for discussion', '[{"en":"The committee tabled a proposal to revise the pricing structure.","zh-TW":"委員會提出了一項修訂定價結構的提案供討論。"},{"en":"We plan to table a proposal at the next board meeting.","zh-TW":"我們計劃在下次董事會會議上提出一項提案。"},{"note":"In American English, ''table'' can mean to postpone. In British English it means to bring forward for discussion"}]', 'business phrase'),
('come to an agreement', '達成協議；取得共識', 'to reach a mutual decision after negotiation', '[{"en":"After two days of talks the parties finally came to an agreement.","zh-TW":"經過兩天的會談，雙方最終達成了協議。"},{"en":"We hope to come to an agreement before the end of the quarter.","zh-TW":"我們希望在本季末之前達成協議。"}]', 'business phrase'),
('raise a concern', '提出顧慮；表達擔憂', 'to mention a worry or problem that needs attention', '[{"en":"Several board members raised concerns about the proposed merger.","zh-TW":"幾位董事會成員對擬議中的合併提出了顧慮。"},{"en":"Please raise any concerns before we finalize the contract.","zh-TW":"請在我們定稿合約前提出任何顧慮。"}]', 'business phrase'),
('set the agenda', '設定議程；決定討論事項', 'to determine what topics will be discussed in a meeting', '[{"en":"The chairperson sets the agenda for every quarterly review.","zh-TW":"主席為每次季度審查設定議程。"},{"en":"By setting the agenda early we ensure all key issues are covered.","zh-TW":"透過提早設定議程，我們確保所有關鍵議題都被涵蓋。"}]', 'business phrase'),
('adjourn the meeting', '休會；正式結束會議', 'to formally end or suspend a meeting', '[{"en":"The chairperson adjourned the meeting until the following Monday.","zh-TW":"主席將會議休會至下週一再繼續。"},{"en":"We adjourned the meeting early as the key decision-makers were absent.","zh-TW":"由於關鍵決策者缺席，我們提前休會。"}]', 'business phrase'),
('at an impasse', '陷入僵局；無法取得進展', 'in a deadlock where no progress can be made', '[{"en":"Negotiations are at an impasse over the intellectual property rights.","zh-TW":"談判在智慧財產權問題上陷入了僵局。"},{"en":"The two sides were at an impasse so mediation was requested.","zh-TW":"雙方陷入僵局，因此要求調解。"}]', 'expression'),
('split the difference', '各讓一半；折中妥協', 'to reach a compromise by each party conceding equally', '[{"en":"They could not agree on the price so they decided to split the difference.","zh-TW":"他們無法就價格達成協議，所以決定各讓一半。"},{"en":"Splitting the difference at fifty thousand satisfied both parties.","zh-TW":"以五萬元折中妥協令雙方都感到滿意。"}]', 'idiom'),
('put it to a vote', '付諸表決；進行投票決定', 'to decide something by having people vote', '[{"en":"Since we cannot reach consensus let us put it to a vote.","zh-TW":"既然我們無法達成共識，讓我們付諸表決。"},{"en":"The proposal was put to a vote and passed by a majority.","zh-TW":"提案付諸表決，並以多數通過。"}]', 'business phrase'),
('play devil''s advocate', '故意持反對立場；唱反調以引發討論', 'to argue the opposing side to stimulate discussion or test an idea', '[{"en":"Let me play devil''s advocate and ask why we should not proceed.","zh-TW":"讓我唱唱反調，問問為什麼我們不應該繼續。"},{"en":"Playing devil''s advocate is a useful way to stress-test a strategy.","zh-TW":"故意持反對立場是壓力測試策略的有效方式。"}]', 'idiom'),
('on the table', '在討論中；提供中', 'being offered or currently under consideration', '[{"en":"Several options are on the table and we will evaluate them next week.","zh-TW":"目前有幾個選項在討論中，我們下週將進行評估。"},{"en":"A significant pay rise is on the table if you take the new role.","zh-TW":"如果你接受新職位，可觀的薪資提升就在眼前。"}]', 'expression'),
('take a step back', '退一步思考；重新審視', 'to pause and reconsider the situation from a wider perspective', '[{"en":"Before deciding, let us take a step back and assess the risks.","zh-TW":"在做決定之前，讓我們退一步評估風險。"},{"en":"Taking a step back showed us that our approach was too narrow.","zh-TW":"退一步思考讓我們意識到自己的方法過於狹隘。"}]', 'expression'),
('reach a middle ground', '找到折中點；達成妥協方案', 'to find a compromise acceptable to both sides', '[{"en":"The two parties eventually reached a middle ground on delivery terms.","zh-TW":"雙方最終就交貨條款找到了折中點。"},{"en":"Our goal is to reach a middle ground that works for everyone involved.","zh-TW":"我們的目標是找到對所有相關人員都適用的折中方案。"}]', 'expression'),
('take the floor', '發言；取得發言權', 'to begin speaking formally in a meeting', '[{"en":"The VP of Sales took the floor to present the quarterly results.","zh-TW":"銷售副總裁發言報告了季度業績。"},{"en":"Would anyone like to take the floor before we move to the next item?","zh-TW":"在我們進入下一項目之前，有人想要發言嗎？"}]', 'business phrase'),
('open the floor', '開放發言；邀請大家提問', 'to invite others to speak or ask questions', '[{"en":"After the presentation she opened the floor to questions.","zh-TW":"簡報結束後，她開放發言讓大家提問。"},{"en":"Let us open the floor and hear what everyone thinks about this plan.","zh-TW":"讓我們開放發言，聽聽大家對這個計畫的看法。"}]', 'business phrase'),
('keep to the point', '切中要點；不偏離主題', 'to stay focused on the relevant topic without digressing', '[{"en":"Please keep to the point as we only have fifteen minutes.","zh-TW":"請切中要點，因為我們只有十五分鐘。"},{"en":"The facilitator reminded presenters to keep to the point during pitches.","zh-TW":"主持人提醒發表者在推介時切中要點。"}]', 'business phrase'),
('climb the ladder', '晉升；逐步升遷', 'to advance step by step to higher positions in a career', '[{"en":"He has been climbing the ladder steadily since joining the company.","zh-TW":"他自加入公司以來，一直穩步晉升。"},{"en":"Climbing the corporate ladder requires both talent and persistence.","zh-TW":"在企業晉升需要才能和毅力。"}]', 'idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('get promoted', '獲得晉升；被升職', 'to be given a higher position or rank at work', '[{"en":"She worked hard for two years and finally got promoted to senior manager.","zh-TW":"她努力工作兩年，終於晉升為高級經理。"},{"en":"Getting promoted often requires demonstrating leadership potential.","zh-TW":"獲得晉升通常需要展示領導潛力。"}]', 'collocation'),
('take the initiative', '採取主動；主動行動', 'to act proactively without being told', '[{"en":"She took the initiative to redesign the onboarding process.","zh-TW":"她主動重新設計了入職流程。"},{"en":"Managers appreciate employees who take the initiative.","zh-TW":"管理者欣賞主動採取行動的員工。"}]', 'collocation'),
('a team player', '具有團隊精神的人；善於合作的人', 'someone who works well as part of a team', '[{"en":"We are looking for a team player who can collaborate across departments.","zh-TW":"我們正在尋找一位能跨部門合作、具有團隊精神的人。"},{"en":"Being a team player is just as important as individual performance.","zh-TW":"具有團隊精神與個人表現同樣重要。"}]', 'expression'),
('work-life balance', '工作與生活的平衡', 'a healthy balance between professional and personal life', '[{"en":"The company promotes work-life balance with flexible working hours.","zh-TW":"公司以彈性工時促進工作與生活的平衡。"},{"en":"Poor work-life balance can lead to burnout and high staff turnover.","zh-TW":"不良的工作與生活平衡可能導致過勞和高員工流動率。"}]', 'collocation'),
('move up the ranks', '在組織中升遷；職位提升', 'to advance to higher positions within an organization', '[{"en":"He moved up the ranks quickly thanks to his exceptional results.","zh-TW":"他因出色的業績而迅速在組織中升遷。"},{"en":"Moving up the ranks in a large corporation takes time and strategy.","zh-TW":"在大型企業中升遷需要時間和策略。"}]', 'expression'),
('in the running', '有競爭資格；角逐中', 'competing for a position or award', '[{"en":"She is in the running for the regional manager position.","zh-TW":"她正在角逐地區經理的職位。"},{"en":"Three candidates are still in the running after the first interview round.","zh-TW":"第一輪面試後，三位候選人仍在競爭中。"}]', 'expression'),
('keep one''s head above water', '勉強應付；維持正常運作', 'to manage to cope with a difficult workload or situation', '[{"en":"With three projects running simultaneously she struggled to keep her head above water.","zh-TW":"同時進行三個專案，她很難勉強應付。"},{"en":"We are keeping our heads above water but need more resources soon.","zh-TW":"我們目前勉強應付，但很快就需要更多資源。"}]', 'idiom'),
('dead-end job', '沒有前途的工作；死路一條的職位', 'a job with no possibility of advancement or improvement', '[{"en":"He left the dead-end job to pursue a career in technology.","zh-TW":"他辭去沒有前途的工作，轉而追求科技職涯。"},{"en":"Feeling stuck in a dead-end job can affect motivation and morale.","zh-TW":"覺得困在沒有前途的工作中會影響動力和士氣。"}]', 'collocation'),
('headhunted', '被獵頭；被挖角', 'approached by a recruiter to take a new job', '[{"en":"She was headhunted by a leading investment bank after her promotion.","zh-TW":"晉升後，她被一家頂尖投資銀行獵頭挖角。"},{"en":"Being headhunted is a sign that your skills are highly valued.","zh-TW":"被獵頭是你的技能備受重視的標誌。"}]', 'business phrase'),
('burn the midnight oil', '開夜車；工作到深夜', 'to work very late into the night', '[{"en":"The team burned the midnight oil to finish the proposal before the deadline.","zh-TW":"團隊開夜車在截止日期前完成了提案。"},{"en":"She burned the midnight oil for weeks preparing for the board presentation.","zh-TW":"她開了好幾週的夜車準備董事會簡報。"}]', 'idiom'),
('toe the line', '遵守規則；服從規定', 'to conform to expected standards or follow rules', '[{"en":"New employees are expected to toe the line during their probation period.","zh-TW":"新員工在試用期間需要遵守規則。"},{"en":"He was warned to toe the line or face disciplinary action.","zh-TW":"他被警告必須服從規定，否則將面臨紀律處分。"}]', 'idiom'),
('make a career move', '做出職涯轉換；採取職涯行動', 'to change jobs or make a strategic decision about one''s career', '[{"en":"She made a bold career move by switching from finance to tech.","zh-TW":"她大膽地從金融轉換到科技領域，做出了職涯轉換。"},{"en":"This is a smart career move given the growth of the industry.","zh-TW":"鑑於該行業的增長，這是一個明智的職涯行動。"}]', 'collocation'),
('job satisfaction', '工作滿意度；工作成就感', 'the sense of fulfillment and happiness from one''s work', '[{"en":"High job satisfaction leads to lower staff turnover.","zh-TW":"高工作滿意度會降低員工流動率。"},{"en":"She cited job satisfaction as the main reason for staying with the company.","zh-TW":"她將工作滿意度列為留在公司的主要原因。"}]', 'collocation'),
('on-the-job training', '在職培訓；邊做邊學', 'learning skills while performing the job rather than in a classroom', '[{"en":"New recruits receive on-the-job training during their first three months.","zh-TW":"新員工在前三個月接受在職培訓。"},{"en":"On-the-job training is the most practical way to develop industry skills.","zh-TW":"在職培訓是培養行業技能最實際的方式。"}]', 'collocation'),
('foot the bill', '付帳；承擔費用', 'to pay the cost of something, especially something expensive', '[{"en":"The company will foot the bill for all travel and accommodation expenses.","zh-TW":"公司將承擔所有差旅和住宿費用。"},{"en":"Who is going to foot the bill for the office renovation?","zh-TW":"誰來付辦公室裝修的帳？"}]', 'idiom'),
('tighten the belt', '縮緊開支；節省開銷', 'to spend less money and reduce expenses', '[{"en":"After the slowdown we had to tighten the belt across all departments.","zh-TW":"在業績放緩後，我們不得不在所有部門縮緊開支。"},{"en":"The company is tightening the belt by freezing all non-essential hiring.","zh-TW":"公司透過凍結所有非必要招聘來縮緊開支。"}]', 'idiom'),
('golden handshake', '優厚的離職補償；豐厚的解雇金', 'a generous financial package given to an executive upon leaving a company', '[{"en":"The departing CEO received a golden handshake worth five million dollars.","zh-TW":"離職的執行長獲得了價值五百萬美元的豐厚離職補償。"},{"en":"Golden handshakes are designed to secure a smooth leadership transition.","zh-TW":"優厚的離職補償旨在確保領導層的順利交接。"}]', 'collocation'),
('golden parachute', '黃金降落傘；高管離職保障金', 'a lucrative severance deal for executives if the company is acquired or they are dismissed', '[{"en":"His contract included a golden parachute clause worth ten million.","zh-TW":"他的合約包含一項價值一千萬的黃金降落傘條款。"},{"en":"Critics argue that golden parachutes reward failure rather than success.","zh-TW":"批評者認為黃金降落傘是在獎勵失敗而非成功。"}]', 'collocation'),
('money talks', '有錢能使鬼推磨；財力決定影響力', 'financial power has great influence in decisions and relationships', '[{"en":"In this industry money talks and the biggest spenders get the best deals.","zh-TW":"在這個行業，有錢能使鬼推磨，花費最多的人能拿到最好的交易。"},{"en":"He had the best idea but money talks, and the rival had deeper pockets.","zh-TW":"他有最好的創意，但財力決定影響力，競爭對手資金更雄厚。"}]', 'idiom'),
('on a shoestring budget', '以極少的預算；資金非常有限地', 'with very little money available', '[{"en":"They launched the product on a shoestring budget and still turned a profit.","zh-TW":"他們以極少的預算推出產品，卻仍然實現了盈利。"},{"en":"Managing a team on a shoestring budget requires creativity.","zh-TW":"以資金非常有限的預算管理團隊需要創意。"}]', 'expression'),
('burn through money', '快速消耗資金；大量花錢', 'to spend money very quickly', '[{"en":"The startup was burning through money faster than it was raising it.","zh-TW":"這家新創公司消耗資金的速度比募資還快。"},{"en":"Without cost controls we will burn through the budget in three months.","zh-TW":"沒有成本控制，我們將在三個月內燒完預算。"}]', 'expression'),
('revenue stream', '收入來源；資金流入管道', 'a source of income for a business', '[{"en":"The company is diversifying its revenue streams to reduce dependency on one product.","zh-TW":"公司正在多元化其收入來源，以減少對單一產品的依賴。"},{"en":"Licensing is a growing revenue stream for the tech firm.","zh-TW":"授權是該科技公司不斷增長的收入來源。"}]', 'collocation'),
('pay dividends', '帶來好處；產生回報', 'to produce benefits or profitable results over time', '[{"en":"Investing in staff training pays dividends in the long run.","zh-TW":"投資員工培訓從長遠來看會帶來好處。"},{"en":"The early sacrifices they made are now paying dividends.","zh-TW":"他們早期的犧牲現在正在產生回報。"},{"note":"Can refer to actual financial dividends or be used figuratively"}]', 'collocation'),
('cash-strapped', '資金拮据；資金短缺', 'having very little money available', '[{"en":"The cash-strapped startup had to delay its product launch.","zh-TW":"資金拮据的新創公司不得不推遲產品發布。"},{"en":"Many small businesses are cash-strapped during economic downturns.","zh-TW":"在經濟下行期間，許多小型企業資金短缺。"}]', 'collocation'),
('a windfall', '意外之財；意外橫財', 'an unexpected financial gain or profit', '[{"en":"The company received a windfall after selling its real estate assets.","zh-TW":"公司出售房地產資產後獲得了意外之財。"},{"en":"A windfall from the insurance claim helped them survive the crisis.","zh-TW":"保險理賠帶來的意外之財幫助他們度過了危機。"}]', 'business phrase'),
('on credit', '賒帳；先買後付', 'buying something now and paying for it later', '[{"en":"The company purchased the equipment on credit to preserve cash flow.","zh-TW":"公司賒帳購買設備以保護現金流。"},{"en":"Buying on credit can be useful but requires careful cash flow management.","zh-TW":"先買後付很有用，但需要謹慎管理現金流。"}]', 'expression'),
('overheads', '間接費用；日常營運開銷', 'the regular fixed costs of running a business such as rent and utilities', '[{"en":"Moving to a smaller office significantly reduced our overheads.","zh-TW":"搬到較小的辦公室大幅降低了我們的間接費用。"},{"en":"High overheads are eating into the company''s profit margins.","zh-TW":"高額的間接費用正在侵蝕公司的利潤率。"}]', 'collocation'),
('talk shop', '談公事；聊工作相關話題', 'to talk about work or business topics', '[{"en":"They met for coffee and ended up talking shop for two hours.","zh-TW":"他們喝咖啡時最後聊了兩小時的公事。"},{"en":"It is hard not to talk shop when you work with your best friend.","zh-TW":"當你和最好的朋友一起工作時，很難不聊工作話題。"}]', 'idiom'),
('put one''s cards on the table', '攤牌；坦誠說明立場', 'to be completely honest about one''s intentions or position', '[{"en":"Let me put my cards on the table and tell you exactly what we need.","zh-TW":"讓我攤牌，直接告訴你我們確切需要什麼。"},{"en":"She put her cards on the table and asked for a thirty percent raise.","zh-TW":"她攤牌，要求加薪三十個百分點。"}]', 'idiom'),
('a numbers game', '數字遊戲；靠量取勝的策略', 'a situation where success depends on large quantities rather than quality', '[{"en":"Cold calling is a numbers game — the more you call the more you close.","zh-TW":"電話推銷是數字遊戲——打越多電話，成交越多。"},{"en":"In recruiting, finding top talent is not just a numbers game.","zh-TW":"在招聘中，找到頂尖人才不僅僅是數字遊戲。"}]', 'expression'),
('a hard sell', '難以推銷；很難說服', 'something difficult to persuade people to accept or buy', '[{"en":"A price increase is always a hard sell to existing customers.","zh-TW":"漲價對現有客戶來說總是很難推銷的。"},{"en":"The new software was a hard sell without a proper demo.","zh-TW":"沒有適當的演示，新軟體很難說服人。"}]', 'expression'),
('bring up to speed', '向…更新情況；讓…了解最新動態', 'to give someone the latest information they need', '[{"en":"Can you bring the new team member up to speed on the project?","zh-TW":"你能讓新團隊成員了解專案的最新動態嗎？"},{"en":"She spent the morning bringing the client up to speed on the changes.","zh-TW":"她用了整個上午讓客戶了解最新的變化。"}]', 'phrasal verb'),
('narrow it down', '縮小範圍；精簡選擇', 'to reduce a number of options to a smaller, more manageable set', '[{"en":"We have five candidates — let us narrow it down to two.","zh-TW":"我們有五位候選人——讓我們把範圍縮小到兩位。"},{"en":"After the initial review we narrowed the vendor list down to three.","zh-TW":"初步審查後，我們將供應商名單縮小到三家。"}]', 'phrasal verb'),
('run past', '請人審閱；向某人諮詢', 'to tell someone about something to get their reaction or approval', '[{"en":"Let me run this pricing strategy past the finance team first.","zh-TW":"讓我先請財務團隊審閱這個定價策略。"},{"en":"Could you run the draft contract past legal before we sign?","zh-TW":"在我們簽署前，你能請法務審閱合約草案嗎？"}]', 'phrasal verb'),
('get down to brass tacks', '討論實質問題；切入正題', 'to start discussing the most important or practical details', '[{"en":"Let us get down to brass tacks and agree on the contract terms.","zh-TW":"讓我們切入正題，就合約條款達成協議。"},{"en":"After the introductions it is time to get down to brass tacks.","zh-TW":"介紹完畢後，是時候討論實質問題了。"}]', 'idiom'),
('take it or leave it', '愛要不要；不二價', 'a final offer with no room for further negotiation', '[{"en":"This is our final offer — take it or leave it.","zh-TW":"這是我們的最終出價——愛要不要。"},{"en":"He presented a take-it-or-leave-it proposal to close the negotiation.","zh-TW":"他提出了不二價的提案以結束談判。"}]', 'expression'),
('make concessions', '做出讓步；妥協', 'to give up something in order to reach an agreement', '[{"en":"Both parties had to make concessions to finalize the deal.","zh-TW":"雙方都必須做出讓步以完成交易。"},{"en":"He was unwilling to make any concessions on the delivery date.","zh-TW":"他不願意在交貨日期上做出任何讓步。"}]', 'collocation'),
('write off a debt', '核銷壞帳；沖銷債務', 'to officially accept that a debt will not be repaid and remove it from accounts', '[{"en":"The bank decided to write off the debt after the company went bankrupt.","zh-TW":"公司破產後，銀行決定核銷這筆壞帳。"},{"en":"Writing off a debt is a last resort after all collection efforts fail.","zh-TW":"核銷壞帳是在所有催收努力失敗後的最後手段。"}]', 'collocation'),
('fixed costs', '固定成本；不變費用', 'business expenses that remain constant regardless of output', '[{"en":"Rent and salaries are examples of fixed costs that do not change monthly.","zh-TW":"租金和薪資是每月不變的固定成本範例。"},{"en":"Reducing fixed costs is often the first step in a turnaround plan.","zh-TW":"降低固定成本通常是扭虧為盈計畫的第一步。"}]', 'collocation'),
('variable costs', '可變成本；隨產量變動的費用', 'business expenses that change depending on the level of production or sales', '[{"en":"As sales volume increases variable costs rise proportionally.","zh-TW":"隨著銷售量增加，可變成本按比例上升。"},{"en":"The company reduced variable costs by renegotiating supplier contracts.","zh-TW":"公司透過重新談判供應商合約降低了可變成本。"}]', 'collocation'),
('cash flow', '現金流量；資金流動', 'the movement of money in and out of a business', '[{"en":"Strong cash flow allows the company to invest in new opportunities.","zh-TW":"強勁的現金流量使公司能夠投資新機會。"},{"en":"Managing cash flow is essential for any small business to survive.","zh-TW":"管理現金流量對任何小型企業的生存都至關重要。"}]', 'collocation'),
('net profit', '淨利潤；純利', 'the profit remaining after all costs and taxes have been deducted', '[{"en":"The company reported a net profit of two million for the quarter.","zh-TW":"公司報告本季淨利潤為兩百萬。"},{"en":"Increasing net profit requires either growing revenue or cutting costs.","zh-TW":"增加淨利潤需要增加收入或削減成本。"}]', 'collocation'),
('operating expenses', '營運費用；日常業務支出', 'the day-to-day costs of running a business', '[{"en":"The new automation system significantly reduced our operating expenses.","zh-TW":"新的自動化系統大幅降低了我們的營運費用。"},{"en":"Operating expenses must be kept under control to maintain profitability.","zh-TW":"必須控制好營運費用以維持盈利能力。"}]', 'collocation'),
('asset allocation', '資產配置；資金分配', 'the distribution of investments across different asset categories', '[{"en":"A balanced asset allocation reduces overall portfolio risk.","zh-TW":"均衡的資產配置可降低整體投資組合風險。"},{"en":"The CFO reviewed the company''s asset allocation strategy quarterly.","zh-TW":"財務長每季審查公司的資產配置策略。"}]', 'collocation'),
('liquidity', '流動性；資金流通能力', 'the availability of liquid assets to meet short-term financial obligations', '[{"en":"The bank ran into trouble due to a lack of liquidity.","zh-TW":"銀行因流動性不足而陷入麻煩。"},{"en":"Maintaining adequate liquidity is critical during periods of uncertainty.","zh-TW":"在不確定時期維持足夠的流動性至關重要。"}]', 'business phrase'),
('burn rate', '資金消耗率；燒錢速度', 'the rate at which a company spends its capital before generating positive cash flow', '[{"en":"The startup''s burn rate means they have six months of runway left.","zh-TW":"這家新創公司的資金消耗率意味著他們只剩六個月的資金跑道。"},{"en":"Investors were concerned about the high burn rate with no revenue in sight.","zh-TW":"投資者對高燒錢速度卻看不到收入感到擔憂。"}]', 'collocation'),
('market cap', '市值；市場資本額', 'the total market value of a company''s outstanding shares', '[{"en":"The company''s market cap surpassed one billion dollars after the IPO.","zh-TW":"上市後公司市值突破十億美元。"},{"en":"Market cap is one indicator of a company''s size and investor confidence.","zh-TW":"市值是衡量公司規模和投資者信心的指標之一。"}]', 'collocation'),
('fiscal year', '財政年度；會計年度', 'a twelve-month period used for accounting and financial reporting', '[{"en":"The company''s fiscal year ends on March 31st rather than December 31st.","zh-TW":"公司的財政年度結束於三月三十一日而非十二月三十一日。"},{"en":"Revenue targets are set at the beginning of each fiscal year.","zh-TW":"收入目標在每個財政年度開始時設定。"}]', 'collocation'),
('venture capital', '創業投資；風險資本', 'funding provided to early-stage high-potential companies in exchange for equity', '[{"en":"The startup raised ten million in venture capital to fund its expansion.","zh-TW":"這家新創公司籌集了一千萬的創業投資來資助擴張。"},{"en":"Securing venture capital requires a compelling pitch and strong growth metrics.","zh-TW":"獲得創業投資需要引人注目的簡報和強勁的增長指標。"}]', 'collocation'),
('unique selling proposition', '獨特銷售主張；差異化優勢', 'the feature that makes a product or service different from competitors', '[{"en":"The brand''s unique selling proposition is its lifetime warranty.","zh-TW":"這個品牌的獨特銷售主張是其終身保固。"},{"en":"Defining your unique selling proposition is the first step in any marketing strategy.","zh-TW":"定義你的獨特銷售主張是任何行銷策略的第一步。"},{"note":"Often abbreviated as USP"}]', 'business phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('customer retention', '客戶留存率；維繫客戶', 'the ability to keep existing customers over time', '[{"en":"Improving customer retention is more cost-effective than acquiring new customers.","zh-TW":"提升客戶留存率比獲取新客戶更具成本效益。"},{"en":"A loyalty programme is a popular strategy for boosting customer retention.","zh-TW":"忠誠度計畫是提升客戶留存率的常見策略。"}]', 'collocation'),
('turnaround time', '周轉時間；處理完成所需時間', 'the time taken to complete a task or process from start to finish', '[{"en":"Our average turnaround time for customer orders is forty-eight hours.","zh-TW":"我們客戶訂單的平均周轉時間為四十八小時。"},{"en":"Reducing turnaround time was the key goal of the process improvement project.","zh-TW":"縮短周轉時間是流程改善專案的關鍵目標。"}]', 'collocation'),
('trade surplus', '貿易順差；出口大於進口', 'when a country exports more than it imports', '[{"en":"The country maintained a trade surplus for the fifth consecutive year.","zh-TW":"該國連續第五年保持貿易順差。"},{"en":"A trade surplus can strengthen a country''s currency over time.","zh-TW":"貿易順差從長遠來看可能使一國貨幣升值。"}]', 'collocation'),
('trade deficit', '貿易逆差；進口大於出口', 'when a country imports more than it exports', '[{"en":"The widening trade deficit raised concerns among policymakers.","zh-TW":"不斷擴大的貿易逆差引起了政策制定者的擔憂。"},{"en":"Measures were introduced to reduce the trade deficit with key partners.","zh-TW":"採取了措施以減少與主要夥伴的貿易逆差。"}]', 'collocation'),
('barriers to entry', '進入壁壘；市場進入障礙', 'factors that make it difficult for new competitors to enter a market', '[{"en":"High start-up costs are a major barrier to entry in the pharmaceutical industry.","zh-TW":"高昂的啟動成本是製藥行業的主要進入壁壘。"},{"en":"Strong brand loyalty creates significant barriers to entry for new competitors.","zh-TW":"強烈的品牌忠誠度為新競爭者製造了重大的進入壁壘。"}]', 'collocation'),
('bulk order', '大量訂購；批量訂單', 'a large purchase of goods, usually at a discounted price', '[{"en":"Placing a bulk order reduces the unit cost significantly.","zh-TW":"大量訂購可以大幅降低單位成本。"},{"en":"The retail chain placed a bulk order ahead of the holiday season.","zh-TW":"連鎖零售商在假日季前下了批量訂單。"}]', 'collocation'),
('vendor management', '供應商管理；廠商關係管理', 'the process of overseeing and controlling relationships with suppliers', '[{"en":"Effective vendor management ensures consistent quality and timely delivery.","zh-TW":"有效的供應商管理確保一致的品質和及時交貨。"},{"en":"The procurement team improved vendor management by centralising all contracts.","zh-TW":"採購團隊透過集中管理所有合約改善了供應商管理。"}]', 'collocation'),
('change management', '變革管理；組織變革推動', 'the structured approach to transitioning individuals or organizations through change', '[{"en":"A solid change management plan minimises disruption during the merger.","zh-TW":"完善的變革管理計畫可在合併期間將干擾降至最低。"},{"en":"Change management requires clear communication and strong leadership.","zh-TW":"變革管理需要清晰的溝通和強有力的領導。"}]', 'collocation'),
('organizational culture', '組織文化；企業文化', 'the shared values, beliefs, and practices within an organization', '[{"en":"A positive organizational culture attracts and retains top talent.","zh-TW":"積極的組織文化能吸引並留住頂尖人才。"},{"en":"The new CEO prioritized transforming the organizational culture.","zh-TW":"新執行長優先致力於轉變組織文化。"}]', 'collocation'),
('benchmarking', '標竿管理；比較基準', 'the practice of comparing business processes and metrics against industry best performers', '[{"en":"Benchmarking against competitors revealed gaps in our customer service.","zh-TW":"與競爭對手的標竿比較揭示了我們客戶服務的差距。"},{"en":"The company uses benchmarking to set realistic performance targets.","zh-TW":"公司使用標竿管理來設定切實可行的績效目標。"}]', 'business phrase'),
('best practice', '最佳實踐；最佳做法', 'the most effective method or approach accepted as superior in an industry', '[{"en":"Sharing best practices across departments improves overall performance.","zh-TW":"在各部門間分享最佳實踐可提升整體績效。"},{"en":"The manual documents best practices for handling client complaints.","zh-TW":"該手冊記錄了處理客戶投訴的最佳做法。"}]', 'collocation'),
('key deliverable', '關鍵交付成果；重要輸出項目', 'a specific, tangible output that must be produced as part of a project', '[{"en":"The key deliverables for this phase include a prototype and a test report.","zh-TW":"這個階段的關鍵交付成果包括原型和測試報告。"},{"en":"All team members must be clear on the key deliverables before work begins.","zh-TW":"所有團隊成員在開始工作之前必須清楚關鍵交付成果。"}]', 'collocation'),
('break ranks', '打破常規；不服從集體決定', 'to act against the decisions or rules of one''s group', '[{"en":"One board member broke ranks and voted against the proposal.","zh-TW":"一位董事會成員打破常規，投票反對該提案。"},{"en":"Breaking ranks on this issue could damage team cohesion.","zh-TW":"在這個問題上打破常規可能會損害團隊凝聚力。"}]', 'idiom'),
('sleeping partner', '隱名合夥人；不參與日常管理的投資人', 'a business partner who provides capital but takes no active role in management', '[{"en":"He acts as a sleeping partner and does not attend board meetings.","zh-TW":"他作為隱名合夥人，不出席董事會會議。"},{"en":"The firm brought in a sleeping partner to fund the new division.","zh-TW":"公司引入了隱名合夥人為新部門提供資金。"}]', 'business phrase'),
('get the message across', '傳達清楚；讓人明白意思', 'to communicate an idea successfully so others understand it', '[{"en":"Use visuals to get the message across more effectively in presentations.","zh-TW":"在簡報中使用視覺效果更有效地傳達意思。"},{"en":"She struggled to get the message across to the non-technical audience.","zh-TW":"她難以向非技術背景的聽眾傳達清楚她的意思。"}]', 'expression'),
('take on board', '接受；認真考慮（意見或建議）', 'to accept and consider feedback or advice seriously', '[{"en":"Management took the team''s concerns on board and revised the plan.","zh-TW":"管理層認真考慮了團隊的顧慮並修訂了計畫。"},{"en":"She took all the client''s feedback on board before the final presentation.","zh-TW":"她在最終簡報前認真考慮了所有客戶的反饋。"}]', 'phrasal verb'),
('non-disclosure', '保密；不披露協議', 'an agreement to keep certain information confidential', '[{"en":"Both parties signed a non-disclosure agreement before sharing financials.","zh-TW":"雙方在分享財務資料前簽署了保密協議。"},{"en":"The non-disclosure clause prevents either party from revealing trade secrets.","zh-TW":"保密條款防止任何一方洩露商業機密。"},{"note":"Commonly used as in ''non-disclosure agreement'' or NDA"}]', 'collocation'),
('think big', '有遠大抱負；敢於宏觀思考', 'to have ambitious and broad goals rather than limiting oneself', '[{"en":"The founder encouraged the team to think big and set bold targets.","zh-TW":"創辦人鼓勵團隊有遠大抱負，設定大膽的目標。"},{"en":"Thinking big is important but must be backed by a solid execution plan.","zh-TW":"有遠大抱負很重要，但必須有扎實的執行計畫支撐。"}]', 'expression'),
('sweeten the deal', '讓條件更具吸引力；增加優惠', 'to make an offer more attractive by adding extra benefits', '[{"en":"They sweetened the deal by offering free shipping and extended warranties.","zh-TW":"他們透過提供免費運送和延長保固來讓條件更具吸引力。"},{"en":"To close the sale the manager sweetened the deal with a ten percent discount.","zh-TW":"為了完成銷售，經理增加了十個百分點的折扣作為優惠。"}]', 'idiom'),
('a blank check', '無限授權；充分授權', 'complete freedom to act or spend as much as needed', '[{"en":"The CEO was given a blank check to restructure the failing division.","zh-TW":"執行長獲得無限授權來重組虧損部門。"},{"en":"Giving a vendor a blank check without oversight can lead to budget overruns.","zh-TW":"在沒有監督的情況下給供應商無限授權可能導致預算超支。"}]', 'idiom'),
('top-down approach', '由上而下的方式；高層主導', 'a method where decisions and instructions come from senior management', '[{"en":"The new strategy was communicated through a top-down approach.","zh-TW":"新策略透過由上而下的方式傳達。"},{"en":"A top-down approach ensures consistency but may reduce employee buy-in.","zh-TW":"由上而下的方式確保一致性，但可能降低員工的認同感。"}]', 'business phrase'),
('lead time', '前置時間；備貨所需時間', 'the time between placing an order and receiving the goods or completing a task', '[{"en":"The lead time for this supplier is typically six weeks.","zh-TW":"這家供應商的前置時間通常為六週。"},{"en":"Reducing lead time gives the company a competitive advantage.","zh-TW":"縮短前置時間使公司具有競爭優勢。"}]', 'collocation'),
('value-added', '增值的；附加價值的', 'providing extra benefit or enhancement beyond the basic product or service', '[{"en":"The consultants offered value-added services such as training and support.","zh-TW":"顧問提供了包括培訓和支援在內的增值服務。"},{"en":"Value-added features can justify a higher price point.","zh-TW":"增值功能可以為更高的定價提供依據。"}]', 'collocation'),
('red ocean', '紅海市場；競爭激烈的既有市場', 'a highly competitive market where companies fight for existing demand', '[{"en":"The smartphone market has become a red ocean with shrinking margins.","zh-TW":"智慧型手機市場已成為利潤空間收窄的紅海市場。"},{"en":"Instead of competing in a red ocean we are creating a new market category.","zh-TW":"我們不是在紅海市場競爭，而是正在創造一個新的市場類別。"},{"note":"Contrasts with ''blue ocean'' (uncontested market space)"}]', 'business phrase'),
('blue ocean', '藍海市場；未開發的新市場空間', 'an untapped or uncontested market space with little to no competition', '[{"en":"The company found its blue ocean by targeting underserved rural customers.","zh-TW":"公司透過鎖定服務不足的農村客戶找到了自己的藍海市場。"},{"en":"Blue ocean strategy focuses on creating demand rather than competing for it.","zh-TW":"藍海策略專注於創造需求而非爭奪需求。"},{"note":"Contrasts with ''red ocean'' (highly competitive existing market)"}]', 'business phrase'),
('scope of work', '工作範圍；專案範疇', 'the defined tasks, deliverables, and boundaries of a project', '[{"en":"The scope of work must be agreed before signing the service contract.","zh-TW":"在簽署服務合約前必須就工作範圍達成共識。"},{"en":"Any changes to the scope of work will require a revised budget estimate.","zh-TW":"工作範圍的任何變更都需要修訂預算估算。"}]', 'collocation'),
('quid pro quo', '交換條件；以物易物', 'a favour or advantage given in return for something of equal value', '[{"en":"The partnership was built on a quid pro quo of shared resources and contacts.","zh-TW":"這次合作建立在共享資源和人脈的交換條件基礎上。"},{"en":"In diplomacy and business, quid pro quo arrangements are common.","zh-TW":"在外交和商業中，交換條件安排很常見。"}]', 'business phrase'),
('market positioning', '市場定位；品牌定位策略', 'the way a company differentiates its product in the minds of consumers', '[{"en":"The rebranding effort was designed to improve the company''s market positioning.","zh-TW":"重新品牌化工作旨在改善公司的市場定位。"},{"en":"Strong market positioning allows a company to command premium prices.","zh-TW":"強有力的市場定位使公司能夠維持溢價。"}]', 'collocation'),
('pricing strategy', '定價策略；價格制定方式', 'the method used to set the price of a product or service', '[{"en":"The company adopted a penetration pricing strategy to gain market share quickly.","zh-TW":"公司採用滲透定價策略迅速獲取市場份額。"},{"en":"Choosing the right pricing strategy is critical for sustainable profitability.","zh-TW":"選擇正確的定價策略對可持續盈利至關重要。"}]', 'collocation'),
('brand awareness', '品牌知名度；品牌認知度', 'the extent to which consumers are familiar with a brand and its products', '[{"en":"Social media campaigns significantly increased brand awareness among young consumers.","zh-TW":"社交媒體活動顯著提高了年輕消費者的品牌知名度。"},{"en":"Building brand awareness takes time and consistent marketing investment.","zh-TW":"建立品牌知名度需要時間和持續的行銷投入。"}]', 'collocation'),
('demand forecast', '需求預測；市場需求預估', 'an estimate of future customer demand for a product or service', '[{"en":"Accurate demand forecasting reduces the risk of overstock or shortages.","zh-TW":"準確的需求預測可降低庫存過多或短缺的風險。"},{"en":"The demand forecast for Q4 suggests a thirty percent increase in orders.","zh-TW":"第四季的需求預測顯示訂單增加三十個百分點。"}]', 'collocation');
INSERT INTO grammar_topics (id, title, category, level, explanation_md) VALUES
(1, 'Present Simple vs Present Continuous', 'tense', 2, '現在簡單式用於習慣或事實（She works every day），現在進行式用於當下正在發生的動作（She is working now）。靜態動詞如 know、believe 不用進行式。商業英語中，簡單式描述職責，進行式描述當前專案。'),
(2, 'Past Simple vs Past Continuous', 'tense', 2, '過去簡單式描述已完成的過去動作，過去進行式描述過去某時刻正在進行的動作。兩者常搭配：進行式為背景，簡單式為插入動作。'),
(3, 'Present Perfect', 'tense', 3, '現在完成式（have/has + 過去分詞）連結過去動作與現在結果，常與 just、already、yet、ever、never、since、for 連用，不與 yesterday、last year 等明確過去時間連用。'),
(4, 'Present Perfect vs Past Simple', 'tense', 3, '現在完成式強調對現在的影響；過去簡單式描述已結束的特定事件。ago/yesterday/last year → 過去式；already/yet/just/since/for → 完成式。'),
(5, 'Past Perfect', 'tense', 3, '過去完成式（had + 過去分詞）描述過去某時間點之前已完成的動作，建立兩個過去事件的先後順序，常與 before、by the time、when、already 等連用。'),
(6, 'Future: will vs going to', 'tense', 2, 'will 用於臨時決定、承諾或預測；be going to 用於已計劃的意圖或根據證據的預測。兩者均可表未來，but 語用不同。'),
(7, 'Future Perfect and Future Continuous', 'tense', 4, '未來完成式（will have + p.p.）表示到未來某點前將完成的動作；未來進行式（will be + V-ing）表示未來某時刻正在進行的動作。兩者常用於商業時程規劃。'),
(8, 'Mixed Tenses', 'tense', 4, '混合時態練習要求根據語境選擇正確時態，是商業英語的重要能力。正確選擇時態能清楚傳達事件的時間順序和因果關係。'),
(9, 'Definite Article: the', 'article', 2, '定冠詞 the 用於雙方均知的特定事物、再次提及、獨一無二的事物及最高級前。商業英語中常見於職稱（the CEO）、特定文件（the report）、最高級（the best）。'),
(10, 'Indefinite Articles: a / an', 'article', 1, '不定冠詞 a 用在輔音音素前，an 用在母音音素前。注意判斷依據是發音不是拼字（如 an hour、an MBA）。用於首次提及或泛指某類別。'),
(11, 'Zero Article', 'article', 3, '零冠詞（不加冠詞）用於複數可數名詞泛稱、不可數名詞泛稱、專有名詞、及 go to work/by email 等固定搭配。避免在泛稱前加 the。'),
(12, 'Prepositions of Time: at/in/on', 'preposition', 2, 'at 用於精確時間（at 3 p.m.）；in 用於較長時段（in March、in 2024）；on 用於特定日期和星期（on Monday、on January 5th）。商業場合中正確使用避免誤解。'),
(13, 'Prepositions of Place: at/in/on', 'preposition', 2, 'at 表精確地點或功能性場所（at the reception）；in 表有邊界空間或地區（in the office）；on 表面或樓層（on the desk、on the third floor）。'),
(14, 'Prepositions of Movement', 'preposition', 2, '移動介系詞描述從一地到另一地的動作：to（去到）、into（進入）、out of（出去）、through（穿過）、across（橫越）、along（沿著）、past（經過）。'),
(15, 'Dependent Prepositions (adjective + prep)', 'preposition', 3, '形容詞與特定介系詞的固定搭配，如 responsible for、interested in、satisfied with、familiar with。必須記憶，不可任意替換。'),
(16, 'Dependent Prepositions (verb + prep)', 'preposition', 3, '動詞與特定介系詞的固定搭配，如 apply for、deal with、rely on、invest in。錯誤使用介系詞會造成誤解，需熟記常見搭配。'),
(17, 'Zero and First Conditional', 'conditional', 2, '零條件句（if + 現在式，現在式）表普遍事實；第一條件句（if + 現在式，will）表真實可能的未來情況。商業英語常用第一條件句提案或預測。'),
(18, 'Second Conditional', 'conditional', 3, '第二條件句（if + 過去式，would）表示假設或不太可能的情況。注意 if 子句中 be 動詞正式英語用 were，常用於假設討論和商業頭腦風暴。'),
(19, 'Third Conditional', 'conditional', 4, '第三條件句（if + had + p.p.，would have + p.p.）描述過去假設，用於反思決策。商業案例分析和後見之明討論中常見。'),
(20, 'Mixed Conditionals', 'conditional', 5, '混合條件句結合不同時態：最常見是 if + 過去完成式（過去假設），would + 原形（現在結果），如 If I had taken that job, I would be in London now。'),
(21, 'Modal: can / could', 'modal', 2, 'can 表現在的能力、許可或可能性；could 表過去能力、假設可能性或禮貌請求。商業英語中 could 比 can 更正式有禮貌。'),
(22, 'Modal: must / have to', 'modal', 2, 'must 表主觀強烈義務或邏輯推論；have to 表外在客觀規定。must not 表禁止；do not have to 表不必要（不是禁止）。'),
(23, 'Modal: should / ought to', 'modal', 2, 'should 和 ought to 表建議或期望，should 更口語常用。商業英語中 should 常見於建議、指南、政策手冊中。'),
(24, 'Modal: may / might', 'modal', 3, 'may 和 might 都表可能性，might 確定性略低。may 也可表正式許可。商業報告中用於謹慎預測，避免過於武斷。'),
(25, 'Modal: would', 'modal', 3, 'would 多用法：過去習慣、禮貌請求（Would you...）、假設（I would accept）、提供建議（I would recommend）。商業溝通中是最禮貌的情態動詞。'),
(26, 'Modal Perfect: should have / could have / would have', 'modal', 4, '情態完成式談論過去不同的可能：should have（應該做但沒做，遺憾/批評），could have（本可以，可能性），would have（假設結果）。'),
(27, 'Passive Voice: Simple Tenses', 'passive', 3, '被動語態（am/is/are/was/were + p.p.）強調動作接受者，廣泛用於商業正式文件。當行為者不重要或不明確時特別適用。'),
(28, 'Passive Voice: Perfect Tenses', 'passive', 4, '完成被動式：現在完成被動（have/has been + p.p.）和過去完成被動（had been + p.p.）。商業報告中用於說明已完成的程序，語氣正式客觀。'),
(29, 'Passive Voice: Modal Verbs', 'passive', 4, '情態被動（modal + be + p.p.）廣泛用於商業政策和通知：must be submitted、should be reviewed、will be sent、can be accessed。'),
(30, 'Causative Have/Get', 'passive', 4, '使役結構：have/get something done（安排別人做）；have someone do（主動命令）；get someone to do（說服/促使）。常用於委託、外包描述。'),
(31, 'Reported Speech: Statements', 'reported speech', 3, '間接引語將直接引語轉為第三人稱，動詞時態後移，代名詞和時間副詞也需調整。商業會議記錄和轉述客戶意見時常用。'),
(32, 'Reported Speech: Questions', 'reported speech', 3, '間接問句語序是陳述句序，no 不用問號。yes/no 問句用 if/whether 引導。如：She asked what the deadline was；He asked if the report was ready。'),
(33, 'Reported Speech: Commands', 'reported speech', 3, '間接命令句：tell/ask/order/advise + 受詞 + to do（肯定）；tell + 受詞 + not to do（否定）。'),
(34, 'Backshift in Reported Speech', 'reported speech', 4, '間接引語時態後移規則：現在→過去，過去→過去完成，will→would，can→could，may→might。時間副詞：now→then，today→that day，tomorrow→the following day，here→there。'),
(35, 'Defining Relative Clauses', 'relative clause', 3, '限定性關係子句提供識別被修飾名詞所必需的資訊，不用逗號，可用 who（人）、which（物）、that（人或物）、whose（所有格）。'),
(36, 'Non-defining Relative Clauses', 'relative clause', 4, '非限定性關係子句提供額外（非必要）資訊，用逗號隔開，不可用 that，只用 who/which/whose/where/when。'),
(37, 'Relative Pronouns: who/which/that/whose', 'relative clause', 3, 'who 指人（主格/受格），which 指物（限定/非限定），that 指人或物（只限限定子句），whose 表所有格（人或物）。'),
(38, 'Gerund vs Infinitive after Verbs', 'gerund/infinitive', 3, '某些動詞後接動名詞（enjoy/finish/suggest/consider/avoid），某些後接不定詞（want/decide/agree/plan/refuse），有些兩者皆可但意思可能不同（stop/remember/try）。'),
(39, 'Gerund as Subject', 'gerund/infinitive', 2, '動名詞可作句子主語，如 Managing a team requires strong communication skills。這種結構在商業政策說明、工作描述中非常常見。'),
(40, 'Infinitive of Purpose', 'gerund/infinitive', 2, '不定詞表目的（to do），更正式用 in order to 或 so as to。商業英語中清楚說明行動目的，常見於策略計劃和提案。'),
(41, 'Verb + Object + Infinitive', 'gerund/infinitive', 3, '某些動詞後接受詞再接不定詞：want/ask/advise/require/expect/allow/encourage + 受詞 + to do。商業指示和委託中大量使用。'),
(42, 'Comparative Adjectives', 'comparison', 2, '比較級：單音節 + -er（faster）；多音節 + more（more efficient）；不規則：good→better，bad→worse，far→farther/further。'),
(43, 'Superlative Adjectives', 'comparison', 2, '最高級：單音節 + the -est（the fastest）；多音節 + the most（the most innovative）；不規則：good→the best，bad→the worst。'),
(44, 'Comparing with as...as', 'comparison', 2, 'as + 形容詞/副詞 + as 表相等；not as...as 表不如；the same...as 表相同；as much/many...as 表數量相等。'),
(45, 'Double Comparatives', 'comparison', 4, '雙重比較結構 the + 比較級 + the + 比較級，表示正比或反比關係。常見於商業策略討論，如 The more we invest, the higher the returns。'),
(46, 'Adverbial Clauses of Time', 'clause', 3, '時間副詞子句由 when、while、as soon as、before、after、until、by the time 等引導，表示動作發生的時間關係。'),
(47, 'Adverbial Clauses of Reason', 'clause', 3, '原因副詞子句由 because、since、as、now that 等引導，解釋動作的原因。商業英語中常用於說明決策理由。'),
(48, 'Adverbial Clauses of Contrast', 'clause', 3, '對比副詞子句由 although、even though、while、whereas 等引導，承認一個事實同時提出相反情況。商業英語中用於客觀分析。'),
(49, 'Adverbial Clauses of Result', 'clause', 3, '結果副詞子句由 so...that 或 such...that 引導，表示原因導致的結果。如 The presentation was so compelling that the client signed immediately。'),
(50, 'Noun Clauses', 'clause', 4, '名詞子句充當名詞功能（主語、受語或補語），常由 that、whether、what、how、why、who 等引導。商業英語中常用於表達觀點和轉述資訊。');
INSERT INTO grammar_topics (id, title, category, level, explanation_md) VALUES
(51, 'Coordinating Conjunctions: FANBOYS', 'conjunction', 2, 'FANBOYS（for、and、nor、but、or、yet、so）連接對等成分。商業英語常用 and（增加）、but（對比）、so（結果）、or（選擇）。'),
(52, 'Subordinating Conjunctions', 'conjunction', 3, '從屬連接詞引導從屬子句，包括時間（when）、原因（because）、條件（if/unless）、對比（although）等，建立複雜的邏輯關係。'),
(53, 'Correlative Conjunctions: either...or / neither...nor', 'conjunction', 3, '相關連接詞成對使用：either...or（兩者之一）；neither...nor（兩者都不）；both...and（兩者都）；not only...but also（不只...而且）。主謂一致依就近原則。'),
(54, 'Basic Sentence Structure (SVO)', 'word order', 1, '英語基本結構是主語-動詞-受語（SVO）。時間和地點副詞通常置句尾。修飾語放被修飾詞附近。這是所有英語寫作的基礎。'),
(55, 'Adverb Placement', 'word order', 3, '頻率副詞（always/often/never）置 be 後、主要動詞前；程度副詞（very/quite）置形容詞/副詞前；時間/地點副詞通常句尾。'),
(56, 'Inversion after Negative Adverbials', 'word order', 5, '否定副詞位於句首時需主謂倒裝：Never have we seen...；Not only did we...；Rarely does...；Hardly had...。常見於正式商業演講和高品質寫作。'),
(57, 'Quantifiers: some / any / no', 'determiner', 2, 'some 用於肯定句和期望肯定答案的疑問句；any 用於否定句和一般疑問句；no = not any（語氣更強）。'),
(58, 'Quantifiers: much / many / a lot of', 'determiner', 2, 'much + 不可數名詞（much time）；many + 可數名詞（many clients）；a lot of 兩者皆可，口語化。正式書面英語偏好 much/many。'),
(59, 'Quantifiers: few / little / a few / a little', 'determiner', 3, 'few/little 表幾乎沒有（消極）；a few/a little 表有一些（積極）。few/a few 用於可數名詞；little/a little 用於不可數名詞。'),
(60, 'Each / Every / All', 'determiner', 3, 'each 強調個別性（each employee）；every 強調整體的每一個（every department）；all 表全體（all staff）。each/every 接單數動詞，all 接複數動詞。'),
(61, 'Reflexive Pronouns', 'pronoun', 2, '反身代名詞（myself、yourself、himself、herself、itself、ourselves、yourselves、themselves）用於反身動作或強調（親自）。'),
(62, 'Indefinite Pronouns: someone/anyone/no one', 'pronoun', 2, 'someone/somebody 肯定句；anyone/anybody 疑問/否定句；no one/nobody 否定意義。對應 something/anything/nothing；somewhere/anywhere/nowhere。'),
(63, 'Countable and Uncountable Nouns', 'noun', 2, '可數名詞有複數（report→reports）；不可數名詞無複數（information、advice、equipment、furniture、progress、research、knowledge、news）。'),
(64, 'Compound Nouns', 'noun', 3, '複合名詞由兩個或更多詞組成，如 market research、software update、customer service。重音通常在第一個詞。書寫形式有分開、連字號或合一詞等。'),
(65, 'Order of Adjectives', 'adjective', 3, '形容詞排列順序：數量→意見→尺寸→年齡→形狀→顏色→來源→材質→目的。如 a small modern Japanese conference room。'),
(66, 'Participial Adjectives: -ed vs -ing', 'adjective', 3, '-ed 形容詞描述人的感受（I''m satisfied）；-ing 形容詞描述造成感受的事物（The results are satisfying）。混用是常見錯誤。'),
(67, 'Adverbs of Frequency', 'adverb', 2, '頻率副詞依次：always→usually/generally→often/frequently→sometimes/occasionally→rarely/seldom→never。置 be 後、主要動詞前。'),
(68, 'Adverbs of Degree', 'adverb', 3, '程度副詞強化或弱化程度：very/extremely/highly（非常）、quite/fairly/rather（相當）、somewhat/slightly（稍微）、barely/hardly（幾乎不）。'),
(69, 'Connecting Adverbs', 'adverb', 3, '連接副詞（conjunctive adverbs）連接兩個獨立子句，通常前有分號或句號後有逗號：however、therefore、moreover、furthermore、nevertheless、consequently、meanwhile。'),
(70, 'Cleft Sentences: It is...that', 'emphasis', 4, '分裂句 It is/was...that 強調句中特定成分。如 It was the CEO who approved it（強調主語）；It is the price that concerns us（強調受語）。'),
(71, 'Emphatic Do', 'emphasis', 4, '強調助動詞 do/does/did 用於強調肯定動詞，反駁懷疑或加強肯定語氣，如 We do appreciate your feedback。'),
(72, 'Subjunctive Mood', 'subjunctive', 5, '虛擬語氣用於建議/要求動詞（suggest/recommend/insist/require/demand）後的 that 子句，動詞用原形。It is essential/important/necessary + that + 原形。'),
(73, 'Wishes and Regrets: wish / if only', 'subjunctive', 4, 'wish + 過去式表現在的願望；wish + 過去完成式表過去的遺憾；wish + would 表對他人行為的期望；if only 語氣更強。'),
(74, 'Present Participle Clauses', 'participle clause', 4, '現在分詞子句（-ing 子句）表示同時進行或原因，取代副詞子句使文章更簡潔。如 Knowing the deadline, she worked overtime。'),
(75, 'Past Participle Clauses', 'participle clause', 4, '過去分詞子句（-ed 子句）通常表被動的完成動作，取代 when/after/because + passive。如 Reviewed by the team, the report was approved。'),
(76, 'Reduced Relative Clauses', 'participle clause', 4, '關係子句縮減：主動 → 現在分詞（the employee who manages = the employee managing）；被動 → 過去分詞（the report that was submitted = the report submitted）。'),
(77, 'Formal vs Informal Register', 'register', 3, '正式英語：完整形式（I am writing）、正式詞彙（assist/commence/enquire）、被動語態、避免縮寫。非正式：縮寫、口語詞彙。根據語境調整語體。'),
(78, 'Hedging Language', 'register', 4, '模糊限制語軟化陳述，表達不確定性或保持禮貌：It seems/appears that、This might/may、It would appear that、Apparently、Somewhat。廣泛用於商業分析和外交溝通。'),
(79, 'Nominalization', 'register', 4, '名詞化將動詞/形容詞轉為名詞，使文體更正式客觀。decide→decision、improve→improvement、analyze→analysis、discuss→discussion。'),
(80, 'Formal Writing: Passive and Impersonal', 'register', 4, '正式商業寫作使用被動語態（It has been decided）和非人稱結構（It is important to note that）保持客觀性，廣泛用於商業報告、提案和官方通知。'),
(81, 'Colons and Semicolons', 'punctuation', 3, '冒號（:）引出列表、解釋或強調；分號（;）連接兩個獨立但緊密相關的子句，代替句號。正確使用展現書面語言精確性。'),
(82, 'Apostrophes', 'punctuation', 2, '撇號用於縮寫（it''s = it is；we''re = we are）和所有格（the company''s policy；the managers'' reports）。注意 its（所有格）vs it''s（it is）。'),
(83, 'TOEIC: Part 5 Vocabulary in Context', 'TOEIC', 3, 'TOEIC Part 5 根據上下文選擇正確詞彙。策略：先讀完整句子，注意關鍵詞和搭配，用消去法。廣泛閱讀商業文章是提升詞彙的最佳方法。'),
(84, 'TOEIC: Part 5 Grammar Focus', 'TOEIC', 3, 'TOEIC Part 5 語法題涵蓋時態、詞類、介系詞等，需快速準確判斷。考試策略：識別空格的詞性，排除明顯錯誤，注意主謂一致。'),
(85, 'TOEIC: Part 6 Text Completion', 'TOEIC', 3, 'TOEIC Part 6 需根據整段上下文選擇正確詞彙、時態或句子。理解篇章邏輯和連貫性是關鍵，要看前後文選擇最合適的填空。'),
(86, 'TOEIC: Business Vocabulary I', 'TOEIC', 2, 'TOEIC 商業核心詞彙：合約（contract/agreement）、付款（invoice/receipt）、出貨（shipment/dispatch）、人資（recruitment/candidate）等。'),
(87, 'TOEIC: Business Vocabulary II', 'TOEIC', 2, 'TOEIC 商業詞彙進階：財務（fiscal/revenue/deficit）、策略（merger/acquisition/restructuring）、客戶關係（retention/satisfaction/complaint）等。'),
(88, 'TOEIC: Business Vocabulary III', 'TOEIC', 3, 'TOEIC 進階商業詞彙：談判（negotiate/concession）、組織（hierarchy/delegate）、數位商業（platform/scalable/disruptive）等。'),
(89, 'TOEIC: Part 7 Reading Comprehension Strategies', 'TOEIC', 3, 'TOEIC Part 7 需快速掌握文章主旨、推斷資訊及理解細節。常見題型：主旨題、細節題、詞義題、推斷題。本主題練習商業文件閱讀理解。'),
(90, 'TOEIC: Subject-Verb Agreement', 'TOEIC', 2, '主謂一致是 TOEIC 高頻考點：集合名詞、either/neither、not only...but also、there is/are、每一/all of。'),
(91, 'TOEIC: Preposition and Phrasal Verb Collocations', 'TOEIC', 3, 'TOEIC 常考介系詞固定搭配和片語動詞，如 look forward to、in charge of、deal with、carry out、put off。'),
(92, 'TOEIC: Word Forms', 'TOEIC', 3, 'TOEIC 詞形變化題考驗能否識別空格需要的詞性（名詞/動詞/形容詞/副詞），需熟悉常見詞尾：-tion、-ment、-al、-ous、-ly、-ize 等。'),
(93, 'TOEIC: Sentence Structure Errors', 'TOEIC', 3, '辨識常見語法錯誤：主謂不一致、時態錯誤、多餘詞、遺漏詞等。TOEIC Part 5 需快速識別並選出正確選項。'),
(94, 'Tag Questions', 'grammar', 3, '附加問句（疑問附加語）：陳述句用正附加，疑問句用負附加（She is here, isn''t she? / He isn''t coming, is he?）。情態動詞、完成式、被動式均有對應附加問句。'),
(95, 'Conditionals: unless / provided that / as long as', 'conditional', 3, 'unless = if not（除非）；provided (that) = on condition that（前提是）；as long as = if（只要）。這三個詞都引導條件子句，是 if 的重要替代表達。'),
(96, 'Present Perfect Continuous', 'tense', 4, '現在完成進行式（have/has been + V-ing）強調從過去持續到現在的動作，常與 for/since/all day/recently 連用，強調動作的持續性。'),
(97, 'Reported Speech: No Backshift Exceptions', 'reported speech', 4, '當報告的是普遍事實、科學真理、仍為真的情況，或報告者認為時態不需後移時，時態不必後移。正式學術和新聞英語中常見此現象。'),
(98, 'Sentence Connectors: Listing and Addition', 'conjunction', 3, '列舉和補充連接詞：firstly/secondly/finally（列舉順序）；in addition/furthermore/moreover（補充）；as well as/also/too（也）；what is more（更重要的是）。'),
(99, 'Sentence Connectors: Contrast and Concession', 'conjunction', 3, '對比讓步連接詞：however/nevertheless（然而）；on the other hand（另一方面）；by contrast（相比之下）；in spite of this（儘管如此）；even so（即便如此）。'),
(100, 'Question Forms', 'grammar', 2, '疑問句種類：Yes/No 問句（使用助動詞倒裝）；Wh- 問句（疑問詞 + 助動詞倒裝）；間接問句（陳述語序）；主語問句（疑問詞作主語，無倒裝）。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(1, 'multiple_choice', 'She _____ in the marketing department.', '["is working","work","working","works"]', 'works', 'works 用現在簡單式描述固定職責。'),
(1, 'multiple_choice', 'They _____ on a new product right now.', '["worked","works","are working","work"]', 'are working', 'right now 需用現在進行式 are working。'),
(1, 'multiple_choice', 'He usually _____ to the office by 9 a.m.', '["has arrived","is arriving","arrive","arrives"]', 'arrives', 'usually 搭配現在簡單式 arrives。'),
(1, 'multiple_choice', 'We _____ our quarterly report this week.', '["prepared","are preparing","prepare","prepares"]', 'are preparing', 'this week 暫時性，are preparing 正確。'),
(1, 'multiple_choice', 'The CEO _____ a speech at the conference tomorrow.', '["gave","give","is giving","gives"]', 'is giving', '已安排的未來，is giving 正確。'),
(1, 'multiple_choice', 'Our team _____ five days a week.', '["are working","work","works","is working"]', 'works', 'five days a week 頻率，works 三單正確。'),
(1, 'fill_blank', 'Listen! The manager _____ (speak) to the client right now.', NULL, 'is speaking', 'Listen! 表當下進行，is speaking。'),
(1, 'fill_blank', 'She always _____ (check) her emails before the meeting.', NULL, 'checks', 'always 搭配簡單式，checks 三單。'),
(1, 'multiple_choice', 'I _____ the new software is very efficient.', '["thinks","think","am thinking","thought"]', 'think', 'think 靜態動詞，不用進行式。'),
(1, 'multiple_choice', 'The sales figures _____ every quarter.', '["increases","increase","increased","are increasing"]', 'increase', 'every quarter 固定規律，簡單式 increase。'),
(1, 'fill_blank', 'Sales _____ (rise) steadily this quarter.', NULL, 'are rising', 'this quarter 當下趨勢，are rising。'),
(1, 'transform', 'The company reviews budgets quarterly. (Rewrite using: reviews)', NULL, 'The company reviews its annual budget every quarter.', '現在簡單式 reviews 表定期政策。'),
(1, 'multiple_choice', 'She _____ at three different locations this month.', '["works","worked","work","is working"]', 'is working', 'this month 暫時性，is working 正確。'),
(1, 'multiple_choice', 'We _____ international clients on a regular basis.', '["served","serve","are serving","serves"]', 'serve', 'on a regular basis 固定習慣，serve 複數主詞。'),
(1, 'fill_blank', 'Please be quiet. I _____ (concentrate) on this report.', NULL, 'am concentrating', '當下正在進行，am concentrating。'),
(1, 'multiple_choice', 'The training program _____ for new hires every six months.', '["run","runs","ran","is running"]', 'runs', 'every six months 固定週期，runs 三單。'),
(1, 'multiple_choice', 'Look at those clouds — it _____ to rain.', '["went","go","is going","goes"]', 'is going', '根據眼前跡象，is going to rain。'),
(1, 'fill_blank', 'Profits _____ (grow) faster than expected this year.', NULL, 'are growing', 'this year 當前進行趨勢，are growing。'),
(1, 'multiple_choice', 'She _____ in charge of client relations.', '["be","was","are","is"]', 'is', 'is 現在式三單，描述當前職責。'),
(1, 'multiple_choice', 'The board _____ three times a year.', '["is meeting","meets","met","meet"]', 'meets', 'three times a year 頻率，簡單式 meets。'),
(2, 'multiple_choice', 'She _____ a presentation when the power went out.', '["was giving","gives","had given","gave"]', 'was giving', '過去進行式描述背景動作 was giving；when 引入插入動作。'),
(2, 'multiple_choice', 'The team _____ the project last Friday.', '["completes","was completing","has completed","completed"]', 'completed', 'last Friday 明確時間點，過去簡單式 completed。'),
(2, 'multiple_choice', 'While I _____ the contract, my boss called.', '["had reviewed","reviewed","was reviewing","review"]', 'was reviewing', 'while 引導背景進行式 was reviewing。'),
(2, 'multiple_choice', 'He _____ the report at 10 a.m. yesterday.', '["wrote","had written","was writing","writes"]', 'was writing', 'at 10 a.m. yesterday 指過去時刻進行中，was writing。'),
(2, 'multiple_choice', 'We _____ the deal in 2022.', '["were finalizing","finalized","finalize","had finalized"]', 'finalized', 'in 2022 完成時間點，過去簡單式 finalized。'),
(2, 'fill_blank', 'When the CEO entered, everyone _____ (stand) up.', NULL, 'stood', 'stand up 是即時反應，過去簡單式 stood。'),
(2, 'fill_blank', 'They _____ (negotiate) for two hours when the client left.', NULL, 'were negotiating', '背景動作用過去進行式 were negotiating。'),
(2, 'multiple_choice', 'I _____ in Tokyo when I received the news.', '["have attended","attend","was attending","attended"]', 'was attending', '背景進行式 was attending，插入 received。'),
(2, 'multiple_choice', 'The system _____ down three times last week.', '["went","was going","goes","had gone"]', 'went', 'last week 加次數，過去簡單式 went。'),
(2, 'transform', 'She talked to the client. At the same time she reviewed the doc. (Use: while)', NULL, 'While she was talking to the client, she reviewed the document.', 'while 引導背景進行式，主句過去簡單式。'),
(2, 'fill_blank', 'He _____ (travel) to Singapore when his flight got delayed.', NULL, 'was travelling', '背景動作用過去進行式 was travelling。'),
(2, 'multiple_choice', 'The review _____ three hours.', '["was lasting","has lasted","lasted","lasts"]', 'lasted', '過去簡單式 lasted 描述完整持續時間。'),
(2, 'multiple_choice', 'What _____ you _____ at 3 p.m. Thursday?', '["did / do","have / done","do / doing","were / doing"]', 'were / doing', 'at 3 p.m. 過去時刻，過去進行式疑問句。'),
(2, 'fill_blank', 'As I _____ (prepare) the slides, I noticed an error.', NULL, 'was preparing', 'As 引導背景動作，過去進行式 was preparing。'),
(2, 'multiple_choice', 'The new policy _____ effect in January last year.', '["was taking","takes","took","had taken"]', 'took', '明確時間，過去簡單式 took effect。'),
(2, 'multiple_choice', 'She _____ the file when her computer crashed.', '["updates","had updated","updated","was updating"]', 'was updating', '背景 was updating，插入 crashed。'),
(2, 'fill_blank', 'The team _____ (celebrate) when they heard the news.', NULL, 'was celebrating', '背景動作用過去進行式 was celebrating。'),
(2, 'multiple_choice', 'The conference _____ for three days.', '["lasts","lasted","was lasting","has lasted"]', 'lasted', '過去簡單式 lasted 描述完成持續。'),
(2, 'transform', 'He worked at the office. Then his phone rang. (Use: was working when)', NULL, 'He was working at the office when his phone rang.', 'was working 背景進行式，when 引入插入動作。'),
(2, 'multiple_choice', 'I _____ the client when my manager interrupted.', '["have called","was calling","called","call"]', 'was calling', '背景 was calling，插入 interrupted。'),
(3, 'multiple_choice', 'We _____ the new system last month.', '["were implementing","implement","implemented","have implemented"]', 'implemented', 'last month 明確過去，過去簡單式 implemented。'),
(3, 'multiple_choice', 'The company _____ its revenue by 20% this year.', '["increase","increased","has increased","was increasing"]', 'has increased', 'this year 到目前，現在完成式 has increased。'),
(3, 'fill_blank', 'She _____ (work) here for five years.', NULL, 'has worked', 'for five years 持續到現在，has worked。'),
(3, 'multiple_choice', 'Have you _____ the client''s requirements?', '["review","were reviewing","reviewed","reviewing"]', 'reviewed', 'Have you + 過去分詞，現在完成式疑問句。'),
(3, 'fill_blank', 'Profits _____ (rise) steadily since the restructuring.', NULL, 'have risen', 'since 搭配現在完成式 have risen。'),
(3, 'multiple_choice', 'This is the best quarter our company _____.', '["was ever having","ever had","had ever","has ever had"]', 'has ever had', 'ever 搭配最高級使用現在完成式。'),
(3, 'transform', 'We launched the product. It is now in 30 markets. (Use: have launched)', NULL, 'We have launched the product and it is now in 30 markets.', '現在完成式連結過去行動與現在狀態。'),
(3, 'multiple_choice', 'They _____ their headquarters to Singapore.', '["move","were moving","have moved","moved"]', 'have moved', '強調結果，現在完成式 have moved。'),
(3, 'fill_blank', 'The manager _____ just _____ (return) from the trade fair.', NULL, 'has / returned', 'just 搭配現在完成式。'),
(3, 'multiple_choice', 'We _____ this client for over ten years.', '["are serving","served","have served","serve"]', 'have served', 'for over ten years 持續到現在，have served。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(3, 'multiple_choice', 'The report _____ not been submitted yet.', '["have","has","had","was"]', 'has', 'report 單數，has not been submitted yet。'),
(3, 'fill_blank', 'How long _____ you _____ (be) in this role?', NULL, 'have / been', 'How long + have + 主詞 + been 問持續時間。'),
(3, 'multiple_choice', 'Our new policy _____ already _____ results.', '["has / produced","is / producing","have / produced","had / produced"]', 'has / produced', 'already 搭配現在完成式，policy 單數 has。'),
(3, 'multiple_choice', 'She _____ three conferences this year.', '["attends","was attending","has attended","attended"]', 'has attended', 'this year 到目前，現在完成式。'),
(3, 'transform', 'I have never visited Seoul. (Use: first time)', NULL, 'This is the first time I have visited Seoul.', 'first time + 現在完成式表達首次經驗。'),
(3, 'fill_blank', 'The board _____ (approve) the proposal this morning.', NULL, 'has approved', 'this morning 仍在今天，has approved。'),
(3, 'multiple_choice', 'Sales _____ doubled since the campaign launched.', '["have","had","has","are"]', 'have', 'Sales 複數，have doubled。'),
(3, 'multiple_choice', 'I _____ just _____ an email from the client.', '["did / receive","had / received","have / received","was / receiving"]', 'have / received', 'just 搭配現在完成式。'),
(3, 'multiple_choice', 'The team _____ the prototype three times this week.', '["has tested","tested","was testing","test"]', 'has tested', 'this week 到目前，has tested。'),
(3, 'multiple_choice', 'She _____ not yet _____ the draft contract.', '["has / finalized","did / finalize","had / finalized","is / finalizing"]', 'has / finalized', 'not yet 搭配現在完成式 has not finalized。'),
(4, 'multiple_choice', 'I _____ the report an hour ago.', '["have submitted","submit","submitted","was submitting"]', 'submitted', 'an hour ago 過去時間點，過去簡單式 submitted。'),
(4, 'multiple_choice', 'We _____ our target this quarter so far.', '["were exceeding","exceed","exceeded","have exceeded"]', 'have exceeded', 'so far 到現在，現在完成式 have exceeded。'),
(4, 'multiple_choice', 'She _____ the company in 2015.', '["join","joined","had joined","has joined"]', 'joined', 'in 2015 明確過去，過去簡單式 joined。'),
(4, 'fill_blank', 'Have you _____ (send) the invoice yet?', NULL, 'sent', 'yet 搭配現在完成式，sent 是 send 的過去分詞。'),
(4, 'multiple_choice', 'The last product launch _____ very successful.', '["has been","were","was","is"]', 'was', 'last product launch 過去特定事件，was。'),
(4, 'multiple_choice', 'The company _____ three offices since 2010.', '["opens","has opened","opened","was opening"]', 'has opened', 'since 2010 到現在，has opened。'),
(4, 'fill_blank', 'We _____ (not / receive) any feedback yet.', NULL, 'have not received', 'yet 否定句搭配現在完成式。'),
(4, 'multiple_choice', 'Did you _____ the presentation last Tuesday?', '["delivering","delivered","deliver","have delivered"]', 'deliver', 'Did you + 原形動詞，過去式疑問句。'),
(4, 'transform', 'The price dropped and is still low for three months. (Use: has dropped)', NULL, 'The price has dropped and has remained low for three months.', '現在完成式強調持續到現在的結果。'),
(4, 'multiple_choice', 'This is the third time he _____ late this month.', '["is","had been","has been","was"]', 'has been', 'this month 到現在累積，has been。'),
(4, 'multiple_choice', 'The auditors _____ the accounts last week.', '["were checking","have checked","checked","check"]', 'checked', 'last week 明確過去，過去簡單式 checked。'),
(4, 'fill_blank', 'How many deals _____ the team _____ (close) this quarter?', NULL, 'has / closed', 'this quarter 到目前，現在完成式疑問句。'),
(4, 'multiple_choice', 'We _____ a new office in Berlin last year.', '["open","had opened","have opened","opened"]', 'opened', 'last year 明確過去，過去簡單式 opened。'),
(4, 'multiple_choice', 'Our profits _____ significantly since we restructured.', '["have grown","are growing","grew","grow"]', 'have grown', 'since 搭配現在完成式 have grown。'),
(4, 'transform', 'I lost the contract six months ago. (Use: ago)', NULL, 'I lost the contract six months ago.', 'ago 搭配過去簡單式。'),
(4, 'fill_blank', 'The CEO _____ (step down) last Friday.', NULL, 'stepped down', 'last Friday 明確過去，過去簡單式 stepped down。'),
(4, 'multiple_choice', 'They _____ never _____ such strong demand before.', '["did / see","were / seeing","have / seen","had / seen"]', 'have / seen', 'never + 現在完成式表從未有的經驗。'),
(4, 'multiple_choice', 'When _____ the merger _____?', '["had / happened","has / happened","did / happen","was / happening"]', 'did / happen', 'When 問明確時間，過去簡單式疑問句。'),
(4, 'fill_blank', 'We _____ (partner) with three new suppliers since January.', NULL, 'have partnered', 'since January 到現在，現在完成式。'),
(4, 'multiple_choice', 'I _____ him at the trade fair in April.', '["meet","was meeting","met","have met"]', 'met', 'in April 過去時間點，過去簡單式 met。'),
(5, 'multiple_choice', 'By the time the client arrived, we _____ all the documents.', '["have prepared","were preparing","had prepared","prepared"]', 'had prepared', 'by the time 建立先後，had prepared 在到達前完成。'),
(5, 'multiple_choice', 'She realized she _____ the wrong file.', '["was sending","has sent","had sent","sent"]', 'had sent', 'realized 在過去，發送更早，過去完成式 had sent。'),
(5, 'fill_blank', 'Before the meeting started, the team _____ (review) the agenda.', NULL, 'had reviewed', 'before 表先後，更早的動作用過去完成式。'),
(5, 'multiple_choice', 'When I arrived, the presentation _____ already _____.', '["had / started","has / started","did / start","was / starting"]', 'had / started', 'already + 過去完成式；had started。'),
(5, 'multiple_choice', 'He _____ never _____ such a complex contract before.', '["was / negotiating","did / negotiate","had / negotiated","has / negotiated"]', 'had / negotiated', 'never + 過去完成式表從未有的經驗。'),
(5, 'transform', 'First we submitted. Then we received approval. (Use: had submitted)', NULL, 'We had submitted the proposal before we received approval.', 'had submitted 描述更早的動作。'),
(5, 'multiple_choice', 'By the end of Q3, we _____ the annual target.', '["were exceeding","exceeded","had exceeded","have exceeded"]', 'had exceeded', 'by the end of Q3 設定過去時間點，had exceeded。'),
(5, 'fill_blank', 'The client _____ (already / sign) the NDA before the first meeting.', NULL, 'had already signed', 'before 連接兩個過去事件，更早用過去完成式。'),
(5, 'multiple_choice', 'I discovered that my colleague _____ the same research.', '["conducted","was conducting","has conducted","had conducted"]', 'had conducted', 'discovered 過去，研究更早，had conducted。'),
(5, 'multiple_choice', 'They _____ the merger long before it was announced.', '["had planned","were planning","planned","have planned"]', 'had planned', 'long before 強調先後，had planned。'),
(5, 'fill_blank', 'Once the audit _____ (complete), the results were presented.', NULL, 'had been completed', 'once 引導過去完成被動式。'),
(5, 'multiple_choice', 'The product had been on the market two years before it _____ a profit.', '["had made","made","was making","makes"]', 'made', 'made 是後發生的過去事件，簡單過去式。'),
(5, 'multiple_choice', 'We _____ already _____ a similar service before the client asked.', '["did / develop","were / developing","have / developed","had / developed"]', 'had / developed', 'already + 過去完成式 had developed。'),
(5, 'transform', 'The team finished. Then the director reviewed it. (Use: had finished)', NULL, 'By the time the director reviewed it, the team had finished the report.', 'had finished 在 reviewed 之前完成。'),
(5, 'fill_blank', 'I realized I _____ (forget) to include the appendix.', NULL, 'had forgotten', 'realized 在過去，forget 更早，had forgotten。'),
(5, 'multiple_choice', 'All the guests _____ when the CEO made her announcement.', '["have arrived","arrived","were arriving","had arrived"]', 'had arrived', 'when the CEO made 設定過去時間點，had arrived 已到。'),
(5, 'multiple_choice', 'They _____ not _____ the terms before signing.', '["had / understood","did / understand","have / understood","were / understanding"]', 'had / understood', '簽約前的過去完成式否定。'),
(5, 'fill_blank', 'The company _____ (expand) into Asia before the crisis hit.', NULL, 'had expanded', 'before 建立先後，更早用過去完成式。'),
(5, 'multiple_choice', 'By the time I joined, the company _____ its strategy.', '["already revised","has already revised","was already revising","had already revised"]', 'had already revised', 'had already revised 過去完成式。'),
(5, 'multiple_choice', 'She found out that the deal _____ without her approval.', '["had approved","had been approved","has been approved","was approved"]', 'had been approved', '過去完成被動式 had been approved。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(6, 'multiple_choice', 'I _____ send you the contract as soon as it''s ready.', '["am going to","was","would","will"]', 'will', 'will 表即時承諾；am going to 也可，但 will 更常見於即時承諾。'),
(6, 'multiple_choice', 'We _____ launch the new product line next spring. Everything is planned.', '["would","were going to","will","are going to"]', 'are going to', '已計劃好的意圖用 be going to；will 表臨時決定。'),
(6, 'multiple_choice', 'Look at those sales numbers — this _____ be our best year ever!', '["is going to","was going to","would","will"]', 'is going to', '根據眼前證據預測，用 be going to。'),
(6, 'fill_blank', 'I just decided — I _____ (take) the overseas assignment.', NULL, 'will take', 'just decided 表臨時決定，用 will。'),
(6, 'multiple_choice', 'The director _____ give a speech at the annual banquet next month.', '["would","was going to","is going to","will"]', 'is going to', 'next month 已排定計劃，be going to 更合適。'),
(6, 'transform', 'It is planned that the company expands to Europe next year. (Use: going to)', NULL, 'The company is going to expand to Europe next year.', '已計劃的意圖用 be going to。'),
(6, 'multiple_choice', 'Don''t worry, I _____ help you with the report.', '["was going to","would","will","am going to"]', 'will', '即時答應幫忙，will 最自然。'),
(6, 'fill_blank', 'We _____ (hold) the annual conference in Dubai. All arrangements are made.', NULL, 'are going to hold', '已安排好的計劃，be going to 正確。'),
(6, 'multiple_choice', 'It looks like the project _____ be delayed.', '["will","is going to","was going to","would"]', 'is going to', '根據現有跡象預測，be going to。'),
(6, 'multiple_choice', 'She _____ be the new CFO. It was announced yesterday.', '["would be","is going to","was going to","will"]', 'is going to', '已宣布的計劃，be going to。'),
(6, 'fill_blank', 'Someone has to present this. — OK, I _____ (do) it.', NULL, 'will do', '即時決定，will do。'),
(6, 'multiple_choice', 'By this time next year, we _____ have doubled our market share.', '["would","are going to","will","were going to"]', 'will', '未來完成式 will have doubled，預測未來時間點前完成。'),
(6, 'transform', 'The manager has decided to retire in July. (Use: going to retire)', NULL, 'The manager is going to retire in July.', '已決定的計劃，be going to。'),
(6, 'multiple_choice', 'I _____ definitely call you back after the meeting.', '["am going to","would","was going to","will"]', 'will', '即時承諾用 will。'),
(6, 'fill_blank', 'The negotiation _____ (start) at 2 p.m. It''s on the schedule.', NULL, 'is going to start', '已排定計劃，be going to start。'),
(6, 'multiple_choice', 'There''s no way around it — we _____ need more funding.', '["would","are going to","will","were going to"]', 'will', '客觀預測用 will；are going to 也可。'),
(6, 'multiple_choice', 'She promised she _____ send the invoice today.', '["will","would","was going to","is going to"]', 'would', 'promised 後的間接引語用 would。'),
(6, 'fill_blank', 'Watch out! That pile of documents _____ (fall).', NULL, 'is going to fall', '根據眼前情況的即時預測，be going to。'),
(6, 'multiple_choice', 'We _____ restructure the department. We''ve been planning it for months.', '["would","will","are going to","were going to"]', 'are going to', '幾個月的計劃，be going to。'),
(6, 'multiple_choice', 'I think the market _____ recover by Q3.', '["will","would","was going to","is going to"]', 'will', '主觀預測用 will。'),
(7, 'multiple_choice', 'By next Friday, we _____ the audit report.', '["will be submitting","are submitting","will submit","will have submitted"]', 'will have submitted', 'by next Friday 搭配未來完成式 will have submitted。'),
(7, 'multiple_choice', 'This time next week, I _____ the annual conference in London.', '["will attend","will have attended","attend","will be attending"]', 'will be attending', 'this time next week 指未來某時刻進行中，will be attending。'),
(7, 'fill_blank', 'By the end of this year, the company _____ (open) ten new branches.', NULL, 'will have opened', 'by the end of this year 搭配未來完成式。'),
(7, 'multiple_choice', 'Don''t call at 3 p.m. — she _____ her presentation then.', '["gives","will have given","will be giving","will give"]', 'will be giving', 'at 3 p.m. 未來時刻正在進行，will be giving。'),
(7, 'multiple_choice', 'We _____ the new platform for six months by December.', '["will have been using","will use","have been using","will be using"]', 'will have been using', 'by December 強調持續時間完成，未來完成進行式。'),
(7, 'transform', 'The project ends on March 31. (Use: will have completed by)', NULL, 'We will have completed the project by March 31.', 'by + 未來時間點，搭配未來完成式。'),
(7, 'multiple_choice', 'I _____ in this role for ten years next June.', '["have been working","will work","will have been working","will be working"]', 'will have been working', 'next June 到那時累積10年，未來完成進行式。'),
(7, 'fill_blank', 'By the time you read this, the meeting _____ (start) already.', NULL, 'will have already started', 'by the time 搭配未來完成式。'),
(7, 'multiple_choice', 'At this time tomorrow, they _____ final contract terms.', '["negotiate","will have negotiated","will be negotiating","will negotiate"]', 'will be negotiating', 'this time tomorrow 未來某時刻進行中，will be negotiating。'),
(7, 'multiple_choice', 'We _____ 1,000 units by the end of Q2.', '["will ship","will be shipping","will have shipped","are shipping"]', 'will have shipped', 'by the end of Q2 搭配未來完成式 will have shipped。'),
(7, 'fill_blank', 'This time next month, I _____ (work) in our Singapore office.', NULL, 'will be working', 'this time next month 未來時刻正在進行。'),
(7, 'multiple_choice', 'By 2027, the company _____ its expansion into five new markets.', '["will have completed","will be completing","completes","will complete"]', 'will have completed', 'by 2027 搭配未來完成式。'),
(7, 'multiple_choice', 'She _____ in the middle of her vacation when you call.', '["will be relaxing","relaxes","will have relaxed","will relax"]', 'will be relaxing', 'when you call 那個時間點正在休假，will be relaxing。'),
(7, 'transform', 'The renovation ends before the clients arrive. (Use: will have finished)', NULL, 'The renovation will have finished before the clients arrive.', 'before 搭配未來完成式。'),
(7, 'fill_blank', 'By the end of Q4, total revenue _____ (reach) $10 million.', NULL, 'will have reached', 'by the end of Q4 搭配未來完成式。'),
(7, 'multiple_choice', 'Don''t disturb the CEO at 2 p.m. — she _____ an important call.', '["will be having","has","will have had","will have"]', 'will be having', '2 p.m. 未來時刻進行中，will be having。'),
(7, 'multiple_choice', 'We _____ this software for a year by next January.', '["will have been using","have used","will use","will be using"]', 'will have been using', 'by next January 累積一年，未來完成進行式。'),
(7, 'fill_blank', 'By the time the new hire starts, we _____ (complete) the onboarding materials.', NULL, 'will have completed', 'by the time 搭配未來完成式。'),
(7, 'multiple_choice', 'This time next year, the team _____ in a brand new office.', '["works","will be working","will have worked","will work"]', 'will be working', 'this time next year 未來時刻進行。'),
(7, 'multiple_choice', 'By 2030, we _____ 500 employees worldwide.', '["will be hiring","will have hired","are hiring","will hire"]', 'will have hired', 'by 2030 搭配未來完成式 will have hired。'),
(8, 'multiple_choice', 'She _____ the company for three years when she _____ her first promotion.', '["has been working / receives","was working / has received","worked / was receiving","had been working / received"]', 'had been working / received', 'had been working 表在 received 之前持續的動作。'),
(8, 'multiple_choice', 'By the time I _____ tomorrow, the deal _____.', '["will arrive / is signed","arrived / had been signed","arrive / will have been signed","am arriving / will sign"]', 'arrive / will have been signed', 'arrive 時間子句用現在式，主句用未來完成被動式。'),
(8, 'multiple_choice', 'We _____ the market every year, but this year we _____ something different.', '["analyse / tried","have analysed / tried","analyse / are trying","analysed / tried"]', 'analyse / are trying', 'every year 簡單式，this year 進行式（暫時策略）。'),
(8, 'fill_blank', 'The team _____ (just / finish) the report when the client _____ (call).', NULL, 'had just finished / called', 'had just finished 過去完成，called 插入動作。'),
(8, 'multiple_choice', 'She _____ in marketing for ten years before she _____ to management.', '["worked / has moved","had worked / moved","was working / moved","has worked / moves"]', 'had worked / moved', '在 moved 之前的持續，had worked；then moved。'),
(8, 'multiple_choice', 'I _____ a lot of business trips lately, so I _____ quite tired.', '["took / was","had taken / was","have been taking / am","take / am"]', 'have been taking / am', 'lately 現在完成進行式，result 現在狀態。'),
(8, 'multiple_choice', 'As soon as she _____ the budget, she _____ the board.', '["is approving / will inform","approved / informed","will approve / informs","approves / will inform"]', 'approves / will inform', 'as soon as 時間子句用現在式，主句用 will。'),
(8, 'transform', 'The company lost money last year. Now it is profitable. (Use appropriate tenses)', NULL, 'The company lost money last year, but it has become profitable now.', 'lost 過去式；has become 現在完成式表狀態改變。'),
(8, 'multiple_choice', 'When I came into the office, she _____ already _____ all the preparations.', '["did / make","has / made","had / made","was / making"]', 'had / made', 'came 過去，preparations 更早完成，had made。'),
(8, 'fill_blank', 'Sales _____ (increase) every quarter since the new strategy _____ (implement).', NULL, 'have increased / was implemented', 'since 搭配現在完成式；被動過去式 was implemented。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(8, 'multiple_choice', 'He _____ the company before it _____ public.', '["was leaving / had gone","leaves / goes","left / has gone","had left / went"]', 'had left / went', '左邊更早 had left；然後 went public。'),
(8, 'multiple_choice', 'The factory _____ at full capacity when the order _____.', '["was operating / arrived","is operating / will arrive","has been operating / arrives","operated / was arriving"]', 'was operating / arrived', '背景進行式 was operating，插入 arrived。'),
(8, 'multiple_choice', 'By next March, she _____ in management for five years.', '["will have been","was","has been","will be"]', 'will have been', 'by next March 未來時間點，will have been。'),
(8, 'fill_blank', 'I _____ (not / see) her since she _____ (transfer) to the Hong Kong office.', NULL, 'have not seen / was transferred', 'since 搭配現在完成式；transferred 被動過去式。'),
(8, 'multiple_choice', 'While we _____ the presentation, our server _____ down.', '["prepared / was going","prepare / goes","had prepared / went","were preparing / went"]', 'were preparing / went', '背景進行式 were preparing，插入 went down。'),
(8, 'multiple_choice', 'She _____ this role for two years by the time she _____ her MBA.', '["held / finished","will have held / finishes","holds / finishes","has held / finishes"]', 'will have held / finishes', 'by the time 未來完成式 will have held；時間子句用現在式。'),
(8, 'multiple_choice', 'The client _____ before we _____ to respond.', '["had left / had time","has left / have time","was leaving / had time","left / have time"]', 'had left / had time', 'had left 和 had time 兩個過去完成式，強調均在主句時間前。'),
(8, 'transform', 'First the budget was approved. Then the project started. (Use: had been approved)', NULL, 'The project started after the budget had been approved.', 'after 連接：had been approved 更早，started 後來。'),
(8, 'multiple_choice', 'She _____ three proposals this week and _____ two of them.', '["has written / submitted","wrote / has submitted","is writing / submitted","writes / submits"]', 'has written / submitted', 'this week 現在完成式，且已提交也是本週。'),
(8, 'multiple_choice', 'He rarely _____ late, but yesterday he _____ the whole morning.', '["is / missed","is / has missed","has been / missed","was / misses"]', 'is / missed', 'rarely is 習慣；yesterday missed 過去事件。'),
(9, 'multiple_choice', 'Please send me _____ contract you mentioned in your email.', '["a","the","—","an"]', 'the', 'mentioned 已知，雙方都知的特定合約，用 the。'),
(9, 'multiple_choice', 'She is _____ CEO of a Fortune 500 company.', '["—","an","a","the"]', 'the', 'CEO 是獨一無二的職位，且特指某公司，用 the。'),
(9, 'multiple_choice', 'We need to review _____ annual budget before the board meeting.', '["the","—","an","a"]', 'the', 'annual budget 是特定文件，用 the。'),
(9, 'multiple_choice', 'This is _____ most efficient solution we''ve found.', '["a","an","—","the"]', 'the', '最高級前用 the。'),
(9, 'fill_blank', 'I met _____ client you recommended. He was very professional.', NULL, 'the', 'you recommended 使其特定化，用 the。'),
(9, 'multiple_choice', 'She gave _____ speech at _____ conference last week.', '["a / the","a / a","the / a","the / the"]', 'a / the', 'speech 首次提及用 a；conference 已知特定活動用 the。'),
(9, 'multiple_choice', '_____ new product launch was a great success.', '["The","An","—","A"]', 'The', '特定的新產品發表（已知事件），用 The。'),
(9, 'multiple_choice', 'Can you go over _____ proposal one more time?', '["the","an","a","—"]', 'the', '已知特定提案，用 the。'),
(9, 'transform', 'Our company has a headquarters. It is in Tokyo. (Use: the)', NULL, 'Our company''s headquarters is in the heart of Tokyo.', 'headquarters 特指，用 the。'),
(9, 'multiple_choice', 'We discussed _____ merger at _____ last board meeting.', '["the / a","the / the","a / a","a / the"]', 'the / the', '已知的合併案和上次的董事會議，均用 the。'),
(9, 'fill_blank', 'Could you book _____ meeting room on the third floor?', NULL, 'the', '特定的三樓會議室，用 the。'),
(9, 'multiple_choice', 'This is _____ first time we''ve worked with this supplier.', '["the","an","a","—"]', 'the', '第一次（序數概念），用 the first time。'),
(9, 'multiple_choice', '_____ finance team will present _____ results next Tuesday.', '["The / a","The / the","A / the","A / a"]', 'The / the', '已知部門和已知結果，均用 the。'),
(9, 'multiple_choice', 'It''s _____ best deal we''ve ever made.', '["the","an","a","—"]', 'the', '最高級 best 前用 the。'),
(9, 'fill_blank', 'We are aiming for _____ top position in _____ market.', NULL, 'the / the', 'top position 特指，market 已知特定市場，均用 the。'),
(9, 'multiple_choice', 'She is in charge of _____ Asia-Pacific region.', '["the","—","a","an"]', 'the', '地理區域名稱前通常用 the。'),
(9, 'multiple_choice', 'I''ll forward you _____ minutes of today''s meeting.', '["—","a","an","the"]', 'the', '特定的今天會議記錄，用 the。'),
(9, 'multiple_choice', 'We need _____ decision by Friday.', '["—","a","the","an"]', 'a', '首次提及，未特定的某個決定，用 a。'),
(9, 'transform', 'There is only one director of operations. (Use: the)', NULL, 'Please contact the director of operations regarding this issue.', '職稱加上唯一性，用 the。'),
(9, 'multiple_choice', '_____ productivity in our team has improved significantly.', '["An","—","The","A"]', 'The', '特指我們團隊的生產力，用 The。'),
(10, 'multiple_choice', 'She submitted _____ expense report this morning.', '["an","the","a","—"]', 'an', 'expense 以母音音素 /e/ 開頭，用 an。'),
(10, 'multiple_choice', 'We need to hire _____ experienced project manager.', '["the","an","—","a"]', 'an', 'experienced 以母音音素 /e/ 開頭，用 an。'),
(10, 'multiple_choice', 'He has _____ MBA from a top university.', '["an","a","the","—"]', 'an', 'MBA 發音 /em biː eɪ/，M 發母音音素，用 an。'),
(10, 'multiple_choice', 'Can you send _____ update by end of day?', '["—","the","an","a"]', 'an', 'update 以母音音素 /ʌ/ 開頭，用 an。'),
(10, 'multiple_choice', 'She made _____ excellent presentation to the board.', '["a","the","an","—"]', 'an', 'excellent 以母音音素 /e/ 開頭，用 an。'),
(10, 'fill_blank', 'We are looking for _____ office in _____ central location.', NULL, 'an / a', 'office 母音開頭 an；central 輔音開頭 a。'),
(10, 'multiple_choice', 'It was _____ unique opportunity that we couldn''t pass up.', '["—","a","the","an"]', 'a', 'unique 發音 /juːniːk/，以 /j/ 輔音音素開頭，用 a。'),
(10, 'multiple_choice', 'Please prepare _____ agenda for the meeting.', '["—","a","an","the"]', 'an', 'agenda 以母音音素 /æ/ 開頭，用 an。'),
(10, 'multiple_choice', 'He is _____ honest and dedicated employee.', '["—","an","a","the"]', 'an', 'honest 以母音音素 /ɒ/ 開頭（h 不發音），用 an。'),
(10, 'transform', 'Please write one report per week. (Use: a)', NULL, 'Please submit a report every week.', 'a 用於泛指一份報告。'),
(10, 'multiple_choice', 'That was _____ one-time offer.', '["—","the","an","a"]', 'a', 'one-time 發音 /wʌn/，以 /w/ 輔音音素開頭，用 a。'),
(10, 'multiple_choice', 'She gave _____ half-hour presentation.', '["the","—","an","a"]', 'a', 'half-hour 發音 /hɑːf/，以 /h/ 輔音音素開頭，用 a。'),
(10, 'fill_blank', 'It was _____ historic moment for our company.', NULL, 'a', 'historic 發音 /hɪˈstɒrɪk/，以 /h/ 開頭，用 a（英式有人用 an）。'),
(10, 'multiple_choice', 'He is _____ EU representative attending the summit.', '["a","—","an","the"]', 'a', 'EU 發音 /juː/，以 /j/ 輔音音素開頭，用 a。'),
(10, 'multiple_choice', 'We had _____ informal meeting with the client.', '["a","—","the","an"]', 'an', 'informal 以母音音素 /ɪ/ 開頭，用 an。'),
(10, 'multiple_choice', 'She received _____ award for outstanding performance.', '["—","the","a","an"]', 'an', 'award 以母音音素 /ə/ 開頭，用 an。'),
(10, 'fill_blank', 'This is _____ once-in-a-lifetime opportunity.', NULL, 'a', 'once 發音 /wʌns/，以 /w/ 輔音音素開頭，用 a。'),
(10, 'multiple_choice', 'He sent _____ urgent email to the entire team.', '["a","the","—","an"]', 'an', 'urgent 以母音音素 /ʌ/ 開頭，用 an。'),
(10, 'multiple_choice', 'She is _____ account manager at our firm.', '["an","the","a","—"]', 'an', 'account 以母音音素 /ə/ 開頭，用 an。'),
(10, 'multiple_choice', 'They issued _____ official statement this morning.', '["—","a","an","the"]', 'an', 'official 以母音音素 /ə/ 開頭，用 an。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(11, 'multiple_choice', '_____ information you need is on the company website.', '["A","The","—","An"]', 'The', '特定資訊（you need 限定），用 The。'),
(11, 'multiple_choice', 'She travels to _____ Japan every quarter for business.', '["an","—","a","the"]', '—', '國家名通常不加冠詞。'),
(11, 'multiple_choice', 'We communicate mostly by _____ email.', '["the","a","—","an"]', '—', 'by email 固定搭配，零冠詞。'),
(11, 'multiple_choice', '_____ managers are responsible for team performance.', '["The","A","—","An"]', '—', '泛指所有管理者，複數名詞泛稱，零冠詞。'),
(11, 'fill_blank', 'She goes to _____ work by subway every day.', NULL, '—（不加冠詞）', 'go to work 固定搭配，零冠詞。'),
(11, 'multiple_choice', '_____ knowledge is essential in today''s business world.', '["—","An","The","A"]', '—', 'knowledge 不可數泛稱，零冠詞。'),
(11, 'multiple_choice', 'We had _____ lunch with the new partners.', '["an","the","—","a"]', '—', 'have lunch 固定搭配，零冠詞（也可 a business lunch）。'),
(11, 'multiple_choice', 'The company invested heavily in _____ technology last year.', '["the","a","—","an"]', '—', 'technology 不可數泛稱，零冠詞。'),
(11, 'transform', 'The advice from experts is valuable. (Use zero article for advice)', NULL, 'Advice from experts is always valuable in business.', 'advice 不可數泛稱，零冠詞。'),
(11, 'multiple_choice', 'He is based in _____ New York.', '["a","the","—","an"]', '—', '城市名一般不加冠詞。'),
(11, 'multiple_choice', '_____ progress has been made on the project.', '["A","An","The","—"]', '—', 'progress 不可數泛稱，零冠詞（如要特指則用 The progress）。'),
(11, 'multiple_choice', 'Could you send the report by _____ post?', '["an","a","the","—"]', '—', 'by post 固定搭配，零冠詞。'),
(11, 'fill_blank', 'We need to improve _____ communication within the team.', NULL, '—（不加冠詞）', 'communication 不可數泛稱，零冠詞。'),
(11, 'multiple_choice', 'She joined _____ Microsoft after graduating.', '["an","—","a","the"]', '—', '公司名專有名詞通常不加冠詞。'),
(11, 'multiple_choice', 'We are making _____ good progress on the project.', '["—","the","an","a"]', '—', 'make progress 固定搭配中，good progress 零冠詞。'),
(11, 'multiple_choice', 'He was promoted to _____ director last month.', '["—","a","the","an"]', '—', 'become/be appointed + 職稱，零冠詞。'),
(11, 'fill_blank', '_____ teamwork is crucial for project success.', NULL, '—（不加冠詞）', 'teamwork 不可數泛稱，零冠詞。'),
(11, 'multiple_choice', 'The CEO went to _____ university in the UK.', '["a","—","the","an"]', '—', 'go to university 固定搭配，零冠詞。'),
(11, 'multiple_choice', '_____ automation is transforming the manufacturing industry.', '["An","The","—","A"]', '—', 'automation 不可數泛稱，零冠詞。'),
(11, 'multiple_choice', 'We need to focus on _____ customer satisfaction.', '["—","an","the","a"]', '—', '泛指顧客滿意度，不可數概念，零冠詞。'),
(12, 'multiple_choice', 'The meeting is scheduled _____ 10 a.m.', '["on","in","at","by"]', 'at', '精確時間點用 at。'),
(12, 'multiple_choice', 'The product was launched _____ 2021.', '["on","by","in","at"]', 'in', '年份用 in。'),
(12, 'multiple_choice', 'We have a client call _____ Tuesday.', '["on","at","by","in"]', 'on', '星期幾用 on。'),
(12, 'multiple_choice', 'I''ll send you the report _____ the morning.', '["at","by","on","in"]', 'in', 'the morning/afternoon/evening 用 in。'),
(12, 'fill_blank', 'The contract expires _____ March 31st.', NULL, 'on', '特定日期用 on。'),
(12, 'multiple_choice', 'She joined the company _____ January.', '["in","at","by","on"]', 'in', '月份用 in。'),
(12, 'multiple_choice', 'The office opens _____ 9 o''clock.', '["at","by","in","on"]', 'at', '精確時間點用 at。'),
(12, 'multiple_choice', 'We should finalize the deal _____ the end of the month.', '["in","at","on","by"]', 'by', 'deadline 截止日期用 by。'),
(12, 'transform', 'The conference happens in the third week of August. (Use: on)', NULL, 'The conference is on August 18th.', '具體日期用 on。'),
(12, 'multiple_choice', 'The project started _____ the summer.', '["at","on","by","in"]', 'in', 'the summer 季節用 in。'),
(12, 'multiple_choice', 'She usually works late _____ Fridays.', '["at","by","on","in"]', 'on', '星期幾用 on。'),
(12, 'fill_blank', 'The team meeting is _____ noon every Wednesday.', NULL, 'at', 'noon 是特定時間點，用 at。'),
(12, 'multiple_choice', 'The deal was signed _____ midnight.', '["at","in","on","by"]', 'at', 'midnight 是精確時間點，用 at。'),
(12, 'multiple_choice', 'Our fiscal year ends _____ December.', '["at","on","in","by"]', 'in', '月份用 in。'),
(12, 'multiple_choice', 'He was promoted _____ 2023.', '["by","on","in","at"]', 'in', '年份用 in。'),
(12, 'fill_blank', 'The workshop is scheduled _____ the afternoon of June 5th.', NULL, 'on the afternoon of', '特定日期的下午用 on the afternoon of。'),
(12, 'multiple_choice', 'She will return from leave _____ Monday morning.', '["in","by","at","on"]', 'on', 'Monday morning 特定時間組合用 on。'),
(12, 'multiple_choice', 'The proposal is due _____ the end of this week.', '["on","in","at","by"]', 'by', 'due 截止用 by。'),
(12, 'multiple_choice', 'We met _____ a conference in Singapore _____ 2022.', '["at / in","in / in","on / in","at / at"]', 'at / in', 'conference 地點 at；year 用 in。'),
(12, 'multiple_choice', 'The company was founded _____ the early 1990s.', '["by","in","at","on"]', 'in', 'decade 用 in the 1990s。'),
(13, 'multiple_choice', 'The manager is _____ her office right now.', '["on","at","in","by"]', 'in', 'office 是封閉空間，用 in。'),
(13, 'multiple_choice', 'Please meet me _____ the reception desk.', '["by","in","at","on"]', 'at', 'reception desk 是功能性地點，用 at。'),
(13, 'multiple_choice', 'The documents are _____ the table.', '["in","at","by","on"]', 'on', 'table 是表面，用 on。'),
(13, 'multiple_choice', 'Our headquarters is _____ London.', '["on","by","in","at"]', 'in', '城市用 in。'),
(13, 'fill_blank', 'The printer is _____ the third floor.', NULL, 'on', 'floor 樓層用 on。'),
(13, 'multiple_choice', 'She is _____ a business trip.', '["by","in","on","at"]', 'on', 'on a business trip 固定搭配。'),
(13, 'multiple_choice', 'I''ll see you _____ the conference center.', '["at","by","on","in"]', 'at', 'conference center 功能性地點，用 at。'),
(13, 'multiple_choice', 'The logo is _____ the top of the page.', '["on","in","by","at"]', 'at', 'at the top 指頂部位置。'),
(13, 'fill_blank', 'Can you post it _____ the notice board?', NULL, 'on', 'notice board 是表面，用 on。'),
(13, 'multiple_choice', 'The product details are listed _____ page 10.', '["in","at","by","on"]', 'on', 'page 頁面用 on。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(13, 'multiple_choice', 'She is waiting _____ the entrance.', '["on","by","in","at"]', 'at', 'entrance 功能性地點，用 at。'),
(13, 'multiple_choice', 'There''s a typo _____ paragraph three.', '["in","at","on","by"]', 'in', 'paragraph 段落用 in。'),
(13, 'multiple_choice', 'He works _____ a large corporation _____ the city centre.', '["for / at","at / at","for / in","at / in"]', 'for / in', 'work for 公司；city centre 地區 in。'),
(13, 'transform', 'The error is located at line 5 of the report. (Use: on)', NULL, 'The error is on line 5 of the report.', 'line 行用 on。'),
(13, 'fill_blank', 'Please put your signature _____ the dotted line.', NULL, 'on', 'dotted line 是線（表面），用 on。'),
(13, 'multiple_choice', 'The annual report is _____ the website.', '["in","by","on","at"]', 'on', 'website 用 on。'),
(13, 'multiple_choice', 'She arrived _____ the airport at 6 a.m.', '["by","in","on","at"]', 'at', 'airport 功能性地點，用 at。'),
(13, 'multiple_choice', 'The branch is located _____ the financial district.', '["on","in","at","by"]', 'in', 'district 地區，用 in。'),
(13, 'fill_blank', 'The meeting notes are _____ the shared drive.', NULL, 'in', 'shared drive 是虛擬空間，用 in。'),
(13, 'multiple_choice', 'He is _____ a meeting and cannot be disturbed.', '["by","at","in","on"]', 'in', 'in a meeting 固定搭配。'),
(14, 'multiple_choice', 'She walked _____ the conference room without knocking.', '["into","onto","in","to"]', 'into', 'into 表從外進入，walked into 進入會議室。'),
(14, 'multiple_choice', 'He traveled _____ Singapore for the trade fair.', '["into","toward","to","onto"]', 'to', 'to 表目的地，traveled to Singapore。'),
(14, 'multiple_choice', 'The new employee walked _____ the office on her first day.', '["through","to","in","into"]', 'into', 'walked into 進入辦公室。'),
(14, 'multiple_choice', 'The CEO walked _____ the building past the reception area.', '["across","into","through","along"]', 'through', 'through 表穿越整個空間，walked through。'),
(14, 'fill_blank', 'She drove _____ the tunnel to get to the airport.', NULL, 'through', 'through 穿越隧道。'),
(14, 'multiple_choice', 'The delivery van drove _____ the warehouse district.', '["across","into","along","through"]', 'through', 'through 穿越區域。'),
(14, 'multiple_choice', 'Please walk _____ the corridor to find the HR office.', '["through","along","past","into"]', 'along', 'along 沿著走廊走。'),
(14, 'multiple_choice', 'The manager moved her desk _____ the window.', '["onto","to","into","toward"]', 'to', 'moved to 移到某地點。'),
(14, 'transform', 'He entered the meeting room. (Use: walked into)', NULL, 'He walked into the meeting room.', 'walked into 表進入的動作。'),
(14, 'multiple_choice', 'She ran _____ the street to catch a taxi.', '["through","across","into","along"]', 'across', 'across 橫越街道。'),
(14, 'multiple_choice', 'The courier went _____ the building to make the delivery.', '["to","through","past","into"]', 'into', 'into 進入建築物。'),
(14, 'fill_blank', 'We drove _____ the new factory on our way to the airport.', NULL, 'past', 'past 表經過某地點。'),
(14, 'multiple_choice', 'The document was passed _____ the table.', '["along","into","through","across"]', 'across', 'passed across 從桌子一端傳到另一端。'),
(14, 'multiple_choice', 'She took the elevator _____ the parking garage.', '["onto","into","to","through"]', 'to', 'to 表目的地樓層或地點。'),
(14, 'multiple_choice', 'The goods were shipped _____ several distribution centers.', '["through","to","into","across"]', 'through', 'through 表中轉經過幾個中心。'),
(14, 'fill_blank', 'Could you bring the files _____ my office?', NULL, 'to', 'bring to 帶到某地。'),
(14, 'multiple_choice', 'He walked _____ the podium to begin his keynote.', '["across","into","to","onto"]', 'to', 'walked to 走向講台（onto 也可用於上台）。'),
(14, 'multiple_choice', 'The intern hurried _____ the corridor to deliver the report.', '["through","along","across","into"]', 'along', 'along 沿走廊快走。'),
(14, 'multiple_choice', 'The new manager was moved _____ the Tokyo branch.', '["to","through","onto","into"]', 'to', 'moved to 調派到東京分部。'),
(14, 'multiple_choice', 'She glanced _____ the street before crossing.', '["through","along","across","into"]', 'across', 'across 橫過，glanced across 朝對面看。'),
(15, 'multiple_choice', 'She is responsible _____ managing the entire supply chain.', '["of","for","to","with"]', 'for', 'responsible for 負責，固定搭配。'),
(15, 'multiple_choice', 'Are you familiar _____ our company''s return policy?', '["of","with","to","about"]', 'with', 'familiar with 熟悉，固定搭配。'),
(15, 'multiple_choice', 'The team was satisfied _____ the outcome of the negotiation.', '["of","by","about","with"]', 'with', 'satisfied with 對...滿意，固定搭配。'),
(15, 'multiple_choice', 'He is interested _____ exploring new markets in Southeast Asia.', '["for","with","about","in"]', 'in', 'interested in 對...感興趣，固定搭配。'),
(15, 'fill_blank', 'She is very good _____ managing difficult clients.', NULL, 'at', 'good at 擅長，固定搭配。'),
(15, 'multiple_choice', 'We are committed _____ delivering the highest quality service.', '["to","with","for","in"]', 'to', 'committed to 致力於，固定搭配。'),
(15, 'multiple_choice', 'He was disappointed _____ the quarterly results.', '["in","with","about","by"]', 'with', 'disappointed with/in 對...失望，均可用。'),
(15, 'multiple_choice', 'The CFO is worried _____ the rising operational costs.', '["with","of","for","about"]', 'about', 'worried about 擔心，固定搭配。'),
(15, 'transform', 'He has awareness of the risks. (Use: aware of)', NULL, 'He is aware of the risks involved in this project.', 'aware of 知道，固定搭配。'),
(15, 'multiple_choice', 'Our company is capable _____ handling large-scale projects.', '["to","of","for","with"]', 'of', 'capable of 有能力，固定搭配。'),
(15, 'multiple_choice', 'The client was impressed _____ our presentation.', '["about","by","with","of"]', 'by', 'impressed by/with 均可，by 更強調感受來源。'),
(15, 'fill_blank', 'She is enthusiastic _____ the new marketing initiative.', NULL, 'about', 'enthusiastic about 對...充滿熱情，固定搭配。'),
(15, 'multiple_choice', 'We are concerned _____ the delay in delivery.', '["about","of","with","for"]', 'about', 'concerned about 擔憂，固定搭配。'),
(15, 'multiple_choice', 'He is not suitable _____ this position.', '["for","of","with","to"]', 'for', 'suitable for 適合，固定搭配。'),
(15, 'multiple_choice', 'The manager was very strict _____ punctuality.', '["with","of","about","for"]', 'about', 'strict about 嚴格要求，固定搭配。'),
(15, 'fill_blank', 'Our team is very proud _____ this achievement.', NULL, 'of', 'proud of 對...感到驕傲，固定搭配。'),
(15, 'multiple_choice', 'She is very skilled _____ data analysis.', '["for","at","with","in"]', 'at', 'skilled at 擅長，固定搭配（skilled in 也可）。'),
(15, 'multiple_choice', 'The company is based _____ Singapore.', '["in","at","on","for"]', 'in', 'based in 總部設於，固定搭配。'),
(15, 'multiple_choice', 'He is tired _____ attending endless meetings.', '["from","with","about","of"]', 'of', 'tired of 厭倦，固定搭配。'),
(15, 'multiple_choice', 'The team is fully dedicated _____ completing this project.', '["with","for","in","to"]', 'to', 'dedicated to 獻身於，固定搭配。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(16, 'multiple_choice', 'We applied _____ a government grant to fund the project.', '["to","for","in","with"]', 'for', 'apply for 申請，固定搭配。'),
(16, 'multiple_choice', 'She deals _____ customer complaints on a daily basis.', '["with","in","for","about"]', 'with', 'deal with 處理，固定搭配。'),
(16, 'multiple_choice', 'Our success relies _____ the dedication of our team members.', '["in","with","on","for"]', 'on', 'rely on 依賴，固定搭配。'),
(16, 'multiple_choice', 'The company is investing _____ renewable energy infrastructure.', '["into","in","for","on"]', 'in', 'invest in 投資於，固定搭配。'),
(16, 'fill_blank', 'He agreed _____ the proposed changes to the contract.', NULL, 'to', 'agree to (proposal/change) 同意某事，固定搭配。'),
(16, 'multiple_choice', 'We need to comply _____ all local safety regulations.', '["for","by","to","with"]', 'with', 'comply with 遵守，固定搭配。'),
(16, 'multiple_choice', 'She specializes _____ international trade law.', '["in","for","with","on"]', 'in', 'specialize in 專門從事，固定搭配。'),
(16, 'multiple_choice', 'The manager apologized _____ the miscommunication.', '["with","to","for","about"]', 'for', 'apologize for 為...道歉，固定搭配。'),
(16, 'transform', 'He contributes money to the charity fund. (Use: contributes to)', NULL, 'He contributes to the company''s success every day.', 'contribute to 貢獻於，固定搭配。'),
(16, 'multiple_choice', 'We are looking _____ a new distribution partner.', '["at","after","into","for"]', 'for', 'look for 尋找，固定搭配。'),
(16, 'multiple_choice', 'She reported _____ the regional director every week.', '["on","for","to","with"]', 'to', 'report to 向...匯報，固定搭配。'),
(16, 'fill_blank', 'The company prides itself _____ excellent customer service.', NULL, 'on', 'pride oneself on 以...自豪，固定搭配。'),
(16, 'multiple_choice', 'He is responsible _____ a team of 15 engineers.', '["for","with","to","of"]', 'for', 'responsible for 負責，固定搭配。'),
(16, 'multiple_choice', 'We should focus _____ improving client retention rates.', '["with","on","in","for"]', 'on', 'focus on 專注於，固定搭配。'),
(16, 'multiple_choice', 'The team succeeded _____ launching the product on schedule.', '["at","with","in","for"]', 'in', 'succeed in 成功地做到，固定搭配。'),
(16, 'fill_blank', 'Could you elaborate _____ the cost-saving measures?', NULL, 'on', 'elaborate on 詳細說明，固定搭配。'),
(16, 'multiple_choice', 'Our policy prohibits us _____ sharing confidential data.', '["for","from","with","of"]', 'from', 'prohibit from 禁止，固定搭配。'),
(16, 'multiple_choice', 'She tends _____ work long hours before major deadlines.', '["to","with","toward","for"]', 'to', 'tend to 傾向於，固定搭配。'),
(16, 'multiple_choice', 'We are considering _____ expanding to new markets.', '["—","on","about","for"]', '—', 'consider + V-ing 直接接動名詞，不需介系詞。'),
(16, 'multiple_choice', 'He objected _____ the proposed budget cuts.', '["to","about","with","for"]', 'to', 'object to 反對，固定搭配。'),
(17, 'multiple_choice', 'If you _____ the invoice, we will process your order immediately.', '["send","sending","will send","sent"]', 'send', 'if 子句用現在式；send 正確。'),
(17, 'multiple_choice', 'If demand increases, prices generally _____.', '["are rising","rose","will rise","rise"]', 'rise', '零條件句：普遍規律，兩個現在式。'),
(17, 'multiple_choice', 'If she _____ the interview, she will get the job.', '["will pass","passes","passed","passing"]', 'passes', 'if 子句現在式 passes，主句 will get。'),
(17, 'fill_blank', 'If we _____ (not / reduce) costs, the project will go over budget.', NULL, 'do not reduce', 'if 子句現在式，否定 do not reduce。'),
(17, 'multiple_choice', 'If you heat water to 100°C, it _____.', '["will boil","boiled","is boiling","boils"]', 'boils', '零條件句：科學事實，兩個現在式。'),
(17, 'multiple_choice', 'We will lose the client if we _____ to respond quickly.', '["are failing","failed","will fail","fail"]', 'fail', 'if 子句現在式 fail，主句 will lose。'),
(17, 'multiple_choice', 'If the team _____ the target, they will receive a bonus.', '["met","will meet","meets","is meeting"]', 'meets', 'if 子句現在式 meets，主句 will receive。'),
(17, 'transform', 'We might expand if we secure funding. (Use: will expand if we secure)', NULL, 'We will expand into new markets if we secure the necessary funding.', '第一條件句：will + if + 現在式。'),
(17, 'multiple_choice', 'If you press this button, the printer _____.', '["started","will start","is starting","starts"]', 'starts', '零條件句：操作指示，兩個現在式。'),
(17, 'fill_blank', 'If the weather _____ (be) good, the outdoor event will go ahead.', NULL, 'is', 'if 子句現在式 is，天氣預測。'),
(17, 'multiple_choice', 'If the client _____ by Friday, we will cancel the order.', '["will not confirm","has not confirmed","did not confirm","does not confirm"]', 'does not confirm', 'if 子句現在式否定 does not confirm。'),
(17, 'multiple_choice', 'Temperatures _____ if greenhouse gas emissions continue to rise.', '["will increase","increased","increase","are increasing"]', 'will increase', '第一條件句主句用 will increase 預測。'),
(17, 'multiple_choice', 'If you _____ your password, you can reset it online.', '["will forget","forgot","are forgetting","forget"]', 'forget', 'if 子句現在式 forget，零條件句操作說明。'),
(17, 'fill_blank', 'If the proposal _____ (approve) this week, work will begin immediately.', NULL, 'is approved', 'if 子句被動現在式 is approved。'),
(17, 'multiple_choice', 'She _____ the project if she gets the approval.', '["is managing","manages","managed","will manage"]', 'will manage', '主句 will manage，第一條件句。'),
(17, 'multiple_choice', 'If you _____ any questions, please contact our helpdesk.', '["have","will have","had","are having"]', 'have', 'if 子句現在式 have。'),
(17, 'transform', 'Assuming we sign the contract, we start next month. (Use: If we sign)', NULL, 'If we sign the contract this week, we will start next month.', '第一條件句：if + 現在式，will + 原形。'),
(17, 'fill_blank', 'If you _____ (not / leave) now, you will miss the train.', NULL, 'do not leave', 'if 子句否定現在式。'),
(17, 'multiple_choice', 'If the market _____ as expected, returns will be strong.', '["performs","performed","will perform","is performing"]', 'performs', 'if 子句現在式 performs。'),
(17, 'multiple_choice', 'Employees receive overtime pay if they _____ more than 40 hours a week.', '["work","worked","are working","will work"]', 'work', '零條件句：公司政策，兩個現在式。'),
(18, 'multiple_choice', 'If I _____ the manager, I would restructure the team.', '["were","am","was","be"]', 'were', '正式英語 if I were 用 were，第二條件句。'),
(18, 'multiple_choice', 'If we _____ more resources, we could finish ahead of schedule.', '["have","will have","had","would have"]', 'had', 'if 子句過去式 had，第二條件句。'),
(18, 'multiple_choice', 'She would apply for the promotion if she _____ more confident.', '["were","would be","was","is"]', 'were', '正式英語 if she were，第二條件句。'),
(18, 'fill_blank', 'If our pricing _____ (be) more competitive, we would win more clients.', NULL, 'were', '第二條件句 if 子句用 were。'),
(18, 'multiple_choice', 'What would you do if you _____ in charge?', '["were","are","would be","will be"]', 'were', 'if you were in charge 第二條件句 were。'),
(18, 'multiple_choice', 'If they _____ the investment, the company would expand faster.', '["increase","will increase","increased","would increase"]', 'increased', 'if 子句過去式 increased，主句 would expand。'),
(18, 'transform', 'We can''t reduce costs without cutting staff. (Use: If we could)', NULL, 'If we could reduce costs without cutting staff, we would do it immediately.', '第二條件句：假設我們有能力做到。'),
(18, 'multiple_choice', 'If the market _____ differently, we would need a new strategy.', '["behaves","would behave","will behave","behaved"]', 'behaved', 'if 子句過去式 behaved，第二條件句假設。'),
(18, 'fill_blank', 'I would attend the conference if I _____ (not / be) so busy.', NULL, 'were not', '第二條件句 if I were not，正式英語。'),
(18, 'multiple_choice', 'If the client _____ more time, we could deliver a better product.', '["would give","will give","gave","gives"]', 'gave', 'if 子句過去式 gave，第二條件句。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(18, 'multiple_choice', 'She would be able to lead the project if she _____ more experience.', '["had","will have","has","would have"]', 'had', 'if 子句過去式 had，第二條件句。'),
(18, 'multiple_choice', 'If we _____ a bigger budget, we could run a global campaign.', '["have","will have","would have","had"]', 'had', 'if 子句 had，第二條件句假設更多預算。'),
(18, 'transform', 'We don''t have time, so we can''t review everything. (Use: If we had)', NULL, 'If we had more time, we would review every aspect of the proposal.', '第二條件句假設有時間的情況。'),
(18, 'fill_blank', 'What would you recommend if you _____ (be) the consultant?', NULL, 'were', '正式第二條件句，if you were。'),
(18, 'multiple_choice', 'If the headquarters _____ in Asia, travel costs would be lower.', '["would be","is","was","were"]', 'were', 'if 子句 were，正式第二條件句。'),
(18, 'multiple_choice', 'He would accept the offer if the salary _____ higher.', '["is","would be","was","were"]', 'were', 'if the salary were 第二條件句正式用法。'),
(18, 'multiple_choice', 'If I _____ you, I would focus on client retention.', '["would be","am","were","was"]', 'were', 'If I were you 建議句型。'),
(18, 'fill_blank', 'If the partnership _____ (be) confirmed, we would announce it immediately.', NULL, 'were', '第二條件句 if 子句用 were。'),
(18, 'multiple_choice', 'The project would take less time if we _____ more staff.', '["hired","will hire","would hire","hire"]', 'hired', 'if 子句過去式 hired。'),
(18, 'multiple_choice', 'If they _____ the deal, it would be a major milestone.', '["secured","secure","would secure","will secure"]', 'secured', 'if 子句過去式 secured，第二條件句。'),
(19, 'multiple_choice', 'If we _____ earlier, we would have captured the market.', '["invested","have invested","had invested","would invest"]', 'had invested', 'if 子句過去完成式 had invested，第三條件句。'),
(19, 'multiple_choice', 'She would have got the promotion if she _____ the project.', '["has completed","would complete","completed","had completed"]', 'had completed', 'if 子句 had completed，第三條件句。'),
(19, 'fill_blank', 'If the team _____ (communicate) better, the misunderstanding would not have occurred.', NULL, 'had communicated', '第三條件句 if 子句 had communicated。'),
(19, 'multiple_choice', 'We would have met the deadline if there _____ no supply chain issues.', '["had been","was","had have","were"]', 'had been', 'if 子句 had been，第三條件句被動條件。'),
(19, 'multiple_choice', 'If I _____ the email earlier, I would have responded in time.', '["had seen","have seen","would see","saw"]', 'had seen', 'if 子句 had seen，第三條件句。'),
(19, 'multiple_choice', 'The project would have succeeded if we _____ a better team.', '["had assembled","have assembled","would assemble","assembled"]', 'had assembled', 'if 子句 had assembled，第三條件句。'),
(19, 'transform', 'We didn''t launch early enough. That''s why we lost market share. (Use: If we had launched)', NULL, 'If we had launched the product earlier, we would have gained more market share.', '第三條件句反思過去決策。'),
(19, 'fill_blank', 'If the budget _____ (approve) earlier, we would have started sooner.', NULL, 'had been approved', '第三條件句被動 had been approved。'),
(19, 'multiple_choice', 'She wouldn''t have resigned if she _____ a pay rise.', '["received","has received","had received","would receive"]', 'had received', 'if 子句 had received，第三條件句。'),
(19, 'multiple_choice', 'If the negotiations _____ longer, we might have reached a better deal.', '["would last","had lasted","have lasted","lasted"]', 'had lasted', 'if 子句 had lasted，第三條件句。'),
(19, 'multiple_choice', 'We _____ more if we had targeted a different demographic.', '["had sold","would have sold","sold","would sell"]', 'would have sold', '主句 would have sold，第三條件句結果。'),
(19, 'fill_blank', 'If they _____ (accept) our initial proposal, the project would have started in Q1.', NULL, 'had accepted', '第三條件句 if 子句 had accepted。'),
(19, 'multiple_choice', 'He would have attended the summit if he _____ been invited.', '["has","had","was","would have"]', 'had', 'if 子句 had been，第三條件句。'),
(19, 'transform', 'The deal fell through because we lacked preparation. (Use: If we had prepared)', NULL, 'If we had prepared more thoroughly, the deal would not have fallen through.', '第三條件句反思準備不足。'),
(19, 'multiple_choice', 'If the system _____ down, we would have lost all the data.', '["would crash","had crashed","has crashed","crashed"]', 'had crashed', 'if 子句 had crashed，第三條件句。'),
(19, 'multiple_choice', 'She would have become CEO if she _____ at the company longer.', '["would stay","has stayed","stayed","had stayed"]', 'had stayed', 'if 子句 had stayed，第三條件句。'),
(19, 'fill_blank', 'If we _____ (hire) more staff, we would not have missed the deadline.', NULL, 'had hired', '第三條件句 if 子句 had hired。'),
(19, 'multiple_choice', 'The launch would have been more successful if we _____ the market properly.', '["researched","had researched","would research","have researched"]', 'had researched', 'if 子句 had researched，第三條件句。'),
(19, 'multiple_choice', 'If I _____ the job offer, I would have moved to London.', '["accepted","would accept","had accepted","have accepted"]', 'had accepted', 'if 子句 had accepted，第三條件句。'),
(19, 'multiple_choice', 'They wouldn''t have run out of stock if they _____ demand correctly.', '["have forecast","had forecast","would forecast","forecast"]', 'had forecast', 'if 子句 had forecast，第三條件句。'),
(20, 'multiple_choice', 'If I _____ that job offer in 2020, I would be in New York now.', '["took","would take","had taken","take"]', 'had taken', 'if 子句 had taken（過去假設），主句 would be（現在結果）。'),
(20, 'multiple_choice', 'She would already be a director if she _____ the promotion.', '["accepts","accepted","had accepted","would accept"]', 'had accepted', '混合條件：had accepted 過去，would be 現在。'),
(20, 'fill_blank', 'If we _____ (invest) in that startup, we would be much wealthier now.', NULL, 'had invested', '混合條件：had invested 過去，would be 現在。'),
(20, 'multiple_choice', 'If the project _____ failed, the company would be in a much worse position today.', '["didn''t","wouldn''t have","had not","hasn''t"]', 'had not', 'had not failed（過去完成式否定），would be（現在）。'),
(20, 'multiple_choice', 'He wouldn''t be so stressed now if he _____ better at delegating.', '["were","would have been","had been","was"]', 'had been', '混合條件：had been 過去，wouldn''t be 現在。'),
(20, 'multiple_choice', 'If I _____ that business partnership, we might be global leaders today.', '["had not turned down","hadn''t turned down","didn''t turn down","won''t turn down"]', 'had not turned down', 'had not turned down 過去完成式否定。'),
(20, 'transform', 'We made a bad decision last year. That''s why we''re struggling now. (Use mixed conditional)', NULL, 'If we had made a better decision last year, we would not be struggling now.', '混合條件反思過去決策的現在影響。'),
(20, 'fill_blank', 'If she _____ (not / resign) last year, she would still be working here.', NULL, 'had not resigned', '混合條件：had not resigned 過去，would be 現在。'),
(20, 'multiple_choice', 'If the market _____ crashed in 2020, our investment would be thriving now.', '["wouldn''t have","didn''t","had not","hasn''t"]', 'had not', 'had not crashed 過去完成否定，would be thriving 現在結果。'),
(20, 'multiple_choice', 'He would be more fluent in English now if he _____ his studies earlier.', '["would start","has started","started","had started"]', 'had started', '混合條件：had started 過去，would be 現在。'),
(20, 'multiple_choice', 'If we _____ diversified earlier, we would be less vulnerable to market changes now.', '["had","have","did","would have"]', 'had', 'had diversified 過去完成，would be 現在結果。'),
(20, 'fill_blank', 'If they _____ (choose) a different supplier, delivery would not be an issue now.', NULL, 'had chosen', '混合條件：had chosen 過去假設，would not be 現在影響。'),
(20, 'multiple_choice', 'She wouldn''t have so many responsibilities now if she _____ every opportunity.', '["won''t seize","hadn''t seized","didn''t seize","hasn''t seized"]', 'hadn''t seized', '混合條件：hadn''t seized 過去，wouldn''t have 現在。'),
(20, 'multiple_choice', 'If the team _____ the right tools from the start, we would be much further along.', '["would use","had used","was using","used"]', 'had used', '混合條件：had used 過去，would be 現在。'),
(20, 'transform', 'He spent too much on advertising. Now the budget is tight. (Use mixed conditional)', NULL, 'If he had not spent so much on advertising, the budget would not be so tight now.', '混合條件：had not spent 過去，would not be 現在。'),
(20, 'fill_blank', 'If we _____ (build) that factory, our capacity would be double what it is today.', NULL, 'had built', '混合條件：had built 過去假設，would be 現在。'),
(20, 'multiple_choice', 'She might be fluent in Japanese now if she _____ the language course.', '["had completed","has completed","completed","would complete"]', 'had completed', '混合條件：had completed 過去，might be 現在。'),
(20, 'multiple_choice', 'If I _____ the networking event, I would already know the key clients.', '["had attended","have attended","attended","would attend"]', 'had attended', '混合條件：had attended 過去，would know 現在。'),
(20, 'fill_blank', 'The company _____ (be) more profitable now if they had controlled costs earlier.', NULL, 'would be', '混合條件主句：would be 現在結果。'),
(20, 'multiple_choice', 'If she _____ taken that scholarship, she would have a much stronger network now.', '["had","would have","has","was"]', 'had', 'had taken 過去，would have 現在。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(21, 'multiple_choice', '_____ you send me the revised proposal by Thursday?', '["Can","Will","Could","Should"]', 'Could', 'Could you 是更禮貌的請求方式，商業英語常用。'),
(21, 'multiple_choice', 'She _____ speak three languages fluently.', '["could","can","may","should"]', 'can', '描述現在的能力，用 can。'),
(21, 'multiple_choice', 'When I was a junior analyst, I _____ rarely attend senior meetings.', '["may","can","should","could"]', 'could', '過去的情況（when I was），用 could 表過去能力。'),
(21, 'fill_blank', '_____ I borrow your notes from the meeting?', NULL, 'Could', 'Could I 是禮貌請求許可的表達。'),
(21, 'multiple_choice', 'This feature _____ be implemented in the next software update.', '["could","can","should","will"]', 'could', 'could 表假設可能性，語氣較不確定。'),
(21, 'multiple_choice', 'The new system _____ process 1,000 transactions per second.', '["might","could","may","can"]', 'can', '描述系統現在的能力，用 can。'),
(21, 'multiple_choice', '_____ you explain this clause in the contract in more detail?', '["Could","Would","Can","Should"]', 'Could', 'Could you 更禮貌正式，商業英語偏好。'),
(21, 'transform', 'It is possible that we find a cheaper supplier. (Use: could find)', NULL, 'We could find a cheaper supplier if we expand our search.', 'could 表假設可能性。'),
(21, 'multiple_choice', 'The design team _____ create five mockups within two days.', '["can","should","could","may"]', 'can', 'can 表現在能力。'),
(21, 'fill_blank', '_____ she attend the conference in your place?', NULL, 'Could', 'Could she 詢問可能性或請求。'),
(21, 'multiple_choice', 'I _____ not reach the client all morning — the number was busy.', '["could","would","can","should"]', 'could', 'could not 過去無法，描述過去的失敗嘗試。'),
(21, 'multiple_choice', 'The project manager _____ assign tasks more efficiently.', '["can","should","could","must"]', 'could', 'could 表假設改進的可能性，比 should 更婉轉。'),
(21, 'multiple_choice', '_____ you please confirm your attendance by Friday?', '["Must","Could","Will","Can"]', 'Could', 'Could you please 是最禮貌的正式請求。'),
(21, 'fill_blank', 'She _____ not understand the technical jargon in the report.', NULL, 'could', 'could not 過去無法理解。'),
(21, 'multiple_choice', 'If we improve logistics, we _____ reduce delivery time by 20%.', '["could","can","will","should"]', 'could', 'could 表達假設條件下的可能性。'),
(21, 'multiple_choice', 'This opportunity _____ be very profitable for us.', '["must","should","could","can"]', 'could', 'could 表評估中的可能性，語氣謹慎。'),
(21, 'multiple_choice', 'She _____ type 80 words per minute when she was a secretary.', '["might","may","can","could"]', 'could', '過去能力用 could。'),
(21, 'transform', 'I want permission to work from home on Fridays. (Use: Could I)', NULL, 'Could I work from home on Fridays?', 'Could I 是禮貌請求許可的標準句型。'),
(21, 'multiple_choice', 'The team _____ complete the project ahead of schedule if they work overtime.', '["can","should","could","must"]', 'could', 'could 表條件下的可能性。'),
(21, 'multiple_choice', 'We _____ always outsource this task if our team is overloaded.', '["may","can","could","should"]', 'can', 'can 表現在存在的選項和能力。'),
(22, 'multiple_choice', 'All employees _____ complete the annual compliance training.', '["might","must","should","have to"]', 'must', 'must 表公司規定的強烈義務。'),
(22, 'multiple_choice', 'She _____ travel to five countries next month — it''s in her contract.', '["must","ought to","has to","should"]', 'has to', 'has to 表合約中的外在義務。'),
(22, 'multiple_choice', 'You _____ share confidential client data outside the company.', '["should not","must not","cannot","do not have to"]', 'must not', 'must not 表嚴格禁止，比 should not 更強烈。'),
(22, 'multiple_choice', 'Employees _____ work on Sundays unless it''s an emergency.', '["cannot","do not have to","must not","should not"]', 'do not have to', 'do not have to 表不必要，不是禁止。'),
(22, 'fill_blank', 'I _____ (finish) the report tonight — the board needs it tomorrow morning.', NULL, 'must finish', 'must 表強烈主觀義務。'),
(22, 'multiple_choice', 'She _____ be the new director — she was introduced as such.', '["must","has to","should","ought to"]', 'must', 'must 表邏輯推斷（她一定是...）。'),
(22, 'multiple_choice', 'We _____ meet the ISO certification requirements by Q4.', '["must","have to","ought to","should"]', 'have to', 'have to 表外在認證要求。'),
(22, 'multiple_choice', 'You _____ use a VPN when accessing the company server remotely.', '["should","have to","ought to","must"]', 'must', 'must 表 IT 安全規定的強制要求。'),
(22, 'transform', 'It is mandatory to wear a hard hat in the construction zone. (Use: must)', NULL, 'You must wear a hard hat in the construction zone at all times.', 'must 表嚴格規定。'),
(22, 'multiple_choice', 'I _____ make 20 client calls today — that''s my target.', '["need","must","have to","should"]', 'have to', 'have to 表外在業績目標的要求。'),
(22, 'multiple_choice', 'He _____ be exhausted — he worked 18 hours straight.', '["must","ought to","should","has to"]', 'must', 'must 表對現在情況的推斷。'),
(22, 'fill_blank', 'We _____ (disclose) all financial risks in the prospectus — it''s the law.', NULL, 'must disclose', '法律規定用 must 表強制義務。'),
(22, 'multiple_choice', 'You _____ leave the office during core hours without manager approval.', '["must not","should not","cannot","do not have to"]', 'must not', 'must not 表禁止行為。'),
(22, 'multiple_choice', 'They _____ submit monthly reports to the head office.', '["should","must","have to","ought to"]', 'have to', 'have to 表定期外在規定。'),
(22, 'multiple_choice', 'The certificate _____ be renewed every two years.', '["must","has to","should","ought to"]', 'has to', 'has to 表外在規定要求。'),
(22, 'fill_blank', 'You _____ (not/attend) the optional seminar if you are busy.', NULL, 'do not have to attend', 'do not have to 表不強制，非禁止。'),
(22, 'multiple_choice', 'This document _____ be the one signed by both parties.', '["has to","ought to","should","must"]', 'must', 'must 表根據邏輯的推斷。'),
(22, 'multiple_choice', 'She _____ clock in before 9 a.m. — it''s company policy.', '["ought to","must","should","has to"]', 'has to', 'has to 表公司外在政策。'),
(22, 'multiple_choice', 'All contracts _____ be reviewed by legal before signing.', '["ought to","should","have to","must"]', 'must', 'must 強調公司強制規定。'),
(22, 'multiple_choice', 'You _____ book a meeting room if it''s just a quick chat.', '["must not","do not have to","cannot","should not"]', 'do not have to', 'do not have to 表不必要，不是禁止。'),
(23, 'multiple_choice', 'You _____ proofread your emails before sending them to clients.', '["will","can","should","must"]', 'should', 'should 表建議最佳做法。'),
(23, 'multiple_choice', 'We _____ consider the risks before making a final decision.', '["can","ought","should","must"]', 'should', 'should 表建議考慮因素。'),
(23, 'multiple_choice', 'She _____ to request a meeting before the deadline.', '["must","should","can","ought"]', 'ought', 'ought to 和 should 意思相同，ought 後接 to。'),
(23, 'fill_blank', 'The report _____ (include) an executive summary for clarity.', NULL, 'should include', 'should 建議最佳做法。'),
(23, 'multiple_choice', 'Managers _____ give regular feedback to their team members.', '["should","can","might","must"]', 'should', 'should 表期望行為和建議。'),
(23, 'multiple_choice', 'The team _____ have more frequent progress updates.', '["would","should","must","can"]', 'should', 'should 建議改進做法。'),
(23, 'multiple_choice', 'According to the guidelines, all invoices _____ be processed within 30 days.', '["would","should","can","must"]', 'should', 'should 表期望和建議的標準做法。'),
(23, 'transform', 'It is advisable to back up your data regularly. (Use: should)', NULL, 'You should back up your data on a regular basis.', 'should 表建議。'),
(23, 'multiple_choice', 'We _____ have informed the client earlier about the delay.', '["must","would","can","should"]', 'should', 'should have 表對過去的後悔或批評（但本題是現在建議框架）。'),
(23, 'fill_blank', 'She _____ (consult) the legal team before signing any external agreements.', NULL, 'should consult', 'should 建議徵詢法律意見。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(23, 'multiple_choice', 'The presentation _____ be no longer than 30 minutes.', '["must","will","can","should"]', 'should', 'should 表建議長度，比 must 委婉。'),
(23, 'multiple_choice', 'He _____ arrive early to the interview to make a good impression.', '["could","must","should","can"]', 'should', 'should 建議最佳行為。'),
(23, 'multiple_choice', 'Staff _____ not use company resources for personal purposes.', '["might","can","must","should"]', 'should', 'should not 表不建議，比 must not 稍委婉。'),
(23, 'fill_blank', 'We _____ (review) the budget more carefully next time.', NULL, 'should review', 'should 表建議改進。'),
(23, 'multiple_choice', 'If there is a conflict of interest, employees _____ declare it.', '["should","must","would","can"]', 'should', 'should 表期望行為（declare 利益衝突）。'),
(23, 'multiple_choice', 'The contractor _____ have submitted the documents last week.', '["should","would","can","must"]', 'should', 'should have + p.p. 表對過去的批評。'),
(23, 'multiple_choice', 'All team members _____ attend the kickoff meeting.', '["might","should","can","must"]', 'should', 'should 表期望出席，比 must 稍委婉。'),
(23, 'transform', 'It is expected that you dress professionally. (Use: should)', NULL, 'You should dress professionally at all client meetings.', 'should 表期望行為。'),
(23, 'fill_blank', 'The project timeline _____ (update) whenever there are significant changes.', NULL, 'should be updated', 'should be + p.p. 被動建議。'),
(23, 'multiple_choice', 'He _____ to acknowledge the client''s concerns more empathetically.', '["can","ought","must","should"]', 'ought', 'ought to 同 should，表應該的行為。'),
(24, 'multiple_choice', 'The project _____ be delayed due to supply chain issues.', '["should","will","may","must"]', 'may', 'may 表可能性（50%左右）。'),
(24, 'multiple_choice', 'Sales _____ decline if we don''t improve our marketing strategy.', '["must","will","might","should"]', 'might', 'might 表較低確定性的預測。'),
(24, 'multiple_choice', '_____ I ask you to review this document before the meeting?', '["May","Can","Will","Should"]', 'May', 'May I 是非常正式的請求許可方式。'),
(24, 'fill_blank', 'The merger _____ (not / proceed) as planned if regulations change.', NULL, 'may not proceed', 'may not 表可能不會發生。'),
(24, 'multiple_choice', 'She _____ have the authority to sign this contract.', '["will","should","may","must"]', 'may', 'may 表不確定的可能性。'),
(24, 'multiple_choice', 'The conference _____ be moved online — nothing is confirmed yet.', '["will","should","must","might"]', 'might', 'might 強調更高的不確定性。'),
(24, 'multiple_choice', 'You _____ use the conference room if it''s available.', '["should","may","might","will"]', 'may', 'may 表正式許可使用。'),
(24, 'transform', 'It is possible that the price will increase next quarter. (Use: may increase)', NULL, 'The price may increase next quarter due to rising material costs.', 'may increase 表謹慎預測。'),
(24, 'multiple_choice', 'The results _____ not be what we expected.', '["will","should","must","may"]', 'may', 'may not 表可能不達預期。'),
(24, 'fill_blank', 'We _____ (need) to revise our timeline if the client requests changes.', NULL, 'might need', 'might 表較不確定的可能性。'),
(24, 'multiple_choice', 'There _____ be some unexpected costs associated with this project.', '["will","may","must","should"]', 'may', 'may be 表可能性，商業預測中常用。'),
(24, 'multiple_choice', 'The CEO _____ attend the meeting remotely.', '["will","must","may","should"]', 'may', 'may 表尚未確定的可能性。'),
(24, 'multiple_choice', 'This approach _____ not be suitable for all clients.', '["might","should","will","must"]', 'might', 'might not 較謹慎的否定可能性。'),
(24, 'fill_blank', 'The new product _____ (appeal) to a younger demographic.', NULL, 'may appeal', 'may 表商業可能性預測。'),
(24, 'multiple_choice', 'He _____ already be aware of the issue — let me check.', '["might","will","must","may"]', 'might', 'might 表較低確定性的猜測。'),
(24, 'multiple_choice', 'Profits _____ increase significantly if we enter the Asian market.', '["may","should","will","must"]', 'may', 'may 表條件性可能，語氣謹慎。'),
(24, 'multiple_choice', '_____ we proceed to the next agenda item?', '["Might","Can","Will","May"]', 'May', 'May we 是正式許可/請求。'),
(24, 'transform', 'There is a possibility that the deadline will be extended. (Use: might be extended)', NULL, 'The deadline might be extended, depending on progress.', 'might 表較不確定的可能。'),
(24, 'fill_blank', 'She _____ (not / be) available for the Thursday meeting.', NULL, 'may not be', 'may not be 表可能無法出席。'),
(24, 'multiple_choice', 'The new regulation _____ affect our supply chain operations.', '["must","might","may","will"]', 'may', 'may 表政策可能帶來的影響，謹慎語氣。'),
(25, 'multiple_choice', '_____ you be able to join the call this afternoon?', '["Would","Will","Should","Could"]', 'Would', 'Would you be able to 最禮貌的商業邀請/詢問。'),
(25, 'multiple_choice', 'When I was a junior analyst, I _____ prepare reports every Friday.', '["used to","could","will","would"]', 'would', 'would 表過去的規律性習慣。'),
(25, 'multiple_choice', 'I _____ recommend the premium package for your business needs.', '["could","would","should","will"]', 'would', 'I would recommend 委婉建議。'),
(25, 'fill_blank', '_____ you mind sending me the updated version by 5 p.m.?', NULL, 'Would', 'Would you mind 是非常禮貌的請求。'),
(25, 'multiple_choice', 'She said she _____ forward the documents later that day.', '["would","should","could","will"]', 'would', '間接引語中 will → would。'),
(25, 'multiple_choice', 'In the past, the team _____ hold daily briefings every morning.', '["would","will","could","should"]', 'would', 'would 表過去規律習慣。'),
(25, 'multiple_choice', 'He _____ like to schedule a meeting to discuss the proposal.', '["should","would","will","could"]', 'would', 'would like to 是禮貌表達意願的固定搭配。'),
(25, 'transform', 'Please give me your opinion on this. (Use: I would appreciate)', NULL, 'I would appreciate your thoughts on this proposal.', 'would appreciate 禮貌請求意見。'),
(25, 'multiple_choice', '_____ it be possible to extend the deadline by one week?', '["Could","Would","Should","Will"]', 'Would', 'Would it be possible to 是非常正式的商業請求。'),
(25, 'fill_blank', 'I _____ (not / advise) accepting the offer without legal review.', NULL, 'would not advise', 'would not advise 委婉建議不要。'),
(25, 'multiple_choice', 'If given the choice, she _____ prefer a hybrid work model.', '["should","will","would","could"]', 'would', 'would prefer 表假設偏好。'),
(25, 'multiple_choice', 'We _____ be happy to arrange a demonstration of our product.', '["should","would","will","could"]', 'would', 'would be happy to 禮貌答應商業請求。'),
(25, 'multiple_choice', 'He _____ often arrive early to prepare for the day ahead.', '["would","could","should","will"]', 'would', 'would 表過去的習慣行為。'),
(25, 'fill_blank', '_____ you be available for a call next Tuesday at 2 p.m.?', NULL, 'Would', 'Would you be available 商業日程安排的禮貌問法。'),
(25, 'multiple_choice', 'I _____ suggest reviewing the contract terms once more.', '["would","should","will","could"]', 'would', 'I would suggest 委婉建議。'),
(25, 'multiple_choice', 'The board _____ appreciate a more detailed financial analysis.', '["would","will","could","should"]', 'would', 'would appreciate 表假設的讚賞或期望。'),
(25, 'multiple_choice', 'In her previous role, she _____ manage a team of 20 people.', '["could","will","should","would"]', 'would', 'would 表過去職責的規律習慣。'),
(25, 'transform', 'Please accept our apology for the inconvenience. (Use: We would like to)', NULL, 'We would like to apologize for any inconvenience caused.', 'would like to 禮貌的商業道歉。'),
(25, 'fill_blank', 'This product _____ (suit) clients who prioritize efficiency.', NULL, 'would suit', 'would suit 條件性建議搭配。'),
(25, 'multiple_choice', 'I _____ not want to miss this opportunity if I were in your position.', '["will","could","would","should"]', 'would', 'would not want 表假設情況下的意願。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(26, 'multiple_choice', 'We _____ informed the client about the delay earlier.', '["would have","should have","could have","must have"]', 'should have', 'should have + p.p. 表批評或遺憾：應該通知但沒有。'),
(26, 'multiple_choice', 'She _____ the meeting from the start — she had the expertise.', '["must have led","could have led","should have led","would have led"]', 'could have led', 'could have 表過去本可以做的可能性。'),
(26, 'multiple_choice', 'If we had acted faster, we _____ the contract.', '["might have won","should have won","would have won","could have won"]', 'would have won', '第三條件句結果：would have won。'),
(26, 'fill_blank', 'The error _____ (avoid) if the team had followed the protocol.', NULL, 'could have been avoided', 'could have been + p.p. 表過去本可避免的被動式。'),
(26, 'multiple_choice', 'He _____ the report on time — he had enough information.', '["should have submitted","must have submitted","would have submitted","could have submitted"]', 'could have submitted', 'could have 表過去本有能力做到。'),
(26, 'multiple_choice', 'I _____ accepted the original offer — the counter-offer was worse.', '["would have","should have","must have","could have"]', 'should have', 'should have + p.p. 表後悔沒接受。'),
(26, 'multiple_choice', 'They _____ the market more thoroughly before launching.', '["might have researched","could have researched","should have researched","would have researched"]', 'should have researched', 'should have 表應該做的準備工作。'),
(26, 'transform', 'It was a mistake not to hire more staff. (Use: should have hired)', NULL, 'We should have hired more staff to handle the increased demand.', 'should have hired 表過去應該做的決定。'),
(26, 'multiple_choice', 'She _____ the project independently — she had all the skills.', '["must have managed","would have managed","could have managed","should have managed"]', 'could have managed', 'could have 表過去本有能力獨立完成。'),
(26, 'fill_blank', 'He _____ (not / approve) the expense without authorization.', NULL, 'should not have approved', 'should not have + p.p. 表批評：不應該那樣做。'),
(26, 'multiple_choice', 'If she had asked for help, we _____ her.', '["should have assisted","could have assisted","would have assisted","must have assisted"]', 'would have assisted', '第三條件句：would have + p.p.'),
(26, 'multiple_choice', 'The system _____ down if the backup had been set up properly.', '["must not have crashed","should not have crashed","would not have crashed","could not have crashed"]', 'would not have crashed', '第三條件句否定：would not have + p.p.'),
(26, 'multiple_choice', 'We _____ a different supplier — the current one has been unreliable.', '["could have chosen","might have chosen","would have chosen","should have chosen"]', 'should have chosen', 'should have 對過去選擇的後悔。'),
(26, 'fill_blank', 'If the meeting had started on time, we _____ (finish) early.', NULL, 'would have finished', '第三條件句主句 would have finished。'),
(26, 'multiple_choice', 'The team _____ the risk earlier — there were warning signs.', '["could have identified","must have identified","would have identified","should have identified"]', 'should have identified', 'should have 表應負責任的批評。'),
(26, 'multiple_choice', 'He _____ the presentation better if he''d had more preparation time.', '["would have delivered","should have delivered","must have delivered","could have delivered"]', 'could have delivered', 'could have 表有條件的過去可能性。'),
(26, 'multiple_choice', 'We _____ the deal — the client was clearly interested.', '["would have closed","could have closed","should have closed","must have closed"]', 'should have closed', 'should have 表失去機會的遺憾。'),
(26, 'transform', 'It was possible to reduce costs by 15%. (Use: could have reduced)', NULL, 'We could have reduced costs by 15% if we had optimized the supply chain.', 'could have 表過去本可實現的節約。'),
(26, 'fill_blank', 'She _____ (inform) us earlier — we were completely unprepared.', NULL, 'should have informed', 'should have + p.p. 批評應該提前告知。'),
(26, 'multiple_choice', 'If they had responded sooner, the partnership _____ saved.', '["would have been","must have been","should have been","could have been"]', 'could have been', 'could have been + p.p. 表過去被動可能性。'),
(27, 'multiple_choice', 'The quarterly report _____ by the finance team every month.', '["will prepare","is prepared","prepares","has prepared"]', 'is prepared', '被動現在式 is prepared，report 是接受者。'),
(27, 'multiple_choice', 'The contract _____ by both parties yesterday.', '["was signed","has been signed","signed","is signed"]', 'was signed', 'yesterday 過去時間，被動過去式 was signed。'),
(27, 'multiple_choice', 'New employees _____ a two-week training program.', '["gave","are given","are giving","give"]', 'are given', 'are given 被動現在式，employees 接受培訓。'),
(27, 'fill_blank', 'The budget proposal _____ (approve) by the board last Tuesday.', NULL, 'was approved', 'last Tuesday 過去，被動過去式 was approved。'),
(27, 'multiple_choice', 'These products _____ in several Asian countries.', '["manufacture","were manufacturing","manufactured","are manufactured"]', 'are manufactured', 'are manufactured 被動現在式，描述持續的製造。'),
(27, 'multiple_choice', 'The new policy _____ to all staff via email last week.', '["communicated","was communicated","has been communicated","is communicated"]', 'was communicated', 'last week 過去，被動過去式 was communicated。'),
(27, 'multiple_choice', 'All expenses _____ by the accounting department.', '["reviewing","are reviewed","review","were reviewed"]', 'are reviewed', 'are reviewed 被動現在式表定期流程。'),
(27, 'transform', 'The IT department manages the server maintenance. (Use passive)', NULL, 'The server maintenance is managed by the IT department.', 'is managed by 被動語態。'),
(27, 'fill_blank', 'The new office building _____ (design) by a renowned architect.', NULL, 'was designed', 'was designed 被動過去式。'),
(27, 'multiple_choice', 'Invoices _____ within 30 days of receipt.', '["are processing","are processed","process","were processed"]', 'are processed', 'are processed 被動現在式表公司政策。'),
(27, 'multiple_choice', 'The client _____ about the changes immediately.', '["is notifying","notified","was notified","has notified"]', 'was notified', 'was notified 被動過去式，client 接受通知。'),
(27, 'multiple_choice', 'Performance reviews _____ twice a year.', '["have conducted","are conducted","conduct","were conducting"]', 'are conducted', 'are conducted 被動現在式描述定期程序。'),
(27, 'fill_blank', 'The sales data _____ (analyze) by the marketing team on a monthly basis.', NULL, 'is analyzed', '被動現在式 is analyzed 表定期活動。'),
(27, 'multiple_choice', 'The order was _____ due to a quality control issue.', '["cancel","cancelling","have cancelled","cancelled"]', 'cancelled', 'was cancelled 被動過去式，由 was 引導，接過去分詞。'),
(27, 'multiple_choice', 'The new product line _____ at the trade fair last year.', '["has been launched","was launched","is launched","launched"]', 'was launched', 'last year 過去，was launched 被動過去式。'),
(27, 'multiple_choice', 'All decisions _____ by the senior management team.', '["make","have made","were making","are made"]', 'are made', 'are made 被動現在式表決策流程。'),
(27, 'transform', 'They deliver goods to clients within 48 hours. (Use passive)', NULL, 'Goods are delivered to clients within 48 hours.', 'are delivered 被動現在式，強調流程而非執行者。'),
(27, 'fill_blank', 'Overtime payments _____ (calculate) based on the employee''s basic salary.', NULL, 'are calculated', 'are calculated 被動現在式表計算方式。'),
(27, 'multiple_choice', 'The report _____ once a quarter to the board of directors.', '["is submitted","submits","was submitting","submitting"]', 'is submitted', 'is submitted 被動現在式表定期提交。'),
(27, 'multiple_choice', 'The system _____ down for maintenance every weekend.', '["takes","is taken","has taken","was taking"]', 'is taken', 'is taken down 被動現在式 phrasal verb。'),
(28, 'multiple_choice', 'The contract _____ by both parties as of this morning.', '["is signed","had been signed","has been signed","was signed"]', 'has been signed', 'as of this morning 連結到現在，現在完成被動。'),
(28, 'multiple_choice', 'All the required documents _____ before the deadline.', '["were submitted","had been submitted","have been submitted","were being submitted"]', 'had been submitted', 'before the deadline 建立先後，過去完成被動。'),
(28, 'fill_blank', 'The new accounting software _____ (install) across all departments.', NULL, 'has been installed', 'has been + p.p. 現在完成被動，現在已完成。'),
(28, 'multiple_choice', 'By the time we arrived, the presentation _____ already _____.', '["was / being prepared","has / been prepared","had / been prepared","is / prepared"]', 'had / been prepared', 'had been prepared 過去完成被動 already。'),
(28, 'multiple_choice', 'The budget _____ three times this year.', '["is revised","was revised","has been revised","had been revised"]', 'has been revised', 'this year 到目前，現在完成被動 has been revised。'),
(28, 'multiple_choice', 'Before the announcement, the plan _____ carefully.', '["has been reviewed","had been reviewed","was being reviewed","was reviewed"]', 'had been reviewed', 'before 建立先後，過去完成被動 had been reviewed。'),
(28, 'transform', 'The team finished the analysis. (Use present perfect passive)', NULL, 'The analysis has been completed by the team.', 'has been completed 現在完成被動。'),
(28, 'fill_blank', 'The terms of the agreement _____ (negotiate) over several weeks.', NULL, 'have been negotiated', 'have been + p.p. 現在完成被動。'),
(28, 'multiple_choice', 'It _____ that the new policy would be implemented in Q3.', '["had been announced","was announced","is announced","has been announced"]', 'has been announced', 'has been announced 現在完成被動，強調現在已知。'),
(28, 'multiple_choice', 'By 2020, three offices _____ opened globally.', '["were","have been","had been","are"]', 'had been', 'by 2020 過去時間點，had been opened 過去完成被動。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(28, 'multiple_choice', 'New safety standards _____ to all employees this week.', '["had been communicated","have been communicated","were communicated","are communicated"]', 'have been communicated', 'this week 到目前，現在完成被動。'),
(28, 'fill_blank', 'The results _____ (verify) by an independent auditor before release.', NULL, 'had been verified', 'before release 建立先後，過去完成被動。'),
(28, 'multiple_choice', 'A breakthrough solution _____ by our R&D team.', '["was developed","is developed","has been developed","had been developed"]', 'has been developed', '強調現在成果，現在完成被動 has been developed。'),
(28, 'multiple_choice', 'By the end of Q2, 1,000 units _____ shipped.', '["had been","were","are","have been"]', 'had been', 'by the end of Q2 過去時間點，had been shipped。'),
(28, 'multiple_choice', 'Three candidates _____ for the final interview.', '["were shortlisted","are shortlisted","have been shortlisted","had been shortlisted"]', 'have been shortlisted', '強調目前狀態，現在完成被動。'),
(28, 'transform', 'Someone already reviewed the proposal. (Use present perfect passive)', NULL, 'The proposal has already been reviewed by the committee.', 'has already been reviewed 現在完成被動。'),
(28, 'fill_blank', 'The merger _____ (finalize) by the legal teams of both companies.', NULL, 'has been finalized', 'has been + p.p. 現在完成被動。'),
(28, 'multiple_choice', 'Before launch, the product _____ extensively for safety.', '["is tested","was tested","had been tested","has been tested"]', 'had been tested', 'before launch 先後關係，過去完成被動。'),
(28, 'multiple_choice', 'The client _____ kept informed throughout the project.', '["had been","was","is","has been"]', 'has been', 'has been kept 現在完成被動持續式。'),
(28, 'multiple_choice', 'The new system _____ in use since January.', '["had been","was","has been","is"]', 'has been', 'since January 持續到現在，has been in use。'),
(29, 'multiple_choice', 'The report _____ submitted by 5 p.m. on Friday.', '["should","must be","can","will"]', 'must be', 'must be + p.p. 表強制要求的被動式。'),
(29, 'multiple_choice', 'All proposals _____ reviewed by the compliance team.', '["can","will","must","should be"]', 'should be', 'should be + p.p. 建議性被動規定。'),
(29, 'multiple_choice', 'Your application _____ processed within five working days.', '["should","must","will be","can"]', 'will be', 'will be + p.p. 預告未來被動動作。'),
(29, 'fill_blank', 'The invoice _____ (pay) within 30 days of receipt.', NULL, 'must be paid', 'must be + p.p. 強制性被動規定。'),
(29, 'multiple_choice', 'Client data _____ shared with third parties without consent.', '["must not be","will not","should not","can not"]', 'must not be', 'must not be + p.p. 嚴格禁止的被動式。'),
(29, 'multiple_choice', 'These documents _____ kept confidential at all times.', '["can be","must be","should","will be"]', 'must be', 'must be + p.p. 強制保密要求。'),
(29, 'multiple_choice', 'The application form _____ completed in full.', '["will be","must","should be","can"]', 'should be', 'should be + p.p. 建議做到完整填寫。'),
(29, 'transform', 'We can access the system remotely. (Use passive)', NULL, 'The system can be accessed remotely.', 'can be + p.p. 情態被動，強調系統功能。'),
(29, 'fill_blank', 'The budget _____ (approve) before any expenditure is made.', NULL, 'must be approved', 'must be + p.p. 強制先決條件。'),
(29, 'multiple_choice', 'All visitors _____ registered at the front desk.', '["must be","should","will","can"]', 'must be', 'must be + p.p. 強制安全規定。'),
(29, 'multiple_choice', 'The timeline _____ adjusted if there are unexpected delays.', '["should be","must be","may be","will be"]', 'may be', 'may be + p.p. 表可能需要調整。'),
(29, 'multiple_choice', 'Results _____ announced at the annual shareholders'' meeting.', '["can","should","will be","must be"]', 'will be', 'will be + p.p. 預告未來被動事件。'),
(29, 'fill_blank', 'Personal information _____ (not / share) without written permission.', NULL, 'must not be shared', 'must not be + p.p. 嚴格禁止。'),
(29, 'multiple_choice', 'Overtime _____ authorized in advance by your line manager.', '["must be","should","will be","can"]', 'must be', 'must be + p.p. 強制預先授權。'),
(29, 'multiple_choice', 'These changes _____ implemented by the end of Q3.', '["must","can","will","should be"]', 'should be', 'should be + p.p. 建議性期限。'),
(29, 'multiple_choice', 'A copy of the contract _____ sent to all parties involved.', '["should","will be","can","must be"]', 'will be', 'will be + p.p. 預告文件分發。'),
(29, 'transform', 'Someone should inform the client about this. (Use passive)', NULL, 'The client should be informed about this change immediately.', 'should be + p.p. 情態被動。'),
(29, 'fill_blank', 'The equipment _____ (inspect) regularly to ensure safety.', NULL, 'should be inspected', 'should be + p.p. 定期安全檢查建議。'),
(29, 'multiple_choice', 'The project _____ completed without additional resources.', '["must not be","should not be","cannot be","will not be"]', 'cannot be', 'cannot be + p.p. 表無法完成的被動式。'),
(29, 'multiple_choice', 'Any defects _____ reported to the quality control team.', '["must","can","should be","will be"]', 'should be', 'should be + p.p. 建議性程序。'),
(30, 'multiple_choice', 'We _____ the office _____ last month.', '["made / renovated","got / renovate","had / renovated","let / renovate"]', 'had / renovated', 'have something done 安排裝修，had renovated。'),
(30, 'multiple_choice', 'She needs to _____ her laptop _____ before the conference.', '["have / repair","get / repaired","make / repaired","let / repaired"]', 'get / repaired', 'get something done 安排修理，get repaired。'),
(30, 'multiple_choice', 'The manager _____ the intern _____ the report.', '["let / prepared","made / to prepare","had / prepare","got / prepared"]', 'had / prepare', 'have someone do 命令做某事，had + 人 + 原形。'),
(30, 'fill_blank', 'We need to _____ the contract _____ (check) by our lawyers.', NULL, 'have / checked', 'have something done 委託律師審查。'),
(30, 'multiple_choice', 'Can you _____ the presentation slides _____ by tomorrow?', '["make / prepared","have / prepare","get / ready","let / ready"]', 'get / ready', 'get something ready 使其準備好。'),
(30, 'multiple_choice', 'She _____ her team _____ a full market analysis.', '["had / conduct","got / conducted","made / to conduct","let / conduct"]', 'had / conduct', 'had someone do 命令做分析。'),
(30, 'multiple_choice', 'We should _____ the financial reports _____ by an external auditor.', '["let / audited","get / audit","make / audited","have / audited"]', 'have / audited', 'have something done 外部審計。'),
(30, 'transform', 'An outside company cleaned the office. (Use: had the office)', NULL, 'We had the office cleaned by an outside company.', 'have something done 被動使役。'),
(30, 'fill_blank', 'Could you _____ someone _____ (deliver) the documents to our client?', NULL, 'get / to deliver', 'get someone to do 說服/委派做事。'),
(30, 'multiple_choice', 'He _____ the brochures _____ at a local print shop.', '["got / print","let / printed","made / printed","had / printed"]', 'had / printed', 'had something printed 委託印製。'),
(30, 'multiple_choice', 'They are going to _____ the website _____ next week.', '["let / redesigned","make / redesigned","get / redesign","have / redesigned"]', 'have / redesigned', 'have something done 委外改版。'),
(30, 'multiple_choice', 'She _____ the assistant _____ the meeting room before the clients arrived.', '["got / setting up","let / set up","made / set up","had / set up"]', 'had / set up', 'had someone do 命令安排。'),
(30, 'fill_blank', 'I need to _____ my car _____ (service) before the long drive.', NULL, 'have / serviced', 'have something done 服務的委託。'),
(30, 'multiple_choice', 'We _____ the new branch _____ by an interior design firm.', '["got / furnish","had / furnished","made / furnished","let / furnish"]', 'had / furnished', 'had something done 委外室內設計。'),
(30, 'multiple_choice', 'The CEO _____ the PR team _____ a press release immediately.', '["made / to draft","got / drafted","let / draft","had / draft"]', 'had / draft', 'had someone do 命令起草。'),
(30, 'multiple_choice', 'Can you _____ the report _____ into Chinese?', '["get / translated","have / translate","make / translated","let / translate"]', 'get / translated', 'get something done 委外翻譯。'),
(30, 'transform', 'An expert examined the machinery. (Use: had the machinery)', NULL, 'We had the machinery examined by an expert.', 'had something done 委請專家檢查。'),
(30, 'fill_blank', 'She _____ the IT team _____ (install) the new software on her computer.', NULL, 'had / install', 'had someone do 命令安裝，原形動詞。'),
(30, 'multiple_choice', 'We plan to _____ the annual report _____ before the AGM.', '["get / publish","let / published","make / published","have / published"]', 'have / published', 'have something done 印製報告。'),
(30, 'multiple_choice', 'He _____ his assistant _____ all the travel arrangements.', '["got / to make","let / make","had / make","made / to make"]', 'got / to make', 'got someone to do 說服/委派做安排。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(31, 'multiple_choice', 'He said, ''I will send the report.'' → He said he _____ send the report.', '["shall","will","can","would"]', 'would', 'will → would 時態後移。'),
(31, 'multiple_choice', 'She told me, ''I am working on the proposal.'' → She told me she _____ on the proposal.', '["was working","works","worked","is working"]', 'was working', 'am/is working → was working 時態後移。'),
(31, 'multiple_choice', 'They said, ''We have completed the audit.'' → They said they _____ the audit.', '["were completing","had completed","have completed","completed"]', 'had completed', 'have completed → had completed 時態後移。'),
(31, 'fill_blank', 'She said, ''I can finish this by Friday.'' → She said she _____ finish it by Friday.', NULL, 'could', 'can → could 時態後移。'),
(31, 'multiple_choice', 'The manager said, ''The project is on track.'' → The manager said the project _____ on track.', '["will be","were","was","is"]', 'was', 'is → was 時態後移。'),
(31, 'multiple_choice', 'He told us, ''I signed the contract yesterday.'' → He told us he _____ the contract the day before.', '["had signed","was signing","signed","has signed"]', 'had signed', 'signed → had signed 時態後移。'),
(31, 'transform', 'The CEO said: ''We will expand into Europe next year.'' (Use reported speech)', NULL, 'The CEO said they would expand into Europe the following year.', 'will → would；next year → the following year。'),
(31, 'fill_blank', 'She said, ''I am going to attend the conference.'' → She said she _____ the conference.', NULL, 'was going to attend', 'am going to → was going to 時態後移。'),
(31, 'multiple_choice', 'He said, ''The client may cancel the order.'' → He said the client _____ cancel the order.', '["will","might","can","may"]', 'might', 'may → might 時態後移。'),
(31, 'multiple_choice', 'They announced, ''We are launching a new product.'' → They announced they _____ a new product.', '["launch","are launching","launched","were launching"]', 'were launching', 'are launching → were launching 時態後移。'),
(31, 'fill_blank', 'She said, ''I have never seen such a detailed proposal.'' → She said she _____ such a detailed proposal.', NULL, 'had never seen', 'have never seen → had never seen 時態後移。'),
(31, 'multiple_choice', 'The director said, ''The results exceeded expectations.'' → The director said the results _____ expectations.', '["have exceeded","had exceeded","were exceeding","exceeded"]', 'had exceeded', 'exceeded → had exceeded 時態後移。'),
(31, 'multiple_choice', 'He told us, ''We must cut costs immediately.'' → He told us they _____ cut costs immediately.', '["must","should","would","had to"]', 'had to', 'must → had to 時態後移。'),
(31, 'transform', 'The client said: ''I need more time to review the terms.'' (Use reported speech)', NULL, 'The client said he needed more time to review the terms.', 'need → needed 時態後移。'),
(31, 'fill_blank', 'She told me, ''I will call you tomorrow.'' → She told me she _____ the next day.', NULL, 'would call', 'will → would；tomorrow → the next day。'),
(31, 'multiple_choice', 'He said, ''The meeting starts at 10.'' → He said the meeting _____ at 10.', '["started","start","starts","had started"]', 'started', 'starts → started 時態後移（現在→過去）。'),
(31, 'multiple_choice', 'They said, ''We can deliver within 48 hours.'' → They said they _____ deliver within 48 hours.', '["could","would","will","can"]', 'could', 'can → could 時態後移。'),
(31, 'fill_blank', 'The consultant said, ''This approach is more efficient.'' → The consultant said that approach _____ more efficient.', NULL, 'was', 'is → was 時態後移。'),
(31, 'multiple_choice', 'She said, ''I haven''t finished the analysis.'' → She said she _____ the analysis.', '["haven''t finished","hadn''t finished","wasn''t finishing","didn''t finish"]', 'hadn''t finished', 'haven''t → hadn''t 時態後移。'),
(31, 'multiple_choice', 'He told the team, ''The client is impressed.'' → He told the team the client _____ impressed.', '["was","has been","were","is"]', 'was', 'is → was 時態後移。'),
(32, 'multiple_choice', '''What is the deadline?'' → She asked what the deadline _____.', '["is","was","were","will be"]', 'was', '間接問句陳述語序，is → was。'),
(32, 'multiple_choice', '''Is the report ready?'' → He asked _____ the report was ready.', '["whether","if","that","what"]', 'if', 'yes/no 問句用 if 或 whether 引導間接問句。'),
(32, 'multiple_choice', '''When will the meeting start?'' → They asked when the meeting _____.', '["would start","starts","will start","started"]', 'would start', 'will → would；陳述語序。'),
(32, 'fill_blank', '''Do you need any assistance?'' → She asked _____ I needed any assistance.', NULL, 'if/whether', 'yes/no 問句用 if 或 whether 引導。'),
(32, 'multiple_choice', '''Where is the nearest conference center?'' → He asked where the nearest conference center _____.', '["is","was","were","will be"]', 'was', '間接問句 is → was。'),
(32, 'multiple_choice', '''Have you reviewed the proposal?'' → She asked _____ I had reviewed the proposal.', '["that","if","what","whether"]', 'whether', 'whether 引導 yes/no 間接問句。'),
(32, 'multiple_choice', '''How many units can we order?'' → The client asked how many units they _____ order.', '["will","would","could","can"]', 'could', 'can → could 時態後移。'),
(32, 'transform', '''Are you satisfied with the service?'' → The manager asked ...(Use reported question)', NULL, 'The manager asked whether we were satisfied with the service.', 'whether + 陳述語序 + was。'),
(32, 'fill_blank', '''Why did the project fail?'' → The board asked why the project _____.', NULL, 'had failed', 'why + 過去完成式（failed → had failed）。'),
(32, 'multiple_choice', '''What does the contract include?'' → She asked what the contract _____.', '["included","will include","has included","includes"]', 'included', 'includes → included 時態後移。'),
(32, 'multiple_choice', '''Can I speak to the manager?'' → He asked _____ he could speak to the manager.', '["whether","if","what","that"]', 'if', 'yes/no 問句 if 引導。'),
(32, 'multiple_choice', '''Who is in charge of the project?'' → They asked _____ was in charge of the project.', '["whether","who","which","what"]', 'who', 'who 仍是疑問詞，引導間接問句。'),
(32, 'fill_blank', '''How long will the installation take?'' → She asked how long the installation _____ take.', NULL, 'would', 'will → would 時態後移。'),
(32, 'multiple_choice', '''Did the client confirm the order?'' → He asked _____ the client had confirmed the order.', '["whether","what","that","if"]', 'whether', 'whether 引導 yes/no 間接問句；did confirm → had confirmed。'),
(32, 'multiple_choice', '''Which option do you prefer?'' → She asked which option we _____.', '["will prefer","preferred","have preferred","prefer"]', 'preferred', 'prefer → preferred 時態後移。'),
(32, 'transform', '''Is there a cheaper alternative?'' → The client asked ...(Use reported question)', NULL, 'The client asked if there was a cheaper alternative.', 'if + 陳述語序 + was。'),
(32, 'fill_blank', '''What time does the office open?'' → He asked what time the office _____.', NULL, 'opened', 'does open → opened 時態後移。'),
(32, 'multiple_choice', '''Has the payment been processed?'' → She asked _____ the payment had been processed.', '["what","that","whether","if"]', 'whether', 'whether + 被動過去完成式 had been processed。'),
(32, 'multiple_choice', '''Who approved the budget?'' → They asked who _____ the budget.', '["has approved","had approved","was approving","approved"]', 'had approved', 'approved → had approved 時態後移。'),
(32, 'multiple_choice', '''What are the main objectives?'' → He asked what the main objectives _____.', '["are","will be","were","had been"]', 'were', 'are → were 時態後移。'),
(33, 'multiple_choice', '''Submit the report by Friday.'' → He told us _____ the report by Friday.', '["submitting","that we submit","to submit","submit"]', 'to submit', 'tell + 人 + to do 間接命令。'),
(33, 'multiple_choice', '''Don''t be late.'' → She asked them _____ late.', '["to not be","not to be","not be","that not be"]', 'not to be', '間接否定命令：not to + 原形。'),
(33, 'multiple_choice', '''Please prepare the agenda.'' → The manager asked her _____ the agenda.', '["prepare","that she prepares","to prepare","preparing"]', 'to prepare', 'ask + 人 + to do 間接請求。'),
(33, 'fill_blank', '''Follow the company guidelines.'' → He told the new staff _____ the company guidelines.', NULL, 'to follow', 'tell + 人 + to do。'),
(33, 'multiple_choice', '''Don''t share the confidential data.'' → She told him _____ the confidential data.', '["to not share","not sharing","that he not share","not to share"]', 'not to share', 'tell + 人 + not to do。'),
(33, 'multiple_choice', '''Please review the proposal carefully.'' → He asked the team _____ the proposal carefully.', '["to review","that they review","review","reviewing"]', 'to review', 'ask + 人 + to do。'),
(33, 'multiple_choice', '''Call the client immediately.'' → She instructed me _____ the client immediately.', '["to call","that I call","call","calling"]', 'to call', 'instruct + 人 + to do 間接命令。'),
(33, 'transform', 'The boss said: ''Please don''t miss the deadline.'' (Use reported command)', NULL, 'The boss asked us not to miss the deadline.', 'asked + 人 + not to do。'),
(33, 'fill_blank', '''Update the spreadsheet daily.'' → The supervisor told the intern _____ the spreadsheet daily.', NULL, 'to update', 'tell + 人 + to do。'),
(33, 'multiple_choice', '''Please don''t use the printer during peak hours.'' → She asked staff _____ the printer during peak hours.', '["not using","not to use","to not use","that they not use"]', 'not to use', 'ask + 人 + not to do。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(33, 'multiple_choice', '''Read the contract carefully before signing.'' → He advised her _____ the contract carefully.', '["that she reads","read","to read","reading"]', 'to read', 'advise + 人 + to do。'),
(33, 'multiple_choice', '''Don''t discuss salary with colleagues.'' → The HR manager warned them _____ salary with colleagues.', '["that they not discuss","not discussing","to not discuss","not to discuss"]', 'not to discuss', 'warn + 人 + not to do。'),
(33, 'fill_blank', '''Please confirm the order by email.'' → She asked the client _____ the order by email.', NULL, 'to confirm', 'ask + 人 + to do。'),
(33, 'multiple_choice', '''Attend the orientation session.'' → The company required all new hires _____ the orientation session.', '["that they attend","attending","attend","to attend"]', 'to attend', 'require + 人 + to do。'),
(33, 'multiple_choice', '''Don''t park in the visitor spaces.'' → He told staff _____ in the visitor spaces.', '["not to park","to not park","not parking","that they not park"]', 'not to park', 'tell + 人 + not to do。'),
(33, 'transform', 'The IT team said: ''Please restart your computer after the update.'' (Use reported)', NULL, 'The IT team asked all users to restart their computers after the update.', 'asked + 人 + to do，注意代名詞調整。'),
(33, 'fill_blank', '''Send me the draft by Monday.'' → She instructed him _____ the draft by Monday.', NULL, 'to send', 'instruct + 人 + to do。'),
(33, 'multiple_choice', '''Don''t forget to include the appendix.'' → She reminded him _____ to include the appendix.', '["to not","that he don''t","not","do not"]', 'not', 'remind + 人 + not to forget。'),
(33, 'multiple_choice', '''Please copy me on all emails to the client.'' → He asked her _____ him on all emails to the client.', '["that she copies","copying","to copy","copy"]', 'to copy', 'ask + 人 + to do。'),
(33, 'multiple_choice', '''Report any issues immediately.'' → The manager told staff _____ any issues immediately.', '["that they report","reporting","to report","report"]', 'to report', 'tell + 人 + to do。'),
(34, 'multiple_choice', '''I am writing the contract now.'' → She said she _____ the contract then.', '["wrote","is writing","writes","was writing"]', 'was writing', 'is writing → was writing，now → then。'),
(34, 'multiple_choice', '''We will finalize the deal tomorrow.'' → They said they _____ the deal the following day.', '["had finalized","will finalize","would finalize","finalize"]', 'would finalize', 'will → would；tomorrow → the following day。'),
(34, 'multiple_choice', '''I have already sent the invoice.'' → He said he _____ the invoice.', '["had already sent","has already sent","was already sending","already sent"]', 'had already sent', 'have sent → had sent 時態後移。'),
(34, 'fill_blank', '''The client can meet us today.'' → She said the client _____ meet them that day.', NULL, 'could', 'can → could；today → that day。'),
(34, 'multiple_choice', '''I may attend the conference.'' → She said she _____ attend the conference.', '["might","may","can","would"]', 'might', 'may → might 時態後移。'),
(34, 'multiple_choice', '''We signed the deal last week.'' → He said they _____ the deal the week before.', '["were signing","had signed","have signed","signed"]', 'had signed', 'signed → had signed；last week → the week before。'),
(34, 'transform', 'Direct: ''This is our best offer.'' → Report this statement.', NULL, 'She said that was their best offer.', 'this → that；is → was；our → their。'),
(34, 'fill_blank', '''I have been working here for three years.'' → He said he _____ there for three years.', NULL, 'had been working', 'have been working → had been working；here → there。'),
(34, 'multiple_choice', '''Our profits are increasing this year.'' → She said their profits _____ that year.', '["had increased","were increasing","increase","are increasing"]', 'were increasing', 'are increasing → were increasing；this → that。'),
(34, 'multiple_choice', '''I must submit the report today.'' → He said he _____ submit the report that day.', '["would","had to","should","must"]', 'had to', 'must → had to；today → that day。'),
(34, 'multiple_choice', '''We are expanding into new markets here.'' → She said they _____ into new markets there.', '["are expanding","expand","have expanded","were expanding"]', 'were expanding', 'are expanding → were expanding；here → there。'),
(34, 'fill_blank', '''The meeting will be held tomorrow.'' → She said the meeting _____ the following day.', NULL, 'would be held', 'will be held → would be held；tomorrow → the following day。'),
(34, 'multiple_choice', '''We can reduce costs by 10%.'' → He said they _____ reduce costs by 10%.', '["can","could","might","would"]', 'could', 'can → could 時態後移。'),
(34, 'multiple_choice', '''I''ve never seen such growth.'' → She said she _____ such growth.', '["had never seen","hadn''t been seeing","has never seen","never saw"]', 'had never seen', 'have never seen → had never seen。'),
(34, 'transform', 'Direct: ''These negotiations may take longer than expected.'' → Report this.', NULL, 'He warned that those negotiations might take longer than expected.', 'may → might；these → those。'),
(34, 'fill_blank', '''We finished the project yesterday.'' → They said they _____ the project the day before.', NULL, 'had finished', 'finished → had finished；yesterday → the day before。'),
(34, 'multiple_choice', '''We are going to restructure the company.'' → He said they _____ the company.', '["will restructure","were going to restructure","would restructure","are going to restructure"]', 'were going to restructure', 'are going to → were going to。'),
(34, 'multiple_choice', '''The client is here now.'' → She said the client _____ there then.', '["had been","is","was","were"]', 'was', 'is → was；here → there；now → then。'),
(34, 'fill_blank', '''I can''t attend the meeting today.'' → He said he _____ the meeting that day.', NULL, 'couldn''t attend', 'can''t → couldn''t；today → that day。'),
(34, 'multiple_choice', '''We''ve already solved the problem.'' → She said they _____ the problem.', '["were solving","solved","had already solved","have already solved"]', 'had already solved', 'have solved → had solved。'),
(35, 'multiple_choice', 'The employee _____ submitted the best proposal will be promoted.', '["which","whose","who","that"]', 'who', 'who 指人，限定性關係子句。'),
(35, 'multiple_choice', 'The software _____ we use has been updated.', '["which","who","whose","that"]', 'that', 'that 可指物，限定性關係子句。'),
(35, 'multiple_choice', 'The company _____ products are sold worldwide is headquartered in Germany.', '["whose","who","that","which"]', 'whose', 'whose 所有格，修飾 products。'),
(35, 'fill_blank', 'The report _____ was submitted last week has been approved.', NULL, 'that/which', 'that 或 which 指物，限定性關係子句。'),
(35, 'multiple_choice', 'The manager _____ I reported to was very supportive.', '["whose","who","which","that"]', 'who', 'who 指人，作受語。'),
(35, 'multiple_choice', 'The city _____ the conference will be held is London.', '["which","who","where","that"]', 'where', 'where 指地點的關係副詞。'),
(35, 'multiple_choice', 'The client _____ placed the largest order will receive a discount.', '["whose","who","which","that"]', 'who', 'who 指人（客戶）。'),
(35, 'transform', 'The candidate was hired. He had the most experience. (Use: who)', NULL, 'The candidate who had the most experience was hired.', 'who 引導限定性關係子句。'),
(35, 'multiple_choice', 'The proposal _____ received the most votes was accepted.', '["which","that","who","whose"]', 'that', 'that 指物（proposal），限定性子句。'),
(35, 'fill_blank', 'The department _____ handles international accounts is expanding.', NULL, 'that/which', 'that 或 which 指部門。'),
(35, 'multiple_choice', 'The time _____ we need to submit the report is 5 p.m.', '["which","when","that","who"]', 'when', 'when 指時間的關係副詞。'),
(35, 'multiple_choice', 'The platform _____ we have chosen is highly secure.', '["who","which","that","whose"]', 'that', 'that 指物。'),
(35, 'multiple_choice', 'The partner _____ firm specializes in intellectual property law is ideal.', '["that","who","which","whose"]', 'whose', 'whose 所有格，修飾 firm。'),
(35, 'fill_blank', 'The strategy _____ proved most effective was adopted by the board.', NULL, 'that/which', 'that 或 which 指策略。'),
(35, 'multiple_choice', 'The director _____ presentation impressed the investors was promoted.', '["who","which","whose","that"]', 'whose', 'whose 所有格，修飾 presentation。'),
(35, 'multiple_choice', 'The branch _____ was opened last year is already profitable.', '["who","that","whose","which"]', 'that', 'that 指物（branch）。'),
(35, 'transform', 'She identified the error. The error had caused the delay. (Use: that)', NULL, 'She identified the error that had caused the delay.', 'that 引導限定性關係子句。'),
(35, 'fill_blank', 'The vendor _____ we have partnered with offers competitive pricing.', NULL, 'that/who', 'that 或 who（公司可用 who 或 that）。'),
(35, 'multiple_choice', 'The year _____ we launched the product was 2021.', '["when","that","who","which"]', 'when', 'when 指年份（時間關係副詞）。'),
(35, 'multiple_choice', 'The team _____ developed the app won the innovation award.', '["whose","who","which","that"]', 'that', 'that 指整個團隊（也可 who）。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(36, 'multiple_choice', 'Our CEO, _____ joined in 2015, has transformed the company.', '["whose","which","that","who"]', 'who', '非限定性關係子句，不可用 that，用 who 指人。'),
(36, 'multiple_choice', 'The new office, _____ is located in the city centre, opened last month.', '["whose","which","who","that"]', 'which', '非限定性關係子句，which 指物，不可用 that。'),
(36, 'multiple_choice', 'The merger, _____ was announced last week, surprised the industry.', '["which","that","whose","who"]', 'which', '非限定性關係子句 which 指事件。'),
(36, 'fill_blank', 'Ms. Chen, _____ daughter is also an engineer, leads our R&D team.', NULL, 'whose', 'whose 所有格非限定性關係子句。'),
(36, 'multiple_choice', 'The contract, _____ runs until 2028, includes performance clauses.', '["who","which","whose","that"]', 'which', '非限定性子句 which，注意逗號。'),
(36, 'multiple_choice', 'The annual conference, _____ attracts 500 delegates, is held in April.', '["who","whose","which","that"]', 'which', '非限定性子句 which 指事件。'),
(36, 'transform', 'John Smith leads the team. He has 20 years of experience. (Use non-defining)', NULL, 'John Smith, who has 20 years of experience, leads the team.', '非限定性子句加逗號，who 指人。'),
(36, 'multiple_choice', 'Singapore, _____ we opened our first Asian office, is a key market.', '["that","where","which","who"]', 'where', 'where 指地點的非限定性關係副詞。'),
(36, 'fill_blank', 'The Q4 report, _____ shows record profits, will be presented to the board tomorrow.', NULL, 'which', '非限定性子句 which，注意逗號。'),
(36, 'multiple_choice', 'Our largest client, _____ we have worked with for ten years, renewed the contract.', '["whom","which","that","who"]', 'whom', 'whom 是受格關係代名詞，正式用法（也可用 who）。'),
(36, 'multiple_choice', 'The product launch, _____ attracted significant media attention, was a success.', '["whose","who","which","that"]', 'which', '非限定性子句 which。'),
(36, 'multiple_choice', 'Dr. Lee, _____ research was cited in the report, will present at the conference.', '["that","who","which","whose"]', 'whose', 'whose 所有格非限定性關係子句。'),
(36, 'transform', 'The proposal was rejected. It had been reviewed by all departments. (Use non-defining)', NULL, 'The proposal, which had been reviewed by all departments, was rejected.', 'which 非限定性子句加逗號。'),
(36, 'fill_blank', '2023, _____ we achieved record revenue, was our best year.', NULL, 'when', 'when 指年份的非限定性關係副詞。'),
(36, 'multiple_choice', 'The CFO, _____ resigned last month, was known for his innovative strategies.', '["that","which","whose","who"]', 'who', '非限定性子句 who 指人。'),
(36, 'multiple_choice', 'The new policy, _____ takes effect in January, will affect all employees.', '["whose","who","which","that"]', 'which', '非限定性子句 which 指政策。'),
(36, 'fill_blank', 'Our branch in Tokyo, _____ opened five years ago, is now our most profitable.', NULL, 'which', '非限定性子句 which 補充說明東京分部。'),
(36, 'multiple_choice', 'The training program, _____ lasts three weeks, covers essential business skills.', '["whose","which","that","who"]', 'which', '非限定性子句 which。'),
(36, 'multiple_choice', 'Mr. Wang, _____ I met at the trade fair, is interested in a partnership.', '["who","which","that","whom"]', 'whom', 'whom 受格，正式英語；也可用 who。'),
(36, 'multiple_choice', 'The AGM, _____ all shareholders are invited to attend, is scheduled for May.', '["whose","which","that","who"]', 'which', '非限定性子句 which。'),
(37, 'multiple_choice', 'The person _____ handles our logistics is very efficient.', '["whose","which","who","that"]', 'who', 'who 指人，主格。'),
(37, 'multiple_choice', 'The document _____ I need is on your desk.', '["which","whose","who","that"]', 'that', 'that 指物，可替代 which（限定子句）。'),
(37, 'multiple_choice', 'The company _____ logo is red and blue is our main competitor.', '["that","who","whose","which"]', 'whose', 'whose 所有格，修飾 logo。'),
(37, 'fill_blank', 'The staff member _____ processed your order has been promoted.', NULL, 'who/that', 'who 或 that 均可指人（限定子句）。'),
(37, 'multiple_choice', 'The software _____ we installed last week has improved productivity.', '["who","whose","that","which"]', 'that', 'that 指物。'),
(37, 'multiple_choice', 'The employee _____ performance was exceptional received a bonus.', '["who","that","which","whose"]', 'whose', 'whose 所有格，修飾 performance。'),
(37, 'multiple_choice', 'The branch _____ the CEO visited last month is performing well.', '["that","whose","who","which"]', 'that', 'that 指物，受格用法（受詞可省略）。'),
(37, 'transform', 'The consultant helped us. His firm is based in New York. (Use: whose)', NULL, 'The consultant whose firm is based in New York helped us.', 'whose 所有格限定性關係子句。'),
(37, 'multiple_choice', 'The system _____ was installed last year needs an upgrade.', '["whose","who","that","which"]', 'that', 'that 指物，主格用法。'),
(37, 'fill_blank', 'The client _____ we spoke to yesterday wants a revised proposal.', NULL, 'who/whom/that', 'who 或 that 可指人；whom 正式受格。'),
(37, 'multiple_choice', 'The project _____ budget exceeded one million was reviewed by the board.', '["which","that","who","whose"]', 'whose', 'whose 所有格，修飾 budget。'),
(37, 'multiple_choice', 'The partner _____ brought in the most new clients won the award.', '["whose","which","who","that"]', 'who', 'who 指人（partner），主格。'),
(37, 'multiple_choice', 'The regulations _____ were introduced last year affected many industries.', '["that","whose","who","which"]', 'that', 'that 指物（regulations）。'),
(37, 'transform', 'The manager worked hard. She always meets her targets. (Use: who)', NULL, 'She is the kind of manager who always meets her targets.', 'who 引導描述人的關係子句。'),
(37, 'fill_blank', 'The product _____ we developed has received excellent reviews.', NULL, 'that/which', 'that 或 which 均可指物。'),
(37, 'multiple_choice', 'The consultant _____ advice we followed was right.', '["whose","that","which","who"]', 'whose', 'whose 所有格，修飾 advice。'),
(37, 'multiple_choice', 'This is the platform _____ connects buyers and sellers globally.', '["which","that","whose","who"]', 'that', 'that 指物，限定性子句。'),
(37, 'fill_blank', 'The team _____ won the award was from the marketing department.', NULL, 'that/which', 'that 或 which 均可（限定性子句）。'),
(37, 'multiple_choice', 'The investor _____ funded the startup is well known in the industry.', '["who","that","which","whose"]', 'who', 'who 指人（investor）。'),
(37, 'multiple_choice', 'The policy _____ was introduced in Q1 has improved efficiency.', '["that","who","which","whose"]', 'that', 'that 指物（policy）。'),
(38, 'multiple_choice', 'She decided _____ the new marketing strategy.', '["of implementing","to implement","implementing","implement"]', 'to implement', 'decide + to do 決定做。'),
(38, 'multiple_choice', 'We considered _____ our office in Singapore.', '["relocate","of relocating","to relocate","relocating"]', 'relocating', 'consider + V-ing 考慮做。'),
(38, 'multiple_choice', 'He agreed _____ the proposal by the end of the week.', '["of reviewing","to review","reviewing","review"]', 'to review', 'agree + to do 同意做。'),
(38, 'fill_blank', 'She finished _____ (write) the report and sent it to the client.', NULL, 'writing', 'finish + V-ing 完成做。'),
(38, 'multiple_choice', 'They plan _____ a new branch in Europe next year.', '["opening","of opening","open","to open"]', 'to open', 'plan + to do 計劃做。'),
(38, 'multiple_choice', 'He suggested _____ the product launch to Q1.', '["of postponing","postponing","postpone","to postpone"]', 'postponing', 'suggest + V-ing 建議做。'),
(38, 'multiple_choice', 'I avoid _____ important meetings without proper preparation.', '["attend","of attending","to attend","attending"]', 'attending', 'avoid + V-ing 避免做。'),
(38, 'transform', 'The manager said he would sign the contract. (Use: agreed to sign)', NULL, 'The manager agreed to sign the contract before the deadline.', 'agree + to do。'),
(38, 'multiple_choice', 'She stopped _____ when she heard the news.', '["to talk","talking","talk","of talking"]', 'talking', 'stopped talking 停止說話（動作結束）；stopped to talk 停下來去說話。'),
(38, 'fill_blank', 'We expect _____ (receive) the shipment by Thursday.', NULL, 'to receive', 'expect + to do 期待。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(38, 'multiple_choice', 'The team practiced _____ the presentation before the big day.', '["of giving","giving","give","to give"]', 'giving', 'practice + V-ing 練習做。'),
(38, 'multiple_choice', 'She remembered _____ the invoice — it was done last week.', '["sending","of sending","to send","send"]', 'sending', 'remembered sending 記得曾做（過去已做）。'),
(38, 'multiple_choice', 'He tried _____ the client''s concerns in his email.', '["to address","addressing","of addressing","address"]', 'to address', 'try + to do 嘗試做（努力）。'),
(38, 'fill_blank', 'Would you mind _____ (postpone) the meeting by one hour?', NULL, 'postponing', 'Would you mind + V-ing 請求。'),
(38, 'multiple_choice', 'We recommend _____ the terms before signing.', '["reviewing","review","to review","of reviewing"]', 'reviewing', 'recommend + V-ing 建議做。'),
(38, 'multiple_choice', 'She managed _____ all five projects on time.', '["to complete","complete","of completing","completing"]', 'to complete', 'manage + to do 設法做到。'),
(38, 'multiple_choice', 'He enjoys _____ with international clients.', '["of working","working","work","to work"]', 'working', 'enjoy + V-ing 喜歡做。'),
(38, 'transform', 'It would be a good idea to expand into Asia. (Use: suggest expanding)', NULL, 'She suggested expanding into Asian markets next year.', 'suggest + V-ing。'),
(38, 'fill_blank', 'The company failed _____ (meet) its Q3 targets.', NULL, 'to meet', 'fail + to do 未能做到。'),
(38, 'multiple_choice', 'She offered _____ with the onboarding process.', '["to help","helping","help","of helping"]', 'to help', 'offer + to do 提議做。'),
(39, 'multiple_choice', '_____ effectively with clients is a key skill in sales.', '["To communicate","Communication","Communicating","Communicate"]', 'Communicating', 'Communicating 動名詞作主語。'),
(39, 'multiple_choice', '_____ the budget carefully ensures financial stability.', '["Management","Managed","Managing","To manage"]', 'Managing', 'Managing 動名詞作主語。'),
(39, 'fill_blank', '_____ (meet) deadlines consistently is essential in this role.', NULL, 'Meeting', 'Meeting 動名詞作主語。'),
(39, 'multiple_choice', '_____ a diverse team brings different perspectives to problem-solving.', '["Leading","Lead","Leads","To lead"]', 'Leading', 'Leading 動名詞作主語。'),
(39, 'multiple_choice', '_____ customer satisfaction should be every employee''s priority.', '["To maintain","Maintained","Maintain","Maintaining"]', 'Maintaining', 'Maintaining 動名詞作主語。'),
(39, 'multiple_choice', '_____ the right suppliers is crucial for quality control.', '["Selected","Select","Selecting","To select"]', 'Selecting', 'Selecting 動名詞作主語。'),
(39, 'transform', 'It is important to track your expenses carefully. (Use gerund as subject)', NULL, 'Tracking your expenses carefully is important for financial management.', 'Tracking 動名詞作主語。'),
(39, 'fill_blank', '_____ (negotiate) well can save the company significant costs.', NULL, 'Negotiating', 'Negotiating 動名詞作主語。'),
(39, 'multiple_choice', '_____ new technologies early gives companies a competitive advantage.', '["Adopted","Adopt","Adopting","To adopt"]', 'Adopting', 'Adopting 動名詞作主語。'),
(39, 'multiple_choice', '_____ in professional development benefits both employees and the company.', '["Investing","Invested","Invest","To invest"]', 'Investing', 'Investing 動名詞作主語。'),
(39, 'multiple_choice', '_____ clearly and concisely is vital for business communication.', '["To write","Written","Writing","Write"]', 'Writing', 'Writing 動名詞作主語。'),
(39, 'fill_blank', '_____ (build) a strong network is essential for career growth.', NULL, 'Building', 'Building 動名詞作主語。'),
(39, 'multiple_choice', '_____ a global workforce requires cross-cultural competence.', '["To manage","Managed","Managing","Manage"]', 'Managing', 'Managing 動名詞作主語。'),
(39, 'multiple_choice', '_____ the market before entering reduces business risk.', '["Research","Researching","To research","Researched"]', 'Researching', 'Researching 動名詞作主語。'),
(39, 'transform', 'It takes skill to analyze complex data quickly. (Use gerund subject)', NULL, 'Analyzing complex data quickly takes considerable skill and experience.', 'Analyzing 動名詞作主語。'),
(39, 'fill_blank', '_____ (set) clear goals is the first step to project success.', NULL, 'Setting', 'Setting 動名詞作主語。'),
(39, 'multiple_choice', '_____ regularly with your team prevents miscommunication.', '["Met","To meet","Meeting","Meet"]', 'Meeting', 'Meeting 動名詞作主語。'),
(39, 'multiple_choice', '_____ to clients'' needs builds long-term business relationships.', '["Listening","To listen","Listen","Listened"]', 'Listening', 'Listening 動名詞作主語。'),
(39, 'fill_blank', '_____ (take) initiative is a quality we look for in all our employees.', NULL, 'Taking', 'Taking 動名詞作主語。'),
(39, 'multiple_choice', '_____ the company''s mission and values is expected of all staff.', '["To understand","Understand","Understanding","Understood"]', 'Understanding', 'Understanding 動名詞作主語。'),
(40, 'multiple_choice', 'She flew to Shanghai _____ meet the key supplier.', '["so as","for","to","in order"]', 'to', 'to + 原形動詞表目的。'),
(40, 'multiple_choice', 'We hired a consultant _____ improve our operational efficiency.', '["for","at","to","in"]', 'to', 'to + 原形動詞表目的。'),
(40, 'multiple_choice', 'He attended the seminar _____ network with industry leaders.', '["in order","to","for","so as"]', 'to', 'to + 原形動詞表目的。'),
(40, 'fill_blank', 'She called the client _____ (confirm) the order details.', NULL, 'to confirm', 'to + 原形動詞表目的。'),
(40, 'multiple_choice', 'We use this platform _____ streamline communication across departments.', '["at","in","for","to"]', 'to', 'to + 原形表工具使用目的。'),
(40, 'multiple_choice', 'The company launched a new initiative _____ attract top talent.', '["in order to","for","so as","to"]', 'in order to', 'in order to 更正式的目的表達，也可用 to。'),
(40, 'multiple_choice', 'He took a finance course _____ better understand the balance sheet.', '["in","for","to","at"]', 'to', 'to + 原形動詞表目的。'),
(40, 'transform', 'We created the policy. The purpose was to prevent data breaches. (Use: in order to)', NULL, 'We created this policy in order to prevent data breaches.', 'in order to 更正式的目的不定詞。'),
(40, 'fill_blank', 'The team worked overtime _____ (meet) the project deadline.', NULL, 'to meet', 'to + 原形動詞表目的。'),
(40, 'multiple_choice', 'She gave the client a discount _____ retain the business relationship.', '["so as","to","in order","for"]', 'to', 'to + 原形動詞表目的。'),
(40, 'multiple_choice', 'We need _____ expand our market presence.', '["for","so as","in","to"]', 'to', 'need + to + 原形。'),
(40, 'multiple_choice', 'The CEO travelled to New York _____ sign the partnership agreement.', '["in","at","for","to"]', 'to', 'to + 原形動詞表目的。'),
(40, 'fill_blank', 'We streamlined our process _____ (reduce) operational costs.', NULL, 'to reduce', 'to + 原形動詞表目的。'),
(40, 'multiple_choice', 'She took detailed notes _____ not forget any action items.', '["in order not to","so as not to","to not","not to"]', 'so as not to', 'so as not to 表負面目的（避免）。'),
(40, 'multiple_choice', 'The firm invested in R&D _____ develop innovative solutions.', '["in","for","at","to"]', 'to', 'to + 原形動詞表目的。'),
(40, 'multiple_choice', 'He reviewed the proposal carefully _____ identify any weaknesses.', '["so as","for","in order to","to"]', 'in order to', 'in order to 更正式的目的不定詞。'),
(40, 'transform', 'We redesigned the website. The goal was to improve user experience. (Use: to)', NULL, 'We redesigned the website to improve the user experience.', 'to + 原形動詞表目的。'),
(40, 'fill_blank', 'She prepared a detailed handover document _____ (help) her successor.', NULL, 'to help', 'to + 原形動詞表目的。'),
(40, 'multiple_choice', 'The company held focus groups _____ gather consumer feedback.', '["for","in","at","to"]', 'to', 'to + 原形動詞表目的。'),
(40, 'multiple_choice', 'We implemented the new system _____ reduce manual data entry.', '["for","to","in","at"]', 'to', 'to + 原形動詞表目的。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(41, 'multiple_choice', 'The manager asked the team _____ the report by noon.', '["to submit","submit","submitting","of submitting"]', 'to submit', 'ask + 人 + to do。'),
(41, 'multiple_choice', 'We want our employees _____ with clients professionally.', '["of communicating","communicate","communicating","to communicate"]', 'to communicate', 'want + 人 + to do。'),
(41, 'fill_blank', 'The director advised us _____ (reconsider) the pricing strategy.', NULL, 'to reconsider', 'advise + 人 + to do。'),
(41, 'multiple_choice', 'The company requires all staff _____ annual training.', '["complete","of completing","to complete","completing"]', 'to complete', 'require + 人 + to do。'),
(41, 'multiple_choice', 'She encouraged her team _____ new approaches.', '["to try","of trying","trying","try"]', 'to try', 'encourage + 人 + to do。'),
(41, 'multiple_choice', 'We expect all applicants _____ a portfolio.', '["submit","of submitting","submitting","to submit"]', 'to submit', 'expect + 人 + to do。'),
(41, 'multiple_choice', 'The policy allows employees _____ from home two days a week.', '["work","to work","of working","working"]', 'to work', 'allow + 人 + to do。'),
(41, 'transform', 'The CEO told us: manage the budget carefully. (Use: asked us to)', NULL, 'The CEO asked us to manage the budget more carefully.', 'ask + 人 + to do。'),
(41, 'multiple_choice', 'He hired a consultant _____ the marketing strategy.', '["to revise","of revising","revise","revising"]', 'to revise', 'hired someone to do 委託做某事。'),
(41, 'fill_blank', 'The board authorized the CFO _____ (sign) contracts up to $1 million.', NULL, 'to sign', 'authorize + 人 + to do 授權。'),
(41, 'multiple_choice', 'She invited the client _____ a factory tour.', '["of joining","join","joining","to join"]', 'to join', 'invite + 人 + to do。'),
(41, 'multiple_choice', 'The company trains staff _____ with the new software.', '["of working","to work","work","working"]', 'to work', 'trains someone to do 培訓做某事。'),
(41, 'multiple_choice', 'He persuaded the client _____ the extended warranty.', '["purchase","of purchasing","purchasing","to purchase"]', 'to purchase', 'persuade + 人 + to do。'),
(41, 'fill_blank', 'We need you _____ (confirm) your attendance by Friday.', NULL, 'to confirm', 'need + 人 + to do。'),
(41, 'multiple_choice', 'The supervisor told the intern _____ the filing system.', '["organize","to organize","of organizing","organizing"]', 'to organize', 'tell + 人 + to do。'),
(41, 'multiple_choice', 'They enabled the team _____ remotely during the crisis.', '["work","to work","working","of working"]', 'to work', 'enable + 人 + to do 使...能夠。'),
(41, 'transform', 'The client asked: please send us a detailed quotation. (Use: asked us to)', NULL, 'The client asked us to send them a detailed quotation.', 'ask + 人 + to do，注意代名詞調整。'),
(41, 'fill_blank', 'The manager reminded her _____ (submit) the expense claims.', NULL, 'to submit', 'remind + 人 + to do。'),
(41, 'multiple_choice', 'The firm appointed her _____ the new regional director.', '["of being","being","to be","be"]', 'to be', 'appoint + 人 + to be 任命為。'),
(41, 'multiple_choice', 'He helped the client _____ the right product.', '["to choose","choose","choosing","of choosing"]', 'to choose', 'help + 人 + to do（to 可省略）。'),
(42, 'multiple_choice', 'Our new system is _____ than the previous one.', '["faster","more fast","fast","more faster"]', 'faster', '單音節加 -er：faster。'),
(42, 'multiple_choice', 'This approach is _____ to implement than the original plan.', '["easiest","more easy","easier","most easy"]', 'easier', 'easy → easier，比較級。'),
(42, 'multiple_choice', 'The new model is _____ efficient than its predecessor.', '["very","most","much","more"]', 'more', '多音節用 more + 形容詞。'),
(42, 'fill_blank', 'Their customer service is _____ (good) than ours.', NULL, 'better', 'good → better 不規則比較級。'),
(42, 'multiple_choice', 'The situation is _____ than we initially expected.', '["more bad","more worse","worser","worse"]', 'worse', 'bad → worse 不規則比較級。'),
(42, 'multiple_choice', 'The revised proposal is _____ clear than the first version.', '["more clear","most clear","clearer","clearly"]', 'clearer', 'clear → clearer，單音節加 -er。'),
(42, 'multiple_choice', 'Processing times are _____ with the new software.', '["shortest","most short","more short","shorter"]', 'shorter', 'short → shorter 比較級。'),
(42, 'transform', 'Version 2 is not as effective as version 1. (Use: less effective)', NULL, 'Version 2 is less effective than version 1.', 'less + 形容詞表劣於比較。'),
(42, 'multiple_choice', 'She is a _____ communicator than her predecessor.', '["most good","better","more good","gooder"]', 'better', 'good → better 不規則比較級。'),
(42, 'fill_blank', 'This solution is _____ (cost-effective) than the alternatives.', NULL, 'more cost-effective', '多音節形容詞 more + cost-effective。'),
(42, 'multiple_choice', 'The new office is _____ accessible to public transport.', '["very","much","more","most"]', 'more', 'more accessible 多音節比較級。'),
(42, 'multiple_choice', 'Working conditions are _____ than they were five years ago.', '["much good","more better","much more better","much better"]', 'much better', 'much 可加強比較級，good → better。'),
(42, 'multiple_choice', 'Our Q3 results were _____ than Q2.', '["strongly","more strong","most strong","stronger"]', 'stronger', 'strong → stronger 比較級。'),
(42, 'transform', 'Outsourcing is cheaper. In-house is more reliable. (Use: cheaper than)', NULL, 'Outsourcing is cheaper than in-house, but in-house is more reliable.', 'cheaper than 比較兩種選項。'),
(42, 'fill_blank', 'This model is _____ (efficient) and _____ (affordable) than the old one.', NULL, 'more efficient / more affordable', '多音節形容詞加 more。'),
(42, 'multiple_choice', 'This quarter''s performance is _____ than last year''s.', '["much far good","farther good","far better","more far better"]', 'far better', 'far better 用 far 加強比較級。'),
(42, 'multiple_choice', 'The process became _____ as we automated more tasks.', '["most smooth","smoother","smoothly","more smooth"]', 'smoother', 'smooth → smoother 比較級。'),
(42, 'multiple_choice', 'This is a _____ approach to solving the problem.', '["innovativer","more innovative","much innovative","most innovative"]', 'more innovative', 'innovative 多音節，more innovative。'),
(42, 'fill_blank', 'The new hire is _____ (experienced) than we expected.', NULL, 'more experienced', 'experienced 多音節，more experienced。'),
(42, 'multiple_choice', 'His proposal is _____ than hers in terms of feasibility.', '["more realistic","realisticker","much realistic","most realistic"]', 'more realistic', 'realistic 多音節，more realistic。'),
(43, 'multiple_choice', 'This is _____ proposal we have received.', '["the better","the best","better","the most good"]', 'the best', 'good → the best 最高級。'),
(43, 'multiple_choice', 'Our Q4 was _____ quarter in the company''s history.', '["most profitable","the profitablest","the most profitable","more profitable"]', 'the most profitable', 'profitable 多音節，the most profitable。'),
(43, 'multiple_choice', 'She is _____ candidate for this role.', '["the qualifiedest","most qualified","the most qualified","more qualified"]', 'the most qualified', 'qualified 多音節，the most qualified。'),
(43, 'fill_blank', 'This was _____ (bad) product launch we''ve ever experienced.', NULL, 'the worst', 'bad → the worst 不規則最高級。'),
(43, 'multiple_choice', 'The new software is _____ option available.', '["most cheap","the cheapest","cheaper","cheapest"]', 'the cheapest', 'cheap → the cheapest，最高級前加 the。'),
(43, 'multiple_choice', 'This deal represents _____ opportunity we have seen this year.', '["the most great","more great","the greatest","greatest"]', 'the greatest', 'great → the greatest。'),
(43, 'multiple_choice', 'That was _____ presentation I have ever attended.', '["more inspiring","the most inspiring","the most inspired","the inspiringest"]', 'the most inspiring', 'inspiring 多音節，the most inspiring。'),
(43, 'transform', 'No other quarter performed better than Q3. (Use: best)', NULL, 'Q3 was our best-performing quarter of the year.', 'the best 最高級。'),
(43, 'multiple_choice', 'He is _____ salesperson on our team.', '["the most productive","the productivest","more productive","most productive"]', 'the most productive', 'productive 多音節，the most productive。'),
(43, 'fill_blank', 'This is _____ (far) we have ever expanded geographically.', NULL, 'the furthest/farthest', 'far → the furthest/farthest 最高級。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(43, 'multiple_choice', 'The first approach is _____ of all the options presented.', '["least expensive","less expensive","the most cheapest","the least expensive"]', 'the least expensive', 'the least expensive 最低程度最高級。'),
(43, 'multiple_choice', 'She achieved _____ results in the department.', '["higher","highest","the highest","most high"]', 'the highest', 'high → the highest，最高級前 the。'),
(43, 'multiple_choice', 'This has been _____ challenging project I have managed.', '["more","the better","the most","a most"]', 'the most', 'the most + challenging，多音節最高級。'),
(43, 'transform', 'No solution is simpler than option A. (Use: simplest)', NULL, 'Option A is the simplest solution available.', 'the simplest 最高級。'),
(43, 'fill_blank', 'He is one of _____ (experienced) managers in the industry.', NULL, 'the most experienced', 'one of the most + 形容詞最高級。'),
(43, 'multiple_choice', 'The Tokyo branch is performing _____ of all our offices.', '["better","the most good","the best","much good"]', 'the best', 'best 副詞最高級，表現最好。'),
(43, 'multiple_choice', 'This was _____ decision we could have made.', '["more bad","badder","the most bad","the worst"]', 'the worst', 'bad → the worst 最高級。'),
(43, 'multiple_choice', 'He is _____ analyst on the team in terms of accuracy.', '["the precisest","the most precise","more precise","most precise"]', 'the most precise', 'precise 多音節，the most precise。'),
(43, 'fill_blank', 'This strategy gave us _____ (high) return on investment.', NULL, 'the highest', 'high → the highest，最高級。'),
(43, 'multiple_choice', 'That client has been _____ loyal partner since the beginning.', '["a most","our best","our most","the more"]', 'our most', 'our most loyal 限定詞 + 最高級。'),
(44, 'multiple_choice', 'Our new product is _____ reliable _____ the competitor''s.', '["as / as","more / as","so / as","as / than"]', 'as / as', 'as...as 表兩者相等。'),
(44, 'multiple_choice', 'The delivery was not _____ fast _____ we had expected.', '["as / as","so / as","more / as","as / than"]', 'as / as', 'not as...as 表不如預期。'),
(44, 'multiple_choice', 'This branch is performing just _____ well _____ last year.', '["so / as","as / than","as / as","more / as"]', 'as / as', 'just as...as 強調完全相等。'),
(44, 'fill_blank', 'Our costs are twice _____ high _____ our competitors''.', NULL, 'as / as', 'twice as...as 表兩倍關係。'),
(44, 'multiple_choice', 'She works just _____ hard _____ anyone else on the team.', '["so / as","more / as","as / than","as / as"]', 'as / as', 'just as...as 完全相等。'),
(44, 'multiple_choice', 'Is this model _____ durable _____ the previous one?', '["so / as","more / as","as / as","as / than"]', 'as / as', 'as...as 疑問句比較。'),
(44, 'multiple_choice', 'The results weren''t _____ impressive _____ expected.', '["so / as","as / than","more / as","as / as"]', 'as / as', 'not as...as 表低於預期。'),
(44, 'transform', 'Revenues are equal this year and last year. (Use: as high as)', NULL, 'Revenues this year are as high as last year''s.', 'as...as 表數量相等。'),
(44, 'multiple_choice', 'The new platform is _____ efficient _____ the old one.', '["more / as","as much / than","as / as twice","twice as / as"]', 'twice as / as', 'twice as...as 兩倍效率。'),
(44, 'fill_blank', 'Their pricing is _____ competitive _____ ours.', NULL, 'not as / as', 'not as...as 表劣勢比較。'),
(44, 'multiple_choice', 'This report is _____ detailed _____ the one last quarter.', '["more / as","so / as","as / than","as / as"]', 'as / as', 'as...as 兩份報告同等詳細。'),
(44, 'multiple_choice', 'She speaks _____ clearly _____ any senior manager.', '["more / as","as / than","as / as","so / as"]', 'as / as', '副詞用 as...as。'),
(44, 'multiple_choice', 'The client isn''t _____ demanding _____ we thought.', '["more / as","as / as","so / as","as / than"]', 'as / as', 'not as...as 表不如預期。'),
(44, 'transform', 'Profits in Q1 equal profits in Q2. (Use: as high as)', NULL, 'Q1 profits were as high as Q2 profits.', 'as...as 數量相等。'),
(44, 'fill_blank', 'Our service is _____ reliable _____ our top competitor''s.', NULL, 'as / as', 'as...as 表相等。'),
(44, 'multiple_choice', 'This proposal is _____ comprehensive _____ the other one.', '["not so / than","less / than","so / as","not as / as"]', 'not as / as', 'not as...as 表較不全面。'),
(44, 'multiple_choice', 'The new hire is _____ experienced _____ the rest of the team.', '["as / as","as / than","more / as","so / as"]', 'as / as', 'as...as 相等經驗。'),
(44, 'fill_blank', 'Working remotely can be _____ productive _____ working in the office.', NULL, 'as / as', 'as...as 表相等生產力。'),
(44, 'multiple_choice', 'The interest rate is _____ high _____ it was last year.', '["so / as","as / than","not as / as","less / than"]', 'not as / as', 'not as...as 表較低。'),
(44, 'multiple_choice', 'This software is _____ user-friendly _____ its predecessor.', '["three times as / as","times as / as","as / so","more / as"]', 'three times as / as', 'three times as...as 三倍用法。'),
(45, 'multiple_choice', '_____ we invest in training, _____ our team performs.', '["More / better","The more / the more better","The most / the best","The more / the better"]', 'The more / the better', 'The more...the better 雙重比較。'),
(45, 'multiple_choice', '_____ the deadline, _____ the team works.', '["The most close / the hardest","Closer / harder","More close / more hard","The closer / the harder"]', 'The closer / the harder', 'The closer...the harder 雙重比較。'),
(45, 'fill_blank', '_____ clients we retain, _____ our revenue grows. (Use double comparative)', NULL, 'The more / the more', 'The more...the more 正比關係。'),
(45, 'multiple_choice', '_____ the team communicates, _____ the project runs.', '["Most frequently / most smoothly","More frequently / more smooth","The frequently / the smooth","The more frequently / the more smoothly"]', 'The more frequently / the more smoothly', 'the + 比較副詞的雙重比較。'),
(45, 'multiple_choice', '_____ data we have, _____ informed our decisions.', '["More / most","More / more","The more / the more","The most / the most"]', 'The more / the more', 'The more data...the more informed 雙重比較。'),
(45, 'multiple_choice', '_____ we delay, _____ it will cost.', '["The longest / the most","Longer / more","The more long / the more much","The longer / the more"]', 'The longer / the more', 'The longer...the more 時間與費用的反比。'),
(45, 'transform', 'If we expand faster, we get better economies of scale. (Use double comparative)', NULL, 'The faster we expand, the greater the economies of scale we achieve.', 'The faster...the greater 雙重比較。'),
(45, 'fill_blank', '_____ transparent our reporting, _____ investors trust us. (Use double comparative)', NULL, 'The more / the more', 'The more transparent...the more trust 雙重比較。'),
(45, 'multiple_choice', '_____ the team''s morale, _____ their performance.', '["The higher / the better","Higher / better","High / good","The most high / the best"]', 'The higher / the better', 'The higher...the better 雙重比較。'),
(45, 'multiple_choice', '_____ we automate, _____ time we save.', '["Most / more","The more / the more","The most / most","More / more"]', 'The more / the more', 'The more...the more 自動化與時間節省的正比。'),
(45, 'multiple_choice', '_____ complex the deal, _____ time it takes to close.', '["The more / the more","The most / most","More / more","Most / the most"]', 'The more / the more', 'The more complex...the more time 雙重比較。'),
(45, 'fill_blank', '_____ quickly we resolve the issue, _____ the client will be. (Use double comparative)', NULL, 'The more / the happier', 'The more quickly...the happier 雙重比較。'),
(45, 'multiple_choice', '_____ employees we hire, _____ our training costs.', '["The most / highest","Most / more high","The more / the higher","More / higher"]', 'The more / the higher', 'The more...the higher 雙重比較。'),
(45, 'transform', 'Strong branding leads to higher customer loyalty. (Use double comparative)', NULL, 'The stronger the brand, the higher the customer loyalty.', 'The stronger...the higher 雙重比較。'),
(45, 'multiple_choice', '_____ we focus on quality, _____ our reputation becomes.', '["Most / more strong","More / stronger","The more / the stronger","The most / strongest"]', 'The more / the stronger', 'The more...the stronger 品質與聲譽的關係。'),
(45, 'fill_blank', '_____ diversified the portfolio, _____ the risk. (Use double comparative)', NULL, 'The more / the lower', 'The more diversified...the lower the risk 雙重比較。'),
(45, 'multiple_choice', '_____ innovative the product, _____ it captures the market.', '["More / faster","The more / the faster","Most / more fast","The most / fastest"]', 'The more / the faster', 'The more innovative...the faster market capture。'),
(45, 'multiple_choice', '_____ clear our strategy, _____ aligned the team will be.', '["The most / most","Much / more","The more / the more","More / more"]', 'The more / the more', 'The more clear...the more aligned 雙重比較。'),
(45, 'transform', 'Faster decisions produce better results. (Use double comparative)', NULL, 'The faster we make decisions, the better the results will be.', 'The faster...the better 雙重比較。'),
(45, 'fill_blank', '_____ data-driven our approach, _____ accurate our forecasts. (Use double comparative)', NULL, 'The more / the more', 'The more data-driven...the more accurate 雙重比較。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(46, 'multiple_choice', '_____ the contract is signed, we can begin the project.', '["While","Until","Once","As soon as"]', 'Once', 'Once 表一旦...就，同 as soon as。'),
(46, 'multiple_choice', 'Please notify me _____ the client arrives.', '["before","as soon as","while","until"]', 'as soon as', 'as soon as 表一到達就立即通知。'),
(46, 'multiple_choice', 'She will stay in the office _____ the report is finished.', '["before","while","until","when"]', 'until', 'until 表持續到某事完成為止。'),
(46, 'fill_blank', '_____ (finish) the presentation, we will take questions.', NULL, 'After finishing / When we finish', 'after + V-ing 或 when + clause。'),
(46, 'multiple_choice', 'He checks his emails _____ he commutes to work.', '["once","until","while","before"]', 'while', 'while 表同時進行的動作。'),
(46, 'multiple_choice', 'We need to finalize the budget _____ the board meeting.', '["until","when","before","after"]', 'before', 'before the board meeting 截止時間。'),
(46, 'transform', 'The meeting ends. Then we will announce the results. (Use: after)', NULL, 'After the meeting ends, we will announce the results.', 'after + 時間子句。'),
(46, 'fill_blank', '_____ (submit) your application, please read all the requirements.', NULL, 'Before submitting', 'before + V-ing 提交前注意事項。'),
(46, 'multiple_choice', 'Sales increased significantly _____ the new campaign was launched.', '["before","after","while","until"]', 'after', 'after the campaign was launched 描述因果和時間。'),
(46, 'multiple_choice', 'By the time the CEO arrived, the team _____ already started.', '["had","have","was","has"]', 'had', 'by the time + 現在式，主句過去完成式。'),
(46, 'multiple_choice', '_____ working with international clients, she developed strong language skills.', '["While","Before","Until","Once"]', 'While', 'while + V-ing 表同時進行的情況。'),
(46, 'fill_blank', 'We cannot proceed _____ we receive the signed contract.', NULL, 'until', 'until 表等到...才能進行。'),
(46, 'multiple_choice', 'She always reviews the agenda _____ she enters the meeting room.', '["after","before","while","until"]', 'before', 'before 表進場前先做的事。'),
(46, 'multiple_choice', 'The problem was resolved _____ it escalated further.', '["when","before","until","after"]', 'before', 'before it escalated 提前解決。'),
(46, 'transform', 'The training finishes. We will assign team roles. (Use: when)', NULL, 'When the training finishes, we will assign everyone their team roles.', 'when + 現在式（表未來），will 主句。'),
(46, 'fill_blank', 'We had completed the onboarding _____ the new hire started.', NULL, 'before', 'before the new hire started，時間先後關係。'),
(46, 'multiple_choice', '_____ the audit is complete, the results will be shared with all departments.', '["Once","Before","Until","While"]', 'Once', 'Once the audit is complete 表完成後。'),
(46, 'multiple_choice', 'She takes notes _____ the client is speaking.', '["until","after","before","while"]', 'while', 'while 表同時進行。'),
(46, 'multiple_choice', 'The deal was announced _____ both sides had agreed on all terms.', '["after","before","while","until"]', 'after', 'after both sides agreed 強調先後。'),
(46, 'multiple_choice', 'He will work on this project _____ he transfers to the new position.', '["until","when","before","after"]', 'until', 'until he transfers 持續到調職為止。'),
(47, 'multiple_choice', '_____ the deadline was extended, we have more time to review.', '["Since","Despite","Although","Because of"]', 'Since', 'since/because 引導原因子句。'),
(47, 'multiple_choice', 'We had to cancel the event _____ low attendance.', '["because of","since","now that","as"]', 'because of', 'because of + 名詞短語（非子句）表原因。'),
(47, 'multiple_choice', 'She was promoted _____ she consistently exceeded her targets.', '["however","because","although","despite"]', 'because', 'because 引導原因子句。'),
(47, 'fill_blank', '_____ the market has stabilized, we can proceed with the investment.', NULL, 'Now that', 'now that 表現在情況改變，因此...。'),
(47, 'multiple_choice', '_____ the project was behind schedule, additional resources were allocated.', '["As","Despite","Although","However"]', 'As', 'as 引導原因子句，較正式。'),
(47, 'multiple_choice', 'We need to act quickly _____ our competitors are already ahead.', '["however","because","although","despite"]', 'because', 'because 引導原因子句。'),
(47, 'multiple_choice', 'He was unable to attend the meeting _____ a prior commitment.', '["as","due to","because","since"]', 'due to', 'due to + 名詞短語（非子句）表原因，正式用法。'),
(47, 'transform', 'The project failed. The reason was poor communication. (Use: because)', NULL, 'The project failed because of poor communication among the teams.', 'because of + 名詞短語。'),
(47, 'fill_blank', '_____ the economy is recovering, consumer confidence is rising.', NULL, 'As / Since', 'as 或 since 引導原因子句。'),
(47, 'multiple_choice', '_____ he had the most experience, he was chosen to lead the negotiation.', '["Despite","However","Since","Although"]', 'Since', 'since 引導原因子句，用於說明已知原因。'),
(47, 'multiple_choice', 'The order was delayed _____ a production error.', '["since","owing to","because","as"]', 'owing to', 'owing to + 名詞短語，正式原因表達。'),
(47, 'multiple_choice', '_____ the new policy was implemented, employee satisfaction has improved.', '["Because of","Now that","Although","Since"]', 'Now that', 'now that 表現在的新情況導致的結果。'),
(47, 'fill_blank', 'She was given extra responsibility _____ she had proven herself reliable.', NULL, 'because / since', 'because 或 since 引導原因子句。'),
(47, 'multiple_choice', 'The meeting was rescheduled _____ the CEO was travelling.', '["however","despite","although","as"]', 'as', 'as 引導原因子句，較正式。'),
(47, 'multiple_choice', 'We lost the contract _____ our pricing was not competitive.', '["despite","although","however","because"]', 'because', 'because 引導原因子句。'),
(47, 'transform', 'The branch closed. There was insufficient demand. (Use: due to)', NULL, 'The branch was closed due to insufficient demand in the local market.', 'due to + 名詞短語表原因。'),
(47, 'fill_blank', '_____ (because) bad weather, the outdoor event was moved indoors.', NULL, 'Because of / Due to', 'because of / due to + 名詞短語。'),
(47, 'multiple_choice', 'She left the firm early _____ a family emergency.', '["since","because of","as","now that"]', 'because of', 'because of + 名詞短語。'),
(47, 'multiple_choice', '_____ sales are declining, we must reassess our strategy.', '["However","Despite","Although","As"]', 'As', 'as 引導原因子句。'),
(47, 'multiple_choice', 'The contract was terminated _____ breach of terms.', '["since","as","because","due to"]', 'due to', 'due to 正式書面原因表達。'),
(48, 'multiple_choice', '_____ the budget was limited, the project was completed on time.', '["Although","Since","While","Because"]', 'Although', 'although 引導讓步子句。'),
(48, 'multiple_choice', 'Sales increased _____ we reduced our marketing spend.', '["although","even though","while","because"]', 'even though', 'even though 強調更大的讓步（減少行銷費用仍增加）。'),
(48, 'multiple_choice', 'Our product is more expensive _____ it offers greater value.', '["despite","however","although","but"]', 'but', 'but 連接對比子句（並列）。'),
(48, 'fill_blank', '_____ (although) the proposal was rejected, we learned from the experience.', NULL, 'Although / Even though', 'although/even though 引導讓步子句。'),
(48, 'multiple_choice', '_____ our team is small, we consistently deliver high-quality results.', '["Although","Despite","However","Whereas"]', 'Whereas', 'whereas 也可引導對比（此處也可用 Although）。'),
(48, 'multiple_choice', 'The market is recovering _____ some sectors are still struggling.', '["while","since","although","because"]', 'while', 'while 表兩種情況的對比。'),
(48, 'multiple_choice', 'She accepted the offer _____ the salary was lower than expected.', '["because","even though","since","while"]', 'even though', 'even though 強調讓步。'),
(48, 'transform', 'We increased output. At the same time, we reduced defects. (Use: while)', NULL, 'While we increased output, we also managed to reduce defects.', 'while 表同時對比或並列情況。'),
(48, 'fill_blank', '_____ having limited resources, the team delivered excellent results.', NULL, 'Despite', 'despite + V-ing 讓步表達。'),
(48, 'multiple_choice', 'The demand for our product is high _____ the price increase.', '["even though","despite","while","although"]', 'despite', 'despite + 名詞短語（非子句）。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(48, 'multiple_choice', '_____ the economic downturn, our company remained profitable.', '["Despite","Even though","While","Although"]', 'Despite', 'despite + 名詞短語。'),
(48, 'multiple_choice', 'The new system is faster _____ it requires more training.', '["since","while","because","although"]', 'although', 'although 引導對比子句。'),
(48, 'fill_blank', '_____ (although) the conditions were challenging, the team exceeded targets.', NULL, 'Although / Even though', '讓步子句。'),
(48, 'multiple_choice', 'Customer satisfaction improved _____ there were some complaints.', '["since","even though","because","while"]', 'even though', 'even though 強調讓步。'),
(48, 'multiple_choice', 'Their prices are higher _____ ours.', '["although","than","while","however"]', 'than', 'than 比較，注意此處不是對比子句。'),
(48, 'transform', 'We faced many challenges. However, we achieved our goals. (Use: although)', NULL, 'Although we faced many challenges, we still achieved our goals.', 'although 讓步子句。'),
(48, 'multiple_choice', '_____ the merger was risky, the board approved it unanimously.', '["While","Although","Because","Since"]', 'Although', 'although 引導讓步子句。'),
(48, 'fill_blank', 'Sales rose in Asia _____ they fell in Europe.', NULL, 'while / whereas', 'while/whereas 表兩個對比事實。'),
(48, 'multiple_choice', 'He is very skilled _____ sometimes lacks attention to detail.', '["while","since","although","because"]', 'although', 'although 引導讓步子句。'),
(48, 'multiple_choice', '_____ the challenges we faced, the project was a success.', '["Even though","While","Despite","Although"]', 'Despite', 'despite + 名詞短語。'),
(49, 'multiple_choice', 'The data was _____ complex _____ the team needed extra time to analyse it.', '["so / which","such / that","so / that","such / which"]', 'so / that', 'so + 形容詞 + that 結果子句。'),
(49, 'multiple_choice', 'It was _____ a successful campaign _____ we repeated it the following year.', '["so a / that","such / that","so / that","such a / which"]', 'such / that', 'such a + 名詞 + that 結果子句。'),
(49, 'multiple_choice', 'The proposal was _____ well written _____ it was immediately approved.', '["such / that","such / which","so / that","so / which"]', 'so / that', 'so + 副詞 + that。'),
(49, 'fill_blank', 'The traffic was _____ bad _____ she missed the beginning of the meeting.', NULL, 'so / that', 'so + 形容詞 + that 結果子句。'),
(49, 'multiple_choice', 'They made _____ many mistakes _____ the contract had to be rewritten.', '["so / which","so / that","such / that","such / which"]', 'so / that', 'so many + 名詞 + that 結果子句。'),
(49, 'multiple_choice', 'There was _____ a high demand _____ production could not keep up.', '["so a / that","such / that","such / which","so / that"]', 'such / that', 'such + 冠詞 + 名詞 + that。'),
(49, 'multiple_choice', 'The client was _____ impressed _____ she recommended us to three other companies.', '["such / which","so / that","such / that","so / which"]', 'so / that', 'so + 形容詞 + that 結果子句。'),
(49, 'transform', 'The presentation was very long. Nobody could stay focused. (Use: so long that)', NULL, 'The presentation was so long that nobody could stay focused.', 'so + 形容詞 + that 結果子句。'),
(49, 'fill_blank', 'It was _____ an innovative idea _____ the board immediately approved the funding.', NULL, 'such / that', 'such a/an + 名詞 + that 結果子句。'),
(49, 'multiple_choice', 'He spoke _____ clearly _____ everyone understood the strategy perfectly.', '["such / that","so / that","such / which","so / which"]', 'so / that', 'so + 副詞 + that 結果子句。'),
(49, 'multiple_choice', 'There was _____ little time left _____ we had to postpone the launch.', '["so much / that","so / that","such / that","such much / that"]', 'so / that', 'so little + 不可數名詞 + that。'),
(49, 'multiple_choice', 'The results were _____ positive _____ we decided to scale up immediately.', '["such / which","so / that","so / which","such / that"]', 'so / that', 'so + 形容詞 + that。'),
(49, 'fill_blank', 'She worked _____ hard _____ she was promoted within six months.', NULL, 'so / that', 'so + 副詞 + that。'),
(49, 'multiple_choice', 'It was _____ a tight deadline _____ the team worked through the weekend.', '["such / that","such / which","so / that","so a / that"]', 'such / that', 'such a + 名詞 + that。'),
(49, 'multiple_choice', 'The savings were _____ significant _____ the project paid for itself in one year.', '["so / that","so / which","such / that","such / which"]', 'so / that', 'so + 形容詞 + that。'),
(49, 'transform', 'The report had many errors. It had to be completely rewritten. (Use: so many)', NULL, 'The report had so many errors that it had to be completely rewritten.', 'so many + 名詞 + that。'),
(49, 'fill_blank', 'She was _____ knowledgeable _____ everyone came to her for advice.', NULL, 'so / that', 'so + 形容詞 + that。'),
(49, 'multiple_choice', 'There were _____ few applicants _____ the position remained unfilled.', '["such / which","such few / that","so / that","such / that"]', 'so / that', 'so few + 名詞 + that。'),
(49, 'multiple_choice', 'The product launch was _____ a success _____ supply ran out within days.', '["such / that","so / that","so a / that","such / which"]', 'such / that', 'such a + 名詞 + that。'),
(49, 'multiple_choice', 'He presented the plan _____ persuasively _____ the investors agreed immediately.', '["so / which","such / that","such / which","so / that"]', 'so / that', 'so + 副詞 + that。'),
(50, 'multiple_choice', 'The client mentioned _____ the delivery timeline was too long.', '["how","which","that","what"]', 'that', 'that 引導受語名詞子句。'),
(50, 'multiple_choice', 'We need to understand _____ the customer really wants.', '["how","which","that","what"]', 'what', 'what 引導名詞子句，表「什麼」。'),
(50, 'multiple_choice', '_____ the merger will succeed depends on many factors.', '["What","Whether","If","That"]', 'Whether', 'whether 引導主語名詞子句，表是否。'),
(50, 'fill_blank', 'The report shows _____ revenue has increased by 15%.', NULL, 'that', 'that 引導受語名詞子句。'),
(50, 'multiple_choice', 'She asked _____ we could reduce the price.', '["which","what","whether","that"]', 'whether', 'whether 引導間接是否問句（名詞子句）。'),
(50, 'multiple_choice', 'The key issue is _____ we can maintain quality while reducing costs.', '["how","what","whether","that"]', 'whether', 'whether 作補語名詞子句。'),
(50, 'multiple_choice', 'Do you know _____ the meeting is scheduled for today?', '["if","that","what","whether"]', 'whether', 'whether 引導名詞子句，較 if 正式。'),
(50, 'transform', 'The team discussed the timeline. They wanted to know if it was realistic. (Use: whether)', NULL, 'The team discussed whether the timeline was realistic.', 'whether 名詞子句作受語。'),
(50, 'multiple_choice', 'I understand _____ you are concerned about the budget.', '["how","which","that","what"]', 'that', 'that 引導受語名詞子句，表達理解。'),
(50, 'fill_blank', 'The CEO announced _____ the company would expand into three new markets.', NULL, 'that', 'that 引導受語名詞子句（宣布）。'),
(50, 'multiple_choice', '_____ he managed to close the deal was impressive.', '["That","What","Which","How"]', 'How', 'how 引導主語名詞子句，表示方式。'),
(50, 'multiple_choice', 'They are still debating _____ to outsource the work.', '["whether","that","what","how"]', 'whether', 'whether to do 引導名詞子句。'),
(50, 'multiple_choice', 'The manager explained _____ the new process works.', '["that","which","how","what"]', 'how', 'how 引導名詞子句表方式。'),
(50, 'transform', 'He wanted to know the reason for the delay. (Use: why the project was delayed)', NULL, 'He wanted to know why the project had been delayed.', 'why 引導名詞子句作受語。'),
(50, 'fill_blank', 'It is important _____ all team members attend the briefing.', NULL, 'that', 'It is important that + 名詞子句。'),
(50, 'multiple_choice', '_____ the project will be completed by Q3 is not yet confirmed.', '["What","Whether","That","If"]', 'Whether', 'whether 引導主語名詞子句。'),
(50, 'multiple_choice', 'We need to determine _____ the project is still viable.', '["whether","that","how","what"]', 'whether', 'whether 引導受語名詞子句（判斷是否）。'),
(50, 'multiple_choice', 'The fact _____ sales are declining concerns the board.', '["how","that","which","what"]', 'that', 'the fact that 固定搭配引導名詞子句。'),
(50, 'fill_blank', 'I believe _____ we can still meet the deadline with extra resources.', NULL, 'that', 'believe + that 名詞子句。'),
(50, 'multiple_choice', 'Please confirm _____ you will be attending the annual summit.', '["that","what","whether","if"]', 'whether', 'confirm whether 確認是否，正式用法。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(51, 'multiple_choice', 'We increased our budget, _____ the results exceeded expectations.', '["but","and","for","so"]', 'and', 'and 增加並列資訊。'),
(51, 'multiple_choice', 'The proposal was thorough, _____ the client rejected it.', '["and","but","for","so"]', 'but', 'but 表對比轉折。'),
(51, 'multiple_choice', 'Sales were strong, _____ we decided to expand.', '["for","but","so","and"]', 'so', 'so 表結果。'),
(51, 'multiple_choice', 'We can meet on Monday _____ Wednesday.', '["but","or","and","nor"]', 'or', 'or 表選擇。'),
(51, 'fill_blank', 'The product was innovative, _____ it failed to meet safety standards.', NULL, 'yet', 'yet 表意外的轉折，同 but（但更書面）。'),
(51, 'multiple_choice', 'She is experienced in marketing, _____ is she in sales.', '["but","nor","and","or"]', 'nor', 'neither... nor，nor 引導倒裝句。'),
(51, 'multiple_choice', 'We hired more staff, _____ we still can''t meet demand.', '["but","and","yet","so"]', 'yet', 'yet 表出乎意料的轉折。'),
(51, 'multiple_choice', 'He presented the data, _____ the board approved the plan.', '["and","so","but","for"]', 'and', 'and 表順序敘述。'),
(51, 'transform', 'We reduced costs. Therefore we increased profits. (Use: so)', NULL, 'We reduced costs, so we were able to increase profits.', 'so 連接兩個對等子句表結果。'),
(51, 'fill_blank', 'You can email me _____ call me — whichever is more convenient.', NULL, 'or', 'or 表兩個選擇。'),
(51, 'multiple_choice', 'The office is small, _____ the team is very productive.', '["but","and","so","yet"]', 'yet', 'yet 表意外對比（雖然...但）。'),
(51, 'multiple_choice', 'She is the team lead, _____ she has final say on all decisions.', '["so","for","but","and"]', 'so', 'so 表結果或因此。'),
(51, 'multiple_choice', 'We need to cut costs _____ maintain quality.', '["but","and","so","or"]', 'but', 'but 表兩者並列的張力（既要...又要）。'),
(51, 'transform', 'The deadline passed. However, the work was not finished. (Use: but)', NULL, 'The deadline passed, but the work was still not finished.', 'but 表轉折對比。'),
(51, 'fill_blank', 'We can outsource the project _____ handle it in-house.', NULL, 'or', 'or 表選擇。'),
(51, 'multiple_choice', 'She worked hard, _____ she earned the promotion.', '["but","so","and","for"]', 'so', 'so 表結果。'),
(51, 'multiple_choice', 'The team completed the audit _____ submitted the report on the same day.', '["so","but","or","and"]', 'and', 'and 連接兩個動作。'),
(51, 'multiple_choice', 'He is detail-oriented, _____ his team relies on him for accuracy.', '["for","so","but","and"]', 'so', 'so 表結果或原因（較口語）。'),
(51, 'fill_blank', 'We don''t have enough staff, _____ we need to outsource.', NULL, 'so', 'so 連接對等子句表結果。'),
(51, 'multiple_choice', 'The project was risky, _____ the potential returns were worth it.', '["for","but","and","so"]', 'but', 'but 表轉折讓步。'),
(52, 'multiple_choice', 'We will proceed _____ we receive written approval.', '["once","despite","because","although"]', 'once', 'once 表一旦...就，條件性時間。'),
(52, 'multiple_choice', '_____ the budget was approved, the project began immediately.', '["As soon as","Unless","Because of","Although"]', 'As soon as', 'as soon as 表一旦批准就開始。'),
(52, 'multiple_choice', 'She won the contract _____ her proposal was the most detailed.', '["although","because","unless","while"]', 'because', 'because 引導原因子句。'),
(52, 'fill_blank', '_____ the terms are acceptable, we will sign the contract next week.', NULL, 'If / Once / Provided that', '條件從屬連接詞。'),
(52, 'multiple_choice', 'We will miss the deadline _____ we hire more staff immediately.', '["although","if","because","unless"]', 'unless', 'unless = if not，表除非。'),
(52, 'multiple_choice', '_____ the price increases, customer demand may decrease.', '["If","Although","While","Because"]', 'If', 'if 引導條件子句。'),
(52, 'multiple_choice', 'The deal was secured _____ it took longer than expected.', '["because","since","while","although"]', 'although', 'although 引導讓步子句。'),
(52, 'transform', 'Provided the team works overtime, we can deliver on time. (Use: if)', NULL, 'If the team works overtime, we can deliver the project on time.', 'if 條件子句。'),
(52, 'fill_blank', 'She will accept the position _____ the relocation package is included.', NULL, 'provided that / if', 'provided that = if，條件。'),
(52, 'multiple_choice', '_____ he was new to the role, he handled the project remarkably well.', '["Although","While","Because","Since"]', 'Although', 'although 引導讓步子句。'),
(52, 'multiple_choice', 'The system crashed _____ the software was not properly updated.', '["although","because","while","unless"]', 'because', 'because 引導原因子句。'),
(52, 'multiple_choice', 'We cannot proceed _____ all stakeholders have signed off.', '["because","although","unless","until"]', 'until', 'until 表持續等到...才能進行。'),
(52, 'fill_blank', '_____ we invest in technology, we will fall behind competitors.', NULL, 'Unless', 'unless 表除非投資，否則就落後。'),
(52, 'multiple_choice', 'The report was delayed _____ technical difficulties.', '["unless","due to","although","despite"]', 'due to', 'due to + 名詞短語。'),
(52, 'multiple_choice', 'Sales improved _____ the team adopted a new approach.', '["unless","after","although","because"]', 'after', 'after 引導時間子句。'),
(52, 'transform', 'He didn''t attend training. As a result, he wasn''t promoted. (Use: because)', NULL, 'He wasn''t promoted because he hadn''t attended the required training.', 'because 引導原因子句。'),
(52, 'fill_blank', '_____ all conditions are met, the contract will be finalized.', NULL, 'Once / When / Provided that', '條件性從屬連接詞。'),
(52, 'multiple_choice', '_____ the market improves, we will reassess our expansion plans.', '["When","Although","Despite","Unless"]', 'When', 'when 引導時間/條件子句。'),
(52, 'multiple_choice', 'She will lead the project _____ she receives the necessary approvals.', '["unless","because","once","although"]', 'once', 'once 表一旦獲批就...。'),
(52, 'multiple_choice', '_____ the initial cost is high, the long-term benefits are clear.', '["While","Because","Since","Although"]', 'Although', 'although 引導讓步子句。'),
(53, 'multiple_choice', '_____ the manager _____ the assistant will attend the meeting — one of them will.', '["Neither / nor","Not only / but also","Either / or","Both / and"]', 'Either / or', 'either...or 表兩者之一。'),
(53, 'multiple_choice', '_____ the quality _____ the price met our expectations.', '["Neither / nor","Both / and","Either / or","Not only / but also"]', 'Neither / nor', 'neither...nor 表兩者都不符合。'),
(53, 'multiple_choice', '_____ the marketing team _____ the sales team contributed to the success.', '["Not only / but also","Either / or","Neither / nor","Both / and"]', 'Both / and', 'both...and 表兩者都。'),
(53, 'fill_blank', 'We can _____ negotiate the price _____ extend the deadline, but not both.', NULL, 'either / or', 'either...or 表兩個選項之一。'),
(53, 'multiple_choice', '_____ did she miss the deadline, _____ she failed to communicate the delay.', '["Not only / but also","Either / or","Neither / nor","Both / and"]', 'Not only / but also', 'not only...but also 表遞進強調。'),
(53, 'multiple_choice', '_____ the product quality _____ the customer service was satisfactory.', '["Either / or","Neither / nor","Both / and","Not only / but also"]', 'Neither / nor', 'neither...nor 表兩者皆不滿意。'),
(53, 'multiple_choice', 'Either the finance team _____ the legal team _____ the authority to approve this.', '["or / have","or / has","nor / have","and / has"]', 'or / has', 'either...or 就近原則，legal team 單數 has。'),
(53, 'transform', 'We need to improve quality. We also need to reduce costs. (Use: not only...but also)', NULL, 'We need to not only improve quality but also reduce our operating costs.', 'not only...but also 並列。'),
(53, 'fill_blank', 'Neither the CEO _____ the board members _____ present at the signing.', NULL, 'nor / were', 'neither...nor，board members 複數 were。'),
(53, 'multiple_choice', '_____ completing the project on time _____ under budget would be ideal.', '["Either / or","Not only / but also","Neither / nor","Both / and"]', 'Both / and', 'both...and 表兩個目標都達成。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(53, 'multiple_choice', 'Either you meet the requirements, _____ we cannot proceed.', '["and","nor","or","but"]', 'or', 'either...or 構成結果。'),
(53, 'multiple_choice', 'Neither the proposal _____ the contract _____ been signed yet.', '["nor / have","or / has","or / have","nor / has"]', 'nor / has', 'neither...nor，contract 單數，has。'),
(53, 'transform', 'She is efficient. She is also creative. (Use: not only...but also)', NULL, 'She is not only efficient but also highly creative in her approach.', 'not only...but also 強調雙重優點。'),
(53, 'fill_blank', 'We _____ lack the resources _____ the expertise to complete this in-house.', NULL, 'neither / nor', 'neither...nor 表兩者都缺乏。'),
(53, 'multiple_choice', 'Not only _____ she increase sales, _____ she reduced costs.', '["would / but also","is / but also","did / but also","has / and also"]', 'did / but also', 'not only...but also 倒裝結構。'),
(53, 'multiple_choice', 'Either the project manager _____ the deputy will lead the team.', '["or","and","but","nor"]', 'or', 'either...or 選擇。'),
(53, 'fill_blank', '_____ the budget increase _____ the deadline extension was approved.', NULL, 'Neither / nor', 'neither...nor 表兩個請求都被拒絕。'),
(53, 'multiple_choice', 'Both quality _____ efficiency _____ key priorities for our team.', '["nor / are","or / is","and / are","and / is"]', 'and / are', 'both...and 複數，are 正確。'),
(53, 'multiple_choice', 'Not only _____ we exceed revenue targets, _____ we also cut expenses.', '["did / but","have / and","are / but also","were / but also"]', 'did / but', 'not only did（倒裝） + but also。'),
(53, 'multiple_choice', 'Either we find a solution _____ we will lose the client.', '["but","or","nor","and"]', 'or', 'either...or 表兩者取一。'),
(54, 'multiple_choice', 'The manager / approved / the proposal. Which is the correct SVO order?', '["Approved the manager the proposal.","The manager approved the proposal.","The proposal approved the manager.","The proposal the manager approved."]', 'The manager approved the proposal.', '標準 SVO 語序。'),
(54, 'multiple_choice', 'Which sentence has correct SVO order?', '["She submitted the report on Friday.","She the report submitted Friday.","On Friday she submitted the report to.","Submitted she the report Friday."]', 'She submitted the report on Friday.', 'She（S）submitted（V）the report（O）on Friday（時間）。'),
(54, 'fill_blank', 'Reorder: yesterday / the client / called / us → _____.', NULL, 'The client called us yesterday.', 'SVO + 時間副詞置句尾。'),
(54, 'multiple_choice', 'Which is the correct sentence structure?', '["The CEO announced the new strategy at the annual meeting.","Announced at the annual meeting the strategy the CEO.","The CEO at the annual meeting the strategy announced.","At the annual meeting announced the CEO the strategy."]', 'The CEO announced the new strategy at the annual meeting.', 'SVO 語序，時間/地點副詞後置。'),
(54, 'multiple_choice', 'Which sentence follows correct English word order?', '["Emailed she the client the invoice.","She emailed the invoice to the client also correct","She emailed the client the invoice.","The invoice she emailed the client."]', 'She emailed the client the invoice.', 'SVOO（雙受語）語序，人在前物在後，或 She emailed the invoice to the client。'),
(54, 'multiple_choice', 'Where does the adverb ''often'' go in ''She checks her emails''?', '["She often checks her emails.","Often she checks her emails.","She checks her emails often.","She checks often her emails."]', 'She often checks her emails.', '頻率副詞 often 置主要動詞前（助動詞後）。'),
(54, 'transform', 'daily / attends / the manager / morning briefings (Arrange correctly)', NULL, 'The manager attends daily morning briefings.', 'SVO 語序，daily 形容詞修飾 briefings。'),
(54, 'fill_blank', 'Arrange: report / submitted / the team / on time → _____.', NULL, 'The team submitted the report on time.', 'The team（S）submitted（V）the report（O）on time（時間）。'),
(54, 'multiple_choice', 'Which sentence is grammatically correct?', '["Highly rate customers the service.","Customers rate the service highly.","Customers the service rate highly.","Rate customers highly the service."]', 'Customers rate the service highly.', 'SVO + 副詞 highly 置句尾。'),
(54, 'multiple_choice', 'In English, adjectives go _____the noun they modify.', '["before","around","after","following"]', 'before', '形容詞通常置名詞之前（前置修飾）。'),
(54, 'multiple_choice', 'Which is correct?', '["The budget discussed we during the meeting.","We discussed during the meeting the budget.","We discussed the budget during the meeting.","During the meeting we the budget discussed."]', 'We discussed the budget during the meeting.', 'SVO 語序，介系詞短語置句尾。'),
(54, 'fill_blank', 'Arrange: efficiently / the new system / processes / data → _____.', NULL, 'The new system processes data efficiently.', 'SVO + 副詞 efficiently 置句尾。'),
(54, 'multiple_choice', 'Which sentence is correct?', '["He presented to the board the quarterly results.","He presented the quarterly results to the board.","He to the board the quarterly results presented.","To the board he presented the quarterly results."]', 'He presented the quarterly results to the board.', 'SVO + 介系詞短語。'),
(54, 'multiple_choice', 'Where does ''yesterday'' go: ''She attended the conference''?', '["She attended the conference yesterday.","Yesterday she attended the conference yesterday.","She attended yesterday the conference.","She yesterday attended the conference."]', 'She attended the conference yesterday.', '時間副詞通常置句尾（或句首）。'),
(54, 'transform', 'in the city centre / is located / our new office (Arrange correctly)', NULL, 'Our new office is located in the city centre.', 'SV + 地點介系詞短語置句尾。'),
(54, 'fill_blank', 'Arrange: the proposal / carefully / reviewed / she → _____.', NULL, 'She reviewed the proposal carefully.', 'SVO + 副詞 carefully。'),
(54, 'multiple_choice', 'Which is correct word order with indirect and direct objects?', '["Me please send the updated report.","Please send the updated report me.","Please send updated the report me.","Please send me the updated report."]', 'Please send me the updated report.', '雙受語語序：人（me）在直接受語（the report）之前。'),
(54, 'multiple_choice', 'Which sentence is correct?', '["The finance team on time submitted the monthly report.","The finance team submitted the monthly report on time.","On time the finance team submitted the monthly report.","Submitted the monthly report the finance team on time."]', 'The finance team submitted the monthly report on time.', 'SVO + on time 時間副詞置句尾。'),
(54, 'fill_blank', 'Arrange: the clients / impressed / the presentation / deeply → _____.', NULL, 'The presentation deeply impressed the clients.', '深刻印象，副詞 deeply 放動詞前更常見在此語境。'),
(54, 'multiple_choice', 'Which is grammatically correct?', '["She gave the client a detailed overview of the project.","She gave a detailed overview to client the project.","A detailed overview she gave the client of the project.","The client she gave a detailed overview the project."]', 'She gave the client a detailed overview of the project.', 'She（S）gave（V）the client（IO）a detailed overview（DO）。'),
(55, 'multiple_choice', 'She _____ meets her deadlines.', '["all time meets","always","meets always","always met"]', 'always', 'always 頻率副詞置主要動詞前。'),
(55, 'multiple_choice', 'He _____ is late for meetings.', '["all times is","is all times","never is","is never"]', 'is never', 'is never：never 置 be 動詞後。'),
(55, 'multiple_choice', 'The manager reviewed the report _____ before the presentation.', '["quickly","quickest","quickened","quick"]', 'quickly', 'quickly 方式副詞置句尾。'),
(55, 'fill_blank', 'She speaks _____ (clear) and _____ (confident) in client meetings.', NULL, 'clearly / confidently', '副詞 -ly 修飾動詞。'),
(55, 'multiple_choice', 'It is _____ important to proofread before submitting.', '["extremer","most extreme","extreme","extremely"]', 'extremely', 'extremely 程度副詞置形容詞前。'),
(55, 'multiple_choice', 'He has _____ submitted the expense report.', '["already","just before","submitted already","before submitted"]', 'already', 'already 現在完成式置助動詞後。'),
(55, 'multiple_choice', 'They _____ complete this type of project in two weeks.', '["usually","complete usually","usually completed","usual complete"]', 'usually', 'usually 頻率副詞置主要動詞前。'),
(55, 'transform', 'She is efficient. She is very dedicated. (Rewrite with adverbs)', NULL, 'She works efficiently and is extremely dedicated.', '副詞形式修飾動詞/形容詞。'),
(55, 'multiple_choice', 'The proposal was _____ detailed.', '["surprising","surprisingly","with surprise","surprise"]', 'surprisingly', 'surprisingly 程度副詞修飾形容詞 detailed。'),
(55, 'fill_blank', 'The team worked _____ (hard) to meet the deadline.', NULL, 'hard', 'hard 既是形容詞也是副詞，不加 -ly。'),
(55, 'multiple_choice', 'He _____ checks his emails before noon.', '["rarely","rarely checked","check rarely","rare checks"]', 'rarely', 'rarely 頻率副詞置主要動詞前。'),
(55, 'multiple_choice', 'The CEO spoke _____ about the company''s future.', '["enthusiasm","enthusiastically","with enthusiastic","enthusiastic"]', 'enthusiastically', '-ly 副詞修飾動詞 spoke。'),
(55, 'multiple_choice', 'The report is _____ complete — just the conclusion is missing.', '["close","near","almost","most"]', 'almost', 'almost 程度副詞置形容詞前。'),
(55, 'transform', 'She is a careful worker. She is also precise. (Use adverbs)', NULL, 'She works carefully and precisely.', '副詞修飾動詞。'),
(55, 'fill_blank', 'I _____ (occasional) work from home on Fridays.', NULL, 'occasionally', 'occasionally 頻率副詞。'),
(55, 'multiple_choice', 'We have _____ resolved all the outstanding issues.', '["at final","finally","final","at last finally"]', 'finally', 'finally 置助動詞後，have finally resolved。'),
(55, 'multiple_choice', 'The client was _____ satisfied with the outcome.', '["with fully","fulling","full","fully"]', 'fully', 'fully 程度副詞修飾形容詞 satisfied。'),
(55, 'multiple_choice', 'She _____ arrives early to prepare for the day.', '["arrives usual","usual arrives","usually arrived","usually"]', 'usually', 'usually 頻率副詞置主要動詞前。'),
(55, 'fill_blank', 'The new policy is _____ (entire) designed to improve safety.', NULL, 'entirely', 'entirely 程度副詞修飾 designed。'),
(55, 'multiple_choice', 'He speaks English _____ in formal settings.', '["fluenter","fluently","with fluency","fluent"]', 'fluently', 'fluently 副詞修飾 speaks。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(56, 'multiple_choice', '_____ have we seen such a rapid growth in revenue.', '["Hardly","No","Never","Not"]', 'Never', '"Never have we seen" 否定副詞倒裝。'),
(56, 'multiple_choice', 'Not only _____ we exceed our targets, but we also reduced costs.', '["were","did","do","have"]', 'did', 'not only + did 倒裝（過去式）。'),
(56, 'multiple_choice', 'Rarely _____ the board make a unanimous decision so quickly.', '["does","is","has","do"]', 'does', 'rarely + does 倒裝（現在式三單）。'),
(56, 'fill_blank', 'Under no circumstances _____ (should) employees share login credentials.', NULL, 'should', 'under no circumstances 後倒裝，should 提前。'),
(56, 'multiple_choice', 'Hardly _____ the meeting started when a problem arose.', '["does","was","did","had"]', 'had', 'hardly had...when 倒裝句型。'),
(56, 'multiple_choice', 'Not only _____ the product innovative, but it is also affordable.', '["has","are","does","is"]', 'is', 'not only is...（現在式），是倒裝。'),
(56, 'multiple_choice', 'On no account _____ employees use company devices for personal use.', '["must","should","shall","ought"]', 'should', 'on no account + should 倒裝表禁止。'),
(56, 'transform', 'We have never encountered such a challenging project before. (Use inversion)', NULL, 'Never have we encountered such a challenging project before.', 'Never have we 否定副詞倒裝。'),
(56, 'multiple_choice', 'Seldom _____ we receive such positive feedback from clients.', '["have","are","do","does"]', 'do', 'seldom + do 倒裝（複數主詞）。'),
(56, 'fill_blank', 'No sooner _____ she submitted the report _____ the client called.', NULL, 'had / than', 'No sooner had...than 倒裝句型。'),
(56, 'multiple_choice', 'Not until the contract _____ signed _____ the project begin.', '["was / will","had / would","was / could","is / will"]', 'was / could', 'not until + 過去式，主句倒裝 could。'),
(56, 'multiple_choice', 'Little _____ the team know that the client would reject the proposal.', '["does","was","do","did"]', 'did', 'little did...know 否定副詞倒裝。'),
(56, 'multiple_choice', 'Under no circumstances _____ the price be negotiated further.', '["may","could","shall","can"]', 'can', 'under no circumstances + 情態動詞倒裝。'),
(56, 'transform', 'We had never invested so heavily in a single project. (Use inversion)', NULL, 'Never had we invested so heavily in a single project.', 'Never had we 否定副詞倒裝。'),
(56, 'fill_blank', 'Barely _____ (have) the new CEO taken office when the crisis began.', NULL, 'had', 'barely had...when 倒裝句型。'),
(56, 'multiple_choice', 'Not until this year _____ we fully recovered from the downturn.', '["did","had","have","were"]', 'have', 'not until + 現在完成式倒裝 have we。'),
(56, 'multiple_choice', 'Rarely _____ seen such commitment from a team.', '["I have","have we","have I","did I"]', 'have I', 'rarely have I 否定副詞倒裝。'),
(56, 'transform', 'The company had barely announced the merger when investors reacted. (Use inversion)', NULL, 'Barely had the company announced the merger when investors reacted.', 'Barely had...when 倒裝。'),
(56, 'fill_blank', 'Only when the audit _____ (complete) did the board realize the extent of the losses.', NULL, 'was completed', 'only when + 過去被動式；主句倒裝。'),
(56, 'multiple_choice', 'So _____ was the demand that the factory had to run 24 hours.', '["greatly","much great","great","greaten"]', 'great', 'so great...that 引起的倒裝感嘆結構。'),
(57, 'multiple_choice', 'We have _____ updates to share with the team.', '["every","any","no","some"]', 'some', 'some 在肯定句中表有一些。'),
(57, 'multiple_choice', 'Is there _____ feedback from the client?', '["every","any","some","no"]', 'any', 'any 在一般疑問句中。'),
(57, 'multiple_choice', 'We don''t have _____ available budget this quarter.', '["any","some","no","every"]', 'any', 'don''t have any 否定句中用 any。'),
(57, 'fill_blank', 'There are _____ issues with the contract that need to be resolved.', NULL, 'some', '肯定句中 some 表有一些問題。'),
(57, 'multiple_choice', 'Could you give me _____ advice on this proposal?', '["any","every","some","no"]', 'some', 'Could you give me some 期望肯定回應的疑問句。'),
(57, 'multiple_choice', 'We have _____ objections to the proposal.', '["every","no","some","any"]', 'no', 'no objections = not any objections，語氣更強。'),
(57, 'multiple_choice', 'Do you have _____ questions before we begin?', '["no","every","some","any"]', 'any', 'any 在一般疑問句中。'),
(57, 'fill_blank', 'She sent _____ files that contained sensitive information.', NULL, 'some', '肯定句 some files。'),
(57, 'multiple_choice', 'There is _____ guarantee that the deal will succeed.', '["no","every","some","any"]', 'no', 'no guarantee 強調沒有保證。'),
(57, 'multiple_choice', 'We still have _____ work to do before the deadline.', '["every","any","no","some"]', 'some', 'some work 肯定句有些工作要做。'),
(57, 'multiple_choice', 'He didn''t make _____ errors in the report.', '["every","any","no","some"]', 'any', 'didn''t make any errors 否定句用 any。'),
(57, 'fill_blank', 'Could you send me _____ samples of your product?', NULL, 'some', 'Could you send some 期望肯定的疑問句。'),
(57, 'multiple_choice', 'There is _____ room for negotiation on the price.', '["any","no","every","some"]', 'some', 'some room 表有協商空間。'),
(57, 'multiple_choice', 'We have _____ time to waste — the deadline is tomorrow.', '["some","any","every","no"]', 'no', 'no time to waste 強調完全沒有時間。'),
(57, 'multiple_choice', 'Have you received _____ response from the client?', '["any","every","no","some"]', 'any', 'any 在疑問句中。'),
(57, 'fill_blank', 'She made _____ useful suggestions during the meeting.', NULL, 'some', 'some suggestions 肯定句有幾個有用建議。'),
(57, 'multiple_choice', 'There is _____ doubt that this was the right decision.', '["no","every","any","some"]', 'no', 'no doubt 強調毫無疑問。'),
(57, 'transform', 'Do we have budget left? I''d like to know. (Use: any)', NULL, 'Do we have any budget left for this initiative?', 'any 疑問句中用於詢問是否有。'),
(57, 'fill_blank', 'Is there _____ chance we can reschedule the meeting?', NULL, 'any', 'any chance 疑問句詢問可能性。'),
(57, 'multiple_choice', 'We encountered _____ difficulties with the software installation.', '["no","every","some","any"]', 'some', 'some difficulties 肯定句有些困難。'),
(58, 'multiple_choice', 'We don''t have _____ time to complete this analysis.', '["much","few","many","a lot"]', 'much', 'much + 不可數名詞 time。'),
(58, 'multiple_choice', 'There are _____ opportunities in the Asian market.', '["many","much","few","a lot"]', 'many', 'many + 可數複數名詞 opportunities。'),
(58, 'multiple_choice', 'She has _____ experience in project management.', '["much of","few","many","a lot of"]', 'a lot of', 'experience 不可數，a lot of experience，也可用 much（正式）。'),
(58, 'fill_blank', 'We received _____ (many) applications for the position.', NULL, 'many / a lot of', 'many + 可數名詞；a lot of 也可。'),
(58, 'multiple_choice', 'There is _____ competition in the software market.', '["a lot of","many","much of","few"]', 'a lot of', 'competition 不可數，a lot of competition。'),
(58, 'multiple_choice', 'How _____ staff do we need for this project?', '["few","many","a lot of","much"]', 'many', 'how many + 可數名詞 staff。'),
(58, 'multiple_choice', 'We''ve made _____ progress on the merger negotiations.', '["much of","many","a lot of","few"]', 'a lot of', 'progress 不可數，a lot of progress（口語），much progress（正式）。'),
(58, 'fill_blank', 'She doesn''t have _____ information about the client''s requirements.', NULL, 'much', 'much + 不可數名詞 information，否定句。'),
(58, 'multiple_choice', 'How _____ budget has been allocated for marketing?', '["many","few","much","a lot of"]', 'much', 'how much + 不可數名詞 budget。'),
(58, 'multiple_choice', 'There are _____ factors to consider before making a decision.', '["much","a lot","many","few"]', 'many', 'many + 可數複數名詞 factors。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(58, 'multiple_choice', 'We don''t have _____ meetings scheduled for next week.', '["many","much","few","a lot"]', 'many', 'many + 可數名詞 meetings，否定句。'),
(58, 'fill_blank', 'She put _____ effort into preparing for the presentation.', NULL, 'a lot of / much', 'effort 不可數，a lot of 或 much（正式）。'),
(58, 'multiple_choice', '_____ of our clients have requested extended payment terms.', '["Many","Few","A lot","Much"]', 'Many', 'Many + 可數複數名詞 clients。'),
(58, 'multiple_choice', 'There isn''t _____ room in the budget for unexpected expenses.', '["few","a lot","much","many"]', 'much', 'much + 不可數名詞 room（空間）。'),
(58, 'multiple_choice', 'We have _____ data to support our recommendation.', '["few","many","a lot of","much of"]', 'a lot of', 'data 不可數，a lot of data。'),
(58, 'transform', 'The number of complaints was high last quarter. (Use: many)', NULL, 'We received many complaints from clients last quarter.', 'many + 可數複數名詞。'),
(58, 'fill_blank', 'How _____ research have you done on the topic?', NULL, 'much', 'much + 不可數名詞 research。'),
(58, 'multiple_choice', '_____ of the new initiatives are already showing results.', '["A lot","Much","Many","Few"]', 'Many', 'Many + 可數複數 initiatives。'),
(58, 'multiple_choice', 'She has _____ knowledge of international trade law.', '["many","few","extensive","a lot"]', 'extensive', 'extensive knowledge（形容詞）；much knowledge（正式）也可。'),
(58, 'multiple_choice', 'There are _____ advantages to adopting this technology.', '["few","a lot","much","many"]', 'many', 'many + 可數複數名詞 advantages。'),
(59, 'multiple_choice', 'We have _____ options — the situation is very limited.', '["few","little","a few","a little"]', 'few', 'few 幾乎沒有，語氣消極。'),
(59, 'multiple_choice', 'There is _____ time left to revise the proposal — about 30 minutes.', '["little","a little","a few","few"]', 'a little', 'a little 表還有一些時間，積極。'),
(59, 'multiple_choice', 'Only _____ candidates met the minimum qualifications.', '["a little","little","few","a few"]', 'a few', 'a few 表有幾位符合，積極。'),
(59, 'fill_blank', 'There is _____ hope of securing the contract at this late stage.', NULL, 'little', 'little 幾乎沒有希望，消極。'),
(59, 'multiple_choice', 'We still have _____ unresolved issues with the vendor.', '["a little","little","few","a few"]', 'a few', 'a few issues 幾個問題（還有一些需處理）。'),
(59, 'multiple_choice', '_____ effort is required to operate this new system.', '["Few","Little","A little","A few"]', 'Little', 'little effort 幾乎不需要努力。'),
(59, 'multiple_choice', 'She has _____ experience in this field — just six months.', '["a little","a few","few","little"]', 'a little', 'a little experience 有一些（雖然不多但有）。'),
(59, 'transform', 'We have some remaining budget. We can use it for training. (Use: a little)', NULL, 'We have a little budget remaining, which we can use for training.', 'a little + 不可數名詞，積極。'),
(59, 'multiple_choice', '_____ companies offer such a comprehensive package.', '["Little","A little","Few","A few"]', 'Few', 'few companies 幾乎沒有公司（罕見）。'),
(59, 'fill_blank', 'There was _____ confusion after the announcement, so clarification was needed.', NULL, 'a little / some', 'a little confusion 有些困惑（不可數）。'),
(59, 'multiple_choice', 'She has _____ relevant experience, so she may need extra support.', '["little","a few","a little","few"]', 'little', 'little experience 幾乎沒有，語氣消極。'),
(59, 'multiple_choice', 'We received _____ complaints this month, which is encouraging.', '["a few","a little","little","few"]', 'a few', 'a few complaints 有幾個（語氣積極，表示只是少數）。'),
(59, 'multiple_choice', 'There is _____ evidence to support this claim.', '["a little","few","a few","little"]', 'little', 'little evidence 幾乎沒有證據，消極。'),
(59, 'transform', 'We have some time before the call. Let''s prepare. (Use: a little)', NULL, 'We have a little time before the call, so let''s prepare.', 'a little time 有一點時間（積極）。'),
(59, 'fill_blank', '_____ members of the team understood the technical requirements.', NULL, 'Few', 'few members 幾乎沒有人理解，消極。'),
(59, 'multiple_choice', 'She made _____ mistakes in the report — just two minor ones.', '["a few","few","a little","little"]', 'a few', 'a few mistakes 有幾個（有限的）錯誤。'),
(59, 'multiple_choice', 'We have _____ information about the client''s decision-making process.', '["a little","few","little","a few"]', 'little', 'little information 幾乎沒有資訊，消極。'),
(59, 'fill_blank', 'I have _____ concerns about the plan, but overall it looks good.', NULL, 'a few', 'a few concerns 有幾個顧慮（但整體正面）。'),
(59, 'multiple_choice', 'There is _____ demand for this product in the local market.', '["a little","little","a few","few"]', 'little', 'little demand 需求很低，消極。'),
(59, 'multiple_choice', 'She has _____ suggestions to improve the workflow.', '["a little","little","a few","few"]', 'a few', 'a few suggestions 有幾個建議，積極。'),
(60, 'multiple_choice', '_____ employee is required to complete the annual review form.', '["Both","Each","All","Every"]', 'Each', 'each + 單數名詞，強調個別；every 也可用。'),
(60, 'multiple_choice', '_____ department will be assessed during the annual audit.', '["All","Both","Every","Each"]', 'Every', 'every + 單數名詞，強調全部的每一個。'),
(60, 'multiple_choice', '_____ staff members are invited to attend the town hall meeting.', '["Every","Both","All","Each"]', 'All', 'all + 複數名詞，全體。'),
(60, 'fill_blank', '_____ time she presents to the board, she receives excellent feedback.', NULL, 'Every', 'every time 固定搭配，表每次。'),
(60, 'multiple_choice', '_____ of the proposals was reviewed individually.', '["Both","Each","Every","All"]', 'Each', 'each of the + 複數名詞 + 單數動詞。'),
(60, 'multiple_choice', 'We need _____ team member to confirm their attendance.', '["all","both","every","each"]', 'every', 'every + 單數名詞，強調全部。'),
(60, 'multiple_choice', '_____ the information you need is in the report.', '["Both","All","Each","Every"]', 'All', 'all the information 全部資訊，不可數名詞。'),
(60, 'transform', 'We need to inform every person on the team. (Use: each member)', NULL, 'Each member of the team needs to be informed of the changes.', 'each + 單數名詞，強調個別通知。'),
(60, 'fill_blank', 'She takes notes at _____ team meeting.', NULL, 'every / each', 'every/each team meeting，表每次例會。'),
(60, 'multiple_choice', '_____ the applications were reviewed before the shortlist was made.', '["All","Each","Every","Both"]', 'All', 'all the applications 所有申請，複數。'),
(60, 'multiple_choice', '_____ country in the region will be affected by the new trade agreement.', '["Every","Each","Both","All"]', 'Every', 'every country，強調全部每一個國家。'),
(60, 'multiple_choice', 'She spoke to _____ member of the team individually.', '["all","both","each","every"]', 'each', 'each 強調一個一個地個別交談。'),
(60, 'fill_blank', '_____ document in the submission must be signed.', NULL, 'Each / Every', 'each/every + 單數名詞，強調每份文件。'),
(60, 'multiple_choice', 'Not _____ employee was aware of the policy change.', '["both","all","each","every"]', 'every', 'not every 表示不是所有人都知道。'),
(60, 'multiple_choice', '_____ of our offices follow the same security protocols.', '["Each","Both","All","Every"]', 'All', 'all of our offices 複數主語 + 複數動詞。'),
(60, 'transform', 'Both team A and team B submitted their reports. (Use: all)', NULL, 'All teams submitted their reports by the deadline.', 'all teams 表全部的隊伍。'),
(60, 'fill_blank', '_____ item on the agenda was discussed in detail.', NULL, 'Each / Every', 'each/every item 單數，強調每個項目。'),
(60, 'multiple_choice', 'We need to renew _____ subscription before the year ends.', '["all","each","every","both"]', 'every', 'every subscription 每個訂閱（強調整體）。'),
(60, 'multiple_choice', 'She met _____ client personally to understand their needs.', '["both","all","each","every"]', 'every', 'every client 強調沒有一個例外；each 也可用。'),
(60, 'multiple_choice', '_____ of the managers attended the leadership training.', '["All","Every","Each","Both"]', 'All', 'all of the managers 全部的管理者。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(61, 'multiple_choice', 'He prepared the entire presentation _____ without any help.', '["himself","by him","his own","himself only"]', 'himself', 'himself 表強調（他親自）。'),
(61, 'multiple_choice', 'Please help _____ to the refreshments after the meeting.', '["you","yours","yourself","yourselves"]', 'yourself', 'help yourself 請自取，禮貌用語。'),
(61, 'multiple_choice', 'The CEO _____ attended the small team briefing.', '["she","herself","her","hers"]', 'herself', 'herself 強調 CEO 親自出席。'),
(61, 'fill_blank', 'The system updated _____ overnight without any manual input.', NULL, 'itself', 'itself 反身代名詞，系統自動更新。'),
(61, 'multiple_choice', 'We _____ identified the problem before the client noticed.', '["ourself","us","ours","ourselves"]', 'ourselves', 'ourselves 主語 we 的反身代名詞。'),
(61, 'multiple_choice', 'You should introduce _____ to the new team members.', '["yourself","yourselves","yours","you"]', 'yourself', 'yourself 反身，主語 you 單數。'),
(61, 'multiple_choice', 'She hurt _____ trying to carry all the boxes alone.', '["she","herself","her","hers"]', 'herself', 'herself 反身動作。'),
(61, 'multiple_choice', 'They _____ admitted that the project had failed.', '["themselves","theirs","theirselves","them"]', 'themselves', 'themselves 強調他們主動承認。'),
(61, 'transform', 'The team did the work without any outside help. (Use: by themselves)', NULL, 'The team completed the project entirely by themselves.', 'by themselves 表靠自己完成。'),
(61, 'multiple_choice', 'The new software installs _____ automatically.', '["itself","it","its","alone"]', 'itself', 'itself 反身代名詞，系統安裝自身。'),
(61, 'fill_blank', 'He signed the contract _____ to show his commitment.', NULL, 'himself', 'himself 強調本人親自簽署。'),
(61, 'multiple_choice', 'We need to ask _____ whether this strategy is sustainable.', '["ourself","ourselves","ours","us"]', 'ourselves', 'ourselves 反身，主語 we。'),
(61, 'multiple_choice', 'She blamed _____ for the miscommunication.', '["herself","hers","she","her"]', 'herself', 'herself 反身動作（責怪自己）。'),
(61, 'multiple_choice', 'The team should be proud of _____ for achieving this milestone.', '["them","themselves","theirselves","theirs"]', 'themselves', 'themselves 反身，主語 they。'),
(61, 'multiple_choice', 'Please make _____ at home during your visit to our office.', '["yours","you","yourselves","yourself"]', 'yourself', 'make yourself at home 固定用語。'),
(61, 'transform', 'The manager completed the audit without assistance. (Use: himself)', NULL, 'The manager completed the audit himself.', 'himself 強調親自完成。'),
(61, 'fill_blank', 'I taught _____ to use the new CRM system.', NULL, 'myself', 'myself 反身，主語 I，自學。'),
(61, 'multiple_choice', 'They _____ did all the coding without hiring external developers.', '["theirs","themselves","theirselves","them"]', 'themselves', 'themselves 強調自己完成。'),
(61, 'multiple_choice', 'The company prides _____ on its customer service.', '["its","alone","itself","it"]', 'itself', 'pride itself on 固定搭配，反身代名詞 itself。'),
(61, 'multiple_choice', 'Please address any concerns _____ rather than escalating immediately.', '["yourself","yours","you","yourselves"]', 'yourself', 'yourself 反身，請自行處理。'),
(62, 'multiple_choice', '_____ needs to take responsibility for this error.', '["Anyone","No one","Everybody","Someone"]', 'Someone', 'someone 在肯定句中表某人。'),
(62, 'multiple_choice', 'Has _____ reviewed the final draft yet?', '["someone","no one","anyone","everybody"]', 'anyone', 'anyone 在疑問句中。'),
(62, 'multiple_choice', '_____ informed the client about the delay — that was a big mistake.', '["Someone","Anyone","Everybody","No one"]', 'No one', 'no one 表沒有人，語氣強調失誤。'),
(62, 'fill_blank', 'Is there _____ who can help me with this spreadsheet?', NULL, 'anyone', '疑問句中用 anyone。'),
(62, 'multiple_choice', 'There''s _____ at the door asking for the manager.', '["nobody","no one","anyone","someone"]', 'someone', 'someone 在肯定句中。'),
(62, 'multiple_choice', '_____ in the team knows the answer — we need expert help.', '["Everyone","Nobody","Somebody","Anybody"]', 'Nobody', 'nobody 否定，無人知曉。'),
(62, 'multiple_choice', 'Did _____ attend the meeting on my behalf?', '["no one","someone","anyone","nobody"]', 'anyone', '疑問句中 anyone。'),
(62, 'fill_blank', 'We didn''t hear _____ from the client after we sent the proposal.', NULL, 'anything', 'anything 否定句中表沒有任何消息。'),
(62, 'multiple_choice', '_____ told me that the meeting was cancelled — I went there for nothing.', '["Anybody","Nobody","Everyone","Somebody"]', 'Nobody', 'nobody told me 沒有人告訴我。'),
(62, 'multiple_choice', 'Can _____ explain why the report is missing data?', '["someone","anyone","nobody","no one"]', 'anyone', '疑問句中 anyone。'),
(62, 'multiple_choice', '_____ from the finance team confirmed the budget allocation.', '["Nobody","Someone","Anyone","No one"]', 'Someone', 'someone 在肯定句，表有某人確認了。'),
(62, 'fill_blank', 'Is there _____ wrong with the system? It keeps crashing.', NULL, 'anything', 'anything wrong 疑問句詢問是否有問題。'),
(62, 'multiple_choice', 'We need _____ who is fluent in Mandarin for this client.', '["nobody","someone","no one","anyone"]', 'someone', 'someone 特定需求，肯定句。'),
(62, 'multiple_choice', '_____ objected to the new policy at the meeting.', '["Someone","No one","Anyone","Everybody"]', 'No one', 'no one objected 沒有人反對。'),
(62, 'transform', 'I can''t find the document anywhere. (Use: nowhere)', NULL, 'The document is nowhere to be found.', 'nowhere 表哪裡都找不到。'),
(62, 'fill_blank', 'Has _____ sent the meeting invitation to the client?', NULL, 'anyone', '疑問句中 anyone。'),
(62, 'multiple_choice', 'There''s _____ important I need to discuss with you.', '["something","nothing","everything","anything"]', 'something', 'something 肯定句中表有某件重要的事。'),
(62, 'multiple_choice', 'She didn''t tell _____ about the confidential deal.', '["anyone","nobody","someone","no one"]', 'anyone', 'didn''t tell anyone 否定句中 anyone。'),
(62, 'fill_blank', '_____ knows why the project was cancelled so abruptly.', NULL, 'Nobody / No one', 'nobody/no one 表沒有人知道原因。'),
(62, 'multiple_choice', 'He looked _____ for the missing file but couldn''t find it.', '["everywhere","anywhere","somewhere","nowhere"]', 'everywhere', 'everywhere 表到處都找了。'),
(63, 'multiple_choice', 'Can you give me some _____ on this matter?', '["an advice","advise","advices","advice"]', 'advice', 'advice 不可數，不加複數；some advice。'),
(63, 'multiple_choice', 'We need more _____ before making a decision.', '["information","an information","informing","informations"]', 'information', 'information 不可數，no plural；some information。'),
(63, 'multiple_choice', 'All the _____ in the office will be replaced next month.', '["furnitures","furnishings","a furniture","furniture"]', 'furniture', 'furniture 不可數；所有傢俱 all the furniture。'),
(63, 'fill_blank', 'She gave us some useful _____ (feedback) on our presentation.', NULL, 'feedback', 'feedback 不可數，not feedbacks。'),
(63, 'multiple_choice', 'We received _____ from the committee.', '["no newses","no news","any newses","a news"]', 'no news', 'news 不可數，no news（沒有消息）。'),
(63, 'multiple_choice', 'The _____ she provided saved us hours of research.', '["datum","a data","data","datas"]', 'data', 'data 通常作複數（the data are/is），不說 datas。'),
(63, 'multiple_choice', 'We made significant _____ on the project this week.', '["progressing","a progress","progress","progresses"]', 'progress', 'progress 不可數，significant progress。'),
(63, 'fill_blank', 'The company invested heavily in _____ (research).', NULL, 'research', 'research 不可數，not researches。'),
(63, 'multiple_choice', 'Could you share _____ about the client''s background?', '["some knowledges","a knowledge","some knowledge","any knowledges"]', 'some knowledge', 'knowledge 不可數，some knowledge。'),
(63, 'multiple_choice', 'We need _____ manager to oversee this project.', '["an","some","a","any"]', 'a', 'manager 可數，a manager。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(63, 'multiple_choice', 'She has _____ experience in supply chain management.', '["a great deal of","several","many","a few"]', 'a great deal of', 'experience（經驗）不可數，a great deal of experience。'),
(63, 'fill_blank', 'We received _____ important _____ (news) from our Tokyo office today.', NULL, 'some / news', 'news 不可數，some important news。'),
(63, 'multiple_choice', 'The _____ is very complex in this legal document.', '["languaging","language","a language","languages"]', 'language', 'language（此處指語言表達）不可數泛稱。'),
(63, 'multiple_choice', 'They need _____ new _____ to complete the system.', '["any / equipments","a / equipment","some / equipments","some / equipment"]', 'some / equipment', 'equipment 不可數，some equipment。'),
(63, 'multiple_choice', 'We don''t have _____ time to review each document individually.', '["a few","several","many","enough"]', 'enough', 'enough + 不可數名詞 time；many/a few 只用於可數名詞。'),
(63, 'transform', 'She gave me several pieces of advice. (Correct the error if any)', NULL, 'She gave me some valuable advice on the project.', 'advice 不可數，不說 pieces of advice（雖然技術上可以，but several advice 是錯的）。'),
(63, 'fill_blank', 'We need to collect more _____ (information) before deciding.', NULL, 'information', 'information 不可數，not informations。'),
(63, 'multiple_choice', 'All the _____ has been carefully reviewed by the legal team.', '["document","a documentation","documentations","documentation"]', 'documentation', 'documentation 不可數，all the documentation。'),
(63, 'multiple_choice', 'We have received _____ applications for the position.', '["many","much","a lot","several of"]', 'many', 'applications 可數複數，many applications。'),
(63, 'multiple_choice', 'She has _____ knowledge of the local market.', '["several","extensive","a few","many"]', 'extensive', 'extensive knowledge，knowledge 不可數，不用 many。'),
(64, 'multiple_choice', 'We need to conduct a thorough _____ before launching.', '["market research","markets research","researching market","researches of market"]', 'market research', 'market research 複合名詞，market 作前置修飾語。'),
(64, 'multiple_choice', 'Please send this to the _____ department.', '["customer''s service","customers service","service customer","customer service"]', 'customer service', 'customer service 複合名詞。'),
(64, 'multiple_choice', 'We have a _____ on Thursday to discuss the new strategy.', '["boards meeting","meeting of board","board meeting","boardly meeting"]', 'board meeting', 'board meeting 複合名詞。'),
(64, 'fill_blank', 'The _____ (cost/cutting) measures have been very effective.', NULL, 'cost-cutting', 'cost-cutting 連字號複合形容詞。'),
(64, 'multiple_choice', 'She is the _____ of the company.', '["decision maker","decision-maker","decisions-maker","maker of decision"]', 'decision-maker', 'decision-maker 連字號複合名詞。'),
(64, 'multiple_choice', 'Please review the _____ before signing.', '["terms contract","terms of contract","contract terms","contractual of terms"]', 'contract terms', 'contract terms 複合名詞。'),
(64, 'multiple_choice', 'The _____ was delayed due to supply issues.', '["launching of product","launch of product","product launch","products launch"]', 'product launch', 'product launch 複合名詞。'),
(64, 'fill_blank', 'She is in charge of _____ (staff/training).', NULL, 'staff training', 'staff training 複合名詞。'),
(64, 'multiple_choice', 'We need a _____ for the conference room.', '["whiteboard","white board","boarding white","board of white"]', 'whiteboard', 'whiteboard 合一詞的複合名詞。'),
(64, 'multiple_choice', 'The _____ will be distributed to all employees.', '["staff handbook","handbook of staff","staffs handbook","handbooking staff"]', 'staff handbook', 'staff handbook 複合名詞。'),
(64, 'multiple_choice', 'He''s responsible for _____ at our company.', '["controlling of quality","qualities control","control of qualities","quality control"]', 'quality control', 'quality control 複合名詞。'),
(64, 'fill_blank', 'The _____ (data/base) needs to be updated regularly.', NULL, 'database', 'database 合一詞的複合名詞。'),
(64, 'multiple_choice', 'Our _____ team is expanding to meet growing demand.', '["selling force","sales force","sales'' force","force of sales"]', 'sales force', 'sales force 複合名詞。'),
(64, 'multiple_choice', 'They attended a _____ on digital marketing.', '["shop of work","working shop","work shop","workshop"]', 'workshop', 'workshop 合一詞複合名詞。'),
(64, 'multiple_choice', 'Please prepare a _____ for tomorrow''s meeting.', '["presentation of PowerPoint","PowerPointing presentation","presented PowerPoint","PowerPoint presentation"]', 'PowerPoint presentation', 'PowerPoint presentation 複合名詞。'),
(64, 'transform', 'The deadline for the project is next Friday. (Use: project deadline)', NULL, 'The project deadline has been set for next Friday.', 'project deadline 複合名詞。'),
(64, 'fill_blank', 'We need to strengthen our _____ (supply/chain) management.', NULL, 'supply chain', 'supply chain 複合名詞，兩個詞分開。'),
(64, 'multiple_choice', 'She works in _____ management.', '["human resources","humans resource","resource of humans","human''s resources"]', 'human resources', 'human resources management 複合名詞。'),
(64, 'multiple_choice', 'The company issues a monthly _____ to all stakeholders.', '["news letter","letter of news","newsletter","news-letter"]', 'newsletter', 'newsletter 合一詞複合名詞。'),
(64, 'multiple_choice', 'We scheduled a _____ to review the annual figures.', '["reviewing of budget","budget review","review of budgeting","budgets review"]', 'budget review', 'budget review 複合名詞。'),
(65, 'multiple_choice', 'She works in a _____ conference room.', '["modern, small","small, modern","small modern''s","modern small''s"]', 'small, modern', '尺寸（small）在意見/描述（modern）前。'),
(65, 'multiple_choice', 'They bought _____ office chairs.', '["ten comfortable new","comfortable new ten","new comfortable ten","ten new comfortable"]', 'ten comfortable new', '數量（ten）→意見（comfortable）→年齡（new）。'),
(65, 'multiple_choice', 'He is a _____ manager.', '["young talent","talent, young","young, talented","talented, young"]', 'young, talented', '年齡（young）→意見（talented）通常意見前，但 young talented 在此更自然。'),
(65, 'fill_blank', 'We need a _____ (large/Chinese/round) conference table.', NULL, 'large round Chinese', '尺寸→形狀→來源。'),
(65, 'multiple_choice', 'She received _____ promotion.', '["an well-deserved","a well-deserved","a deserved-well","a well-deserving"]', 'a well-deserved', 'a well-deserved 意見性形容詞。'),
(65, 'multiple_choice', 'They installed _____ doors in the new office.', '["beautiful sliding glass","sliding beautiful glass","glass beautiful sliding","beautiful glass sliding"]', 'beautiful glass sliding', '意見（beautiful）→材質（glass）→用途（sliding）。'),
(65, 'multiple_choice', 'It was _____ decision.', '["a difficult business","a business''s difficult","difficult''s business","a business difficult"]', 'a difficult business', '意見（difficult）→目的（business）。'),
(65, 'fill_blank', 'He drives a _____ (small/new/red/Japanese) car.', NULL, 'small new red Japanese', '尺寸→年齡→顏色→來源。'),
(65, 'multiple_choice', 'She is a _____ professional.', '["experienced highly","high experienced","highly experienced","experiencedly high"]', 'highly experienced', '副詞（highly）修飾形容詞（experienced）。'),
(65, 'multiple_choice', 'We ordered _____ sofas for the reception area.', '["two leather large","large two leather","leather two large","two large leather"]', 'two large leather', '數量（two）→尺寸（large）→材質（leather）。'),
(65, 'multiple_choice', 'He is an _____ businessman.', '["ambitious young","ambitious youngly","ambition young","young ambitious"]', 'ambitious young', '意見（ambitious）→年齡（young）。'),
(65, 'fill_blank', 'We use a _____ (modern/digital/small) filing system.', NULL, 'small modern digital', '尺寸→意見→目的（數位）。'),
(65, 'multiple_choice', 'She presented a _____ plan.', '["three-year detailed","detail three-year","three detailed-year","detailed three-year"]', 'detailed three-year', '意見（detailed）→描述（three-year）。'),
(65, 'multiple_choice', 'They work in a _____ building.', '["grey, large, modern","large, grey, modern","modern, grey, large","modern, large, grey"]', 'large, grey, modern', '尺寸（large）→顏色（grey）→年齡/描述（modern）。'),
(65, 'multiple_choice', 'It''s a _____ issue.', '["seriously financial","serious financial","financial serious","finance serious"]', 'serious financial', '意見（serious）→目的（financial）。'),
(65, 'transform', 'The office has a new, small, Italian espresso machine. (Write in correct order)', NULL, 'The office has a new small Italian espresso machine.', '年齡（new）→尺寸（small）→來源（Italian）。'),
(65, 'fill_blank', 'We need a _____ (reliable/new/German) engineering partner.', NULL, 'reliable new German', '意見（reliable）→年齡（new）→來源（German）。'),
(65, 'multiple_choice', 'She wore a _____ jacket.', '["smart black business","smart business black","business smart black","black smart business"]', 'smart black business', '意見（smart）→顏色（black）→目的（business）。'),
(65, 'multiple_choice', 'He has _____ experience.', '["international considerable","considerable international","considerable internation","considerately international"]', 'considerable international', '意見（considerable）→來源/範疇（international）。'),
(65, 'multiple_choice', 'We installed _____ screens in the boardroom.', '["several flat large","several large flat","large several flat","flat large several"]', 'several large flat', '數量（several）→尺寸（large）→形狀（flat）。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(66, 'multiple_choice', 'The presentation was _____ — everyone was falling asleep.', '["bored","boring","boringly","bore"]', 'boring', 'boring 形容報告本身令人無聊。'),
(66, 'multiple_choice', 'She was _____ by the innovative features of the new software.', '["impressing","impressed","impress","impressingly"]', 'impressed', 'impressed 形容她的感受，-ed 形容詞。'),
(66, 'multiple_choice', 'The training session was _____ and highly effective.', '["engaging","engaged","engagement","engagingly"]', 'engaging', 'engaging 形容訓練課程令人投入，-ing 形容詞。'),
(66, 'fill_blank', 'He was _____ (confuse) by the conflicting reports from different departments.', NULL, 'confused', 'confused 形容他的感受（被搞糊塗了）。'),
(66, 'multiple_choice', 'The client seemed _____ with the proposed timeline.', '["satisfied","satisfying","satisfy","satisfiedly"]', 'satisfied', 'satisfied 形容客戶的感受，-ed 形容詞。'),
(66, 'multiple_choice', 'The merger news was _____ for the entire industry.', '["surprised","surprising","surprisingly","surprise"]', 'surprising', 'surprising 形容消息本身令人驚訝，-ing。'),
(66, 'multiple_choice', 'He was _____ about the prospect of leading the project.', '["exciting","excited","excitedly","excite"]', 'excited', 'excited 形容他的感受，-ed。'),
(66, 'transform', 'The quarterly data shocked the investors. (Use -ing or -ed adjective)', NULL, 'The quarterly data was shocking. The investors were shocked.', 'shocking 形容資料，shocked 形容投資者的感受。'),
(66, 'multiple_choice', 'The client was _____ by the delay and demanded an explanation.', '["frustratedly","frustrating","frustrate","frustrated"]', 'frustrated', 'frustrated 形容客戶的感受，-ed。'),
(66, 'fill_blank', 'The new system is very _____ (interest) to use.', NULL, 'interesting', 'interesting 形容系統本身，-ing。'),
(66, 'multiple_choice', 'She gave a very _____ speech at the award ceremony.', '["inspiring","inspired","inspire","inspiredly"]', 'inspiring', 'inspiring 形容演講令人振奮，-ing。'),
(66, 'multiple_choice', 'He is _____ with his current workload.', '["overwhelming","overwhelmedly","overwhelm","overwhelmed"]', 'overwhelmed', 'overwhelmed 形容他的感受，-ed。'),
(66, 'multiple_choice', 'The results were _____ — far better than expected.', '["encouraging","encouragedly","encourage","encouraged"]', 'encouraging', 'encouraging 形容結果令人鼓舞，-ing。'),
(66, 'fill_blank', 'They were _____ (embarrass) by the mistake in the public report.', NULL, 'embarrassed', 'embarrassed 形容他們的感受，-ed。'),
(66, 'multiple_choice', 'The proposal is quite _____ and needs revision.', '["confuse","confusingly","confusing","confused"]', 'confusing', 'confusing 形容提案令人困惑，-ing。'),
(66, 'multiple_choice', 'She was _____ to hear that she had been selected.', '["delightedly","delighting","delight","delighted"]', 'delighted', 'delighted 形容她的感受（非常高興），-ed。'),
(66, 'multiple_choice', 'The project status update was rather _____.', '["alarm","alarming","alarmingly","alarmed"]', 'alarming', 'alarming 形容更新內容令人擔憂，-ing。'),
(66, 'transform', 'The technical report was hard to follow. Many people felt confused. (Use adjectives)', NULL, 'The technical report was confusing, and many readers were confused.', 'confusing（報告）vs confused（讀者感受）。'),
(66, 'fill_blank', 'The team felt _____ (motivate) by the CEO''s speech.', NULL, 'motivated', 'motivated 形容團隊的感受，-ed。'),
(66, 'multiple_choice', 'His presentation was extremely _____ and well-structured.', '["information","informative","informed","informingly"]', 'informative', 'informative 形容報告本身資訊豐富，-ive 形容詞。'),
(67, 'multiple_choice', 'She _____ sends a follow-up email after every client meeting.', '["seldom","never","always","is always"]', 'always', 'always 頻率最高，置主要動詞前。'),
(67, 'multiple_choice', 'We _____ hold team-building events twice a year.', '["rarely","always","usually","never"]', 'usually', 'usually 表一般情況下（通常），置主要動詞前。'),
(67, 'multiple_choice', 'He is _____ late — it''s a known problem.', '["always","usually","rarely","often"]', 'often', 'often 置 be 動詞後。'),
(67, 'fill_blank', 'Our team _____ (occasional) works overtime to meet deadlines.', NULL, 'occasionally', 'occasionally 頻率副詞置主要動詞前。'),
(67, 'multiple_choice', 'She _____ forgets important deadlines.', '["always","often","usually","rarely"]', 'rarely', 'rarely 幾乎不，置主要動詞前。'),
(67, 'multiple_choice', 'The CEO _____ attends daily briefings — her schedule is too busy.', '["rarely","always","often","usually"]', 'rarely', 'rarely attends 幾乎不出席。'),
(67, 'multiple_choice', 'We _____ receive complaints about our premium service.', '["always","usually","often","seldom"]', 'seldom', 'seldom 幾乎不（書面），置主要動詞前。'),
(67, 'transform', 'She doesn''t often work on weekends. (Use: rarely)', NULL, 'She rarely works on weekends, even during busy periods.', 'rarely 頻率低，置動詞前。'),
(67, 'multiple_choice', 'The quarterly report is _____ submitted on time.', '["always","never","seldom","rarely"]', 'always', 'always 表每次都準時，置 be 後。'),
(67, 'fill_blank', 'He _____ (frequent) checks the project dashboard.', NULL, 'frequently', 'frequently 頻率副詞。'),
(67, 'multiple_choice', 'We _____ find errors in automatically generated reports.', '["seldom","never","sometimes","always"]', 'sometimes', 'sometimes 有時（中等頻率）。'),
(67, 'multiple_choice', 'The manager _____ praises good work publicly.', '["regularly","never","rarely","seldom"]', 'regularly', 'regularly 定期，置主要動詞前。'),
(67, 'multiple_choice', 'Clients _____ request revisions to the proposal.', '["never","rarely","seldom","often"]', 'often', 'often 表常常請求修改。'),
(67, 'transform', 'It''s not common for her to miss meetings. (Use: rarely)', NULL, 'She rarely misses meetings without giving prior notice.', 'rarely 幾乎不，置主要動詞前。'),
(67, 'fill_blank', 'He _____ (never) submits his reports without proofreading them.', NULL, 'never', 'never 絕對不，置主要動詞前。'),
(67, 'multiple_choice', 'She is _____ the first person to arrive in the office.', '["never","always","seldom","usually"]', 'usually', 'usually the first 通常最早。'),
(67, 'multiple_choice', 'We _____ miss a delivery deadline.', '["always","never","often","usually"]', 'never', 'never miss 絕不錯過。'),
(67, 'multiple_choice', 'The board _____ meets once a month.', '["rarely","seldom","typically","never"]', 'typically', 'typically 通常（典型地），頻率副詞。'),
(67, 'fill_blank', 'She _____ (always) double-checks her calculations before presenting.', NULL, 'always', 'always 置主要動詞前。'),
(67, 'multiple_choice', 'Performance reviews are _____ conducted annually.', '["never","normally","seldom","rarely"]', 'normally', 'normally conducted 通常每年進行。'),
(68, 'multiple_choice', 'The new policy is _____ important for all employees to understand.', '["extremer","most extremely","extreme","extremely"]', 'extremely', 'extremely + 形容詞，程度副詞。'),
(68, 'multiple_choice', 'The presentation was _____ persuasive, but not entirely convincing.', '["very much","much","quite","mostly"]', 'quite', 'quite 表相當（有些限制性）。'),
(68, 'multiple_choice', 'She was _____ aware of the risks before signing the contract.', '["fully","with fully","full","fulling"]', 'fully', 'fully aware 完全知曉，程度副詞 fully。'),
(68, 'fill_blank', 'The results are _____ (slight) better than last quarter.', NULL, 'slightly', 'slightly + 比較級，稍微好一點。'),
(68, 'multiple_choice', 'He is _____ experienced in international negotiations.', '["a lot","high","highly","very much"]', 'highly', 'highly experienced 非常有經驗（highly 修飾形容詞）。'),
(68, 'multiple_choice', 'The project is _____ complete — only the final report is missing.', '["mostly","almost","nearly complete","quite"]', 'almost', 'almost complete 幾乎完成。'),
(68, 'multiple_choice', 'The client was _____ satisfied with the revised proposal.', '["entirely","entire","entiredly","with entirely"]', 'entirely', 'entirely satisfied 完全滿意。'),
(68, 'transform', 'She is not very confident about the outcome. (Use: somewhat)', NULL, 'She is somewhat uncertain about the final outcome.', 'somewhat 表有些程度的不確定。'),
(68, 'multiple_choice', 'The budget is _____ tight this quarter.', '["pretty much","quite much","fairly so","rather"]', 'rather', 'rather tight 相當緊（商業正式用語）。'),
(68, 'fill_blank', 'This task is _____ (complete) straightforward and shouldn''t take long.', NULL, 'completely / quite', 'completely 或 quite straightforward。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(68, 'multiple_choice', 'He is _____ qualified for this position — exceeds all requirements.', '["more than","much","quite","enough"]', 'more than', 'more than qualified 超過所需資格。'),
(68, 'multiple_choice', 'The market has _____ changed in the past decade.', '["significantly","much significantly","a significant","significant"]', 'significantly', 'significantly 副詞修飾動詞 changed。'),
(68, 'multiple_choice', 'The proposal is _____ ready — just needs final approval.', '["mostly","quite","almost","nearly much"]', 'almost', 'almost ready 快要好了。'),
(68, 'transform', 'The improvement was not large, just moderate. (Use: slightly)', NULL, 'The improvement was slightly larger than in the previous period.', 'slightly + 比較級表輕微差距。'),
(68, 'fill_blank', 'She is _____ (absolute) committed to meeting this deadline.', NULL, 'absolutely', 'absolutely committed 完全投入。'),
(68, 'multiple_choice', 'The team was _____ overwhelmed by the scope of the project.', '["at initial","initialy","initially","initial"]', 'initially', 'initially overwhelmed 最初感到不堪負荷。'),
(68, 'multiple_choice', 'Results are _____ dependent on market conditions.', '["largely","large","larging","much largely"]', 'largely', 'largely dependent 很大程度上取決於。'),
(68, 'multiple_choice', 'This approach is _____ different from what we tried before.', '["a fundamental","fundamental","fundamentally","with fundamental"]', 'fundamentally', 'fundamentally different 根本上不同。'),
(68, 'fill_blank', 'The contract terms are _____ (fair) reasonable and we recommend signing.', NULL, 'fairly', 'fairly reasonable 相當合理。'),
(68, 'multiple_choice', 'She is _____ capable of handling this independently.', '["much perfectly","perfecting","perfect","perfectly"]', 'perfectly', 'perfectly capable 完全有能力。'),
(69, 'multiple_choice', 'The project was delayed; _____, we met the overall goal.', '["meanwhile","moreover","therefore","however"]', 'however', 'however 表轉折讓步。'),
(69, 'multiple_choice', 'Sales increased last quarter; _____, we need to maintain the momentum.', '["meanwhile","moreover","however","therefore"]', 'therefore', 'therefore 表因此，結果。'),
(69, 'multiple_choice', 'The new system is faster; _____, it is much easier to use.', '["however","moreover","meanwhile","therefore"]', 'moreover', 'moreover 表此外、而且（遞進）。'),
(69, 'fill_blank', 'We have reduced costs; _____, we have improved quality.', NULL, 'furthermore / moreover', 'furthermore 表進一步，遞進。'),
(69, 'multiple_choice', 'The budget was cut; _____, the team delivered excellent results.', '["meanwhile","moreover","therefore","nevertheless"]', 'nevertheless', 'nevertheless 表儘管如此（讓步）。'),
(69, 'multiple_choice', 'Sales dropped in Q1; _____, the company remained profitable.', '["therefore","moreover","however","meanwhile"]', 'however', 'however 表轉折。'),
(69, 'multiple_choice', 'The report was incomplete; _____, the meeting was postponed.', '["moreover","however","consequently","meanwhile"]', 'consequently', 'consequently 表因此，結果。'),
(69, 'transform', 'We finished the analysis. At the same time, the client submitted new data. (Use: meanwhile)', NULL, 'We finished the analysis; meanwhile, the client submitted additional data.', 'meanwhile 表同時發生。'),
(69, 'multiple_choice', 'The strategy was risky; _____, it paid off in the long run.', '["meanwhile","moreover","therefore","nevertheless"]', 'nevertheless', 'nevertheless 表儘管如此，結果還是成功。'),
(69, 'fill_blank', 'We exceeded our targets; _____, the board has approved additional funding.', NULL, 'consequently / therefore', 'consequently/therefore 表因此獲批預算。'),
(69, 'multiple_choice', 'The market is volatile; _____, we are reviewing our investment strategy.', '["meanwhile","moreover","however","therefore"]', 'therefore', 'therefore 表因此要重新評估。'),
(69, 'multiple_choice', 'She is skilled in data analysis; _____, she is an excellent communicator.', '["however","therefore","meanwhile","moreover"]', 'moreover', 'moreover 遞進，不只有分析能力還有溝通能力。'),
(69, 'multiple_choice', 'The results were disappointing; _____, we are committed to improvement.', '["therefore","moreover","however","meanwhile"]', 'however', 'however 轉折，表仍致力於改進。'),
(69, 'transform', 'The price increased. As a result, demand fell. (Use: consequently)', NULL, 'The price increased; consequently, demand fell significantly.', 'consequently 表結果。'),
(69, 'fill_blank', 'The negotiations failed; _____, the company sought alternative partners.', NULL, 'consequently / therefore', '因此尋求替代夥伴。'),
(69, 'multiple_choice', 'The first proposal was rejected; _____, we submitted a revised version.', '["meanwhile","consequently","moreover","however"]', 'consequently', 'consequently 表因此採取後續行動。'),
(69, 'multiple_choice', 'The new policy saves time; _____, it reduces errors.', '["furthermore","therefore","meanwhile","however"]', 'furthermore', 'furthermore 表此外（遞進優點）。'),
(69, 'multiple_choice', 'We cut costs; _____, we maintained service quality.', '["meanwhile","nevertheless","moreover","therefore"]', 'nevertheless', 'nevertheless 表儘管削減成本，服務品質仍維持。'),
(69, 'fill_blank', 'The report was submitted on time; _____, the content was incomplete.', NULL, 'however', 'however 表轉折（準時但內容不完整）。'),
(69, 'multiple_choice', 'She worked long hours; _____, she took regular breaks.', '["moreover","meanwhile","nevertheless","therefore"]', 'nevertheless', 'nevertheless 表儘管如此仍有休息。'),
(70, 'multiple_choice', '_____ is the communication breakdown that caused the project delay.', '["That","What","It","This"]', 'It', 'It is...that 分裂句固定結構。'),
(70, 'multiple_choice', 'It was _____ who first proposed the new strategy.', '["which marketing director","the marketing director","marketing director that","what marketing director"]', 'the marketing director', 'It was + 強調成分 + who（指人）。'),
(70, 'multiple_choice', 'It is _____ that we need to focus on first.', '["the retention customer","which customer retention","customer retention","what customer retention"]', 'customer retention', 'It is...that 強調受語。'),
(70, 'fill_blank', '_____ (It) is the timeline, not the budget, _____ (that) concerns the board most.', NULL, 'It / that', 'It is...that 強調主語中的特定成分。'),
(70, 'multiple_choice', 'It was _____ that the company experienced its biggest growth.', '["on 2022","at 2022","in 2022","2022"]', 'in 2022', 'It was + 時間 + that 強調時間。'),
(70, 'multiple_choice', 'It is _____ that sets us apart from our competitors.', '["what our quality","the quality our","our commitment to quality","which quality"]', 'our commitment to quality', 'It is...that 強調核心競爭優勢。'),
(70, 'multiple_choice', 'It was the sales team _____ secured the deal.', '["that","which","whom","who"]', 'that', 'It was + 人 + that/who。'),
(70, 'transform', 'The quality of our service concerns clients most. (Use cleft sentence)', NULL, 'It is the quality of our service that clients appreciate most.', 'It is...that 分裂句強調主語。'),
(70, 'multiple_choice', 'It was _____ that the system crashed.', '["in during audit","while the audit","at audit","during the audit"]', 'during the audit', 'It was + 時間狀語 + that 強調時間。'),
(70, 'fill_blank', 'It _____ (be) the CEO''s vision _____ (drive) the company''s transformation.', NULL, 'was / that', 'It was...that 強調 CEO 的願景。'),
(70, 'multiple_choice', 'It is _____ that we must improve immediately.', '["what response time","the responding time","which response","our response time"]', 'our response time', 'It is...that 強調需改進的方面。'),
(70, 'multiple_choice', 'It was _____ that led to the breakthrough.', '["which team","the team''s collaboration","what collaboration","the collaborate team"]', 'the team''s collaboration', 'It was...that 強調成功原因。'),
(70, 'multiple_choice', 'It is not the price but the _____ that matters to clients.', '["qualify","quality","qualified","qualities"]', 'quality', 'It is...that 強調客戶真正在意的是品質。'),
(70, 'transform', 'The new technology changed how we work. (Use cleft sentence)', NULL, 'It is the new technology that has completely changed how we work.', 'It is...that 強調主語。'),
(70, 'fill_blank', 'It was _____ the product launch _____ attracted international media attention.', NULL, 'the success of / that', 'It was...that 強調事件。'),
(70, 'multiple_choice', 'It was _____ that she finally received the recognition she deserved.', '["on award ceremony","at the annual awards ceremony","in annual ceremony","at ceremony annual"]', 'at the annual awards ceremony', 'It was + 地點狀語 + that 強調地點。'),
(70, 'multiple_choice', '_____ is his attention to detail that makes him invaluable.', '["This","That","What","It"]', 'It', 'It is...that 分裂句。'),
(70, 'transform', 'The new regulation affected the whole industry. (Use cleft sentence)', NULL, 'It was the new regulation that affected the entire industry.', 'It was...that 強調主語。'),
(70, 'fill_blank', 'It _____ (be) the client''s feedback _____ (guide) the product revision.', NULL, 'was / that', 'It was...that 強調客戶意見的重要性。'),
(70, 'multiple_choice', 'It is _____ that has made this project so challenging.', '["the lacking resources","the lack of resources","what lack of resources","which resource lack"]', 'the lack of resources', 'It is...that 強調挑戰原因。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(71, 'multiple_choice', 'We _____ appreciate your patience during this process.', '["are","do","have","really"]', 'do', 'do appreciate 強調確實感謝，反駁不耐煩的印象。'),
(71, 'multiple_choice', 'She _____ submit the report — I saw her send it myself.', '["does","did","was","has"]', 'did', 'did submit 強調她確實提交了（過去式強調）。'),
(71, 'multiple_choice', 'He _____ try his best, even if the results weren''t perfect.', '["is","has","would","does"]', 'does', 'does try 強調他確實努力了（三單現在式）。'),
(71, 'fill_blank', 'I _____ (emphatic) believe this is the right decision for the company.', NULL, 'do', 'do believe 強調肯定信念。'),
(71, 'multiple_choice', 'We _____ value our relationship with your company.', '["do","would","have","are"]', 'do', 'do value 強調確實重視關係。'),
(71, 'multiple_choice', 'They _____ complete their projects on time, contrary to what you might think.', '["have","were","do","are"]', 'do', 'do complete 反駁認為他們不能按時完成的看法。'),
(71, 'multiple_choice', 'She _____ work extremely hard — she just doesn''t show it.', '["is","has","does","would"]', 'does', 'does work 強調她確實努力（三單）。'),
(71, 'transform', 'We really care about quality. (Use emphatic do)', NULL, 'We do care about maintaining the highest quality standards.', 'do care 強調確實在乎。'),
(71, 'fill_blank', 'The team _____ (emphatic) meet their deadlines, despite the challenges.', NULL, 'does', 'does meet 強調三單事實。'),
(71, 'multiple_choice', 'He _____ send the invoice, but it may have gone to your spam folder.', '["did","was","had","has"]', 'did', 'did send 強調他確實寄了（過去式）。'),
(71, 'multiple_choice', 'We _____ understand the urgency of this matter.', '["are","do","have","would"]', 'do', 'do understand 強調理解的語氣。'),
(71, 'multiple_choice', 'I _____ apologize for any inconvenience this may have caused.', '["do","have","am","would"]', 'do', 'do apologize 強調真誠道歉。'),
(71, 'transform', 'She took all the necessary precautions. (Use emphatic did)', NULL, 'She did take all the necessary precautions before the launch.', 'did take 強調過去確實採取措施。'),
(71, 'fill_blank', 'They _____ (emphatic) try to resolve the issue before escalating.', NULL, 'did', 'did try 強調過去確實嘗試解決。'),
(71, 'multiple_choice', 'The results _____ show improvement compared to last quarter.', '["have","are","would","do"]', 'do', 'do show 強調結果確實顯示改善。'),
(71, 'multiple_choice', 'We _____ meet our obligations under the contract.', '["are","have","do","would"]', 'do', 'do meet 強調確實履行合約義務。'),
(71, 'multiple_choice', 'She _____ receive the email, but she was too busy to respond.', '["has","did","was","had"]', 'did', 'did receive 強調她確實收到了（過去式）。'),
(71, 'transform', 'The new policy has had a positive impact. (Use emphatic does)', NULL, 'The new policy does have a positive impact on employee morale.', 'does have 強調政策確實有效。'),
(71, 'fill_blank', 'I _____ (emphatic) think we should reconsider our approach.', NULL, 'do', 'do think 強調肯定意見。'),
(71, 'multiple_choice', 'He _____ handle pressure very well — that''s why he leads the team.', '["would","is","does","has"]', 'does', 'does handle 強調能力（三單）。'),
(72, 'multiple_choice', 'We recommend that the board _____ the proposal immediately.', '["approves","approved","approve","approving"]', 'approve', 'recommend that + 原形動詞（虛擬語氣）。'),
(72, 'multiple_choice', 'The committee insists that all documents _____ in English.', '["were submitted","be submitted","should submitted","are submitted"]', 'be submitted', 'insist that + 原形被動（be + p.p.）。'),
(72, 'multiple_choice', 'It is essential that every employee _____ the training.', '["attends","is attending","attend","attended"]', 'attend', 'It is essential that + 原形動詞。'),
(72, 'fill_blank', 'The director suggested that the team _____ (reconsider) its approach.', NULL, 'reconsider', 'suggest that + 原形動詞，虛擬語氣。'),
(72, 'multiple_choice', 'The policy requires that all contractors _____ background checks.', '["are undergoing","undergo","underwent","undergoes"]', 'undergo', 'require that + 原形動詞。'),
(72, 'multiple_choice', 'It is important that the report _____ before Friday.', '["should completed","was completed","is completed","be completed"]', 'be completed', 'It is important that + 原形（被動）。'),
(72, 'multiple_choice', 'She demands that the error _____ immediately.', '["is corrected","was corrected","be corrected","should corrected"]', 'be corrected', 'demand that + 原形（被動）。'),
(72, 'transform', 'The management says all staff must attend. (Use: requires that)', NULL, 'Management requires that all staff attend the mandatory briefing.', 'require that + 原形動詞。'),
(72, 'fill_blank', 'The legal team recommended that the contract _____ (revise) before signing.', NULL, 'be revised', 'recommend that + 原形被動，虛擬語氣。'),
(72, 'multiple_choice', 'It is vital that the team _____ aware of the new regulations.', '["was","should be","be","is"]', 'be', 'It is vital that + be（原形）。'),
(72, 'multiple_choice', 'The auditor suggested that the company _____ its accounting practices.', '["reviewed","review","reviews","should review"]', 'review', 'suggest that + 原形動詞。'),
(72, 'multiple_choice', 'We insist that the supplier _____ a replacement within 48 hours.', '["is providing","provide","provides","should provide"]', 'provide', 'insist that + 原形動詞。'),
(72, 'transform', 'It is necessary for all managers to complete the form. (Use subjunctive)', NULL, 'It is necessary that all managers complete the certification form.', 'It is necessary that + 原形動詞。'),
(72, 'fill_blank', 'The board proposed that a new committee _____ (form) to investigate the issue.', NULL, 'be formed', 'propose that + 原形（被動），虛擬語氣。'),
(72, 'multiple_choice', 'It is crucial that the strategy _____ before the board meeting.', '["was finalized","is finalized","be finalized","should finalize"]', 'be finalized', 'It is crucial that + 原形（被動）。'),
(72, 'multiple_choice', 'The manager recommended that she _____ leadership training.', '["undergo","undergoes","underwent","is undergoing"]', 'undergo', 'recommend that + 原形，虛擬語氣。'),
(72, 'multiple_choice', 'The protocol demands that all visitors _____ security badges.', '["should wear","wear","wears","wore"]', 'wear', 'demand that + 原形動詞。'),
(72, 'transform', 'We advise that all stakeholders attend. (Use: suggest that)', NULL, 'We suggest that all stakeholders attend the annual general meeting.', 'suggest that + 原形動詞。'),
(72, 'fill_blank', 'It is imperative that the deadline _____ (meet).', NULL, 'be met', 'be met 原形被動，虛擬語氣。'),
(72, 'multiple_choice', 'She proposed that the salary review _____ every year.', '["be conducted","should conducted","is conducted","was conducted"]', 'be conducted', 'propose that + 原形被動。'),
(73, 'multiple_choice', 'I wish I _____ more time to review the proposal.', '["had","have","will have","would have"]', 'had', 'wish + 過去式表對現在的願望。'),
(73, 'multiple_choice', 'She wishes she _____ taken that promotion years ago.', '["had","will have","have","would have"]', 'had', 'wish + 過去完成式表對過去的遺憾。'),
(73, 'multiple_choice', 'If only we _____ better market research before the launch.', '["do","would do","did","had done"]', 'had done', 'if only + 過去完成式表過去的遺憾，語氣更強。'),
(73, 'fill_blank', 'He wishes the client _____ (respond) faster to our emails.', NULL, 'would respond', 'wish + would + 原形表對他人行為的期望。'),
(73, 'multiple_choice', 'We wish we _____ the contract before the price increase.', '["had signed","signed","have signed","would sign"]', 'had signed', 'wish + 過去完成式表後悔沒有及早簽約。'),
(73, 'multiple_choice', 'If only she _____ more confident during the presentation.', '["had been","were","was","would be"]', 'were', 'if only + were（正式英語）表對現在的願望。'),
(73, 'multiple_choice', 'I wish our team _____ more efficiently.', '["has worked","worked","would work","works"]', 'worked', 'wish + 過去式表對現在的願望。'),
(73, 'transform', 'I regret that we did not hire more staff. (Use: If only)', NULL, 'If only we had hired more staff, we could have met the demand.', 'if only + 過去完成式表過去遺憾。'),
(73, 'fill_blank', 'He wishes the new system _____ (work) as well as the old one.', NULL, 'worked', 'wish + 過去式表對現在的願望。'),
(73, 'multiple_choice', 'If only I _____ about the deal before it fell through.', '["would know","have known","had known","knew"]', 'had known', 'if only + 過去完成式表遺憾。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(73, 'multiple_choice', 'She wishes she _____ have a better work-life balance.', '["can","would","should","could"]', 'could', 'wish + could 表希望能夠（可能性的願望）。'),
(73, 'multiple_choice', 'We wish the client _____ give us more detailed feedback.', '["should","would","could","will"]', 'would', 'wish + would 表期望他人行為改變。'),
(73, 'transform', 'We regret that we lost that account. (Use: We wish we hadn''t)', NULL, 'We wish we hadn''t lost that valuable account.', 'wish + 過去完成否定表遺憾。'),
(73, 'fill_blank', 'If only the budget _____ (be) larger, we could have achieved more.', NULL, 'had been', 'if only + 過去完成式表過去遺憾。'),
(73, 'multiple_choice', 'He wishes he _____ asked for more details before signing.', '["have","had","would have","will have"]', 'had', 'wish + 過去完成式表遺憾。'),
(73, 'multiple_choice', 'If only we _____ the opportunity sooner.', '["recognized","have recognized","would recognize","had recognized"]', 'had recognized', 'if only + 過去完成式。'),
(73, 'multiple_choice', 'She wishes her presentation _____ gone better.', '["had","have","would have","will have"]', 'had', 'wish + 過去完成式表遺憾。'),
(73, 'transform', 'I regret that I didn''t network more at the conference. (Use: I wish I had)', NULL, 'I wish I had networked more at the conference.', 'wish + 過去完成式表遺憾。'),
(73, 'fill_blank', 'If only the team _____ (follow) the original plan, we would be on track.', NULL, 'had followed', 'if only + 過去完成式表後悔。'),
(73, 'multiple_choice', 'We wish the supplier _____ more transparent about delivery times.', '["is","were","was","would be"]', 'were', 'wish + were（過去式）表對現在狀況的願望。'),
(74, 'multiple_choice', '_____ the contract carefully, she noticed a significant error.', '["Read","Having read","Reading","To read"]', 'Reading', 'Reading 現在分詞子句表示同時進行的動作。'),
(74, 'multiple_choice', '_____ in the industry for ten years, she has built an impressive network.', '["To work","Having worked","Worked","Working"]', 'Having worked', 'Having worked = 完成分詞子句，表在主句動作前已完成。'),
(74, 'multiple_choice', '_____ a cost-effective solution, the team adopted the new software.', '["Sought","Having sought","To seek","Seeking"]', 'Seeking', 'Seeking a solution 分詞子句表目的或同時進行。'),
(74, 'fill_blank', '_____ (walk) into the meeting room, he noticed the client looked concerned.', NULL, 'Walking', 'Walking into 現在分詞子句。'),
(74, 'multiple_choice', '_____ that the client was unsatisfied, the manager personally called.', '["Known","Knowing","Having known","To know"]', 'Knowing', 'Knowing that 現在分詞子句表示因為知道。'),
(74, 'multiple_choice', 'She sat at her desk, _____ through the annual report.', '["having flipped","flipped","to flip","flipping"]', 'flipping', 'flipping through 伴隨動作的現在分詞子句。'),
(74, 'multiple_choice', '_____ all stakeholders, the manager made a balanced decision.', '["Consulted","To consult","Consulting","Having consulted"]', 'Consulting', 'Consulting all stakeholders 分詞子句（因此/同時）。'),
(74, 'transform', 'Because she had reviewed all the data, she was confident in her recommendation. (Use -ing clause)', NULL, 'Having reviewed all the data, she was confident in her recommendation.', 'Having reviewed 完成分詞子句。'),
(74, 'fill_blank', '_____ (understand) the risks, the board approved the merger cautiously.', NULL, 'Understanding', 'Understanding the risks 現在分詞子句表因為了解風險。'),
(74, 'multiple_choice', 'He answered all the client''s questions, _____ his expertise.', '["to demonstrate","demonstrated","demonstrating","having demonstrated"]', 'demonstrating', 'demonstrating 伴隨動作的分詞子句。'),
(74, 'multiple_choice', '_____ a thorough analysis, the consultants recommended restructuring.', '["Having conducted","To conduct","Conducting","Conducted"]', 'Having conducted', 'Having conducted 表在主句動作前已完成分析。'),
(74, 'multiple_choice', 'The CEO gave the speech, _____ to the achievements of the entire team.', '["referring","having referred","referred","to refer"]', 'referring', 'referring to 分詞子句，伴隨動作。'),
(74, 'transform', 'Because she worked efficiently, she finished ahead of schedule. (Use -ing clause)', NULL, 'Working efficiently, she finished the project well ahead of schedule.', 'Working efficiently 現在分詞子句表原因。'),
(74, 'fill_blank', '_____ (not / realize) the severity, he underestimated the challenge.', NULL, 'Not realizing', 'Not realizing 否定分詞子句。'),
(74, 'multiple_choice', '_____ the proposal three times, she finally submitted it.', '["Revising","Having revised","Revised","To revise"]', 'Having revised', 'Having revised 表完成後提交。'),
(74, 'multiple_choice', 'She reported the issue, _____ full documentation to support her claims.', '["to provide","having provided","provided","providing"]', 'providing', 'providing 伴隨動作。'),
(74, 'multiple_choice', '_____ late, he missed the beginning of the presentation.', '["To arrive","Having arrived","Arriving","Arrived"]', 'Arriving', 'Arriving late 現在分詞子句（因為晚到）。'),
(74, 'transform', 'After she read the brief, she prepared detailed questions. (Use -ing clause)', NULL, 'Having read the brief, she prepared detailed and insightful questions.', 'Having read 完成分詞子句。'),
(74, 'fill_blank', '_____ (consider) all options, the team chose the most cost-effective approach.', NULL, 'Having considered', 'Having considered 完成分詞子句。'),
(74, 'multiple_choice', 'The director walked out, _____ nothing further to add.', '["saying","said","to say","having said"]', 'saying', 'saying 伴隨動作的分詞子句。'),
(75, 'multiple_choice', '_____ by the legal team, the contract was ready to sign.', '["Reviewing","Having reviewed","To review","Reviewed"]', 'Reviewed', 'Reviewed by 被動過去分詞子句，表完成審查後。'),
(75, 'multiple_choice', '_____ clearly, the instructions were easy to follow.', '["Having written","Written","To write","Writing"]', 'Written', 'Written clearly 被動過去分詞子句。'),
(75, 'multiple_choice', 'The report, _____ overnight, impressed everyone the next morning.', '["completing","having completed","completed","to complete"]', 'completed', 'completed overnight 被動分詞子句。'),
(75, 'fill_blank', '_____ (train) by industry experts, the staff are highly competent.', NULL, 'Trained', 'Trained by 被動過去分詞子句。'),
(75, 'multiple_choice', '_____ thoroughly, the proposal was approved without objection.', '["Having prepared","To prepare","Prepared","Preparing"]', 'Prepared', 'Prepared thoroughly 被動過去分詞子句。'),
(75, 'multiple_choice', 'The data, _____ three times, was finally accepted as accurate.', '["verifying","to verify","verified","having verified"]', 'verified', 'verified three times 被動分詞子句（非限定）。'),
(75, 'multiple_choice', '_____ in Seoul, the new branch quickly became profitable.', '["Establishing","Established","To establish","Having established"]', 'Established', 'Established in Seoul 被動過去分詞子句。'),
(75, 'transform', 'Because the design was approved, production could begin. (Use past participle clause)', NULL, 'Approved by the design committee, the product went into production.', 'Approved 被動過去分詞子句。'),
(75, 'fill_blank', '_____ (submit) on time, the report received positive feedback from the board.', NULL, 'Submitted', 'Submitted on time 被動分詞子句。'),
(75, 'multiple_choice', 'The proposal, _____ by senior leadership, was distributed to all managers.', '["to endorse","endorsed","endorsing","having endorsed"]', 'endorsed', 'endorsed by senior leadership 被動分詞修飾 proposal。'),
(75, 'multiple_choice', '_____ on the market for ten years, the brand is widely trusted.', '["To establish","Having established","Establishing","Established"]', 'Established', 'Established on the market 被動過去分詞子句。'),
(75, 'multiple_choice', 'Once _____, the product will be available in all major retail stores.', '["to launch","launched","having launched","launching"]', 'launched', 'Once launched 被動過去分詞子句。'),
(75, 'transform', 'After the issue was identified, the team worked on a solution. (Use past participle clause)', NULL, 'Identified early, the issue was resolved before it escalated.', 'Identified 被動過去分詞子句。'),
(75, 'fill_blank', '_____ (analyse) carefully, the results showed a clear trend.', NULL, 'Analysed', 'Analysed carefully 被動過去分詞子句。'),
(75, 'multiple_choice', 'If _____ correctly, this strategy should yield significant returns.', '["having implemented","implementing","implemented","to implement"]', 'implemented', 'If implemented correctly 條件被動分詞子句。'),
(75, 'multiple_choice', 'The system, _____ in 2020, is due for an upgrade.', '["having installed","installing","installed","to install"]', 'installed', 'installed in 2020 被動分詞修飾 system。'),
(75, 'multiple_choice', '_____ in three languages, the annual report reaches a global audience.', '["To publish","Published","Publishing","Having published"]', 'Published', 'Published in three languages 被動過去分詞子句。'),
(75, 'transform', 'Once we finalize the agreement, we will make an announcement. (Use past participle clause)', NULL, 'Once finalized, the agreement will be publicly announced.', 'Once finalized 被動過去分詞子句。'),
(75, 'fill_blank', '_____ (overwhelm) with requests, the support team needed more staff.', NULL, 'Overwhelmed', 'Overwhelmed 被動過去分詞子句，表被淹沒在請求中。'),
(75, 'multiple_choice', '_____ by the client, the revised proposal was immediately accepted.', '["Having requested","Requesting","Requested","To request"]', 'Requested', 'Requested by the client 被動過去分詞子句。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(76, 'multiple_choice', 'The employee _____ the project is very experienced.', '["managed","managing","who managing","to manage"]', 'managing', 'managing 現在分詞縮減關係子句（= who manages）。'),
(76, 'multiple_choice', 'The report _____ last week has been approved.', '["submitted","that submitted","to submit","submitting"]', 'submitted', 'submitted 過去分詞縮減被動關係子句（= that was submitted）。'),
(76, 'multiple_choice', 'The candidates _____ for the position all have relevant experience.', '["to apply","applied","who applying","applying"]', 'applying', 'applying 現在分詞縮減主動關係子句。'),
(76, 'fill_blank', 'The system _____ (install) last year needs an upgrade.', NULL, 'installed', 'installed 過去分詞縮減被動關係子句。'),
(76, 'multiple_choice', 'The clients _____ at the trade fair placed large orders.', '["contacting","contacted","who contacting","to contact"]', 'contacted', 'contacted 過去分詞縮減被動關係子句（= who were contacted）。'),
(76, 'multiple_choice', 'The team _____ the analysis made several key recommendations.', '["conducted","who conducting","to conduct","conducting"]', 'conducting', 'conducting 現在分詞縮減主動關係子句（= that is conducting）。'),
(76, 'multiple_choice', 'The software _____ by our IT team is highly efficient.', '["that developing","developed","developing","to develop"]', 'developed', 'developed 過去分詞縮減被動關係子句。'),
(76, 'transform', 'The employee who was selected for the promotion has ten years of experience. (Reduce)', NULL, 'The employee selected for the promotion has ten years of experience.', 'selected 過去分詞縮減被動關係子句。'),
(76, 'fill_blank', 'The proposal _____ (consider) by the board will be announced next week.', NULL, 'being considered', 'being considered 表正在進行中的被動分詞子句。'),
(76, 'multiple_choice', 'Any employee _____ in misconduct will face disciplinary action.', '["to engage","engaged","who engaging","engaging"]', 'engaging', 'engaging in 現在分詞縮減主動關係子句。'),
(76, 'multiple_choice', 'The documents _____ to all parties must be signed.', '["to send","sent","sending","that sending"]', 'sent', 'sent to all parties 過去分詞縮減被動關係子句。'),
(76, 'multiple_choice', 'The companies _____ to participate in the pilot program will be contacted.', '["to select","selected","selecting","that selecting"]', 'selected', 'selected 過去分詞縮減被動關係子句。'),
(76, 'transform', 'The manager who is leading the restructuring is highly experienced. (Reduce)', NULL, 'The manager leading the restructuring is highly experienced.', 'leading 現在分詞縮減主動關係子句。'),
(76, 'fill_blank', 'The data _____ (collect) over three years will be analysed this quarter.', NULL, 'collected', 'collected 過去分詞縮減被動關係子句。'),
(76, 'multiple_choice', 'All orders _____ before Friday will be processed by next week.', '["that placing","to place","placing","placed"]', 'placed', 'placed before Friday 過去分詞縮減被動關係子句。'),
(76, 'multiple_choice', 'The team _____ on the new platform faces some technical challenges.', '["worked","that working","working","to work"]', 'working', 'working on 現在分詞縮減主動關係子句。'),
(76, 'multiple_choice', 'The contract _____ by both parties takes effect immediately.', '["signing","signed","that signing","to sign"]', 'signed', 'signed by both parties 過去分詞縮減被動關係子句。'),
(76, 'transform', 'The client who complained about the delay was given a discount. (Reduce)', NULL, 'The client complaining about the delay was given a discount.', 'complaining 現在分詞縮減主動關係子句。'),
(76, 'fill_blank', 'The staff _____ (recruit) through the agency will start next month.', NULL, 'recruited', 'recruited 過去分詞縮減被動關係子句。'),
(76, 'multiple_choice', 'The strategy _____ last year has proven very effective.', '["adopting","that adopting","adopted","to adopt"]', 'adopted', 'adopted last year 過去分詞縮減被動關係子句。'),
(77, 'multiple_choice', 'Which is more formal?', '["Hey, want to know about your services?","I''m writing to ask about your services.","I am writing to enquire about your services.","Got questions about your services."]', 'I am writing to enquire about your services.', '完整形式、正式詞彙 enquire，更書面正式。'),
(77, 'multiple_choice', 'Which is the formal equivalent of ''buy''?', '["get","pick up","grab","purchase"]', 'purchase', 'purchase 比 buy 更正式。'),
(77, 'multiple_choice', 'Which is the formal equivalent of ''use''?', '["make use","use out","utilise","use up"]', 'utilise', 'utilise 是 use 的正式書面表達。'),
(77, 'fill_blank', 'Please _____ (tell) us if you require further assistance. (formal)', NULL, 'inform', 'inform 比 tell 更正式。'),
(77, 'multiple_choice', 'Which is more appropriate for a formal business letter?', '["Sorry, but you didn''t get the job.","We regret to inform you that your application has been unsuccessful.","We''re sad to say you failed.","Your application didn''t make it."]', 'We regret to inform you that your application has been unsuccessful.', '正式：regret to inform，完整形式，禮貌措辭。'),
(77, 'multiple_choice', 'Which is the formal equivalent of ''help''?', '["chip in","assist","lend a hand","pitch in"]', 'assist', 'assist 比 help 更正式。'),
(77, 'multiple_choice', 'Which is more formal?', '["Just give us a call anytime.","Feel free to contact us.","Please do not hesitate to contact us.","Ring us whenever."]', 'Please do not hesitate to contact us.', 'Please do not hesitate to 是正式商業英語的標準用語。'),
(77, 'transform', 'The meeting is going to start at 2 p.m. (Make more formal)', NULL, 'The meeting is scheduled to commence at 2:00 p.m.', 'is scheduled to commence 更正式；2:00 p.m. 更正式。'),
(77, 'multiple_choice', 'Which is the formal equivalent of ''end''?', '["finish up","stop","terminate","quit"]', 'terminate', 'terminate 比 end 更正式（尤指合約）。'),
(77, 'fill_blank', 'We would like to _____ (send) you a copy of our latest brochure. (formal)', NULL, 'forward', 'forward 比 send 更正式。'),
(77, 'multiple_choice', 'Which is NOT appropriate in a formal business email?', '["That sounds great! I''ll get back to you ASAP.","Please find attached the requested document.","We look forward to your response.","We would be delighted to proceed."]', 'That sounds great! I''ll get back to you ASAP.', '口語縮寫 ASAP 和感嘆號不適合正式商業郵件。'),
(77, 'multiple_choice', 'Which sentence uses formal register?', '["Just confirming I got your message.","We wish to confirm receipt of your correspondence.","Thanks for writing to us.","We got your email."]', 'We wish to confirm receipt of your correspondence.', '正式：confirm receipt of your correspondence，無縮寫，正式詞彙。'),
(77, 'transform', 'We want to know if you''re interested. (Make more formal)', NULL, 'We would like to know whether you would be interested in this proposal.', 'would like to + whether 更正式。'),
(77, 'fill_blank', 'I _____ (write) to follow up on our discussion last week. (formal)', NULL, 'am writing to', 'am writing to 正式信件開頭。'),
(77, 'multiple_choice', 'Which is the formal equivalent of ''start''?', '["get going","kick off","commence","start up"]', 'commence', 'commence 比 start 更正式。'),
(77, 'multiple_choice', 'Which sentence is most appropriate for a formal email closing?', '["Hope to hear from you.","We look forward to hearing from you at your earliest convenience.","Talk soon!","Get back to me when you can."]', 'We look forward to hearing from you at your earliest convenience.', '正式結尾語，完整表達，無縮寫。'),
(77, 'multiple_choice', 'Which is the formal way to say ''find out''?', '["look into","figure out","ascertain","dig up"]', 'ascertain', 'ascertain 是 find out 的正式書面表達。'),
(77, 'transform', 'Thanks for your help. (Make more formal)', NULL, 'We would like to express our sincere gratitude for your assistance.', 'express gratitude 正式感謝用語。'),
(77, 'fill_blank', 'We are _____ (look/for) suitable candidates for this position. (formal)', NULL, 'seeking', 'seeking 比 looking for 更正式。'),
(77, 'multiple_choice', 'Which is the formal way to say ''talk about''?', '["talk through","discuss","go over","chat about"]', 'discuss', 'discuss 比 talk about 更正式書面。'),
(78, 'multiple_choice', 'This _____ indicate that sales are beginning to recover.', '["certainly","may","always","definitely"]', 'may', 'may 表謹慎的可能性，是典型的模糊限制語。'),
(78, 'multiple_choice', 'It _____ that there has been a misunderstanding.', '["seems","proves","clearly is","is"]', 'seems', 'it seems that 表猜測/外交委婉。'),
(78, 'multiple_choice', 'The results _____ suggest that the strategy is working.', '["always","definitely","would appear to","certainly"]', 'would appear to', 'would appear to 是高度模糊限制語。'),
(78, 'fill_blank', 'Sales have _____ (possible) declined due to seasonal factors.', NULL, 'possibly', 'possibly 表猜測性副詞，模糊限制語。'),
(78, 'multiple_choice', 'This is _____ due to increased competition.', '["definitely","certainly","arguably","clearly"]', 'arguably', 'arguably 表可以爭論，軟化斷言。'),
(78, 'multiple_choice', 'There _____ be some resistance to the new policy.', '["must","might","shall","will"]', 'might', 'might 表猜測可能性，模糊限制語。'),
(78, 'multiple_choice', 'It _____ that costs will continue to rise.', '["is clear","is likely","is certain","is definite"]', 'is likely', 'is likely 表可能但不確定。'),
(78, 'transform', 'The data shows that profits will fall. (Soften with hedging)', NULL, 'The data suggests that profits may fall slightly next quarter.', 'suggests 和 may 模糊限制語。'),
(78, 'multiple_choice', 'The decline _____ be attributed to external factors.', '["can probably","always","definitely","certainly can"]', 'can probably', 'can probably 是模糊限制語組合。'),
(78, 'fill_blank', 'This _____ (tend) to indicate that there is room for improvement.', NULL, 'tends to', 'tends to indicate 是模糊限制語搭配。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(78, 'multiple_choice', 'It _____ fair to say that progress has been made.', '["would be","is definitely","is certainly","is clearly"]', 'would be', 'it would be fair to say 是典型模糊限制語。'),
(78, 'multiple_choice', 'The evidence _____ suggest a causal relationship.', '["does not","does not necessarily","never","cannot"]', 'does not necessarily', 'does not necessarily 是模糊限制的否定表達。'),
(78, 'multiple_choice', 'There is _____ a connection between the two events.', '["certainly","clearly","possibly","definitely"]', 'possibly', 'possibly 表謹慎猜測。'),
(78, 'transform', 'We are sure that the market will improve. (Add hedging)', NULL, 'We believe that the market may improve over the coming months.', 'believe that...may 模糊限制語。'),
(78, 'fill_blank', 'The report _____ (indicate) that further research is needed.', NULL, 'indicates / suggests', 'indicates 比 proves 更謹慎；suggests 更是模糊限制語。'),
(78, 'multiple_choice', 'This _____ be seen as a positive development.', '["could","shall","will","must"]', 'could', 'could be seen as 模糊限制語。'),
(78, 'multiple_choice', 'It _____ that some stakeholders may have concerns.', '["is certain","is conceivable","is definite","is obvious"]', 'is conceivable', 'it is conceivable that 是正式模糊限制語。'),
(78, 'transform', 'The new regulation will affect all businesses. (Soften with hedging)', NULL, 'The new regulation is likely to affect most businesses to some extent.', 'is likely to 和 to some extent 模糊限制語。'),
(78, 'fill_blank', 'This _____ (appear) to be a viable long-term solution.', NULL, 'appears', 'appears to be 是模糊限制語。'),
(78, 'multiple_choice', 'The figures _____ point to a slight improvement.', '["certainly","definitely","clearly","seem to"]', 'seem to', 'seem to 表謹慎推斷，模糊限制語。'),
(79, 'multiple_choice', 'Which sentence uses nominalization?', '["We''re putting off the launch.","We decided to postpone the launch.","We postponed it.","A decision was made to postpone the launch."]', 'A decision was made to postpone the launch.', 'A decision was made 將動詞 decide 名詞化。'),
(79, 'multiple_choice', 'Which is the nominalized form of ''improve''?', '["improvement","improved","improving","to improve"]', 'improvement', 'improvement 是 improve 的名詞化形式。'),
(79, 'multiple_choice', 'Which sentence uses nominalization?', '["More people want it.","Demand has increased.","People are buying more.","An increase in demand has been observed."]', 'An increase in demand has been observed.', 'An increase in demand 名詞化 demand increased。'),
(79, 'fill_blank', 'Which noun is the nominalization of ''reduce''? → _____.', NULL, 'reduction', 'reduction 是 reduce 的名詞化。'),
(79, 'multiple_choice', 'We need to _____ our strategy. (Make it more formal using nominalization)', '["check","review","look at","conduct a review of"]', 'conduct a review of', 'conduct a review of 是 review 的名詞化形式，更正式。'),
(79, 'multiple_choice', 'Which is the nominalized form of ''analyse''?', '["to analyse","analysing","analysis","analysed"]', 'analysis', 'analysis 是 analyse 的名詞化。'),
(79, 'multiple_choice', 'Which sentence uses nominalization?', '["We finished setting up the system.","We implemented the new system on schedule.","The new system was set up on time.","The implementation of the new system was completed on schedule."]', 'The implementation of the new system was completed on schedule.', 'The implementation 名詞化 implement。'),
(79, 'transform', 'We agreed to proceed with the merger. (Nominalize)', NULL, 'Agreement was reached to proceed with the merger.', 'agreement 是 agree 的名詞化。'),
(79, 'fill_blank', 'The _____ (discuss) of the proposal took two hours.', NULL, 'discussion', 'discussion 是 discuss 的名詞化。'),
(79, 'multiple_choice', 'Which is the nominalized form of ''fail''?', '["to fail","failure","failed","failing"]', 'failure', 'failure 是 fail 的名詞化。'),
(79, 'multiple_choice', 'Which sentence is more formal through nominalization?', '["We''ve grown a lot.","Significant growth has been achieved.","Growth happened significantly.","We grew significantly."]', 'Significant growth has been achieved.', 'significant growth has been achieved 名詞化 grew。'),
(79, 'multiple_choice', 'Which is the nominalized form of ''solve''?', '["solved","solving","to solve","solution"]', 'solution', 'solution 是 solve 的名詞化。'),
(79, 'fill_blank', 'The _____ (acquire) of the company was completed last year.', NULL, 'acquisition', 'acquisition 是 acquire 的名詞化。'),
(79, 'multiple_choice', 'Which sentence uses nominalization correctly?', '["We were negotiating for three weeks.","Negotiating took three weeks.","The negotiation of terms took three weeks.","We negotiated terms for three weeks."]', 'The negotiation of terms took three weeks.', 'The negotiation of terms 名詞化 negotiated。'),
(79, 'multiple_choice', 'Which is the nominalized form of ''decide''?', '["to decide","decision","deciding","decided"]', 'decision', 'decision 是 decide 的名詞化。'),
(79, 'transform', 'We evaluated the risks carefully. (Nominalize)', NULL, 'A thorough evaluation of the risks was conducted.', 'evaluation 是 evaluate 的名詞化。'),
(79, 'fill_blank', 'We conducted a _____ (investigate) into the issue.', NULL, 'investigation', 'investigation 是 investigate 的名詞化。'),
(79, 'multiple_choice', 'Which is the nominalized form of ''recommend''?', '["recommended","recommending","to recommend","recommendation"]', 'recommendation', 'recommendation 是 recommend 的名詞化。'),
(79, 'multiple_choice', 'Which sentence demonstrates nominalization?', '["We expanded successfully into Asia.","We went into Asia successfully.","The expansion of our operations into Asia has been successful.","Expanding into Asia worked out."]', 'The expansion of our operations into Asia has been successful.', 'The expansion of our operations 名詞化 expanded。'),
(79, 'multiple_choice', 'Which is the nominalized form of ''approve''?', '["approving","approval","to approve","approved"]', 'approval', 'approval 是 approve 的名詞化。'),
(80, 'multiple_choice', 'Which is the more formal, impersonal version?', '["I''ve decided to postpone it.","We decided to postpone the launch.","It has been decided to postpone the launch.","Let''s postpone the launch."]', 'It has been decided to postpone the launch.', 'It has been decided 非人稱被動式，最正式。'),
(80, 'multiple_choice', 'Which sentence uses impersonal structure?', '["Note that the results are preliminary.","It is important to note that the results are preliminary.","You should note the preliminary results.","I want you to note the preliminary results."]', 'It is important to note that the results are preliminary.', 'It is important to note that 非人稱結構。'),
(80, 'multiple_choice', 'Which is the most formal way to start a recommendation?', '["You should implement these measures.","Implement these measures.","It is recommended that the following measures be implemented.","We recommend implementing these measures."]', 'It is recommended that the following measures be implemented.', 'It is recommended that + 虛擬語氣，非人稱被動，最正式。'),
(80, 'fill_blank', 'It _____ (note) that the data has certain limitations.', NULL, 'should be noted', 'it should be noted that 非人稱被動式。'),
(80, 'multiple_choice', 'Which uses passive voice appropriately?', '["We rejected the proposal.","They rejected the proposal because of budget.","The proposal was rejected due to budget constraints.","Budget constraints made us reject it."]', 'The proposal was rejected due to budget constraints.', 'The proposal was rejected 被動語態，不強調行為者。'),
(80, 'multiple_choice', 'Which is the most formal impersonal structure?', '["It would appear that further investigation is required.","Apparently, we need to investigate more.","It seems we need to look into this more.","We think further investigation is needed."]', 'It would appear that further investigation is required.', 'It would appear that 最高度正式非人稱結構。'),
(80, 'multiple_choice', 'Which sentence demonstrates formal passive writing?', '["We got the board to review the findings.","The findings have been reviewed and approved by the board.","The board reviewed and approved the findings.","The board has reviewed and approved everything."]', 'The findings have been reviewed and approved by the board.', 'The findings have been reviewed...被動語態，無人稱強調。'),
(80, 'transform', 'We will announce the results at the AGM. (Make impersonal/passive)', NULL, 'It has been decided that the results will be announced at the AGM.', '被動+非人稱結構。'),
(80, 'fill_blank', 'It _____ (establish) that the new policy will take effect in Q2.', NULL, 'has been established', 'it has been established that 非人稱被動式。'),
(80, 'multiple_choice', 'Which is the most appropriate sentence for a formal report conclusion?', '["Obviously the strategy worked.","The strategy was effective, we think.","It can therefore be concluded that the strategy has been effective.","So we can say the strategy worked."]', 'It can therefore be concluded that the strategy has been effective.', 'It can be concluded that 正式非人稱被動推論。'),
(80, 'multiple_choice', 'Which impersonal structure is correct?', '["It is believed that the market will recover by year end.","People believe the market will recover.","We believe the market will recover.","I believe the market will recover."]', 'It is believed that the market will recover by year end.', 'It is believed that 非人稱被動，報告中常用。'),
(80, 'multiple_choice', 'Which is the most formal?', '["We are taking steps to address the issue.","We''re working on fixing the issue.","Steps are being taken to address the issue.","We''re on it."]', 'Steps are being taken to address the issue.', 'Steps are being taken 被動進行式，非人稱。'),
(80, 'transform', 'We need to ensure all employees understand the policy. (Make formal/impersonal)', NULL, 'It is essential that all employees are made aware of the new policy.', 'It is essential that + 被動，非人稱。'),
(80, 'fill_blank', 'It _____ (report) that the merger negotiations are ongoing.', NULL, 'has been reported', 'it has been reported that 非人稱被動式。'),
(80, 'multiple_choice', 'Which is the most appropriate for a formal notice?', '["All staff must attend the briefing.","You all have to attend.","All staff are required to attend the mandatory briefing.","Everyone needs to come to the briefing."]', 'All staff are required to attend the mandatory briefing.', 'All staff are required to 被動非人稱，最正式。'),
(80, 'multiple_choice', 'Which is a correct impersonal structure?', '["Note that sales improved.","We should note that sales improved.","Don''t forget sales improved.","It is worth noting that sales have improved significantly."]', 'It is worth noting that sales have improved significantly.', 'It is worth noting that 非人稱結構。'),
(80, 'multiple_choice', 'Which sentence best exemplifies formal passive in reports?', '["We spent six months collecting data.","Data collection took six months.","The data was collected over a period of six months.","We collected data for six months."]', 'The data was collected over a period of six months.', 'The data was collected 標準學術/報告被動式。'),
(80, 'transform', 'We have identified several key issues. (Make formal/impersonal)', NULL, 'Several key issues have been identified in the course of this review.', 'Several key issues have been identified 非人稱被動式。'),
(80, 'fill_blank', 'It is _____ (expect) that the new system will reduce errors by 30%.', NULL, 'expected', 'it is expected that 非人稱被動預測。'),
(80, 'multiple_choice', 'Which is the most formal way to express an obligation?', '["It is mandatory that all contractors comply with safety regulations.","Make sure all contractors follow safety rules.","All contractors must comply with safety regulations.","Every contractor needs to follow safety rules."]', 'It is mandatory that all contractors comply with safety regulations.', 'It is mandatory that + 虛擬語氣，非人稱被動，最正式。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(81, 'multiple_choice', 'Which sentence correctly uses a colon?', '["The proposal covers three areas, budget: timeline and resources.","The proposal covers three areas: budget, timeline, and resources.","The proposal covers three areas; budget, timeline, and resources.","The proposal covers: three areas budget timeline resources."]', 'The proposal covers three areas: budget, timeline, and resources.', '冒號引出列表正確用法。'),
(81, 'multiple_choice', 'Which sentence correctly uses a semicolon?', '["The project is behind schedule: we need more resources.","The project is behind schedule; we need to allocate more resources.","The project is behind schedule, we need more resources.","The project is behind schedule but we need more resources."]', 'The project is behind schedule; we need to allocate more resources.', '分號連接兩個獨立但相關的子句。'),
(81, 'fill_blank', 'The meeting covered the following topics_____ budget allocation, staffing, and the Q4 strategy.', NULL, '：（colon）', '冒號引出列表。'),
(81, 'multiple_choice', 'Which correctly uses a colon?', '["Please bring the following, documents: your passport CV and references.","Please bring the following documents; your passport, CV, and references.","Please bring: the following documents your passport CV and references.","Please bring the following documents: your passport, CV, and references."]', 'Please bring the following documents: your passport, CV, and references.', '冒號引出列表。'),
(81, 'multiple_choice', 'Which correctly uses a semicolon?', '["Sales increased in Asia, however they declined in Europe.","Sales increased in Asia: however, they declined in Europe.","Sales increased in Asia; however, they declined in Europe.","Sales increased in Asia - however they declined in Europe."]', 'Sales increased in Asia; however, they declined in Europe.', '分號 + 連接副詞 however 正確用法。'),
(81, 'multiple_choice', 'Where should a colon go in this sentence? ''We offer three payment options _____ monthly, quarterly, or annually.''', '["，",":","；","—"]', ':', '冒號引出選項列表。'),
(81, 'fill_blank', 'She has one goal_____ to become the regional director within five years.', NULL, '：（colon）', '冒號強調唯一目標。'),
(81, 'multiple_choice', 'Which is correct?', '["The budget was approved consequently the project began.","The budget was approved: consequently the project began.","The budget was approved; consequently, the project began.","The budget was approved, consequently the project began."]', 'The budget was approved; consequently, the project began.', '分號 + 連接副詞 consequently 正確。'),
(81, 'multiple_choice', 'Which sentence uses a semicolon correctly?', '["The report is comprehensive, it covers all KPIs.","The report is comprehensive; it covers all key performance indicators.","The report is comprehensive: it covers all KPIs.","The report is comprehensive. It covers all KPIs."]', 'The report is comprehensive; it covers all key performance indicators.', '分號連接兩個緊密相關的獨立子句。'),
(81, 'transform', 'The company has three priorities. These are: growth, innovation, and sustainability. (Combine using colon)', NULL, 'The company has three priorities: growth, innovation, and sustainability.', '冒號合併為一個句子列舉。'),
(81, 'multiple_choice', 'Which correctly uses a colon?', '["The conclusion: is clear we must cut costs immediately.","The conclusion is clear, we must cut costs immediately.","The conclusion is clear; we must cut costs immediately.","The conclusion is clear: we must cut costs immediately."]', 'The conclusion is clear: we must cut costs immediately.', '冒號強調後面的重要陳述。'),
(81, 'fill_blank', 'We have identified two issues_____ the timeline is too tight, and the budget is insufficient.', NULL, '：（colon）', '冒號引出後面的說明。'),
(81, 'multiple_choice', 'Which sentence uses punctuation correctly?', '["She is qualified; she has an MBA and ten years of experience.","She is qualified - she has an MBA and ten years of experience.","She is qualified, she has an MBA and ten years of experience.","She is qualified: she has an MBA and ten years of experience."]', 'She is qualified; she has an MBA and ten years of experience.', '分號連接兩個獨立子句正確（冒號也可，但分號表更對等關係）。'),
(81, 'multiple_choice', 'Choose the correctly punctuated sentence:', '["There are four steps, research plan execute and review.","There are four steps; research, plan, execute, and review.","There are four, steps: research plan execute and review.","There are four steps: research, plan, execute, and review."]', 'There are four steps: research, plan, execute, and review.', '冒號引出四個步驟的列表。'),
(81, 'transform', 'Sales are falling. Furthermore, costs are rising. (Join with semicolon)', NULL, 'Sales are falling; furthermore, costs are rising.', '分號 + 連接副詞 furthermore。'),
(81, 'fill_blank', 'The agenda includes the following items_____ Q3 review, budget proposal, and staffing update.', NULL, '：（colon）', '冒號引出會議議程列表。'),
(81, 'multiple_choice', 'Which is correct?', '["The deadline is Friday. Please ensure all reports are submitted.","The deadline is Friday: please ensure all reports are submitted.","The deadline is Friday; please ensure all reports are submitted.","The deadline is Friday, please ensure all reports are submitted."]', 'The deadline is Friday; please ensure all reports are submitted.', '分號連接兩個緊密相關子句，命令強調。'),
(81, 'multiple_choice', 'Choose the correct sentence:', '["The audit revealed one major concern, insufficient documentation.","The audit revealed: one major concern insufficient documentation.","The audit revealed one major concern; insufficient documentation.","The audit revealed one major concern: insufficient documentation."]', 'The audit revealed one major concern: insufficient documentation.', '冒號強調唯一的重大問題。'),
(81, 'fill_blank', 'We have three options_____ negotiate, compromise, or walk away.', NULL, '：（colon）', '冒號引出選項。'),
(81, 'multiple_choice', 'Which correctly uses a semicolon?', '["He is an expert in finance, she specializes in operations.","He is an expert in finance: she specializes in operations.","He is an expert in finance; she specializes in operations.","He is an expert in finance. she specializes in operations."]', 'He is an expert in finance; she specializes in operations.', '分號連接對比的兩個獨立子句。'),
(82, 'multiple_choice', 'Which is correct?', '["The companies'' annual report was released today.","The companies annual report was released today.","The company''s annual report was released today.","The companys'' annual report was released today."]', 'The company''s annual report was released today.', 'company''s 單數所有格。'),
(82, 'multiple_choice', 'Which is correct?', '["It is''s important to review the contract carefully.","Its important to review the contract carefully.","It''s important to review the contract carefully.","Its'' important to review the contract carefully."]', 'It''s important to review the contract carefully.', 'It''s = it is，縮寫用撇號。'),
(82, 'multiple_choice', 'Which is correct?', '["The managers report''s are due on Friday.","The manager''s reports are due on Friday.","The managers'' reports are due on Friday.","The managers reports are due on Friday."]', 'The managers'' reports are due on Friday.', 'managers'' 複數所有格（多個管理者的報告）。'),
(82, 'fill_blank', 'The product has its _____ (own) unique features. (its or it''s?)', NULL, 'its', '其 own = its，所有格，不加撇號。'),
(82, 'multiple_choice', 'Which is correct?', '["The teams'' performance exceeded all expectations.","The teams performance exceeded all expectations.","The team''s performance exceeded all expectations.","The team''s performance exceeded all expectations."]', 'The team''s performance exceeded all expectations.', 'team''s 單數所有格正確。'),
(82, 'multiple_choice', 'Which sentence uses the apostrophe correctly?', '["Were pleased to announce the launch of our new product.","We are''s pleased to announce our new product.","We''re pleased to announce the launch of our new product.","Were'' pleased to announce the launch."]', 'We''re pleased to announce the launch of our new product.', 'We''re = we are，縮寫正確。'),
(82, 'multiple_choice', 'Which is correct?', '["The CEOs'' decision was final.","The CEOs decision was final.","The CEO''s decision was final.","The CEO''s decision was final."]', 'The CEO''s decision was final.', 'CEO''s 單數所有格正確。'),
(82, 'fill_blank', 'The company revised _____ pricing strategy. (its or it''s?)', NULL, 'its', 'its 所有格，不加撇號。'),
(82, 'multiple_choice', 'Which is correct for multiple employees?', '["The employees contract''s were all renewed.","The employees contracts were all renewed.","The employees'' contracts were all renewed.","The employee''s contracts were all renewed."]', 'The employees'' contracts were all renewed.', 'employees'' 複數所有格。'),
(82, 'multiple_choice', 'Which is correct?', '["They''s already submitted their proposals.","Their''ve already submitted their proposals.","They''ve already submitted their proposals.","They have''s already submitted their proposals."]', 'They''ve already submitted their proposals.', 'They''ve = they have，縮寫正確。'),
(82, 'multiple_choice', 'Which sentence is correct?', '["The shareholder''s meeting is scheduled for next Tuesday.","The shareholders'' meeting is scheduled for next Tuesday.","The shareholder''s'' meeting is scheduled for next Tuesday.","The shareholders meeting is scheduled for next Tuesday."]', 'The shareholders'' meeting is scheduled for next Tuesday.', 'shareholders'' 複數所有格（多個股東的會議）。'),
(82, 'fill_blank', '_____ (It is) been three months since the merger was announced.', NULL, 'It''s', 'It''s = it has，縮寫用撇號。'),
(82, 'multiple_choice', 'Which is correct?', '["The two companies''s merger was announced yesterday.","The two company''s merger was announced yesterday.","The two companies'' merger was announced yesterday.","The two companies merger was announced yesterday."]', 'The two companies'' merger was announced yesterday.', 'companies'' 複數所有格。'),
(82, 'multiple_choice', 'Which is correct?', '["He responsible for client relations.","His responsible for client relations.","He''s responsible for client relations.","He is''s responsible for client relations."]', 'He''s responsible for client relations.', 'He''s = he is，縮寫正確。'),
(82, 'multiple_choice', 'Which apostrophe usage is correct?', '["The department''s budget was increased.","The departments budget was increased.","The department''s budget was increased.","The departments'' budget was increased."]', 'The department''s budget was increased.', 'department''s 單數所有格。'),
(82, 'transform', 'The office of the director is on the 10th floor. (Use possessive apostrophe)', NULL, 'The director''s office is on the 10th floor.', 'director''s 單數所有格代替 of 結構。'),
(82, 'fill_blank', 'The company _____ known for its innovative products. (it''s or its)', NULL, 'It''s', 'It''s = it is，作謂語動詞。'),
(82, 'multiple_choice', 'Which is correct?', '["Don''t share the clients'' personal data.","Do not share the clients personal data.","Don''t share the client''s personal data.","Dont share the client''s personal data."]', 'Don''t share the client''s personal data.', 'Don''t 縮寫；client''s 單數所有格正確。'),
(82, 'multiple_choice', 'Which is correct for a company owned by multiple owners?', '["The directors decision was unanimous.","The director''s decision was unanimous.","The directors'' decision was unanimous.","The directors''s decision was unanimous."]', 'The directors'' decision was unanimous.', 'directors'' 複數所有格正確。'),
(82, 'multiple_choice', 'Which sentence has NO apostrophe error?', '["We''ve received confirmation from all our supplier''s.","Weve received confirmation from all our suppliers.","We have''s received confirmation from all our suppliers.","We''ve received confirmation from all our suppliers."]', 'We''ve received confirmation from all our suppliers.', 'We''ve 縮寫正確；suppliers 複數名詞，不需要撇號。'),
(83, 'multiple_choice', 'The new software will greatly _____ our workflow efficiency.', '["extend","enhance","enlarge","expand"]', 'enhance', 'enhance 提升（品質/效率），最適合 workflow efficiency 的搭配。'),
(83, 'multiple_choice', 'All employees are required to _____ with the new data protection regulations.', '["follow","obey","agree","comply"]', 'comply', 'comply with regulations 固定搭配，表遵守法規。'),
(83, 'multiple_choice', 'The company plans to _____ its operations to Southeast Asia next year.', '["increase","develop","expand","enhance"]', 'expand', 'expand operations 擴大業務規模，固定搭配。'),
(83, 'fill_blank', 'The director will _____ the team through the restructuring process.', NULL, 'guide / lead', 'guide/lead someone through a process 指引通過。'),
(83, 'multiple_choice', 'The quarterly results _____ a significant improvement in profit margins.', '["reveal out","demonstrate","indicate to","show up"]', 'demonstrate', 'demonstrate 正式表達，展示結果；demonstrate a improvement 正確搭配。'),
(83, 'multiple_choice', 'We need to _____ additional funding to complete the project.', '["get","earn","find","secure"]', 'secure', 'secure funding 取得資金，商業英語固定搭配。'),
(83, 'multiple_choice', 'The board has _____ the new marketing strategy.', '["accepted","confirmed","endorsed","agreed"]', 'endorsed', 'endorse 正式核可/背書，比 agree 更強烈。'),
(83, 'fill_blank', 'The company _____ a significant market share within its first year.', NULL, 'captured / gained', 'capture/gain market share 取得市場份額。'),
(83, 'multiple_choice', 'Please _____ receipt of this document by signing the enclosed form.', '["verify","acknowledge","confirm","accept"]', 'acknowledge', 'acknowledge receipt of 確認收到，正式書面搭配。'),
(83, 'multiple_choice', 'The new policy will _____ in effect from the first of next month.', '["make","come","go","take"]', 'come', 'come into effect 生效，固定搭配。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(83, 'multiple_choice', 'She was _____ as the most innovative employee of the year.', '["appreciated","rewarded","recognized","known"]', 'recognized', 'recognized as 被認可為，正式表彰搭配。'),
(83, 'fill_blank', 'The merger was _____ by the relevant regulatory authorities.', NULL, 'approved / sanctioned', 'approve/sanction the merger 批准合併。'),
(83, 'multiple_choice', 'The team needs to _____ a solution before the client meeting tomorrow.', '["devise","develop up","find out","think"]', 'devise', 'devise a solution 設計/制定解決方案，正式搭配。'),
(83, 'multiple_choice', 'Our products are _____ to customers in over 50 countries.', '["available","obtainable","possible","accessible"]', 'available', 'available to customers 對客戶可取得，常用搭配。'),
(83, 'multiple_choice', 'The company has _____ significant progress in reducing its carbon footprint.', '["achieved","done","accomplished","made"]', 'made', 'make progress 固定搭配。'),
(83, 'fill_blank', 'She _____ an important role in the company''s expansion into Asia.', NULL, 'played', 'play a role 扮演角色，固定搭配。'),
(83, 'multiple_choice', 'The new branch will be _____ in the financial district.', '["situated","placed","positioned","located"]', 'located', 'located in 位於，商業英語常見。'),
(83, 'multiple_choice', 'The proposal was _____ on several grounds, including cost and timing.', '["refused","denied","rejected","declined"]', 'rejected', 'rejected on grounds 以...為由被拒絕。'),
(83, 'fill_blank', 'The CEO _____ a speech about the company''s vision at the annual meeting.', NULL, 'delivered / gave', 'deliver/give a speech 發表演講。'),
(83, 'multiple_choice', 'All team members are expected to _____ their best effort in this project.', '["offer","provide","give","contribute"]', 'contribute', 'contribute one''s best effort 貢獻最大努力，正式商業表達。'),
(84, 'multiple_choice', 'The committee _____ a final decision until all the data has been reviewed.', '["has not made","does not make","will not make","did not make"]', 'will not make', 'will not make...until 表未來的條件：直到資料審查完才做決定。'),
(84, 'multiple_choice', 'Please ensure the report is submitted _____ Friday at the latest.', '["until","before","on","by"]', 'by', 'by Friday 截止日期用 by（at the latest 確認是截止）。'),
(84, 'multiple_choice', 'All staff who _____ the meeting will receive the minutes by email.', '["will not attend","are not attending","have not attended","do not attend"]', 'do not attend', 'do not attend 泛指所有不出席者（零條件句式）。'),
(84, 'fill_blank', 'The software _____ (install) on all company computers by the end of the week.', NULL, 'will have been installed', '未來完成被動式。'),
(84, 'multiple_choice', 'Neither the CEO nor the directors _____ available for comment.', '["has been","is","was","were"]', 'were', 'neither...nor 就近原則，directors 複數，were。'),
(84, 'multiple_choice', 'The proposal, _____ was submitted last week, has been approved.', '["what","who","which","that"]', 'which', '非限定性關係子句（逗號隔開），用 which。'),
(84, 'multiple_choice', 'She has been working for the company _____ she graduated.', '["as","from","for","since"]', 'since', 'since + 時間點，現在完成進行式。'),
(84, 'fill_blank', 'The meeting _____ (reschedule) to 3 p.m. due to a scheduling conflict.', NULL, 'has been rescheduled', '現在完成被動式，說明已完成的重新安排。'),
(84, 'multiple_choice', 'He was promoted _____ his outstanding performance.', '["because of","even though","although","despite"]', 'because of', 'because of + 名詞短語表原因。'),
(84, 'multiple_choice', 'The report must _____ before the board meeting begins.', '["be to review","review","be reviewed","be reviewing"]', 'be reviewed', 'must be reviewed 情態動詞被動式。'),
(84, 'multiple_choice', 'Applicants _____ relevant experience are encouraged to apply.', '["having","with","of","who have"]', 'with', 'with relevant experience 介系詞短語修飾 applicants（也可用 having 或 who have）。'),
(84, 'fill_blank', 'By the time the new branch opens, we _____ (expand) into five new markets.', NULL, 'will have expanded', 'by the time 未來完成式。'),
(84, 'multiple_choice', 'The results were _____ better than anticipated.', '["considerably","considering","considerable","considerate"]', 'considerably', 'considerably 副詞修飾 better（比較級）。'),
(84, 'multiple_choice', '_____ the price increase, demand remains strong.', '["Because of","Even though","Despite","Although"]', 'Despite', 'Despite + 名詞短語（price increase），讓步。'),
(84, 'multiple_choice', 'She is the _____ experienced candidate for this position.', '["most","very","much","more"]', 'most', 'the most + 形容詞最高級。'),
(84, 'transform', 'Active: The HR team reviewed all applications. (Passive)', NULL, 'All applications were reviewed by the HR team.', 'were reviewed by 被動語態。'),
(84, 'fill_blank', 'The client _____ (not / respond) to our emails for two weeks.', NULL, 'has not responded', '現在完成式否定，for two weeks 持續。'),
(84, 'multiple_choice', 'We recommend that all participants _____ the pre-reading materials.', '["are reviewing","reviewed","review","reviews"]', 'review', 'recommend that + 原形動詞（虛擬語氣）。'),
(84, 'multiple_choice', 'The survey results indicate _____ customer satisfaction has improved.', '["that","how","which","what"]', 'that', 'indicate + that 名詞子句受語。'),
(84, 'multiple_choice', 'All shipments _____ before they are dispatched.', '["must be inspected","are must inspected","must have inspected","must inspect"]', 'must be inspected', 'must be inspected 情態動詞被動。'),
(85, 'multiple_choice', 'Thank you for your email of March 15th. We are _____ to inform you that...', '["happy","delighted","glad","pleased"]', 'pleased', 'pleased 最常見的正式商業郵件開頭表達（delighted 也正式但 pleased 更標準）。'),
(85, 'multiple_choice', 'We _____ your order and it will be dispatched within two working days.', '["will receive","have received","received","are receiving"]', 'have received', 'have received 現在完成式，說明已收到訂單。'),
(85, 'multiple_choice', 'Should you have any questions, please do not _____ to contact us.', '["hesitate","try","want","wait"]', 'hesitate', 'do not hesitate to contact us 正式商業套語。'),
(85, 'fill_blank', 'We are writing to _____ you that your application has been successful.', NULL, 'inform', 'inform someone that 正式商業通知。'),
(85, 'multiple_choice', 'Further to our conversation _____ Friday, I am sending you the revised proposal.', '["in","by","on","at"]', 'on', 'on Friday 特定日期用 on。'),
(85, 'multiple_choice', 'Please find _____ the document you requested.', '["attached","inside","below","enclosed"]', 'attached', 'Please find attached 電子郵件附件的標準用語。'),
(85, 'multiple_choice', 'We would like to take this _____ to thank you for your continued support.', '["chance","opportunity","time","occasion"]', 'opportunity', 'take this opportunity to 正式感謝套語。'),
(85, 'transform', 'Write the standard phrase to open an email politely enquiring about an order status.', NULL, 'I am writing to enquire about the current status of our order placed on March 10th.', 'enquire about 正式詢問。'),
(85, 'fill_blank', 'I am _____ to confirm that the meeting has been rescheduled to 10 a.m.', NULL, 'writing', 'I am writing to confirm 正式郵件開頭。'),
(85, 'multiple_choice', 'We _____ any inconvenience this may have caused.', '["apologise for","apologise of","are sorry to","apologise about"]', 'apologise for', 'apologise for 正式道歉，固定搭配。'),
(85, 'multiple_choice', 'Please _____ receipt of this email by clicking the confirmation link below.', '["acknowledge","confirm","accept","verify"]', 'acknowledge', 'acknowledge receipt 確認收到，正式書面用語。'),
(85, 'multiple_choice', 'We are _____ to announce the appointment of Ms. Chen as our new CFO.', '["happy","pleased","glad","delighted"]', 'delighted', 'delighted to announce 正式公告用語，最正式。'),
(85, 'fill_blank', 'If you _____ any further queries, please do not hesitate to get in touch.', NULL, 'have / should have', 'If you have / should you have 正式條件句。'),
(85, 'multiple_choice', 'This is to _____ you that your account has been successfully created.', '["notify","inform","say","tell"]', 'notify', 'notify someone that 正式通知。'),
(85, 'multiple_choice', 'We _____ to your email within one business day.', '["responded","will respond","respond","are responding"]', 'will respond', 'will respond 承諾未來動作。'),
(85, 'multiple_choice', 'As per our _____ agreement, payment is due within 30 days of the invoice date.', '["mutual","common","collective","shared"]', 'mutual', 'mutual agreement 雙方協議，固定搭配。'),
(85, 'fill_blank', 'We wish to _____ your attention to the changes outlined in this document.', NULL, 'draw / bring', 'draw/bring someone''s attention to 引起注意。'),
(85, 'multiple_choice', 'We look _____ to receiving your response.', '["ahead","onward","towards","forward"]', 'forward', 'look forward to + V-ing 固定期待用語。'),
(85, 'multiple_choice', 'Please _____ that any expenses must be pre-approved by your line manager.', '["understand","remember","note","know"]', 'note', 'Please note that 正式提醒用語。'),
(85, 'multiple_choice', 'In _____ to your query, please find the requested information below.', '["response","reaction","answer","reply"]', 'response', 'in response to 正式回覆套語。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(86, 'multiple_choice', 'Please find the _____ for your recent order attached to this email.', '["invoice","account","receipt","bill"]', 'invoice', 'invoice 發票（向客戶請款的帳單），receipt 收據（已付款證明）。'),
(86, 'multiple_choice', 'The company sent out a _____ to inform employees about the new policy.', '["memo","bulletin","notice","announcement"]', 'memo', 'memo（備忘錄）通常指公司內部通知。'),
(86, 'multiple_choice', 'We need to finalize the _____ before the deal can go through.', '["deal","paper","contract","agreement"]', 'contract', 'finalize the contract 最終確定合約，最準確。'),
(86, 'fill_blank', 'The goods will be _____ within three business days of receiving payment.', NULL, 'dispatched / shipped', 'dispatched/shipped 出貨，商業英語常用。'),
(86, 'multiple_choice', 'She is responsible for _____ new talent for the organization.', '["employing to","staffing up","hiring out","recruiting"]', 'recruiting', 'recruiting new talent 招募新人才，固定搭配。'),
(86, 'multiple_choice', 'The _____ terms state that payment is due within 30 days.', '["financial","billing","payment","invoice"]', 'payment', 'payment terms 付款條件，固定搭配。'),
(86, 'multiple_choice', 'We need to review the _____ before signing to ensure all terms are acceptable.', '["criteria and standards","policies and procedures","rules and regulations","terms and conditions"]', 'terms and conditions', 'terms and conditions 條款細則，合約必備。'),
(86, 'fill_blank', 'Could you provide us with a _____ for the services you will provide?', NULL, 'quotation / quote', 'quotation/quote 報價單，正式商業文件。'),
(86, 'multiple_choice', 'The _____ meeting gave employees a chance to raise concerns about the restructuring.', '["staff","town hall","company","group"]', 'town hall', 'town hall meeting 全員大會，商業英語術語。'),
(86, 'multiple_choice', 'She was given a _____ for her outstanding contribution to the project.', '["reward","raise","bonus","promotion"]', 'bonus', 'bonus 獎金（非加薪 raise，非晉升 promotion）。'),
(86, 'multiple_choice', 'Please submit your _____ form for the expenses incurred during your business trip.', '["invoice","payment","reimbursement","claim"]', 'reimbursement', 'reimbursement form 費用報銷表格，最準確。'),
(86, 'fill_blank', 'The client requested a _____ on the price for placing a large order.', NULL, 'discount / reduction', 'discount 折扣，commercial 英語常見。'),
(86, 'multiple_choice', 'The new marketing _____ increased brand awareness significantly.', '["program","project","initiative","campaign"]', 'campaign', 'marketing campaign 行銷活動，最常見搭配。'),
(86, 'multiple_choice', 'She was asked to prepare a _____ of the meeting for distribution.', '["notes","transcript","minutes","record"]', 'minutes', 'minutes of a meeting 會議記錄，固定搭配。'),
(86, 'multiple_choice', 'We would like to place an _____ for 500 units of your product.', '["application","request","inquiry","order"]', 'order', 'place an order 下訂單，固定搭配。'),
(86, 'fill_blank', 'The company''s annual _____ showed strong revenue growth.', NULL, 'report / financial results', 'annual report 年度報告，常見商業文件。'),
(86, 'multiple_choice', 'The _____ department handles all compensation and benefits issues.', '["Personnel","Staffing","Human Resources","Employee"]', 'Human Resources', 'Human Resources（HR）人力資源部門，最通用。'),
(86, 'multiple_choice', 'We are currently _____ a new software development partner.', '["searching","finding","seeking","looking"]', 'seeking', 'seeking a partner 尋求合作夥伴，正式動詞。'),
(86, 'fill_blank', 'Please _____ the attached document and return it signed.', NULL, 'review / sign', 'review and sign 審閱並簽署。'),
(86, 'multiple_choice', 'The _____ for the new CEO position attracted over 200 applicants.', '["bulletin","announcement","advertisement","job posting"]', 'job posting', 'job posting 職位公告，數位時代最常用。'),
(87, 'multiple_choice', 'The company reported a _____ of $2 million due to unexpected costs.', '["deficit","deficiency","loss","shortage"]', 'deficit', 'deficit 赤字/虧損，財務術語。'),
(87, 'multiple_choice', 'Our top priority this year is _____ — keeping our existing clients happy.', '["customer service","client management","customer retention","account handling"]', 'customer retention', 'customer retention 客戶保留率，商業策略關鍵詞。'),
(87, 'multiple_choice', 'The _____ year runs from April to March in our company.', '["fiscal","annual","financial","accounting"]', 'fiscal', 'fiscal year 財政年度，正式財務術語。'),
(87, 'multiple_choice', 'The two companies announced a _____ that will create the largest firm in the sector.', '["merger","alliance","acquisition","partnership"]', 'merger', 'merger 合併（兩公司合為一）；acquisition 收購（一方買下另一方）。'),
(87, 'fill_blank', 'The company''s _____ grew by 15% compared to the same period last year.', NULL, 'revenue / turnover', 'revenue 收入，financial 核心指標。'),
(87, 'multiple_choice', 'She has a strong _____ record — she has never missed a deadline.', '["job","performance","track","work"]', 'track', 'track record 業績記錄，固定搭配。'),
(87, 'multiple_choice', 'We need to improve our _____ process to attract better candidates.', '["recruitment","staffing","hiring","employment"]', 'recruitment', 'recruitment process 招募流程，正式 HR 術語。'),
(87, 'fill_blank', 'The board approved a major _____ to streamline operations and reduce headcount.', NULL, 'restructuring', 'restructuring 重組，商業策略術語。'),
(87, 'multiple_choice', 'She serves as a _____ between the client and the technical team.', '["go-between","bridge","liaison","contact"]', 'liaison', 'liaison 聯絡員/中間人，正式商業術語。'),
(87, 'multiple_choice', 'The company filed for _____ after failing to repay its debts.', '["bankruptcy","closure","insolvency","liquidation"]', 'bankruptcy', 'bankruptcy 破產，法律商業術語。'),
(87, 'multiple_choice', 'We need to allocate more resources to _____ development.', '["goods","product","item","merchandise"]', 'product', 'product development 產品開發，固定搭配。'),
(87, 'fill_blank', 'The new acquisition will _____ our market position significantly.', NULL, 'strengthen / enhance', 'strengthen/enhance our position 鞏固/提升市場地位。'),
(87, 'multiple_choice', 'She was given _____ to negotiate directly with the supplier.', '["allowance","ability","permission","authorization"]', 'authorization', 'authorization 授權，正式商業術語。'),
(87, 'multiple_choice', 'The _____ of the company''s shares fell sharply following the announcement.', '["rate","worth","price","value"]', 'value', 'value of shares 股票價值，financial 術語。'),
(87, 'multiple_choice', 'We need to reduce our _____ costs to improve profit margins.', '["fixed","running","operational","overhead"]', 'overhead', 'overhead costs 間接成本/管理費用，financial 術語。'),
(87, 'fill_blank', 'The client submitted a formal _____ about the quality of our service.', NULL, 'complaint', 'complaint 正式投訴，商業英語。'),
(87, 'multiple_choice', 'The company set an _____ target of 20% revenue growth next year.', '["optimistic","realistic","ambitious","aggressive"]', 'ambitious', 'ambitious target 雄心勃勃的目標，正面語境。'),
(87, 'multiple_choice', 'She is in charge of _____ with key industry partners.', '["networking","communicating","collaborating","liaising"]', 'liaising', 'liaising with partners 與合作夥伴保持聯繫，正式動詞。'),
(87, 'fill_blank', 'All employees must sign a _____ (non-disclosure agreement) before starting.', NULL, 'non-disclosure agreement / NDA', 'NDA 保密協議，商業英語縮寫。'),
(87, 'multiple_choice', 'The company signed a _____ with a major retailer to distribute its products.', '["retail deal","trade contract","sales contract","distribution agreement"]', 'distribution agreement', 'distribution agreement 分銷協議，正式商業術語。'),
(88, 'multiple_choice', 'The two sides reached a _____ after weeks of difficult talks.', '["agreement","compromise","settlement","deal"]', 'compromise', 'reach a compromise 達成妥協，談判術語。'),
(88, 'multiple_choice', 'He _____ the task to his assistant to free up time for strategic work.', '["transferred","gave","delegated","assigned"]', 'delegated', 'delegate a task 委派任務，管理術語。'),
(88, 'multiple_choice', 'The company''s _____ revenue grew by 30% thanks to its new app.', '["digital","internet","online","tech"]', 'digital', 'digital revenue 數位收入，現代商業術語。'),
(88, 'fill_blank', 'The startup''s _____ model is designed to serve millions of users without extra costs.', NULL, 'scalable / scalability', 'scalable business model 可擴展商業模式。'),
(88, 'multiple_choice', 'Her _____ of industry trends allowed her to anticipate market shifts.', '["awareness","knowledge","grasp","understanding"]', 'knowledge', 'knowledge of 對...的瞭解，knowledge of industry trends 最自然。'),
(88, 'multiple_choice', 'The company is trying to _____ its brand in the competitive market.', '["differentiate","separate","distinguish","isolate"]', 'differentiate', 'differentiate a brand 讓品牌差異化，商業策略術語。'),
(88, 'multiple_choice', 'We need to assess the _____ of opening a new branch in that market.', '["possibility","probability","feasibility","viability"]', 'feasibility', 'feasibility 可行性，assess the feasibility 評估可行性。'),
(88, 'fill_blank', 'The new product was a _____ technology that changed how people communicate.', NULL, 'disruptive', 'disruptive technology 顛覆性科技，現代商業術語。'),
(88, 'multiple_choice', 'She has a strong _____ and is known for meeting her targets consistently.', '["values","morals","standards","work ethic"]', 'work ethic', 'work ethic 工作道德/勤勉，固定搭配。'),
(88, 'multiple_choice', 'The company offered a _____ to the client to make up for the delivery delay.', '["concession","compensation","discount","benefit"]', 'concession', 'concession 讓步/優惠，談判術語。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(88, 'multiple_choice', 'The annual _____ with external auditors is a regulatory requirement.', '["inspection","audit","review","check"]', 'audit', 'audit 審計，formal financial inspection。'),
(88, 'fill_blank', 'She _____ successfully between the two competing factions to reach an agreement.', NULL, 'mediated / negotiated', 'mediate/negotiate between parties 調解/談判。'),
(88, 'multiple_choice', 'He presented a _____ case for investing in the new technology.', '["good","strong","convincing","compelling"]', 'compelling', 'compelling case 有說服力的論點，商業提案術語。'),
(88, 'multiple_choice', 'The company''s _____ structure was simplified to improve decision-making speed.', '["corporate","organizational","management","company"]', 'organizational', 'organizational structure 組織架構，管理術語。'),
(88, 'multiple_choice', 'All parties must _____ to the confidentiality clause in the contract.', '["hold","adhere","stick","follow"]', 'adhere', 'adhere to 遵守，正式法律/商業術語。'),
(88, 'fill_blank', 'The firm announced it would _____ its non-core assets to focus on its main business.', NULL, 'divest / sell off', 'divest 出售非核心資產，商業策略術語。'),
(88, 'multiple_choice', 'She presented a _____ plan with three phases covering the next five years.', '["management","strategic","operational","business"]', 'strategic', 'strategic plan 策略計劃，固定搭配。'),
(88, 'multiple_choice', 'The _____ of the deal fell through at the last minute.', '["ending","closing","completion","finalization"]', 'finalization', 'finalization of a deal 最終確定交易，名詞化形式。'),
(88, 'fill_blank', 'The company''s _____ (market capitalization) exceeded $10 billion last year.', NULL, 'market capitalization / market cap', 'market cap 市值，重要財務術語。'),
(88, 'multiple_choice', 'His _____ approach to management earned him a reputation as a great leader.', '["collaborative","cooperative","joint","team"]', 'collaborative', 'collaborative approach 協作方式，管理術語。'),
(89, 'multiple_choice', 'In a business email, ''Please find attached...'' means:', '["Please look for the attachment.","Please attach a document.","The attachment is included with the email.","The document will be sent later."]', 'The attachment is included with the email.', 'Please find attached 表附件已附上。'),
(89, 'multiple_choice', 'What does ''As per our previous discussion'' indicate in an email?', '["The writer is referring back to an earlier conversation.","The writer is disagreeing.","The writer is starting a new topic.","The writer is apologising."]', 'The writer is referring back to an earlier conversation.', 'as per 表依照，referring to earlier discussion。'),
(89, 'multiple_choice', 'In a job posting, ''competitive salary'' most likely means:', '["A salary that involves competition.","A salary that compares well with industry standards.","A salary that is the highest available.","A salary that is challenging to earn."]', 'A salary that compares well with industry standards.', 'competitive salary 有競爭力的薪資，與業界相當。'),
(89, 'fill_blank', 'In a business letter, ''We regret to inform you...'' is used to deliver _____  news.', NULL, 'negative / bad', 'regret to inform 表遺憾地通知，傳遞壞消息。'),
(89, 'multiple_choice', 'What does ''cc:'' mean in an email header?', '["The email is from the CEO.","The email has been copied to additional recipients.","The email needs confirmation.","The email content is confidential."]', 'The email has been copied to additional recipients.', 'cc = carbon copy，副本收件人。'),
(89, 'multiple_choice', 'In a memo, ''effective immediately'' means:', '["The change has been effective for a while.","The change or instruction starts right away.","The change may be effective in the future.","The change will be effective eventually."]', 'The change or instruction starts right away.', 'effective immediately 立即生效。'),
(89, 'multiple_choice', 'A ''cover letter'' in a job application is:', '["A letter introducing yourself and explaining your interest in the position.","A summary of your work experience.","A reference from a previous employer.","A list of your qualifications."]', 'A letter introducing yourself and explaining your interest in the position.', 'cover letter 求職信，介紹自己與申請原因。'),
(89, 'transform', 'What does ''Subject to change without notice'' mean in a price list? (Explain in English)', NULL, 'It means prices may change at any time and the company does not have to inform customers in advance.', 'subject to change without notice 隨時可能改變，不另行通知。'),
(89, 'multiple_choice', 'In a notice, ''This supersedes all previous versions'' means:', '["This is the most current version and replaces all older ones.","This is the first version.","This has been approved by all departments.","This corrects errors in the last version."]', 'This is the most current version and replaces all older ones.', 'supersede 取代，表此版本為最新官方版本。'),
(89, 'multiple_choice', 'What does ''please RSVP by Friday'' mean?', '["Please arrive no later than Friday.","Please respond to survey questions by Friday.","Please read and review the invitation by Friday.","Please confirm whether you will attend by Friday."]', 'Please confirm whether you will attend by Friday.', 'RSVP = Répondez s''il vous plaît（法文），請回覆確認出席。'),
(89, 'multiple_choice', 'In a business report, ''Q3'' refers to:', '["The third question in a survey.","The third goal of the project.","The third item on the agenda.","The third quarter of the financial year."]', 'The third quarter of the financial year.', 'Q3 = Quarter 3，第三季。'),
(89, 'fill_blank', '''The meeting has been postponed until further notice'' means it has been _____.', NULL, 'cancelled / delayed indefinitely', 'postponed until further notice 暫時延期，無新日期。'),
(89, 'multiple_choice', 'What is an ''agenda'' in the context of a meeting?', '["The minutes of the previous meeting.","A list of attendees.","A summary of decisions made.","A list of topics to be discussed during the meeting."]', 'A list of topics to be discussed during the meeting.', 'agenda 會議議程，討論事項清單。'),
(89, 'multiple_choice', 'In a business context, ''ROI'' stands for:', '["Rate of Inflation","Return on Investment","Revenue over Income","Results of Implementation"]', 'Return on Investment', 'ROI = Return on Investment 投資報酬率。'),
(89, 'multiple_choice', 'If a contract is ''null and void'', it means:', '["The contract is valid and enforceable.","The contract has expired.","The contract has no legal force.","The contract needs revision."]', 'The contract has no legal force.', 'null and void 無效，不具法律效力。'),
(89, 'transform', 'What does ''The figures are subject to revision'' mean in a report?', NULL, 'It means the figures may be updated or changed later, and the current figures are not final.', 'subject to revision 可能修訂，非最終數字。'),
(89, 'fill_blank', 'In a job advertisement, ''competitive benefits package'' refers to salary, _____, and other perks.', NULL, 'healthcare / bonuses / paid leave', 'benefits package 福利套餐，包含薪資外的各種福利。'),
(89, 'multiple_choice', '''FYI'' in an email subject line means:', '["For Your Immediate response","From Your Inbox","For Your Information — no action required.","Follow Up Instructions"]', 'For Your Information — no action required.', 'FYI = For Your Information 供您參考。'),
(89, 'multiple_choice', 'A ''bottom line'' in business refers to:', '["The net profit or loss of a company.","The final sentence of a report.","The last point in a presentation.","The baseline budget."]', 'The net profit or loss of a company.', 'bottom line 最終損益，常引申為最重要的結果。'),
(89, 'multiple_choice', 'In business correspondence, ''enclosed please find'' means:', '["Please prepare the enclosed document.","Please search for the enclosed document.","The document will be sent separately.","The mentioned document is included with the letter."]', 'The mentioned document is included with the letter.', 'enclosed please find = please find enclosed 信中附上文件。'),
(90, 'multiple_choice', 'The number of employees in this branch _____ increased.', '["have","were","are","has"]', 'has', 'the number of 作主語，動詞用單數 has。'),
(90, 'multiple_choice', 'A number of issues _____ been identified.', '["have","is","was","has"]', 'have', 'a number of 作主語，動詞用複數 have。'),
(90, 'multiple_choice', 'Each of the candidates _____ required to submit a portfolio.', '["are","is","have been","were"]', 'is', 'each of + 複數名詞，動詞用單數 is。'),
(90, 'fill_blank', 'Neither the CEO nor the managers _____ available for comment.', NULL, 'were', 'neither...nor 就近原則，managers 複數，were。'),
(90, 'multiple_choice', 'Not only the sales team but also the director _____ attending the summit.', '["have been","were","is","are"]', 'is', 'not only...but also 就近原則，director 單數，is。'),
(90, 'multiple_choice', 'The staff _____ notified about the policy change.', '["were","is","has been","was"]', 'were', 'staff 通常視為複數（集合名詞），were。'),
(90, 'multiple_choice', 'All of the information _____ been verified.', '["has","have","are","were"]', 'has', 'all of + 不可數名詞 information，動詞單數 has。'),
(90, 'multiple_choice', 'Either the manager or the assistants _____ responsible.', '["is","are","have been","were"]', 'are', 'either...or 就近原則，assistants 複數，are。'),
(90, 'fill_blank', 'The board of directors _____ a meeting next Tuesday.', NULL, 'is holding', 'board of directors 集合名詞（正式英語多用單數）is holding。'),
(90, 'multiple_choice', 'There _____ several problems with the proposal.', '["were","is","are","has been"]', 'are', 'there are + 複數名詞 problems。'),
(90, 'multiple_choice', 'The team''s performance _____ improved significantly.', '["were","have","has","are"]', 'has', 'team''s performance 主語單數，has improved。'),
(90, 'multiple_choice', 'None of the applications _____ complete.', '["was","are","has been","is"]', 'are', 'none of + 複數名詞，可接複數（informal: none are）。'),
(90, 'multiple_choice', 'The data _____ clearly showing an upward trend.', '["is","have been","were","are"]', 'is', 'data 作不可數名詞時，is（現代用法）。'),
(90, 'fill_blank', 'A series of workshops _____ scheduled for the new hires.', NULL, 'has been / is', 'a series of 集合名詞，單數動詞。'),
(90, 'multiple_choice', 'Both the quality and the cost _____ need to be considered.', '["of the product","product''s","products''","of product"]', 'of the product', 'both...and 後，動詞複數（need），of the product 修飾兩者。'),
(90, 'multiple_choice', 'Each department _____ submit its report by the end of the month.', '["must their own","must they","must","must their"]', 'must', 'each department 單數，must + 原形動詞。'),
(90, 'multiple_choice', 'More than one application _____ been disqualified.', '["were","are","has","have"]', 'has', 'more than one + 單數名詞，動詞用單數 has。'),
(90, 'fill_blank', 'The committee _____ (decide) on the final candidate last week.', NULL, 'decided', 'committee 集合名詞（正式英語單數），decided。'),
(90, 'multiple_choice', 'Economics _____ the study of how resources are allocated.', '["is","have been","are","were"]', 'is', 'Economics 學科名稱用單數 is。'),
(90, 'multiple_choice', 'Ten years _____ a long time to commit to any project.', '["is","were","are","have been"]', 'is', 'ten years as a concept of duration = single unit，is。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(91, 'multiple_choice', 'She is _____ charge of the entire Asia-Pacific marketing division.', '["in","on","at","for"]', 'in', 'in charge of 負責，固定搭配。'),
(91, 'multiple_choice', 'We need to _____ out a full audit before the end of the quarter.', '["do","take","make","carry"]', 'carry', 'carry out 執行/進行，固定搭配。'),
(91, 'multiple_choice', 'The meeting has been _____ off until next week.', '["put","moved","set","taken"]', 'put', 'put off 推遲，片語動詞。'),
(91, 'fill_blank', 'She is looking _____ to working with the new team.', NULL, 'forward', 'look forward to 期待，固定搭配。'),
(91, 'multiple_choice', 'We had to _____ with several complaints from clients this week.', '["manage","cope","handle","deal"]', 'deal', 'deal with 處理，固定片語動詞。'),
(91, 'multiple_choice', 'The project was _____ off due to budget constraints.', '["set","taken","put","called"]', 'called', 'called off 取消，片語動詞。'),
(91, 'multiple_choice', 'Please _____ back to me by tomorrow with your decision.', '["respond","reply","come","get"]', 'get', 'get back to someone 回覆，片語動詞。'),
(91, 'fill_blank', 'We need to _____ on a decision before the client arrives.', NULL, 'agree', 'agree on a decision 就某事達成一致。'),
(91, 'multiple_choice', 'The new policy will _____ into effect next Monday.', '["make","come","go","take"]', 'come', 'come into effect 生效，固定搭配。'),
(91, 'multiple_choice', 'She was _____ up for a promotion after her outstanding performance.', '["stood","put","set","raised"]', 'put', 'put someone up for 提名，片語動詞。'),
(91, 'multiple_choice', 'He _____ through all the reports in record time.', '["looked","ran","went","read"]', 'went', 'go through 仔細閱讀/審閱，片語動詞。'),
(91, 'fill_blank', 'We need to _____ up with a new marketing strategy for Q3.', NULL, 'come', 'come up with 想出，片語動詞。'),
(91, 'multiple_choice', 'The CEO _____ out the company''s five-year plan at the AGM.', '["set","drew","put","laid"]', 'laid', 'lay out 詳細說明，片語動詞。'),
(91, 'multiple_choice', 'The company _____ in on a deal worth $10 million.', '["cashed","came","broke","moved"]', 'cashed', 'cash in on 從中獲利，片語動詞。'),
(91, 'multiple_choice', 'He was asked to _____ for the director at the meeting.', '["substitute to","fill up","stand in","cover over"]', 'stand in', 'stand in for 代替，片語動詞。'),
(91, 'fill_blank', 'Please _____ on the key points only — we have limited time.', NULL, 'focus', 'focus on 專注於，片語動詞。'),
(91, 'multiple_choice', 'The deal is still _____ — we haven''t confirmed it yet.', '["up the air","up in the air","in the air","on the air"]', 'up in the air', 'up in the air 懸而未決，固定習語。'),
(91, 'multiple_choice', 'She _____ up the courage to ask for a raise.', '["gained","worked","built","found"]', 'worked', 'work up the courage 鼓起勇氣，固定搭配。'),
(91, 'multiple_choice', 'We need to _____ down the cost of each component.', '["divide","cut","break","split"]', 'break', 'break down 分解，片語動詞。'),
(91, 'multiple_choice', 'The client _____ through on their promise and paid on time.', '["came","held","followed","went"]', 'came', 'come through 兌現承諾，片語動詞。'),
(92, 'multiple_choice', 'The company made a major _____ in the new factory.', '["investment","invest","investing","invested"]', 'investment', '空格需名詞，investment（-ment 名詞字尾）。'),
(92, 'multiple_choice', 'She was _____ promoted to regional director after just two years.', '["recent","recentness","recently","recency"]', 'recently', '空格需副詞修飾 promoted，recently（-ly）。'),
(92, 'multiple_choice', 'The _____ of the product launch was widely praised.', '["executing","execution","execute","executive"]', 'execution', '空格需名詞，execution（-tion 名詞字尾）。'),
(92, 'fill_blank', 'The company is committed to _____ (sustain) its growth over the next decade.', NULL, 'sustaining / sustainable growth', 'sustaining 動名詞作受語。'),
(92, 'multiple_choice', 'Her _____ analysis of the market proved invaluable.', '["thoroughness","thoroughly","thoroughly","thorough"]', 'thorough', '空格需形容詞修飾 analysis，thorough。'),
(92, 'multiple_choice', 'The process was completed very _____.', '["efficient","efficiency","efficientness","efficiently"]', 'efficiently', '空格需副詞修飾動詞，efficiently（-ly）。'),
(92, 'multiple_choice', 'There has been significant _____ in our customer satisfaction scores.', '["improvement","improve","improving","improved"]', 'improvement', '空格需名詞，improvement（-ment）。'),
(92, 'fill_blank', 'The team was highly _____ (motivate) by the CEO''s speech.', NULL, 'motivated', 'motivated 過去分詞作形容詞。'),
(92, 'multiple_choice', 'She gave a very _____ presentation.', '["impress","impressive","impressively","impression"]', 'impressive', '空格需形容詞修飾名詞，impressive（-ive）。'),
(92, 'multiple_choice', 'The _____ of all employees must be verified.', '["identity","identify","identifying","identified"]', 'identity', '空格需名詞，identity（-ity 名詞字尾）。'),
(92, 'multiple_choice', 'He spoke _____ about the company''s plans.', '["confidence","confidently","confident","confidently"]', 'confidently', '空格需副詞修飾動詞 spoke，confidently（-ly）。'),
(92, 'fill_blank', 'The _____ (manage) team met to discuss the restructuring plan.', NULL, 'management', 'management team 管理團隊，名詞 management。'),
(92, 'multiple_choice', 'We need to _____ our processes to reduce costs.', '["streamlines","streamlined","streamline","streamlining"]', 'streamline', '空格需動詞（need to + 原形），streamline。'),
(92, 'multiple_choice', 'Her attention to _____ is what sets her apart.', '["details","detail","detailing","detailed"]', 'detail', 'attention to detail 固定搭配，名詞 detail。'),
(92, 'multiple_choice', 'The new system is remarkably _____ to operate.', '["ease","easily","easier","easy"]', 'easy', '空格需形容詞（is + 形容詞），easy。'),
(92, 'transform', 'The project''s success depended on the team''s cooperation. (Find the verb form)', NULL, 'The team cooperated effectively, ensuring the project''s success.', 'cooperated 是動詞形式；cooperation 是名詞。'),
(92, 'fill_blank', 'She has extensive _____ (know) in this field.', NULL, 'knowledge', 'knowledge 是 know 的名詞形式。'),
(92, 'multiple_choice', 'He is _____ for his creative approach to problem-solving.', '["renowned","renown","renownedly","renowning"]', 'renowned', 'renowned 知名的，形容詞。'),
(92, 'multiple_choice', 'The company places great _____ on teamwork.', '["emphasis","emphasizing","emphatic","emphasize"]', 'emphasis', '空格需名詞，place emphasis on 強調。'),
(92, 'multiple_choice', 'The _____ of the new policy was handled smoothly.', '["implementing","implementation","implement","implemented"]', 'implementation', '空格需名詞，implementation（-tion）。'),
(93, 'multiple_choice', 'Which sentence is grammatically correct?', '["She has worked here from 2018.","She has been working here since 2018.","She works here since 2018.","She is working here since 2018."]', 'She has been working here since 2018.', 'since + 完成式，has been working 正確。'),
(93, 'multiple_choice', 'Which sentence is correct?', '["The report will submit by Friday.","The report will be submitted by Friday.","The report will be submit by Friday.","The report be submitted by Friday."]', 'The report will be submitted by Friday.', 'will be submitted 未來被動式正確。'),
(93, 'multiple_choice', 'Which sentence has a grammatical error?', '["He waited for two hours.","He has been waiting since two hours.","He has been waiting for two hours.","He has been waiting since 10 a.m."]', 'He has been waiting since two hours.', 'since + 時間點（since 10 a.m.）；for + 時間段（for two hours）。'),
(93, 'fill_blank', 'Find the error: ''The staffs were informed about the change.'' → Correct: _____.', NULL, 'The staff were informed about the change.', 'staff 不可數/集合名詞，不加 s。'),
(93, 'multiple_choice', 'Which sentence is correct?', '["Neither he nor she were present.","Neither he nor she was present.","Neither he nor her were present.","Neither him nor her was present."]', 'Neither he nor she was present.', 'he/she 主格；neither...nor + 單數動詞 was。'),
(93, 'multiple_choice', 'Which is correct?', '["The project must be complete on time.","The project must completed on time.","The project must be completed on time.","The project must to be completed on time."]', 'The project must be completed on time.', 'must be + p.p. 情態動詞被動，completed 不是 complete。'),
(93, 'multiple_choice', 'Which sentence has a grammatical error?', '["She got used to working late.","She is used to work late.","She is used to working late.","She was used to working late."]', 'She is used to work late.', 'be used to + V-ing 習慣於，不是 to + 原形。'),
(93, 'fill_blank', 'Find the error: ''We are looking forward to hear from you.'' → Correct: _____.', NULL, 'We are looking forward to hearing from you.', 'look forward to + V-ing，不是 to + 原形。'),
(93, 'multiple_choice', 'Which sentence is correct?', '["The client, whom I met yesterday, was very impressed.","The client, who I met yesterday, was very impressed.","The client, that I met yesterday, was very impressed.","The client, which I met yesterday, was very impressed."]', 'The client, who I met yesterday, was very impressed.', 'whom（受格）用於受詞關係代名詞（正式）；who 也可接受，which/that 在非限定子句中不適用。'),
(93, 'multiple_choice', 'Which sentence has a grammatical error?', '["In spite of the rain, the event was a success.","Despite of the rain, the event was a success.","Despite the rain, the event was a success.","Although it rained, the event was a success."]', 'Despite of the rain, the event was a success.', 'despite + 名詞短語，不需要 of；despite of 是錯誤用法。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(93, 'multiple_choice', 'Which is correct?', '["He was very tired that he couldn''t concentrate.","He was such tired that he couldn''t concentrate.","He was so tired that he couldn''t concentrate.","He was too tired that he couldn''t concentrate."]', 'He was so tired that he couldn''t concentrate.', 'so + 形容詞 + that 結果子句正確。'),
(93, 'fill_blank', 'Find the error: ''I look forward to hear from you soon.'' → Correct: _____.', NULL, 'I look forward to hearing from you soon.', 'look forward to + V-ing。'),
(93, 'multiple_choice', 'Which sentence is correct?', '["All employees are required attend the meeting.","All employees are required to attend the meeting.","All employees are require to attend the meeting.","All employees required to attend the meeting."]', 'All employees are required to attend the meeting.', 'are required to + 原形，被動式不定詞。'),
(93, 'multiple_choice', 'Which sentence has an error?', '["We discussed about the budget in detail.","We talked about the budget in detail.","We went over the budget in detail.","We discussed the budget in detail."]', 'We discussed about the budget in detail.', 'discuss 直接接受語（不需 about），discussed about 是錯誤用法。'),
(93, 'multiple_choice', 'Which is correct?', '["The manager together with her team are attending.","The manager, together with her team, are attending the summit.","The manager, together with her team, is attending the summit.","The manager and her team is attending the summit."]', 'The manager, together with her team, is attending the summit.', 'together with 不影響主語（manager），動詞用單數 is。'),
(93, 'transform', 'Find and correct the error: ''She suggested to postpone the meeting.''', NULL, 'She suggested postponing the meeting.', 'suggest + V-ing，不接 to + 原形。'),
(93, 'fill_blank', 'Find the error: ''He is responsible of managing the team.'' → Correct: _____.', NULL, 'He is responsible for managing the team.', 'responsible for，不是 responsible of。'),
(93, 'multiple_choice', 'Which sentence is correct?', '["Please let me know whether you need any further informations.","Please let me know if you need any further information.","Please let I know if you need any further information.","Please let me know if you need any further information."]', 'Please let me know if you need any further information.', 'information 不可數（no plural）；let me know（not let I know）。'),
(93, 'multiple_choice', 'Which sentence has a grammatical error?', '["The new policy has an effect on all employees.","The new policy effects all employees starting next month.","The new policy affects all employees starting next month.","The new policy will affect all employees."]', 'The new policy effects all employees starting next month.', 'effect 是名詞，affect 是動詞；effects（當動詞用）是「使...生效」，不是 affects 的意思。'),
(93, 'multiple_choice', 'Which sentence is correct?', '["She is one of the most talented employee I have ever met.","She is one of the most talented employees I have ever met.","She is one of the most talent employees I have ever met.","She is the one of most talented employees I have ever meet."]', 'She is one of the most talented employees I have ever met.', 'one of the most + 最高級 + 複數名詞 + I have ever met 正確。'),
(94, 'multiple_choice', 'She works in finance, _____ ?', '["does she","isn''t she","isn''t it","doesn''t she"]', 'doesn''t she', '助動詞 does 的否定附加問句 doesn''t she。'),
(94, 'multiple_choice', 'You haven''t met the new director, _____ ?', '["don''t you","didn''t you","haven''t you","have you"]', 'have you', 'haven''t 的正面附加問句 have you。'),
(94, 'multiple_choice', 'The meeting was cancelled, _____ ?', '["isn''t it","wasn''t there","was it","wasn''t it"]', 'wasn''t it', 'was 的否定附加問句 wasn''t it。'),
(94, 'fill_blank', 'They will submit the report on time, _____ ?', NULL, 'won''t they', 'will 的否定附加問句 won''t they。'),
(94, 'multiple_choice', 'He can speak three languages, _____ ?', '["can''t he","cannot he","isn''t he","doesn''t he"]', 'can''t he', 'can 的否定附加問句 can''t he。'),
(94, 'multiple_choice', 'We should review the contract again, _____ ?', '["shouldn''t we","should we","don''t we","aren''t we"]', 'shouldn''t we', 'should 的否定附加問句 shouldn''t we。'),
(94, 'multiple_choice', 'The project hasn''t been approved yet, _____ ?', '["has it","doesn''t it","is it","hasn''t it"]', 'has it', 'hasn''t 的正面附加問句 has it。'),
(94, 'fill_blank', 'You are the new account manager, _____ ?', NULL, 'aren''t you', 'are 的否定附加問句 aren''t you。'),
(94, 'multiple_choice', 'Nobody called while I was in the meeting, _____ ?', '["didn''t nobody","did anybody","did they","didn''t they"]', 'did they', 'nobody 是否定詞，附加問句用正面 did they。'),
(94, 'multiple_choice', 'Let''s take a break, _____ ?', '["will we","shall we","shall they","don''t we"]', 'shall we', 'let''s 的附加問句固定用 shall we。'),
(94, 'multiple_choice', 'She''d already submitted the proposal, _____ ?', '["hasn''t she","hadn''t she","wouldn''t she","didn''t she"]', 'hadn''t she', 'had（= she''d）的否定附加問句 hadn''t she。'),
(94, 'fill_blank', 'This is your first time attending the summit, _____ ?', NULL, 'isn''t it', 'is 的否定附加問句 isn''t it。'),
(94, 'multiple_choice', 'You wouldn''t mind reviewing this draft, _____ ?', '["would you","will you","wouldn''t you","do you"]', 'would you', 'wouldn''t 的正面附加問句 would you。'),
(94, 'multiple_choice', 'Everyone signed the NDA, _____ ?', '["isn''t it","haven''t they","didn''t they","did they"]', 'didn''t they', 'everyone 指全體，附加問句用 didn''t they。'),
(94, 'multiple_choice', 'The data must be verified, _____ ?', '["shouldn''t it","must it","mustn''t it","isn''t it"]', 'mustn''t it', 'must 的否定附加問句 mustn''t it。'),
(94, 'fill_blank', 'You''ve been here before, _____ ?', NULL, 'haven''t you', 'have 的否定附加問句 haven''t you。'),
(94, 'multiple_choice', 'Nothing was mentioned about the timeline, _____ ?', '["was it","were it","wasn''t it","did it"]', 'was it', 'nothing 是否定詞，正面附加問句 was it。'),
(94, 'multiple_choice', 'She''s been promoted, _____ ?', '["hasn''t it","didn''t she","isn''t she","hasn''t she"]', 'hasn''t she', 'has been 的否定附加問句 hasn''t she。'),
(94, 'multiple_choice', 'The deadline is firm, _____ ?', '["isn''t it","doesn''t it","is it","isn''t there"]', 'isn''t it', 'is 的否定附加問句 isn''t it。'),
(94, 'transform', 'He should have informed us earlier. Make a tag question.', NULL, 'He should have informed us earlier, shouldn''t he?', 'should have 的否定附加問句 shouldn''t he。'),
(95, 'multiple_choice', 'We will proceed _____ all parties have agreed.', '["although","unless","as long as","despite"]', 'as long as', 'as long as = if（只要），條件表達。'),
(95, 'multiple_choice', '_____ we receive the payment, we cannot dispatch the goods.', '["Unless","As long as","If","Provided that"]', 'Unless', 'unless = if not，除非我們收到付款才出貨。'),
(95, 'multiple_choice', 'The deal will go through _____ both sides sign by Friday.', '["unless","provided that","despite","although"]', 'provided that', 'provided that = on condition that，前提是。'),
(95, 'fill_blank', 'We will extend the deadline _____ you submit a progress report.', NULL, 'provided that / as long as', 'provided that/as long as 表前提條件。'),
(95, 'multiple_choice', 'She will accept the role _____ she gets a competitive package.', '["although","unless","provided","as long as"]', 'as long as', 'as long as 表只要條件成立就接受。'),
(95, 'multiple_choice', 'We will not proceed _____ we have full board approval.', '["provided","as long as","unless","if"]', 'unless', 'unless = if not，沒有全體批准就不推進。'),
(95, 'multiple_choice', '_____ the weather permits, the outdoor event will go ahead.', '["Despite","Unless","Although","Provided that"]', 'Provided that', 'provided that 表前提條件。'),
(95, 'fill_blank', 'The project will stay on budget _____ we avoid scope creep.', NULL, 'as long as', 'as long as 只要避免範疇蔓延。'),
(95, 'multiple_choice', '_____ you have any objections, please raise them now.', '["Unless","Provided that","If","As long as"]', 'If', 'if 普通條件，現在請提出異議。'),
(95, 'multiple_choice', 'She will stay with the company _____ her salary is reviewed.', '["despite","although","provided that","unless"]', 'provided that', 'provided that 表前提條件。'),
(95, 'transform', 'We will sign the contract if the price is right. (Use: as long as)', NULL, 'We will sign the contract as long as the price is competitive.', 'as long as 替換 if 表條件。'),
(95, 'fill_blank', 'The partnership will continue _____ both parties honour the agreement.', NULL, 'as long as / provided that', 'as long as / provided that 表持續條件。'),
(95, 'multiple_choice', '_____ costs are controlled, the project should be profitable.', '["As long as","Despite","Although","Unless"]', 'As long as', 'as long as 表只要成本受控。'),
(95, 'multiple_choice', 'We cannot release the report _____ it has been approved.', '["provided","if","as long as","unless"]', 'unless', 'unless = if not，沒批准就不能發佈。'),
(95, 'multiple_choice', 'She will mentor the new team _____ she is given adequate time.', '["although","provided that","despite","unless"]', 'provided that', 'provided that 表前提（給她足夠時間）。'),
(95, 'transform', 'I will help if you ask me. (Use: unless)', NULL, 'I will not help unless you ask me directly.', 'unless = if not。'),
(95, 'fill_blank', 'The system will run smoothly _____ it is updated regularly.', NULL, 'as long as / provided that', '只要定期更新，系統就能正常運作。'),
(95, 'multiple_choice', '_____ there are objections, we will proceed with the plan.', '["As long as","If","Provided that","Unless"]', 'Unless', 'unless there are objections = if there are no objections。'),
(95, 'multiple_choice', 'The contract is valid _____ both parties comply with its terms.', '["unless","as long as","despite","although"]', 'as long as', 'as long as 表持續條件。'),
(95, 'multiple_choice', 'We will launch in Q2 _____ the testing phase is completed on time.', '["despite","although","unless","provided that"]', 'provided that', 'provided that 表前提條件。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(96, 'multiple_choice', 'She _____ on this project since January.', '["has worked","is working","works","has been working"]', 'has been working', 'since 搭配現在完成進行式，強調持續動作。'),
(96, 'multiple_choice', 'We _____ for a new supplier for three months.', '["look","are looking","have been looking","looked"]', 'have been looking', 'for three months 持續到現在，現在完成進行式。'),
(96, 'multiple_choice', 'How long _____ you _____ for the company?', '["have / worked","are / working","did / work","have / been working"]', 'have / been working', 'How long + have + been + V-ing 問持續時間。'),
(96, 'fill_blank', 'The team _____ (work) overtime all week to meet the deadline.', NULL, 'has been working', 'all week 現在完成進行式，強調持續。'),
(96, 'multiple_choice', 'He looks tired. He _____ since 6 a.m.', '["worked","has worked","has been working","is working"]', 'has been working', '說明疲憊的原因，has been working 強調持續。'),
(96, 'multiple_choice', 'Sales _____ declining for the past three quarters.', '["are","has been","have been","were"]', 'have been', 'Sales 複數，have been declining。'),
(96, 'fill_blank', 'I _____ (try) to contact you all morning!', NULL, 'have been trying', 'all morning 現在完成進行式，強調反覆嘗試。'),
(96, 'multiple_choice', 'The R&D team _____ the new formula for two years.', '["has developed","developed","develops","has been developing"]', 'has been developing', 'for two years 持續到現在，has been developing。'),
(96, 'multiple_choice', 'She _____ consistently well since joining the team.', '["performs","is performing","has been performing","has performed"]', 'has been performing', 'since joining 持續表現，has been performing。'),
(96, 'transform', 'She started learning Mandarin. She still learns it today. (Use present perfect continuous)', NULL, 'She has been learning Mandarin for the past two years.', 'has been learning + for + 時間段。'),
(96, 'fill_blank', 'The company _____ (expand) its operations across Southeast Asia.', NULL, 'has been expanding', 'has been expanding 強調持續中的擴張。'),
(96, 'multiple_choice', 'It _____ raining since last night, so the event may be cancelled.', '["has been","was","is","had been"]', 'has been', 'since last night 現在完成進行式 has been raining。'),
(96, 'multiple_choice', 'They _____ new markets for the past six months.', '["have explored","explore","have been exploring","explored"]', 'have been exploring', 'for the past six months 現在完成進行式。'),
(96, 'multiple_choice', 'He _____ complaints from clients about the delay.', '["receives","received","has received","has been receiving"]', 'has been receiving', '強調持續收到投訴，has been receiving。'),
(96, 'fill_blank', 'We _____ (wait) for your approval for over a week.', NULL, 'have been waiting', 'have been waiting 強調一直在等待。'),
(96, 'multiple_choice', 'She _____ for this position for a very long time.', '["prepares","prepared","has prepared","has been preparing"]', 'has been preparing', 'has been preparing 強調長期備考。'),
(96, 'multiple_choice', 'The team _____ very hard recently.', '["has been working","works","has worked","worked"]', 'has been working', 'recently 搭配現在完成進行式。'),
(96, 'transform', 'He started negotiating last month and is still negotiating. (Use: has been)', NULL, 'He has been negotiating the contract terms for over a month.', 'has been negotiating 現在完成進行式。'),
(96, 'fill_blank', 'They _____ (discuss) the terms for hours — no agreement yet.', NULL, 'have been discussing', 'have been discussing 強調持續的討論。'),
(96, 'multiple_choice', 'The company _____ a new investor for the past year.', '["sought","seeks","has been seeking","has sought"]', 'has been seeking', 'for the past year 現在完成進行式。'),
(97, 'multiple_choice', 'He said the Earth _____ round.', '["has been","is","was","will be"]', 'is', '普遍科學事實，時態不後移，保持 is。'),
(97, 'multiple_choice', 'She said that water _____ at 100 degrees Celsius.', '["boiled","boils","will boil","would boil"]', 'boils', '普遍科學事實不後移，boils 正確。'),
(97, 'multiple_choice', 'He mentioned that the meeting _____ at 3 p.m. today.', '["is","will be","was","would be"]', 'is', '仍然為真（今天的會議），可不後移，is 正確。'),
(97, 'fill_blank', 'She said the sun _____ in the east. (No backshift needed)', NULL, 'rises', '普遍自然事實不後移，rises。'),
(97, 'multiple_choice', 'He told me that he _____ in marketing for over 20 years.', '["worked","is working","has been working","had been working"]', 'has been working', '仍然為真（他現在仍在），可保持 has been working。'),
(97, 'multiple_choice', 'The manager said that the policy _____ into effect next Monday.', '["comes","will come","would come","came"]', 'comes', '未來仍為真（政策下週生效），can report as is。'),
(97, 'multiple_choice', 'She explained that our product _____ the highest in the industry.', '["would rank","ranked","ranks","has ranked"]', 'ranks', '仍為真的事實，ranks 可不後移。'),
(97, 'fill_blank', 'He pointed out that the company _____ (be) the market leader for five years.', NULL, 'has been / is', '現在仍為真，可不後移。'),
(97, 'multiple_choice', 'She noted that honesty _____ the best policy.', '["would be","is","was","has been"]', 'is', '普遍真理不後移，is 正確。'),
(97, 'multiple_choice', 'He said that oil prices _____ due to geopolitical tensions.', '["were rising","rose","would rise","are rising"]', 'are rising', '仍在發生的趨勢，are rising 不後移。'),
(97, 'transform', 'She told me: ''Our team always meets deadlines.'' (Report without backshift)', NULL, 'She told me that their team always meets deadlines.', 'meets 仍為真，不後移。'),
(97, 'fill_blank', 'He said the agreement _____ (still / be) in force.', NULL, 'is still in force', '仍然有效，is 不後移。'),
(97, 'multiple_choice', 'She reminded us that the office _____ at 9 a.m.', '["opened","would open","opens","will open"]', 'opens', '每日慣例仍為真，opens 不後移。'),
(97, 'multiple_choice', 'He noted that the economy _____ steadily.', '["is growing","would grow","grew","was growing"]', 'is growing', '現在仍在進行的趨勢，is growing 不後移。'),
(97, 'multiple_choice', 'She said that client satisfaction _____ our top priority.', '["remains","would remain","will remain","remained"]', 'remains', '現在仍為真，remains 不後移。'),
(97, 'transform', 'He told us: ''The contract expires in two months.'' (Report - still true)', NULL, 'He told us that the contract expires in two months.', '仍然有效的未來事實，expires 不後移。'),
(97, 'fill_blank', 'She mentioned that the new system _____ (work) well.', NULL, 'works / is working', '現在仍為真，works/is working 不後移。'),
(97, 'multiple_choice', 'He said quality assurance _____ every batch.', '["covered","would cover","covers","will cover"]', 'covers', '仍為真的程序，covers 不後移。'),
(97, 'multiple_choice', 'She noted that the market _____ still very competitive.', '["has been","was","is","would be"]', 'is', 'is 仍然為真，不後移。'),
(97, 'multiple_choice', 'He said that good communication _____ the key to success.', '["was","is","would be","has been"]', 'is', '普遍商業原則，is 不後移。'),
(98, 'multiple_choice', '_____, we need to review the budget; secondly, we need to hire more staff.', '["At first","In first","Firstly","For first"]', 'Firstly', 'Firstly...Secondly 列舉順序，最正式。'),
(98, 'multiple_choice', 'The product is affordable; _____, it is highly durable.', '["however","meanwhile","therefore","furthermore"]', 'furthermore', 'furthermore 補充更多優點。'),
(98, 'multiple_choice', 'She speaks French and Spanish. _____, she is learning Mandarin.', '["In addition","Furthermore","Moreover","As well"]', 'In addition', 'In addition 補充資訊，最常見。'),
(98, 'fill_blank', 'The new system saves time. _____, it reduces errors significantly.', NULL, 'Moreover / Furthermore', 'moreover/furthermore 補充遞進關係。'),
(98, 'multiple_choice', 'We offer competitive pricing _____ excellent after-sales service.', '["and also","furthermore","as well as","in addition to"]', 'as well as', 'as well as 連接兩個名詞短語，最自然。'),
(98, 'multiple_choice', 'He is experienced in finance; _____, he has a strong background in tech.', '["furthermore","however","what is more","therefore"]', 'what is more', 'what is more 強調遞進，書面。'),
(98, 'multiple_choice', '_____, the company expanded; then it diversified; _____, it went global.', '["In first / at last","First / finally","Firstly / last","At first / final"]', 'First / finally', 'first...finally 列舉序列最常見。'),
(98, 'transform', 'There are two reasons: cost and time. We need to cut costs. We also need to save time. (List)', NULL, 'Firstly, we need to reduce costs; secondly, we need to save time.', 'firstly...secondly 正式列舉。'),
(98, 'fill_blank', 'The plan is ambitious. _____, it is achievable with the right resources.', NULL, 'However / Nevertheless / That said', '轉折後的補充讓步。'),
(98, 'multiple_choice', '_____ cutting costs, we are also improving quality.', '["As well","Moreover","In addition to","Furthermore"]', 'In addition to', 'in addition to + V-ing 補充動作。');
INSERT INTO grammar_questions (topic_id, question_type, question, options_json, correct_answer, explanation) VALUES
(98, 'multiple_choice', 'She is talented; _____, she works incredibly hard.', '["however","therefore","meanwhile","moreover"]', 'moreover', 'moreover 補充遞進。'),
(98, 'multiple_choice', 'The new branch, _____, will create 200 jobs.', '["therefore","however","furthermore","in addition"]', 'in addition', 'in addition 補充資訊。'),
(98, 'fill_blank', 'The product is innovative. _____, the pricing is very competitive.', NULL, 'In addition / Furthermore / Moreover', '補充更多優點。'),
(98, 'multiple_choice', 'We completed the project on time; _____, we came in under budget.', '["nevertheless","therefore","however","what is more"]', 'what is more', 'what is more 表示額外的好消息。'),
(98, 'multiple_choice', 'He is responsible, _____ punctual, and highly professional.', '["in addition","moreover","furthermore","as well as"]', 'as well as', 'as well as 連接形容詞。'),
(98, 'transform', 'We have three advantages. Add a listing structure.', NULL, 'Firstly, we offer the lowest price; secondly, the fastest delivery; and finally, the best service.', 'firstly...secondly...finally 列舉。'),
(98, 'fill_blank', 'She has strong analytical skills. _____, she is an excellent communicator.', NULL, 'Furthermore / In addition / Moreover', '補充第二個優點。'),
(98, 'multiple_choice', 'The strategy is cost-effective; _____, it is environmentally friendly.', '["therefore","however","meanwhile","in addition"]', 'in addition', 'in addition 補充環保優點。'),
(98, 'multiple_choice', 'Not only was the presentation well-organized; it was _____ very engaging.', '["also","furthermore","as well","too"]', 'also', 'not only...also 固定搭配。'),
(98, 'multiple_choice', 'The training covers technical skills _____ soft skills.', '["and also","furthermore","as well as","in addition to"]', 'as well as', 'as well as 連接兩種技能。'),
(99, 'multiple_choice', 'Sales increased in Asia; _____, they declined in Europe.', '["moreover","meanwhile","therefore","however"]', 'however', 'however 表轉折對比。'),
(99, 'multiple_choice', 'The project was challenging; _____, the team delivered excellent results.', '["meanwhile","nevertheless","moreover","therefore"]', 'nevertheless', 'nevertheless 表儘管如此。'),
(99, 'multiple_choice', 'Our product is expensive. _____, clients continue to choose it for its quality.', '["Despite","Even so","Although","However"]', 'Even so', 'even so 表即便如此，強調讓步。'),
(99, 'fill_blank', 'We increased our marketing spend. _____, sales have not improved significantly.', NULL, 'However / Nevertheless', '表轉折讓步。'),
(99, 'multiple_choice', 'Our competitors charge less; _____, we offer superior quality and service.', '["moreover","on the other hand","therefore","however"]', 'on the other hand', 'on the other hand 表另一方面的權衡。'),
(99, 'multiple_choice', 'The cost is high; _____, the long-term benefits justify the investment.', '["however","therefore","moreover","meanwhile"]', 'however', 'however 表轉折，引出讓步的論點。'),
(99, 'multiple_choice', '_____, our Asian division is thriving; our European operations are struggling.', '["However","By contrast","On the other hand","Nevertheless"]', 'By contrast', 'by contrast 強調明確對比。'),
(99, 'transform', 'We cut costs. However, quality did not improve. (Use: Nevertheless)', NULL, 'We cut costs; nevertheless, quality did not improve as expected.', 'nevertheless 表儘管如此。'),
(99, 'fill_blank', 'The new approach is promising. _____, it carries significant risks.', NULL, 'However / That said / On the other hand', '表轉折，引出風險。'),
(99, 'multiple_choice', 'Sales figures were disappointing. _____, the team remained motivated.', '["Despite","Even so","Although","However"]', 'Even so', 'even so 表即便如此，士氣仍高。'),
(99, 'multiple_choice', 'Costs increased; _____, we maintained our profit margins.', '["meanwhile","nonetheless","moreover","therefore"]', 'nonetheless', 'nonetheless = nevertheless，儘管如此。'),
(99, 'multiple_choice', 'The first option is faster; _____, the second is more cost-effective.', '["therefore","however","on the other hand","moreover"]', 'on the other hand', 'on the other hand 引出對比選項。'),
(99, 'fill_blank', 'The proposal was well-received. _____, the board requested significant revisions.', NULL, 'However / That said', '然而仍需修改。'),
(99, 'multiple_choice', '_____, we underperformed this year; we have a clear strategy for improvement.', '["That said","By contrast","Even so","On the other hand"]', 'That said', 'that said 承認不足的同時轉入正面。'),
(99, 'multiple_choice', 'Prices have fallen; _____, consumer demand has not increased significantly.', '["but","yet","and","so"]', 'yet', 'yet 表意外的轉折（落price but 需求未增）。'),
(99, 'transform', 'The results were poor. In contrast, our competitors performed well. (Use: whereas)', NULL, 'Whereas our competitors performed well, our results were disappointing.', 'whereas 引導對比子句。'),
(99, 'fill_blank', 'The market is growing rapidly. _____, competition is intensifying.', NULL, 'However / At the same time', '表同時發生的對比情況。'),
(99, 'multiple_choice', 'Our costs are lower than competitors; _____, our margins are not higher.', '["and","yet","but","however"]', 'yet', 'yet 表意外轉折。'),
(99, 'multiple_choice', 'The strategy succeeded in Q1; _____, Q2 results were disappointing.', '["moreover","however","therefore","meanwhile"]', 'however', 'however 轉折，說明結果不一致。'),
(99, 'multiple_choice', 'We have strong regional support; _____, global recognition remains limited.', '["meanwhile","therefore","nonetheless","moreover"]', 'nonetheless', 'nonetheless 表儘管如此，全球知名度仍有限。'),
(100, 'multiple_choice', '_____ did the new policy take effect?', '["What time did","Since when","At when","When"]', 'When', 'When 問時間。'),
(100, 'multiple_choice', '_____ approved the budget increase?', '["Which","Who","Whose","Whom"]', 'Who', 'who 問主語人物，主語問句無倒裝。'),
(100, 'multiple_choice', '_____ is she responsible for?', '["Which","What","Whom","Why"]', 'What', 'what is she responsible for 問職責。'),
(100, 'multiple_choice', 'Could you tell me _____ the meeting is?', '["where","when is","where does","where is"]', 'where', '間接問句陳述語序：where the meeting is。'),
(100, 'fill_blank', '_____ long have you been working in this department?', NULL, 'How', 'How long 問持續時間。'),
(100, 'multiple_choice', '_____ does the company ship its products to?', '["What","Which","Where","Whom"]', 'Where', 'where 問地點目的地。'),
(100, 'multiple_choice', 'Do you know _____ submitted the proposal?', '["whose","whom","who","which"]', 'who', '主語間接問句，who 正確。'),
(100, 'multiple_choice', '_____ did the delay happen?', '["How","What","Where","Why"]', 'Why', 'why 問原因。'),
(100, 'fill_blank', '_____ many employees are in the Hong Kong office?', NULL, 'How', 'How many 問數量。'),
(100, 'multiple_choice', '_____ is in charge of client relations?', '["Which","Who","Whose","Whom"]', 'Who', 'who 問主語人物。'),
(100, 'multiple_choice', 'Could you clarify _____ the new process works?', '["where","what","why","how"]', 'how', 'how 問方式，間接問句陳述語序。'),
(100, 'multiple_choice', '_____ proposed the new strategy?', '["Whom","Which","Whose","Who"]', 'Who', 'who 問主語，主語問句。'),
(100, 'fill_blank', '_____ are the benefits of this approach?', NULL, 'What', 'What are the benefits 問優點。'),
(100, 'multiple_choice', '_____ client complained about the service?', '["Who","Which","What","Whom"]', 'Which', 'which 問哪一位（有限範圍）。'),
(100, 'multiple_choice', 'Do you know _____ the document was filed?', '["when is","how","where is","where"]', 'where', '間接問句陳述語序，where the document was filed。'),
(100, 'multiple_choice', '_____ often does the board meet?', '["When","How much","What","How"]', 'How', 'how often 問頻率。'),
(100, 'transform', 'Ask about the reason for the project delay using a formal indirect question.', NULL, 'Could you explain why the project has been delayed?', 'Could you explain why + 陳述語序。'),
(100, 'fill_blank', '_____ many days did it take to complete the audit?', NULL, 'How', 'How many days 問天數。'),
(100, 'multiple_choice', '_____ won the contract?', '["What","Whom","Which","Who"]', 'Who', 'who 問主語，主語問句。'),
(100, 'multiple_choice', '_____ long will the restructuring take?', '["What","How","When","Where"]', 'How', 'how long 問時間長度。');
